ql\n--   - 006_p0_custom_request_public_post_browse_rpc.sql\n--   - 007_p0_custom_order_revisions_and_order_events_rls.sql\n--   - 008_p0_disputes_insert_party_rls.sql\n--   - 009_p0_disputes_submitted_by_and_active_unique.sql\n--   - 010_p0_custom_order_deliverable_files_storage.sql\n--   - 011_p0_custom_order_deliverable_version_unique.sql\n--   - 012_p0_custom_request_post_attachments_storage.sql\n--   - 013_p0_custom_order_settlement_items.sql\n--   - 014_p0_harden_custom_order_settlement_items.sql\n--   - 015_p0_prevent_settlement_during_active_dispute.sql\n--   - 016_p0_community_comments.sql\n--   - 017_p0_community_author_role_compat.sql\n--   - 018_p0_mentor_list_open_custom_request_posts.sql\n--   - 019_p0_subscription_cash_debit.sql\n--   - 020_p0_cash_topup_charge.sql\n--   - 021_p0_refund_ins_admin_only.sql\n--   - 022_p0_subscription_cash_debit_grants.sql\n--   - 023_p0_subscription_cash_debit_service_role_only.sql\n--   - 024_p0_cash_topup_service_role_grant.sql\n--   - 025_p0_payments_drop_update_own.sql\n--   - 026_p0_msr_insert_subscription_check.sql\n--   - 027_p0_harden_payments_and_question_room_rls.sql\n--   - 028_p0_lock_subscriptions_writes.sql\n--   - 029_p0_lock_subscription_deletes.sql\n--   - 030_p0_refund_approve_reject_admin_rpc.sql\n--   - 031_p1_admin_notices_promotions.sql\n--\n-- Excluded source files:\n--   - 002_app_core_schema_draft.sql\n--   - 036_p1_prelaunch_rls_tightening.sql\n--\n-- Dry-run / verification notes:\n--   - 011 has duplicate deliverable-version check queries in comments; review original file for non-empty DBs.\n--   - Bundle assumes blank DB; 002_app_core_schema_draft.sql is intentionally excluded.\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0002 | supabase/bundles/bundle_1_base_001_031.sql | 001_initial_auth_profile.sql <<<\n-- ===== 001_initial_auth_profile.sql =====\n\n-- Supabase SQL Editor에 붙여넣어 한 번에 실행하세요. (필요 시 팀에서 마이그레이션으로 옮깁니다.)\n-- TODO: 멘토 verification_status 심사(관리자 콘솔), 관리자 승인 플로우, student-id-images bucket은 대시보드에서 생성·정책 점검\n-- TODO: 향후 role별 dashboard redirect는 앱의 getPostLoginPath와 맞출 것\n\n-- Extensions\ncreate extension if not exists \"pgcrypto\"", "-- updated_at touch\ncreate or replace function public.set_updated_at()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$$", "-- 1) public.users\ncreate table if not exists public.users (\n  id uuid primary key references auth.users (id) on delete cascade,\n  role text not null check (role in (''student'', ''mentor'', ''admin'')),\n  status text not null default ''active'',\n  full_name text,\n  nickname text,\n  email text,\n  grade_level text,\n  student_status text,\n  birth_date date,\n  terms_agreed_at timestamptz,\n  privacy_agreed_at timestamptz,\n  marketing_agreed boolean not null default false,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "create index if not exists users_email_idx on public.users (email)", "drop trigger if exists trg_users_set_updated on public.users", "create trigger trg_users_set_updated\n  before update on public.users\n  for each row execute function public.set_updated_at()", "-- 2) public.mentor_profiles\ncreate table if not exists public.mentor_profiles (\n  user_id uuid primary key references public.users (id) on delete cascade,\n  university_name text not null,\n  department_name text not null,\n  teaching_subjects text[] not null default ''{}'',\n  high_school_name text not null,\n  intro_line text,\n  verification_status text not null default ''pending'',\n  student_id_image_url text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "drop trigger if exists trg_mentor_profiles_set_updated on public.mentor_profiles", "create trigger trg_mentor_profiles_set_updated\n  before update on public.mentor_profiles\n  for each row execute function public.set_updated_at()", "-- 3) public.verification_logs\ncreate table if not exists public.verification_logs (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete cascade,\n  log_type text not null,\n  status text not null,\n  memo text,\n  created_at timestamptz not null default now()\n)", "create index if not exists verification_logs_user_id_idx on public.verification_logs (user_id)", "-- --------------------------------------------------------------------------\n-- auth.users 가입 시 user_metadata( raw_user_meta_data )로 public.users / mentor / log 자동 반영\n-- signUp options.data 키: app_role, full_name, nickname, grade_level, student_status, birth_date(YYYY-MM-DD),\n--   university_name, department_name, teaching_subjects_csv(콤마구분), high_school_name, intro_line,\n--   terms_agreed, privacy_agreed, marketing_agreed (text ''true''/''false'')\n-- --------------------------------------------------------------------------\ncreate or replace function public.handle_new_auth_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  m jsonb;\n  r text;\n  subj text[];\n  subj_str text;\n  bdate date;\nbegin\n  m := coalesce(NEW.raw_user_meta_data, ''{}''::jsonb);\n  r := lower(trim(m->>''app_role''));\n  if r is null or r = '''' then\n    r := ''student'';\n  end if;\n  if r not in (''student'', ''mentor'', ''admin'') then\n    r := ''student'';\n  end if;\n\n  subj_str := nullif(trim(m->>''teaching_subjects_csv''), '''');\n  if subj_str is not null then\n    subj := array(\n      select trim(both '' '' from x)\n      from unnest(string_to_array(subj_str, '','')) as x\n      where length(trim(both '' '' from x)) > 0\n    );\n  else\n    subj := ''{}'';\n  end if;\n\n  begin\n    bdate := (m->>''birth_date'')::date;\n  exception when others then\n    bdate := null;\n  end;\n\n  insert into public.users (\n    id, role, status, full_name, nickname, email,\n    grade_level, student_status, birth_date,\n    terms_agreed_at, privacy_agreed_at, marketing_agreed, updated_at\n  ) values (\n    NEW.id, r, ''active'',\n    nullif(trim(m->>''full_name''), ''''),\n    nullif(trim(m->>''nickname''), ''''),\n    coalesce(NEW.email, ''''),\n    nullif(trim(m->>''grade_level''), ''''),\n    nullif(trim(m->>''student_status''), ''''),\n    bdate,\n    case when (m->>''terms_agreed'') = ''true'' then now() else null end,\n    case when (m->>''privacy_agreed'') = ''true'' then now() else null end,\n    case when (m->>''marketing_agreed'') = ''true'' then true else false end,\n    now()\n  )\n  on conflict (id) do update set\n    role = excluded.role,\n    full_name = coalesce(excluded.full_name, public.users.full_name),\n    nickname = coalesce(excluded.nickname, public.users.nickname),\n    email = excluded.email,\n    grade_level = coalesce(excluded.grade_level, public.users.grade_level),\n    student_status = coalesce(excluded.student_status, public.users.student_status),\n    birth_date = coalesce(excluded.birth_date, public.users.birth_date),\n    terms_agreed_at = coalesce(excluded.terms_agreed_at, public.users.terms_agreed_at),\n    privacy_agreed_at = coalesce(excluded.privacy_agreed_at, public.users.privacy_agreed_at),\n    marketing_agreed = excluded.marketing_agreed,\n    updated_at = now();\n\n  if r = ''mentor'' then\n    insert into public.mentor_profiles (\n      user_id, university_name, department_name, teaching_subjects, high_school_name, intro_line,\n      verification_status, student_id_image_url, updated_at\n    ) values (\n      NEW.id,\n      coalesce(nullif(trim(m->>''university_name''), ''''), ''(미입력)''),\n      coalesce(nullif(trim(m->>''department_name''), ''''), ''(미입력)''),\n      coalesce(subj, ''{}''),\n      coalesce(nullif(trim(m->>''high_school_name''), ''''), ''(미입력)''),\n      nullif(trim(m->>''intro_line''), ''''),\n      ''pending'',\n      null,\n      now()\n    )\n    on conflict (user_id) do update set\n      university_name = excluded.university_name,\n      department_name = excluded.department_name,\n      teaching_subjects = excluded.teaching_subjects,\n      high_school_name = excluded.high_school_name,\n      intro_line = coalesce(excluded.intro_line, public.mentor_profiles.intro_line),\n      updated_at = now();\n\n    insert into public.verification_logs (user_id, log_type, status, memo) values\n      (NEW.id, ''mentor_verification'', ''pending'', ''sign-up'');\n  end if;\n\n  return NEW;\nend;\n$$", "drop trigger if exists on_auth_user_created on auth.users", "create trigger on_auth_user_created\n  after insert on auth.users\n  for each row execute function public.handle_new_auth_user()", "-- --------------------------------------------------------------------------\n-- RLS\n-- --------------------------------------------------------------------------\nalter table public.users enable row level security", "alter table public.mentor_profiles enable row level security", "alter table public.verification_logs enable row level security", "-- users: 본인만 select/insert/update\ndrop policy if exists \"users_select_own\" on public.users", "create policy \"users_select_own\" on public.users\n  for select to authenticated\n  using (id = (select auth.uid()))", "drop policy if exists \"users_insert_own\" on public.users", "create policy \"users_insert_own\" on public.users\n  for insert to authenticated\n  with check (id = (select auth.uid()))", "drop policy if exists \"users_update_own\" on public.users", "create policy \"users_update_own\" on public.users\n  for update to authenticated\n  using (id = (select auth.uid()))\n  with check (id = (select auth.uid()))", "-- mentor_profiles: 본인만 select/insert/update\ndrop policy if exists \"mentor_select_own\" on public.mentor_profiles", "create policy \"mentor_select_own\" on public.mentor_profiles\n  for select to authenticated\n  using (user_id = (select auth.uid()))", "drop policy if exists \"mentor_insert_own\" on public.mentor_profiles", "create policy \"mentor_insert_own\" on public.mentor_profiles\n  for insert to authenticated\n  with check (user_id = (select auth.uid()))", "drop policy if exists \"mentor_update_own\" on public.mentor_profiles", "create policy \"mentor_update_own\" on public.mentor_profiles\n  for update to authenticated\n  using (user_id = (select auth.uid()))\n  with check (user_id = (select auth.uid()))", "-- verification_logs: 일반 유저 select 불가(관리자·서비스롤은 RLS bypass). insert는 본인 로그 남기기(가입/재시도) 용\ndrop policy if exists \"ver_logs_insert_own\" on public.verification_logs", "create policy \"ver_logs_insert_own\" on public.verification_logs\n  for insert to authenticated\n  with check (user_id = (select auth.uid()))", "-- 관리자 전용 select 예시(관리자 역할/테이블 생기기 전엔 service_role로만 SQL Editor에서 조회)\n-- create policy \"ver_logs_admin_select\" on public.verification_logs\n--   for select to authenticated\n--   using (exists (select 1 from public.users u where u.id = auth.uid() and u.role = ''admin''));\n\n-- --------------------------------------------------------------------------\n-- Storage: bucket student-id-images (비공개 권장). bucket은 UI에서도 생성 가능. 중복 실행은 무시.\n-- TODO: production에서 bucket 정책·CORS·객체 수명 점검\n-- --------------------------------------------------------------------------\ninsert into storage.buckets (id, name, public)\n  values (''student-id-images'', ''student-id-images'', false)\n  on conflict (id) do update set public = excluded.public", "-- 인증된 사용자: 객체 경로가 `{auth.uid()}/...`일 때만 접근(첫 path segment = uid)\ndrop policy if exists \"student_id_images_select_own\" on storage.objects", "create policy \"student_id_images_select_own\" on storage.objects\n  for select to authenticated\n  using (\n    bucket_id = ''student-id-images''\n    and split_part (name, ''/'', 1) = (select auth.uid()::text)\n  )", "drop policy if exists \"student_id_images_insert_own\" on storage.objects", "create policy \"student_id_images_insert_own\" on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = ''student-id-images''\n    and split_part (name, ''/'', 1) = (select auth.uid()::text)\n  )", "drop policy if exists \"student_id_images_update_own\" on storage.objects", "create policy \"student_id_images_update_own\" on storage.objects\n  for update to authenticated\n  using (\n    bucket_id = ''student-id-images''\n    and split_part (name, ''/'', 1) = (select auth.uid()::text)\n  )\n  with check (\n    bucket_id = ''student-id-images''\n    and split_part (name, ''/'', 1) = (select auth.uid()::text)\n  )", "drop policy if exists \"student_id_images_delete_own\" on storage.objects", "create policy \"student_id_images_delete_own\" on storage.objects\n  for delete to authenticated\n  using (\n    bucket_id = ''student-id-images''\n    and split_part (name, ''/'', 1) = (select auth.uid()::text)\n  )", "-- anon 은 storage 접근 없음(기본)\n\ncomment on table public.users is ''앱 프로필. auth 가입 직후 트리거로 1줄 동기화 + 세션 있을 시 클라이언트 upsert''", "comment on table public.mentor_profiles is ''멘토 전용 프로필. TODO: verification_status 심사''", "comment on table public.verification_logs is ''인증/심사 로그. select는 관리자(미구현) 또는 service_role.''", "-- >>> NATIVE_BASELINE_PART 0003 | supabase/bundles/bundle_1_base_001_031.sql | 002_p0_subscriptions_questions_draft.sql <<<\n-- ===== 002_p0_subscriptions_questions_draft.sql =====\n\n-- [의존 순서] 이 파일은 001_initial_auth_profile.sql 이후 적용할 것\n-- [번호 충돌] 접두 002 — 동일 번호: 002_app_core_schema_draft.sql, 002_custom_request_orders_status.sql\n--   (이 파일: P0 구독·결제·Q&A. 적용 이력 불명 시 번호 변경 없이 Runbook 순서로만 적용)\n-- =============================================================================\n-- DRAFT P0 (002) — 구독/결제 intent, 멘토–학생 room, Q&A, 알림\n--   • Supabase/프로덕션에 직접 적용하지 마세요.\n--   • 001_initial_auth_profile.sql (public.users 등) 이후에만 실행하도록 가정.\n--   • 002_app_core_schema_draft.sql 은 인벤토리 초안, 본 파일은 P0 적용용(compatibility).\n--   • 2025-04 보강: markPaymentSucceeded / insertSubscriptionRow / read 알림 대응 RLS\n--   • 장기: service_role 웹훅 기준 쓰기 — 현재는 앱 finalize·보상 delete 최소 동작\n-- [불확실] payments에 student_id·payer_id 는 탐지용(구 앱) — user_id 권한과 동일 주체\n-- =============================================================================\n\ncreate extension if not exists pgcrypto", "create or replace function public.set_updated_at()\nreturns trigger\nlanguage plpgsql\nas $fn$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$fn$", "-- -----------------------------------------------------------------------------\n-- payments\n--   • user_id: 결제(의뢰) 학생 — RLS \"본인\" 기준\n--   • status: intent는 pending|processing, finalize 시 succeeded|paid|…(앱 markPayment*)\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.payments (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete cascade,\n  -- 탐지용(구 스키마/ pickExistingColumn) — RLS·정책의 주체는 user_id\n  student_id uuid references public.users (id) on delete set null,\n  payer_id uuid references public.users (id) on delete set null,\n  mentor_id uuid references public.users (id) on delete set null,\n  amount numeric not null,\n  currency text not null default ''KRW'',\n  status text not null default ''pending'' check (\n    status in (\n      ''pending'', ''processing'', ''succeeded'', ''failed'', ''canceled'', ''refunded'',\n      ''paid'', ''success'', ''complete'', ''captured'' -- markPaymentSucceeded 후보\n    )\n  ),\n  kind text,\n  idempotency_key text unique,\n  external_id text,\n  metadata jsonb,\n  data jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "drop trigger if exists trg_payments_set_updated on public.payments", "create trigger trg_payments_set_updated\n  before update on public.payments\n  for each row execute function public.set_updated_at()", "create index if not exists idx_payments_user on public.payments (user_id, created_at desc)", "create index if not exists idx_payments_mentor on public.payments (mentor_id, created_at desc)", "create index if not exists idx_payments_status on public.payments (status, created_at desc)", "alter table public.payments enable row level security", "drop policy if exists \"payments_select_own\" on public.payments", "create policy \"payments_select_own\" on public.payments\n  for select to authenticated\n  using ( (select auth.uid()) in (user_id, student_id, payer_id, mentor_id) )", "drop policy if exists \"payments_insert_intent\" on public.payments", "create policy \"payments_insert_intent\" on public.payments\n  for insert to authenticated\n  with check (\n    (select auth.uid()) = user_id\n    and (status in (''pending'', ''processing''))\n  )", "-- [compatibility] 본인 결제 행만 status 갱신( finalize, 멱등 완료 처리)\ndrop policy if exists \"payments_update_own\" on public.payments", "create policy \"payments_update_own\" on public.payments\n  for update to authenticated\n  using ( (select auth.uid()) in (user_id, student_id, payer_id) )\n  with check ( (select auth.uid()) in (user_id, student_id, payer_id) )", "-- [보안] service_role: RLS bypass — 어느 user row 도 서버에서만; 클라 wide update 금지\n-- [마이그레이션] 전부 service_role 로만 쓰게 바꾸는 경우 이 policy 제거\n\n-- -----------------------------------------------------------------------------\n-- subscriptions\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.subscriptions (\n  id uuid primary key default gen_random_uuid(),\n  student_id uuid not null references public.users (id) on delete cascade,\n  mentor_id uuid not null references public.users (id) on delete cascade,\n  payment_id uuid references public.payments (id) on delete set null,\n  plan_tier text,\n  plan_id uuid, -- app insertSubscriptionRow( mentor_plans id )\n  status text not null default ''pending'' check (status in (''pending'', ''active'', ''past_due'', ''canceled'', ''expired'')),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "create unique index if not exists uq_subscriptions_pair on public.subscriptions (student_id, mentor_id)", "create index if not exists idx_subs_status on public.subscriptions (status, updated_at desc)", "drop trigger if exists trg_subs_set_updated on public.subscriptions", "create trigger trg_subs_set_updated\n  before update on public.subscriptions\n  for each row execute function public.set_updated_at()", "alter table public.subscriptions enable row level security", "drop policy if exists \"subscriptions_select_parties\" on public.subscriptions", "create policy \"subscriptions_select_parties\" on public.subscriptions\n  for select to authenticated\n  using ( (select auth.uid()) in (student_id, mentor_id) )", "-- finalize: student 세션으로 active 구독 insert\ndrop policy if exists \"subscriptions_insert_student\" on public.subscriptions", "create policy \"subscriptions_insert_student\" on public.subscriptions\n  for insert to authenticated\n  with check ( (select auth.uid()) = student_id and status in (''pending'', ''active'', ''expired'', ''canceled'', ''past_due'') )", "-- (status는 앱이 active — 위 리스트에 포함; 스키마 default는 pending)\ndrop policy if exists \"subscriptions_update_student\" on public.subscriptions", "create policy \"subscriptions_update_student\" on public.subscriptions\n  for update to authenticated\n  using ( (select auth.uid()) = student_id )\n  with check ( (select auth.uid()) = student_id )", "-- [참고] mentor row 는 update 정책 없음(읽기만)\n-- finalize 실패 시 보상: 본인 구독 row 삭제\ndrop policy if exists \"subscriptions_delete_student\" on public.subscriptions", "create policy \"subscriptions_delete_student\" on public.subscriptions\n  for delete to authenticated\n  using ( (select auth.uid()) = student_id )", "-- -----------------------------------------------------------------------------\n-- mentor_student_rooms\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.mentor_student_rooms (\n  id uuid primary key default gen_random_uuid(),\n  student_id uuid not null references public.users (id) on delete cascade,\n  mentor_id uuid not null references public.users (id) on delete cascade,\n  payment_id uuid references public.payments (id) on delete set null,\n  subscription_id uuid references public.subscriptions (id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "create unique index if not exists uq_msr_pair on public.mentor_student_rooms (student_id, mentor_id)", "drop trigger if exists trg_msr_set_updated on public.mentor_student_rooms", "create trigger trg_msr_set_updated\n  before update on public.mentor_student_rooms\n  for each row execute function public.set_updated_at()", "alter table public.mentor_student_rooms enable row level security", "drop policy if exists \"msr_select\" on public.mentor_student_rooms", "create policy \"msr_select\" on public.mentor_student_rooms\n  for select to authenticated\n  using ( (select auth.uid()) in (student_id, mentor_id) )", "drop policy if exists \"msr_insert_pair\" on public.mentor_student_rooms", "create policy \"msr_insert_pair\" on public.mentor_student_rooms\n  for insert to authenticated\n  with check ( (select auth.uid()) in (student_id, mentor_id) )", "drop policy if exists \"msr_update_parties\" on public.mentor_student_rooms", "create policy \"msr_update_parties\" on public.mentor_student_rooms\n  for update to authenticated\n  using ( (select auth.uid()) in (student_id, mentor_id) )\n  with check ( (select auth.uid()) in (student_id, mentor_id) )", "-- service_role: bypass\n\n-- -----------------------------------------------------------------------------\n-- question_threads\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.question_threads (\n  id uuid primary key default gen_random_uuid(),\n  mentor_student_room_id uuid not null references public.mentor_student_rooms (id) on delete cascade,\n  title text,\n  status text default ''open'' check (status in (''open'', ''closed'', ''archived'')),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "create index if not exists idx_qt_msr on public.question_threads (mentor_student_room_id, created_at desc)", "drop trigger if exists trg_qt_set_updated on public.question_threads", "create trigger trg_qt_set_updated\n  before update on public.question_threads\n  for each row execute function public.set_updated_at()", "alter table public.question_threads enable row level security", "drop policy if exists \"qt_select_via_room\" on public.question_threads", "create policy \"qt_select_via_room\" on public.question_threads\n  for select to authenticated\n  using (\n    exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = question_threads.mentor_student_room_id\n        and ( (select auth.uid()) in (r.student_id, r.mentor_id) )\n    )\n  )", "drop policy if exists \"qt_write_via_room\" on public.question_threads", "create policy \"qt_write_via_room\" on public.question_threads\n  for insert to authenticated\n  with check (\n    exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = mentor_student_room_id\n        and ( (select auth.uid()) in (r.student_id, r.mentor_id) )\n    )\n  )", "drop policy if exists \"qt_update_via_room\" on public.question_threads", "create policy \"qt_update_via_room\" on public.question_threads\n  for update to authenticated\n  using (\n    exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = question_threads.mentor_student_room_id\n        and ( (select auth.uid()) in (r.student_id, r.mentor_id) )\n    )\n  )\n  with check (\n    exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = mentor_student_room_id\n        and ( (select auth.uid()) in (r.student_id, r.mentor_id) )\n    )\n  )", "-- -----------------------------------------------------------------------------\n-- question_messages\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.question_messages (\n  id uuid primary key default gen_random_uuid(),\n  thread_id uuid not null references public.question_threads (id) on delete cascade,\n  author_id uuid not null references public.users (id) on delete cascade,\n  body text not null,\n  created_at timestamptz not null default now()\n)", "create index if not exists idx_qm_thread on public.question_messages (thread_id, created_at asc)", "alter table public.question_messages enable row level security", "drop policy if exists \"qm_select\" on public.question_messages", "create policy \"qm_select\" on public.question_messages\n  for select to authenticated\n  using (\n    exists (\n      select 1 from public.question_threads t\n      join public.mentor_student_rooms r on r.id = t.mentor_student_room_id\n      where t.id = question_messages.thread_id\n        and ( (select auth.uid()) in (r.student_id, r.mentor_id) )\n    )\n  )", "drop policy if exists \"qm_insert\" on public.question_messages", "create policy \"qm_insert\" on public.question_messages\n  for insert to authenticated\n  with check (\n    (select auth.uid()) = author_id\n    and exists (\n      select 1 from public.question_threads t\n      join public.mentor_student_rooms r on r.id = t.mentor_student_room_id\n      where t.id = thread_id\n        and ( (select auth.uid()) in (r.student_id, r.mentor_id) )\n    )\n  )", "-- update/delete 없음(append)\n\n-- -----------------------------------------------------------------------------\n-- connection_notes\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.connection_notes (\n  id uuid primary key default gen_random_uuid(),\n  mentor_student_room_id uuid not null references public.mentor_student_rooms (id) on delete cascade,\n  body text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "create index if not exists idx_cn_msr on public.connection_notes (mentor_student_room_id, updated_at desc)", "drop trigger if exists trg_cn_set_updated on public.connection_notes", "create trigger trg_cn_set_updated\n  before update on public.connection_notes\n  for each row execute function public.set_updated_at()", "alter table public.connection_notes enable row level security", "drop policy if exists \"cn_select\" on public.connection_notes", "create policy \"cn_select\" on public.connection_notes\n  for select to authenticated\n  using (\n    exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = connection_notes.mentor_student_room_id\n        and ( (select auth.uid()) in (r.student_id, r.mentor_id) )\n    )\n  )", "drop policy if exists \"cn_insert\" on public.connection_notes", "create policy \"cn_insert\" on public.connection_notes\n  for insert to authenticated\n  with check (\n    exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = mentor_student_room_id\n        and ( (select auth.uid()) in (r.student_id, r.mentor_id) )\n    )\n  )", "drop policy if exists \"cn_update\" on public.connection_notes", "create policy \"cn_update\" on public.connection_notes\n  for update to authenticated\n  using (\n    exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = connection_notes.mentor_student_room_id\n        and ( (select auth.uid()) in (r.student_id, r.mentor_id) )\n    )\n  )\n  with check (\n    exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = mentor_student_room_id\n        and ( (select auth.uid()) in (r.student_id, r.mentor_id) )\n    )\n  )", "drop policy if exists \"cn_delete\" on public.connection_notes", "create policy \"cn_delete\" on public.connection_notes\n  for delete to authenticated\n  using (\n    exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = connection_notes.mentor_student_room_id\n        and ( (select auth.uid()) in (r.student_id, r.mentor_id) )\n    )\n  )", "-- -----------------------------------------------------------------------------\n-- notifications — 수신자 후보(앱 pickExistingColumn) + read 후보\n--   • authenticated insert/delete 없음(시스템/서비스) — [delete policy 없음=거부]\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.notifications (\n  id uuid primary key default gen_random_uuid(),\n  type text,\n  body text,\n  is_read boolean not null default false,\n  read boolean,\n  acknowledged boolean,\n  read_at timestamptz,\n  read_at_utc timestamptz,\n  seen_at timestamptz,\n  opened_at timestamptz,\n  viewed_at timestamptz,\n  acknowledged_at timestamptz,\n  metadata jsonb,\n  data jsonb,\n  -- 수신(정확히 하나는 반드시 설정 권장) — RLS: 아래 id 중 auth.uid() 일치\n  user_id uuid references public.users (id) on delete cascade,\n  recipient_id uuid references public.users (id) on delete cascade,\n  student_id uuid references public.users (id) on delete cascade,\n  mentor_id uuid references public.users (id) on delete cascade,\n  target_user_id uuid references public.users (id) on delete cascade,\n  owner_id uuid references public.users (id) on delete cascade,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint notifications_at_least_one_recipient check (\n    user_id is not null\n    or recipient_id is not null\n    or student_id is not null\n    or mentor_id is not null\n    or target_user_id is not null\n    or owner_id is not null\n  )\n)", "create index if not exists idx_notif_user_unread on public.notifications (user_id, is_read, created_at desc)", "create index if not exists idx_notif_recipient on public.notifications (recipient_id, is_read, created_at desc)", "drop trigger if exists trg_notif_set_updated on public.notifications", "create trigger trg_notif_set_updated\n  before update on public.notifications\n  for each row execute function public.set_updated_at()", "alter table public.notifications enable row level security", "drop policy if exists \"notif_select_own\" on public.notifications", "drop policy if exists \"notif_select_recipient\" on public.notifications", "create policy \"notif_select_recipient\" on public.notifications\n  for select to authenticated\n  using (\n    (\n      (user_id is not null and (select auth.uid()) = user_id) or\n      (recipient_id is not null and (select auth.uid()) = recipient_id) or\n      (student_id is not null and (select auth.uid()) = student_id) or\n      (mentor_id is not null and (select auth.uid()) = mentor_id) or\n      (target_user_id is not null and (select auth.uid()) = target_user_id) or\n      (owner_id is not null and (select auth.uid()) = owner_id)\n    )\n  )", "drop policy if exists \"notif_update_own\" on public.notifications", "drop policy if exists \"notif_update_recipient_read\" on public.notifications", "create policy \"notif_update_recipient_read\" on public.notifications\n  for update to authenticated\n  using (\n    (\n      (user_id is not null and (select auth.uid()) = user_id) or\n      (recipient_id is not null and (select auth.uid()) = recipient_id) or\n      (student_id is not null and (select auth.uid()) = student_id) or\n      (mentor_id is not null and (select auth.uid()) = mentor_id) or\n      (target_user_id is not null and (select auth.uid()) = target_user_id) or\n      (owner_id is not null and (select auth.uid()) = owner_id)\n    )\n  )\n  with check (\n    (\n      (user_id is not null and (select auth.uid()) = user_id) or\n      (recipient_id is not null and (select auth.uid()) = recipient_id) or\n      (student_id is not null and (select auth.uid()) = student_id) or\n      (mentor_id is not null and (select auth.uid()) = mentor_id) or\n      (target_user_id is not null and (select auth.uid()) = target_user_id) or\n      (owner_id is not null and (select auth.uid()) = owner_id)\n    )\n  )", "-- insert: authenticated 막힘(시스템) — notif_delete_own 제거(삭제 policy 없음)\ndrop policy if exists \"notif_delete_own\" on public.notifications", "-- =============================================================================\n-- [참고] 이 파일은 신규 스키마 + 제약/정책. 기존 002_p0 (좁은 notifications)에서 올릴\n--   때: notifications 컬럼/제약/정책 diff 스크립트 별도\n-- =============================================================================\n-- 미적용. 검토·스테이징 먼저.\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0004 | supabase/bundles/bundle_1_base_001_031.sql | 003_p0_custom_request_draft.sql <<<\n-- ===== 003_p0_custom_request_draft.sql =====\n\n-- =============================================================================\n-- DRAFT P0 (003) — 맞춤의뢰(포스트·지원·주문) + 주문–결제 연결 + 납품/리비전/메시지/이벤트\n--   • 미적용. 001 + 002( payments 등 ) 이후 실행.\n--   • compatibility: insertWithCandidates + order lifecycle 리터럴(멀티 status 열) 수용\n-- [불확실] admin, 시스템 event insert\n-- =============================================================================\n\ncreate extension if not exists pgcrypto", "create or replace function public.set_updated_at()\nreturns trigger\nlanguage plpgsql\nas $fn$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$fn$", "-- id 혼용 컬럼 → canonical(맞춤의뢰 post_id)\ncreate or replace function public.cra_backfill_post_fk()\nreturns trigger\nlanguage plpgsql\nas $cra$\nbegin\n  if new.post_id is null and new.custom_request_post_id is not null then\n    new.post_id := new.custom_request_post_id;\n  end if;\n  if new.post_id is null and new.custom_request_id is not null then\n    new.post_id := new.custom_request_id;\n  end if;\n  if new.post_id is null and new.request_id is not null then\n    new.post_id := new.request_id;\n  end if;\n  return new;\nend;\n$cra$", "-- 주문: post/student/mentor/application id 동의어 → canonical\ncreate or replace function public.cro_backfill_fks()\nreturns trigger\nlanguage plpgsql\nas $fn$\nbegin\n  if new.post_id is null and new.custom_request_post_id is not null then\n    new.post_id := new.custom_request_post_id;\n  end if;\n  if new.post_id is null and new.custom_request_id is not null then\n    new.post_id := new.custom_request_id;\n  end if;\n  if new.post_id is null and new.request_id is not null then\n    new.post_id := new.request_id;\n  end if;\n\n  if new.application_id is null and new.custom_request_application_id is not null then\n    new.application_id := new.custom_request_application_id;\n  end if;\n  if new.application_id is null and new.selected_application_id is not null then\n    new.application_id := new.selected_application_id;\n  end if;\n\n  if new.mentor_id is null and new.selected_mentor_id is not null then\n    new.mentor_id := new.selected_mentor_id;\n  end if;\n  if new.mentor_id is null and new.assigned_mentor_id is not null then\n    new.mentor_id := new.assigned_mentor_id;\n  end if;\n  if new.mentor_id is null and new.expert_id is not null then\n    new.mentor_id := new.expert_id;\n  end if;\n\n  if new.student_id is null and new.buyer_id is not null then\n    new.student_id := new.buyer_id;\n  end if;\n  if new.student_id is null and new.client_id is not null then\n    new.student_id := new.client_id;\n  end if;\n  if new.student_id is null and new.user_id is not null then\n    new.student_id := new.user_id;\n  end if;\n  if new.student_id is null and new.author_id is not null then\n    new.student_id := new.author_id;\n  end if;\n  if new.student_id is null and new.requester_id is not null then\n    new.student_id := new.requester_id;\n  end if;\n  return new;\nend;\n$fn$", "-- -----------------------------------------------------------------------------\n-- custom_request_posts\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.custom_request_posts (\n  id uuid primary key default gen_random_uuid(),\n  author_id uuid not null references public.users (id) on delete cascade,\n  title text,\n  body text,\n  content text,\n  subject text,\n  description text,\n  goal text,\n  subcategory text,\n  category text,\n  due_at timestamptz,\n  deadline timestamptz,\n  due_date timestamptz,\n  deliverable_type text,\n  deliverable_format text,\n  result_format text,\n  output_format text,\n  budget_min numeric,\n  budget_max numeric,\n  student_id uuid references public.users (id) on delete set null,\n  user_id uuid references public.users (id) on delete set null,\n  requester_id uuid references public.users (id) on delete set null,\n  client_id uuid references public.users (id) on delete set null,\n  state text,\n  status text not null default ''open'' check (\n    status in (\n      ''open'', ''closed'', ''cancelled'', ''canceled'', ''fulfilled'',\n      ''pending'', ''draft'', ''archived'', ''in_review'', ''in_progress''\n    )\n  ),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "alter table public.custom_request_posts enable row level security", "create index if not exists idx_crp_author on public.custom_request_posts (author_id, status, created_at desc)", "create index if not exists idx_crp_status on public.custom_request_posts (status, created_at desc)", "create index if not exists idx_crp_user on public.custom_request_posts (user_id, status, created_at desc)", "drop trigger if exists trg_crp_set_updated on public.custom_request_posts", "create trigger trg_crp_set_updated\n  before update on public.custom_request_posts\n  for each row execute function public.set_updated_at()", "-- -----------------------------------------------------------------------------\n-- custom_request_applications\n-- post_id NOT NULL: BEFORE INSERT backfill(앱이 custom_request_post_id만 줄 때)\n-- status: text (CHECK 생략 — app 리터릴 여유)\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.custom_request_applications (\n  id uuid primary key default gen_random_uuid(),\n  post_id uuid not null references public.custom_request_posts (id) on delete cascade,\n  custom_request_id uuid,\n  custom_request_post_id uuid,\n  request_id uuid,\n  mentor_id uuid not null references public.users (id) on delete cascade,\n  applicant_id uuid references public.users (id) on delete set null,\n  proposer_id uuid references public.users (id) on delete set null,\n  user_id uuid references public.users (id) on delete set null,\n  proposed_price numeric,\n  price numeric,\n  bid_amount numeric,\n  delivery_at timestamptz,\n  proposed_due timestamptz,\n  due_proposed timestamptz,\n  scope text,\n  offer_scope text,\n  services_offered text,\n  cover_letter text,\n  message text,\n  self_intro text,\n  content text,\n  extra_answers text,\n  answers text,\n  notes text,\n  school text,\n  university text,\n  university_name text,\n  major text,\n  department text,\n  field text,\n  status text not null default ''submitted'',\n  state text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "alter table public.custom_request_applications enable row level security", "create index if not exists idx_cra_post on public.custom_request_applications (post_id, status)", "create index if not exists idx_cra_mentor on public.custom_request_applications (mentor_id, created_at desc)", "drop trigger if exists trg_cra_backfill on public.custom_request_applications", "create trigger trg_cra_backfill\n  before insert on public.custom_request_applications\n  for each row execute function public.cra_backfill_post_fk()", "drop trigger if exists trg_cra_set_updated on public.custom_request_applications", "create trigger trg_cra_set_updated\n  before update on public.custom_request_applications\n  for each row execute function public.set_updated_at()", "-- -----------------------------------------------------------------------------\n-- custom_request_orders\n--   • post_id, student_id, mentor_id: BEFORE INSERT backfill(동의어 컬럼)\n--   • 다중 상태 열: 앱 open / pending / unpaid / … 그대로 저장(후속 단일화)\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.custom_request_orders (\n  id uuid primary key default gen_random_uuid(),\n\n  post_id uuid not null references public.custom_request_posts (id) on delete restrict,\n  application_id uuid references public.custom_request_applications (id) on delete set null,\n  student_id uuid not null references public.users (id) on delete restrict,\n  mentor_id uuid not null references public.users (id) on delete restrict,\n\n  custom_request_post_id uuid references public.custom_request_posts (id) on delete set null,\n  custom_request_id uuid,\n  request_id uuid,\n  buyer_id uuid references public.users (id) on delete set null,\n  client_id uuid references public.users (id) on delete set null,\n  user_id uuid references public.users (id) on delete set null,\n  author_id uuid references public.users (id) on delete set null,\n  requester_id uuid references public.users (id) on delete set null,\n  selected_mentor_id uuid references public.users (id) on delete set null,\n  assigned_mentor_id uuid references public.users (id) on delete set null,\n  expert_id uuid references public.users (id) on delete set null,\n  custom_request_application_id uuid,\n  selected_application_id uuid references public.custom_request_applications (id) on delete set null,\n  status text,\n  state text,\n  order_status text,\n  stage text,\n  payment_status text,\n  agreed_price numeric,\n  proposed_price numeric,\n  price numeric,\n  amount numeric,\n  started_at timestamptz,\n  work_started_at timestamptz,\n  in_progress_at timestamptz,\n  mentor_started_at timestamptz,\n  completed_at timestamptz,\n  accepted_at timestamptz,\n  closed_at timestamptz,\n  finished_at timestamptz,\n\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "alter table public.custom_request_orders enable row level security", "drop trigger if exists trg_cro_backfill on public.custom_request_orders", "create trigger trg_cro_backfill\n  before insert on public.custom_request_orders\n  for each row execute function public.cro_backfill_fks()", "drop trigger if exists trg_cro_set_updated on public.custom_request_orders", "create trigger trg_cro_set_updated\n  before update on public.custom_request_orders\n  for each row execute function public.set_updated_at()", "-- 앱 p3( custom_request_post_id + student + mentor) 만 오면 post/스튜/멘토 backfill\ncreate index if not exists idx_cro_student on public.custom_request_orders (student_id, status)", "create index if not exists idx_cro_mentor on public.custom_request_orders (mentor_id, status)", "create index if not exists idx_cro_post on public.custom_request_orders (post_id, status)", "-- [참고] app 이 post_id 없이 custom_request_post_id만 넣는 경우, 트리거로 post_id 채움.\n--   앱 p1: post_id + custom_request_post_id + … 동시 제공 → NOT NULL post_id 는 충족\n--   앱 p3: custom_request_post_id, student, mentor — 트리거가 post_id, student, mentor 복사\n\n-- -----------------------------------------------------------------------------\n-- order_payments\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.order_payments (\n  id uuid primary key default gen_random_uuid(),\n  custom_request_order_id uuid not null references public.custom_request_orders (id) on delete cascade,\n  payment_id uuid not null references public.payments (id) on delete restrict,\n  created_at timestamptz not null default now()\n)", "alter table public.order_payments enable row level security", "create unique index if not exists uq_order_payments_pair on public.order_payments (custom_request_order_id, payment_id)", "create index if not exists idx_order_payments_order on public.order_payments (custom_request_order_id)", "create index if not exists idx_order_payments_pay on public.order_payments (payment_id)", "-- -----------------------------------------------------------------------------\n-- 자식: custom_request_order_id(필수 FK) + 호환 id 열(비 FK, nullable)\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.custom_order_deliverables (\n  id uuid primary key default gen_random_uuid(),\n  custom_request_order_id uuid not null references public.custom_request_orders (id) on delete cascade,\n  order_id uuid,\n  custom_order_id uuid,\n  request_order_id uuid,\n  file_url text,\n  note text,\n  version int not null default 1,\n  status text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz\n)", "alter table public.custom_order_deliverables enable row level security", "create index if not exists idx_cdel_order on public.custom_order_deliverables (custom_request_order_id, version, created_at desc)", "create table if not exists public.custom_order_revisions (\n  id uuid primary key default gen_random_uuid(),\n  custom_request_order_id uuid not null references public.custom_request_orders (id) on delete cascade,\n  order_id uuid,\n  custom_order_id uuid,\n  request_order_id uuid,\n  author_id uuid not null references public.users (id) on delete cascade,\n  request_note text,\n  status text,\n  created_at timestamptz not null default now()\n)", "alter table public.custom_order_revisions enable row level security", "create index if not exists idx_crev_order on public.custom_order_revisions (custom_request_order_id, created_at desc)", "create table if not exists public.custom_order_messages (\n  id uuid primary key default gen_random_uuid(),\n  custom_request_order_id uuid not null references public.custom_request_orders (id) on delete cascade,\n  order_id uuid,\n  custom_order_id uuid,\n  request_order_id uuid,\n  author_id uuid not null references public.users (id) on delete cascade,\n  body text not null,\n  created_at timestamptz not null default now()\n)", "alter table public.custom_order_messages enable row level security", "create index if not exists idx_cmsg_order on public.custom_order_messages (custom_request_order_id, created_at asc)", "create table if not exists public.order_events (\n  id uuid primary key default gen_random_uuid(),\n  custom_request_order_id uuid not null references public.custom_request_orders (id) on delete cascade,\n  order_id uuid,\n  custom_order_id uuid,\n  request_order_id uuid,\n  event text,\n  kind text,\n  metadata jsonb,\n  created_at timestamptz not null default now()\n)", "alter table public.order_events enable row level security", "create index if not exists idx_oev_order on public.order_events (custom_request_order_id, created_at asc)", "-- -----------------------------------------------------------------------------\n-- RLS\n-- -----------------------------------------------------------------------------\ncreate or replace function public.is_admin()\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $f$\n  select coalesce((\n    select u.role = ''admin'' from public.users u where u.id = auth.uid()\n  ), false);\n$f$", "-- posts: 앱 3번째 insert 가 author_id 대신 user_id + client_id 만 줄 수 있음\ndrop policy if exists \"crp_select\" on public.custom_request_posts", "create policy \"crp_select\" on public.custom_request_posts\n  for select to authenticated\n  using (\n    author_id = (select auth.uid())\n    or user_id = (select auth.uid())\n    or student_id = (select auth.uid())\n    or requester_id = (select auth.uid())\n    or client_id = (select auth.uid())\n    or (select public.is_admin()) = true\n  )", "drop policy if exists \"crp_insert\" on public.custom_request_posts", "create policy \"crp_insert\" on public.custom_request_posts\n  for insert to authenticated\n  with check (\n    author_id = (select auth.uid())\n    or user_id = (select auth.uid())\n    or student_id = (select auth.uid())\n    or requester_id = (select auth.uid())\n    or client_id = (select auth.uid())\n    or (select public.is_admin()) = true\n  )", "drop policy if exists \"crp_update\" on public.custom_request_posts", "create policy \"crp_update\" on public.custom_request_posts\n  for update to authenticated\n  using (\n    author_id = (select auth.uid())\n    or user_id = (select auth.uid())\n    or student_id = (select auth.uid())\n    or requester_id = (select auth.uid())\n    or client_id = (select auth.uid())\n    or (select public.is_admin()) = true\n  )\n  with check (\n    author_id = (select auth.uid())\n    or user_id = (select auth.uid())\n    or student_id = (select auth.uid())\n    or requester_id = (select auth.uid())\n    or client_id = (select auth.uid())\n    or (select public.is_admin()) = true\n  )", "-- applications: post 작성자(멘본인이 지원) / 멘토(지원자) / author match post\ndrop policy if exists \"cra_select\" on public.custom_request_applications", "create policy \"cra_select\" on public.custom_request_applications\n  for select to authenticated\n  using (\n    mentor_id = (select auth.uid())\n    or exists (select 1 from public.custom_request_posts p where p.id = post_id and p.author_id = (select auth.uid()))\n    or exists (select 1 from public.custom_request_posts p where p.id = post_id and p.user_id = (select auth.uid()))\n    or (select public.is_admin()) = true\n  )", "drop policy if exists \"cra_insert\" on public.custom_request_applications", "create policy \"cra_insert\" on public.custom_request_applications\n  for insert to authenticated\n  with check ( mentor_id = (select auth.uid()) or (select public.is_admin()) = true )", "drop policy if exists \"cra_update\" on public.custom_request_applications", "create policy \"cra_update\" on public.custom_request_applications\n  for update to authenticated\n  using (\n    mentor_id = (select auth.uid()) or (select public.is_admin()) = true\n  )\n  with check ( mentor_id = (select auth.uid()) or (select public.is_admin()) = true )", "-- orders: student/buyer/client/…/mentor\ndrop policy if exists \"cro_select\" on public.custom_request_orders", "create policy \"cro_select\" on public.custom_request_orders\n  for select to authenticated\n  using (\n    student_id = (select auth.uid())\n    or buyer_id = (select auth.uid())\n    or client_id = (select auth.uid())\n    or user_id = (select auth.uid())\n    or author_id = (select auth.uid())\n    or requester_id = (select auth.uid())\n    or mentor_id = (select auth.uid())\n    or (select public.is_admin()) = true\n  )", "drop policy if exists \"cro_insert\" on public.custom_request_orders", "create policy \"cro_insert\" on public.custom_request_orders\n  for insert to authenticated\n  with check (\n    student_id = (select auth.uid())\n    or buyer_id = (select auth.uid())\n    or client_id = (select auth.uid())\n    or user_id = (select auth.uid())\n    or author_id = (select auth.uid())\n    or requester_id = (select auth.uid())\n    or (select public.is_admin()) = true\n  )", "drop policy if exists \"cro_update\" on public.custom_request_orders", "create policy \"cro_update\" on public.custom_request_orders\n  for update to authenticated\n  using (\n    student_id = (select auth.uid())\n    or buyer_id = (select auth.uid())\n    or client_id = (select auth.uid())\n    or user_id = (select auth.uid())\n    or author_id = (select auth.uid())\n    or requester_id = (select auth.uid())\n    or mentor_id = (select auth.uid())\n    or (select public.is_admin()) = true\n  )\n  with check (\n    student_id = (select auth.uid())\n    or buyer_id = (select auth.uid())\n    or client_id = (select auth.uid())\n    or user_id = (select auth.uid())\n    or author_id = (select auth.uid())\n    or requester_id = (select auth.uid())\n    or mentor_id = (select auth.uid())\n    or (select public.is_admin()) = true\n  )", "-- order_payments, deliverables, …\ndrop policy if exists \"opay_select\" on public.order_payments", "create policy \"opay_select\" on public.order_payments\n  for select to authenticated\n  using (\n    exists (\n      select 1 from public.custom_request_orders o\n      where o.id = custom_request_order_id\n        and ( (select public.is_admin()) = true\n          or (select auth.uid()) in (o.student_id, o.mentor_id)\n          or o.buyer_id = (select auth.uid())\n          or o.client_id = (select auth.uid())\n          or o.user_id = (select auth.uid())\n          or o.author_id = (select auth.uid())\n          or o.requester_id = (select auth.uid()) )\n    )\n  )", "drop policy if exists \"opay_insert\" on public.order_payments", "create policy \"opay_insert\" on public.order_payments\n  for insert to authenticated\n  with check ( (select public.is_admin()) = true )", "drop policy if exists \"cdel_select\" on public.custom_order_deliverables", "create policy \"cdel_select\" on public.custom_order_deliverables\n  for select to authenticated\n  using (\n    exists (\n      select 1 from public.custom_request_orders o\n      where o.id = custom_request_order_id\n        and ( (select public.is_admin()) = true\n          or (select auth.uid()) in (o.student_id, o.mentor_id)\n          or o.buyer_id = (select auth.uid())\n          or o.client_id = (select auth.uid())\n          or o.user_id = (select auth.uid())\n          or o.author_id = (select auth.uid())\n          or o.requester_id = (select auth.uid()) )\n    )\n  )", "drop policy if exists \"cdel_insert\" on public.custom_order_deliverables", "create policy \"cdel_insert\" on public.custom_order_deliverables\n  for insert to authenticated\n  with check (\n    exists (select 1 from public.custom_request_orders o where o.id = custom_request_order_id and o.mentor_id = (select auth.uid()) )\n  )", "drop policy if exists \"crev_all_party\" on public.custom_order_revisions", "create policy \"crev_all_party\" on public.custom_order_revisions\n  for select to authenticated\n  using (\n    exists (\n      select 1 from public.custom_request_orders o\n      where o.id = custom_request_order_id\n        and ( (select public.is_admin()) = true\n          or (select auth.uid()) in (o.student_id, o.mentor_id)\n          or o.buyer_id = (select auth.uid())\n          or o.client_id = (select auth.uid())\n          or o.user_id = (select auth.uid())\n          or o.author_id = (select auth.uid())\n          or o.requester_id = (select auth.uid()) )\n    )\n  )", "drop policy if exists \"crev_ins\" on public.custom_order_revisions", "create policy \"crev_ins\" on public.custom_order_revisions\n  for insert to authenticated\n  with check ( author_id = (select auth.uid()) )", "drop policy if exists \"cmsg_all_party\" on public.custom_order_messages", "create policy \"cmsg_all_party\" on public.custom_order_messages\n  for select to authenticated\n  using (\n    exists (\n      select 1 from public.custom_request_orders o\n      where o.id = custom_request_order_id\n        and ( (select public.is_admin()) = true\n          or (select auth.uid()) in (o.student_id, o.mentor_id)\n          or o.buyer_id = (select auth.uid())\n          or o.client_id = (select auth.uid())\n          or o.user_id = (select auth.uid())\n          or o.author_id = (select auth.uid())\n          or o.requester_id = (select auth.uid()) )\n    )\n  )", "drop policy if exists \"cmsg_ins\" on public.custom_order_messages", "create policy \"cmsg_ins\" on public.custom_order_messages\n  for insert to authenticated\n  with check (\n    (select auth.uid()) = author_id\n    and exists (\n      select 1 from public.custom_request_orders o\n      where o.id = custom_request_order_id\n        and ( (select auth.uid()) in (o.student_id, o.mentor_id)\n          or o.buyer_id = (select auth.uid())\n          or o.client_id = (select auth.uid())\n          or o.user_id = (select auth.uid())\n          or o.author_id = (select auth.uid())\n          or o.requester_id = (select auth.uid()) )\n    )\n  )", "drop policy if exists \"oev_select\" on public.order_events", "create policy \"oev_select\" on public.order_events\n  for select to authenticated\n  using (\n    exists (\n      select 1 from public.custom_request_orders o\n      where o.id = custom_request_order_id\n        and ( (select public.is_admin()) = true\n          or (select auth.uid()) in (o.student_id, o.mentor_id)\n          or o.buyer_id = (select auth.uid())\n          or o.client_id = (select auth.uid())\n          or o.user_id = (select auth.uid())\n          or o.author_id = (select auth.uid())\n          or o.requester_id = (select auth.uid()) )\n    )\n  )", "-- =============================================================================\n-- 미적용. 검토·스테이징 먼저.\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0005 | supabase/bundles/bundle_1_base_001_031.sql | 004_p0_cash_disputes_admin_draft.sql <<<\n-- ===== 004_p0_cash_disputes_admin_draft.sql =====\n\n-- =============================================================================\n-- DRAFT P0 (004) — 캐시(지갑/원장/충전패키지) · 분쟁/환불 · 커뮤니티(숏폼/게시) · 멘토플랜/리뷰\n--   • 미적용. 001 이후 실행(002,003 과 순서: 보통 002→003→004 ; cash 는 users만 의존)\n--   • cash_ledger: append-only (authenticated UPDATE/INSERT/DELETE policy 없음) — service_role\n--   • P0 compatibility(002,003): 002/003 적용은 본 파일 `custom_request_orders`/`payments`/`subscriptions` FK 전제\n--   • cash_wallets 잔액: 클라이언트 update 금지(서비스/원장 누적)\n--   • disputes/refunds: 당사자 + admin( users.role=admin, is_admin() 003에서 정의 시 재사용 권장)\n-- [불확실] 003 is_admin() 미정의 DB 단독 실행, 공개 콘텐츠 읽기 범위\n-- =============================================================================\n\ncreate extension if not exists pgcrypto", "create or replace function public.set_updated_at()\nreturns trigger\nlanguage plpgsql\nas $t$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$t$", "-- 003을 안 돌렸다면: 동일 is_admin\ncreate or replace function public.is_admin()\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $f$\n  select coalesce((\n    select u.role = ''admin'' from public.users u where u.id = auth.uid()\n  ), false);\n$f$", "-- -----------------------------------------------------------------------------\n-- cash_wallets\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.cash_wallets (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null unique references public.users (id) on delete cascade,\n  balance_cents bigint not null default 0,\n  updated_at timestamptz not null default now()\n)", "drop trigger if exists trg_cw_set_updated on public.cash_wallets", "create trigger trg_cw_set_updated\n  before update on public.cash_wallets\n  for each row execute function public.set_updated_at()", "-- -----------------------------------------------------------------------------\n-- cash_ledger — append-only; delta_cents(+) 충전 (-) 사용\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.cash_ledger (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete cascade,\n  delta_cents bigint not null,\n  reason text,\n  ref_type text,\n  ref_id uuid,\n  idempotency_key text unique,\n  created_at timestamptz not null default now()\n)", "create index if not exists idx_cl_user_created on public.cash_ledger (user_id, created_at desc)", "create index if not exists idx_cl_idem on public.cash_ledger (idempotency_key)", "-- -----------------------------------------------------------------------------\n-- cash_topup_packages\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.cash_topup_packages (\n  id uuid primary key default gen_random_uuid(),\n  amount_cents int not null,\n  price_cents int,\n  display_order int default 0,\n  active boolean not null default true,\n  label text,\n  created_at timestamptz not null default now()\n)", "-- -----------------------------------------------------------------------------\n-- disputes, refunds\n-- status: [검토] 코드에서 enum 미고정 — 보수적 check 생략 또는 open|resolved|rejected|… 정할 것\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.disputes (\n  id uuid primary key default gen_random_uuid(),\n  student_id uuid references public.users (id) on delete set null,\n  mentor_id uuid references public.users (id) on delete set null,\n  custom_request_order_id uuid references public.custom_request_orders (id) on delete set null,\n  payment_id uuid references public.payments (id) on delete set null,\n  subscription_id uuid references public.subscriptions (id) on delete set null,\n  status text not null default ''open'' check (status in (''open'', ''under_review'', ''resolved'', ''dismissed'', ''escalated'')),\n  body text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz\n)", "create table if not exists public.refunds (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete cascade,\n  amount_cents bigint,\n  status text not null default ''pending'' check (status in (''pending'', ''succeeded'', ''rejected'', ''canceled'')),\n  payment_id uuid references public.payments (id) on delete set null,\n  custom_request_order_id uuid references public.custom_request_orders (id) on delete set null,\n  created_at timestamptz not null default now()\n)", "create index if not exists idx_refunds_user on public.refunds (user_id, created_at desc)", "-- -----------------------------------------------------------------------------\n-- shortform_posts, community_posts — public list(읽기) + 작성자 쓰기; 상세: 운영에서 끌릴지 검토\n-- visibility: [불확실] public 전체 공개\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.shortform_posts (\n  id uuid primary key default gen_random_uuid(),\n  author_id uuid not null references public.users (id) on delete cascade,\n  title text,\n  body text,\n  category text,\n  source text,\n  created_at timestamptz not null default now()\n)", "create table if not exists public.community_posts (\n  id uuid primary key default gen_random_uuid(),\n  author_id uuid not null references public.users (id) on delete cascade,\n  title text,\n  body text,\n  category text,\n  created_at timestamptz not null default now()\n)", "create index if not exists idx_sf_cat on public.shortform_posts (category, created_at desc)", "create index if not exists idx_cp_cat on public.community_posts (category, created_at desc)", "-- -----------------------------------------------------------------------------\n-- mentor_plans, reviews\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.mentor_plans (\n  id uuid primary key default gen_random_uuid(),\n  mentor_id uuid not null references public.users (id) on delete cascade,\n  plan_tier text not null,\n  amount_cents int,\n  label text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz\n)", "create index if not exists idx_mp_mentor on public.mentor_plans (mentor_id, plan_tier)", "drop trigger if exists trg_mp_set_updated on public.mentor_plans", "create trigger trg_mp_set_updated\n  before update on public.mentor_plans\n  for each row execute function public.set_updated_at()", "create table if not exists public.reviews (\n  id uuid primary key default gen_random_uuid(),\n  mentor_id uuid not null references public.users (id) on delete cascade,\n  author_id uuid not null references public.users (id) on delete cascade,\n  rating smallint not null check (rating between 1 and 5),\n  body text,\n  created_at timestamptz not null default now()\n)", "create index if not exists idx_rev_mentor on public.reviews (mentor_id, created_at desc)", "-- -----------------------------------------------------------------------------\n-- RLS\n-- -----------------------------------------------------------------------------\n\nalter table public.cash_wallets enable row level security", "drop policy if exists \"cwal_select\" on public.cash_wallets", "create policy \"cwal_select\" on public.cash_wallets\n  for select to authenticated\n  using ( user_id = (select auth.uid()) )", "-- write 없음(서비스/원장 반영) — service_role\n\nalter table public.cash_ledger enable row level security", "drop policy if exists \"cled_select\" on public.cash_ledger", "create policy \"cled_select\" on public.cash_ledger\n  for select to authenticated\n  using ( user_id = (select auth.uid()) )", "-- insert / update / delete: policy 없음 = RLS 기본 거부(원장·클라이언트 직접 조작 방지) — service_role/서버\n\nalter table public.cash_topup_packages enable row level security", "-- 패키지 목록은 공개 읽기(캐시 UI)\ndrop policy if exists \"pkg_select_public\" on public.cash_topup_packages", "create policy \"pkg_select_public\" on public.cash_topup_packages\n  for select\n  to anon, authenticated\n  using ( coalesce(active, true) = true )", "-- 쓰기: admin( insert/update/delete 분리)\ndrop policy if exists \"pkg_insert_admin\" on public.cash_topup_packages", "create policy \"pkg_insert_admin\" on public.cash_topup_packages\n  for insert to authenticated\n  with check ( (select public.is_admin()) = true )", "drop policy if exists \"pkg_update_admin\" on public.cash_topup_packages", "create policy \"pkg_update_admin\" on public.cash_topup_packages\n  for update to authenticated\n  using ( (select public.is_admin()) = true )\n  with check ( (select public.is_admin()) = true )", "drop policy if exists \"pkg_delete_admin\" on public.cash_topup_packages", "create policy \"pkg_delete_admin\" on public.cash_topup_packages\n  for delete to authenticated\n  using ( (select public.is_admin()) = true )", "alter table public.disputes enable row level security", "drop policy if exists \"dispute_select\" on public.disputes", "create policy \"dispute_select\" on public.disputes\n  for select to authenticated\n  using (\n    (select auth.uid()) in (student_id, mentor_id) or (select public.is_admin()) = true\n  )", "-- insert/일반 사용자: [검토] — 필요 시 student만, 여기는 admin+서비스 전제\ndrop policy if exists \"dispute_ins\" on public.disputes", "create policy \"dispute_ins\" on public.disputes\n  for insert to authenticated\n  with check ( student_id = (select auth.uid()) or (select public.is_admin()) = true )", "drop policy if exists \"dispute_update_admin\" on public.disputes", "create policy \"dispute_update_admin\" on public.disputes\n  for update to authenticated\n  using ( (select public.is_admin()) = true )\n  with check ( (select public.is_admin()) = true )", "alter table public.refunds enable row level security", "drop policy if exists \"refund_select\" on public.refunds", "create policy \"refund_select\" on public.refunds\n  for select to authenticated\n  using ( user_id = (select auth.uid()) or (select public.is_admin()) = true )", "drop policy if exists \"refund_ins\" on public.refunds", "create policy \"refund_ins\" on public.refunds\n  for insert to authenticated\n  with check ( (select public.is_admin()) = true or user_id = (select auth.uid()) )", "-- (환불 요청은 user, 승인은 admin — [불확실])\n\nalter table public.shortform_posts enable row level security", "drop policy if exists \"sp_select_all\" on public.shortform_posts", "create policy \"sp_select_all\" on public.shortform_posts\n  for select\n  to anon, authenticated\n  using ( true )", "drop policy if exists \"sp_write_self\" on public.shortform_posts", "create policy \"sp_write_self\" on public.shortform_posts\n  for insert to authenticated\n  with check ( author_id = (select auth.uid()) or (select public.is_admin()) = true )", "drop policy if exists \"sp_update_self\" on public.shortform_posts", "create policy \"sp_update_self\" on public.shortform_posts\n  for update to authenticated\n  using ( author_id = (select auth.uid()) or (select public.is_admin()) = true )", "alter table public.community_posts enable row level security", "drop policy if exists \"cp_select_all\" on public.community_posts", "create policy \"cp_select_all\" on public.community_posts\n  for select\n  to anon, authenticated\n  using ( true )", "drop policy if exists \"cp_write_self\" on public.community_posts", "create policy \"cp_write_self\" on public.community_posts\n  for insert to authenticated\n  with check ( author_id = (select auth.uid()) or (select public.is_admin()) = true )", "drop policy if exists \"cp_update_self\" on public.community_posts", "create policy \"cp_update_self\" on public.community_posts\n  for update to authenticated\n  using ( author_id = (select auth.uid()) or (select public.is_admin()) = true )", "alter table public.mentor_plans enable row level security", "drop policy if exists \"mplan_select\" on public.mentor_plans", "create policy \"mplan_select\" on public.mentor_plans\n  for select\n  to anon, authenticated\n  using ( true )", "drop policy if exists \"mplan_ins\" on public.mentor_plans", "create policy \"mplan_ins\" on public.mentor_plans\n  for insert to authenticated\n  with check ( mentor_id = (select auth.uid()) or (select public.is_admin()) = true )", "drop policy if exists \"mplan_upd\" on public.mentor_plans", "create policy \"mplan_upd\" on public.mentor_plans\n  for update to authenticated\n  using ( mentor_id = (select auth.uid()) or (select public.is_admin()) = true )\n  with check ( mentor_id = (select auth.uid()) or (select public.is_admin()) = true )", "drop policy if exists \"mplan_del\" on public.mentor_plans", "create policy \"mplan_del\" on public.mentor_plans\n  for delete to authenticated\n  using ( mentor_id = (select auth.uid()) or (select public.is_admin()) = true )", "alter table public.reviews enable row level security", "drop policy if exists \"rev_select\" on public.reviews", "create policy \"rev_select\" on public.reviews\n  for select\n  to anon, authenticated\n  using ( true )", "drop policy if exists \"rev_ins\" on public.reviews", "create policy \"rev_ins\" on public.reviews\n  for insert to authenticated\n  with check ( author_id = (select auth.uid()) )", "-- update: 본인 또는 admin(부정리뷰) — [불확실]\ndrop policy if exists \"rev_update_own\" on public.reviews", "create policy \"rev_update_own\" on public.reviews\n  for update to authenticated\n  using ( author_id = (select auth.uid()) or (select public.is_admin()) = true )", "-- =============================================================================\n-- [주의] mentor_plans: FOR ALL 정책(멘토 도메인). 결제/원장과는 분리.\n-- [주의] set_updated_at(mentor_plans) requires function from 001/002/003\n-- =============================================================================\n-- 미적용. 스테이징 검증 후.\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0006 | supabase/bundles/bundle_1_base_001_031.sql | 002_custom_request_orders_status.sql <<<\n-- ===== 002_custom_request_orders_status.sql =====\n\n-- [의존 순서] 이 파일은 003_p0_custom_request_draft.sql 이후 적용할 것\n-- [번호 충돌] 접두 002 — 동일 번호: 002_p0_subscriptions_questions_draft.sql, 002_app_core_schema_draft.sql\n--   (이 파일: orderSchemaGate 마커만. DDL은 003_p0_custom_request_draft.sql)\n-- Marker for app/src E2E: enables lib/customRequest/orderSchemaGate (mentor \"작업 시작\" 등).\n-- Canonical DDL for custom_request_orders and related RLS: see 003_p0_custom_request_draft.sql\nselect 1", "-- >>> NATIVE_BASELINE_PART 0007 | supabase/bundles/bundle_1_base_001_031.sql | 005_p0_public_mentor_read_rpc.sql <<<\n-- ===== 005_p0_public_mentor_read_rpc.sql =====\n\n-- =============================================================================\n-- P0: 공개 멘토 목록/상세를 위한 읽기 RPC (001 users·mentor_profiles RLS “본인만” 보완)\n--  • application layer가 직접 public.users 전체 row(이메일 등)를 공개 SELECT 하지 않도록\n--    SECURITY DEFINER + 컬럼 제한(이메일 제외)으로 expose.\n--  • **staging·운영** 적용 전 service_role / SQL Editor에서 점검. 운영은 이메일·정책·감사에 맞게 조정.\n--  • 장기: 읽기 전용 VIEW + 최소 열, 또는 service_role BFF only.\n-- =============================================================================\n\n-- 멘토 목록: 이메일 제외(노출 최소)\ndrop function if exists public.mentor_directory_list(integer)", "create or replace function public.mentor_directory_list(p_limit int default 80)\nreturns table (\n  id uuid,\n  role text,\n  status text,\n  full_name text,\n  nickname text,\n  grade_level text,\n  student_status text,\n  birth_date date,\n  terms_agreed_at timestamptz,\n  privacy_agreed_at timestamptz,\n  marketing_agreed boolean,\n  created_at timestamptz,\n  updated_at timestamptz\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select\n    u.id,\n    u.role,\n    u.status,\n    u.full_name,\n    u.nickname,\n    u.grade_level,\n    u.student_status,\n    u.birth_date,\n    u.terms_agreed_at,\n    u.privacy_agreed_at,\n    u.marketing_agreed,\n    u.created_at,\n    u.updated_at\n  from public.users u\n  where u.role = ''mentor''\n  order by u.created_at desc\n  limit greatest(1, least(p_limit, 200));\n$$", "-- 멘토 1인 공개(상세/구독) — role=mentor 가 아니면 0행\ndrop function if exists public.mentor_user_public(uuid)", "create or replace function public.mentor_user_public(p_mentor_id uuid)\nreturns table (\n  id uuid,\n  role text,\n  status text,\n  full_name text,\n  nickname text,\n  grade_level text,\n  student_status text,\n  birth_date date,\n  terms_agreed_at timestamptz,\n  privacy_agreed_at timestamptz,\n  marketing_agreed boolean,\n  created_at timestamptz,\n  updated_at timestamptz\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select\n    u.id,\n    u.role,\n    u.status,\n    u.full_name,\n    u.nickname,\n    u.grade_level,\n    u.student_status,\n    u.birth_date,\n    u.terms_agreed_at,\n    u.privacy_agreed_at,\n    u.marketing_agreed,\n    u.created_at,\n    u.updated_at\n  from public.users u\n  where u.id = p_mentor_id\n    and u.role = ''mentor''\n  limit 1;\n$$", "-- 멘토 프로필 배치(목록·상세) — RLS “본인만” 보완\ndrop function if exists public.mentor_profiles_for_directory(uuid[])", "create or replace function public.mentor_profiles_for_directory(p_ids uuid[])\nreturns setof public.mentor_profiles\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select mp.*\n  from public.mentor_profiles mp\n  where p_ids is not null\n    and array_length(p_ids, 1) is not null\n    and mp.user_id = any (p_ids);\n$$", "revoke all on function public.mentor_directory_list(int) from public", "revoke all on function public.mentor_user_public(uuid) from public", "revoke all on function public.mentor_profiles_for_directory(uuid[]) from public", "grant execute on function public.mentor_directory_list(int) to anon, authenticated", "grant execute on function public.mentor_user_public(uuid) to anon, authenticated", "grant execute on function public.mentor_profiles_for_directory(uuid[]) to anon, authenticated", "comment on function public.mentor_directory_list is ''P0 멘토 디렉터리(이메일 제외). 001 RLS로 목록이 비는 문제를 해결.''", "comment on function public.mentor_user_public is ''P0 멘토 1인 공개 프로필용 users 행(이메일 제외).''", "comment on function public.mentor_profiles_for_directory is ''P0 멘토 user_id[] 에 대한 mentor_profiles.''", "-- >>> NATIVE_BASELINE_PART 0008 | supabase/bundles/bundle_1_base_001_031.sql | 006_p0_custom_request_public_post_browse_rpc.sql <<<\n-- ===== 006_p0_custom_request_public_post_browse_rpc.sql =====\n\n-- =============================================================================\n-- P0: 멘토가 맞춤의뢰 공개 상세(/custom-request/[id])를 읽기 위한 최소 열 RPC\n--  • custom_request_posts SELECT RLS(crp_select)는 작성자·동의어 컬럼만 허용 →\n--    멘토의 직접 SELECT는 0행 → 앱이 notFound()를 호출하는 문제를 해결.\n--  • SECURITY DEFINER로 테이블을 읽되, 반환 컬럼만 제한(작성자 uuid·연락처 등 미포함).\n--  • 호출: authenticated 만. 멘토(role) + status=open(또는 state 공개 계열) 일 때만 1행 반환.\n--    작성자·관리자는 앱에서 기존 loadCustomPostById(직접 SELECT)로 충분.\n--  • staging·운영 적용 전 SQL Editor에서 점검.\n-- =============================================================================\n\ndrop function if exists public.get_public_custom_request_post_for_browse(uuid)", "create or replace function public.get_public_custom_request_post_for_browse(p_post_id uuid)\nreturns table (\n  id uuid,\n  title text,\n  body text,\n  content text,\n  subject text,\n  description text,\n  goal text,\n  subcategory text,\n  category text,\n  due_at timestamptz,\n  deadline timestamptz,\n  due_date timestamptz,\n  deliverable_type text,\n  deliverable_format text,\n  result_format text,\n  output_format text,\n  budget_min numeric,\n  budget_max numeric,\n  state text,\n  status text,\n  created_at timestamptz,\n  updated_at timestamptz\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $fn$\n  select\n    p.id,\n    p.title,\n    p.body,\n    p.content,\n    p.subject,\n    p.description,\n    p.goal,\n    p.subcategory,\n    p.category,\n    p.due_at,\n    p.deadline,\n    p.due_date,\n    p.deliverable_type,\n    p.deliverable_format,\n    p.result_format,\n    p.output_format,\n    p.budget_min,\n    p.budget_max,\n    p.state,\n    p.status,\n    p.created_at,\n    p.updated_at\n  from public.custom_request_posts p\n  where p.id = p_post_id\n    and (select auth.uid()) is not null\n    and (\n      (select public.is_admin()) = true\n      or (\n        exists (\n          select 1\n          from public.users u\n          where u.id = (select auth.uid())\n            and u.role = ''mentor''\n        )\n        and (\n          lower(trim(coalesce(p.status, ''''))) = ''open''\n          or lower(trim(coalesce(p.state, ''''))) in (''open'', ''published'')\n        )\n      )\n    )\n  limit 1;\n$fn$", "revoke all on function public.get_public_custom_request_post_for_browse(uuid) from public", "grant execute on function public.get_public_custom_request_post_for_browse(uuid) to authenticated", "comment on function public.get_public_custom_request_post_for_browse(uuid) is\n  ''P0 멘토·관리자: 모집 중 맞춤의뢰 상세(최소 열). 작성자 본인은 직접 SELECT(RLS) 사용.''", "-- >>> NATIVE_BASELINE_PART 0009 | supabase/bundles/bundle_1_base_001_031.sql | 007_p0_custom_order_revisions_and_order_events_rls.sql <<<\n-- ===== 007_p0_custom_order_revisions_and_order_events_rls.sql =====\n\n-- P0: 학생(의뢰자) 전용 수정 요청 insert, order_events insert(주문 당사자)\n-- 선행: 003_p0_custom_request_draft.sql (custom_request_orders, custom_order_revisions, order_events)\n\n-- -----------------------------------------------------------------------------\n-- custom_order_revisions: author=본인 + 의뢰자(학생) 당사자만 insert\n-- -----------------------------------------------------------------------------\ndrop policy if exists \"crev_ins\" on public.custom_order_revisions", "create policy \"crev_ins\" on public.custom_order_revisions\n  for insert to authenticated\n  with check (\n    author_id = (select auth.uid())\n    and exists (\n      select 1 from public.custom_request_orders o\n      where o.id = custom_request_order_id\n        and (\n          o.student_id = (select auth.uid())\n          or o.buyer_id = (select auth.uid())\n          or o.user_id = (select auth.uid())\n          or o.client_id = (select auth.uid())\n          or o.author_id = (select auth.uid())\n          or o.requester_id = (select auth.uid())\n        )\n    )\n  )", "-- -----------------------------------------------------------------------------\n-- order_events: 당사자 insert(메시지/수정요청 이벤트 기록)\n-- -----------------------------------------------------------------------------\ndrop policy if exists \"oev_insert\" on public.order_events", "create policy \"oev_insert\" on public.order_events\n  for insert to authenticated\n  with check (\n    exists (\n      select 1 from public.custom_request_orders o\n      where\n        o.id = custom_request_order_id\n        and (\n          o.student_id = (select auth.uid())\n          or o.mentor_id = (select auth.uid())\n          or o.buyer_id = (select auth.uid())\n          or o.user_id = (select auth.uid())\n          or o.client_id = (select auth.uid())\n          or o.author_id = (select auth.uid())\n          or o.requester_id = (select auth.uid())\n        )\n    )\n  )", "-- >>> NATIVE_BASELINE_PART 0010 | supabase/bundles/bundle_1_base_001_031.sql | 008_p0_disputes_insert_party_rls.sql <<<\n-- ===== 008_p0_disputes_insert_party_rls.sql =====\n\n-- P0: 맞춤의뢰 주문방 — disputes insert 를 학생·멘토(주문 당사자)로 제한.\n-- 선행: 004_p0_cash_disputes_admin_draft.sql (disputes, custom_request_orders)\n-- 기본 004 `dispute_ins` 는 student_id = auth.uid() 만 허용 → 멘토 신청 불가. 본 정책으로 교체.\n\ndrop policy if exists \"dispute_ins\" on public.disputes", "create policy \"dispute_ins\" on public.disputes\n  for insert to authenticated\n  with check (\n    (select auth.uid()) in (student_id, mentor_id)\n    and custom_request_order_id is not null\n    and exists (\n      select 1\n      from public.custom_request_orders o\n      where o.id = custom_request_order_id\n        and o.student_id = student_id\n        and o.mentor_id = mentor_id\n        and (\n          o.student_id = (select auth.uid())\n          or o.mentor_id = (select auth.uid())\n          or o.buyer_id = (select auth.uid())\n          or o.user_id = (select auth.uid())\n          or o.client_id = (select auth.uid())\n          or o.author_id = (select auth.uid())\n          or o.requester_id = (select auth.uid())\n        )\n    )\n  )", "-- >>> NATIVE_BASELINE_PART 0011 | supabase/bundles/bundle_1_base_001_031.sql | 009_p0_disputes_submitted_by_and_active_unique.sql <<<\n-- ===== 009_p0_disputes_submitted_by_and_active_unique.sql =====\n\n-- P0: 맞춤의뢰 disputes — submitted_by(감사) + active 분쟁 1건만(부분 유니크 인덱스)\n-- 선행: 004( disputes 테이블 ) · 008_p0_disputes_insert_party_rls.sql ( RLS )\n-- Staging/운영: Supabase SQL Editor에서 순서대로 적용.\n\n-- ---------------------------------------------------------------------------\n-- 1) submitted_by — auth.users 참조(레거시 호환: 열이 이미 있으면 ADD 생략)\n-- ---------------------------------------------------------------------------\ndo $migration$\nbegin\n  if not exists (\n    select 1\n    from information_schema.columns\n    where table_schema = ''public''\n      and table_name = ''disputes''\n      and column_name = ''submitted_by''\n  ) then\n    alter table public.disputes\n      add column submitted_by uuid null references auth.users (id) on delete set null;\n  end if;\nend;\n$migration$", "comment on column public.disputes.submitted_by is\n  ''분쟁 접수 시점의 로그인 사용자(auth.users.id). RLS/앱 insert와 별도 감사 추적.''", "-- ---------------------------------------------------------------------------\n-- 2) 동일 주문에 open / under_review / escalated 인 분쟁 1건만(부분 유니크 인덱스)\n--    ( ALTER TABLE ... ADD CONSTRAINT ... WHERE 는 사용하지 않음 )\n-- ---------------------------------------------------------------------------\ncreate unique index if not exists disputes_order_active_unique\n  on public.disputes (custom_request_order_id)\n  where (status in (''open'', ''under_review'', ''escalated''))", "-- NULL custom_request_order_id 행이 여럿이어도(비권장) 인덱스는 서로 충돌하지 않음(PostgreSQL NULL ≠ NULL).\n\n-- =============================================================================\n-- Supabase SQL Editor — 검증용(개발/스테이징에서 실행)\n-- =============================================================================\n-- -- 1) disputes RLS\n-- select c.relname, c.relrowsecurity as rls_on\n-- from pg_class c\n-- join pg_namespace n on n.oid = c.relnamespace\n-- where n.nspname = ''public'' and c.relname = ''disputes'';\n--\n-- -- 2) disputes policy 목록\n-- select schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check\n-- from pg_policies\n-- where schemaname = ''public'' and tablename = ''disputes''\n-- order by policyname;\n--\n-- -- 3) active unique 인덱스\n-- select indexname, indexdef\n-- from pg_indexes\n-- where schemaname = ''public'' and tablename = ''disputes'' and indexname = ''disputes_order_active_unique'';\n--\n-- -- 4) 주문 상태 실제 값(terminal 정합성 확인 — orderLifecycleConstants 와 대조)\n-- select distinct status, state, order_status\n-- from public.custom_request_orders\n-- order by 1 nulls first, 2 nulls first, 3 nulls first;\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0012 | supabase/bundles/bundle_1_base_001_031.sql | 010_p0_custom_order_deliverable_files_storage.sql <<<\n-- ===== 010_p0_custom_order_deliverable_files_storage.sql =====\n\n-- P0: 맞춤의뢰 납품 첨부 — private Storage 버킷 + custom_order_deliverables 메타 컬럼 + storage.objects RLS\n-- 선행: 003( custom_request_orders, custom_order_deliverables ) · 001( is_admin / users )\n-- Staging/운영: idempotent, 여러 번 실행해도 안전\n\n-- ---------------------------------------------------------------------------\n-- 1) custom_order_deliverables — 스토리지/파일 메타(기존 호환: IF NOT EXISTS)\n-- ---------------------------------------------------------------------------\ndo $alter$\nbegin\n  if not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''custom_order_deliverables'' and column_name = ''storage_path'') then\n    alter table public.custom_order_deliverables add column storage_path text;\n  end if;\n  if not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''custom_order_deliverables'' and column_name = ''original_filename'') then\n    alter table public.custom_order_deliverables add column original_filename text;\n  end if;\n  if not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''custom_order_deliverables'' and column_name = ''mime_type'') then\n    alter table public.custom_order_deliverables add column mime_type text;\n  end if;\n  if not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''custom_order_deliverables'' and column_name = ''file_size'') then\n    alter table public.custom_order_deliverables add column file_size bigint;\n  end if;\n  if not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''custom_order_deliverables'' and column_name = ''file_size_bytes'') then\n    alter table public.custom_order_deliverables add column file_size_bytes bigint;\n  end if;\nend\n$alter$", "comment on column public.custom_order_deliverables.storage_path is\n  ''Storage object key(버킷 내부, ASCII-only). 예: {orderId}/{ver}/{ts}-{8hex}.png — 원본 한글 파일명은 original_filename.''", "-- ---------------------------------------------------------------------------\n-- 2) Storage bucket (private)\n-- ---------------------------------------------------------------------------\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues (\n  ''custom-order-deliverables'',\n  ''custom-order-deliverables'',\n  false,\n  20971520,\n  array[\n    ''application/pdf'',\n    ''image/png'',\n    ''image/jpeg'',\n    ''image/webp'',\n    ''application/zip'',\n    ''application/vnd.openxmlformats-officedocument.wordprocessingml.document'',\n    ''application/vnd.openxmlformats-officedocument.presentationml.presentation''\n  ]::text[]\n)\non conflict (id) do update set\n  public = excluded.public,\n  file_size_limit = coalesce(excluded.file_size_limit, storage.buckets.file_size_limit),\n  allowed_mime_types = coalesce(excluded.allowed_mime_types, storage.buckets.allowed_mime_types)", "-- ---------------------------------------------------------------------------\n-- 3) Path → 주문 UUID(첫 세그먼트) + 당사자/멘토 판단 (storage RLS)\n-- ---------------------------------------------------------------------------\ncreate or replace function public.cro_uuid_from_deliverable_storage_path(p_name text)\nreturns uuid\nlanguage plpgsql\nimmutable\nsecurity definer\nset search_path = public\nas $f$\nbegin\n  return nullif(split_part(p_name, ''/'', 1), '''')::uuid;\nexception\n  when others then\n    return null;\nend;\n$f$", "create or replace function public.user_is_party_to_cro_storage_path(p_name text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $f$\n  select exists (\n    select 1\n    from public.custom_request_orders o\n    where o.id = public.cro_uuid_from_deliverable_storage_path(p_name)\n      and (\n        (select auth.uid()) in (o.student_id, o.mentor_id)\n        or (select auth.uid()) in (o.buyer_id, o.client_id, o.user_id, o.author_id, o.requester_id)\n        or (select public.is_admin()) = true\n      )\n  );\n$f$", "create or replace function public.user_is_mentor_of_cro_storage_path(p_name text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $f$\n  select exists (\n    select 1\n    from public.custom_request_orders o\n    where o.id = public.cro_uuid_from_deliverable_storage_path(p_name)\n      and o.mentor_id = (select auth.uid())\n  );\n$f$", "-- storage.objects: SELECT 당사자, INSERT 멘토만(납품 업로드)\ndrop policy if exists \"custom_order_deliverable_storage_read_party\" on storage.objects", "create policy \"custom_order_deliverable_storage_read_party\"\n  on storage.objects\n  for select\n  to authenticated\n  using (\n    bucket_id = ''custom-order-deliverables''\n    and public.user_is_party_to_cro_storage_path(name)\n  )", "drop policy if exists \"custom_order_deliverable_storage_insert_mentor\" on storage.objects", "create policy \"custom_order_deliverable_storage_insert_mentor\"\n  on storage.objects\n  for insert\n  to authenticated\n  with check (\n    bucket_id = ''custom-order-deliverables''\n    and public.user_is_mentor_of_cro_storage_path(name)\n  )", "-- (선택) storage.objects RLS on storage: Supabase는 기본으로 storage.objects RLS on — bucket 정책 누적\n-- create index: 주문+버전 조회는 003에 idx_cdel_order 존재\ncreate index if not exists idx_cdel_order_storage\n  on public.custom_order_deliverables (custom_request_order_id, storage_path)\n  where storage_path is not null", "-- =============================================================================\n-- Supabase — 검증용 (SQL Editor)\n-- -- 버킷\n-- select * from storage.buckets where id = ''custom-order-deliverables'';\n-- -- deliverables 열\n-- select column_name, data_type from information_schema.columns\n--   where table_schema = ''public'' and table_name = ''custom_order_deliverables'' order by ordinal_position;\n-- -- storage policies\n-- select * from pg_policies where schemaname = ''storage'' and tablename = ''objects'' and policyname like ''custom_order_deliverable%'';\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0013 | supabase/bundles/bundle_1_base_001_031.sql | 011_p0_custom_order_deliverable_version_unique.sql <<<\n-- ===== 011_p0_custom_order_deliverable_version_unique.sql =====\n\n-- P0: 동일 주문(custom_request_order_id)에 동일 version 의 납품이 2건 이상 생기지 않도록 DB 제약\n-- 선행: 003/010( custom_order_deliverables ), 010 Storage\n-- idempotent: unique index IF NOT EXISTS\n-- [주의] 이미 동일 (custom_request_order_id, version) 이 2행 이상이면 인덱스 생성이 **실패**한다.\n--        선행: 아래 \"중복 행\" 주석 쿼리로 확인 후 수동 병합·정리, 그다음 이 파일 실행.\n\ncreate unique index if not exists deliverables_order_version_unique\n  on public.custom_order_deliverables (custom_request_order_id, version)\n  where custom_request_order_id is not null and version is not null", "-- =============================================================================\n-- Supabase SQL Editor — 확인용(주석)\n-- =============================================================================\n-- -- 1) unique index 존재\n-- select indexname, indexdef\n-- from pg_indexes\n-- where schemaname = ''public''\n--   and tablename = ''custom_order_deliverables''\n--   and indexname = ''deliverables_order_version_unique'';\n--\n-- -- 2) (적용 전) custom_request_order_id+version 중복 행(정리 전 점검)\n-- -- select custom_request_order_id, version, count(*)\n-- -- from public.custom_order_deliverables\n-- -- where custom_request_order_id is not null and version is not null\n-- -- group by 1, 2\n-- -- having count(*) > 1;\n--\n-- -- 3) 고아 storage object (DB에 storage_path 가 없는 버킷 객체) — storage_path = name 주의\n-- -- select obj.name, obj.id\n-- -- from storage.objects obj\n-- -- left join public.custom_order_deliverables d\n-- --   on d.storage_path = obj.name\n-- -- where obj.bucket_id = ''custom-order-deliverables''\n-- --   and d.id is null;\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0014 | supabase/bundles/bundle_1_base_001_031.sql | 012_p0_custom_request_post_attachments_storage.sql <<<\n-- ===== 012_p0_custom_request_post_attachments_storage.sql =====\n\n-- P0: 맞춤의뢰 등록 첨부 — private Storage + custom_request_post_attachments + storage.objects RLS\n-- 선행: 001( users ), 003( custom_request_posts ) — is_admin() 정의 권장\n-- 010( custom-order-deliverables )와 버킷/정책명 분리, idempotent\n\n-- ---------------------------------------------------------------------------\n-- 1) custom_request_post_attachments\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.custom_request_post_attachments (\n  id uuid primary key default gen_random_uuid(),\n  custom_request_post_id uuid not null references public.custom_request_posts (id) on delete cascade,\n  uploaded_by uuid not null references public.users (id) on delete restrict,\n  storage_path text not null,\n  original_filename text not null,\n  mime_type text,\n  file_size_bytes bigint,\n  created_at timestamptz not null default now()\n)", "comment on table public.custom_request_post_attachments is\n  ''의뢰 등록 시 학생이 올린 첨부 메타. storage_path 는 ASCII 키(버킷 내부), 표시명은 original_filename.''", "create index if not exists idx_crpa_post_created\n  on public.custom_request_post_attachments (custom_request_post_id, created_at asc)", "alter table public.custom_request_post_attachments enable row level security", "-- post 작성자(동의어) 또는 mentor/admin — 멘토는 지원 전 의뢰 열람·다운로드\ndrop policy if exists \"crpa_select_authorized\" on public.custom_request_post_attachments", "create policy \"crpa_select_authorized\"\n  on public.custom_request_post_attachments\n  for select\n  to authenticated\n  using (\n    (select public.is_admin()) = true\n    or exists (select 1 from public.users u where u.id = (select auth.uid()) and u.role = ''mentor'')\n    or exists (\n      select 1\n      from public.custom_request_posts p\n      where p.id = custom_request_post_id\n        and (\n          p.author_id = (select auth.uid())\n          or p.student_id = (select auth.uid())\n          or p.user_id = (select auth.uid())\n          or p.requester_id = (select auth.uid())\n          or p.client_id = (select auth.uid())\n        )\n    )\n  )", "drop policy if exists \"crpa_insert_author\" on public.custom_request_post_attachments", "create policy \"crpa_insert_author\"\n  on public.custom_request_post_attachments\n  for insert\n  to authenticated\n  with check (\n    uploaded_by = (select auth.uid())\n    and exists (\n      select 1\n      from public.custom_request_posts p\n      where p.id = custom_request_post_id\n        and (\n          p.author_id = (select auth.uid())\n          or p.student_id = (select auth.uid())\n          or p.user_id = (select auth.uid())\n          or p.requester_id = (select auth.uid())\n          or p.client_id = (select auth.uid())\n        )\n    )\n  )", "-- ---------------------------------------------------------------------------\n-- 2) Storage bucket (private)\n-- ---------------------------------------------------------------------------\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues (\n  ''custom-request-post-attachments'',\n  ''custom-request-post-attachments'',\n  false,\n  20971520,\n  array[\n    ''application/pdf'',\n    ''image/png'',\n    ''image/jpeg'',\n    ''image/webp'',\n    ''application/zip'',\n    ''application/vnd.openxmlformats-officedocument.wordprocessingml.document'',\n    ''application/vnd.openxmlformats-officedocument.presentationml.presentation''\n  ]::text[]\n)\non conflict (id) do update set\n  public = excluded.public,\n  file_size_limit = coalesce(excluded.file_size_limit, storage.buckets.file_size_limit),\n  allowed_mime_types = coalesce(excluded.allowed_mime_types, storage.buckets.allowed_mime_types)", "-- ---------------------------------------------------------------------------\n-- 3) Path → post UUID(첫 세그먼트) + 권한 (storage RLS)\n-- ---------------------------------------------------------------------------\ncreate or replace function public.crp_uuid_from_post_attachment_path(p_name text)\nreturns uuid\nlanguage plpgsql\nimmutable\nsecurity definer\nset search_path = public\nas $f$\nbegin\n  return nullif(split_part(p_name, ''/'', 1), '''')::uuid;\nexception\n  when others then\n    return null;\nend;\n$f$", "create or replace function public.user_is_post_author_for_crpa_path(p_name text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $f$\n  select exists (\n    select 1\n    from public.custom_request_posts p\n    where p.id = public.crp_uuid_from_post_attachment_path(p_name)\n      and (\n        p.author_id = (select auth.uid())\n        or p.student_id = (select auth.uid())\n        or p.user_id = (select auth.uid())\n        or p.requester_id = (select auth.uid())\n        or p.client_id = (select auth.uid())\n      )\n  );\n$f$", "create or replace function public.user_can_read_crpa_storage_path(p_name text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $f$\n  select\n    (select public.is_admin()) = true\n    or public.user_is_post_author_for_crpa_path(p_name) = true\n    or exists (select 1 from public.users u where u.id = (select auth.uid()) and u.role = ''mentor'');\n$f$", "-- storage.objects: 읽기 — 작성자·멘토·admin / 쓰기 — 작성자만(의뢰 등록 시 업로드)\ndrop policy if exists \"crpa_storage_read_authorized\" on storage.objects", "create policy \"crpa_storage_read_authorized\"\n  on storage.objects\n  for select\n  to authenticated\n  using (\n    bucket_id = ''custom-request-post-attachments''\n    and public.user_can_read_crpa_storage_path(name)\n  )", "drop policy if exists \"crpa_storage_insert_author\" on storage.objects", "create policy \"crpa_storage_insert_author\"\n  on storage.objects\n  for insert\n  to authenticated\n  with check (\n    bucket_id = ''custom-request-post-attachments''\n    and public.user_is_post_author_for_crpa_path(name)\n  )", "-- =============================================================================\n-- Supabase — 검증용 (SQL Editor)\n-- -- 테이블\n-- select column_name, data_type from information_schema.columns\n--   where table_schema = ''public'' and table_name = ''custom_request_post_attachments'' order by ordinal_position;\n-- -- 버킷\n-- select * from storage.buckets where id = ''custom-request-post-attachments'';\n-- -- storage policies\n-- select * from pg_policies\n--   where schemaname = ''storage'' and tablename = ''objects'' and policyname like ''crpa_%'';\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0015 | supabase/bundles/bundle_1_base_001_031.sql | 013_p0_custom_order_settlement_items.sql <<<\n-- ===== 013_p0_custom_order_settlement_items.sql =====\n\n-- P0: 맞춤의뢰 주문 — 멘토 정산 예정(1차) + 금액·상태 메타\n-- 선행: 001(users), 003(custom_request_posts, custom_request_orders) · is_admin()\n-- idempotent, 010/012와 충돌 없음\n--\n-- 보강(학생 insert 제거·CHECK·서비스 롤 insert): 014_p0_harden_custom_order_settlement_items.sql\n\n-- ---------------------------------------------------------------------------\n-- 1) custom_order_settlement_items\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.custom_order_settlement_items (\n  id uuid primary key default gen_random_uuid(),\n  custom_request_order_id uuid not null references public.custom_request_orders (id) on delete cascade,\n  mentor_id uuid not null references public.users (id) on delete restrict,\n  student_id uuid references public.users (id) on delete set null,\n  gross_amount integer not null,\n  platform_fee_amount integer not null,\n  mentor_amount integer not null,\n  fee_rate numeric not null default 0.20,\n  status text not null default ''pending'' check (status in (''pending'', ''on_hold'', ''payable'', ''paid'', ''cancelled'')),\n  reason text,\n  paid_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "comment on table public.custom_order_settlement_items is\n  ''맞춤의뢰 주문 납품 수락 후 정산·지급 후보(실제 PG/지급은 별도).''", "create unique index if not exists uq_cosi_one_per_order\n  on public.custom_order_settlement_items (custom_request_order_id)", "create index if not exists idx_cosi_mentor_created\n  on public.custom_order_settlement_items (mentor_id, created_at desc)", "create index if not exists idx_cosi_student\n  on public.custom_order_settlement_items (student_id, created_at desc)", "drop trigger if exists trg_cosi_set_updated on public.custom_order_settlement_items", "create trigger trg_cosi_set_updated\n  before update on public.custom_order_settlement_items\n  for each row execute function public.set_updated_at()", "alter table public.custom_order_settlement_items enable row level security", "-- 당사자(학생·멘토) + admin — insert는 학생(의뢰자) 본인만(수락 액션)\ndrop policy if exists \"cosi_select_parties\" on public.custom_order_settlement_items", "create policy \"cosi_select_parties\"\n  on public.custom_order_settlement_items\n  for select\n  to authenticated\n  using (\n    (select public.is_admin()) = true\n    or mentor_id = (select auth.uid())\n    or student_id = (select auth.uid())\n  )", "drop policy if exists \"cosi_insert_by_student\" on public.custom_order_settlement_items", "create policy \"cosi_insert_by_student\"\n  on public.custom_order_settlement_items\n  for insert\n  to authenticated\n  with check ( student_id = (select auth.uid()) )", "-- 정산 row 갱신은 운영·배치(서비스) 전제 — 클라이언트 직접 update 방지(관리자만)\ndrop policy if exists \"cosi_update_admin\" on public.custom_order_settlement_items", "create policy \"cosi_update_admin\"\n  on public.custom_order_settlement_items\n  for update\n  to authenticated\n  using ( (select public.is_admin()) = true )\n  with check ( (select public.is_admin()) = true )", "-- =============================================================================\n-- Supabase — 검증용\n-- -- 테이블\n-- select column_name, data_type from information_schema.columns\n--   where table_schema = ''public'' and table_name = ''custom_order_settlement_items'' order by ordinal_position;\n-- -- 특정 주문\n-- select * from public.custom_order_settlement_items where custom_request_order_id = ''<uuid>'';\n-- -- 멘토 목록\n-- select * from public.custom_order_settlement_items where mentor_id = auth.uid() order by created_at desc;\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0016 | supabase/bundles/bundle_1_base_001_031.sql | 014_p0_harden_custom_order_settlement_items.sql <<<\n-- ===== 014_p0_harden_custom_order_settlement_items.sql =====\n\n-- P0 보강: custom_order_settlement_items — RLS(학생 직접 insert 제거) + 금액·요율 CHECK\n-- 선행: 013_p0_custom_order_settlement_items.sql — 스테이징에 013만 있으면 014만 추가 적용하면 됨\n-- idempotent\n\n-- ---------------------------------------------------------------------------\n-- 1) RLS: authenticated 학생 insert 제거 (정산 insert는 service role·서버 전용)\n-- ---------------------------------------------------------------------------\ndrop policy if exists \"cosi_insert_by_student\" on public.custom_order_settlement_items", "-- ---------------------------------------------------------------------------\n-- 2) CHECK 제약(기존에 없을 때만). 위반 행이 있으면 ADD CONSTRAINT는 실패할 수 있음 — 데이터 정리 후 재실행.\n-- ---------------------------------------------------------------------------\ndo $$\nbegin\n  if not exists (\n    select 1 from pg_constraint\n    where conname = ''cosi_chk_amounts_core''\n  ) then\n    alter table public.custom_order_settlement_items\n      add constraint cosi_chk_amounts_core check (\n        gross_amount > 0\n        and mentor_amount > 0\n        and platform_fee_amount >= 0\n        and (platform_fee_amount + mentor_amount) = gross_amount\n      );\n  end if;\nend $$", "do $$\nbegin\n  if not exists (\n    select 1 from pg_constraint\n    where conname = ''cosi_chk_fee_rate_bounds''\n  ) then\n    alter table public.custom_order_settlement_items\n      add constraint cosi_chk_fee_rate_bounds check (fee_rate >= 0 and fee_rate <= 1);\n  end if;\nend $$", "-- status CHECK는 013 create table 시 이미 포함됨 (pending, on_hold, payable, paid, cancelled)\n\n-- custom_request_order_id 유일: 013 uq_cosi_one_per_order 인덱스로 이미 강제됨.\n-- (테이블이 비어 unique constraint만 필요하면) 이름 있는 UNIQUE는 인덱스로 충분.\n\n-- =============================================================================\n-- 검증(수동)\n-- \\d+ public.custom_order_settlement_items\n-- select conname from pg_constraint where conrelid = ''public.custom_order_settlement_items''::regclass;\n-- select * from pg_policies where tablename = ''custom_order_settlement_items'';\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0017 | supabase/bundles/bundle_1_base_001_031.sql | 015_p0_prevent_settlement_during_active_dispute.sql <<<\n-- ===== 015_p0_prevent_settlement_during_active_dispute.sql =====\n\n-- P0: 진행 중 분쟁이 있을 때 custom_order_settlement_items INSERT 차단 (RLS·service role 모두 동일)\n-- 선행: 004(disputes), 013(custom_order_settlement_items)\n-- active dispute: disputes.status in (open, under_review, escalated) — orderDisputeHelpers와 동일\n-- idempotent: CREATE OR REPLACE FUNCTION + DROP TRIGGER IF EXISTS\n\ncreate or replace function public.trg_block_settlement_on_active_dispute()\nreturns trigger\nlanguage plpgsql\nsecurity invoker\nset search_path = public\nas $fn$\ndeclare\n  v_cnt integer;\nbegin\n  if new.custom_request_order_id is null then\n    return new;\n  end if;\n\n  select count(*)::integer\n    into v_cnt\n  from public.disputes d\n  where d.custom_request_order_id = new.custom_request_order_id\n    and d.status in (''open'', ''under_review'', ''escalated'');\n\n  if v_cnt > 0 then\n    raise exception ''settlement insert blocked: active dispute for order %'', new.custom_request_order_id\n      using errcode = ''P0001'',\n            hint = ''진행 중인 분쟁이 있으면 정산 예정을 추가할 수 없습니다.'';\n  end if;\n\n  return new;\nend;\n$fn$", "drop trigger if exists trg_cosi_prevent_active_dispute on public.custom_order_settlement_items", "create trigger trg_cosi_prevent_active_dispute\n  before insert on public.custom_order_settlement_items\n  for each row\n  execute function public.trg_block_settlement_on_active_dispute()", "-- =============================================================================\n-- 확인용 (수동 실행)\n-- -- 1) trigger 존재\n-- select event_object_table, trigger_name, action_timing, event_manipulation\n-- from information_schema.triggers\n-- where trigger_schema = ''public''\n--   and event_object_table = ''custom_order_settlement_items''\n--   and trigger_name = ''trg_cosi_prevent_active_dispute'';\n--\n-- -- 2) function 존재\n-- select routine_schema, routine_name, routine_type\n-- from information_schema.routines\n-- where routine_schema = ''public''\n--   and routine_name = ''trg_block_settlement_on_active_dispute'';\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0018 | supabase/bundles/bundle_1_base_001_031.sql | 016_p0_community_comments.sql <<<\n-- ===== 016_p0_community_comments.sql =====\n\n-- 커뮤니티 게시판/숏폼 공용 댓글 (post_type + post_id로 글을 가리킴, FK는 게시글 테이블에 직접 연결하지 않음)\n-- 선행: 001(확장 pgcrypto, public.set_updated_at)\n-- v1 RLS: SELECT(visible) + INSERT(로그인·본인)만. UPDATE/DELETE/관리자는 추후(서비스 롤·별도 SQL).\n\ncreate extension if not exists pgcrypto", "-- ---------------------------------------------------------------------------\n-- 1) 테이블\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.community_comments (\n  id uuid primary key default gen_random_uuid(),\n  post_type text not null\n    check (post_type in (''board'', ''shortform'')),\n  post_id uuid not null,\n  author_id uuid not null references auth.users (id) on delete cascade,\n  -- RLS로 타인 public.users 를 읽기 어려울 수 있어, 등록 시 표시용 스냅샷만 저장\n  author_label text not null default ''쌤버십 회원'',\n  body text not null,\n  status text not null default ''visible'',\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint community_comments_status_chk check (status in (''visible'', ''hidden'')),\n  constraint community_comments_body_len_chk\n    check (char_length(trim(body)) between 1 and 1000)\n)", "create index if not exists community_comments_post_list_idx\n  on public.community_comments (post_type, post_id, created_at asc)", "create index if not exists community_comments_author_idx\n  on public.community_comments (author_id)", "drop trigger if exists trg_community_comments_set_updated on public.community_comments", "create trigger trg_community_comments_set_updated\n  before update on public.community_comments\n  for each row execute function public.set_updated_at()", "-- ---------------------------------------------------------------------------\n-- 2) RLS\n-- ---------------------------------------------------------------------------\nalter table public.community_comments enable row level security", "-- 읽기: visible 만 (anon 포함)\ndrop policy if exists \"community_comments_select_visible\" on public.community_comments", "create policy \"community_comments_select_visible\"\n  on public.community_comments\n  for select\n  to anon, authenticated\n  using (status = ''visible'')", "-- 쓰기: 로그인, 본인을 author_id 로, body 길이·post_type 는 테이블 check 와 RLS로 이중 맞춤\ndrop policy if exists \"community_comments_insert_authenticated\" on public.community_comments", "create policy \"community_comments_insert_authenticated\"\n  on public.community_comments\n  for insert\n  to authenticated\n  with check (\n    author_id = (select auth.uid())\n    and (select auth.uid()) is not null\n    and char_length(trim(body)) between 1 and 1000\n  )", "-- ---------------------------------------------------------------------------\n-- 3) 확인용 (Supabase SQL Editor; 주석)\n-- select id, post_type, post_id, left(body, 30), author_label, status, created_at\n-- from public.community_comments\n-- order by created_at desc\n-- limit 5;\n\n\n-- >>> NATIVE_BASELINE_PART 0019 | supabase/bundles/bundle_1_base_001_031.sql | 017_p0_community_author_role_compat.sql <<<\n-- ===== 017_p0_community_author_role_compat.sql =====\n\n-- P0: community_posts / shortform_posts — author_role (앱 insert와 스키마 정렬)\n-- idempotent, staging(컬럼 부족) / 로컬 초안(004) 모두에 적용 가능\n-- Supabase: SQL Editor에서 실행\n\n-- ---------------------------------------------------------------------------\n-- public.community_posts\n-- ---------------------------------------------------------------------------\nalter table public.community_posts\n  add column if not exists author_role text default ''mentor''", "update public.community_posts\nset author_role = ''mentor''\nwhere author_role is null", "alter table public.community_posts\n  alter column author_role set default ''mentor''", "do $do$\nbegin\n  if not exists (\n    select 1\n    from pg_constraint\n    where conname = ''community_posts_author_role_chk''\n      and conrelid = ''public.community_posts''::regclass\n  ) then\n    alter table public.community_posts\n      add constraint community_posts_author_role_chk\n      check (author_role in (''mentor'', ''student'', ''admin'', ''user''));\n  end if;\nend\n$do$", "-- ---------------------------------------------------------------------------\n-- public.shortform_posts\n-- ---------------------------------------------------------------------------\nalter table public.shortform_posts\n  add column if not exists author_role text default ''mentor''", "update public.shortform_posts\nset author_role = ''mentor''\nwhere author_role is null", "alter table public.shortform_posts\n  alter column author_role set default ''mentor''", "do $do$\nbegin\n  if not exists (\n    select 1\n    from pg_constraint\n    where conname = ''shortform_posts_author_role_chk''\n      and conrelid = ''public.shortform_posts''::regclass\n  ) then\n    alter table public.shortform_posts\n      add constraint shortform_posts_author_role_chk\n      check (author_role in (''mentor'', ''student'', ''admin'', ''user''));\n  end if;\nend\n$do$", "-- ---------------------------------------------------------------------------\n-- 확인용 (Supabase SQL Editor; 주석)\n-- select id, author_id, author_role, title, left(body, 30) as body_excerpt, category, created_at\n--   from public.community_posts\n--  order by created_at desc\n--  limit 5;\n-- select id, author_id, author_role, title, left(body, 30) as body_excerpt, category, source, created_at\n--   from public.shortform_posts\n--  order by created_at desc\n--  limit 5;\n\n\n-- >>> NATIVE_BASELINE_PART 0020 | supabase/bundles/bundle_1_base_001_031.sql | 018_p0_mentor_list_open_custom_request_posts.sql <<<\n-- ===== 018_p0_mentor_list_open_custom_request_posts.sql =====\n\n-- P0: Mentor/admin browse list for open custom request posts.\n-- custom_request_posts is protected by RLS, so mentors cannot directly SELECT the open request list.\n-- This SECURITY DEFINER RPC exposes only the fields needed for the mentor browse/list UI.\n-- Idempotent: create or replace.\n-- Run after the existing 006 browse RPC in the Supabase SQL Editor.\ndrop function if exists public.list_open_custom_request_posts_for_mentor_browse(integer)", "create or replace function public.list_open_custom_request_posts_for_mentor_browse(p_limit int default 50)\nreturns table (\n  id uuid,\n  title text,\n  body text,\n  content text,\n  subject text,\n  description text,\n  goal text,\n  subcategory text,\n  category text,\n  due_at timestamptz,\n  deadline timestamptz,\n  due_date timestamptz,\n  deliverable_type text,\n  deliverable_format text,\n  result_format text,\n  output_format text,\n  budget_min numeric,\n  budget_max numeric,\n  state text,\n  status text,\n  created_at timestamptz,\n  updated_at timestamptz\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $fn$\n  select\n    p.id,\n    p.title,\n    p.body,\n    p.content,\n    p.subject,\n    p.description,\n    p.goal,\n    p.subcategory,\n    p.category,\n    p.due_at,\n    p.deadline,\n    p.due_date,\n    p.deliverable_type,\n    p.deliverable_format,\n    p.result_format,\n    p.output_format,\n    p.budget_min,\n    p.budget_max,\n    p.state,\n    p.status,\n    p.created_at,\n    p.updated_at\n  from public.custom_request_posts p\n  where (select auth.uid()) is not null\n    and (\n      (select public.is_admin()) = true\n      or (\n        exists (\n          select 1\n          from public.users u\n          where u.id = (select auth.uid())\n            and u.role = ''mentor''\n        )\n        and (\n          lower(trim(coalesce(p.status, ''''))) = ''open''\n          or lower(trim(coalesce(p.state, ''''))) in (''open'', ''published'')\n        )\n      )\n    )\n  order by p.created_at desc\n  limit least(coalesce(nullif(p_limit, 0), 50), 200);\n$fn$", "revoke all on function public.list_open_custom_request_posts_for_mentor_browse(int) from public", "grant execute on function public.list_open_custom_request_posts_for_mentor_browse(int) to authenticated", "comment on function public.list_open_custom_request_posts_for_mentor_browse(int) is\n  ''P0: Mentor/admin browse list for open custom request posts. Used because direct SELECT on custom_request_posts is restricted by RLS.''", "-- >>> NATIVE_BASELINE_PART 0021 | supabase/bundles/bundle_1_base_001_031.sql | 019_p0_subscription_cash_debit.sql <<<\n-- ===== 019_p0_subscription_cash_debit.sql =====\n\n-- P0: 구독 체크아웃 — 캐시 원장 차감 + 지갑을 단일 DB 함수(원자적 트랜잭션)에서 처리\n-- 004_p0_cash_disputes_admin_draft (cash_ledger, cash_wallets) 이후 적용 권장\n--\n-- 호출: service_role (서버) 전용. 클라이언트/ authenticated 에 직접 부여하지 않는다.\n-- 016 스키마 파일(community)과 번호가 겹치지 않게 019로 둔다.\n\ncreate or replace function public.record_subscription_cash_debit(\n  p_user_id uuid,\n  p_subscription_id uuid,\n  p_payment_id uuid,\n  p_amount_cents bigint\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_idem text := ''sub_debit_'' || p_payment_id::text;\n  v_new_ledger_id uuid;\n  v_wu int;\nbegin\n  if p_user_id is null or p_subscription_id is null or p_payment_id is null then\n    raise exception ''p_user_id, p_subscription_id, p_payment_id are required'';\n  end if;\n\n  if p_amount_cents is null or p_amount_cents <= 0 then\n    raise exception ''p_amount_cents must be a positive amount'';\n  end if;\n\n  -- 1) 멱등: idempotency_key 는 전역 unique. 먼저 insert 시도 → conflict 이면 이미 처리됨(지갑 재차감 없음)\n  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n  values (\n    p_user_id,\n    -p_amount_cents,\n    ''subscription_payment'',\n    ''subscriptions'',\n    p_subscription_id,\n    v_idem\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_new_ledger_id;\n\n  if v_new_ledger_id is null then\n    return;\n  end if;\n\n  -- 2) wallet 행 + 잔액 차감 (insert 성공한 트랜잭션만 아래로 진행; 실패 시 1) 롤백)\n  insert into public.cash_wallets (user_id, balance_cents)\n  values (p_user_id, 0)\n  on conflict (user_id) do nothing;\n\n  update public.cash_wallets w\n  set balance_cents = w.balance_cents - p_amount_cents\n  where w.user_id = p_user_id\n    and w.balance_cents >= p_amount_cents;\n  get diagnostics v_wu = row_count;\n  if coalesce(v_wu, 0) = 0 then\n    raise exception ''CASH_INSUFFICIENT'' using errcode = ''P0001'';\n  end if;\nend;\n$function$", "revoke all on function public.record_subscription_cash_debit(uuid, uuid, uuid, bigint) from public", "-- record_subscription_cash_debit 성공 뒤 결제 상태 표시(마크)가 실패할 때만: 원장+지갑을 한 번에 되돌림(append-only, 멱등)\ncreate or replace function public.record_subscription_cash_rollback(\n  p_user_id uuid,\n  p_subscription_id uuid,\n  p_payment_id uuid,\n  p_amount_cents bigint\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_idem text := ''sub_rollback_'' || p_payment_id::text;\n  v_new_ledger_id uuid;\n  v_wu int;\nbegin\n  if p_user_id is null or p_subscription_id is null or p_payment_id is null then\n    raise exception ''p_user_id, p_subscription_id, p_payment_id are required'';\n  end if;\n  if p_amount_cents is null or p_amount_cents <= 0 then\n    return;\n  end if;\n\n  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n  values (\n    p_user_id,\n    p_amount_cents,\n    ''subscription_checkout_rollback'',\n    ''subscriptions'',\n    p_subscription_id,\n    v_idem\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_new_ledger_id;\n\n  if v_new_ledger_id is null then\n    return;\n  end if;\n\n  update public.cash_wallets w\n  set balance_cents = w.balance_cents + p_amount_cents\n  where w.user_id = p_user_id;\n  get diagnostics v_wu = row_count;\n  if coalesce(v_wu, 0) = 0 then\n    insert into public.cash_wallets (user_id, balance_cents)\n    values (p_user_id, p_amount_cents);\n  end if;\nend;\n$function$", "revoke all on function public.record_subscription_cash_rollback(uuid, uuid, uuid, bigint) from public", "-- 주석: authenticated 에 grant 하지 않음. 애플리케이션에서 createServiceRoleClient (service_role JWT)로만 invoke.\n\n\n-- >>> NATIVE_BASELINE_PART 0022 | supabase/bundles/bundle_1_base_001_031.sql | 020_p0_cash_topup_charge.sql <<<\n-- ===== 020_p0_cash_topup_charge.sql =====\n\n-- P0: 캐시 충전 — 원장(양수) + 지갑 증가를 한 트랜잭션에서 처리\n-- 004_p0_cash_disputes_admin_draft (cash_wallets, cash_ledger) 이후 적용 권장\n--\n-- 호출: service_role(서버) 전용. authenticated/anon에 GRANT 하지 않는다.\n\ncreate or replace function public.record_cash_topup(\n  p_user_id uuid,\n  p_amount_cents bigint,\n  p_idempotency_key text\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_new_ledger_id uuid;\n  v_wu int;\n  v_idem text;\nbegin\n  if p_user_id is null then\n    raise exception ''p_user_id is required'';\n  end if;\n  v_idem := nullif(trim(coalesce(p_idempotency_key, '''')), '''');\n  if v_idem is null or length(v_idem) = 0 then\n    raise exception ''p_idempotency_key is required'';\n  end if;\n  if p_amount_cents is null or p_amount_cents <= 0 then\n    raise exception ''p_amount_cents must be positive'';\n  end if;\n  if p_amount_cents > 1000000000 then\n    raise exception ''p_amount_too_large'';\n  end if;\n\n  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n  values (\n    p_user_id,\n    p_amount_cents,\n    ''cash_topup'',\n    ''topup'',\n    null,\n    v_idem\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_new_ledger_id;\n\n  if v_new_ledger_id is null then\n    return;\n  end if;\n\n  insert into public.cash_wallets (user_id, balance_cents)\n  values (p_user_id, 0)\n  on conflict (user_id) do nothing;\n\n  update public.cash_wallets w\n  set balance_cents = w.balance_cents + p_amount_cents\n  where w.user_id = p_user_id;\n  get diagnostics v_wu = row_count;\n  if coalesce(v_wu, 0) = 0 then\n    raise exception ''CASH_WALLET_UPSERT_FAILED'' using errcode = ''P0001'';\n  end if;\nend;\n$function$", "revoke all on function public.record_cash_topup(uuid, bigint, text) from public", "-- Supabase/앱: createServiceRoleClient() 로만 RPC 호출.\n\n\n-- >>> NATIVE_BASELINE_PART 0023 | supabase/bundles/bundle_1_base_001_031.sql | 021_p0_refund_ins_admin_only.sql <<<\n-- ===== 021_p0_refund_ins_admin_only.sql =====\n\n-- refunds INSERT: admin만 허용 (public.is_admin() = true)\n-- 선행: public.refunds, public.is_admin() (001/003/004 등)\n\ndrop policy if exists \"refund_ins\" on public.refunds", "create policy \"refund_ins\" on public.refunds\n  for insert to authenticated\n  with check ((select public.is_admin()) = true)", "-- >>> NATIVE_BASELINE_PART 0024 | supabase/bundles/bundle_1_base_001_031.sql | 022_p0_subscription_cash_debit_grants.sql <<<\n-- ===== 022_p0_subscription_cash_debit_grants.sql =====\n\ngrant execute on function public.record_subscription_cash_debit(uuid, uuid, uuid, bigint) to service_role", "grant execute on function public.record_subscription_cash_rollback(uuid, uuid, uuid, bigint) to service_role", "comment on function public.record_subscription_cash_debit(uuid, uuid, uuid, bigint)\n  is ''P0: Debits wallet cash for subscription checkout. Intended to be called only from trusted service-role server code.''", "comment on function public.record_subscription_cash_rollback(uuid, uuid, uuid, bigint)\n  is ''P0: Rolls back subscription wallet debit. Intended to be called only from trusted service-role server code.''", "-- >>> NATIVE_BASELINE_PART 0025 | supabase/bundles/bundle_1_base_001_031.sql | 023_p0_subscription_cash_debit_service_role_only.sql <<<\n-- ===== 023_p0_subscription_cash_debit_service_role_only.sql =====\n\nrevoke all on function public.record_subscription_cash_debit(uuid, uuid, uuid, bigint) from public", "revoke all on function public.record_subscription_cash_debit(uuid, uuid, uuid, bigint) from anon", "revoke all on function public.record_subscription_cash_debit(uuid, uuid, uuid, bigint) from authenticated", "revoke all on function public.record_subscription_cash_rollback(uuid, uuid, uuid, bigint) from public", "revoke all on function public.record_subscription_cash_rollback(uuid, uuid, uuid, bigint) from anon", "revoke all on function public.record_subscription_cash_rollback(uuid, uuid, uuid, bigint) from authenticated", "grant execute on function public.record_subscription_cash_debit(uuid, uuid, uuid, bigint) to service_role", "grant execute on function public.record_subscription_cash_rollback(uuid, uuid, uuid, bigint) to service_role", "comment on function public.record_subscription_cash_debit(uuid, uuid, uuid, bigint)\n  is ''P0: Service-role only RPC for subscription cash debit. Public, anon, and authenticated execution are explicitly revoked.''", "comment on function public.record_subscription_cash_rollback(uuid, uuid, uuid, bigint)\n  is ''P0: Service-role only RPC for subscription cash debit rollback. Public, anon, and authenticated execution are explicitly revoked.''", "-- >>> NATIVE_BASELINE_PART 0026 | supabase/bundles/bundle_1_base_001_031.sql | 024_p0_cash_topup_service_role_grant.sql <<<\n-- ===== 024_p0_cash_topup_service_role_grant.sql =====\n\nrevoke all on function public.record_cash_topup(uuid, bigint, text) from public", "revoke all on function public.record_cash_topup(uuid, bigint, text) from anon", "revoke all on function public.record_cash_topup(uuid, bigint, text) from authenticated", "grant execute on function public.record_cash_topup(uuid, bigint, text) to service_role", "comment on function public.record_cash_topup(uuid, bigint, text)\n  is ''P0: Service-role only RPC for test cash topup. Public, anon, and authenticated execution are explicitly revoked.''", "-- >>> NATIVE_BASELINE_PART 0027 | supabase/bundles/bundle_1_base_001_031.sql | 025_p0_payments_drop_update_own.sql <<<\n-- ===== 025_p0_payments_drop_update_own.sql =====\n\ndrop policy if exists \"payments_update_own\" on public.payments", "comment on table public.payments\n  is ''Payments are not user-updatable. Payment status transitions must be performed by trusted service-role server code.''", "-- >>> NATIVE_BASELINE_PART 0028 | supabase/bundles/bundle_1_base_001_031.sql | 026_p0_msr_insert_subscription_check.sql <<<\n-- ===== 026_p0_msr_insert_subscription_check.sql =====\n\ndrop policy if exists \"msr_insert_pair\" on public.mentor_student_rooms", "drop policy if exists \"msr_insert_with_active_subscription\" on public.mentor_student_rooms", "create policy \"msr_insert_with_active_subscription\" on public.mentor_student_rooms\n  for insert to authenticated\n  with check (\n    (select auth.uid()) = student_id\n    and exists (\n      select 1\n      from public.subscriptions s\n      where s.student_id = (select auth.uid())\n        and s.mentor_id = mentor_student_rooms.mentor_id\n        and s.status = ''active''\n    )\n  )", "comment on table public.mentor_student_rooms\n  is ''Question rooms require an active subscription for authenticated inserts. Trusted service-role server code may still bypass RLS for controlled room creation.''", "-- >>> NATIVE_BASELINE_PART 0029 | supabase/bundles/bundle_1_base_001_031.sql | 027_p0_harden_payments_and_question_room_rls.sql <<<\n-- ===== 027_p0_harden_payments_and_question_room_rls.sql =====\n\n-- =============================================================================\n-- 027 P0 harden payments and mentor_student_rooms RLS\n--\n-- Purpose\n-- 1. payments:\n--    - Authenticated users must NOT update payment status directly.\n--    - Payment status changes must happen only through trusted server/service_role flow.\n--\n-- 2. mentor_student_rooms:\n--    - Authenticated users must NOT insert rooms directly from the client.\n--    - Room creation must happen through subscription checkout server flow.\n--\n-- Notes\n-- - This migration intentionally does NOT create an authenticated INSERT policy\n--   for mentor_student_rooms.\n-- - service_role bypasses RLS, so finalizeSubscriptionCheckout can still create\n--   or reuse rooms through the server path.\n-- - Run this first on staging if possible.\n-- =============================================================================\n\n-- -----------------------------------------------------------------------------\n-- A) Harden public.payments\n-- -----------------------------------------------------------------------------\n\n-- Remove direct authenticated UPDATE policies.\ndrop policy if exists \"payments_update_own\" on public.payments", "drop policy if exists \"payments_update_student\" on public.payments", "drop policy if exists \"payments_user_update\" on public.payments", "drop policy if exists \"payments_students_update\" on public.payments", "-- Remove old broad policy if it exists.\n-- This may include UPDATE, so we split read/insert back into narrower policies.\ndrop policy if exists \"payments_self_rw\" on public.payments", "-- Keep authenticated read access only for own related rows.\ndrop policy if exists \"payments_select_own\" on public.payments", "create policy \"payments_select_own\" on public.payments\n  for select to authenticated\n  using (\n    (select auth.uid()) in (user_id, student_id, payer_id, mentor_id)\n  )", "-- Allow users to create only pending/processing payment intents for themselves.\n-- Actual success/failure status changes must be done by server/service_role.\ndrop policy if exists \"payments_insert_intent\" on public.payments", "create policy \"payments_insert_intent\" on public.payments\n  for insert to authenticated\n  with check (\n    (select auth.uid()) = user_id\n    and status in (''pending'', ''processing'')\n  )", "comment on table public.payments is\n  ''RLS: authenticated users can select own payments and insert pending intents only. No authenticated UPDATE policy.''", "-- -----------------------------------------------------------------------------\n-- B) Harden public.mentor_student_rooms\n-- -----------------------------------------------------------------------------\n\n-- Remove client-side room creation policies.\ndrop policy if exists \"msr_insert_pair\" on public.mentor_student_rooms", "drop policy if exists \"msr_insert_with_active_subscription\" on public.mentor_student_rooms", "-- Remove old broad policy if it exists.\ndrop policy if exists \"msr_pair\" on public.mentor_student_rooms", "-- Keep room visibility for participants.\ndrop policy if exists \"msr_select\" on public.mentor_student_rooms", "create policy \"msr_select\" on public.mentor_student_rooms\n  for select to authenticated\n  using (\n    (select auth.uid()) in (student_id, mentor_id)\n  )", "-- Remove broad participant UPDATE policy.\n-- Room rows should generally be controlled by server/service_role because\n-- student_id, mentor_id, and subscription_id are security-sensitive.\ndrop policy if exists \"msr_update_parties\" on public.mentor_student_rooms", "comment on table public.mentor_student_rooms is\n  ''RLS: authenticated users can select participant rooms only. No authenticated INSERT or UPDATE policy. Room creation is server/service_role only.''", "-- -----------------------------------------------------------------------------\n-- C) Verification queries to run manually after applying this SQL\n-- -----------------------------------------------------------------------------\n\n-- 1. payments must have no UPDATE policy.\n-- Expected result: 0 rows.\n-- SELECT policyname, cmd, qual, with_check\n-- FROM pg_policies\n-- WHERE schemaname = ''public''\n--   AND tablename = ''payments''\n--   AND cmd = ''UPDATE'';\n\n-- 2. mentor_student_rooms must have no INSERT policy.\n-- Expected result: 0 rows.\n-- SELECT policyname, cmd, with_check\n-- FROM pg_policies\n-- WHERE schemaname = ''public''\n--   AND tablename = ''mentor_student_rooms''\n--   AND cmd = ''INSERT'';\n\n-- 3. mentor_student_rooms must have no UPDATE policy.\n-- Expected result: 0 rows, unless you intentionally add a narrower server-reviewed policy later.\n-- SELECT policyname, cmd, qual, with_check\n-- FROM pg_policies\n-- WHERE schemaname = ''public''\n--   AND tablename = ''mentor_student_rooms''\n--   AND cmd = ''UPDATE'';\n\n-- 4. Detect rooms without subscription_id.\n-- Investigate every returned row before launch.\n-- SELECT id, student_id, mentor_id, subscription_id, created_at\n-- FROM public.mentor_student_rooms\n-- WHERE subscription_id IS NULL\n-- ORDER BY created_at DESC\n-- LIMIT 20;\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0030 | supabase/bundles/bundle_1_base_001_031.sql | 028_p0_lock_subscriptions_writes.sql <<<\n-- ===== 028_p0_lock_subscriptions_writes.sql =====\n\n-- P0: block authenticated direct INSERT/UPDATE on subscription tables.\n-- App writes go through service_role: insertSubscriptionRow in subscribeCheckoutService.ts\n-- - Does not change SELECT policies (except: subscriptions_pair is FOR ALL — dropped and\n--   replaced with SELECT-only when no SELECT/ALL policy would remain; see 002_p0/002_app drafts).\n-- - Does not change payments, mentor_student_rooms.\n\nDO $$\nDECLARE\n  nsel int;\nBEGIN\n  -- public.subscriptions\n  IF to_regclass(''public.subscriptions'') IS NOT NULL THEN\n    drop policy if exists \"subscriptions_insert_student\" on public.subscriptions;\n    drop policy if exists \"subscriptions_update_student\" on public.subscriptions;\n    drop policy if exists \"subscriptions_self_rw\" on public.subscriptions;\n    drop policy if exists \"subscriptions_pair\" on public.subscriptions;\n\n    select coalesce(count(*)::int, 0) into nsel\n    from pg_policies\n    where schemaname = ''public''\n      and tablename = ''subscriptions''\n      and cmd in (''SELECT'', ''ALL'');\n    if nsel is null then\n      nsel := 0;\n    end if;\n    if nsel = 0 then\n      -- Match 002_p0_subscriptions_questions_draft.sql (student_id, mentor_id).\n      -- 002_app_core_schema_draft \"subscriptions_pair\" used coalesce; if your schema\n      -- differs, add a SELECT policy manually.\n      drop policy if exists \"subscriptions_select_parties\" on public.subscriptions;\n      create policy \"subscriptions_select_parties\" on public.subscriptions\n        for select to authenticated\n        using ( (select auth.uid()) in (student_id, mentor_id) );\n    end if;\n  end if;\n\n  -- public.mentor_subscriptions\n  if to_regclass(''public.mentor_subscriptions'') is not null then\n    drop policy if exists \"mentor_subscriptions_insert_student\" on public.mentor_subscriptions;\n    drop policy if exists \"mentor_subscriptions_update_student\" on public.mentor_subscriptions;\n    drop policy if exists \"mentor_subscriptions_self_rw\" on public.mentor_subscriptions;\n  end if;\n\n  -- public.user_subscriptions\n  if to_regclass(''public.user_subscriptions'') is not null then\n    drop policy if exists \"user_subscriptions_insert_student\" on public.user_subscriptions;\n    drop policy if exists \"user_subscriptions_update_student\" on public.user_subscriptions;\n    drop policy if exists \"user_subscriptions_self_rw\" on public.user_subscriptions;\n  end if;\nEND\n$$", "-- Check (run in SQL editor; expect no INSERT/UPDATE for these tables from this migration):\n-- SELECT schemaname, tablename, policyname, cmd, with_check\n-- FROM pg_policies\n-- WHERE schemaname = ''public''\n--   AND tablename IN (''subscriptions'', ''mentor_subscriptions'', ''user_subscriptions'')\n--   AND cmd IN (''INSERT'', ''UPDATE'')\n-- ORDER BY tablename, cmd, policyname;\n\n\n-- >>> NATIVE_BASELINE_PART 0031 | supabase/bundles/bundle_1_base_001_031.sql | 029_p0_lock_subscription_deletes.sql <<<\n-- ===== 029_p0_lock_subscription_deletes.sql =====\n\n-- P0: remove authenticated DELETE (and listed FOR ALL / self_rw) policies on subscription tables.\n-- Service role is used for subscription lifecycle from the app; students must not delete rows to bypass status.\n-- 028: INSERT/UPDATE already locked down; this file targets DELETE and duplicate drops for self_rw/pair.\n-- Does not drop or alter SELECT-only policies (e.g. subscriptions_select_parties). Do not create new DELETE policies.\n\nDO $$\nBEGIN\n  IF to_regclass(''public.subscriptions'') IS NOT NULL THEN\n    drop policy if exists \"subscriptions_delete_student\" on public.subscriptions;\n    drop policy if exists \"subscriptions_delete_own\" on public.subscriptions;\n    drop policy if exists \"subscriptions_user_delete\" on public.subscriptions;\n    drop policy if exists \"subscriptions_self_rw\" on public.subscriptions;\n    drop policy if exists \"subscriptions_pair\" on public.subscriptions;\n  end if;\n\n  IF to_regclass(''public.mentor_subscriptions'') IS NOT NULL THEN\n    drop policy if exists \"mentor_subscriptions_delete_student\" on public.mentor_subscriptions;\n    drop policy if exists \"mentor_subscriptions_delete_own\" on public.mentor_subscriptions;\n    drop policy if exists \"mentor_subscriptions_user_delete\" on public.mentor_subscriptions;\n    drop policy if exists \"mentor_subscriptions_self_rw\" on public.mentor_subscriptions;\n    drop policy if exists \"mentor_subscriptions_pair\" on public.mentor_subscriptions;\n  end if;\n\n  IF to_regclass(''public.user_subscriptions'') IS NOT NULL THEN\n    drop policy if exists \"user_subscriptions_delete_student\" on public.user_subscriptions;\n    drop policy if exists \"user_subscriptions_delete_own\" on public.user_subscriptions;\n    drop policy if exists \"user_subscriptions_user_delete\" on public.user_subscriptions;\n    drop policy if exists \"user_subscriptions_self_rw\" on public.user_subscriptions;\n    drop policy if exists \"user_subscriptions_pair\" on public.user_subscriptions;\n  end if;\nEND\n$$", "-- After apply: no INSERT/UPDATE/DELETE policies on these tables (expected 0 rows):\n-- SELECT schemaname, tablename, policyname, cmd, qual, with_check\n-- FROM pg_policies\n-- WHERE schemaname = ''public''\n--   AND tablename IN (''subscriptions'', ''mentor_subscriptions'', ''user_subscriptions'')\n--   AND cmd IN (''INSERT'', ''UPDATE'', ''DELETE'')\n-- ORDER BY tablename, cmd, policyname;\n\n-- SELECT policies for parties (e.g. subscriptions_select_parties) should still exist; verify:\n-- SELECT schemaname, tablename, policyname, cmd, qual\n-- FROM pg_policies\n-- WHERE schemaname = ''public''\n--   AND tablename IN (''subscriptions'', ''mentor_subscriptions'', ''user_subscriptions'')\n--   AND cmd = ''SELECT''\n-- ORDER BY tablename, policyname;\n\n\n-- >>> NATIVE_BASELINE_PART 0032 | supabase/bundles/bundle_1_base_001_031.sql | 030_p0_refund_approve_reject_admin_rpc.sql <<<\n-- ===== 030_p0_refund_approve_reject_admin_rpc.sql =====\n\n-- P0: 관리자 환불 승인/거절 — 단일 트랜잭션 RPC (service_role 전용)\n-- 선행: public.refunds, public.cash_wallets, public.cash_ledger, public.users(role)\n--       payments, subscriptions, custom_request_orders, custom_order_settlement_items (해당 플로우 사용 시)\n-- idempotent: cash_ledger.idempotency_key = ''refund_credit:'' || refund_id\n-- 금액: cash_ledger.delta_cents / cash_wallets.balance_cents 는 운영에서 “원” 단위와 동일한 정수를 씁니다.\n--       refunds.amount_cents 가 비어 있거나 0 이하면 payments 로 자동 추정하지 않습니다(승인 차단).\n\n-- -----------------------------------------------------------------------------\n-- 1) refunds.updated_at 전용 트리거 함수 (set_updated_at 전제 없이 적용 가능)\n-- -----------------------------------------------------------------------------\ncreate or replace function public.set_refunds_updated_at()\nreturns trigger\nlanguage plpgsql\nsecurity invoker\nset search_path = public\nas $fn$\nbegin\n  new.updated_at := now();\n  return new;\nend;\n$fn$", "-- -----------------------------------------------------------------------------\n-- 2) refunds 컬럼 보강\n-- -----------------------------------------------------------------------------\nalter table public.refunds add column if not exists updated_at timestamptz not null default now()", "alter table public.refunds add column if not exists processed_at timestamptz", "alter table public.refunds add column if not exists processed_by uuid references public.users (id) on delete set null", "alter table public.refunds add column if not exists admin_note text", "drop trigger if exists trg_refunds_set_updated on public.refunds", "create trigger trg_refunds_set_updated\n  before update on public.refunds\n  for each row execute function public.set_refunds_updated_at()", "-- -----------------------------------------------------------------------------\n-- 3) approve_refund_request_admin\n-- -----------------------------------------------------------------------------\ncreate or replace function public.approve_refund_request_admin(\n  p_refund_id uuid,\n  p_admin_id uuid,\n  p_admin_note text default null\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  r public.refunds%rowtype;\n  v_amount bigint;\n  v_settlement_status text;\n  v_idem text := ''refund_credit:'' || p_refund_id::text;\n  v_ledger_id uuid;\n  v_existing_delta bigint;\n  v_wu int;\n  v_admin_ok boolean;\nbegin\n  if p_refund_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''환불 ID가 필요합니다.'');\n  end if;\n  if p_admin_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''관리자 ID가 필요합니다.'');\n  end if;\n\n  select exists(\n    select 1 from public.users u where u.id = p_admin_id and u.role = ''admin''\n  ) into v_admin_ok;\n  if not coalesce(v_admin_ok, false) then\n    raise exception ''ADMIN_REQUIRED'';\n  end if;\n\n  select * into r from public.refunds where id = p_refund_id for update;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''message'', ''환불 요청을 찾을 수 없습니다.'');\n  end if;\n\n  if r.status is distinct from ''pending'' then\n    return jsonb_build_object(\n      ''ok'', true,\n      ''noop'', true,\n      ''refund_id'', p_refund_id,\n      ''message'', ''이미 처리되었거나 대기 상태가 아닙니다.'',\n      ''status'', r.status\n    );\n  end if;\n\n  -- 정산 지급 완료 시 자동 환불 차단\n  if r.custom_request_order_id is not null then\n    select s.status into v_settlement_status\n    from public.custom_order_settlement_items s\n    where s.custom_request_order_id = r.custom_request_order_id\n    limit 1;\n    if found and v_settlement_status = ''paid'' then\n      return jsonb_build_object(\n        ''ok'', false,\n        ''message'', ''이미 정산 지급이 완료된 건은 자동 환불할 수 없습니다. 수동 조정이 필요합니다.''\n      );\n    end if;\n  end if;\n\n  if r.amount_cents is null or r.amount_cents <= 0 then\n    raise exception ''환불 금액이 설정되지 않아 자동 승인할 수 없습니다.'';\n  end if;\n\n  v_amount := r.amount_cents;\n\n  if v_amount > 1000000000 then\n    return jsonb_build_object(''ok'', false, ''message'', ''환불 금액이 허용 한도를 초과합니다.'');\n  end if;\n\n  -- 정산 예정만 취소 (paid 는 위에서 차단)\n  if r.custom_request_order_id is not null then\n    update public.custom_order_settlement_items s\n    set status = ''cancelled'', updated_at = now()\n    where s.custom_request_order_id = r.custom_request_order_id\n      and s.status in (''pending'', ''on_hold'', ''payable'');\n  end if;\n\n  insert into public.cash_ledger (\n    user_id, delta_cents, reason, ref_type, ref_id, idempotency_key\n  )\n  values (\n    r.user_id, v_amount, ''refund_approved'', ''refunds'', r.id, v_idem\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_ledger_id;\n\n  if v_ledger_id is null then\n    select cl.delta_cents into v_existing_delta\n    from public.cash_ledger cl\n    where cl.idempotency_key = v_idem\n    limit 1;\n    if not found then\n      raise exception ''REFUND_LEDGER_IDEMPOTENT_MISS'' using errcode = ''P0001'';\n    end if;\n    if v_existing_delta is distinct from v_amount then\n      raise exception ''REFUND_LEDGER_AMOUNT_MISMATCH'' using errcode = ''P0001'';\n    end if;\n  end if;\n\n  if v_ledger_id is not null then\n    insert into public.cash_wallets (user_id, balance_cents)\n    values (r.user_id, 0)\n    on conflict (user_id) do nothing;\n\n    update public.cash_wallets w\n    set balance_cents = w.balance_cents + v_amount\n    where w.user_id = r.user_id;\n    get diagnostics v_wu = row_count;\n    if coalesce(v_wu, 0) = 0 then\n      raise exception ''CASH_WALLET_UPDATE_FAILED'' using errcode = ''P0001'';\n    end if;\n  end if;\n\n  update public.refunds\n  set\n    status = ''succeeded'',\n    processed_at = now(),\n    processed_by = p_admin_id,\n    admin_note = p_admin_note,\n    updated_at = now()\n  where id = r.id;\n\n  if r.payment_id is not null then\n    update public.payments p\n    set status = ''refunded'', updated_at = now()\n    where p.id = r.payment_id;\n  end if;\n\n  if r.payment_id is not null then\n    update public.subscriptions s\n    set status = ''canceled'', updated_at = now()\n    where s.payment_id = r.payment_id\n      and s.status is distinct from ''canceled'';\n  end if;\n\n  if r.custom_request_order_id is not null then\n    update public.custom_request_orders o\n    set payment_status = ''refunded'', updated_at = now()\n    where o.id = r.custom_request_order_id;\n  end if;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''noop'', false,\n    ''refund_id'', r.id,\n    ''ledger_inserted'', (v_ledger_id is not null),\n    ''amount_cents'', v_amount,\n    ''message'', ''환불이 승인되었습니다.''\n  );\nend;\n$function$", "-- -----------------------------------------------------------------------------\n-- 4) reject_refund_request_admin\n-- -----------------------------------------------------------------------------\ncreate or replace function public.reject_refund_request_admin(\n  p_refund_id uuid,\n  p_admin_id uuid,\n  p_admin_note text default null\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  r public.refunds%rowtype;\n  v_admin_ok boolean;\nbegin\n  if p_refund_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''환불 ID가 필요합니다.'');\n  end if;\n  if p_admin_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''관리자 ID가 필요합니다.'');\n  end if;\n\n  select exists(\n    select 1 from public.users u where u.id = p_admin_id and u.role = ''admin''\n  ) into v_admin_ok;\n  if not coalesce(v_admin_ok, false) then\n    raise exception ''ADMIN_REQUIRED'';\n  end if;\n\n  select * into r from public.refunds where id = p_refund_id for update;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''message'', ''환불 요청을 찾을 수 없습니다.'');\n  end if;\n\n  if r.status is distinct from ''pending'' then\n    return jsonb_build_object(\n      ''ok'', true,\n      ''noop'', true,\n      ''refund_id'', p_refund_id,\n      ''message'', ''이미 처리되었거나 대기 상태가 아닙니다.'',\n      ''status'', r.status\n    );\n  end if;\n\n  update public.refunds\n  set\n    status = ''rejected'',\n    processed_at = now(),\n    processed_by = p_admin_id,\n    admin_note = p_admin_note,\n    updated_at = now()\n  where id = r.id;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''noop'', false,\n    ''refund_id'', r.id,\n    ''message'', ''환불이 거절되었습니다.''\n  );\nend;\n$function$", "-- -----------------------------------------------------------------------------\n-- 5) EXECUTE: service_role 만 (승인/거절 RPC)\n-- -----------------------------------------------------------------------------\nrevoke all on function public.approve_refund_request_admin(uuid, uuid, text) from public", "revoke all on function public.approve_refund_request_admin(uuid, uuid, text) from anon", "revoke all on function public.approve_refund_request_admin(uuid, uuid, text) from authenticated", "grant execute on function public.approve_refund_request_admin(uuid, uuid, text) to service_role", "revoke all on function public.reject_refund_request_admin(uuid, uuid, text) from public", "revoke all on function public.reject_refund_request_admin(uuid, uuid, text) from anon", "revoke all on function public.reject_refund_request_admin(uuid, uuid, text) from authenticated", "grant execute on function public.reject_refund_request_admin(uuid, uuid, text) to service_role", "comment on function public.approve_refund_request_admin(uuid, uuid, text)\n  is ''P0: Admin refund approve — idempotent ledger credit, service_role only. Caller must enforce app-level admin; RPC re-checks users.role=admin.''", "comment on function public.reject_refund_request_admin(uuid, uuid, text)\n  is ''P0: Admin refund reject — refunds row only, service_role only.''", "comment on function public.set_refunds_updated_at()\n  is ''P0: refunds.updated_at only — independent of public.set_updated_at.''", "-- >>> NATIVE_BASELINE_PART 0033 | supabase/bundles/bundle_1_base_001_031.sql | 031_p1_admin_notices_promotions.sql <<<\n-- ===== 031_p1_admin_notices_promotions.sql =====\n\n-- P1: 관리자 공지(app_notices) · 프로모션(promotion_campaigns)\n-- 선행: 001 public.users (id references auth.users)\n-- Idempotent: 여러 번 실행해도 안전\n-- RLS: admin만 쓰기; 활성·기간 내 행은 anon/authenticated 조회 가능\n\ncreate extension if not exists \"pgcrypto\"", "-- ---------------------------------------------------------------------------\n-- updated_at 전용 트리거 함수 (이 파일에서 정의, set_updated_at에 비의존)\n-- ---------------------------------------------------------------------------\ncreate or replace function public.set_admin_content_updated_at()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$$", "-- ---------------------------------------------------------------------------\n-- public.app_notices\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.app_notices (\n  id uuid primary key default gen_random_uuid(),\n  title text not null,\n  body text not null default '''',\n  type text not null default ''notice'',\n  target text null,\n  is_active boolean not null default false,\n  starts_at timestamptz null,\n  ends_at timestamptz null,\n  created_by uuid null references public.users (id) on delete set null,\n  updated_by uuid null references public.users (id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint app_notices_title_nonempty check (char_length(trim(title)) > 0),\n  constraint app_notices_type_allowed check (type in (''notice'', ''event'', ''maintenance'', ''update'')),\n  constraint app_notices_date_range check (\n    starts_at is null or ends_at is null or ends_at >= starts_at\n  )\n)", "create index if not exists app_notices_created_at_idx on public.app_notices (created_at desc)", "create index if not exists app_notices_active_window_idx on public.app_notices (is_active, starts_at, ends_at)", "drop trigger if exists trg_app_notices_set_updated on public.app_notices", "create trigger trg_app_notices_set_updated\n  before update on public.app_notices\n  for each row execute function public.set_admin_content_updated_at()", "-- ---------------------------------------------------------------------------\n-- public.promotion_campaigns\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.promotion_campaigns (\n  id uuid primary key default gen_random_uuid(),\n  title text not null,\n  body text not null default '''',\n  target text null,\n  is_active boolean not null default false,\n  starts_at timestamptz null,\n  ends_at timestamptz null,\n  created_by uuid null references public.users (id) on delete set null,\n  updated_by uuid null references public.users (id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint promotion_campaigns_title_nonempty check (char_length(trim(title)) > 0),\n  constraint promotion_campaigns_date_range check (\n    starts_at is null or ends_at is null or ends_at >= starts_at\n  )\n)", "create index if not exists promotion_campaigns_created_at_idx on public.promotion_campaigns (created_at desc)", "create index if not exists promotion_campaigns_active_window_idx on public.promotion_campaigns (is_active, starts_at, ends_at)", "drop trigger if exists trg_promotion_campaigns_set_updated on public.promotion_campaigns", "create trigger trg_promotion_campaigns_set_updated\n  before update on public.promotion_campaigns\n  for each row execute function public.set_admin_content_updated_at()", "-- ---------------------------------------------------------------------------\n-- RLS\n-- ---------------------------------------------------------------------------\nalter table public.app_notices enable row level security", "alter table public.promotion_campaigns enable row level security", "-- app_notices: admin 전체 조회 · 활성+기간 내 공개 조회\ndrop policy if exists \"app_notices_select\" on public.app_notices", "create policy \"app_notices_select\"\n  on public.app_notices for select\n  to anon, authenticated\n  using (\n    exists (\n      select 1 from public.users u\n      where u.id = auth.uid() and u.role = ''admin''\n    )\n    or (\n      coalesce(is_active, false) = true\n      and (starts_at is null or starts_at <= now())\n      and (ends_at is null or ends_at >= now())\n    )\n  )", "drop policy if exists \"app_notices_insert_admin\" on public.app_notices", "create policy \"app_notices_insert_admin\"\n  on public.app_notices for insert\n  to authenticated\n  with check (\n    exists (select 1 from public.users u where u.id = auth.uid() and u.role = ''admin'')\n  )", "drop policy if exists \"app_notices_update_admin\" on public.app_notices", "create policy \"app_notices_update_admin\"\n  on public.app_notices for update\n  to authenticated\n  using (exists (select 1 from public.users u where u.id = auth.uid() and u.role = ''admin''))\n  with check (exists (select 1 from public.users u where u.id = auth.uid() and u.role = ''admin''))", "drop policy if exists \"app_notices_delete_admin\" on public.app_notices", "create policy \"app_notices_delete_admin\"\n  on public.app_notices for delete\n  to authenticated\n  using (exists (select 1 from public.users u where u.id = auth.uid() and u.role = ''admin''))", "-- promotion_campaigns\ndrop policy if exists \"promotion_campaigns_select\" on public.promotion_campaigns", "create policy \"promotion_campaigns_select\"\n  on public.promotion_campaigns for select\n  to anon, authenticated\n  using (\n    exists (\n      select 1 from public.users u\n      where u.id = auth.uid() and u.role = ''admin''\n    )\n    or (\n      coalesce(is_active, false) = true\n      and (starts_at is null or starts_at <= now())\n      and (ends_at is null or ends_at >= now())\n    )\n  )", "drop policy if exists \"promotion_campaigns_insert_admin\" on public.promotion_campaigns", "create policy \"promotion_campaigns_insert_admin\"\n  on public.promotion_campaigns for insert\n  to authenticated\n  with check (\n    exists (select 1 from public.users u where u.id = auth.uid() and u.role = ''admin'')\n  )", "drop policy if exists \"promotion_campaigns_update_admin\" on public.promotion_campaigns", "create policy \"promotion_campaigns_update_admin\"\n  on public.promotion_campaigns for update\n  to authenticated\n  using (exists (select 1 from public.users u where u.id = auth.uid() and u.role = ''admin''))\n  with check (exists (select 1 from public.users u where u.id = auth.uid() and u.role = ''admin''))", "drop policy if exists \"promotion_campaigns_delete_admin\" on public.promotion_campaigns", "create policy \"promotion_campaigns_delete_admin\"\n  on public.promotion_campaigns for delete\n  to authenticated\n  using (exists (select 1 from public.users u where u.id = auth.uid() and u.role = ''admin''))", "-- ---------------------------------------------------------------------------\n-- Grants (RLS와 함께 사용)\n-- ---------------------------------------------------------------------------\ngrant select on public.app_notices to anon, authenticated", "grant select on public.promotion_campaigns to anon, authenticated", "grant insert, update, delete on public.app_notices to authenticated", "grant insert, update, delete on public.promotion_campaigns to authenticated", "-- >>> NATIVE_BASELINE_PART 0034 | supabase/bundles/bundle_2_features_032_061.sql | preamble <<<\n-- =============================================================================\n-- bundle_2_features_032_061.sql\n-- Generated by Codex from supabase/sql/*.sql. DO NOT EDIT ORIGINAL SQL FILES.\n-- This bundle is for a blank/company Supabase setup via SQL Editor.\n-- Execute bundle_1, verify, then bundle_2, verify, then bundle_3.\n-- DB execution was NOT perfo