ept as source order requested.\n--   - 036_p1_prelaunch_rls_tightening.sql is intentionally excluded as audit/draft.\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0035 | supabase/bundles/bundle_2_features_032_061.sql | 032_p0_weekly_question_usage.sql <<<\n-- ===== 032_p0_weekly_question_usage.sql =====\n\n-- [의존 순서] 이 파일은 002_p0_subscriptions_questions_draft.sql 이후 적용할 것\n-- [번호 충돌] 접두 032 — 동일 번호: 032_p1_admin_content_reports.sql (이 파일: 주간 질문 한도 P0)\n-- P0: 주간 질문 한도 (월~일, confirmed 만 소비) + usage RPC\n\nalter table public.question_threads drop constraint if exists question_threads_status_check", "alter table public.question_threads\n  add constraint question_threads_status_check\n  check (status in (''pending'', ''answered'', ''confirmed'', ''open'', ''closed'', ''archived''))", "comment on column public.question_threads.status is\n  ''pending=답변대기, answered=답변도착, confirmed=학생확인(소비). open/closed/archived=레거시 호환''", "update public.question_threads\nset status = case\n  when status = ''open'' then ''pending''\n  when status = ''closed'' then ''confirmed''\n  else status\nend\nwhere status in (''open'', ''closed'')", "create or replace function public.get_weekly_question_usage(\n  p_student_id uuid,\n  p_mentor_id uuid\n)\nreturns json\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_week_start timestamptz;\n  v_week_end timestamptz;\n  v_used integer;\n  v_plan_tier text;\n  v_limit integer;\nbegin\n  if p_student_id is null or p_mentor_id is null then\n    raise exception ''p_student_id and p_mentor_id are required'';\n  end if;\n\n  -- 월요일 00:00 (Asia/Seoul) ~ 다음 월요일 00:00\n  v_week_start := (\n    date_trunc(''week'', (now() at time zone ''Asia/Seoul''))\n    at time zone ''Asia/Seoul''\n  );\n  v_week_end := v_week_start + interval ''7 days'';\n\n  select s.plan_tier into v_plan_tier\n  from public.subscriptions s\n  where s.student_id = p_student_id\n    and s.mentor_id = p_mentor_id\n    and s.status = ''active''\n  order by s.created_at desc\n  limit 1;\n\n  v_limit := case lower(coalesce(v_plan_tier, ''''))\n    when ''limited'' then 4\n    when ''standard'' then 9\n    when ''premium'' then 999\n    else 0\n  end;\n\n  select count(*)::integer into v_used\n  from public.question_threads qt\n  inner join public.mentor_student_rooms r on r.id = qt.mentor_student_room_id\n  where r.student_id = p_student_id\n    and r.mentor_id = p_mentor_id\n    and qt.status = ''confirmed''\n    and coalesce(qt.updated_at, qt.created_at) >= v_week_start\n    and coalesce(qt.updated_at, qt.created_at) < v_week_end;\n\n  return json_build_object(\n    ''used'', coalesce(v_used, 0),\n    ''limit'', v_limit,\n    ''plan_tier'', v_plan_tier,\n    ''remaining'', greatest(0, v_limit - coalesce(v_used, 0)),\n    ''can_ask'', coalesce(v_used, 0) < v_limit,\n    ''week_start'', v_week_start,\n    ''week_end'', v_week_end\n  );\nend;\n$function$", "revoke all on function public.get_weekly_question_usage(uuid, uuid) from public", "grant execute on function public.get_weekly_question_usage(uuid, uuid) to authenticated", "grant execute on function public.get_weekly_question_usage(uuid, uuid) to service_role", "-- >>> NATIVE_BASELINE_PART 0036 | supabase/bundles/bundle_2_features_032_061.sql | 032_p1_admin_content_reports.sql <<<\n-- ===== 032_p1_admin_content_reports.sql =====\n\n-- [의존 순서] 이 파일은 001_initial_auth_profile.sql 이후 적용할 것\n-- [번호 충돌] 접두 032 — 동일 번호: 032_p0_weekly_question_usage.sql (이 파일: content_reports P1)\n-- P1: 콘텐츠 신고(content_reports) — 관리자 콘솔 /admin/reports\n-- 선행: 001 public.users, public.set_updated_at(), public.is_admin() 권장(003/004 등)\n-- Idempotent\n\ncreate extension if not exists \"pgcrypto\"", "-- ---------------------------------------------------------------------------\n-- public.content_reports\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.content_reports (\n  id uuid primary key default gen_random_uuid(),\n  reporter_id uuid references public.users (id) on delete set null,\n  target_type text not null,\n  target_id uuid null,\n  reason text null,\n  description text null,\n  status text not null default ''pending'',\n  admin_note text null,\n  resolved_by uuid references public.users (id) on delete set null,\n  resolved_at timestamptz null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint content_reports_status_allowed check (\n    status in (''pending'', ''reviewing'', ''resolved'', ''rejected'', ''dismissed'')\n  ),\n  constraint content_reports_target_type_nonempty check (char_length(trim(target_type)) > 0)\n)", "create index if not exists content_reports_status_created_idx on public.content_reports (status, created_at desc)", "create index if not exists content_reports_reporter_id_idx on public.content_reports (reporter_id)", "create index if not exists content_reports_target_idx on public.content_reports (target_type, target_id)", "drop trigger if exists trg_content_reports_set_updated on public.content_reports", "create trigger trg_content_reports_set_updated\n  before update on public.content_reports\n  for each row execute function public.set_updated_at()", "-- ---------------------------------------------------------------------------\n-- RLS\n-- ---------------------------------------------------------------------------\nalter table public.content_reports enable row level security", "drop policy if exists \"content_reports_select_admin\" on public.content_reports", "create policy \"content_reports_select_admin\"\n  on public.content_reports for select\n  to authenticated\n  using (\n    exists (\n      select 1 from public.users u\n      where u.id = auth.uid() and u.role = ''admin''\n    )\n  )", "drop policy if exists \"content_reports_select_reporter\" on public.content_reports", "create policy \"content_reports_select_reporter\"\n  on public.content_reports for select\n  to authenticated\n  using (reporter_id = (select auth.uid()))", "drop policy if exists \"content_reports_insert_reporter\" on public.content_reports", "create policy \"content_reports_insert_reporter\"\n  on public.content_reports for insert\n  to authenticated\n  with check (reporter_id = (select auth.uid()))", "drop policy if exists \"content_reports_update_admin\" on public.content_reports", "create policy \"content_reports_update_admin\"\n  on public.content_reports for update\n  to authenticated\n  using (\n    exists (\n      select 1 from public.users u\n      where u.id = auth.uid() and u.role = ''admin''\n    )\n  )\n  with check (\n    exists (\n      select 1 from public.users u\n      where u.id = auth.uid() and u.role = ''admin''\n    )\n  )", "drop policy if exists \"content_reports_delete_admin\" on public.content_reports", "create policy \"content_reports_delete_admin\"\n  on public.content_reports for delete\n  to authenticated\n  using (\n    exists (\n      select 1 from public.users u\n      where u.id = auth.uid() and u.role = ''admin''\n    )\n  )", "-- ---------------------------------------------------------------------------\n-- Grants (RLS와 함께 사용; anon 직접 접근 없음)\n-- ---------------------------------------------------------------------------\ngrant select, insert, update, delete on public.content_reports to authenticated", "comment on table public.content_reports is ''P1 콘텐츠 신고. 관리자 전체 조회·처리, 일반 사용자는 본인 신고만 조회·삽입.''", "-- >>> NATIVE_BASELINE_PART 0037 | supabase/bundles/bundle_2_features_032_061.sql | 033_question_threads_topic.sql <<<\n-- ===== 033_question_threads_topic.sql =====\n\n-- [의존 순서] 이 파일은 002_p0_subscriptions_questions_draft.sql 이후 적용할 것\n-- [번호 충돌] 접두 033 — 동일 번호: 033_p1_admin_reviews_moderation.sql (이 파일: question_threads.topic)\n-- 질문 스레드 과목 태그 (제목과 분리)\nalter table public.question_threads add column if not exists topic text", "comment on column public.question_threads.topic is ''질문 과목 태그 (미적분, 확률과통계 등)''", "-- >>> NATIVE_BASELINE_PART 0038 | supabase/bundles/bundle_2_features_032_061.sql | 034_mentor_favorites.sql <<<\n-- ===== 034_mentor_favorites.sql =====\n\n-- [의존 순서] 이 파일은 001_initial_auth_profile.sql 이후 적용할 것\n-- [번호 충돌] 접두 034 — 동일 번호: 034_p1_admin_disputes_processing.sql (이 파일: favorites)\n-- 멘토 찜하기 (학생·로그인 사용자)\ncreate table if not exists public.favorites (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete cascade,\n  mentor_id uuid not null references public.users (id) on delete cascade,\n  created_at timestamptz not null default now(),\n  constraint favorites_user_mentor_unique unique (user_id, mentor_id)\n)", "create index if not exists favorites_user_id_idx on public.favorites (user_id)", "create index if not exists favorites_mentor_id_idx on public.favorites (mentor_id)", "alter table public.favorites enable row level security", "drop policy if exists favorites_select_own on public.favorites", "create policy favorites_select_own\n  on public.favorites for select\n  using (auth.uid() = user_id)", "drop policy if exists favorites_insert_own on public.favorites", "create policy favorites_insert_own\n  on public.favorites for insert\n  with check (auth.uid() = user_id)", "drop policy if exists favorites_delete_own on public.favorites", "create policy favorites_delete_own\n  on public.favorites for delete\n  using (auth.uid() = user_id)", "-- >>> NATIVE_BASELINE_PART 0039 | supabase/bundles/bundle_2_features_032_061.sql | 034_p1_admin_disputes_processing.sql <<<\n-- ===== 034_p1_admin_disputes_processing.sql =====\n\n-- [의존 순서] 이 파일은 004_p0_cash_disputes_admin_draft.sql 이후 적용할 것\n-- [번호 충돌] 접두 034 — 동일 번호: 034_mentor_favorites.sql (이 파일: disputes 운영 컬럼)\n-- =============================================================================\n-- 034_p1_admin_disputes_processing.sql\n-- 목적: 관리자 분쟁 처리(운영 메모, 해결 시각·처리자) 보조 컬럼을 idempotent 하게 추가\n-- 적용: 저장소 전용. Supabase 에는 수동 적용하지 않음.\n-- 선행: 004 public.disputes, 003 public.is_admin(), auth.users\n-- 주의: 환불·정산·주문 상태 자동 변경은 포함하지 않습니다. 기존 RLS 정책 무리한 DROP 금지.\n-- =============================================================================\n\nalter table if exists public.disputes\n  add column if not exists admin_note text", "alter table if exists public.disputes\n  add column if not exists resolved_at timestamptz", "alter table if exists public.disputes\n  add column if not exists resolved_by uuid null references auth.users (id) on delete set null", "comment on column public.disputes.admin_note is ''관리자 운영 메모(내부).''", "comment on column public.disputes.resolved_at is ''해결·종결 처리 시각(선택).''", "comment on column public.disputes.resolved_by is ''해결·종결 처리자 auth.users.id(선택).''", "-- 004 dispute_update_admin 정책이 있으면 admin 이 이미 update 가능. 별도 정책 추가 없이 컬럼만 확장합니다.\n\n\n-- >>> NATIVE_BASELINE_PART 0040 | supabase/bundles/bundle_2_features_032_061.sql | 035_p1_admin_audit_logs.sql <<<\n-- ===== 035_p1_admin_audit_logs.sql =====\n\n-- =============================================================================\n-- 035_p1_admin_audit_logs.sql\n-- 목적: 관리자 통합 활동 로그(/admin/audit-logs)에서 verification_logs를 세션으로 조회\n-- 적용: 저장소 전용. Supabase SQL Editor에서 수동 적용.\n-- 선행: 001 public.verification_logs, 003 public.is_admin()\n-- 주의: 기존 ver_logs_insert_own 유지. 자동 환불·정산·주문 변경 없음. begin/commit 없음.\n-- =============================================================================\n\ndrop policy if exists ver_logs_admin_select on public.verification_logs", "create policy ver_logs_admin_select\n  on public.verification_logs\n  for select\n  to authenticated\n  using ((select public.is_admin()) = true)", "comment on policy ver_logs_admin_select on public.verification_logs is ''관리자 콘솔 통합 활동 로그 조회용.''", "-- >>> NATIVE_BASELINE_PART 0041 | supabase/bundles/bundle_2_features_032_061.sql | 037_p1_community_board_v2.sql <<<\n-- ===== 037_p1_community_board_v2.sql =====\n\n-- 커뮤니티 게시판 v2: community_posts 확장, comments(2depth), post_reactions, community_hashtags, 이미지 Storage\n-- 선행: 001(users), 004(community_posts), 016(community_comments — 숏폼·레거시)\n\ncreate extension if not exists pgcrypto", "-- ---------------------------------------------------------------------------\n-- 1) community_posts 확장\n-- ---------------------------------------------------------------------------\nalter table public.community_posts\n  add column if not exists content text,\n  add column if not exists image_urls text[] not null default ''{}'',\n  add column if not exists hashtags text[] not null default ''{}'',\n  add column if not exists view_count int not null default 0,\n  add column if not exists like_count int not null default 0,\n  add column if not exists comment_count int not null default 0,\n  add column if not exists status text not null default ''published'',\n  add column if not exists author_label text,\n  add column if not exists updated_at timestamptz", "update public.community_posts\nset content = coalesce(nullif(trim(content), ''''), nullif(trim(body), ''''))\nwhere content is null or trim(content) = ''''", "alter table public.community_posts\n  drop constraint if exists community_posts_status_chk", "alter table public.community_posts\n  add constraint community_posts_status_chk\n  check (status in (''draft'', ''published'', ''hidden''))", "create index if not exists idx_cp_status_created\n  on public.community_posts (status, created_at desc)", "create index if not exists idx_cp_category_created\n  on public.community_posts (category, created_at desc)", "-- ---------------------------------------------------------------------------\n-- 2) comments (게시판 전용, 최대 2depth)\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.comments (\n  id uuid primary key default gen_random_uuid(),\n  post_id uuid not null references public.community_posts (id) on delete cascade,\n  author_id uuid not null references public.users (id) on delete cascade,\n  parent_id uuid references public.comments (id) on delete cascade,\n  content text not null,\n  like_count int not null default 0,\n  is_deleted boolean not null default false,\n  author_label text not null default ''쌤버십 회원'',\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint comments_content_len_chk check (char_length(trim(content)) between 1 and 2000)\n)", "create index if not exists idx_comments_post_created\n  on public.comments (post_id, created_at asc)", "create index if not exists idx_comments_parent\n  on public.comments (parent_id)", "-- ---------------------------------------------------------------------------\n-- 3) post_reactions (좋아요 / 스크랩)\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.post_reactions (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete cascade,\n  post_id uuid not null references public.community_posts (id) on delete cascade,\n  type text not null check (type in (''like'', ''scrap'')),\n  created_at timestamptz not null default now(),\n  unique (user_id, post_id, type)\n)", "create index if not exists idx_post_reactions_post\n  on public.post_reactions (post_id, type)", "-- ---------------------------------------------------------------------------\n-- 4) community_hashtags\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.community_hashtags (\n  tag text primary key,\n  count int not null default 0,\n  updated_at timestamptz not null default now()\n)", "-- ---------------------------------------------------------------------------\n-- 5) 트리거·함수\n-- ---------------------------------------------------------------------------\ncreate or replace function public.community_sync_hashtags()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $f$\ndeclare\n  t text;\n  old_tags text[];\n  new_tags text[];\nbegin\n  old_tags := coalesce(\n    case when tg_op = ''UPDATE'' then old.hashtags else ''{}''::text[] end,\n    ''{}''::text[]\n  );\n  new_tags := coalesce(new.hashtags, ''{}''::text[]);\n\n  if tg_op = ''DELETE'' then\n    foreach t in array old_tags loop\n      update public.community_hashtags set count = greatest(count - 1, 0), updated_at = now() where tag = t;\n    end loop;\n    return old;\n  end if;\n\n  foreach t in array old_tags loop\n    if not (t = any (new_tags)) then\n      update public.community_hashtags set count = greatest(count - 1, 0), updated_at = now() where tag = t;\n    end if;\n  end loop;\n\n  foreach t in array new_tags loop\n    if not (t = any (old_tags)) then\n      insert into public.community_hashtags (tag, count) values (t, 1)\n      on conflict (tag) do update set count = community_hashtags.count + 1, updated_at = now();\n    end if;\n  end loop;\n  return new;\nend;\n$f$", "drop trigger if exists trg_cp_sync_hashtags on public.community_posts", "create trigger trg_cp_sync_hashtags\n  after insert or update of hashtags or delete on public.community_posts\n  for each row execute function public.community_sync_hashtags()", "create or replace function public.community_refresh_post_comment_count()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $f$\ndeclare\n  pid uuid;\nbegin\n  pid := coalesce(new.post_id, old.post_id);\n  update public.community_posts p\n  set comment_count = (\n    select count(*)::int from public.comments c\n    where c.post_id = pid and c.is_deleted = false\n  )\n  where p.id = pid;\n  return coalesce(new, old);\nend;\n$f$", "drop trigger if exists trg_comments_refresh_count on public.comments", "create trigger trg_comments_refresh_count\n  after insert or update of is_deleted or delete on public.comments\n  for each row execute function public.community_refresh_post_comment_count()", "create or replace function public.increment_community_post_view(p_post_id uuid)\nreturns void\nlanguage sql\nsecurity definer\nset search_path = public\nas $f$\n  update public.community_posts\n  set view_count = view_count + 1\n  where id = p_post_id and status = ''published'';\n$f$", "grant execute on function public.increment_community_post_view(uuid) to anon, authenticated", "create or replace function public.community_refresh_post_like_count()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $f$\ndeclare\n  pid uuid;\nbegin\n  pid := coalesce(new.post_id, old.post_id);\n  update public.community_posts p\n  set like_count = (\n    select count(*)::int from public.post_reactions r\n    where r.post_id = pid and r.type = ''like''\n  )\n  where p.id = pid;\n  return coalesce(new, old);\nend;\n$f$", "drop trigger if exists trg_post_reactions_like_count on public.post_reactions", "create trigger trg_post_reactions_like_count\n  after insert or delete on public.post_reactions\n  for each row execute function public.community_refresh_post_like_count()", "-- ---------------------------------------------------------------------------\n-- 6) Storage — community-post-images (public read)\n-- ---------------------------------------------------------------------------\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues (\n  ''community-post-images'',\n  ''community-post-images'',\n  false,\n  5242880,\n  array[''image/jpeg'', ''image/png'', ''image/webp'', ''image/gif'']::text[]\n)\non conflict (id) do update set\n  public = excluded.public,\n  file_size_limit = excluded.file_size_limit,\n  allowed_mime_types = excluded.allowed_mime_types", "drop policy if exists \"cpi_public_read\" on storage.objects", "create policy \"cpi_public_read\"\n  on storage.objects for select\n  to anon, authenticated\n  using (bucket_id = ''community-post-images'')", "drop policy if exists \"cpi_auth_insert_own\" on storage.objects", "create policy \"cpi_auth_insert_own\"\n  on storage.objects for insert\n  to authenticated\n  with check (\n    bucket_id = ''community-post-images''\n    and (storage.foldername(name))[1] = (select auth.uid())::text\n  )", "drop policy if exists \"cpi_auth_update_own\" on storage.objects", "create policy \"cpi_auth_update_own\"\n  on storage.objects for update\n  to authenticated\n  using (\n    bucket_id = ''community-post-images''\n    and (storage.foldername(name))[1] = (select auth.uid())::text\n  )", "drop policy if exists \"cpi_auth_delete_own\" on storage.objects", "create policy \"cpi_auth_delete_own\"\n  on storage.objects for delete\n  to authenticated\n  using (\n    bucket_id = ''community-post-images''\n    and (storage.foldername(name))[1] = (select auth.uid())::text\n  )", "-- ---------------------------------------------------------------------------\n-- 7) RLS — comments\n-- ---------------------------------------------------------------------------\nalter table public.comments enable row level security", "drop policy if exists \"comments_select_visible\" on public.comments", "create policy \"comments_select_visible\"\n  on public.comments for select to anon, authenticated\n  using (is_deleted = false)", "drop policy if exists \"comments_insert_own\" on public.comments", "create policy \"comments_insert_own\"\n  on public.comments for insert to authenticated\n  with check (author_id = (select auth.uid()))", "drop policy if exists \"comments_update_own\" on public.comments", "create policy \"comments_update_own\"\n  on public.comments for update to authenticated\n  using (author_id = (select auth.uid()))\n  with check (author_id = (select auth.uid()))", "drop policy if exists \"comments_delete_own\" on public.comments", "create policy \"comments_delete_own\"\n  on public.comments for delete to authenticated\n  using (author_id = (select auth.uid()))", "-- ---------------------------------------------------------------------------\n-- 8) RLS — post_reactions\n-- ---------------------------------------------------------------------------\nalter table public.post_reactions enable row level security", "drop policy if exists \"post_reactions_select_all\" on public.post_reactions", "create policy \"post_reactions_select_all\"\n  on public.post_reactions for select to anon, authenticated\n  using (true)", "drop policy if exists \"post_reactions_insert_own\" on public.post_reactions", "create policy \"post_reactions_insert_own\"\n  on public.post_reactions for insert to authenticated\n  with check (user_id = (select auth.uid()))", "drop policy if exists \"post_reactions_delete_own\" on public.post_reactions", "create policy \"post_reactions_delete_own\"\n  on public.post_reactions for delete to authenticated\n  using (user_id = (select auth.uid()))", "-- ---------------------------------------------------------------------------\n-- 9) RLS — community_hashtags (읽기 공개)\n-- ---------------------------------------------------------------------------\nalter table public.community_hashtags enable row level security", "drop policy if exists \"community_hashtags_select_all\" on public.community_hashtags", "create policy \"community_hashtags_select_all\"\n  on public.community_hashtags for select to anon, authenticated\n  using (true)", "-- ---------------------------------------------------------------------------\n-- 10) community_posts RLS 보강 (published/draft)\n-- ---------------------------------------------------------------------------\ndrop policy if exists \"cp_select_published\" on public.community_posts", "create policy \"cp_select_published\"\n  on public.community_posts for select to anon, authenticated\n  using (\n    status = ''published''\n    or author_id = (select auth.uid())\n    or (select public.is_admin()) = true\n  )", "drop policy if exists \"cp_update_own\" on public.community_posts", "create policy \"cp_update_own\"\n  on public.community_posts for update to authenticated\n  using (author_id = (select auth.uid()) or (select public.is_admin()) = true)\n  with check (author_id = (select auth.uid()) or (select public.is_admin()) = true)", "drop policy if exists \"cp_delete_own\" on public.community_posts", "create policy \"cp_delete_own\"\n  on public.community_posts for delete to authenticated\n  using (author_id = (select auth.uid()) or (select public.is_admin()) = true)", "-- >>> NATIVE_BASELINE_PART 0042 | supabase/bundles/bundle_2_features_032_061.sql | 038_p1_shortform_v2.sql <<<\n-- ===== 038_p1_shortform_v2.sql =====\n\n-- 숏폼 v2: video_url, thumbnail, tags, status, counts, Storage bucket\n-- 선행: 004(shortform_posts), 001(users)\n\ncreate extension if not exists pgcrypto", "alter table public.shortform_posts\n  add column if not exists creator_id uuid references public.users (id) on delete cascade,\n  add column if not exists video_url text,\n  add column if not exists thumbnail_url text,\n  add column if not exists description text,\n  add column if not exists tags text[] not null default ''{}'',\n  add column if not exists status text not null default ''published'',\n  add column if not exists view_count int not null default 0,\n  add column if not exists like_count int not null default 0,\n  add column if not exists updated_at timestamptz", "update public.shortform_posts\nset creator_id = coalesce(creator_id, author_id)\nwhere creator_id is null and author_id is not null", "alter table public.shortform_posts\n  drop constraint if exists shortform_posts_status_chk", "alter table public.shortform_posts\n  add constraint shortform_posts_status_chk\n  check (status in (''draft'', ''published'', ''hidden''))", "create index if not exists idx_sf_status_created on public.shortform_posts (status, created_at desc)", "create index if not exists idx_sf_category_created on public.shortform_posts (category, created_at desc)", "create or replace function public.increment_shortform_post_view(p_post_id uuid)\nreturns void language sql security definer set search_path = public as $f$\n  update public.shortform_posts set view_count = view_count + 1\n  where id = p_post_id and status = ''published'';\n$f$", "grant execute on function public.increment_shortform_post_view(uuid) to anon, authenticated", "-- 멘토만 insert (users.role = mentor)\ncreate or replace function public.is_mentor()\nreturns boolean language sql stable security definer set search_path = public as $f$\n  select coalesce((select u.role = ''mentor'' from public.users u where u.id = auth.uid()), false);\n$f$", "insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues (\n  ''shortform-videos'',\n  ''shortform-videos'',\n  false,\n  524288000,\n  array[''video/mp4'', ''video/quicktime'', ''video/webm'']::text[]\n)\non conflict (id) do update set\n  public = excluded.public,\n  file_size_limit = excluded.file_size_limit,\n  allowed_mime_types = excluded.allowed_mime_types", "insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues (\n  ''shortform-thumbnails'',\n  ''shortform-thumbnails'',\n  false,\n  5242880,\n  array[''image/jpeg'', ''image/png'', ''image/webp'']::text[]\n)\non conflict (id) do update set public = excluded.public", "drop policy if exists \"sfv_public_read\" on storage.objects", "create policy \"sfv_public_read\" on storage.objects for select to anon, authenticated\n  using (bucket_id in (''shortform-videos'', ''shortform-thumbnails''))", "drop policy if exists \"sfv_mentor_insert\" on storage.objects", "create policy \"sfv_mentor_insert\" on storage.objects for insert to authenticated\n  with check (\n    bucket_id in (''shortform-videos'', ''shortform-thumbnails'')\n    and (select public.is_mentor()) = true\n    and (storage.foldername(name))[1] = (select auth.uid())::text\n  )", "drop policy if exists \"sfv_mentor_delete_own\" on storage.objects", "create policy \"sfv_mentor_delete_own\" on storage.objects for delete to authenticated\n  using (\n    bucket_id in (''shortform-videos'', ''shortform-thumbnails'')\n    and (storage.foldername(name))[1] = (select auth.uid())::text\n  )", "drop policy if exists \"sf_select_published\" on public.shortform_posts", "create policy \"sf_select_published\" on public.shortform_posts for select to anon, authenticated\n  using (\n    status = ''published''\n    or author_id = (select auth.uid())\n    or creator_id = (select auth.uid())\n    or (select public.is_admin()) = true\n  )", "drop policy if exists \"sf_insert_mentor\" on public.shortform_posts", "create policy \"sf_insert_mentor\" on public.shortform_posts for insert to authenticated\n  with check (\n    (select public.is_mentor()) = true\n    and (author_id = (select auth.uid()) or creator_id = (select auth.uid()))\n  )", "drop policy if exists \"sf_update_own\" on public.shortform_posts", "create policy \"sf_update_own\" on public.shortform_posts for update to authenticated\n  using (author_id = (select auth.uid()) or creator_id = (select auth.uid()))\n  with check (author_id = (select auth.uid()) or creator_id = (select auth.uid()))", "drop policy if exists \"sf_delete_own\" on public.shortform_posts", "create policy \"sf_delete_own\" on public.shortform_posts for delete to authenticated\n  using (author_id = (select auth.uid()) or creator_id = (select auth.uid()))", "-- >>> NATIVE_BASELINE_PART 0043 | supabase/bundles/bundle_2_features_032_061.sql | 039_p1_custom_request_compat.sql <<<\n-- ===== 039_p1_custom_request_compat.sql =====\n\n-- [의존 순서] 이 파일은 003_p0_custom_request_draft.sql 이후 적용할 것\n-- [번호 충돌] 접두 039 — 동일 번호: 039_storage_buckets_private_audit.sql (이 파일: 맞춤의뢰 컬럼 호환)\n-- 맞춤의뢰 스키마 호환 (003 선행). 앱 v2 필드 보강.\n-- 기존 003 테이블이 있으면 컬럼만 추가, 없으면 003 먼저 적용.\n\ncreate extension if not exists pgcrypto", "alter table if exists public.custom_request_posts\n  add column if not exists file_urls text[] not null default ''{}'',\n  add column if not exists budget_min int,\n  add column if not exists budget_max int", "alter table if exists public.custom_request_applications\n  add column if not exists estimated_days int,\n  add column if not exists portfolio_urls text[] not null default ''{}''", "alter table if exists public.custom_order_deliverables\n  add column if not exists file_name text,\n  add column if not exists version int not null default 1", "comment on column public.custom_request_posts.file_urls is ''의뢰 등록 첨부 public URL 배열(레거시 호환)''", "-- >>> NATIVE_BASELINE_PART 0044 | supabase/bundles/bundle_2_features_032_061.sql | 039_storage_buckets_private_audit.sql <<<\n-- ===== 039_storage_buckets_private_audit.sql =====\n\n-- [의존 순서] 이 파일은 001_initial_auth_profile.sql 이후 적용할 것\n-- [번호 충돌] 접두 039 — 동일 번호: 039_p1_custom_request_compat.sql (이 파일: storage buckets private)\n-- --------------------------------------------------------------------------\n-- Storage 버킷 비공개 점검 (쌤버십 필수 3종 + 미디어 버킷)\n-- 실행 후: SELECT id, name, public FROM storage.buckets ORDER BY id;\n-- --------------------------------------------------------------------------\n\n-- 필수 비공개 (개인정보·납품·의뢰 첨부)\ninsert into storage.buckets (id, name, public)\nvalues (''student-id-images'', ''student-id-images'', false)\non conflict (id) do update set public = false", "insert into storage.buckets (id, name, public)\nvalues (''custom-order-deliverables'', ''custom-order-deliverables'', false)\non conflict (id) do update set public = false", "insert into storage.buckets (id, name, public)\nvalues (''custom-request-post-attachments'', ''custom-request-post-attachments'', false)\non conflict (id) do update set public = false", "-- 커뮤니티·숏폼 미디어 (RLS + signed URL 사용)\nupdate storage.buckets set public = false where id in (\n  ''community-post-images'',\n  ''shortform-videos'',\n  ''shortform-thumbnails''\n)", "-- 점검 쿼리 (Supabase SQL Editor에서 실행)\n-- SELECT id, name, public FROM storage.buckets ORDER BY id;\n\n\n-- >>> NATIVE_BASELINE_PART 0045 | supabase/bundles/bundle_2_features_032_061.sql | 040_admin_action_logs.sql <<<\n-- ===== 040_admin_action_logs.sql =====\n\n-- 관리자 활동 로그 (백오피스 감사)\n-- 선행: 001 users, is_admin()\n\ncreate extension if not exists pgcrypto", "create table if not exists public.admin_action_logs (\n  id uuid primary key default gen_random_uuid(),\n  admin_id uuid references auth.users (id) on delete set null,\n  action_type text not null,\n  target_type text,\n  target_id uuid,\n  detail jsonb,\n  created_at timestamptz not null default now()\n)", "create index if not exists idx_admin_action_logs_created on public.admin_action_logs (created_at desc)", "create index if not exists idx_admin_action_logs_admin on public.admin_action_logs (admin_id, created_at desc)", "alter table public.admin_action_logs enable row level security", "drop policy if exists admin_action_logs_select_admin on public.admin_action_logs", "create policy admin_action_logs_select_admin on public.admin_action_logs\n  for select to authenticated\n  using ((select public.is_admin()) = true)", "drop policy if exists admin_action_logs_insert_admin on public.admin_action_logs", "create policy admin_action_logs_insert_admin on public.admin_action_logs\n  for insert to authenticated\n  with check ((select public.is_admin()) = true and admin_id = (select auth.uid()))", "-- >>> NATIVE_BASELINE_PART 0046 | supabase/bundles/bundle_2_features_032_061.sql | 041_mentor_payout_account.sql <<<\n-- ===== 041_mentor_payout_account.sql =====\n\n-- 멘토 정산 계좌 (마스킹 표시용)\nalter table public.mentor_profiles\n  add column if not exists payout_bank_name text,\n  add column if not exists payout_account_number text", "comment on column public.mentor_profiles.payout_bank_name is ''정산 입금 은행명''", "comment on column public.mentor_profiles.payout_account_number is ''정산 입금 계좌번호(서버 저장, UI 마스킹)''", "-- >>> NATIVE_BASELINE_PART 0047 | supabase/bundles/bundle_2_features_032_061.sql | 042_reviews_system.sql <<<\n-- ===== 042_reviews_system.sql =====\n\n-- 멘토 리뷰 (학생 작성, 멘토 답글 1회) — 코어 스키마 (P0-2 교정본, 042와 동기화)\n-- 004(author_id/body) base 위 멱등 정합. 구 042형(student_id/content·mentor_id→mentor_profiles)을 폐기.\n-- 모더레이션 컬럼/FK는 아래 033_p1 정본, 정책은 033/045(및 별도 126) 정본 — 여기서 정의하지 않음.\ncreate table if not exists public.reviews (\n  id uuid primary key default gen_random_uuid(),\n  mentor_id uuid not null references public.users (id) on delete cascade,\n  author_id uuid not null references public.users (id) on delete cascade,\n  rating smallint not null check (rating between 1 and 5),\n  body text not null,\n  subscription_count integer,\n  mentor_reply text,\n  mentor_replied_at timestamptz,\n  is_hidden boolean not null default false,\n  created_at timestamptz not null default now()\n)", "-- 004형 base 위 멱등 코어 컬럼 정합 (모더레이션 컬럼 제외 — 033_p1 소유)\nalter table public.reviews add column if not exists author_id uuid", "alter table public.reviews add column if not exists body text", "alter table public.reviews add column if not exists subscription_count integer", "alter table public.reviews add column if not exists mentor_reply text", "alter table public.reviews add column if not exists mentor_replied_at timestamptz", "alter table public.reviews add column if not exists is_hidden boolean not null default false", "do $$\nbegin\n  if not exists (select 1 from public.reviews where body is null) then\n    alter table public.reviews alter column body set not null;\n  end if;\nend $$", "-- 정본 FK 수렴 (mentor_id/author_id → users). moderated_by FK는 033_p1 소유.\ndo $$\ndeclare c record;\nbegin\n  for c in\n    select con.conname\n    from pg_constraint con\n    where con.conrelid = ''public.reviews''::regclass and con.contype = ''f''\n      and con.conkey && (\n        select coalesce(array_agg(attnum), ''{}'')\n        from pg_attribute\n        where attrelid = ''public.reviews''::regclass\n          and attname in (''mentor_id'',''author_id''))\n  loop\n    execute format(''alter table public.reviews drop constraint %I'', c.conname);\n  end loop;\nend $$", "alter table public.reviews\n  add constraint reviews_mentor_id_fkey foreign key (mentor_id) references public.users (id) on delete cascade,\n  add constraint reviews_author_id_fkey foreign key (author_id) references public.users (id) on delete cascade", "create index if not exists idx_reviews_mentor_created on public.reviews (mentor_id, created_at desc)", "create index if not exists idx_reviews_author on public.reviews (author_id)", "create unique index if not exists uq_reviews_mentor_author on public.reviews (mentor_id, author_id)", "alter table public.reviews enable row level security", "-- 정책 미정의(정본: 033_*/045_*/126_reviews_rls_hardening.sql).\n\ncomment on table public.reviews is ''멘토 리뷰: 자격 검증(유료 2회+ 구독) 후 학생 작성, 본문 수정 불가, 멘토 답글 1회, 관리자 모더레이션(033/126)''", "-- >>> NATIVE_BASELINE_PART 0048 | supabase/bundles/bundle_2_features_032_061.sql | 033_p1_admin_reviews_moderation.sql <<<\n-- ===== 033_p1_admin_reviews_moderation.sql =====\n\n-- [의존 순서] 이 파일은 042_reviews_system.sql 이후 적용할 것\n-- [번호 충돌] 접두 033 — 동일 번호: 033_question_threads_topic.sql (이 파일: reviews 관리자 모더레이션)\n-- =============================================================================\n-- 033_p1_admin_reviews_moderation.sql\n-- 목적: public.reviews 운영 조치 컬럼 + 공개 SELECT 제한(숨김·블라인드 비노출) + 관리자 전체 조회\n-- 적용: 저장소 전용. Supabase SQL Editor에 수동 적용. (자동 배포 없음)\n-- 선행: public.reviews, public.is_admin() (003 등), auth.users\n-- 주의: 기존 rev_ins / rev_update_own 등 쓰기 정책은 변경하지 않습니다.\n-- =============================================================================\n\n-- —— 컬럼( idempotent ) ——\nalter table if exists public.reviews\n  add column if not exists is_hidden boolean not null default false", "alter table if exists public.reviews\n  add column if not exists is_blinded boolean not null default false", "alter table if exists public.reviews\n  add column if not exists moderation_state text not null default ''visible''", "alter table if exists public.reviews\n  add column if not exists moderated_at timestamptz", "alter table if exists public.reviews\n  add column if not exists moderated_by uuid null references auth.users (id) on delete set null", "comment on column public.reviews.is_hidden is ''관리자·운영: 공개 목록에서 제외.''", "comment on column public.reviews.is_blinded is ''관리자·운영: 블라인드(비노출).''", "comment on column public.reviews.moderation_state is ''운영 상태(예: visible, reviewed).''", "comment on column public.reviews.moderated_at is ''마지막 운영 조치 시각.''", "comment on column public.reviews.moderated_by is ''마지막 운영 조치자 auth.users.id.''", "alter table if exists public.reviews enable row level security", "-- —— SELECT: 004 등에서 rev_select 가 using(true) 이면 숨김이 무력화되므로 제거 후 재정의 ——\ndrop policy if exists rev_select on public.reviews", "drop policy if exists reviews_select_public_visible on public.reviews", "drop policy if exists reviews_select_admin on public.reviews", "-- 익명·일반 로그인: 공개로 볼 수 있는 리뷰만 (컬럼은 위에서 항상 존재)\ncreate policy reviews_select_public_visible\n  on public.reviews\n  for select\n  to anon, authenticated\n  using (\n    coalesce(is_hidden, false) = false\n    and coalesce(is_blinded, false) = false\n  )", "-- 관리자: 전체 행 조회(관리 콘솔·검수). is_admin() = public.users.role = ''admin''\ncreate policy reviews_select_admin\n  on public.reviews\n  for select\n  to authenticated\n  using ((select public.is_admin()) = true)", "-- rev_ins / rev_update_own 등 기존 정책은 그대로 둡니다.\n\n\n-- >>> NATIVE_BASELINE_PART 0049 | supabase/bundles/bundle_2_features_032_061.sql | 043_p1_accept_order_settlement_atomic_rpc.sql <<<\n-- ===== 043_p1_accept_order_settlement_atomic_rpc.sql =====\n\n-- P1: 학생 납품 수락 + 정산 예정 insert — 단일 트랜잭션 (service_role 전용 RPC)\n-- 선행: 003(custom_request_orders), 013(custom_order_settlement_items), 015(dispute trigger)\n-- idempotent: CREATE OR REPLACE\n\n-- ---------------------------------------------------------------------------\n-- Helpers\n-- ---------------------------------------------------------------------------\ncreate or replace function public._positive_int_from_numeric(v numeric)\nreturns integer\nlanguage sql\nimmutable\nas $$\n  select case when v is not null and v > 0 then floor(v)::integer else null end;\n$$", "create or replace function public._order_primary_status_norm(o public.custom_request_orders)\nreturns text\nlanguage sql\nimmutable\nas $$\n  select lower(trim(coalesce(\n    nullif(trim((o).status), ''''),\n    nullif(trim((o).state), ''''),\n    nullif(trim((o).order_status), ''''),\n    nullif(trim((o).stage), ''''),\n    ''''\n  )));\n$$", "-- 금액 컬럼 출처: 003_p0_custom_request_draft.sql (custom_request_orders / custom_request_applications)\ncreate or replace function public._pick_custom_order_gross_won(\n  o public.custom_request_orders,\n  app public.custom_request_applications\n)\nreturns integer\nlanguage sql\nstable\nas $$\n  select coalesce(\n    public._positive_int_from_numeric((o).agreed_price),\n    public._positive_int_from_numeric((o).proposed_price),\n    public._positive_int_from_numeric((o).price),\n    public._positive_int_from_numeric((o).amount),\n    public._positive_int_from_numeric((app).proposed_price),\n    public._positive_int_from_numeric((app).bid_amount),\n    public._positive_int_from_numeric((app).price)\n  );\n$$", "-- ---------------------------------------------------------------------------\n-- accept_custom_order_deliverable_atomic\n-- ---------------------------------------------------------------------------\ncreate or replace function public.accept_custom_order_deliverable_atomic(\n  p_order_id uuid,\n  p_student_id uuid,\n  p_require_payment boolean default true\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  o public.custom_request_orders%rowtype;\n  app public.custom_request_applications%rowtype;\n  v_norm text;\n  v_pay text;\n  v_dispute_cnt integer;\n  v_deliverable_cnt integer;\n  v_existing_settlement uuid;\n  v_gross integer;\n  v_platform_fee integer;\n  v_mentor_amount integer;\n  v_settlement_id uuid;\n  v_settlement_created boolean := false;\n  v_now timestamptz := now();\n  v_fee_rate numeric := 0.20;\nbegin\n  if p_order_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''orderId가 필요합니다.'');\n  end if;\n  if p_student_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''학생 ID가 필요합니다.'');\n  end if;\n\n  select * into o\n  from public.custom_request_orders\n  where id = p_order_id\n  for update;\n\n  if not found then\n    return jsonb_build_object(''ok'', false, ''message'', ''주문을 찾을 수 없어요.'');\n  end if;\n\n  if o.student_id is distinct from p_student_id then\n    return jsonb_build_object(''ok'', false, ''message'', ''의뢰자(학생) 본인만 납품을 수락할 수 있습니다.'');\n  end if;\n\n  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''''), '''')));\n  if p_require_payment and v_pay is distinct from ''paid'' then\n    return jsonb_build_object(''ok'', false, ''message'', ''결제가 완료되지 않은 주문은 수락할 수 없습니다.'');\n  end if;\n\n  if o.completed_at is not null\n     or o.closed_at is not null\n     or o.finished_at is not null\n     or lower(trim(coalesce(o.status, ''''))) in (\n       ''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',\n       ''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved''\n     )\n     or lower(trim(coalesce(o.state, ''''))) in (\n       ''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',\n       ''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved''\n     )\n     or lower(trim(coalesce(o.order_status, ''''))) in (\n       ''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',\n       ''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved''\n     )\n  then\n    return jsonb_build_object(''ok'', false, ''message'', ''이미 완료된 주문입니다.'');\n  end if;\n\n  v_norm := public._order_primary_status_norm(o);\n  if v_norm = '''' then\n    return jsonb_build_object(''ok'', false, ''message'', ''주문 상태를 확인할 수 없어 수락할 수 없습니다.'');\n  end if;\n\n  if v_norm not in (\n    ''delivered'',''delivered_pending_review'',''waiting_review'',''pending_review'',\n    ''redelivered'',''delivery_submitted'',''in_review''\n  ) then\n    return jsonb_build_object(\n      ''ok'', false,\n      ''message'', format(''현재 상태(%s)에서는 납품 수락을 할 수 없습니다.'', v_norm)\n    );\n  end if;\n\n  select count(*)::integer into v_dispute_cnt\n  from public.disputes d\n  where d.custom_request_order_id = p_order_id\n    and d.status in (''open'', ''under_review'', ''escalated'');\n\n  if v_dispute_cnt > 0 then\n    return jsonb_build_object(''ok'', false, ''message'', ''진행 중인 분쟁이 있어 납품 수락을 할 수 없습니다.'');\n  end if;\n\n  select count(*)::integer into v_deliverable_cnt\n  from public.custom_order_deliverables d\n  where d.custom_request_order_id = p_order_id;\n\n  if v_deliverable_cnt < 1 then\n    return jsonb_build_object(''ok'', false, ''message'', ''등록된 납품이 없어 수락할 수 없습니다.'');\n  end if;\n\n  select id into v_existing_settlement\n  from public.custom_order_settlement_items s\n  where s.custom_request_order_id = p_order_id;\n\n  select a.* into app\n  from public.custom_request_applications a\n  where a.id = coalesce(o.application_id, o.custom_request_application_id, o.selected_application_id)\n  limit 1;\n\n  if v_existing_settlement is null then\n    v_gross := public._pick_custom_order_gross_won(o, app);\n    if v_gross is not null and v_gross > 0 then\n      v_platform_fee := floor(v_gross * v_fee_rate)::integer;\n      v_mentor_amount := v_gross - v_platform_fee;\n\n      insert into public.custom_order_settlement_items (\n        custom_request_order_id,\n        mentor_id,\n        student_id,\n        gross_amount,\n        platform_fee_amount,\n        mentor_amount,\n        fee_rate,\n        status\n      ) values (\n        p_order_id,\n        o.mentor_id,\n        o.student_id,\n        v_gross,\n        v_platform_fee,\n        v_mentor_amount,\n        v_fee_rate,\n        ''pending''\n      )\n      returning id into v_settlement_id;\n\n      v_settlement_created := true;\n    end if;\n  else\n    v_settlement_id := v_existing_settlement;\n  end if;\n\n  update public.custom_request_orders\n  set\n    status = ''completed'',\n    state = ''completed'',\n    order_status = ''completed'',\n    accepted_at = coalesce(accepted_at, v_now),\n    completed_at = coalesce(completed_at, v_now),\n    updated_at = v_now\n  where id = p_order_id;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''settlement_created'', v_settlement_created,\n    ''settlement_id'', v_settlement_id,\n    ''gross'', v_gross,\n    ''fee_rate'', v_fee_rate\n  );\nexception\n  when others then\n    if sqlstate = ''23505'' then\n      -- unique settlement per order — treat as idempotent success path\n      select id into v_existing_settlement\n      from public.custom_order_settlement_items s\n      where s.custom_request_order_id = p_order_id;\n\n      update public.custom_request_orders\n      set\n        status = ''completed'',\n        state = ''completed'',\n        order_status = ''completed'',\n        accepted_at = coalesce(accepted_at, v_now),\n        completed_at = coalesce(completed_at, v_now),\n        updated_at = v_now\n      where id = p_order_id;\n\n      return jsonb_build_object(\n        ''ok'', true,\n        ''settlement_created'', false,\n        ''settlement_id'', v_existing_settlement,\n        ''reason'', ''already_exists''\n      );\n    end if;\n    raise;\nend;\n$function$", "comment on function public.accept_custom_order_deliverable_atomic(uuid, uuid, boolean) is\n  ''P1: Student deliverable accept — order completed + settlement row in one transaction. service_role only; app validates student session then passes p_student_id.''", "revoke all on function public.accept_custom_order_deliverable_atomic(uuid, uuid, boolean) from public", "grant execute on function public.accept_custom_order_deliverable_atomic(uuid, uuid, boolean) to service_role", "-- >>> NATIVE_BASELINE_PART 0050 | supabase/bundles/bundle_2_features_032_061.sql | 044_free_question_usage.sql <<<\n-- ===== 044_free_question_usage.sql =====\n\n-- P2: 무료 질문권 사용 기록 (학생당 15회·멘토당 3회 — 앱에서 count)\n-- 선행: 001(users)\n-- idempotent\n\ncreate table if not exists public.free_question_usage (\n  id uuid primary key default gen_random_uuid(),\n  student_id uuid not null references public.users (id) on delete cascade,\n  mentor_id uuid not null references public.users (id) on delete cascade,\n  created_at timestamptz not null default now()\n)", "comment on table public.free_question_usage is\n  ''구독 전 무료 질문권 차감. 학생 전체 15회·멘토당 3회는 서버에서 count로 강제.''", "create index if not exists idx_fqu_student_created\n  on public.free_question_usage (student_id, created_at desc)", "create index if not exists idx_fqu_student_mentor\n  on public.free_question_usage (student_id, mentor_id, created_at desc)", "alter table public.free_question_usage enable row level security", "drop policy if exists \"fqu_select_own\" on public.free_question_usage", "create policy \"fqu_select_own\"\n  on public.free_question_usage\n  for select\n  to authenticated\n  using ( student_id = (select auth.uid()) )", "drop policy if exists \"fqu_insert_own\" on public.free_question_usage", "create policy \"fqu_insert_own\"\n  on public.free_question_usage\n  for insert\n  to authenticated\n  with check ( student_id = (select auth.uid()) )", "-- >>> NATIVE_BASELINE_PART 0051 | supabase/bundles/bundle_2_features_032_061.sql | 045_review_eligibility_guard.sql <<<\n-- ===== 045_review_eligibility_guard.sql =====\n\n-- =============================================================================\n-- 045_review_eligibility_guard.sql\n-- 목적: reviews INSERT RLS — 동일 멘토에 결제 완료 구독 2회 이상일 때만 허용\n-- 선행: 004_p0_cash_disputes_admin_draft.sql (reviews.author_id), 002_p0 (subscriptions.student_id)\n-- 적용: Supabase SQL Editor 수동 적용\n-- =============================================================================\n\ncreate or replace function public.check_review_eligibility(\n  p_mentor_id uuid,\n  p_student_id uuid\n) returns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  paid_count integer;\n  ledger_paid integer;\nbegin\n  if p_mentor_id is null or p_student_id is null then\n    return false;\n  end if;\n\n  -- subscriptions.payment_id → payments (002 스키마; payments.subscription_id 없음)\n  select count(*)::integer\n  into paid_count\n  from public.subscriptions s\n  inner join public.payments p on p.id = s.payment_id\n  where s.student_id = p_student_id\n    and s.mentor_id = p_mentor_id\n    and lower(trim(p.status)) in (\n      ''paid'', ''succeeded'', ''completed'', ''complete'', ''success'',\n      ''captured'', ''escrowed'', ''paid_out''\n    )\n    and p.amount > 0\n    and coalesce(lower(trim(s.plan_tier)), '''') not in (''free'', ''trial'')\n    and coalesce(lower(trim(s.plan_tier)), '''') not like ''%trial%'';\n\n  if paid_count >= 2 then\n    return true;\n  end if;\n\n  -- 캐시 구독 차감( payment_id 없음 ) 대체 판정\n  select count(*)::integer\n  into ledger_paid\n  from public.subscriptions s\n  where s.student_id = p_student_id\n    and s.mentor_id = p_mentor_id\n    and exists (\n      select 1\n      from public.cash_ledger cl\n      where cl.user_id = p_student_id\n        and cl.ref_type = ''subscriptions''\n        and cl.ref_id = s.id\n        and cl.delta_cents < 0\n    );\n\n  return ledger_paid >= 2;\nend;\n$$", "revoke all on function public.check_review_eligibility(uuid, uuid) from public, anon", "grant execute on function public.check_review_eligibility(uuid, uuid) to authenticated", "comment on function public.check_review_eligibility(uuid, uuid) is\n  ''리뷰 작성 자격: 동일 멘토 paid 구독 2회+ (payments 또는 cash_ledger 차감)''", "drop policy if exists \"reviews_insert_author\" on public.reviews", "drop policy if exists \"reviews_insert_student\" on public.reviews", "create policy \"reviews_insert_student\" on public.reviews\n  for insert\n  to authenticated\n  with check (\n    (select auth.uid()) = author_id\n    and public.check_review_eligibility(mentor_id, (select auth.uid()))\n  )", "-- >>> NATIVE_BASELINE_PART 0052 | supabase/bundles/bundle_2_features_032_061.sql | 046_free_question_usage_db_guard.sql <<<\n-- ===== 046_free_question_usage_db_guard.sql =====\n\n-- 046_free_question_usage_db_guard.sql\n-- 무료 질문권 TOCTOU 방지: free_question_usage INSERT 시 DB 레벨 한도 강제\n-- 선행: 044_free_question_usage.sql\n\ncreate or replace function public.check_free_question_usage_limits()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  per_mentor_count integer;\n  total_count integer;\nbegin\n  select count(*)::integer\n  into per_mentor_count\n  from public.free_question_usage\n  where student_id = new.student_id\n    and mentor_id = new.mentor_id;\n\n  if per_mentor_count >= 3 then\n    raise exception ''FREE_QUESTION_PER_MENTOR_LIMIT''\n      using errcode = ''P0001'';\n  end if;\n\n  select count(*)::integer\n  into total_count\n  from public.free_question_usage\n  where student_id = new.student_id;\n\n  if total_count >= 15 then\n    raise exception ''FREE_QUESTION_TOTAL_LIMIT''\n      using errcode = ''P0002'';\n  end if;\n\n  return new;\nend;\n$$", "drop trigger if exists trg_free_question_usage_limits on public.free_question_usage", "create trigger trg_free_question_usage_limits\n  before insert on public.free_question_usage\n  for each row\n  execute function public.check_free_question_usage_limits()", "revoke all on function public.check_free_question_usage_limits() from public, anon", "grant execute on function public.check_free_question_usage_limits() to authenticated", "-- >>> NATIVE_BASELINE_PART 0053 | supabase/bundles/bundle_2_features_032_061.sql | 047_active_dispute_settlement_block_trigger.sql <<<\n-- ===== 047_active_dispute_settlement_block_trigger.sql =====\n\n-- =============================================================================\n-- 047_active_dispute_settlement_block_trigger.sql\n-- Supabase SQL Editor: \"VERIFY - Active Dispute Blocking Trigger\" 이관본\n-- 목적: 진행 중 분쟁(open|under_review|escalated) 시 custom_order_settlement_items INSERT 차단\n-- 선행: 004_p0_cash_disputes_admin_draft.sql (disputes), 013_p0_custom_order_settlement_items.sql\n-- idempotent: CREATE OR REPLACE FUNCTION + DROP TRIGGER IF EXISTS\n-- =============================================================================\n\ncreate or replace function public.trg_block_settlement_on_active_dispute()\nreturns trigger\nlanguage plpgsql\nsecurity invoker\nset search_path = public\nas $fn$\ndeclare\n  v_cnt integer;\nbegin\n  if new.custom_request_order_id is null then\n    return new;\n  end if;\n\n  select count(*)::integer\n    into v_cnt\n  from public.disputes d\n  where d.custom_request_order_id = new.custom_request_order_id\n    and d.status in (''open'', ''under_review'', ''escalated'');\n\n  if v_cnt > 0 then\n    raise exception ''settlement insert blocked: active dispute for order %'', new.custom_request_order_id\n      using errcode = ''P0001'',\n            hint = ''진행 중인 분쟁이 있으면 정산 예정을 추가할 수 없습니다.'';\n  end if;\n\n  return new;\nend;\n$fn$", "drop trigger if exists trg_cosi_prevent_active_dispute on public.custom_order_settlement_items", "create trigger trg_cosi_prevent_active_dispute\n  before insert on public.custom_order_settlement_items\n  for each row\n  execute function public.trg_block_settlement_on_active_dispute()", "-- =============================================================================\n-- VERIFY - Active Dispute Blocking Trigger\n-- =============================================================================\n\n-- 1) trigger 존재\n-- [bundle note] Original verification SELECT removed from executable flow:\n-- select event_object_table, trigger_name, action_timing, event_manipulation\n-- from information_schema.triggers\n-- where trigger_schema = ''public''\n--   and event_object_table = ''custom_order_settlement_items''\n--   and trigger_name = ''trg_cosi_prevent_active_dispute'';\n\n-- 2) function 존재\n-- [bundle note] Original verification SELECT removed from executable flow:\n-- select routine_schema, routine_name, routine_type\n-- from information_schema.routines\n-- where routine_schema = ''public''\n--   and routine_name = ''trg_block_settlement_on_active_dispute'';\n\n\n-- >>> NATIVE_BASELINE_PART 0054 | supabase/bundles/bundle_2_features_032_061.sql | 048_connection_notes_author.sql <<<\n-- ===== 048_connection_notes_author.sql =====\n\n-- STEP 2: 연결노트 작성자 식별 컬럼 추가\n-- 문제: connection_notes 에 작성자 컬럼이 없어 UI가 작성자(학생/멘토)를 구분하지 못하고\n--       항상 \"학생\"으로 표시되던 버그. author_id / author_role 를 추가해 본인/상대를 구분한다.\n-- 선행: 002_p0_subscriptions_questions_draft.sql (connection_notes 정의)\n-- idempotent\n\nalter table public.connection_notes\n  add column if not exists author_id uuid references public.users (id) on delete set null", "alter table public.connection_notes\n  add column if not exists author_role text", "create index if not exists idx_cn_author\n  on public.connection_notes (mentor_student_room_id, author_id)", "-- =============================================================================\n-- 검증 (SQL Editor)\n-- select column_name, data_type from information_schema.columns\n--   where table_schema = ''public'' and table_name = ''connection_notes'' order by ordinal_position;\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0055 | supabase/bundles/bundle_2_features_032_061.sql | 049_question_room_attachments_storage.sql <<<\n-- ===== 049_question_room_attachments_storage.sql =====\n\n-- STEP 5: 질문방 채팅 파일/사진 첨부 — private Storage 버킷 + storage.objects RLS\n-- 경로 규칙: `<mentor_student_room_id>/<thread_id>/<uuid>-<filename>` (첫 세그먼트 = room id)\n-- 읽기/쓰기: 해당 room 의 학생·멘토 당사자만. 선행: 002_p0 (mentor_student_rooms)\n-- idempotent\n\n-- ---------------------------------------------------------------------------\n-- 1) Storage bucket (private)\n-- ---------------------------------------------------------------------------\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues (\n  ''question-room-attachments'',\n  ''question-room-attachments'',\n  false,\n  20971520,\n  array[\n    ''image/png'',\n    ''image/jpeg'',\n    ''image/webp'',\n    ''image/gif'',\n    ''application/pdf'',\n    ''application/zip'',\n    ''application/vnd.openxmlformats-officedocument.wordprocessingml.document'',\n    ''application/vnd.openxmlformats-officedocument.presentationml.presentation''\n  ]::text[]\n)\non conflict (id) do update set\n  public = excluded.public,\n  file_size_limit = coalesce(excluded.file_size_limit, storage.buckets.file_size_limit),\n  allowed_mime_types = coalesce(excluded.allowed_mime_types, storage.buckets.allowed_mime_types)", "-- ---------------------------------------------------------------------------\n-- 2) Path → room UUID(첫 세그먼트) + 당사자 권한\n-- ---------------------------------------------------------------------------\ncreate or replace function public.qra_room_uuid_from_path(p_name text)\nreturns uuid\nlanguage plpgsql\nimmutable\nsecurity definer\nset search_path = public\nas $f$\nbegin\n  return nullif(split_part(p_name, ''/'', 1), '''')::uuid;\nexception\n  when others then\n    return null;\nend;\n$f$", "create or replace function public.user_is_room_party_for_qra_path(p_name text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $f$\n  select exists (\n    select 1\n    from public.mentor_student_rooms r\n    where r.id = public.qra_room_uuid_from_path(p_name)\n      and (select auth.uid()) in (r.student_id, r.mentor_id)\n  );\n$f$", "-- storage.objects: 읽기·쓰기 모두 해당 room 의 당사자(학생/멘토)만\ndrop policy if exists \"qra_storage_read_party\" on storage.objects", "create policy \"qra_storage_read_party\"\n  on storage.objects\n  for select\n  to authenticated\n  using (\n    bucket_id = ''question-room-attachments''\n    and public.user_is_room_party_for_qra_path(name)\n  )", "drop policy if exists \"qra_storage_insert_party\" on storage.objects", "create policy \"qra_storage_insert_party\"\n  on storage.objects\n  for insert\n  to authenticated\n  with check (\n    bucket_id = ''question-room-attachments''\n    and public.user_is_room_party_for_qra_path(name)\n  )", "-- =============================================================================\n-- 검증 (SQL Editor)\n-- select * from storage.buckets where id = ''question-room-attachments'';\n-- select * from pg_policies where schemaname = ''storage'' and tablename = ''objects'' and policyname like ''qra_%'';\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0056 | supabase/bundles/bundle_2_features_032_061.sql | 050_mentor_subscription_cap.sql <<<\n-- ===== 050_mentor_subscription_cap.sql =====\n\n-- 050_mentor_subscription_cap.sql\n-- 멘토 구독 cap(수용량) 구조.\n--   • 플랜별 cap 가중치(잠금값): limited 1.0 / standard 2.5 / premium 4.5\n--   • 멘토 1인 cap 상한 기본값 28 (관리자만 조정) → mentor_profiles.cap_limit\n--   • 멘토 사용 cap = 활성(active) 구독들의 플랜 cap 가중치 합\n--   • 결제 확정 트랜잭션(=subscriptions insert) 내에서 DB 트리거로 초과 차단(동시성 안전)\n-- idempotent. Supabase SQL Editor에서 수동 적용.\n\n-- -----------------------------------------------------------------------------\n-- 1) 멘토 cap 상한 컬럼 (기본 28, 관리자만 수정)\n-- -----------------------------------------------------------------------------\nalter table public.mentor_profiles\n  add column if not exists cap_limit numeric not null default 28", "-- -----------------------------------------------------------------------------\n-- 2) 플랜 cap 가중치 컬럼 (참조용) — tier/금액으로 채움\n-- -----------------------------------------------------------------------------\nalter table public.mentor_plans\n  add column if not exists cap_weight numeric", "-- tier 기준 채움 (limited/standard/premium)\nupdate public.mentor_plans\nset cap_weight = case lower(coalesce(plan_tier, ''''))\n    when ''limited'' then 1.0\n    when ''standard'' then 2.5\n    when ''premium'' then 4.5\n    else cap_weight\n  end\nwhere cap_weight is null\n  and lower(coalesce(plan_tier, '''')) in (''limited'', ''standard'', ''premium'')", "-- 금액(amount_cents = 캐시×100) 기준 폴백 (tier 비어있는 행)\nupdate public.mentor_plans\nset cap_weight = case amount_cents\n    when 5500000 then 1.0   -- 55,000 캐시\n    when 11490000 then 2.5  -- 114,900 캐시\n    when 24990000 then 4.5  -- 249,900 캐시\n    else cap_weight\n  end\nwhere cap_weight is null\n  and amount_cents in (5500000, 11490000, 24990000)", "-- -----------------------------------------------------------------------------\n-- 3) tier → cap 가중치 매핑 함수 (잠금값)\n-- -----------------------------------------------------------------------------\ncreate or replace function public.subscription_cap_weight(p_tier text)\nreturns numeric\nlanguage sql\nimmutable\nas $$\n  select case lower(coalesce(p_tier, ''''))\n    when ''limited'' then 1.0\n    when ''standard'' then 2.5\n    when ''premium'' then 4.5\n    else 0\n  end::numeric;\n$$", "-- -----------------------------------------------------------------------------\n-- 4) 멘토 사용 cap 합 (활성 구독 기준) — SECURITY DEFINER로 RLS 우회 집계\n--    개별 구독은 노출하지 않고 합계 numeric만 반환.\n-- -----------------------------------------------------------------------------\ncreate or replace function public.mentor_cap_used(p_mentor_id uuid)\nreturns numeric\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce(sum(public.subscription_cap_weight(s.plan_tier)), 0)::numeric\n  from public.subscriptions s\n  where s.mentor_id = p_mentor_id\n    and lower(coalesce(s.status, '''')) = ''active'';\n$$", "-- 멘토 cap 상한 (없으면 28)\ncreate or replace function public.mentor_cap_limit(p_mentor_id uuid)\nreturns numeric\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce(\n    (select mp.cap_limit from public.mentor_profiles mp where mp.user_id = p_mentor_id),\n    28\n  )::numeric;\n$$", "grant execute on function public.subscription_cap_weight(text) to anon, authenticated, service_role", "grant execute on function public.mentor_cap_used(uuid) to anon, authenticated, service_role", "grant execute on function public.mentor_cap_limit(uuid) to anon, authenticated, service_role", "-- -----------------------------------------------------------------------------\n-- 5) 신규 active 구독 insert/update 시 cap 초과 차단 트리거 (동시성 안전)\n--    (used_cap + 신규 plan cap_weight) > cap_limit 이면 예외.\n-- -----------------------------------------------------------------------------\ncreate or replace function public.enforce_mentor_cap()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_used numeric;\n  v_limit numeric;\n  v_new numeric;\nbegin\n  -- active 로 들어오는(또는 active 로 바뀌는) 행만 검사\n  if lower(coalesce(NEW.status, '''')) <> ''active'' then\n    return NEW;\n  end if;\n  if TG_OP = ''UPDATE'' and lower(coalesce(OLD.status, '''')) = ''active'' then\n    -- 이미 active 였던 행의 갱신은 추가 cap 점유가 아님\n    return NEW;\n  end if;\n\n  v_new := public.subscription_cap_weight(NEW.plan_tier);\n  if v_new <= 0 then\n    return NEW; -- 가중치를 모르는 플랜은 차단하지 않음\n  end if;\n\n  select coalesce(sum(public.subscription_cap_weight(s.plan_tier)), 0)\n    into v_used\n  from public.subscriptions s\n  where s.mentor_id = NEW.mentor_id\n    and lower(coalesce(s.status, '''')) = ''active''\n    and s.id <> NEW.id;\n\n  v_limit := public.mentor_cap_limit(NEW.mentor_id);\n\n  if (v_used + v_new) > v_limit then\n    raise exception ''MENTOR_CAP_EXCEEDED: mentor % cap %/% (+%) 초과'', NEW.mentor_id, v_used, v_limit, v_new\n      using errcode = ''check_violation'';\n  end if;\n\n  return NEW;\nend;\n$$", "drop trigger if exists trg_enforce_mentor_cap on public.subscriptions", "create trigger trg_enforce_mentor_cap\n  before insert or update of status, plan_tier on public.subscriptions\n  for each row execute function public.enforce_mentor_cap()", "-- >>> NATIVE_BASELINE_PART 0057 | supabase/bundles/bundle_2_features_032_061.sql | 051_community_typo_author_label_category_backfill.sql <<<\n-- ===== 051_community_typo_author_label_category_backfill.sql =====\n\n-- 051 community comments 오타 백필 + community_posts category 기본값 (실제 존재 컬럼만)\n\nupdate public.community_comments\nset author_label = replace(author_label, ''쉘버십'', ''쌤버십'')\nwhere author_label like ''%쉘버십%''", "update public.community_posts\nset category = ''free''\nwhere category is null or trim(category) = ''''", "-- >>> NATIVE_BASELINE_PART 0058 | supabase/bundles/bundle_2_features_032_061.sql | 052_free_question_policy_7_total_7day_expiry.sql <<<\n-- ===== 052_free_question_policy_7_total_7day_expiry.sql =====\n\n-- 052_free_question_policy_7_total_7day_expiry.sql\n-- 무료 질문권: 총량 15→7, 가입일(users.created_at) 기준 7일 만료 (앱 freeQuestionPolicy.ts와 동기)\n-- 선행: 044_free_question_usage.sql, 046_free_question_usage_db_guard.sql\n\ncreate or replace function public.check_free_question_usage_limits()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  per_mentor_count integer;\n  total_count integer;\n  signup_at timestamptz;\nbegin\n  select created_at\n  into signup_at\n  from public.users\n  where id = new.student_id;\n\n  if signup_at is null then\n    raise exception ''FREE_QUESTION_STUDENT_NOT_FOUND''\n      using errcode = ''P0003'';\n  end if;\n\n  if signup_at + interval ''7 days'' < now() then\n    raise exception ''FREE_QUESTION_EXPIRED''\n      using errcode = ''P0003'';\n  end if;\n\n  select count(*)::integer\n  into per_mentor_count\n  from public.free_question_usage\n  where student_id = new.student_id\n    and mentor_id = new.mentor_id;\n\n  if per_mentor_count >= 3 then\n    raise exception ''FREE_QUESTION_PER_MENTOR_LIMIT''\n      using errcode = ''P0001'';\n  end if;\n\n  select count(*)::integer\n  into total_count\n  from public.free_question_usage\n  where student_id = new.student_id;\n\n  if total_count >= 7 then\n    raise exception ''FREE_QUESTION_TOTAL_LIMIT''\n      using errcode = ''P0002'';\n  end if;\n\n  return new;\nend;\n$$", "drop trigger if exists trg_free_question_usage_limits on public.free_question_usage", "create trigger trg_free_question_usage_limits\n  before insert on public.free_question_usage\n  for each row\n  execute function public.check_free_question_usage_limits()", "revoke all on function public.check_free_question_usage_limits() from public, anon", "grant execute on function public.check_free_question_usage_limits() to authenticated", "comment on function public.check_free_question_usage_limits() is\n  ''무료 질문권: 가입 후 7일·총 7회·멘토당 3회 INSERT 강제''", "-- >>> NATIVE_BASELINE_PART 0059 | supabase/bundles/bundle_2_features_032_061.sql | 053_community_rls_legacy_select_cleanup.sql <<<\n-- ===== 053_community_rls_legacy_select_cleanup.sql =====\n\n-- 053 community RLS cleanup (is_mentor 의존 제거, 안전/idempotent 버전)\n\ndrop policy if exists cp_select_own on public.community_posts", "create policy cp_select_own\n  on public.community_posts\n  for select\n  using (\n    author_id = (select auth.uid())\n    or (select is_admin())\n  )", "drop policy if exists cp_select_all on public.community_posts", "drop policy if exists sp_select_all on public.shortform_posts", "-- shortform_posts: 미발행(draft) 숏폼 노출 차단 (community_posts와 동일 기준)\ndrop policy if exists \"누구나 숏폼 읽기\" on public.shortform_posts", "drop policy if exists sf_select_published on public.shortform_posts", "create policy sf_select_published\n  on public.shortform_posts for select to anon, authenticated\n  using (\n    status = ''published''\n    or author_id = (select auth.uid())\n    or creator_id = (select auth.uid())\n    or (select is_admin())\n  )", "-- >>> NATIVE_BASELINE_PART 0060 | supabase/bundles/bundle_2_features_032_061.sql | 053b_shortform_posts_published_select_rls.sql <<<\n-- ===== 053b_shortform_posts_published_select_rls.sql =====\n\n-- 053b: shortform_posts 공개 SELECT RLS\n-- 읽기 허용: published 글 / 작성자(author_id·creator_id) / 관리자.\n-- 주의: 이 정책은 staging DB에 이미 적용됨. 이 파일은 레포 정본 완성/재구축용.\n-- (drop if exists + create 라 idempotent: 재구축 시 안전하게 재적용됨)\n-- 선행: 004 또는 038(shortform_posts·status), 003 등 is_admin()\n-- 관련: 053_community_rls_legacy_select_cleanup.sql — community_posts 정리 + 동일 shortform 정책 인라인 포함\n\ndrop policy if exists sf_select_published on public.shortform_posts", "drop policy if exists sf_select_published on public.shortform_posts", "create policy sf_select_published\n  on public.shortform_posts for select to anon, authenticated\n  using (\n    status = ''published''\n    or author_id = (select auth.uid())\n    or creator_id = (select auth.uid())\n    or (select is_admin())\n  )", "-- >>> NATIVE_BASELINE_PART 0061 | supabase/bundles/bundle_2_features_032_061.sql | 054_p0_custom_order_escrow_hold.sql <<<\n-- ===== 054_p0_custom_order_escrow_hold.sql =====\n\n-- P0: 맞춤의뢰 예치(에스크로 hold) — 학생 캐시 차감 + cash_ledger append-only\n-- 선행: 004_p0_cash_disputes_admin_draft.sql (cash_wallets, cash_ledger)\n--        003_p0_custom_request_draft.sql (custom_request_orders)\n-- idempotent: CREATE OR REPLACE\n--\n-- 호출: service_role (서버) 전용. authenticated/anon GRANT 금지.\n-- idempotency_key: ''cr_hold_'' || p_order_id\n-- reason: custom_order_escrow_hold | ref_type: custom_request_orders\n\ncreate or replace function public.record_custom_order_escrow_hold(\n  p_student_id uuid,\n  p_order_id uuid,\n  p_amount_cents bigint\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_idem text := ''cr_hold_'' || p_order_id::text;\n  v_new_ledger_id uuid;\n  v_wu int;\nbegin\n  if p_student_id is null or p_order_id is null then\n    raise exception ''p_student_id and p_order_id are required'';\n  end if;\n\n  if p_amount_cents is null or p_amount_cents <= 0 then\n    raise exception ''p_amount_cents must be a positive amount'';\n  end if;\n\n  if p_amount_cents > 1000000000 then\n    raise exception ''p_amount_too_large'';\n  end if;\n\n  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n  values (\n    p_student_id,\n    -p_amount_cents,\n    ''custom_order_escrow_hold'',\n    ''custom_request_orders'',\n    p_order_id,\n    v_idem\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_new_ledger_id;\n\n  if v_new_ledger_id is null then\n    return;\n  end if;\n\n  insert into public.cash_wallets (user_id, balance_cents)\n  values (p_student_id, 0)\n  on conflict (user_id) do nothing;\n\n  update public.cash_wallets w\n  set balance_cents = w.balance_cents - p_amount_cents\n  where w.user_id = p_student_id\n    and w.balance_cents >= p_amount_cents;\n  get diagnostics v_wu = row_count;\n  if coalesce(v_wu, 0) = 0 then\n    raise exception ''CASH_INSUFFICIENT'' using errcode = ''P0001'';\n  end if;\nend;\n$function$", "comment on function public.record_custom_order_escrow_hold(uuid, uuid, bigint) is\n  ''P0: Custom order escrow hold — student wallet debit + ledger (append-only). service_role only.''", "revoke all on function public.record_custom_order_escrow_hold(uuid, uuid, bigint) from public", "revoke all on function public.record_custom_order_escrow_hold(uuid, uuid, bigint) from anon", "revoke all on function public.record_custom_order_escrow_hold(uuid, uuid, bigint) from authenticated", "grant execute on function public.record_custom_order_escrow_hold(uuid, uuid, bigint) to service_role", "-- >>> NATIVE_BASELINE_PART 0062 | supabase/bundles/bundle_2_features_032_061.sql | 055_p0_custom_order_escrow_payout.sql <<<\n-- ===== 055_p0_custom_order_escrow_payout.sql =====\n\n-- P0: 맞춤의뢰 에스크로 2단계 — 납품 수락 시 멘토 지급 + settlement paid + payment_status paid\n-- 선행: 043(accept_custom_order_deliverable_atomic), 054(record_custom_order_escrow_hold)\n-- idempotent: CREATE OR REPLACE\n--\n-- 호출: service_role 전용. authenticated/anon GRANT 금지.\n-- 멱등키: cr_payout_{order_id} (주문당 정산·지급 1회, uq_cosi_one_per_order 와 정합)\n-- fee_rate: accept RPC·settlement insert 시 기존 0.20 유지(변경 금지)\n\n-- ---------------------------------------------------------------------------\n-- record_custom_order_escrow_payout\n-- ---------------------------------------------------------------------------\ncreate or replace function public.record_custom_order_escrow_payout(\n  p_order_id uuid\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  o public.custom_request_orders%rowtype;\n  s public.custom_order_settlement_items%rowtype;\n  v_idem text := ''cr_payout_'' || p_order_id::text;\n  v_mentor_cents bigint;\n  v_hold_cents bigint;\n  v_gross_cents bigint;\n  v_new_ledger_id uuid;\n  v_wu int;\n  v_pay text;\n  v_now timestamptz := now();\nbegin\n  if p_order_id is null then\n    raise exception ''p_order_id is required'';\n  end if;\n\n  select * into o\n  from public.custom_request_orders\n  where id = p_order_id\n  for update;\n\n  if not found then\n    raise exception ''ORDER_NOT_FOUND'';\n  end if;\n\n  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''''), '''')));\n\n  select * into s\n  from public.custom_order_settlement_items\n  where custom_request_order_id = p_order_id\n  for update;\n\n  if not found then\n    raise exception ''SETTLEMENT_NOT_FOUND'';\n  end if;\n\n  -- 이미 지급 완료 — 멱등 수리(주문 payment_status 만 escrowed→paid 보정)\n  if s.status = ''paid'' then\n    if v_pay = ''escrowed'' then\n      update public.custom_request_orders\n      set payment_status = ''paid'', updated_at = v_now\n      where id = p_order_id;\n    end if;\n    return;\n  end if;\n\n  if s.status not in (''pending'', ''payable'', ''on_hold'') then\n    raise exception ''SETTLEMENT_NOT_PAYABLE'';\n  end if;\n\n  -- escrowed(정상) 또는 paid(부분 실패 수리) 만 지급. unpaid·legacy 무예치 차단.\n  if v_pay not in (''escrowed'', ''paid'') then\n    raise exception ''PAYMENT_NOT_ESCROWED'';\n  end if;\n\n  -- 예치 hold 존재·금액 정합: hold cents == settlement gross(원)×100\n  select abs(l.delta_cents) into v_hold_cents\n  from public.cash_ledger l\n  where l.idempotency_key = ''cr_hold_'' || p_order_id::text\n    and l.reason = ''custom_order_escrow_hold''\n  limit 1;\n\n  v_gross_cents := s.gross_amount::bigint * 100;\n\n  if v_hold_cents is null then\n    raise exception ''ESCROW_HOLD_MISSING'';\n  end if;\n\n  if v_hold_cents <> v_gross_cents then\n    raise exception ''ESCROW_HOLD_AMOUNT_MISMATCH'';\n  end if;\n\n  -- mentor_amount: 원(integer) → cents(원×100). gross/ledger 와 동일 단위 규칙.\n  v_mentor_cents := s.mentor_amount::bigint * 100;\n\n  if v_mentor_cents is null or v_mentor_cents <= 0 then\n    raise exception ''INVALID_MENTOR_AMOUNT'';\n  end if;\n\n  if v_mentor_cents > 1000000000 then\n    raise exception ''p_amount_too_large'';\n  end if;\n\n  -- 플랫폼 수수료(gross − mentor_amount)는 별도 platform wallet ledger 없음 — hold 차감분에 implicit.\n\n  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n  values (\n    s.mentor_id,\n    v_mentor_cents,\n    ''custom_order_escrow_payout'',\n    ''custom_request_orders'',\n    p_order_id,\n    v_idem\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_new_ledger_id;\n\n  if v_new_ledger_id is null then\n    update public.custom_order_settlement_items\n    set status = ''paid'', paid_at = coalesce(paid_at, v_now), updated_at = v_now\n    where id = s.id and status <> ''paid'';\n\n    update public.custom_request_orders\n    set payment_status = ''paid'', updated_at = v_now\n    where id = p_order_id and payment_status = ''escrowed'';\n\n    return;\n  end if;\n\n  insert into public.cash_wallets (user_id, balance_cents)\n  values (s.mentor_id, 0)\n  on conflict (user_id) do nothing;\n\n  update public.cash_wallets w\n  set balance_cents = w.balance_cents + v_mentor_cents\n  where w.user_id = s.mentor_id;\n  get diagnostics v_wu = row_count;\n  if coalesce(v_wu, 0) = 0 then\n    raise exception ''CASH_WALLET_UPSERT_FAILED'' using errcode = ''P0001'';\n  end if;\n\n  update public.custom_order_settlement_items\n  set status = ''paid'', paid_at = v_now, updated_at = v_now\n  where id = s.id;\n\n  update public.custom_request_orders\n  set payment_status = ''paid'', updated_at = v_now\n  where id = p_order_id;\nend;\n$function$", "comment on function public.record_custom_order_escrow_payout(uuid) is\n  ''P0: Custom order escrow payout — mentor wallet credit (mentor_amount×100 cents) + settlement paid. service_role only.''", "revoke all on function public.record_custom_order_escrow_payout(uuid) from public", "revoke all on function public.record_custom_order_escrow_payout(uuid) from anon", "revoke all on function public.record_custom_order_escrow_payout(uuid) from authenticated", "grant execute on function public.record_custom_order_escrow_payout(uuid) to service_role", "-- ---------------------------------------------------------------------------\n-- accept_custom_order_deliverable_atomic — escrowed 수락 허용 + payout 연동(동일 트랜잭션)\n-- ---------------------------------------------------------------------------\ncreate or replace function public.accept_custom_order_deliverable_atomic(\n  p_order_id uuid,\n  p_student_id uuid,\n  p_require_payment boolean default true\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  o public.custom_request_orders%rowtype;\n  app public.custom_request_applications%rowtype;\n  v_norm text;\n  v_pay text;\n  v_dispute_cnt integer;\n  v_deliverable_cnt integer;\n  v_existing_settlement uuid;\n  v_gross integer;\n  v_platform_fee integer;\n  v_mentor_amount integer;\n  v_settlement_id uuid;\n  v_settlement_created boolean := false;\n  v_payout_done boolean := false;\n  v_now timestamptz := now();\n  v_fee_rate numeric := 0.20;\nbegin\n  if p_order_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''orderId가 필요합니다.'');\n  end if;\n  if p_student_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''학생 ID가 필요합니다.'');\n  end if;\n\n  select * into o\n  from public.custom_request_orders\n  where id = p_order_id\n  for update;\n\n  if not found then\n    return jsonb_build_object(''ok'', false, ''message'', ''주문을 찾을 수 없어요.'');\n  end if;\n\n  if o.student_id is distinct from p_student_id then\n    return jsonb_build_object(''ok'', false, ''message'', ''의뢰자(학생) 본인만 납품을 수락할 수 있습니다.'');\n  end if;\n\n  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''''), '''')));\n  -- escrowed(예치 완료) 또는 paid(멱등·수리) 만 허용. unpaid 등 레거시 무예치 차단.\n  if p_require_payment and v_pay not in (''paid'', ''escrowed'') then\n    return jsonb_build_object(''ok'', false, ''message'', ''결제(예치)가 완료되지 않은 주문은 수락할 수 없습니다.'');\n  end if;\n\n  if o.completed_at is not null\n     or o.closed_at is not null\n     or o.finished_at is not null\n     or lower(trim(coalesce(o.status, ''''))) in (\n       ''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',\n       ''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved''\n     )\n     or lower(trim(coalesce(o.state, ''''))) in (\n       ''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',\n       ''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved''\n     )\n     or lower(trim(coalesce(o.order_status, ''''))) in (\n       ''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',\n       ''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved''\n     )\n  then\n    return jsonb_build_object(''ok'', false, ''message'', ''이미 완료된 주문입니다.'');\n  end if;\n\n  v_norm := public._order_primary_status_norm(o);\n  if v_norm = '''' then\n    return jsonb_build_object(''ok'', false, ''message'', ''주문 상태를 확인할 수 없어 수락할 수 없습니다.'');\n  end if;\n\n  if v_norm not in (\n    ''delivered'',''delivered_pending_review'',''waiting_review'',''pending_review'',\n    ''redelivered'',''delivery_submitted'',''in_review''\n  ) then\n    return jsonb_build_object(\n      ''ok'', false,\n      ''message'', format(''현재 상태(%s)에서는 납품 수락을 할 수 없습니다.'', v_norm)\n    );\n  end if;\n\n  select count(*)::integer into v_dispute_cnt\n  from public.disputes d\n  where d.custom_request_order_id = p_order_id\n    and d.status in (''open'', ''under_review'', ''escalated'');\n\n  if v_dispute_cnt > 0 then\n    return jsonb_build_object(''ok'', false, ''message'', ''진행 중인 분쟁이 있어 납품 수락을 할 수 없습니다.'');\n  end if;\n\n  select count(*)::integer into v_deliverable_cnt\n  from public.custom_order_deliverables d\n  where d.custom_request_order_id = p_order_id;\n\n  if v_deliverable_cnt < 1 then\n    return jsonb_build_object(''ok'', false, ''message'', ''등록된 납품이 없어 수락할 수 없습니다.'');\n  end if;\n\n  select id into v_existing_settlement\n  from public.custom_order_settlement_items s\n  where s.custom_request_order_id = p_order_id;\n\n  select a.* into app\n  from public.custom_request_applications a\n  where a.id = coalesce(o.application_id, o.custom_request_application_id, o.selected_application_id)\n  limit 1;\n\n  if v_existing_settlement is null then\n    v_gross := public._pick_custom_order_gross_won(o, app);\n    if v_gross is not null and v_gross > 0 then\n      v_platform_fee := floor(v_gross * v_fee_rate)::integer;\n      v_mentor_amount := v_gross - v_platform_fee;\n\n      insert into public.custom_order_settlement_items (\n        custom_request_order_id,\n        mentor_id,\n        student_id,\n        gross_amount,\n        platform_fee_amount,\n        mentor_amount,\n        fee_rate,\n        status\n      ) values (\n        p_order_id,\n        o.mentor_id,\n        o.student_id,\n        v_gross,\n        v_platform_fee,\n        v_mentor_amount,\n        v_fee_rate,\n        ''pending''\n      )\n      returning id into v_settlement_id;\n\n      v_settlement_created := true;\n    end if;\n  else\n    v_settlement_id := v_existing_settlement;\n  end if;\n\n  update public.custom_request_orders\n  set\n    status = ''completed'',\n    state = ''completed'',\n    order_status = ''completed'',\n    accepted_at = coalesce(accepted_at, v_now),\n    completed_at = coalesce(completed_at, v_now),\n    updated_at = v_now\n  where id = p_order_id;\n\n  if v_settlement_id is not null then\n    perform public.record_custom_order_escrow_payout(p_order_id);\n    v_payout_done := true;\n  end if;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''settlement_created'', v_settlement_created,\n    ''settlement_id'', v_settlement_id,\n    ''gross'', v_gross,\n    ''fee_rate'', v_fee_rate,\n    ''payout_done'', v_payout_done\n  );\nexception\n  when others then\n    if sqlstate = ''23505'' then\n      select id into v_existing_settlement\n      from public.custom_order_settlement_items s\n      where s.custom_request_order_id = p_order_id;\n\n      update public.custom_request_orders\n      set\n        status = ''completed'',\n        state = ''completed'',\n        order_status = ''completed'',\n        accepted_at = coalesce(accepted_at, v_now),\n        completed_at = coalesce(completed_at, v_now),\n        updated_at = v_now\n      where id = p_order_id;\n\n      if v_existing_settlement is not null then\n        perform public.record_custom_order_escrow_payout(p_order_id);\n        v_payout_done := true;\n      end if;\n\n      return jsonb_build_object(\n        ''ok'', true,\n        ''settlement_created'', false,\n        ''settlement_id'', v_existing_settlement,\n        ''payout_done'', v_payout_done,\n        ''reason'', ''already_exists''\n      );\n    end if;\n    raise;\nend;\n$function$", "comment on function public.accept_custom_order_deliverable_atomic(uuid, uuid, boolean) is\n  ''P1+P0: Student deliverable accept — order completed + settlement + mentor escrow payout in one transaction. service_role only.''", "revoke all on function public.accept_custom_order_deliverable_atomic(uuid, uuid, boolean) from public", "grant execute on function public.accept_custom_order_deliverable_atomic(uuid, uuid, boolean) to service_role", "-- >>> NATIVE_BASELINE_PART 0063 | supabase/bundles/bundle_2_features_032_061.sql | 056_p0_custom_order_escrow_refund.sql <<<\n-- ===== 056_p0_custom_order_escrow_refund.sql =====\n\n-- P0: 맞춤의뢰 에스크로 3단계 — 예치 전액 학생 반환(취소·환불) + 관리자 환불 연동\n-- 선행: 054(record_custom_order_escrow_hold), 055(record_custom_order_escrow_payout), 030(approve_refund_request_admin)\n-- idempotent: CREATE OR REPLACE\n--\n-- 호출: service_role 전용. authenticated/anon GRANT 금지.\n-- 멱등키: cr_refund_{order_id}\n-- reason: custom_order_escrow_refund\n\n-- ---------------------------------------------------------------------------\n-- record_custom_order_escrow_refund\n-- ---------------------------------------------------------------------------\ncreate or replace function public.record_custom_order_escrow_refund(\n  p_order_id uuid\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  o public.custom_request_orders%rowtype;\n  s public.custom_order_settlement_items%rowtype;\n  v_hold_idem text := ''cr_hold_'' || p_order_id::text;\n  v_payout_idem text := ''cr_payout_'' || p_order_id::text;\n  v_refund_idem text := ''cr_refund_'' || p_order_id::text;\n  v_hold_cents bigint;\n  v_pay text;\n  v_norm text;\n  v_new_ledger_id uuid;\n  v_wu int;\n  v_now timestamptz := now();\nbegin\n  if p_order_id is null then\n    raise exception ''p_order_id is required'';\n  end if;\n\n  select * into o\n  from public.custom_request_orders\n  where id = p_order_id\n  for update;\n\n  if not found then\n    raise exception ''ORDER_NOT_FOUND'';\n  end if;\n\n  if o.student_id is null then\n    raise exception ''STUDENT_NOT_FOUND'';\n  end if;\n\n  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''''), '''')));\n  v_norm := public._order_primary_status_norm(o);\n\n  -- 멘토 지급 완료 차단: payout ledger 또는 settlement paid\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key = v_payout_idem\n      and l.reason = ''custom_order_escrow_payout''\n  ) then\n    raise exception ''ALREADY_PAID_OUT'';\n  end if;\n\n  select * into s\n  from public.custom_order_settlement_items\n  where custom_request_order_id = p_order_id\n  for update;\n\n  if found and s.status = ''paid'' then\n    raise exception ''ALREADY_PAID_OUT'';\n  end if;\n\n  -- 멱등: 이미 환불 ledger 있으면 상태만 수리 후 종료\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key = v_refund_idem\n      and l.reason = ''custom_order_escrow_refund''\n  ) then\n    if v_pay = ''escrowed'' then\n      update public.custom_request_orders\n      set payment_status = ''refunded'', updated_at = v_now\n      where id = p_order_id;\n    end if;\n\n    update public.custom_order_settlement_items\n    set status = ''cancelled'', updated_at = v_now\n    where custom_request_order_id = p_order_id\n      and status in (''pending'', ''on_hold'', ''payable'');\n\n    if v_norm not in (''cancelled'', ''canceled'', ''refunded'') then\n      update public.custom_request_orders\n      set\n        status = ''cancelled'',\n        state = ''cancelled'',\n        order_status = ''cancelled'',\n        updated_at = v_now\n      where id = p_order_id;\n    end if;\n\n    return;\n  end if;\n\n  -- hold 필수\n  select abs(l.delta_cents) into v_hold_cents\n  from public.cash_ledger l\n  where l.idempotency_key = v_hold_idem\n    and l.reason = ''custom_order_escrow_hold''\n  limit 1;\n\n  if v_hold_cents is null then\n    raise exception ''ESCROW_HOLD_MISSING'';\n  end if;\n\n  if v_hold_cents <= 0 or v_hold_cents > 1000000000 then\n    raise exception ''ESCROW_HOLD_AMOUNT_INVALID'';\n  end if;\n\n  -- 환불 대상: escrowed(정상) 또는 refunded(부분 실패 수리)\n  if v_pay not in (''escrowed'', ''refunded'') then\n    raise exception ''PAYMENT_NOT_ESCROWED'';\n  end if;\n\n  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n  values (\n    o.student_id,\n    v_hold_cents,\n    ''custom_order_escrow_refund'',\n    ''custom_request_orders'',\n    p_order_id,\n    v_refund_idem\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_new_ledger_id;\n\n  if v_new_ledger_id is null then\n    return;\n  end if;\n\n  insert into public.cash_wallets (user_id, balance_cents)\n  values (o.student_id, 0)\n  on conflict (user_id) do nothing;\n\n  update public.cash_wallets w\n  set balance_cents = w.balance_cents + v_hold_cents\n  where w.user_id = o.student_id;\n  get diagnostics v_wu = row_count;\n  if coalesce(v_wu, 0) = 0 then\n    raise exception ''CASH_WALLET_UPDATE_FAILED'' using errcode = ''P0001'';\n  end if;\n\n  update public.custom_order_settlement_items\n  set status = ''cancelled'', updated_at = v_now\n  where custom_request_order_id = p_order_id\n    and status in (''pending'', ''on_hold'', ''payable'');\n\n  update public.custom_request_orders\n  set\n    payment_status = ''refunded'',\n    status = ''cancelled'',\n    state = ''cancelled'',\n    order_status = ''cancelled'',\n    updated_at = v_now\n  where id = p_order_id;\nend;\n$function$", "comment on function public.record_custom_order_escrow_refund(uuid) is\n  ''P0: Custom order escrow refund — return hold to student wallet (append-only). Blocks paid-out orders. service_role only.''", "revoke all on function public.record_custom_order_escrow_refund(uuid) from public", "revoke all on function public.record_custom_order_escrow_refund(uuid) from anon", "revoke all on function public.record_custom_order_escrow_refund(uuid) from authenticated", "grant execute on function public.record_custom_order_escrow_refund(uuid) to service_role", "-- ---------------------------------------------------------------------------\n-- approve_refund_request_admin — 맞춤의뢰 예치 주문은 escrow refund 경로(이중 credit 방지)\n-- ---------------------------------------------------------------------------\ncreate or replace function public.approve_refund_request_admin(\n  p_refund_id uuid,\n  p_admin_id uuid,\n  p_admin_note text default null\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  r public.refunds%rowtype;\n  v_amount bigint;\n  v_settlement_status text;\n  v_idem text := ''refund_credit:'' || p_refund_id::text;\n  v_ledger_id uuid;\n  v_existing_delta bigint;\n  v_wu int;\n  v_admin_ok boolean;\n  v_hold_cents bigint;\n  v_escrow_refund boolean := false;\nbegin\n  if p_refund_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''환불 ID가 필요합니다.'');\n  end if;\n  if p_admin_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''관리자 ID가 필요합니다.'');\n  end if;\n\n  select exists(\n    select 1 from public.users u where u.id = p_admin_id and u.role = ''admin''\n  ) into v_admin_ok;\n  if not coalesce(v_admin_ok, false) then\n    raise exception ''ADMIN_REQUIRED'';\n  end if;\n\n  select * into r from public.refunds where id = p_refund_id for update;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''message'', ''환불 요청을 찾을 수 없습니다.'');\n  end if;\n\n  if r.status is distinct from ''pending'' then\n    return jsonb_build_object(\n      ''ok'', true,\n      ''noop'', true,\n      ''refund_id'', p_refund_id,\n      ''message'', ''이미 처리되었거나 대기 상태가 아닙니다.'',\n      ''status'', r.status\n    );\n  end if;\n\n  if r.custom_request_order_id is not null then\n    select s.status into v_settlement_status\n    from public.custom_order_settlement_items s\n    where s.custom_request_order_id = r.custom_request_order_id\n    limit 1;\n    if found and v_settlement_status = ''paid'' then\n      return jsonb_build_object(\n        ''ok'', false,\n        ''message'', ''이미 정산 지급이 완료된 건은 자동 환불할 수 없습니다. 수동 조정이 필요합니다.''\n      );\n    end if;\n\n    if exists (\n      select 1 from public.cash_ledger l\n      where l.idempotency_key = ''cr_payout_'' || r.custom_request_order_id::text\n        and l.reason = ''custom_order_escrow_payout''\n    ) then\n      return jsonb_build_object(\n        ''ok'', false,\n        ''message'', ''이미 정산 지급이 완료된 건은 자동 환불할 수 없습니다. 수동 조정이 필요합니다.''\n      );\n    end if;\n\n    select abs(l.delta_cents) into v_hold_cents\n    from public.cash_ledger l\n    where l.idempotency_key = ''cr_hold_'' || r.custom_request_order_id::text\n      and l.reason = ''custom_order_escrow_hold''\n    limit 1;\n\n    if v_hold_cents is not null then\n      v_escrow_refund := true;\n      begin\n        perform public.record_custom_order_escrow_refund(r.custom_request_order_id);\n      exception\n        when others then\n          if sqlerrm like ''%ALREADY_PAID_OUT%'' or sqlerrm like ''%ESCROW_HOLD_MISSING%'' then\n            return jsonb_build_object(''ok'', false, ''message'', ''이미 정산 지급이 완료된 건은 자동 환불할 수 없습니다. 수동 조정이 필요합니다.'');\n          end if;\n          if sqlerrm like ''%PAYMENT_NOT_ESCROWED%'' then\n            return jsonb_build_object(''ok'', false, ''message'', ''예치(에스크로) 상태가 아니어서 예치 반환을 할 수 없습니다.'');\n          end if;\n          raise;\n      end;\n      v_amount := v_hold_cents;\n    end if;\n  end if;\n\n  if not v_escrow_refund then\n    if r.amount_cents is null or r.amount_cents <= 0 then\n      raise exception ''환불 금액이 설정되지 않아 자동 승인할 수 없습니다.'';\n    end if;\n\n    v_amount := r.amount_cents;\n\n    if v_amount > 1000000000 then\n      return jsonb_build_object(''ok'', false, ''message'', ''환불 금액이 허용 한도를 초과합니다.'');\n    end if;\n\n    if r.custom_request_order_id is not null then\n      update public.custom_order_settlement_items s\n      set status = ''cancelled'', updated_at = now()\n      where s.custom_request_order_id = r.custom_request_order_id\n        and s.status in (''pending'', ''on_hold'', ''payable'');\n    end if;\n\n    insert into public.cash_ledger (\n      user_id, delta_cents, reason, ref_type, ref_id, idempotency_key\n    )\n    values (\n      r.user_id, v_amount, ''refund_approved'', ''refunds'', r.id, v_idem\n    )\n    on conflict (idempotency_key) do nothing\n    returning id into v_ledger_id;\n\n    if v_ledger_id is null then\n      select cl.delta_cents into v_existing_delta\n      from public.cash_ledger cl\n      where cl.idempotency_key = v_idem\n      limit 1;\n      if not found then\n        raise exception ''REFUND_LEDGER_IDEMPOTENT_MISS'' using errcode = ''P0001'';\n      end if;\n      if v_existing_delta is distinct from v_amount then\n        raise exception ''REFUND_LEDGER_AMOUNT_MISMATCH'' using errcode = ''P0001'';\n      end if;\n    end if;\n\n    if v_ledger_id is not null then\n      insert into public.cash_wallets (user_id, balance_cents)\n      values (r.user_id, 0)\n      on conflict (user_id) do nothing;\n\n      update public.cash_wallets w\n      set balance_cents = w.balance_cents + v_amount\n      where w.user_id = r.user_id;\n      get diagnostics v_wu = row_count;\n      if coalesce(v_wu, 0) = 0 then\n        raise exception ''CASH_WALLET_UPDATE_FAILED'' using errcode = ''P0001'';\n      end if;\n    end if;\n\n    if r.custom_request_order_id is not null then\n      update public.custom_request_orders o\n      set payment_status = ''refunded'', updated_at = now()\n      where o.id = r.custom_request_order_id;\n    end if;\n  end if;\n\n  update public.refunds\n  set\n    status = ''succeeded'',\n    processed_at = now(),\n    processed_by = p_admin_id,\n    admin_note = p_admin_note,\n    updated_at = now()\n  where id = r.id;\n\n  if r.payment_id is not null then\n    update public.payments p\n    set status = ''refunded'', updated_at = now()\n    where p.id = r.payment_id;\n  end if;\n\n  if r.payment_id is not null then\n    update public.subscriptions s\n    set status = ''canceled'', updated_at = now()\n    where s.payment_id = r.payment_id\n      and s.status is distinct from ''canceled'';\n  end if;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''noop'', false,\n    ''refund_id'', r.id,\n    ''ledger_inserted'', case when v_escrow_refund then true else (v_ledger_id is not null) end,\n    ''escrow_refund'', v_escrow_refund,\n    ''amount_cents'', v_amount,\n    ''message'', ''환불이 승인되었습니다.''\n  );\nend;\n$function$", "comment on function public.approve_refund_request_admin(uuid, uuid, text) is\n  ''P0: Admin refund approve — custom order escrow uses record_custom_order_escrow_refund (no refund_credit double pay). service_role only.''", "revoke all on function public.approve_refund_request_admin(uuid, uuid, text) from public", "revoke all on function public.approve_refund_request_admin(uuid, uuid, text) from anon", "revoke all on function public.approve_refund_request_admin(uuid, uuid, text) from authenticated", "grant execute on function public.approve_refund_request_admin(uuid, uuid, text) to service_role", "-- >>> NATIVE_BASELINE_PART 0064 | supabase/bundles/bundle_2_features_032_061.sql | 057_p0_custom_order_dispute_split.sql <<<\n-- ===== 057_p0_custom_order_dispute_split.sql =====\n\n-- P0: 맞춤의뢰 에스크로 4단계-A — 분쟁 예치 분배(멘토 gross·학생 환불, 20% 공제)\n-- 선행: 054(hold), 055(payout), 056(refund), 043(_order_primary_status_norm), 004(disputes)\n-- idempotent: CREATE OR REPLACE\n--\n-- 호출: service_role 전용. authenticated/anon GRANT 금지.\n-- 멱등키: cr_dispute_payout_{order_id}, cr_dispute_refund_{order_id}\n-- reason: custom_order_dispute_payout | custom_order_dispute_refund\n-- 플랫폼 수수료분: 별도 platform wallet ledger 없음 — hold 차감분에 implicit(055/056 동일).\n\n-- ---------------------------------------------------------------------------\n-- record_custom_order_dispute_split\n-- ---------------------------------------------------------------------------\ncreate or replace function public.record_custom_order_dispute_split(\n  p_order_id uuid,\n  p_mentor_gross_won integer,\n  p_student_refund_won integer,\n  p_admin_id uuid\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  o public.custom_request_orders%rowtype;\n  s public.custom_order_settlement_items%rowtype;\n  v_hold_idem text := ''cr_hold_'' || p_order_id::text;\n  v_payout_idem text := ''cr_payout_'' || p_order_id::text;\n  v_refund_idem text := ''cr_refund_'' || p_order_id::text;\n  v_dispute_payout_idem text := ''cr_dispute_payout_'' || p_order_id::text;\n  v_dispute_refund_idem text := ''cr_dispute_refund_'' || p_order_id::text;\n  v_hold_cents bigint;\n  v_hold_gross_won integer;\n  v_settlement_gross integer;\n  v_fee_rate numeric := 0.20;\n  v_platform_fee_won integer;\n  v_mentor_net_won integer;\n  v_mentor_cents bigint;\n  v_student_cents bigint;\n  v_pay text;\n  v_norm text;\n  v_admin_ok boolean;\n  v_new_mentor_ledger uuid;\n  v_new_student_ledger uuid;\n  v_wu int;\n  v_now timestamptz := now();\n  v_disputes_resolved int := 0;\nbegin\n  if p_order_id is null then\n    raise exception ''p_order_id is required'';\n  end if;\n  if p_admin_id is null then\n    raise exception ''ADMIN_REQUIRED'';\n  end if;\n  if p_mentor_gross_won is null or p_student_refund_won is null then\n    raise exception ''DISPUTE_SPLIT_AMOUNTS_REQUIRED'';\n  end if;\n  if p_mentor_gross_won < 0 or p_student_refund_won < 0 then\n    raise exception ''DISPUTE_SPLIT_AMOUNTS_INVALID'';\n  end if;\n\n  select exists(\n    select 1 from public.users u where u.id = p_admin_id and u.role = ''admin''\n  ) into v_admin_ok;\n  if not coalesce(v_admin_ok, false) then\n    raise exception ''ADMIN_REQUIRED'';\n  end if;\n\n  select * into o\n  from public.custom_request_orders\n  where id = p_order_id\n  for update;\n\n  if not found then\n    raise exception ''ORDER_NOT_FOUND'';\n  end if;\n\n  if o.student_id is null or o.mentor_id is null then\n    raise exception ''ORDER_PARTIES_MISSING'';\n  end if;\n\n  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''''), '''')));\n  v_norm := public._order_primary_status_norm(o);\n\n  -- payout / refund / dispute-split 상호 배타\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key = v_payout_idem\n      and l.reason = ''custom_order_escrow_payout''\n  ) then\n    raise exception ''ALREADY_PAID_OUT'';\n  end if;\n\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key = v_refund_idem\n      and l.reason = ''custom_order_escrow_refund''\n  ) then\n    raise exception ''ALREADY_REFUNDED'';\n  end if;\n\n  select * into s\n  from public.custom_order_settlement_items\n  where custom_request_order_id = p_order_id\n  for update;\n\n  if found and s.status = ''paid'' then\n    raise exception ''ALREADY_PAID_OUT'';\n  end if;\n\n  select abs(l.delta_cents) into v_hold_cents\n  from public.cash_ledger l\n  where l.idempotency_key = v_hold_idem\n    and l.reason = ''custom_order_escrow_hold''\n  limit 1;\n\n  if v_hold_cents is null then\n    raise exception ''ESCROW_HOLD_MISSING'';\n  end if;\n\n  if v_hold_cents <= 0 or v_hold_cents > 1000000000 then\n    raise exception ''ESCROW_HOLD_AMOUNT_INVALID'';\n  end if;\n\n  if v_hold_cents % 100 <> 0 then\n    raise exception ''ESCROW_HOLD_AMOUNT_INVALID'';\n  end if;\n\n  v_hold_gross_won := (v_hold_cents / 100)::integer;\n\n  if found then\n    v_settlement_gross := s.gross_amount;\n    if v_settlement_gross is distinct from v_hold_gross_won then\n      raise exception ''ESCROW_HOLD_AMOUNT_MISMATCH'';\n    end if;\n  end if;\n\n  -- 멱등: 분배 ledger 가 하나라도 있으면 상태 수리 후 종료\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key in (v_dispute_payout_idem, v_dispute_refund_idem)\n      and l.reason in (''custom_order_dispute_payout'', ''custom_order_dispute_refund'')\n  ) then\n    update public.custom_order_settlement_items\n    set status = ''cancelled'', updated_at = v_now\n    where custom_request_order_id = p_order_id\n      and status in (''pending'', ''on_hold'', ''payable'');\n\n    update public.custom_request_orders\n    set\n      payment_status = ''dispute_resolved'',\n      status = ''dispute_resolved'',\n      state = ''dispute_resolved'',\n      order_status = ''dispute_resolved'',\n      updated_at = v_now\n    where id = p_order_id;\n\n    update public.disputes d\n    set\n      status = ''resolved'',\n      resolved_at = coalesce(d.resolved_at, v_now),\n      resolved_by = coalesce(d.resolved_by, p_admin_id),\n      updated_at = v_now\n    where d.custom_request_order_id = p_order_id\n      and d.status in (''open'', ''under_review'', ''escalated'');\n\n    get diagnostics v_disputes_resolved = row_count;\n\n    return jsonb_build_object(\n      ''ok'', true,\n      ''noop'', true,\n      ''order_id'', p_order_id,\n      ''hold_gross_won'', v_hold_gross_won,\n      ''disputes_resolved'', v_disputes_resolved\n    );\n  end if;\n\n  if p_mentor_gross_won + p_student_refund_won is distinct from v_hold_gross_won then\n    raise exception ''DISPUTE_SPLIT_MISMATCH'';\n  end if;\n\n  if v_pay not in (''escrowed'', ''dispute_resolved'') then\n    raise exception ''PAYMENT_NOT_ESCROWED'';\n  end if;\n\n  v_platform_fee_won := floor(p_mentor_gross_won * v_fee_rate)::integer;\n  v_mentor_net_won := p_mentor_gross_won - v_platform_fee_won;\n  v_mentor_cents := v_mentor_net_won::bigint * 100;\n  v_student_cents := p_student_refund_won::bigint * 100;\n\n  if v_mentor_cents > 1000000000 or v_student_cents > 1000000000 then\n    raise exception ''p_amount_too_large'';\n  end if;\n\n  if v_mentor_cents > 0 then\n    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n    values (\n      o.mentor_id,\n      v_mentor_cents,\n      ''custom_order_dispute_payout'',\n      ''custom_request_orders'',\n      p_order_id,\n      v_dispute_payout_idem\n    )\n    on conflict (idempotency_key) do nothing\n    returning id into v_new_mentor_ledger;\n\n    if v_new_mentor_ledger is not null then\n      insert into public.cash_wallets (user_id, balance_cents)\n      values (o.mentor_id, 0)\n      on conflict (user_id) do nothing;\n\n      update public.cash_wallets w\n      set balance_cents = w.balance_cents + v_mentor_cents\n      where w.user_id = o.mentor_id;\n      get diagnostics v_wu = row_count;\n      if coalesce(v_wu, 0) = 0 then\n        raise exception ''CASH_WALLET_UPDATE_FAILED'' using errcode = ''P0001'';\n      end if;\n    end if;\n  end if;\n\n  if v_student_cents > 0 then\n    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n    values (\n      o.student_id,\n      v_student_cents,\n      ''custom_order_dispute_refund'',\n      ''custom_request_orders'',\n      p_order_id,\n      v_dispute_refund_idem\n    )\n    on conflict (idempotency_key) do nothing\n    returning id into v_new_student_ledger;\n\n    if v_new_student_ledger is not null then\n      insert into public.cash_wallets (user_id, balance_cents)\n      values (o.student_id, 0)\n      on conflict (user_id) do nothing;\n\n      update public.cash_wallets w\n      set balance_cents = w.balance_cents + v_student_cents\n      where w.user_id = o.student_id;\n      get diagnostics v_wu = row_count;\n      if coalesce(v_wu, 0) = 0 then\n        raise exception ''CASH_WALLET_UPDATE_FAILED'' using errcode = ''P0001'';\n      end if;\n    end if;\n  end if;\n\n  update public.custom_order_settlement_items\n  set status = ''cancelled'', updated_at = v_now\n  where custom_request_order_id = p_order_id\n    and status in (''pending'', ''on_hold'', ''payable'');\n\n  update public.custom_request_orders\n  set\n    payment_status = ''dispute_resolved'',\n    status = ''dispute_resolved'',\n    state = ''dispute_resolved'',\n    order_status = ''dispute_resolved'',\n    updated_at = v_now\n  where id = p_order_id;\n\n  update public.disputes d\n  set\n    status = ''resolved'',\n    resolved_at = coalesce(d.resolved_at, v_now),\n    resolved_by = coalesce(d.resolved_by, p_admin_id),\n    updated_at = v_now\n  where d.custom_request_order_id = p_order_id\n    and d.status in (''open'', ''under_review'', ''escalated'');\n\n  get diagnostics v_disputes_resolved = row_count;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''noop'', false,\n    ''order_id'', p_order_id,\n    ''hold_gross_won'', v_hold_gross_won,\n    ''mentor_gross_won'', p_mentor_gross_won,\n    ''mentor_platform_fee_won'', v_platform_fee_won,\n    ''mentor_net_won'', v_mentor_net_won,\n    ''mentor_cents'', v_mentor_cents,\n    ''student_refund_won'', p_student_refund_won,\n    ''student_cents'', v_student_cents,\n    ''fee_rate'', v_fee_rate,\n    ''disputes_resolved'', v_disputes_resolved\n  );\nend;\n$function$", "comment on function public.record_custom_order_dispute_split(uuid, integer, integer, uuid) is\n  ''P0: Custom order dispute escrow split — mentor net (gross−20%) + student refund; hold gross must match sum. service_role only.''", "revoke all on function public.record_custom_order_dispute_split(uuid, integer, integer, uuid) from public", "revoke all on function public.record_custom_order_dispute_split(uuid, integer, integer, uuid) from anon", "revoke all on function public.record_custom_order_dispute_split(uuid, integer, integer, uuid) from authenticated", "grant execute on function public.record_custom_order_dispute_split(uuid, integer, integer, uuid) to service_role", "-- >>> NATIVE_BASELINE_PART 0065 | supabase/bundles/bundle_2_features_032_061.sql | 058_mentor_student_nickname_rpc.sql <<<\n-- ===== 058_mentor_student_nickname_rpc.sql =====\n\n-- =============================================================================\n-- P0: 멘토 맞춤의뢰 화면 — 의뢰자 닉네임/이름 표시용 RPC\n--  • users SELECT RLS(users_select_own)는 본인만 → 멘토가 학생 users 직접 SELECT 불가.\n--  • SECURITY DEFINER + custom_request_orders(mentor_id = auth.uid()) 연결 student_id 만 반환.\n--  • 반환: id, nickname, full_name (이메일 등 미포함). 관계 없는 student_id 는 0행.\n--  • 호출: authenticated 멘토. staging·운영 적용 전 SQL Editor에서 점검.\n--  • **이미 Supabase 적용됨 — 기록용.**\n-- =============================================================================\n\ncreate or replace function public.get_mentor_student_nicknames(p_student_ids uuid[])\nreturns table (\n  id uuid,\n  nickname text,\n  full_name text\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select\n    u.id,\n    u.nickname,\n    u.full_name\n  from public.users u\n  where p_student_ids is not null\n    and array_length(p_student_ids, 1) is not null\n    and u.id = any (p_student_ids)\n    and (select auth.uid()) is not null\n    and exists (\n      select 1\n      from public.custom_request_orders o\n      where o.mentor_id = (select auth.uid())\n        and o.student_id = u.id\n    );\n$$", "revoke all on function public.get_mentor_student_nicknames(uuid[]) from public", "grant execute on function public.get_mentor_student_nicknames(uuid[]) to authenticated", "comment on function public.get_mentor_student_nicknames(uuid[]) is\n  ''P0 멘토: 본인 맞춤의뢰 주문에 연결된 학생 id[] 에 대한 nickname·full_name(표시용).''", "-- >>> NATIVE_BASELINE_PART 0066 | supabase/bundles/bundle_2_features_032_061.sql | 059_p0_custom_request_application_attachments_storage.sql <<<\n-- ===== 059_p0_custom_request_application_attachments_storage.sql =====\n\n-- P0: 멘토 지원서 포트폴리오 첨부 — private Storage + custom_request_application_attachments + storage.objects RLS\n-- 선행: 001( users ), 003( custom_request_posts / custom_request_applications ), is_admin()\n-- 012( post 첨부 )와 버킷/정책명 분리. RLS 주의: post는 mentor 전원 read — 본 테이블은 **지원 멘토 본인 + post 작성 학생 + admin** 만 read.\n-- idempotent\n\n-- ---------------------------------------------------------------------------\n-- 1) custom_request_application_attachments\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.custom_request_application_attachments (\n  id uuid primary key default gen_random_uuid(),\n  application_id uuid not null references public.custom_request_applications (id) on delete cascade,\n  uploaded_by uuid not null references public.users (id) on delete restrict,\n  storage_path text not null,\n  original_filename text not null,\n  mime_type text,\n  file_size_bytes bigint,\n  created_at timestamptz not null default now()\n)", "comment on table public.custom_request_application_attachments is\n  ''멘토 지원서 제출 시 올린 포트폴리오/참고 파일 메타. storage_path 는 ASCII 키(버킷 내부), 표시명은 original_filename.''", "create index if not exists idx_craa_application_created\n  on public.custom_request_application_attachments (application_id, created_at asc)", "alter table public.custom_request_application_attachments enable row level security", "-- ---------------------------------------------------------------------------\n-- 2) Helper — application → post 작성자(학생) 확인 (012 post 작성자 동의어)\n-- ---------------------------------------------------------------------------\ncreate or replace function public.user_is_post_author_for_craa_application(p_application_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $f$\n  select exists (\n    select 1\n    from public.custom_request_applications a\n    join public.custom_request_posts p on p.id = a.post_id\n    where a.id = p_application_id\n      and (\n        p.author_id = (select auth.uid())\n        or p.student_id = (select auth.uid())\n        or p.user_id = (select auth.uid())\n        or p.requester_id = (select auth.uid())\n        or p.client_id = (select auth.uid())\n      )\n  );\n$f$", "create or replace function public.user_is_application_mentor_for_craa_application(p_application_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $f$\n  select exists (\n    select 1\n    from public.custom_request_applications a\n    where a.id = p_application_id\n      and a.mentor_id = (select auth.uid())\n  );\n$f$", "-- ---------------------------------------------------------------------------\n-- 3) 테이블 RLS — INSERT: 지원 멘토 본인 / SELECT: 멘토 본인 · post 작성 학생 · admin (mentor 전원 read 금지)\n-- ---------------------------------------------------------------------------\ndrop policy if exists \"craa_insert_mentor\" on public.custom_request_application_attachments", "create policy \"craa_insert_mentor\"\n  on public.custom_request_application_attachments\n  for insert\n  to authenticated\n  with check (\n    uploaded_by = (select auth.uid())\n    and public.user_is_application_mentor_for_craa_application(application_id) = true\n  )", "drop policy if exists \"craa_select_authorized\" on public.custom_request_application_attachments", "create policy \"craa_select_authorized\"\n  on public.custom_request_application_attachments\n  for select\n  to authenticated\n  using (\n    (select public.is_admin()) = true\n    or public.user_is_application_mentor_for_craa_application(application_id) = true\n    or public.user_is_post_author_for_craa_application(application_id) = true\n  )", "-- ---------------------------------------------------------------------------\n-- 4) Storage bucket (private) — 012와 동일 20MB / MIME\n-- ---------------------------------------------------------------------------\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues (\n  ''custom-request-application-attachments'',\n  ''custom-request-application-attachments'',\n  false,\n  20971520,\n  array[\n    ''application/pdf'',\n    ''image/png'',\n    ''image/jpeg'',\n    ''image/webp'',\n    ''application/zip'',\n    ''application/vnd.openxmlformats-officedocument.wordprocessingml.document'',\n    ''application/vnd.openxmlformats-officedocument.presentationml.presentation''\n  ]::text[]\n)\non conflict (id) do update set\n  public = excluded.public,\n  file_size_limit = coalesce(excluded.file_size_limit, storage.buckets.file_size_limit),\n  allowed_mime_types = coalesce(excluded.allowed_mime_types, storage.buckets.allowed_mime_types)", "-- ---------------------------------------------------------------------------\n-- 5) Path → application UUID(첫 세그먼트) + storage.objects RLS\n--    경로: {applicationId}/{timestamp}-{8hex}.{ext}\n-- ---------------------------------------------------------------------------\ncreate or replace function public.craa_application_uuid_from_path(p_name text)\nreturns uuid\nlanguage plpgsql\nimmutable\nsecurity definer\nset search_path = public\nas $f$\nbegin\n  return nullif(split_part(p_name, ''/'', 1), '''')::uuid;\nexception\n  when others then\n    return null;\nend;\n$f$", "create or replace function public.user_is_application_mentor_for_craa_path(p_name text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $f$\n  select public.user_is_application_mentor_for_craa_application(\n    public.craa_application_uuid_from_path(p_name)\n  );\n$f$", "create or replace function public.user_can_read_craa_storage_path(p_name text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $f$\n  select\n    (select public.is_admin()) = true\n    or public.user_is_application_mentor_for_craa_path(p_name) = true\n    or public.user_is_post_author_for_craa_application(\n      public.craa_application_uuid_from_path(p_name)\n    ) = true;\n$f$", "drop policy if exists \"craa_storage_read_authorized\" on storage.objects", "create policy \"craa_storage_read_authorized\"\n  on storage.objects\n  for select\n  to authenticated\n  using (\n    bucket_id = ''custom-request-application-attachments''\n    and public.user_can_read_craa_storage_path(name)\n  )", "drop policy if exists \"craa_storage_insert_mentor\" on storage.objects", "create policy \"craa_storage_insert_mentor\"\n  on storage.objects\n  for insert\n  to authenticated\n  with check (\n    bucket_id = ''custom-request-application-attachments''\n    and public.user_is_application_mentor_for_craa_path(name) = true\n  )", "-- =============================================================================\n-- Supabase SQL Editor — 검증용\n-- -- 테이블\n-- select column_name, data_type from information_schema.columns\n--   where table_schema = ''public'' and table_name = ''custom_request_application_attachments''\n--   order by ordinal_position;\n-- -- 버킷\n-- select id, name, public, file_size_limit from storage.buckets\n--   where id = ''custom-request-application-attachments'';\n-- -- 정책\n-- select policyname, cmd from pg_policies\n--   where schemaname = ''public'' and tablename = ''custom_request_application_attachments'';\n-- select policyname, cmd from pg_policies\n--   where schemaname = ''storage'' and tablename = ''objects'' and policyname like ''craa_%'';\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0067 | supabase/bundles/bundle_2_features_032_061.sql | 060_ai_readiness_question_schema.sql <<<\n-- ===== 060_ai_readiness_question_schema.sql =====\n\n-- =============================================================================\n-- 060_ai_readiness_question_schema.sql\n-- 목적: 질문방 AI 분석 대비 스키마 + 답변 합의/첨부 메타 기반\n-- 적용: Supabase SQL Editor 수동 적용\n-- =============================================================================\n\n-- 1) 과목 표준 축\ncreate table if not exists public.subjects (\n  code text primary key,\n  label text not null,\n  sort_order int not null default 0\n)", "insert into public.subjects (code, label, sort_order) values\n  (''korean'',''국어'',1),\n  (''english'',''영어'',2),\n  (''math'',''수학'',3),\n  (''science'',''과학'',4),\n  (''social'',''사회·역사'',5),\n  (''essay'',''논술·글쓰기'',6),\n  (''career'',''진로·입시'',7),\n  (''etc'',''기타'',99)\non conflict (code) do nothing", "alter table public.subjects enable row level security", "drop policy if exists subjects_select_all on public.subjects", "create policy subjects_select_all on public.subjects\n  for select\n  to anon, authenticated\n  using (true)", "grant select on public.subjects to anon, authenticated", "alter table public.question_threads\n  add column if not exists subject text references public.subjects(code)", "comment on column public.question_threads.subject is\n  ''표준 과목 코드(public.subjects.code). 자유 단원/개념 메모는 기존 topic 컬럼을 사용한다.''", "-- 2) 오답/숙련도 표시\nalter table public.question_threads\n  add column if not exists is_wrong_answer boolean not null default false,\n  add column if not exists mastery_status text default ''unknown''", "alter table public.question_threads\n  drop constraint if exists question_threads_mastery_status_check", "alter table public.question_threads\n  add constraint question_threads_mastery_status_check\n  check (mastery_status in (''unknown'',''wrong'',''review'',''mastered''))", "comment on column public.question_threads.is_wrong_answer is\n  ''학생이 틀렸던 문제인지 여부. 학생 본인만 UI에서 토글한다.''", "comment on column public.question_threads.mastery_status is\n  ''AI/복습 분석용 숙련도 상태: unknown/wrong/review/mastered.''", "-- 3) 답변 합의 타임스탬프\nalter table public.question_threads\n  add column if not exists first_answered_at timestamptz,\n  add column if not exists confirmed_at timestamptz", "comment on column public.question_threads.first_answered_at is\n  ''멘토가 최초로 답변 완료 처리한 시각. 평균 응답시간 계산 기준.''", "comment on column public.question_threads.confirmed_at is\n  ''학생이 답변 확인 완료 처리한 시각.''", "-- 4) AI 초안 자리\ncreate table if not exists public.ai_drafts (\n  id uuid primary key default gen_random_uuid(),\n  thread_id uuid references public.question_threads(id) on delete set null,\n  mentor_id uuid references public.users(id),\n  draft_body text not null,\n  final_body text,\n  model text,\n  prompt_tokens int,\n  completion_tokens int,\n  created_at timestamptz not null default now()\n)", "alter table public.ai_drafts enable row level security", "drop policy if exists ai_drafts_select_own on public.ai_drafts", "create policy ai_drafts_select_own on public.ai_drafts\n  for select\n  to authenticated\n  using (mentor_id = (select auth.uid()))", "drop policy if exists ai_drafts_insert_own on public.ai_drafts", "create policy ai_drafts_insert_own on public.ai_drafts\n  for insert\n  to authenticated\n  with check (mentor_id = (select auth.uid()))", "grant select, insert on public.ai_drafts to authenticated", "-- 5) 멘토 답변 스타일\nalter table public.mentor_profiles\n  add column if not exists answer_style text", "comment on column public.mentor_profiles.answer_style is\n  ''멘토 답변 스타일 메모. 향후 AI 초안/프로필 개인화에 사용.''", "-- 6) 질문 첨부 메타. 기존 메시지 본문 마커 방식은 유지하고 신규 업로드부터 병행 기록한다.\ncreate table if not exists public.question_attachments (\n  id uuid primary key default gen_random_uuid(),\n  thread_id uuid not null references public.question_threads(id) on delete cascade,\n  message_id uuid references public.question_messages(id) on delete set null,\n  storage_path text not null,\n  file_name text,\n  mime_type text,\n  created_at timestamptz not null default now()\n)", "create index if not exists idx_question_attachments_thread_created\n  on public.question_attachments (thread_id, created_at desc)", "create index if not exists idx_question_attachments_message\n  on public.question_attachments (message_id)", "alter table public.question_attachments enable row level security", "drop policy if exists question_attachments_select_via_room on public.question_attachments", "create policy question_attachments_select_via_room on public.question_attachments\n  for select\n  to authenticated\n  using (\n    exists (\n      select 1\n      from public.question_threads qt\n      join public.mentor_student_rooms r on r.id = qt.mentor_student_room_id\n      where qt.id = question_attachments.thread_id\n        and (\n          r.student_id = (select auth.uid())\n          or r.mentor_id = (select auth.uid())\n          or exists (\n            select 1 from public.users u\n            where u.id = (select auth.uid()) and u.role = ''admin''\n          )\n        )\n    )\n  )", "drop policy if exists question_attachments_insert_via_room on public.question_attachments", "create policy question_attachments_insert_via_room on public.question_attachments\n  for insert\n  to authenticated\n  with check (\n    exists (\n      select 1\n      from public.question_threads qt\n      join public.mentor_student_rooms r on r.id = qt.mentor_student_room_id\n      where qt.id = question_attachments.thread_id\n        and (\n          r.student_id = (select auth.uid())\n          or r.mentor_id = (select auth.uid())\n        )\n    )\n    and (\n      message_id is null\n      or exists (\n        select 1\n        from public.question_messages qm\n        where qm.id = question_attachments.message_id\n          and qm.thread_id = question_attachments.thread_id\n      )\n    )\n  )", "grant select, insert on public.question_attachments to authenticated", "comment on table public.question_attachments is\n  ''질문방 첨부 메타. private storage 경로와 메시지 연결을 보존해 AI/운영 분석에서 본문 마커 의존을 줄인다.''", "-- >>> NATIVE_BASELINE_PART 0068 | supabase/bundles/bundle_2_features_032_061.sql | 061_review_consecutive_and_response_time.sql <<<\n-- ===== 061_review_consecutive_and_response_time.sql =====\n\n-- =============================================================================\n-- 061_review_consecutive_and_response_time.sql\n-- 목적: 리뷰 자격 2개월 연속 구독 기준 + 멘토 평균 응답시간 RPC\n-- 적용: Supabase SQL Editor 수동 적용\n-- =============================================================================\n\ncreate or replace function public.check_review_eligibility(\n  p_mentor_id uuid,\n  p_student_id uuid\n) returns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  with paid_events as (\n    -- subscriptions.payment_id -> payments: 결제 성공 구독 이력\n    select coalesce(p.created_at, s.created_at) as paid_at\n    from public.subscriptions s\n    join public.payments p on p.id = s.payment_id\n    where s.student_id = p_student_id\n      and s.mentor_id = p_mentor_id\n      and lower(trim(p.status)) in (\n        ''paid'', ''succeeded'', ''completed'', ''complete'', ''success'',\n        ''captured'', ''escrowed'', ''paid_out''\n      )\n      and p.amount > 0\n      and coalesce(lower(trim(s.plan_tier)), '''') not in (''free'', ''trial'')\n      and coalesce(lower(trim(s.plan_tier)), '''') not like ''%trial%''\n\n    union all\n\n    -- cash wallet checkout: cash_ledger 차감 시각을 결제 주기 대체 이력으로 사용\n    select cl.created_at as paid_at\n    from public.subscriptions s\n    join public.cash_ledger cl on cl.ref_type = ''subscriptions'' and cl.ref_id = s.id\n    where s.student_id = p_student_id\n      and s.mentor_id = p_mentor_id\n      and cl.user_id = p_student_id\n      and cl.delta_cents < 0\n      and coalesce(lower(trim(s.plan_tier)), '''') not in (''free'', ''trial'')\n      and coalesce(lower(trim(s.plan_tier)), '''') not like ''%trial%''\n\n    union all\n\n    -- payment rows created by subscribe_checkout can be enough when subscription rows are upserted.\n    select p.created_at as paid_at\n    from public.payments p\n    where (p.user_id = p_student_id or p.student_id = p_student_id or p.payer_id = p_student_id)\n      and p.mentor_id = p_mentor_id\n      and lower(trim(p.status)) in (\n        ''paid'', ''succeeded'', ''completed'', ''complete'', ''success'',\n        ''captured'', ''escrowed'', ''paid_out''\n      )\n      and p.amount > 0\n      and (\n        coalesce(lower(trim(p.kind)), '''') = ''subscription''\n        or coalesce(p.metadata->>''source'', '''') = ''subscribe_checkout''\n        or coalesce(p.data->>''source'', '''') = ''subscribe_checkout''\n      )\n  ),\n  paid_months as (\n    select distinct date_trunc(''month'', paid_at at time zone ''Asia/Seoul'')::date as month_start\n    from paid_events\n    where paid_at is not null\n  )\n  select exists (\n    select 1\n    from paid_months a\n    join paid_months b on b.month_start = (a.month_start + interval ''1 month'')::date\n  );\n$$", "revoke all on function public.check_review_eligibility(uuid, uuid) from public, anon", "grant execute on function public.check_review_eligibility(uuid, uuid) to authenticated", "comment on function public.check_review_eligibility(uuid, uuid) is\n  ''리뷰 작성 자격: 동일 멘토에 결제 성공 구독이 2개월 연속 존재해야 함(payments/subscriptions/cash_ledger 기준).''", "create or replace function public.get_mentor_avg_response_hours(p_mentor_id uuid)\nreturns numeric\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  with spans as (\n    select\n      qt.created_at as start_at,\n      qt.first_answered_at as end_at\n    from public.question_threads qt\n    join public.mentor_student_rooms r on r.id = qt.mentor_student_room_id\n    where r.mentor_id = p_mentor_id\n      and qt.first_answered_at is not null\n      and qt.first_answered_at > qt.created_at\n      and lower(trim(qt.status)) in (''answered'', ''confirmed'')\n  ),\n  day_segments as (\n    select\n      s.start_at,\n      s.end_at,\n      gs.local_day\n    from spans s\n    cross join lateral generate_series(\n      date_trunc(''day'', s.start_at at time zone ''Asia/Seoul''),\n      date_trunc(''day'', s.end_at at time zone ''Asia/Seoul''),\n      interval ''1 day''\n    ) as gs(local_day)\n  ),\n  counted as (\n    select\n      start_at,\n      end_at,\n      greatest(\n        0,\n        extract(epoch from (\n          least(end_at, (local_day + interval ''1 day'') at time zone ''Asia/Seoul'')\n          - greatest(start_at, (local_day + interval ''6 hours'') at time zone ''Asia/Seoul'')\n        ))\n      ) as seconds_counted\n    from day_segments\n  ),\n  per_thread as (\n    select start_at, end_at, sum(seconds_counted) as seconds_counted\n    from counted\n    group by start_at, end_at\n  )\n  select round((avg(seconds_counted) / 3600.0)::numeric, 2)\n  from per_thread\n  where seconds_counted > 0;\n$$", "revoke all on function public.get_mentor_avg_response_hours(uuid) from public", "grant execute on function public.get_mentor_avg_response_hours(uuid) to anon, authenticated, service_role", "comment on function public.get_mentor_avg_response_hours(uuid) is\n  ''멘토 평균 응답시간: question_threads.created_at -> first_answered_at, 로컬 00:00~06:00 제외, answered/confirmed 대상.''", "-- >>> NATIVE_BASELINE_PART 0069 | supabase/bundles/bundle_3_recent_062_069.sql | preamble <<<\n-- =============================================================================\n-- bundle_3_recent_062_069.sql\n-- Generated by Codex from supabase/sql/*.sql. DO NOT EDIT ORIGINAL SQL FILES.\n-- This bundle is for a blank/company Supabase setup via SQL Editor.\n-- Execute bundle_1, verify, then bundle_2, verify, then bundle_3.\n-- DB execution was NOT performed when generating this file.\n--\n-- Included source files:\n--   - 062_custom_request_order_unique_active_application.sql\n--   - 063_gate_deliverable_storage_by_order_completion.sql\n--   - 064_subscription_billing_period_schema.sql\n--   - 065_anchor_weekly_question_usage.sql\n--   - 066_review_eligibility_billing_events.sql\n--   - 067_mentor_subscription_pricing.sql\n--   - 068_subscription_renewal_rpc.sql\n--   - 069_subscription_cancel_refund_request.sql\n--\n-- Excluded source files:\n--   - 002_app_core_schema_draft.sql\n--   - 036_p1_prelaunch_rls_tightening.sql\n--\n-- Dry-run / verification notes:\n--   - 062 duplicate-check SELECT removed; the unique index statement uses non-concurrent CREATE UNIQUE INDEX.\n--   - 064 dry-run SELECT section removed; original file has backfill probes for non-empty DBs.\n--   - 065 and 066 dry-run checks are comments only and remain non-executable.\n--   - 067 DRY RUN SELECTs removed; duplicate guard remains inside migration.\n--   - 069 VERIFY SELECTs are comments only and remain non-executable.\n-- =============================================================================\n\n\n-- >>> NATIVE_BASELINE_PART 0070 | supabase/bundles/bundle_3_recent_062_069.sql | 062_custom_request_order_unique_active_application.sql <<<\n-- ===== 062_custom_request_order_unique_active_application.sql =====\n\n-- 062_custom_request_order_unique_active_application.sql\n-- Purpose: prevent duplicate custom-request orders and duplicate escrow holds caused by double submit.\n--\n-- Apply order:\n--   1) Run the duplicate-check SELECT below first.\n--   2) If it returns any rows, stop and resolve the duplicate orders manually before creating the index.\n--   3) If it returns 0 rows, run the CREATE UNIQUE INDEX statement.\n--\n-- Notes:\n--   - This file does not modify escrow RPCs 054~057 and does not relax RLS.\n--   - The index is partial: cancelled/canceled/refunded/rejected orders are excluded so a student can reorder\n--     after cancellation/refund.\n--   - CREATE INDEX must not run inside an explicit transaction block.\n\n-- [bundle note] Original duplicate-check SELECT removed from this one-pass bundle.\n-- Run the check separately if you are applying to a non-empty database.\n\ncreate unique index if not exists ux_cro_active_application_once\n  on public.custom_request_orders ((\n    coalesce(selected_application_id, application_id, custom_request_application_id)\n  ))\n  where coalesce(selected_application_id, application_id, custom_request_application_id) is not null\n    and lower(coalesce(payment_status, '''')) not in (''cancelled'', ''canceled'', ''refunded'')\n    and lower(coalesce(status, '''')) not in (''cancelled'', ''canceled'', ''refunded'', ''rejected'')\n    and lower(coalesce(state, '''')) not in (''cancelled'', ''canceled'', ''refunded'', ''rejected'')\n    and lower(coalesce(order_status, '''')) not in (''cancelled'', ''canceled'', ''refunded'', ''rejected'')", "-- >>> NATIVE_BASELINE_PART 0071 | supabase/bundles/bundle_3_recent_062_069.sql | 063_gate_deliverable_storage_by_order_completion.sql <<<\n-- ===== 063_gate_deliverable_storage_by_order_completion.sql =====\n\n-- 063_gate_deliverable_storage_by_order_completion.sql\n-- Purpose: prevent students from bypassing the server download action by creating a direct\n-- signed URL for custom-order deliverable storage objects before order acceptance/completion.\n--\n-- Apply order:\n--   1) Apply after 010_p0_custom_order_deliverable_files_storage.sql and the app deploy that\n--      strips storage_path from pre-completion student views.\n--   2) Run the policy inspection query below before and after applying this file.\n--\n-- Rollback:\n--   drop policy if exists \"custom_order_deliverable_storage_read_party\" on storage.objects;\n--   create policy \"custom_order_deliverable_storage_read_party\"\n--     on storage.objects\n--     for select\n--     to authenticated\n--     using (\n--       bucket_id = ''custom-order-deliverables''\n--       and public.user_is_party_to_cro_storage_path(name)\n--     );\n--\n-- Inspect:\n--   select policyname, cmd, roles, qual\n--   from pg_policies\n--   where schemaname = ''storage''\n--     and tablename = ''objects''\n--     and policyname like ''custom_order_deliverable%'';\n\ncreate or replace function public.cro_primary_status_norm(o public.custom_request_orders)\nreturns text\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $f$\n  select lower(coalesce(\n    nullif(btrim(o.status), ''''),\n    nullif(btrim(o.state), ''''),\n    nullif(btrim(o.order_status), ''''),\n    nullif(btrim(o.stage), ''''),\n    ''''\n  ));\n$f$", "create or replace function public.cro_student_can_read_deliverable_storage(o public.custom_request_orders)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $f$\n  select case\n    when public.cro_primary_status_norm(o) in (\n      ''cancelled'',\n      ''canceled'',\n      ''refunded'',\n      ''rejected'',\n      ''disputed'',\n      ''dispute_resolved''\n    ) then false\n    when public.cro_primary_status_norm(o) in (''completed'', ''accepted'', ''finished'') then true\n    when public.cro_primary_status_norm(o) in (\n      ''delivered'',\n      ''delivered_pending_review'',\n      ''waiting_review'',\n      ''pending_review'',\n      ''redelivered'',\n      ''delivery_submitted'',\n      ''in_review'',\n      ''paid''\n    ) then false\n    when o.completed_at is not null or o.accepted_at is not null then true\n    else false\n  end;\n$f$", "create or replace function public.user_can_read_cro_deliverable_storage_path(p_name text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $f$\n  select exists (\n    select 1\n    from public.custom_request_orders o\n    where o.id = public.cro_uuid_from_deliverable_storage_path(p_name)\n      and (\n        (select public.is_admin()) = true\n        or o.mentor_id = (select auth.uid())\n        or (\n          (\n            o.student_id = (select auth.uid())\n            or o.buyer_id = (select auth.uid())\n            or o.client_id = (select auth.uid())\n            or o.user_id = (select auth.uid())\n            or o.author_id = (select auth.uid())\n            or o.requester_id = (select auth.uid())\n          )\n          and public.cro_student_can_read_deliverable_storage(o)\n        )\n      )\n  );\n$f$", "drop policy if exists \"custom_order_deliverable_storage_read_party\" on storage.objects", "create policy \"custom_order_deliverable_storage_read_party\"\n  on storage.objects\n  for select\n  to authenticated\n  using (\n    bucket_id = ''custom-order-deliverables''\n    and public.user_can_read_cro_deliverable_storage_path(name)\n  )", "-- >>> NATIVE_BASELINE_PART 0072 | supabase/bundles/bundle_3_recent_062_069.sql | 064_subscription_billing_period_schema.sql <<<\n-- ===== 064_subscription_billing_period_schema.sql =====\n\n-- =============================================================================\n-- 064_subscription_billing_period_schema.sql\n-- Purpose: P1 foundation for monthly subscription renewal.\n-- Scope:\n--   1) Add billing-period columns to public.subscriptions.\n--   2) Add public.subscription_billing_events.\n--   3) Backfill existing subscriptions and record the initial payment as a\n--      succeeded billing event.\n--\n-- Not included in P1:\n--   - No automatic renewal batch/cron.\n--   - No additional cash debit RPC.\n--   - No changes to record_subscription_cash_debit (019).\n--   - No changes to custom request escrow RPCs (054~057).\n--   - No change to uq_subscriptions_pair lifetime one-row model.\n--\n-- Execution order in Supabase SQL Editor:\n--   A. Review the dry-run SELECT results in section 0.\n--   B. If counts look correct, run the whole file.\n--\n-- Rollback notes:\n--   - Drop table public.subscription_billing_events after clearing\n--     subscriptions.last_billing_event_id.\n--   - Drop the added subscriptions columns if P1 must be fully reverted.\n-- =============================================================================\n\n-- -----------------------------------------------------------------------------\n-- 0) Dry-run probes removed from this one-pass bundle.\n--    Review the original file if applying to a non-empty database.\n-- -----------------------------------------------------------------------------\n\n-- -----------------------------------------------------------------------------\n-- 1) subscriptions: billing period columns.\n-- -----------------------------------------------------------------------------\nalter table public.subscriptions\n  add column if not exists started_at timestamptz,\n  add column if not exists current_period_start timestamptz,\n  add column if not exists current_period_end timestamptz,\n  add column if not exists next_billing_at timestamptz,\n  add column if not exists billing_cycle text default ''monthly'',\n  add column if not exists cancel_at_period_end boolean not null default false,\n  add column if not exists cancel_requested_at timestamptz,\n  add column if not exists canceled_at timestamptz,\n  add column if not exists expired_at timestamptz,\n  add column if not exists last_renewed_at timestamptz,\n  add column if not exists last_billing_event_id uuid,\n  add column if not exists last_payment_id uuid,\n  add column if not exists grace_until timestamptz", "alter table public.subscriptions\n  alter column billing_cycle set default ''monthly''", "do $$\ndeclare\n  v_constraint_name text;\nbegin\n  for v_constraint_name in\n    select c.conname\n    from pg_constraint c\n    where c.conrelid = ''public.subscriptions''::regclass\n      and c.contype = ''c''\n      and pg_get_constraintdef(c.oid) ilike ''%status%''\n  loop\n    execute format(''alter table public.subscriptions drop constraint if exists %I'', v_constraint_name);\n  end loop;\nend\n$$", "alter table public.subscriptions\n  add constraint subscriptions_status_check\n  check (\n    status in (\n      ''pending'',\n      ''active'',\n      ''past_due'',\n      ''cancel_scheduled'',\n      ''canceled'',\n      ''expired'',\n      ''refunded''\n    )\n  )", "do $$\nbegin\n  if not exists (\n    select 1\n    from pg_constraint\n    where conrelid = ''public.subscriptions''::regclass\n      and conname = ''subscriptions_last_payment_id_fkey''\n  ) then\n    alter table public.subscriptions\n      add constraint subscriptions_last_payment_id_fkey\n      foreign key (last_payment_id) references public.payments(id) on delete set null;\n  end if;\nend\n$$", "-- -----------------------------------------------------------------------------\n-- 2) subscription_billing_events: append-only billing history.\n-- -----------------------------------------------------------------------------\ncreate table if not exists public.subscription_billing_events (\n  id uuid primary key default gen_random_uuid(),\n  subscription_id uuid not null references public.subscriptions(id) on delete cascade,\n  student_id uuid not null references public.users(id) on delete cascade,\n  mentor_id uuid not null references public.users(id) on delete cascade,\n  event_type text not null check (\n    event_type in (\n      ''initial'',\n      ''renewal'',\n      ''renewal_failed'',\n      ''expired'',\n      ''cancel_scheduled'',\n      ''canceled'',\n      ''refund''\n    )\n  ),\n  status text not null check (\n    status in (\n      ''pending'',\n      ''processing'',\n      ''succeeded'',\n      ''failed'',\n      ''skipped'',\n      ''refunded''\n    )\n  ),\n  period_start timestamptz,\n  period_end timestamptz,\n  billing_at timestamptz,\n  amount_cents int,\n  plan_tier text,\n  plan_id uuid,\n  idempotency_key text unique,\n  ledger_id uuid references public.cash_ledger(id) on delete set null,\n  payment_id uuid references public.payments(id) on delete set null,\n  failure_code text,\n  failure_message text,\n  attempt_count int not null default 0,\n  created_at timestamptz not null default now(),\n  processed_at timestamptz\n)", "alter table public.subscription_billing_events enable row level security", "drop policy if exists \"subscription_billing_events_select_parties\" on public.subscription_billing_events", "create policy \"subscription_billing_events_select_parties\" on public.subscription_billing_events\n  for select to authenticated\n  using (\n    (select auth.uid()) in (student_id, mentor_id)\n    or (select public.is_admin()) = true\n  )", "-- No INSERT/UPDATE/DELETE policies for authenticated users.\n-- Server writes use service_role, which bypasses RLS.\ngrant select on table public.subscription_billing_events to authenticated", "grant all on table public.subscription_billing_events to service_role", "create index if not exists idx_subscription_billing_events_subscription_period\n  on public.subscription_billing_events (subscription_id, period_start)", "create index if not exists idx_subscription_billing_events_pair_status\n  on public.subscription_billing_events (student_id, mentor_id, status)", "create index if not exists idx_subscription_billing_events_pending_billing_at\n  on public.subscription_billing_events (billing_at)\n  where status = ''pending''", "do $$\nbegin\n  if not exists (\n    select 1\n    from pg_constraint\n    where conrelid = ''public.subscriptions''::regclass\n      and conname = ''subscriptions_last_billing_event_id_fkey''\n  ) then\n    alter table public.subscriptions\n      add constraint subscriptions_last_billing_event_id_fkey\n      foreign key (last_billing_event_id)\n      references public.subscription_billing_events(id)\n      on delete set null;\n  end if;\nend\n$$", "-- -----------------------------------------------------------------------------\n-- 3) Backfill existing subscriptions.\n--    Month-end policy: PostgreSQL interval arithmetic clamps missing month days\n--    to the target month''s last day (for example Jan 31 + 1 month = Feb 28/29).\n-- -----------------------------------------------------------------------------\nupdate public.subscriptions\nset\n  started_at = coalesce(started_at, created_at),\n  current_period_start = coalesce(current_period_start, coalesce(started_at, created_at)),\n  current_period_end = coalesce(current_period_end, coalesce(started_at, created_at) + interval ''1 month''),\n  next_billing_at = coalesce(next_billing_at, coalesce(current_period_end, coalesce(started_at, created_at) + interval ''1 month'')),\n  billing_cycle = coalesce(nullif(billing_cycle, ''''), ''monthly''),\n  last_payment_id = coalesce(last_payment_id, payment_id)\nwhere started_at is null\n   or current_period_start is null\n   or current_period_end is null\n   or next_billing_at is null\n   or billing_cycle is null\n   or billing_cycle = ''''\n   or (last_payment_id is null and payment_id is not null)", "with initial_source as (\n  select\n    s.id as subscription_id,\n    s.student_id,\n    s.mentor_id,\n    s.plan_tier,\n    s.plan_id,\n    s.payment_id,\n    s.current_period_start,\n    s.current_period_end,\n    coalesce(cl.created_at, p.created_at, s.created_at) as billing_at,\n    coalesce(\n      abs(cl.delta_cents)::int,\n      mp.amount_cents::int,\n      case\n        when p.amount is not null and p.amount > 0 then round(p.amount * 100)::int\n        else null\n      end\n    ) as amount_cents,\n    cl.id as ledger_id\n  from public.subscriptions s\n  left join public.payments p on p.id = s.payment_id\n  left join public.mentor_plans mp on mp.id = s.plan_id\n  left join lateral (\n    select l.id, l.delta_cents, l.created_at\n    from public.cash_ledger l\n    where l.ref_type = ''subscriptions''\n      and l.ref_id = s.id\n      and l.user_id = s.student_id\n      and l.delta_cents < 0\n    order by l.created_at asc\n    limit 1\n  ) cl on true\n)\ninsert into public.subscription_billing_events (\n  subscription_id,\n  student_id,\n  mentor_id,\n  event_type,\n  status,\n  period_start,\n  period_end,\n  billing_at,\n  amount_cents,\n  plan_tier,\n  plan_id,\n  idempotency_key,\n  ledger_id,\n  payment_id,\n  created_at,\n  processed_at\n)\nselect\n  src.subscription_id,\n  src.student_id,\n  src.mentor_id,\n  ''initial'',\n  ''succeeded'',\n  src.current_period_start,\n  src.current_period_end,\n  src.billing_at,\n  src.amount_cents,\n  src.plan_tier,\n  src.plan_id,\n  ''sub_initial:'' || src.subscription_id::text,\n  src.ledger_id,\n  src.payment_id,\n  now(),\n  src.billing_at\nfrom initial_source src\non conflict (idempotency_key) do nothing", "update public.subscriptions s\nset\n  last_billing_event_id = coalesce(s.last_billing_event_id, e.id),\n  last_payment_id = coalesce(s.last_payment_id, e.payment_id, s.payment_id)\nfrom public.subscription_billing_events e\nwhere e.subscription_id = s.id\n  and e.event_type = ''initial''\n  and e.idempotency_key = ''sub_initial:'' || s.id::text\n  and (s.last_billing_event_id is null or s.last_payment_id is null)", "-- -----------------------------------------------------------------------------\n-- 4) Verification queries.\n-- -----------------------------------------------------------------------------\nselect\n  count(*) as initial_billing_events_total,\n  count(*) filter (where event_type = ''initial'' and status = ''succeeded'') as initial_succeeded_total\nfrom public.subscription_billing_events", "select\n  s.id,\n  s.status,\n  s.started_at,\n  s.current_period_start,\n  s.current_period_end,\n  s.next_billing_at,\n  s.last_billing_event_id,\n  e.idempotency_key as initial_event_key,\n  e.amount_cents as initial_event_amount_cents\nfrom public.subscriptions s\nleft join public.subscription_billing_events e on e.id = s.last_billing_event_id\norder by s.created_at asc", "-- >>> NATIVE_BASELINE_PART 0073 | supabase/bundles/bundle_3_recent_062_069.sql | 065_anchor_weekly_question_usage.sql <<<\n-- ===== 065_anchor_weekly_question_usage.sql =====\n\n-- =============================================================================\n-- 065_anchor_weekly_question_usage.sql\n-- Purpose: Question quota windows reset every 7 days from the subscription\n--          start anchor, not on the calendar Monday boundary.\n--\n-- Prerequisite:\n--   - 064_subscription_billing_period_schema.sql has been applied.\n--\n-- Scope:\n--   - Replace get_weekly_question_usage(uuid, uuid) only.\n--   - No cash debit, renewal batch, escrow, or custom request changes.\n--\n-- Dry-run checks before/after applying:\n--   select id, student_id, mentor_id, status, started_at, created_at\n--   from public.subscriptions\n--   where status = ''active''\n--   order by created_at desc\n--   limit 20;\n--\n-- Formula:\n--   anchor = coalesce(subscriptions.started_at, subscriptions.created_at)\n--   period_start = anchor + floor((now - anchor) / 7 days) * 7 days\n--   period_end = period_start + 7 days\n-- =============================================================================\n\ncreate or replace function public.get_weekly_question_usage(\n  p_student_id uuid,\n  p_mentor_id uuid\n)\nreturns json\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_anchor timestamptz;\n  v_week_start timestamptz;\n  v_week_end timestamptz;\n  v_elapsed_seconds numeric;\n  v_period_index integer;\n  v_used integer := 0;\n  v_plan_tier text;\n  v_limit integer := 0;\nbegin\n  if p_student_id is null or p_mentor_id is null then\n    raise exception ''p_student_id and p_mentor_id are required'';\n  end if;\n\n  select\n    s.plan_tier,\n    coalesce(s.started_at, s.created_at)\n  into v_plan_tier, v_anchor\n  from public.subscriptions s\n  where s.student_id = p_student_id\n    and s.mentor_id = p_mentor_id\n    and lower(coalesce(s.status, '''')) = ''active''\n  order by s.created_at desc\n  limit 1;\n\n  v_limit := case lower(coalesce(v_plan_tier, ''''))\n    when ''limited'' then 4\n    when ''standard'' then 9\n    when ''premium'' then 999\n    else 0\n  end;\n\n  if v_anchor is not null then\n    v_elapsed_seconds := extract(epoch from (now() - v_anchor));\n    v_period_index := greatest(0, floor(v_elapsed_seconds / 604800.0)::integer);\n    v_week_start := v_anchor + (v_period_index * interval ''7 days'');\n    v_week_end := v_week_start + interval ''7 days'';\n\n    select count(*)::integer into v_used\n    from public.question_threads qt\n    inner join public.mentor_student_rooms r on r.id = qt.mentor_student_room_id\n    where r.student_id = p_student_id\n      and r.mentor_id = p_mentor_id\n      and qt.status = ''confirmed''\n      and coalesce(qt.updated_at, qt.created_at) >= v_week_start\n      and coalesce(qt.updated_at, qt.created_at) < v_week_end;\n  end if;\n\n  return json_build_object(\n    ''used'', coalesce(v_used, 0),\n    ''limit'', v_limit,\n    ''plan_tier'', v_plan_tier,\n    ''remaining'', greatest(0, v_limit - coalesce(v_used, 0)),\n    ''can_ask'', coalesce(v_used, 0) < v_limit,\n    ''week_start'', v_week_start,\n    ''week_end'', v_week_end\n  );\nend;\n$function$", "revoke all on function public.get_weekly_question_usage(uuid, uuid) from public", "grant execute on function public.get_weekly_question_usage(uuid, uuid) to authenticated", "grant execute on function public.get_weekly_question_usage(uuid, uuid) to service_role", "comment on function public.get_weekly_question_usage(uuid, uuid) is\n  ''Weekly question usage: confirmed threads counted in a 7-day window anchored to subscriptions.started_at (fallback created_at), independently per student-mentor subscription.''", "-- >>> NATIVE_BASELINE_PART 0074 | supabase/bundles/bundle_3_recent_062_069.sql | 066_review_eligibility_billing_events.sql <<<\n-- ===== 066_review_eligibility_billing_events.sql =====\n\n-- =============================================================================\n-- 066_review_eligibility_billing_events.sql\n-- Purpose: Review eligibility is based on 2+ successful paid billing events for\n--          the same student/mentor pair.\n--\n-- Prerequisite:\n--   - 064_subscription_billing_period_schema.sql has been applied.\n--\n-- Scope:\n--   - Replace public.check_review_eligibility(uuid, uuid).\n--   - Keep reviews storage/display/reply/moderation logic unchanged.\n--   - No subscription renewal debit, cron, escrow, or custom request changes.\n--\n-- Dry-run checks:\n--   select student_id, mentor_id, count(*) as succeeded_paid_events\n--   from public.subscription_billing_events\n--   where status = ''succeeded''\n--     and event_type in (''initial'', ''renewal'')\n--     and coalesce(amount_cents, 0) > 0\n--     and coalesce(lower(trim(plan_tier)), '''') not in (''free'', ''trial'')\n--     and coalesce(lower(trim(plan_tier)), '''') not like ''%trial%''\n--   group by student_id, mentor_id\n--   order by succeeded_paid_events desc;\n-- =============================================================================\n\ncreate or replace function public.check_review_eligibility(\n  p_mentor_id uuid,\n  p_student_id uuid\n) returns boolean\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  event_paid integer := 0;\n  ledger_paid integer := 0;\n  payment_paid integer := 0;\nbegin\n  if p_mentor_id is null or p_student_id is null then\n    return false;\n  end if;\n\n  select count(*)::integer\n  into event_paid\n  from public.subscription_billing_events e\n  where e.student_id = p_student_id\n    and e.mentor_id = p_mentor_id\n    and e.status = ''succeeded''\n    and e.event_type in (''initial'', ''renewal'')\n    and coalesce(e.amount_cents, 0) > 0\n    and coalesce(lower(trim(e.plan_tier)), '''') not in (''free'', ''trial'')\n    and coalesce(lower(trim(e.plan_tier)), '''') not like ''%trial%'';\n\n  if event_paid >= 2 then\n    return true;\n  end if;\n\n  -- Fallback for old data if billing events are missing/incomplete.\n  -- Count ledger rows first because a cash checkout has both payments and ledger;\n  -- do not add the two counts together.\n  select count(*)::integer\n  into ledger_paid\n  from public.subscriptions s\n  join public.cash_ledger cl\n    on cl.ref_type = ''subscriptions''\n   and cl.ref_id = s.id\n   and cl.user_id = p_student_id\n   and cl.delta_cents < 0\n  where s.student_id = p_student_id\n    and s.mentor_id = p_mentor_id\n    and coalesce(lower(trim(s.plan_tier)), '''') not in (''free'', ''trial'')\n    and coalesce(lower(trim(s.plan_tier)), '''') not like ''%trial%'';\n\n  if ledger_paid >= 2 then\n    return true;\n  end if;\n\n  select count(*)::integer\n  into payment_paid\n  from public.payments p\n  where (p.user_id = p_student_id or p.student_id = p_student_id or p.payer_id = p_student_id)\n    and p.mentor_id = p_mentor_id\n    and lower(trim(p.status)) in (\n      ''paid'', ''succeeded'', ''completed'', ''complete'', ''success'',\n      ''captured'', ''escrowed'', ''paid_out''\n    )\n    and p.amount > 0\n    and (\n      coalesce(lower(trim(p.kind)), '''') = ''subscription''\n      or coalesce(p.metadata->>''source'', '''') = ''subscribe_checkout''\n      or coalesce(p.data->>''source'', '''') = ''subscribe_checkout''\n    );\n\n  return greatest(event_paid, ledger_paid, payment_paid) >= 2;\nend;\n$$", "revoke all on function public.check_review_eligibility(uuid, uuid) from public, anon", "grant execute on function public.check_review_eligibility(uuid, uuid) to authenticated", "comment on function public.check_review_eligibility(uuid, uuid) is\n  ''Review eligibility: same student/mentor pair needs at least two successful paid subscription billing events (initial/renewal). Falls back to legacy subscription ledger/payment counts without summing duplicate sources.''", "-- >>> NATIVE_BASELINE_PART 0075 | supabase/bundles/bundle_3_recent_062_069.sql | 067_mentor_subscription_pricing.sql <<<\n-- ===== 067_mentor_subscription_pricing.sql =====\n\n-- 067_mentor_subscription_pricing.sql\n-- Purpose: allow mentors to set subscription plan prices through public.mentor_plans.amount_cents.\n--\n-- Execution order:\n-- 1) Review the DRY-RUN SELECT results below.\n-- 2) If duplicate_rows returns any row, stop and resolve duplicates manually before running the migration.\n-- 3) Run the whole file in Supabase SQL Editor.\n--\n-- Rollback notes:\n-- - drop index if exists public.uq_mentor_plans_mentor_tier;\n-- - alter table public.mentor_plans drop column if exists price_updated_at;\n-- - seeded rows can be removed manually only if they were not edited/used.\n\n-- [bundle note] Original DRY RUN SELECTs 1~3 removed from this one-pass bundle.\n-- Review the original file if applying to a non-empty database.\n\nbegin", "alter table public.mentor_plans\n  add column if not exists price_updated_at timestamptz", "do $$\ndeclare\n  duplicate_count integer;\nbegin\n  select count(*)\n    into duplicate_count\n  from (\n    select mentor_id, plan_tier\n    from public.mentor_plans\n    where mentor_id is not null\n      and plan_tier in (''limited'', ''standard'', ''premium'')\n    group by mentor_id, plan_tier\n    having count(*) > 1\n  ) d;\n\n  if duplicate_count > 0 then\n    raise exception ''mentor_plans has duplicate mentor_id/plan_tier rows. Review DRY RUN 1 and resolve duplicates before creating the unique index.'';\n  end if;\nend $$", "create unique index if not exists uq_mentor_plans_mentor_tier\n  on public.mentor_plans (mentor_id, plan_tier)", "-- Normalize legacy values accidentally stored as KRW in amount_cents.\nupdate public.mentor_plans\nset\n  amount_cents = amount_cents * 100,\n  updated_at = now(),\n  price_updated_at = coalesce(price_updated_at, now())\nwhere (\n    (plan_tier = ''limited'' and amount_cents between 39900 and 69900)\n or (plan_tier = ''standard'' and amount_cents between 84900 and 149900)\n or (plan_tier = ''premium'' and amount_cents between 189900 and 329900)\n)", "-- Prevent null/zero prices from becoming zero-cash checkout rows. Ranges are not enforced by DB.\nupdate public.mentor_plans\nset\n  amount_cents = case plan_tier\n    when ''limited'' then 5500000\n    when ''standard'' then 11490000\n    when ''premium'' then 24990000\n    else amount_cents\n  end,\n  updated_at = now(),\n  price_updated_at = coalesce(price_updated_at, now())\nwhere plan_tier in (''limited'', ''standard'', ''premium'')\n  and (amount_cents is null or amount_cents <= 0)", "-- Seed every mentor with the three required tiers. Mentors may later edit prices freely.\nwith mentor_users as (\n  select id\n  from public.users\n  where role = ''mentor''\n),\ntiers(plan_tier, label, amount_cents) as (\n  values\n    (''limited'', ''Limited'', 5500000),\n    (''standard'', ''Standard'', 11490000),\n    (''premium'', ''Premium'', 24990000)\n)\ninsert into public.mentor_plans (\n  mentor_id,\n  plan_tier,\n  label,\n  amount_cents,\n  created_at,\n  updated_at,\n  price_updated_at\n)\nselect\n  m.id,\n  t.plan_tier,\n  t.label,\n  t.amount_cents,\n  now(),\n  now(),\n  now()\nfrom mentor_users m\ncross join tiers t\non conflict (mentor_id, plan_tier) do nothing", "comment on column public.mentor_plans.price_updated_at is\n  ''Last time the mentor subscription price was changed. Ranges are soft-guided in UI, not DB-enforced.''", "commit", "-- >>> NATIVE_BASELINE_PART 0076 | supabase/bundles/bundle_3_recent_062_069.sql | 068_subscription_renewal_rpc.sql <<<\n-- ===== 068_subscription_renewal_rpc.sql =====\n\n-- =============================================================================\n-- 068_subscription_renewal_rpc.sql\n-- Purpose: P2 monthly subscription renewal debit RPC.\n--\n-- Safety:\n--   - Does not modify 019 record_subscription_cash_debit.\n--   - Does not touch custom request escrow RPCs 054~057.\n--   - No negative wallet balance: wallet update requires balance >= amount.\n--   - Idempotency layers:\n--       1) subscription_billing_events.idempotency_key unique\n--       2) cash_ledger.idempotency_key unique\n--       3) subscriptions row SELECT ... FOR UPDATE\n--\n-- Execution:\n--   Run after 064_subscription_billing_period_schema.sql.\n--\n-- Rollback:\n--   revoke all on function public.process_subscription_renewal(uuid, timestamptz, bigint, text, timestamptz) from public;\n--   drop function if exists public.process_subscription_renewal(uuid, timestamptz, bigint, text, timestamptz);\n-- =============================================================================\n\ncreate or replace function public.process_subscription_renewal(\n  p_subscription_id uuid,\n  p_period_end timestamptz,\n  p_amount_cents bigint,\n  p_idempotency_key text,\n  p_processed_at timestamptz default now()\n)\nreturns table (\n  ok boolean,\n  code text,\n  message text,\n  billing_event_id uuid,\n  ledger_id uuid,\n  next_period_start timestamptz,\n  next_period_end timestamptz,\n  wallet_balance_cents bigint,\n  attempt_count int\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_sub public.subscriptions%rowtype;\n  v_event public.subscription_billing_events%rowtype;\n  v_event_id uuid;\n  v_ledger_id uuid;\n  v_wallet_balance bigint;\n  v_period_start timestamptz;\n  v_period_end timestamptz;\n  v_attempt_count int;\nbegin\n  if p_subscription_id is null then\n    return query select false, ''invalid_subscription''::text, ''subscription_id is required''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\n    return;\n  end if;\n\n  if p_amount_cents is null or p_amount_cents <= 0 then\n    return query select false, ''invalid_amount''::text, ''p_amount_cents must be positive''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\n    return;\n  end if;\n\n  if p_idempotency_key is null or length(trim(p_idempotency_key)) = 0 then\n    return query select false, ''invalid_idempotency_key''::text, ''idempotency_key is required''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\n    return;\n  end if;\n\n  select *\n    into v_sub\n  from public.subscriptions\n  where id = p_subscription_id\n  for update;\n\n  if not found then\n    return query select false, ''not_found''::text, ''subscription not found''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\n    return;\n  end if;\n\n  if coalesce(v_sub.status, '''') not in (''active'', ''past_due'') then\n    return query select false, ''not_renewable_status''::text, ''subscription status is not renewable''::text, null::uuid, null::uuid, v_sub.current_period_start, v_sub.current_period_end, null::bigint, 0::int;\n    return;\n  end if;\n\n  select *\n    into v_event\n  from public.subscription_billing_events\n  where idempotency_key = p_idempotency_key\n  for update;\n\n  if found then\n    if v_event.status = ''succeeded'' then\n      return query select true, ''already_succeeded''::text, ''renewal already processed''::text, v_event.id, v_event.ledger_id, v_event.period_start, v_event.period_end, null::bigint, coalesce(v_event.attempt_count, 0);\n      return;\n    end if;\n\n    if v_event.status in (''pending'', ''processing'') then\n      return query select false, ''already_processing''::text, ''renewal is already processing''::text, v_event.id, v_event.ledger_id, v_event.period_start, v_event.period_end, null::bigint, coalesce(v_event.attempt_count, 0);\n      return;\n    end if;\n\n    update public.subscription_billing_events as e\n    set\n      event_type = ''renewal'',\n      status = ''processing'',\n      failure_code = null,\n      failure_message = null,\n      amount_cents = p_amount_cents::int,\n      billing_at = p_processed_at,\n      attempt_count = coalesce(attempt_count, 0) + 1,\n      processed_at = null\n    where e.id = v_event.id\n    returning e.* into v_event;\n\n    v_event_id := v_event.id;\n    v_attempt_count := coalesce(v_event.attempt_count, 1);\n  else\n    v_period_start := coalesce(v_sub.current_period_end, p_period_end, p_processed_at);\n    v_period_end := v_period_start + interval ''1 month'';\n\n    insert into public.subscription_billing_events (\n      subscription_id,\n      student_id,\n      mentor_id,\n      event_type,\n      status,\n      period_start,\n      period_end,\n      billing_at,\n      amount_cents,\n      plan_tier,\n      plan_id,\n      idempotency_key,\n      attempt_count,\n      created_at\n    )\n    values (\n      v_sub.id,\n      v_sub.student_id,\n      v_sub.mentor_id,\n      ''renewal'',\n      ''processing'',\n      v_period_start,\n      v_period_end,\n      p_processed_at,\n      p_amount_cents::int,\n      v_sub.plan_tier,\n      v_sub.plan_id,\n      p_idempotency_key,\n      1,\n      p_processed_at\n    )\n    returning * into v_event;\n\n    v_event_id := v_event.id;\n    v_attempt_count := 1;\n  end if;\n\n  insert into public.cash_wallets (user_id, balance_cents)\n  values (v_sub.student_id, 0)\n  on conflict (user_id) do nothing;\n\n  update public.cash_wallets\n  set balance_cents = balance_cents - p_amount_cents\n  where user_id = v_sub.student_id\n    and balance_cents >= p_amount_cents\n  returning balance_cents into v_wallet_balance;\n\n  if not found then\n    update public.subscription_billing_events as e\n    set\n      event_type = ''renewal_failed'',\n      status = ''failed'',\n      failure_code = ''insufficient_cash'',\n      failure_message = ''CASH_INSUFFICIENT'',\n      processed_at = p_processed_at\n    where e.id = v_event_id\n    returning e.attempt_count into v_attempt_count;\n\n    update public.subscriptions\n    set\n      status = ''past_due'',\n      grace_until = coalesce(grace_until, p_processed_at + interval ''2 days''),\n      updated_at = p_processed_at,\n      last_billing_event_id = v_event_id\n    where id = v_sub.id;\n\n    return query select false, ''insufficient_cash''::text, ''CASH_INSUFFICIENT''::text, v_event_id, null::uuid, v_event.period_start, v_event.period_end, null::bigint, coalesce(v_attempt_count, 1);\n    return;\n  end if;\n\n  insert into public.cash_ledger (\n    user_id,\n    delta_cents,\n    reason,\n    ref_type,\n    ref_id,\n    idempotency_key,\n    created_at\n  )\n  values (\n    v_sub.student_id,\n    -p_amount_cents,\n    ''subscription_renewal'',\n    ''subscriptions'',\n    v_sub.id,\n    p_idempotency_key,\n    p_processed_at\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_ledger_id;\n\n  if v_ledger_id is null then\n    select id\n      into v_ledger_id\n    from public.cash_ledger\n    where idempotency_key = p_idempotency_key;\n  end if;\n\n  v_period_start := coalesce(v_event.period_start, v_sub.current_period_end, p_period_end, p_processed_at);\n  v_period_end := coalesce(v_event.period_end, v_period_start + interval ''1 month'');\n\n  update public.subscription_billing_events as e\n  set\n    event_type = ''renewal'',\n    status = ''succeeded'',\n    ledger_id = v_ledger_id,\n    processed_at = p_processed_at,\n    failure_code = null,\n    failure_message = null,\n    period_start = v_period_start,\n    period_end = v_period_end,\n    amount_cents = p_amount_cents::int\n  where e.id = v_event_id\n  returning e.attempt_count into v_attempt_count;\n\n  update public.subscriptions\n  set\n    status = ''active'',\n    current_period_start = v_period_start,\n    current_period_end = v_period_end,\n    next_billing_at = v_period_end,\n    last_renewed_at = p_processed_at,\n    last_billing_event_id = v_event_id,\n    grace_until = null,\n    updated_at = p_processed_at\n  where id = v_sub.id;\n\n  return query select true, ''succeeded''::text, ''renewal processed''::text, v_event_id, v_ledger_id, v_period_start, v_period_end, v_wallet_balance, coalesce(v_attempt_count, 1);\nend;\n$function$", "revoke all on function public.process_subscription_renewal(uuid, timestamptz, bigint, text, timestamptz) from public", "grant execute on function public.process_subscription_renewal(uuid, timestamptz, bigint, text, timestamptz) to service_role", "-- >>> NATIVE_BASELINE_PART 0077 | supabase/bundles/bundle_3_recent_062_069.sql | 069_subscription_cancel_refund_request.sql <<<\n-- ===== 069_subscription_cancel_refund_request.sql =====\n\n-- 069_subscription_cancel_refund_request.sql\n-- P4: subscription cancel-at-period-end + prorated refund request metadata.\n--\n-- Execution order:\n--   1) Run this whole file in Supabase SQL Editor.\n--   2) Run the verification SELECTs below.\n--   3) If unexpected duplicate pending subscription refunds appear, resolve them manually.\n--\n-- VERIFY 1: pending subscription refund rows after metadata exists\n-- select subscription_id, count(*)\n-- from public.refunds\n-- where subscription_id is not null and status = ''pending''\n-- group by subscription_id\n-- having count(*) > 1;\n--\n-- VERIFY 2: subscription refunds that would sync status when approved\n-- select r.id, r.subscription_id, r.payment_id, r.status, r.amount_cents\n-- from public.refunds r\n-- where coalesce(r.request_type, '''') = ''subscription_prorated''\n-- order by r.created_at desc\n-- limit 20;\n\nbegin", "alter table public.refunds\n  add column if not exists subscription_id uuid references public.subscriptions(id) on delete set null,\n  add column if not exists request_type text,\n  add column if not exists reason text", "create index if not exists idx_refunds_subscription_status\n  on public.refunds (subscription_id, status, created_at desc)\n  where subscription_id is not null", "create index if not exists idx_refunds_subscription_prorated_pending\n  on public.refunds (subscription_id, created_at desc)\n  where subscription_id is not null\n    and status = ''pending''\n    and request_type = ''subscription_prorated''", "create or replace function public.sync_subscription_refunded_from_refund()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\nbegin\n  if new.status = ''succeeded''\n     and coalesce(new.request_type, '''') = ''subscription_prorated''\n     and new.subscription_id is not null then\n    update public.subscriptions s\n    set\n      status = ''refunded'',\n      cancel_at_period_end = false,\n      canceled_at = coalesce(s.canceled_at, now()),\n      expired_at = coalesce(s.expired_at, now()),\n      next_billing_at = null,\n      updated_at = now()\n    where s.id = new.subscription_id;\n  end if;\n  return new;\nend;\n$function$", "drop trigger if exists trg_refunds_sync_subscription_refunded on public.refunds", "create trigger trg_refunds_sync_subscription_refunded\n  after update of status on public.refunds\n  for each row\n  when (new.status = ''succeeded'')\n  execute function public.sync_subscription_refunded_from_refund()", "create or replace function public.keep_subscription_refunded_status()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\nbegin\n  if new.status = ''canceled''\n     and exists (\n       select 1\n       from public.refunds r\n       where r.status = ''succeeded''\n         and coalesce(r.request_type, '''') = ''subscription_prorated''\n         and (\n           r.subscription_id = new.id\n           or (\n             r.subscription_id is null\n             and r.payment_id is not null\n             and r.payment_id = new.payment_id\n           )\n         )\n     ) then\n    new.status := ''refunded'';\n    new.cancel_at_period_end := false;\n    new.canceled_at := coalesce(new.canceled_at, now());\n    new.expired_at := coalesce(new.expired_at, now());\n    new.next_billing_at := null;\n  end if;\n  return new;\nend;\n$function$", "drop trigger if exists trg_subscriptions_keep_refunded_status on public.subscriptions", "create trigger trg_subscriptions_keep_refunded_status\n  before update of status on public.subscriptions\n  for each row\n  execute function public.keep_subscription_refunded_status()", "comment on column public.refunds.subscription_id is\n  ''P4 subscription refund request target. Student requests are inserted by server action; admin approval remains existing refund RPC.''", "comment on column public.refunds.request_type is\n  ''Use subscription_prorated for student-requested remaining-period subscription refunds.''", "comment on function public.sync_subscription_refunded_from_refund() is\n  ''P4: When a subscription_prorated refund is approved, mark the target subscription refunded.''", "comment on function public.keep_subscription_refunded_status() is\n  ''P4: Preserve refunded subscription status when legacy refund RPC updates by payment_id to canceled.''", "commit", "-- >>> NATIVE_BASELINE_PART 0078 | supabase/baseline/supplements/001_dashboard_era_community_policies.sql | 001_dashboard_era_community_policies.sql <<<\n-- 001_dashboard_era_community_policies.sql — 대시보드 UI 로 생성됐던 out-of-band 정책 복원.\n--\n-- 근거: 원장 20260731170632(community_direct_write_lockdown) 사전 게이트가\n-- community_posts 쓰기 정책 6종( cp_write_self / cp_update_own / cp_update_self /\n-- cp_delete_own + 한글명 2종 )의 존재를 name+cmd+roles 로 단언한 뒤 6종 전부 DROP 한다.\n-- 한글명 2종은 어떤 저장소 SQL 에도 CREATE 가 없다 — 초기 대시보드 정책 편집기 산물.\n--\n-- ⚠️ 원문 qual/with_check 는 부모에서 이미 DROP 되어 복구 불가(UNRECOVERABLE).\n-- 게이트는 name+cmd+roles 만 검사하고 이 정책들은 최종 상태에 남지 않으므로,\n-- 아래 본문은 당시 통용되던 self-write 형태로 재구성했다(최종 스키마 영향 0).\ndo $$ begin\n  if not exists (select 1 from pg_policies where schemaname=''public''\n                 and tablename=''community_posts'' and policyname=''로그인 유저 게시글 작성'') then\n    execute ''create policy \"로그인 유저 게시글 작성\" on public.community_posts''\n         || '' for insert to public with check (auth.uid() is not null and author_id = auth.uid())'';\n  end if;\n  if not exists (select 1 from pg_policies where schemaname=''public''\n                 and tablename=''community_posts'' and policyname=''본인 게시글 수정'') then\n    execute ''create policy \"본인 게시글 수정\" on public.community_posts''\n         || '' for update to public using (author_id = auth.uid()) with check (author_id = auth.uid())'';\n  end if;\nend $$", "-- >>> NATIVE_BASELINE_PART 0079 | supabase/baseline/supplements/002_out_of_band_schema_remnants.sql | 002_out_of_band_schema_remnants.sql <<<\n-- 002_out_of_band_schema_remnants.sql — 저장소 SQL 에 없는 부모 실측 객체 복원\n-- (002_app_core_schema_draft 일부 수동 적용 흔적 + 대시보드 생성 제약).\n-- 모든 정의는 부모 인벤토리(정보 스키마·pg_get_constraintdef) 원문 기반.\nalter table public.custom_order_deliverables add column if not exists mentor_id uuid", "alter table public.custom_order_messages add column if not exists content text", "alter table public.custom_order_messages add column if not exists file_url text", "alter table public.custom_order_messages add column if not exists sender_id uuid", "alter table public.custom_request_applications add column if not exists proposal text", "alter table public.question_threads add column if not exists view_count integer default 0", "do $$ begin\n  if not exists (select 1 from pg_constraint c join pg_class cl on cl.oid=c.conrelid\n                 join pg_namespace n on n.oid=cl.relnamespace\n                 where n.nspname=''public'' and cl.relname=''custom_order_deliverables'' and c.conname=''custom_order_deliverables_mentor_id_fkey'') then\n    alter table public.custom_order_deliverables add constraint custom_order_deliverables_mentor_id_fkey FOREIGN KEY (mentor_id) REFERENCES auth.users(id);\n  end if;\nend $$", "do $$ begin\n  if not exists (select 1 from pg_constraint c join pg_class cl on cl.oid=c.conrelid\n                 join pg_namespace n on n.oid=cl.relnamespace\n                 where n.nspname=''public'' and cl.relname=''custom_order_messages'' and c.conname=''custom_order_messages_sender_id_fkey'') then\n    alter table public.custom_order_messages add constraint custom_order_messages_sender_id_fkey FOREIGN KEY (sender_id) REFERENCES auth.users(id);\n  end if;\nend $$", "do $$ begin\n  if not exists (select 1 from pg_constraint c join pg_class cl on cl.oid=c.conrelid\n                 join pg_namespace n on n.oid=cl.relnamespace\n                 where n.nspname=''public'' and cl.relname=''favorites'' and c.conname=''favorites_user_id_mentor_id_key'') then\n    alter table public.favorites add constraint favorites_user_id_mentor_id_key UNIQUE (user_id, mentor_id);\n  end if;\nend $$", "-- 로컬 잉여(부모 부재) 정리 — as-applied 발산분\nalter table public.favorites drop constraint if exists favorites_user_mentor_unique", "alter table public.comments drop constraint if exists comments_content_len_chk", "alter table public.comments drop column if exists updated_at", "alter table public.community_hashtags drop column if exists updated_at", "-- >>> NATIVE_BASELINE_PART 0080 | supabase/baseline/supplements/003_out_of_band_policies.sql | 003_out_of_band_policies.sql <<<\n-- 003_out_of_band_policies.sql — 대시보드 생성 정책 9종 (부모 pg_policies 원문 그대로)\ndo $$ begin\n  if not exists (select 1 from pg_policies where schemaname=''public'' and tablename=''admin_action_logs'' and policyname=''관리자만 로그 기록'') then\n    execute $pol$create policy \"관리자만 로그 기록\" on public.admin_action_logs for insert to public\n  with check ((auth.uid() = admin_id))$pol$;\n  end if;\nend $$", "do $$ begin\n  if not exists (select 1 from pg_policies where schemaname=''public'' and tablename=''admin_action_logs'' and policyname=''관리자만 로그 조회'') then\n    execute $pol$create policy \"관리자만 로그 조회\" on public.admin_action_logs for select to public\n  using ((EXISTS ( SELECT 1\n   FROM users\n  WHERE ((users.id = auth.uid()) AND (users.role = ''admin''::text)))))$pol$;\n  end if;\nend $$", "do $$ begin\n  if not exists (select 1 from pg_policies where schemaname=''public'' and tablename=''community_posts'' and policyname=''누구나 게시글 읽기'') then\n    execute $pol$create policy \"누구나 게시글 읽기\" on public.community_posts for select to public\n  using ((status = ''published''::text))$pol$;\n  end if;\nend $$", "do $$ begin\n  if not exists (select 1 from pg_policies where schemaname=''public'' and tablename=''custom_order_deliverables'' and policyname=''멘토만 납품 업로드'') then\n    execute $pol$create policy \"멘토만 납품 업로드\" on public.custom_order_deliverables for insert to public\n  with check ((auth.uid() = mentor_id))$pol$;\n  end if;\nend $$", "do $$ begin\n  if not exists (select 1 from pg_policies where schemaname=''public'' and tablename=''custom_order_messages'' and policyname=''당사자만 메시지 전송'') then\n    execute $pol$create policy \"당사자만 메시지 전송\" on public.custom_order_messages for insert to public\n  with check ((auth.uid() = author_id))$pol$;\n  end if;\nend $$", "do $$ begin\n  if not exists (select 1 from pg_policies where schemaname=''public'' and tablename=''custom_request_applications'' and policyname=''멘토만 지원'') then\n    execute $pol$create policy \"멘토만 지원\" on public.custom_request_applications for insert to public\n  with check ((auth.uid() = mentor_id))$pol$;\n  end if;\nend $$", "do $$ begin\n  if not exists (select 1 from pg_policies where schemaname=''public'' and tablename=''custom_request_orders'' and policyname=''주문 당사자만 읽기'') then\n    execute $pol$create policy \"주문 당사자만 읽기\" on public.custom_request_orders for select to public\n  using (((auth.uid() = student_id) OR (auth.uid() = mentor_id)))$pol$;\n  end if;\nend $$", "do $$ begin\n  if not exists (select 1 from pg_policies where schemaname=''public'' and tablename=''custom_request_posts'' and policyname=''학생만 의뢰 등록'') then\n    execute $pol$create policy \"학생만 의뢰 등록\" on public.custom_request_posts for insert to public\n  with check ((auth.uid() = author_id))$pol$;\n  end if;\nend $$", "do $$ begin\n  if not exists (select 1 from pg_policies where schemaname=''public'' and tablename=''post_reactions'' and policyname=''본인 반응만 조회'') then\n    execute $pol$create policy \"본인 반응만 조회\" on public.post_reactions for select to public\n  using ((auth.uid() = user_id))$pol$;\n  end if;\nend $$", "-- >>> NATIVE_BASELINE_PART 0081 | supabase/baseline/supplements/004_rls_auto_enable_event_trigger.sql | 004_rls_auto_enable_event_trigger.sql <<<\n-- 004_rls_auto_enable_event_trigger.sql — out-of-band 이벤트 트리거 복원 (부모 실측 원문).\n-- 부모 pg_event_trigger: ensure_rls (ddl_command_end; CREATE TABLE/CREATE TABLE AS/SELECT INTO)\n-- → public 스키마 신규 테이블 RLS 자동 활성화. 저장소 SQL 에 없음(대시보드/수동 적용 산물).\nCREATE OR REPLACE FUNCTION public.rls_auto_enable()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog''\nAS $function$\nDECLARE\n  cmd record;\nBEGIN\n  FOR cmd IN\n    SELECT *\n    FROM pg_event_trigger_ddl_commands()\n    WHERE command_tag IN (''CREATE TABLE'', ''CREATE TABLE AS'', ''SELECT INTO'')\n      AND object_type IN (''table'',''partitioned table'')\n  LOOP\n     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN (''public'') AND cmd.schema_name NOT IN (''pg_catalog'',''information_schema'') AND cmd.schema_name NOT LIKE ''pg_toast%'' AND cmd.schema_name NOT LIKE ''pg_temp%'' THEN\n      BEGIN\n        EXECUTE format(''alter table if exists %s enable row level security'', cmd.object_identity);\n        RAISE LOG ''rls_auto_enable: enabled RLS on %'', cmd.object_identity;\n      EXCEPTION\n        WHEN OTHERS THEN\n          RAISE LOG ''rls_auto_enable: failed to enable RLS on %'', cmd.object_identity;\n      END;\n     ELSE\n        RAISE LOG ''rls_auto_enable: skip % (either system schema or not in enforced list: %.)'', cmd.object_identity, cmd.schema_name;\n     END IF;\n  END LOOP;\nEND;\n$function$", "do $$ begin\n  if not exists (select 1 from pg_event_trigger where evtname = ''ensure_rls'') then\n    create event trigger ensure_rls on ddl_command_end\n      when tag in (''CREATE TABLE'', ''CREATE TABLE AS'', ''SELECT INTO'')\n      execute function public.rls_auto_enable();\n  end if;\nend $$", "-- >>> NATIVE_BASELINE_PART 0082 | supabase/sql/070_individual_question_schema_escrow.sql | 070_individual_question_schema_escrow.sql <<<\n-- =============================================================================\n-- 070_individual_question_schema_escrow.sql\n-- Purpose: Individual one-off questions (cash escrow) Q1 foundation.\n--\n-- Scope:\n--   - New tables for individual questions, messages, attachments, and mentor\n--     direct-question pricing.\n--   - Private storage bucket + RLS for individual-question attachments.\n--   - New escrow RPCs: create/hold, claim, release payout, refund.\n--\n-- Safety:\n--   - Does not modify subscription debit RPC 019.\n--   - Does not modify custom-request escrow RPCs 054~057.\n--   - Does not modify mentor_student_rooms/question_threads/free quota.\n--   - Wallet debits require balance_cents >= price_cents. No negative balance.\n--   - Idempotency layers:\n--       1) individual_questions.create_idempotency_key unique\n--       2) cash_ledger.idempotency_key unique\n--       3) row locks on cash_wallets / individual_questions where needed\n--\n-- Execute after:\n--   004_p0_cash_disputes_admin_draft.sql\n--   060_ai_readiness_question_schema.sql is not required, but expected in the\n--   current app setup.\n--\n-- Manual verification after running:\n--   select * from storage.buckets where id = ''individual-question-attachments'';\n--   select table_name from information_schema.tables\n--     where table_schema = ''public'' and table_name like ''individual_question%'';\n--   select routine_name from information_schema.routines\n--     where routine_schema = ''public'' and routine_name like ''%individual_question%'';\n-- =============================================================================\n\ncreate extension if not exists pgcrypto", "-- ---------------------------------------------------------------------------\n-- Tables\n-- ---------------------------------------------------------------------------\n\ncreate table if not exists public.individual_questions (\n  id uuid primary key default gen_random_uuid(),\n  student_id uuid not null references public.users(id) on delete cascade,\n  question_type text not null check (question_type in (''direct'', ''open'')),\n  designated_mentor_id uuid references public.users(id) on delete set null,\n  claimed_mentor_id uuid references public.users(id) on delete set null,\n  claimed_at timestamptz,\n  subject text,\n  topic text,\n  title text not null,\n  body text not null,\n  price_cents int not null check (price_cents > 0),\n  status text not null default ''escrowed'' check (\n    status in (\n      ''escrowed'',\n      ''assigned'',\n      ''open'',\n      ''claimed'',\n      ''answered'',\n      ''released'',\n      ''expired'',\n      ''refunded'',\n      ''canceled''\n    )\n  ),\n  expires_at timestamptz,\n  answered_at timestamptz,\n  released_at timestamptz,\n  refunded_at timestamptz,\n  hold_ledger_id uuid references public.cash_ledger(id) on delete set null,\n  release_ledger_id uuid references public.cash_ledger(id) on delete set null,\n  refund_ledger_id uuid references public.cash_ledger(id) on delete set null,\n  create_idempotency_key text not null unique,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint individual_questions_direct_mentor_required check (\n    question_type <> ''direct'' or designated_mentor_id is not null\n  ),\n  constraint individual_questions_open_claim_consistency check (\n    question_type <> ''open'' or designated_mentor_id is null\n  )\n)", "drop trigger if exists trg_individual_questions_set_updated on public.individual_questions", "create trigger trg_individual_questions_set_updated\n  before update on public.individual_questions\n  for each row\n  execute function public.set_updated_at()", "create index if not exists idx_iq_status_expires\n  on public.individual_questions (status, expires_at)", "create index if not exists idx_iq_open_list\n  on public.individual_questions (question_type, status, created_at desc)\n  where status = ''open''", "create index if not exists idx_iq_designated_mentor_status\n  on public.individual_questions (designated_mentor_id, status, created_at desc)", "create index if not exists idx_iq_claimed_mentor_status\n  on public.individual_questions (claimed_mentor_id, status, created_at desc)", "create index if not exists idx_iq_student_created\n  on public.individual_questions (student_id, created_at desc)", "create table if not exists public.individual_question_messages (\n  id uuid primary key default gen_random_uuid(),\n  question_id uuid not null references public.individual_questions(id) on delete cascade,\n  author_id uuid not null references public.users(id) on delete cascade,\n  body text not null,\n  created_at timestamptz not null default now(),\n  constraint individual_question_messages_id_question_unique unique (id, question_id)\n)", "create index if not exists idx_iqm_question_created\n  on public.individual_question_messages (question_id, created_at asc)", "create table if not exists public.individual_question_attachments (\n  id uuid primary key default gen_random_uuid(),\n  question_id uuid not null references public.individual_questions(id) on delete cascade,\n  message_id uuid references public.individual_question_messages(id) on delete set null,\n  storage_path text not null,\n  file_name text,\n  mime_type text,\n  created_at timestamptz not null default now()\n)", "create index if not exists idx_iqa_question_created\n  on public.individual_question_attachments (question_id, created_at desc)", "create index if not exists idx_iqa_message\n  on public.individual_question_attachments (message_id)", "create table if not exists public.mentor_individual_question_pricing (\n  mentor_id uuid primary key references public.users(id) on delete cascade,\n  amount_cents int not null check (amount_cents > 0),\n  updated_at timestamptz not null default now()\n)", "drop trigger if exists trg_miqp_set_updated on public.mentor_individual_question_pricing", "create trigger trg_miqp_set_updated\n  before update on public.mentor_individual_question_pricing\n  for each row\n  execute function public.set_updated_at()", "-- ---------------------------------------------------------------------------\n-- Helpers\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.individual_question_user_is_admin(p_user_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $function$\n  select coalesce((\n    select u.role = ''admin''\n    from public.users u\n    where u.id = p_user_id\n  ), false);\n$function$", "create or replace function public.individual_question_user_is_approved_mentor(p_user_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $function$\n  select exists (\n    select 1\n    from public.mentor_profiles mp\n    where mp.user_id = p_user_id\n      and lower(coalesce(mp.verification_status, '''')) in (''approved'', ''verified'', ''active'')\n  );\n$function$", "create or replace function public.user_is_individual_question_party(p_question_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $function$\n  select exists (\n    select 1\n    from public.individual_questions q\n    where q.id = p_question_id\n      and (\n        q.student_id = (select auth.uid())\n        or q.designated_mentor_id = (select auth.uid())\n        or q.claimed_mentor_id = (select auth.uid())\n        or public.individual_question_user_is_admin((select auth.uid()))\n      )\n  );\n$function$", "-- Approved mentors can browse only sanitized open-question fields.\n-- Do not expose student_id, body, ledger IDs, or attachment paths here.\ncreate or replace function public.list_open_individual_questions_for_mentor(p_limit integer default 50)\nreturns table (\n  id uuid,\n  subject text,\n  topic text,\n  title text,\n  price_cents int,\n  expires_at timestamptz,\n  created_at timestamptz\n)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);\nbegin\n  if not public.individual_question_user_is_approved_mentor((select auth.uid())) then\n    return;\n  end if;\n\n  return query\n    select\n      q.id,\n      q.subject,\n      q.topic,\n      q.title,\n      q.price_cents,\n      q.expires_at,\n      q.created_at\n    from public.individual_questions q\n    where q.question_type = ''open''\n      and q.status = ''open''\n      and q.claimed_mentor_id is null\n      and (q.expires_at is null or q.expires_at > now())\n    order by q.created_at desc\n    limit v_limit;\nend;\n$function$", "-- ---------------------------------------------------------------------------\n-- RLS\n-- ---------------------------------------------------------------------------\n\nalter table public.individual_questions enable row level security", "alter table public.individual_question_messages enable row level security", "alter table public.individual_question_attachments enable row level security", "alter table public.mentor_individual_question_pricing enable row level security", "drop policy if exists \"iq_select_party\" on public.individual_questions", "create policy \"iq_select_party\"\n  on public.individual_questions\n  for select\n  to authenticated\n  using (public.user_is_individual_question_party(id))", "drop policy if exists \"iqm_select_party\" on public.individual_question_messages", "create policy \"iqm_select_party\"\n  on public.individual_question_messages\n  for select\n  to authenticated\n  using (public.user_is_individual_question_party(question_id))", "drop policy if exists \"iqa_select_party\" on public.individual_question_attachments", "create policy \"iqa_select_party\"\n  on public.individual_question_attachments\n  for select\n  to authenticated\n  using (public.user_is_individual_question_party(question_id))", "drop policy if exists \"miqp_select_authenticated\" on public.mentor_individual_question_pricing", "create policy \"miqp_select_authenticated\"\n  on public.mentor_individual_question_pricing\n  for select\n  to authenticated\n  using (true)", "-- No authenticated insert/update/delete policies on individual question tables.\n-- Mutations must go through service-role server actions / SECURITY DEFINER RPCs.\n\n-- ---------------------------------------------------------------------------\n-- Storage bucket + RLS\n-- Path rule: <individual_question_id>/<uuid>-<filename>\n-- ---------------------------------------------------------------------------\n\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues (\n  ''individual-question-attachments'',\n  ''individual-question-attachments'',\n  false,\n  20971520,\n  array[\n    ''image/png'',\n    ''image/jpeg'',\n    ''image/webp'',\n    ''image/gif'',\n    ''application/pdf'',\n    ''application/zip'',\n    ''application/vnd.openxmlformats-officedocument.wordprocessingml.document'',\n    ''application/vnd.openxmlformats-officedocument.presentationml.presentation''\n  ]::text[]\n)\non conflict (id) do update set\n  public = excluded.public,\n  file_size_limit = coalesce(excluded.file_size_limit, storage.buckets.file_size_limit),\n  allowed_mime_types = coalesce(excluded.allowed_mime_types, storage.buckets.allowed_mime_types)", "create or replace function public.individual_question_uuid_from_storage_path(p_name text)\nreturns uuid\nlanguage plpgsql\nimmutable\nsecurity definer\nset search_path = public\nas $function$\nbegin\n  return nullif(split_part(p_name, ''/'', 1), '''')::uuid;\nexception\n  when others then\n    return null;\nend;\n$function$", "create or replace function public.user_is_party_for_individual_question_storage_path(p_name text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $function$\n  select public.user_is_individual_question_party(\n    public.individual_question_uuid_from_storage_path(p_name)\n  );\n$function$", "drop policy if exists \"iqa_storage_read_party\" on storage.objects", "create policy \"iqa_storage_read_party\"\n  on storage.objects\n  for select\n  to authenticated\n  using (\n    bucket_id = ''individual-question-attachments''\n    and public.user_is_party_for_individual_question_storage_path(name)\n  )", "drop policy if exists \"iqa_storage_insert_party\" on storage.objects", "create policy \"iqa_storage_insert_party\"\n  on storage.objects\n  for insert\n  to authenticated\n  with check (\n    bucket_id = ''individual-question-attachments''\n    and public.user_is_party_for_individual_question_storage_path(name)\n  )", "-- ---------------------------------------------------------------------------\n-- RPC return contract\n-- ---------------------------------------------------------------------------\n\ndo $$\nbegin\n  if not exists (\n    select 1\n    from pg_type t\n    join pg_namespace n on n.oid = t.typnamespace\n    where n.nspname = ''public''\n      and t.typname = ''individual_question_escrow_result''\n  ) then\n    execute ''\n      create type public.individual_question_escrow_result as (\n        ok boolean,\n        code text,\n        message text,\n        question_id uuid,\n        status text,\n        ledger_id uuid,\n        wallet_balance_cents bigint\n      )\n    '';\n  end if;\nend $$", "-- ---------------------------------------------------------------------------\n-- RPC: create + escrow hold\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.create_individual_question_with_hold(\n  p_student_id uuid,\n  p_question_type text,\n  p_mentor_id uuid,\n  p_subject text,\n  p_topic text,\n  p_title text,\n  p_body text,\n  p_price_cents int,\n  p_idempotency_key text\n)\nreturns public.individual_question_escrow_result\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_type text := lower(trim(coalesce(p_question_type, '''')));\n  v_status text;\n  v_idem text := trim(coalesce(p_idempotency_key, ''''));\n  v_question public.individual_questions%rowtype;\n  v_ledger_id uuid;\n  v_wallet_balance bigint;\n  v_wallet_rows int;\nbegin\n  if p_student_id is null then\n    return (false, ''invalid_student'', ''student_id is required'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if not exists (select 1 from public.users u where u.id = p_student_id and u.role = ''student'') then\n    return (false, ''invalid_student'', ''student must be a student user'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_type not in (''direct'', ''open'') then\n    return (false, ''invalid_type'', ''question_type must be direct or open'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_type = ''direct'' and p_mentor_id is null then\n    return (false, ''mentor_required'', ''direct question requires mentor_id'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_type = ''direct'' and not public.individual_question_user_is_approved_mentor(p_mentor_id) then\n    return (false, ''mentor_not_approved'', ''mentor is not approved for individual questions'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if p_price_cents is null or p_price_cents <= 0 then\n    return (false, ''invalid_price'', ''price_cents must be positive'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if p_price_cents > 1000000000 then\n    return (false, ''price_too_large'', ''price_cents is too large'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if length(v_idem) = 0 then\n    return (false, ''invalid_idempotency_key'', ''idempotency_key is required'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if length(trim(coalesce(p_title, ''''))) = 0 or length(trim(coalesce(p_body, ''''))) = 0 then\n    return (false, ''invalid_content'', ''title and body are required'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  select *\n    into v_question\n  from public.individual_questions\n  where create_idempotency_key = v_idem;\n\n  if found then\n    select balance_cents\n      into v_wallet_balance\n    from public.cash_wallets\n    where user_id = p_student_id;\n\n    return (\n      true,\n      ''already_exists'',\n      ''individual question already created for idempotency key'',\n      v_question.id,\n      v_question.status,\n      v_question.hold_ledger_id,\n      v_wallet_balance\n    )::public.individual_question_escrow_result;\n  end if;\n\n  insert into public.cash_wallets (user_id, balance_cents)\n  values (p_student_id, 0)\n  on conflict (user_id) do nothing;\n\n  select balance_cents\n    into v_wallet_balance\n  from public.cash_wallets\n  where user_id = p_student_id\n  for update;\n\n  -- Re-check idempotency after wallet lock to avoid double debit on concurrent calls.\n  select *\n    into v_question\n  from public.individual_questions\n  where create_idempotency_key = v_idem;\n\n  if found then\n    return (\n      true,\n      ''already_exists'',\n      ''individual question already created for idempotency key'',\n      v_question.id,\n      v_question.status,\n      v_question.hold_ledger_id,\n      v_wallet_balance\n    )::public.individual_question_escrow_result;\n  end if;\n\n  if coalesce(v_wallet_balance, 0) < p_price_cents then\n    return (\n      false,\n      ''insufficient_cash'',\n      ''CASH_INSUFFICIENT'',\n      null,\n      null,\n      null,\n      coalesce(v_wallet_balance, 0)\n    )::public.individual_question_escrow_result;\n  end if;\n\n  v_status := case when v_type = ''direct'' then ''assigned'' else ''open'' end;\n\n  insert into public.individual_questions (\n    student_id,\n    question_type,\n    designated_mentor_id,\n    subject,\n    topic,\n    title,\n    body,\n    price_cents,\n    status,\n    create_idempotency_key\n  )\n  values (\n    p_student_id,\n    v_type,\n    case when v_type = ''direct'' then p_mentor_id else null end,\n    nullif(trim(coalesce(p_subject, '''')), ''''),\n    nullif(trim(coalesce(p_topic, '''')), ''''),\n    trim(p_title),\n    trim(p_body),\n    p_price_cents,\n    v_status,\n    v_idem\n  )\n  returning * into v_question;\n\n  insert into public.cash_ledger (\n    user_id,\n    delta_cents,\n    reason,\n    ref_type,\n    ref_id,\n    idempotency_key\n  )\n  values (\n    p_student_id,\n    -p_price_cents,\n    ''individual_question_escrow_hold'',\n    ''individual_questions'',\n    v_question.id,\n    ''iq_hold:'' || v_question.id::text\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_ledger_id;\n\n  if v_ledger_id is null then\n    raise exception ''INDIVIDUAL_QUESTION_HOLD_LEDGER_CONFLICT'';\n  end if;\n\n  update public.cash_wallets\n  set balance_cents = balance_cents - p_price_cents\n  where user_id = p_student_id\n    and balance_cents >= p_price_cents\n  returning balance_cents into v_wallet_balance;\n\n  get diagnostics v_wallet_rows = row_count;\n  if coalesce(v_wallet_rows, 0) = 0 then\n    raise exception ''CASH_INSUFFICIENT_AFTER_LOCK'' using errcode = ''P0001'';\n  end if;\n\n  update public.individual_questions\n  set hold_ledger_id = v_ledger_id\n  where id = v_question.id\n  returning * into v_question;\n\n  return (\n    true,\n    ''created'',\n    ''individual question created and cash held'',\n    v_question.id,\n    v_question.status,\n    v_ledger_id,\n    v_wallet_balance\n  )::public.individual_question_escrow_result;\nend;\n$function$", "-- ---------------------------------------------------------------------------\n-- RPC: open question first-claim\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.claim_individual_question(\n  p_question_id uuid,\n  p_mentor_id uuid\n)\nreturns public.individual_question_escrow_result\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_question public.individual_questions%rowtype;\nbegin\n  if p_question_id is null or p_mentor_id is null then\n    return (false, ''invalid_input'', ''question_id and mentor_id are required'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if not public.individual_question_user_is_approved_mentor(p_mentor_id) then\n    return (false, ''mentor_not_approved'', ''mentor is not approved for individual questions'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  update public.individual_questions\n  set\n    claimed_mentor_id = p_mentor_id,\n    claimed_at = now(),\n    status = ''claimed''\n  where id = p_question_id\n    and question_type = ''open''\n    and status = ''open''\n    and claimed_mentor_id is null\n    and (expires_at is null or expires_at > now())\n    and student_id <> p_mentor_id\n  returning * into v_question;\n\n  if not found then\n    return (false, ''not_available'', ''question is already claimed, expired, or unavailable'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  return (true, ''claimed'', ''individual question claimed'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\nend;\n$function$", "-- ---------------------------------------------------------------------------\n-- RPC: answer accepted -> mentor payout\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.release_individual_question_payout(\n  p_question_id uuid\n)\nreturns public.individual_question_escrow_result\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_question public.individual_questions%rowtype;\n  v_mentor_id uuid;\n  v_ledger_id uuid;\n  v_wallet_balance bigint;\n  v_new_ledger boolean := false;\nbegin\n  if p_question_id is null then\n    return (false, ''invalid_question'', ''question_id is required'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  select *\n    into v_question\n  from public.individual_questions\n  where id = p_question_id\n  for update;\n\n  if not found then\n    return (false, ''not_found'', ''individual question not found'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_question.release_ledger_id is not null or v_question.status = ''released'' then\n    return (true, ''already_released'', ''individual question already released'', v_question.id, v_question.status, v_question.release_ledger_id, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_question.refund_ledger_id is not null or v_question.status = ''refunded'' then\n    return (false, ''already_refunded'', ''individual question already refunded'', v_question.id, v_question.status, v_question.refund_ledger_id, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_question.status <> ''answered'' then\n    return (false, ''not_answered'', ''question must be answered before payout'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_question.hold_ledger_id is null then\n    return (false, ''hold_missing'', ''escrow hold ledger is missing'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  v_mentor_id := coalesce(v_question.claimed_mentor_id, v_question.designated_mentor_id);\n  if v_mentor_id is null then\n    return (false, ''mentor_missing'', ''mentor is missing'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if exists (\n    select 1\n    from public.cash_ledger l\n    where l.idempotency_key = ''iq_refund:'' || v_question.id::text\n      and l.reason = ''individual_question_refund''\n  ) then\n    return (false, ''already_refunded'', ''refund ledger already exists'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  insert into public.cash_ledger (\n    user_id,\n    delta_cents,\n    reason,\n    ref_type,\n    ref_id,\n    idempotency_key\n  )\n  values (\n    v_mentor_id,\n    v_question.price_cents,\n    ''individual_question_payout'',\n    ''individual_questions'',\n    v_question.id,\n    ''iq_payout:'' || v_question.id::text\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_ledger_id;\n\n  if v_ledger_id is not null then\n    v_new_ledger := true;\n  else\n    select id\n      into v_ledger_id\n    from public.cash_ledger\n    where idempotency_key = ''iq_payout:'' || v_question.id::text\n      and reason = ''individual_question_payout'';\n  end if;\n\n  if v_ledger_id is null then\n    raise exception ''INDIVIDUAL_QUESTION_PAYOUT_LEDGER_MISSING'';\n  end if;\n\n  if v_new_ledger then\n    insert into public.cash_wallets (user_id, balance_cents)\n    values (v_mentor_id, 0)\n    on conflict (user_id) do nothing;\n\n    update public.cash_wallets\n    set balance_cents = balance_cents + v_question.price_cents\n    where user_id = v_mentor_id\n    returning balance_cents into v_wallet_balance;\n\n    if not found then\n      raise exception ''INDIVIDUAL_QUESTION_MENTOR_WALLET_CREDIT_FAILED'';\n    end if;\n  end if;\n\n  update public.individual_questions\n  set\n    status = ''released'',\n    released_at = coalesce(released_at, now()),\n    release_ledger_id = v_ledger_id\n  where id = v_question.id\n  returning * into v_question;\n\n  return (true, ''released'', ''individual question payout released'', v_question.id, v_question.status, v_ledger_id, v_wallet_balance)::public.individual_question_escrow_result;\nend;\n$function$", "-- ---------------------------------------------------------------------------\n-- RPC: escrow refund\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.refund_individual_question_hold(\n  p_question_id uuid\n)\nreturns public.individual_question_escrow_result\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_question public.individual_questions%rowtype;\n  v_ledger_id uuid;\n  v_wallet_balance bigint;\n  v_new_ledger boolean := false;\nbegin\n  if p_question_id is null then\n    return (false, ''invalid_question'', ''question_id is required'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  select *\n    into v_question\n  from public.individual_questions\n  where id = p_question_id\n  for update;\n\n  if not found then\n    return (false, ''not_found'', ''individual question not found'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_question.refund_ledger_id is not null or v_question.status = ''refunded'' then\n    return (true, ''already_refunded'', ''individual question already refunded'', v_question.id, v_question.status, v_question.refund_ledger_id, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_question.release_ledger_id is not null or v_question.status = ''released'' then\n    return (false, ''already_released'', ''individual question already released'', v_question.id, v_question.status, v_question.release_ledger_id, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_question.hold_ledger_id is null then\n    return (false, ''hold_missing'', ''escrow hold ledger is missing'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if exists (\n    select 1\n    from public.cash_ledger l\n    where l.idempotency_key = ''iq_payout:'' || v_question.id::text\n      and l.reason = ''individual_question_payout''\n  ) then\n    return (false, ''already_released'', ''payout ledger already exists'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  insert into public.cash_ledger (\n    user_id,\n    delta_cents,\n    reason,\n    ref_type,\n    ref_id,\n    idempotency_key\n  )\n  values (\n    v_question.student_id,\n    v_question.price_cents,\n    ''individual_question_refund'',\n    ''individual_questions'',\n    v_question.id,\n    ''iq_refund:'' || v_question.id::text\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_ledger_id;\n\n  if v_ledger_id is not null then\n    v_new_ledger := true;\n  else\n    select id\n      into v_ledger_id\n    from public.cash_ledger\n    where idempotency_key = ''iq_refund:'' || v_question.id::text\n      and reason = ''individual_question_refund'';\n  end if;\n\n  if v_ledger_id is null then\n    raise exception ''INDIVIDUAL_QUESTION_REFUND_LEDGER_MISSING'';\n  end if;\n\n  if v_new_ledger then\n    insert into public.cash_wallets (user_id, balance_cents)\n    values (v_question.student_id, 0)\n    on conflict (user_id) do nothing;\n\n    update public.cash_wallets\n    set balance_cents = balance_cents + v_question.price_cents\n    where user_id = v_question.student_id\n    returning balance_cents into v_wallet_balance;\n\n    if not found then\n      raise exception ''INDIVIDUAL_QUESTION_STUDENT_WALLET_REFUND_FAILED'';\n    end if;\n  end if;\n\n  update public.individual_questions\n  set\n    status = ''refunded'',\n    refunded_at = coalesce(refunded_at, now()),\n    refund_ledger_id = v_ledger_id\n  where id = v_question.id\n  returning * into v_question;\n\n  return (true, ''refunded'', ''individual question escrow refunded'', v_question.id, v_question.status, v_ledger_id, v_wallet_balance)::public.individual_question_escrow_result;\nend;\n$function$", "-- ---------------------------------------------------------------------------\n-- Grants\n-- ---------------------------------------------------------------------------\n\nrevoke all on function public.individual_question_user_is_admin(uuid) from public, anon", "grant execute on function public.individual_question_user_is_admin(uuid) to authenticated, service_role", "revoke all on function public.individual_question_user_is_approved_mentor(uuid) from public, anon", "grant execute on function public.individual_question_user_is_approved_mentor(uuid) to authenticated, service_role", "revoke all on function public.user_is_individual_question_party(uuid) from public, anon", "grant execute on function public.user_is_individual_question_party(uuid) to authenticated, service_role", "revoke all on function public.list_open_individual_questions_for_mentor(integer) from public, anon", "grant execute on function public.list_open_individual_questions_for_mentor(integer) to authenticated", "revoke all on function public.create_individual_question_with_hold(uuid, text, uuid, text, text, text, text, int, text) from public, anon, authenticated", "grant execute on function public.create_individual_question_with_hold(uuid, text, uuid, text, text, text, text, int, text) to service_role", "revoke all on function public.claim_individual_question(uuid, uuid) from public, anon, authenticated", "grant execute on function public.claim_individual_question(uuid, uuid) to service_role", "revoke all on function public.release_individual_question_payout(uuid) from public, anon, authenticated", "grant execute on function public.release_individual_question_payout(uuid) to service_role", "revoke all on function public.refund_individual_question_hold(uuid) from public, anon, authenticated", "grant execute on function public.refund_individual_question_hold(uuid) to service_role", "comment on table public.individual_questions is\n  ''Q1 individual one-off questions. Cash is held at creation and released/refunded by dedicated RPCs.''", "comment on table public.mentor_individual_question_pricing is\n  ''Mentor direct-question answer price. Separate from subscription mentor_plans.''", "comment on function public.create_individual_question_with_hold(uuid, text, uuid, text, text, text, text, int, text) is\n  ''Q1 individual question create + escrow hold. service_role only.''", "comment on function public.claim_individual_question(uuid, uuid) is\n  ''Q1 open individual question first-claim. Atomic update where claimed_mentor_id is null. service_role only.''", "comment on function public.release_individual_question_payout(uuid) is\n  ''Q1 individual question payout. Requires status=answered and no refund/payout. service_role only.''", "comment on function public.refund_individual_question_hold(uuid) is\n  ''Q1 individual question escrow refund. Blocks if payout exists. service_role only.''", "-- >>> NATIVE_BASELINE_PART 0083 | supabase/sql/072_harden_linter_warnings.sql | 072_harden_linter_warnings.sql <<<\n-- =============================================================================\n-- 072_harden_linter_warnings.sql\n--\n-- 목적: Supabase 린터 경고 보강 (기존 SQL 미수정, 새 번호로만).\n--   A. 돈/민감 RPC를 service_role 전용으로 명시적 재확인(anon/authenticated 차단).\n--      - 대부분 019~070 에서 이미 닫혀 있음. 단, 아래 둘은 `revoke from public`만 되어\n--        있어 anon/authenticated 명시 revoke가 빠져 있었다 → 본 파일에서 보강:\n--          * process_subscription_renewal (068)\n--          * accept_custom_order_deliverable_atomic (043/055)\n--      - 나머지는 멱등 재확인(이미 닫혀 있어도 무해).\n--   B. search_path 미설정 함수에 `set search_path = public` 고정(동작 불변, 보안 모범).\n--\n-- ⚠️ 안전:\n--   - service_role grant 는 반드시 유지(서버가 호출). 절대 제거 금지.\n--   - RLS·함수 본문·로직 변경 없음. 권한/속성만 조정.\n--   - 선행 마이그레이션(~071) 적용 후 실행. 존재하지 않는 함수가 있으면 그 줄에서\n--     에러가 나니, 해당 함수 미적용 환경이면 그 줄만 주석 처리하고 재실행.\n--\n-- 실행: Supabase SQL Editor (소유자/service_role 권한). DB 실행은 사용자가 직접.\n--   권장 순서: (0) 아래 \"점검 쿼리\" 먼저 실행 → 본 파일 실행 → 재점검.\n-- =============================================================================\n\n\n-- ---------------------------------------------------------------------------\n-- (0) 점검 쿼리 — 먼저 실행해 실제 노출 여부 확인 (읽기 전용)\n--     anon/authenticated 에 can_exec=true 인 돈 RPC가 있으면 진짜 노출 → (A)가 닫음.\n--     전부 false 면 린터 오탐(이미 닫힘) — (A)는 멱등 재확인.\n-- ---------------------------------------------------------------------------\n-- select p.proname, r.rolname,\n--        has_function_privilege(r.rolname, p.oid, ''execute'') as can_exec\n-- from pg_proc p\n-- cross join (select ''anon'' as rolname union all select ''authenticated'') r\n-- where p.pronamespace = ''public''::regnamespace\n--   and p.proname in (\n--     ''record_subscription_cash_debit'',''record_subscription_cash_rollback'',\n--     ''record_cash_topup'',''process_subscription_renewal'',\n--     ''accept_custom_order_deliverable_atomic'',\n--     ''record_custom_order_escrow_hold'',''record_custom_order_escrow_payout'',\n--     ''record_custom_order_escrow_refund'',''record_custom_order_dispute_split'',\n--     ''approve_refund_request_admin'',''reject_refund_request_admin'',\n--     ''create_individual_question_with_hold'',''claim_individual_question'',\n--     ''release_individual_question_payout'',''refund_individual_question_hold''\n--   )\n-- order by 1, 2;\n\n\n-- ---------------------------------------------------------------------------\n-- (A) 돈/민감 RPC — service_role 전용 명시적 재확인 (idempotent)\n--     revoke from public, anon, authenticated  +  grant execute to service_role\n-- ---------------------------------------------------------------------------\n\n-- 구독 캐시 차감/롤백 (019/022/023)\nrevoke all on function public.record_subscription_cash_debit(uuid, uuid, uuid, bigint) from public, anon, authenticated", "grant execute on function public.record_subscription_cash_debit(uuid, uuid, uuid, bigint) to service_role", "revoke all on function public.record_subscription_cash_rollback(uuid, uuid, uuid, bigint) from public, anon, authenticated", "grant execute on function public.record_subscription_cash_rollback(uuid, uuid, uuid, bigint) to service_role", "-- 캐시 충전 (020/024)\nrevoke all on function public.record_cash_topup(uuid, bigint, text) from public, anon, authenticated", "grant execute on function public.record_cash_topup(uuid, bigint, text) to service_role", "-- 구독 갱신 배치 RPC (068) — 기존에 anon/authenticated 명시 revoke 누락분 보강\nrevoke all on function public.process_subscription_renewal(uuid, timestamptz, bigint, text, timestamptz) from public, anon, authenticated", "grant execute on function public.process_subscription_renewal(uuid, timestamptz, bigint, text, timestamptz) to service_role", "-- 맞춤의뢰 정산 수락(원자) (043/055) — 기존에 anon/authenticated 명시 revoke 누락분 보강\nrevoke all on function public.accept_custom_order_deliverable_atomic(uuid, uuid, boolean) from public, anon, authenticated", "grant execute on function public.accept_custom_order_deliverable_atomic(uuid, uuid, boolean) to service_role", "-- 맞춤의뢰 에스크로 hold/payout/refund (054/055/056)\nrevoke all on function public.record_custom_order_escrow_hold(uuid, uuid, bigint) from public, anon, authenticated", "grant execute on function public.record_custom_order_escrow_hold(uuid, uuid, bigint) to service_role", "revoke all on function public.record_custom_order_escrow_payout(uuid) from public, anon, authenticated", "grant execute on function public.record_custom_order_escrow_payout(uuid) to service_role", "revoke all on function public.record_custom_order_escrow_refund(uuid) from public, anon, authenticated", "grant execute on function public.record_custom_order_escrow_refund(uuid) to service_role", "-- 맞춤의뢰 분쟁 분할 (057)\nrevoke all on function public.record_custom_order_dispute_split(uuid, integer, integer, uuid) from public, anon, authenticated", "grant execute on function public.record_custom_order_dispute_split(uuid, integer, integer, uuid) to service_role", "-- 환불 승인/거절 관리자 RPC (030)\nrevoke all on function public.approve_refund_request_admin(uuid, uuid, text) from public, anon, authenticated", "grant execute on function public.approve_refund_request_admin(uuid, uuid, text) to service_role", "revoke all on function public.reject_refund_request_admin(uuid, uuid, text) from public, anon, authenticated", "grant execute on function public.reject_refund_request_admin(uuid, uuid, text) to service_role", "-- 개별질문 에스크로 (070)\nrevoke all on function public.create_individual_question_with_hold(uuid, text, uuid, text, text, text, text, int, text) from public, anon, authenticated", "grant execute on function public.create_individual_question_with_hold(uuid, text, uuid, text, text, text, text, int, text) to service_role", "revoke all on function public.claim_individual_question(uuid, uuid) from public, anon, authenticated", "grant execute on function public.claim_individual_question(uuid, uuid) to service_role", "revoke all on function public.release_individual_question_payout(uuid) from public, anon, authenticated", "grant execute on function public.release_individual_question_payout(uuid) to service_role", "revoke all on function public.refund_individual_question_hold(uuid) from public, anon, authenticated", "grant execute on function public.refund_individual_question_hold(uuid) to service_role", "-- ---------------------------------------------------------------------------\n-- (B) search_path 고정 — `set search_path = public` (동작 불변, 함수 본문 미수정)\n--     린터가 지목한, search_path 미설정 함수만. 이미 설정된 함수\n--     (accept_custom_order_deliverable_atomic, record_subscription_cash_debit 등)는 제외.\n-- ---------------------------------------------------------------------------\n\n-- 트리거/유틸 함수 (인자 없음)\nalter function public.set_updated_at() set search_path = public", "alter function public.cra_backfill_post_fk() set search_path = public", "alter function public.cro_backfill_fks() set search_path = public", "alter function public.set_admin_content_updated_at() set search_path = public", "-- 맞춤의뢰 정산 보조 함수 (043)\nalter function public._positive_int_from_numeric(numeric) set search_path = public", "alter function public._order_primary_status_norm(public.custom_request_orders) set search_path = public", "alter function public._pick_custom_order_gross_won(public.custom_request_orders, public.custom_request_applications) set search_path = public", "-- 구독 cap 가중치 (050)\nalter function public.subscription_cap_weight(text) set search_path = public", "-- ---------------------------------------------------------------------------\n-- (C) 의도적으로 두는 것 (변경하지 않음)\n--   - mentor_directory_list 등 공개 조회 RPC: anon/authenticated 공개가 의도된 설계.\n--     (birth_date 등 민감 컬럼 노출 점검은 별도 백로그.)\n--   - view-count/increment, is_admin/is_mentor 헬퍼: 공개여도 데이터 변경은 RLS로 보호 → 무해.\n--\n-- (D) SQL 아님 — 대시보드에서:\n--   Authentication > Policies(또는 Auth 설정) > \"Leaked Password Protection\" 토글 ON.\n-- ---------------------------------------------------------------------------\n\n-- >>> NATIVE_BASELINE_PART 0084 | supabase/sql/073_fix_exposed_cash_debit.sql | 073_fix_exposed_cash_debit.sql <<<\n-- =============================================================================\n-- 073_fix_exposed_cash_debit.sql\n--\n-- 배경 (072 적용 후 실측):\n--   record_subscription_cash_debit 가 DB에 2개 오버로드로 존재하고, 그중 한 버전이\n--   anon/authenticated 에 EXECUTE 노출(can_exec=true)로 확인됨. 019/023/072 의 revoke 는\n--   (uuid,uuid,uuid,bigint) 시그니처만 대상으로 해서, 다른 시그니처(예: integer 버전 —\n--   소스 마이그레이션엔 없는 DB 잔존 중복)가 닫히지 않았다. 구독 캐시 차감 함수라 차단 필수.\n--\n-- 방침:\n--   - 시그니처를 추측하지 않고, public.record_subscription_cash_debit 의 \"모든 오버로드\"를\n--     동적으로 순회하며 revoke(public/anon/authenticated) + grant(service_role) → 멱등·견고.\n--   - drop 은 하지 않음: 앱이 named-arg RPC 로 호출하므로 PostgREST 가 어느 오버로드에\n--     바인딩하는지 100% 확정 전엔 위험(구독 결제 깨짐). 불확실 → revoke 만(안전).\n--\n-- 앱 호출 확인:\n--   lib/subscribe/subscribeCheckoutService.ts → admin.rpc(\"record_subscription_cash_debit\",\n--   { p_user_id, p_subscription_id, p_payment_id, p_amount_cents }) 를 service_role 로 호출.\n--   → 모든 오버로드에 service_role grant 유지하므로 결제 동작 보존.\n--\n-- 실행: Supabase SQL Editor (소유자/service_role). DB 실행은 사용자가 직접.\n--   순서: (0) 조사 → 본 파일 → (재점검).\n-- =============================================================================\n\n\n-- ---------------------------------------------------------------------------\n-- (0) 조사 — 모든 오버로드의 정확한 시그니처/노출/보안속성 (읽기 전용, 먼저 실행)\n-- ---------------------------------------------------------------------------\n-- select p.oid::regprocedure as full_signature,\n--        pg_get_function_identity_arguments(p.oid) as args,\n--        has_function_privilege(''anon'', p.oid, ''execute'') as anon_exec,\n--        has_function_privilege(''authenticated'', p.oid, ''execute'') as auth_exec,\n--        p.prosecdef as security_definer\n-- from pg_proc p\n-- where p.pronamespace = ''public''::regnamespace\n--   and p.proname = ''record_subscription_cash_debit''\n-- order by 1;\n\n\n-- ---------------------------------------------------------------------------\n-- (A) 모든 오버로드 일괄 차단 (시그니처 무관, 멱등)\n--     revoke from public, anon, authenticated  +  grant execute to service_role\n-- ---------------------------------------------------------------------------\ndo $$\ndeclare\n  r record;\nbegin\n  for r in\n    select p.oid::regprocedure as sig\n    from pg_proc p\n    where p.pronamespace = ''public''::regnamespace\n      and p.proname = ''record_subscription_cash_debit''\n  loop\n    execute format(''revoke all on function %s from public, anon, authenticated'', r.sig);\n    execute format(''grant execute on function %s to service_role'', r.sig);\n    raise notice ''hardened record_subscription_cash_debit -> %'', r.sig;\n  end loop;\nend $$", "-- ---------------------------------------------------------------------------\n-- (B) 알려진 정규 시그니처(앱이 의도하는 버전) 명시 재확인 — 레포 규약과 일치, 멱등\n-- ---------------------------------------------------------------------------\nrevoke all on function public.record_subscription_cash_debit(uuid, uuid, uuid, bigint) from public, anon, authenticated", "grant execute on function public.record_subscription_cash_debit(uuid, uuid, uuid, bigint) to service_role", "-- ---------------------------------------------------------------------------\n-- (C) (선택, 기본 비활성) 중복 오버로드 제거 — 매우 신중히.\n--     (0) 조사로 노출된 시그니처가 정규 bigint 버전이 \"아니고\",\n--     앱(PostgREST)이 그 버전을 호출하지 않음을 확인한 경우에만 주석 해제 실행.\n--     예) integer 버전이 잔존 중복이라 확정되면:\n--   -- drop function if exists public.record_subscription_cash_debit(uuid, uuid, uuid, integer);\n--     ⚠️ 앱이 바인딩하는 버전을 drop 하면 구독 결제가 깨진다. 불확실하면 (A)의 revoke 로 충분.\n-- ---------------------------------------------------------------------------\n\n\n-- ---------------------------------------------------------------------------\n-- (재점검) 모든 오버로드가 anon/auth false 여야 함 — 본 파일 실행 후 확인\n-- ---------------------------------------------------------------------------\n-- select p.oid::regprocedure as full_signature,\n--        has_function_privilege(''anon'', p.oid, ''execute'') as anon_exec,\n--        has_function_privilege(''authenticated'', p.oid, ''execute'') as auth_exec\n-- from pg_proc p\n-- where p.pronamespace = ''public''::regnamespace\n--   and p.proname = ''record_subscription_cash_debit''\n-- order by 1;\n\n-- >>> NATIVE_BASELINE_PART 0085 | supabase/sql/074_subjects_subdivision.sql | 074_subjects_subdivision.sql <<<\n-- =============================================================================\n-- 074_subjects_subdivision.sql\n--\n-- 목적: 과목 세분화 토대 — public.subjects 에 계층(parent_code) + 소분류 code 추가.\n--   앱 정본 상수(lib/subjects/subjectCatalog.ts)와 code/label/parent/sort 가 정확히 일치.\n--   question_threads.subject 는 subjects.code FK 이므로, 화면이 소분류 code 를 저장하기\n--   \"전에\" 이 SQL 로 소분류 행이 먼저 존재해야 한다(FK 위반 방지).\n--\n-- 안전:\n--   - 기존 대분류 code(korean/english/math/science/social/essay/career/etc) 유지 — 삭제/치환 없음.\n--   - 기존 데이터 마이그레이션 불필요(대분류 보존, 소분류는 추가만). 멱등.\n--   - social label 만 ''사회·역사'' → ''사회'' 로 update. korean_history(한국사) 신규 대분류 추가.\n--   - 기존 SQL(060 등) 미수정. 074 새 파일.\n--\n-- 실행: Supabase SQL Editor. 순서 — (0)점검 → 본문 → (검증).\n-- =============================================================================\n\n\n-- ---------------------------------------------------------------------------\n-- (0) 점검 — 현재 subjects 현황 (읽기 전용)\n-- ---------------------------------------------------------------------------\n-- select code, label, sort_order from public.subjects order by sort_order, code;\n\n\n-- ---------------------------------------------------------------------------\n-- 1) 계층 컬럼 추가 (self-FK). 기존 행은 parent_code = null (대분류).\n-- ---------------------------------------------------------------------------\nalter table public.subjects\n  add column if not exists parent_code text references public.subjects(code)", "comment on column public.subjects.parent_code is\n  ''대분류 code(없으면 자기 자신이 대분류). subjectCatalog.ts 와 일치.''", "-- ---------------------------------------------------------------------------\n-- 2) 기존 대분류 label/sort 정합 (code 유지, social 라벨만 변경)\n-- ---------------------------------------------------------------------------\nupdate public.subjects set label = ''사회'', sort_order = 50 where code = ''social''", "update public.subjects set sort_order = 10 where code = ''korean''", "update public.subjects set sort_order = 20 where code = ''english''", "update public.subjects set sort_order = 30 where code = ''math''", "update public.subjects set sort_order = 60 where code = ''science''", "update public.subjects set sort_order = 70 where code = ''essay''", "update public.subjects set sort_order = 80 where code = ''career''", "update public.subjects set sort_order = 99 where code = ''etc''", "-- ---------------------------------------------------------------------------\n-- 3) 신규 대분류: 한국사 (소분류 없음). 소분류 INSERT 전에 먼저 생성(FK).\n-- ---------------------------------------------------------------------------\ninsert into public.subjects (code, label, sort_order, parent_code) values\n  (''korean_history'', ''한국사'', 40, null)\non conflict (code) do nothing", "-- ---------------------------------------------------------------------------\n-- 4) 소분류 INSERT — parent_code 는 이미 존재하는 대분류 참조. 멱등.\n-- ---------------------------------------------------------------------------\ninsert into public.subjects (code, label, sort_order, parent_code) values\n  -- 국어\n  (''korean_speech_writing'', ''화법과작문'', 11, ''korean''),\n  (''korean_language_media'', ''언어와매체'', 12, ''korean''),\n  (''korean_reading'', ''독서'', 13, ''korean''),\n  (''korean_literature'', ''문학'', 14, ''korean''),\n  -- 수학\n  (''math_1'', ''수학Ⅰ'', 31, ''math''),\n  (''math_2'', ''수학Ⅱ'', 32, ''math''),\n  (''math_calculus'', ''미적분'', 33, ''math''),\n  (''math_statistics'', ''확률과통계'', 34, ''math''),\n  (''math_geometry'', ''기하'', 35, ''math''),\n  -- 사회\n  (''social_life_ethics'', ''생활과윤리'', 51, ''social''),\n  (''social_ethics_thought'', ''윤리와사상'', 52, ''social''),\n  (''social_korea_geo'', ''한국지리'', 53, ''social''),\n  (''social_world_geo'', ''세계지리'', 54, ''social''),\n  (''social_east_asia_history'', ''동아시아사'', 55, ''social''),\n  (''social_world_history'', ''세계사'', 56, ''social''),\n  (''social_economics'', ''경제'', 57, ''social''),\n  (''social_politics_law'', ''정치와법'', 58, ''social''),\n  (''social_culture'', ''사회문화'', 59, ''social''),\n  -- 과학\n  (''science_physics_1'', ''물리학Ⅰ'', 61, ''science''),\n  (''science_chemistry_1'', ''화학Ⅰ'', 62, ''science''),\n  (''science_biology_1'', ''생명과학Ⅰ'', 63, ''science''),\n  (''science_earth_1'', ''지구과학Ⅰ'', 64, ''science''),\n  (''science_physics_2'', ''물리학Ⅱ'', 65, ''science''),\n  (''science_chemistry_2'', ''화학Ⅱ'', 66, ''science''),\n  (''science_biology_2'', ''생명과학Ⅱ'', 67, ''science''),\n  (''science_earth_2'', ''지구과학Ⅱ'', 68, ''science'')\non conflict (code) do nothing", "-- ---------------------------------------------------------------------------\n-- (검증) 대분류 → 소분류 트리 / 총 36행 기대 (대분류 9 + 소분류 27)\n-- ---------------------------------------------------------------------------\n-- select\n--   coalesce(parent_code, code) as major,\n--   code, label, sort_order, parent_code\n-- from public.subjects\n-- order by\n--   (select s2.sort_order from public.subjects s2 where s2.code = coalesce(public.subjects.parent_code, public.subjects.code)),\n--   sort_order;\n-- select count(*) as total_rows from public.subjects;  -- 기대: 36\n\n-- >>> NATIVE_BASELINE_PART 0086 | supabase/sql/075_individual_question_transfers.sql | 075_individual_question_transfers.sql <<<\n-- =============================================================================\n-- 075_individual_question_transfers.sql\n--\n-- 목적: 구독 전환 시 released 개별질문을 구독 질문방으로 \"이전\"한 기록을 남겨\n--       중복 이전을 막는 멱등 매핑 테이블. (실제 이전은 앱 service_role 로직에서)\n--\n-- 안전:\n--   - 기존 SQL 미수정(075 새 파일). question_threads/messages/attachments·버킷 재사용.\n--   - 돈/에스크로 무관(released = 종료 건만 대상).\n--   - 멱등: individual_question_id PK → 이미 이전된 질문은 재이전 skip.\n--\n-- 실행: Supabase SQL Editor. (0) 점검 → 본문 → (검증).\n-- =============================================================================\n\n-- (0) 점검\n-- select count(*) from public.individual_question_transfers;\n\ncreate table if not exists public.individual_question_transfers (\n  individual_question_id uuid primary key references public.individual_questions(id) on delete cascade,\n  student_id uuid not null references public.users(id) on delete cascade,\n  mentor_id uuid not null references public.users(id) on delete cascade,\n  room_id uuid references public.mentor_student_rooms(id) on delete set null,\n  thread_id uuid references public.question_threads(id) on delete set null,\n  transferred_at timestamptz not null default now()\n)", "create index if not exists idx_iqt_student_mentor\n  on public.individual_question_transfers (student_id, mentor_id)", "alter table public.individual_question_transfers enable row level security", "-- 본인(학생)만 조회. 쓰기는 정책 없음 → service_role 전용(2단계 UI에서 배너·링크 조회용).\ndrop policy if exists \"iqt_select_student\" on public.individual_question_transfers", "create policy \"iqt_select_student\"\n  on public.individual_question_transfers\n  for select\n  to authenticated\n  using (student_id = (select auth.uid()))", "revoke all on table public.individual_question_transfers from public, anon", "grant select on table public.individual_question_transfers to authenticated", "grant all on table public.individual_question_transfers to service_role", "comment on table public.individual_question_transfers is\n  ''구독 전환 시 released 개별질문 → 구독 질문방 thread 이전 기록(멱등 키). 쓰기는 service_role.''", "-- (검증)\n-- select individual_question_id, room_id, thread_id, transferred_at\n-- from public.individual_question_transfers order by transferred_at desc;\n\n-- >>> NATIVE_BASELINE_PART 0087 | supabase/sql/076_connection_notes_owner_edit.sql | 076_connection_notes_owner_edit.sql <<<\n-- =============================================================================\n-- 076_connection_notes_owner_edit.sql\n--\n-- 보안 수정: connection_notes 의 cn_update / cn_delete 정책이 \"room 당사자\"만\n-- 검사하고 작성자(author_id)를 검사하지 않아, 같은 방의 상대가 남의 노트를\n-- 수정/삭제할 수 있었다. 작성자 본인(author_id = auth.uid())만 허용하도록 좁힌다.\n-- (cn_select 는 room 당사자 열람 그대로 유지 — 상대 노트는 읽기만.)\n--\n-- 안전:\n--   - 기존 SQL(002) 미수정. 본 파일에서 정책을 drop 후 author 제약으로 재생성.\n--   - 완화가 아니라 \"강화\"(권한 축소). 멱등(drop if exists).\n--   - 선례: 003_p0(author_id = (select auth.uid())), 001(user_id = (select auth.uid())).\n--   - author_id 가 null 인 레거시 노트는 본인 제약상 수정/삭제 불가(불변) — 의도된 동작.\n--\n-- 실행: Supabase SQL Editor. (0) 점검 → 본문 → (확인).\n-- =============================================================================\n\n-- (0) 점검 — 현재 정책\n-- select policyname, cmd, qual, with_check\n-- from pg_policies\n-- where schemaname = ''public'' and tablename = ''connection_notes''\n-- order by cmd;\n\nalter table public.connection_notes enable row level security", "drop policy if exists \"cn_update\" on public.connection_notes", "create policy \"cn_update\" on public.connection_notes\n  for update to authenticated\n  using (author_id = (select auth.uid()))\n  with check (author_id = (select auth.uid()))", "drop policy if exists \"cn_delete\" on public.connection_notes", "create policy \"cn_delete\" on public.connection_notes\n  for delete to authenticated\n  using (author_id = (select auth.uid()))", "-- (확인) cn_update/cn_delete 의 qual 에 author_id 제약이 들어갔는지\n-- select policyname, cmd, qual, with_check\n-- from pg_policies\n-- where schemaname = ''public'' and tablename = ''connection_notes'' and policyname in (''cn_update'',''cn_delete'');\n\n-- >>> NATIVE_BASELINE_PART 0088 | supabase/sql/077_mentor_school_verification.sql | 077_mentor_school_verification.sql <<<\n-- =============================================================================\n-- 077_mentor_school_verification.sql\n-- Purpose: A-1 mentor school/major verification storage.\n-- Scope: creates only a new table, indexes, table-local trigger, and RLS policies.\n-- Apply: run manually in Supabase SQL Editor after 001(users, set_updated_at)\n--        and an is_admin() migration such as 003/004.\n-- Notes:\n--   - Does not modify mentor_profiles, public mentor RPCs, payments, escrow, or 070 RPCs.\n--   - Keeps verified school/major values separate from mentor_profiles free-text fields.\n-- =============================================================================\n\ncreate table if not exists public.mentor_school_verifications (\n  id uuid primary key default gen_random_uuid(),\n  mentor_id uuid not null references public.users(id) on delete cascade,\n  status text not null default ''pending'' check (\n    status in (''pending'', ''approved'', ''rejected'', ''resubmit_required'')\n  ),\n  verified_university_name text,\n  verified_university_id text,\n  verified_major_category text check (\n    verified_major_category is null\n    or verified_major_category in (\n      ''메디컬'',\n      ''교육'',\n      ''인문'',\n      ''사회상경'',\n      ''자연'',\n      ''공학'',\n      ''예체능'',\n      ''기타''\n    )\n  ),\n  verified_department_name text,\n  school_tier text check (\n    school_tier is null\n    or school_tier in (\n      ''서연고'',\n      ''서성한'',\n      ''중경외시'',\n      ''그외'',\n      ''미분류''\n    )\n  ),\n  document_storage_ref text,\n  reviewed_by uuid references public.users(id) on delete set null,\n  reviewed_at timestamptz,\n  reject_reason text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "comment on table public.mentor_school_verifications is\n  ''Mentor school/major verification records. Verified values are separated from mentor_profiles free-text university_name/department_name.''", "comment on column public.mentor_school_verifications.mentor_id is\n  ''Mentor user id. Follows existing mentor_id -> public.users(id) pattern.''", "comment on column public.mentor_school_verifications.status is\n  ''pending / approved / rejected / resubmit_required.''", "comment on column public.mentor_school_verifications.verified_university_id is\n  ''Normalized university key for the later B-stage classification table.''", "comment on column public.mentor_school_verifications.verified_major_category is\n  ''Major category code for B-stage filtering/classification.''", "comment on column public.mentor_school_verifications.school_tier is\n  ''School tier code assigned by admin/classification table.''", "comment on column public.mentor_school_verifications.document_storage_ref is\n  ''Private Storage object reference for submitted school/major proof document.''", "create index if not exists idx_mentor_school_verifications_mentor_id\n  on public.mentor_school_verifications (mentor_id)", "create index if not exists idx_mentor_school_verifications_status\n  on public.mentor_school_verifications (status)", "-- Keep updated_at current using the existing shared trigger function from 001.\ndrop trigger if exists trg_mentor_school_verifications_set_updated_at\n  on public.mentor_school_verifications", "create trigger trg_mentor_school_verifications_set_updated_at\n  before update on public.mentor_school_verifications\n  for each row execute function public.set_updated_at()", "-- Mentors may submit/re-submit documents, but may not self-approve or self-fill\n-- admin-owned verified/review fields.\ncreate or replace function public.mentor_school_verifications_guard_self_review()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\nbegin\n  if coalesce((select public.is_admin()), false) then\n    return new;\n  end if;\n\n  if new.mentor_id = (select auth.uid()) then\n    new.status := ''pending'';\n    new.verified_university_name := null;\n    new.verified_university_id := null;\n    new.verified_major_category := null;\n    new.verified_department_name := null;\n    new.school_tier := null;\n    new.reviewed_by := null;\n    new.reviewed_at := null;\n    new.reject_reason := null;\n  end if;\n\n  return new;\nend;\n$function$", "drop trigger if exists trg_mentor_school_verifications_guard_self_review\n  on public.mentor_school_verifications", "create trigger trg_mentor_school_verifications_guard_self_review\n  before insert or update on public.mentor_school_verifications\n  for each row execute function public.mentor_school_verifications_guard_self_review()", "alter table public.mentor_school_verifications enable row level security", "-- No public/anon direct access policy.\n\ndrop policy if exists msv_select_own on public.mentor_school_verifications", "create policy msv_select_own\n  on public.mentor_school_verifications\n  for select\n  to authenticated\n  using (mentor_id = (select auth.uid()))", "drop policy if exists msv_insert_own_pending on public.mentor_school_verifications", "create policy msv_insert_own_pending\n  on public.mentor_school_verifications\n  for insert\n  to authenticated\n  with check (\n    mentor_id = (select auth.uid())\n    and status = ''pending''\n    and exists (\n      select 1\n      from public.users u\n      where u.id = (select auth.uid())\n        and u.role = ''mentor''\n    )\n    and verified_university_name is null\n    and verified_university_id is null\n    and verified_major_category is null\n    and verified_department_name is null\n    and school_tier is null\n    and reviewed_by is null\n    and reviewed_at is null\n    and reject_reason is null\n  )", "drop policy if exists msv_update_own_pending on public.mentor_school_verifications", "create policy msv_update_own_pending\n  on public.mentor_school_verifications\n  for update\n  to authenticated\n  using (\n    mentor_id = (select auth.uid())\n    and status in (''pending'', ''resubmit_required'')\n  )\n  with check (\n    mentor_id = (select auth.uid())\n    and status = ''pending''\n    and verified_university_name is null\n    and verified_university_id is null\n    and verified_major_category is null\n    and verified_department_name is null\n    and school_tier is null\n    and reviewed_by is null\n    and reviewed_at is null\n    and reject_reason is null\n  )", "drop policy if exists msv_admin_select_all on public.mentor_school_verifications", "create policy msv_admin_select_all\n  on public.mentor_school_verifications\n  for select\n  to authenticated\n  using ((select public.is_admin()) = true)", "drop policy if exists msv_admin_update_all on public.mentor_school_verifications", "create policy msv_admin_update_all\n  on public.mentor_school_verifications\n  for update\n  to authenticated\n  using ((select public.is_admin()) = true)\n  with check ((select public.is_admin()) = true)", "comment on policy msv_select_own on public.mentor_school_verifications is\n  ''Mentors can read only their own school verification rows.''", "comment on policy msv_insert_own_pending on public.mentor_school_verifications is\n  ''Mentors can submit only their own pending document rows; admin-owned verified fields remain null.''", "comment on policy msv_update_own_pending on public.mentor_school_verifications is\n  ''Mentors can update only own pending/resubmit_required rows back to pending, without self-approving.''", "comment on policy msv_admin_select_all on public.mentor_school_verifications is\n  ''Admins can review all mentor school verification rows.''", "comment on policy msv_admin_update_all on public.mentor_school_verifications is\n  ''Admins can approve/reject/request resubmission and fill verified values.''", "-- >>> NATIVE_BASELINE_PART 0089 | supabase/sql/078_p0_public_mentor_read_rpc_v2.sql | 078_p0_public_mentor_read_rpc_v2.sql <<<\n-- 078_p0_public_mentor_read_rpc_v2.sql\n-- P0: Replace public mentor read RPCs with whitelist-only v2 functions.\n-- Run manually in Supabase SQL Editor.\n\nbegin", "-- Public mentor directory: safe user fields only.\ncreate or replace function public.mentor_directory_list_v2(p_limit int default 80)\nreturns table (\n  id uuid,\n  role text,\n  status text,\n  full_name text,\n  nickname text,\n  created_at timestamptz\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select\n    u.id,\n    u.role,\n    u.status,\n    u.full_name,\n    u.nickname,\n    u.created_at\n  from public.users u\n  where u.role = ''mentor''\n  order by u.created_at desc\n  limit greatest(1, least(coalesce(p_limit, 80), 200));\n$$", "-- Public single mentor user row: safe user fields only.\ncreate or replace function public.mentor_user_public_v2(p_mentor_id uuid)\nreturns table (\n  id uuid,\n  role text,\n  status text,\n  full_name text,\n  nickname text,\n  created_at timestamptz\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select\n    u.id,\n    u.role,\n    u.status,\n    u.full_name,\n    u.nickname,\n    u.created_at\n  from public.users u\n  where u.id = p_mentor_id\n    and u.role = ''mentor''\n  limit 1;\n$$", "-- Public mentor profiles: safe profile fields plus approved school verification display fields.\ncreate or replace function public.mentor_profiles_for_directory_v2(p_ids uuid[])\nreturns table (\n  user_id uuid,\n  university_name text,\n  department_name text,\n  teaching_subjects text[],\n  intro_line text,\n  verification_status text,\n  created_at timestamptz,\n  verified_university_name text,\n  verified_department_name text,\n  verified_major_category text,\n  school_tier text,\n  school_verified boolean\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select\n    mp.user_id,\n    mp.university_name,\n    mp.department_name,\n    mp.teaching_subjects,\n    mp.intro_line,\n    mp.verification_status,\n    mp.created_at,\n    sv.verified_university_name,\n    sv.verified_department_name,\n    sv.verified_major_category,\n    sv.school_tier,\n    (sv.mentor_id is not null) as school_verified\n  from public.mentor_profiles mp\n  left join lateral (\n    select\n      msv.mentor_id,\n      msv.verified_university_name,\n      msv.verified_department_name,\n      msv.verified_major_category,\n      msv.school_tier\n    from public.mentor_school_verifications msv\n    where msv.mentor_id = mp.user_id\n      and msv.status = ''approved''\n    order by coalesce(msv.reviewed_at, msv.updated_at, msv.created_at) desc, msv.created_at desc\n    limit 1\n  ) sv on true\n  where p_ids is not null\n    and array_length(p_ids, 1) is not null\n    and mp.user_id = any (p_ids);\n$$", "revoke all on function public.mentor_directory_list_v2(int) from public", "revoke all on function public.mentor_user_public_v2(uuid) from public", "revoke all on function public.mentor_profiles_for_directory_v2(uuid[]) from public", "grant execute on function public.mentor_directory_list_v2(int) to anon, authenticated", "grant execute on function public.mentor_user_public_v2(uuid) to anon, authenticated", "grant execute on function public.mentor_profiles_for_directory_v2(uuid[]) to anon, authenticated", "-- Stop direct anon/authenticated access to the old over-broad public RPCs.\n-- Do not drop them here; revoking execute avoids breaking hidden dependencies more abruptly.\nrevoke execute on function public.mentor_directory_list(int) from anon, authenticated", "revoke execute on function public.mentor_user_public(uuid) from anon, authenticated", "revoke execute on function public.mentor_profiles_for_directory(uuid[]) from anon, authenticated", "revoke all on function public.mentor_directory_list(int) from public", "revoke all on function public.mentor_user_public(uuid) from public", "revoke all on function public.mentor_profiles_for_directory(uuid[]) from public", "comment on function public.mentor_directory_list_v2(int) is ''P0 public mentor directory whitelist. Excludes PII, consent metadata, payout data, and document paths.''", "comment on function public.mentor_user_public_v2(uuid) is ''P0 public single mentor user whitelist. Excludes PII, consent metadata, payout data, and document paths.''", "comment on function public.mentor_profiles_for_directory_v2(uuid[]) is ''P0 public mentor profile whitelist plus approved school verification display fields only.''", "commit", "-- >>> NATIVE_BASELINE_PART 0090 | supabase/sql/079_b_classification_catalog.sql | 079_b_classification_catalog.sql <<<\n-- 079_b_classification_catalog.sql\n-- B: Admin-managed school tier / major category catalogs and school-tier mappings.\n-- Apply manually in Supabase SQL Editor after review.\n--\n-- Safety:\n-- - Extends only mentor_school_verifications.school_tier CHECK by adding ''건동홍''.\n-- - Does not touch mentor_school_verifications RLS, triggers, self-fill guard,\n--   verified_major_category CHECK, payments, escrow, or 070 RPCs.\n\nbegin", "do $$\ndeclare\n  v_constraint_names name[];\n  v_constraint_name name;\n  v_constraint_def text;\nbegin\n  if to_regclass(''public.mentor_school_verifications'') is null then\n    raise exception ''mentor_school_verifications table does not exist; apply 077 first'';\n  end if;\n\n  select array_agg(c.conname order by c.conname)\n    into v_constraint_names\n  from pg_constraint c\n  join pg_attribute a\n    on a.attrelid = c.conrelid\n   and a.attnum = any(c.conkey)\n  where c.conrelid = ''public.mentor_school_verifications''::regclass\n    and c.contype = ''c''\n    and c.conkey = array[a.attnum]::smallint[]\n    and a.attname = ''school_tier''\n    and pg_get_constraintdef(c.oid) like ''%서연고%''\n    and pg_get_constraintdef(c.oid) like ''%서성한%''\n    and pg_get_constraintdef(c.oid) like ''%중경외시%''\n    and pg_get_constraintdef(c.oid) like ''%그외%''\n    and pg_get_constraintdef(c.oid) like ''%미분류%'';\n\n  if coalesce(array_length(v_constraint_names, 1), 0) <> 1 then\n    raise exception\n      ''expected exactly one school_tier CHECK on mentor_school_verifications, found %: %'',\n      coalesce(array_length(v_constraint_names, 1), 0),\n      coalesce(v_constraint_names::text, ''{}'');\n  end if;\n\n  v_constraint_name := v_constraint_names[1];\n\n  select pg_get_constraintdef(c.oid)\n    into v_constraint_def\n  from pg_constraint c\n  where c.conrelid = ''public.mentor_school_verifications''::regclass\n    and c.conname = v_constraint_name;\n\n  raise notice ''Replacing school_tier CHECK %. Old definition: %'', v_constraint_name, v_constraint_def;\n\n  execute format(\n    ''alter table public.mentor_school_verifications drop constraint if exists %I'',\n    v_constraint_name\n  );\n\n  alter table public.mentor_school_verifications\n    add constraint mentor_school_verifications_school_tier_check\n    check (\n      school_tier is null\n      or school_tier in (\n        ''서연고'',\n        ''서성한'',\n        ''중경외시'',\n        ''건동홍'',\n        ''그외'',\n        ''미분류''\n      )\n    );\nend;\n$$", "create table if not exists public.school_tier_catalog (\n  code text primary key,\n  label text not null,\n  display_order integer not null default 0,\n  is_active boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint school_tier_catalog_code_allowed check (\n    code in (''서연고'', ''서성한'', ''중경외시'', ''건동홍'', ''그외'', ''미분류'')\n  ),\n  constraint school_tier_catalog_label_nonempty check (char_length(trim(label)) > 0)\n)", "create table if not exists public.major_category_catalog (\n  code text primary key,\n  label text not null,\n  display_order integer not null default 0,\n  is_active boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint major_category_catalog_code_allowed check (\n    code in (''메디컬'', ''교육'', ''인문'', ''사회상경'', ''자연'', ''공학'', ''예체능'', ''기타'')\n  ),\n  constraint major_category_catalog_label_nonempty check (char_length(trim(label)) > 0)\n)", "create table if not exists public.school_tier_mappings (\n  id uuid primary key default gen_random_uuid(),\n  school_name text not null,\n  school_tier_code text not null references public.school_tier_catalog(code) on update restrict on delete restrict,\n  note text,\n  is_active boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint school_tier_mappings_school_name_nonempty check (char_length(trim(school_name)) > 0)\n)", "create unique index if not exists school_tier_mappings_school_name_unique\n  on public.school_tier_mappings (lower(trim(school_name)))", "create index if not exists school_tier_catalog_active_order_idx\n  on public.school_tier_catalog (is_active, display_order, code)", "create index if not exists major_category_catalog_active_order_idx\n  on public.major_category_catalog (is_active, display_order, code)", "create index if not exists school_tier_mappings_active_order_idx\n  on public.school_tier_mappings (is_active, school_tier_code, school_name)", "drop trigger if exists trg_school_tier_catalog_set_updated_at\n  on public.school_tier_catalog", "create trigger trg_school_tier_catalog_set_updated_at\n  before update on public.school_tier_catalog\n  for each row execute function public.set_updated_at()", "drop trigger if exists trg_major_category_catalog_set_updated_at\n  on public.major_category_catalog", "create trigger trg_major_category_catalog_set_updated_at\n  before update on public.major_category_catalog\n  for each row execute function public.set_updated_at()", "drop trigger if exists trg_school_tier_mappings_set_updated_at\n  on public.school_tier_mappings", "create trigger trg_school_tier_mappings_set_updated_at\n  before update on public.school_tier_mappings\n  for each row execute function public.set_updated_at()", "alter table public.school_tier_catalog enable row level security", "alter table public.major_category_catalog enable row level security", "alter table public.school_tier_mappings enable row level security", "drop policy if exists school_tier_catalog_select_active_or_admin\n  on public.school_tier_catalog", "create policy school_tier_catalog_select_active_or_admin\n  on public.school_tier_catalog\n  for select\n  to anon, authenticated\n  using (is_active = true or coalesce((select public.is_admin()), false) = true)", "drop policy if exists major_category_catalog_select_active_or_admin\n  on public.major_category_catalog", "create policy major_category_catalog_select_active_or_admin\n  on public.major_category_catalog\n  for select\n  to anon, authenticated\n  using (is_active = true or coalesce((select public.is_admin()), false) = true)", "drop policy if exists school_tier_catalog_write_admin\n  on public.school_tier_catalog", "create policy school_tier_catalog_write_admin\n  on public.school_tier_catalog\n  for all\n  to authenticated\n  using (coalesce((select public.is_admin()), false) = true)\n  with check (coalesce((select public.is_admin()), false) = true)", "drop policy if exists major_category_catalog_write_admin\n  on public.major_category_catalog", "create policy major_category_catalog_write_admin\n  on public.major_category_catalog\n  for all\n  to authenticated\n  using (coalesce((select public.is_admin()), false) = true)\n  with check (coalesce((select public.is_admin()), false) = true)", "drop policy if exists school_tier_mappings_admin_all\n  on public.school_tier_mappings", "create policy school_tier_mappings_admin_all\n  on public.school_tier_mappings\n  for all\n  to authenticated\n  using (coalesce((select public.is_admin()), false) = true)\n  with check (coalesce((select public.is_admin()), false) = true)", "grant select on public.school_tier_catalog to anon, authenticated", "grant select on public.major_category_catalog to anon, authenticated", "grant select on public.school_tier_mappings to authenticated", "grant insert, update, delete on public.school_tier_catalog to authenticated", "grant insert, update, delete on public.major_category_catalog to authenticated", "grant insert, update, delete on public.school_tier_mappings to authenticated", "insert into public.school_tier_catalog (code, label, display_order, is_active)\nvalues\n  (''서연고'', ''서연고'', 1, true),\n  (''서성한'', ''서성한'', 2, true),\n  (''중경외시'', ''중경외시'', 3, true),\n  (''건동홍'', ''건동홍'', 4, true),\n  (''그외'', ''그외'', 5, true),\n  (''미분류'', ''미분류'', 6, true)\non conflict (code) do nothing", "insert into public.major_category_catalog (code, label, display_order, is_active)\nvalues\n  (''메디컬'', ''메디컬'', 1, true),\n  (''교육'', ''교육'', 2, true),\n  (''인문'', ''인문'', 3, true),\n  (''사회상경'', ''사회상경'', 4, true),\n  (''자연'', ''자연'', 5, true),\n  (''공학'', ''공학'', 6, true),\n  (''예체능'', ''예체능'', 7, true),\n  (''기타'', ''기타'', 8, true)\non conflict (code) do nothing", "commit", "-- >>> NATIVE_BASELINE_PART 0091 | supabase/sql/080_c_individual_question_qualification.sql | 080_c_individual_question_qualification.sql <<<\n-- =============================================================================\n-- 080_c_individual_question_qualification.sql\n-- Purpose: Store qualification requirements for open individual questions.\n--\n-- Safety:\n--   - Does not edit/drop/revoke 070 create_individual_question_with_hold v1.\n--   - Adds nullable qualification columns to individual_questions.\n--   - Adds create_individual_question_with_hold_v2 by copying v1 escrow flow\n--     and only adding qualification validation + insert columns.\n--   - v2 execute remains service_role only.\n--   - Does not touch payments, custom-request escrow, refunds, 077 RLS/triggers.\n-- =============================================================================\n\nbegin", "alter table public.individual_questions\n  add column if not exists required_school_tier text,\n  add column if not exists required_major_category text", "alter table public.individual_questions\n  drop constraint if exists individual_questions_required_school_tier_check,\n  add constraint individual_questions_required_school_tier_check\n    check (\n      required_school_tier is null\n      or required_school_tier in (''서연고'', ''서성한'', ''중경외시'', ''건동홍'', ''그외'', ''미분류'')\n    )", "alter table public.individual_questions\n  drop constraint if exists individual_questions_required_major_category_check,\n  add constraint individual_questions_required_major_category_check\n    check (\n      required_major_category is null\n      or required_major_category in (''메디컬'', ''교육'', ''인문'', ''사회상경'', ''자연'', ''공학'', ''예체능'', ''기타'')\n    )", "create index if not exists idx_iq_open_required_qualification\n  on public.individual_questions (\n    required_school_tier,\n    required_major_category,\n    created_at desc\n  )\n  where question_type = ''open'' and status = ''open''", "create or replace function public.create_individual_question_with_hold_v2(\n  p_student_id uuid,\n  p_question_type text,\n  p_mentor_id uuid,\n  p_subject text,\n  p_topic text,\n  p_title text,\n  p_body text,\n  p_price_cents int,\n  p_idempotency_key text,\n  p_required_school_tier text default null,\n  p_required_major_category text default null\n)\nreturns public.individual_question_escrow_result\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_type text := lower(trim(coalesce(p_question_type, '''')));\n  v_status text;\n  v_idem text := trim(coalesce(p_idempotency_key, ''''));\n  v_required_school_tier text := nullif(trim(coalesce(p_required_school_tier, '''')), '''');\n  v_required_major_category text := nullif(trim(coalesce(p_required_major_category, '''')), '''');\n  v_question public.individual_questions%rowtype;\n  v_ledger_id uuid;\n  v_wallet_balance bigint;\n  v_wallet_rows int;\nbegin\n  if p_student_id is null then\n    return (false, ''invalid_student'', ''student_id is required'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if not exists (select 1 from public.users u where u.id = p_student_id and u.role = ''student'') then\n    return (false, ''invalid_student'', ''student must be a student user'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_type not in (''direct'', ''open'') then\n    return (false, ''invalid_type'', ''question_type must be direct or open'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_type = ''direct'' and p_mentor_id is null then\n    return (false, ''mentor_required'', ''direct question requires mentor_id'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_type = ''direct'' and not public.individual_question_user_is_approved_mentor(p_mentor_id) then\n    return (false, ''mentor_not_approved'', ''mentor is not approved for individual questions'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if p_price_cents is null or p_price_cents <= 0 then\n    return (false, ''invalid_price'', ''price_cents must be positive'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if p_price_cents > 1000000000 then\n    return (false, ''price_too_large'', ''price_cents is too large'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if length(v_idem) = 0 then\n    return (false, ''invalid_idempotency_key'', ''idempotency_key is required'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if length(trim(coalesce(p_title, ''''))) = 0 or length(trim(coalesce(p_body, ''''))) = 0 then\n    return (false, ''invalid_content'', ''title and body are required'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_type <> ''open'' then\n    v_required_school_tier := null;\n    v_required_major_category := null;\n  end if;\n\n  if v_required_school_tier is not null\n     and v_required_school_tier not in (''서연고'', ''서성한'', ''중경외시'', ''건동홍'', ''그외'', ''미분류'') then\n    return (false, ''invalid_required_school_tier'', ''required_school_tier is invalid'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_required_major_category is not null\n     and v_required_major_category not in (''메디컬'', ''교육'', ''인문'', ''사회상경'', ''자연'', ''공학'', ''예체능'', ''기타'') then\n    return (false, ''invalid_required_major_category'', ''required_major_category is invalid'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  select *\n    into v_question\n  from public.individual_questions\n  where create_idempotency_key = v_idem;\n\n  if found then\n    select balance_cents\n      into v_wallet_balance\n    from public.cash_wallets\n    where user_id = p_student_id;\n\n    return (\n      true,\n      ''already_exists'',\n      ''individual question already created for idempotency key'',\n      v_question.id,\n      v_question.status,\n      v_question.hold_ledger_id,\n      v_wallet_balance\n    )::public.individual_question_escrow_result;\n  end if;\n\n  insert into public.cash_wallets (user_id, balance_cents)\n  values (p_student_id, 0)\n  on conflict (user_id) do nothing;\n\n  select balance_cents\n    into v_wallet_balance\n  from public.cash_wallets\n  where user_id = p_student_id\n  for update;\n\n  -- Re-check idempotency after wallet lock to avoid double debit on concurrent calls.\n  select *\n    into v_question\n  from public.individual_questions\n  where create_idempotency_key = v_idem;\n\n  if found then\n    return (\n      true,\n      ''already_exists'',\n      ''individual question already created for idempotency key'',\n      v_question.id,\n      v_question.status,\n      v_question.hold_ledger_id,\n      v_wallet_balance\n    )::public.individual_question_escrow_result;\n  end if;\n\n  if coalesce(v_wallet_balance, 0) < p_price_cents then\n    return (\n      false,\n      ''insufficient_cash'',\n      ''CASH_INSUFFICIENT'',\n      null,\n      null,\n      null,\n      coalesce(v_wallet_balance, 0)\n    )::public.individual_question_escrow_result;\n  end if;\n\n  v_status := case when v_type = ''direct'' then ''assigned'' else ''open'' end;\n\n  insert into public.individual_questions (\n    student_id,\n    question_type,\n    designated_mentor_id,\n    subject,\n    topic,\n    title,\n    body,\n    price_cents,\n    status,\n    create_idempotency_key,\n    required_school_tier,\n    required_major_category\n  )\n  values (\n    p_student_id,\n    v_type,\n    case when v_type = ''direct'' then p_mentor_id else null end,\n    nullif(trim(coalesce(p_subject, '''')), ''''),\n    nullif(trim(coalesce(p_topic, '''')), ''''),\n    trim(p_title),\n    trim(p_body),\n    p_price_cents,\n    v_status,\n    v_idem,\n    v_required_school_tier,\n    v_required_major_category\n  )\n  returning * into v_question;\n\n  insert into public.cash_ledger (\n    user_id,\n    delta_cents,\n    reason,\n    ref_type,\n    ref_id,\n    idempotency_key\n  )\n  values (\n    p_student_id,\n    -p_price_cents,\n    ''individual_question_escrow_hold'',\n    ''individual_questions'',\n    v_question.id,\n    ''iq_hold:'' || v_question.id::text\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_ledger_id;\n\n  if v_ledger_id is null then\n    raise exception ''INDIVIDUAL_QUESTION_HOLD_LEDGER_CONFLICT'';\n  end if;\n\n  update public.cash_wallets\n  set balance_cents = balance_cents - p_price_cents\n  where user_id = p_student_id\n    and balance_cents >= p_price_cents\n  returning balance_cents into v_wallet_balance;\n\n  get diagnostics v_wallet_rows = row_count;\n  if coalesce(v_wallet_rows, 0) = 0 then\n    raise exception ''CASH_INSUFFICIENT_AFTER_LOCK'' using errcode = ''P0001'';\n  end if;\n\n  update public.individual_questions\n  set hold_ledger_id = v_ledger_id\n  where id = v_question.id\n  returning * into v_question;\n\n  return (\n    true,\n    ''created'',\n    ''individual question created and cash held'',\n    v_question.id,\n    v_question.status,\n    v_ledger_id,\n    v_wallet_balance\n  )::public.individual_question_escrow_result;\nend;\n$function$", "revoke all on function public.create_individual_question_with_hold_v2(\n  uuid, text, uuid, text, text, text, text, int, text, text, text\n) from public, anon, authenticated", "grant execute on function public.create_individual_question_with_hold_v2(\n  uuid, text, uuid, text, text, text, text, int, text, text, text\n) to service_role", "comment on column public.individual_questions.required_school_tier is\n  ''Open individual-question qualification requirement: school tier. Null means no requirement.''", "comment on column public.individual_questions.required_major_category is\n  ''Open individual-question qualification requirement: major category. Null means no requirement.''", "comment on function public.create_individual_question_with_hold_v2(\n  uuid, text, uuid, text, text, text, text, int, text, text, text\n) is\n  ''Q1 individual question create + escrow hold v2. Adds nullable open-question qualification requirements. service_role only.''", "commit", "-- >>> NATIVE_BASELINE_PART 0092 | supabase/sql/081_d_claim_gate.sql | 081_d_claim_gate.sql <<<\n-- =============================================================================\n-- 081_d_claim_gate.sql\n-- Purpose: Enforce open individual-question qualification requirements at claim.\n--\n-- Safety:\n--   - Does not edit/drop/revoke 070 claim_individual_question v1.\n--   - Adds claim_individual_question_v2 with the same signature as v1.\n--   - Keeps v1 first-claim UPDATE conditions and ledger/wallet no-op behavior.\n--   - Adds only a pre-UPDATE early return guard based on latest approved\n--     mentor_school_verifications row.\n--   - v2 execute remains service_role only.\n--   - Requires 079 school tier CHECK/catalog and 080 individual question\n--     qualification columns to be applied first.\n-- =============================================================================\n\nbegin", "create or replace function public.claim_individual_question_v2(\n  p_question_id uuid,\n  p_mentor_id uuid\n)\nreturns public.individual_question_escrow_result\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_question public.individual_questions%rowtype;\n  v_required_school_tier text;\n  v_required_major_category text;\n  v_verified_school_tier text;\n  v_verified_major_category text;\nbegin\n  if p_question_id is null or p_mentor_id is null then\n    return (false, ''invalid_input'', ''question_id and mentor_id are required'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if not public.individual_question_user_is_approved_mentor(p_mentor_id) then\n    return (false, ''mentor_not_approved'', ''mentor is not approved for individual questions'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  select\n    q.required_school_tier,\n    q.required_major_category\n    into v_required_school_tier, v_required_major_category\n  from public.individual_questions q\n  where q.id = p_question_id\n    and q.question_type = ''open''\n    and q.status = ''open''\n    and q.claimed_mentor_id is null\n    and (q.expires_at is null or q.expires_at > now())\n    and q.student_id <> p_mentor_id;\n\n  if not found then\n    return (false, ''not_available'', ''question is already claimed, expired, or unavailable'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_required_school_tier is not null or v_required_major_category is not null then\n    select\n      msv.school_tier,\n      msv.verified_major_category\n      into v_verified_school_tier, v_verified_major_category\n    from public.mentor_school_verifications msv\n    where msv.mentor_id = p_mentor_id\n      and msv.status = ''approved''\n    order by coalesce(msv.reviewed_at, msv.updated_at, msv.created_at) desc, msv.created_at desc\n    limit 1;\n\n    if not found then\n      return (false, ''mentor_school_verification_required'', ''mentor school verification is required for this question'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n    end if;\n\n    if v_required_school_tier is not null\n       and coalesce(v_verified_school_tier, '''') <> v_required_school_tier then\n      return (false, ''mentor_qualification_not_met'', ''mentor school tier does not match this question requirement'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n    end if;\n\n    if v_required_major_category is not null\n       and coalesce(v_verified_major_category, '''') <> v_required_major_category then\n      return (false, ''mentor_qualification_not_met'', ''mentor major category does not match this question requirement'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n    end if;\n  end if;\n\n  update public.individual_questions\n  set\n    claimed_mentor_id = p_mentor_id,\n    claimed_at = now(),\n    status = ''claimed''\n  where id = p_question_id\n    and question_type = ''open''\n    and status = ''open''\n    and claimed_mentor_id is null\n    and (expires_at is null or expires_at > now())\n    and student_id <> p_mentor_id\n  returning * into v_question;\n\n  if not found then\n    return (false, ''not_available'', ''question is already claimed, expired, or unavailable'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  return (true, ''claimed'', ''individual question claimed'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\nend;\n$function$", "revoke all on function public.claim_individual_question_v2(uuid, uuid)\n  from public, anon, authenticated", "grant execute on function public.claim_individual_question_v2(uuid, uuid)\n  to service_role", "comment on function public.claim_individual_question_v2(uuid, uuid) is\n  ''Q1 open individual question first-claim v2. Enforces required school/major qualification against the latest approved mentor_school_verifications row. service_role only.''", "commit", "-- >>> NATIVE_BASELINE_PART 0093 | supabase/sql/082_community_shortform_likes.sql | 082_community_shortform_likes.sql <<<\n-- =============================================================================\n-- 082_community_shortform_likes.sql\n-- Purpose: Add per-user like storage for shortform posts and keep\n--          shortform_posts.like_count in sync.\n--\n-- Safety:\n--   - Does not edit existing community/shortform tables except updating\n--     shortform_posts.like_count through a trigger.\n--   - RLS is narrow: authenticated users can read/insert/delete only their own\n--     shortform reaction rows. Public count is exposed through\n--     shortform_posts.like_count.\n--   - No payment/escrow/auth-verification objects touched.\n-- =============================================================================\n\nbegin", "create extension if not exists pgcrypto", "create table if not exists public.shortform_reactions (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete cascade,\n  shortform_id uuid not null references public.shortform_posts (id) on delete cascade,\n  type text not null default ''like'' check (type in (''like'')),\n  created_at timestamptz not null default now(),\n  unique (user_id, shortform_id, type)\n)", "create index if not exists idx_shortform_reactions_shortform\n  on public.shortform_reactions (shortform_id, type)", "create index if not exists idx_shortform_reactions_user\n  on public.shortform_reactions (user_id, created_at desc)", "create or replace function public.community_refresh_shortform_like_count()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  pid uuid;\nbegin\n  pid := coalesce(new.shortform_id, old.shortform_id);\n\n  update public.shortform_posts p\n  set like_count = (\n    select count(*)::int\n    from public.shortform_reactions r\n    where r.shortform_id = pid\n      and r.type = ''like''\n  )\n  where p.id = pid;\n\n  return coalesce(new, old);\nend;\n$function$", "drop trigger if exists trg_shortform_reactions_like_count on public.shortform_reactions", "create trigger trg_shortform_reactions_like_count\n  after insert or delete on public.shortform_reactions\n  for each row execute function public.community_refresh_shortform_like_count()", "alter table public.shortform_reactions enable row level security", "drop policy if exists \"shortform_reactions_select_own\" on public.shortform_reactions", "create policy \"shortform_reactions_select_own\"\n  on public.shortform_reactions for select to authenticated\n  using (user_id = (select auth.uid()))", "drop policy if exists \"shortform_reactions_insert_own\" on public.shortform_reactions", "create policy \"shortform_reactions_insert_own\"\n  on public.shortform_reactions for insert to authenticated\n  with check (\n    user_id = (select auth.uid())\n    and type = ''like''\n  )", "drop policy if exists \"shortform_reactions_delete_own\" on public.shortform_reactions", "create policy \"shortform_reactions_delete_own\"\n  on public.shortform_reactions for delete to authenticated\n  using (user_id = (select auth.uid()))", "grant select, insert, delete on public.shortform_reactions to authenticated", "commit", "-- >>> NATIVE_BASELINE_PART 0094 | supabase/sql/083_custom_order_message_attachments.sql | 083_custom_order_message_attachments.sql <<<\n-- =============================================================================\n-- 083_custom_order_message_attachments.sql\n-- Purpose: Private, party-only attachments for custom order room messages.\n--\n-- Safety:\n--   - Does not touch custom request order state machines, escrow, payment,\n--     refund, 070 individual-question RPCs, or 077 verification objects.\n--   - Creates a new private Storage bucket and a new metadata table only.\n--   - Access is limited to the canonical order student_id, mentor_id, and admins.\n--   - SQL is intended for manual Supabase SQL Editor execution.\n-- =============================================================================\n\nbegin", "insert into storage.buckets (\n  id,\n  name,\n  public,\n  file_size_limit,\n  allowed_mime_types\n)\nvalues (\n  ''custom-order-message-attachments'',\n  ''custom-order-message-attachments'',\n  false,\n  20971520,\n  array[\n    ''application/pdf'',\n    ''image/png'',\n    ''image/jpeg'',\n    ''image/webp'',\n    ''application/zip'',\n    ''application/vnd.openxmlformats-officedocument.wordprocessingml.document'',\n    ''application/vnd.openxmlformats-officedocument.presentationml.presentation''\n  ]\n)\non conflict (id) do update\nset\n  public = false,\n  file_size_limit = excluded.file_size_limit,\n  allowed_mime_types = excluded.allowed_mime_types", "create table if not exists public.custom_order_message_attachments (\n  id uuid primary key default gen_random_uuid(),\n  order_id uuid not null references public.custom_request_orders (id) on delete cascade,\n  message_id uuid references public.custom_order_messages (id) on delete set null,\n  uploader_id uuid not null references public.users (id) on delete cascade,\n  storage_path text not null,\n  original_filename text not null,\n  mime_type text not null,\n  file_size_bytes bigint not null,\n  created_at timestamptz not null default now(),\n  constraint custom_order_message_attachments_storage_path_unique unique (storage_path),\n  constraint custom_order_message_attachments_size_check\n    check (file_size_bytes > 0 and file_size_bytes <= 20971520),\n  constraint custom_order_message_attachments_mime_type_check\n    check (\n      mime_type in (\n        ''application/pdf'',\n        ''image/png'',\n        ''image/jpeg'',\n        ''image/webp'',\n        ''application/zip'',\n        ''application/vnd.openxmlformats-officedocument.wordprocessingml.document'',\n        ''application/vnd.openxmlformats-officedocument.presentationml.presentation''\n      )\n    ),\n  constraint custom_order_message_attachments_storage_path_check\n    check (\n      storage_path ~* ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9]+-[a-z0-9]{8,32}\\.[a-z0-9]+$''\n    )\n)", "create index if not exists idx_custom_order_message_attachments_order\n  on public.custom_order_message_attachments (order_id, created_at asc)", "create index if not exists idx_custom_order_message_attachments_message\n  on public.custom_order_message_attachments (message_id)", "alter table public.custom_order_message_attachments enable row level security", "create or replace function public.custom_order_message_attachment_order_id_from_path(p_name text)\nreturns uuid\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_parts text[];\nbegin\n  v_parts := storage.foldername(coalesce(p_name, ''''));\n  if array_length(v_parts, 1) < 1 then\n    return null;\n  end if;\n  if v_parts[1] !~* ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' then\n    return null;\n  end if;\n  return v_parts[1]::uuid;\nexception\n  when others then\n    return null;\nend;\n$function$", "create or replace function public.custom_order_message_attachment_uploader_id_from_path(p_name text)\nreturns uuid\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_parts text[];\nbegin\n  v_parts := storage.foldername(coalesce(p_name, ''''));\n  if array_length(v_parts, 1) < 2 then\n    return null;\n  end if;\n  if v_parts[2] !~* ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' then\n    return null;\n  end if;\n  return v_parts[2]::uuid;\nexception\n  when others then\n    return null;\nend;\n$function$", "create or replace function public.custom_order_message_attachment_is_party(p_order_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $function$\n  select coalesce((\n    select\n      public.is_admin()\n      or o.student_id = (select auth.uid())\n      or o.mentor_id = (select auth.uid())\n    from public.custom_request_orders o\n    where o.id = p_order_id\n  ), false);\n$function$", "drop policy if exists \"coma_select_party\" on public.custom_order_message_attachments", "create policy \"coma_select_party\" on public.custom_order_message_attachments\n  for select to authenticated\n  using (public.custom_order_message_attachment_is_party(order_id))", "drop policy if exists \"coma_insert_party\" on public.custom_order_message_attachments", "create policy \"coma_insert_party\" on public.custom_order_message_attachments\n  for insert to authenticated\n  with check (\n    uploader_id = (select auth.uid())\n    and public.custom_order_message_attachment_is_party(order_id)\n  )", "drop policy if exists \"coma_delete_uploader_or_admin\" on public.custom_order_message_attachments", "create policy \"coma_delete_uploader_or_admin\" on public.custom_order_message_attachments\n  for delete to authenticated\n  using (\n    uploader_id = (select auth.uid())\n    or public.is_admin()\n  )", "grant select, insert, delete on public.custom_order_message_attachments to authenticated", "grant execute on function public.custom_order_message_attachment_order_id_from_path(text) to authenticated", "grant execute on function public.custom_order_message_attachment_uploader_id_from_path(text) to authenticated", "grant execute on function public.custom_order_message_attachment_is_party(uuid) to authenticated", "drop policy if exists \"custom_order_message_attachments_storage_select_party\" on storage.objects", "create policy \"custom_order_message_attachments_storage_select_party\" on storage.objects\n  for select to authenticated\n  using (\n    bucket_id = ''custom-order-message-attachments''\n    and exists (\n      select 1\n      from public.custom_order_message_attachments a\n      where a.storage_path = storage.objects.name\n        and public.custom_order_message_attachment_is_party(a.order_id)\n    )\n  )", "drop policy if exists \"custom_order_message_attachments_storage_insert_party\" on storage.objects", "create policy \"custom_order_message_attachments_storage_insert_party\" on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = ''custom-order-message-attachments''\n    and public.custom_order_message_attachment_order_id_from_path(name) is not null\n    and public.custom_order_message_attachment_uploader_id_from_path(name) = (select auth.uid())\n    and public.custom_order_message_attachment_is_party(\n      public.custom_order_message_attachment_order_id_from_path(name)\n    )\n  )", "drop policy if exists \"custom_order_message_attachments_storage_delete_uploader_or_admin\" on storage.objects", "create policy \"custom_order_message_attachments_storage_delete_uploader_or_admin\" on storage.objects\n  for delete to authenticated\n  using (\n    bucket_id = ''custom-order-message-attachments''\n    and (\n      exists (\n        select 1\n        from public.custom_order_message_attachments a\n        where a.storage_path = storage.objects.name\n          and (\n            a.uploader_id = (select auth.uid())\n            or public.is_admin()\n          )\n      )\n      or (\n        public.custom_order_message_attachment_uploader_id_from_path(name) = (select auth.uid())\n        and public.custom_order_message_attachment_is_party(\n          public.custom_order_message_attachment_order_id_from_path(name)\n        )\n      )\n    )\n  )", "comment on table public.custom_order_message_attachments is\n  ''Private custom-order chat attachments. Metadata only; file bytes live in custom-order-message-attachments Storage bucket.''", "comment on function public.custom_order_message_attachment_is_party(uuid) is\n  ''Returns true when auth.uid() is custom_request_orders.student_id, custom_request_orders.mentor_id, or admin. Used by order-message attachment table and Storage RLS.''", "commit", "-- >>> NATIVE_BASELINE_PART 0095 | supabase/sql/084_admin_case_notes.sql | 084_admin_case_notes.sql <<<\n-- =============================================================================\n-- 084_admin_case_notes.sql\n-- 목적: 관리자 전용 분쟁·신고 운영 메모 타임라인\n-- 적용: 생성만. Claude 검토 후 Supabase SQL Editor에서 수동 실행.\n-- 선행: 001 auth/users/is_admin(), 004 public.disputes, 032 public.content_reports\n-- 주의: 분쟁/환불/주문/정산 상태 변경 없음. 기존 RLS 정책 완화 없음.\n-- =============================================================================\n\ncreate extension if not exists pgcrypto", "create table if not exists public.admin_case_notes (\n  id uuid primary key default gen_random_uuid(),\n  dispute_id uuid null references public.disputes (id) on delete cascade,\n  report_id uuid null references public.content_reports (id) on delete cascade,\n  note text not null,\n  admin_id uuid null references auth.users (id) on delete set null,\n  created_at timestamptz not null default now(),\n  constraint admin_case_notes_note_nonempty check (char_length(btrim(note)) > 0),\n  constraint admin_case_notes_exactly_one_target check (num_nonnulls(dispute_id, report_id) = 1)\n)", "create index if not exists idx_admin_case_notes_dispute_created\n  on public.admin_case_notes (dispute_id, created_at desc)\n  where dispute_id is not null", "create index if not exists idx_admin_case_notes_report_created\n  on public.admin_case_notes (report_id, created_at desc)\n  where report_id is not null", "create index if not exists idx_admin_case_notes_admin_created\n  on public.admin_case_notes (admin_id, created_at desc)", "alter table public.admin_case_notes enable row level security", "drop policy if exists admin_case_notes_select_admin on public.admin_case_notes", "create policy admin_case_notes_select_admin\n  on public.admin_case_notes\n  for select\n  to authenticated\n  using ((select public.is_admin()) = true)", "drop policy if exists admin_case_notes_insert_admin on public.admin_case_notes", "create policy admin_case_notes_insert_admin\n  on public.admin_case_notes\n  for insert\n  to authenticated\n  with check (\n    (select public.is_admin()) = true\n    and admin_id = (select auth.uid())\n  )", "drop policy if exists admin_case_notes_update_admin on public.admin_case_notes", "create policy admin_case_notes_update_admin\n  on public.admin_case_notes\n  for update\n  to authenticated\n  using ((select public.is_admin()) = true)\n  with check ((select public.is_admin()) = true)", "drop policy if exists admin_case_notes_delete_admin on public.admin_case_notes", "create policy admin_case_notes_delete_admin\n  on public.admin_case_notes\n  for delete\n  to authenticated\n  using ((select public.is_admin()) = true)", "grant select, insert, update, delete on public.admin_case_notes to authenticated", "comment on table public.admin_case_notes is ''관리자 전용 분쟁·신고 운영 메모 타임라인.''", "comment on column public.admin_case_notes.dispute_id is ''분쟁 메모 대상(public.disputes.id). report_id와 둘 중 하나만 사용.''", "comment on column public.admin_case_notes.report_id is ''신고 메모 대상(public.content_reports.id). dispute_id와 둘 중 하나만 사용.''", "comment on column public.admin_case_notes.note is ''관리자 내부 운영 메모. 공개 노출 금지.''", "comment on column public.admin_case_notes.admin_id is ''메모 작성 관리자 auth.users.id.''", "-- >>> NATIVE_BASELINE_PART 0096 | supabase/sql/085_connection_notes_author_rls.sql | 085_connection_notes_author_rls.sql <<<\n-- =============================================================================\n-- 085_connection_notes_author_rls.sql\n--\n-- C-5/H-3 security hardening: connection_notes write policies must verify the\n-- authenticated writer, not only room membership.\n--\n-- Background:\n--   - 002 created cn_insert/cn_update/cn_delete with room-party checks only.\n--   - 048 added nullable author_id / author_role.\n--   - 076 narrowed update/delete to author_id = auth.uid(), but cn_insert still\n--     allowed a room party to submit another participant''s author_id.\n--\n-- This file replaces only write policies. cn_select is intentionally left as-is:\n-- room participants may continue to read each other''s connection notes.\n-- Existing SQL files are not modified.\n-- =============================================================================\n\n-- Review before execution:\n-- select policyname, cmd, qual, with_check\n-- from pg_policies\n-- where schemaname = ''public'' and tablename = ''connection_notes''\n-- order by cmd, policyname;\n\nalter table public.connection_notes enable row level security", "-- Insert: a room participant may create only their own note.\ndrop policy if exists \"cn_insert\" on public.connection_notes", "create policy \"cn_insert\" on public.connection_notes\n  for insert to authenticated\n  with check (\n    author_id = (select auth.uid())\n    and exists (\n      select 1\n      from public.mentor_student_rooms r\n      where r.id = mentor_student_room_id\n        and (select auth.uid()) in (r.student_id, r.mentor_id)\n    )\n  )", "-- Update: only the original author may update their own note, while still being\n-- a participant of the note''s room. The WITH CHECK clause prevents changing the\n-- row into a state owned by another author or outside the actor''s rooms.\ndrop policy if exists \"cn_update\" on public.connection_notes", "create policy \"cn_update\" on public.connection_notes\n  for update to authenticated\n  using (\n    author_id = (select auth.uid())\n    and exists (\n      select 1\n      from public.mentor_student_rooms r\n      where r.id = connection_notes.mentor_student_room_id\n        and (select auth.uid()) in (r.student_id, r.mentor_id)\n    )\n  )\n  with check (\n    author_id = (select auth.uid())\n    and exists (\n      select 1\n      from public.mentor_student_rooms r\n      where r.id = mentor_student_room_id\n        and (select auth.uid()) in (r.student_id, r.mentor_id)\n    )\n  )", "-- Delete: only the original author may delete their own note, while still being\n-- a participant of the note''s room.\ndrop policy if exists \"cn_delete\" on public.connection_notes", "create policy \"cn_delete\" on public.connection_notes\n  for delete to authenticated\n  using (\n    author_id = (select auth.uid())\n    and exists (\n      select 1\n      from public.mentor_student_rooms r\n      where r.id = connection_notes.mentor_student_room_id\n        and (select auth.uid()) in (r.student_id, r.mentor_id)\n    )\n  )", "-- Verify after execution:\n-- select policyname, cmd, qual, with_check\n-- from pg_policies\n-- where schemaname = ''public'' and tablename = ''connection_notes''\n--   and policyname in (''cn_select'', ''cn_insert'', ''cn_update'', ''cn_delete'')\n-- order by cmd, policyname;\n--\n-- Expected behavior:\n--   - Same-room student inserting a mentor author_id is rejected.\n--   - Same-room participant updating/deleting someone else''s note is rejected.\n--   - The original author can create/update/delete their own note.\n--   - cn_select remains participant-readable and is not recreated here.\n-- =============================================================================\n\n-- >>> NATIVE_BASELINE_PART 0097 | supabase/sql/086_subscription_settlement_items.sql | 086_subscription_settlement_items.sql <<<\n-- =============================================================================\n-- 086_subscription_settlement_items.sql\n-- Purpose: Subscription billing event -> mentor settlement ledger.\n-- Scope:\n--   - Create subscription_settlement_items.\n--   - Create service_role-only refresh/aggregate RPC.\n--   - Record settlement state only. No bank transfer, no cash_ledger mutation.\n--   - Do not touch escrow(054~057), 070, refund RPC(030/068/069), or 077.\n-- Prerequisite:\n--   - 064_subscription_billing_period_schema.sql\n--   - 068_subscription_renewal_rpc.sql\n--   - 069_subscription_cancel_refund_request.sql\n-- =============================================================================\n\nbegin", "create table if not exists public.subscription_settlement_items (\n  id uuid primary key default gen_random_uuid(),\n  billing_event_id uuid not null references public.subscription_billing_events(id) on delete restrict,\n  subscription_id uuid not null references public.subscriptions(id) on delete restrict,\n  mentor_id uuid not null references public.users(id) on delete restrict,\n  student_id uuid references public.users(id) on delete set null,\n  payment_id uuid references public.payments(id) on delete set null,\n  ledger_id uuid references public.cash_ledger(id) on delete set null,\n  event_type text not null check (event_type in (''initial'', ''renewal'')),\n  billing_at timestamptz not null,\n  period_start timestamptz,\n  period_end timestamptz,\n  gross_cents bigint not null,\n  platform_fee_cents bigint not null,\n  mentor_amount_cents bigint not null,\n  fee_rate numeric not null default 0.30,\n  status text not null default ''pending'' check (status in (''pending'', ''paid'', ''hold'', ''canceled'')),\n  hold_reason text,\n  paid_at timestamptz,\n  idempotency_key text not null unique,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint ssi_unique_billing_event unique (billing_event_id),\n  constraint ssi_amounts_core check (\n    gross_cents > 0\n    and platform_fee_cents >= 0\n    and mentor_amount_cents > 0\n    and platform_fee_cents + mentor_amount_cents = gross_cents\n  ),\n  constraint ssi_fee_rate_bounds check (fee_rate >= 0 and fee_rate <= 1),\n  constraint ssi_paid_at_required check (status <> ''paid'' or paid_at is not null)\n)", "comment on table public.subscription_settlement_items is\n  ''Mentor settlement ledger for succeeded subscription billing events. This records payable state only; actual transfer is separate.''", "comment on column public.subscription_settlement_items.billing_event_id is\n  ''One settlement item per succeeded subscription_billing_events row. Unique/idempotent source key.''", "comment on column public.subscription_settlement_items.gross_cents is\n  ''Gross subscription billing amount in minor units. Source: subscription_billing_events.amount_cents.''", "comment on column public.subscription_settlement_items.platform_fee_cents is\n  ''floor(gross_cents * 0.30). Fee rounding follows custom order settlement 043.''", "comment on column public.subscription_settlement_items.mentor_amount_cents is\n  ''gross_cents - platform_fee_cents. Remainder belongs to mentor.''", "comment on column public.subscription_settlement_items.status is\n  ''pending=payable later, paid=transfer completed, hold=refund/cancel/manual review hold, canceled=not payable.''", "create unique index if not exists uq_ssi_billing_event\n  on public.subscription_settlement_items (billing_event_id)", "create index if not exists idx_ssi_mentor_created\n  on public.subscription_settlement_items (mentor_id, created_at desc)", "create index if not exists idx_ssi_mentor_status_created\n  on public.subscription_settlement_items (mentor_id, status, created_at desc)", "create index if not exists idx_ssi_subscription_period\n  on public.subscription_settlement_items (subscription_id, period_start, period_end)", "create index if not exists idx_ssi_billing_at\n  on public.subscription_settlement_items (billing_at desc)", "drop trigger if exists trg_ssi_set_updated on public.subscription_settlement_items", "create trigger trg_ssi_set_updated\n  before update on public.subscription_settlement_items\n  for each row execute function public.set_updated_at()", "alter table public.subscription_settlement_items enable row level security", "revoke all on table public.subscription_settlement_items from anon", "revoke insert, update, delete on table public.subscription_settlement_items from authenticated", "grant select on table public.subscription_settlement_items to authenticated", "grant all on table public.subscription_settlement_items to service_role", "drop policy if exists \"ssi_select_mentor_own\" on public.subscription_settlement_items", "create policy \"ssi_select_mentor_own\"\n  on public.subscription_settlement_items\n  for select\n  to authenticated\n  using (mentor_id = (select auth.uid()))", "-- No INSERT/UPDATE/DELETE policies for authenticated users.\n-- Admin read/write remains server-side service_role only.\n\ncreate or replace function public.refresh_subscription_settlement_items(\n  p_from timestamptz default null,\n  p_to timestamptz default null\n)\nreturns table (\n  item_status text,\n  item_count bigint,\n  gross_cents bigint,\n  platform_fee_cents bigint,\n  mentor_amount_cents bigint\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\nbegin\n  with source_events as (\n    select\n      e.id as billing_event_id,\n      e.subscription_id,\n      e.student_id,\n      e.mentor_id,\n      e.payment_id,\n      e.ledger_id,\n      e.event_type,\n      coalesce(e.billing_at, e.processed_at, e.created_at) as billing_at,\n      e.period_start,\n      e.period_end,\n      e.amount_cents::bigint as gross_cents,\n      lower(coalesce(s.status, '''')) as subscription_status,\n      coalesce(s.cancel_at_period_end, false) as cancel_at_period_end,\n      coalesce(rf.has_pending_refund, false) as has_pending_refund,\n      coalesce(rf.has_succeeded_refund, false) as has_succeeded_refund\n    from public.subscription_billing_events e\n    join public.subscriptions s on s.id = e.subscription_id\n    left join lateral (\n      select\n        bool_or(lower(coalesce(r.status, '''')) = ''pending'') as has_pending_refund,\n        bool_or(lower(coalesce(r.status, '''')) in (''succeeded'', ''success'', ''approved'', ''paid'')) as has_succeeded_refund\n      from public.refunds r\n      where coalesce(r.request_type, '''') = ''subscription_prorated''\n        and (\n          r.subscription_id = e.subscription_id\n          or (\n            r.subscription_id is null\n            and r.payment_id is not null\n            and r.payment_id = e.payment_id\n          )\n        )\n    ) rf on true\n    where e.status = ''succeeded''\n      and e.event_type in (''initial'', ''renewal'')\n      and coalesce(e.amount_cents, 0) > 0\n      and (p_from is null or coalesce(e.billing_at, e.processed_at, e.created_at) >= p_from)\n      and (p_to is null or coalesce(e.billing_at, e.processed_at, e.created_at) < p_to)\n  ), calculated as (\n    select\n      se.*,\n      floor(se.gross_cents::numeric * 0.30)::bigint as platform_fee_cents,\n      (se.gross_cents - floor(se.gross_cents::numeric * 0.30)::bigint) as mentor_amount_cents,\n      case\n        when se.has_succeeded_refund or se.subscription_status = ''refunded'' then ''canceled''\n        when se.has_pending_refund then ''hold''\n        when se.subscription_status in (''cancel_scheduled'', ''canceled'', ''cancelled'', ''expired'') then ''hold''\n        when se.cancel_at_period_end then ''hold''\n        else ''pending''\n      end as sync_status,\n      case\n        when se.has_succeeded_refund or se.subscription_status = ''refunded'' then ''refund_succeeded''\n        when se.has_pending_refund then ''refund_pending''\n        when se.subscription_status in (''cancel_scheduled'', ''canceled'', ''cancelled'', ''expired'') then ''subscription_canceled_or_expired''\n        when se.cancel_at_period_end then ''cancel_at_period_end''\n        else null\n      end as sync_hold_reason\n    from source_events se\n  )\n  insert into public.subscription_settlement_items (\n    billing_event_id,\n    subscription_id,\n    mentor_id,\n    student_id,\n    payment_id,\n    ledger_id,\n    event_type,\n    billing_at,\n    period_start,\n    period_end,\n    gross_cents,\n    platform_fee_cents,\n    mentor_amount_cents,\n    fee_rate,\n    status,\n    hold_reason,\n    idempotency_key\n  )\n  select\n    c.billing_event_id,\n    c.subscription_id,\n    c.mentor_id,\n    c.student_id,\n    c.payment_id,\n    c.ledger_id,\n    c.event_type,\n    c.billing_at,\n    c.period_start,\n    c.period_end,\n    c.gross_cents,\n    c.platform_fee_cents,\n    c.mentor_amount_cents,\n    0.30,\n    c.sync_status,\n    c.sync_hold_reason,\n    ''sub_settlement:'' || c.billing_event_id::text\n  from calculated c\n  on conflict (billing_event_id) do nothing;\n\n  with source_events as (\n    select\n      e.id as billing_event_id,\n      lower(coalesce(s.status, '''')) as subscription_status,\n      coalesce(s.cancel_at_period_end, false) as cancel_at_period_end,\n      coalesce(rf.has_pending_refund, false) as has_pending_refund,\n      coalesce(rf.has_succeeded_refund, false) as has_succeeded_refund\n    from public.subscription_billing_events e\n    join public.subscriptions s on s.id = e.subscription_id\n    left join lateral (\n      select\n        bool_or(lower(coalesce(r.status, '''')) = ''pending'') as has_pending_refund,\n        bool_or(lower(coalesce(r.status, '''')) in (''succeeded'', ''success'', ''approved'', ''paid'')) as has_succeeded_refund\n      from public.refunds r\n      where coalesce(r.request_type, '''') = ''subscription_prorated''\n        and (\n          r.subscription_id = e.subscription_id\n          or (\n            r.subscription_id is null\n            and r.payment_id is not null\n            and r.payment_id = e.payment_id\n          )\n        )\n    ) rf on true\n    where e.status = ''succeeded''\n      and e.event_type in (''initial'', ''renewal'')\n      and coalesce(e.amount_cents, 0) > 0\n      and (p_from is null or coalesce(e.billing_at, e.processed_at, e.created_at) >= p_from)\n      and (p_to is null or coalesce(e.billing_at, e.processed_at, e.created_at) < p_to)\n  ), calculated as (\n    select\n      se.billing_event_id,\n      case\n        when se.has_succeeded_refund or se.subscription_status = ''refunded'' then ''canceled''\n        when se.has_pending_refund then ''hold''\n        when se.subscription_status in (''cancel_scheduled'', ''canceled'', ''cancelled'', ''expired'') then ''hold''\n        when se.cancel_at_period_end then ''hold''\n        else ''pending''\n      end as sync_status,\n      case\n        when se.has_succeeded_refund or se.subscription_status = ''refunded'' then ''refund_succeeded''\n        when se.has_pending_refund then ''refund_pending''\n        when se.subscription_status in (''cancel_scheduled'', ''canceled'', ''cancelled'', ''expired'') then ''subscription_canceled_or_expired''\n        when se.cancel_at_period_end then ''cancel_at_period_end''\n        else null\n      end as sync_hold_reason\n    from source_events se\n  )\n  update public.subscription_settlement_items i\n  set\n    status = c.sync_status,\n    hold_reason = c.sync_hold_reason,\n    updated_at = now()\n  from calculated c\n  where i.billing_event_id = c.billing_event_id\n    and i.status <> ''paid''\n    and (\n      (c.sync_status = ''canceled'' and i.status <> ''canceled'')\n      or (c.sync_status = ''hold'' and i.status = ''pending'')\n    );\n\n  return query\n  select\n    i.status::text as item_status,\n    count(*)::bigint as item_count,\n    coalesce(sum(i.gross_cents), 0)::bigint as gross_cents,\n    coalesce(sum(i.platform_fee_cents), 0)::bigint as platform_fee_cents,\n    coalesce(sum(i.mentor_amount_cents), 0)::bigint as mentor_amount_cents\n  from public.subscription_settlement_items i\n  where (p_from is null or i.billing_at >= p_from)\n    and (p_to is null or i.billing_at < p_to)\n  group by i.status\n  order by i.status;\nend;\n$function$", "comment on function public.refresh_subscription_settlement_items(timestamptz, timestamptz) is\n  ''Service-role-only idempotent sync from succeeded subscription_billing_events to subscription_settlement_items. Does not transfer money or mutate cash_ledger.''", "revoke all on function public.refresh_subscription_settlement_items(timestamptz, timestamptz) from public, anon, authenticated", "grant execute on function public.refresh_subscription_settlement_items(timestamptz, timestamptz) to service_role", "commit", "-- >>> NATIVE_BASELINE_PART 0098 | supabase/sql/087_user_consent_records.sql | 087_user_consent_records.sql <<<\n-- =============================================================================\n-- 087_user_consent_records.sql\n-- Purpose: Signup consent ledger skeleton, including under-14 guardian consent.\n-- Scope:\n--   - Create user_consent_records.\n--   - Persist signup consent records from auth.users raw_user_meta_data.\n--   - Legal wording / guardian verification details remain placeholders.\n--   - No auth/session core changes, no payment/escrow/070/077 changes.\n-- =============================================================================\n\nbegin", "create table if not exists public.user_consent_records (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users(id) on delete cascade,\n  consent_type text not null check (consent_type in (''terms'', ''privacy'', ''marketing'', ''minor_guardian_consent'')),\n  consent_actor text not null check (consent_actor in (''user'', ''guardian'')),\n  is_minor boolean not null default false,\n  guardian_consent boolean not null default false,\n  consent_version text not null,\n  guardian_ref text,\n  agreed_at timestamptz not null default now(),\n  source text not null default ''signup'',\n  metadata jsonb not null default ''{}''::jsonb,\n  idempotency_key text not null unique,\n  created_at timestamptz not null default now()\n)", "comment on table public.user_consent_records is\n  ''Append-only signup consent ledger. Includes under-14 guardian consent skeleton; legal wording and verification method are placeholders.''", "comment on column public.user_consent_records.guardian_ref is\n  ''Reserved for legal-approved guardian identity/verification reference. Keep null until legal chooses the method.''", "comment on column public.user_consent_records.metadata is\n  ''Non-public operational metadata for consent provenance. Do not expose publicly.''", "create index if not exists idx_ucr_user_created\n  on public.user_consent_records (user_id, created_at desc)", "create index if not exists idx_ucr_user_type_created\n  on public.user_consent_records (user_id, consent_type, created_at desc)", "alter table public.user_consent_records enable row level security", "revoke all on table public.user_consent_records from anon", "revoke insert, update, delete on table public.user_consent_records from authenticated", "grant select on table public.user_consent_records to authenticated", "grant all on table public.user_consent_records to service_role", "drop policy if exists \"ucr_select_own\" on public.user_consent_records", "create policy \"ucr_select_own\"\n  on public.user_consent_records\n  for select\n  to authenticated\n  using (user_id = (select auth.uid()))", "-- No authenticated write policy. Signup writes are handled by SECURITY DEFINER trigger;\n-- admin/server maintenance remains service_role only.\n\ncreate or replace function public.handle_new_auth_user_consent_records()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  m jsonb;\n  v_role text;\n  v_birth_date date;\n  v_is_minor boolean := false;\n  v_version text;\n  v_agreed_at timestamptz := now();\n  v_metadata jsonb;\nbegin\n  m := coalesce(new.raw_user_meta_data, ''{}''::jsonb);\n  v_role := lower(coalesce(nullif(trim(m->>''app_role''), ''''), ''student''));\n  v_version := coalesce(nullif(trim(m->>''consent_version''), ''''), ''legal-placeholder-2026-06-20'');\n\n  begin\n    v_birth_date := nullif(trim(m->>''birth_date''), '''')::date;\n  exception when others then\n    v_birth_date := null;\n  end;\n\n  v_is_minor := coalesce(\n    nullif(trim(m->>''is_minor''), '''')::boolean,\n    case when v_birth_date is not null\n         then (current_date < (v_birth_date + interval ''14 years'')::date)\n         else false end\n  );\n\n  v_metadata := jsonb_build_object(\n    ''role'', v_role,\n    ''birth_date'', case when v_birth_date is not null then v_birth_date::text else null end,\n    ''age_gate_checked_at'', nullif(trim(m->>''age_gate_checked_at''), ''''),\n    ''verification_method'', coalesce(nullif(trim(m->>''guardian_verification_method''), ''''), ''legal_review_pending'')\n  );\n\n  if (m->>''terms_agreed'') = ''true'' then\n    insert into public.user_consent_records (\n      user_id, consent_type, consent_actor, is_minor, guardian_consent,\n      consent_version, agreed_at, source, metadata, idempotency_key\n    ) values (\n      new.id, ''terms'', ''user'', v_is_minor, false,\n      v_version, v_agreed_at, ''signup'', v_metadata, ''signup:'' || new.id::text || '':terms:'' || v_version\n    ) on conflict (idempotency_key) do nothing;\n  end if;\n\n  if (m->>''privacy_agreed'') = ''true'' then\n    insert into public.user_consent_records (\n      user_id, consent_type, consent_actor, is_minor, guardian_consent,\n      consent_version, agreed_at, source, metadata, idempotency_key\n    ) values (\n      new.id, ''privacy'', ''user'', v_is_minor, false,\n      v_version, v_agreed_at, ''signup'', v_metadata, ''signup:'' || new.id::text || '':privacy:'' || v_version\n    ) on conflict (idempotency_key) do nothing;\n  end if;\n\n  if (m->>''marketing_agreed'') = ''true'' then\n    insert into public.user_consent_records (\n      user_id, consent_type, consent_actor, is_minor, guardian_consent,\n      consent_version, agreed_at, source, metadata, idempotency_key\n    ) values (\n      new.id, ''marketing'', ''user'', v_is_minor, false,\n      v_version, v_agreed_at, ''signup'', v_metadata, ''signup:'' || new.id::text || '':marketing:'' || v_version\n    ) on conflict (idempotency_key) do nothing;\n  end if;\n\n  if v_is_minor and (m->>''guardian_consent'') = ''true'' then\n    insert into public.user_consent_records (\n      user_id, consent_type, consent_actor, is_minor, guardian_consent,\n      consent_version, guardian_ref, agreed_at, source, metadata, idempotency_key\n    ) values (\n      new.id, ''minor_guardian_consent'', ''guardian'', true, true,\n      v_version, nullif(trim(m->>''guardian_ref''), ''''), v_agreed_at, ''signup'', v_metadata,\n      ''signup:'' || new.id::text || '':minor_guardian_consent:'' || v_version\n    ) on conflict (idempotency_key) do nothing;\n  end if;\n\n  return new;\nend;\n$function$", "comment on function public.handle_new_auth_user_consent_records() is\n  ''Signup consent ledger trigger. Stores terms/privacy/marketing and under-14 guardian consent skeleton from auth metadata.''", "revoke all on function public.handle_new_auth_user_consent_records() from public, anon, authenticated", "grant execute on function public.handle_new_auth_user_consent_records() to service_role", "drop trigger if exists zz_on_auth_user_created_consent_records on auth.users", "create trigger zz_on_auth_user_created_consent_records\n  after insert on auth.users\n  for each row execute function public.handle_new_auth_user_consent_records()", "commit", "-- >>> NATIVE_BASELINE_PART 0099 | supabase/sql/088_custom_order_status_transition_rpcs.sql | 088_custom_order_status_transition_rpcs.sql <<<\n-- =============================================================================\n-- 088_custom_order_status_transition_rpcs.sql\n-- Purpose: Move custom_request_orders party status transitions behind RPCs (M-1 step 1).\n-- Scope:\n--   - Add SECURITY DEFINER RPCs for existing party status transitions.\n--   - Preserve current transition rules before later RLS lockdown.\n--   - Do not change RLS policies or table grants in this step.\n--   - No escrow/refund/settlement/cash_ledger changes.\n-- =============================================================================\n\nbegin", "create or replace function public._cro_transition_primary_status_col(o public.custom_request_orders)\nreturns text\nlanguage plpgsql\nstable\nset search_path = public\nas $function$\nbegin\n  if o.status is not null and btrim(o.status) <> '''' then\n    return ''status'';\n  elsif o.state is not null and btrim(o.state) <> '''' then\n    return ''state'';\n  elsif o.order_status is not null and btrim(o.order_status) <> '''' then\n    return ''order_status'';\n  elsif o.stage is not null and btrim(o.stage) <> '''' then\n    return ''stage'';\n  end if;\n  return null;\nend;\n$function$", "create or replace function public._cro_transition_primary_status_norm(o public.custom_request_orders)\nreturns text\nlanguage plpgsql\nstable\nset search_path = public\nas $function$\ndeclare\n  v_col text;\nbegin\n  v_col := public._cro_transition_primary_status_col(o);\n  if v_col = ''status'' then\n    return lower(btrim(o.status));\n  elsif v_col = ''state'' then\n    return lower(btrim(o.state));\n  elsif v_col = ''order_status'' then\n    return lower(btrim(o.order_status));\n  elsif v_col = ''stage'' then\n    return lower(btrim(o.stage));\n  end if;\n  return '''';\nend;\n$function$", "create or replace function public._cro_transition_is_terminal(o public.custom_request_orders)\nreturns boolean\nlanguage plpgsql\nstable\nset search_path = public\nas $function$\ndeclare\n  v_terminal text[] := array[\n    ''completed'', ''accepted'', ''closed'', ''finished'', ''cancelled'', ''canceled'',\n    ''refunded'', ''rejected'', ''done'', ''resolved'', ''dispute_resolved''\n  ];\nbegin\n  if lower(btrim(coalesce(o.status, ''''))) = any(v_terminal) then\n    return true;\n  elsif lower(btrim(coalesce(o.state, ''''))) = any(v_terminal) then\n    return true;\n  elsif lower(btrim(coalesce(o.order_status, ''''))) = any(v_terminal) then\n    return true;\n  elsif lower(btrim(coalesce(o.stage, ''''))) = any(v_terminal) then\n    return true;\n  elsif o.completed_at is not null or o.closed_at is not null or o.finished_at is not null then\n    return true;\n  end if;\n  return false;\nend;\n$function$", "create or replace function public._cro_transition_payment_confirmed(o public.custom_request_orders)\nreturns boolean\nlanguage plpgsql\nstable\nset search_path = public\nas $function$\ndeclare\n  v_confirmed text[] := array[''paid'', ''succeeded'', ''escrowed'', ''completed'', ''complete'', ''success'', ''captured'', ''paid_out''];\nbegin\n  if lower(btrim(coalesce(o.payment_status, ''''))) = any(v_confirmed) then\n    return true;\n  end if;\n  return false;\nend;\n$function$", "create or replace function public._cro_transition_actor_is_mentor(o public.custom_request_orders, p_actor uuid)\nreturns boolean\nlanguage sql\nstable\nset search_path = public\nas $function$\n  select p_actor is not null and (\n    o.mentor_id = p_actor\n    or o.selected_mentor_id = p_actor\n    or o.assigned_mentor_id = p_actor\n    or o.expert_id = p_actor\n  );\n$function$", "create or replace function public._cro_transition_actor_is_student(o public.custom_request_orders, p_actor uuid)\nreturns boolean\nlanguage sql\nstable\nset search_path = public\nas $function$\n  select p_actor is not null and (\n    o.student_id = p_actor\n    or o.buyer_id = p_actor\n    or o.client_id = p_actor\n    or o.user_id = p_actor\n    or o.author_id = p_actor\n    or o.requester_id = p_actor\n  );\n$function$", "create or replace function public._cro_transition_has_active_dispute(p_order_id uuid)\nreturns boolean\nlanguage sql\nstable\nset search_path = public\nas $function$\n  select exists (\n    select 1\n    from public.disputes d\n    where d.custom_request_order_id = p_order_id\n      and d.status in (''open'', ''under_review'', ''escalated'')\n  );\n$function$", "create or replace function public._cro_transition_deliverable_count(p_order_id uuid)\nreturns integer\nlanguage sql\nstable\nset search_path = public\nas $function$\n  select count(*)::integer\n  from public.custom_order_deliverables d\n  where d.custom_request_order_id = p_order_id;\n$function$", "create or replace function public._cro_transition_revision_count(p_order_id uuid)\nreturns integer\nlanguage sql\nstable\nset search_path = public\nas $function$\n  select count(*)::integer\n  from public.custom_order_revisions r\n  where r.custom_request_order_id = p_order_id;\n$function$", "create or replace function public.custom_order_mentor_start(p_order_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_actor uuid := auth.uid();\n  o public.custom_request_orders%rowtype;\n  v_primary_col text;\n  v_norm text;\n  v_now timestamptz := now();\nbegin\n  if v_actor is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''P0001'';\n  end if;\n\n  select * into o\n  from public.custom_request_orders\n  where id = p_order_id\n  for update;\n\n  if not found then\n    raise exception ''ORDER_NOT_FOUND'' using errcode = ''P0001'';\n  end if;\n\n  if not public._cro_transition_actor_is_mentor(o, v_actor) then\n    raise exception ''ORDER_MENTOR_FORBIDDEN'' using errcode = ''P0001'';\n  end if;\n\n  if public._cro_transition_has_active_dispute(p_order_id) then\n    raise exception ''ORDER_HAS_ACTIVE_DISPUTE'' using errcode = ''P0001'';\n  end if;\n\n  if not public._cro_transition_payment_confirmed(o) then\n    raise exception ''ORDER_PAYMENT_NOT_CONFIRMED'' using errcode = ''P0001'';\n  end if;\n\n  if public._cro_transition_is_terminal(o) then\n    raise exception ''ORDER_TERMINAL'' using errcode = ''P0001'';\n  end if;\n\n  v_primary_col := public._cro_transition_primary_status_col(o);\n  v_norm := public._cro_transition_primary_status_norm(o);\n\n  if v_primary_col is null or v_norm = '''' then\n    raise exception ''ORDER_STATUS_COLUMN_MISSING'' using errcode = ''P0001'';\n  end if;\n\n  if v_norm = ''open'' then\n    raise exception ''ORDER_ALREADY_STARTED'' using errcode = ''P0001'';\n  end if;\n\n  if v_norm <> ''pending'' then\n    raise exception ''ORDER_STATUS_NOT_STARTABLE'' using errcode = ''P0001'';\n  end if;\n\n  update public.custom_request_orders\n  set\n    status = case when v_primary_col = ''status'' then ''open'' else status end,\n    state = case when v_primary_col = ''state'' then ''open'' else state end,\n    order_status = case when v_primary_col = ''order_status'' then ''open'' else order_status end,\n    stage = case when v_primary_col = ''stage'' then ''open'' else stage end,\n    started_at = v_now\n  where id = p_order_id;\n\n  return jsonb_build_object(''ok'', true, ''transition'', ''mentor_start'', ''from'', v_norm, ''to'', ''open'');\nend;\n$function$", "create or replace function public.custom_order_mentor_deliver(p_order_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_actor uuid := auth.uid();\n  o public.custom_request_orders%rowtype;\n  v_primary_col text;\n  v_norm text;\nbegin\n  if v_actor is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''P0001'';\n  end if;\n\n  select * into o\n  from public.custom_request_orders\n  where id = p_order_id\n  for update;\n\n  if not found then\n    raise exception ''ORDER_NOT_FOUND'' using errcode = ''P0001'';\n  end if;\n\n  if not public._cro_transition_actor_is_mentor(o, v_actor) then\n    raise exception ''ORDER_MENTOR_FORBIDDEN'' using errcode = ''P0001'';\n  end if;\n\n  if public._cro_transition_is_terminal(o) then\n    raise exception ''ORDER_TERMINAL'' using errcode = ''P0001'';\n  end if;\n\n  if public._cro_transition_deliverable_count(p_order_id) < 1 then\n    raise exception ''ORDER_DELIVERABLE_REQUIRED'' using errcode = ''P0001'';\n  end if;\n\n  v_primary_col := public._cro_transition_primary_status_col(o);\n  v_norm := public._cro_transition_primary_status_norm(o);\n\n  update public.custom_request_orders\n  set\n    order_status = ''delivered'',\n    status = case when v_primary_col = ''status'' then ''delivered'' else status end,\n    state = case when v_primary_col = ''state'' then ''delivered'' else state end,\n    stage = case when v_primary_col = ''stage'' then ''delivered'' else stage end\n  where id = p_order_id;\n\n  return jsonb_build_object(''ok'', true, ''transition'', ''mentor_deliver'', ''from'', v_norm, ''to'', ''delivered'');\nend;\n$function$", "create or replace function public.custom_order_student_request_revision(\n  p_order_id uuid,\n  p_note text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_actor uuid := auth.uid();\n  o public.custom_request_orders%rowtype;\n  v_norm text;\n  v_note text := btrim(coalesce(p_note, ''''));\n  v_revision_id uuid;\nbegin\n  if v_actor is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''P0001'';\n  end if;\n\n  if v_note = '''' then\n    raise exception ''REVISION_NOTE_REQUIRED'' using errcode = ''P0001'';\n  end if;\n\n  if char_length(v_note) > 8000 then\n    raise exception ''REVISION_NOTE_TOO_LONG'' using errcode = ''P0001'';\n  end if;\n\n  select * into o\n  from public.custom_request_orders\n  where id = p_order_id\n  for update;\n\n  if not found then\n    raise exception ''ORDER_NOT_FOUND'' using errcode = ''P0001'';\n  end if;\n\n  if not public._cro_transition_actor_is_student(o, v_actor) then\n    raise exception ''ORDER_STUDENT_FORBIDDEN'' using errcode = ''P0001'';\n  end if;\n\n  if public._cro_transition_has_active_dispute(p_order_id) then\n    raise exception ''ORDER_HAS_ACTIVE_DISPUTE'' using errcode = ''P0001'';\n  end if;\n\n  v_norm := public._cro_transition_primary_status_norm(o);\n  if v_norm = '''' then\n    raise exception ''ORDER_STATUS_COLUMN_MISSING'' using errcode = ''P0001'';\n  end if;\n\n  if public._cro_transition_is_terminal(o) then\n    raise exception ''ORDER_TERMINAL'' using errcode = ''P0001'';\n  end if;\n\n  if v_norm not in (\n    ''delivered'', ''delivered_pending_review'', ''waiting_review'', ''pending_review'',\n    ''redelivered'', ''delivery_submitted'', ''in_review''\n  ) then\n    raise exception ''ORDER_STATUS_NOT_REVISIONABLE'' using errcode = ''P0001'';\n  end if;\n\n  if public._cro_transition_deliverable_count(p_order_id) < 1 then\n    raise exception ''ORDER_DELIVERABLE_REQUIRED'' using errcode = ''P0001'';\n  end if;\n\n  if public._cro_transition_revision_count(p_order_id) >= 2 then\n    raise exception ''REVISION_LIMIT_EXCEEDED'' using errcode = ''P0001'';\n  end if;\n\n  if lower(btrim(coalesce(o.order_status, ''''))) <> ''delivered'' then\n    raise exception ''ORDER_STATUS_NOT_DELIVERED'' using errcode = ''P0001'';\n  end if;\n\n  insert into public.custom_order_revisions (\n    custom_request_order_id,\n    order_id,\n    custom_order_id,\n    request_order_id,\n    author_id,\n    request_note,\n    status\n  ) values (\n    p_order_id,\n    p_order_id,\n    p_order_id,\n    p_order_id,\n    v_actor,\n    v_note,\n    ''open''\n  ) returning id into v_revision_id;\n\n  update public.custom_request_orders\n  set order_status = ''revision_requested''\n  where id = p_order_id\n    and order_status = ''delivered'';\n\n  if not found then\n    raise exception ''ORDER_STATUS_NOT_DELIVERED'' using errcode = ''P0001'';\n  end if;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''transition'', ''student_request_revision'',\n    ''from'', v_norm,\n    ''to'', ''revision_requested'',\n    ''revision_id'', v_revision_id\n  );\nend;\n$function$", "comment on function public.custom_order_mentor_start(uuid) is\n  ''M-1 step 1: mentor-owned custom order work-start transition. Authenticated caller only; validates actor, payment, dispute, and current status.''", "comment on function public.custom_order_mentor_deliver(uuid) is\n  ''M-1 step 1: mentor-owned custom order delivered transition. Authenticated caller only; validates actor, terminal state, and deliverable existence.''", "comment on function public.custom_order_student_request_revision(uuid, text) is\n  ''M-1 step 1: student-owned custom order revision request transition. Inserts revision row and updates order_status atomically.''", "revoke all on function public._cro_transition_primary_status_col(public.custom_request_orders) from public, anon, authenticated", "revoke all on function public._cro_transition_primary_status_norm(public.custom_request_orders) from public, anon, authenticated", "revoke all on function public._cro_transition_is_terminal(public.custom_request_orders) from public, anon, authenticated", "revoke all on function public._cro_transition_payment_confirmed(public.custom_request_orders) from public, anon, authenticated", "revoke all on function public._cro_transition_actor_is_mentor(public.custom_request_orders, uuid) from public, anon, authenticated", "revoke all on function public._cro_transition_actor_is_student(public.custom_request_orders, uuid) from public, anon, authenticated", "revoke all on function public._cro_transition_has_active_dispute(uuid) from public, anon, authenticated", "revoke all on function public._cro_transition_deliverable_count(uuid) from public, anon, authenticated", "revoke all on function public._cro_transition_revision_count(uuid) from public, anon, authenticated", "revoke all on function public.custom_order_mentor_start(uuid) from public, anon", "revoke all on function public.custom_order_mentor_deliver(uuid) from public, anon", "revoke all on function public.custom_order_student_request_revision(uuid, text) from public, anon", "grant execute on function public.custom_order_mentor_start(uuid) to authenticated, service_role", "grant execute on function public.custom_order_mentor_deliver(uuid) to authenticated, service_role", "grant execute on function public.custom_order_student_request_revision(uuid, text) to authenticated, service_role", "commit", "-- >>> NATIVE_BASELINE_PART 0100 | supabase/sql/089_mentor_academic_record_change_requests.sql | 089_mentor_academic_record_change_requests.sql <<<\n-- =============================================================================\n-- 089_mentor_academic_record_change_requests.sql\n-- Purpose: Mentor academic-record change requests (편입/졸업/전과 등으로 학교 변경).\n-- Scope: creates only a new table, indexes, table-local triggers, and RLS policies.\n-- Apply: run manually in Supabase SQL Editor after 001(users, set_updated_at)\n--        and an is_admin() migration such as 003/004.\n-- Notes:\n--   - Mirrors 077_mentor_school_verification.sql structure.\n--   - Does not modify mentor_profiles, public mentor RPCs, payments, escrow, or 070 RPCs.\n--   - mentor_profiles.university_name 은 멘토가 직접 못 바꾸고, 관리자가 이 요청을\n--     승인할 때만 approved_university_name 값으로 갱신한다(앱 서버 액션에서 처리).\n-- =============================================================================\n\ncreate table if not exists public.mentor_academic_record_change_requests (\n  id uuid primary key default gen_random_uuid(),\n  mentor_id uuid not null references public.users(id) on delete cascade,\n  status text not null default ''pending'' check (\n    status in (''pending'', ''approved'', ''rejected'', ''resubmit_required'')\n  ),\n  -- 멘토가 신청 시 입력하는 자유 텍스트 (관리자 검토 참고용)\n  requested_university_name text,\n  change_reason text,\n  document_storage_ref text,\n  -- 관리자가 승인 시 확정하는 학교명 → mentor_profiles.university_name 으로 반영\n  approved_university_name text,\n  reviewed_by uuid references public.users(id) on delete set null,\n  reviewed_at timestamptz,\n  reject_reason text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "comment on table public.mentor_academic_record_change_requests is\n  ''Mentor-submitted academic record change requests. Mentor cannot self-edit mentor_profiles.university_name; admin approval applies approved_university_name.''", "comment on column public.mentor_academic_record_change_requests.mentor_id is\n  ''Mentor user id. Follows existing mentor_id -> public.users(id) pattern.''", "comment on column public.mentor_academic_record_change_requests.status is\n  ''pending / approved / rejected / resubmit_required.''", "comment on column public.mentor_academic_record_change_requests.requested_university_name is\n  ''Free-text new school name claimed by the mentor (admin reference only).''", "comment on column public.mentor_academic_record_change_requests.change_reason is\n  ''Mentor note describing the change (편입/졸업/전과 등).''", "comment on column public.mentor_academic_record_change_requests.document_storage_ref is\n  ''Private Storage object reference for submitted academic-change proof document.''", "comment on column public.mentor_academic_record_change_requests.approved_university_name is\n  ''University name confirmed by admin at approval time, applied to mentor_profiles.university_name.''", "create index if not exists idx_mentor_acad_change_mentor_id\n  on public.mentor_academic_record_change_requests (mentor_id)", "create index if not exists idx_mentor_acad_change_status\n  on public.mentor_academic_record_change_requests (status)", "-- Keep updated_at current using the existing shared trigger function from 001.\ndrop trigger if exists trg_mentor_acad_change_set_updated_at\n  on public.mentor_academic_record_change_requests", "create trigger trg_mentor_acad_change_set_updated_at\n  before update on public.mentor_academic_record_change_requests\n  for each row execute function public.set_updated_at()", "-- Mentors may submit/re-submit documents, but may not self-approve or self-fill\n-- admin-owned review fields.\ncreate or replace function public.mentor_acad_change_guard_self_review()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\nbegin\n  if coalesce((select public.is_admin()), false) then\n    return new;\n  end if;\n\n  if new.mentor_id = (select auth.uid()) then\n    new.status := ''pending'';\n    new.approved_university_name := null;\n    new.reviewed_by := null;\n    new.reviewed_at := null;\n    new.reject_reason := null;\n  end if;\n\n  return new;\nend;\n$function$", "drop trigger if exists trg_mentor_acad_change_guard_self_review\n  on public.mentor_academic_record_change_requests", "create trigger trg_mentor_acad_change_guard_self_review\n  before insert or update on public.mentor_academic_record_change_requests\n  for each row execute function public.mentor_acad_change_guard_self_review()", "alter table public.mentor_academic_record_change_requests enable row level security", "-- No public/anon direct access policy.\n\ndrop policy if exists macc_select_own on public.mentor_academic_record_change_requests", "create policy macc_select_own\n  on public.mentor_academic_record_change_requests\n  for select\n  to authenticated\n  using (mentor_id = (select auth.uid()))", "drop policy if exists macc_insert_own_pending on public.mentor_academic_record_change_requests", "create policy macc_insert_own_pending\n  on public.mentor_academic_record_change_requests\n  for insert\n  to authenticated\n  with check (\n    mentor_id = (select auth.uid())\n    and status = ''pending''\n    and exists (\n      select 1\n      from public.users u\n      where u.id = (select auth.uid())\n        and u.role = ''mentor''\n    )\n    and approved_university_name is null\n    and reviewed_by is null\n    and reviewed_at is null\n    and reject_reason is null\n  )", "drop policy if exists macc_update_own_pending on public.mentor_academic_record_change_requests", "create policy macc_update_own_pending\n  on public.mentor_academic_record_change_requests\n  for update\n  to authenticated\n  using (\n    mentor_id = (select auth.uid())\n    and status in (''pending'', ''resubmit_required'')\n  )\n  with check (\n    mentor_id = (select auth.uid())\n    and status = ''pending''\n    and approved_university_name is null\n    and reviewed_by is null\n    and reviewed_at is null\n    and reject_reason is null\n  )", "drop policy if exists macc_admin_select_all on public.mentor_academic_record_change_requests", "create policy macc_admin_select_all\n  on public.mentor_academic_record_change_requests\n  for select\n  to authenticated\n  using ((select public.is_admin()) = true)", "drop policy if exists macc_admin_update_all on public.mentor_academic_record_change_requests", "create policy macc_admin_update_all\n  on public.mentor_academic_record_change_requests\n  for update\n  to authenticated\n  using ((select public.is_admin()) = true)\n  with check ((select public.is_admin()) = true)", "comment on policy macc_select_own on public.mentor_academic_record_change_requests is\n  ''Mentors can read only their own academic-record change requests.''", "comment on policy macc_insert_own_pending on public.mentor_academic_record_change_requests is\n  ''Mentors can submit only their own pending requests; admin-owned fields remain null.''", "comment on policy macc_update_own_pending on public.mentor_academic_record_change_requests is\n  ''Mentors can update only own pending/resubmit_required rows back to pending, without self-approving.''", "comment on policy macc_admin_select_all on public.mentor_academic_record_change_requests is\n  ''Admins can review all mentor academic-record change requests.''", "comment on policy macc_admin_update_all on public.mentor_academic_record_change_requests is\n  ''Admins can approve/reject/request resubmission.''", "-- >>> NATIVE_BASELINE_PART 0101 | supabase/sql/090_custom_order_fee_5pct.sql | 090_custom_order_fee_5pct.sql <<<\n-- 090_custom_order_fee_5pct.sql\n-- 맞춤의뢰 플랫폼 수수료 20% → 5% (멘토 80% → 95%). 수수료 정책 변경 252.\n--\n-- 변경점(돈): accept_custom_order_deliverable_atomic 의 v_fee_rate 0.20 → 0.05.\n--   · 055의 함수 본문을 그대로 두고 v_fee_rate만 0.05로 교체(create or replace).\n--   · 불변식 보존: platform_fee = floor(gross*0.05), mentor_amount = gross - platform_fee (합 = gross).\n--   · 멱등성·에스크로·지급(record_custom_order_escrow_payout) 로직 미변경.\n-- 소급 안 함: 이미 생성된 custom_order_settlement_items 행의 fee_rate/금액은 그대로(구 20% 유지).\n--   신규 정산 row만 5% 적용.\n-- 컬럼 default(013: 0.20)도 5%로 맞춤(RPC는 명시 insert라 default 영향 적으나 정합 위해).\n--\n-- 실행: 검토 후 Supabase SQL Editor에서 전체 실행. (service_role 권한 RPC)\n\nbegin", "-- 1) settlement_items 기본 수수료율 default 0.20 → 0.05 (신규 insert 기본값 정합)\nalter table public.custom_order_settlement_items\n  alter column fee_rate set default 0.05", "-- 2) 수락+정산+지급 원자 RPC — v_fee_rate만 0.05로 교체(055 본문 동일)\ncreate or replace function public.accept_custom_order_deliverable_atomic(\n  p_order_id uuid,\n  p_student_id uuid,\n  p_require_payment boolean default true\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  o public.custom_request_orders%rowtype;\n  app public.custom_request_applications%rowtype;\n  v_norm text;\n  v_pay text;\n  v_dispute_cnt integer;\n  v_deliverable_cnt integer;\n  v_existing_settlement uuid;\n  v_gross integer;\n  v_platform_fee integer;\n  v_mentor_amount integer;\n  v_settlement_id uuid;\n  v_settlement_created boolean := false;\n  v_payout_done boolean := false;\n  v_now timestamptz := now();\n  v_fee_rate numeric := 0.05;  -- 252: 맞춤의뢰 수수료 5%\nbegin\n  if p_order_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''orderId가 필요합니다.'');\n  end if;\n  if p_student_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''학생 ID가 필요합니다.'');\n  end if;\n\n  select * into o\n  from public.custom_request_orders\n  where id = p_order_id\n  for update;\n\n  if not found then\n    return jsonb_build_object(''ok'', false, ''message'', ''주문을 찾을 수 없어요.'');\n  end if;\n\n  if o.student_id is distinct from p_student_id then\n    return jsonb_build_object(''ok'', false, ''message'', ''의뢰자(학생) 본인만 납품을 수락할 수 있습니다.'');\n  end if;\n\n  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''''), '''')));\n  -- escrowed(예치 완료) 또는 paid(멱등·수리) 만 허용. unpaid 등 레거시 무예치 차단.\n  if p_require_payment and v_pay not in (''paid'', ''escrowed'') then\n    return jsonb_build_object(''ok'', false, ''message'', ''결제(예치)가 완료되지 않은 주문은 수락할 수 없습니다.'');\n  end if;\n\n  if o.completed_at is not null\n     or o.closed_at is not null\n     or o.finished_at is not null\n     or lower(trim(coalesce(o.status, ''''))) in (\n       ''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',\n       ''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved''\n     )\n     or lower(trim(coalesce(o.state, ''''))) in (\n       ''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',\n       ''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved''\n     )\n     or lower(trim(coalesce(o.order_status, ''''))) in (\n       ''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',\n       ''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved''\n     )\n  then\n    return jsonb_build_object(''ok'', false, ''message'', ''이미 완료된 주문입니다.'');\n  end if;\n\n  v_norm := public._order_primary_status_norm(o);\n  if v_norm = '''' then\n    return jsonb_build_object(''ok'', false, ''message'', ''주문 상태를 확인할 수 없어 수락할 수 없습니다.'');\n  end if;\n\n  if v_norm not in (\n    ''delivered'',''delivered_pending_review'',''waiting_review'',''pending_review'',\n    ''redelivered'',''delivery_submitted'',''in_review''\n  ) then\n    return jsonb_build_object(\n      ''ok'', false,\n      ''message'', format(''현재 상태(%s)에서는 납품 수락을 할 수 없습니다.'', v_norm)\n    );\n  end if;\n\n  select count(*)::integer into v_dispute_cnt\n  from public.disputes d\n  where d.custom_request_order_id = p_order_id\n    and d.status in (''open'', ''under_review'', ''escalated'');\n\n  if v_dispute_cnt > 0 then\n    return jsonb_build_object(''ok'', false, ''message'', ''진행 중인 분쟁이 있어 납품 수락을 할 수 없습니다.'');\n  end if;\n\n  select count(*)::integer into v_deliverable_cnt\n  from public.custom_order_deliverables d\n  where d.custom_request_order_id = p_order_id;\n\n  if v_deliverable_cnt < 1 then\n    return jsonb_build_object(''ok'', false, ''message'', ''등록된 납품이 없어 수락할 수 없습니다.'');\n  end if;\n\n  select id into v_existing_settlement\n  from public.custom_order_settlement_items s\n  where s.custom_request_order_id = p_order_id;\n\n  select a.* into app\n  from public.custom_request_applications a\n  where a.id = coalesce(o.application_id, o.custom_request_application_id, o.selected_application_id)\n  limit 1;\n\n  if v_existing_settlement is null then\n    v_gross := public._pick_custom_order_gross_won(o, app);\n    if v_gross is not null and v_gross > 0 then\n      v_platform_fee := floor(v_gross * v_fee_rate)::integer;\n      v_mentor_amount := v_gross - v_platform_fee;\n\n      insert into public.custom_order_settlement_items (\n        custom_request_order_id,\n        mentor_id,\n        student_id,\n        gross_amount,\n        platform_fee_amount,\n        mentor_amount,\n        fee_rate,\n        status\n      ) values (\n        p_order_id,\n        o.mentor_id,\n        o.student_id,\n        v_gross,\n        v_platform_fee,\n        v_mentor_amount,\n        v_fee_rate,\n        ''pending''\n      )\n      returning id into v_settlement_id;\n\n      v_settlement_created := true;\n    end if;\n  else\n    v_settlement_id := v_existing_settlement;\n  end if;\n\n  update public.custom_request_orders\n  set\n    status = ''completed'',\n    state = ''completed'',\n    order_status = ''completed'',\n    accepted_at = coalesce(accepted_at, v_now),\n    completed_at = coalesce(completed_at, v_now),\n    updated_at = v_now\n  where id = p_order_id;\n\n  if v_settlement_id is not null then\n    perform public.record_custom_order_escrow_payout(p_order_id);\n    v_payout_done := true;\n  end if;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''settlement_created'', v_settlement_created,\n    ''settlement_id'', v_settlement_id,\n    ''gross'', v_gross,\n    ''fee_rate'', v_fee_rate,\n    ''payout_done'', v_payout_done\n  );\nexception\n  when others then\n    if sqlstate = ''23505'' then\n      select id into v_existing_settlement\n      from public.custom_order_settlement_items s\n      where s.custom_request_order_id = p_order_id;\n\n      update public.custom_request_orders\n      set\n        status = ''completed'',\n        state = ''completed'',\n        order_status = ''completed'',\n        accepted_at = coalesce(accepted_at, v_now),\n        completed_at = coalesce(completed_at, v_now),\n        updated_at = v_now\n      where id = p_order_id;\n\n      if v_existing_settlement is not null then\n        perform public.record_custom_order_escrow_payout(p_order_id);\n        v_payout_done := true;\n      end if;\n\n      return jsonb_build_object(\n        ''ok'', true,\n        ''settlement_created'', false,\n        ''settlement_id'', v_existing_settlement,\n        ''payout_done'', v_payout_done,\n        ''reason'', ''already_exists''\n      );\n    end if;\n    raise;\nend;\n$function$", "comment on function public.accept_custom_order_deliverable_atomic(uuid, uuid, boolean) is\n  ''252: Custom order accept + settlement(5% fee) + mentor escrow payout, one transaction. service_role only.''", "revoke all on function public.accept_custom_order_deliverable_atomic(uuid, uuid, boolean) from public", "grant execute on function public.accept_custom_order_deliverable_atomic(uuid, uuid, boolean) to service_role", "commit", "-- 검증(실행 후 확인):\n-- 1) 신규 주문 정산 시 fee_rate=0.05, mentor_amount=floor(gross*0.95), platform_fee=gross-mentor_amount.\n-- 2) 기존 행은 fee_rate=0.20 그대로(소급 안 됨).\n\n-- >>> NATIVE_BASELINE_PART 0102 | supabase/sql/091_individual_question_release_refund_wrappers.sql | 091_individual_question_release_refund_wrappers.sql <<<\n-- =============================================================================\n-- 091_individual_question_release_refund_wrappers.sql\n-- Purpose: Authenticated client RPC wrappers the Flutter app calls by name for\n--          individual-question escrow RELEASE (payout) and REFUND.\n--          The app calls release_individual_question / refund_individual_question\n--          with {p_question_id}. Core escrow RPCs (070) are service_role only,\n--          so these SECURITY DEFINER wrappers enforce \"본인(student) 한정\" and\n--          delegate to the existing core. No new money math is introduced.\n--\n-- Money-gate (💰) notes:\n--   - Wrappers ONLY delegate to existing cores; they add NO amount calculation.\n--   - release/refund have NO _v2 in 070, so wrappers call the v1 cores as-is.\n--   - Self-only: only the question''s student (auth.uid() = student_id) may\n--     trigger release(정산) or refund(환불). Mentor/other roles are rejected.\n--   - Core idempotency (cash_ledger.idempotency_key ''iq_payout:''/''iq_refund:'')\n--     still blocks double payout/refund; wrappers do not bypass it.\n--\n-- Safety:\n--   - Additive only. Does NOT edit/drop/revoke 070 core functions.\n--   - Does not touch tables, RLS, or other escrow flows.\n--   - Reuses public.individual_question_escrow_result return type (070).\n--\n-- Rollback:\n--   drop function if exists public.refund_individual_question(uuid);\n--   drop function if exists public.release_individual_question(uuid);\n-- =============================================================================\n\nbegin", "-- ---------------------------------------------------------------------------\n-- RPC wrapper: release (student confirms answer -> mentor payout)\n-- App call: rpc(''release_individual_question'', { p_question_id })\n-- ---------------------------------------------------------------------------\ncreate or replace function public.release_individual_question(\n  p_question_id uuid\n)\nreturns public.individual_question_escrow_result\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_res public.individual_question_escrow_result;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  if p_question_id is null then\n    raise exception ''INVALID_INPUT: question_id is required'' using errcode = ''22023'';\n  end if;\n\n  -- 본인 한정: only the owning student may release/settle their question.\n  if not exists (\n    select 1\n    from public.individual_questions q\n    where q.id = p_question_id\n      and q.student_id = v_uid\n  ) then\n    raise exception ''NOT_QUESTION_OWNER'' using errcode = ''42501'';\n  end if;\n\n  v_res := public.release_individual_question_payout(p_question_id);\n\n  if not v_res.ok then\n    raise exception ''INDIVIDUAL_QUESTION_RELEASE_FAILED:%:%'', v_res.code, v_res.message\n      using errcode = ''P0001'';\n  end if;\n\n  return v_res;\nend;\n$function$", "revoke all on function public.release_individual_question(uuid)\n  from public, anon, authenticated", "grant execute on function public.release_individual_question(uuid)\n  to authenticated", "comment on function public.release_individual_question(uuid) is\n  ''Authenticated client wrapper for individual-question payout. Self(student)-only; delegates to release_individual_question_payout (no _v2). Adds no money math.''", "-- ---------------------------------------------------------------------------\n-- RPC wrapper: refund (student cancels -> escrow returned to student)\n-- App call: rpc(''refund_individual_question'', { p_question_id })\n-- ---------------------------------------------------------------------------\ncreate or replace function public.refund_individual_question(\n  p_question_id uuid\n)\nreturns public.individual_question_escrow_result\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_res public.individual_question_escrow_result;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  if p_question_id is null then\n    raise exception ''INVALID_INPUT: question_id is required'' using errcode = ''22023'';\n  end if;\n\n  -- 본인 한정: only the owning student may refund their question.\n  if not exists (\n    select 1\n    from public.individual_questions q\n    where q.id = p_question_id\n      and q.student_id = v_uid\n  ) then\n    raise exception ''NOT_QUESTION_OWNER'' using errcode = ''42501'';\n  end if;\n\n  v_res := public.refund_individual_question_hold(p_question_id);\n\n  if not v_res.ok then\n    raise exception ''INDIVIDUAL_QUESTION_REFUND_FAILED:%:%'', v_res.code, v_res.message\n      using errcode = ''P0001'';\n  end if;\n\n  return v_res;\nend;\n$function$", "revoke all on function public.refund_individual_question(uuid)\n  from public, anon, authenticated", "grant execute on function public.refund_individual_question(uuid)\n  to authenticated", "comment on function public.refund_individual_question(uuid) is\n  ''Authenticated client wrapper for individual-question escrow refund. Self(student)-only; delegates to refund_individual_question_hold (no _v2). Adds no money math.''", "commit", "-- >>> NATIVE_BASELINE_PART 0103 | supabase/sql/092_individual_question_create_claim_wrappers.sql | 092_individual_question_create_claim_wrappers.sql <<<\n-- =============================================================================\n-- 092_individual_question_create_claim_wrappers.sql\n-- Purpose: Authenticated client RPC wrappers the Flutter app calls by name for\n--          individual-question CREATE (escrow hold), CLAIM (open-question\n--          first-claim), and ANSWER (mentor posts answer + transition to\n--          ''answered''). All mutations go through SECURITY DEFINER RPCs to honor\n--          070''s design (no authenticated direct write on escrow tables).\n--\n--          The app calls:\n--            create_individual_question_as_student {p_question_type,p_title,\n--              p_body,p_amount_cents?,p_designated_mentor_id?,p_idempotency_key?}\n--            claim_individual_question_as_mentor   {p_question_id}\n--            answer_individual_question            {p_question_id, p_body}\n--\n--          Core escrow RPCs (070/080/081) are service_role only, so these\n--          SECURITY DEFINER wrappers enforce \"본인 한정\" (self-only) and delegate\n--          to the existing cores. No new money math is introduced.\n--\n-- Money-gate (💰) notes:\n--   - Wrappers ONLY delegate to existing cores; they add NO amount calculation.\n--   - 🔴 v2 호출: create -> create_individual_question_with_hold_v2,\n--     claim -> claim_individual_question_v2. v1 코어가 아니라 v2를 호출하여\n--     자격(학교tier/전공) 게이트가 항상 적용되도록 일관성을 맞춘다. 단,\n--     이 래퍼는 자격 파라미터를 null로만 전달한다(기존 동작과 동일, 추가 제약 없음).\n--   - Direct(지정) 질문 가격은 앱이 보내지 않고, 래퍼가 멘토 가격표\n--     (mentor_individual_question_pricing.amount_cents)에서 조회한다 = 앱 표시가와\n--     동일 소스. 임의 금액 계산을 하지 않는다.\n--   - Core idempotency (individual_questions.create_idempotency_key + cash_ledger\n--     ''iq_hold:'') still blocks double-hold. 앱이 키를 보내지 않으면 래퍼가\n--     랜덤 키를 생성한다(코어의 NOT NULL 충족용). 진짜 멱등(재시도 중복 예치 방지)을\n--     원하면 앱이 안정적인 키를 보내야 한다 — 보고서 미결 항목으로 표기.\n--\n-- Permission-gate (🔑) notes:\n--   - G 교정: 에스크로 테이블 직접쓰기 정책(iq_update_claimed_mentor_answer,\n--     iqm_insert_party)을 두지 않는다. 대신 answer_individual_question RPC 가\n--     메시지 insert + status=''answered'' 전이를 원자적으로 처리(070 의 RPC-only\n--     변경 설계와 일치, 웹과 동일 잠금). 멘토 권한은 payout 과 동일하게\n--     coalesce(claimed_mentor_id, designated_mentor_id) 로 바인딩. 현금 이동 없음.\n--   - SELECT 는 070 의 기존 iq_select_party / iqm_select_party(헬퍼\n--     user_is_individual_question_party)가 당사자 읽기를 이미 허용 → 추가 없음.\n--\n-- Safety:\n--   - Additive only. Does NOT edit/drop/revoke 070/080/081 core functions.\n--   - create/claim/answer 래퍼는 신규 함수명이므로 기존 객체와 충돌 없음.\n--   - 신규 RLS 정책 추가 없음(직접쓰기는 RPC 경유로 처리).\n--\n-- Rollback:\n--   drop function if exists public.answer_individual_question(uuid, text);\n--   drop function if exists public.claim_individual_question_as_mentor(uuid);\n--   drop function if exists public.create_individual_question_as_student(text, text, text, int, uuid, text);\n-- =============================================================================\n\nbegin", "-- ---------------------------------------------------------------------------\n-- RPC wrapper: create (student creates question + escrow hold)\n-- App call: rpc(''create_individual_question_as_student'', { ... })\n--   open   : { p_question_type:''open'',   p_title, p_body, p_amount_cents }\n--   direct : { p_question_type:''direct'', p_title, p_body, p_designated_mentor_id }\n-- Returns the created individual_questions row (app reads row.first).\n-- ---------------------------------------------------------------------------\ncreate or replace function public.create_individual_question_as_student(\n  p_question_type text,\n  p_title text,\n  p_body text,\n  p_amount_cents int default null,\n  p_designated_mentor_id uuid default null,\n  p_idempotency_key text default null\n)\nreturns setof public.individual_questions\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_type text := lower(trim(coalesce(p_question_type, '''')));\n  v_idem text := nullif(trim(coalesce(p_idempotency_key, '''')), '''');\n  v_price int;\n  v_res public.individual_question_escrow_result;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  if v_type not in (''direct'', ''open'') then\n    raise exception ''INVALID_INPUT: question_type must be direct or open''\n      using errcode = ''22023'';\n  end if;\n\n  if length(trim(coalesce(p_title, ''''))) = 0\n     or length(trim(coalesce(p_body, ''''))) = 0 then\n    raise exception ''INVALID_INPUT: title and body are required''\n      using errcode = ''22023'';\n  end if;\n\n  -- 가격 결정: open 은 앱이 보낸 금액, direct 은 멘토 가격표에서 조회.\n  if v_type = ''direct'' then\n    if p_designated_mentor_id is null then\n      raise exception ''INVALID_INPUT: designated_mentor_id is required for direct''\n        using errcode = ''22023'';\n    end if;\n\n    select amount_cents\n      into v_price\n    from public.mentor_individual_question_pricing\n    where mentor_id = p_designated_mentor_id;\n\n    if v_price is null then\n      raise exception ''MENTOR_PRICE_NOT_SET'' using errcode = ''P0001'';\n    end if;\n  else\n    v_price := p_amount_cents;\n    if v_price is null or v_price <= 0 then\n      raise exception ''INVALID_INPUT: amount_cents must be positive for open''\n        using errcode = ''22023'';\n    end if;\n  end if;\n\n  -- 멱등성 키: 앱이 안 보내면 랜덤 생성(코어 NOT NULL 충족용).\n  if v_idem is null then\n    v_idem := ''iqc:'' || gen_random_uuid()::text;\n  end if;\n\n  -- 🔴 v2 코어 호출(자격 게이트 일관). 자격 파라미터는 null 만 전달.\n  v_res := public.create_individual_question_with_hold_v2(\n    v_uid,                       -- p_student_id (self only)\n    v_type,                      -- p_question_type\n    p_designated_mentor_id,      -- p_mentor_id (direct only; null for open)\n    null,                        -- p_subject\n    null,                        -- p_topic\n    p_title,                     -- p_title\n    p_body,                      -- p_body\n    v_price,                     -- p_price_cents\n    v_idem,                      -- p_idempotency_key\n    null,                        -- p_required_school_tier\n    null                         -- p_required_major_category\n  );\n\n  if not v_res.ok then\n    raise exception ''INDIVIDUAL_QUESTION_CREATE_FAILED:%:%'', v_res.code, v_res.message\n      using errcode = ''P0001'';\n  end if;\n\n  return query\n    select * from public.individual_questions where id = v_res.question_id;\nend;\n$function$", "revoke all on function public.create_individual_question_as_student(text, text, text, int, uuid, text)\n  from public, anon, authenticated", "grant execute on function public.create_individual_question_as_student(text, text, text, int, uuid, text)\n  to authenticated", "comment on function public.create_individual_question_as_student(text, text, text, int, uuid, text) is\n  ''Authenticated client wrapper for individual-question create + escrow hold. Self(student)-only; delegates to create_individual_question_with_hold_v2 (v2, qualification params null). Direct price looked up from mentor_individual_question_pricing. Adds no money math.''", "-- ---------------------------------------------------------------------------\n-- RPC wrapper: claim (mentor first-claims an open question)\n-- App call: rpc(''claim_individual_question_as_mentor'', { p_question_id })\n-- ---------------------------------------------------------------------------\ncreate or replace function public.claim_individual_question_as_mentor(\n  p_question_id uuid\n)\nreturns public.individual_question_escrow_result\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_res public.individual_question_escrow_result;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  if p_question_id is null then\n    raise exception ''INVALID_INPUT: question_id is required'' using errcode = ''22023'';\n  end if;\n\n  -- 🔴 v2 코어 호출(자격 게이트 일관). 멘토 = auth.uid() 강제.\n  v_res := public.claim_individual_question_v2(p_question_id, v_uid);\n\n  if not v_res.ok then\n    raise exception ''INDIVIDUAL_QUESTION_CLAIM_FAILED:%:%'', v_res.code, v_res.message\n      using errcode = ''P0001'';\n  end if;\n\n  return v_res;\nend;\n$function$", "revoke all on function public.claim_individual_question_as_mentor(uuid)\n  from public, anon, authenticated", "grant execute on function public.claim_individual_question_as_mentor(uuid)\n  to authenticated", "comment on function public.claim_individual_question_as_mentor(uuid) is\n  ''Authenticated client wrapper for open individual-question first-claim. Self(mentor=auth.uid())-only; delegates to claim_individual_question_v2 (v2, qualification gate). Adds no money math.''", "-- ---------------------------------------------------------------------------\n-- RPC: answer (mentor posts answer + transition to ''answered'') — G 교정\n--   070 설계 원칙: 개별질문(에스크로) 테이블은 authenticated 직접 insert/update\n--   를 두지 않고, 모든 변경은 service_role/SECURITY DEFINER RPC 로만(070 주석).\n--   → 앱 answer() 의 직접 insert+update 2회를 이 단일 RPC 로 대체(웹과 동일 잠금).\n--   → 따라서 직접쓰기 정책(iq_update_claimed_mentor_answer, iqm_insert_party)은\n--     두지 않는다. SELECT 는 070 의 기존 iqm_select_party / iq_select_party 가\n--     이미 당사자 읽기를 허용하므로 추가 불필요.\n--\n-- 멘토 바인딩: payout(release_individual_question_payout)이 정산 대상으로\n--   coalesce(claimed_mentor_id, designated_mentor_id) 를 쓰므로 answer 권한도\n--   동일하게 바인딩한다. (open=claimed_mentor_id, direct=designated_mentor_id;\n--   claimed 단독 체크는 direct 질문에서 실패하므로 금지.)\n-- status 가드: 070 CHECK 값 기준 답변 가능 상태만 허용 = ''claimed''(open 클레임 후),\n--   ''assigned''(direct 지정). 그 외(escrowed/open/answered/released/refunded/\n--   expired/canceled)는 거부. 현금 이동 없음(정산은 별도 release RPC).\n-- ---------------------------------------------------------------------------\ncreate or replace function public.answer_individual_question(\n  p_question_id uuid,\n  p_body text\n)\nreturns setof public.individual_questions\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_question public.individual_questions%rowtype;\n  v_mentor_id uuid;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  if coalesce(btrim(p_body), '''') = '''' then\n    raise exception ''INVALID_INPUT: body is required'' using errcode = ''22023'';\n  end if;\n\n  select *\n    into v_question\n  from public.individual_questions\n  where id = p_question_id\n  for update;\n\n  if not found then\n    raise exception ''QUESTION_NOT_FOUND'' using errcode = ''P0001'';\n  end if;\n\n  -- payout 과 동일한 멘토 해석(open=claimed, direct=designated).\n  v_mentor_id := coalesce(v_question.claimed_mentor_id, v_question.designated_mentor_id);\n  if v_mentor_id is null or v_mentor_id <> v_uid then\n    raise exception ''NOT_QUESTION_MENTOR'' using errcode = ''42501'';\n  end if;\n\n  if v_question.status not in (''claimed'', ''assigned'') then\n    raise exception ''NOT_ANSWERABLE_STATUS:%'', v_question.status using errcode = ''P0001'';\n  end if;\n\n  insert into public.individual_question_messages (question_id, author_id, body)\n  values (p_question_id, v_uid, p_body);\n\n  update public.individual_questions\n  set status = ''answered'',\n      answered_at = coalesce(answered_at, now())\n  where id = p_question_id\n  returning * into v_question;\n\n  return next v_question;\nend;\n$function$", "revoke all on function public.answer_individual_question(uuid, text)\n  from public, anon", "grant execute on function public.answer_individual_question(uuid, text)\n  to authenticated", "comment on function public.answer_individual_question(uuid, text) is\n  ''Authenticated wrapper: mentor posts an answer message + transitions question to answered, atomically. Mentor = coalesce(claimed_mentor_id, designated_mentor_id) (matches payout). No cash movement. Replaces app direct insert/update to keep 070 RPC-only mutation design.''", "commit", "-- >>> NATIVE_BASELINE_PART 0104 | supabase/sql/093_scan_annotations_and_withdrawals.sql | 093_scan_annotations_and_withdrawals.sql <<<\n-- =============================================================================\n-- 093_scan_annotations_and_withdrawals.sql\n-- Purpose: Restore two app-referenced objects that the backend never created:\n--          (1) scan_annotations table + ''scan-annotations'' Storage bucket\n--              (스캔 첨삭: 멘토/학생이 스캔 원본에 주석을 얹어 저장/조회)\n--          (2) withdrawals table (멘토 출금 \"요청 로그\")\n--          plus RLS for the tables and the storage bucket.\n--\n-- 🗂️ Schema-gate + 🔑 Permission-gate notes:\n--   - 신규 테이블/버킷 추가(additive). 기존 객체 수정/삭제 없음.\n--   - annotation_json 은 반드시 TEXT. 앱은 정규화 주석을 String 으로 보내고\n--     String 으로 읽는다(scan_annotation.dart fromMap: annotation_json as String?).\n--     jsonb 로 만들면 읽을 때 Map 이 와서 조용히 데이터가 깨진다 → TEXT 고정.\n--   - scan_annotations 접근: 해당 mentor_student_rooms 의 당사자(student_id 또는\n--     mentor_id = auth.uid())만 select/insert/update. author_id 는 본인만.\n--   - 버킷 ''scan-annotations'' 는 비공개. 경로 1번째 폴더 = roomId 로 방 당사자만\n--     읽기/쓰기.\n--\n-- 💰 Money-gate note (withdrawals):\n--   - withdrawals 는 \"출금 요청 로그\"까지만. 잔액 검증/실제 차감/송금은 하지 않는다.\n--     ''paid'' 전이 및 지급은 서버/관리자(finance-settlement) 책임 — authenticated\n--     는 status=''requested'' 행만 insert 가능, update/delete 불가(자가 ''paid'' 차단).\n--   - 금액 단위는 원=캐시(정수). amount_cash 그대로 저장(×/÷100 없음).\n--\n-- Safety:\n--   - 모든 객체 if-not-exists / drop-if-exists 후 생성으로 멱등.\n--   - set_updated_at() 트리거 함수는 기존 마이그레이션에 존재한다고 가정(재사용).\n--\n-- Rollback:\n--   drop table if exists public.scan_annotations;\n--   drop table if exists public.withdrawals;\n--   delete from storage.buckets where id = ''scan-annotations'';\n--   (storage.objects 정책은 아래 drop policy 문 참조)\n-- =============================================================================\n\nbegin", "-- ===========================================================================\n-- (1) scan_annotations\n-- ===========================================================================\ncreate table if not exists public.scan_annotations (\n  id uuid primary key default gen_random_uuid(),\n  mentor_student_room_id uuid not null\n    references public.mentor_student_rooms(id) on delete cascade,\n  author_id uuid not null references public.users(id),\n  author_role text not null check (author_role in (''student'', ''mentor'')),\n  annotation_json text not null default ''{}'',\n  scan_image_path text,\n  preview_path text,\n  has_annotations boolean not null default false,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "create index if not exists idx_scan_annotations_room_created\n  on public.scan_annotations (mentor_student_room_id, created_at desc)", "drop trigger if exists trg_scan_annotations_updated_at on public.scan_annotations", "create trigger trg_scan_annotations_updated_at\n  before update on public.scan_annotations\n  for each row execute function public.set_updated_at()", "alter table public.scan_annotations enable row level security", "-- 방 당사자만 조회.\ndrop policy if exists \"scan_annotations_select_party\" on public.scan_annotations", "create policy \"scan_annotations_select_party\" on public.scan_annotations\n  for select to authenticated\n  using (\n    exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = scan_annotations.mentor_student_room_id\n        and ((select auth.uid()) = r.student_id\n             or (select auth.uid()) = r.mentor_id)\n    )\n  )", "-- 본인 글, 방 당사자만 작성.\ndrop policy if exists \"scan_annotations_insert_author\" on public.scan_annotations", "create policy \"scan_annotations_insert_author\" on public.scan_annotations\n  for insert to authenticated\n  with check (\n    (select auth.uid()) = author_id\n    and exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = scan_annotations.mentor_student_room_id\n        and ((select auth.uid()) = r.student_id\n             or (select auth.uid()) = r.mentor_id)\n    )\n  )", "-- 본인 글, 방 당사자만 수정.\ndrop policy if exists \"scan_annotations_update_author\" on public.scan_annotations", "create policy \"scan_annotations_update_author\" on public.scan_annotations\n  for update to authenticated\n  using ((select auth.uid()) = author_id)\n  with check (\n    (select auth.uid()) = author_id\n    and exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = scan_annotations.mentor_student_room_id\n        and ((select auth.uid()) = r.student_id\n             or (select auth.uid()) = r.mentor_id)\n    )\n  )", "comment on table public.scan_annotations is\n  ''스캔 첨삭 주석 행. annotation_json 은 0~1 정규화 주석을 TEXT 로 보관(앱이 String 으로 주고받음). 방 당사자/작성자 한정 RLS.''", "-- ===========================================================================\n-- (2) scan-annotations Storage bucket (private)\n-- ===========================================================================\ninsert into storage.buckets (id, name, public)\nvalues (''scan-annotations'', ''scan-annotations'', false)\non conflict (id) do nothing", "-- 경로 규칙: ''<roomId>/<stamp>-original.jpg'' | ''<roomId>/<stamp>-preview.png''\n-- 1번째 폴더 = roomId. 해당 방 당사자만 read/write.\ndrop policy if exists \"scan_annotations_obj_select\" on storage.objects", "create policy \"scan_annotations_obj_select\" on storage.objects\n  for select to authenticated\n  using (\n    bucket_id = ''scan-annotations''\n    and exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = ((storage.foldername(name))[1])::uuid\n        and ((select auth.uid()) = r.student_id\n             or (select auth.uid()) = r.mentor_id)\n    )\n  )", "drop policy if exists \"scan_annotations_obj_insert\" on storage.objects", "create policy \"scan_annotations_obj_insert\" on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = ''scan-annotations''\n    and exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = ((storage.foldername(name))[1])::uuid\n        and ((select auth.uid()) = r.student_id\n             or (select auth.uid()) = r.mentor_id)\n    )\n  )", "drop policy if exists \"scan_annotations_obj_update\" on storage.objects", "create policy \"scan_annotations_obj_update\" on storage.objects\n  for update to authenticated\n  using (\n    bucket_id = ''scan-annotations''\n    and exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = ((storage.foldername(name))[1])::uuid\n        and ((select auth.uid()) = r.student_id\n             or (select auth.uid()) = r.mentor_id)\n    )\n  )\n  with check (\n    bucket_id = ''scan-annotations''\n    and exists (\n      select 1 from public.mentor_student_rooms r\n      where r.id = ((storage.foldername(name))[1])::uuid\n        and ((select auth.uid()) = r.student_id\n             or (select auth.uid()) = r.mentor_id)\n    )\n  )", "-- ===========================================================================\n-- (3) withdrawals (멘토 출금 요청 로그)\n-- ===========================================================================\ncreate table if not exists public.withdrawals (\n  id uuid primary key default gen_random_uuid(),\n  mentor_id uuid not null references public.users(id),\n  amount_cash integer not null check (amount_cash > 0),\n  status text not null default ''requested'' check (status in (''requested'', ''paid'')),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "create index if not exists idx_withdrawals_mentor_created\n  on public.withdrawals (mentor_id, created_at desc)", "drop trigger if exists trg_withdrawals_updated_at on public.withdrawals", "create trigger trg_withdrawals_updated_at\n  before update on public.withdrawals\n  for each row execute function public.set_updated_at()", "alter table public.withdrawals enable row level security", "-- 본인 출금 내역만 조회.\ndrop policy if exists \"withdrawals_select_self\" on public.withdrawals", "create policy \"withdrawals_select_self\" on public.withdrawals\n  for select to authenticated\n  using ((select auth.uid()) = mentor_id)", "-- 본인 명의로 ''requested'' 상태만 생성(자가 ''paid'' 차단).\ndrop policy if exists \"withdrawals_insert_self_requested\" on public.withdrawals", "create policy \"withdrawals_insert_self_requested\" on public.withdrawals\n  for insert to authenticated\n  with check (\n    (select auth.uid()) = mentor_id\n    and status = ''requested''\n  )", "-- update/delete 정책 없음 → authenticated 는 상태 변경/삭제 불가.\n-- ''paid'' 전이·실제 지급은 service_role/관리자 책임(돈 사고 방지).\n\ncomment on table public.withdrawals is\n  ''멘토 출금 요청 로그. authenticated 는 본인 requested 행만 insert/select. paid 전이·지급은 서버/관리자 책임. amount_cash 단위=원=캐시(정수).''", "commit", "-- >>> NATIVE_BASELINE_PART 0105 | supabase/sql/094_individual_question_pricing_rpc.sql | 094_individual_question_pricing_rpc.sql <<<\n-- =============================================================================\n-- 094_individual_question_pricing_rpc.sql\n-- Purpose (S3): Restore the mentor self-service write path for individual-question\n--               pricing. mentor_individual_question_pricing has RLS on with only\n--               a SELECT policy (070 miqp_select_authenticated) → authenticated\n--               INSERT/UPDATE is deny-all, so the app''s price upsert is blocked.\n--               070 도메인 테이블이므로 직접 쓰기 정책 대신 SECURITY DEFINER RPC\n--               로 멘토 본인 가격만 upsert (answer_individual_question 와 동일 원칙).\n--\n-- S3 정적 대조 결과(이 파일이 다루지 않는 항목 — 무변경):\n--   - favorites          : 034 에 RLS + select/insert/delete own(user_id) 이미\n--                          완비 → 변경 불요. (브리프의 \"정책 0개\"는 034 번호 충돌\n--                          favorites vs admin_disputes 로 인한 정적 대조 착오)\n--   - disputes(insert)   : 036 dispute_ins WITH CHECK 가 앱 insert\n--                          (custom_request_order_id + student_id=auth.uid(),\n--                          mentor_id 미설정) 와 일치 → 무변경.\n--                          앱의 custom_request_orders status=''disputed'' 직접\n--                          update 도 003 cro_update(student_id=auth.uid()) 로 허용.\n--\n-- Permission-gate (🔑):\n--   - set_individual_question_price: 멘토 본인(mentor_id = auth.uid()) 가격만\n--     upsert. 타인 가격 변경 불가. 현금 이동 없음.\n--   - 승인 멘토 한정 게이트는 기본 미적용(아래 주석 토글). 사유: 가격 행은\n--     direct 질문에만 쓰이고 direct 생성 시점에 이미 approved-mentor 게이트(080)가\n--     적용된다. 미승인 사용자의 가격 행은 inert. 온보딩 단계(승인 전) 가격 설정\n--     UX 를 막지 않기 위해 self-only 로 둔다. → 비즈니스 룰 확정 시 토글.\n--\n-- Money note (💰): 이 값은 direct 질문 hold 금액 산정(091/092 래퍼)에 쓰인다.\n--   RPC 는 금액을 받기만 하고 계산하지 않는다(검증: amount_cents > 0).\n--\n-- Safety:\n--   - Additive only. 신규 함수만 추가. 기존 테이블/정책/함수 수정·삭제 없음.\n--   - SELECT 정책(miqp_select_authenticated)은 그대로 두어 가격 조회는 유지.\n--\n-- Rollback:\n--   drop function if exists public.set_individual_question_price(int);\n-- =============================================================================\n\nbegin", "create or replace function public.set_individual_question_price(\n  p_amount_cents int\n)\nreturns setof public.mentor_individual_question_pricing\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_mentor uuid := (select auth.uid());\nbegin\n  if v_mentor is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  if coalesce(p_amount_cents, 0) <= 0 then\n    raise exception ''INVALID_INPUT: amount_cents must be positive'' using errcode = ''22023'';\n  end if;\n\n  -- (옵션·미적용) 승인 멘토 한정 게이트 — 비즈니스 룰 확정 시 주석 해제:\n  -- if not public.individual_question_user_is_approved_mentor(v_mentor) then\n  --   raise exception ''MENTOR_NOT_APPROVED'' using errcode = ''42501'';\n  -- end if;\n\n  insert into public.mentor_individual_question_pricing (mentor_id, amount_cents)\n  values (v_mentor, p_amount_cents)\n  on conflict (mentor_id) do update\n    set amount_cents = excluded.amount_cents,\n        updated_at = now();\n\n  return query\n    select * from public.mentor_individual_question_pricing where mentor_id = v_mentor;\nend;\n$function$", "revoke all on function public.set_individual_question_price(int)\n  from public, anon", "grant execute on function public.set_individual_question_price(int)\n  to authenticated", "comment on function public.set_individual_question_price(int) is\n  ''Authenticated wrapper: mentor upserts their own individual-question price. Self(mentor=auth.uid())-only; no cash movement. Replaces app direct upsert (070 RPC-only mutation design). Approved-mentor gate optional (off by default).''", "commit", "-- >>> NATIVE_BASELINE_PART 0106 | supabase/sql/095_subscription_fee_15pct.sql | 095_subscription_fee_15pct.sql <<<\n-- 095_subscription_fee_15pct.sql\n-- 구독 플랫폼 수수료 30% → 15% (멘토 70% → 85%). 수수료 정책 변경 254.\n--\n-- 변경점(돈): refresh_subscription_settlement_items 의 0.30 → 0.15 (계산 2곳 + insert fee_rate 1곳).\n--   · 086의 함수 본문을 그대로 두고 율만 0.15로 교체(create or replace).\n--   · 불변식 보존: platform_fee = floor(gross*0.15), mentor_amount = gross - platform_fee (합 = gross).\n--   · 멱등성(idempotency_key ''sub_settlement:{billing_event_id}'', on conflict do nothing)·송금 미수행 로직 미변경.\n-- 소급 안 함: 이미 생성된 subscription_settlement_items 행의 fee_rate/금액은 그대로(구 30% 유지).\n--   신규 정산 row만 15% 적용.\n-- 컬럼 default(086: 0.30)도 0.15로 맞춤(RPC는 명시 insert라 default 영향 적으나 정합 위해).\n--\n-- 실행: 검토 후 Supabase SQL Editor에서 전체 실행. (service_role 전용 RPC)\n\nbegin", "-- 1) subscription_settlement_items 기본 수수료율 default 0.30 → 0.15\nalter table public.subscription_settlement_items\n  alter column fee_rate set default 0.15", "-- 2) 집계 RPC — 0.30 → 0.15 (086 본문 동일, 율만 변경)\ncreate or replace function public.refresh_subscription_settlement_items(\n  p_from timestamptz default null,\n  p_to timestamptz default null\n)\nreturns table (\n  item_status text,\n  item_count bigint,\n  gross_cents bigint,\n  platform_fee_cents bigint,\n  mentor_amount_cents bigint\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\nbegin\n  with source_events as (\n    select\n      e.id as billing_event_id,\n      e.subscription_id,\n      e.student_id,\n      e.mentor_id,\n      e.payment_id,\n      e.ledger_id,\n      e.event_type,\n      coalesce(e.billing_at, e.processed_at, e.created_at) as billing_at,\n      e.period_start,\n      e.period_end,\n      e.amount_cents::bigint as gross_cents,\n      lower(coalesce(s.status, '''')) as subscription_status,\n      coalesce(s.cancel_at_period_end, false) as cancel_at_period_end,\n      coalesce(rf.has_pending_refund, false) as has_pending_refund,\n      coalesce(rf.has_succeeded_refund, false) as has_succeeded_refund\n    from public.subscription_billing_events e\n    join public.subscriptions s on s.id = e.subscription_id\n    left join lateral (\n      select\n        bool_or(lower(coalesce(r.status, '''')) = ''pending'') as has_pending_refund,\n        bool_or(lower(coalesce(r.status, '''')) in (''succeeded'', ''success'', ''approved'', ''paid'')) as has_succeeded_refund\n      from public.refunds r\n      where coalesce(r.request_type, '''') = ''subscription_prorated''\n        and (\n          r.subscription_id = e.subscription_id\n          or (\n            r.subscription_id is null\n            and r.payment_id is not null\n            and r.payment_id = e.payment_id\n          )\n        )\n    ) rf on true\n    where e.status = ''succeeded''\n      and e.event_type in (''initial'', ''renewal'')\n      and coalesce(e.amount_cents, 0) > 0\n      and (p_from is null or coalesce(e.billing_at, e.processed_at, e.created_at) >= p_from)\n      and (p_to is null or coalesce(e.billing_at, e.processed_at, e.created_at) < p_to)\n  ), calculated as (\n    select\n      se.*,\n      floor(se.gross_cents::numeric * 0.15)::bigint as platform_fee_cents,\n      (se.gross_cents - floor(se.gross_cents::numeric * 0.15)::bigint) as mentor_amount_cents,\n      case\n        when se.has_succeeded_refund or se.subscription_status = ''refunded'' then ''canceled''\n        when se.has_pending_refund then ''hold''\n        when se.subscription_status in (''cancel_scheduled'', ''canceled'', ''cancelled'', ''expired'') then ''hold''\n        when se.cancel_at_period_end then ''hold''\n        else ''pending''\n      end as sync_status,\n      case\n        when se.has_succeeded_refund or se.subscription_status = ''refunded'' then ''refund_succeeded''\n        when se.has_pending_refund then ''refund_pending''\n        when se.subscription_status in (''cancel_scheduled'', ''canceled'', ''cancelled'', ''expired'') then ''subscription_canceled_or_expired''\n        when se.cancel_at_period_end then ''cancel_at_period_end''\n        else null\n      end as sync_hold_reason\n    from source_events se\n  )\n  insert into public.subscription_settlement_items (\n    billing_event_id,\n    subscription_id,\n    mentor_id,\n    student_id,\n    payment_id,\n    ledger_id,\n    event_type,\n    billing_at,\n    period_start,\n    period_end,\n    gross_cents,\n    platform_fee_cents,\n    mentor_amount_cents,\n    fee_rate,\n    status,\n    hold_reason,\n    idempotency_key\n  )\n  select\n    c.billing_event_id,\n    c.subscription_id,\n    c.mentor_id,\n    c.student_id,\n    c.payment_id,\n    c.ledger_id,\n    c.event_type,\n    c.billing_at,\n    c.period_start,\n    c.period_end,\n    c.gross_cents,\n    c.platform_fee_cents,\n    c.mentor_amount_cents,\n    0.15,\n    c.sync_status,\n    c.sync_hold_reason,\n    ''sub_settlement:'' || c.billing_event_id::text\n  from calculated c\n  on conflict (billing_event_id) do nothing;\n\n  with source_events as (\n    select\n      e.id as billing_event_id,\n      lower(coalesce(s.status, '''')) as subscription_status,\n      coalesce(s.cancel_at_period_end, false) as cancel_at_period_end,\n      coalesce(rf.has_pending_refund, false) as has_pending_refund,\n      coalesce(rf.has_succeeded_refund, false) as has_succeeded_refund\n    from public.subscription_billing_events e\n    join public.subscriptions s on s.id = e.subscription_id\n    left join lateral (\n      select\n        bool_or(lower(coalesce(r.status, '''')) = ''pending'') as has_pending_refund,\n        bool_or(lower(coalesce(r.status, '''')) in (''succeeded'', ''success'', ''approved'', ''paid'')) as has_succeeded_refund\n      from public.refunds r\n      where coalesce(r.request_type, '''') = ''subscription_prorated''\n        and (\n          r.subscription_id = e.subscription_id\n          or (\n            r.subscription_id is null\n            and r.payment_id is not null\n            and r.payment_id = e.payment_id\n          )\n        )\n    ) rf on true\n    where e.status = ''succeeded''\n      and e.event_type in (''initial'', ''renewal'')\n      and coalesce(e.amount_cents, 0) > 0\n      and (p_from is null or coalesce(e.billing_at, e.processed_at, e.created_at) >= p_from)\n      and (p_to is null or coalesce(e.billing_at, e.processed_at, e.created_at) < p_to)\n  ), calculated as (\n    select\n      se.billing_event_id,\n      case\n        when se.has_succeeded_refund or se.subscription_status = ''refunded'' then ''canceled''\n        when se.has_pending_refund then ''hold''\n        when se.subscription_status in (''cancel_scheduled'', ''canceled'', ''cancelled'', ''expired'') then ''hold''\n        when se.cancel_at_period_end then ''hold''\n        else ''pending''\n      end as sync_status,\n      case\n        when se.has_succeeded_refund or se.subscription_status = ''refunded'' then ''refund_succeeded''\n        when se.has_pending_refund then ''refund_pending''\n        when se.subscription_status in (''cancel_scheduled'', ''canceled'', ''cancelled'', ''expired'') then ''subscription_canceled_or_expired''\n        when se.cancel_at_period_end then ''cancel_at_period_end''\n        else null\n      end as sync_hold_reason\n    from source_events se\n  )\n  update public.subscription_settlement_items i\n  set\n    status = c.sync_status,\n    hold_reason = c.sync_hold_reason,\n    updated_at = now()\n  from calculated c\n  where i.billing_event_id = c.billing_event_id\n    and i.status <> ''paid''\n    and (\n      (c.sync_status = ''canceled'' and i.status <> ''canceled'')\n      or (c.sync_status = ''hold'' and i.status = ''pending'')\n    );\n\n  return query\n  select\n    i.status::text as item_status,\n    count(*)::bigint as item_count,\n    coalesce(sum(i.gross_cents), 0)::bigint as gross_cents,\n    coalesce(sum(i.platform_fee_cents), 0)::bigint as platform_fee_cents,\n    coalesce(sum(i.mentor_amount_cents), 0)::bigint as mentor_amount_cents\n  from public.subscription_settlement_items i\n  where (p_from is null or i.billing_at >= p_from)\n    and (p_to is null or i.billing_at < p_to)\n  group by i.status\n  order by i.status;\nend;\n$function$", "comment on function public.refresh_subscription_settlement_items(timestamptz, timestamptz) is\n  ''254: 15% fee. Service-role-only idempotent sync from succeeded subscription_billing_events to subscription_settlement_items. Does not transfer money or mutate cash_ledger.''", "revoke all on function public.refresh_subscription_settlement_items(timestamptz, timestamptz) from public, anon, authenticated", "grant execute on function public.refresh_subscription_settlement_items(timestamptz, timestamptz) to service_role", "commit", "-- 검증(실행 후 확인):\n-- 1) 신규 정산 시 fee_rate=0.15, platform_fee=floor(gross*0.15), mentor_amount=gross-platform_fee.\n-- 2) 기존 행은 fee_rate=0.30 그대로(소급 안 됨).\n\n-- >>> NATIVE_BASELINE_PART 0107 | supabase/sql/096_individual_question_fee_15pct.sql | 096_individual_question_fee_15pct.sql <<<\n-- 096_individual_question_fee_15pct.sql\n-- 개별질문 플랫폼 수수료 0% → 15% (멘토 전액 → 85%). 수수료 정책 변경 255.\n--\n-- 변경점(돈): release_individual_question_payout 의 멘토 지급액을\n--   price_cents 전액 → floor(price_cents * 0.85). 플랫폼 15%는 hold 차액으로 implicit 보관\n--   (맞춤의뢰 055 방식과 동일 — 별도 platform wallet/ledger 만들지 않음).\n--   · 070의 함수 본문을 그대로 두고 지급액 2곳(cash_ledger delta + wallet credit)만 v_mentor_cents로 통일.\n--   · 멱등성(idempotency_key ''iq_payout:{id}'', on conflict do nothing, v_new_ledger 가드) 보존.\n--   · hold/refund 로직·다른 개별질문 RPC(create/claim/refund) 미터치.\n-- 소급 안 함: 이미 released된 과거 건은 전액 지급된 그대로. 신규 release만 85%.\n-- 표시: 개별질문은 멘토 정산 화면 합산·수수료 라벨이 없어 앱 변경 없음(멘토 cash_ledger/잔액에 85% 자동 반영).\n--\n-- 실행: 검토 후 Supabase SQL Editor에서 전체 실행. (service_role 전용 RPC)\n-- ⚠️ 090(맞춤의뢰)·095(구독)·096(개별질문) 세 파일을 함께 실행 권장(번호순 090→095→096).\n\nbegin", "create or replace function public.release_individual_question_payout(\n  p_question_id uuid\n)\nreturns public.individual_question_escrow_result\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_question public.individual_questions%rowtype;\n  v_mentor_id uuid;\n  v_ledger_id uuid;\n  v_wallet_balance bigint;\n  v_new_ledger boolean := false;\n  v_mentor_cents bigint;  -- 255: 멘토 지급 = floor(price_cents * 0.85), 플랫폼 15% 차액 implicit\nbegin\n  if p_question_id is null then\n    return (false, ''invalid_question'', ''question_id is required'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  select *\n    into v_question\n  from public.individual_questions\n  where id = p_question_id\n  for update;\n\n  if not found then\n    return (false, ''not_found'', ''individual question not found'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_question.release_ledger_id is not null or v_question.status = ''released'' then\n    return (true, ''already_released'', ''individual question already released'', v_question.id, v_question.status, v_question.release_ledger_id, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_question.refund_ledger_id is not null or v_question.status = ''refunded'' then\n    return (false, ''already_refunded'', ''individual question already refunded'', v_question.id, v_question.status, v_question.refund_ledger_id, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_question.status <> ''answered'' then\n    return (false, ''not_answered'', ''question must be answered before payout'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_question.hold_ledger_id is null then\n    return (false, ''hold_missing'', ''escrow hold ledger is missing'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  v_mentor_id := coalesce(v_question.claimed_mentor_id, v_question.designated_mentor_id);\n  if v_mentor_id is null then\n    return (false, ''mentor_missing'', ''mentor is missing'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if exists (\n    select 1\n    from public.cash_ledger l\n    where l.idempotency_key = ''iq_refund:'' || v_question.id::text\n      and l.reason = ''individual_question_refund''\n  ) then\n    return (false, ''already_refunded'', ''refund ledger already exists'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  -- 멘토 몫 85% (플랫폼 15%는 price_cents - v_mentor_cents = hold 차액으로 남김)\n  v_mentor_cents := floor(v_question.price_cents::numeric * 0.85)::bigint;\n  if v_mentor_cents <= 0 then\n    return (false, ''invalid_payout'', ''mentor payout amount must be positive'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  insert into public.cash_ledger (\n    user_id,\n    delta_cents,\n    reason,\n    ref_type,\n    ref_id,\n    idempotency_key\n  )\n  values (\n    v_mentor_id,\n    v_mentor_cents,\n    ''individual_question_payout'',\n    ''individual_questions'',\n    v_question.id,\n    ''iq_payout:'' || v_question.id::text\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_ledger_id;\n\n  if v_ledger_id is not null then\n    v_new_ledger := true;\n  else\n    select id\n      into v_ledger_id\n    from public.cash_ledger\n    where idempotency_key = ''iq_payout:'' || v_question.id::text\n      and reason = ''individual_question_payout'';\n  end if;\n\n  if v_ledger_id is null then\n    raise exception ''INDIVIDUAL_QUESTION_PAYOUT_LEDGER_MISSING'';\n  end if;\n\n  if v_new_ledger then\n    insert into public.cash_wallets (user_id, balance_cents)\n    values (v_mentor_id, 0)\n    on conflict (user_id) do nothing;\n\n    update public.cash_wallets\n    set balance_cents = balance_cents + v_mentor_cents\n    where user_id = v_mentor_id\n    returning balance_cents into v_wallet_balance;\n\n    if not found then\n      raise exception ''INDIVIDUAL_QUESTION_MENTOR_WALLET_CREDIT_FAILED'';\n    end if;\n  end if;\n\n  update public.individual_questions\n  set\n    status = ''released'',\n    released_at = coalesce(released_at, now()),\n    release_ledger_id = v_ledger_id\n  where id = v_question.id\n  returning * into v_question;\n\n  return (true, ''released'', ''individual question payout released'', v_question.id, v_question.status, v_ledger_id, v_wallet_balance)::public.individual_question_escrow_result;\nend;\n$function$", "comment on function public.release_individual_question_payout(uuid) is\n  ''255: 15% platform fee. Mentor payout = floor(price_cents*0.85). Platform 15% implicit in hold. Idempotent (iq_payout:{id}). service_role only.''", "revoke all on function public.release_individual_question_payout(uuid) from public, anon, authenticated", "grant execute on function public.release_individual_question_payout(uuid) to service_role", "commit", "-- 검증(실행 후 확인):\n-- 1) 신규 release 시 멘토 cash_ledger delta = floor(price_cents*0.85), wallet도 동일 증가.\n-- 2) 과거 released 건은 그대로(전액). refund(미답변)는 전액 환불 유지(미변경).\n\n-- >>> NATIVE_BASELINE_PART 0108 | supabase/sql/097_mentor_profile_avatar.sql | 097_mentor_profile_avatar.sql <<<\n-- 멘토 프로필 사진(아바타) — 컬럼 + Storage 버킷 + RLS\n-- 선행: 001(users), mentor_profiles(가입 sync 시 생성)\n-- 표시 1순위 키: lib/mentor/mentorDisplayFields.ts → photoUrl = profile_image_url\n--\n-- ⚠️ 운영 메모: 기존 민감 버킷(student-id-images, community-post-images 등)은\n--    public = false + signed URL 패턴입니다. 프로필 사진은 멘토찾기/상세에서\n--    누구에게나 공개되는 영구 이미지이므로, 저장한 URL이 만료되지 않도록\n--    public = true 버킷 + getPublicUrl 영구 URL을 사용합니다(표시 코드 미터치 전제).\n--    돈/기존 버킷/기존 RLS는 일절 건드리지 않습니다.\n\ncreate extension if not exists pgcrypto", "-- ---------------------------------------------------------------------------\n-- 1) mentor_profiles.profile_image_url 컬럼\n--    (존재 여부 확인: 본 파일 헤더 주석의 점검 쿼리 또는 아래 add ... if not exists)\n-- ---------------------------------------------------------------------------\nalter table public.mentor_profiles\n  add column if not exists profile_image_url text", "-- ---------------------------------------------------------------------------\n-- 2) Storage — profile-avatars (public read, 영구 URL)\n--    community-post-images 버킷 정의를 모델로 하되 public = true.\n-- ---------------------------------------------------------------------------\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues (\n  ''profile-avatars'',\n  ''profile-avatars'',\n  true,\n  5242880,\n  array[''image/jpeg'', ''image/png'', ''image/webp'']::text[]\n)\non conflict (id) do update set\n  public = excluded.public,\n  file_size_limit = excluded.file_size_limit,\n  allowed_mime_types = excluded.allowed_mime_types", "-- 공개 읽기(스토리지 API select 패리티 — public 버킷이라 CDN 경로는 RLS 무관)\ndrop policy if exists \"pa_public_read\" on storage.objects", "create policy \"pa_public_read\"\n  on storage.objects for select\n  to anon, authenticated\n  using (bucket_id = ''profile-avatars'')", "-- 본인 폴더({user_id}/...)만 insert/update/delete\ndrop policy if exists \"pa_auth_insert_own\" on storage.objects", "create policy \"pa_auth_insert_own\"\n  on storage.objects for insert\n  to authenticated\n  with check (\n    bucket_id = ''profile-avatars''\n    and (storage.foldername(name))[1] = (select auth.uid())::text\n  )", "drop policy if exists \"pa_auth_update_own\" on storage.objects", "create policy \"pa_auth_update_own\"\n  on storage.objects for update\n  to authenticated\n  using (\n    bucket_id = ''profile-avatars''\n    and (storage.foldername(name))[1] = (select auth.uid())::text\n  )", "drop policy if exists \"pa_auth_delete_own\" on storage.objects", "create policy \"pa_auth_delete_own\"\n  on storage.objects for delete\n  to authenticated\n  using (\n    bucket_id = ''profile-avatars''\n    and (storage.foldername(name))[1] = (select auth.uid())::text\n  )", "-- >>> NATIVE_BASELINE_PART 0109 | supabase/sql/098_weekly_usage_count_on_create.sql | 098_weekly_usage_count_on_create.sql <<<\n-- =============================================================================\n-- 098_weekly_usage_count_on_create.sql\n-- Purpose: Weekly question quota is consumed on CREATE (thread written), not on\n--          student confirmation. Policy 286/284: count on write, no restore.\n--          Mentor non-answer is handled by report/ops flow, not quota refund.\n--\n-- Prerequisite:\n--   - 065_anchor_weekly_question_usage.sql has been applied.\n--\n-- Scope:\n--   - Replace get_weekly_question_usage(uuid, uuid) only (065 active body).\n--   - No cash debit, renewal batch, escrow, or custom request changes.\n--\n-- Changes vs 065 (ONLY these two lines in the count query):\n--   1) Count condition: qt.status = ''confirmed''\n--        -> lower(coalesce(qt.status,'''')) in (''pending'',''answered'',''confirmed'',''closed'',''archived'')\n--      i.e. any forward (non-discarded) thread, counted from creation.\n--   2) Window timestamp: coalesce(qt.updated_at, qt.created_at) -> qt.created_at\n--      i.e. usage window keyed to write time, independent of later status changes.\n--   Everything else (anchor 7-day boundary, limit, can_ask, signature, return)\n--   is reproduced from 065 verbatim.\n--\n-- Formula (unchanged):\n--   anchor = coalesce(subscriptions.started_at, subscriptions.created_at)\n--   period_start = anchor + floor((now - anchor) / 7 days) * 7 days\n--   period_end = period_start + 7 days\n--\n-- Verify after applying:\n--   select * from get_weekly_question_usage(''<student_uuid>'',''<mentor_uuid>'');\n--   -- After creating 1 pending thread, used should be +1 (before any confirm).\n-- =============================================================================\n\ncreate or replace function public.get_weekly_question_usage(\n  p_student_id uuid,\n  p_mentor_id uuid\n)\nreturns json\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_anchor timestamptz;\n  v_week_start timestamptz;\n  v_week_end timestamptz;\n  v_elapsed_seconds numeric;\n  v_period_index integer;\n  v_used integer := 0;\n  v_plan_tier text;\n  v_limit integer := 0;\nbegin\n  if p_student_id is null or p_mentor_id is null then\n    raise exception ''p_student_id and p_mentor_id are required'';\n  end if;\n\n  select\n    s.plan_tier,\n    coalesce(s.started_at, s.created_at)\n  into v_plan_tier, v_anchor\n  from public.subscriptions s\n  where s.student_id = p_student_id\n    and s.mentor_id = p_mentor_id\n    and lower(coalesce(s.status, '''')) = ''active''\n  order by s.created_at desc\n  limit 1;\n\n  v_limit := case lower(coalesce(v_plan_tier, ''''))\n    when ''limited'' then 4\n    when ''standard'' then 9\n    when ''premium'' then 999\n    else 0\n  end;\n\n  if v_anchor is not null then\n    v_elapsed_seconds := extract(epoch from (now() - v_anchor));\n    v_period_index := greatest(0, floor(v_elapsed_seconds / 604800.0)::integer);\n    v_week_start := v_anchor + (v_period_index * interval ''7 days'');\n    v_week_end := v_week_start + interval ''7 days'';\n\n    select count(*)::integer into v_used\n    from public.question_threads qt\n    inner join public.mentor_student_rooms r on r.id = qt.mentor_student_room_id\n    where r.student_id = p_student_id\n      and r.mentor_id = p_mentor_id\n      and lower(coalesce(qt.status, '''')) in (''pending'', ''answered'', ''confirmed'', ''closed'', ''archived'')\n      and qt.created_at >= v_week_start\n      and qt.created_at < v_week_end;\n  end if;\n\n  return json_build_object(\n    ''used'', coalesce(v_used, 0),\n    ''limit'', v_limit,\n    ''plan_tier'', v_plan_tier,\n    ''remaining'', greatest(0, v_limit - coalesce(v_used, 0)),\n    ''can_ask'', coalesce(v_used, 0) < v_limit,\n    ''week_start'', v_week_start,\n    ''week_end'', v_week_end\n  );\nend;\n$function$", "revoke all on function public.get_weekly_question_usage(uuid, uuid) from public", "grant execute on function public.get_weekly_question_usage(uuid, uuid) to authenticated", "grant execute on function public.get_weekly_question_usage(uuid, uuid) to service_role", "comment on function public.get_weekly_question_usage(uuid, uuid) is\n  ''Weekly question usage: forward (non-discarded) threads counted by created_at in a 7-day window anchored to subscriptions.started_at (fallback created_at), independently per student-mentor subscription. Quota consumed on create (098), not on confirm.''", "-- >>> NATIVE_BASELINE_PART 0110 | supabase/sql/099_subscription_refund_settlement_paid_guard.sql | 099_subscription_refund_settlement_paid_guard.sql <<<\n-- =============================================================================\n-- 099_subscription_refund_settlement_paid_guard.sql\n-- Purpose: Block auto-approval of a SUBSCRIPTION refund when the mentor\n--          settlement for that payment is already ''paid'' (prevents double loss:\n--          mentor keeps payout AND student gets refunded). Mirrors the existing\n--          custom-order guard in 030, which only covered custom_request_order_id.\n--\n-- Prerequisite:\n--   - 030_p0_refund_approve_reject_admin_rpc.sql has been applied.\n--   - 086_subscription_settlement_items.sql has been applied.\n--   - 069_subscription_cancel_refund_request.sql has been applied\n--     (refunds.subscription_id / request_type).\n--\n-- Scope:\n--   - Replace approve_refund_request_admin(uuid, uuid, text) only.\n--   - reject_refund_request_admin is NOT touched.\n--   - Full 030 approve body reproduced verbatim; ONLY the new subscription guard\n--     block is inserted (right after the custom-order guard, before the amount\n--     check). v_settlement_status is already declared in 030 (reused).\n--\n-- Guard semantics (design 285):\n--   - Match by payment_id (NOT subscription_id) so a multi-period subscription''s\n--     old paid renewal does NOT false-block a refund of a newer unpaid period.\n--   - Any ''paid'' settlement item on that payment -> soft refuse (ok:false),\n--     no cash/ledger mutation, route admin to manual handling.\n--\n-- Verify after applying:\n--   select proname from pg_proc where proname = ''approve_refund_request_admin'';\n-- Test A (must pass): settlement pending/hold -> approve -> ok:true (refund runs).\n-- Test B (must block): settlement paid -> approve -> ok:false (manual), no cash change.\n-- =============================================================================\n\ncreate or replace function public.approve_refund_request_admin(\n  p_refund_id uuid,\n  p_admin_id uuid,\n  p_admin_note text default null\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  r public.refunds%rowtype;\n  v_amount bigint;\n  v_settlement_status text;\n  v_idem text := ''refund_credit:'' || p_refund_id::text;\n  v_ledger_id uuid;\n  v_existing_delta bigint;\n  v_wu int;\n  v_admin_ok boolean;\nbegin\n  if p_refund_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''환불 ID가 필요합니다.'');\n  end if;\n  if p_admin_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''관리자 ID가 필요합니다.'');\n  end if;\n\n  select exists(\n    select 1 from public.users u where u.id = p_admin_id and u.role = ''admin''\n  ) into v_admin_ok;\n  if not coalesce(v_admin_ok, false) then\n    raise exception ''ADMIN_REQUIRED'';\n  end if;\n\n  select * into r from public.refunds where id = p_refund_id for update;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''message'', ''환불 요청을 찾을 수 없습니다.'');\n  end if;\n\n  if r.status is distinct from ''pending'' then\n    return jsonb_build_object(\n      ''ok'', true,\n      ''noop'', true,\n      ''refund_id'', p_refund_id,\n      ''message'', ''이미 처리되었거나 대기 상태가 아닙니다.'',\n      ''status'', r.status\n    );\n  end if;\n\n  -- 정산 지급 완료 시 자동 환불 차단 (맞춤의뢰)\n  if r.custom_request_order_id is not null then\n    select s.status into v_settlement_status\n    from public.custom_order_settlement_items s\n    where s.custom_request_order_id = r.custom_request_order_id\n    limit 1;\n    if found and v_settlement_status = ''paid'' then\n      return jsonb_build_object(\n        ''ok'', false,\n        ''message'', ''이미 정산 지급이 완료된 건은 자동 환불할 수 없습니다. 수동 조정이 필요합니다.''\n      );\n    end if;\n  end if;\n\n  -- 정산 지급 완료 시 자동 환불 차단 (구독) — 099 추가\n  -- payment_id 매칭: 다기간 구독의 과거 paid 갱신분이 신규 미지급 기간 환불을 오탐 차단하지 않도록.\n  if r.payment_id is not null\n     and (r.subscription_id is not null\n          or coalesce(r.request_type, '''') = ''subscription_prorated'') then\n    select s.status into v_settlement_status\n    from public.subscription_settlement_items s\n    where s.payment_id = r.payment_id\n      and s.status = ''paid''\n    limit 1;\n    if found then\n      return jsonb_build_object(\n        ''ok'', false,\n        ''message'', ''이미 멘토 정산 지급이 완료된 구독 건은 자동 환불할 수 없습니다. 수동 조정이 필요합니다.''\n      );\n    end if;\n  end if;\n\n  if r.amount_cents is null or r.amount_cents <= 0 then\n    raise exception ''환불 금액이 설정되지 않아 자동 승인할 수 없습니다.'';\n  end if;\n\n  v_amount := r.amount_cents;\n\n  if v_amount > 1000000000 then\n    return jsonb_build_object(''ok'', false, ''message'', ''환불 금액이 허용 한도를 초과합니다.'');\n  end if;\n\n  -- 정산 예정만 취소 (paid 는 위에서 차단)\n  if r.custom_request_order_id is not null then\n    update public.custom_order_settlement_items s\n    set status = ''cancelled'', updated_at = now()\n    where s.custom_request_order_id = r.custom_request_order_id\n      and s.status in (''pending'', ''on_hold'', ''payable'');\n  end if;\n\n  insert into public.cash_ledger (\n    user_id, delta_cents, reason, ref_type, ref_id, idempotency_key\n  )\n  values (\n    r.user_id, v_amount, ''refund_approved'', ''refunds'', r.id, v_idem\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_ledger_id;\n\n  if v_ledger_id is null then\n    select cl.delta_cents into v_existing_delta\n    from public.cash_ledger cl\n    where cl.idempotency_key = v_idem\n    limit 1;\n    if not found then\n      raise exception ''REFUND_LEDGER_IDEMPOTENT_MISS'' using errcode = ''P0001'';\n    end if;\n    if v_existing_delta is distinct from v_amount then\n      raise exception ''REFUND_LEDGER_AMOUNT_MISMATCH'' using errcode = ''P0001'';\n    end if;\n  end if;\n\n  if v_ledger_id is not null then\n    insert into public.cash_wallets (user_id, balance_cents)\n    values (r.user_id, 0)\n    on conflict (user_id) do nothing;\n\n    update public.cash_wallets w\n    set balance_cents = w.balance_cents + v_amount\n    where w.user_id = r.user_id;\n    get diagnostics v_wu = row_count;\n    if coalesce(v_wu, 0) = 0 then\n      raise exception ''CASH_WALLET_UPDATE_FAILED'' using errcode = ''P0001'';\n    end if;\n  end if;\n\n  update public.refunds\n  set\n    status = ''succeeded'',\n    processed_at = now(),\n    processed_by = p_admin_id,\n    admin_note = p_admin_note,\n    updated_at = now()\n  where id = r.id;\n\n  if r.payment_id is not null then\n    update public.payments p\n    set status = ''refunded'', updated_at = now()\n    where p.id = r.payment_id;\n  end if;\n\n  if r.payment_id is not null then\n    update public.subscriptions s\n    set status = ''canceled'', updated_at = now()\n    where s.payment_id = r.payment_id\n      and s.status is distinct from ''canceled'';\n  end if;\n\n  if r.custom_request_order_id is not null then\n    update public.custom_request_orders o\n    set payment_status = ''refunded'', updated_at = now()\n    where o.id = r.custom_request_order_id;\n  end if;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''noop'', false,\n    ''refund_id'', r.id,\n    ''ledger_inserted'', (v_ledger_id is not null),\n    ''amount_cents'', v_amount,\n    ''message'', ''환불이 승인되었습니다.''\n  );\nend;\n$function$", "-- EXECUTE: service_role 만 (승인 RPC) — 030 과 동일 권한 재적용\nrevoke all on function public.approve_refund_request_admin(uuid, uuid, text) from public", "revoke all on function public.approve_refund_request_admin(uuid, uuid, text) from anon", "revoke all on function public.approve_refund_request_admin(uuid, uuid, text) from authenticated", "grant execute on function public.approve_refund_request_admin(uuid, uuid, text) to service_role", "comment on function public.approve_refund_request_admin(uuid, uuid, text)\n  is ''P0: Admin refund approve — idempotent ledger credit, service_role only. Blocks auto-refund when custom-order OR subscription settlement (by payment_id) is already paid (099).''", "-- >>> NATIVE_BASELINE_PART 0111 | supabase/sql/100_fix_subscription_renewal_attempt_count.sql | 100_fix_subscription_renewal_attempt_count.sql <<<\n-- =============================================================================\n-- 100_fix_subscription_renewal_attempt_count.sql\n--\n-- Purpose: SQL 068 `process_subscription_renewal` 재시도(RETRY) 경로의\n--   `column reference \"attempt_count\" is ambiguous` 버그 패치.\n--\n-- Bug: 함수가 `returns table (... attempt_count int)` 로 output 컬럼을 가지므로,\n--   068 102~113행의 UPDATE … SET attempt_count = coalesce(attempt_count, 0) + 1\n--   에서 RHS의 unqualified `attempt_count` 가 출력 컬럼 vs 테이블 컬럼으로 모호.\n--   결과: insufficient_cash로 past_due 된 구독을 학생이 충전한 뒤 다음 배치에서\n--   재시도 시 RPC가 ERROR로 롤백 → 영원히 복구 불가.\n--\n-- Fix: RHS만 `e.attempt_count` 로 테이블 별칭 prefix 추가 (의미 동일, ambiguous 해소).\n--   - 갱신/차감/멱등/돈 흐름 로직 변경 없음\n--   - 멱등 키(`sub_renewal:<id>:<date>`) 그대로\n--   - 본문 그 외 모든 라인 068과 일치\n--   - 함수 시그니처/리턴 타입/SECURITY DEFINER/search_path 동일\n--\n-- Apply:\n--   psql -f supabase/sql/100_fix_subscription_renewal_attempt_count.sql\n--\n-- 검증(이 파일 적용 후):\n--   1) e2e/subscription-renewal-sim.spec.ts 의 2-3b 가 PASS 되어\n--      past_due → 충전 → 다음 배치 → renewed + status=active 가 되어야 함\n--   2) 2-1(취소만료) / 2-2(정상 갱신·멱등) / 2-3(잔액부족 past_due) 회귀 없음\n--\n-- Rollback: 068 SQL을 다시 적용하면 원복.\n-- =============================================================================\n\ncreate or replace function public.process_subscription_renewal(\n  p_subscription_id uuid,\n  p_period_end timestamptz,\n  p_amount_cents bigint,\n  p_idempotency_key text,\n  p_processed_at timestamptz default now()\n)\nreturns table (\n  ok boolean,\n  code text,\n  message text,\n  billing_event_id uuid,\n  ledger_id uuid,\n  next_period_start timestamptz,\n  next_period_end timestamptz,\n  wallet_balance_cents bigint,\n  attempt_count int\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_sub public.subscriptions%rowtype;\n  v_event public.subscription_billing_events%rowtype;\n  v_event_id uuid;\n  v_ledger_id uuid;\n  v_wallet_balance bigint;\n  v_period_start timestamptz;\n  v_period_end timestamptz;\n  v_attempt_count int;\nbegin\n  if p_subscription_id is null then\n    return query select false, ''invalid_subscription''::text, ''subscription_id is required''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\n    return;\n  end if;\n\n  if p_amount_cents is null or p_amount_cents <= 0 then\n    return query select false, ''invalid_amount''::text, ''p_amount_cents must be positive''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\n    return;\n  end if;\n\n  if p_idempotency_key is null or length(trim(p_idempotency_key)) = 0 then\n    return query select false, ''invalid_idempotency_key''::text, ''idempotency_key is required''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\n    return;\n  end if;\n\n  select *\n    into v_sub\n  from public.subscriptions\n  where id = p_subscription_id\n  for update;\n\n  if not found then\n    return query select false, ''not_found''::text, ''subscription not found''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\n    return;\n  end if;\n\n  if coalesce(v_sub.status, '''') not in (''active'', ''past_due'') then\n    return query select false, ''not_renewable_status''::text, ''subscription status is not renewable''::text, null::uuid, null::uuid, v_sub.current_period_start, v_sub.current_period_end, null::bigint, 0::int;\n    return;\n  end if;\n\n  select *\n    into v_event\n  from public.subscription_billing_events\n  where idempotency_key = p_idempotency_key\n  for update;\n\n  if found then\n    if v_event.status = ''succeeded'' then\n      return query select true, ''already_succeeded''::text, ''renewal already processed''::text, v_event.id, v_event.ledger_id, v_event.period_start, v_event.period_end, null::bigint, coalesce(v_event.attempt_count, 0);\n      return;\n    end if;\n\n    if v_event.status in (''pending'', ''processing'') then\n      return query select false, ''already_processing''::text, ''renewal is already processing''::text, v_event.id, v_event.ledger_id, v_event.period_start, v_event.period_end, null::bigint, coalesce(v_event.attempt_count, 0);\n      return;\n    end if;\n\n    -- ★ 패치: RHS의 unqualified `attempt_count` 를 `e.attempt_count` 로 한정.\n    --   (이 SET 절 외 다른 모든 라인은 068과 일치.)\n    update public.subscription_billing_events as e\n    set\n      event_type = ''renewal'',\n      status = ''processing'',\n      failure_code = null,\n      failure_message = null,\n      amount_cents = p_amount_cents::int,\n      billing_at = p_processed_at,\n      attempt_count = coalesce(e.attempt_count, 0) + 1,\n      processed_at = null\n    where e.id = v_event.id\n    returning e.* into v_event;\n\n    v_event_id := v_event.id;\n    v_attempt_count := coalesce(v_event.attempt_count, 1);\n  else\n    v_period_start := coalesce(v_sub.current_period_end, p_period_end, p_processed_at);\n    v_period_end := v_period_start + interval ''1 month'';\n\n    insert into public.subscription_billing_events (\n      subscription_id,\n      student_id,\n      mentor_id,\n      event_type,\n      status,\n      period_start,\n      period_end,\n      billing_at,\n      amount_cents,\n      plan_tier,\n      plan_id,\n      idempotency_key,\n      attempt_count,\n      created_at\n    )\n    values (\n      v_sub.id,\n      v_sub.student_id,\n      v_sub.mentor_id,\n      ''renewal'',\n      ''processing'',\n      v_period_start,\n      v_period_end,\n      p_processed_at,\n      p_amount_cents::int,\n      v_sub.plan_tier,\n      v_sub.plan_id,\n      p_idempotency_key,\n      1,\n      p_processed_at\n    )\n    returning * into v_event;\n\n    v_event_id := v_event.id;\n    v_attempt_count := 1;\n  end if;\n\n  insert into public.cash_wallets (user_id, balance_cents)\n  values (v_sub.student_id, 0)\n  on conflict (user_id) do nothing;\n\n  update public.cash_wallets\n  set balance_cents = balance_cents - p_amount_cents\n  where user_id = v_sub.student_id\n    and balance_cents >= p_amount_cents\n  returning balance_cents into v_wallet_balance;\n\n  if not found then\n    update public.subscription_billing_events as e\n    set\n      event_type = ''renewal_failed'',\n      status = ''failed'',\n      failure_code = ''insufficient_cash'',\n      failure_message = ''CASH_INSUFFICIENT'',\n      processed_at = p_processed_at\n    where e.id = v_event_id\n    returning e.attempt_count into v_attempt_count;\n\n    update public.subscriptions\n    set\n      status = ''past_due'',\n      grace_until = coalesce(grace_until, p_processed_at + interval ''2 days''),\n      updated_at = p_processed_at,\n      last_billing_event_id = v_event_id\n    where id = v_sub.id;\n\n    return query select false, ''insufficient_cash''::text, ''CASH_INSUFFICIENT''::text, v_event_id, null::uuid, v_event.period_start, v_event.period_end, null::bigint, coalesce(v_attempt_count, 1);\n    return;\n  end if;\n\n  insert into public.cash_ledger (\n    user_id,\n    delta_cents,\n    reason,\n    ref_type,\n    ref_id,\n    idempotency_key,\n    created_at\n  )\n  values (\n    v_sub.student_id,\n    -p_amount_cents,\n    ''subscription_renewal'',\n    ''subscriptions'',\n    v_sub.id,\n    p_idempotency_key,\n    p_processed_at\n  )\n  on conflict (idempotency_key) do nothing\n  returning id into v_ledger_id;\n\n  if v_ledger_id is null then\n    select id\n      into v_ledger_id\n    from public.cash_ledger\n    where idempotency_key = p_idempotency_key;\n  end if;\n\n  v_period_start := coalesce(v_event.period_start, v_sub.current_period_end, p_period_end, p_processed_at);\n  v_period_end := coalesce(v_event.period_end, v_period_start + interval ''1 month'');\n\n  update public.subscription_billing_events as e\n  set\n    event_type = ''renewal'',\n    status = ''succeeded'',\n    ledger_id = v_ledger_id,\n    processed_at = p_processed_at,\n    failure_code = null,\n    failure_message = null,\n    period_start = v_period_start,\n    period_end = v_period_end,\n    amount_cents = p_amount_cents::int\n  where e.id = v_event_id\n  returning e.attempt_count into v_attempt_count;\n\n  update public.subscriptions\n  set\n    status = ''active'',\n    current_period_start = v_period_start,\n    current_period_end = v_period_end,\n    next_billing_at = v_period_end,\n    last_renewed_at = p_processed_at,\n    last_billing_event_id = v_event_id,\n    grace_until = null,\n    updated_at = p_processed_at\n  where id = v_sub.id;\n\n  return query select true, ''succeeded''::text, ''renewal processed''::text, v_event_id, v_ledger_id, v_period_start, v_period_end, v_wallet_balance, coalesce(v_attempt_count, 1);\nend;\n$function$", "-- GRANT/REVOKE 는 068에서 이미 설정되어 있으나 안전을 위해 재선언(중복 무해).\nrevoke all on function public.process_subscription_renewal(uuid, timestamptz, bigint, text, timestamptz) from public", "grant execute on function public.process_subscription_renewal(uuid, timestamptz, bigint, text, timestamptz) to service_role", "comment on function public.process_subscription_renewal(uuid, timestamptz, bigint, text, timestamptz) is\n  ''Subscription renewal RPC (068) + 100 patch: ambiguous `attempt_count` reference resolved with `e.` table alias on the retry-path UPDATE. Logic/idempotency/money flow unchanged.''", "-- >>> NATIVE_BASELINE_PART 0112 | supabase/sql/101_community_comments_admin_moderation.sql | 101_community_comments_admin_moderation.sql <<<\n-- =============================================================================\n-- 101_community_comments_admin_moderation.sql\n--\n-- Purpose: community_comments 모더레이션 활성화 — 현재 UPDATE/DELETE RLS 정책\n--   자체가 없어 admin도 댓글을 hidden 으로 바꾸거나 삭제할 수 없음.\n--\n-- Changes (RLS only):\n--   1) community_comments_update_admin (UPDATE) — admin 만 통과\n--   2) community_comments_delete_admin (DELETE) — admin 만 통과\n--   3) SELECT 정책 교체 — 기존 ''community_comments_select_visible''(visible 만)\n--      을 작성자 본인 + admin도 볼 수 있게 확장(작성자 본인 댓글 hidden 후\n--      자기 댓글 회수·검토 가능).\n--\n-- Safety:\n--   - 컬럼·테이블 스키마 변경 없음. RLS 정책만 추가/교체.\n--   - DML/Trigger/Index 미변경.\n--   - is_admin() (SECURITY DEFINER 함수) 는 기존 활성 정책(community_posts /\n--     shortform_posts) 와 동일 패턴.\n--\n-- Apply (로컬):\n--   psql -f supabase/sql/101_community_comments_admin_moderation.sql\n--\n-- Verify:\n--   select polname from pg_policies where tablename=''community_comments'';\n--   -- expect: community_comments_insert_authenticated,\n--   --          community_comments_select_visible,\n--   --          community_comments_update_admin,\n--   --          community_comments_delete_admin\n--\n-- Rollback:\n--   drop policy if exists \"community_comments_update_admin\" on public.community_comments;\n--   drop policy if exists \"community_comments_delete_admin\" on public.community_comments;\n--   drop policy if exists \"community_comments_select_visible\" on public.community_comments;\n--   create policy \"community_comments_select_visible\" on public.community_comments\n--     for select to anon, authenticated using (status = ''visible'');\n-- =============================================================================\n\nbegin", "-- SELECT 정책 교체 — visible 댓글 누구나 / 본인 댓글 + admin 은 hidden 도 조회\ndrop policy if exists \"community_comments_select_visible\" on public.community_comments", "create policy \"community_comments_select_visible\"\n  on public.community_comments\n  for select\n  to anon, authenticated\n  using (\n    status = ''visible''\n    or author_id = (select auth.uid())\n    or (select public.is_admin()) = true\n  )", "-- UPDATE 정책 — admin 전용(작성자 본인 수정은 별도 정책이 없으면 보존하지\n-- 않음. 현 스키마는 댓글 수정 UI 없음, 추후 author update 정책 필요 시 별도 추가).\ndrop policy if exists \"community_comments_update_admin\" on public.community_comments", "create policy \"community_comments_update_admin\"\n  on public.community_comments\n  for update\n  to authenticated\n  using ((select public.is_admin()) = true)\n  with check ((select public.is_admin()) = true)", "-- DELETE 정책 — admin 전용\ndrop policy if exists \"community_comments_delete_admin\" on public.community_comments", "create policy \"community_comments_delete_admin\"\n  on public.community_comments\n  for delete\n  to authenticated\n  using ((select public.is_admin()) = true)", "comment on policy \"community_comments_select_visible\" on public.community_comments is\n  ''community_comments: visible 댓글은 누구나 / 본인 댓글 또는 admin 은 hidden 도 조회''", "comment on policy \"community_comments_update_admin\" on public.community_comments is\n  ''community_comments: admin 만 status 등 변경(모더레이션) 가능''", "comment on policy \"community_comments_delete_admin\" on public.community_comments is\n  ''community_comments: admin 만 행 삭제 가능''", "commit", "-- >>> NATIVE_BASELINE_PART 0113 | supabase/sql/102_account_status_management.sql | 102_account_status_management.sql <<<\n-- 102_account_status_management.sql\n-- P0 #4 — 계정 상태 관리(active / suspended / banned)\n--\n-- 정책\n--  - users.status 는 이미 존재(default ''active''). 여기서는 정지/차단 부가정보 컬럼만 추가.\n--  - suspended : 일시 정지. suspended_until 이 있으면 그 시각 이후 자동 해제(앱 가드가 lazy 판정).\n--  - banned    : 영구 차단(suspended_until = null).\n--  - 핵심 액션 차단은 RLS 가 아니라 앱 서버 액션 가드에서 수행(테스트·복구 용이, 검증된 RLS 보존).\n--  - DB check 제약은 추가하지 않음(운영 기존 데이터 보호). 허용값은 앱에서 강제.\n--\n-- 운영 적용 대상: 예(컬럼 추가 + 인덱스, 파괴적 변경 없음).\n\nalter table public.users\n  add column if not exists suspended_until timestamptz,\n  add column if not exists status_reason text,\n  add column if not exists status_changed_at timestamptz,\n  add column if not exists status_changed_by uuid references public.users (id) on delete set null", "comment on column public.users.suspended_until is ''정지 만료 시각(suspended 전용). null=영구/미설정. 이 시각 이후 앱 가드가 active로 간주''", "comment on column public.users.status_reason is ''정지/차단 사유(관리자 기록)''", "comment on column public.users.status_changed_at is ''상태 마지막 변경 시각''", "comment on column public.users.status_changed_by is ''상태를 변경한 관리자 user id''", "-- 정지/차단 계정 빠른 조회용(active 가 대부분이라 부분 인덱스)\ncreate index if not exists users_status_blocked_idx\n  on public.users (status, suspended_until)\n  where status <> ''active''", "-- >>> NATIVE_BASELINE_PART 0114 | supabase/sql/103_mentor_activity_suspension.sql | 103_mentor_activity_suspension.sql <<<\n-- 103_mentor_activity_suspension.sql\n-- P0 #5 — 멘토 활동 중단 대안(완전 종료 / 일시 중단 / 무단 이탈)\n--\n-- 정책 요약\n--  - 완전 종료: 즉시 신규 구독 차단 + 2주 사전 공지 → 유예 종료 시 잔여 100% 환불.\n--  - 일시 중단: 최대 1주. 쉰 일수만큼 구독 기간 연장. 일반휴식 6개월 1회 빈도제한, 질병 예외(관리자 확인).\n--  - 무단 이탈: 정산 자동 0 처리 금지 → \"정산 보류 + 무단이탈 의심\"으로 관리자 큐에 올려 최종 확인(구제 가능).\n--  - 떠나는 멘토의 질문방·연결노트 기록은 보존(별도 DDL 없음 — on delete 미사용).\n--\n-- 운영 적용 대상: 예(컬럼 추가 + 신규 테이블, 파괴적 변경 없음).\n\n-- 1) mentor_profiles 활동 상태 컬럼\nalter table public.mentor_profiles\n  add column if not exists activity_status text not null default ''active'',\n  add column if not exists termination_requested_at timestamptz,\n  add column if not exists termination_effective_at timestamptz,\n  add column if not exists pause_started_at timestamptz,\n  add column if not exists pause_until timestamptz,\n  add column if not exists pause_reason text,\n  add column if not exists last_pause_at timestamptz,\n  add column if not exists abandonment_flagged_at timestamptz", "comment on column public.mentor_profiles.activity_status is ''active | terminating(2주 공지중) | terminated | paused''", "comment on column public.mentor_profiles.termination_effective_at is ''완전종료 유예 만료(요청+14일). 이후 잔여 환불 생성 대상''", "comment on column public.mentor_profiles.pause_until is ''일시중단 복귀 예정 시각(최대 +7일)''", "comment on column public.mentor_profiles.last_pause_at is ''마지막 일반휴식 시각(6개월 빈도 제한 판정)''", "comment on column public.mentor_profiles.abandonment_flagged_at is ''무단이탈 의심 플래그 시각''", "-- 2) mentor_plans 비활성 플래그(중단 시 신규 노출 차단용 소프트 플래그)\nalter table public.mentor_plans\n  add column if not exists is_active boolean not null default true", "comment on column public.mentor_plans.is_active is ''멘토 활동 중단 시 false. 신규 구독 노출/허용 게이트(가격 계산값은 보존)''", "-- 3) 멘토 활동 이벤트(관리자 검토 큐 + 감사)\ncreate table if not exists public.mentor_activity_events (\n  id uuid primary key default gen_random_uuid(),\n  mentor_id uuid not null references public.users (id) on delete cascade,\n  event_type text not null,    -- termination_requested | termination_finalized | pause_started | pause_resumed | abandonment_suspected\n  reason text,\n  detail jsonb,\n  status text not null default ''logged'',  -- logged | pending_review | approved(=정산보류 확정) | released(=구제)\n  created_at timestamptz not null default now(),\n  reviewed_by uuid references public.users (id) on delete set null,\n  reviewed_at timestamptz\n)", "create index if not exists mentor_activity_events_mentor_idx\n  on public.mentor_activity_events (mentor_id, created_at desc)", "create index if not exists mentor_activity_events_review_idx\n  on public.mentor_activity_events (status)\n  where status = ''pending_review''", "-- RLS: 관리자 콘솔은 service_role 로 접근. 일반 사용자 직접 접근 차단(정책 없음 = 잠금).\nalter table public.mentor_activity_events enable row level security", "-- >>> NATIVE_BASELINE_PART 0115 | supabase/sql/104_user_warnings.sql | 104_user_warnings.sql <<<\n-- 104_user_warnings.sql\n-- P1 ② — 사용자 경고 누적 → N회(3회) 시 자동 일시정지\n--\n-- 정책\n--  - 관리자(또는 분쟁/신고 처리)가 경고를 발급 → user_warnings 누적.\n--  - 활성 경고가 임계치(기본 3) 도달 시 앱에서 자동으로 users.status=''suspended''(7일).\n--  - 자동 정지 메커니즘은 PART A(102)의 계정 상태 + applyAccountStatus 재사용.\n--\n-- 운영 적용 대상: 예(신규 테이블 + 인덱스).\n\ncreate table if not exists public.user_warnings (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete cascade,\n  issued_by uuid references public.users (id) on delete set null,\n  reason text not null,\n  severity text not null default ''normal'',  -- normal | severe\n  source text not null default ''admin'',     -- admin | dispute | report\n  is_active boolean not null default true,   -- 만료/철회 시 false\n  created_at timestamptz not null default now()\n)", "create index if not exists user_warnings_user_idx\n  on public.user_warnings (user_id, created_at desc)", "create index if not exists user_warnings_active_idx\n  on public.user_warnings (user_id)\n  where is_active = true", "comment on table public.user_warnings is ''사용자 경고 누적 로그. 활성 경고 3회 도달 시 앱이 자동 일시정지''", "-- 관리자 콘솔은 service_role 로 접근. 일반 사용자 직접 접근 차단(정책 없음 = 잠금).\nalter table public.user_warnings enable row level security", "-- >>> NATIVE_BASELINE_PART 0116 | supabase/sql/105_subscription_settlement_period_gating.sql | 105_subscription_settlement_period_gating.sql <<<\n-- =============================================================================\n-- 105_subscription_settlement_period_gating.sql   [DRAFT — DB 미적용]\n-- 목적(토대): 구독 정산항목을 \"기간 완료(period_end<=now) 후에만 지급대기(pending)\"가\n--   되도록 게이팅한다. 미완료 사이클은 새 상태 ''accruing''(지급 불가)로 둔다.\n--   즉시지급 동작·수수료·돈 이동은 이 파일에서 바꾸지 않는다(086 본문 verbatim + 게이팅만).\n--\n-- 선행: 086 → 095_subscription_fee_15pct.sql 적용됨.\n-- 적용: 사용자가 Supabase에서 직접 실행(이 단계에선 미적용).\n--\n-- ★ 베이스 = 095 버전(구독 수수료 15%/85%). 30% 회귀 아님.\n--   현재 유효 정의는 095(095:21 create or replace, 0.15: 095:79-80 계산·095:130 insert·\n--   095:18 컬럼 default)다. 086의 30%는 stale(095가 덮어씀). 본 105는 105가 095보다\n--   나중 번호라 함수를 재정의하므로, 반드시 095(0.15) 본문을 베이스로 삼는다.\n--   계산 2곳 + insert fee_rate 1곳 모두 0.15 — 0.30 절대 금지(있으면 15→30 회귀 버그).\n--   (CLAUDE.md 30%는 stale이나 이 프롬프트 범위 밖 — 미수정. fee_rate 컬럼 default는\n--    095:18이 이미 0.15로 바꿔둠 → 본 파일은 default 미터치.)\n--\n-- 변경점(095 베이스 대비, 딱 4가지 — 수수료는 095 그대로 0.15):\n--   (1) status CHECK 에 ''accruing'' 추가.\n--   (2) INSERT 블록 calculated CASE: else ''pending'' 앞에\n--       when period_end is null or period_end > now() then ''accruing''.\n--   (3) UPDATE(재싱크) 블록: source_events 에 e.period_end 추가 + 동일 CASE 게이팅 +\n--       WHERE 에 업그레이드 1줄 or (c.sync_status=''pending'' and i.status=''accruing'').\n--       (paid 는 i.status<>''paid'' 가드로 절대 미터치 — 086 그대로)\n--   (4) 1회성 백필: status=''pending'' 이며 미완료(period_end null/미래) → ''accruing''.\n-- =============================================================================\n\n-- (1) status CHECK 에 ''accruing'' 추가 (086:33 인라인 CHECK 교체)\nalter table public.subscription_settlement_items\n  drop constraint if exists subscription_settlement_items_status_check", "alter table public.subscription_settlement_items\n  add constraint subscription_settlement_items_status_check\n  check (status in (''accruing'', ''pending'', ''paid'', ''hold'', ''canceled''))", "-- (2)(3) refresh 함수 재정의 — 086 본문 동일 + period 게이팅만 추가\ncreate or replace function public.refresh_subscription_settlement_items(\n  p_from timestamptz default null,\n  p_to timestamptz default null\n)\nreturns table (\n  item_status text,\n  item_count bigint,\n  gross_cents bigint,\n  platform_fee_cents bigint,\n  mentor_amount_cents bigint\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\nbegin\n  with source_events as (\n    select\n      e.id as billing_event_id,\n      e.subscription_id,\n      e.student_id,\n      e.mentor_id,\n      e.payment_id,\n      e.ledger_id,\n      e.event_type,\n      coalesce(e.billing_at, e.processed_at, e.created_at) as billing_at,\n      e.period_start,\n      e.period_end,\n      e.amount_cents::bigint as gross_cents,\n      lower(coalesce(s.status, '''')) as subscription_status,\n      coalesce(s.cancel_at_period_end, false) as cancel_at_period_end,\n      coalesce(rf.has_pending_refund, false) as has_pending_refund,\n      coalesce(rf.has_succeeded_refund, false) as has_succeeded_refund\n    from public.subscription_billing_events e\n    join public.subscriptions s on s.id = e.subscription_id\n    left join lateral (\n      select\n        bool_or(lower(coalesce(r.status, '''')) = ''pending'') as has_pending_refund,\n        bool_or(lower(coalesce(r.status, '''')) in (''succeeded'', ''success'', ''approved'', ''paid'')) as has_succeeded_refund\n      from public.refunds r\n      where coalesce(r.request_type, '''') = ''subscription_prorated''\n        and (\n          r.subscription_id = e.subscription_id\n          or (\n            r.subscription_id is null\n            and r.payment_id is not null\n            and r.payment_id = e.payment_id\n          )\n        )\n    ) rf on true\n    where e.status = ''succeeded''\n      and e.event_type in (''initial'', ''renewal'')\n      and coalesce(e.amount_cents, 0) > 0\n      and (p_from is null or coalesce(e.billing_at, e.processed_at, e.created_at) >= p_from)\n      and (p_to is null or coalesce(e.billing_at, e.processed_at, e.created_at) < p_to)\n  ), calculated as (\n    select\n      se.*,\n      floor(se.gross_cents::numeric * 0.15)::bigint as platform_fee_cents,\n      (se.gross_cents - floor(se.gross_cents::numeric * 0.15)::bigint) as mentor_amount_cents,\n      case\n        when se.has_succeeded_refund or se.subscription_status = ''refunded'' then ''canceled''\n        when se.has_pending_refund then ''hold''\n        when se.subscription_status in (''cancel_scheduled'', ''canceled'', ''cancelled'', ''expired'') then ''hold''\n        when se.cancel_at_period_end then ''hold''\n        -- [105 게이팅] 기간 미완료(또는 period_end 미상)면 지급 불가 = accruing\n        when se.period_end is null or se.period_end > now() then ''accruing''\n        else ''pending''\n      end as sync_status,\n      case\n        when se.has_succeeded_refund or se.subscription_status = ''refunded'' then ''refund_succeeded''\n        when se.has_pending_refund then ''refund_pending''\n        when se.subscription_status in (''cancel_scheduled'', ''canceled'', ''cancelled'', ''expired'') then ''subscription_canceled_or_expired''\n        when se.cancel_at_period_end then ''cancel_at_period_end''\n        else null\n      end as sync_hold_reason\n    from source_events se\n  )\n  insert into public.subscription_settlement_items (\n    billing_event_id,\n    subscription_id,\n    mentor_id,\n    student_id,\n    payment_id,\n    ledger_id,\n    event_type,\n    billing_at,\n    period_start,\n    period_end,\n    gross_cents,\n    platform_fee_cents,\n    mentor_amount_cents,\n    fee_rate,\n    status,\n    hold_reason,\n    idempotency_key\n  )\n  select\n    c.billing_event_id,\n    c.subscription_id,\n    c.mentor_id,\n    c.student_id,\n    c.payment_id,\n    c.ledger_id,\n    c.event_type,\n    c.billing_at,\n    c.period_start,\n    c.period_end,\n    c.gross_cents,\n    c.platform_fee_cents,\n    c.mentor_amount_cents,\n    0.15,\n    c.sync_status,\n    c.sync_hold_reason,\n    ''sub_settlement:'' || c.billing_event_id::text\n  from calculated c\n  on conflict (billing_event_id) do nothing;\n\n  with source_events as (\n    select\n      e.id as billing_event_id,\n      e.period_end,\n      lower(coalesce(s.status, '''')) as subscription_status,\n      coalesce(s.cancel_at_period_end, false) as cancel_at_period_end,\n      coalesce(rf.has_pending_refund, false) as has_pending_refund,\n      coalesce(rf.has_succeeded_refund, false) as has_succeeded_refund\n    from public.subscription_billing_events e\n    join public.subscriptions s on s.id = e.subscription_id\n    left join lateral (\n      select\n        bool_or(lower(coalesce(r.status, '''')) = ''pending'') as has_pending_refund,\n        bool_or(lower(coalesce(r.status, '''')) in (''succeeded'', ''success'', ''approved'', ''paid'')) as has_succeeded_refund\n      from public.refunds r\n      where coalesce(r.request_type, '''') = ''subscription_prorated''\n        and (\n          r.subscription_id = e.subscription_id\n          or (\n            r.subscription_id is null\n            and r.payment_id is not null\n            and r.payment_id = e.payment_id\n          )\n        )\n    ) rf on true\n    where e.status = ''succeeded''\n      and e.event_type in (''initial'', ''renewal'')\n      and coalesce(e.amount_cents, 0) > 0\n      and (p_from is null or coalesce(e.billing_at, e.processed_at, e.created_at) >= p_from)\n      and (p_to is null or coalesce(e.billing_at, e.processed_at, e.created_at) < p_to)\n  ), calculated as (\n    select\n      se.billing_event_id,\n      case\n        when se.has_succeeded_refund or se.subscription_status = ''refunded'' then ''canceled''\n        when se.has_pending_refund then ''hold''\n        when se.subscription_status in (''cancel_scheduled'', ''canceled'', ''cancelled'', ''expired'') then ''hold''\n        when se.cancel_at_period_end then ''hold''\n        -- [105 게이팅] 기간 미완료(또는 period_end 미상)면 accruing\n        when se.period_end is null or se.period_end > now() then ''accruing''\n        else ''pending''\n      end as sync_status,\n      case\n        when se.has_succeeded_refund or se.subscription_status = ''refunded'' then ''refund_succeeded''\n        when se.has_pending_refund then ''refund_pending''\n        when se.subscription_status in (''cancel_scheduled'', ''canceled'', ''cancelled'', ''expired'') then ''subscription_canceled_or_expired''\n        when se.cancel_at_period_end then ''cancel_at_period_end''\n        else null\n      end as sync_hold_reason\n    from source_events se\n  )\n  update public.subscription_settlement_items i\n  set\n    status = c.sync_status,\n    hold_reason = c.sync_hold_reason,\n    updated_at = now()\n  from calculated c\n  where i.billing_event_id = c.billing_event_id\n    and i.status <> ''paid''\n    and (\n      (c.sync_status = ''canceled'' and i.status <> ''canceled'')\n      or (c.sync_status = ''hold'' and i.status = ''pending'')\n      -- [105 게이팅] 기간이 완료되면 accruing → pending 업그레이드\n      or (c.sync_status = ''pending'' and i.status = ''accruing'')\n    );\n\n  return query\n  select\n    i.status::text as item_status,\n    count(*)::bigint as item_count,\n    coalesce(sum(i.gross_cents), 0)::bigint as gross_cents,\n    coalesce(sum(i.platform_fee_cents), 0)::bigint as platform_fee_cents,\n    coalesce(sum(i.mentor_amount_cents), 0)::bigint as mentor_amount_cents\n  from public.subscription_settlement_items i\n  where (p_from is null or i.billing_at >= p_from)\n    and (p_to is null or i.billing_at < p_to)\n  group by i.status\n  order by i.status;\nend;\n$function$", "comment on function public.refresh_subscription_settlement_items(timestamptz, timestamptz) is\n  ''105: 095(수수료 15%) 베이스 + period 완료 게이팅(accruing). 미완료=accruing(지급불가), period_end<=now 시 pending 업그레이드. 수수료 15%/85% 유지(30% 회귀 아님).''", "-- (4) 1회성 백필 — 미완료인데 pending 으로 적립돼 있던 진행중 사이클을 accruing 으로.\n--     paid/hold/canceled 는 status=''pending'' 필터로 자동 제외(기존 paid 보존).\nupdate public.subscription_settlement_items\nset status = ''accruing'', updated_at = now()\nwhere status = ''pending''\n  and (period_end is null or period_end > now())", "-- >>> NATIVE_BASELINE_PART 0117 | supabase/sql/106_payout_runs.sql | 106_payout_runs.sql <<<\n-- =============================================================================\n-- 106_payout_runs.sql   [DRAFT — DB 미적용]\n-- 목적(토대): 23일 통합 지급의 ''불변 지급 기록'' 골격.\n--   payout_runs(가변: 실행 상태/합계) + payout_run_items(불변: 지급 1건 스냅샷).\n--   이 파일은 테이블/제약/RLS/불변 트리거만. 지급 RPC·뷰는 별도(107, ②단계).\n--\n-- 선행: 004(cash_ledger), pgcrypto. 적용은 사용자가 Supabase에서 직접(이 단계 미적용).\n-- 돈 이동 없음(스키마만). main·타 로직 미터치.\n-- =============================================================================\n\ncreate extension if not exists pgcrypto", "-- ---------------------------------------------------------------------------\n-- payout_runs (가변) — 한 번의 23일 지급 실행 헤더\n--   멱등키 ''payout:YYYY-MM'' 로 같은 달 재실행 방지. status/합계는 갱신 허용.\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.payout_runs (\n  id uuid primary key default gen_random_uuid(),\n  run_date date not null,                 -- 지급일(매월 23일)\n  cutoff_end timestamptz not null,        -- 전월 말 23:59 (이 시점까지 완료분 대상)\n  status text not null default ''executing'' check (status in (''executing'', ''completed'')),\n  mentor_count integer not null default 0,\n  total_mentor_cents bigint not null default 0,\n  executed_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  idempotency_key text not null,\n  constraint payout_runs_idem_unique unique (idempotency_key)\n)", "create index if not exists idx_payout_runs_run_date\n  on public.payout_runs (run_date desc)", "-- updated_at 자동 갱신(086 에서 쓰는 공용 트리거 함수 재사용)\ndrop trigger if exists trg_payout_runs_set_updated on public.payout_runs", "create trigger trg_payout_runs_set_updated\n  before update on public.payout_runs\n  for each row execute function public.set_updated_at()", "-- ---------------------------------------------------------------------------\n-- payout_run_items (불변) — 지급 1건 = 멘토·채널·금액 스냅샷(immutable)\n--   source_type + source_id 폴리모픽(구독/CR/IQ). 금액은 FK 파생이 아닌 ''복사''(고정).\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.payout_run_items (\n  id uuid primary key default gen_random_uuid(),\n  payout_run_id uuid not null references public.payout_runs (id) on delete restrict,\n  mentor_id uuid not null references public.users (id) on delete restrict,\n  source_type text not null check (source_type in (''subscription'', ''custom_request'', ''individual_question'')),\n  source_id uuid not null,\n  -- 금액 스냅샷(지급 시점 고정 — 원본 행이 나중에 바뀌어도 불변)\n  gross_cents bigint not null,\n  platform_fee_cents bigint not null,\n  mentor_amount_cents bigint not null,\n  fee_rate numeric not null,\n  ledger_id uuid references public.cash_ledger (id) on delete set null,  -- 지급 크레딧 ledger 행\n  created_at timestamptz not null default now(),\n  constraint payout_run_items_unique unique (payout_run_id, source_type, source_id),\n  constraint payout_run_items_amount_chk check (mentor_amount_cents >= 0 and gross_cents >= 0)\n)", "create index if not exists idx_pri_run on public.payout_run_items (payout_run_id)", "create index if not exists idx_pri_mentor on public.payout_run_items (mentor_id, created_at desc)", "create index if not exists idx_pri_source on public.payout_run_items (source_type, source_id)", "-- 불변(append-only) 보장: UPDATE/DELETE 차단 트리거\ncreate or replace function public.payout_run_items_block_mutation()\nreturns trigger\nlanguage plpgsql\nas $f$\nbegin\n  raise exception ''payout_run_items is append-only (immutable); % not allowed'', tg_op\n    using errcode = ''P0001'';\nend;\n$f$", "drop trigger if exists trg_pri_no_update on public.payout_run_items", "create trigger trg_pri_no_update\n  before update on public.payout_run_items\n  for each row execute function public.payout_run_items_block_mutation()", "drop trigger if exists trg_pri_no_delete on public.payout_run_items", "create trigger trg_pri_no_delete\n  before delete on public.payout_run_items\n  for each row execute function public.payout_run_items_block_mutation()", "-- ---------------------------------------------------------------------------\n-- RLS — service_role 만 쓰기. 멘토는 본인 지급항목 읽기 가능. payout_runs 는 운영(service_role)만.\n-- ---------------------------------------------------------------------------\nalter table public.payout_runs enable row level security", "alter table public.payout_run_items enable row level security", "revoke all on table public.payout_runs from anon, authenticated", "grant all on table public.payout_runs to service_role", "revoke all on table public.payout_run_items from anon", "revoke insert, update, delete on table public.payout_run_items from authenticated", "grant select on table public.payout_run_items to authenticated", "grant all on table public.payout_run_items to service_role", "-- 멘토 본인 지급 항목만 읽기 (086 ssi_select_mentor_own 패턴)\ndrop policy if exists \"pri_select_mentor_own\" on public.payout_run_items", "create policy \"pri_select_mentor_own\"\n  on public.payout_run_items\n  for select\n  to authenticated\n  using (mentor_id = (select auth.uid()))", "-- payout_run_items 에 INSERT/UPDATE/DELETE 정책 없음 → 쓰기는 service_role(RPC)만.\n-- payout_runs 에 정책 없음 → authenticated 접근 불가(운영 service_role 전용).\n\ncomment on table public.payout_runs is\n  ''106: 23일 통합 지급 실행 헤더(가변). idempotency_key=payout:YYYY-MM 로 월 1회.''", "comment on table public.payout_run_items is\n  ''106: 지급 1건 불변 스냅샷(append-only). source_type+source_id 폴리모픽(구독/CR/IQ). 금액 복사 고정.''", "-- >>> NATIVE_BASELINE_PART 0118 | supabase/sql/108_pay_due_payouts_rpc.sql | 108_pay_due_payouts_rpc.sql <<<\n-- =============================================================================\n-- 108_pay_due_payouts_rpc.sql      ★★★ DRAFT — DB 미적용 / 실행 금지 ★★★\n-- =============================================================================\n-- 목적(②단계): 매월 23일 \"통합 후불 지급\" 배치 RPC.\n--   due_payouts(107) 후보 중 completion_ts <= cutoff(전월 말 23:59) AND 미지급만\n--   골라 채널별 지급 primitive 를 호출하고, payout_run_items(106)에 불변 스냅샷 적재.\n--\n-- ⚠️ 이 파일은 \"검토용 초안\"이다. 적용(psql 실행)·함수 교체·git push 금지.\n--    실제 송금이 일어나는 RPC 이므로 오너 검토 + 스테이징 검증 후에만 적용.\n--\n-- 선행(적용 시): 105(게이팅·accruing), 106(payout_runs/items), 107(due_payouts),\n--   109(IQ release/지급 분리), 110(CR 즉시지급 perform 제거), 114(원천징수 컬럼·뷰).\n--\n-- [W-01 개정] 프리랜서 사업소득 원천징수 3.3% — 지급 시점 공제:\n--   각 지급 건마다 withholding = floor(mentor_amount_cents * 0.033) 을 산출해\n--   ① cash_ledger 에 공제 라인(-withholding, reason=''payout_withholding_3_3pct'',\n--      idem ''wh:{source_type}:{source_id}'') 을 남기고 지갑에서 차감(멱등),\n--   ② payout_run_items(114 컬럼)에 withholding_cents·net_paid_cents 스냅샷 적재.\n--   채널 primitive(055/096/109)는 무수정 — 전액 적립 후 공제 라인으로 순액화하여\n--   원장 추적성(적립·공제 각 1행)을 보장한다. 실지급액 = mentor_amount - withholding.\n--\n-- 핵심 안전 불변식(설계 검증 STEP2 근거):\n--   (A) cutoff 게이트: completion_ts <= cutoff 로 \"기간 미완료(미래 period_end=accruing)\"\n--       구독 행을 배제. ← due_payouts 뷰 자체는 cutoff 미적용(107:5)이므로 이 게이트가\n--       유일한 미완료 차단막. 빠지면 미래 사이클이 조기 지급되는 치명 버그.\n--   (B) 미지급만: 채널 primitive 가 각자 멱등(cr_payout_/iq_payout:/sub_payout:) +\n--       payout_run_items UNIQUE(run,source_type,source_id) → 재실행 이중지급 불가.\n--   (C) 환불/취소/분쟁/hold 는 due_payouts(107) 단계에서 이미 제외됨.\n--   (D) 계좌 미등록(mentor_profiles.payout_account_number 공백) 멘토는 skip(미지급 보류).\n-- =============================================================================\n\ncreate or replace function public.pay_due_payouts_for_run(\n  p_run_date date,\n  p_idempotency_key text default null\n)\nreturns table (\n  run_id uuid,\n  paid_count integer,\n  skipped_no_account integer,\n  total_mentor_cents bigint\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_idem text := coalesce(p_idempotency_key, ''payout:'' || to_char(p_run_date, ''YYYY-MM''));\n  -- 전월 말 23:59:59 — 이 시점까지 ''완료된'' 건만 지급 대상(미래 accruing 배제).\n  v_cutoff timestamptz := date_trunc(''month'', p_run_date::timestamp) - interval ''1 second'';\n  v_run public.payout_runs%rowtype;\n  v_run_id uuid;\n  rec record;\n  v_ledger_id uuid;\n  v_has_account boolean;\n  v_paid integer := 0;\n  v_skipped integer := 0;\n  v_total bigint := 0;\n  -- [W-01] 원천징수 3.3%\n  v_withholding bigint;\n  v_net bigint;\n  v_wh_ledger_id uuid;\nbegin\n  -- 1) 멱등 run 헤더 확보(같은 달 재실행 방지). 이미 completed 면 그 결과만 반환.\n  select * into v_run from public.payout_runs where idempotency_key = v_idem;\n  if found then\n    v_run_id := v_run.id;\n    if v_run.status = ''completed'' then\n      return query\n        select v_run.id, v_run.mentor_count, 0, v_run.total_mentor_cents;\n      return;\n    end if;\n  else\n    insert into public.payout_runs (run_date, cutoff_end, status, idempotency_key)\n    values (p_run_date, v_cutoff, ''executing'', v_idem)\n    returning id into v_run_id;\n  end if;\n\n  -- 2) 지급 대상 루프 — due_payouts 에서 cutoff 통과분만.\n  --    (이미 payout_run_items 에 적재된 건은 UNIQUE 로 자동 스킵되지만, 명시적으로도 제외)\n  for rec in\n    select d.*\n    from public.due_payouts d\n    where d.completion_ts <= v_cutoff\n      and not exists (\n        select 1 from public.payout_run_items i\n        where i.source_type = d.source_type and i.source_id = d.source_id\n      )\n    order by d.mentor_id, d.source_type, d.completion_ts\n  loop\n    -- (D) 계좌 미등록 멘토는 skip(보류). 다음 회차에 계좌 등록되면 재포착.\n    select coalesce(nullif(trim(mp.payout_account_number), ''''), '''') <> ''''\n      into v_has_account\n    from public.mentor_profiles mp\n    where mp.user_id = rec.mentor_id;\n\n    if coalesce(v_has_account, false) = false then\n      v_skipped := v_skipped + 1;\n      continue;\n    end if;\n\n    v_ledger_id := null;\n\n    -- 3) 채널별 지급 primitive 호출(각자 멱등). 그 후 ledger_id 역조회해 스냅샷.\n    if rec.source_type = ''custom_request'' then\n      perform public.record_custom_order_escrow_payout(rec.source_id);\n      select id into v_ledger_id from public.cash_ledger\n      where idempotency_key = ''cr_payout_'' || rec.source_id::text\n        and reason = ''custom_order_escrow_payout'' limit 1;\n\n    elsif rec.source_type = ''individual_question'' then\n      -- 109 분리본: status=''released'' & release_ledger_id is null 인 건을 지급.\n      perform public.release_individual_question_payout(rec.source_id);\n      select id into v_ledger_id from public.cash_ledger\n      where idempotency_key = ''iq_payout:'' || rec.source_id::text\n        and reason = ''individual_question_payout'' limit 1;\n\n    elsif rec.source_type = ''subscription'' then\n      -- 구독은 별도 primitive 없음 → 여기서 멘토 float 크레딧 + ssi status=paid.\n      -- ★ 금액은 due_payouts(=ssi) 에 적재된 값 verbatim 사용.\n      --   (오너 결정 ②: 기존 30%-수수료 적립 행은 재계산 없이 적재값 그대로 지급.)\n      insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n      values (rec.mentor_id, rec.mentor_amount_cents, ''subscription_settlement_payout'',\n              ''subscription_settlement_items'', rec.source_id, ''sub_payout:'' || rec.source_id::text)\n      on conflict (idempotency_key) do nothing\n      returning id into v_ledger_id;\n\n      if v_ledger_id is not null then\n        insert into public.cash_wallets (user_id, balance_cents)\n        values (rec.mentor_id, 0) on conflict (user_id) do nothing;\n        update public.cash_wallets w\n        set balance_cents = w.balance_cents + rec.mentor_amount_cents\n        where w.user_id = rec.mentor_id;\n      else\n        -- 멱등 재실행 — 기존 지급 ledger 역조회\n        select id into v_ledger_id from public.cash_ledger\n        where idempotency_key = ''sub_payout:'' || rec.source_id::text limit 1;\n      end if;\n\n      update public.subscription_settlement_items\n      set status = ''paid'', paid_at = coalesce(paid_at, now()), updated_at = now()\n      where id = rec.source_id and status <> ''paid'';\n    else\n      -- 알 수 없는 채널 — 안전하게 skip(이론상 도달 불가, due_payouts CHECK 3채널).\n      continue;\n    end if;\n\n    -- 3.5) [W-01] 원천징수 3.3% 공제 — 채널 무관 공통. 적립(전액) 뒤 공제 라인으로 순액화.\n    v_withholding := floor(rec.mentor_amount_cents::numeric * 0.033)::bigint;\n    v_net := rec.mentor_amount_cents - v_withholding;\n\n    if v_withholding > 0 then\n      v_wh_ledger_id := null;\n      insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n      values (rec.mentor_id, -v_withholding, ''payout_withholding_3_3pct'',\n              rec.source_type, rec.source_id, ''wh:'' || rec.source_type || '':'' || rec.source_id::text)\n      on conflict (idempotency_key) do nothing\n      returning id into v_wh_ledger_id;\n\n      -- 신규 공제 라인이 실제로 생겼을 때만 지갑 차감(재실행 멱등).\n      if v_wh_ledger_id is not null then\n        update public.cash_wallets w\n        set balance_cents = w.balance_cents - v_withholding\n        where w.user_id = rec.mentor_id;\n      end if;\n    end if;\n\n    -- 4) 불변 스냅샷 적재(106+114). 금액은 지급 시점 고정.\n    insert into public.payout_run_items (\n      payout_run_id, mentor_id, source_type, source_id,\n      gross_cents, platform_fee_cents, mentor_amount_cents, fee_rate, ledger_id,\n      withholding_cents, net_paid_cents\n    ) values (\n      v_run_id, rec.mentor_id, rec.source_type, rec.source_id,\n      rec.gross_cents, rec.platform_fee_cents, rec.mentor_amount_cents, rec.fee_rate, v_ledger_id,\n      v_withholding, v_net\n    )\n    on conflict (payout_run_id, source_type, source_id) do nothing;\n\n    v_paid := v_paid + 1;\n    v_total := v_total + rec.mentor_amount_cents;\n  end loop;\n\n  -- 5) run 헤더 마감(합계·상태).\n  update public.payout_runs\n  set status = ''completed'',\n      mentor_count = (select count(distinct mentor_id) from public.payout_run_items where payout_run_id = v_run_id),\n      total_mentor_cents = (select coalesce(sum(mentor_amount_cents), 0) from public.payout_run_items where payout_run_id = v_run_id),\n      executed_at = now(),\n      updated_at = now()\n  where id = v_run_id;\n\n  return query select v_run_id, v_paid, v_skipped, v_total;\nend;\n$function$", "comment on function public.pay_due_payouts_for_run(date, text) is\n  ''108[DRAFT]: 23일 통합 후불 지급. due_payouts 중 completion_ts<=전월말 & 미지급만 채널별 지급+불변 스냅샷. 멱등(payout:YYYY-MM). service_role only. ★미적용 초안.''", "revoke all on function public.pay_due_payouts_for_run(date, text) from public, anon, authenticated", "grant execute on function public.pay_due_payouts_for_run(date, text) to service_role", "-- =============================================================================\n-- 적용 전 검토 포인트(오너):\n--   1) cutoff 정의: date_trunc(''month'', run_date) - 1s = 전월 말 23:59:59. (23일 실행 가정)\n--   2) 구독 미래 accruing 행은 (A) cutoff 게이트로만 배제 — due_payouts 뷰에 미래행이\n--      보이는 건 정상(STEP2 발견). 이 RPC 없이 뷰를 직접 지급하면 조기지급 위험.\n--   3) 계좌 미등록 skip 은 ''영구 누락''이 아니라 ''이번 회차 보류''(다음 달 재포착).\n--   4) 구독 30%-적립 레거시 행: 적재값 그대로 지급(오너 결정 ②). 재계산 안 함.\n--   5) 실제 적용 순서: 105→106→107→109→110→108. 108 단독 적용 금지.\n-- =============================================================================\n\n-- >>> NATIVE_BASELINE_PART 0119 | supabase/sql/109_individual_question_release_split.sql | 109_individual_question_release_split.sql <<<\n-- =============================================================================\n-- 109_individual_question_release_split.sql   ★★★ DRAFT — DB 미적용 / 실행 금지 ★★★\n-- =============================================================================\n-- 목적(②단계): 개별질문(IQ)의 \"완료 확정\"과 \"실제 지급\"을 분리한다.\n--   현행(096)은 학생 확정 시 release_individual_question_payout 가 status=released +\n--   released_at + release_ledger_id + 멘토 wallet 크레딧을 ''한 번에'' 처리 = 즉시지급.\n--   후불 모델에선 확정=완료사실만 기록(돈 X), 지급은 23일 배치(108)에서.\n--\n-- 변경(초안, 2개):\n--   (a) NEW: mark_individual_question_released(uuid) — status=''released'' + released_at 만.\n--       release_ledger_id 는 NULL 유지 → due_payouts(107)에 \"미지급 완료건\"으로 노출.\n--       (앱: individualQuestionActions.ts:588 가 이 함수를 호출하도록 교체 — 별도 패치, 본 파일 아님)\n--   (b) MODIFY: release_individual_question_payout(uuid) — 가드를 ''released & 미지급'' 허용으로.\n--       096 본문 동일(멘토 85% floor(price*0.85), 멱등 iq_payout:{id}) — 가드 2줄만 완화.\n--\n-- ⚠️ 미적용 초안. 적용 시 108·110 과 함께 검토. release 함수 ''동작 변경''이므로 오너 승인 필수.\n-- 근거: 096(현행 payout), 070(스키마/상태), individualQuestionActions.ts:577-594(확정 액션).\n-- =============================================================================\n\n-- (a) 완료 확정만(돈 X) — answered → released, release_ledger_id 는 NULL 유지.\ncreate or replace function public.mark_individual_question_released(\n  p_question_id uuid\n)\nreturns public.individual_question_escrow_result\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_q public.individual_questions%rowtype;\n  v_mentor_id uuid;\nbegin\n  if p_question_id is null then\n    return (false, ''invalid_question'', ''question_id is required'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  select * into v_q from public.individual_questions where id = p_question_id for update;\n  if not found then\n    return (false, ''not_found'', ''individual question not found'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  -- 이미 지급됨(레거시 즉시지급분 포함) — 멱등 통과.\n  if v_q.release_ledger_id is not null then\n    return (true, ''already_released'', ''already released/paid'', v_q.id, v_q.status, v_q.release_ledger_id, null)::public.individual_question_escrow_result;\n  end if;\n  -- 이미 확정(미지급) — 멱등 통과.\n  if v_q.status = ''released'' then\n    return (true, ''already_released'', ''already marked released (unpaid)'', v_q.id, v_q.status, null, null)::public.individual_question_escrow_result;\n  end if;\n  if v_q.refund_ledger_id is not null or v_q.status = ''refunded'' then\n    return (false, ''already_refunded'', ''already refunded'', v_q.id, v_q.status, v_q.refund_ledger_id, null)::public.individual_question_escrow_result;\n  end if;\n  if v_q.status <> ''answered'' then\n    return (false, ''not_answered'', ''question must be answered before release'', v_q.id, v_q.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  v_mentor_id := coalesce(v_q.claimed_mentor_id, v_q.designated_mentor_id);\n  if v_mentor_id is null then\n    return (false, ''mentor_missing'', ''mentor is missing'', v_q.id, v_q.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  -- 완료 사실만 기록 — 돈 이동·release_ledger_id 설정 없음(지급은 108 배치).\n  update public.individual_questions\n  set status = ''released'', released_at = coalesce(released_at, now())\n  where id = v_q.id\n  returning * into v_q;\n\n  return (true, ''released'', ''marked released (payout deferred to batch)'', v_q.id, v_q.status, null, null)::public.individual_question_escrow_result;\nend;\n$function$", "comment on function public.mark_individual_question_released(uuid) is\n  ''109[DRAFT]: IQ 완료 확정만(status=released, 돈 X). 지급은 108 배치. service_role only.''", "revoke all on function public.mark_individual_question_released(uuid) from public, anon, authenticated", "grant execute on function public.mark_individual_question_released(uuid) to service_role", "-- (b) 지급 primitive — 가드만 ''released & 미지급'' 허용으로 완화(096 본문과 금액 동일).\n--     변경점은 딱 2곳:\n--       · 096:48  release_ledger_id 있으면 already → 유지(이미 지급)\n--                 BUT status=''released'' 단독은 더 이상 already 로 막지 않음(미지급일 수 있음).\n--       · 096:56  status <> ''answered'' 거부 → status in (''answered'',''released'') 허용.\ncreate or replace function public.release_individual_question_payout(\n  p_question_id uuid\n)\nreturns public.individual_question_escrow_result\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_question public.individual_questions%rowtype;\n  v_mentor_id uuid;\n  v_ledger_id uuid;\n  v_wallet_balance bigint;\n  v_new_ledger boolean := false;\n  v_mentor_cents bigint;\nbegin\n  if p_question_id is null then\n    return (false, ''invalid_question'', ''question_id is required'', null, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  select * into v_question from public.individual_questions where id = p_question_id for update;\n  if not found then\n    return (false, ''not_found'', ''individual question not found'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  -- [109 변경] 이미 ''지급''된 경우만 멱등 통과(release_ledger_id 기준). status=''released''\n  --   단독은 미지급 상태일 수 있으므로 더 이상 차단하지 않는다.\n  if v_question.release_ledger_id is not null then\n    return (true, ''already_released'', ''individual question already paid'', v_question.id, v_question.status, v_question.release_ledger_id, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_question.refund_ledger_id is not null or v_question.status = ''refunded'' then\n    return (false, ''already_refunded'', ''individual question already refunded'', v_question.id, v_question.status, v_question.refund_ledger_id, null)::public.individual_question_escrow_result;\n  end if;\n\n  -- [109 변경] answered(레거시 즉시지급) 또는 released(후불 확정) 둘 다 지급 가능.\n  if v_question.status not in (''answered'', ''released'') then\n    return (false, ''not_answered'', ''question must be answered/released before payout'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if v_question.hold_ledger_id is null then\n    return (false, ''hold_missing'', ''escrow hold ledger is missing'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  v_mentor_id := coalesce(v_question.claimed_mentor_id, v_question.designated_mentor_id);\n  if v_mentor_id is null then\n    return (false, ''mentor_missing'', ''mentor is missing'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key = ''iq_refund:'' || v_question.id::text\n      and l.reason = ''individual_question_refund''\n  ) then\n    return (false, ''already_refunded'', ''refund ledger already exists'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  v_mentor_cents := floor(v_question.price_cents::numeric * 0.85)::bigint;  -- 096: 멘토 85%\n  if v_mentor_cents <= 0 then\n    return (false, ''invalid_payout'', ''mentor payout amount must be positive'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n  values (v_mentor_id, v_mentor_cents, ''individual_question_payout'', ''individual_questions'',\n          v_question.id, ''iq_payout:'' || v_question.id::text)\n  on conflict (idempotency_key) do nothing\n  returning id into v_ledger_id;\n\n  if v_ledger_id is not null then\n    v_new_ledger := true;\n  else\n    select id into v_ledger_id from public.cash_ledger\n    where idempotency_key = ''iq_payout:'' || v_question.id::text\n      and reason = ''individual_question_payout'';\n  end if;\n\n  if v_ledger_id is null then\n    raise exception ''INDIVIDUAL_QUESTION_PAYOUT_LEDGER_MISSING'';\n  end if;\n\n  if v_new_ledger then\n    insert into public.cash_wallets (user_id, balance_cents) values (v_mentor_id, 0)\n    on conflict (user_id) do nothing;\n    update public.cash_wallets set balance_cents = balance_cents + v_mentor_cents\n    where user_id = v_mentor_id returning balance_cents into v_wallet_balance;\n    if not found then\n      raise exception ''INDIVIDUAL_QUESTION_MENTOR_WALLET_CREDIT_FAILED'';\n    end if;\n  end if;\n\n  update public.individual_questions\n  set status = ''released'', released_at = coalesce(released_at, now()), release_ledger_id = v_ledger_id\n  where id = v_question.id\n  returning * into v_question;\n\n  return (true, ''released'', ''individual question payout released'', v_question.id, v_question.status, v_ledger_id, v_wallet_balance)::public.individual_question_escrow_result;\nend;\n$function$", "comment on function public.release_individual_question_payout(uuid) is\n  ''109[DRAFT]: 096(85%) 베이스 + 가드 완화(answered/released & 미지급 지급 가능). 108 배치가 호출. 멱등. service_role only.''", "revoke all on function public.release_individual_question_payout(uuid) from public, anon, authenticated", "grant execute on function public.release_individual_question_payout(uuid) to service_role", "-- =============================================================================\n-- ※ 앱 코드 패치(별도, 본 SQL 파일에서 미적용):\n--   lib/individualQuestion/individualQuestionActions.ts:588\n--     - 현행: admin.rpc(\"release_individual_question_payout\", { p_question_id })  ← 즉시지급\n--     - 변경: admin.rpc(\"mark_individual_question_released\", { p_question_id })   ← 확정만, 지급은 23일\n--   (해당 TS 변경은 이 작업 범위에서 ''작성 설명''만. 실제 코드 수정·적용은 오너 승인 후.)\n-- =============================================================================\n\n-- >>> NATIVE_BASELINE_PART 0120 | supabase/sql/110_custom_request_remove_immediate_payout.sql | 110_custom_request_remove_immediate_payout.sql <<<\n-- =============================================================================\n-- 110_custom_request_remove_immediate_payout.sql  ★★★ DRAFT — DB 미적용 / 실행 금지 ★★★\n-- =============================================================================\n-- 목적(②단계): 맞춤의뢰(CR) 즉시지급 제거 → 후불(23일 배치)로 일원화.\n--   현행(090) accept_custom_order_deliverable_atomic 는 납품 수락 시\n--     · 주문 completed + settlement(pending) 생성까지 하고\n--     · 곧바로 perform record_custom_order_escrow_payout(...) 로 ''즉시지급''한다(090:178, 090:208).\n--   후불 모델에선 수락=완료사실만(settlement ''pending'' 유지), 지급은 108 배치에서.\n--   → due_payouts(107) CR 브랜치가 settlement.status in (pending,on_hold,payable) &\n--     order.accepted_at not null 인 건을 후보로 잡으므로, 수락만 해두면 배치가 포착한다.\n--\n-- 변경(초안): 090 본문 verbatim + 즉시지급 2줄(perform/ v_payout_done) 제거.\n--   · v_fee_rate=0.05 유지(090). 수수료·정산 생성·멱등·예외수리 로직 전부 동일.\n--   · 제거 대상: 090:178-179(정상 경로), 090:208-209(23505 예외 수리 경로)의\n--     perform record_custom_order_escrow_payout + v_payout_done := true.\n--   · record_custom_order_escrow_payout 함수 자체는 미터치(108 배치가 그대로 호출).\n--\n-- ⚠️ 미적용 초안. ''동작 변경''(즉시지급 제거)이므로 108·109 와 함께 오너 승인 후 적용.\n-- 근거: 090(현행 accept), 055(record_custom_order_escrow_payout), 107(CR due 브랜치 54-62).\n-- =============================================================================\n\ncreate or replace function public.accept_custom_order_deliverable_atomic(\n  p_order_id uuid,\n  p_student_id uuid,\n  p_require_payment boolean default true\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  o public.custom_request_orders%rowtype;\n  app public.custom_request_applications%rowtype;\n  v_norm text;\n  v_pay text;\n  v_dispute_cnt integer;\n  v_deliverable_cnt integer;\n  v_existing_settlement uuid;\n  v_gross integer;\n  v_platform_fee integer;\n  v_mentor_amount integer;\n  v_settlement_id uuid;\n  v_settlement_created boolean := false;\n  v_now timestamptz := now();\n  v_fee_rate numeric := 0.05;  -- 252: 맞춤의뢰 수수료 5%(090 유지)\nbegin\n  if p_order_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''orderId가 필요합니다.'');\n  end if;\n  if p_student_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''학생 ID가 필요합니다.'');\n  end if;\n\n  select * into o from public.custom_request_orders where id = p_order_id for update;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''message'', ''주문을 찾을 수 없어요.'');\n  end if;\n  if o.student_id is distinct from p_student_id then\n    return jsonb_build_object(''ok'', false, ''message'', ''의뢰자(학생) 본인만 납품을 수락할 수 있습니다.'');\n  end if;\n\n  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''''), '''')));\n  if p_require_payment and v_pay not in (''paid'', ''escrowed'') then\n    return jsonb_build_object(''ok'', false, ''message'', ''결제(예치)가 완료되지 않은 주문은 수락할 수 없습니다.'');\n  end if;\n\n  if o.completed_at is not null or o.closed_at is not null or o.finished_at is not null\n     or lower(trim(coalesce(o.status, ''''))) in (''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved'')\n     or lower(trim(coalesce(o.state, ''''))) in (''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved'')\n     or lower(trim(coalesce(o.order_status, ''''))) in (''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved'')\n  then\n    return jsonb_build_object(''ok'', false, ''message'', ''이미 완료된 주문입니다.'');\n  end if;\n\n  v_norm := public._order_primary_status_norm(o);\n  if v_norm = '''' then\n    return jsonb_build_object(''ok'', false, ''message'', ''주문 상태를 확인할 수 없어 수락할 수 없습니다.'');\n  end if;\n  if v_norm not in (''delivered'',''delivered_pending_review'',''waiting_review'',''pending_review'',''redelivered'',''delivery_submitted'',''in_review'') then\n    return jsonb_build_object(''ok'', false, ''message'', format(''현재 상태(%s)에서는 납품 수락을 할 수 없습니다.'', v_norm));\n  end if;\n\n  select count(*)::integer into v_dispute_cnt\n  from public.disputes d\n  where d.custom_request_order_id = p_order_id and d.status in (''open'', ''under_review'', ''escalated'');\n  if v_dispute_cnt > 0 then\n    return jsonb_build_object(''ok'', false, ''message'', ''진행 중인 분쟁이 있어 납품 수락을 할 수 없습니다.'');\n  end if;\n\n  select count(*)::integer into v_deliverable_cnt\n  from public.custom_order_deliverables d where d.custom_request_order_id = p_order_id;\n  if v_deliverable_cnt < 1 then\n    return jsonb_build_object(''ok'', false, ''message'', ''등록된 납품이 없어 수락할 수 없습니다.'');\n  end if;\n\n  select id into v_existing_settlement\n  from public.custom_order_settlement_items s where s.custom_request_order_id = p_order_id;\n\n  select a.* into app from public.custom_request_applications a\n  where a.id = coalesce(o.application_id, o.custom_request_application_id, o.selected_application_id) limit 1;\n\n  if v_existing_settlement is null then\n    v_gross := public._pick_custom_order_gross_won(o, app);\n    if v_gross is not null and v_gross > 0 then\n      v_platform_fee := floor(v_gross * v_fee_rate)::integer;\n      v_mentor_amount := v_gross - v_platform_fee;\n      insert into public.custom_order_settlement_items (\n        custom_request_order_id, mentor_id, student_id, gross_amount,\n        platform_fee_amount, mentor_amount, fee_rate, status\n      ) values (\n        p_order_id, o.mentor_id, o.student_id, v_gross,\n        v_platform_fee, v_mentor_amount, v_fee_rate, ''pending''\n      ) returning id into v_settlement_id;\n      v_settlement_created := true;\n    end if;\n  else\n    v_settlement_id := v_existing_settlement;\n  end if;\n\n  update public.custom_request_orders\n  set status = ''completed'', state = ''completed'', order_status = ''completed'',\n      accepted_at = coalesce(accepted_at, v_now), completed_at = coalesce(completed_at, v_now), updated_at = v_now\n  where id = p_order_id;\n\n  -- [110 제거] 즉시지급 없음. settlement 는 ''pending'' 유지 → 108 배치(23일)가 지급.\n  --   (구 090:178-179 perform record_custom_order_escrow_payout + v_payout_done 제거)\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''settlement_created'', v_settlement_created,\n    ''settlement_id'', v_settlement_id,\n    ''gross'', v_gross,\n    ''fee_rate'', v_fee_rate,\n    ''payout_done'', false,           -- 후불: 수락 시점 미지급\n    ''payout_deferred'', true\n  );\nexception\n  when others then\n    if sqlstate = ''23505'' then\n      select id into v_existing_settlement\n      from public.custom_order_settlement_items s where s.custom_request_order_id = p_order_id;\n\n      update public.custom_request_orders\n      set status = ''completed'', state = ''completed'', order_status = ''completed'',\n          accepted_at = coalesce(accepted_at, v_now), completed_at = coalesce(completed_at, v_now), updated_at = v_now\n      where id = p_order_id;\n\n      -- [110 제거] 예외 수리 경로도 즉시지급 안 함(구 090:208-209 제거).\n      return jsonb_build_object(\n        ''ok'', true,\n        ''settlement_created'', false,\n        ''settlement_id'', v_existing_settlement,\n        ''payout_done'', false,\n        ''payout_deferred'', true,\n        ''reason'', ''already_exists''\n      );\n    end if;\n    raise;\nend;\n$function$", "comment on function public.accept_custom_order_deliverable_atomic(uuid, uuid, boolean) is\n  ''110[DRAFT]: 납품 수락 = 주문 completed + settlement(pending)만. 즉시지급 제거 → 지급은 108 배치(23일). fee 5% 유지. service_role only.''", "revoke all on function public.accept_custom_order_deliverable_atomic(uuid, uuid, boolean) from public", "grant execute on function public.accept_custom_order_deliverable_atomic(uuid, uuid, boolean) to service_role", "-- >>> NATIVE_BASELINE_PART 0121 | supabase/sql/111_due_payouts_completion_guard.sql | 111_due_payouts_completion_guard.sql <<<\n-- =============================================================================\n-- 111_due_payouts_completion_guard.sql\n-- 목적: due_payouts(107)에 \"완료 시각이 현재 이하\" 방어를 한 겹 추가.\n--   = 미완료(미래 period_end=accruing 등) 행이 뷰에 아예 안 보이게.\n--   배경: 107은 cutoff를 의도적으로 RPC(108)에 위임 → 뷰 단독으로는 미래 period 행이\n--   노출됐음(STEP2 발견). Option A: 뷰에도 completion_ts<=now() 방어를 둬 이중 안전망.\n--   ※ 23일 배치의 정밀 cutoff(전월 말 23:59)는 여전히 108 RPC가 담당. 본 방어는\n--     \"현재 이미 완료된 것만 후보\"라는 약한 상한(now())일 뿐 — 둘은 상호보완.\n--   ※ 돈 이동 없음(뷰만). 컬럼 구조 107과 동일 → CREATE OR REPLACE.\n--\n-- 변경점(107 대비, 각 채널 WHERE 에 완료시각<=now() 1줄씩):\n--   구독: ssi.period_end <= now()\n--   CR  : o.accepted_at <= now()\n--   IQ  : q.released_at <= now()\n-- =============================================================================\n\ncreate or replace view public.due_payouts as\n\n-- ── 구독 ──────────────────────────────────────────────────────────────────\nselect\n  ''subscription''::text                  as source_type,\n  ssi.id                                as source_id,\n  ssi.mentor_id                         as mentor_id,\n  ssi.mentor_amount_cents::bigint       as mentor_amount_cents,\n  ssi.gross_cents::bigint               as gross_cents,\n  ssi.platform_fee_cents::bigint        as platform_fee_cents,\n  ssi.fee_rate                          as fee_rate,\n  ssi.period_end                        as completion_ts\nfrom public.subscription_settlement_items ssi\nwhere ssi.period_end is not null\n  and ssi.period_end <= now()                          -- [111] 미완료(미래 period) 배제\n  and ssi.status not in (''paid'', ''hold'', ''canceled'')\n\nunion all\n\n-- ── 맞춤의뢰(CR) ─────────────────────────────────────────────────────────\nselect\n  ''custom_request''::text                          as source_type,\n  cs.id                                           as source_id,\n  cs.mentor_id                                    as mentor_id,\n  (cs.mentor_amount::bigint * 100)                as mentor_amount_cents,\n  (cs.gross_amount::bigint * 100)                 as gross_cents,\n  (cs.platform_fee_amount::bigint * 100)          as platform_fee_cents,\n  cs.fee_rate                                     as fee_rate,\n  o.accepted_at                                   as completion_ts\nfrom public.custom_order_settlement_items cs\njoin public.custom_request_orders o on o.id = cs.custom_request_order_id\nwhere cs.status in (''pending'', ''on_hold'', ''payable'')\n  and o.accepted_at is not null\n  and o.accepted_at <= now()                           -- [111] 미래 수락시각 방어\n  and coalesce(lower(trim(o.payment_status)), '''') <> ''refunded''\n  and coalesce(lower(trim(o.status)), '''') not in (''cancelled'', ''canceled'', ''refunded'')\n  and not exists (\n    select 1 from public.disputes d\n    where d.custom_request_order_id = o.id\n      and d.status in (''open'', ''under_review'', ''escalated'')\n  )\n\nunion all\n\n-- ── 개별질문(IQ) ─────────────────────────────────────────────────────────\nselect\n  ''individual_question''::text                              as source_type,\n  q.id                                                     as source_id,\n  coalesce(q.claimed_mentor_id, q.designated_mentor_id)    as mentor_id,\n  floor(q.price_cents::numeric * 0.85)::bigint             as mentor_amount_cents,\n  q.price_cents::bigint                                    as gross_cents,\n  (q.price_cents - floor(q.price_cents::numeric * 0.85)::bigint) as platform_fee_cents,\n  0.15::numeric                                            as fee_rate,\n  q.released_at                                            as completion_ts\nfrom public.individual_questions q\nwhere q.released_at is not null\n  and q.released_at <= now()                             -- [111] 미래 확정시각 방어\n  and q.release_ledger_id is null\n  and q.refund_ledger_id is null\n  and q.status not in (''refunded'', ''expired'', ''canceled'')\n  and coalesce(q.claimed_mentor_id, q.designated_mentor_id) is not null", "comment on view public.due_payouts is\n  ''107+111: 3채널 지급가능 후보(완료 사실 있고 미지급·환불/취소/분쟁 제외) + completion_ts<=now() 방어. 23일 cutoff는 108 RPC.''", "revoke all on public.due_payouts from anon, authenticated", "grant select on public.due_payouts to service_role", "-- >>> NATIVE_BASELINE_PART 0122 | supabase/sql/112_mentor_directory_rpc_photo_highschool.sql | 112_mentor_directory_rpc_photo_highschool.sql <<<\n-- 112_mentor_directory_rpc_photo_highschool.sql\n-- 공개 멘토 프로필 RPC(mentor_profiles_for_directory_v2)에 프로필 사진·고교 표시 필드 추가.\n-- 선행: 078_p0_public_mentor_read_rpc_v2.sql, 097_mentor_profile_avatar.sql\n--   - mentor_profiles.high_school_name  (001, not null text)\n--   - mentor_profiles.profile_image_url (097, text)\n-- ⚠️ 본 SQL은 이미 운영 DB에 적용됨. 저장소 기록용이며 재실행해도 안전(idempotent).\n--   RETURNS TABLE 시그니처가 바뀌므로 CREATE OR REPLACE만으로는 불가 → DROP 후 재생성.\n-- Run manually in Supabase SQL Editor.\n\nbegin", "-- 반환 컬럼(시그니처) 변경을 위해 기존 함수 제거 후 재생성.\ndrop function if exists public.mentor_profiles_for_directory_v2(uuid[])", "-- Public mentor profiles: safe profile fields plus approved school verification display fields,\n-- 그리고 공개 표시용 프로필 사진(profile_image_url)·고교(high_school_name).\ncreate or replace function public.mentor_profiles_for_directory_v2(p_ids uuid[])\nreturns table (\n  user_id uuid,\n  university_name text,\n  department_name text,\n  teaching_subjects text[],\n  intro_line text,\n  verification_status text,\n  created_at timestamptz,\n  verified_university_name text,\n  verified_department_name text,\n  verified_major_category text,\n  school_tier text,\n  school_verified boolean,\n  high_school_name text,\n  profile_image_url text\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select\n    mp.user_id,\n    mp.university_name,\n    mp.department_name,\n    mp.teaching_subjects,\n    mp.intro_line,\n    mp.verification_status,\n    mp.created_at,\n    sv.verified_university_name,\n    sv.verified_department_name,\n    sv.verified_major_category,\n    sv.school_tier,\n    (sv.mentor_id is not null) as school_verified,\n    mp.high_school_name,\n    mp.profile_image_url\n  from public.mentor_profiles mp\n  left join lateral (\n    select\n      msv.mentor_id,\n      msv.verified_university_name,\n      msv.verified_department_name,\n      msv.verified_major_category,\n      msv.school_tier\n    from public.mentor_school_verifications msv\n    where msv.mentor_id = mp.user_id\n      and msv.status = ''approved''\n    order by coalesce(msv.reviewed_at, msv.updated_at, msv.created_at) desc, msv.created_at desc\n    limit 1\n  ) sv on true\n  where p_ids is not null\n    and array_length(p_ids, 1) is not null\n    and mp.user_id = any (p_ids);\n$$", "revoke all on function public.mentor_profiles_for_directory_v2(uuid[]) from public", "grant execute on function public.mentor_profiles_for_directory_v2(uuid[]) to anon, authenticated", "comment on function public.mentor_profiles_for_directory_v2(uuid[]) is ''P0 public mentor profile whitelist plus approved school verification display fields, public profile photo, and high school name only.''", "commit", "-- >>> NATIVE_BASELINE_PART 0123 | supabase/sql/113_individual_question_subject_gate.sql | 113_individual_question_subject_gate.sql <<<\n-- 개별질문 공개 목록/맡기를 멘토 담당 과목(mentor_profiles.teaching_subjects)으로 제한.\n-- 과목 없는(null) 질문은 일반 질문으로 모두에게 노출/허용.\n\nCREATE OR REPLACE FUNCTION public.list_open_individual_questions_for_mentor(p_limit integer DEFAULT 50)\n RETURNS TABLE(id uuid, subject text, topic text, title text, price_cents integer, expires_at timestamp with time zone, created_at timestamp with time zone)\n LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO ''public''\nAS $function$\ndeclare\n  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);\n  v_subjects text[];\nbegin\n  if not public.individual_question_user_is_approved_mentor((select auth.uid())) then\n    return;\n  end if;\n  select mp.teaching_subjects into v_subjects\n  from public.mentor_profiles mp\n  where mp.user_id = (select auth.uid());\n  return query\n    select q.id, q.subject, q.topic, q.title, q.price_cents, q.expires_at, q.created_at\n    from public.individual_questions q\n    where q.question_type = ''open''\n      and q.status = ''open''\n      and q.claimed_mentor_id is null\n      and (q.expires_at is null or q.expires_at > now())\n      and (q.subject is null or q.subject = any(coalesce(v_subjects, array[]::text[])))\n    order by q.created_at desc\n    limit v_limit;\nend;\n$function$", "CREATE OR REPLACE FUNCTION public.claim_individual_question_v2(p_question_id uuid, p_mentor_id uuid)\n RETURNS individual_question_escrow_result\n LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''public''\nAS $function$\ndeclare\n  v_question public.individual_questions%rowtype;\n  v_required_school_tier text;\n  v_required_major_category text;\n  v_verified_school_tier text;\n  v_verified_major_category text;\n  v_question_subject text;\n  v_mentor_subjects text[];\nbegin\n  if p_question_id is null or p_mentor_id is null then\n    return (false, ''invalid_input'', ''question_id and mentor_id are required'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n  if not public.individual_question_user_is_approved_mentor(p_mentor_id) then\n    return (false, ''mentor_not_approved'', ''mentor is not approved for individual questions'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n  select q.required_school_tier, q.required_major_category, q.subject\n    into v_required_school_tier, v_required_major_category, v_question_subject\n  from public.individual_questions q\n  where q.id = p_question_id and q.question_type = ''open'' and q.status = ''open''\n    and q.claimed_mentor_id is null and (q.expires_at is null or q.expires_at > now())\n    and q.student_id <> p_mentor_id;\n  if not found then\n    return (false, ''not_available'', ''question is already claimed, expired, or unavailable'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n  -- 과목 게이트: 담당 과목이 아닌 질문은 거부(과목 없는 질문은 허용)\n  if v_question_subject is not null then\n    select mp.teaching_subjects into v_mentor_subjects from public.mentor_profiles mp where mp.user_id = p_mentor_id;\n    if not (v_question_subject = any(coalesce(v_mentor_subjects, array[]::text[]))) then\n      return (false, ''mentor_subject_not_met'', ''mentor does not teach this subject'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n    end if;\n  end if;\n  if v_required_school_tier is not null or v_required_major_category is not null then\n    select msv.school_tier, msv.verified_major_category into v_verified_school_tier, v_verified_major_category\n    from public.mentor_school_verifications msv\n    where msv.mentor_id = p_mentor_id and msv.status = ''approved''\n    order by coalesce(msv.reviewed_at, msv.updated_at, msv.created_at) desc, msv.created_at desc\n    limit 1;\n    if not found then\n      return (false, ''mentor_school_verification_required'', ''mentor school verification is required for this question'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n    end if;\n    if v_required_school_tier is not null and coalesce(v_verified_school_tier, '''') <> v_required_school_tier then\n      return (false, ''mentor_qualification_not_met'', ''mentor school tier does not match this question requirement'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n    end if;\n    if v_required_major_category is not null and coalesce(v_verified_major_category, '''') <> v_required_major_category then\n      return (false, ''mentor_qualification_not_met'', ''mentor major category does not match this question requirement'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n    end if;\n  end if;\n  update public.individual_questions\n  set claimed_mentor_id = p_mentor_id, claimed_at = now(), status = ''claimed''\n  where id = p_question_id and question_type = ''open'' and status = ''open''\n    and claimed_mentor_id is null and (expires_at is null or expires_at > now())\n    and student_id <> p_mentor_id\n  returning * into v_question;\n  if not found then\n    return (false, ''not_available'', ''question is already claimed, expired, or unavailable'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n  return (true, ''claimed'', ''individual question claimed'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\nend;\n$function$", "-- >>> NATIVE_BASELINE_PART 0124 | supabase/sql/114_payout_withholding_3_3pct.sql | 114_payout_withholding_3_3pct.sql <<<\n-- =============================================================================\n-- 114_payout_withholding_3_3pct.sql\n-- 목적(W-01): 프리랜서 사업소득 원천징수 3.3% — \"23일 후불 지급 시점 공제\" 설계 확정분.\n--   ① payout_run_items(106)에 공제액·실지급액 컬럼 추가(불변 스냅샷·원장성 추적).\n--   ② due_payouts 뷰(111 정의 기반)에 공제 예정액을 노출.\n--   실제 공제 실행은 108 RPC(pay_due_payouts_for_run — W-01 개정판)가 담당.\n--\n-- ⚠️ 적용 메모:\n--   - payout_run_items 는 라이브 기적용 테이블(106) → 본 ALTER 는 비파괴(ADD COLUMN)지만\n--     라이브 반영은 별도 운영 결정. 108/109/110(DRAFT) 가동 전에는 공제가 일어나지 않음.\n--   - payout_run_items_block_mutation 트리거(106)는 행 UPDATE/DELETE 차단용 —\n--     컬럼 추가(DDL)·신규 INSERT 와 충돌 없음(트리거 변경 불필요).\n--   - 컬럼 명칭: 기존 gross_cents/platform_fee_cents/mentor_amount_cents 와의\n--     단위·명명 일관성을 위해 *_cents 채택(1캐시=1원, cents=원×100 규약).\n--\n-- 선행(적용 시): 105, 106, 107, 108(W-01 개정판), 109, 110, 111, ~113.\n-- =============================================================================\n\n-- ① 불변 스냅샷에 원천징수 추적 컬럼 추가\nalter table public.payout_run_items\n  add column if not exists withholding_cents bigint,\n  add column if not exists net_paid_cents bigint", "comment on column public.payout_run_items.withholding_cents is\n  ''W-01: 프리랜서 사업소득 원천징수 3.3% 공제액 = floor(mentor_amount_cents * 0.033). 지급 시점 고정.''", "comment on column public.payout_run_items.net_paid_cents is\n  ''W-01: 실지급액 = mentor_amount_cents - withholding_cents. 지급 시점 고정.''", "-- ② due_payouts 뷰 — 공제 예정액 노출 (111 정의 verbatim + 말미 2컬럼 추가)\n--    CREATE OR REPLACE VIEW 는 기존 컬럼 뒤에만 추가 가능 → 끝에 덧붙인다.\ncreate or replace view public.due_payouts as\n\n-- ── 구독 ──────────────────────────────────────────────────────────────────\nselect\n  ''subscription''::text                  as source_type,\n  ssi.id                                as source_id,\n  ssi.mentor_id                         as mentor_id,\n  ssi.mentor_amount_cents::bigint       as mentor_amount_cents,\n  ssi.gross_cents::bigint               as gross_cents,\n  ssi.platform_fee_cents::bigint        as platform_fee_cents,\n  ssi.fee_rate                          as fee_rate,\n  ssi.period_end                        as completion_ts,\n  floor(ssi.mentor_amount_cents::numeric * 0.033)::bigint as withholding_cents_est,   -- [114]\n  (ssi.mentor_amount_cents::bigint\n    - floor(ssi.mentor_amount_cents::numeric * 0.033)::bigint) as net_cents_est        -- [114]\nfrom public.subscription_settlement_items ssi\nwhere ssi.period_end is not null\n  and ssi.period_end <= now()                          -- [111] 미완료(미래 period) 배제\n  and ssi.status not in (''paid'', ''hold'', ''canceled'')\n\nunion all\n\n-- ── 맞춤의뢰(CR) ─────────────────────────────────────────────────────────\nselect\n  ''custom_request''::text                          as source_type,\n  cs.id                                           as source_id,\n  cs.mentor_id                                    as mentor_id,\n  (cs.mentor_amount::bigint * 100)                as mentor_amount_cents,\n  (cs.gross_amount::bigint * 100)                 as gross_cents,\n  (cs.platform_fee_amount::bigint * 100)          as platform_fee_cents,\n  cs.fee_rate                                     as fee_rate,\n  o.accepted_at                                   as completion_ts,\n  floor((cs.mentor_amount::numeric * 100) * 0.033)::bigint as withholding_cents_est,   -- [114]\n  ((cs.mentor_amount::bigint * 100)\n    - floor((cs.mentor_amount::numeric * 100) * 0.033)::bigint) as net_cents_est        -- [114]\nfrom public.custom_order_settlement_items cs\njoin public.custom_request_orders o on o.id = cs.custom_request_order_id\nwhere cs.status in (''pending'', ''on_hold'', ''payable'')\n  and o.accepted_at is not null\n  and o.accepted_at <= now()                           -- [111] 미래 수락시각 방어\n  and coalesce(lower(trim(o.payment_status)), '''') <> ''refunded''\n  and coalesce(lower(trim(o.status)), '''') not in (''cancelled'', ''canceled'', ''refunded'')\n  and not exists (\n    select 1 from public.disputes d\n    where d.custom_request_order_id = o.id\n      and d.status in (''open'', ''under_review'', ''escalated'')\n  )\n\nunion all\n\n-- ── 개별질문(IQ) ─────────────────────────────────────────────────────────\nselect\n  ''individual_question''::text                              as source_type,\n  q.id                                                     as source_id,\n  coalesce(q.claimed_mentor_id, q.designated_mentor_id)    as mentor_id,\n  floor(q.price_cents::numeric * 0.85)::bigint             as mentor_amount_cents,\n  q.price_cents::bigint                                    as gross_cents,\n  (q.price_cents - floor(q.price_cents::numeric * 0.85)::bigint) as platform_fee_cents,\n  0.15::numeric                                            as fee_rate,\n  q.released_at                                            as completion_ts,\n  floor(floor(q.price_cents::numeric * 0.85) * 0.033)::bigint as withholding_cents_est, -- [114]\n  (floor(q.price_cents::numeric * 0.85)::bigint\n    - floor(floor(q.price_cents::numeric * 0.85) * 0.033)::bigint) as net_cents_est      -- [114]\nfrom public.individual_questions q\nwhere q.released_at is not null\n  and q.released_at <= now()                             -- [111] 미래 확정시각 방어\n  and q.release_ledger_id is null\n  and q.refund_ledger_id is null\n  and q.status not in (''refunded'', ''expired'', ''canceled'')\n  and coalesce(q.claimed_mentor_id, q.designated_mentor_id) is not null", "comment on view public.due_payouts is\n  ''107+111+114: 3채널 지급가능 후보 + completion_ts<=now() 방어 + 원천징수 3.3% 공제 예정액(withholding_cents_est/net_cents_est). 정밀 cutoff·실제 공제는 108 RPC.''", "revoke all on public.due_payouts from anon, authenticated", "grant select on public.due_payouts to service_role", "-- >>> NATIVE_BASELINE_PART 0125 | supabase/sql/115_account_deletion.sql | 115_account_deletion.sql <<<\n-- =============================================================================\n-- 115_account_deletion.sql\n-- ⚠️ 라이브 미적용 — 기능 플래그(NEXT_PUBLIC_FEATURE_ACCOUNT_DELETION) ON 배포 시점에 적용 (114 패턴)\n-- =============================================================================\n-- 목적(스펙 docs/plans/account-deletion-spec.md): 계정 삭제 = PII 익명화 + 원장 보존.\n--   물리 삭제 금지 근거(스펙 §0): public.users FK 84개(CASCADE 41) + users→auth.users\n--   ON DELETE CASCADE → auth 하드삭제 시 원장·거래 연쇄 파괴. 따라서 soft-delete만.\n--\n-- 신규 객체만 추가한다 — 기존 RLS/트리거/함수 무수정.\n--   ① user_deletion_log  : 감사 로그 (service_role 전용 — RLS enable + 정책 없음 = 기본 거부, payout_runs 패턴)\n--   ② anonymize_user_for_deletion(uuid, text) : SECURITY DEFINER RPC, service_role 전용\n--\n-- 실스키마 확정(2026-07-04 staging 실측 — 스펙 §1 \"임의 추정 금지\" 이행):\n--   users PII: full_name·nickname·email(nullable)·grade_level·student_status·birth_date\n--   users.status: CHECK 제약 없음(users_role_check만 존재) → ''deleted'' 마킹에 CHECK 확장 불필요\n--   mentor_profiles PII: university_name·department_name·high_school_name(NOT NULL 3종),\n--     teaching_subjects(NOT NULL array), intro_line·answer_style·student_id_image_url·\n--     profile_image_url·payout_bank_name·payout_account_number(nullable)\n--\n-- 금지(스펙 §1-2): cash_ledger·payments·settlement·payout·orders·subscriptions·reviews·\n--   community 콘텐츠의 UPDATE/DELETE 일절 없음 — 이 파일은 users/mentor_profiles의\n--   PII 컬럼 UPDATE + 신규 로그 INSERT만 수행한다. 작성자 표기는 표시 계층 조인이\n--   익명화된 nickname(''탈퇴회원_…'')을 읽어 자동 반영된다.\n--\n-- 선행(적용 시): 001(users/mentor_profiles), 102(status 부가 컬럼).\n-- =============================================================================\n\n-- ① 감사 로그 — service_role 전용\ncreate table if not exists public.user_deletion_log (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null unique references public.users (id),\n  requested_at timestamptz not null default now(),\n  reason text null,\n  snapshot jsonb not null default ''{}''::jsonb\n)", "comment on table public.user_deletion_log is\n  ''115: 계정 삭제(익명화) 감사 로그. user_id unique = RPC 멱등 기준. snapshot은 비-PII 메타만.''", "alter table public.user_deletion_log enable row level security", "-- 정책 없음 = anon/authenticated 기본 거부(service_role은 RLS 우회) — payout_runs(106) 패턴.\nrevoke all on public.user_deletion_log from public, anon, authenticated", "-- ② 익명화 RPC — service_role 전용\ncreate or replace function public.anonymize_user_for_deletion(\n  p_user_id uuid,\n  p_reason text default null\n)\nreturns table (already_deleted boolean, anonymized boolean)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_user public.users%rowtype;\n  v_has_mentor_profile boolean;\nbegin\n  -- 가드: 대상 존재\n  select * into v_user from public.users where id = p_user_id;\n  if not found then\n    raise exception ''anonymize_user_for_deletion: user % not found'', p_user_id;\n  end if;\n\n  -- 멱등: 이미 삭제 처리된 계정이면 no-op 반환\n  if exists (select 1 from public.user_deletion_log l where l.user_id = p_user_id)\n     or lower(coalesce(v_user.status, '''')) = ''deleted'' then\n    return query select true, false;\n    return;\n  end if;\n\n  select exists (select 1 from public.mentor_profiles mp where mp.user_id = p_user_id)\n    into v_has_mentor_profile;\n\n  -- users PII 익명화 (스펙 §1-2; email은 nullable 실측 → null)\n  update public.users\n  set full_name = ''탈퇴회원'',\n      nickname = ''탈퇴회원_'' || left(p_user_id::text, 8),\n      email = null,\n      grade_level = null,\n      student_status = null,\n      birth_date = null,\n      status = ''deleted'',\n      status_reason = coalesce(p_reason, ''user_requested_deletion''),\n      status_changed_at = now(),\n      updated_at = now()\n  where id = p_user_id;\n\n  -- mentor_profiles PII 익명화 (존재 시; NOT NULL 컬럼은 익명 문구, nullable은 null)\n  if v_has_mentor_profile then\n    update public.mentor_profiles\n    set university_name = ''(삭제됨)'',\n        department_name = ''(삭제됨)'',\n        high_school_name = ''(삭제됨)'',\n        teaching_subjects = ''{}''::text[],\n        intro_line = null,\n        answer_style = null,\n        student_id_image_url = null,\n        profile_image_url = null,\n        payout_bank_name = null,\n        payout_account_number = null,\n        updated_at = now()\n    where user_id = p_user_id;\n  end if;\n\n  -- 감사 로그 (snapshot은 비-PII 메타만 — PII 보관 시 익명화 취지 훼손)\n  insert into public.user_deletion_log (user_id, reason, snapshot)\n  values (\n    p_user_id,\n    p_reason,\n    jsonb_build_object(''role'', v_user.role, ''had_mentor_profile'', v_has_mentor_profile)\n  )\n  on conflict (user_id) do nothing;\n\n  return query select false, true;\nend;\n$function$", "comment on function public.anonymize_user_for_deletion(uuid, text) is\n  ''115: 계정 삭제 — users/mentor_profiles PII 익명화 + status=deleted + 감사 로그. 멱등(user_deletion_log unique). service_role 전용. ★라이브 미적용(플래그 ON 배포 시 적용).''", "revoke all on function public.anonymize_user_for_deletion(uuid, text) from public, anon, authenticated", "grant execute on function public.anonymize_user_for_deletion(uuid, text) to service_role", "-- >>> NATIVE_BASELINE_PART 0126 | supabase/sql/116_user_blocks.sql | 116_user_blocks.sql <<<\n-- =============================================================================\n-- 116_user_blocks.sql\n-- ⚠️ 라이브 미적용 — 플래그(NEXT_PUBLIC_FEATURE_USER_BLOCKS) ON 배포 시 적용 (114 패턴)\n-- =============================================================================\n-- 목적(스펙 docs/plans/user-blocks-spec.md): 사용자간 차단 — Google Play UGC 정책\n-- (신고+차단 병존) 대응. 공유 DB이므로 앱·웹이 같은 목록을 사용한다.\n-- 차단 = 노출 필터(차단한 사람의 뷰에만 적용). 상대 기능 제한 아님.\n-- 신규 객체만 추가 — 기존 RLS/테이블 무수정. v1 적용 범위 = 커뮤니티 UGC.\n-- 선행(적용 시): 001(users). ※ 115는 계정삭제 PR(feat/account-deletion)이 선점한 번호.\n-- =============================================================================\n\ncreate table if not exists public.user_blocks (\n  blocker_id uuid not null references public.users (id) on delete cascade,\n  blocked_id uuid not null references public.users (id) on delete cascade,\n  created_at timestamptz not null default now(),\n  primary key (blocker_id, blocked_id),\n  check (blocker_id <> blocked_id)\n)", "create index if not exists idx_user_blocks_blocker on public.user_blocks (blocker_id)", "comment on table public.user_blocks is\n  ''116: 사용자 차단(노출 필터). blocker의 뷰에서 blocked의 커뮤니티 UGC를 숨긴다. 불변 쌍(UPDATE 정책 없음).''", "alter table public.user_blocks enable row level security", "-- 본인 것만 조회·생성·해제 (self-block은 CHECK가 차단)\ndrop policy if exists ub_select_own on public.user_blocks", "create policy ub_select_own\n  on public.user_blocks for select\n  to authenticated\n  using (blocker_id = (select auth.uid()))", "drop policy if exists ub_insert_own on public.user_blocks", "create policy ub_insert_own\n  on public.user_blocks for insert\n  to authenticated\n  with check (blocker_id = (select auth.uid()))", "drop policy if exists ub_delete_own on public.user_blocks", "create policy ub_delete_own\n  on public.user_blocks for delete\n  to authenticated\n  using (blocker_id = (select auth.uid()))", "-- UPDATE 정책 없음 = 불변 쌍(차단은 생성/해제만).\n\n-- 관리자 운영 조회\ndrop policy if exists ub_select_admin on public.user_blocks", "create policy ub_select_admin\n  on public.user_blocks for select\n  to authenticated\n  using (public.is_admin())", "-- >>> NATIVE_BASELINE_PART 0127 | supabase/sql/117_question_attachments_v2_author_realtime_backfill.sql | 117_question_attachments_v2_author_realtime_backfill.sql <<<\n-- =============================================================================\n-- 117: 질문방 첨부 v2 — author_id 신설 + 레거시 마커 백필 + realtime + 마커 메시지 삭제\n-- =============================================================================\n-- 배경(XV-ATTACH): 웹은 서명 URL 을 메시지 본문 마커([[img]]/[[file]])로 저장·렌더,\n-- 앱은 question_attachments 행 기준 렌더 — 크로스(웹↔앱) 첨부 미표시 + 웹 7일 URL 부패.\n-- 확정 방향: 본문 마커 폐지, 첨부 테이블 단일 정본(첨부 v2 계약).\n--   결정 ①(2026-07-12): 레거시 마커 메시지는 백필 후 삭제(A안).\n--   결정 ③(2026-07-12): question_attachments 를 realtime publication 에 추가.\n--\n-- 실행 순서 고정: A(컬럼·정책) → C(기존 행 author 백필) → B(마커→행 백필)\n--                → E(realtime) → D(마커 메시지 삭제). D 는 반드시 B·C 뒤.\n-- 사전 조건: 049(버킷·스토리지 정책), 060(question_attachments 테이블·RLS) 적용 완료.\n-- 검증 쿼리: 파일 하단 §V. 문제 시 관찰: 삭제 전 마커 메시지는 §V-0 으로 건수 확인.\n\n-- -----------------------------------------------------------------------------\n-- A. author_id 컬럼 + insert 정책 강화(위조 방지)\n-- -----------------------------------------------------------------------------\nalter table public.question_attachments\n  add column if not exists author_id uuid references public.users(id) on delete set null", "comment on column public.question_attachments.author_id is\n  ''첨부 발신자(첨부 v2). null = author 미기록 레거시 — 클라이언트는 중립(중앙) 카드로 렌더.''", "drop policy if exists question_attachments_insert_via_room on public.question_attachments", "create policy question_attachments_insert_via_room on public.question_attachments\n  for insert\n  to authenticated\n  with check (\n    exists (\n      select 1\n      from public.question_threads qt\n      join public.mentor_student_rooms r on r.id = qt.mentor_student_room_id\n      where qt.id = question_attachments.thread_id\n        and (\n          r.student_id = (select auth.uid())\n          or r.mentor_id = (select auth.uid())\n        )\n    )\n    and (\n      message_id is null\n      or exists (\n        select 1\n        from public.question_messages qm\n        where qm.id = question_attachments.message_id\n          and qm.thread_id = question_attachments.thread_id\n      )\n    )\n    -- 첨부 v2: author_id 는 본인 것만(레거시 호환 위해 null 허용).\n    and (author_id is null or author_id = (select auth.uid()))\n  )", "-- -----------------------------------------------------------------------------\n-- C. 백필 2 — 이미 존재하는 linked 행의 author_id 를 연결 메시지 작성자로 채움\n--    (D 에서 마커 메시지가 삭제되기 전에 발신자 정보를 보존한다)\n-- -----------------------------------------------------------------------------\nupdate public.question_attachments a\n   set author_id = m.author_id\n  from public.question_messages m\n where a.message_id = m.id\n   and a.author_id is null", "-- -----------------------------------------------------------------------------\n-- B. 백필 1 — 마커 메시지 중 연결 행이 없는 것에서 storage 경로를 추출해 행 생성\n--    서명 URL 형식: .../storage/v1/object/sign/question-room-attachments/<path>?token=...\n--    업로더 경로 문자셋([\\w.\\-/])상 URL 인코딩 없음 — ''%'' 포함 극단 케이스는 스킵(§V-3 로 검출).\n-- -----------------------------------------------------------------------------\nwith markers as (\n  select\n    m.id          as message_id,\n    m.thread_id   as thread_id,\n    m.author_id   as author_id,\n    m.created_at  as created_at,\n    m.body        as body,\n    (m.body like ''[[img]]%'') as is_img\n  from public.question_messages m\n  where (m.body like ''[[img]]%'' or m.body like ''[[file]]%'')\n    and not exists (\n      select 1 from public.question_attachments a where a.message_id = m.id\n    )\n),\nparsed as (\n  select\n    message_id, thread_id, author_id, created_at, is_img,\n    case when is_img then null\n         else nullif(split_part(substr(body, length(''[[file]]'') + 1), ''|||'', 1), '''')\n    end as file_name,\n    -- 마커 종류와 무관하게 URL 파트에서 버킷 뒤 경로를 추출\n    substring(body from ''/object/sign/question-room-attachments/([^?]+)'') as storage_path\n  from markers\n)\ninsert into public.question_attachments\n  (thread_id, message_id, author_id, storage_path, file_name, mime_type, created_at)\nselect\n  p.thread_id,\n  p.message_id,\n  p.author_id,\n  p.storage_path,\n  coalesce(\n    p.file_name,\n    -- 이미지: 경로 말단에서 웹 업로더 접두(`{uuid}-`) 제거 시도\n    regexp_replace(split_part(p.storage_path, ''/'', 3),\n                   ''^[0-9a-fA-F-]{36}-'', '''')\n  ),\n  case\n    when p.is_img then\n      case lower(regexp_replace(p.storage_path, ''^.*\\.'', ''''))\n        when ''png''  then ''image/png''\n        when ''jpg''  then ''image/jpeg''\n        when ''jpeg'' then ''image/jpeg''\n        when ''webp'' then ''image/webp''\n        when ''gif''  then ''image/gif''\n        else ''image/jpeg''\n      end\n    else\n      case lower(regexp_replace(p.storage_path, ''^.*\\.'', ''''))\n        when ''pdf''  then ''application/pdf''\n        when ''zip''  then ''application/zip''\n        when ''docx'' then ''application/vnd.openxmlformats-officedocument.wordprocessingml.document''\n        when ''pptx'' then ''application/vnd.openxmlformats-officedocument.presentationml.presentation''\n        else ''application/octet-stream''\n      end\n  end,\n  p.created_at\nfrom parsed p\nwhere p.storage_path is not null\n  and position(''%'' in p.storage_path) = 0", "-- 인코딩 의심 경로는 스킵(§V-3)\n\n-- -----------------------------------------------------------------------------\n-- E. realtime — 앱이 상대방 첨부(standalone 포함)를 즉시 반영하도록 publication 추가\n--    (재실행 안전: 이미 포함돼 있으면 duplicate_object 무시)\n-- -----------------------------------------------------------------------------\ndo $$\nbegin\n  alter publication supabase_realtime add table public.question_attachments;\nexception\n  when duplicate_object then null;\nend $$", "-- -----------------------------------------------------------------------------\n-- D. 마커 메시지 삭제(결정 ① A안) — FK on delete set null 로 행은 standalone 전환.\n--    행이 확보된(백필 포함) 마커 메시지만 삭제한다. 경로 추출 실패분은 남겨 §V-3 에서 수동 처리.\n-- -----------------------------------------------------------------------------\ndelete from public.question_messages m\n where (m.body like ''[[img]]%'' or m.body like ''[[file]]%'')\n   and exists (\n     select 1 from public.question_attachments a where a.message_id = m.id\n   )", "-- =============================================================================\n-- §V. 적용 직후 검증 쿼리 (수동 실행)\n-- -----------------------------------------------------------------------------\n-- V-0) 삭제 전 마커 총량 파악(적용 ''전''에 실행):\n--   select count(*) from public.question_messages\n--    where body like ''[[img]]%'' or body like ''[[file]]%'';\n-- V-1) 잔존 마커 = 0 기대(경로 추출 실패분만 남을 수 있음 → V-3):\n--   select count(*) from public.question_messages\n--    where body like ''[[img]]%'' or body like ''[[file]]%'';\n-- V-2) linked 였다가 standalone 으로 전환된 행(message_id null) 분포 확인:\n--   select count(*) filter (where message_id is null) as standalone,\n--          count(*) filter (where author_id is null)  as author_null\n--     from public.question_attachments;\n-- V-3) 경로 추출 실패로 남은 마커(수동 1건 처리 대상):\n--   select id, thread_id, left(body, 120) from public.question_messages\n--    where (body like ''[[img]]%'' or body like ''[[file]]%'');\n-- =============================================================================\n\n-- >>> NATIVE_BASELINE_PART 0128 | supabase/sql/119_users_role_guard.sql | 119_users_role_guard.sql <<<\n-- =============================================================================\n-- 119: users.role 권한상승 차단 가드 (XV-01 / P0)\n-- =============================================================================\n-- 배경(XV-01): 001 의 \"users_update_own\" 정책이 컬럼 제한 없이 본인 행 UPDATE 를\n--   허용한다. 즉 로그인한 누구나\n--     update public.users set role = ''admin'' where id = auth.uid();\n--   로 스스로를 admin 으로 승격할 수 있다(P0 권한상승). role 은 is_admin() ·\n--   requireRole() · 다수 RLS 정책의 근거 값이라 즉시 전체 권한으로 번진다.\n--\n-- 조치: BEFORE UPDATE 트리거로 role 변경을 DB 최하층에서 차단한다.\n--   허용 조건(아래 셋 중 하나) 외에는 ROLE_CHANGE_FORBIDDEN 예외.\n--     1) 호출자 JWT role = ''service_role'' (서버 admin API 경유)\n--     2) JWT 자체가 없는 직접 DB 세션 (Supabase SQL Editor(postgres)·마이그레이션.\n--        PostgREST/GoTrue 경유 요청은 항상 role 클레임을 갖고 오므로 API 로는\n--        이 분기를 위조할 수 없다. 최초 admin 시드·수동 복구 경로 보존 목적)\n--     3) 호출자가 public.users 에서 role = ''admin'' (관리자 콘솔)\n--   ※ users 에 is_admin 같은 boolean 권한 컬럼은 없음(001 정의 + alter 이력 grep 0건.\n--     marketing_agreed 는 동의 플래그로 권한 아님) → 가드 대상은 role 단일 컬럼.\n--   ※ 3) 은 003 의 public.is_admin() 과 동일 판정이나, 실행 순서 의존을 없애기 위해\n--     인라인 EXISTS 로 자체 판정한다(BEFORE UPDATE 시점의 SELECT 는 변경 전\n--     스냅샷을 보므로 자기 자신을 승격하며 통과하는 경로는 생기지 않는다).\n--\n-- 성격: 재실행 안전(create or replace + drop trigger if exists). 파괴적 변경 없음.\n--   기존 정상 플로우(닉네임 등 role 무변경 UPDATE)는 WHEN 절에서 걸러져 비용 0에 수렴.\n-- 사전 조건: 001(public.users). RLS 정책 변경 없음 — 정책과 무관하게 모든 UPDATE\n--   경로(향후 정책 실수 포함)에 대해 동작하는 심층방어다.\n-- 검증 쿼리: 파일 하단 §V.\n-- =============================================================================\n\n-- -----------------------------------------------------------------------------\n-- A. 가드 함수\n-- -----------------------------------------------------------------------------\n-- security definer: 함수 소유자 권한으로 public.users 를 조회해 호출자의 admin\n-- 여부를 판정한다(호출자 RLS 로는 타인 행이 안 보여도 판정 가능해야 하므로).\n-- auth.jwt() 는 request.jwt.claims(요청 JWT)를 읽으므로 definer 여부와 무관하게\n-- \"호출자\" 기준이 유지된다.\ncreate or replace function public.enforce_users_role_guard()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_jwt_role text;\nbegin\n  -- 트리거를 WHEN 절 없이 재생성해도 안전하도록 함수 안에서도 재확인\n  if new.role is distinct from old.role then\n    v_jwt_role := auth.jwt() ->> ''role'';\n\n    if v_jwt_role = ''service_role'' then\n      return new; -- 1) 서버(service key) 경유\n    end if;\n\n    if v_jwt_role is null then\n      return new; -- 2) JWT 없는 직접 DB 세션(SQL Editor·마이그레이션)\n    end if;\n\n    if exists (\n      select 1\n        from public.users u\n       where u.id = (select auth.uid())\n         and u.role = ''admin''\n    ) then\n      return new; -- 3) 관리자\n    end if;\n\n    raise exception ''ROLE_CHANGE_FORBIDDEN''\n      using errcode = ''42501'', -- insufficient_privilege\n            detail  = format(''users.id=%s role %L -> %L'', old.id, old.role, new.role),\n            hint    = ''role 변경은 service_role 또는 admin 만 가능합니다.'';\n  end if;\n\n  return new;\nend;\n$$", "comment on function public.enforce_users_role_guard() is\n  ''XV-01: users.role 변경을 service_role/직접 DB 세션/admin 으로 제한하는 BEFORE UPDATE 가드.''", "-- 트리거 함수는 RPC 로 직접 호출될 수 없지만 관례대로 실행권한을 조인다.\nrevoke execute on function public.enforce_users_role_guard() from public, anon, authenticated", "-- -----------------------------------------------------------------------------\n-- B. 트리거 (재실행 안전)\n-- -----------------------------------------------------------------------------\ndrop trigger if exists trg_users_role_guard on public.users", "create trigger trg_users_role_guard\n  before update on public.users\n  for each row\n  when (old.role is distinct from new.role)\n  execute function public.enforce_users_role_guard()", "-- =============================================================================\n-- §V. 적용 직후 검증 (Supabase SQL Editor 에서 수동 실행)\n-- =============================================================================\n-- §V-0. 설치 확인 — 1행(트리거)·1행(함수) 기대:\n--   select tgname, tgenabled from pg_trigger\n--    where tgrelid = ''public.users''::regclass and tgname = ''trg_users_role_guard'';\n--   select proname, prosecdef from pg_proc\n--    where pronamespace = ''public''::regnamespace and proname = ''enforce_users_role_guard'';\n--\n-- §V-a. 일반 유저 시뮬레이션 → ROLE_CHANGE_FORBIDDEN 에러 기대.\n--   (<uid> 는 role=''student''/''mentor'' 인 실제 uuid 로 치환. RLS(users_update_own)\n--    때문에 sub 와 where id 가 같아야 트리거까지 도달한다.)\n--   begin;\n--     set local role authenticated;\n--     set local request.jwt.claims = ''{\"sub\":\"<uid>\",\"role\":\"authenticated\"}'';\n--     update public.users set role = ''admin'' where id = ''<uid>''::uuid;\n--   rollback;\n--   -- 기대: ERROR: ROLE_CHANGE_FORBIDDEN (42501)\n--\n-- §V-b. service_role 시뮬레이션 → 통과(UPDATE 1) 기대. rollback 이라 실변경 없음.\n--   begin;\n--     set local role service_role;\n--     set local request.jwt.claims = ''{\"role\":\"service_role\"}'';\n--     update public.users set role = ''mentor'' where id = ''<uid>''::uuid;\n--   rollback;\n--\n-- §V-c. (참고) role 무변경 UPDATE 는 어떤 호출자든 가드 미발동:\n--   §V-a 블록에서 set role 대신 nickname 등 다른 컬럼을 바꾸면 정상 통과해야 한다.\n-- =============================================================================\n\n-- >>> NATIVE_BASELINE_PART 0129 | supabase/sql/120_admin_console_fixes.sql | 120_admin_console_fixes.sql <<<\n-- 120_admin_console_fixes.sql\n-- 관리자 기능 점검(2026-07-17) 후속 수정 모음. 전 구간 멱등(재실행 안전).\n--\n-- A. content_reports 상태 CHECK 확장\n--    검수 콘솔의 숨김/삭제 처리(updateContentReportModerationAction)가\n--    status=''hidden''/''removed'' 를 쓰지만 032 CHECK가 거부 → 콘텐츠만 변경되고\n--    신고 상태 갱신이 실패하는 불일치. 허용값에 두 상태를 추가한다.\n-- B. disputes 상태 CHECK 확장\n--    제재 액션(applyDisputeSanctionAction)의 on_hold/sanction_* 상태를 허용.\n--    기존 CHECK 위반으로 제재 전체(계정 정지 연동 포함)가 첫 UPDATE에서 실패했다.\n-- C. 실 DB에만 수동 적용돼 있던 관리자 정책 백포트 (레포 SQL로 재구축 시에도 관리자 콘솔이 동작하도록)\n--    - users_admin_select_all / mp_admin_select_all / student_id_images_admin_select\n-- D. 게시판 v2 comments 정리\n--    - 조건 `true` 인 레거시 공개 정책 3종 제거(삭제된 댓글까지 전체 공개되던 누출).\n--      정상 노출은 comments_select_visible(is_deleted=false, anon+authenticated)이 계속 담당.\n--    - 관리자 검수용 select(숨김 포함)/update/delete 정책 추가.\n-- E. 관리자 증거 열람 보강\n--    - question-room-attachments / scan-annotations 버킷과 scan_annotations 테이블에\n--      관리자 SELECT 정책 추가(분쟁·신고 검토 시 첨부 확인용, service_role 불필요).\n\n-- ── A. content_reports 상태 CHECK ────────────────────────────────────────────\nalter table public.content_reports\n  drop constraint if exists content_reports_status_allowed", "alter table public.content_reports\n  add constraint content_reports_status_allowed\n  check (status = any (array[\n    ''pending'', ''reviewing'', ''resolved'', ''rejected'', ''dismissed'',\n    ''hidden'', ''removed''\n  ]))", "-- ── B. disputes 상태 CHECK ──────────────────────────────────────────────────\nalter table public.disputes\n  drop constraint if exists disputes_status_check", "alter table public.disputes\n  add constraint disputes_status_check\n  check (status = any (array[\n    ''open'', ''under_review'', ''resolved'', ''dismissed'', ''escalated'',\n    ''on_hold'', ''sanction_7d'', ''sanction_30d'', ''sanction_permanent''\n  ]))", "-- ── C. 관리자 정책 백포트 ────────────────────────────────────────────────────\ndrop policy if exists users_admin_select_all on public.users", "create policy users_admin_select_all on public.users\n  for select to authenticated\n  using ((select public.is_admin()) = true)", "drop policy if exists mp_admin_select_all on public.mentor_profiles", "create policy mp_admin_select_all on public.mentor_profiles\n  for select to authenticated\n  using ((select public.is_admin()) = true)", "drop policy if exists student_id_images_admin_select on storage.objects", "create policy student_id_images_admin_select on storage.objects\n  for select to authenticated\n  using (bucket_id = ''student-id-images'' and (select public.is_admin()) = true)", "-- ── D. comments(게시판 v2) 정책 정리 ─────────────────────────────────────────\ndrop policy if exists \"누구나 댓글 읽기\" on public.comments", "drop policy if exists \"로그인 유저 댓글 작성\" on public.comments", "drop policy if exists \"본인 댓글 삭제\" on public.comments", "drop policy if exists comments_admin_select_all on public.comments", "create policy comments_admin_select_all on public.comments\n  for select to authenticated\n  using ((select public.is_admin()) = true)", "drop policy if exists comments_admin_update on public.comments", "create policy comments_admin_update on public.comments\n  for update to authenticated\n  using ((select public.is_admin()) = true)\n  with check ((select public.is_admin()) = true)", "drop policy if exists comments_admin_delete on public.comments", "create policy comments_admin_delete on public.comments\n  for delete to authenticated\n  using ((select public.is_admin()) = true)", "-- ── E. 관리자 증거 열람(스토리지·주석 테이블) ────────────────────────────────\ndrop policy if exists qra_storage_read_admin on storage.objects", "create policy qra_storage_read_admin on storage.objects\n  for select to authenticated\n  using (bucket_id = ''question-room-attachments'' and (select public.is_admin()) = true)", "drop policy if exists scan_annotations_obj_admin_select on storage.objects", "create policy scan_annotations_obj_admin_select on storage.objects\n  for select to authenticated\n  using (bucket_id = ''scan-annotations'' and (select public.is_admin()) = true)", "drop policy if exists scan_annotations_admin_select on public.scan_annotations", "create policy scan_annotations_admin_select on public.scan_annotations\n  for select to authenticated\n  using ((select public.is_admin()) = true)", "comment on constraint content_reports_status_allowed on public.content_reports is\n  ''120: hidden/removed 추가 — 검수 콘솔 숨김/삭제 처리와 정합.''", "comment on constraint disputes_status_check on public.disputes is\n  ''120: on_hold/sanction_7d/sanction_30d/sanction_permanent 추가 — 분쟁 제재 액션과 정합.''", "-- >>> NATIVE_BASELINE_PART 0130 | supabase/sql/122_signup_role_no_admin.sql | 122_signup_role_no_admin.sql <<<\n-- --------------------------------------------------------------------------\n-- 122_signup_role_no_admin.sql\n-- 목적(P0-1): 가입 메타데이터(app_role)로 admin 권한 자가 획득 차단.\n--   handle_new_auth_user() 의 role 화이트리스트에서 ''admin'' 을 제거한다.\n--   001_initial_auth_profile.sql 본문과 완전히 동일하며, 단 한 줄\n--   (role 분기 화이트리스트)만 ''admin'' 미허용으로 교정한다.\n-- 선행: 001_initial_auth_profile.sql\n-- 참고: 운영/스테이징 DB에는 동등 교정이 이미 적용되어 있음\n--   (supabase_migrations 원장: 20260717044250 fix_xv01_signup_admin_provisioning).\n--   본 파일은 저장소 클린 설치 정본(001)과의 정합용 — 클린 설치 시에도\n--   가입 경로로 admin 승격이 불가능하도록 닫는다. (서버 방어는 DB가 정본;\n--   UI/TS 메타 정규화는 보조일 뿐이다.)\n-- --------------------------------------------------------------------------\n\ncreate or replace function public.handle_new_auth_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  m jsonb;\n  r text;\n  subj text[];\n  subj_str text;\n  bdate date;\nbegin\n  m := coalesce(NEW.raw_user_meta_data, ''{}''::jsonb);\n  r := lower(trim(m->>''app_role''));\n  if r is null or r = '''' then\n    r := ''student'';\n  end if;\n  -- P0-1: ''admin'' 제거 — 가입 메타로는 student/mentor 만 허용, 그 외 전부 student.\n  if r not in (''student'', ''mentor'') then\n    r := ''student'';\n  end if;\n\n  subj_str := nullif(trim(m->>''teaching_subjects_csv''), '''');\n  if subj_str is not null then\n    subj := array(\n      select trim(both '' '' from x)\n      from unnest(string_to_array(subj_str, '','')) as x\n      where length(trim(both '' '' from x)) > 0\n    );\n  else\n    subj := ''{}'';\n  end if;\n\n  begin\n    bdate := (m->>''birth_date'')::date;\n  exception when others then\n    bdate := null;\n  end;\n\n  insert into public.users (\n    id, role, status, full_name, nickname, email,\n    grade_level, student_status, birth_date,\n    terms_agreed_at, privacy_agreed_at, marketing_agreed, updated_at\n  ) values (\n    NEW.id, r, ''active'',\n    nullif(trim(m->>''full_name''), ''''),\n    nullif(trim(m->>''nickname''), ''''),\n    coalesce(NEW.email, ''''),\n    nullif(trim(m->>''grade_level''), ''''),\n    nullif(trim(m->>''student_status''), ''''),\n    bdate,\n    case when (m->>''terms_agreed'') = ''true'' then now() else null end,\n    case when (m->>''privacy_agreed'') = ''true'' then now() else null end,\n    case when (m->>''marketing_agreed'') = ''true'' then true else false end,\n    now()\n  )\n  on conflict (id) do update set\n    role = excluded.role,\n    full_name = coalesce(excluded.full_name, public.users.full_name),\n    nickname = coalesce(excluded.nickname, public.users.nickname),\n    email = excluded.email,\n    grade_level = coalesce(excluded.grade_level, public.users.grade_level),\n    student_status = coalesce(excluded.student_status, public.users.student_status),\n    birth_date = coalesce(excluded.birth_date, public.users.birth_date),\n    terms_agreed_at = coalesce(excluded.terms_agreed_at, public.users.terms_agreed_at),\n    privacy_agreed_at = coalesce(excluded.privacy_agreed_at, public.users.privacy_agreed_at),\n    marketing_agreed = excluded.marketing_agreed,\n    updated_at = now();\n\n  if r = ''mentor'' then\n    insert into public.mentor_profiles (\n      user_id, university_name, department_name, teaching_subjects, high_school_name, intro_line,\n      verification_status, student_id_image_url, updated_at\n    ) values (\n      NEW.id,\n      coalesce(nullif(trim(m->>''university_name''), ''''), ''(미입력)''),\n      coalesce(nullif(trim(m->>''department_name''), ''''), ''(미입력)''),\n      coalesce(subj, ''{}''),\n      coalesce(nullif(trim(m->>''high_school_name''), ''''), ''(미입력)''),\n      nullif(trim(m->>''intro_line''), ''''),\n      ''pending'',\n      null,\n      now()\n    )\n    on conflict (user_id) do update set\n      university_name = excluded.university_name,\n      department_name = excluded.department_name,\n      teaching_subjects = excluded.teaching_subjects,\n      high_school_name = excluded.high_school_name,\n      intro_line = coalesce(excluded.intro_line, public.mentor_profiles.intro_line),\n      updated_at = now();\n\n    insert into public.verification_logs (user_id, log_type, status, memo) values\n      (NEW.id, ''mentor_verification'', ''pending'', ''sign-up'');\n  end if;\n\n  return NEW;\nend;\n$$", "-- >>> NATIVE_BASELINE_PART 0131 | supabase/sql/123_reviews_converge.sql | 123_reviews_converge.sql <<<\n-- --------------------------------------------------------------------------\n-- 123_reviews_converge.sql   (P0-2 · 리뷰 스키마/데이터 수렴 — 멱등, 단일 트랜잭션)\n-- [적용됨 — ssambership-staging 에 2026-07-19 단일 트랜잭션(lock_timeout 3s) 적용·검증 통과.\n--   ⚠️ execute_sql 로 적용해 supabase_migrations 원장에는 미기재(드리프트) — 원장 기재는 별도 승인 후.]\n-- 목적: 하이브리드(042형 student_id/content NOT NULL + 004형 author_id/body) 상태를\n--   정본(author_id/body, subscription_count nullable, unique(mentor_id,author_id))으로 수렴.\n--   현재 웹 write(author_id/body만 INSERT)가 레거시 NOT NULL(student_id/content) 위반으로\n--   실패하는 결함을 해소한다.\n-- 선행: 004(reviews base)·042(reviews core). 정책 정본화는 126_reviews_rls_hardening.sql.\n-- ⚠️ 보안: student_id/content 제거 전에 reviews 의 기존 정책을 \"전부\" 제거해 fail-closed 로 만든다\n--   (rev_select USING(true)·rev_ins·rev_update_own·reviews_select_public·reviews_insert_student·\n--    reviews_insert_author·042/한글 정책 등 — student_id 참조 정책이 남으면 컬럼 DROP 실패,\n--    permissive 정책이 남으면 123~126 구간 보호 무력화). 123 적용 후 126 적용 전까지 리뷰 기능은\n--    닫힌 상태(정책 0개)이며, 이 구간에는 리뷰 트래픽을 재개하지 않는다.\n-- 정본 컬럼: id, mentor_id, author_id, rating, body(NOT NULL), subscription_count(nullable),\n--   mentor_reply, mentor_replied_at, is_hidden, is_blinded, moderation_state,\n--   moderated_at, moderated_by, created_at.\n-- 주의: 백필 → 격리 → SET NOT NULL → 중복정리 → UNIQUE 순서. 전 과정 단일 트랜잭션+테이블 잠금.\n--   (staging 실적용 시 reviews 0행이라 데이터 단계는 no-op이나, 실데이터 환경 대비 멱등 유지.)\n-- --------------------------------------------------------------------------\n\nbegin", "lock table public.reviews in share row exclusive mode", "-- (0) fail-closed: reviews 의 모든 정책 제거 (이름 불문 — 아래 컬럼 DROP·구간 보호를 위해 선행) -----\ndo $$\ndeclare pol record;\nbegin\n  for pol in\n    select policyname from pg_policies where schemaname=''public'' and tablename=''reviews''\n  loop\n    execute format(''drop policy if exists %I on public.reviews'', pol.policyname);\n  end loop;\nend $$", "-- (2-1) 컬럼 조건부 정합 (042형/004형 모두 대응) --------------------------------\nalter table public.reviews add column if not exists author_id uuid", "alter table public.reviews add column if not exists body text", "alter table public.reviews add column if not exists subscription_count integer", "alter table public.reviews add column if not exists mentor_reply text", "alter table public.reviews add column if not exists mentor_replied_at timestamptz", "alter table public.reviews add column if not exists is_hidden boolean not null default false", "alter table public.reviews add column if not exists is_blinded boolean not null default false", "alter table public.reviews add column if not exists moderation_state text not null default ''visible''", "alter table public.reviews add column if not exists moderated_at timestamptz", "alter table public.reviews add column if not exists moderated_by uuid", "-- (2-2) 백필 (042형 잔존 컬럼이 있으면 author_id<-student_id, body<-content) --------\ndo $$\nbegin\n  if exists (select 1 from information_schema.columns\n             where table_schema=''public'' and table_name=''reviews'' and column_name=''student_id'') then\n    update public.reviews set author_id = student_id where author_id is null;\n  end if;\n  if exists (select 1 from information_schema.columns\n             where table_schema=''public'' and table_name=''reviews'' and column_name=''content'') then\n    update public.reviews set body = content where body is null;\n  end if;\nend $$", "-- (2-3) NULL/고아 행 격리 — SET NOT NULL 앞 (service_role 전용 아카이브) --------------\ncreate table if not exists public.reviews_quarantine_archive (\n  id uuid primary key default gen_random_uuid(),\n  original_id uuid, reason text not null, payload jsonb not null,\n  archived_at timestamptz not null default now())", "alter table public.reviews_quarantine_archive enable row level security", "revoke all on public.reviews_quarantine_archive from public, anon, authenticated", "grant select, insert, update, delete on public.reviews_quarantine_archive to service_role", "drop policy if exists reviews_quarantine_archive_service on public.reviews_quarantine_archive", "create policy reviews_quarantine_archive_service on public.reviews_quarantine_archive\n  for all to service_role using (true) with check (true)", "create temporary table _rev_quarantine on commit drop as\n  select r.id from public.reviews r\n  where r.body is null or r.author_id is null\n     or not exists (select 1 from public.users u where u.id = r.author_id)\n     or not exists (select 1 from public.users u where u.id = r.mentor_id)", "insert into public.reviews_quarantine_archive (original_id, reason, payload)\n  select r.id, ''null_or_orphan_pre_converge'', to_jsonb(r)\n  from public.reviews r join _rev_quarantine q on q.id = r.id", "delete from public.reviews r using _rev_quarantine q where q.id = r.id", "-- (2-4) 레거시 NOT NULL/DEFAULT 해소 + 정본 필수 컬럼 확정 -------------------------\nalter table public.reviews alter column subscription_count drop default", "do $$\nbegin\n  if exists (select 1 from information_schema.columns\n             where table_schema=''public'' and table_name=''reviews''\n               and column_name=''subscription_count'' and is_nullable=''NO'') then\n    alter table public.reviews alter column subscription_count drop not null;\n  end if;\nend $$", "alter table public.reviews alter column author_id set not null", "alter table public.reviews alter column body set not null", "-- (2-4a) 레거시 student_id/content + 참조 객체 제거 (정책은 (0)에서 이미 전부 제거됨) ------\nalter table public.reviews drop constraint if exists reviews_student_id_fkey", "alter table public.reviews drop constraint if exists reviews_one_per_pair", "-- 구 (mentor_id, student_id) 유니크\ndrop index if exists public.idx_reviews_one_per_pair_compat", "drop index if exists public.idx_reviews_student", "alter table public.reviews drop column if exists student_id", "alter table public.reviews drop column if exists content", "-- (2-6) 인덱스 정본 수렴 -------------------------------------------------------\ncreate index if not exists idx_reviews_author on public.reviews (author_id)", "create index if not exists idx_reviews_mentor_created on public.reviews (mentor_id, created_at desc)", "-- (3) 중복 (mentor_id, author_id) 정리 후 UNIQUE ------------------------------\ncreate table if not exists public.reviews_duplicates_archive (\n  id uuid primary key default gen_random_uuid(),\n  original_id uuid, reason text not null, payload jsonb not null,\n  archived_at timestamptz not null default now())", "alter table public.reviews_duplicates_archive enable row level security", "revoke all on public.reviews_duplicates_archive from public, anon, authenticated", "grant select, insert, update, delete on public.reviews_duplicates_archive to service_role", "drop policy if exists reviews_duplicates_archive_service on public.reviews_duplicates_archive", "create policy reviews_duplicates_archive_service on public.reviews_duplicates_archive\n  for all to service_role using (true) with check (true)", "create temporary table _rev_dups on commit drop as\n  select id from (select id, row_number() over (partition by mentor_id, author_id\n                    order by created_at desc, id) as rn from public.reviews) k where k.rn > 1", "insert into public.reviews_duplicates_archive (original_id, reason, payload)\n  select r.id, ''dup_mentor_author_pre_unique'', to_jsonb(r)\n  from public.reviews r join _rev_dups d on d.id = r.id", "delete from public.reviews r using _rev_dups d where d.id = r.id", "create unique index if not exists uq_reviews_mentor_author on public.reviews (mentor_id, author_id)", "-- RLS 는 켜진 채로, 정책 0개(fail-closed) 상태로 커밋. 126 적용 시 정본 정책 재생성.\nalter table public.reviews enable row level security", "commit", "-- >>> NATIVE_BASELINE_PART 0132 | supabase/sql/124_iq_refund_state_gate.sql | 124_iq_refund_state_gate.sql <<<\n-- --------------------------------------------------------------------------\n-- 124_iq_refund_state_gate.sql   (P0-5 · 개별질문 답변후 셀프환불 차단 — 경쟁조건 제거)\n-- [적용됨 — ssambership-staging 에 2026-07-19 단일 트랜잭션(lock_timeout 3s) 적용·검증 통과\n--   (구조 assertion 5 + 시나리오 A~D PASS · 동시성 E는 독립 2세션 필요로 PENDING). core 정의 해시 불변 확인.\n--   원장 미기재 — 적용 이력: docs/audit/sql_apply_manifest.md]\n-- 목적: 학생 셀프환불 래퍼 refund_individual_question(p_question_id) 에 상태 게이트를 추가해,\n--   답변받은(answered) 개별질문의 셀프환불을 차단하고 경쟁조건(claimed↔answer 전이)을 제거한다.\n--   현재 래퍼(091)는 \"본인 여부\"만 확인하고 core(refund_individual_question_hold, 070)는\n--   refunded/released/payout-ledger/hold-missing 만 차단해 ''answered''(및 expired/canceled 등)를\n--   막지 않는다 → 학생이 답변을 받은 뒤에도 셀프환불이 가능(자금 결함).\n--   래퍼에서 대상 행을 FOR UPDATE 로 잠근 뒤 소유자·상태를 판정해 경쟁조건(claimed↔answer 전이)을 제거한다.\n-- 선행: 070, 091  (070 = core refund_individual_question_hold · 091 = wrapper refund_individual_question)\n-- ⚠️ core 는 변경하지 않는다(향후 감사가능 관리자 환불 여지 유지). 웹 만료 배치\n--    (individualQuestionExpiryBatch.ts)는 core 를 service_role 로 직접 호출하므로 본 변경과 무관.\n-- 허용 환불 상태(정본): escrowed / open / assigned / claimed\n--   (앱 individual_question_models.dart 및 individual_questions_status_check 기준).\n--   그 외(answered/released/expired/canceled)는 거부, refunded 는 core 위임으로 멱등 처리.\n-- --------------------------------------------------------------------------\n\ncreate or replace function public.refund_individual_question(p_question_id uuid)\nreturns public.individual_question_escrow_result\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_owner uuid;\n  v_status text;\n  v_refund_ledger uuid;\n  v_res public.individual_question_escrow_result;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  if p_question_id is null then\n    raise exception ''INVALID_INPUT: question_id is required'' using errcode = ''22023'';\n  end if;\n\n  -- 경쟁조건 제거: 대상 행을 잠근 뒤 소유자·상태를 판정한다(별표 없이 필요한 컬럼만).\n  select q.student_id, q.status, q.refund_ledger_id\n    into v_owner, v_status, v_refund_ledger\n  from public.individual_questions q\n  where q.id = p_question_id\n  for update;\n\n  -- 존재하지 않거나 소유자가 아니면 거부(비존재도 소유권 오류로 비노출 — 기존 동작 유지).\n  if not found or v_owner is distinct from v_uid then\n    raise exception ''NOT_QUESTION_OWNER'' using errcode = ''42501'';\n  end if;\n\n  -- 이미 환불된 경우: 거부가 아니라 core 로 위임해 멱등(already_refunded) 결과를 반환한다.\n  if v_status = ''refunded'' or v_refund_ledger is not null then\n    return public.refund_individual_question_hold(p_question_id);\n  end if;\n\n  -- 허용 상태 외에는 환불 불가(특히 ''answered'' 차단).\n  if v_status not in (''escrowed'', ''open'', ''assigned'', ''claimed'') then\n    raise exception ''REFUND_NOT_ALLOWED: status=%'', v_status using errcode = ''P0001'';\n  end if;\n\n  -- 허용 상태 → core 호출(core 는 유지). 잠금은 같은 트랜잭션에서 재진입 가능.\n  v_res := public.refund_individual_question_hold(p_question_id);\n\n  if not v_res.ok then\n    raise exception ''INDIVIDUAL_QUESTION_REFUND_FAILED:%:%'', v_res.code, v_res.message\n      using errcode = ''P0001'';\n  end if;\n\n  return v_res;\nend;\n$$", "comment on function public.refund_individual_question(uuid) is\n  ''P0-5 상태 게이트 래퍼: FOR UPDATE 로 대상 개별질문을 잠근 뒤 소유자를 확인하고, ''\n  ''허용 상태(escrowed/open/assigned/claimed)만 core(refund_individual_question_hold) 로 위임한다. ''\n  ''answered 등 그 외 상태는 REFUND_NOT_ALLOWED 로 거부하고, 이미 refunded 인 건은 core 위임으로 ''\n  ''already_refunded(ok=true) 멱등 반환한다. core 정의·권한은 변경하지 않는다.''", "-- >>> NATIVE_BASELINE_PART 0133 | supabase/sql/125_dispute_split_fee_5pct.sql | 125_dispute_split_fee_5pct.sql <<<\n-- --------------------------------------------------------------------------\n-- 125_dispute_split_fee_5pct.sql   (P0-6 · 맞춤의뢰 분쟁 분배 플랫폼 수수료 20%→5%)\n-- [적용됨 — ssambership-staging 에 2026-07-19 단일 트랜잭션(lock_timeout 3s) 적용·검증 통과\n--   (구조 assertion T1~T9 + 시나리오 S1~S5 전부 PASS). def md5 5cceee2f…→c60df394…, COMMENT gross−5%,\n--   ACL service_role 전용 확인. fixture 전량 rollback·baseline 0행 복원.\n--   원장 미기재 — 적용 이력: docs/audit/sql_apply_manifest.md]\n-- 목적: record_custom_order_dispute_split 의 플랫폼 수수료율만 0.20 → 0.05 로 확정한다\n--   (맞춤의뢰 정본 수수료 5% · 멘토 수령 95%). 기준 = 운영 실행 본문(057 정의) + 운영 ACL(072까지 반영).\n--   ⚠️ 072_harden_linter_warnings.sql 은 이 함수의 본문을 재정의하지 않고 EXECUTE 권한만 재확인한다.\n--   계산 순서·반올림(floor)·불변식·멱등키·원장 사유/참조·반환 계약·권한은 그대로 보존한다.\n--   helper 함수·테이블·다른 금융 RPC·057·072 파일은 수정하지 않는다.\n-- 선행: 057, 072\n-- ⚠️ 운영 실행 로직과 유일한 의미 있는 차이 = v_fee_rate 0.20→0.05 (COMMENT도 20%→5%로 정정; 그 외는 라인엔딩 정규화뿐).\n-- --------------------------------------------------------------------------\n\nCREATE OR REPLACE FUNCTION public.record_custom_order_dispute_split(p_order_id uuid, p_mentor_gross_won integer, p_student_refund_won integer, p_admin_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  o public.custom_request_orders%rowtype;\n  s public.custom_order_settlement_items%rowtype;\n  v_hold_idem text := ''cr_hold_'' || p_order_id::text;\n  v_payout_idem text := ''cr_payout_'' || p_order_id::text;\n  v_refund_idem text := ''cr_refund_'' || p_order_id::text;\n  v_dispute_payout_idem text := ''cr_dispute_payout_'' || p_order_id::text;\n  v_dispute_refund_idem text := ''cr_dispute_refund_'' || p_order_id::text;\n  v_hold_cents bigint;\n  v_hold_gross_won integer;\n  v_settlement_gross integer;\n  v_fee_rate numeric := 0.05;\n  v_platform_fee_won integer;\n  v_mentor_net_won integer;\n  v_mentor_cents bigint;\n  v_student_cents bigint;\n  v_pay text;\n  v_norm text;\n  v_admin_ok boolean;\n  v_new_mentor_ledger uuid;\n  v_new_student_ledger uuid;\n  v_wu int;\n  v_now timestamptz := now();\n  v_disputes_resolved int := 0;\nbegin\n  if p_order_id is null then\n    raise exception ''p_order_id is required'';\n  end if;\n  if p_admin_id is null then\n    raise exception ''ADMIN_REQUIRED'';\n  end if;\n  if p_mentor_gross_won is null or p_student_refund_won is null then\n    raise exception ''DISPUTE_SPLIT_AMOUNTS_REQUIRED'';\n  end if;\n  if p_mentor_gross_won < 0 or p_student_refund_won < 0 then\n    raise exception ''DISPUTE_SPLIT_AMOUNTS_INVALID'';\n  end if;\n\n  select exists(\n    select 1 from public.users u where u.id = p_admin_id and u.role = ''admin''\n  ) into v_admin_ok;\n  if not coalesce(v_admin_ok, false) then\n    raise exception ''ADMIN_REQUIRED'';\n  end if;\n\n  select * into o\n  from public.custom_request_orders\n  where id = p_order_id\n  for update;\n\n  if not found then\n    raise exception ''ORDER_NOT_FOUND'';\n  end if;\n\n  if o.student_id is null or o.mentor_id is null then\n    raise exception ''ORDER_PARTIES_MISSING'';\n  end if;\n\n  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''''), '''')));\n  v_norm := public._order_primary_status_norm(o);\n\n  -- payout / refund / dispute-split 상호 배타\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key = v_payout_idem\n      and l.reason = ''custom_order_escrow_payout''\n  ) then\n    raise exception ''ALREADY_PAID_OUT'';\n  end if;\n\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key = v_refund_idem\n      and l.reason = ''custom_order_escrow_refund''\n  ) then\n    raise exception ''ALREADY_REFUNDED'';\n  end if;\n\n  select * into s\n  from public.custom_order_settlement_items\n  where custom_request_order_id = p_order_id\n  for update;\n\n  if found and s.status = ''paid'' then\n    raise exception ''ALREADY_PAID_OUT'';\n  end if;\n\n  select abs(l.delta_cents) into v_hold_cents\n  from public.cash_ledger l\n  where l.idempotency_key = v_hold_idem\n    and l.reason = ''custom_order_escrow_hold''\n  limit 1;\n\n  if v_hold_cents is null then\n    raise exception ''ESCROW_HOLD_MISSING'';\n  end if;\n\n  if v_hold_cents <= 0 or v_hold_cents > 1000000000 then\n    raise exception ''ESCROW_HOLD_AMOUNT_INVALID'';\n  end if;\n\n  if v_hold_cents % 100 <> 0 then\n    raise exception ''ESCROW_HOLD_AMOUNT_INVALID'';\n  end if;\n\n  v_hold_gross_won := (v_hold_cents / 100)::integer;\n\n  if found then\n    v_settlement_gross := s.gross_amount;\n    if v_settlement_gross is distinct from v_hold_gross_won then\n      raise exception ''ESCROW_HOLD_AMOUNT_MISMATCH'';\n    end if;\n  end if;\n\n  -- 멱등: 분배 ledger 가 하나라도 있으면 상태 수리 후 종료\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key in (v_dispute_payout_idem, v_dispute_refund_idem)\n      and l.reason in (''custom_order_dispute_payout'', ''custom_order_dispute_refund'')\n  ) then\n    update public.custom_order_settlement_items\n    set status = ''cancelled'', updated_at = v_now\n    where custom_request_order_id = p_order_id\n      and status in (''pending'', ''on_hold'', ''payable'');\n\n    update public.custom_request_orders\n    set\n      payment_status = ''dispute_resolved'',\n      status = ''dispute_resolved'',\n      state = ''dispute_resolved'',\n      order_status = ''dispute_resolved'',\n      updated_at = v_now\n    where id = p_order_id;\n\n    update public.disputes d\n    set\n      status = ''resolved'',\n      resolved_at = coalesce(d.resolved_at, v_now),\n      resolved_by = coalesce(d.resolved_by, p_admin_id),\n      updated_at = v_now\n    where d.custom_request_order_id = p_order_id\n      and d.status in (''open'', ''under_review'', ''escalated'');\n\n    get diagnostics v_disputes_resolved = row_count;\n\n    return jsonb_build_object(\n      ''ok'', true,\n      ''noop'', true,\n      ''order_id'', p_order_id,\n      ''hold_gross_won'', v_hold_gross_won,\n      ''disputes_resolved'', v_disputes_resolved\n    );\n  end if;\n\n  if p_mentor_gross_won + p_student_refund_won is distinct from v_hold_gross_won then\n    raise exception ''DISPUTE_SPLIT_MISMATCH'';\n  end if;\n\n  if v_pay not in (''escrowed'', ''dispute_resolved'') then\n    raise exception ''PAYMENT_NOT_ESCROWED'';\n  end if;\n\n  v_platform_fee_won := floor(p_mentor_gross_won * v_fee_rate)::integer;\n  v_mentor_net_won := p_mentor_gross_won - v_platform_fee_won;\n  v_mentor_cents := v_mentor_net_won::bigint * 100;\n  v_student_cents := p_student_refund_won::bigint * 100;\n\n  if v_mentor_cents > 1000000000 or v_student_cents > 1000000000 then\n    raise exception ''p_amount_too_large'';\n  end if;\n\n  if v_mentor_cents > 0 then\n    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n    values (\n      o.mentor_id,\n      v_mentor_cents,\n      ''custom_order_dispute_payout'',\n      ''custom_request_orders'',\n      p_order_id,\n      v_dispute_payout_idem\n    )\n    on conflict (idempotency_key) do nothing\n    returning id into v_new_mentor_ledger;\n\n    if v_new_mentor_ledger is not null then\n      insert into public.cash_wallets (user_id, balance_cents)\n      values (o.mentor_id, 0)\n      on conflict (user_id) do nothing;\n\n      update public.cash_wallets w\n      set balance_cents = w.balance_cents + v_mentor_cents\n      where w.user_id = o.mentor_id;\n      get diagnostics v_wu = row_count;\n      if coalesce(v_wu, 0) = 0 then\n        raise exception ''CASH_WALLET_UPDATE_FAILED'' using errcode = ''P0001'';\n      end if;\n    end if;\n  end if;\n\n  if v_student_cents > 0 then\n    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n    values (\n      o.student_id,\n      v_student_cents,\n      ''custom_order_dispute_refund'',\n      ''custom_request_orders'',\n      p_order_id,\n      v_dispute_refund_idem\n    )\n    on conflict (idempotency_key) do nothing\n    returning id into v_new_student_ledger;\n\n    if v_new_student_ledger is not null then\n      insert into public.cash_wallets (user_id, balance_cents)\n      values (o.student_id, 0)\n      on conflict (user_id) do nothing;\n\n      update public.cash_wallets w\n      set balance_cents = w.balance_cents + v_student_cents\n      where w.user_id = o.student_id;\n      get diagnostics v_wu = row_count;\n      if coalesce(v_wu, 0) = 0 then\n        raise exception ''CASH_WALLET_UPDATE_FAILED'' using errcode = ''P0001'';\n      end if;\n    end if;\n  end if;\n\n  update public.custom_order_settlement_items\n  set status = ''cancelled'', updated_at = v_now\n  where custom_request_order_id = p_order_id\n    and status in (''pending'', ''on_hold'', ''payable'');\n\n  update public.custom_request_orders\n  set\n    payment_status = ''dispute_resolved'',\n    status = ''dispute_resolved'',\n    state = ''dispute_resolved'',\n    order_status = ''dispute_resolved'',\n    updated_at = v_now\n  where id = p_order_id;\n\n  update public.disputes d\n  set\n    status = ''resolved'',\n    resolved_at = coalesce(d.resolved_at, v_now),\n    resolved_by = coalesce(d.resolved_by, p_admin_id),\n    updated_at = v_now\n  where d.custom_request_order_id = p_order_id\n    and d.status in (''open'', ''under_review'', ''escalated'');\n\n  get diagnostics v_disputes_resolved = row_count;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''noop'', false,\n    ''order_id'', p_order_id,\n    ''hold_gross_won'', v_hold_gross_won,\n    ''mentor_gross_won'', p_mentor_gross_won,\n    ''mentor_platform_fee_won'', v_platform_fee_won,\n    ''mentor_net_won'', v_mentor_net_won,\n    ''mentor_cents'', v_mentor_cents,\n    ''student_refund_won'', p_student_refund_won,\n    ''student_cents'', v_student_cents,\n    ''fee_rate'', v_fee_rate,\n    ''disputes_resolved'', v_disputes_resolved\n  );\nend;\n$function$", "-- 메타데이터 COMMENT 정정 (기존 gross−20% → 5%)\ncomment on function public.record_custom_order_dispute_split(\n  uuid, integer, integer, uuid\n) is\n  ''P0: Custom order dispute escrow split — mentor net (gross−5%) + student refund; hold gross must match sum. service_role only.''", "-- service_role 전용 EXECUTE 권한 재확정 (멱등)\nrevoke all on function public.record_custom_order_dispute_split(\n  uuid, integer, integer, uuid\n) from public, anon, authenticated", "grant execute on function public.record_custom_order_dispute_split(\n  uuid, integer, integer, uuid\n) to service_role", "-- >>> NATIVE_BASELINE_PART 0134 | supabase/sql/126_reviews_rls_hardening.sql | 126_reviews_rls_hardening.sql <<<\n-- --------------------------------------------------------------------------\n-- 126_reviews_rls_hardening.sql   (P1-7 · 리뷰 RLS 정본화 — 다세대 정책 정리 + 컬럼 강제)\n-- [적용됨 — ssambership-staging 에 2026-07-19 단일 트랜잭션(lock_timeout 3s) 적용·검증 통과\n--   (구조 assertion 7 + 역할 스모크 5 전부 PASS). 원장 미기재 — 적용 이력은 docs/audit/sql_apply_manifest.md.]\n-- 목적: reviews 의 중복/레거시 정책을 전부 제거하고, 자격검증 INSERT·역할별 UPDATE·\n--   숨김/블라인드 보호 SELECT 정책만 남긴다. 행 접근은 정책이, 컬럼 범위는 트리거가 강제.\n--   ⚠️ 004의 rev_select USING(true) 가 남으면 모든 SELECT 정책과 OR 결합되어 숨김·블라인드\n--      보호가 무력화되므로 반드시 제거한다. 순수 042형/045형의 student_id·author 정책도 제거.\n-- 선행: 066 (check_review_eligibility), 123 (reviews 스키마 수렴·fail-closed 상태).\n--   is_admin()·check_review_eligibility() 는 이미 존재. 123 로 정책 0개(fail-closed)인 상태에서\n--   본 파일이 정본 정책을 다시 연다(적용 전까지 리뷰 트래픽 재개 금지).\n-- --------------------------------------------------------------------------\n\nalter table public.reviews enable row level security", "-- 1) 기존 정책 전부 제거 -----------------------------------------------------\n-- (a) 알려진 이름 명시 제거 (감사용)\ndrop policy if exists \"rev_select\"                     on public.reviews", "-- 004 USING(true) — 치명적\ndrop policy if exists \"rev_ins\"                        on public.reviews", "-- 004 (자격 미검증)\ndrop policy if exists \"rev_update_own\"                 on public.reviews", "-- 004 (with_check 없음)\ndrop policy if exists \"reviews_select_public\"          on public.reviews", "-- 042형 (is_blinded 미검사)\ndrop policy if exists \"reviews_select_public_visible\"  on public.reviews", "drop policy if exists \"reviews_select_admin\"           on public.reviews", "drop policy if exists \"reviews_insert_author\"          on public.reviews", "-- 구 자격 정책명\ndrop policy if exists \"reviews_insert_student\"         on public.reviews", "-- 042형(student_id)/045형(author_id)\ndrop policy if exists \"reviews_update_mentor_reply\"    on public.reviews", "drop policy if exists \"reviews_update_mentor\"          on public.reviews", "drop policy if exists \"reviews_admin_moderate\"         on public.reviews", "drop policy if exists \"reviews_update_admin\"           on public.reviews", "drop policy if exists \"누구나 리뷰 읽기\"                on public.reviews", "drop policy if exists \"학생만 리뷰 작성\"                on public.reviews", "drop policy if exists \"멘토 답글 작성\"                  on public.reviews", "-- (b) 그 외 남은 정책까지 이름 불문 전부 제거 (누락 방지 — OR 결합 무력화 봉쇄)\ndo $$\ndeclare pol record;\nbegin\n  for pol in select policyname from pg_policies where schemaname=''public'' and tablename=''reviews'' loop\n    execute format(''drop policy if exists %I on public.reviews'', pol.policyname);\n  end loop;\nend $$", "-- 2) SELECT 정본 — 공개: 숨김/블라인드 아닌 행만. 관리자: 전체. -----------------\ncreate policy \"reviews_select_public_visible\" on public.reviews\n  for select to anon, authenticated\n  using (coalesce(is_hidden, false) = false and coalesce(is_blinded, false) = false)", "create policy \"reviews_select_admin\" on public.reviews\n  for select to authenticated\n  using ((select public.is_admin()) = true)", "-- 3) INSERT 정본 — 자격검증 (author 본인 + 유료 2회+ 구독 이력) --------------------\ncreate policy \"reviews_insert_student\" on public.reviews\n  for insert to authenticated\n  with check (\n    author_id = (select auth.uid())\n    and public.check_review_eligibility(mentor_id, (select auth.uid()))\n  )", "-- 4) UPDATE 정본 — 행 접근만(컬럼 범위는 5의 트리거) -----------------------------\ncreate policy \"reviews_update_mentor\" on public.reviews\n  for update to authenticated\n  using ((select auth.uid()) = mentor_id)\n  with check ((select auth.uid()) = mentor_id)", "create policy \"reviews_update_admin\" on public.reviews\n  for update to authenticated\n  using ((select public.is_admin()) = true)\n  with check ((select public.is_admin()) = true)", "-- 5) BEFORE UPDATE 트리거 — 역할별 허용 컬럼 강제 --------------------------------\ncreate or replace function public.reviews_enforce_update()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_is_admin boolean := coalesce((select public.is_admin()), false);\nbegin\n  -- service_role: 시스템 경로 통과\n  if coalesce(auth.role(), '''') = ''service_role'' then\n    return new;\n  end if;\n\n  -- 공통 불변 보호 필드 (모든 비-service 액터)\n  if new.id is distinct from old.id\n     or new.mentor_id is distinct from old.mentor_id\n     or new.author_id is distinct from old.author_id\n     or new.rating is distinct from old.rating\n     or new.body is distinct from old.body\n     or new.subscription_count is distinct from old.subscription_count\n     or new.created_at is distinct from old.created_at then\n    raise exception ''reviews: protected columns are immutable'';\n  end if;\n\n  -- 관리자: is_hidden/is_blinded/moderation_state 만. moderated_* 서버 강제.\n  if v_is_admin then\n    if new.mentor_reply is distinct from old.mentor_reply\n       or new.mentor_replied_at is distinct from old.mentor_replied_at then\n      raise exception ''reviews: admin must not change mentor reply fields'';\n    end if;\n    new.moderated_at := now();\n    new.moderated_by := v_uid;\n    return new;\n  end if;\n\n  -- 멘토(본인 리뷰): mentor_reply 만, 1회. moderation 필드 변경 금지. replied_at 서버 강제.\n  if v_uid is not null and v_uid = old.mentor_id then\n    if new.is_hidden is distinct from old.is_hidden\n       or new.is_blinded is distinct from old.is_blinded\n       or new.moderation_state is distinct from old.moderation_state\n       or new.moderated_at is distinct from old.moderated_at\n       or new.moderated_by is distinct from old.moderated_by then\n      raise exception ''reviews: mentor must not change moderation fields'';\n    end if;\n    if old.mentor_reply is not null and new.mentor_reply is distinct from old.mentor_reply then\n      raise exception ''reviews: mentor reply already set (one-time only)'';\n    end if;\n    if new.mentor_reply is distinct from old.mentor_reply\n      then new.mentor_replied_at := now(); else new.mentor_replied_at := old.mentor_replied_at; end if;\n    return new;\n  end if;\n\n  -- 학생(작성자) 및 그 외: 수정 불가\n  raise exception ''reviews: not permitted to update this review'';\nend;\n$$", "drop trigger if exists trg_reviews_enforce_update on public.reviews", "create trigger trg_reviews_enforce_update\n  before update on public.reviews\n  for each row execute function public.reviews_enforce_update()", "-- >>> NATIVE_BASELINE_PART 0135 | supabase/sql/128_refund_admin_restore_escrow.sql | 128_refund_admin_restore_escrow.sql <<<\n-- --------------------------------------------------------------------------\n-- 128_refund_admin_restore_escrow.sql   (P1-9 · 관리자 환불 승인 맞춤의뢰 에스크로 분기 복원)\n-- [적용됨 — ssambership-staging 에 2026-07-19 단일 트랜잭션(lock_timeout 3s) 적용·검증 통과\n--   (구조 T1~T5 + 기능 S1~S4 PASS: 맞춤의뢰 에스크로 환불 복원·generic 이중credit 0·구독 generic 유지·\n--   멱등 noop·정산 paid 차단). def md5 0e730afb…→변경. fixture savepoint 롤백·baseline 0행 복원.\n--   원장 미기재 — 적용 이력: docs/audit/sql_apply_manifest.md]\n-- 목적: 099 가 재정의한 approve_refund_request_admin 은 맞춤의뢰(custom_request_order_id) 환불에도\n--   generic ''refund_approved'' 크레딧(r.amount_cents)만 실행하고 056 에스크로 refund helper 를 호출하지\n--   않아, hold 반환·정산/주문 정리가 에스크로 정본 경로로 이뤄지지 않았다. 본 파일은 **최신 099 본문**을\n--   기준으로 맞춤의뢰 분기를 복원해 record_custom_order_escrow_refund(056) 로 위임하고, 그 경우\n--   generic 크레딧을 실행하지 않아 **이중 credit 을 방지**한다.\n-- 선행: 057(=056 계열 에스크로), 072(권한 재확인). record_custom_order_escrow_refund(056) helper 는 재작성하지 않는다.\n-- 보존: admin 가드 · pending 가드 · 구독 settlement-paid 가드(099) · 구독 generic 크레딧/멱등키·지갑·\n--   payment/subscription 상태 전이. 서명·SECURITY DEFINER·service_role 전용 ACL 불변.\n-- P1-13 주의: 향후 P1-13 이 승인 함수를 재정의할 때 **본 128 본문을 기반**으로 구독 paid 가드·맞춤의뢰\n--   에스크로 분기·(P1-13) billing-event/settlement 잠금을 함께 보존해야 한다.\n-- 실상태(2026-07-19 staging): refunds/custom_request_orders/관련 원장 모두 0행(백필·대사 불필요).\n-- --------------------------------------------------------------------------\n\ncreate or replace function public.approve_refund_request_admin(p_refund_id uuid, p_admin_id uuid, p_admin_note text default null::text)\n returns jsonb\n language plpgsql\n security definer\n set search_path to ''public''\nas $function$\ndeclare\n  r public.refunds%rowtype;\n  v_amount bigint;\n  v_settlement_status text;\n  v_idem text := ''refund_credit:'' || p_refund_id::text;\n  v_ledger_id uuid;\n  v_existing_delta bigint;\n  v_wu int;\n  v_admin_ok boolean;\nbegin\n  if p_refund_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''환불 ID가 필요합니다.'');\n  end if;\n  if p_admin_id is null then\n    return jsonb_build_object(''ok'', false, ''message'', ''관리자 ID가 필요합니다.'');\n  end if;\n\n  select exists(\n    select 1 from public.users u where u.id = p_admin_id and u.role = ''admin''\n  ) into v_admin_ok;\n  if not coalesce(v_admin_ok, false) then\n    raise exception ''ADMIN_REQUIRED'';\n  end if;\n\n  select * into r from public.refunds where id = p_refund_id for update;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''message'', ''환불 요청을 찾을 수 없습니다.'');\n  end if;\n\n  if r.status is distinct from ''pending'' then\n    return jsonb_build_object(''ok'', true, ''noop'', true, ''refund_id'', p_refund_id,\n      ''message'', ''이미 처리되었거나 대기 상태가 아닙니다.'', ''status'', r.status);\n  end if;\n\n  -- 정산 지급 완료 시 자동 환불 차단 (맞춤의뢰)\n  if r.custom_request_order_id is not null then\n    select s.status into v_settlement_status\n    from public.custom_order_settlement_items s\n    where s.custom_request_order_id = r.custom_request_order_id\n    limit 1;\n    if found and v_settlement_status = ''paid'' then\n      return jsonb_build_object(''ok'', false,\n        ''message'', ''이미 정산 지급이 완료된 건은 자동 환불할 수 없습니다. 수동 조정이 필요합니다.'');\n    end if;\n  end if;\n\n  -- 정산 지급 완료 시 자동 환불 차단 (구독) — 099\n  if r.payment_id is not null\n     and (r.subscription_id is not null or coalesce(r.request_type, '''') = ''subscription_prorated'') then\n    select s.status into v_settlement_status\n    from public.subscription_settlement_items s\n    where s.payment_id = r.payment_id and s.status = ''paid''\n    limit 1;\n    if found then\n      return jsonb_build_object(''ok'', false,\n        ''message'', ''이미 멘토 정산 지급이 완료된 구독 건은 자동 환불할 수 없습니다. 수동 조정이 필요합니다.'');\n    end if;\n  end if;\n\n  -- ===== P1-9 복원: 맞춤의뢰 환불은 에스크로 helper(056)로 위임한다.\n  --   helper 가 hold 반환(custom_order_escrow_refund)·정산 취소·주문 취소/refunded 를 멱등 처리한다.\n  --   generic ''refund_approved'' 크레딧을 함께 실행하지 않아 이중 credit 을 방지한다. =====\n  if r.custom_request_order_id is not null then\n    perform public.record_custom_order_escrow_refund(r.custom_request_order_id);\n    update public.refunds\n    set status = ''succeeded'', processed_at = now(), processed_by = p_admin_id,\n        admin_note = p_admin_note, updated_at = now()\n    where id = r.id;\n    return jsonb_build_object(''ok'', true, ''noop'', false, ''refund_id'', r.id,\n      ''kind'', ''custom_order_escrow'', ''message'', ''맞춤의뢰 환불이 승인되었습니다.'');\n  end if;\n\n  -- ===== 구독/결제 환불: generic 크레딧(기존 099 로직 보존) =====\n  if r.amount_cents is null or r.amount_cents <= 0 then\n    raise exception ''환불 금액이 설정되지 않아 자동 승인할 수 없습니다.'';\n  end if;\n\n  v_amount := r.amount_cents;\n\n  if v_amount > 1000000000 then\n    return jsonb_build_object(''ok'', false, ''message'', ''환불 금액이 허용 한도를 초과합니다.'');\n  end if;\n\n  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n  values (r.user_id, v_amount, ''refund_approved'', ''refunds'', r.id, v_idem)\n  on conflict (idempotency_key) do nothing\n  returning id into v_ledger_id;\n\n  if v_ledger_id is null then\n    select cl.delta_cents into v_existing_delta\n    from public.cash_ledger cl where cl.idempotency_key = v_idem limit 1;\n    if not found then\n      raise exception ''REFUND_LEDGER_IDEMPOTENT_MISS'' using errcode = ''P0001'';\n    end if;\n    if v_existing_delta is distinct from v_amount then\n      raise exception ''REFUND_LEDGER_AMOUNT_MISMATCH'' using errcode = ''P0001'';\n    end if;\n  end if;\n\n  if v_ledger_id is not null then\n    insert into public.cash_wallets (user_id, balance_cents)\n    values (r.user_id, 0)\n    on conflict (user_id) do nothing;\n\n    update public.cash_wallets w\n    set balance_cents = w.balance_cents + v_amount\n    where w.user_id = r.user_id;\n    get diagnostics v_wu = row_count;\n    if coalesce(v_wu, 0) = 0 then\n      raise exception ''CASH_WALLET_UPDATE_FAILED'' using errcode = ''P0001'';\n    end if;\n  end if;\n\n  update public.refunds\n  set status = ''succeeded'', processed_at = now(), processed_by = p_admin_id,\n      admin_note = p_admin_note, updated_at = now()\n  where id = r.id;\n\n  if r.payment_id is not null then\n    update public.payments p set status = ''refunded'', updated_at = now() where p.id = r.payment_id;\n  end if;\n\n  if r.payment_id is not null then\n    update public.subscriptions s\n    set status = ''canceled'', updated_at = now()\n    where s.payment_id = r.payment_id and s.status is distinct from ''canceled'';\n  end if;\n\n  return jsonb_build_object(''ok'', true, ''noop'', false, ''refund_id'', r.id,\n    ''ledger_inserted'', (v_ledger_id is not null), ''amount_cents'', v_amount,\n    ''message'', ''환불이 승인되었습니다.'');\nend;\n$function$", "revoke all on function public.approve_refund_request_admin(uuid, uuid, text) from public, anon, authenticated", "grant execute on function public.approve_refund_request_admin(uuid, uuid, text) to service_role", "-- >>> NATIVE_BASELINE_PART 0136 | supabase/sql/129_shortform_author_label.sql | 129_shortform_author_label.sql <<<\n-- --------------------------------------------------------------------------\n-- 129_shortform_author_label.sql   (P0-3 · 숏폼 작성자 라벨 컬럼 정본화)\n-- [적용됨 — ssambership-staging 에 2026-07-19 단일 트랜잭션(lock_timeout 3s, LOCK shortform_posts) 적용.\n--   구조 assertion A1~A5 PASS(컬럼 text·nullable·default 없음 / 신규 제약 0 / 정책 7개 불변 / RLS on / 0행).\n--   rollback-only fixture 는 별도 미승인이라 생략. 원장 미기재 — 적용 이력: docs/audit/sql_apply_manifest.md]\n-- 목적: shortform_posts 에 작성자 표시 라벨 author_label(text, nullable) 컬럼을 추가해,\n--   웹 writer(insertShortformPost/updateShortformPost)가 이미 payload 로 기록하는 필드와\n--   스키마 계약을 일치시킨다. 현재 컬럼 부재로 정상 INSERT 가 실패 → 폴백 INSERT(video_url·status\n--   누락, status default ''published'' 로 강제공개)로 빠지는 P0-3 결함의 \"스키마측 원인\"을 제거한다.\n--   (코드측 폴백 삭제·Storage 보상은 웹 변경에서 별도 처리.)\n-- 선행: 038  (038_p1_shortform_v2.sql = shortform_posts v2 정본 형태[video_url·status CHECK·tags 등].\n--            최초 테이블 draft 는 002_app_core_schema_draft.sql / 004_p0_cash_disputes_admin_draft.sql,\n--            author_role 은 017, likes 는 082. author_label 은 커뮤니티 게시판(037)·댓글(016)에만\n--            존재했고 shortform_posts 에는 부재였음 — 본 파일에서 최초 추가.)\n-- 계약: community_posts(037)·community_comments(016) 의 author_label 은 NOT NULL + default 이지만,\n--   숏폼 표시는 resolveCommunityAuthorLabel(저장 라벨 → users 조회 → 브랜드 라벨) 폴백이 있어\n--   NOT NULL/DEFAULT/길이 CHECK 를 강제하지 않는다(오너 지시). nullable text 단일 컬럼만 추가한다.\n--   기존 데이터 백필 불필요(staging 0행). 표시 폴백이 미저장 행을 그대로 처리한다.\n-- --------------------------------------------------------------------------\n\nalter table public.shortform_posts\n  add column if not exists author_label text", "-- >>> NATIVE_BASELINE_PART 0137 | supabase/sql/130_shortform_scrap_reaction.sql | 130_shortform_scrap_reaction.sql <<<\n-- --------------------------------------------------------------------------\n-- 130_shortform_scrap_reaction.sql   (P2-14 · 숏폼 reactions scrap 허용)\n-- [적용됨 — ssambership-staging 에 2026-07-19 단일 트랜잭션(lock_timeout 3s) 적용·검증 통과\n--   (T1 CHECK like/scrap · T2 RLS WITH CHECK like/scrap · S1 인증 사용자 scrap+like 삽입 성공·잘못된 type 거부).\n--   fixture savepoint 롤백·baseline 0행 복원. 원장 미기재 — 적용 이력: docs/audit/sql_apply_manifest.md]\n-- 목적: shortform_reactions 의 type 을 like 뿐 아니라 scrap 도 허용한다. **CHECK 제약과 RLS INSERT\n--   WITH CHECK 를 함께** 바꿔야 한다(한쪽만 바꾸면 실패). 게시판(post_reactions)은 이미 like/scrap 을\n--   지원하나 숏폼은 CHECK·RLS 가 like 만 허용해 scrap 삽입이 거부됐다.\n-- 선행: 082(shortform_reactions). 실상태: 0행, `type_check`=CHECK(type=''like''), insert 정책 WITH CHECK=type=''like''.\n-- 보존: UNIQUE(user_id,shortform_id,type)·FK·delete/select 정책 불변. 데이터 백필 불필요(0행).\n-- --------------------------------------------------------------------------\n\nalter table public.shortform_reactions drop constraint if exists shortform_reactions_type_check", "alter table public.shortform_reactions\n  add constraint shortform_reactions_type_check check (type in (''like'', ''scrap''))", "drop policy if exists shortform_reactions_insert_own on public.shortform_reactions", "create policy shortform_reactions_insert_own on public.shortform_reactions\n  for insert to authenticated\n  with check ((user_id = (select auth.uid())) and (type in (''like'', ''scrap'')))", "-- >>> NATIVE_BASELINE_PART 0138 | supabase/sql/131_p1_13_subscription_checkout_atomic.sql | 131_p1_13_subscription_checkout_atomic.sql <<<\n-- 131_p1_13_subscription_checkout_atomic.sql\n-- P1-13: 구독·결제 원자 상태기계 (예약 번호 131 = P1-13 전용).\n--\n-- 모델: 즉시 내부지갑 적립(실은행 송금 아님). 정본 테이블 public.payments / public.subscriptions.\n-- 기존 웹 체크아웃(finalizeSubscriptionCheckout)의 3단계 비원자 시퀀스\n--   insertSubscriptionRow(직접 INSERT) → record_subscription_cash_debit → markPaymentSucceeded\n-- 를 단일 트랜잭션 RPC 로 대체한다. 실패 시 부분 반영·수동 보상 경로 제거.\n--\n-- 안전: staging 0행(금융 계보 충돌 없음). rollback-only fixture 만. 실지갑·실결제·실원장 무변경.\n--       기존 019/023 record_subscription_cash_debit(멱등 primitive) 재사용. 028/029 direct-write 잠금 유지.\n-- 동시성: 독립 2세션 실측 부재 → CONCURRENCY_VALIDATION_DEBT.\n-- 선행: 019/023(cash debit), 064(billing period), 067(mentor_plans), 121(plan band).\n\nbegin", "set local lock_timeout=''5s''", "-- ── 1) 스키마: payments.plan_id + camelCase metadata.planId 백필 ──\nalter table public.payments add column if not exists plan_id uuid", "update public.payments\n  set plan_id = (metadata->>''planId'')::uuid\n  where plan_id is null\n    and coalesce(metadata->>''planId'','''') ~ ''^[0-9a-fA-F-]{36}$''", "-- ── 2) 스키마: mentor_profiles.is_open_for_subscriptions 정본(기본 open) ──\nalter table public.mentor_profiles\n  add column if not exists is_open_for_subscriptions boolean not null default true", "-- ── 3) 원자 상태기계 RPC (service_role 전용) ──\ncreate or replace function public.confirm_subscription_checkout(\n  p_payment_id uuid,\n  p_plan_id uuid,\n  p_idempotency_key text default null\n) returns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_student uuid; v_mentor uuid; v_pay_status text; v_created_at timestamptz;\n  v_plan_mentor uuid; v_plan_tier text; v_plan_active boolean; v_amount_cents int;\n  v_is_open boolean; v_sub_id uuid; v_existing_delta bigint; v_reactivated boolean := false;\n  v_succeeded_aliases text[] := array[''succeeded'',''paid'',''success'',''complete'',''captured''];\nbegin\n  -- 결제 행 잠금 + 로드.\n  select user_id, mentor_id, status, created_at\n    into v_student, v_mentor, v_pay_status, v_created_at\n  from public.payments where id = p_payment_id for update;\n  if not found then raise exception ''PAYMENT_NOT_FOUND''; end if;\n  if v_student is null then raise exception ''PAYMENT_NO_USER''; end if;\n\n  -- 이미 성공(별칭 포함) → 멱등 반환.\n  if v_pay_status = any(v_succeeded_aliases) then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor;\n    return jsonb_build_object(''ok'', true, ''idempotent'', true, ''subscription_id'', v_sub_id, ''payment_status'', ''succeeded'');\n  end if;\n  -- processing 은 성공 아님. 그 외 종료 상태 거부.\n  if v_pay_status = ''processing'' then raise exception ''PAYMENT_PROCESSING''; end if;\n  if v_pay_status in (''failed'',''canceled'',''refunded'') then raise exception ''PAYMENT_NOT_PENDING''; end if;\n  if v_pay_status <> ''pending'' then raise exception ''PAYMENT_STATE_UNEXPECTED''; end if;\n  -- pending 확정 TTL 30분(서버 시각 강제).\n  if v_created_at is null or now() > v_created_at + interval ''30 minutes'' then\n    raise exception ''PAYMENT_STALE'';\n  end if;\n\n  -- 멘토·플랜 잠금 + 자격/금액 정본.\n  perform 1 from public.mentor_profiles where user_id = v_mentor for update;\n  select is_open_for_subscriptions into v_is_open from public.mentor_profiles where user_id = v_mentor;\n  if not coalesce(v_is_open, true) then raise exception ''MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS''; end if;\n\n  select mentor_id, plan_tier, is_active, amount_cents\n    into v_plan_mentor, v_plan_tier, v_plan_active, v_amount_cents\n  from public.mentor_plans where id = p_plan_id for update;\n  if not found then raise exception ''PLAN_NOT_FOUND''; end if;\n  if v_plan_mentor <> v_mentor then raise exception ''PLAN_MENTOR_MISMATCH''; end if;\n  if not coalesce(v_plan_active, true) then raise exception ''PLAN_INACTIVE''; end if;\n  if v_amount_cents is null or v_amount_cents <= 0 then raise exception ''PLAN_AMOUNT_INVALID''; end if;\n\n  -- 원장 멱등 사전 검사: 동일 payment 의 기존 debit 행이 있으면 금액(전 필드) 일치만 허용.\n  select delta_cents into v_existing_delta from public.cash_ledger\n    where idempotency_key = ''sub_debit_'' || p_payment_id::text;\n  if v_existing_delta is not null and v_existing_delta <> -v_amount_cents then\n    -- 불일치 격리: 구조화 실패(롤백되나 호출자가 대사 기록). 자동 삭제·대사 금지.\n    raise exception ''LEDGER_AMOUNT_MISMATCH existing=% expected=%'', v_existing_delta, -v_amount_cents;\n  end if;\n\n  -- 구독 생성/재활성화(uq_subscriptions_pair 로 pair 잠금·mutex).\n  insert into public.subscriptions (\n    student_id, mentor_id, plan_id, plan_tier, status, payment_id,\n    started_at, current_period_start, current_period_end, next_billing_at, billing_cycle,\n    cancel_at_period_end, last_payment_id\n  ) values (\n    v_student, v_mentor, p_plan_id, v_plan_tier, ''active'', p_payment_id,\n    now(), now(), now() + interval ''1 month'', now() + interval ''1 month'', ''monthly'',\n    false, p_payment_id\n  )\n  on conflict (student_id, mentor_id) do update set\n    plan_id = excluded.plan_id, plan_tier = excluded.plan_tier, status = ''active'',\n    payment_id = excluded.payment_id, last_payment_id = excluded.last_payment_id,\n    started_at = coalesce(public.subscriptions.started_at, now()),\n    current_period_start = now(), current_period_end = now() + interval ''1 month'',\n    next_billing_at = now() + interval ''1 month'', cancel_at_period_end = false,\n    cancel_requested_at = null, canceled_at = null, expired_at = null, grace_until = null,\n    last_renewed_at = now(), updated_at = now()\n  returning id into v_sub_id;\n  v_reactivated := (v_existing_delta is not null);\n\n  -- 지갑 차감(019/023 멱등 primitive; 잔액 부족 시 CASH_INSUFFICIENT).\n  perform public.record_subscription_cash_debit(v_student, v_sub_id, p_payment_id, v_amount_cents::bigint);\n\n  -- payment succeeded 정본화 + plan_id/metadata 백필.\n  update public.payments\n    set status = ''succeeded'', plan_id = p_plan_id,\n        metadata = coalesce(metadata, ''{}''::jsonb) || jsonb_build_object(''planId'', p_plan_id::text, ''subscription_id'', v_sub_id::text),\n        updated_at = now()\n  where id = p_payment_id;\n\n  return jsonb_build_object(\n    ''ok'', true, ''subscription_id'', v_sub_id, ''payment_status'', ''succeeded'',\n    ''amount_cents'', v_amount_cents, ''reactivated'', v_reactivated\n  );\nend;\n$$", "revoke all on function public.confirm_subscription_checkout(uuid,uuid,text) from public, anon, authenticated", "grant execute on function public.confirm_subscription_checkout(uuid,uuid,text) to service_role", "commit", "-- §V (rollback-only): pending→active+debit+succeeded · 재호출 멱등 · processing 거부 · TTL stale 거부 ·\n--   is_open=false 거부 · 잔액부족 CASH_INSUFFICIENT · 금액은 mentor_plans 정본 · plan_id/metadata 백필 ·\n--   재활성화(취소 후) 기간 초기화 · 원장 금액 불일치 LEDGER_AMOUNT_MISMATCH.\n-- service_role 전용(authenticated/anon 실행 불가). 동시성 2세션 = CONCURRENCY_VALIDATION_DEBT.\n\n-- >>> NATIVE_BASELINE_PART 0139 | supabase/sql/132_notification_outbox_foundation.sql | 132_notification_outbox_foundation.sql <<<\n-- --------------------------------------------------------------------------\n-- 132_notification_outbox_foundation.sql   (P1-11F · 알림 outbox foundation)\n-- [적용됨 — ssambership-staging 에 2026-07-19 단일 트랜잭션(lock_timeout 3s) 적용·검증 통과\n--   (구조 T1~T5 + 멱등/fan-out/RLS호환 F1~F5 PASS). fixture savepoint 롤백·baseline 0행 복원.\n--   원장 미기재 — 적용 이력: docs/audit/sql_apply_manifest.md]\n-- 목적(결정 C 계약): 도메인 write 와 같은 트랜잭션에서 인앱 알림 + outbox 를 원자적으로 기록할\n--   최소 foundation 을 만든다. 외부 FCM 호출·device token·17개 writer 연결은 P1-11C(별도)에서 완성.\n-- 계약:\n--   - 수신자별 행 모델. 다중 수신자는 같은 domain event 를 수신자별 행으로 fan-out.\n--   - notifications: UNIQUE(recipient_user_id, event_key) — 수신자·이벤트당 인앱 1건(멱등).\n--   - notification_outbox: UNIQUE(recipient_user_id, dedup_key) — 수신자·dedup 당 outbox 1건(멱등).\n--   - 기록 함수는 SECURITY DEFINER·service_role 전용(public/anon/authenticated 실행 금지).\n--   - payload 에 canonical event id(event_key/notification_id) 포함. 외부 발송은 트랜잭션 밖 worker.\n-- 선행: 없음(신규 테이블/컬럼). 단 P1-8(127)·P1-13(131) 도메인 RPC 가 본 helper 를 호출하므로\n--   클린설치에서 본 파일은 127/131 보다 먼저 적용해야 한다(apply_manifest_prod.md 참조).\n-- 실상태: notifications 존재(0행, 6개 레거시 수신자 컬럼·event_key 부재). notification_outbox·device_tokens 부재.\n--   기존 RLS(notif_select_recipient/notif_update_recipient_read)는 user_id 등 레거시 컬럼을 검사하므로\n--   helper 는 recipient_user_id 와 함께 user_id 도 세팅해 기존 RLS 읽기/읽음 호환을 유지한다.\n-- 제외: FCM worker, device token lifecycle, 도메인 writer 연결, type 백필(0행이라 불필요), Flutter.\n-- --------------------------------------------------------------------------\n\n-- 1) notifications 정본 컬럼(additive · nullable · 레거시 호환)\nalter table public.notifications\n  add column if not exists recipient_user_id uuid references public.users(id) on delete cascade", "alter table public.notifications\n  add column if not exists event_key text", "-- 수신자·이벤트당 인앱 1건(부분 UNIQUE — 레거시 NULL 행은 제약 밖).\ncreate unique index if not exists uq_notifications_recipient_event\n  on public.notifications (recipient_user_id, event_key)\n  where recipient_user_id is not null and event_key is not null", "create index if not exists idx_notifications_recipient_user\n  on public.notifications (recipient_user_id)\n  where recipient_user_id is not null", "-- 2) notification_outbox (신규 · service_role 전용)\ncreate table if not exists public.notification_outbox (\n  id uuid primary key default gen_random_uuid(),\n  recipient_user_id uuid not null references public.users(id) on delete cascade,\n  notification_id uuid references public.notifications(id) on delete set null,\n  event_key text not null,\n  dedup_key text not null,\n  event_type text not null,\n  payload jsonb not null default ''{}''::jsonb,\n  status text not null default ''pending'',\n  attempt_count int not null default 0,\n  max_attempts int not null default 8,\n  lease_owner text,\n  leased_until timestamptz,\n  next_attempt_at timestamptz not null default now(),\n  last_error text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint notification_outbox_status_chk\n    check (status in (''pending'',''leased'',''sent'',''failed'',''dead'')),\n  constraint notification_outbox_recipient_dedup_uq\n    unique (recipient_user_id, dedup_key)\n)", "-- worker claim 용(pending/failed 를 next_attempt_at 순으로).\ncreate index if not exists idx_notification_outbox_claim\n  on public.notification_outbox (status, next_attempt_at)\n  where status in (''pending'',''failed'')", "-- updated_at 자동 갱신(기존 set_updated_at() 재사용).\ndrop trigger if exists trg_notification_outbox_set_updated on public.notification_outbox", "create trigger trg_notification_outbox_set_updated\n  before update on public.notification_outbox\n  for each row execute function public.set_updated_at()", "-- 3) RLS: outbox 는 service_role 전용(정책 없음 → authenticated/anon 거부, service_role 우회).\nalter table public.notification_outbox enable row level security", "revoke all on public.notification_outbox from anon, authenticated", "grant select, insert, update, delete on public.notification_outbox to service_role", "-- 4) 도메인 알림 기록 helper (도메인 트랜잭션 안에서 호출 · 멱등)\ncreate or replace function public.record_domain_notification(\n  p_recipient_user_id uuid,\n  p_event_key text,\n  p_dedup_key text,\n  p_event_type text,\n  p_title text,\n  p_body text,\n  p_link text default null,\n  p_metadata jsonb default ''{}''::jsonb,\n  p_payload jsonb default ''{}''::jsonb\n) returns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_notif_id uuid;\n  v_outbox_id uuid;\n  v_notif_created boolean := false;\n  v_outbox_created boolean := false;\nbegin\n  if p_recipient_user_id is null then\n    raise exception ''RECIPIENT_REQUIRED'';\n  end if;\n  if p_event_key is null or p_dedup_key is null or p_event_type is null then\n    raise exception ''EVENT_KEYS_REQUIRED'';\n  end if;\n\n  -- 인앱 알림: 수신자·event_key 당 1건. user_id 도 세팅해 기존 RLS(recipient) 호환.\n  insert into public.notifications\n    (recipient_user_id, user_id, event_key, type, body, metadata, data, is_read)\n  values\n    (p_recipient_user_id, p_recipient_user_id, p_event_key, p_event_type, p_body,\n     coalesce(p_metadata, ''{}''::jsonb) || jsonb_build_object(''event_key'', p_event_key, ''link'', p_link),\n     jsonb_build_object(''title'', p_title, ''link'', p_link),\n     false)\n  on conflict (recipient_user_id, event_key)\n    where recipient_user_id is not null and event_key is not null\n  do nothing\n  returning id into v_notif_id;\n  v_notif_created := v_notif_id is not null;\n\n  if v_notif_id is null then\n    select id into v_notif_id\n    from public.notifications\n    where recipient_user_id = p_recipient_user_id and event_key = p_event_key\n    limit 1;\n  end if;\n\n  -- outbox: 수신자·dedup_key 당 1건. payload 에 canonical event id 포함.\n  insert into public.notification_outbox\n    (recipient_user_id, notification_id, event_key, dedup_key, event_type, payload)\n  values\n    (p_recipient_user_id, v_notif_id, p_event_key, p_dedup_key, p_event_type,\n     coalesce(p_payload, ''{}''::jsonb) || jsonb_build_object(''event_key'', p_event_key, ''notification_id'', v_notif_id))\n  on conflict (recipient_user_id, dedup_key)\n  do nothing\n  returning id into v_outbox_id;\n  v_outbox_created := v_outbox_id is not null;\n\n  if v_outbox_id is null then\n    select id into v_outbox_id\n    from public.notification_outbox\n    where recipient_user_id = p_recipient_user_id and dedup_key = p_dedup_key\n    limit 1;\n  end if;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''notification_id'', v_notif_id,\n    ''outbox_id'', v_outbox_id,\n    ''notification_created'', v_notif_created,\n    ''outbox_created'', v_outbox_created\n  );\nend;\n$$", "comment on function public.record_domain_notification(uuid, text, text, text, text, text, text, jsonb, jsonb) is\n  ''P1-11F: 도메인 트랜잭션 내 인앱 알림+outbox 원자·멱등 기록. 수신자·event_key/dedup_key 당 1건. service_role 전용. 외부 발송은 worker(트랜잭션 밖).''", "revoke all on function public.record_domain_notification(uuid, text, text, text, text, text, text, jsonb, jsonb) from public, anon, authenticated", "grant execute on function public.record_domain_notification(uuid, text, text, text, text, text, text, jsonb, jsonb) to service_role", "-- >>> NATIVE_BASELINE_PART 0140 | supabase/sql/133_mark_all_notifications_read.sql | 133_mark_all_notifications_read.sql <<<\n-- --------------------------------------------------------------------------\n-- 133_mark_all_notifications_read.sql   (P2-15 · 본인 전체 미읽음 알림 읽음 처리 RPC)\n-- [적용됨 — ssambership-staging 에 2026-07-19 단일 트랜잭션(lock_timeout 3s) 적용·검증 통과\n--   (T1 secdef/search_path · T2 authenticated/service_role 실행·anon 불가 · S1 본인 3건 읽음 · S2 재호출 0 멱등 · S3 타 사용자 보존).\n--   fixture savepoint 롤백·baseline 0행 복원. 원장 미기재 — 적용 이력: docs/audit/sql_apply_manifest.md]\n-- 목적: 클라이언트가 \"로드한 ID\"만 읽음 처리하던 문제를 없애고, 서버에서 본인 전체 미읽음 알림을\n--   원자적으로 읽음 처리하는 RPC 를 제공한다. 소유권은 auth.uid() 로 서버 판정하고, 멱등(재호출 0건)·\n--   row count 반환. SECURITY DEFINER 지만 WHERE 로 본인 행만 갱신하므로 authenticated 실행 허용.\n-- 선행: 132(notifications.recipient_user_id). notifications 6개 레거시 수신자 컬럼 + recipient_user_id 를 모두 소유 판정.\n-- 보존: is_read(정본)·read_at 만 갱신. 다른 컬럼·정책·타 사용자 행 불변.\n-- --------------------------------------------------------------------------\n\ncreate or replace function public.mark_all_notifications_read()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_count int;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  update public.notifications\n  set is_read = true,\n      read_at = coalesce(read_at, now()),\n      updated_at = now()\n  where is_read is distinct from true\n    and (\n      user_id = v_uid or recipient_id = v_uid or student_id = v_uid\n      or mentor_id = v_uid or target_user_id = v_uid or owner_id = v_uid\n      or recipient_user_id = v_uid\n    );\n  get diagnostics v_count = row_count;\n  return coalesce(v_count, 0);\nend;\n$$", "comment on function public.mark_all_notifications_read() is\n  ''P2-15: 호출자(auth.uid()) 본인의 전체 미읽음 알림을 읽음 처리하고 갱신 행수를 반환한다(멱등). 로드한 ID 에 의존하지 않는다.''", "revoke all on function public.mark_all_notifications_read() from public, anon", "grant execute on function public.mark_all_notifications_read() to authenticated, service_role", "-- >>> NATIVE_BASELINE_PART 0141 | supabase/sql/134_mentor_profile_bio.sql | 134_mentor_profile_bio.sql <<<\n-- --------------------------------------------------------------------------\n-- 134_mentor_profile_bio.sql   (P2-24 · 멘토 상세 소개(bio) 저장 컬럼)\n-- [적용됨 — ssambership-staging 에 2026-07-19 단일 트랜잭션(lock_timeout 3s, LOCK mentor_profiles) 적용.\n--   구조 검증: bio 컬럼 text·nullable·default 없음. 원장 미기재 — 적용 이력: docs/audit/sql_apply_manifest.md]\n-- 목적: 프로필 편집의 \"상세 소개\"(bio, 500자) 는 폼에 있으나 저장 컬럼이 없어 서버가 무시했다.\n--   nullable bio text 컬럼을 추가해 웹 편집이 실제로 저장되도록 한다. intro_line(한줄 소개)과 별개.\n-- 선행: mentor_profiles(001/가입 스키마). additive nullable, default 없음, CHECK 없음. 백필 불필요.\n-- --------------------------------------------------------------------------\n\nalter table public.mentor_profiles\n  add column if not exists bio text", "-- >>> NATIVE_BASELINE_PART 0142 | supabase/sql/135_mentor_review_stats_rpc.sql | 135_mentor_review_stats_rpc.sql <<<\n-- --------------------------------------------------------------------------\n-- 135_mentor_review_stats_rpc.sql   (P3-2 · 멘토 리뷰 통계 서버 집계 RPC)\n-- [적용됨 — ssambership-staging 에 2026-07-19 단일 트랜잭션(lock_timeout 3s) 적용·검증 통과\n--   (T1 secdef/search_path · T2 anon/authenticated 실행 · T3 0행 빈결과 · S1 공개 blinded 제외 ·\n--    S2 비관리자 include_hidden 강제 공개 · S3 관리자 include). fixture savepoint 롤백·baseline 0행 복원.\n--   원장 미기재 — 적용 이력: docs/audit/sql_apply_manifest.md]\n-- 목적: 리뷰 평균/분포를 클라이언트가 최대 500건 fetch 후 집계하던 cap 결함을 제거하고, 서버에서\n--   mentor별 count·평균·분포(1~5)를 집계해 반환한다. **집계값만 반환**(원본 행 미노출)하므로 일반\n--   사용자가 blinded/hidden 원본을 우회 조회할 수 없다. 공개 통계는 is_hidden/is_blinded 를 제외한다.\n--   include_hidden 은 관리자(is_admin())만 허용(그 외는 강제 false).\n-- 선행: 042/123/126(reviews 정본: mentor_id·rating·is_hidden·is_blinded). is_admin() 필요.\n-- 방식: SECURITY DEFINER 집계 RPC(권한 제한 — 원본 미노출·include_hidden admin 게이트). anon/authenticated 실행 허용.\n-- --------------------------------------------------------------------------\n\ncreate or replace function public.get_mentor_review_stats(\n  p_mentor_id uuid,\n  p_include_hidden boolean default false\n)\nreturns table(review_count integer, avg_rating numeric, d1 integer, d2 integer, d3 integer, d4 integer, d5 integer)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_include_hidden boolean := coalesce(p_include_hidden, false);\nbegin\n  -- include_hidden 은 관리자만 허용. 그 외에는 공개 집계(hidden/blinded 제외)로 강제.\n  if v_include_hidden and not coalesce(public.is_admin(), false) then\n    v_include_hidden := false;\n  end if;\n\n  return query\n  select\n    count(*)::integer,\n    case when count(*) > 0 then round(avg(r.rating)::numeric, 1) else null end,\n    count(*) filter (where round(r.rating) = 1)::integer,\n    count(*) filter (where round(r.rating) = 2)::integer,\n    count(*) filter (where round(r.rating) = 3)::integer,\n    count(*) filter (where round(r.rating) = 4)::integer,\n    count(*) filter (where round(r.rating) = 5)::integer\n  from public.reviews r\n  where r.mentor_id = p_mentor_id\n    and (\n      v_include_hidden\n      or (coalesce(r.is_hidden, false) = false and coalesce(r.is_blinded, false) = false)\n    );\nend;\n$$", "comment on function public.get_mentor_review_stats(uuid, boolean) is\n  ''P3-2: 멘토 리뷰 통계(count·avg·분포) 서버 집계. 집계값만 반환(원본 미노출). 공개는 hidden/blinded 제외, include_hidden 은 is_admin() 전용.''", "revoke all on function public.get_mentor_review_stats(uuid, boolean) from public", "grant execute on function public.get_mentor_review_stats(uuid, boolean) to anon, authenticated, service_role", "-- >>> NATIVE_BASELINE_PART 0143 | supabase/sql/136_p1_8a_question_room_atomic_rpc.sql | 136_p1_8a_question_room_atomic_rpc.sql <<<\n-- 136_p1_8a_question_room_atomic_rpc.sql\n-- P1-8A: 구독 질문방 원자 RPC + free_question_usage.thread_id 수렴 (정본 수렴 파일)\n--\n-- 계보 메모\n--   * 설계 정본: docs/audit/p1-8a_question_room_rpc_plan.md (원래 127_question_thread_rpcs.sql 로 예약).\n--   * 본 정의는 PR #43(브랜치 claude/v16-web-db-autonomous-*)에서 staging 에 선적용됐다.\n--     PR #43 의 파일 번호 130 은 이 브랜치의 130_shortform_scrap_reaction 과 충돌하므로,\n--     정본 브랜치(PR #42)에서 다음 빈 고유 번호 136 으로 수렴한다. (131=P1-13 예약, 127=설계 예약 gap.)\n--   * 선행 의존: 132_notification_outbox_foundation.sql (P1-11F: notification_outbox + record_domain_notification).\n--     clean-install 시 132 가 반드시 136 보다 먼저 적용돼야 한다.\n--   * 멱등(create or replace / add ... if not exists). staging 에 이미 적용된 부분은 no-op,\n--     UNIQUE(thread_id)/UNIQUE(storage_path)/일반 create RPC/enhanced register 는 델타로 수렴.\n--\n-- 목적\n--   * 무료 질문권 소비(free_question_usage)와 스레드 생성의 비원자·오짝 제거.\n--   * free_question_usage.thread_id 수렴(FK ON DELETE SET NULL + UNIQUE) → 정확 1:1 링크.\n--   * 생성 RPC가 무료/활성구독 자격을 서버에서 분기.\n--   * 멘토 첫 메시지/첨부만 answered 전이 + record_domain_notification exactly-once.\n--   * 계정상태·차단·멘토승인·자격 서버 재검사.\n--\n-- 전환 정책 (P1-8B 는 별도 · WAITING_EXTERNAL_APP)\n--   * 순수 추가형. 기존 direct-write 정책·GRANT(qt_write_via_room/qm_insert/fqu_insert_own/\n--     question_attachments_insert_via_room/049 storage) 유지. 앱 신버전 전 제거·revoke·open→pending 이관 금지.\n--   * 무료사용 FK CASCADE 금지 → thread_id FK ON DELETE SET NULL.\n--\n-- 잠금값: 무료 총 7 / 멘토당 3 / 가입 후 7일. 주간(구독): limited4/standard9/premium999(get_weekly_question_usage).\n--         status CHECK pending/answered/confirmed/open/closed/archived. mastery unknown/wrong/review/mastered.\n\nbegin", "set local lock_timeout = ''5s''", "-- ── 1) free_question_usage.thread_id 수렴 (추가형 + UNIQUE) ──\nalter table public.free_question_usage add column if not exists thread_id uuid", "do $$\nbegin\n  if not exists (select 1 from pg_constraint\n    where conname=''free_question_usage_thread_id_fkey'' and conrelid=''public.free_question_usage''::regclass) then\n    alter table public.free_question_usage\n      add constraint free_question_usage_thread_id_fkey\n      foreign key (thread_id) references public.question_threads(id) on delete set null;\n  end if;\n  -- UNIQUE(thread_id): NULL 다중 허용(레거시), 신규 링크는 스레드당 1건.\n  if not exists (select 1 from pg_constraint\n    where conname=''free_question_usage_thread_id_key'' and conrelid=''public.free_question_usage''::regclass) then\n    alter table public.free_question_usage\n      add constraint free_question_usage_thread_id_key unique (thread_id);\n  end if;\nend$$", "create index if not exists free_question_usage_thread_id_idx\n  on public.free_question_usage (thread_id)", "-- ── 1b) question_attachments.storage_path UNIQUE (0행 → 중복 대사 불필요) ──\ndo $$\nbegin\n  if not exists (select 1 from pg_constraint\n    where conname=''question_attachments_storage_path_key'' and conrelid=''public.question_attachments''::regclass) then\n    alter table public.question_attachments\n      add constraint question_attachments_storage_path_key unique (storage_path);\n  end if;\nend$$", "-- ── 2) 질문 스레드 원자 생성 RPC (일반: 무료/활성구독 서버 분기, 학생 전용) ──\ncreate or replace function public.qna_create_question_thread(\n  p_room_id uuid,\n  p_title text,\n  p_subject text default null,\n  p_topic text default null,\n  p_first_message_body text default null\n) returns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_uid uuid := auth.uid();\n  v_student uuid;\n  v_mentor uuid;\n  v_status text;\n  v_suspended_until timestamptz;\n  v_created_at timestamptz;\n  v_total int;\n  v_per int;\n  v_subject text;\n  v_thread_id uuid;\n  v_message_id uuid;\n  v_has_active_sub boolean;\n  v_usage json;\n  v_path text;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_title is null or btrim(p_title) = '''' then raise exception ''TITLE_REQUIRED''; end if;\n\n  select student_id, mentor_id into v_student, v_mentor\n  from public.mentor_student_rooms where id = p_room_id;\n  if not found then raise exception ''ROOM_NOT_FOUND''; end if;\n\n  if v_uid <> v_student then\n    if v_uid = v_mentor then raise exception ''MENTOR_CANNOT_CREATE_THREAD'';\n    else raise exception ''NOT_ROOM_PARTY''; end if;\n  end if;\n\n  -- 학생 단위 직렬화(무료 총/멘토별 한도 + 주간 한도 경쟁 안전).\n  perform 1 from public.users where id = v_student for update;\n\n  select status, suspended_until, created_at\n    into v_status, v_suspended_until, v_created_at\n  from public.users where id = v_student;\n  if lower(coalesce(v_status,''active'')) = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if lower(coalesce(v_status,''active'')) = ''suspended''\n     and (v_suspended_until is null or v_suspended_until > now()) then\n    raise exception ''ACCOUNT_SUSPENDED'';\n  end if;\n\n  if exists (select 1 from public.user_blocks\n    where (blocker_id=v_student and blocked_id=v_mentor) or (blocker_id=v_mentor and blocked_id=v_student)) then\n    raise exception ''BLOCKED'';\n  end if;\n\n  if not public.individual_question_user_is_approved_mentor(v_mentor) then\n    raise exception ''MENTOR_NOT_APPROVED'';\n  end if;\n\n  -- 자격 분기: 활성 구독 vs 무료.\n  v_has_active_sub := exists (\n    select 1 from public.subscriptions\n    where student_id = v_student and mentor_id = v_mentor and lower(coalesce(status,'''')) = ''active''\n  );\n\n  if v_has_active_sub then\n    v_usage := public.get_weekly_question_usage(v_student, v_mentor);\n    if not coalesce((v_usage->>''can_ask'')::boolean, false) then\n      raise exception ''WEEKLY_LIMIT_EXHAUSTED'';\n    end if;\n    v_path := ''subscription'';\n  else\n    if v_created_at is not null and now() >= v_created_at + interval ''7 days'' then\n      raise exception ''FREE_QUOTA_EXPIRED'';\n    end if;\n    select count(*) into v_total from public.free_question_usage where student_id = v_student;\n    if v_total >= 7 then raise exception ''FREE_QUOTA_TOTAL_EXHAUSTED''; end if;\n    select count(*) into v_per from public.free_question_usage\n      where student_id = v_student and mentor_id = v_mentor;\n    if v_per >= 3 then raise exception ''FREE_QUOTA_MENTOR_EXHAUSTED''; end if;\n    v_path := ''free'';\n  end if;\n\n  v_subject := nullif(btrim(coalesce(p_subject,'''')), '''');\n  if v_subject is not null and not exists (select 1 from public.subjects where code = v_subject) then\n    v_subject := null;\n  end if;\n\n  insert into public.question_threads (mentor_student_room_id, title, status, subject, topic)\n  values (p_room_id, btrim(p_title), ''pending'', v_subject, nullif(btrim(coalesce(p_topic,'''')), ''''))\n  returning id into v_thread_id;\n\n  if p_first_message_body is not null and btrim(p_first_message_body) <> '''' then\n    insert into public.question_messages (thread_id, author_id, body)\n    values (v_thread_id, v_student, btrim(p_first_message_body))\n    returning id into v_message_id;\n  end if;\n\n  if v_path = ''free'' then\n    insert into public.free_question_usage (student_id, mentor_id, thread_id)\n    values (v_student, v_mentor, v_thread_id);\n  end if;\n\n  return jsonb_build_object(\n    ''ok'', true, ''thread_id'', v_thread_id, ''message_id'', v_message_id,\n    ''path'', v_path, ''used_free_quota'', (v_path = ''free'')\n  );\nend;\n$$", "-- ── 2b) 무료 전용 진입점(레거시 호환): 일반 RPC 로 위임(추가형 — drop 금지). ──\ncreate or replace function public.qna_create_free_question_thread(\n  p_room_id uuid,\n  p_title text,\n  p_subject text default null,\n  p_topic text default null,\n  p_first_message_body text default null\n) returns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\nbegin\n  return public.qna_create_question_thread(p_room_id, p_title, p_subject, p_topic, p_first_message_body);\nend;\n$$", "-- ── 3) 메시지 append RPC — 멘토 첫 답변만 answered 전이 + exactly-once 알림 ──\ncreate or replace function public.qna_append_message(\n  p_thread_id uuid,\n  p_body text\n) returns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_uid uuid := auth.uid();\n  v_room uuid;\n  v_student uuid;\n  v_mentor uuid;\n  v_status text;\n  v_thread_status text;\n  v_first_answered timestamptz;\n  v_message_id uuid;\n  v_is_mentor boolean;\n  v_transitioned boolean := false;\n  v_mentor_name text;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_body is null or btrim(p_body) = '''' then raise exception ''BODY_REQUIRED''; end if;\n\n  select t.mentor_student_room_id, t.status, t.first_answered_at\n    into v_room, v_thread_status, v_first_answered\n  from public.question_threads t where t.id = p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n\n  select student_id, mentor_id into v_student, v_mentor\n  from public.mentor_student_rooms where id = v_room;\n\n  if v_uid = v_mentor then v_is_mentor := true;\n  elsif v_uid = v_student then v_is_mentor := false;\n  else raise exception ''NOT_ROOM_PARTY''; end if;\n\n  select status into v_status from public.users where id = v_uid;\n  if lower(coalesce(v_status,''active'')) = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n\n  if v_thread_status in (''confirmed'',''closed'',''archived'') then raise exception ''THREAD_LOCKED''; end if;\n\n  if v_is_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then\n    raise exception ''MENTOR_NOT_APPROVED'';\n  end if;\n\n  insert into public.question_messages (thread_id, author_id, body)\n  values (p_thread_id, v_uid, btrim(p_body)) returning id into v_message_id;\n\n  if v_is_mentor and v_first_answered is null then\n    update public.question_threads\n      set status=''answered'', first_answered_at=now(), updated_at=now()\n    where id = p_thread_id and first_answered_at is null;\n    v_transitioned := true;\n    select coalesce(nullif(btrim(full_name),''''), nullif(btrim(nickname),''''), ''멘토'')\n      into v_mentor_name from public.users where id = v_mentor;\n    perform public.record_domain_notification(\n      v_student,\n      ''question_answered:'' || p_thread_id::text,\n      ''question_answered:'' || p_thread_id::text,\n      ''question_answered'', ''새 답변이 도착했어요'',\n      coalesce(v_mentor_name,''멘토'') || ''님이 답변을 남겼습니다.'',\n      ''/question-room/'' || v_room::text || ''?thread='' || p_thread_id::text,\n      jsonb_build_object(''room_id'', v_room, ''thread_id'', p_thread_id),\n      jsonb_build_object(''room_id'', v_room, ''thread_id'', p_thread_id)\n    );\n  end if;\n\n  return jsonb_build_object(''ok'', true, ''message_id'', v_message_id, ''answered_transition'', v_transitioned);\nend;\n$$", "-- ── 4) 학생 확인 RPC (answered→confirmed) ──\ncreate or replace function public.qna_confirm_thread(p_thread_id uuid)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_status text;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  select t.mentor_student_room_id, t.status into v_room, v_status\n  from public.question_threads t where t.id = p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n  select student_id into v_student from public.mentor_student_rooms where id = v_room;\n  if v_uid <> v_student then raise exception ''STUDENT_ONLY''; end if;\n  if v_status = ''confirmed'' then return jsonb_build_object(''ok'', true, ''thread_id'', p_thread_id); end if;\n  if v_status <> ''answered'' then raise exception ''NOT_ANSWERED''; end if;\n  update public.question_threads\n    set status=''confirmed'', confirmed_at=coalesce(confirmed_at, now()), updated_at=now()\n  where id = p_thread_id;\n  return jsonb_build_object(''ok'', true, ''thread_id'', p_thread_id);\nend;\n$$", "-- ── 5) 오답 표시 RPC (학생) ──\ncreate or replace function public.qna_flag_wrong_answer(p_thread_id uuid, p_is_wrong boolean default true)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_uid uuid := auth.uid(); v_room uuid; v_student uuid;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  select t.mentor_student_room_id into v_room\n  from public.question_threads t where t.id = p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n  select student_id into v_student from public.mentor_student_rooms where id = v_room;\n  if v_uid <> v_student then raise exception ''STUDENT_ONLY''; end if;\n  update public.question_threads\n    set is_wrong_answer=coalesce(p_is_wrong,true),\n        mastery_status=case when coalesce(p_is_wrong,true) then ''wrong'' else ''unknown'' end,\n        updated_at=now()\n  where id = p_thread_id;\n  return jsonb_build_object(''ok'', true, ''thread_id'', p_thread_id, ''is_wrong_answer'', coalesce(p_is_wrong,true));\nend;\n$$", "-- ── 6) 첨부 등록 RPC — 경로 thread-id 검증 + 멘토 첫 첨부 answered 전이 + exactly-once 알림 ──\ncreate or replace function public.qna_register_attachment(\n  p_thread_id uuid,\n  p_storage_path text,\n  p_file_name text default null,\n  p_mime_type text default null,\n  p_message_id uuid default null\n) returns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_uid uuid := auth.uid();\n  v_room uuid;\n  v_student uuid;\n  v_mentor uuid;\n  v_thread_status text;\n  v_first_answered timestamptz;\n  v_att_id uuid;\n  v_is_mentor boolean;\n  v_transitioned boolean := false;\n  v_mentor_name text;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_storage_path is null or btrim(p_storage_path) = '''' then raise exception ''STORAGE_PATH_REQUIRED''; end if;\n\n  select t.mentor_student_room_id, t.status, t.first_answered_at\n    into v_room, v_thread_status, v_first_answered\n  from public.question_threads t where t.id = p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n\n  select student_id, mentor_id into v_student, v_mentor\n  from public.mentor_student_rooms where id = v_room;\n  if v_uid = v_mentor then v_is_mentor := true;\n  elsif v_uid = v_student then v_is_mentor := false;\n  else raise exception ''NOT_ROOM_PARTY''; end if;\n\n  if v_thread_status in (''confirmed'',''closed'',''archived'') then raise exception ''THREAD_LOCKED''; end if;\n\n  -- 경로 thread-id 검증: {room}/{thread}/... 프리픽스 (buildObjectPath 계약).\n  if p_storage_path not like (v_room::text || ''/'' || p_thread_id::text || ''/%'') then\n    raise exception ''STORAGE_PATH_MISMATCH'';\n  end if;\n\n  if p_message_id is not null and not exists (\n    select 1 from public.question_messages m where m.id = p_message_id and m.thread_id = p_thread_id\n  ) then raise exception ''MESSAGE_THREAD_MISMATCH''; end if;\n\n  insert into public.question_attachments (thread_id, message_id, author_id, storage_path, file_name, mime_type)\n  values (p_thread_id, p_message_id, v_uid, btrim(p_storage_path), p_file_name, p_mime_type)\n  returning id into v_att_id;\n\n  if v_is_mentor and v_first_answered is null then\n    update public.question_threads\n      set status=''answered'', first_answered_at=now(), updated_at=now()\n    where id = p_thread_id and first_answered_at is null;\n    v_transitioned := true;\n    select coalesce(nullif(btrim(full_name),''''), nullif(btrim(nickname),''''), ''멘토'')\n      into v_mentor_name from public.users where id = v_mentor;\n    perform public.record_domain_notification(\n      v_student,\n      ''question_answered:'' || p_thread_id::text,\n      ''question_answered:'' || p_thread_id::text,\n      ''question_answered'', ''새 답변이 도착했어요'',\n      coalesce(v_mentor_name,''멘토'') || ''님이 파일을 보냈습니다.'',\n      ''/question-room/'' || v_room::text || ''?thread='' || p_thread_id::text,\n      jsonb_build_object(''room_id'', v_room, ''thread_id'', p_thread_id),\n      jsonb_build_object(''room_id'', v_room, ''thread_id'', p_thread_id)\n    );\n  end if;\n\n  return jsonb_build_object(''ok'', true, ''attachment_id'', v_att_id, ''answered_transition'', v_transitioned);\nend;\n$$", "-- ── 7) 권한: authenticated + service_role. public·anon revoke. ──\nrevoke all on function public.qna_create_question_thread(uuid,text,text,text,text) from public, anon", "revoke all on function public.qna_create_free_question_thread(uuid,text,text,text,text) from public, anon", "revoke all on function public.qna_append_message(uuid,text) from public, anon", "revoke all on function public.qna_confirm_thread(uuid) from public, anon", "revoke all on function public.qna_flag_wrong_answer(uuid,boolean) from public, anon", "revoke all on function public.qna_register_attachment(uuid,text,text,text,uuid) from public, anon", "grant execute on function public.qna_create_question_thread(uuid,text,text,text,text) to authenticated, service_role", "grant execute on function public.qna_create_free_question_thread(uuid,text,text,text,text) to authenticated, service_role", "grant execute on function public.qna_append_message(uuid,text) to authenticated, service_role", "grant execute on function public.qna_confirm_thread(uuid) to authenticated, service_role", "grant execute on function public.qna_flag_wrong_answer(uuid,boolean) to authenticated, service_role", "grant execute on function public.qna_register_attachment(uuid,text,text,text,uuid) to authenticated, service_role", "commit", "-- §V (rollback-only fixture): 무료/구독 경로 생성, thread_id UNIQUE, storage_path UNIQUE,\n--   append/register 멘토 첫답 answered+exactly-once, confirm(answered 선행), wrong, 비당사자·한도 거부.\n-- pending-refund lock 경계(결정 C)는 P1-13 billing-event 정본 확정 시 helper 로 교체 = WAITING_P1_13.\n\n-- >>> NATIVE_BASELINE_PART 0144 | supabase/sql/137_p3_8_realtime_messages_threads.sql | 137_p3_8_realtime_messages_threads.sql <<<\n-- 137_p3_8_realtime_messages_threads.sql\n-- P3-8: 질문방 실시간 — supabase_realtime publication 에 question_messages / question_threads 추가.\n--\n-- 계보: PR #43 에서 staging 선적용(파일 131). 131 은 정본 브랜치에서 P1-13 예약 번호라 137 로 수렴.\n-- 배경: 117 은 question_attachments 만 추가 → 메시지 신규/스레드 상태전이 실시간 미반영(재조회 폴백).\n-- 안전: 두 테이블 모두 SELECT RLS(qm_select/qt_select_via_room) → 브로드캐스트도 당사자만 수신.\n--       replica identity 는 attachments 와 동일 default(PK). 멱등.\n-- 선행: 136(P1-8A) 이후. 038/117(실시간 계보).\n\ndo $$\nbegin\n  if not exists (select 1 from pg_publication_tables where pubname=''supabase_realtime'' and schemaname=''public'' and tablename=''question_messages'') then\n    execute ''alter publication supabase_realtime add table public.question_messages'';\n  end if;\n  if not exists (select 1 from pg_publication_tables where pubname=''supabase_realtime'' and schemaname=''public'' and tablename=''question_threads'') then\n    execute ''alter publication supabase_realtime add table public.question_threads'';\n  end if;\nend$$", "-- §V: select tablename from pg_publication_tables where pubname=''supabase_realtime'' and schemaname=''public''\n--       and tablename in (''question_messages'',''question_threads'',''question_attachments''); → 3행.\n\n-- >>> NATIVE_BASELINE_PART 0145 | supabase/sql/138_p3_9_student_nickname_rpc_anon_revoke.sql | 138_p3_9_student_nickname_rpc_anon_revoke.sql <<<\n-- 138_p3_9_student_nickname_rpc_anon_revoke.sql\n-- P3-9(부분): 학생 PII 반환 RPC 의 anon/public 실행권 회수(심층방어).\n--\n-- 계보: PR #43 에서 staging 선적용(파일 132). 132 는 정본 브랜치에서 notification_outbox_foundation 과\n--       충돌하므로 138 로 수렴.\n-- get_mentor_student_nicknames(uuid[]) 는 SECURITY DEFINER 로 users.nickname/full_name(PII)을 반환한다.\n-- 본문은 이미 (a) auth.uid() not null (b) 호출자가 custom_request_orders 의 해당 학생 멘토일 때만 반환하도록\n-- 제한하지만, Supabase 기본 권한으로 anon 에도 EXECUTE 가 부여돼 있었다. anon 은 결과가 비지만 PII 정의함수를\n-- anon 이 호출 가능한 상태 자체를 제거한다.\n--\n-- P3-9 나머지(활성구독/질문방 당사자 기준으로 노출 인가 재정의)는 현행 custom_request_orders 기준과\n-- 다른 인가 집합으로의 기능 변경이라 제품 결정 필요 = DEFERRED_PRODUCT_DECISION.\n\nrevoke all on function public.get_mentor_student_nicknames(uuid[]) from anon, public", "-- §V: select grantee from information_schema.routine_privileges\n--     where specific_schema=''public'' and routine_name=''get_mentor_student_nicknames''; → {authenticated, service_role}(및 owner).\n\n-- >>> NATIVE_BASELINE_PART 0146 | supabase/sql/139_p1_8a_attachment_storage_contract.sql | 139_p1_8a_attachment_storage_contract.sql <<<\n-- 139_p1_8a_attachment_storage_contract.sql\n-- P1-8A 첨부 Storage 계약 완결 — 136 을 수정하지 않는 수렴 보정.\n--\n-- 배경: 049 는 question-room-attachments INSERT(party via path)·SELECT(party/admin) 정책만 두고\n--       DELETE 정책이 없어 보상 삭제가 조용히 실패했다. 등록 RPC 도 storage 객체 존재·owner 를 대조하지 않았다.\n-- 안전: 추가형(DELETE 정책 신설) + INSERT 정책 조건 강화(당사자 + 경로 thread 소속 + 쓰기가능 상태).\n--       기존 direct-write 테이블 정책·049 SELECT/INSERT 존재 자체는 유지(앱 전환 전 최종 제거 금지).\n-- 선행: 136(RPC), 049(qra storage), 132(record_domain_notification).\n\nbegin", "set local lock_timeout=''5s''", "-- 경로의 thread 세그먼트가 room 에 속하고 쓰기 가능한 상태인지 검사(경로 = {room}/{thread}/{uuid}-name).\ncreate or replace function public.qra_thread_writable_for_path(p_name text)\nreturns boolean language sql stable security definer set search_path to ''public'' as $$\n  select exists (\n    select 1\n    from public.question_threads t\n    where t.id = nullif(split_part(p_name, ''/'', 2), '''')::uuid\n      and t.mentor_student_room_id = public.qra_room_uuid_from_path(p_name)\n      and coalesce(t.status, '''') in (''pending'',''open'',''answered'')\n  );\n$$", "revoke all on function public.qra_thread_writable_for_path(text) from public, anon", "grant execute on function public.qra_thread_writable_for_path(text) to authenticated, service_role", "-- 업로드 INSERT 정책 강화: 당사자 + 경로 thread 소속 + 쓰기가능 상태.\n--  (자격(무료/구독)은 등록 RPC 가 authoritative 하게 재검사하고, 실패 시 미등록 객체를 보상 삭제한다.)\ndrop policy if exists qra_storage_insert_party on storage.objects", "create policy qra_storage_insert_party on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = ''question-room-attachments''\n    and public.user_is_room_party_for_qra_path(name)\n    and public.qra_thread_writable_for_path(name)\n  )", "-- 보상 DELETE 정책: 본인 소유(owner_id=auth.uid()) + 미등록 객체만. 활성 스레드 조건 없음.\n--  등록된 question_attachments.storage_path 객체는 삭제 불가. 타인 객체 삭제 거부.\ndrop policy if exists qra_storage_delete_unregistered_owner on storage.objects", "create policy qra_storage_delete_unregistered_owner on storage.objects\n  for delete to authenticated\n  using (\n    bucket_id = ''question-room-attachments''\n    and owner_id = (select auth.uid())::text\n    and not exists (\n      select 1 from public.question_attachments a where a.storage_path = storage.objects.name\n    )\n  )", "-- 등록 RPC 강화: storage 객체 존재 + 정확 bucket + owner_id=auth.uid() 대조 추가.\ncreate or replace function public.qna_register_attachment(\n  p_thread_id uuid, p_storage_path text, p_file_name text default null, p_mime_type text default null, p_message_id uuid default null\n) returns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_thread_status text;\n  v_first_answered timestamptz; v_att_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_mentor_name text;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_storage_path is null or btrim(p_storage_path)='''' then raise exception ''STORAGE_PATH_REQUIRED''; end if;\n  select t.mentor_student_room_id, t.status, t.first_answered_at into v_room, v_thread_status, v_first_answered\n    from public.question_threads t where t.id=p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;\n  if v_uid=v_mentor then v_is_mentor:=true; elsif v_uid=v_student then v_is_mentor:=false; else raise exception ''NOT_ROOM_PARTY''; end if;\n  if v_thread_status in (''confirmed'',''closed'',''archived'') then raise exception ''THREAD_LOCKED''; end if;\n  -- 경로 thread-id 일치({room}/{thread}/...).\n  if p_storage_path not like (v_room::text || ''/'' || p_thread_id::text || ''/%'') then raise exception ''STORAGE_PATH_MISMATCH''; end if;\n  -- storage 객체 존재 + 정확 bucket + owner_id=auth.uid().\n  if not exists (\n    select 1 from storage.objects o\n    where o.bucket_id=''question-room-attachments'' and o.name = btrim(p_storage_path)\n      and o.owner_id = v_uid::text\n  ) then raise exception ''STORAGE_OBJECT_NOT_OWNED''; end if;\n  if p_message_id is not null and not exists (select 1 from public.question_messages m where m.id=p_message_id and m.thread_id=p_thread_id) then raise exception ''MESSAGE_THREAD_MISMATCH''; end if;\n\n  insert into public.question_attachments (thread_id, message_id, author_id, storage_path, file_name, mime_type)\n  values (p_thread_id, p_message_id, v_uid, btrim(p_storage_path), p_file_name, p_mime_type) returning id into v_att_id;\n\n  if v_is_mentor and v_first_answered is null then\n    update public.question_threads set status=''answered'', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;\n    v_transitioned := true;\n    select coalesce(nullif(btrim(full_name),''''), nullif(btrim(nickname),''''), ''멘토'') into v_mentor_name from public.users where id=v_mentor;\n    perform public.record_domain_notification(v_student, ''question_answered:''||p_thread_id::text, ''question_answered:''||p_thread_id::text,\n      ''question_answered'',''새 답변이 도착했어요'', coalesce(v_mentor_name,''멘토'')||''님이 파일을 보냈습니다.'',\n      ''/question-room/''||v_room::text||''?thread=''||p_thread_id::text,\n      jsonb_build_object(''room_id'',v_room,''thread_id'',p_thread_id), jsonb_build_object(''room_id'',v_room,''thread_id'',p_thread_id));\n  end if;\n  return jsonb_build_object(''ok'',true,''attachment_id'',v_att_id,''answered_transition'',v_transitioned);\nend; $$", "revoke all on function public.qna_register_attachment(uuid,text,text,text,uuid) from public, anon", "grant execute on function public.qna_register_attachment(uuid,text,text,text,uuid) to authenticated, service_role", "commit", "-- §V: (a) INSERT 정책 = party+thread+writable, (b) DELETE 정책 owner+미등록만,\n--     (c) 등록 RPC 가 미소유/미존재 객체 STORAGE_OBJECT_NOT_OWNED 거부, (d) 등록된 객체 DELETE 거부.\n\n-- >>> NATIVE_BASELINE_PART 0147 | supabase/sql/140_p3_9_student_nickname_subscription_room_scope.sql | 140_p3_9_student_nickname_subscription_room_scope.sql <<<\n-- 140_p3_9_student_nickname_subscription_room_scope.sql\n-- P3-9 완결 — `get_mentor_student_nicknames` 노출 인가를 v16(1) 정책으로 재정의.\n--\n-- 정책: 호출 멘토는 다음 관계의 학생 이름만 조회할 수 있다.\n--   (a) 호출 멘토와 **활성 구독** 관계, 또는\n--   (b) 호출 멘토와 **실제 질문방(mentor_student_rooms) 당사자** 관계.\n-- custom_request_orders 만 존재하는 관계는 (a)/(b) 를 충족하지 않으면 반환 근거가 아니다.\n--\n-- 138(anon/public revoke)을 수정하지 않고 다음 고유 번호로 본문을 재정의한다.\n-- - 호출 멘토는 auth.uid() 에서 서버가 도출(클라이언트 mentor ID 신뢰 금지).\n-- - 타 멘토의 학생 열거 금지(관계는 mentor_id = auth.uid() 로만 성립).\n-- - anon/public 실행 금지 유지, SECURITY DEFINER + 고정 search_path, service_role 허용.\n\ncreate or replace function public.get_mentor_student_nicknames(p_student_ids uuid[])\nreturns table(id uuid, nickname text, full_name text)\nlanguage sql\nstable\nsecurity definer\nset search_path to ''public''\nas $$\n  select u.id, u.nickname, u.full_name\n  from public.users u\n  where p_student_ids is not null\n    and array_length(p_student_ids, 1) is not null\n    and u.id = any (p_student_ids)\n    and (select auth.uid()) is not null\n    and (\n      exists (\n        select 1 from public.subscriptions s\n        where s.mentor_id = (select auth.uid())\n          and s.student_id = u.id\n          and lower(coalesce(s.status, '''')) = ''active''\n      )\n      or exists (\n        select 1 from public.mentor_student_rooms r\n        where r.mentor_id = (select auth.uid())\n          and r.student_id = u.id\n      )\n    );\n$$", "revoke all on function public.get_mentor_student_nicknames(uuid[]) from public, anon", "grant execute on function public.get_mentor_student_nicknames(uuid[]) to authenticated, service_role", "-- §V(rollback-only): 활성구독 학생→반환 · 질문방 학생→반환 · custom_order만/무관계 학생→미반환 ·\n--   타 멘토가 호출→미반환. grantee={authenticated,service_role}.\n\n-- >>> NATIVE_BASELINE_PART 0148 | supabase/sql/141_p1_8a_direct_write_guards.sql | 141_p1_8a_direct_write_guards.sql <<<\n-- 141_p1_8a_direct_write_guards.sql\n-- P1-8A 최종 보안 마감 — 앱 호환 direct-write 우회 방어(서버 트리거) + 업로드 정책 계정/멘토 강제.\n--\n-- 배경: 앱 전환 전 direct-write 정책(qt_write_via_room/qt_update_via_room/qm_insert/\n--       question_attachments_insert_via_room/fqu_insert_own)은 유지한다. 그러나 직접 호출로\n--       워크플로 불변식을 우회할 수 없도록 DB 트리거로 강제한다.\n-- 판별: 신규 qna_* RPC 는 SECURITY DEFINER(owner=postgres)라 실행 중 current_user=''postgres''.\n--       PostgREST 직접 write 는 current_user=''authenticated''/''anon''. → 직접 write 만 가드한다.\n-- 안전: 순수 추가형(트리거·정책 강화). 139 미수정. 무료 한도는 기존 check_free_question_usage_limits\n--       트리거가 유지, fqu RLS 는 student_id=auth.uid() 로 타인 조작 차단.\n-- 선행: 049·136·139.\n\nbegin", "set local lock_timeout=''5s''", "-- 직접(비신뢰) writer 판별: authenticated/anon 세션의 직접 테이블 write.\ncreate or replace function public.qna_is_direct_untrusted_writer()\nreturns boolean language sql stable as $$\n  select current_user in (''authenticated'',''anon'');\n$$", "-- ── Part 1: 업로드 INSERT 정책에 계정 활성 + (멘토면)승인 강제 추가 ──\ncreate or replace function public.qra_uploader_allowed_for_path(p_name text)\nreturns boolean language plpgsql stable security definer set search_path to ''public'' as $$\ndeclare v_room uuid; v_student uuid; v_mentor uuid; v_uid uuid := auth.uid(); v_status text;\nbegin\n  if v_uid is null then return false; end if;\n  v_room := public.qra_room_uuid_from_path(p_name);\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = v_room;\n  if v_student is null then return false; end if;\n  -- 계정 활성(업로더).\n  select status into v_status from public.users where id = v_uid;\n  if lower(coalesce(v_status,''active'')) = ''banned'' then return false; end if;\n  if lower(coalesce(v_status,''active'')) = ''suspended'' then\n    if exists (select 1 from public.users where id=v_uid and (suspended_until is null or suspended_until > now())) then return false; end if;\n  end if;\n  -- 멘토 업로더면 승인 필수.\n  if v_uid = v_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then return false; end if;\n  return true;\nend;\n$$", "revoke all on function public.qra_uploader_allowed_for_path(text) from public, anon", "grant execute on function public.qra_uploader_allowed_for_path(text) to authenticated, service_role", "drop policy if exists qra_storage_insert_party on storage.objects", "create policy qra_storage_insert_party on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = ''question-room-attachments''\n    and public.user_is_room_party_for_qra_path(name)\n    and public.qra_thread_writable_for_path(name)\n    and public.qra_uploader_allowed_for_path(name)\n  )", "-- ── Part 2: question_threads 직접 write 워크플로 가드 ──\ncreate or replace function public.qt_direct_write_guard()\nreturns trigger language plpgsql security invoker set search_path to ''public'' as $$\ndeclare v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid;\nbegin\n  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;\n  select student_id, mentor_id into v_student, v_mentor\n    from public.mentor_student_rooms where id = NEW.mentor_student_room_id;\n  if TG_OP = ''INSERT'' then\n    if coalesce(NEW.status,''pending'') not in (''pending'',''open'') then raise exception ''DIRECT_INSERT_STATUS_FORBIDDEN''; end if;\n    if NEW.first_answered_at is not null or NEW.confirmed_at is not null then raise exception ''DIRECT_INSERT_WORKFLOW_FIELDS_FORBIDDEN''; end if;\n    return NEW;\n  end if;\n  -- UPDATE: role-correct workflow transitions only.\n  if NEW.status is distinct from OLD.status then\n    if NEW.status = ''answered'' and v_uid is distinct from v_mentor then raise exception ''DIRECT_ANSWERED_MENTOR_ONLY''; end if;\n    if NEW.status = ''confirmed'' and v_uid is distinct from v_student then raise exception ''DIRECT_CONFIRM_STUDENT_ONLY''; end if;\n  end if;\n  if NEW.first_answered_at is distinct from OLD.first_answered_at and v_uid is distinct from v_mentor then\n    raise exception ''DIRECT_FIRST_ANSWERED_MENTOR_ONLY'';\n  end if;\n  if (NEW.is_wrong_answer is distinct from OLD.is_wrong_answer or NEW.mastery_status is distinct from OLD.mastery_status)\n     and v_uid is distinct from v_student then\n    raise exception ''DIRECT_WRONG_FLAG_STUDENT_ONLY'';\n  end if;\n  return NEW;\nend;\n$$", "drop trigger if exists trg_qt_direct_write_guard on public.question_threads", "create trigger trg_qt_direct_write_guard before insert or update on public.question_threads\n  for each row execute function public.qt_direct_write_guard()", "-- ── Part 2: question_messages 직접 write — 종료 스레드 거부 ──\ncreate or replace function public.qm_direct_write_guard()\nreturns trigger language plpgsql security invoker set search_path to ''public'' as $$\ndeclare v_status text;\nbegin\n  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;\n  select status into v_status from public.question_threads where id = NEW.thread_id;\n  if v_status in (''confirmed'',''closed'',''archived'') then raise exception ''DIRECT_MSG_THREAD_LOCKED''; end if;\n  return NEW;\nend;\n$$", "drop trigger if exists trg_qm_direct_write_guard on public.question_messages", "create trigger trg_qm_direct_write_guard before insert on public.question_messages\n  for each row execute function public.qm_direct_write_guard()", "-- ── Part 2: question_attachments 직접 write — 종료 스레드·경로/owner 위조 거부 ──\ncreate or replace function public.qa_direct_write_guard()\nreturns trigger language plpgsql security invoker set search_path to ''public'' as $$\ndeclare v_room uuid; v_status text;\nbegin\n  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;\n  select mentor_student_room_id, status into v_room, v_status from public.question_threads where id = NEW.thread_id;\n  if v_status in (''confirmed'',''closed'',''archived'') then raise exception ''DIRECT_ATT_THREAD_LOCKED''; end if;\n  if NEW.storage_path is null or NEW.storage_path not like (v_room::text || ''/'' || NEW.thread_id::text || ''/%'') then\n    raise exception ''DIRECT_ATT_PATH_FORGERY'';\n  end if;\n  if not exists (\n    select 1 from storage.objects o\n    where o.bucket_id=''question-room-attachments'' and o.name = NEW.storage_path and o.owner_id = auth.uid()::text\n  ) then raise exception ''DIRECT_ATT_OBJECT_NOT_OWNED''; end if;\n  return NEW;\nend;\n$$", "drop trigger if exists trg_qa_direct_write_guard on public.question_attachments", "create trigger trg_qa_direct_write_guard before insert on public.question_attachments\n  for each row execute function public.qa_direct_write_guard()", "commit", "-- §V(rollback-only): RPC(postgres) 경로 무영향 · 직접 authenticated 의 타역할 status/first_answered/\n--   wrong 변경 거부 · 종료 스레드 메시지/첨부 거부 · 경로/owner 위조 거부 · 업로드 정책 정지계정/미승인멘토 거부.\n\n-- >>> NATIVE_BASELINE_PART 0149 | supabase/sql/142_p1_8a_pending_refund_lock.sql | 142_p1_8a_pending_refund_lock.sql <<<\n-- 142_p1_8a_pending_refund_lock.sql\n-- P1-8A 즉시 연동 — 활성 구독을 질문 자격으로 인정하기 전 pending refund 잠금 검사.\n--\n-- 계약(결정 C): 활성 구독 기반 자격을 인정하기 전에\n--   1) 해당 subscription 행 FOR UPDATE 잠금\n--   2) 잠근 구독의 두 canonical 구독 환불 유형(subscription_prorated / subscription_mentor_suspended)\n--   3) live pending refund 존재를 별도 statement 로 검사\n--   4) pending 이면 새 질문·후속 메시지·첨부(학생 측)를 거부.\n-- 클라이언트 사전 검사에 의존하지 않는다. 무료 스레드(활성구독 없음)는 미적용.\n-- P1-13 billing-event 정본 확정 시 last_billing_event_id 기준 helper 로 교체 가능한 경계.\n--\n-- 136/139 를 수정하지 않고 create/append/register RPC 를 본문 포함 재정의(create or replace). 순수 로직 추가.\n-- 선행: 131(refunds/subscriptions)·136·139.\n\nbegin", "set local lock_timeout=''5s''", "-- 잠근 구독의 live pending 구독 환불 존재 여부(별도 statement 로 호출).\ncreate or replace function public.qna_subscription_has_live_refund(p_subscription_id uuid)\nreturns boolean language sql stable security definer set search_path to ''public'' as $$\n  select exists (\n    select 1 from public.refunds r\n    where r.subscription_id = p_subscription_id\n      and r.status = ''pending''\n      and r.request_type in (''subscription_prorated'',''subscription_mentor_suspended'')\n  );\n$$", "revoke all on function public.qna_subscription_has_live_refund(uuid) from public, anon", "grant execute on function public.qna_subscription_has_live_refund(uuid) to authenticated, service_role", "-- create: 구독 경로에서 subscription FOR UPDATE + pending-refund 게이트.\ncreate or replace function public.qna_create_question_thread(\n  p_room_id uuid, p_title text, p_subject text default null, p_topic text default null, p_first_message_body text default null\n) returns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid; v_status text; v_suspended_until timestamptz;\n  v_created_at timestamptz; v_total int; v_per int; v_subject text; v_thread_id uuid; v_message_id uuid;\n  v_has_active_sub boolean; v_usage json; v_path text; v_sub_id uuid;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_title is null or btrim(p_title)='''' then raise exception ''TITLE_REQUIRED''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=p_room_id;\n  if not found then raise exception ''ROOM_NOT_FOUND''; end if;\n  if v_uid <> v_student then\n    if v_uid = v_mentor then raise exception ''MENTOR_CANNOT_CREATE_THREAD''; else raise exception ''NOT_ROOM_PARTY''; end if;\n  end if;\n  perform 1 from public.users where id=v_student for update;\n  select status, suspended_until, created_at into v_status, v_suspended_until, v_created_at from public.users where id=v_student;\n  if lower(coalesce(v_status,''active''))=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if lower(coalesce(v_status,''active''))=''suspended'' and (v_suspended_until is null or v_suspended_until > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if exists (select 1 from public.user_blocks where (blocker_id=v_student and blocked_id=v_mentor) or (blocker_id=v_mentor and blocked_id=v_student)) then raise exception ''BLOCKED''; end if;\n  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n\n  v_has_active_sub := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'');\n  if v_has_active_sub then\n    -- 결정 C: 활성 구독 FOR UPDATE 잠금 후 별도 statement 로 live pending refund 검사.\n    select id into v_sub_id from public.subscriptions\n      where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then\n      raise exception ''SUBSCRIPTION_REFUND_PENDING'';\n    end if;\n    v_usage := public.get_weekly_question_usage(v_student, v_mentor);\n    if not coalesce((v_usage->>''can_ask'')::boolean, false) then raise exception ''WEEKLY_LIMIT_EXHAUSTED''; end if;\n    v_path := ''subscription'';\n  else\n    if v_created_at is not null and now() >= v_created_at + interval ''7 days'' then raise exception ''FREE_QUOTA_EXPIRED''; end if;\n    select count(*) into v_total from public.free_question_usage where student_id=v_student;\n    if v_total >= 7 then raise exception ''FREE_QUOTA_TOTAL_EXHAUSTED''; end if;\n    select count(*) into v_per from public.free_question_usage where student_id=v_student and mentor_id=v_mentor;\n    if v_per >= 3 then raise exception ''FREE_QUOTA_MENTOR_EXHAUSTED''; end if;\n    v_path := ''free'';\n  end if;\n\n  v_subject := nullif(btrim(coalesce(p_subject,'''')),'''');\n  if v_subject is not null and not exists (select 1 from public.subjects where code=v_subject) then v_subject := null; end if;\n  insert into public.question_threads (mentor_student_room_id, title, status, subject, topic)\n  values (p_room_id, btrim(p_title), ''pending'', v_subject, nullif(btrim(coalesce(p_topic,'''')),'''')) returning id into v_thread_id;\n  if p_first_message_body is not null and btrim(p_first_message_body) <> '''' then\n    insert into public.question_messages (thread_id, author_id, body) values (v_thread_id, v_student, btrim(p_first_message_body)) returning id into v_message_id;\n  end if;\n  if v_path=''free'' then\n    insert into public.free_question_usage (student_id, mentor_id, thread_id) values (v_student, v_mentor, v_thread_id);\n  end if;\n  return jsonb_build_object(''ok'',true,''thread_id'',v_thread_id,''message_id'',v_message_id,''path'',v_path,''used_free_quota'',(v_path=''free''));\nend; $$", "-- append: 학생 후속 메시지도 활성 구독 pending-refund 게이트.\ncreate or replace function public.qna_append_message(p_thread_id uuid, p_body text)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_status text; v_thread_status text;\n  v_first_answered timestamptz; v_message_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_mentor_name text; v_sub_id uuid;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_body is null or btrim(p_body)='''' then raise exception ''BODY_REQUIRED''; end if;\n  select t.mentor_student_room_id, t.status, t.first_answered_at into v_room, v_thread_status, v_first_answered\n    from public.question_threads t where t.id=p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;\n  if v_uid=v_mentor then v_is_mentor:=true; elsif v_uid=v_student then v_is_mentor:=false; else raise exception ''NOT_ROOM_PARTY''; end if;\n  select status into v_status from public.users where id=v_uid;\n  if lower(coalesce(v_status,''active''))=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if v_thread_status in (''confirmed'',''closed'',''archived'') then raise exception ''THREAD_LOCKED''; end if;\n  if v_is_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  -- 학생 후속 메시지: 활성 구독 FOR UPDATE + live pending refund 게이트.\n  if not v_is_mentor then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n  end if;\n\n  insert into public.question_messages (thread_id, author_id, body) values (p_thread_id, v_uid, btrim(p_body)) returning id into v_message_id;\n  if v_is_mentor and v_first_answered is null then\n    update public.question_threads set status=''answered'', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;\n    v_transitioned := true;\n    select coalesce(nullif(btrim(full_name),''''), nullif(btrim(nickname),''''), ''멘토'') into v_mentor_name from public.users where id=v_mentor;\n    perform public.record_domain_notification(v_student, ''question_answered:''||p_thread_id::text, ''question_answered:''||p_thread_id::text,\n      ''question_answered'',''새 답변이 도착했어요'', coalesce(v_mentor_name,''멘토'')||''님이 답변을 남겼습니다.'',\n      ''/question-room/''||v_room::text||''?thread=''||p_thread_id::text,\n      jsonb_build_object(''room_id'',v_room,''thread_id'',p_thread_id), jsonb_build_object(''room_id'',v_room,''thread_id'',p_thread_id));\n  end if;\n  return jsonb_build_object(''ok'',true,''message_id'',v_message_id,''answered_transition'',v_transitioned);\nend; $$", "-- register: 학생 첨부도 활성 구독 pending-refund 게이트(139 계약 + refund).\ncreate or replace function public.qna_register_attachment(\n  p_thread_id uuid, p_storage_path text, p_file_name text default null, p_mime_type text default null, p_message_id uuid default null\n) returns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_thread_status text;\n  v_first_answered timestamptz; v_att_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_mentor_name text; v_sub_id uuid;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_storage_path is null or btrim(p_storage_path)='''' then raise exception ''STORAGE_PATH_REQUIRED''; end if;\n  select t.mentor_student_room_id, t.status, t.first_answered_at into v_room, v_thread_status, v_first_answered\n    from public.question_threads t where t.id=p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;\n  if v_uid=v_mentor then v_is_mentor:=true; elsif v_uid=v_student then v_is_mentor:=false; else raise exception ''NOT_ROOM_PARTY''; end if;\n  if v_thread_status in (''confirmed'',''closed'',''archived'') then raise exception ''THREAD_LOCKED''; end if;\n  if p_storage_path not like (v_room::text || ''/'' || p_thread_id::text || ''/%'') then raise exception ''STORAGE_PATH_MISMATCH''; end if;\n  if not exists (select 1 from storage.objects o where o.bucket_id=''question-room-attachments'' and o.name = btrim(p_storage_path) and o.owner_id = v_uid::text) then raise exception ''STORAGE_OBJECT_NOT_OWNED''; end if;\n  if p_message_id is not null and not exists (select 1 from public.question_messages m where m.id=p_message_id and m.thread_id=p_thread_id) then raise exception ''MESSAGE_THREAD_MISMATCH''; end if;\n  if not v_is_mentor then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n  end if;\n\n  insert into public.question_attachments (thread_id, message_id, author_id, storage_path, file_name, mime_type)\n  values (p_thread_id, p_message_id, v_uid, btrim(p_storage_path), p_file_name, p_mime_type) returning id into v_att_id;\n  if v_is_mentor and v_first_answered is null then\n    update public.question_threads set status=''answered'', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;\n    v_transitioned := true;\n    select coalesce(nullif(btrim(full_name),''''), nullif(btrim(nickname),''''), ''멘토'') into v_mentor_name from public.users where id=v_mentor;\n    perform public.record_domain_notification(v_student, ''question_answered:''||p_thread_id::text, ''question_answered:''||p_thread_id::text,\n      ''question_answered'',''새 답변이 도착했어요'', coalesce(v_mentor_name,''멘토'')||''님이 파일을 보냈습니다.'',\n      ''/question-room/''||v_room::text||''?thread=''||p_thread_id::text,\n      jsonb_build_object(''room_id'',v_room,''thread_id'',p_thread_id), jsonb_build_object(''room_id'',v_room,''thread_id'',p_thread_id));\n  end if;\n  return jsonb_build_object(''ok'',true,''attachment_id'',v_att_id,''answered_transition'',v_transitioned);\nend; $$", "revoke all on function public.qna_create_question_thread(uuid,text,text,text,text) from public, anon", "revoke all on function public.qna_append_message(uuid,text) from public, anon", "revoke all on function public.qna_register_attachment(uuid,text,text,text,uuid) from public, anon", "grant execute on function public.qna_create_question_thread(uuid,text,text,text,text) to authenticated, service_role", "grant execute on function public.qna_append_message(uuid,text) to authenticated, service_role", "grant execute on function public.qna_register_attachment(uuid,text,text,text,uuid) to authenticated, service_role", "commit", "-- §V(rollback-only): 활성구독+pending 환불(subscription_prorated/mentor_suspended) → 생성·학생append·\n--   학생첨부 SUBSCRIPTION_REFUND_PENDING 거부 · 환불 없으면 정상 · 무료 스레드 미적용 · 멘토 답변 무영향.\n\n-- >>> NATIVE_BASELINE_PART 0150 | supabase/sql/143_p1_13_state_machine_hardening.sql | 143_p1_13_state_machine_hardening.sql <<<\n-- 143_p1_13_state_machine_hardening.sql\n-- P1-13 상태기계 완전성 감사 보정 — 131 을 수정하지 않고 confirm_subscription_checkout 재정의.\n--\n-- 추가/강화:\n--  * 동시 생성 봉쇄: student·mentor pair advisory transaction lock(빈 pair 에도 잠금) + uq_subscriptions_pair\n--    UNIQUE + ON CONFLICT 원자 upsert(SELECT FOR UPDATE 만으로 부족한 신규 pair 경쟁 봉쇄).\n--  * 필수 게이트 추가: 학생 계정 활성 · 멘토 승인 · 멘토 cap(신규/재활성 시) · payment 종류(비구독 kind 거부) ·\n--    payment mentor 존재 · plan_id 일치 · plan active · 정본 플랜 금액 · pending TTL · processing/종료 거부.\n--  * 성공·원장 전필드 멱등: 재호출은 payment/subscription/ledger(user_id·ref_type·ref_id=subscription_id·\n--    delta_cents=-amount·reason·idempotency_key)가 모두 일치할 때만 성공. succeeded 인데 구독/원장 불일치면\n--    성공 반환하지 않고 구조화 실패로 격리(같은 트랜잭션 롤백 — 부분 커밋 없음).\n-- 선행: 131·019/023·067.\n\ncreate or replace function public.confirm_subscription_checkout(\n  p_payment_id uuid, p_plan_id uuid, p_idempotency_key text default null\n) returns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_student uuid; v_mentor uuid; v_pay_status text; v_created_at timestamptz; v_kind text;\n  v_plan_mentor uuid; v_plan_tier text; v_plan_active boolean; v_amount_cents int;\n  v_is_open boolean; v_sub_id uuid; v_reactivated boolean := false;\n  v_status text; v_suspended_until timestamptz;\n  v_l_user uuid; v_l_delta bigint; v_l_reason text; v_l_reftype text; v_l_refid uuid;\n  v_succeeded_aliases text[] := array[''succeeded'',''paid'',''success'',''complete'',''captured''];\nbegin\n  -- 결제 잠금 + 로드.\n  select user_id, mentor_id, status, created_at, kind into v_student, v_mentor, v_pay_status, v_created_at, v_kind\n    from public.payments where id = p_payment_id for update;\n  if not found then raise exception ''PAYMENT_NOT_FOUND''; end if;\n  if v_student is null then raise exception ''PAYMENT_NO_USER''; end if;\n  if v_mentor is null then raise exception ''PAYMENT_NO_MENTOR''; end if;\n  if lower(coalesce(v_kind,'''')) in (''cash_topup'',''topup'',''cash'',''individual_question'',''iq'',''custom_order'',''custom_request'',''deliverable'') then\n    raise exception ''PAYMENT_KIND_INVALID'';\n  end if;\n\n  -- 동시 생성 봉쇄: pair advisory xact lock(빈 pair 포함 전 구간 직렬화).\n  perform pg_advisory_xact_lock(hashtext(v_student::text), hashtext(v_mentor::text));\n\n  -- 플랜 잠금 + 정본 금액.\n  select mentor_id, plan_tier, is_active, amount_cents into v_plan_mentor, v_plan_tier, v_plan_active, v_amount_cents\n    from public.mentor_plans where id = p_plan_id for update;\n  if not found then raise exception ''PLAN_NOT_FOUND''; end if;\n  if v_plan_mentor <> v_mentor then raise exception ''PLAN_MENTOR_MISMATCH''; end if;\n  if v_amount_cents is null or v_amount_cents <= 0 then raise exception ''PLAN_AMOUNT_INVALID''; end if;\n\n  -- 이미 성공(별칭) → 전필드 멱등 검증 후 반환(불일치면 격리).\n  if v_pay_status = any(v_succeeded_aliases) then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor;\n    if v_sub_id is null then raise exception ''ISOLATION_SUCCEEDED_NO_SUBSCRIPTION payment=%'', p_payment_id; end if;\n    select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid\n      from public.cash_ledger where idempotency_key = ''sub_debit_'' || p_payment_id::text;\n    if v_l_user is null then raise exception ''ISOLATION_SUCCEEDED_NO_LEDGER payment=%'', p_payment_id; end if;\n    if v_l_user <> v_student or v_l_refid is distinct from v_sub_id or coalesce(v_l_reftype,'''') <> ''subscriptions''\n       or coalesce(v_l_reason,'''') <> ''subscription_payment'' or v_l_delta <> -v_amount_cents then\n      raise exception ''ISOLATION_LEDGER_FIELD_MISMATCH payment=% sub=%'', p_payment_id, v_sub_id;\n    end if;\n    return jsonb_build_object(''ok'',true,''idempotent'',true,''subscription_id'',v_sub_id,''payment_status'',''succeeded'');\n  end if;\n\n  if v_pay_status = ''processing'' then raise exception ''PAYMENT_PROCESSING''; end if;\n  if v_pay_status in (''failed'',''canceled'',''refunded'') then raise exception ''PAYMENT_NOT_PENDING''; end if;\n  if v_pay_status <> ''pending'' then raise exception ''PAYMENT_STATE_UNEXPECTED''; end if;\n  if v_created_at is null or now() > v_created_at + interval ''30 minutes'' then raise exception ''PAYMENT_STALE''; end if;\n\n  -- 학생 계정 활성.\n  select status, suspended_until into v_status, v_suspended_until from public.users where id = v_student for update;\n  if lower(coalesce(v_status,''active'')) = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if lower(coalesce(v_status,''active'')) = ''suspended'' and (v_suspended_until is null or v_suspended_until > now()) then\n    raise exception ''ACCOUNT_SUSPENDED'';\n  end if;\n\n  -- 멘토 잠금 + 구독 open + 승인 + 플랜 active.\n  perform 1 from public.mentor_profiles where user_id = v_mentor for update;\n  select is_open_for_subscriptions into v_is_open from public.mentor_profiles where user_id = v_mentor;\n  if not coalesce(v_is_open, true) then raise exception ''MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS''; end if;\n  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  if not coalesce(v_plan_active, true) then raise exception ''PLAN_INACTIVE''; end if;\n\n  -- 멘토 cap: 이 pair 가 현재 active 가 아닐 때(신규/재활성)만 가중치 추가 검사.\n  if not exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'') then\n    if public.mentor_cap_used(v_mentor) + public.subscription_cap_weight(v_plan_tier) > public.mentor_cap_limit(v_mentor) then\n      raise exception ''MENTOR_CAP_EXCEEDED'';\n    end if;\n  end if;\n\n  v_reactivated := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor);\n\n  -- 구독 생성/재활성화(UNIQUE + ON CONFLICT 원자).\n  insert into public.subscriptions (student_id, mentor_id, plan_id, plan_tier, status, payment_id,\n    started_at, current_period_start, current_period_end, next_billing_at, billing_cycle, cancel_at_period_end, last_payment_id)\n  values (v_student, v_mentor, p_plan_id, v_plan_tier, ''active'', p_payment_id,\n    now(), now(), now()+interval ''1 month'', now()+interval ''1 month'', ''monthly'', false, p_payment_id)\n  on conflict (student_id, mentor_id) do update set\n    plan_id=excluded.plan_id, plan_tier=excluded.plan_tier, status=''active'', payment_id=excluded.payment_id,\n    last_payment_id=excluded.last_payment_id, started_at=coalesce(public.subscriptions.started_at, now()),\n    current_period_start=now(), current_period_end=now()+interval ''1 month'', next_billing_at=now()+interval ''1 month'',\n    cancel_at_period_end=false, cancel_requested_at=null, canceled_at=null, expired_at=null, grace_until=null,\n    last_renewed_at=now(), updated_at=now()\n  returning id into v_sub_id;\n\n  -- 기존 원장 행이 있으면 전필드 일치만 허용(불일치 격리).\n  select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid\n    from public.cash_ledger where idempotency_key = ''sub_debit_'' || p_payment_id::text;\n  if v_l_user is not null and (v_l_user <> v_student or v_l_refid is distinct from v_sub_id\n     or coalesce(v_l_reftype,'''') <> ''subscriptions'' or coalesce(v_l_reason,'''') <> ''subscription_payment''\n     or v_l_delta <> -v_amount_cents) then\n    raise exception ''ISOLATION_LEDGER_FIELD_MISMATCH payment=% sub=%'', p_payment_id, v_sub_id;\n  end if;\n\n  perform public.record_subscription_cash_debit(v_student, v_sub_id, p_payment_id, v_amount_cents::bigint);\n\n  update public.payments set status=''succeeded'', plan_id=p_plan_id,\n    metadata=coalesce(metadata,''{}''::jsonb) || jsonb_build_object(''planId'',p_plan_id::text,''subscription_id'',v_sub_id::text),\n    updated_at=now() where id=p_payment_id;\n\n  return jsonb_build_object(''ok'',true,''subscription_id'',v_sub_id,''payment_status'',''succeeded'',''amount_cents'',v_amount_cents,''reactivated'',v_reactivated);\nend;\n$$", "revoke all on function public.confirm_subscription_checkout(uuid,uuid,text) from public, anon, authenticated", "grant execute on function public.confirm_subscription_checkout(uuid,uuid,text) to service_role", "-- §V(rollback-only): 게이트 각각 거부(정지학생·미승인멘토·cap초과·비구독kind·plan불일치/미가격·TTL·processing) ·\n--   pending→active+debit+succeeded · 재호출 전필드 멱등 · succeeded인데 ledger 불일치 격리(부분커밋 없음) ·\n--   동시 신규 pair 이중 구독 없음(UNIQUE+advisory). 독립 2세션 실측 = CONCURRENCY_VALIDATION_DEBT.\n\n-- >>> NATIVE_BASELINE_PART 0151 | supabase/sql/144_p1_8a_direct_write_eligibility.sql | 144_p1_8a_direct_write_eligibility.sql <<<\n-- 144_p1_8a_direct_write_eligibility.sql\n-- P1-8A 반려 보정 (1-1/1-2/1-3) — 141/142 미수정, 가드 함수 재정의(신규 파일).\n--\n-- 1-1 직접 thread 생성 한도 우회: 직접 question_threads INSERT 에서 전 자격을 BEFORE 가드가 강제하고,\n--     무료 경로는 AFTER 트리거가 free_question_usage(thread_id 링크)를 원자 소비한다. 구버전의 별도\n--     usage INSERT(thread_id NULL, 직접)는 안전한 멱등 no-op(시간 근접 휴리스틱 없음).\n-- 1-2 직접 멘토 answered: 콘텐츠 없이 status만 answered 로 바꾸는 직접 UPDATE 거부(DIRECT_ANSWERED_VIA_CONTENT_ONLY).\n--     멘토 첫 실제 메시지/첨부는 AFTER 트리거가 self-gating 헬퍼(멘토 본인 + 실제 멘토 콘텐츠 존재 확인)를\n--     호출해 pending/open→answered + canonical question_answered exactly-once 처리(0회 발송 아님).\n-- 1-3 업로드 자격: qra_uploader_allowed_for_path 에 양방향 차단 추가(계정·멘토는 141). 활성구독/무료 자격·\n--     pending refund 는 등록 RPC(qna_register_attachment)가 정본 기록으로 강제(업로드 객체는 등록 전 inert,\n--     실패 시 보상 삭제) — 층위 방어.\n-- 판별: qna_* RPC(owner=postgres)=current_user ''postgres'', 직접=''authenticated''. 가드/AFTER 트리거는 INVOKER,\n--     answered 전이 헬퍼는 self-gating DEFINER(내부 UPDATE 는 postgres 컨텍스트라 qt 가드 skip).\n-- 선행: 136/139/141/142.\n\nbegin", "set local lock_timeout=''5s''", "-- 멘토 첫 콘텐츠 → answered 전이 + exactly-once 알림. self-gating: 호출자=room 멘토 AND 실제 멘토 콘텐츠 존재.\ncreate or replace function public.qna_apply_answered_transition(p_thread_id uuid)\nreturns void language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_room uuid; v_status text; v_first timestamptz; v_student uuid; v_mentor uuid; v_updated int; v_name text;\nbegin\n  select mentor_student_room_id, status, first_answered_at into v_room, v_status, v_first from public.question_threads where id=p_thread_id;\n  if v_room is null then return; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;\n  if auth.uid() is distinct from v_mentor then return; end if;\n  if v_first is not null or v_status not in (''pending'',''open'') then return; end if;\n  if not exists (select 1 from public.question_messages m where m.thread_id=p_thread_id and m.author_id=v_mentor)\n     and not exists (select 1 from public.question_attachments a where a.thread_id=p_thread_id and a.author_id=v_mentor) then\n    return; -- content-less: no-op\n  end if;\n  update public.question_threads set status=''answered'', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;\n  get diagnostics v_updated = row_count;\n  if v_updated>0 then\n    select coalesce(nullif(btrim(full_name),''''),nullif(btrim(nickname),''''),''멘토'') into v_name from public.users where id=v_mentor;\n    perform public.record_domain_notification(v_student,''question_answered:''||p_thread_id::text,''question_answered:''||p_thread_id::text,\n      ''question_answered'',''새 답변이 도착했어요'',coalesce(v_name,''멘토'')||''님이 답변을 남겼습니다.'',\n      ''/question-room/''||v_room::text||''?thread=''||p_thread_id::text,\n      jsonb_build_object(''room_id'',v_room,''thread_id'',p_thread_id),jsonb_build_object(''room_id'',v_room,''thread_id'',p_thread_id));\n  end if;\nend; $$", "revoke all on function public.qna_apply_answered_transition(uuid) from public, anon", "grant execute on function public.qna_apply_answered_transition(uuid) to authenticated, service_role", "-- 양방향 차단 검사(DEFINER: INVOKER 트리거가 RLS 로 상대의 차단 행을 못 보는 문제 방지).\ncreate or replace function public.qna_users_blocked(p_a uuid, p_b uuid)\nreturns boolean language sql stable security definer set search_path to ''public'' as $$\n  select exists (select 1 from public.user_blocks where (blocker_id=p_a and blocked_id=p_b) or (blocker_id=p_b and blocked_id=p_a));\n$$", "revoke all on function public.qna_users_blocked(uuid,uuid) from public, anon", "grant execute on function public.qna_users_blocked(uuid,uuid) to authenticated, service_role", "-- 1-1: 직접 thread INSERT 전 자격 강제. UPDATE 는 직접 answered/first_answered 거부.\ncreate or replace function public.qt_direct_write_guard()\nreturns trigger language plpgsql security invoker set search_path to ''public'' as $$\ndeclare\n  v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid; v_status text; v_suspended_until timestamptz;\n  v_created_at timestamptz; v_total int; v_per int; v_has_sub boolean; v_usage json; v_sub_id uuid;\nbegin\n  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = NEW.mentor_student_room_id;\n  if TG_OP = ''INSERT'' then\n    if v_student is null then raise exception ''ROOM_NOT_FOUND''; end if;\n    if v_uid is distinct from v_student then raise exception ''DIRECT_CREATE_STUDENT_ONLY''; end if;\n    if coalesce(NEW.status,''pending'') not in (''pending'',''open'') then raise exception ''DIRECT_INSERT_STATUS_FORBIDDEN''; end if;\n    if NEW.first_answered_at is not null or NEW.confirmed_at is not null then raise exception ''DIRECT_INSERT_WORKFLOW_FIELDS_FORBIDDEN''; end if;\n    select status, suspended_until, created_at into v_status, v_suspended_until, v_created_at from public.users where id=v_student;\n    if lower(coalesce(v_status,''active''))=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n    if lower(coalesce(v_status,''active''))=''suspended'' and (v_suspended_until is null or v_suspended_until > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n    if public.qna_users_blocked(v_student, v_mentor) then raise exception ''BLOCKED''; end if;\n    if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n    v_has_sub := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'');\n    if v_has_sub then\n      select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'';\n      if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n      v_usage := public.get_weekly_question_usage(v_student, v_mentor);\n      if not coalesce((v_usage->>''can_ask'')::boolean, false) then raise exception ''WEEKLY_LIMIT_EXHAUSTED''; end if;\n    else\n      if v_created_at is not null and now() >= v_created_at + interval ''7 days'' then raise exception ''FREE_QUOTA_EXPIRED''; end if;\n      select count(*) into v_total from public.free_question_usage where student_id=v_student;\n      if v_total >= 7 then raise exception ''FREE_QUOTA_TOTAL_EXHAUSTED''; end if;\n      select count(*) into v_per from public.free_question_usage where student_id=v_student and mentor_id=v_mentor;\n      if v_per >= 3 then raise exception ''FREE_QUOTA_MENTOR_EXHAUSTED''; end if;\n    end if;\n    return NEW;\n  end if;\n  if NEW.status is distinct from OLD.status then\n    if NEW.status = ''answered'' then raise exception ''DIRECT_ANSWERED_VIA_CONTENT_ONLY''; end if;\n    if NEW.status = ''confirmed'' and v_uid is distinct from v_student then raise exception ''DIRECT_CONFIRM_STUDENT_ONLY''; end if;\n  end if;\n  if NEW.first_answered_at is distinct from OLD.first_answered_at then raise exception ''DIRECT_FIRST_ANSWERED_VIA_CONTENT_ONLY''; end if;\n  if (NEW.is_wrong_answer is distinct from OLD.is_wrong_answer or NEW.mastery_status is distinct from OLD.mastery_status) and v_uid is distinct from v_student then raise exception ''DIRECT_WRONG_FLAG_STUDENT_ONLY''; end if;\n  return NEW;\nend; $$", "-- 1-1: 직접 무료 thread 생성 후(AFTER, thread FK 존재) 무료 usage 원자 소비.\ncreate or replace function public.qt_direct_consume_free_usage()\nreturns trigger language plpgsql security invoker set search_path to ''public'' as $$\ndeclare v_student uuid; v_mentor uuid;\nbegin\n  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = NEW.mentor_student_room_id;\n  if not exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'') then\n    insert into public.free_question_usage (student_id, mentor_id, thread_id) values (v_student, v_mentor, NEW.id);\n  end if;\n  return NEW;\nend; $$", "drop trigger if exists trg_qt_direct_consume_free_usage on public.question_threads", "create trigger trg_qt_direct_consume_free_usage after insert on public.question_threads for each row execute function public.qt_direct_consume_free_usage()", "-- 1-1: 구버전 별도 usage INSERT(thread_id NULL, 직접) 안전 멱등 no-op(AFTER 트리거가 정본 소비).\ncreate or replace function public.fqu_legacy_standalone_noop()\nreturns trigger language plpgsql security invoker set search_path to ''public'' as $$\nbegin\n  if public.qna_is_direct_untrusted_writer() and NEW.thread_id is null then return null; end if;\n  return NEW;\nend; $$", "drop trigger if exists trg_fqu_legacy_standalone_noop on public.free_question_usage", "create trigger trg_fqu_legacy_standalone_noop before insert on public.free_question_usage for each row execute function public.fqu_legacy_standalone_noop()", "-- 1-2/1-3 BEFORE 가드: 종료 스레드·경로·owner 위조 거부(answered 전이는 AFTER 에서).\ncreate or replace function public.qm_direct_write_guard()\nreturns trigger language plpgsql security invoker set search_path to ''public'' as $$\ndeclare v_status text;\nbegin\n  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;\n  select status into v_status from public.question_threads where id = NEW.thread_id;\n  if v_status in (''confirmed'',''closed'',''archived'') then raise exception ''DIRECT_MSG_THREAD_LOCKED''; end if;\n  return NEW;\nend; $$", "create or replace function public.qa_direct_write_guard()\nreturns trigger language plpgsql security invoker set search_path to ''public'' as $$\ndeclare v_room uuid; v_status text;\nbegin\n  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;\n  select mentor_student_room_id, status into v_room, v_status from public.question_threads where id = NEW.thread_id;\n  if v_status in (''confirmed'',''closed'',''archived'') then raise exception ''DIRECT_ATT_THREAD_LOCKED''; end if;\n  if NEW.storage_path is null or NEW.storage_path not like (v_room::text||''/''||NEW.thread_id::text||''/%'') then raise exception ''DIRECT_ATT_PATH_FORGERY''; end if;\n  if not exists (select 1 from storage.objects o where o.bucket_id=''question-room-attachments'' and o.name=NEW.storage_path and o.owner_id=auth.uid()::text) then raise exception ''DIRECT_ATT_OBJECT_NOT_OWNED''; end if;\n  return NEW;\nend; $$", "-- 1-2 AFTER: 직접 멘토 첫 메시지/첨부 → self-gating answered 전이.\ncreate or replace function public.qm_direct_answered_after()\nreturns trigger language plpgsql security invoker set search_path to ''public'' as $$\nbegin\n  if public.qna_is_direct_untrusted_writer() then perform public.qna_apply_answered_transition(NEW.thread_id); end if;\n  return NEW;\nend; $$", "drop trigger if exists trg_qm_direct_answered_after on public.question_messages", "create trigger trg_qm_direct_answered_after after insert on public.question_messages for each row execute function public.qm_direct_answered_after()", "create or replace function public.qa_direct_answered_after()\nreturns trigger language plpgsql security invoker set search_path to ''public'' as $$\nbegin\n  if public.qna_is_direct_untrusted_writer() then perform public.qna_apply_answered_transition(NEW.thread_id); end if;\n  return NEW;\nend; $$", "drop trigger if exists trg_qa_direct_answered_after on public.question_attachments", "create trigger trg_qa_direct_answered_after after insert on public.question_attachments for each row execute function public.qa_direct_answered_after()", "-- 1-3: 업로드 자격 helper 에 양방향 차단 추가(계정·멘토는 141).\ncreate or replace function public.qra_uploader_allowed_for_path(p_name text)\nreturns boolean language plpgsql stable security definer set search_path to ''public'' as $$\ndeclare v_room uuid; v_student uuid; v_mentor uuid; v_uid uuid := auth.uid(); v_status text;\nbegin\n  if v_uid is null then return false; end if;\n  v_room := public.qra_room_uuid_from_path(p_name);\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = v_room;\n  if v_student is null then return false; end if;\n  select status into v_status from public.users where id = v_uid;\n  if lower(coalesce(v_status,''active'')) = ''banned'' then return false; end if;\n  if lower(coalesce(v_status,''active'')) = ''suspended'' then\n    if exists (select 1 from public.users where id=v_uid and (suspended_until is null or suspended_until > now())) then return false; end if;\n  end if;\n  if v_uid = v_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then return false; end if;\n  if public.qna_users_blocked(v_student, v_mentor) then return false; end if;\n  return true;\nend; $$", "commit", "-- §V(rollback-only, PASS): 직접 thread-only 생성이 무료 usage 원자 소비(4번째 멘토별 거부)·구버전 standalone\n--   usage no-op·직접 status-only answered 거부·멘토 첫 메시지 answered+exactly-once·RPC(postgres) 무영향.\n\n-- >>> NATIVE_BASELINE_PART 0152 | supabase/sql/145_p1_13_anomaly_persistence.sql | 145_p1_13_anomaly_persistence.sql <<<\n-- 145_p1_13_anomaly_persistence.sql\n-- P1-13 (1-5) 금융 불일치 anomaly 영속성. 131/143 미수정, confirm_subscription_checkout 재정의.\n--\n-- 문제: 143 은 원장/구독 불일치 시 RAISE → audit 기록까지 롤백. 영속 기록이 남지 않는다.\n-- 해결:\n--   * service-role 전용 anomaly 테이블(RLS deny + revoke).\n--   * 금융 write 전 사전 불일치는 anomaly INSERT 후 {ok:false,code} 반환(금융 변경 0 → anomaly 만 커밋).\n--   * 금융 write 도중 오류는 내부 subtransaction(BEGIN..EXCEPTION)으로 구독·차감·payment 변경을 롤백한 뒤\n--     바깥에서 anomaly 를 기록하고 {ok:false} 반환(anomaly 만 커밋).\n-- 반환 계약 변경: 이제 anomaly 는 RAISE 가 아니라 {ok:false,code,anomaly_id} 로 반환한다. 웹은 data.ok 를 검사.\n-- 선행: 131·143·019/023·067.\n\nbegin", "set local lock_timeout=''5s''", "create table if not exists public.subscription_checkout_anomalies (\n  id uuid primary key default gen_random_uuid(),\n  payment_id uuid,\n  subscription_id uuid,\n  code text not null,\n  detail text,\n  expected jsonb,\n  found jsonb,\n  created_at timestamptz not null default now()\n)", "alter table public.subscription_checkout_anomalies enable row level security", "-- 정책 미부여 → authenticated/anon 접근 불가. service_role 은 RLS bypass. DEFINER(postgres) INSERT 가능.\nrevoke all on table public.subscription_checkout_anomalies from public, anon, authenticated", "grant select, insert on table public.subscription_checkout_anomalies to service_role", "create or replace function public.confirm_subscription_checkout(\n  p_payment_id uuid, p_plan_id uuid, p_idempotency_key text default null\n) returns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_student uuid; v_mentor uuid; v_pay_status text; v_created_at timestamptz; v_kind text;\n  v_plan_mentor uuid; v_plan_tier text; v_plan_active boolean; v_amount_cents int;\n  v_is_open boolean; v_sub_id uuid; v_reactivated boolean := false;\n  v_status text; v_suspended_until timestamptz;\n  v_l_user uuid; v_l_delta bigint; v_l_reason text; v_l_reftype text; v_l_refid uuid;\n  v_succeeded_aliases text[] := array[''succeeded'',''paid'',''success'',''complete'',''captured''];\n  v_anom uuid; v_err text; v_errcode text;\nbegin\n  select user_id, mentor_id, status, created_at, kind into v_student, v_mentor, v_pay_status, v_created_at, v_kind\n    from public.payments where id = p_payment_id for update;\n  if not found then raise exception ''PAYMENT_NOT_FOUND''; end if;\n  if v_student is null then raise exception ''PAYMENT_NO_USER''; end if;\n  if v_mentor is null then raise exception ''PAYMENT_NO_MENTOR''; end if;\n  if lower(coalesce(v_kind,'''')) in (''cash_topup'',''topup'',''cash'',''individual_question'',''iq'',''custom_order'',''custom_request'',''deliverable'') then raise exception ''PAYMENT_KIND_INVALID''; end if;\n\n  perform pg_advisory_xact_lock(hashtext(v_student::text), hashtext(v_mentor::text));\n\n  select mentor_id, plan_tier, is_active, amount_cents into v_plan_mentor, v_plan_tier, v_plan_active, v_amount_cents\n    from public.mentor_plans where id = p_plan_id for update;\n  if not found then raise exception ''PLAN_NOT_FOUND''; end if;\n  if v_plan_mentor <> v_mentor then raise exception ''PLAN_MENTOR_MISMATCH''; end if;\n  if v_amount_cents is null or v_amount_cents <= 0 then raise exception ''PLAN_AMOUNT_INVALID''; end if;\n\n  -- 이미 성공 → 전필드 멱등 검증. 불일치는 anomaly INSERT 후 {ok:false} (금융 변경 없음).\n  if v_pay_status = any(v_succeeded_aliases) then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor;\n    if v_sub_id is null then\n      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n        values (p_payment_id, null, ''SUCCEEDED_NO_SUBSCRIPTION'', ''succeeded payment without subscription'') returning id into v_anom;\n      return jsonb_build_object(''ok'',false,''code'',''SUCCEEDED_NO_SUBSCRIPTION'',''anomaly_id'',v_anom);\n    end if;\n    select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid\n      from public.cash_ledger where idempotency_key = ''sub_debit_'' || p_payment_id::text;\n    if v_l_user is null then\n      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n        values (p_payment_id, v_sub_id, ''SUCCEEDED_NO_LEDGER'', ''succeeded payment without ledger debit'') returning id into v_anom;\n      return jsonb_build_object(''ok'',false,''code'',''SUCCEEDED_NO_LEDGER'',''anomaly_id'',v_anom);\n    end if;\n    if v_l_user <> v_student or v_l_refid is distinct from v_sub_id or coalesce(v_l_reftype,'''') <> ''subscriptions''\n       or coalesce(v_l_reason,'''') <> ''subscription_payment'' or v_l_delta <> -v_amount_cents then\n      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)\n        values (p_payment_id, v_sub_id, ''LEDGER_FIELD_MISMATCH'', ''idempotent re-check field mismatch'',\n          jsonb_build_object(''user_id'',v_student,''ref_id'',v_sub_id,''ref_type'',''subscriptions'',''reason'',''subscription_payment'',''delta_cents'',-v_amount_cents),\n          jsonb_build_object(''user_id'',v_l_user,''ref_id'',v_l_refid,''ref_type'',v_l_reftype,''reason'',v_l_reason,''delta_cents'',v_l_delta))\n        returning id into v_anom;\n      return jsonb_build_object(''ok'',false,''code'',''LEDGER_FIELD_MISMATCH'',''anomaly_id'',v_anom);\n    end if;\n    return jsonb_build_object(''ok'',true,''idempotent'',true,''subscription_id'',v_sub_id,''payment_status'',''succeeded'');\n  end if;\n\n  if v_pay_status = ''processing'' then raise exception ''PAYMENT_PROCESSING''; end if;\n  if v_pay_status in (''failed'',''canceled'',''refunded'') then raise exception ''PAYMENT_NOT_PENDING''; end if;\n  if v_pay_status <> ''pending'' then raise exception ''PAYMENT_STATE_UNEXPECTED''; end if;\n  if v_created_at is null or now() > v_created_at + interval ''30 minutes'' then raise exception ''PAYMENT_STALE''; end if;\n\n  select status, suspended_until into v_status, v_suspended_until from public.users where id = v_student for update;\n  if lower(coalesce(v_status,''active'')) = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if lower(coalesce(v_status,''active'')) = ''suspended'' and (v_suspended_until is null or v_suspended_until > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n\n  perform 1 from public.mentor_profiles where user_id = v_mentor for update;\n  select is_open_for_subscriptions into v_is_open from public.mentor_profiles where user_id = v_mentor;\n  if not coalesce(v_is_open, true) then raise exception ''MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS''; end if;\n  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  if not coalesce(v_plan_active, true) then raise exception ''PLAN_INACTIVE''; end if;\n\n  if not exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'') then\n    if public.mentor_cap_used(v_mentor) + public.subscription_cap_weight(v_plan_tier) > public.mentor_cap_limit(v_mentor) then raise exception ''MENTOR_CAP_EXCEEDED''; end if;\n  end if;\n\n  v_reactivated := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor);\n\n  -- 금융 write subtransaction: 오류 시 구독·차감·payment 변경 롤백, 바깥에서 anomaly 기록.\n  begin\n    insert into public.subscriptions (student_id, mentor_id, plan_id, plan_tier, status, payment_id,\n      started_at, current_period_start, current_period_end, next_billing_at, billing_cycle, cancel_at_period_end, last_payment_id)\n    values (v_student, v_mentor, p_plan_id, v_plan_tier, ''active'', p_payment_id,\n      now(), now(), now()+interval ''1 month'', now()+interval ''1 month'', ''monthly'', false, p_payment_id)\n    on conflict (student_id, mentor_id) do update set\n      plan_id=excluded.plan_id, plan_tier=excluded.plan_tier, status=''active'', payment_id=excluded.payment_id,\n      last_payment_id=excluded.last_payment_id, started_at=coalesce(public.subscriptions.started_at, now()),\n      current_period_start=now(), current_period_end=now()+interval ''1 month'', next_billing_at=now()+interval ''1 month'',\n      cancel_at_period_end=false, cancel_requested_at=null, canceled_at=null, expired_at=null, grace_until=null,\n      last_renewed_at=now(), updated_at=now()\n    returning id into v_sub_id;\n\n    select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid\n      from public.cash_ledger where idempotency_key = ''sub_debit_'' || p_payment_id::text;\n    if v_l_user is not null and (v_l_user <> v_student or v_l_refid is distinct from v_sub_id\n       or coalesce(v_l_reftype,'''') <> ''subscriptions'' or coalesce(v_l_reason,'''') <> ''subscription_payment'' or v_l_delta <> -v_amount_cents) then\n      raise exception ''LEDGER_FIELD_MISMATCH'';\n    end if;\n\n    perform public.record_subscription_cash_debit(v_student, v_sub_id, p_payment_id, v_amount_cents::bigint);\n    update public.payments set status=''succeeded'', plan_id=p_plan_id,\n      metadata=coalesce(metadata,''{}''::jsonb) || jsonb_build_object(''planId'',p_plan_id::text,''subscription_id'',v_sub_id::text),\n      updated_at=now() where id=p_payment_id;\n  exception when others then\n    get stacked diagnostics v_errcode = returned_sqlstate;\n    v_err := sqlerrm;\n  end;\n\n  if v_err is not null then\n    -- 잔액 부족은 정상 사용자 오류(anomaly 아님) → anomaly 미기록.\n    if v_err like ''%CASH_INSUFFICIENT%'' then\n      return jsonb_build_object(''ok'',false,''code'',''CASH_INSUFFICIENT'');\n    end if;\n    -- 그 외(원장 불일치·예상 밖) 금융 변경은 subtransaction 롤백됨. anomaly 만 기록·커밋.\n    insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      values (p_payment_id, v_sub_id,\n        case when v_err like ''%LEDGER_FIELD_MISMATCH%'' then ''LEDGER_FIELD_MISMATCH'' else ''FINANCIAL_WRITE_ERROR'' end,\n        left(v_err, 500)) returning id into v_anom;\n    return jsonb_build_object(''ok'',false,\n      ''code'', case when v_err like ''%LEDGER_FIELD_MISMATCH%'' then ''LEDGER_FIELD_MISMATCH'' else ''FINANCIAL_WRITE_ERROR'' end,\n      ''sqlstate'',v_errcode,''anomaly_id'',v_anom);\n  end if;\n\n  return jsonb_build_object(''ok'',true,''subscription_id'',v_sub_id,''payment_status'',''succeeded'',''amount_cents'',v_amount_cents,''reactivated'',v_reactivated);\nend;\n$$", "revoke all on function public.confirm_subscription_checkout(uuid,uuid,text) from public, anon, authenticated", "grant execute on function public.confirm_subscription_checkout(uuid,uuid,text) to service_role", "commit", "-- §V(rollback-only): anomaly 는 별도 트랜잭션에서 조회 가능(영속) · 불일치 시 구독/원장/payment 변경 0 ·\n--   {ok:false,code,anomaly_id} 반환 · 정상 경로 {ok:true}. service_role 외 anomaly 접근 불가.\n\n-- >>> NATIVE_BASELINE_PART 0153 | supabase/baseline/supplements/005_pre147_out_of_band_idem_constraints.sql | 005_pre147_out_of_band_idem_constraints.sql <<<\n-- 005_pre147_out_of_band_idem_constraints.sql — 번호 147/148 적용 ''이전'' 위치 필수.\n-- 부모 실측: 원장 147/148(7/20)의 create unique index IF NOT EXISTS 가 no-op 이 되려면\n-- 이 시점 이전에 동명 ''제약''(constraint) 이 이미 있어야 한다 — 저장소 SQL 에 생성문 없음\n-- (out-of-band, 7/17~7/20 사이). 컬럼·제약 정의는 부모 인벤토리 원문.\nalter table public.community_posts add column if not exists create_idempotency_key uuid", "alter table public.shortform_posts add column if not exists create_idempotency_key uuid", "alter table public.community_posts add column if not exists status text default ''published''::text", "do $$ begin\n  if not exists (select 1 from pg_constraint c join pg_class cl on cl.oid=c.conrelid\n                 where cl.relname=''community_posts'' and c.conname=''community_posts_author_idem_key'') then\n    alter table public.community_posts add constraint community_posts_author_idem_key UNIQUE (author_id, create_idempotency_key);\n  end if;\n  if not exists (select 1 from pg_constraint c join pg_class cl on cl.oid=c.conrelid\n                 where cl.relname=''shortform_posts'' and c.conname=''shortform_posts_author_idem_key'') then\n    alter table public.shortform_posts add constraint shortform_posts_author_idem_key UNIQUE (author_id, create_idempotency_key);\n  end if;\n  if not exists (select 1 from pg_constraint c join pg_class cl on cl.oid=c.conrelid\n                 where cl.relname=''community_posts'' and c.conname=''community_posts_status_check'') then\n    alter table public.community_posts add constraint community_posts_status_check CHECK ((status = ANY (ARRAY[''draft''::text, ''published''::text, ''hidden''::text, ''deleted''::text])));\n  end if;\nend $$", "-- >>> NATIVE_BASELINE_PART 0154 | supabase/sql/147_p2_2_community_board_idempotency_softdelete.sql | 147_p2_2_community_board_idempotency_softdelete.sql <<<\n-- 147_p2_2_community_board_idempotency_softdelete.sql\n-- Phase 2-2 게시판: 중복 방지(create_idempotency_key)·soft-delete(deleted_at) 정본 수렴.\n--\n-- 배경: staging(lbeqxarxothkmzqvpudy)에는 아래 구조가 이전 세션에서 out-of-band 로 이미 적용돼 있으나\n--   저장소 SQL 파일에는 없었다(계보 공백). 이 파일은 그 구조를 정본화한다 —\n--   전부 IF NOT EXISTS 라 staging 에는 no-op, 신규 DB 에는 동일 구조를 재현한다.\n--\n-- 계약:\n--   * create_idempotency_key: nullable uuid. 클라 요청 UUID. NULL 은 \"키 없음\"(중복검사 제외).\n--   * (author_id, create_idempotency_key) UNIQUE — 동일 작성자+동일 키 재삽입 차단.\n--     NULL 은 서로 distinct 하므로 키 없는 삽입은 자유(레거시 호환).\n--   * deleted_at: soft-delete 신호. NOT NULL = 삭제됨. hard DELETE 대신 이 컬럼으로만 삭제.\n--     상태 CHECK(status)는 건드리지 않는다(status=''deleted'' 미사용 — deleted_at 이 정본 신호).\n-- 선행: 037.\n\nbegin", "alter table public.community_posts add column if not exists create_idempotency_key uuid", "alter table public.community_posts add column if not exists deleted_at timestamptz", "-- 동일 작성자+동일 요청키 중복 삽입 차단(ON CONFLICT 타깃). NULL 키는 충돌하지 않음.\ncreate unique index if not exists community_posts_author_idem_key\n  on public.community_posts (author_id, create_idempotency_key)", "-- 활성(미삭제) 목록 조회 가속.\ncreate index if not exists idx_cp_active_created\n  on public.community_posts (created_at desc) where deleted_at is null", "commit", "-- §V(rollback-only): create_idempotency_key·deleted_at 존재 · (author_id,create_idempotency_key) UNIQUE ·\n--   동일 키 재삽입은 UNIQUE 위반(23505) → 웹은 ON CONFLICT 로 기존 행 반환 · NULL 키 다중 삽입 허용 ·\n--   deleted_at 세팅 후 활성 목록에서 제외 · 행은 보존(관리자 감사).\n\n-- >>> NATIVE_BASELINE_PART 0155 | supabase/sql/148_p2_3_shortform_idempotency.sql | 148_p2_3_shortform_idempotency.sql <<<\n-- 148_p2_3_shortform_idempotency.sql\n-- Phase 2-3 숏폼: 중복 업로드 방지(create_idempotency_key) 정본 수렴.\n--\n-- 배경: staging 에 create_idempotency_key + (author_id, create_idempotency_key) UNIQUE 가\n--   out-of-band 로 이미 적용돼 있으나 저장소 SQL 에는 없었다(계보 공백). 정본화 — IF NOT EXISTS 라\n--   staging no-op, 신규 DB 재현.\n-- 계약: 요청 UUID 로 더블클릭·재시도에도 1행. NULL 키는 서로 distinct(레거시 무검사 허용).\n-- 선행: 038.\n\nbegin", "alter table public.shortform_posts add column if not exists create_idempotency_key uuid", "create unique index if not exists shortform_posts_author_idem_key\n  on public.shortform_posts (author_id, create_idempotency_key)", "commit", "-- §V(rollback-only): create_idempotency_key 존재 · (author_id,create_idempotency_key) UNIQUE ·\n--   동일 키 재삽입 23505 → 웹 ON CONFLICT 로 기존 행 반환 · NULL 키 다중 삽입 허용.\n\n-- >>> NATIVE_BASELINE_PART 0156 | supabase/sql/149_p1_8a_storage_insert_eligibility.sql | 149_p1_8a_storage_insert_eligibility.sql <<<\n-- 149_p1_8a_storage_insert_eligibility.sql\n-- Phase 1 후속(비차단) — 질문 첨부 Storage INSERT 자체에 자격 게이트 추가.\n--\n-- 문제: 등록 RPC(qna_register_attachment)가 자격을 최종 강제하지만, 등록 전 객체는 inert 라도\n--   공격자가 등록을 호출하지 않고 Storage 에 업로드만 반복해 quota 를 소모할 수 있다(141 정책은\n--   party·thread-writable·계정/승인/차단만 검사, 구독/무료·환불 자격은 미검사).\n-- 해결: Storage INSERT with_check 에 \"가능한 범위의\" 자격 게이트를 추가한다.\n--   * 학생 업로더: (활성 구독 && 해당 구독 pending 환불 없음) 또는 (구독 없음 && 경로의 thread 가\n--     이 학생의 무료질문 스레드) 일 때만 허용.\n--   * 멘토 업로더: 구독/환불 게이트 미적용(자격은 141 qra_uploader_allowed_for_path 의 승인·party 로 확인).\n-- RLS with_check 는 잠금 불가 → 비잠금 존재검사(best-effort). 최종 원자 잠금·환불검사는 등록 RPC 가 담당.\n-- 141/142 미수정. 선행: 049·141·142·136.\n\nbegin", "set local lock_timeout=''5s''", "create or replace function public.qra_path_upload_eligible(p_name text)\nreturns boolean language plpgsql stable security definer set search_path to ''public'' as $$\ndeclare\n  v_uid uuid := auth.uid(); v_room uuid; v_thread uuid; v_student uuid; v_mentor uuid; v_sub_id uuid;\nbegin\n  if v_uid is null then return false; end if;\n  v_room := public.qra_room_uuid_from_path(p_name);\n  begin\n    v_thread := nullif(split_part(p_name, ''/'', 2), '''')::uuid;\n  exception when others then\n    return false;\n  end;\n  if v_room is null or v_thread is null then return false; end if;\n\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = v_room;\n  if v_student is null then return false; end if;\n\n  -- 멘토 업로더: 구독/무료/환불 게이트 미적용(다른 conjunct 가 승인·party 를 강제).\n  if v_uid = v_mentor then return true; end if;\n  if v_uid <> v_student then return false; end if;\n\n  -- 경로의 thread 가 이 room 소속이어야 한다(임의 thread 세그먼트 위조 차단).\n  if not exists (\n    select 1 from public.question_threads t where t.id = v_thread and t.mentor_student_room_id = v_room\n  ) then\n    return false;\n  end if;\n\n  -- 활성 구독 경로: 해당 구독에 live pending 환불이 없어야 자격(142 helper 재사용, current-event 기준).\n  select id into v_sub_id from public.subscriptions\n    where student_id = v_student and mentor_id = v_mentor and lower(coalesce(status,'''')) = ''active'' limit 1;\n  if v_sub_id is not null then\n    return not public.qna_subscription_has_live_refund(v_sub_id);\n  end if;\n\n  -- 구독 없음 → 경로의 thread 가 이 학생의 무료질문 스레드일 때만 자격.\n  return exists (\n    select 1 from public.free_question_usage f where f.thread_id = v_thread and f.student_id = v_student\n  );\nend; $$", "revoke all on function public.qra_path_upload_eligible(text) from public, anon", "grant execute on function public.qra_path_upload_eligible(text) to authenticated, service_role", "-- Storage INSERT 정책에 자격 conjunct 추가(141 정책 재정의 — party·writable·uploader-allowed 유지 + eligibility).\ndrop policy if exists qra_storage_insert_party on storage.objects", "create policy qra_storage_insert_party on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = ''question-room-attachments''\n    and public.user_is_room_party_for_qra_path(name)\n    and public.qra_thread_writable_for_path(name)\n    and public.qra_uploader_allowed_for_path(name)\n    and public.qra_path_upload_eligible(name)\n  )", "commit", "-- §V(rollback-only): 활성구독+환불없음 학생 업로드 허용 · pending 환불 시 학생 업로드 거부 ·\n--   구독 없고 무료 스레드면 허용 · 구독 없고 무료 아님/타 thread 위조면 거부 · 멘토 업로드 무영향.\n\n-- >>> NATIVE_BASELINE_PART 0157 | supabase/sql/150_p1_13_refund_billing_event_fk.sql | 150_p1_13_refund_billing_event_fk.sql <<<\n-- 150_p1_13_refund_billing_event_fk.sql\n-- Phase 1 후속 — refund ↔ billing event 정본 연결(FK) + 질문 자격 게이트를 current billing event 기준으로.\n--\n-- 배경: refunds 는 지금 subscription_id + request_type + 복사된 payment_id 로만 구독에 연결되고,\n--   어느 billing event(구독 결제 주기)에 대한 환불인지 명시 FK 가 없다.\n-- 변경:\n--   * refunds.billing_event_id uuid FK → subscription_billing_events(id) ON DELETE SET NULL.\n--   * 신규 refund 생성 경로(웹)가 current subscriptions.last_billing_event_id 를 기록한다(코드 측 배선).\n--   * qna_subscription_has_live_refund 를 current billing event 기준으로 정밀화:\n--       billing_event_id 가 있으면 그 값이 구독의 current last_billing_event_id 와 일치하는 pending 만 카운트,\n--       billing_event_id 가 NULL(레거시)이면 안전하게 여전히 카운트(추정 백필 금지 — 막는 쪽이 안전).\n-- 기존 실제 행 추정 백필 금지. staging refunds=0행(신규 컬럼 안전). 선행: 064·069·142.\n\nbegin", "set local lock_timeout=''5s''", "alter table public.refunds add column if not exists billing_event_id uuid", "do $$\nbegin\n  if not exists (\n    select 1 from pg_constraint where conname = ''refunds_billing_event_id_fkey'' and conrelid = ''public.refunds''::regclass\n  ) then\n    alter table public.refunds\n      add constraint refunds_billing_event_id_fkey\n      foreign key (billing_event_id) references public.subscription_billing_events(id) on delete set null;\n  end if;\nend $$", "create index if not exists idx_refunds_billing_event on public.refunds (billing_event_id) where billing_event_id is not null", "-- current billing event 기준 pending 환불 잠금(142 helper 정밀화 — 142 미수정, create or replace).\ncreate or replace function public.qna_subscription_has_live_refund(p_subscription_id uuid)\nreturns boolean language sql stable security definer set search_path to ''public'' as $$\n  select exists (\n    select 1\n    from public.refunds r\n    join public.subscriptions s on s.id = r.subscription_id\n    where r.subscription_id = p_subscription_id\n      and r.status = ''pending''\n      and r.request_type in (''subscription_prorated'',''subscription_mentor_suspended'')\n      -- 신규 행: current billing event 에 대한 환불만 자격을 막는다.\n      -- 레거시(billing_event_id NULL): 추정 없이 안전하게 계속 막는다.\n      and (r.billing_event_id is null or r.billing_event_id = s.last_billing_event_id)\n  );\n$$", "revoke all on function public.qna_subscription_has_live_refund(uuid) from public, anon", "grant execute on function public.qna_subscription_has_live_refund(uuid) to authenticated, service_role", "commit", "-- §진단(production 배포 전 실행 — NULL 레거시 refund 행 파악, 자동 백필 금지):\n--   select id, subscription_id, request_type, status, created_at\n--   from public.refunds\n--   where billing_event_id is null and request_type in (''subscription_prorated'',''subscription_mentor_suspended'')\n--   order by created_at desc;\n--\n-- §V(rollback-only): refunds.billing_event_id FK 존재 · 신규 pending 환불이 current event 이면 게이트 막음 ·\n--   다른(과거) event 의 pending 은 current 질문 자격을 막지 않음 · NULL 레거시는 안전하게 계속 막음.\n\n-- >>> NATIVE_BASELINE_PART 0158 | supabase/sql/151_p1_10_account_deletion_saga.sql | 151_p1_10_account_deletion_saga.sql <<<\n-- 151_p1_10_account_deletion_saga.sql\n-- ⚠️ 라이브 미적용 대비 — 기능 플래그 OFF 기본. 실제 사용자·객체 삭제 없음. 신규 객체만 추가.\n-- P1-10 회원탈퇴 saga 기반 + write gate + P2-22 effective status helper.\n--\n-- 상태기계: pending → locked → purging → storage_purged → finalized → auth_soft_deleted → completed\n--   (+ canceled / failed). pending 만 취소 가능(cancelable_until 이내). purging 이후 취소 금지.\n--   locked→purging 은 조건부 원자 전이. attempts·last_error·next_attempt_at(backoff).\n-- write gate: state 가 locked 이상(취소 불가 시점)이면 해당 유저의 핵심 write 를 차단.\n--   0 job 이면 항상 false → 무영향(기능 OFF 안전). 최종 삭제는 worker(dry-run 기본)가 수행.\n-- 선행: 001(users), 115(anonymize). 037/038/149 storage 정책 재정의(deletion conjunct 추가).\n\nbegin", "set local lock_timeout=''5s''", "-- ── 1) saga 작업 테이블 (service_role 전용) ──────────────────────────────────\ncreate table if not exists public.account_deletion_jobs (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null unique references public.users (id),\n  state text not null default ''pending''\n    check (state in (''pending'',''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted'',''completed'',''canceled'',''failed'')),\n  attempts int not null default 0,\n  last_error text,\n  next_attempt_at timestamptz,\n  cancelable_until timestamptz,\n  dry_run boolean not null default true,\n  requested_at timestamptz not null default now(),\n  locked_at timestamptz, purging_at timestamptz, storage_purged_at timestamptz,\n  finalized_at timestamptz, auth_soft_deleted_at timestamptz, completed_at timestamptz,\n  canceled_at timestamptz, failed_at timestamptz,\n  updated_at timestamptz not null default now()\n)", "comment on table public.account_deletion_jobs is\n  ''151: 회원탈퇴 saga 상태기계. service_role 전용. 기능 플래그 OFF 기본 — 0행이면 write gate 무영향.''", "alter table public.account_deletion_jobs enable row level security", "revoke all on public.account_deletion_jobs from public, anon, authenticated", "grant select, insert, update on public.account_deletion_jobs to service_role", "create index if not exists idx_adj_state_next on public.account_deletion_jobs (state, next_attempt_at)", "-- ── 2) write gate helper + 트리거 ───────────────────────────────────────────\n-- locked 이상(취소 불가) & 미완료 상태면 차단. pending(취소 가능)·completed/canceled/failed 는 허용.\ncreate or replace function public.account_deletion_write_blocked(p_user_id uuid)\nreturns boolean language sql stable security definer set search_path to ''public'' as $$\n  select exists (\n    select 1 from public.account_deletion_jobs j\n    where j.user_id = p_user_id\n      and j.state in (''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted'')\n  );\n$$", "revoke all on function public.account_deletion_write_blocked(uuid) from public, anon", "grant execute on function public.account_deletion_write_blocked(uuid) to authenticated, service_role", "-- 범용 BEFORE INSERT/UPDATE 가드: TG_ARGV[0]=유저 컬럼명. 값이 차단 대상이면 거부.\ncreate or replace function public.account_deletion_write_guard()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_col text := TG_ARGV[0]; v_uid uuid;\nbegin\n  v_uid := (to_jsonb(NEW) ->> v_col)::uuid;\n  if v_uid is not null and public.account_deletion_write_blocked(v_uid) then\n    raise exception ''ACCOUNT_DELETION_IN_PROGRESS'';\n  end if;\n  return NEW;\nend $$", "-- 핵심 테이블(지갑·결제·질문·커뮤니티)에 가드 부착. 0 job 이면 무영향.\ndrop trigger if exists adg_cash_wallets on public.cash_wallets", "create trigger adg_cash_wallets before insert or update on public.cash_wallets\n  for each row execute function public.account_deletion_write_guard(''user_id'')", "drop trigger if exists adg_cash_ledger on public.cash_ledger", "create trigger adg_cash_ledger before insert on public.cash_ledger\n  for each row execute function public.account_deletion_write_guard(''user_id'')", "drop trigger if exists adg_payments on public.payments", "create trigger adg_payments before insert on public.payments\n  for each row execute function public.account_deletion_write_guard(''user_id'')", "drop trigger if exists adg_question_messages on public.question_messages", "create trigger adg_question_messages before insert on public.question_messages\n  for each row execute function public.account_deletion_write_guard(''author_id'')", "drop trigger if exists adg_community_posts on public.community_posts", "create trigger adg_community_posts before insert on public.community_posts\n  for each row execute function public.account_deletion_write_guard(''author_id'')", "drop trigger if exists adg_shortform_posts on public.shortform_posts", "create trigger adg_shortform_posts before insert on public.shortform_posts\n  for each row execute function public.account_deletion_write_guard(''author_id'')", "-- Storage INSERT gate(내가 관리하는 버킷 정책에 deletion conjunct 추가 — 0 job 무영향).\ndrop policy if exists qra_storage_insert_party on storage.objects", "create policy qra_storage_insert_party on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = ''question-room-attachments''\n    and public.user_is_room_party_for_qra_path(name)\n    and public.qra_thread_writable_for_path(name)\n    and public.qra_uploader_allowed_for_path(name)\n    and public.qra_path_upload_eligible(name)\n    and not public.account_deletion_write_blocked(auth.uid())\n  )", "drop policy if exists \"cpi_auth_insert_own\" on storage.objects", "create policy \"cpi_auth_insert_own\" on storage.objects for insert to authenticated\n  with check (\n    bucket_id = ''community-post-images''\n    and (storage.foldername(name))[1] = (select auth.uid())::text\n    and not public.account_deletion_write_blocked(auth.uid())\n  )", "drop policy if exists \"sfv_mentor_insert\" on storage.objects", "create policy \"sfv_mentor_insert\" on storage.objects for insert to authenticated\n  with check (\n    bucket_id in (''shortform-videos'', ''shortform-thumbnails'')\n    and public.is_mentor()\n    and (storage.foldername(name))[1] = (select auth.uid())::text\n    and not public.account_deletion_write_blocked(auth.uid())\n  )", "-- ── 3) 상태기계 RPC (service_role 전용) ─────────────────────────────────────\ncreate or replace function public.account_deletion_request(p_user_id uuid, p_cancelable_minutes int default 30, p_dry_run boolean default true)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_id uuid; v_state text;\nbegin\n  select id, state into v_id, v_state from public.account_deletion_jobs where user_id = p_user_id;\n  if v_id is not null then\n    return jsonb_build_object(''ok'',true,''existing'',true,''job_id'',v_id,''state'',v_state);\n  end if;\n  insert into public.account_deletion_jobs (user_id, state, cancelable_until, dry_run)\n    values (p_user_id, ''pending'', now() + make_interval(mins => greatest(0,p_cancelable_minutes)), coalesce(p_dry_run,true))\n    returning id into v_id;\n  return jsonb_build_object(''ok'',true,''existing'',false,''job_id'',v_id,''state'',''pending'');\nend $$", "create or replace function public.account_deletion_cancel(p_user_id uuid)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_state text; v_cancelable timestamptz;\nbegin\n  select state, cancelable_until into v_state, v_cancelable\n    from public.account_deletion_jobs where user_id = p_user_id for update;\n  if not found then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n  -- purging 이후(=pending 아님) 취소 금지.\n  if v_state <> ''pending'' then return jsonb_build_object(''ok'',false,''code'',''NOT_CANCELABLE'',''state'',v_state); end if;\n  if v_cancelable is not null and now() > v_cancelable then return jsonb_build_object(''ok'',false,''code'',''CANCEL_WINDOW_PASSED''); end if;\n  update public.account_deletion_jobs set state=''canceled'', canceled_at=now(), updated_at=now() where user_id=p_user_id;\n  return jsonb_build_object(''ok'',true,''state'',''canceled'');\nend $$", "-- 조건부 원자 전이(from→to). 유효 전이만 허용. locked→purging 등.\ncreate or replace function public.account_deletion_advance(p_user_id uuid, p_from text, p_to text)\nreturns boolean language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_rows int := 0; v_col text;\nbegin\n  -- pending→locked 은 cancelable_until 경과 후에만(취소 기회 보장).\n  if p_from=''pending'' and p_to=''locked'' then\n    update public.account_deletion_jobs\n      set state=''locked'', locked_at=now(), updated_at=now()\n      where user_id=p_user_id and state=''pending'' and (cancelable_until is null or now() >= cancelable_until);\n    get diagnostics v_rows = row_count;\n    return v_rows > 0;\n  end if;\n  -- 유효 전이표.\n  if not (\n    (p_from=''locked'' and p_to=''purging'') or\n    (p_from=''purging'' and p_to=''storage_purged'') or\n    (p_from=''storage_purged'' and p_to=''finalized'') or\n    (p_from=''finalized'' and p_to=''auth_soft_deleted'') or\n    (p_from=''auth_soft_deleted'' and p_to=''completed'')\n  ) then\n    raise exception ''INVALID_TRANSITION % -> %'', p_from, p_to;\n  end if;\n  v_col := p_to || ''_at'';\n  execute format(\n    ''update public.account_deletion_jobs set state=$2, %I=now(), updated_at=now() where user_id=$1 and state=$3'',\n    v_col\n  ) using p_user_id, p_to, p_from;\n  get diagnostics v_rows = row_count;\n  return v_rows > 0;\nend $$", "create or replace function public.account_deletion_record_error(p_user_id uuid, p_error text, p_backoff_seconds int default 60, p_max_attempts int default 8)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_attempts int;\nbegin\n  update public.account_deletion_jobs\n    set attempts = attempts + 1, last_error = left(coalesce(p_error,''''),1000),\n        next_attempt_at = now() + make_interval(secs => greatest(1,p_backoff_seconds)), updated_at = now()\n    where user_id = p_user_id\n    returning attempts into v_attempts;\n  if v_attempts is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n  if v_attempts >= p_max_attempts then\n    update public.account_deletion_jobs set state=''failed'', failed_at=now(), updated_at=now() where user_id=p_user_id;\n    return jsonb_build_object(''ok'',true,''state'',''failed'',''attempts'',v_attempts);\n  end if;\n  return jsonb_build_object(''ok'',true,''attempts'',v_attempts);\nend $$", "-- worker claim: 처리 대상(취소불가·미완료·backoff 경과) 을 SKIP LOCKED 로 집는다.\ncreate or replace function public.account_deletion_worker_claim(p_limit int default 10)\nreturns setof public.account_deletion_jobs language sql security definer set search_path to ''public'' as $$\n  select * from public.account_deletion_jobs\n  where state in (''pending'',''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted'')\n    and (next_attempt_at is null or next_attempt_at <= now())\n  order by requested_at asc\n  limit greatest(1, p_limit)\n  for update skip locked;\n$$", "revoke all on function public.account_deletion_request(uuid,int,boolean) from public, anon, authenticated", "revoke all on function public.account_deletion_cancel(uuid) from public, anon, authenticated", "revoke all on function public.account_deletion_advance(uuid,text,text) from public, anon, authenticated", "revoke all on function public.account_deletion_record_error(uuid,text,int,int) from public, anon, authenticated", "revoke all on function public.account_deletion_worker_claim(int) from public, anon, authenticated", "grant execute on function public.account_deletion_request(uuid,int,boolean) to service_role", "grant execute on function public.account_deletion_cancel(uuid) to service_role", "grant execute on function public.account_deletion_advance(uuid,text,text) to service_role", "grant execute on function public.account_deletion_record_error(uuid,text,int,int) to service_role", "grant execute on function public.account_deletion_worker_claim(int) to service_role", "commit", "-- §V(rollback-only): request→pending(취소가능) · cancel(pending·window내) 성공 · locked 이후 cancel 거부 ·\n--   pending→locked 은 cancelable_until 경과 후만 · locked→purging 원자 · write gate: locked 유저 지갑/결제/\n--   질문/커뮤니티 INSERT 거부, 정상 유저·0job 허용 · storage_purged 전 finalized 금지(전이표) · advance 멱등(중복 no-op).\n\n-- >>> NATIVE_BASELINE_PART 0159 | supabase/sql/152_p1_11c_notification_delivery_worker.sql | 152_p1_11c_notification_delivery_worker.sql <<<\n-- 152_p1_11c_notification_delivery_worker.sql\n-- P1-11C outbox delivery worker 기반 + P2-17 알림 설정. 실제 FCM 발송 없음(worker 는 dry-run transport).\n--\n-- 신규: device_tokens(유저 소유·RLS) · notification_deliveries(토큰별·service_role, UNIQUE(outbox_id,device_token_id))\n--   · notification_settings(유저 소유·RLS) · claim/lease/backoff/dead-letter/설정강제 RPC.\n-- 132(notification_outbox) 미수정. 선행: 001(users)·132.\n\nbegin", "set local lock_timeout=''5s''", "-- ── device_tokens (유저 소유 · RLS) ─────────────────────────────────────────\ncreate table if not exists public.device_tokens (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users(id) on delete cascade,\n  token text not null unique,\n  platform text not null default ''unknown'' check (platform in (''ios'',''android'',''web'',''unknown'')),\n  revoked_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)", "create index if not exists idx_device_tokens_user on public.device_tokens (user_id) where revoked_at is null", "alter table public.device_tokens enable row level security", "revoke all on public.device_tokens from anon", "-- 본인 토큰만 조회/관리. 재소유(계정 전환)는 SECURITY DEFINER RPC 로.\ndrop policy if exists device_tokens_select_own on public.device_tokens", "create policy device_tokens_select_own on public.device_tokens for select to authenticated using (user_id = (select auth.uid()))", "drop policy if exists device_tokens_modify_own on public.device_tokens", "create policy device_tokens_modify_own on public.device_tokens for all to authenticated\n  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()))", "grant select, insert, update, delete on public.device_tokens to authenticated, service_role", "-- 토큰 등록/재소유: 동일 기기 계정 전환 시 token 을 새 유저가 넘겨받는다(revoked 해제).\ncreate or replace function public.register_device_token(p_token text, p_platform text default ''unknown'')\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_uid uuid := auth.uid(); v_id uuid; v_plat text;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_token is null or btrim(p_token)='''' then raise exception ''TOKEN_REQUIRED''; end if;\n  v_plat := case when p_platform in (''ios'',''android'',''web'') then p_platform else ''unknown'' end;\n  insert into public.device_tokens (user_id, token, platform)\n    values (v_uid, btrim(p_token), v_plat)\n  on conflict (token) do update set user_id = v_uid, platform = v_plat, revoked_at = null, updated_at = now()\n  returning id into v_id;\n  return jsonb_build_object(''ok'', true, ''device_token_id'', v_id);\nend $$", "revoke all on function public.register_device_token(text,text) from public, anon", "grant execute on function public.register_device_token(text,text) to authenticated, service_role", "create or replace function public.revoke_device_token(p_device_token_id uuid)\nreturns boolean language sql security definer set search_path to ''public'' as $$\n  update public.device_tokens set revoked_at = now(), updated_at = now()\n  where id = p_device_token_id and revoked_at is null returning true;\n$$", "revoke all on function public.revoke_device_token(uuid) from public, anon, authenticated", "grant execute on function public.revoke_device_token(uuid) to service_role", "-- ── notification_settings (유저 소유 · RLS · P2-17) ─────────────────────────\n-- groups: event group(qna/order/subscription/refund/system)별 on/off. 미기재 그룹은 기본 on.\ncreate table if not exists public.notification_settings (\n  user_id uuid primary key references public.users(id) on delete cascade,\n  push_enabled boolean not null default true,\n  groups jsonb not null default ''{}''::jsonb,\n  updated_at timestamptz not null default now()\n)", "alter table public.notification_settings enable row level security", "revoke all on public.notification_settings from anon", "drop policy if exists notif_settings_select_own on public.notification_settings", "create policy notif_settings_select_own on public.notification_settings for select to authenticated using (user_id = (select auth.uid()))", "drop policy if exists notif_settings_modify_own on public.notification_settings", "create policy notif_settings_modify_own on public.notification_settings for all to authenticated\n  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()))", "grant select, insert, update on public.notification_settings to authenticated, service_role", "-- event_type → group 매핑(웹 notificationCategories 와 정합).\ncreate or replace function public.notification_event_group(p_event_type text)\nreturns text language sql immutable set search_path to ''public'' as $$\n  select case\n    when p_event_type like ''question_%'' or p_event_type like ''qna_%'' or p_event_type like ''connection_note%'' then ''qna''\n    when p_event_type like ''custom_%'' or p_event_type like ''order_%'' or p_event_type like ''individual_question%'' then ''order''\n    when p_event_type like ''%subscription%'' then ''subscription''\n    when p_event_type like ''%refund%'' then ''refund''\n    else ''system''\n  end;\n$$", "-- 설정 강제: push_enabled && 해당 그룹 off 아님. 설정행 없으면 기본 전부 허용.\ncreate or replace function public.notification_delivery_allowed(p_user_id uuid, p_event_type text)\nreturns boolean language sql stable security definer set search_path to ''public'' as $$\n  select coalesce(\n    (select s.push_enabled and coalesce((s.groups ->> public.notification_event_group(p_event_type))::boolean, true)\n       from public.notification_settings s where s.user_id = p_user_id),\n    true\n  );\n$$", "revoke all on function public.notification_delivery_allowed(uuid,text) from public, anon", "grant execute on function public.notification_delivery_allowed(uuid,text) to authenticated, service_role", "-- ── notification_deliveries (토큰별 · service_role) ─────────────────────────\ncreate table if not exists public.notification_deliveries (\n  id uuid primary key default gen_random_uuid(),\n  outbox_id uuid not null references public.notification_outbox(id) on delete cascade,\n  device_token_id uuid not null references public.device_tokens(id) on delete cascade,\n  status text not null default ''pending'' check (status in (''pending'',''sent'',''failed'',''dead'',''skipped'')),\n  attempt_count int not null default 0,\n  last_error text,\n  sent_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint notification_deliveries_uq unique (outbox_id, device_token_id)\n)", "create index if not exists idx_notif_deliveries_outbox on public.notification_deliveries (outbox_id)", "alter table public.notification_deliveries enable row level security", "revoke all on public.notification_deliveries from anon, authenticated", "grant select, insert, update, delete on public.notification_deliveries to service_role", "-- ── worker RPC ──────────────────────────────────────────────────────────────\n-- claim: pending/failed & next_attempt_at 도래분을 원자적으로 leased 로(SKIP LOCKED).\ncreate or replace function public.notification_outbox_claim(p_owner text, p_limit int default 10, p_lease_seconds int default 60)\nreturns setof public.notification_outbox language plpgsql security definer set search_path to ''public'' as $$\nbegin\n  return query\n  with cte as (\n    select o.id from public.notification_outbox o\n    where o.status in (''pending'',''failed'') and o.next_attempt_at <= now()\n    order by o.next_attempt_at asc\n    limit greatest(1, p_limit)\n    for update skip locked\n  )\n  update public.notification_outbox o\n    set status=''leased'', lease_owner=p_owner, leased_until=now() + make_interval(secs => greatest(1,p_lease_seconds)), updated_at=now()\n    from cte where o.id = cte.id\n    returning o.*;\nend $$", "-- lease 만료 회수: leased 인데 leased_until 경과 → pending 복귀.\ncreate or replace function public.notification_outbox_reclaim_expired()\nreturns int language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_n int;\nbegin\n  update public.notification_outbox set status=''pending'', lease_owner=null, leased_until=null, updated_at=now()\n    where status=''leased'' and leased_until is not null and leased_until < now();\n  get diagnostics v_n = row_count;\n  return v_n;\nend $$", "create or replace function public.notification_outbox_mark_sent(p_id uuid)\nreturns boolean language sql security definer set search_path to ''public'' as $$\n  update public.notification_outbox set status=''sent'', lease_owner=null, leased_until=null, updated_at=now()\n  where id=p_id returning true;\n$$", "-- 실패: attempt++·backoff. max 도달 시 dead-letter.\ncreate or replace function public.notification_outbox_mark_failed(p_id uuid, p_error text, p_backoff_seconds int default 60)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_attempt int; v_max int; v_dead boolean;\nbegin\n  update public.notification_outbox\n    set attempt_count = attempt_count + 1, last_error = left(coalesce(p_error,''''),1000),\n        lease_owner=null, leased_until=null,\n        next_attempt_at = now() + make_interval(secs => greatest(1,p_backoff_seconds)), updated_at=now()\n    where id=p_id\n    returning attempt_count, max_attempts into v_attempt, v_max;\n  if v_attempt is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n  v_dead := v_attempt >= v_max;\n  update public.notification_outbox set status = case when v_dead then ''dead'' else ''failed'' end where id=p_id;\n  return jsonb_build_object(''ok'',true,''attempt'',v_attempt,''dead'',v_dead);\nend $$", "-- 수신자 활성 토큰 × 설정 허용 → delivery fan-out(멱등 UNIQUE). 반환: 생성/스킵 수.\ncreate or replace function public.notification_create_deliveries(p_outbox_id uuid)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_recipient uuid; v_etype text; v_allowed boolean; v_created int := 0;\nbegin\n  select recipient_user_id, event_type into v_recipient, v_etype from public.notification_outbox where id=p_outbox_id;\n  if v_recipient is null then return jsonb_build_object(''ok'',false,''code'',''OUTBOX_NOT_FOUND''); end if;\n  v_allowed := public.notification_delivery_allowed(v_recipient, v_etype);\n  if not v_allowed then\n    return jsonb_build_object(''ok'',true,''created'',0,''suppressed'',true);\n  end if;\n  insert into public.notification_deliveries (outbox_id, device_token_id)\n    select p_outbox_id, dt.id from public.device_tokens dt\n    where dt.user_id = v_recipient and dt.revoked_at is null\n  on conflict (outbox_id, device_token_id) do nothing;\n  get diagnostics v_created = row_count;\n  return jsonb_build_object(''ok'',true,''created'',v_created,''suppressed'',false);\nend $$", "create or replace function public.notification_delivery_mark_sent(p_id uuid)\nreturns boolean language sql security definer set search_path to ''public'' as $$\n  update public.notification_deliveries set status=''sent'', sent_at=now(), updated_at=now() where id=p_id returning true;\n$$", "-- delivery 실패: attempt++. invalid token 이면 토큰 revoke + status=''dead''(재시도 무의미).\ncreate or replace function public.notification_delivery_mark_failed(p_id uuid, p_error text, p_invalid_token boolean default false)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_token_id uuid;\nbegin\n  update public.notification_deliveries\n    set attempt_count = attempt_count + 1, last_error = left(coalesce(p_error,''''),1000),\n        status = case when p_invalid_token then ''dead'' else ''failed'' end, updated_at=now()\n    where id=p_id returning device_token_id into v_token_id;\n  if v_token_id is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n  if p_invalid_token then perform public.revoke_device_token(v_token_id); end if;\n  return jsonb_build_object(''ok'',true,''invalid_token'',p_invalid_token);\nend $$", "revoke all on function public.notification_outbox_claim(text,int,int) from public, anon, authenticated", "revoke all on function public.notification_outbox_reclaim_expired() from public, anon, authenticated", "revoke all on function public.notification_outbox_mark_sent(uuid) from public, anon, authenticated", "revoke all on function public.notification_outbox_mark_failed(uuid,text,int) from public, anon, authenticated", "revoke all on function public.notification_create_deliveries(uuid) from public, anon, authenticated", "revoke all on function public.notification_delivery_mark_sent(uuid) from public, anon, authenticated", "revoke all on function public.notification_delivery_mark_failed(uuid,text,boolean) from public, anon, authenticated", "grant execute on function public.notification_outbox_claim(text,int,int) to service_role", "grant execute on function public.notification_outbox_reclaim_expired() to service_role", "grant execute on function public.notification_outbox_mark_sent(uuid) to service_role", "grant execute on function public.notification_outbox_mark_failed(uuid,text,int) to service_role", "grant execute on function public.notification_create_deliveries(uuid) to service_role", "grant execute on function public.notification_delivery_mark_sent(uuid) to service_role", "grant execute on function public.notification_delivery_mark_failed(uuid,text,boolean) to service_role", "commit", "-- §V(rollback-only): claim 은 pending/도래분만 leased(SKIP LOCKED·동시 이중청구 없음) · 만료 lease 회수 ·\n--   mark_failed backoff·max 도달 dead-letter · create_deliveries 는 활성토큰×설정허용 fan-out(멱등 UNIQUE) ·\n--   설정 off 면 suppressed(0 delivery) · invalid token → 토큰 revoke+delivery dead · device_tokens 본인만 RLS ·\n--   register_device_token 재소유(계정 전환).\n\n-- >>> NATIVE_BASELINE_PART 0160 | supabase/sql/153_p2_25_pay_due_payouts_convergence.sql | 153_p2_25_pay_due_payouts_convergence.sql <<<\n-- 153_p2_25_pay_due_payouts_convergence.sql\n-- P2-25 내부지갑 지급 스택 수렴 — 108(DRAFT 미적용) 정본화 + 114 원천징수 컬럼 + 전역 UNIQUE.\n--\n-- 배경(staging 실측): payout_runs·payout_run_items·due_payouts·per-run UNIQUE 는 적용됨(out-of-band).\n--   그러나 108 RPC(pay_due_payouts_for_run) 미적용, 114 원천징수 컬럼(withholding/net) 미적용,\n--   전역 (source_type,source_id) UNIQUE 미존재. → 이 수렴 파일이 정본.\n-- 결함 수정(108 대비):\n--   (1) 전역 UNIQUE(source_type,source_id) — 다른 배치 재실행에도 동일 source 이중지급 불가.\n--   (2) ON CONFLICT (source_type,source_id) + RETURNING id INTO v_item_id — 실제 신규 행일 때만.\n--   (3) 신규 성공행만 합계(v_paid/v_total) 반영 — 기존 108 은 conflict(중복)에도 카운트 증가하는 버그.\n--   (4) p_dry_run(기본 true) — 돈 이동 0(원장·지갑·상태·행 삽입 없음), 예상 지급건·합계만 산출.\n--   (5) 원천징수 3.3% 컬럼 스냅샷(net_paid_cents) — 적립 후 공제 라인으로 순액화(append-only 원장).\n-- scheduler 는 기본 OFF(이 RPC 는 배치 프리미티브일 뿐 — cron 미설정. 실행은 명시 호출).\n-- payout_run_items staging 0행(전역 UNIQUE 안전). 105/106/107/109/110/111/114 정의는 무수정.\n-- 선행: 106(payout_runs/items)·107/111(due_payouts)·109/110(primitive)·105(gating).\n\nbegin", "set local lock_timeout=''5s''", "-- (114) 원천징수·실지급 스냅샷 컬럼(불변 원장성 추적).\nalter table public.payout_run_items add column if not exists withholding_cents bigint not null default 0", "alter table public.payout_run_items add column if not exists net_paid_cents bigint", "-- (전역 UNIQUE) 동일 source 는 전 배치 통틀어 1회만 지급 스냅샷(다른 배치 재실행 이중지급 차단).\ndo $$\nbegin\n  if not exists (select 1 from pg_constraint where conname=''payout_run_items_source_global_uq'' and conrelid=''public.payout_run_items''::regclass) then\n    alter table public.payout_run_items add constraint payout_run_items_source_global_uq unique (source_type, source_id);\n  end if;\nend $$", "create or replace function public.pay_due_payouts_for_run(\n  p_run_date date,\n  p_idempotency_key text default null,\n  p_dry_run boolean default true\n)\nreturns table (\n  run_id uuid,\n  paid_count integer,\n  skipped_no_account integer,\n  total_mentor_cents bigint,\n  total_withholding_cents bigint,\n  total_net_cents bigint,\n  dry_run boolean\n)\nlanguage plpgsql security definer set search_path = public\nas $function$\ndeclare\n  v_idem text := coalesce(p_idempotency_key, ''payout:'' || to_char(p_run_date, ''YYYY-MM''));\n  v_cutoff timestamptz := date_trunc(''month'', p_run_date::timestamp) - interval ''1 second'';\n  v_run public.payout_runs%rowtype;\n  v_run_id uuid;\n  rec record;\n  v_ledger_id uuid; v_item_id uuid; v_has_account boolean;\n  v_paid int := 0; v_skipped int := 0;\n  v_total bigint := 0; v_total_wh bigint := 0; v_total_net bigint := 0;\n  v_withholding bigint; v_net bigint; v_wh_ledger_id uuid;\nbegin\n  -- dry-run: 돈 이동·행 삽입 없이 예상 지급건·합계만 계산(run 헤더도 만들지 않음).\n  if not p_dry_run then\n    select * into v_run from public.payout_runs where idempotency_key = v_idem;\n    if found then\n      v_run_id := v_run.id;\n      if v_run.status = ''completed'' then\n        return query select v_run.id, v_run.mentor_count, 0, v_run.total_mentor_cents,\n          coalesce((select sum(withholding_cents) from public.payout_run_items where payout_run_id=v_run.id),0),\n          coalesce((select sum(net_paid_cents) from public.payout_run_items where payout_run_id=v_run.id),0), false;\n        return;\n      end if;\n    else\n      insert into public.payout_runs (run_date, cutoff_end, status, idempotency_key)\n      values (p_run_date, v_cutoff, ''executing'', v_idem) returning id into v_run_id;\n    end if;\n  end if;\n\n  for rec in\n    select d.* from public.due_payouts d\n    where d.completion_ts <= v_cutoff\n      and not exists (select 1 from public.payout_run_items i where i.source_type=d.source_type and i.source_id=d.source_id)\n    order by d.mentor_id, d.source_type, d.completion_ts\n  loop\n    select coalesce(nullif(trim(mp.payout_account_number), ''''), '''') <> '''' into v_has_account\n      from public.mentor_profiles mp where mp.user_id = rec.mentor_id;\n    if coalesce(v_has_account, false) = false then\n      v_skipped := v_skipped + 1; continue;\n    end if;\n\n    v_withholding := floor(rec.mentor_amount_cents::numeric * 0.033)::bigint;\n    v_net := rec.mentor_amount_cents - v_withholding;\n\n    if p_dry_run then\n      -- 예상만 집계(돈 이동·삽입 없음).\n      v_paid := v_paid + 1; v_total := v_total + rec.mentor_amount_cents;\n      v_total_wh := v_total_wh + v_withholding; v_total_net := v_total_net + v_net;\n      continue;\n    end if;\n\n    v_ledger_id := null;\n    if rec.source_type = ''custom_request'' then\n      perform public.record_custom_order_escrow_payout(rec.source_id);\n      select id into v_ledger_id from public.cash_ledger\n        where idempotency_key = ''cr_payout_'' || rec.source_id::text and reason=''custom_order_escrow_payout'' limit 1;\n    elsif rec.source_type = ''individual_question'' then\n      perform public.release_individual_question_payout(rec.source_id);\n      select id into v_ledger_id from public.cash_ledger\n        where idempotency_key = ''iq_payout:'' || rec.source_id::text and reason=''individual_question_payout'' limit 1;\n    elsif rec.source_type = ''subscription'' then\n      insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n      values (rec.mentor_id, rec.mentor_amount_cents, ''subscription_settlement_payout'',\n              ''subscription_settlement_items'', rec.source_id, ''sub_payout:'' || rec.source_id::text)\n      on conflict (idempotency_key) do nothing returning id into v_ledger_id;\n      if v_ledger_id is not null then\n        insert into public.cash_wallets (user_id, balance_cents) values (rec.mentor_id, 0) on conflict (user_id) do nothing;\n        update public.cash_wallets w set balance_cents = w.balance_cents + rec.mentor_amount_cents where w.user_id = rec.mentor_id;\n      else\n        select id into v_ledger_id from public.cash_ledger where idempotency_key=''sub_payout:'' || rec.source_id::text limit 1;\n      end if;\n      update public.subscription_settlement_items set status=''paid'', paid_at=coalesce(paid_at, now()), updated_at=now()\n        where id = rec.source_id and status <> ''paid'';\n    else\n      continue;\n    end if;\n\n    -- 원천징수 3.3%: 적립 후 공제 라인(append-only, 멱등). 신규 라인일 때만 지갑 차감.\n    if v_withholding > 0 then\n      v_wh_ledger_id := null;\n      insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n      values (rec.mentor_id, -v_withholding, ''payout_withholding_3_3pct'', rec.source_type, rec.source_id,\n              ''wh:'' || rec.source_type || '':'' || rec.source_id::text)\n      on conflict (idempotency_key) do nothing returning id into v_wh_ledger_id;\n      if v_wh_ledger_id is not null then\n        update public.cash_wallets w set balance_cents = w.balance_cents - v_withholding where w.user_id = rec.mentor_id;\n      end if;\n    end if;\n\n    -- 불변 스냅샷: 전역 UNIQUE(source_type,source_id) 충돌 시 no-op. RETURNING 으로 신규 여부 판정.\n    insert into public.payout_run_items (\n      payout_run_id, mentor_id, source_type, source_id,\n      gross_cents, platform_fee_cents, mentor_amount_cents, fee_rate, ledger_id,\n      withholding_cents, net_paid_cents\n    ) values (\n      v_run_id, rec.mentor_id, rec.source_type, rec.source_id,\n      rec.gross_cents, rec.platform_fee_cents, rec.mentor_amount_cents, rec.fee_rate, v_ledger_id,\n      v_withholding, v_net\n    )\n    on conflict (source_type, source_id) do nothing\n    returning id into v_item_id;\n\n    -- 신규 성공행일 때만 합계 반영(중복은 카운트/합계 미반영 — 108 버그 수정).\n    if v_item_id is not null then\n      v_paid := v_paid + 1;\n      v_total := v_total + rec.mentor_amount_cents;\n      v_total_wh := v_total_wh + v_withholding;\n      v_total_net := v_total_net + v_net;\n    end if;\n  end loop;\n\n  if not p_dry_run then\n    update public.payout_runs\n    set status=''completed'',\n        mentor_count=(select count(distinct mentor_id) from public.payout_run_items where payout_run_id=v_run_id),\n        total_mentor_cents=(select coalesce(sum(mentor_amount_cents),0) from public.payout_run_items where payout_run_id=v_run_id),\n        executed_at=now(), updated_at=now()\n    where id=v_run_id;\n  end if;\n\n  return query select v_run_id, v_paid, v_skipped, v_total, v_total_wh, v_total_net, p_dry_run;\nend;\n$function$", "revoke all on function public.pay_due_payouts_for_run(date, text, boolean) from public, anon, authenticated", "grant execute on function public.pay_due_payouts_for_run(date, text, boolean) to service_role", "commit", "-- §V(rollback-only): 전역 UNIQUE(source_type,source_id) 존재 · withholding/net 컬럼 존재 ·\n--   동일 source 다른 배치 재삽입 UNIQUE 위반→ON CONFLICT no-op(합계 미반영) · 원천징수=floor(amount*0.033) ·\n--   net=amount-withholding · 0원/홀수 금액 정확 · dry_run=true 는 payout_run_items/원장/지갑 변화 0 ·\n--   신규 성공행만 v_paid/v_total 증가. 독립 2세션 동시성 실측 = CONCURRENCY_DEBT.\n\n-- >>> NATIVE_BASELINE_PART 0161 | supabase/sql/154_p1_10_deletion_operational_adapters.sql | 154_p1_10_deletion_operational_adapters.sql <<<\n-- 154_p1_10_deletion_operational_adapters.sql\n-- ⚠️ 기능 플래그 OFF 기본. 실제 사용자·객체 삭제 없음. 신규 객체만 추가(151/115 무수정).\n-- P1-10 운영 어댑터 완결: (1) Storage write gate 전면화(INSERT/UPDATE/upsert/overwrite/move/copy),\n--   (2) job lease/claim(동시 worker 중복 처리 차단), (3) 지갑 forfeit+익명화 원자 RPC.\n-- 선행: 151(account_deletion_jobs·write_blocked)·115(anonymize_user_for_deletion).\n\nbegin", "set local lock_timeout=''5s''", "-- ── 1) Storage write gate 전면화 (RESTRICTIVE — 모든 버킷·모든 write 에 AND) ──────────────\n-- 개별 버킷 정책을 재작성하지 않고, deletion locked 유저의 모든 Storage write 를 한 번에 차단한다.\n-- RESTRICTIVE 는 기존 permissive 정책과 AND 로 결합 → upsert(=INSERT), overwrite/move(=UPDATE),\n-- copy(=INSERT) 모두 포함. service_role(worker 삭제)은 RLS 우회라 무영향. 0 job 이면 항상 true.\ndrop policy if exists adg_storage_block_insert_when_deleting on storage.objects", "create policy adg_storage_block_insert_when_deleting on storage.objects\n  as restrictive for insert to authenticated\n  with check (not public.account_deletion_write_blocked(auth.uid()))", "drop policy if exists adg_storage_block_update_when_deleting on storage.objects", "create policy adg_storage_block_update_when_deleting on storage.objects\n  as restrictive for update to authenticated\n  using (not public.account_deletion_write_blocked(auth.uid()))\n  with check (not public.account_deletion_write_blocked(auth.uid()))", "-- ── 2) job lease/claim (동시 worker 중복 처리 방지) ──────────────────────────────────────\nalter table public.account_deletion_jobs add column if not exists lease_owner text", "alter table public.account_deletion_jobs add column if not exists leased_until timestamptz", "-- 처리 대상(취소불가·미완료·backoff 도래·미lease/만료lease)을 원자적으로 lease 한다(SKIP LOCKED).\ncreate or replace function public.account_deletion_claim(p_owner text, p_limit int default 5, p_lease_seconds int default 300)\nreturns setof public.account_deletion_jobs language plpgsql security definer set search_path to ''public'' as $$\nbegin\n  return query\n  with cte as (\n    select j.id from public.account_deletion_jobs j\n    where j.state in (''pending'',''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted'')\n      and (j.next_attempt_at is null or j.next_attempt_at <= now())\n      and (j.leased_until is null or j.leased_until < now())\n    order by j.requested_at asc\n    limit greatest(1, p_limit)\n    for update skip locked\n  )\n  update public.account_deletion_jobs j\n    set lease_owner = p_owner, leased_until = now() + make_interval(secs => greatest(1, p_lease_seconds)), updated_at = now()\n    from cte where j.id = cte.id\n    returning j.*;\nend $$", "create or replace function public.account_deletion_reclaim_expired()\nreturns int language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_n int;\nbegin\n  update public.account_deletion_jobs set lease_owner=null, leased_until=null, updated_at=now()\n    where leased_until is not null and leased_until < now()\n      and state not in (''completed'',''canceled'',''failed'');\n  get diagnostics v_n = row_count;\n  return v_n;\nend $$", "-- ── 3) write gate 보정: deletion worker 의 forfeit write 는 허용 ──────────────────────────\n-- 151 write_guard 는 locked 유저의 지갑/원장 write 를 막지만, forfeit(정당한 삭제 단계)는 지갑을 0 으로\n-- 만들어야 한다. 트랜잭션 스코프 GUC(ssambership.deletion_worker=''on'')일 때만 우회한다(그 외 전부 차단 유지).\ncreate or replace function public.account_deletion_write_guard()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_col text := TG_ARGV[0]; v_uid uuid;\nbegin\n  if current_setting(''ssambership.deletion_worker'', true) = ''on'' then\n    return NEW;\n  end if;\n  v_uid := (to_jsonb(NEW) ->> v_col)::uuid;\n  if v_uid is not null and public.account_deletion_write_blocked(v_uid) then\n    raise exception ''ACCOUNT_DELETION_IN_PROGRESS'';\n  end if;\n  return NEW;\nend $$", "-- ── 4) 지갑 forfeit + 익명화 원자 RPC (storage 성공 후 단일 트랜잭션) ──────────────────────\n-- 잔액을 0원 원장 라인으로 몰수(append-only)하고 PII 익명화(115)를 같은 트랜잭션에서 수행한다.\n-- job.state 가 storage_purged 일 때만 허용(Storage 성공 전 금융/익명화 금지).\ncreate or replace function public.account_deletion_forfeit_and_anonymize(p_user_id uuid)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_state text; v_balance bigint; v_ledger_id uuid;\nbegin\n  -- 이 트랜잭션 동안 write gate 우회(자기 forfeit write 만 허용). local=true → 함수 종료 시 자동 해제.\n  perform set_config(''ssambership.deletion_worker'', ''on'', true);\n  select state into v_state from public.account_deletion_jobs where user_id = p_user_id for update;\n  if v_state is null then return jsonb_build_object(''ok'',false,''code'',''JOB_NOT_FOUND''); end if;\n  if v_state <> ''storage_purged'' then return jsonb_build_object(''ok'',false,''code'',''WRONG_STATE'',''state'',v_state); end if;\n\n  -- 잔액 forfeit: 남은 balance 를 0 으로 만드는 음수 라인(멱등). append-only(기존 라인 무수정).\n  select balance_cents into v_balance from public.cash_wallets where user_id = p_user_id for update;\n  if v_balance is not null and v_balance > 0 then\n    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n    values (p_user_id, -v_balance, ''account_deletion_forfeit'', ''account_deletion'', p_user_id, ''acct_del_forfeit:''||p_user_id::text)\n    on conflict (idempotency_key) do nothing\n    returning id into v_ledger_id;\n    if v_ledger_id is not null then\n      update public.cash_wallets set balance_cents = 0 where user_id = p_user_id;\n    end if;\n  end if;\n\n  -- PII 익명화(115, 멱등).\n  perform public.anonymize_user_for_deletion(p_user_id, ''account_deletion'');\n  return jsonb_build_object(''ok'',true,''forfeited_cents'',coalesce(v_balance,0),''ledger_id'',v_ledger_id);\nend $$", "revoke all on function public.account_deletion_claim(text,int,int) from public, anon, authenticated", "revoke all on function public.account_deletion_reclaim_expired() from public, anon, authenticated", "revoke all on function public.account_deletion_forfeit_and_anonymize(uuid) from public, anon, authenticated", "grant execute on function public.account_deletion_claim(text,int,int) to service_role", "grant execute on function public.account_deletion_reclaim_expired() to service_role", "grant execute on function public.account_deletion_forfeit_and_anonymize(uuid) to service_role", "commit", "-- §V(rollback-only): locked 유저 Storage INSERT·UPDATE(overwrite/move/upsert) 전면 거부(RESTRICTIVE) ·\n--   정상/0job 유저 무영향 · claim 은 미lease/만료lease 만 원자 lease(동시 worker 중복 0) · 만료 lease 회수 ·\n--   forfeit_and_anonymize 는 storage_purged 에서만 · 잔액 0원 몰수 라인 append-only 멱등 · 익명화 동일 tx.\n\n-- >>> NATIVE_BASELINE_PART 0162 | supabase/sql/155_p1_11_iq_notification_atomization.sql | 155_p1_11_iq_notification_atomization.sql <<<\n-- 155_p1_11_iq_notification_atomization.sql\n-- P1-11 알림 원자화 — 개별질문(IQ) 6 이벤트. domain write(RPC·웹 직접 write 무관)와 같은 트랜잭션에서\n-- record_domain_notification 를 AFTER 트리거로 호출 → 원자·멱등. 웹 best-effort 알림은 코드에서 제거.\n--\n-- 원자성: 트리거는 domain UPDATE/INSERT 트랜잭션 안에서 실행 → domain write 롤백 시 알림도 롤백,\n--   record_domain_notification 오류 시 domain write 도 롤백(예외 미포획 — 원자 계약).\n-- 멱등: (recipient,event_key)·(recipient,dedup_key) UNIQUE(132) → 재실행·중복 0. event_key={event}:{qid|mid}.\n-- 커버 이벤트: individual_question_assigned/claimed/answered/released/expired_refunded/message.\n-- 선행: 132(record_domain_notification)·individual_questions/individual_question_messages.\n\nbegin", "set local lock_timeout=''5s''", "-- 1) 상태 전이 알림(answered/released/claimed/refunded).\ncreate or replace function public.iq_notify_status_transition()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_recipient uuid; v_type text; v_title text; v_body text; v_mentor uuid;\nbegin\n  v_mentor := coalesce(NEW.claimed_mentor_id, NEW.designated_mentor_id);\n  if NEW.status = ''answered'' then\n    v_recipient := NEW.student_id; v_type := ''individual_question_answered'';\n    v_title := ''개별 질문 답변 도착''; v_body := ''요청한 개별 질문에 답변이 등록됐어요.'';\n  elsif NEW.status = ''released'' then\n    v_recipient := v_mentor; v_type := ''individual_question_released'';\n    v_title := ''개별 질문 정산 확정''; v_body := ''학생이 답변을 확정해 정산이 확정됐어요.'';\n  elsif NEW.status = ''claimed'' then\n    v_recipient := NEW.student_id; v_type := ''individual_question_claimed'';\n    v_title := ''개별 질문 수락됨''; v_body := ''멘토가 개별 질문을 수락했어요.'';\n  elsif NEW.status = ''refunded'' then\n    v_recipient := NEW.student_id; v_type := ''individual_question_expired_refunded'';\n    v_title := ''개별 질문 환불''; v_body := ''개별 질문이 만료되어 캐시가 환불됐어요.'';\n  else\n    return NEW;\n  end if;\n  if v_recipient is not null then\n    perform public.record_domain_notification(\n      v_recipient, v_type || '':'' || NEW.id::text, v_type || '':'' || NEW.id::text, v_type,\n      v_title, v_body, null,\n      jsonb_build_object(''question_id'', NEW.id, ''status'', NEW.status),\n      jsonb_build_object(''question_id'', NEW.id));\n  end if;\n  return NEW;\nend $$", "drop trigger if exists trg_iq_notify_status on public.individual_questions", "create trigger trg_iq_notify_status\n  after update on public.individual_questions\n  for each row when (old.status is distinct from new.status)\n  execute function public.iq_notify_status_transition()", "-- 2) 지정형 생성 시 멘토에게 assigned 알림.\ncreate or replace function public.iq_notify_assigned()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\nbegin\n  if NEW.designated_mentor_id is not null then\n    perform public.record_domain_notification(\n      NEW.designated_mentor_id, ''individual_question_assigned:'' || NEW.id::text,\n      ''individual_question_assigned:'' || NEW.id::text, ''individual_question_assigned'',\n      ''새 지정 개별 질문'', ''학생이 나를 지정해 개별 질문을 보냈어요.'', null,\n      jsonb_build_object(''question_id'', NEW.id), jsonb_build_object(''question_id'', NEW.id));\n  end if;\n  return NEW;\nend $$", "drop trigger if exists trg_iq_notify_assigned on public.individual_questions", "create trigger trg_iq_notify_assigned\n  after insert on public.individual_questions\n  for each row execute function public.iq_notify_assigned()", "-- 3) 개별 질문 메시지 → 상대방 알림.\ncreate or replace function public.iqm_notify_message()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_student uuid; v_mentor uuid; v_recipient uuid;\nbegin\n  select student_id, coalesce(claimed_mentor_id, designated_mentor_id)\n    into v_student, v_mentor from public.individual_questions where id = NEW.question_id;\n  if NEW.author_id = v_student then v_recipient := v_mentor;\n  elsif NEW.author_id = v_mentor then v_recipient := v_student;\n  else v_recipient := null; end if;\n  if v_recipient is not null then\n    perform public.record_domain_notification(\n      v_recipient, ''individual_question_message:'' || NEW.id::text,\n      ''individual_question_message:'' || NEW.id::text, ''individual_question_message'',\n      ''개별 질문 새 메시지'', ''개별 질문에 새 메시지가 도착했어요.'', null,\n      jsonb_build_object(''question_id'', NEW.question_id, ''message_id'', NEW.id),\n      jsonb_build_object(''question_id'', NEW.question_id, ''message_id'', NEW.id));\n  end if;\n  return NEW;\nend $$", "drop trigger if exists trg_iqm_notify_message on public.individual_question_messages", "create trigger trg_iqm_notify_message\n  after insert on public.individual_question_messages\n  for each row execute function public.iqm_notify_message()", "commit", "-- §V(rollback-only): answered/released/claimed/refunded 전이 시 수신자별 notification+outbox 1건(멱등) ·\n--   지정 생성 시 멘토 assigned 1건 · 메시지 INSERT 시 상대방 1건 · domain write 롤백 시 알림 0 ·\n--   재실행/중복 전이 시 (recipient,event_key) UNIQUE 로 중복 0.\n\n-- >>> NATIVE_BASELINE_PART 0163 | supabase/sql/156_p2_25_payout_scheduler_foundation.sql | 156_p2_25_payout_scheduler_foundation.sql <<<\n-- 156_p2_25_payout_scheduler_foundation.sql\n-- P2-25 지급 운영 scheduler 기반 — 기본 비활성(OFF). 153 지급 엔진 무수정.\n-- 실송금이 아니라 내부지갑 적립 모델. cron 은 staging 에서도 기본 disabled(명시 enable 없으면 실지급 금지).\n--\n-- 신규:\n--   * payout_settings(싱글턴): scheduler_enabled(기본 false) — 명시 활성 없으면 실지급 금지.\n--   * payout_reconciliation_report(run_date): READ-ONLY — 지급 대상/제외/오류 사유 산출(돈 이동 0).\n--   * run_scheduled_payout(run_date): 래퍼 — enabled 아니면 dry-run(보고서만), enabled 면 실지급(153).\n--     한 배치 중복 실행은 153 멱등(payout:YYYY-MM)으로 봉쇄.\n-- 선행: 153(pay_due_payouts_for_run·payout_run_items·전역 UNIQUE)·107(due_payouts).\n\nbegin", "set local lock_timeout=''5s''", "create table if not exists public.payout_settings (\n  id int primary key default 1 check (id = 1),\n  scheduler_enabled boolean not null default false,\n  updated_at timestamptz not null default now()\n)", "insert into public.payout_settings (id, scheduler_enabled) values (1, false) on conflict (id) do nothing", "alter table public.payout_settings enable row level security", "revoke all on public.payout_settings from anon, authenticated", "grant select, insert, update on public.payout_settings to service_role", "-- 지급 예정일(23일)·회차 산정 READ-ONLY 보고서: 대상/제외/오류 사유.\ncreate or replace function public.payout_reconciliation_report(p_run_date date)\nreturns table (\n  source_type text, source_id uuid, mentor_id uuid,\n  mentor_amount_cents bigint, withholding_cents bigint, net_paid_cents bigint,\n  eligible boolean, reason text\n) language sql stable security definer set search_path to ''public'' as $$\n  with cutoff as (select (date_trunc(''month'', p_run_date::timestamp) - interval ''1 second'') as ts)\n  select\n    d.source_type, d.source_id, d.mentor_id,\n    d.mentor_amount_cents,\n    floor(d.mentor_amount_cents::numeric * 0.033)::bigint as withholding_cents,\n    d.mentor_amount_cents - floor(d.mentor_amount_cents::numeric * 0.033)::bigint as net_paid_cents,\n    (case when exists (select 1 from public.payout_run_items i where i.source_type=d.source_type and i.source_id=d.source_id) then false\n          when d.completion_ts > (select ts from cutoff) then false\n          when coalesce(nullif(trim(mp.payout_account_number),''''),'''') = '''' then false\n          else true end) as eligible,\n    (case when exists (select 1 from public.payout_run_items i where i.source_type=d.source_type and i.source_id=d.source_id) then ''already_paid''\n          when d.completion_ts > (select ts from cutoff) then ''not_due''\n          when coalesce(nullif(trim(mp.payout_account_number),''''),'''') = '''' then ''no_payout_account''\n          else ''eligible'' end) as reason\n  from public.due_payouts d\n  left join public.mentor_profiles mp on mp.user_id = d.mentor_id\n  order by d.mentor_id, d.source_type;\n$$", "revoke all on function public.payout_reconciliation_report(date) from public, anon, authenticated", "grant execute on function public.payout_reconciliation_report(date) to service_role", "-- scheduler 래퍼: enabled 없으면 dry-run(보고서만·돈 이동 0), enabled 면 실지급(153, 멱등).\ncreate or replace function public.run_scheduled_payout(p_run_date date, p_force_dry_run boolean default false)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_enabled boolean; v_dry boolean; v_res record;\nbegin\n  select scheduler_enabled into v_enabled from public.payout_settings where id = 1;\n  v_enabled := coalesce(v_enabled, false);\n  -- 명시 활성 없거나 강제 dry-run 이면 dry-run(실지급 금지).\n  v_dry := (not v_enabled) or coalesce(p_force_dry_run, false);\n  select * into v_res from public.pay_due_payouts_for_run(p_run_date, null, v_dry);\n  return jsonb_build_object(\n    ''ok'', true, ''scheduler_enabled'', v_enabled, ''dry_run'', v_res.dry_run,\n    ''run_id'', v_res.run_id, ''paid_count'', v_res.paid_count, ''skipped_no_account'', v_res.skipped_no_account,\n    ''total_mentor_cents'', v_res.total_mentor_cents, ''total_withholding_cents'', v_res.total_withholding_cents,\n    ''total_net_cents'', v_res.total_net_cents);\nend $$", "revoke all on function public.run_scheduled_payout(date, boolean) from public, anon, authenticated", "grant execute on function public.run_scheduled_payout(date, boolean) to service_role", "commit", "-- §V(rollback-only): payout_settings 기본 scheduler_enabled=false · run_scheduled_payout 은 enabled=false 면\n--   무조건 dry_run(payout_run_items/원장/지갑 변화 0) · enabled=true 라야 실지급 · 보고서는 대상/already_paid/\n--   not_due/no_payout_account 분류(READ-ONLY) · cron 미설정(명시 호출만).\n\n-- >>> NATIVE_BASELINE_PART 0164 | supabase/sql/157_p1_11_subscription_notification_atomization.sql | 157_p1_11_subscription_notification_atomization.sql <<<\n-- 157_p1_11_subscription_notification_atomization.sql\n-- [적용됨 — ssambership-staging 에 2026-07-20 단일 execute_sql(전문 그대로) 적용. staging fixture 24 assertion\n--   전부 PASS(rollback-only)·baseline 복원 확인. ACL 후속 보정: 160(표시 헬퍼 anon/authenticated revoke).\n--   원장 미기재 — 적용 이력: docs/audit/sql_apply_manifest.md]\n-- P1-11 알림 원자화 — 구독 4 이벤트. domain write 와 같은 트랜잭션에서\n-- record_domain_notification 를 AFTER 트리거로 호출 → 원자·멱등. 웹 best-effort 알림은 코드에서 제거.\n--\n-- 원자성: 트리거는 domain INSERT/UPDATE 트랜잭션 안에서 실행 → domain write 롤백 시 알림도 롤백,\n--   record_domain_notification 오류 시 domain write 도 롤백(예외 미포획 — 원자 계약).\n-- 멱등: (recipient,event_key) UNIQUE(132) → 재실행·재시도 중복 0.\n--   event_key = {event}:{subscription_id}:{period_end date | expired date} — 주기(회차)별 1건.\n-- 커버 이벤트:\n--   subscription_renewal_upcoming   billing_events INSERT(renewal/skipped/pre_renewal_notice_sent 마커)\n--   subscription_renewal_succeeded  billing_events INSERT/UPDATE(renewal/succeeded 전이 — 068 RPC)\n--   subscription_renewal_failed_insufficient_cash\n--                                   billing_events INSERT/UPDATE(renewal_failed/failed/insufficient_cash — 068 RPC.\n--                                   재시도 failed→processing→failed 반복은 event_key 로 주기당 1건)\n--   subscription_expired            subscriptions UPDATE(status → ''expired'' 전이 — 만료·해지예약 경로 공통)\n-- 선행: 132(record_domain_notification)·064(subscription_billing_events)·068/100(renewal RPC).\n\nbegin", "set local lock_timeout=''5s''", "-- 0) 표시 이름 헬퍼 — 웹 fetchUserDisplayName(full_name → nickname → ''멘토'')과 동일 우선순위.\ncreate or replace function public.notification_display_name(p_user_id uuid)\nreturns text language sql stable security definer set search_path to ''public'' as $$\n  select coalesce((\n    select coalesce(\n      nullif(trim(coalesce(u.full_name, '''')), ''''),\n      nullif(trim(coalesce(u.nickname, '''')), ''''))\n    from public.users u where u.id = p_user_id\n  ), ''멘토'');\n$$", "revoke all on function public.notification_display_name(uuid) from public", "-- ''멘토'' 접미(noticeMentorLabel)까지 붙인 구독 안내용 라벨.\ncreate or replace function public.notification_mentor_label(p_user_id uuid)\nreturns text language sql stable security definer set search_path to ''public'' as $$\n  select case when n like ''%멘토'' then n else n || '' 멘토'' end\n  from (select public.notification_display_name(p_user_id) as n) s;\n$$", "revoke all on function public.notification_mentor_label(uuid) from public", "-- 캐시 표기 헬퍼 — 웹 formatCashFromCents(cents ÷ 100, 천단위 콤마, ''캐시'')와 동일.\ncreate or replace function public.notification_cash_label(p_amount_cents bigint)\nreturns text language sql immutable as $$\n  select to_char(greatest(0, round(coalesce(p_amount_cents, 0) / 100.0)), ''FM999,999,999,999'') || ''캐시'';\n$$", "revoke all on function public.notification_cash_label(bigint) from public", "-- 한국어 날짜 헬퍼 — 웹 formatNoticeDate(Asia/Seoul, ''YYYY년 M월 D일'')와 동일. null 이면 ''예정일''.\ncreate or replace function public.notification_date_label(p_at timestamptz)\nreturns text language sql immutable as $$\n  select case when p_at is null then ''예정일''\n    else to_char(p_at at time zone ''Asia/Seoul'', ''YYYY\"년\" FMMM\"월\" FMDD\"일\"'') end;\n$$", "revoke all on function public.notification_date_label(timestamptz) from public", "-- 1) subscription_billing_events → 갱신 예고·성공·실패(캐시 부족) 알림.\ncreate or replace function public.sbe_notify_billing_event()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_mentor_label text;\n  v_period_key text;\n  v_grace timestamptz;\nbegin\n  -- 예고 마커: 배치가 INSERT 하는 renewal/skipped/pre_renewal_notice_sent 행(멱등키 sub_renewal_notice:*).\n  if TG_OP = ''INSERT''\n     and NEW.event_type = ''renewal'' and NEW.status = ''skipped''\n     and NEW.failure_code = ''pre_renewal_notice_sent'' then\n    v_mentor_label := public.notification_mentor_label(NEW.mentor_id);\n    v_period_key := to_char(coalesce(NEW.period_end, NEW.billing_at, NEW.created_at, now()), ''YYYY-MM-DD'');\n    perform public.record_domain_notification(\n      NEW.student_id,\n      ''subscription_renewal_upcoming:'' || NEW.subscription_id::text || '':'' || v_period_key,\n      ''subscription_renewal_upcoming:'' || NEW.subscription_id::text || '':'' || v_period_key,\n      ''subscription_renewal_upcoming'',\n      ''구독이 곧 갱신돼요'',\n      v_mentor_label || '' 구독이 곧 갱신돼요. '' || public.notification_date_label(NEW.billing_at)\n        || ''에 '' || public.notification_cash_label(NEW.amount_cents) || ''가 결제됩니다. 잔액을 확인해 주세요.'',\n      ''/wallet/charge'',\n      jsonb_build_object(''subscription_id'', NEW.subscription_id, ''billing_event_id'', NEW.id,\n        ''next_billing_at'', NEW.billing_at, ''amount_cents'', NEW.amount_cents),\n      jsonb_build_object(''subscription_id'', NEW.subscription_id));\n    return NEW;\n  end if;\n\n  -- 갱신 성공: 068 RPC 가 processing → renewal/succeeded 로 UPDATE(INSERT 직행도 커버).\n  if NEW.event_type = ''renewal'' and NEW.status = ''succeeded''\n     and (TG_OP = ''INSERT'' or OLD.status is distinct from NEW.status) then\n    v_mentor_label := public.notification_mentor_label(NEW.mentor_id);\n    v_period_key := to_char(coalesce(NEW.period_end, NEW.billing_at, NEW.created_at, now()), ''YYYY-MM-DD'');\n    perform public.record_domain_notification(\n      NEW.student_id,\n      ''subscription_renewal_succeeded:'' || NEW.subscription_id::text || '':'' || v_period_key,\n      ''subscription_renewal_succeeded:'' || NEW.subscription_id::text || '':'' || v_period_key,\n      ''subscription_renewal_succeeded'',\n      ''구독이 갱신되었어요'',\n      v_mentor_label || '' 구독이 갱신되었어요. '' || public.notification_cash_label(NEW.amount_cents)\n        || '' 결제가 완료됐고, 다음 결제일은 '' || public.notification_date_label(NEW.period_end) || ''입니다.'',\n      ''/subscriptions'',\n      jsonb_build_object(''subscription_id'', NEW.subscription_id, ''billing_event_id'', NEW.id,\n        ''ledger_id'', NEW.ledger_id, ''next_period_end'', NEW.period_end),\n      jsonb_build_object(''subscription_id'', NEW.subscription_id));\n    return NEW;\n  end if;\n\n  -- 갱신 실패(캐시 부족): 068 RPC 가 processing → renewal_failed/failed 로 UPDATE.\n  -- 재시도 주기(failed→processing→failed)마다 발화해도 event_key 로 주기당 1건(웹의 attempt<=1 정책과 동일 효과).\n  if NEW.event_type = ''renewal_failed'' and NEW.status = ''failed''\n     and NEW.failure_code = ''insufficient_cash''\n     and (TG_OP = ''INSERT''\n          or OLD.status is distinct from NEW.status\n          or OLD.event_type is distinct from NEW.event_type) then\n    v_mentor_label := public.notification_mentor_label(NEW.mentor_id);\n    v_period_key := to_char(coalesce(NEW.period_end, NEW.billing_at, NEW.created_at, now()), ''YYYY-MM-DD'');\n    -- 068 은 billing event UPDATE 뒤 subscriptions.grace_until 을 세팅 → 첫 실패 시점엔 아직 null.\n    -- RPC 와 동일 공식(coalesce(grace_until, processed_at + 2일))로 유예일을 계산한다.\n    select s.grace_until into v_grace from public.subscriptions s where s.id = NEW.subscription_id;\n    v_grace := coalesce(v_grace, coalesce(NEW.processed_at, now()) + interval ''2 days'');\n    perform public.record_domain_notification(\n      NEW.student_id,\n      ''subscription_renewal_failed_insufficient_cash:'' || NEW.subscription_id::text || '':'' || v_period_key,\n      ''subscription_renewal_failed_insufficient_cash:'' || NEW.subscription_id::text || '':'' || v_period_key,\n      ''subscription_renewal_failed_insufficient_cash'',\n      ''구독 갱신에 실패했어요'',\n      v_mentor_label || '' 구독 갱신에 실패했어요(캐시 부족). '' || public.notification_date_label(v_grace)\n        || ''까지 충전하면 구독이 유지됩니다.'',\n      ''/wallet/charge'',\n      jsonb_build_object(''subscription_id'', NEW.subscription_id, ''billing_event_id'', NEW.id,\n        ''attempt_count'', NEW.attempt_count),\n      jsonb_build_object(''subscription_id'', NEW.subscription_id));\n    return NEW;\n  end if;\n\n  return NEW;\nend $$", "drop trigger if exists trg_sbe_notify_insert on public.subscription_billing_events", "create trigger trg_sbe_notify_insert\n  after insert on public.subscription_billing_events\n  for each row execute function public.sbe_notify_billing_event()", "drop trigger if exists trg_sbe_notify_update on public.subscription_billing_events", "create trigger trg_sbe_notify_update\n  after update on public.subscription_billing_events\n  for each row when (old.status is distinct from new.status or old.event_type is distinct from new.event_type)\n  execute function public.sbe_notify_billing_event()", "-- 2) subscriptions → 만료 알림(만료·해지예약 소진 경로 공통. 멘토 종료의 ''canceled'' 전이는 대상 아님).\ncreate or replace function public.sub_notify_expired()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_mentor_label text;\n  v_key text;\nbegin\n  v_mentor_label := public.notification_mentor_label(NEW.mentor_id);\n  -- 재구독(pair 1행 모델 재활성) 후 재만료를 구분하기 위해 만료일을 키에 포함.\n  v_key := ''subscription_expired:'' || NEW.id::text || '':''\n    || to_char(coalesce(NEW.expired_at, NEW.current_period_end, now()), ''YYYY-MM-DD'');\n  perform public.record_domain_notification(\n    NEW.student_id, v_key, v_key, ''subscription_expired'',\n    ''구독이 만료되었어요'',\n    v_mentor_label || '' 구독이 만료되었어요. 다시 구독하려면 멘토 페이지에서 재구독할 수 있어요.'',\n    ''/subscriptions'',\n    jsonb_build_object(''subscription_id'', NEW.id, ''mentor_id'', NEW.mentor_id,\n      ''reason'', case when NEW.cancel_at_period_end then ''cancel_at_period_end'' else ''expired'' end),\n    jsonb_build_object(''subscription_id'', NEW.id));\n  return NEW;\nend $$", "drop trigger if exists trg_sub_notify_expired on public.subscriptions", "create trigger trg_sub_notify_expired\n  after update on public.subscriptions\n  for each row when (old.status is distinct from new.status and new.status = ''expired'')\n  execute function public.sub_notify_expired()", "commit", "-- §V(rollback-only): 예고 마커 INSERT 시 학생 1건 · renewal succeeded 전이 시 1건(재실행 중복 0) ·\n--   insufficient_cash 실패 전이 시 1건(재시도 반복에도 주기당 1건) · status→expired 전이 시 1건 ·\n--   initial/expired/canceled billing event 는 무발화 · domain write 롤백 시 알림 0.\n\n-- >>> NATIVE_BASELINE_PART 0165 | supabase/sql/158_p1_11_mentor_notification_atomization.sql | 158_p1_11_mentor_notification_atomization.sql <<<\n-- 158_p1_11_mentor_notification_atomization.sql\n-- [적용됨 — ssambership-staging 에 2026-07-20 단일 execute_sql(전문 그대로) 적용. staging fixture B 절\n--   전부 PASS(rollback-only)·baseline 복원 확인. 원장 미기재 — 적용 이력: docs/audit/sql_apply_manifest.md]\n-- P1-11 알림 원자화 — 멘토 4 이벤트. domain write 와 같은 트랜잭션에서\n-- record_domain_notification 를 AFTER 트리거로 호출 → 원자·멱등. 웹 best-effort 알림은 코드에서 제거.\n--\n-- 원자성: 트리거는 domain UPDATE/INSERT 트랜잭션 안에서 실행 → domain write 롤백 시 알림도 롤백,\n--   record_domain_notification 오류 시 domain write 도 롤백(예외 미포획 — 원자 계약).\n-- 멱등: (recipient,event_key) UNIQUE(132) → 재실행·중복 0.\n-- 커버 이벤트:\n--   mentor_termination_notice   mentor_profiles UPDATE(activity_status → ''terminating'') — 활성 구독 학생 fan-out\n--   mentor_pause_notice         mentor_profiles UPDATE(activity_status → ''paused'') — 활성 구독 학생 fan-out\n--   mentor_termination_refund   refunds INSERT(request_type=''subscription_mentor_suspended'')\n--   mentor_subscription_price_changed\n--                               mentor_plans INSERT/UPDATE(amount_cents 변경) — 활성 구독 학생 fan-out.\n--                               event_key 에 txid 포함 → 동일 트랜잭션 다중 tier upsert 는 학생당 1건.\n-- 선행: 157(notification_mentor_label/notification_cash_label 헬퍼)·132(record_domain_notification)·\n--   103(mentor_profiles activity 컬럼)·069(refunds subscription_id/request_type)·067(mentor_plans).\n\nbegin", "set local lock_timeout=''5s''", "-- 1) mentor_profiles activity_status 전이 → 구독 학생 fan-out(terminating/paused).\ncreate or replace function public.mp_notify_activity_transition()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_sub record;\n  v_key text;\n  v_date_key text;\nbegin\n  if NEW.activity_status = ''terminating'' then\n    v_date_key := to_char(coalesce(NEW.termination_effective_at, now()) at time zone ''UTC'', ''YYYY-MM-DD'');\n    for v_sub in\n      select s.id, s.student_id from public.subscriptions s\n      where s.mentor_id = NEW.user_id and s.status in (''active'', ''past_due'')\n    loop\n      v_key := ''mentor_termination_notice:'' || v_sub.id::text || '':'' || v_date_key;\n      perform public.record_domain_notification(\n        v_sub.student_id, v_key, v_key, ''mentor_termination_notice'',\n        ''멘토 활동 종료 예정'',\n        ''구독 중인 멘토가 활동을 종료합니다. 2주 후('' || v_date_key\n          || '') 구독이 정리되며 남은 기간은 환불됩니다. 그때까지는 정상 이용할 수 있어요.'',\n        ''/subscriptions'',\n        jsonb_build_object(''mentor_id'', NEW.user_id, ''effective_at'', NEW.termination_effective_at,\n          ''subscription_id'', v_sub.id),\n        jsonb_build_object(''mentor_id'', NEW.user_id, ''subscription_id'', v_sub.id));\n    end loop;\n  elsif NEW.activity_status = ''paused'' then\n    v_date_key := to_char(coalesce(NEW.pause_until, now()) at time zone ''UTC'', ''YYYY-MM-DD'');\n    for v_sub in\n      select s.id, s.student_id from public.subscriptions s\n      where s.mentor_id = NEW.user_id and s.status in (''active'', ''past_due'')\n    loop\n      v_key := ''mentor_pause_notice:'' || v_sub.id::text || '':'' || v_date_key;\n      perform public.record_domain_notification(\n        v_sub.student_id, v_key, v_key, ''mentor_pause_notice'',\n        ''멘토 일시 휴식 안내'',\n        ''구독 중인 멘토가 '' || v_date_key || ''까지 일시 휴식합니다. 쉰 기간만큼 구독 기간이 자동 연장됩니다.'',\n        ''/subscriptions'',\n        jsonb_build_object(''mentor_id'', NEW.user_id, ''pause_until'', NEW.pause_until,\n          ''subscription_id'', v_sub.id),\n        jsonb_build_object(''mentor_id'', NEW.user_id, ''subscription_id'', v_sub.id));\n    end loop;\n  end if;\n  return NEW;\nend $$", "drop trigger if exists trg_mp_notify_activity on public.mentor_profiles", "create trigger trg_mp_notify_activity\n  after update on public.mentor_profiles\n  for each row when (old.activity_status is distinct from new.activity_status\n                     and new.activity_status in (''terminating'', ''paused''))\n  execute function public.mp_notify_activity_transition()", "-- 2) refunds INSERT(멘토 종료 잔여 환불) → 학생 알림.\n--    금액 표기는 notification_cash_label(cents ÷ 100) — 구 웹 본문이 cents 를 캐시로 그대로 찍던 표기 오류를 바로잡음.\ncreate or replace function public.refund_notify_mentor_termination()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_mentor uuid;\nbegin\n  select s.mentor_id into v_mentor from public.subscriptions s where s.id = NEW.subscription_id;\n  perform public.record_domain_notification(\n    NEW.user_id,\n    ''mentor_termination_refund:'' || NEW.id::text,\n    ''mentor_termination_refund:'' || NEW.id::text,\n    ''mentor_termination_refund'',\n    ''멘토 활동 종료 — 환불 접수'',\n    ''멘토 활동 종료로 남은 기간 환불('' || public.notification_cash_label(NEW.amount_cents)\n      || '')이 접수되었습니다. 관리자 검토 후 처리됩니다.'',\n    ''/support/refunds'',\n    jsonb_build_object(''refund_id'', NEW.id, ''subscription_id'', NEW.subscription_id, ''mentor_id'', v_mentor),\n    jsonb_build_object(''refund_id'', NEW.id, ''subscription_id'', NEW.subscription_id));\n  return NEW;\nend $$", "drop trigger if exists trg_refund_notify_mentor_termination on public.refunds", "create trigger trg_refund_notify_mentor_termination\n  after insert on public.refunds\n  for each row when (new.request_type = ''subscription_mentor_suspended'')\n  execute function public.refund_notify_mentor_termination()", "-- 3) mentor_plans 가격 변경 → 활성 구독 학생 fan-out.\n--    is_active 토글(활동 중단/복귀)은 amount_cents 불변 → 무발화. 동일 제출(단일 트랜잭션) 다중 tier 는\n--    event_key 의 txid 로 학생당 1건. 다른 제출(다른 트랜잭션)은 새 알림.\ncreate or replace function public.mplan_notify_price_changed()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_sub record;\n  v_key text;\nbegin\n  for v_sub in\n    select s.id, s.student_id from public.subscriptions s\n    where s.mentor_id = NEW.mentor_id and s.status in (''active'', ''cancel_scheduled'', ''past_due'')\n  loop\n    v_key := ''mentor_subscription_price_changed:'' || NEW.mentor_id::text || '':'' || v_sub.id::text\n      || '':'' || txid_current()::text;\n    perform public.record_domain_notification(\n      v_sub.student_id, v_key, v_key, ''mentor_subscription_price_changed'',\n      ''멘토 구독 요금이 변경됐어요'',\n      ''구독 중인 멘토의 요금제가 변경됐어요. 현재 구독에는 바로 적용되지 않고 신규 구독 또는 다음 갱신부터 반영됩니다.'',\n      ''/mentors/'' || NEW.mentor_id::text,\n      jsonb_build_object(''mentor_id'', NEW.mentor_id, ''plan_tier'', NEW.plan_tier,\n        ''subscription_id'', v_sub.id),\n      jsonb_build_object(''mentor_id'', NEW.mentor_id, ''subscription_id'', v_sub.id));\n  end loop;\n  return NEW;\nend $$", "drop trigger if exists trg_mplan_notify_price_insert on public.mentor_plans", "create trigger trg_mplan_notify_price_insert\n  after insert on public.mentor_plans\n  for each row execute function public.mplan_notify_price_changed()", "drop trigger if exists trg_mplan_notify_price_update on public.mentor_plans", "create trigger trg_mplan_notify_price_update\n  after update on public.mentor_plans\n  for each row when (old.amount_cents is distinct from new.amount_cents)\n  execute function public.mplan_notify_price_changed()", "commit", "-- §V(rollback-only): terminating 전이 시 활성 구독 학생별 1건 · paused 전이 시 1건 ·\n--   suspended 환불 INSERT 시 학생 1건(금액 캐시 표기 = cents÷100) · 가격 UPDATE 시 활성 구독 학생별 1건 ·\n--   동일 트랜잭션 3-tier upsert 는 학생당 1건 · is_active 토글 무발화 · domain write 롤백 시 알림 0.\n\n-- >>> NATIVE_BASELINE_PART 0166 | supabase/sql/159_p1_11_custom_request_notification_atomization.sql | 159_p1_11_custom_request_notification_atomization.sql <<<\n-- 159_p1_11_custom_request_notification_atomization.sql\n-- [적용됨 — ssambership-staging 에 2026-07-20 단일 execute_sql(전문 그대로) 적용. staging fixture C 절\n--   전부 PASS(rollback-only)·baseline 복원 확인. 원장 미기재 — 적용 이력: docs/audit/sql_apply_manifest.md]\n-- P1-11 알림 원자화 — 맞춤의뢰 2 이벤트. domain write 와 같은 트랜잭션에서\n-- record_domain_notification 를 AFTER 트리거로 호출 → 원자·멱등. 웹 best-effort 알림은 코드에서 제거.\n--\n-- 원자성: 트리거는 domain INSERT 트랜잭션 안에서 실행 → domain write 롤백 시 알림도 롤백,\n--   record_domain_notification 오류 시 domain write 도 롤백(예외 미포획 — 원자 계약).\n-- 멱등: (recipient,event_key) UNIQUE(132) → 재실행·중복 0. event_key = {event}:{row id}.\n-- 커버 이벤트:\n--   new_application    custom_request_applications INSERT → 의뢰 글 작성자에게\n--   new_order_message  custom_order_messages INSERT → 주문 상대방(학생↔멘토)에게.\n--                      작성자가 당사자가 아니면(관리자 등) 무발화.\n-- 선행: 157(notification_display_name 헬퍼)·132(record_domain_notification)·\n--   003(custom_request_posts/applications/orders·custom_order_messages).\n\nbegin", "set local lock_timeout=''5s''", "-- 1) 맞춤의뢰 지원서 INSERT → 의뢰 글 작성자 알림.\ncreate or replace function public.cra_notify_new_application()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_author uuid;\nbegin\n  select p.author_id into v_author from public.custom_request_posts p where p.id = NEW.post_id;\n  if v_author is not null and v_author is distinct from NEW.mentor_id then\n    perform public.record_domain_notification(\n      v_author,\n      ''new_application:'' || NEW.id::text,\n      ''new_application:'' || NEW.id::text,\n      ''new_application'',\n      ''새 지원서가 도착했어요'',\n      public.notification_display_name(NEW.mentor_id) || ''님이 의뢰에 지원했습니다.'',\n      ''/custom-request/'' || NEW.post_id::text || ''/applications/waiting'',\n      jsonb_build_object(''post_id'', NEW.post_id, ''mentor_id'', NEW.mentor_id, ''application_id'', NEW.id),\n      jsonb_build_object(''post_id'', NEW.post_id, ''application_id'', NEW.id));\n  end if;\n  return NEW;\nend $$", "drop trigger if exists trg_cra_notify_new_application on public.custom_request_applications", "create trigger trg_cra_notify_new_application\n  after insert on public.custom_request_applications\n  for each row execute function public.cra_notify_new_application()", "-- 2) 주문방 메시지 INSERT → 상대방 알림.\ncreate or replace function public.com_notify_new_order_message()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_student uuid;\n  v_mentor uuid;\n  v_recipient uuid;\n  v_sender_role text;\nbegin\n  select o.student_id, o.mentor_id into v_student, v_mentor\n  from public.custom_request_orders o where o.id = NEW.custom_request_order_id;\n  if NEW.author_id = v_student then\n    v_recipient := v_mentor; v_sender_role := ''student'';\n  elsif NEW.author_id = v_mentor then\n    v_recipient := v_student; v_sender_role := ''mentor'';\n  else\n    v_recipient := null;\n  end if;\n  if v_recipient is not null and v_recipient is distinct from NEW.author_id then\n    perform public.record_domain_notification(\n      v_recipient,\n      ''new_order_message:'' || NEW.id::text,\n      ''new_order_message:'' || NEW.id::text,\n      ''new_order_message'',\n      ''주문방에 새 메시지가 왔어요'',\n      public.notification_display_name(NEW.author_id) || ''님이 메시지를 보냈습니다.'',\n      ''/custom-request/orders/'' || NEW.custom_request_order_id::text,\n      jsonb_build_object(''order_id'', NEW.custom_request_order_id, ''sender_id'', NEW.author_id,\n        ''sender_role'', v_sender_role, ''message_id'', NEW.id),\n      jsonb_build_object(''order_id'', NEW.custom_request_order_id, ''message_id'', NEW.id));\n  end if;\n  return NEW;\nend $$", "drop trigger if exists trg_com_notify_new_order_message on public.custom_order_messages", "create trigger trg_com_notify_new_order_message\n  after insert on public.custom_order_messages\n  for each row execute function public.com_notify_new_order_message()", "commit", "-- §V(rollback-only): 지원서 INSERT 시 글 작성자 1건(자기 글 지원 무발화) · 메시지 INSERT 시 상대방 1건\n--   (학생→멘토·멘토→학생, 제3자 작성 무발화) · 재실행 중복 0 · domain write 롤백 시 알림 0.\n\n-- >>> NATIVE_BASELINE_PART 0167 | supabase/sql/160_p1_11_notification_helper_acl_hardening.sql | 160_p1_11_notification_helper_acl_hardening.sql <<<\n-- 160_p1_11_notification_helper_acl_hardening.sql\n-- [적용됨 — ssambership-staging 에 2026-07-20 적용. ACL 확인: 두 헬퍼 postgres/service_role 전용.\n--   적용 후 staging fixture 재실행 24/24 PASS(트리거 경유 호출 무영향). 적용 이력: docs/audit/sql_apply_manifest.md]\n-- P1-11 후속 수렴 — 157 표시 헬퍼 ACL 최소화.\n-- 배경: 157 적용 시 Supabase 기본 권한(ALTER DEFAULT PRIVILEGES)이 신규 함수에\n--   anon/authenticated EXECUTE 를 부여한다. 157 파일의 `revoke ... from public` 은 PUBLIC 부여분만\n--   제거하므로, SECURITY DEFINER 로 users 를 읽는 표시 헬퍼 2종이 anon/authenticated 에서 직접 호출\n--   가능한 상태로 남았다(UUID 를 아는 호출자에게 full_name/nickname 노출 표면 — 138/140 과 동일 계열).\n-- 조치: 두 헬퍼에서 anon/authenticated EXECUTE 를 revoke. 트리거 실행은 함수 owner(postgres) 권한으로\n--   검사되므로 157~159 트리거 동작에는 영향이 없다(적용 후 fixture 재검증으로 확인).\n-- 참고: 트리거 함수(sbe_/sub_/mp_/refund_/mplan_/cra_/com_·155 iq_*)는 trigger 반환형이라 SQL 에서\n--   직접 호출이 불가해 노출 표면이 아니며, cash/date 라벨 헬퍼는 테이블을 읽지 않는 순수 포매터다 — 모두 무변경.\n-- 선행: 157.\n\nbegin", "revoke execute on function public.notification_display_name(uuid) from anon, authenticated", "revoke execute on function public.notification_mentor_label(uuid) from anon, authenticated", "commit", "-- §V: pg_proc ACL 에 anon/authenticated 부재 · service_role/postgres 유지 ·\n--   157~159 fixture 재실행 전부 PASS(트리거 경유 호출 무영향).\n\n-- >>> NATIVE_BASELINE_PART 0168 | supabase/sql/161_p1_10_account_deletion_self_rpc.sql | 161_p1_10_account_deletion_self_rpc.sql <<<\n-- 161_p1_10_account_deletion_self_rpc.sql\n-- [적용됨 — ssambership-staging 에 2026-07-21 적용(MCP execute_sql 단일 트랜잭션,\n--   DDL 커밋 + fixture 는 savepoint 안 ROLLBACK). T1~T4 + S1~S5 + baseline 전부 PASS.\n--   fixture 보정: public.users.role NOT NULL → (id, role=''student'') 로 upsert(1차 시도는\n--   이 제약으로 전체 롤백·함수 미적용, 2차 성공). 적용 이력: docs/audit/sql_apply_manifest.md]\n-- P1-10 후속 — 계정 탈퇴 self RPC 3종(요청/취소/상태).\n-- 배경: 151/154 의 raw `account_deletion_request(p_user_id,…)`/`account_deletion_cancel(p_user_id)` 는\n--   호출자와 p_user_id 일치 검사가 없어(worker/service_role 전제) authenticated 에 GRANT 만 추가하면\n--   타인의 탈퇴 job 을 생성·취소할 수 있다. → GRANT 금지, 본인 ID 를 서버(auth.uid())에서만 도출하는\n--   self wrapper 를 신설하고 raw 는 service_role 전용으로 유지한다.\n-- 조치:\n--   1) account_deletion_request_self(p_cancelable_minutes int=30, p_dry_run bool=false) → jsonb\n--      - auth.uid() 필수(미로그인 AUTH_REQUIRED). 사용자 인자로 타인 ID 를 받지 않음.\n--      - 동일 사용자 동시 요청은 pg_advisory_xact_lock 으로 직렬화(1 job 보장, raw upsert 와 이중 방어).\n--      - 내부에서 raw request 호출(기존 job 이면 멱등 성공) 후 job 행을 읽어\n--        {ok, existing, job_id, state, cancelable_until, dry_run} 반환.\n--   2) account_deletion_cancel_self() → jsonb — auth.uid() 만. raw cancel 위임\n--      (pending + cancelable_until 이내만 ok, locked/purging 이후 NOT_CANCELABLE).\n--   3) account_deletion_status_self() → jsonb — {ok, exists, state, cancelable_until,\n--      write_blocked, can_cancel}. worker 내부 정보(last_error/lease/purge 타임스탬프) 미반환.\n-- 권한: self 3종 = authenticated·service_role EXECUTE(public/anon revoke).\n--   raw request/cancel/advance/claim/worker 계열 ACL 은 변경하지 않는다(service_role 전용 유지 — §V 에서 확인만).\n-- 선행: 151, 154.\n\nbegin", "-- ── 1. 요청 ────────────────────────────────────────────────────────────────\ncreate or replace function public.account_deletion_request_self(\n  p_cancelable_minutes integer default 30,\n  p_dry_run boolean default false\n) returns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_raw jsonb;\n  v_job_id uuid;\n  v_state text;\n  v_cancelable timestamptz;\n  v_dry boolean;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n  -- 동일 사용자 요청 직렬화(트랜잭션 종료 시 자동 해제).\n  perform pg_advisory_xact_lock(hashtextextended(''account_deletion_self:'' || v_uid::text, 0));\n\n  v_raw := public.account_deletion_request(\n    v_uid, greatest(0, coalesce(p_cancelable_minutes, 30)), coalesce(p_dry_run, false));\n\n  select j.id, j.state, j.cancelable_until, j.dry_run\n    into v_job_id, v_state, v_cancelable, v_dry\n  from public.account_deletion_jobs j\n  where j.user_id = v_uid;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''existing'', coalesce((v_raw ->> ''existing'')::boolean, true),\n    ''job_id'', v_job_id,\n    ''state'', v_state,\n    ''cancelable_until'', v_cancelable,\n    ''dry_run'', v_dry\n  );\nend;\n$$", "-- ── 2. 취소 ────────────────────────────────────────────────────────────────\ncreate or replace function public.account_deletion_cancel_self()\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_uid uuid := (select auth.uid());\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n  perform pg_advisory_xact_lock(hashtextextended(''account_deletion_self:'' || v_uid::text, 0));\n  -- raw cancel 이 pending + cancelable_until 이내만 ok 를 준다\n  -- (locked/purging 등은 NOT_CANCELABLE, 창 경과는 CANCEL_WINDOW_PASSED).\n  return public.account_deletion_cancel(v_uid);\nend;\n$$", "-- ── 3. 상태 조회 ────────────────────────────────────────────────────────────\ncreate or replace function public.account_deletion_status_self()\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_job record;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n  select j.state, j.cancelable_until into v_job\n  from public.account_deletion_jobs j\n  where j.user_id = v_uid;\n  if not found then\n    return jsonb_build_object(\n      ''ok'', true, ''exists'', false, ''state'', null,\n      ''cancelable_until'', null, ''write_blocked'', false, ''can_cancel'', false);\n  end if;\n  -- 민감한 worker 오류·purge 내부 정보는 반환하지 않는다.\n  return jsonb_build_object(\n    ''ok'', true,\n    ''exists'', true,\n    ''state'', v_job.state,\n    ''cancelable_until'', v_job.cancelable_until,\n    ''write_blocked'', v_job.state in\n      (''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted''),\n    ''can_cancel'', v_job.state = ''pending''\n      and (v_job.cancelable_until is null or now() <= v_job.cancelable_until)\n  );\nend;\n$$", "-- ── 권한: self 3종 = authenticated/service_role 만 ─────────────────────────\nrevoke all on function public.account_deletion_request_self(integer, boolean) from public, anon", "revoke all on function public.account_deletion_cancel_self() from public, anon", "revoke all on function public.account_deletion_status_self() from public, anon", "grant execute on function public.account_deletion_request_self(integer, boolean) to authenticated, service_role", "grant execute on function public.account_deletion_cancel_self() to authenticated, service_role", "grant execute on function public.account_deletion_status_self() to authenticated, service_role", "comment on function public.account_deletion_request_self(integer, boolean) is\n  ''P1-10: 본인(auth.uid) 탈퇴 요청 self wrapper. raw request 는 service_role 전용 유지.''", "comment on function public.account_deletion_cancel_self() is\n  ''P1-10: 본인 탈퇴 취소(pending+취소창 이내만). raw cancel 은 service_role 전용 유지.''", "comment on function public.account_deletion_status_self() is\n  ''P1-10: 본인 탈퇴 상태(민감 worker 정보 미반환).''", "commit", "-- §V(적용 시 함께 실행한 검증 요약):\n--   T1 self 3종 존재·SECURITY DEFINER·search_path=public·owner=postgres\n--   T2 self 3종 ACL = authenticated/service_role 만(anon/public 없음)\n--   T3 raw request/cancel ACL 불변(postgres/service_role 전용 — authenticated 없음)\n--   T4 request_self 본문에 advisory lock sentinel 존재(동시성 직렬화 —\n--      독립 2세션 실측은 단일 트랜잭션 검증 한계로 PENDING, 124 선례와 동일)\n--   S1 미로그인(claims 없음) → AUTH_REQUIRED\n--   S2 사용자 A request_self(dry_run=true) → 신규 pending job + cancelable_until 반환,\n--      재호출 → existing=true·같은 job_id(멱등·1 job)\n--   S3 A status_self → exists·pending·can_cancel=true / A cancel_self → ok=true\n--   S4 job 을 locked 로 강제 후 cancel_self → NOT_CANCELABLE, status_self →\n--      write_blocked=true·can_cancel=false\n--   S5 authenticated 로 raw account_deletion_request(B.id,…) 직접 호출 → permission denied\n--      (A 가 B 의 job 을 생성·취소할 수 없음 — self 는 인자 자체가 없음)\n--   fixture(auth.users 2명·jobs)는 전부 savepoint 안 → ROLLBACK(잔여 0, dry_run=true 만 사용,\n--   실계정·실탈퇴 없음)\n\n-- >>> NATIVE_BASELINE_PART 0169 | supabase/sql/162_mobile_app_version_policy.sql | 162_mobile_app_version_policy.sql <<<\n-- 162_mobile_app_version_policy.sql\n-- [적용됨 — ssambership-staging 에 2026-07-21 적용(MCP execute_sql 단일 트랜잭션).\n--   T1~T4 + S1~S4 + baseline 전부 PASS. seed=android/ios min=1(비차단).\n--   적용 이력: docs/audit/sql_apply_manifest.md]\n-- Track E 게이트 1/2 — 모바일 앱 최소 지원 버전 정책(강제 업데이트 인프라).\n-- 배경: 게시판 댓글 정본(comments) 전환 시 구버전 앱(legacy write)과 신버전 앱의 데이터\n--   갈라짐을 막으려면 서버 최소버전 응답 + 앱 시작 게이트가 필요하다(앱 계획 §0-2).\n-- 설계:\n--   - 정본 비교값은 build number 정수(min_supported_build/latest_build) — 버전 문자열\n--     비교(''1.10'' < ''1.9'' 오판) 금지. minimum_version_name 은 표시용.\n--   - 테이블 `mobile_app_version_policies`: RLS on·정책 0(직접 접근 불가) + anon/authenticated\n--     테이블 권한 revoke → write 는 service_role 만.\n--   - store_url 은 저장 시 CHECK 로 HTTPS + Google Play/App Store 허용 호스트만\n--     (임의 URL 저장 자체가 불가). NULL 허용(스토어 등재 전).\n--   - RPC `get_mobile_app_version_policy(p_platform)`: 앱 시작·로그인 전 호출 →\n--     anon/authenticated EXECUTE. platform allowlist(android|ios) 밖은 INVALID_PLATFORM.\n--     행 부재 시 차단하지 않는 기본값(min=1) 반환 — RPC 실패(네트워크)와\n--     강제업데이트 필요 상태는 앱에서 분리 처리(실패=재시도 화면).\n--   - 초기 seed: android/ios min_supported_build=1, latest_build=1 — 현재 앱(build 1)을\n--     차단하지 않는 값. ★실제 최소 build 상향은 이 SQL 범위 밖(운영 절차로만).\n-- 선행: 없음(독립).\n\nbegin", "create table if not exists public.mobile_app_version_policies (\n  platform text primary key\n    constraint mavp_platform_chk check (platform in (''android'',''ios'')),\n  min_supported_build integer not null default 1\n    constraint mavp_min_build_chk check (min_supported_build >= 1),\n  latest_build integer not null default 1,\n  minimum_version_name text,\n  store_url text\n    constraint mavp_store_url_chk check (\n      store_url is null or (\n        store_url like ''https://%'' and (\n          store_url like ''https://play.google.com/%''\n          or store_url like ''https://apps.apple.com/%''\n          or store_url like ''https://itunes.apple.com/%''\n        )\n      )\n    ),\n  message text,\n  updated_at timestamptz not null default now(),\n  constraint mavp_latest_ge_min_chk check (latest_build >= min_supported_build)\n)", "alter table public.mobile_app_version_policies enable row level security", "revoke all on table public.mobile_app_version_policies from public, anon, authenticated", "drop trigger if exists trg_mavp_set_updated on public.mobile_app_version_policies", "create trigger trg_mavp_set_updated\n  before update on public.mobile_app_version_policies\n  for each row execute function public.set_updated_at()", "-- 초기 seed — 현재 앱을 차단하지 않는 값(멱등).\ninsert into public.mobile_app_version_policies (platform, min_supported_build, latest_build)\nvalues (''android'', 1, 1), (''ios'', 1, 1)\non conflict (platform) do nothing", "create or replace function public.get_mobile_app_version_policy(p_platform text)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_row public.mobile_app_version_policies;\nbegin\n  if p_platform is null or lower(btrim(p_platform)) not in (''android'',''ios'') then\n    raise exception ''INVALID_PLATFORM'' using errcode = ''22023'';\n  end if;\n  select * into v_row from public.mobile_app_version_policies\n  where platform = lower(btrim(p_platform));\n  if not found then\n    -- 정책 행 부재 = 차단하지 않는 기본값(게이트 fail-open 은 여기까지 —\n    -- RPC/네트워크 실패는 앱이 재시도 화면으로 분리 처리).\n    return jsonb_build_object(\n      ''platform'', lower(btrim(p_platform)),\n      ''min_supported_build'', 1,\n      ''latest_build'', 1,\n      ''minimum_version_name'', null,\n      ''store_url'', null,\n      ''message'', null);\n  end if;\n  return jsonb_build_object(\n    ''platform'', v_row.platform,\n    ''min_supported_build'', v_row.min_supported_build,\n    ''latest_build'', v_row.latest_build,\n    ''minimum_version_name'', v_row.minimum_version_name,\n    ''store_url'', v_row.store_url,\n    ''message'', v_row.message);\nend;\n$$", "revoke all on function public.get_mobile_app_version_policy(text) from public", "grant execute on function public.get_mobile_app_version_policy(text) to anon, authenticated, service_role", "comment on table public.mobile_app_version_policies is\n  ''Track E: 모바일 최소 지원 build 정책(정수 비교 정본). write=service_role, read=RPC 경유만.''", "comment on function public.get_mobile_app_version_policy(text) is\n  ''Track E: 앱 시작 게이트용 버전 정책 조회(anon 허용·platform allowlist).''", "commit", "-- §V(적용 시 함께 실행한 검증 요약):\n--   T1 테이블 존재·RLS on·정책 0·anon/authenticated 테이블 권한 없음\n--   T2 CHECK: platform allowlist / min>=1 / latest>=min / store_url HTTPS+스토어 호스트만\n--   T3 RPC anon+authenticated EXECUTE, secdef, search_path=public\n--   T4 seed 2행(android/ios, min=1·latest=1 — 현재 앱 비차단)\n--   S1 get(''android'') → min_supported_build=1(정수)·jsonb 필드 전체\n--   S2 get(''windows'') → INVALID_PLATFORM\n--   S3 (savepoint) store_url=''http://play.google.com/…'' 및 ''https://evil.com/…'' UPDATE → CHECK 거부,\n--      ''https://play.google.com/store/apps/details?id=com.ssambership.app'' → 허용 후 롤백\n--   S4 (savepoint) authenticated 로 테이블 직접 SELECT/UPDATE → 권한 거부(RPC 경유만)\n--   S5 build 비교는 정수 계약 — ''1.10''/''1.9'' 문자열 비교 오판 원천 배제(스키마 타입 integer 확인)\n--   fixture 전부 savepoint ROLLBACK, seed 만 커밋(비차단 값)\n\n-- >>> NATIVE_BASELINE_PART 0170 | supabase/sql/163_board_comment_canonical_bridge.sql | 163_board_comment_canonical_bridge.sql <<<\n-- 163_board_comment_canonical_bridge.sql\n-- [적용됨 — ssambership-staging 에 2026-07-21 적용(MCP execute_sql 단일 트랜잭션,\n--   DDL 커밋 + fixture 는 savepoint ROLLBACK). T1~T2 + S1~S8 + baseline 전부 PASS\n--   (양방향 동기화·soft-delete·depth/보호필드/hard-delete 가드·숏폼 제외·수 일치).\n--   적용 이력: docs/audit/sql_apply_manifest.md]\n-- Track E 게이트 2/2 — 게시판 댓글 legacy(community_comments) ↔ 정본(comments) 호환 브리지.\n-- 배경(2026-07-21 staging 실측): 웹·현행 앱 모두 board 댓글을 community_comments 에 쓰고,\n--   정본 comments 는 양쪽 다 미사용(두 테이블 모두 0행 — 백필·중복 격리 대상 없음).\n--   신버전 앱이 comments 로 전환해도 구버전 앱·현행 웹이 legacy 를 계속 읽고 쓰는 동안\n--   양쪽 어디에 써도 서로 보이도록 **양방향 멱등 동기화**로 데이터 갈라짐을 막는다.\n--   (숏폼 댓글은 community_comments(post_type=''shortform'') 유지 — 동기화 대상 아님.)\n-- 설계:\n--   - 매핑: comments.legacy_comment_id(uuid UNIQUE, legacy 원본 id) /\n--           community_comments.canonical_comment_id(uuid UNIQUE, 정본 id) — 중복 방지 UNIQUE.\n--   - 재귀 방지: GUC ''app.comment_sync''(트랜잭션 로컬) — 동기화 중 상대 트리거 스킵.\n--   - legacy→정본: board INSERT/UPDATE 를 comments 에 upsert(body→content,\n--     status<>''visible''→is_deleted). legacy DELETE(관리자 hard delete 정책)는 정본을\n--     삭제하지 않고 is_deleted=true 로만 반영(기존 행 자동 삭제 금지).\n--   - 정본→legacy: legacy 미러 upsert(content→body 1000자 절단, is_deleted→status hidden).\n--     정본 hard DELETE(관리자)도 legacy 는 hidden 처리만. reply(parent)는 legacy 에\n--     parent 개념이 없어 평면 미러(구버전 표시 한계 — 전환 공지 사항).\n--   - 정본 가드(comments_write_guard, 신뢰 안 된 writer 만):\n--     · INSERT: legacy_comment_id 위조 금지 / parent 는 같은 post + 최대 2-depth\n--       (parent 의 parent 금지) / 다른 post 부모 참조 거부\n--     · UPDATE: 보호필드(id/post_id/author_id/parent_id/created_at/legacy_comment_id/\n--       like_count) 불변 — content/is_deleted 만 수정 가능\n--     · DELETE: 관리자 외 hard DELETE 거부(soft-delete 강제)\n--   - comment count: trg_comments_refresh_count(기존)가 comments 기준으로\n--     community_posts.comment_count 를 유지 — 양방향 미러로 legacy 행수와 일치.\n-- 선행: 없음(comments/community_comments 는 기존 스키마). 웹 write 경로는 무변경\n--   (legacy 에 계속 써도 정본에 동기화됨 — 앱 배포 전 legacy write 제거 금지 원칙 준수).\n\nbegin", "-- ── 매핑 컬럼 ────────────────────────────────────────────────────────────────\nalter table public.comments\n  add column if not exists legacy_comment_id uuid", "create unique index if not exists comments_legacy_comment_id_key\n  on public.comments (legacy_comment_id) where legacy_comment_id is not null", "alter table public.community_comments\n  add column if not exists canonical_comment_id uuid", "create unique index if not exists community_comments_canonical_id_key\n  on public.community_comments (canonical_comment_id) where canonical_comment_id is not null", "-- ── 재귀 방지 헬퍼 ───────────────────────────────────────────────────────────\ncreate or replace function public.comment_sync_in_progress()\nreturns boolean language sql stable\nas $$ select coalesce(current_setting(''app.comment_sync'', true), ''0'') = ''1'' $$", "-- ── 정본 write 가드(신뢰 안 된 writer 만) ────────────────────────────────────\ncreate or replace function public.comments_write_guard()\nreturns trigger\nlanguage plpgsql\nset search_path to ''public''\nas $$\ndeclare v_parent public.comments;\nbegin\n  if public.comment_sync_in_progress() then\n    return coalesce(new, old);\n  end if;\n  if current_user not in (''authenticated'', ''anon'') then\n    return coalesce(new, old);\n  end if;\n\n  if tg_op = ''DELETE'' then\n    if coalesce((select public.is_admin()), false) then return old; end if;\n    raise exception ''COMMENT_HARD_DELETE_FORBIDDEN'';\n  end if;\n\n  if tg_op = ''INSERT'' then\n    if new.legacy_comment_id is not null then\n      raise exception ''COMMENT_LEGACY_ID_FORBIDDEN'';\n    end if;\n    if new.parent_id is not null then\n      select * into v_parent from public.comments where id = new.parent_id;\n      if not found then raise exception ''COMMENT_PARENT_NOT_FOUND''; end if;\n      if v_parent.post_id is distinct from new.post_id then\n        raise exception ''COMMENT_PARENT_POST_MISMATCH'';\n      end if;\n      if v_parent.parent_id is not null then\n        raise exception ''COMMENT_DEPTH_EXCEEDED'';\n      end if;\n    end if;\n    return new;\n  end if;\n\n  -- UPDATE: 보호필드 불변(content/is_deleted 만 허용).\n  if new.id is distinct from old.id\n     or new.post_id is distinct from old.post_id\n     or new.author_id is distinct from old.author_id\n     or new.parent_id is distinct from old.parent_id\n     or new.created_at is distinct from old.created_at\n     or new.legacy_comment_id is distinct from old.legacy_comment_id\n     or new.like_count is distinct from old.like_count then\n    raise exception ''COMMENT_PROTECTED_FIELDS_IMMUTABLE'';\n  end if;\n  return new;\nend;\n$$", "drop trigger if exists trg_comments_write_guard on public.comments", "create trigger trg_comments_write_guard\n  before insert or update or delete on public.comments\n  for each row execute function public.comments_write_guard()", "-- ── legacy(board) → 정본 동기화 ─────────────────────────────────────────────\ncreate or replace function public.cc_sync_board_to_canonical()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare v_canonical uuid;\nbegin\n  if public.comment_sync_in_progress() then return new; end if;\n  perform set_config(''app.comment_sync'', ''1'', true);\n\n  insert into public.comments (post_id, author_id, content, is_deleted, created_at, legacy_comment_id)\n  values (new.post_id, new.author_id, new.body, new.status <> ''visible'', new.created_at, new.id)\n  on conflict (legacy_comment_id) where legacy_comment_id is not null\n  do update set content = excluded.content, is_deleted = excluded.is_deleted\n  returning id into v_canonical;\n\n  if v_canonical is null then\n    select id into v_canonical from public.comments where legacy_comment_id = new.id;\n  end if;\n  if new.canonical_comment_id is distinct from v_canonical then\n    update public.community_comments set canonical_comment_id = v_canonical where id = new.id;\n  end if;\n\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return new;\nend;\n$$", "drop trigger if exists trg_cc_sync_board_to_canonical on public.community_comments", "create trigger trg_cc_sync_board_to_canonical\n  after insert or update on public.community_comments\n  for each row when (new.post_type = ''board'')\n  execute function public.cc_sync_board_to_canonical()", "create or replace function public.cc_sync_board_delete_to_canonical()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\nbegin\n  if public.comment_sync_in_progress() then return old; end if;\n  perform set_config(''app.comment_sync'', ''1'', true);\n  -- 기존 행 자동 삭제 금지 — soft-delete 만 반영.\n  update public.comments set is_deleted = true where legacy_comment_id = old.id;\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return old;\nend;\n$$", "drop trigger if exists trg_cc_sync_board_delete on public.community_comments", "create trigger trg_cc_sync_board_delete\n  after delete on public.community_comments\n  for each row when (old.post_type = ''board'')\n  execute function public.cc_sync_board_delete_to_canonical()", "-- ── 정본 → legacy 미러 ──────────────────────────────────────────────────────\ncreate or replace function public.comments_mirror_to_legacy()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare v_body text;\nbegin\n  if public.comment_sync_in_progress() then return new; end if;\n  if new.legacy_comment_id is not null then return new; end if; -- legacy 원본은 A 가 유지.\n  v_body := left(coalesce(new.content, ''''), 1000);\n  if char_length(btrim(v_body)) < 1 then return new; end if; -- legacy CHECK(1..1000) 불충족 시 미러 생략.\n  perform set_config(''app.comment_sync'', ''1'', true);\n\n  insert into public.community_comments (post_id, post_type, author_id, body, status, created_at, canonical_comment_id)\n  values (new.post_id, ''board'', new.author_id, v_body,\n          case when coalesce(new.is_deleted, false) then ''hidden'' else ''visible'' end,\n          coalesce(new.created_at, now()), new.id)\n  on conflict (canonical_comment_id) where canonical_comment_id is not null\n  do update set body = excluded.body, status = excluded.status;\n\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return new;\nend;\n$$", "drop trigger if exists trg_comments_mirror_to_legacy on public.comments", "create trigger trg_comments_mirror_to_legacy\n  after insert or update on public.comments\n  for each row execute function public.comments_mirror_to_legacy()", "create or replace function public.comments_mirror_delete_to_legacy()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\nbegin\n  if public.comment_sync_in_progress() then return old; end if;\n  perform set_config(''app.comment_sync'', ''1'', true);\n  -- legacy 미러도 삭제하지 않고 hidden 처리만.\n  update public.community_comments set status = ''hidden'' where canonical_comment_id = old.id;\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return old;\nend;\n$$", "drop trigger if exists trg_comments_mirror_delete on public.comments", "create trigger trg_comments_mirror_delete\n  after delete on public.comments\n  for each row execute function public.comments_mirror_delete_to_legacy()", "commit", "-- §V(적용 시 함께 실행한 검증 요약):\n--   T1 매핑 컬럼+부분 UNIQUE 2종, 가드/동기화 트리거 5종 존재\n--   T2 동기화 함수 4종 SECURITY DEFINER + search_path=public(가드는 invoker)\n--   S1 legacy board INSERT(authenticated) → 정본 1행(body→content·매핑 양방향)·중복 0\n--   S2 legacy UPDATE(status hidden) → 정본 is_deleted=true\n--   S3 legacy DELETE → 정본 행 유지 + is_deleted=true(자동 삭제 없음)\n--   S4 정본 INSERT → legacy 미러 1행(visible)·comment_count 반영, 정본 soft-delete →\n--      legacy hidden, 정본 DELETE(관리자) → legacy hidden 유지\n--   S5 depth: 최상위→답글 OK, 답글의 답글 → COMMENT_DEPTH_EXCEEDED,\n--      다른 post 부모 → COMMENT_PARENT_POST_MISMATCH\n--   S6 신뢰 안 된 writer: author_id 변조 UPDATE → PROTECTED_FIELDS,\n--      비관리자 hard DELETE → HARD_DELETE_FORBIDDEN, legacy_comment_id 위조 INSERT → 거부\n--   S7 shortform legacy INSERT → 정본 미생성(동기화 대상 아님)\n--   S8 board 댓글 수: comments(비삭제) == community_comments(board·visible) 일치\n--   fixture(auth/public users·community_posts·양 테이블) 전부 savepoint ROLLBACK, baseline 0행 복원\n\n-- >>> NATIVE_BASELINE_PART 0171 | supabase/sql/164_board_comment_bridge_bidirectional_convergence.sql | 164_board_comment_bridge_bidirectional_convergence.sql <<<\n-- 164_board_comment_bridge_bidirectional_convergence.sql\n-- [적용됨 — ssambership-staging 에 2026-07-21 적용(MCP execute_sql 단일 트랜잭션,\n--   함수/트리거 커밋 + fixture 는 savepoint ROLLBACK). 적용 전 163 결함 A/B/C 를\n--   rollback-only 스크립트로 재현 확정 → 적용 후 T1 + F1~F15 + baseline(F16/F17)\n--   전부 PASS. 적용 이력: docs/audit/sql_apply_manifest.md]\n-- 163 후속 보정 — 게시판 댓글 브리지의 ''교차 수정/삭제'' 수렴.\n-- 배경(2026-07-21 staging 재현 — rollback-only, 3건 전부 재현 확정):\n--   [A] canonical-origin 댓글의 legacy 미러를 구버전 경로(UPDATE)로 고치면\n--       cc_sync 가 canonical_comment_id 를 무시하고 legacy_comment_id(=미러 id) 기준\n--       upsert 를 해 **canonical 중복 행**을 만든다(원본 미갱신).\n--   [B] 같은 미러를 DELETE 하면 legacy_comment_id=old.id 로만 찾아\n--       canonical 원본(legacy_comment_id NULL)을 soft-delete 하지 못한다.\n--   [C] legacy-origin 의 canonical 행을 신버전이 UPDATE 하면 mirror 함수가\n--       legacy_comment_id IS NOT NULL 에서 즉시 return 해 legacy 원본에 반영되지 않는다.\n-- 조치(163 파일은 수정하지 않고 함수만 교체 + legacy 매핑 보호 가드 신설):\n--   - legacy→canonical: new.canonical_comment_id 가 있으면 그 canonical 행을 FOR UPDATE 잠금,\n--     post/author 정합 검증 후 content/is_deleted 만 UPDATE(새 행 생성 금지). 대상 없음·타 post·\n--     타 작성자는 명시적 실패. 포인터 없는 legacy-origin 만 기존 멱등 upsert.\n--   - legacy DELETE: old.canonical_comment_id 우선, 없으면 legacy_comment_id=old.id 로\n--     canonical soft-delete(hard DELETE 금지). 대상 0행이면 성공으로 위장하지 않고 실패.\n--   - canonical→legacy: new.legacy_comment_id 가 있으면 return 하지 않고 legacy 원본을 찾아\n--     body/status 갱신(매핑 canonical_comment_id=new.id 또는 NULL→세팅, 새 행 생성 금지,\n--     불일치·부재는 명시적 실패). canonical-origin 만 기존 canonical_comment_id 미러 upsert.\n--   - canonical DELETE 미러: canonical-origin(canonical_comment_id=old.id)과\n--     legacy-origin(id=old.legacy_comment_id) 모두 hidden 처리.\n--   - 신설 cc_write_guard(BEFORE, 신뢰 안 된 writer 만): INSERT 시 canonical_comment_id\n--     직접 지정 금지, UPDATE 시 canonical_comment_id/id/post_id/post_type/author_id/created_at\n--     불변(body/status 는 허용 — 관리자 moderation 무영향). SECURITY DEFINER 동기화 경로는\n--     GUC/role 로 통과. 숏폼 write 회귀 없음(포인터를 원래 안 보냄).\n-- 선행: 163.\n\nbegin", "-- ── 0. legacy 매핑 보호 가드(신설) ──────────────────────────────────────────\ncreate or replace function public.cc_write_guard()\nreturns trigger\nlanguage plpgsql\nset search_path to ''public''\nas $$\nbegin\n  if public.comment_sync_in_progress() then return new; end if;\n  if current_user not in (''authenticated'', ''anon'') then return new; end if;\n\n  if tg_op = ''INSERT'' then\n    if new.canonical_comment_id is not null then\n      raise exception ''CC_CANONICAL_ID_FORBIDDEN'';\n    end if;\n    return new;\n  end if;\n\n  -- UPDATE: 매핑·식별 필드 불변(body/status 만 수정 가능).\n  if new.canonical_comment_id is distinct from old.canonical_comment_id\n     or new.id is distinct from old.id\n     or new.post_id is distinct from old.post_id\n     or new.post_type is distinct from old.post_type\n     or new.author_id is distinct from old.author_id\n     or new.created_at is distinct from old.created_at then\n    raise exception ''CC_PROTECTED_FIELDS_IMMUTABLE'';\n  end if;\n  return new;\nend;\n$$", "drop trigger if exists trg_cc_write_guard on public.community_comments", "create trigger trg_cc_write_guard\n  before insert or update on public.community_comments\n  for each row execute function public.cc_write_guard()", "-- ── 1. legacy(board) → canonical: 포인터 우선 수렴 ──────────────────────────\ncreate or replace function public.cc_sync_board_to_canonical()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_canonical uuid;\n  v_target public.comments;\nbegin\n  if public.comment_sync_in_progress() then return new; end if;\n  perform set_config(''app.comment_sync'', ''1'', true);\n\n  if new.canonical_comment_id is not null then\n    -- 이미 매핑된 행(canonical-origin 미러 포함) → 그 canonical 행만 갱신.\n    select * into v_target from public.comments\n    where id = new.canonical_comment_id for update;\n    if not found then\n      raise exception ''COMMENT_BRIDGE_TARGET_MISSING'';\n    end if;\n    if v_target.post_id is distinct from new.post_id then\n      raise exception ''COMMENT_BRIDGE_POST_MISMATCH'';\n    end if;\n    if v_target.author_id is distinct from new.author_id then\n      raise exception ''COMMENT_BRIDGE_AUTHOR_MISMATCH'';\n    end if;\n    update public.comments\n      set content = new.body, is_deleted = (new.status <> ''visible'')\n    where id = new.canonical_comment_id;\n  else\n    -- 포인터 없는 legacy-origin 만 멱등 upsert(163 동일) + 포인터 세팅.\n    insert into public.comments (post_id, author_id, content, is_deleted, created_at, legacy_comment_id)\n    values (new.post_id, new.author_id, new.body, new.status <> ''visible'', new.created_at, new.id)\n    on conflict (legacy_comment_id) where legacy_comment_id is not null\n    do update set content = excluded.content, is_deleted = excluded.is_deleted\n    returning id into v_canonical;\n    if v_canonical is null then\n      select id into v_canonical from public.comments where legacy_comment_id = new.id;\n    end if;\n    update public.community_comments set canonical_comment_id = v_canonical where id = new.id;\n  end if;\n\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return new;\nend;\n$$", "-- ── 2. legacy DELETE → canonical soft-delete(포인터 우선) ───────────────────\ncreate or replace function public.cc_sync_board_delete_to_canonical()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare v_rows int;\nbegin\n  if public.comment_sync_in_progress() then return old; end if;\n  perform set_config(''app.comment_sync'', ''1'', true);\n\n  if old.canonical_comment_id is not null then\n    update public.comments set is_deleted = true where id = old.canonical_comment_id;\n  else\n    update public.comments set is_deleted = true where legacy_comment_id = old.id;\n  end if;\n  get diagnostics v_rows = row_count;\n  if v_rows = 0 then\n    -- 대상 없음을 성공으로 위장하지 않는다(수렴 실패를 드러냄).\n    raise exception ''COMMENT_BRIDGE_TARGET_MISSING'';\n  end if;\n\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return old;\nend;\n$$", "-- ── 3. canonical → legacy: legacy-origin 도 원본 갱신 ───────────────────────\ncreate or replace function public.comments_mirror_to_legacy()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_body text;\n  v_rows int;\nbegin\n  if public.comment_sync_in_progress() then return new; end if;\n  perform set_config(''app.comment_sync'', ''1'', true);\n\n  v_body := left(coalesce(new.content, ''''), 1000);\n\n  if new.legacy_comment_id is not null then\n    -- legacy-origin: 원본 갱신(새 행 생성 금지, 매핑 일치 확인·NULL 이면 세팅).\n    if char_length(btrim(v_body)) >= 1 then\n      update public.community_comments\n        set body = v_body,\n            status = case when coalesce(new.is_deleted, false) then ''hidden'' else ''visible'' end,\n            canonical_comment_id = new.id\n      where id = new.legacy_comment_id\n        and (canonical_comment_id = new.id or canonical_comment_id is null);\n    else\n      -- legacy body CHECK(1..1000) 보호 — 상태만 동기화.\n      update public.community_comments\n        set status = case when coalesce(new.is_deleted, false) then ''hidden'' else ''visible'' end,\n            canonical_comment_id = new.id\n      where id = new.legacy_comment_id\n        and (canonical_comment_id = new.id or canonical_comment_id is null);\n    end if;\n    get diagnostics v_rows = row_count;\n    if v_rows = 0 then\n      -- 원본 부재 또는 매핑 불일치 — 성공으로 위장하지 않는다.\n      raise exception ''COMMENT_BRIDGE_LEGACY_MISSING'';\n    end if;\n  else\n    -- canonical-origin: 기존 미러 upsert(163 동일). 빈 본문은 미러 생략(CHECK 보호).\n    if char_length(btrim(v_body)) >= 1 then\n      insert into public.community_comments (post_id, post_type, author_id, body, status, created_at, canonical_comment_id)\n      values (new.post_id, ''board'', new.author_id, v_body,\n              case when coalesce(new.is_deleted, false) then ''hidden'' else ''visible'' end,\n              coalesce(new.created_at, now()), new.id)\n      on conflict (canonical_comment_id) where canonical_comment_id is not null\n      do update set body = excluded.body, status = excluded.status;\n    end if;\n  end if;\n\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return new;\nend;\n$$", "-- ── 4. canonical DELETE → legacy hidden(양 origin) ──────────────────────────\ncreate or replace function public.comments_mirror_delete_to_legacy()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\nbegin\n  if public.comment_sync_in_progress() then return old; end if;\n  perform set_config(''app.comment_sync'', ''1'', true);\n  update public.community_comments set status = ''hidden''\n  where canonical_comment_id = old.id\n     or (old.legacy_comment_id is not null and id = old.legacy_comment_id);\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return old;\nend;\n$$", "commit", "-- §V(적용 시 함께 실행한 검증 요약):\n--   T1 cc_write_guard 트리거 존재, 동기화 함수 4종 교체 확인(secdef+search_path, 포인터 분기 sentinel)\n--   F1 legacy-origin 생성 → 양쪽 1행 / F2 legacy-origin canonical 수정 → legacy 원본 갱신\n--   F3 legacy-origin canonical soft-delete → legacy hidden / F4 canonical-origin 생성 → 양쪽 1행\n--   F5 canonical-origin legacy 수정 → canonical ''원본'' 갱신 / F6 그 후 canonical 행 수 == 1(중복 0)\n--   F7 canonical-origin legacy DELETE → canonical 잔존+soft-delete / F8 동일 수정 3회 → 양쪽 각 1행\n--   F9 authenticated INSERT 에 canonical_comment_id → 거부 / F10 UPDATE 로 포인터 변경 → 거부\n--   F11 타 post canonical 포인터 → COMMENT_BRIDGE_POST_MISMATCH\n--   F12 타 작성자 canonical 포인터 → COMMENT_BRIDGE_AUTHOR_MISMATCH\n--   F13 shortform 미동기화 / F14 2-depth·타 post parent 기존 가드 유지\n--   F15 canonical(비삭제) == legacy(board·visible) == community_posts.comment_count 일치\n--   F16 fixture 전부 savepoint ROLLBACK / F17 새 조회 baseline 0행 복원\n--   163 결함 재현 스크립트(A/B/C) → 적용 후 동일 시나리오가 수렴(F5~F7)으로 대체됨을 확인\n\n-- >>> NATIVE_BASELINE_PART 0172 | supabase/sql/165_shortform_posts_mentor_insert_policy_convergence.sql | 165_shortform_posts_mentor_insert_policy_convergence.sql <<<\n-- 165_shortform_posts_mentor_insert_policy_convergence.sql\n-- shortform_posts 학생 직접 INSERT 우회 제거 — canonical 멘토 전용 INSERT 로 수렴.\n--\n-- 배경(2026-07-24 staging 실조회·재현 — rollback-only 픽스처):\n--   permissive RLS 는 OR 결합이므로, canonical `sf_insert_mentor`\n--   (authenticated, WITH CHECK: is_mentor() AND (author self OR creator self))가\n--   있어도 아래 레거시 INSERT 정책이 남아 있으면 학생이 PostgREST 직행으로\n--   본인 author_id 행을 INSERT 할 수 있다(서버 액션의 mentor 강제를 우회).\n--     [제거 1] \"멘토만 업로드\"  : TO public,        WITH CHECK (auth.uid() = author_id)\n--                                — 이름과 달리 is_mentor 조건이 없음(038 이전 레거시).\n--     [제거 2] sp_write_self    : TO authenticated, WITH CHECK (author self OR is_admin())\n--                                — 학생 self INSERT 허용 + admin 임의 author 허용(레거시).\n--   적용 전 재현(2026-07-24, 트랜잭션 픽스처·전량 정리): 학생 본인 author_id INSERT\n--   ALLOWED / 타인 author_id 위조 REJECTED(42501) / 멘토 본인 INSERT ALLOWED.\n--\n-- 조치(정확히 INSERT 우회 2건만 — 그 외 불변):\n--   - canonical `sf_insert_mentor` 가 없거나 하는 사이 삭제된 경우를 대비해 먼저\n--     멱등 보장(존재하면 그대로 둠 — 기존 정책 정의 무수정).\n--   - \"멘토만 업로드\", sp_write_self 두 INSERT 정책만 DROP.\n--   - sp_update_self · sf_update_own · sf_delete_own · sf_select_published,\n--     favorites/storage 정책, 기존 행 데이터는 일절 건드리지 않는다.\n--\n-- 적용 후 기대(픽스처): 학생 본인 author_id INSERT REJECTED(42501) /\n--   멘토 본인 INSERT ALLOWED / 위조 REJECTED / INSERT 정책은 sf_insert_mentor 1건.\n-- 선행: 038(shortform v2), 148(멱등키). 후속 없음.\n\n-- 1) canonical mentor INSERT 정책 멱등 보장(부재 시에만 생성 — staging 실측 정의와 동일 식).\ndo $$\nbegin\n  if not exists (\n    select 1 from pg_policies\n    where schemaname = ''public'' and tablename = ''shortform_posts''\n      and policyname = ''sf_insert_mentor'' and cmd = ''INSERT''\n  ) then\n    create policy sf_insert_mentor on public.shortform_posts\n      for insert to authenticated\n      with check (\n        (( select public.is_mentor() ) = true)\n        and (\n          author_id = ( select auth.uid() )\n          or creator_id = ( select auth.uid() )\n        )\n      );\n  end if;\nend $$", "-- 2) 학생 직행 INSERT 를 허용하던 레거시 permissive 정책 2건 제거.\ndrop policy if exists \"멘토만 업로드\" on public.shortform_posts", "drop policy if exists sp_write_self on public.shortform_posts", "-- 검증 쿼리(참고):\n--   select policyname, cmd, roles, with_check from pg_policies\n--   where schemaname=''public'' and tablename=''shortform_posts'' order by cmd, policyname;\n--   기대: INSERT = sf_insert_mentor 1건, UPDATE = sf_update_own·sp_update_self(불변),\n--        DELETE = sf_delete_own(불변), SELECT = sf_select_published(불변).\n\n-- >>> NATIVE_BASELINE_PART 0173 | supabase/sql/166_mentor_plans_default_seed_on_first_approval.sql | 166_mentor_plans_default_seed_on_first_approval.sql <<<\n-- 166_mentor_plans_default_seed_on_first_approval.sql\n-- 멘토 최초 승인 시 기본 요금제 자동 시드 — 승인 전이와 같은 트랜잭션에서 누락 tier 만 보충.\n--\n-- 배경(2026-07-24 staging 실조회):\n--   - 승인 흐름: 관리자 액션이 mentor_profiles.verification_status 를 ''approved'' 로 UPDATE.\n--   - mentor_plans 행이 없으면 실차감액이 권장가 폴백으로만 동작 — 승인 시점에 기본\n--     요금제 3종을 시드해 카탈로그·차감 정본을 DB 행으로 확정한다.\n--   - UNIQUE 상태 정정: (mentor_id, plan_tier) UNIQUE **constraint 는 없음**.\n--     SQL 067 유래 UNIQUE **index** `uq_mentor_plans_mentor_tier`(비partial, (mentor_id,\n--     plan_tier))가 실존하며, PostgreSQL 의 ON CONFLICT (mentor_id, plan_tier) 추론은\n--     UNIQUE index 로도 정상 작동한다. → 이 스크립트는 인덱스를 **검증만** 하고\n--     재생성하지 않는다(부재 환경에서만 방어 생성).\n--\n-- 시드 정본(캐시 권장가 × 100 = cents · CLAUDE.md 잠금값):\n--   limited  2,990,000 / cap 1.0   ·  standard 8,490,000 / cap 2.5   ·  premium 17,490,000 / cap 4.5\n--   label NULL · is_active true · created_at/updated_at/price_updated_at = now()\n--\n-- 규칙:\n--   - ON CONFLICT (mentor_id, plan_tier) DO NOTHING — 기존 plan 의 가격·cap·label·활성\n--     상태를 절대 UPDATE 하지 않는다(커스텀 가격 보존). 누락 tier 만 보충. 반복 승인 멱등.\n--   - 트리거는 ''비승인 → approved'' 전이(UPDATE)에서만 발화. 그 외 전이 미생성.\n--   - SECURITY DEFINER + search_path 고정. EXECUTE 는 트리거 발화에 불필요 — 전부 revoke.\n--   - AFTER ROW 트리거 실패는 승인 UPDATE 와 함께 rollback 된다(원자성).\n--   - 주의: mentor_plans 에는 SQL 158 의 AFTER INSERT 알림 트리거\n--     (trg_mplan_notify_price_insert → mplan_notify_price_changed)가 있어, 시드 INSERT 는\n--     ''활성(active/cancel_scheduled/past_due) 구독자''에게 가격 변경 알림을 fan-out 한다\n--     (tx·구독별 dedup — 동일 tx 다중 tier 는 구독자당 1건). 최초 승인은 구독자 0 이므로\n--     알림 0. 158 은 이 스크립트에서 수정하지 않는다.\n--   - 현재 staging 승인 멘토 2명은 이미 tier 3종을 보유 — backfill 없음(조회 보고만).\n-- 선행: 067(mentor_plans·unique index), 121(밴드 클램프 — 시드값은 밴드 min 과 동일), 158.\n\n-- ── 0. 사전 검증: 중복 0건 + 기존 유니크 인덱스 정의 확인(오정의·중복이면 중단, DROP 금지) ──\ndo $$\ndeclare\n  v_dup integer;\n  v_idx record;\nbegin\n  select count(*) into v_dup from (\n    select mentor_id, plan_tier from public.mentor_plans group by 1, 2 having count(*) > 1\n  ) d;\n  if v_dup > 0 then\n    raise exception ''SQL166_ABORT: mentor_plans 에 (mentor_id, plan_tier) 중복 % 그룹 존재 — 정리 없이 중단(임의 삭제 금지)'', v_dup;\n  end if;\n\n  select i.indisunique as is_unique,\n         (i.indpred is not null) as is_partial,\n         pg_get_indexdef(i.indexrelid) as def\n    into v_idx\n  from pg_index i\n  join pg_class c on c.oid = i.indexrelid\n  join pg_namespace n on n.oid = c.relnamespace\n  where n.nspname = ''public'' and c.relname = ''uq_mentor_plans_mentor_tier'';\n\n  if found then\n    -- 동명 인덱스가 있으면 정의가 정확해야 한다: unique · 비partial · (mentor_id, plan_tier).\n    if (not v_idx.is_unique) or v_idx.is_partial\n       or v_idx.def not like ''%(mentor_id, plan_tier)%'' then\n      raise exception ''SQL166_ABORT: uq_mentor_plans_mentor_tier 정의 불일치(%) — 임의 DROP 하지 않고 중단'', v_idx.def;\n    end if;\n  else\n    -- 인덱스 부재 환경(클린 설치 등)에서만 SQL 067 과 같은 이름·정의로 방어 생성.\n    create unique index if not exists uq_mentor_plans_mentor_tier\n      on public.mentor_plans (mentor_id, plan_tier);\n  end if;\nend $$", "-- ── 1. 시드 함수 ──────────────────────────────────────────────────────────────\ncreate or replace function public.mp_seed_default_plans_on_approval()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\nbegin\n  insert into public.mentor_plans\n    (mentor_id, plan_tier, amount_cents, cap_weight, label, is_active,\n     created_at, updated_at, price_updated_at)\n  values\n    (new.user_id, ''limited'',   2990000, 1.0, null, true, now(), now(), now()),\n    (new.user_id, ''standard'',  8490000, 2.5, null, true, now(), now(), now()),\n    (new.user_id, ''premium'',  17490000, 4.5, null, true, now(), now(), now())\n  on conflict (mentor_id, plan_tier) do nothing;\n  return new;\nend;\n$$", "revoke execute on function public.mp_seed_default_plans_on_approval() from public", "revoke execute on function public.mp_seed_default_plans_on_approval() from anon", "revoke execute on function public.mp_seed_default_plans_on_approval() from authenticated", "-- ── 2. 승인 전이 트리거(비승인 → approved 에서만) ─────────────────────────────\ndrop trigger if exists trg_mp_seed_default_plans on public.mentor_profiles", "create trigger trg_mp_seed_default_plans\n  after update on public.mentor_profiles\n  for each row\n  when (new.verification_status = ''approved''\n        and old.verification_status is distinct from ''approved'')\n  execute function public.mp_seed_default_plans_on_approval()", "-- 검증 쿼리(참고):\n--   select tgname from pg_trigger where tgrelid = ''public.mentor_profiles''::regclass\n--     and tgname = ''trg_mp_seed_default_plans'';\n--   select mentor_id, plan_tier, amount_cents, cap_weight, label, is_active\n--     from mentor_plans order by mentor_id, plan_tier;\n\n-- >>> NATIVE_BASELINE_PART 0174 | supabase/sql/167_iq_attachment_unique_question_storage_path.sql | 167_iq_attachment_unique_question_storage_path.sql <<<\n-- 167_iq_attachment_unique_question_storage_path.sql\n-- individual_question_attachments (question_id, storage_path) UNIQUE 제약 신설 —\n-- 168 등록 RPC 멱등 계약의 arbiter(중복 판정 기준) 를 DB 에 확정한다.\n--\n-- ⚠️ 이 파일은 웨이브 1(트랙 3)에서 **초안으로만** 작성되었다. staging 미적용.\n--    적용은 후속 웨이브(W3)의 순차 적용 세션에서 docs/sql/wave1-iq-contract-plan.md 의\n--    6단계 절차(preflight → rollback-only 재현 → 적용 → fixture → baseline 복원 → manifest)를\n--    따라 수행한다.\n--\n-- 배경(2026-07-25 staging `lbeqxarxothkmzqvpudy` read-only 실조회):\n--   - 제약 실태: pg_constraint 는 pkey(id) + FK 2건(question_id→individual_questions ON DELETE\n--     CASCADE, message_id→individual_question_messages ON DELETE SET NULL) 뿐. UNIQUE **없음**.\n--   - 인덱스 실태: pg_indexes 는 individual_question_attachments_pkey(UNIQUE, id),\n--     idx_iqa_question_created(question_id, created_at DESC), idx_iqa_message(message_id).\n--     → (question_id, storage_path) 를 커버하는 UNIQUE 인덱스도 **없음**.\n--       (UNIQUE 가 constraint 없이 index 로만 존재하는 경우가 있어 양쪽을 모두 조회했다.)\n--   - 중복 실태: 전체 1행 · (question_id, storage_path) 중복 조합 0건 · 중복에 걸린 행 0건 ·\n--     storage_path 단독 중복 0건. → 정리 작업 없이 **직접 생성 가능**.\n--   - 손상 행 실태: question_id NULL 0 · storage_path NULL 0 · 공백 0 · 미trim 0 ·\n--     question FK 고아 0. (question_id 는 NOT NULL uuid 라 NULL·빈 문자열이 스키마상 불가.\n--     v19·v20 클라이언트가 AMBIGUOUS 로 처리하는 대상은 서버 실태 기준 0건이다.)\n--\n-- 조치: (question_id, storage_path) UNIQUE constraint 1건 추가. 그 외 일절 불변.\n--   - constraint 형태를 택한 이유: 168 이 `ON CONFLICT (question_id, storage_path)` 컬럼 추론과\n--     `ON CONFLICT ON CONSTRAINT` 양쪽을 모두 쓸 수 있고, 제약 위반 시 conname 이 오류에 실려\n--     호출자·픽스처가 원인을 특정할 수 있기 때문이다.\n--   - 대상 테이블은 실측 1행이라 ADD CONSTRAINT 의 ACCESS EXCLUSIVE 락 구간이 사실상 0 이다.\n--     (대량 테이블이었다면 CREATE UNIQUE INDEX CONCURRENTLY → ADD CONSTRAINT ... USING INDEX\n--      2단계가 필요했을 것 — 현 실태에서는 불필요.)\n--\n-- 알려진 한계(168 에서 보완):\n--   현행 RPC 는 빈 문자열 검사에만 btrim 을 쓰고 **저장은 원문 그대로** 한다. 따라서\n--   ''uuid/a.png'' 와 ''uuid/a.png '' 는 이 UNIQUE 로 접히지 않는다. 실측 미trim 행 0건이라\n--   지금 당장의 오염은 없고, 168 이 저장 직전 btrim 을 도입해 유입 자체를 막는다.\n--   (정규화를 표현식 인덱스로 강제하지 않는 이유: 앱·픽스처가 조회에 쓰는 경로 문자열과\n--    저장 문자열이 달라지는 부작용을 피하고, 정본을 RPC 한 곳에 두기 위함이다.)\n--\n-- 선행: 070(individual_question 스키마), 117(첨부 v2). 후속: 168(이 제약을 arbiter 로 사용).\n-- 적용 보류 조건: 아래 §0 검증에서 중복 1건이라도 발견되면 **중단**한다. 이 스크립트는\n--   중복을 자동 정리하지 않는다(오염 행 자동 수정 금지 규율 — 처리 옵션은 plan 문서 §5 참조).\n\nbegin", "set local lock_timeout = ''5s''", "-- ── 0. 사전 검증: 중복 0건 재확인(적용 시점 실태 기준). 1건이라도 있으면 트랜잭션 중단 ──\ndo $$\ndeclare\n  v_dup_combos integer;\n  v_dup_rows   integer;\nbegin\n  select count(*), coalesce(sum(c), 0)\n    into v_dup_combos, v_dup_rows\n  from (\n    select count(*) as c\n    from public.individual_question_attachments\n    group by question_id, storage_path\n    having count(*) > 1\n  ) d;\n\n  if v_dup_combos > 0 then\n    raise exception\n      ''ABORT_167: (question_id, storage_path) 중복 조합 %건 / 관련 행 %건 — UNIQUE 생성 불가. 자동 정리 금지, 오너·판정자 결정 필요(plan 문서 §5).'',\n      v_dup_combos, v_dup_rows;\n  end if;\n\n  raise notice ''167 preflight OK: 중복 조합 0건 (총 %행)'',\n    (select count(*) from public.individual_question_attachments);\nend $$", "-- ── 1. UNIQUE 제약 생성(멱등 — 이미 있으면 건너뜀) ──\ndo $$\nbegin\n  if exists (\n    select 1 from pg_constraint\n    where conrelid = ''public.individual_question_attachments''::regclass\n      and conname = ''uq_iqa_question_storage_path''\n  ) then\n    raise notice ''167: uq_iqa_question_storage_path 이미 존재 — 생성 건너뜀(무수정).'';\n  else\n    alter table public.individual_question_attachments\n      add constraint uq_iqa_question_storage_path unique (question_id, storage_path);\n    raise notice ''167: uq_iqa_question_storage_path 생성 완료.'';\n  end if;\nend $$", "commit", "-- ── §V 검증 SELECT (적용 후 별도 실행 — DDL 과 분리) ──\n-- select conname, pg_get_constraintdef(oid)\n--   from pg_constraint\n--  where conrelid = ''public.individual_question_attachments''::regclass and contype = ''u'';\n-- 기대: uq_iqa_question_storage_path | UNIQUE (question_id, storage_path)\n--\n-- select indexname, indexdef from pg_indexes\n--  where schemaname=''public'' and tablename=''individual_question_attachments'';\n-- 기대: 기존 3건 + uq_iqa_question_storage_path (백킹 인덱스) = 4건\n--\n-- ── ROLLBACK 절차 ──\n-- 이 스크립트는 추가형이며 기존 행·정책·함수를 변경하지 않으므로 되돌림이 무손실이다.\n--   alter table public.individual_question_attachments\n--     drop constraint if exists uq_iqa_question_storage_path;\n-- 주의: 168 을 적용한 상태에서 167 만 되돌리면 168 의 ON CONFLICT 가 arbiter 부재로\n--   런타임 오류(42P10)를 낸다. 되돌릴 때는 반드시 **168 → 167 역순**으로 되돌린다.\n\n-- >>> NATIVE_BASELINE_PART 0175 | supabase/sql/169_iq_attachment_storage_delete_policy.sql | 169_iq_attachment_storage_delete_policy.sql <<<\n-- 169_iq_attachment_storage_delete_policy.sql\n-- individual-question-attachments 버킷 조건부 DELETE 정책 신설 —\n-- 업로드는 됐지만 등록(RPC)이 실패한 **미등록 객체**를 업로더 본인이 보상 삭제할 수 있게 한다.\n-- 등록이 완료된 첨부는 계속 삭제 불가.\n--\n-- ⚠️ 이 파일은 웨이브 1(트랙 3)에서 **초안으로만** 작성되었다. staging 미적용.\n--\n-- 배경(2026-07-25 staging `lbeqxarxothkmzqvpudy` read-only 실조회):\n--   - 버킷 실태: individual-question-attachments · public=false · file_size_limit=20971520(20MB) ·\n--     allowed_mime_types 9종(png/jpeg/webp/gif, pdf, zip, docx, pptx, json).\n--   - 이 버킷의 storage.objects 정책 3건 — 명명이 `iqa_storage_*` 이다.\n--     ※ 명명 구분(2026-07-25 재실측): `iqa_select_party` 는 **실재하는 정책명**이지만\n--        storage 가 아니라 **테이블 RLS** 정책이다\n--        (public.individual_question_attachments · SELECT · authenticated ·\n--         using: user_is_individual_question_party(question_id) — 이 테이블의 유일한 정책).\n--        앱의 findRegistered(당사자 SELECT) 가 의존하는 것이 바로 이 테이블 정책이다.\n--        storage 쪽 SELECT 정책명은 별개로 `iqa_storage_read_party` 이며,\n--        아래 신설 DELETE 정책은 storage 쪽 실명 규약(`iqa_storage_*`)을 따른다.\n--        이 스크립트는 테이블 RLS 정책 `iqa_select_party` 를 일절 건드리지 않는다.\n--       · iqa_storage_read_party   (SELECT, authenticated)\n--           using: bucket_id=''individual-question-attachments''\n--                  AND user_is_party_for_individual_question_storage_path(name)\n--       · iqa_storage_insert_party (INSERT, authenticated) — with_check 동일 식\n--       · iqa_storage_update_party_annotations (UPDATE, authenticated)\n--           — split_part(name,''/'',2)=''annotations'' 로 한정\n--   - **DELETE 정책 0건** 재확인. storage.objects 전체의 DELETE 정책 6건을 전수 조회했고\n--     (cpi_auth_delete_own, custom_order_message_attachments_storage_delete_uploader_or_adm,\n--      pa_auth_delete_own, qra_storage_delete_unregistered_owner, sfv_mentor_delete_own,\n--      student_id_images_delete_own) 이 버킷을 커버하는 항목은 **하나도 없다**.\n--     → 현재 미등록 객체는 authenticated 경로로 영구 삭제 불가(고아 누적).\n--   - 고아 실태: 버킷 객체 5건 중 등록 행이 없는 객체 **4건**. 반대로 등록 행은 있는데\n--     객체가 없는 경우 0건. annotations 세그먼트 객체 0건. 서로 다른 첫 세그먼트 5개.\n--\n--   - ⚠️ 소유자 컬럼 실태(정책 설계의 핵심 제약):\n--       이 버킷 5개 객체는 owner·owner_id 가 **전부 NULL/빈 문자열**이다.\n--       반면 다른 7개 버킷(community-post-images 64, question-room-attachments 7,\n--       custom-order-deliverables 2, custom-request-application-attachments 2,\n--       custom-request-post-attachments 2, profile-avatars 1, student-id-images 1)은\n--       owner_id NULL 이 **0건** — 즉 클라이언트 업로드 경로에서는 owner_id 가 정상 기록된다.\n--       따라서 이 버킷의 NULL 은 systemic 결함이 아니라 **fixture/service_role 시드 흔적**으로\n--       판단된다. 앞으로의 정상 업로드에는 owner_id 가 채워지므로 아래 owner_id 조건은 유효하다.\n--       다만 **기존 5개 객체(고아 4건 포함)는 이 정책으로 삭제되지 않는다**(fail-closed).\n--       그 4건의 처리는 자동 정리 대상이 아니며 오너·판정자 결정 사항이다\n--       (docs/sql/wave1-iq-contract-plan.md §5).\n--\n-- 조치: DELETE 정책 1건만 신설. 기존 SELECT/INSERT/UPDATE 정책 3건과 버킷 설정은 일절 불변.\n--   139(question-room-attachments 의 qra_storage_delete_unregistered_owner)와 동일한 패턴에\n--   **당사자 조건을 하나 더 얹었다**. 139 는 (bucket + owner + 미등록) 3조건이지만, 여기서는\n--   경로 첫 세그먼트가 question_id 인 구조를 살려 party 검사까지 요구한다 — 업로더가 사후에\n--   질문 당사자 자격을 잃은 경우(멘토 claim 해제 등)까지 닫기 위함이다.\n--\n-- 선행: 070, 117, 139(패턴 원본). 167·168 과는 **독립**이다(적용 순서상 뒤에 두지만 의존은 아님).\n--   단 \"등록된 객체는 삭제 불가\" 판정이 individual_question_attachments 를 참조하므로,\n--   168 의 멱등 등록이 먼저 자리잡은 뒤 적용하는 편이 보상 삭제 경로의 의미가 분명하다.\n\nbegin", "set local lock_timeout = ''5s''", "-- ── 0. 사전 검증: 이 버킷을 커버하는 DELETE 정책이 정말 없는지 재확인 ──\n--    (있다면 중복·상충 위험 — 조용히 덮지 않고 중단한다.)\ndo $$\ndeclare\n  v_existing text;\nbegin\n  select string_agg(policyname, '', '')\n    into v_existing\n  from pg_policies\n  where schemaname = ''storage''\n    and tablename = ''objects''\n    and cmd in (''DELETE'', ''ALL'')\n    and coalesce(qual, '''') like ''%individual-question-attachments%''\n    and policyname <> ''iqa_storage_delete_unregistered_owner'';\n\n  if v_existing is not null then\n    raise exception\n      ''ABORT_169: 이 버킷을 커버하는 기존 DELETE/ALL 정책 발견 (%). 상충 검토 없이 신설 금지.'',\n      v_existing;\n  end if;\n\n  raise notice ''169 preflight OK: 기존 DELETE 정책 0건 확인.'';\nend $$", "-- ── 1. 조건부 DELETE 정책 신설(멱등 — 재적용 안전) ──\n--    4조건 AND:\n--      (a) 이 버킷일 것\n--      (b) 업로더 본인 소유일 것            → 타인 객체 삭제 차단\n--      (c) 경로가 가리키는 질문의 당사자일 것 → 사후 자격 상실 차단\n--      (d) 등록 행이 없을 것                → 등록 완료 첨부는 삭제 불가(감사 추적 보존)\ndrop policy if exists iqa_storage_delete_unregistered_owner on storage.objects", "create policy iqa_storage_delete_unregistered_owner on storage.objects\n  for delete to authenticated\n  using (\n    bucket_id = ''individual-question-attachments''\n    and owner_id = (select auth.uid())::text\n    and public.user_is_party_for_individual_question_storage_path(name)\n    and not exists (\n      select 1\n      from public.individual_question_attachments a\n      where a.storage_path = storage.objects.name\n    )\n  )", "commit", "-- ── §V 검증 SELECT (적용 후 별도 실행) ──\n-- select policyname, cmd, roles::text, qual\n--   from pg_policies\n--  where schemaname=''storage'' and tablename=''objects''\n--    and policyname=''iqa_storage_delete_unregistered_owner'';\n-- 기대: DELETE | {authenticated} | 위 4조건 AND 식\n--\n-- select count(*) from pg_policies\n--  where schemaname=''storage'' and tablename=''objects'' and policyname like ''iqa_storage_%'';\n-- 기대: 4 (read_party, insert_party, update_party_annotations, delete_unregistered_owner)\n--\n-- ── ROLLBACK 절차 ──\n-- 추가형 단일 정책이므로 되돌림이 무손실이다(기존 3정책·버킷 설정 무변경).\n--   drop policy if exists iqa_storage_delete_unregistered_owner on storage.objects;\n-- 되돌리면 DELETE 정책 0건 상태(=현행 baseline)로 정확히 복귀한다.\n--\n-- ── 적용 보류 조건 ──\n-- §0 검증이 기존 DELETE/ALL 정책을 발견하면 중단한다. 또한 적용 시점에 이 버킷의\n-- owner_id NULL 객체 비율이 여전히 100% 라면, 정책은 신설하되 **보상 삭제 경로가 실제로\n-- 동작하는지는 신규 업로드 픽스처로 확인**해야 한다(기존 5객체로는 검증 불가 — plan 문서 §3).\n\n-- >>> NATIVE_BASELINE_PART 0176 | supabase/sql/170_review_eligibility_relationship_based.sql | 170_review_eligibility_relationship_based.sql <<<\n-- 170_review_eligibility_relationship_based.sql\n-- 리뷰 자격 기준을 **결제 횟수(기준 A)** 에서 **관계 상태(기준 B + C)** 로 전환한다.\n-- 오너 확정 1 (웨이브 2). 066 의 check_review_eligibility(uuid,uuid) 를 CREATE OR REPLACE 로 대체.\n--\n-- ⚠️ 시그니처·이름 불변(변경 금지):\n--   126_reviews_rls_hardening.sql:57 의 INSERT 정책 reviews_insert_student 가\n--     check_review_eligibility(mentor_id, (select auth.uid()))\n--   로 **멘토를 첫 인자**로 넘긴다. 045:8-10 · 061:7-9 · 066:26-28 전부 동일하게\n--   (p_mentor_id, p_student_id) 순서다. 인자 순서를 뒤집으면 INSERT 정책이 조용히\n--   전건 false 가 되어 리뷰 작성이 전면 차단된다. 순서를 바꾸지 말 것.\n--\n-- ── 자격 기준 (둘 중 하나라도 성립하면 자격 있음) ──────────────────────────────\n--   (B) 구독 관계: subscriptions.status ∈ {active, expired, cancel_scheduled}\n--   (C) 완료된 개별질문: individual_questions.status ∈ {answered, released}\n--       멘토 식별 = coalesce(claimed_mentor_id, designated_mentor_id)\n--\n-- ── 제외(문면 명시) ────────────────────────────────────────────────────────────\n--   구독: pending(시작 전) · past_due(hold) · canceled · refunded\n--   IQ  : escrowed · assigned · open · claimed · expired · refunded · canceled (나머지 7종)\n--\n--   \"결제 실패 제외\"는 별도 조건으로 남기지 않는다. 기준이 **결제 횟수에서 관계 상태로**\n--   바뀌면서 상태 매핑에 자연 흡수되기 때문이다 — 결제가 실패하면 구독은 애초에\n--   active/expired/cancel_scheduled 로 진입하지 못하고 pending·past_due 에 머무르며,\n--   환불된 건은 refunded 로 빠진다. 즉 제외 대상은 상태 집합의 여집합으로 이미 닫혀 있다.\n--\n-- ── 실 enum 고정 (staging 실측 CHECK 제약 · 2026-07-25) ────────────────────────\n--   subscriptions_status_check:\n--     pending · active · past_due · cancel_scheduled · canceled · expired · refunded (7종)\n--   individual_questions_status_check:\n--     escrowed · assigned · open · claimed · answered · released · expired · refunded · canceled (9종)\n--   ⚠️ ''confirmed'' · ''completed'' 는 **두 테이블 어디에도 없다**. 사용하면 영구 매칭 0 이다.\n--\n-- ── 폐기되는 구 로직 (066) ────────────────────────────────────────────────────\n--   subscription_billing_events 2건 집계 → cash_ledger 폴백 → payments 폴백의\n--   3경로 카운팅을 전부 제거한다. 관계 상태만으로 판정하므로 집계 경로가 필요 없고,\n--   집계 실패(일시적 DB 오류)가 자격 박탈로 이어지던 취약점도 함께 사라진다.\n--\n-- 관례 계승(066 동일): plpgsql · stable · security definer · search_path=public ·\n--   revoke all from public, anon · grant execute to authenticated.\n--\n-- 선행: 064, 066, 126(이 함수를 참조하는 INSERT 정책). 후속: 171(작성자 수정 경로).\n\ncreate or replace function public.check_review_eligibility(\n  p_mentor_id uuid,\n  p_student_id uuid\n) returns boolean\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if p_mentor_id is null or p_student_id is null then\n    return false;\n  end if;\n\n  -- (B) 구독 관계 — 시작된 적이 있고 환불·취소로 무효화되지 않은 상태\n  if exists (\n    select 1\n    from public.subscriptions s\n    where s.student_id = p_student_id\n      and s.mentor_id = p_mentor_id\n      and s.status in (''active'', ''expired'', ''cancel_scheduled'')\n  ) then\n    return true;\n  end if;\n\n  -- (C) 완료된 개별질문 — 멘토 식별은 claim 우선, 없으면 지정 멘토\n  if exists (\n    select 1\n    from public.individual_questions q\n    where q.student_id = p_student_id\n      and coalesce(q.claimed_mentor_id, q.designated_mentor_id) = p_mentor_id\n      and q.status in (''answered'', ''released'')\n  ) then\n    return true;\n  end if;\n\n  return false;\nend;\n$$", "revoke all on function public.check_review_eligibility(uuid, uuid) from public, anon", "grant execute on function public.check_review_eligibility(uuid, uuid) to authenticated", "comment on function public.check_review_eligibility(uuid, uuid) is\n  ''Review eligibility (relationship-based, wave2 owner decision 1): eligible when the pair has a subscription in {active, expired, cancel_scheduled} OR a completed individual question in {answered, released} (mentor = coalesce(claimed_mentor_id, designated_mentor_id)). Replaces the legacy 2-paid-events counting rule. Argument order (p_mentor_id, p_student_id) is fixed by 126 reviews_insert_student.''", "-- ── §V 검증 SELECT (적용 후 별도 실행) ──\n-- 자격 쌍 수 판정 쿼리(적용 전후 동일 쿼리로 비교):\n-- select count(*) as eligible_pairs\n-- from (\n--   select distinct student_id, mentor_id from (\n--     select s.student_id, s.mentor_id from public.subscriptions s\n--     union\n--     select q.student_id, coalesce(q.claimed_mentor_id, q.designated_mentor_id)\n--       from public.individual_questions q\n--      where coalesce(q.claimed_mentor_id, q.designated_mentor_id) is not null\n--   ) p\n-- ) pairs\n-- where public.check_review_eligibility(pairs.mentor_id, pairs.student_id);\n-- 기대: 적용 전 0 → 적용 후 1 (staging 2026-07-25 기준)\n--\n-- ── ROLLBACK 절차 ──\n-- 066_review_eligibility_billing_events.sql 을 그대로 재적용하면 구 기준으로 복귀한다\n-- (같은 시그니처의 create or replace 이므로 무손실).\n-- 주의: 171 이 적용된 상태에서 170 만 되돌려도 트리거·정책은 계속 동작한다\n--   (171 은 이 함수를 호출하지 않는다 — 수정 시 자격 재검사를 하지 않는 것이 정본이다).\n--   전체 롤백 순서는 171 → 170 → 169 → 168 → 167.\n\n-- >>> NATIVE_BASELINE_PART 0177 | supabase/sql/171_reviews_author_update_and_updated_at.sql | 171_reviews_author_update_and_updated_at.sql <<<\n-- 171_reviews_author_update_and_updated_at.sql\n-- reviews.updated_at 신설 + 학생(작성자) 리뷰 수정 경로 개통. 오너 확정 4·5 (웨이브 2).\n--\n-- ── 왜 3계층을 모두 열어야 하는가 (126 실측) ──────────────────────────────────\n-- 현행 학생 수정은 **세 겹**으로 막혀 있고, 하나라도 남기면 동작하지 않는다:\n--   ① UPDATE 정책이 reviews_update_mentor(126:61) · reviews_update_admin(126:66) 둘뿐 —\n--      작성자 정책 자체가 없다.\n--   ② 트리거 reviews_enforce_update()(126:72) 의 최종 catch-all(126:127)\n--      ''reviews: not permitted to update this review'' 가 작성자를 거절한다.\n--   ③ **공통 불변 보호 필드 가드(126:87-96)가 rating(:91)·body(:92) 를 포함하고,\n--      이 가드가 액터 분기보다 먼저 실행된다**(service_role 조기 반환 :83-85 직후).\n--\n-- ⚠️ 함정: ②만 열고 ③을 그대로 두면 작성자 분기에 도달해도 공통 가드가 먼저 걸려\n--    여전히 실패한다. 반대로 ③에서 rating·body 를 통째로 빼면 **멘토·관리자까지\n--    학생 리뷰 본문을 고칠 수 있게 되는 권한 회귀**다.\n--    → 정답은 공통 가드를 **액터 조건부로 좁히는 것**: rating·body 는 \"작성자일 때만\"\n--      가드 대상에서 제외하고, 그 외 액터에게는 종전대로 불변으로 남긴다.\n--\n-- ── 작성자가 바꿀 수 있는 것: rating · body 둘뿐 ──────────────────────────────\n--   불변(모든 액터): id · mentor_id · author_id · created_at · subscription_count\n--   작성자 분기에서 **추가로** 차단하는 7종 — 관리자 분기(126:99-107)가 mentor_reply·\n--   mentor_replied_at 을, 멘토 분기(126:110-124)가 is_hidden·is_blinded·moderation_state·\n--   moderated_at·moderated_by 를 막는 것과 **대칭**이다. 지금까지 학생은 :127 catch-all 에\n--   걸려 아무것도 못 고쳤으므로 이 방어가 필요 없었지만, 작성자 분기를 여는 순간\n--   **아무 가드도 없는 통로가 생긴다**.\n--   updated_at 은 클라이언트 값을 무시하고 서버가 now() 로 강제한다.\n--\n-- ── 자격 재검사 안 함 (정본 지정) ─────────────────────────────────────────────\n-- 수정 시점에 check_review_eligibility 를 재호출하지 **않는다**. 신기준(170)에서는\n-- expired 도 자격이므로 한 번 얻은 자격이 사실상 유지되어 재검사 결과가 같고,\n-- 재검사를 넣으면 만료 후 오타 수정이 막히는 부작용만 남는다.\n--\n-- ── 작성자 전용 SELECT 정책이 필요한 이유 (기존 결함의 표면화) ────────────────\n-- 126:44-46 의 reviews_select_public_visible 는 is_hidden/is_blinded 가 false 인 행만 보이고,\n-- 나머지 SELECT 정책은 reviews_select_admin(126:48-50) 하나뿐이다 — **작성자 전용 SELECT 정책이 없다**.\n-- 따라서 모더레이션된 본인 리뷰는 조회에서 null 이 되고 → UI 가 신규 작성으로 오판 →\n-- POST 가 uq_reviews_mentor_author(042:66 · 123:129) 에 막혀 23505 가 난다.\n-- 이 결함은 이번 변경이 만드는 것이 아니라 **현재도 존재하며, 편집 모드를 열면 표면화된다**.\n--   → reviews_select_author 를 신설한다. 기존 두 SELECT 정책은 무변경 보존.\n--   ⚠️ 공개 목록 누출 없음 — 공개 노출 2경로는 RLS 가 아니라 명시 필터에 의존한다:\n--      lib/reviews/reviewQueries.ts:36-38 applyPublicFilters(:105-107 적용) 및\n--      listMentorReceivedReviews 의 isPubliclyVisibleReview 후처리(:295).\n--      **이 두 필터를 제거하면 작성자 정책이 누출 경로가 된다 — 절대 제거 금지.**\n--\n-- 선행: 042/123(uq_reviews_mentor_author), 126(정책·트리거 정본), 170.\n\nbegin", "set local lock_timeout = ''5s''", "-- ── 1. updated_at 신설 ────────────────────────────────────────────────────────\n-- 기존 테이블 관례 계승: reviews.created_at 이 timestamptz NOT NULL DEFAULT now() 이고\n-- mentor_profiles·subscriptions·individual_questions 의 updated_at 도 동일 형태다.\n-- 실측 0행이므로 백필 부담 없음.\nalter table public.reviews\n  add column if not exists updated_at timestamptz not null default now()", "-- ── 2. RLS — 작성자 SELECT / UPDATE 정책 신설 (기존 정책 무변경 보존) ─────────\ndrop policy if exists \"reviews_select_author\" on public.reviews", "create policy \"reviews_select_author\" on public.reviews\n  for select to authenticated\n  using (author_id = (select auth.uid()))", "drop policy if exists \"reviews_update_author\" on public.reviews", "create policy \"reviews_update_author\" on public.reviews\n  for update to authenticated\n  using ((select auth.uid()) = author_id)\n  with check ((select auth.uid()) = author_id)", "-- ── 3. 트리거 개정 — 액터 조건부 컬럼 가드 ────────────────────────────────────\ncreate or replace function public.reviews_enforce_update()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_is_admin boolean := coalesce((select public.is_admin()), false);\n  v_is_author boolean;\nbegin\n  -- service_role: 시스템 경로 통과 (126 동작 그대로 보존)\n  if coalesce(auth.role(), '''') = ''service_role'' then\n    return new;\n  end if;\n\n  -- 관리자가 우연히 작성자이기도 한 경우에는 **관리자 의미론을 우선**한다\n  -- (권한이 늘어나지 않는 보수적 방향 — 관리자 분기는 rating·body 를 못 바꾼다).\n  v_is_author := (not v_is_admin) and v_uid is not null and v_uid = old.author_id;\n\n  -- 공통 불변 보호 필드 (모든 비-service 액터)\n  -- 126:87-96 과 동일하되 rating·body 는 아래에서 액터 조건부로 판정한다.\n  if new.id is distinct from old.id\n     or new.mentor_id is distinct from old.mentor_id\n     or new.author_id is distinct from old.author_id\n     or new.subscription_count is distinct from old.subscription_count\n     or new.created_at is distinct from old.created_at then\n    raise exception ''reviews: protected columns are immutable'';\n  end if;\n\n  -- rating·body 는 **작성자만** 변경 가능. 멘토·관리자에게는 종전대로 불변.\n  if not v_is_author then\n    if new.rating is distinct from old.rating\n       or new.body is distinct from old.body then\n      raise exception ''reviews: protected columns are immutable'';\n    end if;\n  end if;\n\n  -- 관리자: is_hidden/is_blinded/moderation_state 만. moderated_* 서버 강제.\n  if v_is_admin then\n    if new.mentor_reply is distinct from old.mentor_reply\n       or new.mentor_replied_at is distinct from old.mentor_replied_at then\n      raise exception ''reviews: admin must not change mentor reply fields'';\n    end if;\n    new.moderated_at := now();\n    new.moderated_by := v_uid;\n    -- 조정은 \"작성자가 마지막으로 수정한 시각\"을 건드리지 않는다.\n    new.updated_at := old.updated_at;\n    return new;\n  end if;\n\n  -- 작성자(학생): rating·body 만. 조정·멘토답글 필드 7종 전량 차단. updated_at 서버 강제.\n  if v_is_author then\n    if new.is_hidden is distinct from old.is_hidden\n       or new.is_blinded is distinct from old.is_blinded\n       or new.moderation_state is distinct from old.moderation_state\n       or new.moderated_at is distinct from old.moderated_at\n       or new.moderated_by is distinct from old.moderated_by\n       or new.mentor_reply is distinct from old.mentor_reply\n       or new.mentor_replied_at is distinct from old.mentor_replied_at then\n      raise exception ''reviews: author must not change moderation or mentor reply fields'';\n    end if;\n    new.updated_at := now();   -- 클라이언트 값 무시\n    return new;\n  end if;\n\n  -- 멘토(본인 리뷰): mentor_reply 만, 1회. moderation 필드 변경 금지. replied_at 서버 강제.\n  if v_uid is not null and v_uid = old.mentor_id then\n    if new.is_hidden is distinct from old.is_hidden\n       or new.is_blinded is distinct from old.is_blinded\n       or new.moderation_state is distinct from old.moderation_state\n       or new.moderated_at is distinct from old.moderated_at\n       or new.moderated_by is distinct from old.moderated_by then\n      raise exception ''reviews: mentor must not change moderation fields'';\n    end if;\n    if old.mentor_reply is not null and new.mentor_reply is distinct from old.mentor_reply then\n      raise exception ''reviews: mentor reply already set (one-time only)'';\n    end if;\n    if new.mentor_reply is distinct from old.mentor_reply\n      then new.mentor_replied_at := now(); else new.mentor_replied_at := old.mentor_replied_at; end if;\n    -- 멘토 답글은 학생 수정 시각을 건드리지 않는다.\n    new.updated_at := old.updated_at;\n    return new;\n  end if;\n\n  -- 그 외: 수정 불가\n  raise exception ''reviews: not permitted to update this review'';\nend;\n$$", "drop trigger if exists trg_reviews_enforce_update on public.reviews", "create trigger trg_reviews_enforce_update\n  before update on public.reviews\n  for each row execute function public.reviews_enforce_update()", "commit", "-- ── §V 검증 SELECT (적용 후 별도 실행) ──\n-- select column_name, data_type, is_nullable, column_default\n--   from information_schema.columns\n--  where table_schema=''public'' and table_name=''reviews'' and column_name=''updated_at'';\n-- 기대: updated_at | timestamp with time zone | NO | now()\n--\n-- select policyname, cmd, roles::text from pg_policies\n--  where schemaname=''public'' and tablename=''reviews'' order by policyname;\n-- 기대 6건: reviews_insert_student(INSERT) · reviews_select_admin(SELECT) ·\n--          reviews_select_author(SELECT) · reviews_select_public_visible(SELECT) ·\n--          reviews_update_admin(UPDATE) · reviews_update_author(UPDATE) · reviews_update_mentor(UPDATE)\n--          → 총 7건\n--\n-- ── ROLLBACK 절차 ──\n--   drop policy if exists \"reviews_update_author\" on public.reviews;\n--   drop policy if exists \"reviews_select_author\" on public.reviews;\n--   -- 트리거 함수는 126_reviews_rls_hardening.sql 의 reviews_enforce_update() 정의를 재적용\n--   alter table public.reviews drop column if exists updated_at;\n-- 전체 롤백 순서: 171 → 170 → 169 → 168 → 167\n\n-- >>> NATIVE_BASELINE_PART 0178 | supabase/sql/173_reviews_moderated_author_edit_guard.sql | 173_reviews_moderated_author_edit_guard.sql <<<\n-- 173_reviews_moderated_author_edit_guard.sql\n-- 모더레이션(숨김·블라인드)된 본인 리뷰의 **작성자 수정**을 서버에서 차단한다.\n--\n-- ── 이 파일이 닫는 결함 ───────────────────────────────────────────────────────\n-- 「작성자 분기가 OLD.is_hidden·OLD.is_blinded 를 보지 않아 모더레이션 리뷰가\n--   직접 요청으로 수정 가능」\n--   171 의 reviews_update_author 정책은 author_id 일치만 보고,\n--   트리거 reviews_enforce_update() 의 작성자 분기(171:작성자 블록)도 조정 상태를\n--   전혀 읽지 않는다. UI 의 canEdit:false 는 클라이언트 가드일 뿐이라\n--   Supabase 직접 호출(PostgREST)로 그대로 우회된다.\n--\n-- ── 171 검증 주석 정정 (파일은 고치지 않는다) ────────────────────────────────\n-- 171 파일 말미 §V 검증 주석의 `-- 기대 6건:` 은 뒤에 정책을 7개 나열하므로\n-- **「기대 7건」이 옳다**(171 본문 말미도 \"→ 총 7건\"으로 스스로 정정하고 있다).\n-- 171 은 이미 staging 에 적용되어 **바이트 동일 보존이 원칙**이므로 파일을 수정하지\n-- 않고 이 헤더에 정정 기록만 남긴다. 실측 기준값도 7건이다.\n--\n-- ── 2계층으로 막는다 (둘 다 필수) ────────────────────────────────────────────\n--   (가) 트리거: 작성자 분기 최상단에서 OLD 의 조정 상태를 보고 예외를 던진다.\n--   (나) RLS   : reviews_update_author 의 USING 에 조정 상태 조건을 더해\n--                애초에 대상 행이 보이지 않게 한다.\n--\n-- ⚠️ 계층 순서가 만드는 결과 — 웹 1행 계약과 묶이는 이유\n--    정책 USING 이 먼저 걸리므로 정상 authenticated 경로에서 UPDATE 는 **예외가 아니라\n--    0행**으로 끝난다. 즉 (나)만 넣고 애플리케이션이 영향 행 수를 확인하지 않으면\n--    사용자에게 「수정 성공」이 표시되는데 실제로는 아무것도 바뀌지 않는다.\n--    → lib/reviews/reviewQueries.ts 의 updateReview() 1행 계약과 **같은 라운드에서**\n--      함께 닫는다. 한쪽만 적용하면 조용한 무효 수정이 남는다.\n--    → 트리거 (가)는 정책을 우회하는 경로(테이블 소유자 세션 등)에 대한 심층 방어다.\n--\n-- ⚠️ 절대 건드리지 않는 것\n--    · reviews_select_author (171): 작성자는 숨김된 본인 리뷰를 **읽을 수 있어야**\n--      mode:''edit'' + canEdit:false 가 성립한다. SELECT 를 같이 조이면 UI 가 다시\n--      신규 작성으로 오판해 uq_reviews_mentor_author 23505 가 난다 — 171 이 닫은\n--      결함의 재발이다.\n--    · lib/reviews/reviewQueries.ts 의 applyPublicFilters(:34-36) 와\n--      listMentorReceivedReviews 의 isPubliclyVisibleReview 후처리(:353):\n--      공개 목록의 유일한 차단막이다. 제거 금지.\n--    · 관리자 분기(숨김·해제) · 멘토 분기(답글) · service_role 조기 반환:\n--      종전 동작 그대로여야 한다. 가드를 작성자 분기 **밖**에 두면 관리자가 숨긴\n--      리뷰를 되돌릴 수 없게 되는 권한 회귀다.\n--\n-- 선행: 126(정책·트리거 정본) · 170 · 171\n\nbegin", "set local lock_timeout = ''5s''", "-- ── 1. 트리거 — 작성자 분기 최상단 가드 ──────────────────────────────────────\n-- plpgsql 은 부분 패치가 불가하므로 171 본문 전체를 그대로 재선언하고\n-- 작성자 분기의 첫 문장으로 가드 1개만 추가한다. 나머지는 한 글자도 바뀌지 않는다.\ncreate or replace function public.reviews_enforce_update()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_is_admin boolean := coalesce((select public.is_admin()), false);\n  v_is_author boolean;\nbegin\n  -- service_role: 시스템 경로 통과 (126 동작 그대로 보존)\n  if coalesce(auth.role(), '''') = ''service_role'' then\n    return new;\n  end if;\n\n  -- 관리자가 우연히 작성자이기도 한 경우에는 **관리자 의미론을 우선**한다\n  -- (권한이 늘어나지 않는 보수적 방향 — 관리자 분기는 rating·body 를 못 바꾼다).\n  v_is_author := (not v_is_admin) and v_uid is not null and v_uid = old.author_id;\n\n  -- 공통 불변 보호 필드 (모든 비-service 액터)\n  -- 126:87-96 과 동일하되 rating·body 는 아래에서 액터 조건부로 판정한다.\n  if new.id is distinct from old.id\n     or new.mentor_id is distinct from old.mentor_id\n     or new.author_id is distinct from old.author_id\n     or new.subscription_count is distinct from old.subscription_count\n     or new.created_at is distinct from old.created_at then\n    raise exception ''reviews: protected columns are immutable'';\n  end if;\n\n  -- rating·body 는 **작성자만** 변경 가능. 멘토·관리자에게는 종전대로 불변.\n  if not v_is_author then\n    if new.rating is distinct from old.rating\n       or new.body is distinct from old.body then\n      raise exception ''reviews: protected columns are immutable'';\n    end if;\n  end if;\n\n  -- 관리자: is_hidden/is_blinded/moderation_state 만. moderated_* 서버 강제.\n  if v_is_admin then\n    if new.mentor_reply is distinct from old.mentor_reply\n       or new.mentor_replied_at is distinct from old.mentor_replied_at then\n      raise exception ''reviews: admin must not change mentor reply fields'';\n    end if;\n    new.moderated_at := now();\n    new.moderated_by := v_uid;\n    -- 조정은 \"작성자가 마지막으로 수정한 시각\"을 건드리지 않는다.\n    new.updated_at := old.updated_at;\n    return new;\n  end if;\n\n  -- 작성자(학생): rating·body 만. 조정·멘토답글 필드 7종 전량 차단. updated_at 서버 강제.\n  if v_is_author then\n    -- ★ 173: 모더레이션된 리뷰는 작성자가 수정할 수 없다.\n    --   이 가드는 **작성자 분기 안에서만** 동작한다 — 관리자의 숨김 해제와\n    --   멘토의 답글은 종전대로 조정된 행에도 적용되어야 하기 때문이다.\n    if coalesce(old.is_hidden, false) or coalesce(old.is_blinded, false) then\n      raise exception ''reviews: moderated review is not editable by author'';\n    end if;\n    if new.is_hidden is distinct from old.is_hidden\n       or new.is_blinded is distinct from old.is_blinded\n       or new.moderation_state is distinct from old.moderation_state\n       or new.moderated_at is distinct from old.moderated_at\n       or new.moderated_by is distinct from old.moderated_by\n       or new.mentor_reply is distinct from old.mentor_reply\n       or new.mentor_replied_at is distinct from old.mentor_replied_at then\n      raise exception ''reviews: author must not change moderation or mentor reply fields'';\n    end if;\n    new.updated_at := now();   -- 클라이언트 값 무시\n    return new;\n  end if;\n\n  -- 멘토(본인 리뷰): mentor_reply 만, 1회. moderation 필드 변경 금지. replied_at 서버 강제.\n  if v_uid is not null and v_uid = old.mentor_id then\n    if new.is_hidden is distinct from old.is_hidden\n       or new.is_blinded is distinct from old.is_blinded\n       or new.moderation_state is distinct from old.moderation_state\n       or new.moderated_at is distinct from old.moderated_at\n       or new.moderated_by is distinct from old.moderated_by then\n      raise exception ''reviews: mentor must not change moderation fields'';\n    end if;\n    if old.mentor_reply is not null and new.mentor_reply is distinct from old.mentor_reply then\n      raise exception ''reviews: mentor reply already set (one-time only)'';\n    end if;\n    if new.mentor_reply is distinct from old.mentor_reply\n      then new.mentor_replied_at := now(); else new.mentor_replied_at := old.mentor_replied_at; end if;\n    -- 멘토 답글은 학생 수정 시각을 건드리지 않는다.\n    new.updated_at := old.updated_at;\n    return new;\n  end if;\n\n  -- 그 외: 수정 불가\n  raise exception ''reviews: not permitted to update this review'';\nend;\n$$", "-- 트리거 자체는 171 에서 이미 붙어 있고 함수만 교체하면 되지만,\n-- 재적용 멱등성을 위해 동일 정의로 다시 건다(동작 변화 없음).\ndrop trigger if exists trg_reviews_enforce_update on public.reviews", "create trigger trg_reviews_enforce_update\n  before update on public.reviews\n  for each row execute function public.reviews_enforce_update()", "-- ── 2. RLS — reviews_update_author USING 강화 ────────────────────────────────\n-- USING 에만 조건을 더한다. WITH CHECK 은 171 그대로 — 작성자 분기는 조정 컬럼을\n-- 어차피 트리거가 막으므로 WITH CHECK 에 중복 조건을 넣을 이유가 없고,\n-- 넣으면 관리자 해제 직후 상태 전이에서 불필요한 거절이 생길 수 있다.\ndrop policy if exists \"reviews_update_author\" on public.reviews", "create policy \"reviews_update_author\" on public.reviews\n  for update to authenticated\n  using ((select auth.uid()) = author_id\n         and coalesce(is_hidden, false) = false\n         and coalesce(is_blinded, false) = false)\n  with check ((select auth.uid()) = author_id)", "commit", "-- ── §V 검증 SELECT (적용 후 별도 실행) ──\n-- select policyname, cmd, qual from pg_policies\n--  where schemaname=''public'' and tablename=''reviews'' order by policyname;\n-- 기대 7건(신설·삭제 0). reviews_update_author 의 qual 만 바뀐다:\n--   ((SELECT auth.uid()) = author_id)\n--     AND (COALESCE(is_hidden,false) = false) AND (COALESCE(is_blinded,false) = false)\n-- 나머지 6건(reviews_insert_student · reviews_select_admin · reviews_select_author ·\n--   reviews_select_public_visible · reviews_update_admin · reviews_update_mentor)은 무변경.\n--\n-- select position(''moderated review is not editable by author'' in prosrc)\n--   from pg_proc where proname=''reviews_enforce_update'';\n-- 기대: > 0 (작성자 분기 안에 정확히 1개)\n--\n-- ── ROLLBACK 절차 ──\n--   -- (1) 정책을 171 정의(조건 없는 author_id 비교)로 되돌린다\n--   drop policy if exists \"reviews_update_author\" on public.reviews;\n--   create policy \"reviews_update_author\" on public.reviews\n--     for update to authenticated\n--     using ((select auth.uid()) = author_id)\n--     with check ((select auth.uid()) = author_id);\n--   -- (2) 트리거 함수는 171_reviews_author_update_and_updated_at.sql 의\n--   --     reviews_enforce_update() 정의를 그대로 재적용한다(가드 1개 제거).\n-- 전체 롤백 순서: 173 → 171 → 170 → 169 → 168 → 167\n\n-- >>> NATIVE_BASELINE_PART 0179 | supabase/sql/174_mentor_school_verification_approval_canon.sql | 174_mentor_school_verification_approval_canon.sql <<<\n-- 174_mentor_school_verification_approval_canon.sql\n-- 멘토 학교·전공 인증 승인 정본화 — 서류 실재 확인 + 재승인 수명주기(superseded) + 1인 1승인 강제.\n--\n-- 배경(2026-07-26 staging 실조회, project lbeqxarxothkmzqvpudy):\n--   - `mentor_school_verifications` 0행 · 인덱스 3건(pkey(id) · btree(mentor_id) · btree(status)).\n--     UNIQUE·partial 인덱스 **없음** → \"멘토별 approved 최대 1건\"을 DB 가 강제하지 않는다.\n--   - status CHECK = `mentor_school_verifications_status_check`\n--     ARRAY[''pending'',''approved'',''rejected'',''resubmit_required''] — ''superseded'' **부재**.\n--   - `document_storage_ref` text NULL · CHECK 없음 → approved 인데 서류 참조가 NULL 인 행이\n--     구조적으로 허용된다(승인 전제 미강제).\n--   - 제출(`submitMentorSchoolVerificationAction`)은 **append-only**: 재제출마다 새 행 INSERT.\n--     관리자 액션은 `.in(''status'', [''pending'',''resubmit_required''])` 로만 UPDATE 하므로\n--     **이미 approved 인 행은 어떤 기존 경로로도 변경되지 않는다** → 재승인 시 approved 가 누적된다.\n--   - 서류 참조 저장 형식(정본 writer): `student-id-images/{mentorId}/school-verifications/{ts}-{hex32}.{ext}`\n--     (`lib/storage/studentIdImageStorage.ts` — 버킷 접두 포함). reader 는 레거시 절대 URL 과\n--     접두 없는 경로도 허용하므로 아래 정규화 함수가 **동일 규칙**을 재현한다.\n--   - `postgres` rolbypassrls=true → SECURITY DEFINER(owner=postgres) 함수는 storage.objects 를\n--     RLS 에 막히지 않고 조회한다(실재 확인이 거짓 음성으로 실패하지 않음).\n--   - 트리거 `mentor_school_verifications_guard_self_review` 는 `is_admin()` 이 true 면 NEW 를\n--     그대로 반환한다 → 관리자 경유 승인/승계 UPDATE 에 간섭하지 않는다.\n--\n-- 규칙:\n--   - CHECK 확장은 **additive**: 기존 4값 + ''superseded''. 기존 행 백필 INSERT/UPDATE 0건\n--     (테이블 0행 — 백필 대상 자체가 없다).\n--   - 승인은 이 RPC **한 경로**로만 한다. 서류 참조 없음·객체 부재·소유 불일치는 전부 거부이며\n--     예외로 트랜잭션 전체가 rollback 된다(승인 0 · 기존 approved 변경 0).\n--   - 재승인은 같은 트랜잭션에서 기존 approved → ''superseded'' 전이 후 대상 행을 approved 로 만든다.\n--   - 부분 UNIQUE 인덱스는 **RPC 정의 뒤에** 만든다(재승인 경로가 승계를 먼저 수행하게 된 뒤에만\n--     1인 1승인을 강제해야 정상 재승인이 23505 로 죽지 않는다).\n--   - 동시 승인은 mentor 단위 advisory xact lock 으로 직렬화하고, 최종 불변식은 부분 UNIQUE\n--     인덱스가 강제한다(락을 우회한 경로가 있어도 approved 2행은 성립할 수 없다).\n-- 선행: 077(테이블·트리거·RLS), 079(school_tier CHECK 6값).\n\n-- ── 0. 사전 검증: 예상 상태와 다르면 중단(임의 정정 금지) ──\ndo $$\ndeclare\n  v_check_def text;\n  v_dup integer;\n  v_bad integer;\nbegin\n  select pg_get_constraintdef(c.oid) into v_check_def\n  from pg_constraint c\n  where c.conrelid = ''public.mentor_school_verifications''::regclass\n    and c.conname = ''mentor_school_verifications_status_check'';\n\n  if v_check_def is null then\n    raise exception ''SQL174_ABORT: mentor_school_verifications_status_check 부재 — 스키마 전제 불일치'';\n  end if;\n  if v_check_def not like ''%pending%'' or v_check_def not like ''%approved%''\n     or v_check_def not like ''%rejected%'' or v_check_def not like ''%resubmit_required%'' then\n    raise exception ''SQL174_ABORT: status CHECK 정의가 예상과 다름(%) — 임의 교체 금지'', v_check_def;\n  end if;\n\n  -- 이미 멘토별 approved 중복이 있으면 인덱스 생성이 실패한다. 임의 삭제하지 않고 중단.\n  select count(*) into v_dup from (\n    select mentor_id from public.mentor_school_verifications\n     where status = ''approved'' group by mentor_id having count(*) > 1\n  ) d;\n  if v_dup > 0 then\n    raise exception ''SQL174_ABORT: approved 중복 멘토 % 명 — 승계 정책 결정 전까지 중단(임의 정리 금지)'', v_dup;\n  end if;\n\n  -- 서류 참조가 비어 있는 approved 행이 있으면 새 계약과 모순 — 관측만 하고 중단.\n  select count(*) into v_bad from public.mentor_school_verifications\n   where status = ''approved'' and btrim(coalesce(document_storage_ref, '''')) = '''';\n  if v_bad > 0 then\n    raise exception ''SQL174_ABORT: 서류 참조 없는 approved % 행 — 백필/무효화 결정 필요(이 스크립트는 백필하지 않음)'', v_bad;\n  end if;\nend $$", "-- ── 1. status CHECK additive 확장(+ ''superseded'') ──\n-- 079 가 school_tier 에서 쓴 것과 같은 drop-then-add 패턴. 값 집합만 넓히고 좁히지 않는다.\nalter table public.mentor_school_verifications\n  drop constraint if exists mentor_school_verifications_status_check", "alter table public.mentor_school_verifications\n  add constraint mentor_school_verifications_status_check\n  check (status = any (array[''pending''::text, ''approved''::text, ''rejected''::text,\n                             ''resubmit_required''::text, ''superseded''::text]))", "comment on constraint mentor_school_verifications_status_check\n  on public.mentor_school_verifications is\n  ''SQL174: 기존 4값 + superseded(재승인 시 직전 approved 의 종료 상태). additive — 값 축소 없음.''", "-- ── 2. 서류 참조 정규화 헬퍼 ──\n-- lib/storage/studentIdImageStorage.ts:parseStudentIdImageStorageRef 와 동일 규칙:\n--   ① 공백 제거 후 빈 문자열 → null\n--   ② http(s):// → ''/student-id-images/'' 마커 뒤를 취하고 ?query·#fragment 절단\n--   ③ ''student-id-images/'' 접두 → 접두 제거 후 선행 슬래시 제거\n--   ④ 슬래시를 포함한 경로 → 선행 슬래시만 제거\n--   ⑤ 그 외(슬래시 없는 단일 토큰) → null\ncreate or replace function public.mentor_school_verification_storage_path(p_ref text)\nreturns text\nlanguage plpgsql\nimmutable\nset search_path = public\nas $$\ndeclare\n  v_raw text := btrim(coalesce(p_ref, ''''));\n  v_marker constant text := ''/student-id-images/'';\n  v_prefix constant text := ''student-id-images/'';\n  v_idx integer;\n  v_path text;\nbegin\n  if v_raw = '''' then\n    return null;\n  end if;\n\n  if v_raw like ''http://%'' or v_raw like ''https://%'' then\n    v_idx := position(v_marker in v_raw);\n    if v_idx = 0 then\n      return null;\n    end if;\n    v_path := substr(v_raw, v_idx + length(v_marker));\n    v_path := split_part(v_path, ''?'', 1);\n    v_path := split_part(v_path, ''#'', 1);\n    return nullif(btrim(v_path), '''');\n  end if;\n\n  if v_raw like (v_prefix || ''%'') then\n    return nullif(regexp_replace(substr(v_raw, length(v_prefix) + 1), ''^/+'', ''''), '''');\n  end if;\n\n  if position(''/'' in v_raw) > 0 then\n    return nullif(regexp_replace(v_raw, ''^/+'', ''''), '''');\n  end if;\n\n  return null;\nend;\n$$", "comment on function public.mentor_school_verification_storage_path(text) is\n  ''SQL174: 저장된 document_storage_ref → student-id-images 버킷 내 객체 경로. 웹 parseStudentIdImageStorageRef 와 동일 규칙. 판별 불가 시 NULL.''", "revoke all on function public.mentor_school_verification_storage_path(text) from public", "revoke all on function public.mentor_school_verification_storage_path(text) from anon", "revoke all on function public.mentor_school_verification_storage_path(text) from authenticated", "-- ── 3. 승인 정본 RPC ──\ncreate or replace function public.approve_mentor_school_verification_admin(\n  p_verification_id uuid,\n  p_university_name text,\n  p_university_id text,\n  p_department_name text,\n  p_major_category text,\n  p_school_tier text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_admin uuid := (select auth.uid());\n  v_row public.mentor_school_verifications;\n  v_path text;\n  v_owner_segment text;\n  v_superseded integer := 0;\nbegin\n  -- (a) 관리자 전용. mentor·student·anon 은 여기서 종료된다.\n  if not coalesce(public.is_admin(), false) then\n    raise exception ''NOT_ADMIN'' using errcode = ''42501'';\n  end if;\n\n  if p_verification_id is null then\n    raise exception ''INVALID_INPUT: verification_id is required'' using errcode = ''22023'';\n  end if;\n  if btrim(coalesce(p_university_name, '''')) = ''''\n     or btrim(coalesce(p_university_id, '''')) = ''''\n     or btrim(coalesce(p_department_name, '''')) = ''''\n     or btrim(coalesce(p_major_category, '''')) = ''''\n     or btrim(coalesce(p_school_tier, '''')) = '''' then\n    raise exception ''INVALID_INPUT: university/department/major/tier are required'' using errcode = ''22023'';\n  end if;\n\n  -- (b) mentor 단위 직렬화 — 같은 멘토의 서로 다른 요청이 동시에 승인되지 않도록.\n  select * into v_row from public.mentor_school_verifications where id = p_verification_id;\n  if not found then\n    raise exception ''VERIFICATION_NOT_FOUND'' using errcode = ''P0002'';\n  end if;\n  perform pg_advisory_xact_lock(hashtextextended(''msv_approve:'' || v_row.mentor_id::text, 0));\n\n  -- 락 획득 후 재조회(대기 중 다른 트랜잭션이 상태를 바꿨을 수 있다).\n  select * into v_row from public.mentor_school_verifications\n   where id = p_verification_id for update;\n  if v_row.status not in (''pending'', ''resubmit_required'') then\n    raise exception ''NOT_REVIEWABLE: %'', v_row.status using errcode = ''22023'';\n  end if;\n\n  -- (c) 서류 참조 실재 확인 — 참조 자체가 없으면 승인 불가.\n  if btrim(coalesce(v_row.document_storage_ref, '''')) = '''' then\n    raise exception ''DOCUMENT_REF_MISSING'' using errcode = ''22023'';\n  end if;\n  v_path := public.mentor_school_verification_storage_path(v_row.document_storage_ref);\n  if v_path is null then\n    raise exception ''DOCUMENT_REF_UNPARSEABLE'' using errcode = ''22023'';\n  end if;\n\n  -- 경로 위조 차단: 객체는 제출 멘토 소유 디렉터리 아래여야 한다\n  -- (writer 규약 ''{mentorId}/school-verifications/...'' — 타인 서류 참조 승인 금지).\n  v_owner_segment := split_part(v_path, ''/'', 1);\n  if v_owner_segment is distinct from v_row.mentor_id::text then\n    raise exception ''DOCUMENT_REF_OWNER_MISMATCH'' using errcode = ''42501'';\n  end if;\n\n  -- 실제 Storage 객체 행 존재 확인(부재면 승인 0 · 기존 approved 변경 0 으로 rollback).\n  if not exists (\n    select 1 from storage.objects o\n     where o.bucket_id = ''student-id-images''\n       and o.name = v_path\n  ) then\n    raise exception ''DOCUMENT_OBJECT_NOT_FOUND'' using errcode = ''22023'';\n  end if;\n\n  -- (d) 재승인 수명주기 — 같은 트랜잭션에서 기존 approved 를 먼저 종료시킨다.\n  update public.mentor_school_verifications\n     set status = ''superseded'',\n         updated_at = now()\n   where mentor_id = v_row.mentor_id\n     and status = ''approved''\n     and id <> v_row.id;\n  get diagnostics v_superseded = row_count;\n\n  -- (e) 대상 행 승인.\n  update public.mentor_school_verifications\n     set status = ''approved'',\n         verified_university_name = btrim(p_university_name),\n         verified_university_id = btrim(p_university_id),\n         verified_department_name = btrim(p_department_name),\n         verified_major_category = btrim(p_major_category),\n         school_tier = btrim(p_school_tier),\n         reviewed_by = v_admin,\n         reviewed_at = now(),\n         reject_reason = null\n   where id = v_row.id;\n\n  -- 감사 가능 최소 정보만 반환한다(서류 내용·signed URL·토큰 미포함).\n  return jsonb_build_object(\n    ''verification_id'', v_row.id,\n    ''mentor_id'', v_row.mentor_id,\n    ''status'', ''approved'',\n    ''superseded_count'', v_superseded,\n    ''reviewed_by'', v_admin\n  );\nend;\n$$", "comment on function public.approve_mentor_school_verification_admin(uuid, text, text, text, text, text) is\n  ''SQL174: 학교·전공 인증 승인 정본. is_admin() 전용 · 서류 참조 실재(storage.objects) 확인 · 소유 경로 검증 · 재승인 시 기존 approved → superseded 를 같은 트랜잭션에서 수행. 실패는 전부 예외(부분 반영 없음).''", "revoke all on function public.approve_mentor_school_verification_admin(uuid, text, text, text, text, text) from public", "revoke all on function public.approve_mentor_school_verification_admin(uuid, text, text, text, text, text) from anon", "grant execute on function public.approve_mentor_school_verification_admin(uuid, text, text, text, text, text)\n  to authenticated, service_role", "-- ── 4. 1인 1승인 부분 UNIQUE 인덱스(반드시 RPC 뒤) ──\ncreate unique index if not exists uq_msv_one_approved_per_mentor\n  on public.mentor_school_verifications (mentor_id)\n  where status = ''approved''", "comment on index public.uq_msv_one_approved_per_mentor is\n  ''SQL174: 멘토별 approved 최대 1행. 재승인은 approve_mentor_school_verification_admin 이 승계(superseded) 후 승인하므로 정상 경로에서는 위반하지 않는다.''", "-- ── ROLLBACK 절차 ──\n-- 역순으로 되돌린다(인덱스 → RPC → 헬퍼 → CHECK).\n--\n--   drop index if exists public.uq_msv_one_approved_per_mentor;\n--   drop function if exists public.approve_mentor_school_verification_admin(uuid, text, text, text, text, text);\n--   drop function if exists public.mentor_school_verification_storage_path(text);\n--   -- CHECK 를 4값으로 되돌리기 전에 superseded 행이 남아 있으면 23514 로 실패한다.\n--   -- 되돌릴 경우 승계 이력을 어떤 값으로 접을지 먼저 결정해야 한다(임의 UPDATE 금지).\n--   alter table public.mentor_school_verifications\n--     drop constraint if exists mentor_school_verifications_status_check;\n--   alter table public.mentor_school_verifications\n--     add constraint mentor_school_verifications_status_check\n--     check (status = any (array[''pending''::text,''approved''::text,''rejected''::text,''resubmit_required''::text]));\n\n-- >>> NATIVE_BASELINE_PART 0180 | supabase/sql/175_p1_10_account_deletion_job_history.sql | 175_p1_10_account_deletion_job_history.sql <<<\n-- 175_p1_10_account_deletion_job_history.sql\n-- ⚠️ 기능 플래그 OFF 기본 · worker kill switch OFF 고정. 실제 사용자·객체 삭제 없음.\n--    기존 SQL 151/154/161 파일은 **수정하지 않는다** — 여기서 재정의만 한다.\n--\n-- W5 §3-5-A(e)(f): 취소 후 재요청 수명주기 + \"사용자당 job 1행\" 가정 제거.\n--\n-- ── 문제(기준 HEAD a6e9183 실측) ──────────────────────────────────────────────\n--   `account_deletion_jobs.user_id` 가 UNIQUE 라서\n--   request → pending → cancel → canceled → request 에서 **새 pending job 을 만들 수 없다**.\n--   151 raw request 는 상태와 무관하게 기존 행을 그대로 돌려주므로 재요청이 영구 차단된다.\n--\n--   그런데 제약만 부분 UNIQUE 로 바꾸면 기존 함수들이 **조용히 깨진다**. 현행 SQL 은\n--   사용자당 행이 정확히 하나라는 가정 위에 쓰여 있어, 다중 행에서는\n--     · plpgsql `select … into` 가 에러 없이 **임의의 한 행**을 집고,\n--     · state 조건 없는 `update … where user_id = …` 가 **그 사용자의 과거 이력 행까지 전부**\n--       덮어쓴다(151행 140 cancel · 151행 183/187 record_error).\n--   이력을 보존하려고 만든 구조가 이력을 파괴한다.\n--\n-- ── 채택안 ────────────────────────────────────────────────────────────────────\n--   (e) 권장안 = **활성 job 에만 걸리는 부분 UNIQUE + job 행별 이력 보존**.\n--       기존 canceled 행을 pending 으로 덮어쓰는 차선은 취소 이력을 잃으므로 쓰지 않는다.\n--   (f) 그래서 아래 함수를 **전부 job_id 지정 또는 활성 상태 한정 술어로 재정의**한다.\n--       `where user_id = …` 단독 UPDATE 를 0 으로 만든다(§7 게이트).\n--\n-- 선행: 151(jobs·상태기계), 154(lease·forfeit), 161(self RPC), 115(anonymize).\n\nbegin", "set local lock_timeout=''5s''", "-- ── 0) 활성 상태 정의 헬퍼 ────────────────────────────────────────────────────\n-- 활성 = 아직 진행 중이라 사용자당 하나만 존재해야 하는 상태.\n-- 종료 상태(completed·canceled·failed)는 이력으로 여러 행 남을 수 있다.\ncreate or replace function public.account_deletion_active_states()\nreturns text[] language sql immutable set search_path to ''public'' as $$\n  select array[''pending'',''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted'']::text[];\n$$", "-- ── 1) user_id UNIQUE → 활성 job 부분 UNIQUE ─────────────────────────────────\n-- 활성 job 중복 0 은 유지하면서, 종료된 이력 행은 얼마든지 쌓일 수 있게 한다.\nalter table public.account_deletion_jobs\n  drop constraint if exists account_deletion_jobs_user_id_key", "create unique index if not exists uq_adj_active_user\n  on public.account_deletion_jobs (user_id)\n  where state in (''pending'',''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted'')", "-- 이력 조회·정렬용(결정적 최신 1행 선택).\ncreate index if not exists idx_adj_user_requested\n  on public.account_deletion_jobs (user_id, requested_at desc, id desc)", "comment on index public.uq_adj_active_user is\n  ''175: 활성 job 은 사용자당 1행. 종료(completed/canceled/failed) 이력 행은 다중 허용.''", "-- ── 2) job 해석 헬퍼 ─────────────────────────────────────────────────────────\n-- 활성 job 1행을 결정적으로 고른다(부분 UNIQUE 로 0 또는 1행이지만 정렬을 명시해 둔다).\ncreate or replace function public.account_deletion_active_job_id(p_user_id uuid)\nreturns uuid language sql stable security definer set search_path to ''public'' as $$\n  select j.id\n  from public.account_deletion_jobs j\n  where j.user_id = p_user_id\n    and j.state in (''pending'',''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted'')\n  order by j.requested_at desc, j.id desc\n  limit 1;\n$$", "-- 상태 무관 최신 1행(활성 job 이 없을 때 사용자에게 보여줄 마지막 시도).\ncreate or replace function public.account_deletion_latest_job_id(p_user_id uuid)\nreturns uuid language sql stable security definer set search_path to ''public'' as $$\n  select j.id\n  from public.account_deletion_jobs j\n  where j.user_id = p_user_id\n  order by j.requested_at desc, j.id desc\n  limit 1;\n$$", "revoke all on function public.account_deletion_active_states() from public, anon, authenticated", "revoke all on function public.account_deletion_active_job_id(uuid) from public, anon, authenticated", "revoke all on function public.account_deletion_latest_job_id(uuid) from public, anon, authenticated", "grant execute on function public.account_deletion_active_states() to service_role", "grant execute on function public.account_deletion_active_job_id(uuid) to service_role", "grant execute on function public.account_deletion_latest_job_id(uuid) to service_role", "-- ── 3) request — 재요청 시 **새 실행 단위**를 만든다 ─────────────────────────\n-- 활성 job 이 있으면 멱등 반환. 없으면 canceled·failed 이력이 있어도 새 행을 insert 한다.\n-- 새 행은 attempts=0 · last_error/next_attempt_at/lease/파괴 타임스탬프 전부 NULL 로\n-- 시작하므로 과거 실행 상태가 섞이지 않는다(§3-5-A(e)).\n-- completed 사용자의 재요청은 **명시적 거부**로 계약을 고정한다 — 계정은 이미 익명화·\n-- soft-delete 된 상태라 새 삭제 실행 단위가 의미를 갖지 못한다.\ncreate or replace function public.account_deletion_request(\n  p_user_id uuid, p_cancelable_minutes int default 30, p_dry_run boolean default true)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_id uuid; v_state text; v_latest uuid; v_latest_state text;\nbegin\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is not null then\n    select j.state into v_state from public.account_deletion_jobs j where j.id = v_id;\n    return jsonb_build_object(''ok'',true,''existing'',true,''job_id'',v_id,''state'',v_state);\n  end if;\n\n  select j.id, j.state into v_latest, v_latest_state\n    from public.account_deletion_jobs j\n    where j.user_id = p_user_id\n    order by j.requested_at desc, j.id desc\n    limit 1;\n  if v_latest_state = ''completed'' then\n    return jsonb_build_object(''ok'',false,''code'',''ALREADY_COMPLETED'',''job_id'',v_latest,''state'',''completed'');\n  end if;\n\n  insert into public.account_deletion_jobs (user_id, state, cancelable_until, dry_run)\n    values (p_user_id, ''pending'',\n            now() + make_interval(mins => greatest(0, coalesce(p_cancelable_minutes,30))),\n            coalesce(p_dry_run,true))\n    returning id into v_id;\n  return jsonb_build_object(''ok'',true,''existing'',false,''job_id'',v_id,''state'',''pending'');\nend $$", "-- ── 4) cancel — 대상 job 1행만 canceled. 과거 이력 행 불변 ───────────────────\ncreate or replace function public.account_deletion_cancel(p_user_id uuid)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_id uuid; v_state text; v_cancelable timestamptz; v_rows int;\nbegin\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n\n  select j.state, j.cancelable_until into v_state, v_cancelable\n    from public.account_deletion_jobs j where j.id = v_id for update;\n  if not found then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n  -- purging 이후(=pending 아님) 취소 금지.\n  if v_state <> ''pending'' then return jsonb_build_object(''ok'',false,''code'',''NOT_CANCELABLE'',''state'',v_state); end if;\n  if v_cancelable is not null and now() > v_cancelable then\n    return jsonb_build_object(''ok'',false,''code'',''CANCEL_WINDOW_PASSED'');\n  end if;\n\n  -- ★ where id = <대상 job> — 151행 140 의 `where user_id=…` 단독 UPDATE 를 대체한다.\n  update public.account_deletion_jobs\n    set state=''canceled'', canceled_at=now(), updated_at=now()\n    where id = v_id and state = ''pending'';\n  get diagnostics v_rows = row_count;\n  if v_rows = 0 then return jsonb_build_object(''ok'',false,''code'',''NOT_CANCELABLE''); end if;\n  return jsonb_build_object(''ok'',true,''state'',''canceled'',''job_id'',v_id);\nend $$", "-- ── 5) advance — 활성 job 1행만 전이 ────────────────────────────────────────\ncreate or replace function public.account_deletion_advance(p_user_id uuid, p_from text, p_to text)\nreturns boolean language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_rows int := 0; v_col text; v_id uuid;\nbegin\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is null then return false; end if;\n\n  -- pending→locked 은 cancelable_until 경과 후에만(취소 기회 보장).\n  -- ※ 176 에서 이 분기는 거부로 바뀐다(동의 검증과 원자 결합 — account_deletion_begin_locked).\n  if p_from=''pending'' and p_to=''locked'' then\n    update public.account_deletion_jobs\n      set state=''locked'', locked_at=now(), updated_at=now()\n      where id = v_id and state=''pending'' and (cancelable_until is null or now() >= cancelable_until);\n    get diagnostics v_rows = row_count;\n    return v_rows > 0;\n  end if;\n\n  if not (\n    (p_from=''locked'' and p_to=''purging'') or\n    (p_from=''purging'' and p_to=''storage_purged'') or\n    (p_from=''storage_purged'' and p_to=''finalized'') or\n    (p_from=''finalized'' and p_to=''auth_soft_deleted'') or\n    (p_from=''auth_soft_deleted'' and p_to=''completed'')\n  ) then\n    raise exception ''INVALID_TRANSITION % -> %'', p_from, p_to;\n  end if;\n\n  v_col := p_to || ''_at'';\n  execute format(\n    ''update public.account_deletion_jobs set state=$2, %I=now(), updated_at=now() where id=$1 and state=$3'',\n    v_col\n  ) using v_id, p_to, p_from;\n  get diagnostics v_rows = row_count;\n  return v_rows > 0;\nend $$", "-- ── 6) record_error — 대상 job 1행만 attempts 증가. 과거 이력 행 불변 ────────\ncreate or replace function public.account_deletion_record_error(\n  p_user_id uuid, p_error text, p_backoff_seconds int default 60, p_max_attempts int default 8)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_attempts int; v_id uuid;\nbegin\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n\n  -- ★ where id = <대상 job> — 151행 183 의 `where user_id=…` 단독 UPDATE 를 대체한다.\n  update public.account_deletion_jobs\n    set attempts = attempts + 1, last_error = left(coalesce(p_error,''''),1000),\n        next_attempt_at = now() + make_interval(secs => greatest(1, coalesce(p_backoff_seconds,60))),\n        updated_at = now()\n    where id = v_id\n    returning attempts into v_attempts;\n  if v_attempts is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n\n  if v_attempts >= p_max_attempts then\n    -- ★ 151행 187 의 `where user_id=…` 단독 UPDATE 를 대체한다.\n    update public.account_deletion_jobs\n      set state=''failed'', failed_at=now(), updated_at=now()\n      where id = v_id;\n    return jsonb_build_object(''ok'',true,''state'',''failed'',''attempts'',v_attempts,''job_id'',v_id);\n  end if;\n  return jsonb_build_object(''ok'',true,''attempts'',v_attempts,''job_id'',v_id);\nend $$", "-- ── 7) forfeit_and_anonymize — 활성 job 상태로만 게이트 판정 ─────────────────\n-- (몰수 동의 재검증은 176 에서 이 함수에 다시 얹는다.)\ncreate or replace function public.account_deletion_forfeit_and_anonymize(p_user_id uuid)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_id uuid; v_state text; v_balance bigint; v_ledger_id uuid;\nbegin\n  perform set_config(''ssambership.deletion_worker'', ''on'', true);\n\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is null then return jsonb_build_object(''ok'',false,''code'',''JOB_NOT_FOUND''); end if;\n  select j.state into v_state from public.account_deletion_jobs j where j.id = v_id for update;\n  if v_state is null then return jsonb_build_object(''ok'',false,''code'',''JOB_NOT_FOUND''); end if;\n  if v_state <> ''storage_purged'' then\n    return jsonb_build_object(''ok'',false,''code'',''WRONG_STATE'',''state'',v_state);\n  end if;\n\n  select w.balance_cents into v_balance from public.cash_wallets w\n    where w.user_id = p_user_id for update;\n  if v_balance is not null and v_balance > 0 then\n    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n    values (p_user_id, -v_balance, ''account_deletion_forfeit'', ''account_deletion'', p_user_id,\n            ''acct_del_forfeit:''||p_user_id::text)\n    on conflict (idempotency_key) do nothing\n    returning id into v_ledger_id;\n    if v_ledger_id is not null then\n      update public.cash_wallets set balance_cents = 0 where user_id = p_user_id;\n    end if;\n  end if;\n\n  perform public.anonymize_user_for_deletion(p_user_id, ''account_deletion'');\n  return jsonb_build_object(''ok'',true,''forfeited_cents'',coalesce(v_balance,0),''ledger_id'',v_ledger_id,''job_id'',v_id);\nend $$", "-- ── 8) self 상태 조회 — 활성 job, 없으면 최신 1행을 결정적으로 반환 ──────────\ncreate or replace function public.account_deletion_status_self()\nreturns jsonb language plpgsql stable security definer set search_path to ''public'' as $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_id uuid;\n  v_job record;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED'' using errcode = ''28000''; end if;\n\n  v_id := coalesce(public.account_deletion_active_job_id(v_uid), public.account_deletion_latest_job_id(v_uid));\n  if v_id is null then\n    return jsonb_build_object(\n      ''ok'', true, ''exists'', false, ''state'', null,\n      ''cancelable_until'', null, ''write_blocked'', false, ''can_cancel'', false);\n  end if;\n\n  select j.state, j.cancelable_until into v_job\n    from public.account_deletion_jobs j where j.id = v_id;\n\n  -- 민감한 worker 오류·purge 내부 정보는 반환하지 않는다.\n  return jsonb_build_object(\n    ''ok'', true,\n    ''exists'', true,\n    ''state'', v_job.state,\n    ''cancelable_until'', v_job.cancelable_until,\n    ''write_blocked'', v_job.state in\n      (''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted''),\n    ''can_cancel'', v_job.state = ''pending''\n      and (v_job.cancelable_until is null or now() <= v_job.cancelable_until)\n  );\nend $$", "-- ── 9) ACL 재확인(재정의로 초기화되지 않도록 명시) ──────────────────────────\nrevoke all on function public.account_deletion_request(uuid,int,boolean) from public, anon, authenticated", "revoke all on function public.account_deletion_cancel(uuid) from public, anon, authenticated", "revoke all on function public.account_deletion_advance(uuid,text,text) from public, anon, authenticated", "revoke all on function public.account_deletion_record_error(uuid,text,int,int) from public, anon, authenticated", "revoke all on function public.account_deletion_forfeit_and_anonymize(uuid) from public, anon, authenticated", "revoke all on function public.account_deletion_status_self() from public, anon", "grant execute on function public.account_deletion_request(uuid,int,boolean) to service_role", "grant execute on function public.account_deletion_cancel(uuid) to service_role", "grant execute on function public.account_deletion_advance(uuid,text,text) to service_role", "grant execute on function public.account_deletion_record_error(uuid,text,int,int) to service_role", "grant execute on function public.account_deletion_forfeit_and_anonymize(uuid) to service_role", "grant execute on function public.account_deletion_status_self() to authenticated, service_role", "commit", "-- ── §V 검증(적용 후 실행) ────────────────────────────────────────────────────\n-- (1) 활성 job 부분 UNIQUE 존재 · user_id 전체 UNIQUE 부재\n--     select indexname, indexdef from pg_indexes\n--      where schemaname=''public'' and tablename=''account_deletion_jobs'';\n--     select conname from pg_constraint where conrelid=''public.account_deletion_jobs''::regclass and contype=''u'';\n--     기대: uq_adj_active_user 존재 · account_deletion_jobs_user_id_key 부재\n-- (2) `where user_id = …` 단독 UPDATE 0 증명\n--     select p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace\n--      where n.nspname=''public'' and p.proname like ''account_deletion%''\n--        and pg_get_functiondef(p.oid) ~* ''update\\s+public\\.account_deletion_jobs[^;]*where\\s+(j\\.)?id\\s*=''\n--     기대: cancel · record_error · advance 가 전부 id 기준\n-- (3) request → cancel → request 로 새 pending job 생성(이력 2행)\n-- (4) 이력 2행 사용자의 cancel/record_error 가 대상 1행만 바꾸는지\n--\n-- ── ROLLBACK ────────────────────────────────────────────────────────────────\n--   drop index if exists public.uq_adj_active_user;\n--   drop index if exists public.idx_adj_user_requested;\n--   alter table public.account_deletion_jobs add constraint account_deletion_jobs_user_id_key unique (user_id);\n--   -- 함수는 151/154/161 원문을 다시 실행해 복원한다(파일 무수정이므로 그대로 재적용 가능).\n--   ※ 부분 UNIQUE 를 되돌리려면 사용자당 이력 행이 1행이어야 한다(다중 행이면 제약 추가 실패).\n\n-- >>> NATIVE_BASELINE_PART 0181 | supabase/sql/176_p1_10_account_deletion_forfeit_consent.sql | 176_p1_10_account_deletion_forfeit_consent.sql <<<\n-- 176_p1_10_account_deletion_forfeit_consent.sql\n-- ⚠️ 기능 플래그 OFF 기본 · worker kill switch OFF 고정. 실제 사용자·객체 삭제 없음.\n--    기존 SQL 151/154/161 파일은 **수정하지 않는다** — 여기서 재정의만 한다.\n--\n-- W5 §3-5-A: 잔액 몰수 동의를 **서버 정본**으로 확정하고 3계층에서 fail-closed 로 강제한다.\n--\n-- ── 문제(기준 HEAD a6e9183 실측) ──────────────────────────────────────────────\n--   · `account_deletion_jobs` 20개 컬럼에 **동의 기록 컬럼이 없다**.\n--   · `account_deletion_request_self(int, bool)` 에 동의 인자도 잔액 사전조건도 없다.\n--   · 154 `account_deletion_forfeit_and_anonymize` 는 `if v_balance > 0` 이면 **무조건 몰수**한다.\n--   · 웹은 클라이언트 boolean(`forfeitConsent`) 만 보고 **자기가 직접** 원장을 넣었다.\n--   즉 saga 경로는 지금도 **동의 없이 양수 잔액을 몰수**하도록 되어 있다. 실피해가 없는\n--   유일한 이유는 kill switch 가 OFF 라 어떤 job 도 storage_purged 에 도달한 적이 없기 때문이다.\n--\n-- ── 3계층 방어(동의 검증은 파괴 작업 **전에** 끝나야 한다) ───────────────────\n--   1층 요청     : 양수 잔액 + 검증된 동의 없음 → **job 생성 0** (FORFEIT_CONSENT_REQUIRED)\n--   2층 worker진입: `pending → locked` **전에** 동의·현재 잔액 재검증\n--                   → advance 0 · session revoke 0 · Storage remove 0 · 몰수 0\n--   3층 몰수 RPC : 마지막 방어선으로 동의를 다시 검증\n--\n-- ── TOCTOU 0 (§3-5-A(d)) ─────────────────────────────────────────────────────\n--   worker 가 잔액을 SELECT 한 뒤 별도로 advance 를 호출하면 그 사이 충전이 끼어든다.\n--   그래서 `account_deletion_begin_locked` 하나가 [job 행 FOR UPDATE → wallet 행 FOR UPDATE\n--   → 검증 → 전이] 를 **단일 트랜잭션**으로 수행하고, raw advance 의 pending→locked 분기는\n--   아예 **거부**한다(우회 0).\n--\n-- 선행: 151, 154, 161, 175.\n\nbegin", "set local lock_timeout=''5s''", "-- ── 1) 동의 정본 컬럼 ────────────────────────────────────────────────────────\n-- 동의는 **금액에 묶인다**. pending 구간은 write block 대상이 아니라(151행 47)\n-- 취소 창 동안 충전이 정상 허용되므로, 동의 시점 금액을 함께 박제해야 stale 판정이 가능하다.\nalter table public.account_deletion_jobs add column if not exists forfeit_consent_at timestamptz", "alter table public.account_deletion_jobs add column if not exists consented_balance_cents bigint", "comment on column public.account_deletion_jobs.forfeit_consent_at is\n  ''176: 잔액 몰수 동의 시각(서버 기록). NULL 이면 동의 없음 — 양수 잔액 사용자는 진행 불가.''", "comment on column public.account_deletion_jobs.consented_balance_cents is\n  ''176: 동의 당시 서버가 읽은 잔액(cents). 현재 잔액이 이보다 크면 FORFEIT_CONSENT_STALE.''", "-- ── 2) 요청 정본 — 동의를 사용자·job 과 결합해 기록한다 ──────────────────────\n-- 클라이언트 boolean 을 그대로 믿지 않는다: 잔액은 **서버가 읽고**, 동의 시각·금액을\n-- job 행에 박제한다. 호출자가 화면에서 본 금액을 echo 하면(p_acknowledged_balance_cents)\n-- 그 시점에 이미 어긋난 동의를 요청 단계에서 걸러낸다.\ncreate or replace function public.account_deletion_request_consented(\n  p_user_id uuid,\n  p_cancelable_minutes int default 30,\n  p_dry_run boolean default true,\n  p_forfeit_consent boolean default false,\n  p_acknowledged_balance_cents bigint default null\n) returns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_id uuid; v_state text; v_latest uuid; v_latest_state text;\n  v_balance bigint; v_consent_at timestamptz; v_consented bigint;\nbegin\n  -- 활성 job 이 있으면 멱등 반환(중복 요청에도 동의 기록·원장 중복 0).\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is not null then\n    select j.state into v_state from public.account_deletion_jobs j where j.id = v_id;\n    return jsonb_build_object(''ok'',true,''existing'',true,''job_id'',v_id,''state'',v_state);\n  end if;\n\n  select j.id, j.state into v_latest, v_latest_state\n    from public.account_deletion_jobs j\n    where j.user_id = p_user_id\n    order by j.requested_at desc, j.id desc\n    limit 1;\n  if v_latest_state = ''completed'' then\n    return jsonb_build_object(''ok'',false,''code'',''ALREADY_COMPLETED'',''job_id'',v_latest,''state'',''completed'');\n  end if;\n\n  -- 잔액은 **서버가 읽는다**. 지갑 행이 없으면 0.\n  select coalesce(w.balance_cents, 0) into v_balance\n    from public.cash_wallets w where w.user_id = p_user_id;\n  v_balance := coalesce(v_balance, 0);\n\n  if v_balance > 0 then\n    if not coalesce(p_forfeit_consent, false) then\n      -- 1층: job 자체를 만들지 않는다.\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_REQUIRED'',''balance_cents'',v_balance);\n    end if;\n    if p_acknowledged_balance_cents is not null and p_acknowledged_balance_cents <> v_balance then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_STALE'',\n        ''acknowledged_balance_cents'', p_acknowledged_balance_cents, ''current_balance_cents'', v_balance);\n    end if;\n    v_consent_at := now();\n    v_consented := v_balance;\n  else\n    -- 잔액 0 사용자는 별도 몰수 동의 없이 진행할 수 있다.\n    v_consent_at := null;\n    v_consented := null;\n  end if;\n\n  insert into public.account_deletion_jobs\n      (user_id, state, cancelable_until, dry_run, forfeit_consent_at, consented_balance_cents)\n    values (p_user_id, ''pending'',\n            now() + make_interval(mins => greatest(0, coalesce(p_cancelable_minutes,30))),\n            coalesce(p_dry_run,true), v_consent_at, v_consented)\n    returning id into v_id;\n\n  return jsonb_build_object(''ok'',true,''existing'',false,''job_id'',v_id,''state'',''pending'',\n                            ''forfeit_consent_at'', v_consent_at,\n                            ''consented_balance_cents'', v_consented);\nend $$", "-- raw 2·3인자 request 는 **동의 없는 경로**다 → 양수 잔액이면 job 생성 0.\ncreate or replace function public.account_deletion_request(\n  p_user_id uuid, p_cancelable_minutes int default 30, p_dry_run boolean default true)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\nbegin\n  return public.account_deletion_request_consented(\n    p_user_id, p_cancelable_minutes, p_dry_run, false, null);\nend $$", "-- ── 3) self RPC ─────────────────────────────────────────────────────────────\n-- self 응답 정형화 — 실패 코드는 그대로 전달하고, 성공 시에만 job 정보를 붙인다.\ncreate or replace function public.account_deletion_self_response(p_user_id uuid, p_raw jsonb)\nreturns jsonb language plpgsql stable security definer set search_path to ''public'' as $$\ndeclare v_job_id uuid; v_state text; v_cancelable timestamptz; v_dry boolean;\nbegin\n  if coalesce((p_raw ->> ''ok'')::boolean, false) is not true then\n    return p_raw;\n  end if;\n  v_job_id := nullif(p_raw ->> ''job_id'','''')::uuid;\n  select j.state, j.cancelable_until, j.dry_run into v_state, v_cancelable, v_dry\n    from public.account_deletion_jobs j where j.id = v_job_id;\n  return jsonb_build_object(\n    ''ok'', true,\n    ''existing'', coalesce((p_raw ->> ''existing'')::boolean, true),\n    ''job_id'', v_job_id,\n    ''state'', v_state,\n    ''cancelable_until'', v_cancelable,\n    ''dry_run'', v_dry\n  );\nend $$", "-- 기존 2인자 시그니처를 **그 자리에서 안전하게** 재정의한다.\n-- 동의 인자를 더한 오버로드를 신설하고 2인자를 남기면 앱이 안전장치를 우회한다 → 금지.\n-- 그래서 2인자 함수 자체가 fail-closed 가 되게 만든다:\n--   잔액 0  → 정상 job 생성\n--   잔액 >0 → FORFEIT_CONSENT_REQUIRED, job 생성 0\ncreate or replace function public.account_deletion_request_self(\n  p_cancelable_minutes integer default 30,\n  p_dry_run boolean default false\n) returns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_raw jsonb;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED'' using errcode = ''28000''; end if;\n  perform pg_advisory_xact_lock(hashtextextended(''account_deletion_self:'' || v_uid::text, 0));\n\n  v_raw := public.account_deletion_request_consented(\n    v_uid, greatest(0, coalesce(p_cancelable_minutes, 30)), coalesce(p_dry_run, false), false, null);\n  return public.account_deletion_self_response(v_uid, v_raw);\nend $$", "-- 동의를 수반하는 self 경로 — **별도 이름**이다(2인자 함수의 오버로드가 아니다).\n-- 이 함수를 호출하는 행위 자체가 동의이며, 금액은 서버가 읽어 job 에 박제한다.\ncreate or replace function public.account_deletion_request_self_consented(\n  p_cancelable_minutes integer default 30,\n  p_dry_run boolean default false,\n  p_acknowledged_balance_cents bigint default null\n) returns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_raw jsonb;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED'' using errcode = ''28000''; end if;\n  perform pg_advisory_xact_lock(hashtextextended(''account_deletion_self:'' || v_uid::text, 0));\n\n  v_raw := public.account_deletion_request_consented(\n    v_uid, greatest(0, coalesce(p_cancelable_minutes, 30)), coalesce(p_dry_run, false),\n    true, p_acknowledged_balance_cents);\n  return public.account_deletion_self_response(v_uid, v_raw);\nend $$", "-- ── 4) 2층 — 동의 검증 + `pending → locked` 원자 전이 ────────────────────────\n-- worker 는 잔액을 따로 SELECT 하지 않는다. 이 함수 하나가 전부다.\n-- 검증 실패 시 **어떤 행도 수정하지 않고** 반환하므로 job 은 pending 그대로 남는다.\ncreate or replace function public.account_deletion_begin_locked(p_user_id uuid)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_id uuid; v_state text; v_cancelable timestamptz;\n  v_consent_at timestamptz; v_consented bigint; v_balance bigint; v_rows int;\nbegin\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is null then return jsonb_build_object(''ok'',false,''code'',''JOB_NOT_FOUND''); end if;\n\n  -- ① 대상 deletion job 행 FOR UPDATE\n  select j.state, j.cancelable_until, j.forfeit_consent_at, j.consented_balance_cents\n    into v_state, v_cancelable, v_consent_at, v_consented\n    from public.account_deletion_jobs j where j.id = v_id for update;\n  if not found then return jsonb_build_object(''ok'',false,''code'',''JOB_NOT_FOUND''); end if;\n  if v_state <> ''pending'' then\n    return jsonb_build_object(''ok'',false,''code'',''NOT_PENDING'',''state'',v_state);\n  end if;\n  if v_cancelable is not null and now() < v_cancelable then\n    return jsonb_build_object(''ok'',false,''code'',''CANCEL_WINDOW_OPEN'',''cancelable_until'',v_cancelable);\n  end if;\n\n  -- ② 대상 cash_wallets 행 FOR UPDATE\n  --    이 잠금을 먼저 잡으면, 뒤따르는 충전은 잠금 해제(=locked 커밋) 후\n  --    151/154 write gate(adg_cash_wallets·adg_cash_ledger)에 의해 거부된다.\n  select coalesce(w.balance_cents, 0) into v_balance\n    from public.cash_wallets w where w.user_id = p_user_id for update;\n  v_balance := coalesce(v_balance, 0);\n\n  -- ③ 동의 시각·동의 금액·현재 잔액 검증\n  if v_balance > 0 then\n    if v_consent_at is null then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_REQUIRED'',''current_balance_cents'',v_balance);\n    end if;\n    -- 증가 → 재동의 요구(파괴 단계 0회). 감소·동일 → 현재 잔액만 몰수(권장 정책).\n    if v_balance > coalesce(v_consented, 0) then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_STALE'',\n        ''consented_balance_cents'', v_consented, ''current_balance_cents'', v_balance);\n    end if;\n  end if;\n\n  -- ④ 검증 성공 시에만 pending → locked\n  update public.account_deletion_jobs\n    set state=''locked'', locked_at=now(), updated_at=now()\n    where id = v_id and state=''pending'';\n  get diagnostics v_rows = row_count;\n  if v_rows = 0 then return jsonb_build_object(''ok'',false,''code'',''NOT_PENDING''); end if;\n\n  return jsonb_build_object(''ok'',true,''state'',''locked'',''job_id'',v_id,''balance_cents'',v_balance);\nend $$", "-- ── 5) raw advance 의 pending→locked 우회 차단 ──────────────────────────────\ncreate or replace function public.account_deletion_advance(p_user_id uuid, p_from text, p_to text)\nreturns boolean language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_rows int := 0; v_col text; v_id uuid;\nbegin\n  -- 동의 검증을 건너뛰는 경로를 남기지 않는다 — 정본은 account_deletion_begin_locked 하나다.\n  if p_from=''pending'' and p_to=''locked'' then\n    raise exception ''USE_BEGIN_LOCKED: pending->locked must go through account_deletion_begin_locked''\n      using errcode = ''42501'';\n  end if;\n\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is null then return false; end if;\n\n  if not (\n    (p_from=''locked'' and p_to=''purging'') or\n    (p_from=''purging'' and p_to=''storage_purged'') or\n    (p_from=''storage_purged'' and p_to=''finalized'') or\n    (p_from=''finalized'' and p_to=''auth_soft_deleted'') or\n    (p_from=''auth_soft_deleted'' and p_to=''completed'')\n  ) then\n    raise exception ''INVALID_TRANSITION % -> %'', p_from, p_to;\n  end if;\n\n  v_col := p_to || ''_at'';\n  execute format(\n    ''update public.account_deletion_jobs set state=$2, %I=now(), updated_at=now() where id=$1 and state=$3'',\n    v_col\n  ) using v_id, p_to, p_from;\n  get diagnostics v_rows = row_count;\n  return v_rows > 0;\nend $$", "-- ── 6) 3층 — 몰수 RPC 의 동의 재검증(마지막 방어선) ─────────────────────────\n-- 멱등키·reason 정본: `acct_del_forfeit:{uid}` / `account_deletion_forfeit`.\n--   웹 즉시 경로가 쓰던 `forfeit_on_deletion:{uid}` / `forfeit_on_deletion` 은 그 경로 자체를\n--   폐지하면서 함께 사라진다. 기존 원장 행은 **소급 수정하지 않는다**(append-only).\ncreate or replace function public.account_deletion_forfeit_and_anonymize(p_user_id uuid)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_id uuid; v_state text; v_balance bigint; v_ledger_id uuid;\n  v_consent_at timestamptz; v_consented bigint;\nbegin\n  perform set_config(''ssambership.deletion_worker'', ''on'', true);\n\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is null then return jsonb_build_object(''ok'',false,''code'',''JOB_NOT_FOUND''); end if;\n  select j.state, j.forfeit_consent_at, j.consented_balance_cents\n    into v_state, v_consent_at, v_consented\n    from public.account_deletion_jobs j where j.id = v_id for update;\n  if v_state is null then return jsonb_build_object(''ok'',false,''code'',''JOB_NOT_FOUND''); end if;\n  if v_state <> ''storage_purged'' then\n    return jsonb_build_object(''ok'',false,''code'',''WRONG_STATE'',''state'',v_state);\n  end if;\n\n  select w.balance_cents into v_balance from public.cash_wallets w\n    where w.user_id = p_user_id for update;\n\n  if v_balance is not null and v_balance > 0 then\n    -- 3층 동의 재검증 — 여기까지 왔다는 건 2층을 통과했다는 뜻이지만, 그래도 다시 본다.\n    if v_consent_at is null then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_REQUIRED'',''current_balance_cents'',v_balance);\n    end if;\n    if v_balance > coalesce(v_consented, 0) then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_STALE'',\n        ''consented_balance_cents'', v_consented, ''current_balance_cents'', v_balance);\n    end if;\n\n    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n    values (p_user_id, -v_balance, ''account_deletion_forfeit'', ''account_deletion'', p_user_id,\n            ''acct_del_forfeit:''||p_user_id::text)\n    on conflict (idempotency_key) do nothing\n    returning id into v_ledger_id;\n    if v_ledger_id is not null then\n      update public.cash_wallets set balance_cents = 0 where user_id = p_user_id;\n    end if;\n  end if;\n\n  perform public.anonymize_user_for_deletion(p_user_id, ''account_deletion'');\n  return jsonb_build_object(''ok'',true,''forfeited_cents'',coalesce(v_balance,0),''ledger_id'',v_ledger_id,''job_id'',v_id);\nend $$", "-- ── 7) ACL ──────────────────────────────────────────────────────────────────\nrevoke all on function public.account_deletion_request_consented(uuid,int,boolean,boolean,bigint) from public, anon, authenticated", "revoke all on function public.account_deletion_request(uuid,int,boolean) from public, anon, authenticated", "revoke all on function public.account_deletion_begin_locked(uuid) from public, anon, authenticated", "revoke all on function public.account_deletion_advance(uuid,text,text) from public, anon, authenticated", "revoke all on function public.account_deletion_forfeit_and_anonymize(uuid) from public, anon, authenticated", "revoke all on function public.account_deletion_self_response(uuid,jsonb) from public, anon, authenticated", "revoke all on function public.account_deletion_request_self(integer, boolean) from public, anon", "revoke all on function public.account_deletion_request_self_consented(integer, boolean, bigint) from public, anon", "grant execute on function public.account_deletion_request_consented(uuid,int,boolean,boolean,bigint) to service_role", "grant execute on function public.account_deletion_request(uuid,int,boolean) to service_role", "grant execute on function public.account_deletion_begin_locked(uuid) to service_role", "grant execute on function public.account_deletion_advance(uuid,text,text) to service_role", "grant execute on function public.account_deletion_forfeit_and_anonymize(uuid) to service_role", "grant execute on function public.account_deletion_self_response(uuid,jsonb) to service_role", "grant execute on function public.account_deletion_request_self(integer, boolean) to authenticated, service_role", "grant execute on function public.account_deletion_request_self_consented(integer, boolean, bigint) to authenticated, service_role", "comment on function public.account_deletion_begin_locked(uuid) is\n  ''176: 동의·잔액·취소창 검증과 pending→locked 를 단일 트랜잭션으로. raw advance 의 pending→locked 는 거부된다.''", "comment on function public.account_deletion_request_self(integer, boolean) is\n  ''P1-10/176: 본인 탈퇴 요청(동의 없음 경로). 양수 잔액이면 FORFEIT_CONSENT_REQUIRED 로 job 생성 0.''", "comment on function public.account_deletion_request_self_consented(integer, boolean, bigint) is\n  ''176: 본인 탈퇴 요청 + 잔액 몰수 동의. 금액은 서버가 읽어 job 에 박제한다(오버로드 아님 — 별도 이름).''", "commit", "-- ── §V 검증(적용 후 실행) ────────────────────────────────────────────────────\n-- (1) 우회 가능한 레거시 오버로드 0\n--     select p.oid::regprocedure::text, array_to_string(p.proacl,'' | '')\n--       from pg_proc p join pg_namespace n on n.oid=p.pronamespace\n--      where n.nspname=''public'' and p.proname like ''account_deletion_request%'';\n--     기대: request_self 는 (integer,boolean) 단 1종 · request 는 (uuid,int,boolean) 단 1종\n-- (2) raw advance 우회 0 — select public.account_deletion_advance(<uid>,''pending'',''locked'') → 42501\n-- (3) 잔액>0 · 동의 없음 → job 생성 0 / 잔액>0 · 동의 → 몰수 원장 정확히 1행\n-- (4) 동의 후 잔액 증가 → begin_locked 가 FORFEIT_CONSENT_STALE, state 는 pending 유지\n--\n-- ── ROLLBACK ────────────────────────────────────────────────────────────────\n--   drop function if exists public.account_deletion_begin_locked(uuid);\n--   drop function if exists public.account_deletion_request_self_consented(integer, boolean, bigint);\n--   drop function if exists public.account_deletion_request_consented(uuid,int,boolean,boolean,bigint);\n--   drop function if exists public.account_deletion_self_response(uuid,jsonb);\n--   alter table public.account_deletion_jobs drop column if exists forfeit_consent_at;\n--   alter table public.account_deletion_jobs drop column if exists consented_balance_cents;\n--   -- request/advance/forfeit_and_anonymize/request_self 는 175(및 151/154/161) 원문 재적용으로 복원.\n\n-- >>> NATIVE_BASELINE_PART 0182 | supabase/sql/177_p1_10_account_deletion_session_revoke.sql | 177_p1_10_account_deletion_session_revoke.sql <<<\n-- 177_p1_10_account_deletion_session_revoke.sql\n-- ⚠️ 기능 플래그 OFF 기본 · worker kill switch OFF 고정. 실제 사용자·객체 삭제 없음.\n--\n-- W5 §3-2: 세션 폐기 인자 오용 제거 — uid 기반 실동작 수단 신설.\n--\n-- ── 문제(기준 HEAD a6e9183 실측) ──────────────────────────────────────────────\n--   `makeRevokeSessions` 가 `admin.auth.admin.signOut(userId, \"global\")` 를 부른다.\n--   설치된 `@supabase/auth-js` **2.104.1** 의 실제 계약은\n--       signOut(jwt: string, scope?: SignOutScope)\n--   이며 **첫 인자는 사용자 UUID 가 아니라 로그인된 사용자의 JWT** 다. worker 는 그 JWT 가 없다.\n--   구 코드가 tsc 를 통과한 이유는 `as unknown as {...}` 로 SDK 타입을 버리고\n--   자체 구조 타입을 새로 선언했기 때문이다(타입 우회).\n--\n-- ── SDK 실측(GoTrueAdminApi 공개 메서드 전수) ────────────────────────────────\n--   signOut(jwt, scope?) · inviteUserByEmail · generateLink · createUser · listUsers ·\n--   getUserById · updateUserById(uid, attributes) · deleteUser(id, shouldSoftDelete?)\n--   (그 외는 전부 private, + mfa/oauth/customProviders 서브 API)\n--   → **uid 만으로 전 세션을 끊는 admin 메서드는 존재하지 않는다.**\n--   `AdminUserAttributes.ban_duration?: string | ''none''` 은 실재한다(types.d.ts:446).\n--\n-- ── 채택 ──────────────────────────────────────────────────────────────────────\n--   지시서가 허용한 3선택지 중 ①+② 를 **함께** 쓴다. 둘은 서로 다른 계약을 만족하며\n--   어느 하나로는 부족하기 때문이다:\n--     ① updateUserById(uid, { ban_duration }) → 신규 로그인·refresh 교환을 Auth 가 거절\n--     ② 이 파일의 RPC                          → auth.sessions·auth.refresh_tokens 실삭제\n--   ★ 어느 쪽도 **이미 발급된 access token 자체는 무효화하지 못한다**(JWT 무상태 —\n--     PostgREST/Storage 는 만료 전까지 서명만 본다). 그 구간은 151/154 write gate 가 막는다.\n--     \"세션 폐기\" · \"재로그인 차단\" · \"기존 토큰 무효화\" 는 서로 다른 계약이다 — 합치지 않는다.\n--\n-- 보안 요건(지시서 §3-2 선택지 2 의무): SECURITY DEFINER · 고정 search_path ·\n--   authenticated·anon·PUBLIC EXECUTE 0 · service_role 전용 grant.\n-- 반환값·로그에 토큰 문자열·세션 식별자를 싣지 않는다(개수만).\n--\n-- 선행: 151, 154, 175, 176.\n\nbegin", "set local lock_timeout=''5s''", "create or replace function public.account_deletion_revoke_sessions(p_user_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare v_sessions int := 0; v_tokens int := 0;\nbegin\n  if p_user_id is null then\n    return jsonb_build_object(''ok'', false, ''code'', ''USER_REQUIRED'');\n  end if;\n\n  -- refresh token 을 먼저 지운다(세션 FK 로 묶인 것 + 레거시 user_id 문자열 컬럼 양쪽).\n  delete from auth.refresh_tokens rt\n   where rt.session_id in (select s.id from auth.sessions s where s.user_id = p_user_id)\n      or rt.user_id = p_user_id::text;\n  get diagnostics v_tokens = row_count;\n\n  delete from auth.sessions s where s.user_id = p_user_id;\n  get diagnostics v_sessions = row_count;\n\n  -- 토큰 값·세션 uuid 는 반환하지 않는다 — 개수만.\n  return jsonb_build_object(\n    ''ok'', true,\n    ''sessions_deleted'', v_sessions,\n    ''refresh_tokens_deleted'', v_tokens\n  );\nend $$", "comment on function public.account_deletion_revoke_sessions(uuid) is\n  ''177: 계정 삭제 locked 단계의 세션 실폐기(auth.sessions·auth.refresh_tokens). service_role 전용. 반환은 개수만.''", "revoke all on function public.account_deletion_revoke_sessions(uuid) from public, anon, authenticated", "grant execute on function public.account_deletion_revoke_sessions(uuid) to service_role", "commit", "-- ── §V 검증(적용 후 실행) ────────────────────────────────────────────────────\n-- (1) ACL 실측 — authenticated·anon·PUBLIC EXECUTE 0\n--     select p.oid::regprocedure::text, p.prosecdef, p.proconfig::text,\n--            array_to_string(p.proacl,'' | '') as acl\n--       from pg_proc p join pg_namespace n on n.oid=p.pronamespace\n--      where n.nspname=''public'' and p.proname=''account_deletion_revoke_sessions'';\n--     기대: prosecdef=true · proconfig={search_path=public} ·\n--           acl = postgres=X/postgres | service_role=X/postgres  (anon·authenticated·\"=X\" 없음)\n-- (2) 전용 staging fixture 로 세션 1건 생성 후 호출 → sessions_deleted>0,\n--     기존 access token 보호 API 재요청 실패 · 기존 refresh token 갱신 실패를 **각각** 판정.\n--     신규 로그인 차단 여부는 ①(ban) 의 몫이며 **별도로** 판정한다.\n--\n-- ── ROLLBACK ────────────────────────────────────────────────────────────────\n--   drop function if exists public.account_deletion_revoke_sessions(uuid);\n--   (추가형 단일 함수 — 되돌림 무손실. auth 스키마 객체는 일절 변경하지 않았다.)\n\n-- >>> NATIVE_BASELINE_PART 0183 | supabase/sql/178_p1_10_account_deletion_legacy_claim_revoke.sql | 178_p1_10_account_deletion_legacy_claim_revoke.sql <<<\n-- 178_p1_10_account_deletion_legacy_claim_revoke.sql\n-- ⚠️ 기능 플래그 OFF 기본 · worker kill switch OFF 고정. 실제 사용자·객체 삭제 없음.\n--\n-- W5 §3-6: 레거시 claim RPC 권한 회수.\n--\n-- ── 대상 ──────────────────────────────────────────────────────────────────────\n--   151 `account_deletion_worker_claim(p_limit integer)` 은 lease 를 **읽지도 쓰지도 않는다**.\n--   동시 러너가 같은 job 을 중복 처리할 수 있어, lease 기반\n--   `account_deletion_claim(p_owner, p_limit, p_lease_seconds)`(154) 로 대체됐다.\n--   그런데 레거시 함수의 `service_role` EXECUTE 가 **여전히 남아 있다**(실측:\n--   acl = postgres=X/postgres | service_role=X/postgres). 정본 경로 단일화 관점에서 회수 대상이다.\n--\n-- ── 회수 전 호출부 실측(저장소 전체) ─────────────────────────────────────────\n--   `account_deletion_worker_claim` 문자열 검색 결과 — 정의·ACL 문(151행 194/208/213)과\n--   \"쓰지 않는다\"는 주석 2곳(app/api/cron/account-deletion/route.ts:29,\n--   lib/account/accountDeletionAdapters.ts:281)뿐. **실제 호출부 0건.**\n--   러너는 154 `account_deletion_claim` 만 쓴다(accountDeletionAdapters.claimDeletionJobs).\n--\n-- ── 선택: DROP 이 아니라 REVOKE ──────────────────────────────────────────────\n--   함수를 폐기하면 151 파일이 기술하는 객체와 DB 실태가 어긋나 롤백 대조가 어려워진다.\n--   (151 은 불변 대상은 아니지만 이번 회차에서 수정하지 않기로 한 파일이다.)\n--   EXECUTE 를 0 으로 만들면 우회 호출 가능성은 동일하게 사라지면서 정의는 감사 가능하게 남는다.\n--   → REVOKE 를 택한다. lease 기반 154 claim 은 그대로 둔다.\n--\n-- 선행: 151, 154.\n\nbegin", "set local lock_timeout=''5s''", "-- 호출부가 생겼는지 마지막으로 한 번 더 방어 — 이 파일 적용 시점의 계약을 명시한다.\ndo $$\nbegin\n  if not exists (\n    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n     where n.nspname = ''public'' and p.proname = ''account_deletion_worker_claim''\n  ) then\n    raise notice ''178: account_deletion_worker_claim 이 이미 없음 — 회수 대상 없음(무해).'';\n  end if;\nend $$", "revoke all on function public.account_deletion_worker_claim(integer) from public, anon, authenticated", "revoke execute on function public.account_deletion_worker_claim(integer) from service_role", "comment on function public.account_deletion_worker_claim(integer) is\n  ''151(레거시): lease 미사용 claim. 178 에서 EXECUTE 전면 회수 — 정본은 154 account_deletion_claim.''", "commit", "-- ── §V 검증(적용 후 실행) ────────────────────────────────────────────────────\n--   select p.oid::regprocedure::text, coalesce(array_to_string(p.proacl,'' | ''),''(default)'') as acl\n--     from pg_proc p join pg_namespace n on n.oid=p.pronamespace\n--    where n.nspname=''public'' and p.proname in (''account_deletion_worker_claim'',''account_deletion_claim'');\n--   기대: worker_claim → postgres=X/postgres 만(service_role 없음)\n--         claim(text,integer,integer) → postgres=X/postgres | service_role=X/postgres (불변)\n--\n-- ── ROLLBACK ────────────────────────────────────────────────────────────────\n--   grant execute on function public.account_deletion_worker_claim(integer) to service_role;\n\n-- >>> NATIVE_BASELINE_PART 0184 | supabase/sql/179_p1_10_account_deletion_consent_column_canon.sql | 179_p1_10_account_deletion_consent_column_canon.sql <<<\n-- 179_p1_10_account_deletion_consent_column_canon.sql\n-- ⚠️ 기능 플래그 OFF 기본 · worker kill switch OFF 고정. 실제 사용자·객체 삭제 없음.\n--    기존 SQL 175~178 파일은 **수정하지 않는다** — 여기서 재정의만 한다(W5-c §3-1).\n--\n-- W5-c §3-1: `consented_balance_cents` 를 **NOT NULL 정본**으로 확정한다.\n--\n-- ── 문제(W5 실행 결과와 개정 지시서 사이의 편차) ─────────────────────────────\n--   176 은 잔액 0 경로에서 `v_consented := null` 로 두었다(176행 93). STALE·REQUIRED\n--   가드는 `coalesce(v_consented, 0)` 으로 방어하고 있어 논리적 구멍은 없지만,\n--   \"동의 금액\" 컬럼에 두 가지 무(無) 표현(NULL/0)이 공존하면 이후 코드가 coalesce 를\n--   빠뜨리는 순간 조용히 오판한다. 표현을 하나로 줄인다:\n--     · 잔액 > 0 동의 경로 → 동의 당시 FOR UPDATE 로 읽은 잔액 기록(현행 유지)\n--     · 잔액 = 0 경로      → `consented_balance_cents = 0` **명시 기록**,\n--                            `forfeit_consent_at` 은 null 유지(동의 행위 자체가 없었음)\n--   NOT NULL 이후에는 NULL 을 넣는 어떤 신규 경로도 **삽입 시점에 즉시 실패**한다\n--   (DEFAULT 0 은 컬럼 생략 경로용 — 명시적 NULL 은 구조적으로 거부된다).\n--\n-- ── 실측(staging lbeqxarxothkmzqvpudy, 2026-07-26 preflight) ──────────────────\n--   account_deletion_jobs: total 1 · consented_balance_cents NULL 0행 → backfill 은\n--   멱등 no-op 이지만 (a) 단계로 남겨 어떤 환경에서도 NOT NULL 승격이 실패하지 않게 한다.\n--\n-- ── job 생성 경로 전수(§2-3 표) ──────────────────────────────────────────────\n--   insert 는 단 한 곳 — account_deletion_request_consented(uuid,int,boolean,boolean,bigint).\n--   account_deletion_request(uuid,int,boolean) / account_deletion_request_self(integer,boolean)\n--   / account_deletion_request_self_consented(integer,boolean,bigint) 은 전부 위 함수로\n--   위임하므로 **재정의 대상은 request_consented 하나**다.\n--\n-- 선행: 151, 154, 161, 175, 176, 177, 178.\n\nbegin", "set local lock_timeout=''5s''", "-- ── (a) 기존 NULL 행 backfill ────────────────────────────────────────────────\nupdate public.account_deletion_jobs\n   set consented_balance_cents = 0\n where consented_balance_cents is null", "-- ── (b) DEFAULT 0 + NOT NULL 승격 ───────────────────────────────────────────\nalter table public.account_deletion_jobs\n  alter column consented_balance_cents set default 0", "alter table public.account_deletion_jobs\n  alter column consented_balance_cents set not null", "comment on column public.account_deletion_jobs.consented_balance_cents is\n  ''179: 동의 당시 서버가 읽은 잔액(cents). NOT NULL — 잔액 0 요청은 0 을 명시 기록한다. ''\n  ''동의 \"행위\" 유무는 forfeit_consent_at 로만 판정한다(0 과 NULL 의 이중 표현 제거). ''\n  ''현재 잔액이 이 값보다 크면 FORFEIT_CONSENT_STALE.''", "-- ── (c) 잔액 0 경로가 NULL 을 방치하던 유일한 insert 함수 재정의 ─────────────\n-- 176 본문과의 차이는 잔액 0 분기 한 줄(v_consented := 0)뿐이다. 함수 본문 외 로직 변경 0.\ncreate or replace function public.account_deletion_request_consented(\n  p_user_id uuid,\n  p_cancelable_minutes int default 30,\n  p_dry_run boolean default true,\n  p_forfeit_consent boolean default false,\n  p_acknowledged_balance_cents bigint default null\n) returns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_id uuid; v_state text; v_latest uuid; v_latest_state text;\n  v_balance bigint; v_consent_at timestamptz; v_consented bigint;\nbegin\n  -- 활성 job 이 있으면 멱등 반환(중복 요청에도 동의 기록·원장 중복 0).\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is not null then\n    select j.state into v_state from public.account_deletion_jobs j where j.id = v_id;\n    return jsonb_build_object(''ok'',true,''existing'',true,''job_id'',v_id,''state'',v_state);\n  end if;\n\n  select j.id, j.state into v_latest, v_latest_state\n    from public.account_deletion_jobs j\n    where j.user_id = p_user_id\n    order by j.requested_at desc, j.id desc\n    limit 1;\n  if v_latest_state = ''completed'' then\n    return jsonb_build_object(''ok'',false,''code'',''ALREADY_COMPLETED'',''job_id'',v_latest,''state'',''completed'');\n  end if;\n\n  -- 잔액은 **서버가 읽는다**. 지갑 행이 없으면 0.\n  select coalesce(w.balance_cents, 0) into v_balance\n    from public.cash_wallets w where w.user_id = p_user_id;\n  v_balance := coalesce(v_balance, 0);\n\n  if v_balance > 0 then\n    if not coalesce(p_forfeit_consent, false) then\n      -- 1층: job 자체를 만들지 않는다.\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_REQUIRED'',''balance_cents'',v_balance);\n    end if;\n    if p_acknowledged_balance_cents is not null and p_acknowledged_balance_cents <> v_balance then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_STALE'',\n        ''acknowledged_balance_cents'', p_acknowledged_balance_cents, ''current_balance_cents'', v_balance);\n    end if;\n    v_consent_at := now();\n    v_consented := v_balance;\n  else\n    -- 잔액 0 사용자는 별도 몰수 동의 없이 진행한다.\n    -- 179: NULL 방치 금지 — 0 을 명시 기록한다. 동의 행위 없음은 forfeit_consent_at null 로만 표현.\n    v_consent_at := null;\n    v_consented := 0;\n  end if;\n\n  insert into public.account_deletion_jobs\n      (user_id, state, cancelable_until, dry_run, forfeit_consent_at, consented_balance_cents)\n    values (p_user_id, ''pending'',\n            now() + make_interval(mins => greatest(0, coalesce(p_cancelable_minutes,30))),\n            coalesce(p_dry_run,true), v_consent_at, v_consented)\n    returning id into v_id;\n\n  return jsonb_build_object(''ok'',true,''existing'',false,''job_id'',v_id,''state'',''pending'',\n                            ''forfeit_consent_at'', v_consent_at,\n                            ''consented_balance_cents'', v_consented);\nend $$", "-- ── (d) ACL 재확인 — create or replace 는 기존 ACL 을 보존하지만 명시로 고정한다 ──\nrevoke all on function public.account_deletion_request_consented(uuid,int,boolean,boolean,bigint) from public, anon, authenticated", "grant execute on function public.account_deletion_request_consented(uuid,int,boolean,boolean,bigint) to service_role", "comment on function public.account_deletion_request_consented(uuid,int,boolean,boolean,bigint) is\n  ''179: 탈퇴 요청 정본(유일한 job insert 경로). 잔액>0 은 서버가 읽은 금액으로 동의 박제, ''\n  ''잔액 0 은 consented_balance_cents=0 명시 기록(forfeit_consent_at 은 null). ''\n  ''기존 STALE·REQUIRED 가드의 coalesce(v_consented,0) 은 방어적 중복으로 176/175 정의에 그대로 남는다.''", "commit", "-- ── §V 검증(적용 후 실행) ────────────────────────────────────────────────────\n-- (1) information_schema.columns: consented_balance_cents is_nullable=''NO'', column_default=''0''\n-- (2) 잔액 0 사용자 request → job.consented_balance_cents = 0 (NULL 아님)\n-- (3) NULL 행 0: select count(*) from account_deletion_jobs where consented_balance_cents is null;\n-- (4) begin_locked / forfeit RPC 의 STALE·REQUIRED 가드는 176 정의(coalesce 유지)가 그대로 동작\n--\n-- ── ROLLBACK ────────────────────────────────────────────────────────────────\n--   alter table public.account_deletion_jobs alter column consented_balance_cents drop not null;\n--   alter table public.account_deletion_jobs alter column consented_balance_cents drop default;\n--   -- request_consented 는 176 원문 재적용으로 복원(backfill 된 0 은 되돌리지 않는다 — 정보 손실 없음:\n--   --  0 이던 NULL 행은 forfeit_consent_at null 로 구분 가능).\n\n-- >>> NATIVE_BASELINE_PART 0185 | supabase/sql/180_p1_10_account_deletion_forfeit_key_canon.sql | 180_p1_10_account_deletion_forfeit_key_canon.sql <<<\n-- 180_p1_10_account_deletion_forfeit_key_canon.sql\n-- ⚠️ 기능 플래그 OFF 기본 · worker kill switch OFF 고정. 실제 사용자·객체 삭제 없음.\n--    기존 SQL 175~179 파일은 **수정하지 않는다** — 여기서 재정의만 한다(W5-c §3-2).\n--\n-- W5-c §3-2: 몰수 멱등키 **정본 확정** + 레거시 키 이중 몰수 **구조적 차단**.\n--\n-- ── 정본(문서화) ─────────────────────────────────────────────────────────────\n--   멱등키 정본  acct_del_forfeit:{uid}\n--   reason 정본  account_deletion_forfeit\n--   레거시 키    forfeit_on_deletion:{uid} / reason forfeit_on_deletion\n--                — 웹 즉시 몰수 경로(64c4eb8 에서 폐지) 가 쓰던 키. 신규 발생 경로는 없다.\n--                기존 원장 행은 **소급 수정 0** (cash_ledger 는 append-only).\n--\n-- ── 왜 가드인가 ──────────────────────────────────────────────────────────────\n--   staging 은 양 키 0행 실측(2026-07-26 preflight 재확인)이지만 production 원장은\n--   아직 실측 전이다. 측정에 기대지 않고 **구조로** 이중 몰수를 0으로 만든다:\n--   과거 웹 즉시 경로가 이미 `forfeit_on_deletion:{uid}` 로 몰수한 사용자가 saga 로\n--   다시 들어오면, 정본 키 원장은 ON CONFLICT 에 걸리지 않으므로(키가 다르다) 같은\n--   지갑이 두 번 몰수될 수 있다. 그 분기를 insert **전에** fail-closed 로 끊는다.\n--\n-- ── 가드 계약 ────────────────────────────────────────────────────────────────\n--   잔액 > 0 분기에서 신규 원장 insert 전에 레거시 키 존재를 확인하고, 존재하면\n--   insert·지갑 차감·익명화 **모두 진행하지 않고**\n--     jsonb: ok=false, code=''LEGACY_FORFEIT_LEDGER_PRESENT'',\n--            current_balance_cents, legacy_idempotency_key\n--   를 반환한다. 운영자 검토 대상으로 record_error 를 남긴다(attempts·backoff 경유 —\n--   자동 재시도가 같은 코드로 반복 실패하면 175 계약대로 failed 로 넘어가 사람이 본다).\n--   잔액 = 0 이면 몰수 분기 자체에 진입하지 않으므로 가드 대상이 아니다(익명화는 진행).\n--\n-- 선행: 151, 154, 161, 175, 176, 177, 178, 179.\n\nbegin", "set local lock_timeout=''5s''", "-- ── 몰수 RPC 재정의 — 176 본문 + 잔액>0 분기의 레거시 키 가드 ────────────────\ncreate or replace function public.account_deletion_forfeit_and_anonymize(p_user_id uuid)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_id uuid; v_state text; v_balance bigint; v_ledger_id uuid;\n  v_consent_at timestamptz; v_consented bigint; v_legacy_key text;\nbegin\n  perform set_config(''ssambership.deletion_worker'', ''on'', true);\n\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is null then return jsonb_build_object(''ok'',false,''code'',''JOB_NOT_FOUND''); end if;\n  select j.state, j.forfeit_consent_at, j.consented_balance_cents\n    into v_state, v_consent_at, v_consented\n    from public.account_deletion_jobs j where j.id = v_id for update;\n  if v_state is null then return jsonb_build_object(''ok'',false,''code'',''JOB_NOT_FOUND''); end if;\n  if v_state <> ''storage_purged'' then\n    return jsonb_build_object(''ok'',false,''code'',''WRONG_STATE'',''state'',v_state);\n  end if;\n\n  select w.balance_cents into v_balance from public.cash_wallets w\n    where w.user_id = p_user_id for update;\n\n  if v_balance is not null and v_balance > 0 then\n    -- 3층 동의 재검증 — 여기까지 왔다는 건 2층을 통과했다는 뜻이지만, 그래도 다시 본다.\n    if v_consent_at is null then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_REQUIRED'',''current_balance_cents'',v_balance);\n    end if;\n    if v_balance > coalesce(v_consented, 0) then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_STALE'',\n        ''consented_balance_cents'', v_consented, ''current_balance_cents'', v_balance);\n    end if;\n\n    -- 180: 레거시 이중 몰수 가드 — 정본 키 insert 는 레거시 키와 충돌하지 않으므로\n    -- ON CONFLICT 멱등이 이 케이스를 잡지 못한다. insert 전에 fail-closed 로 끊는다.\n    v_legacy_key := ''forfeit_on_deletion:'' || p_user_id::text;\n    if exists (select 1 from public.cash_ledger l where l.idempotency_key = v_legacy_key) then\n      perform public.account_deletion_record_error(\n        p_user_id, ''LEGACY_FORFEIT_LEDGER_PRESENT: 운영자 검토 필요 — 레거시 몰수 원장 존재, 재몰수 차단'');\n      return jsonb_build_object(''ok'',false,''code'',''LEGACY_FORFEIT_LEDGER_PRESENT'',\n        ''current_balance_cents'', v_balance,\n        ''legacy_idempotency_key'', v_legacy_key);\n    end if;\n\n    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n    values (p_user_id, -v_balance, ''account_deletion_forfeit'', ''account_deletion'', p_user_id,\n            ''acct_del_forfeit:''||p_user_id::text)\n    on conflict (idempotency_key) do nothing\n    returning id into v_ledger_id;\n    if v_ledger_id is not null then\n      update public.cash_wallets set balance_cents = 0 where user_id = p_user_id;\n    end if;\n  end if;\n\n  perform public.anonymize_user_for_deletion(p_user_id, ''account_deletion'');\n  return jsonb_build_object(''ok'',true,''forfeited_cents'',coalesce(v_balance,0),''ledger_id'',v_ledger_id,''job_id'',v_id);\nend $$", "-- ── ACL 재확인 ───────────────────────────────────────────────────────────────\nrevoke all on function public.account_deletion_forfeit_and_anonymize(uuid) from public, anon, authenticated", "grant execute on function public.account_deletion_forfeit_and_anonymize(uuid) to service_role", "comment on function public.account_deletion_forfeit_and_anonymize(uuid) is\n  ''180: 몰수 멱등키 정본 acct_del_forfeit:{uid} / reason account_deletion_forfeit. ''\n  ''레거시 forfeit_on_deletion:{uid} 원장이 이미 있으면 잔액>0 분기를 ''\n  ''LEGACY_FORFEIT_LEDGER_PRESENT 로 fail-closed(원장 insert·지갑 차감·익명화 0, record_error). ''\n  ''잔액 0 은 가드 대상 아님 — 익명화 진행. 원장 행 소급 수정 0(append-only).''", "commit", "-- ── §V 검증(적용 후 실행) ────────────────────────────────────────────────────\n-- (1) 레거시 키 원장 + storage_purged + 잔액>0 → 몰수 RPC: 신규 원장 0행, 지갑 불변,\n--     익명화 미진행, code=LEGACY_FORFEIT_LEDGER_PRESENT, attempts +1 (record_error)\n-- (2) 레거시 없음 → 정본 키 정확히 1행 + 지갑 0. 재호출 멱등(원장 여전히 1행)\n-- (3) 레거시 존재 + 잔액 0 → ok=true, 몰수 분기 미진입(원장 신규 0행), 익명화 진행\n--\n-- ── ROLLBACK ────────────────────────────────────────────────────────────────\n--   -- 176 원문 재적용으로 forfeit_and_anonymize 를 복원(가드 제거). 데이터 변경 없음.\n\n-- >>> NATIVE_BASELINE_PART 0186 | supabase/sql/181_p1_10_account_deletion_storage_owner_refs.sql | 181_p1_10_account_deletion_storage_owner_refs.sql <<<\n-- 181_p1_10_account_deletion_storage_owner_refs.sql\n-- ⚠️ 기능 플래그 OFF 기본 · worker kill switch OFF 고정. 실제 사용자·객체 삭제 없음.\n--    기존 SQL 167~180 파일은 **수정하지 않는다** — 신규 함수 1개만 추가한다(W5-e E2).\n--\n-- W5-e E2: owner 증거 수집의 PGRST106 해소 — storage owner 전용 SECURITY DEFINER RPC.\n--\n-- ── 문제(W5-e §2-2 read-only 재현, staging lbeqxarxothkmzqvpudy, 2026-07-26) ──\n--   owner 증거 어댑터(`makeResolveObjectOwners`, accountDeletionAdapters.ts)가\n--   PostgREST 로 `storage` 스키마를 직접 조회한다(`admin.schema(\"storage\").from(\"objects\")`).\n--   staging 의 PostgREST 노출 스키마는 `public, graphql_public` 뿐이라 런타임에\n--     {\"code\":\"PGRST106\",\"message\":\"Invalid schema: storage\"}  (HTTP 406)\n--   → 어댑터는 설계대로 예외를 던지고 워커는 fail-closed 로 정지한다.\n--   (fail-closed 자체는 옳다 — 고칠 것은 \"소유 증거를 읽을 수단\"이다.)\n--\n-- ── 채택 ──────────────────────────────────────────────────────────────────────\n--   177(session revoke)·180(forfeit key canon)과 동일 패턴: public 스키마의\n--   SECURITY DEFINER 함수가 비노출 스키마를 대신 읽고, EXECUTE 는 service_role 로만\n--   좁힌다. PostgREST 는 public 스키마 RPC 로 호출하므로 PGRST106 이 구조적으로\n--   사라진다.\n--\n-- ── 캐스팅 근거(§2-1 information_schema 실측 — 추측 아님) ─────────────────────\n--   storage.objects.owner_id 의 실제 타입은 **text** 다(구 `owner` 컬럼이 uuid).\n--   따라서 비교는 `o.owner_id = p_user_id::text` 로 한다. p_user_id 가 null 이면\n--   비교가 unknown 이 되어 0행 — null 가드가 따로 필요 없다.\n--\n-- ── 반환 최소화(least exposure) ───────────────────────────────────────────────\n--   (bucket_id, name) 2컬럼만 반환한다. id·metadata·owner·user_metadata 등은\n--   워커 계획 산출에 불필요하며 반환하지 않는다.\n--\n-- 선행: 175, 176, 177, 178, 179, 180.\n\nbegin", "set local lock_timeout=''5s''", "create or replace function public.account_deletion_storage_owner_refs(p_user_id uuid)\nreturns table(bucket_id text, name text)\nlanguage sql\nstable\nsecurity definer\nset search_path to ''public''\nas $$\n  select o.bucket_id, o.name\n    from storage.objects o\n   where o.owner_id = p_user_id::text;\n$$", "comment on function public.account_deletion_storage_owner_refs(uuid) is\n  ''181: 계정 삭제 owner 증거 수집 — storage.objects 에서 owner_id = 대상 uid 인 객체의 ''\n  ''(bucket_id, name)만 반환. PostgREST 가 storage 스키마를 노출하지 않아(PGRST106) ''\n  ''public 스키마 SECURITY DEFINER RPC 로 대신 읽는다 — 177/180 과 동일 패턴. ''\n  ''owner_id 는 text 라 uuid 를 ::text 캐스팅해 비교한다(§2-1 실측). service_role 전용.''", "revoke all on function public.account_deletion_storage_owner_refs(uuid) from public, anon, authenticated", "grant execute on function public.account_deletion_storage_owner_refs(uuid) to service_role", "commit", "-- ── §V 검증(적용 후 실행 — T34~T36, 별도 begin; … rollback; 배치·mutation 0) ──\n-- T34 ACL: has_function_privilege(''anon''|''authenticated'', …, ''EXECUTE'') 전부 false\n--     (anon false 는 PUBLIC grant 부재까지 함의 — PUBLIC 경유 상속이 없다는 뜻).\n--     proacl 에 ''=X''(PUBLIC) 엔트리 없음 · service_role=X 만.\n-- T35 owner_id 보유 실사용자 1명의 uid 로 호출(set local role service_role)\n--     → 반환 행수 = select count(*) from storage.objects where owner_id = 그 uid::text\n-- T36 임의 신규 uuid → 0행 · pg_get_function_result = ''TABLE(bucket_id text, name text)''\n--\n-- ── ROLLBACK ────────────────────────────────────────────────────────────────\n--   drop function if exists public.account_deletion_storage_owner_refs(uuid);\n--   (추가형 단일 함수 — 되돌림 무손실. storage 스키마 객체는 일절 변경하지 않았다.)\n\n-- >>> NATIVE_BASELINE_PART 0187 | supabase/sql/182_p1_10_account_deletion_consent_locked_read.sql | 182_p1_10_account_deletion_consent_locked_read.sql <<<\n-- 182_p1_10_account_deletion_consent_locked_read.sql\n-- ⚠️ 기능 플래그 OFF 기본 · worker kill switch OFF 고정. 실제 사용자·객체 삭제 없음.\n--    기존 SQL 167~181 파일은 **수정하지 않는다** — request_consented 하나만 재정의한다(W5-e E3).\n--\n-- W5-e E3: 동의 스냅샷 FOR UPDATE 잠금 읽기 재정정.\n--\n-- ── 문제(W5-e §2-3 실측 — 이중 실행의 후퇴) ──────────────────────────────────\n--   01c 가 두 세션에서 실행되며 179 가 A·B 두 판본으로 갈라졌다.\n--   A라인(d12hk2)은 동의 잔액을 `cash_wallets ... FOR UPDATE` 로 잠그고 읽었으나,\n--   staging 에 나중에 적용된 B라인(cx52cq = 정본)은 무잠금 읽기다 — live prosrc 에\n--   ''for update'' 부재를 2026-07-26 재확인했다(179 파일 머리 주석은 \"FOR UPDATE 로 읽은\n--   잔액 기록\"이라 주장하지만 본문이 따르지 않는다). 무잠금이면 동의 스냅샷을 읽는\n--   순간과 job insert 사이에 충전 커밋이 끼어들 수 있고, 그 순간의 동의 금액은\n--   실잔액보다 작게 박제된다(begin_locked 의 STALE 가드가 2층에서 잡지만,\n--   1층 스냅샷 자체가 정확해야 한다는 것이 A라인 정정의 취지였다).\n--\n-- ── 조치 ──────────────────────────────────────────────────────────────────────\n--   account_deletion_request_consented(uuid,int,boolean,boolean,bigint) 재정의:\n--   (a) 동의 잔액을 public.cash_wallets 에서 FOR UPDATE 로 읽어 스냅샷 기록\n--       (지갑 행이 없으면 잠글 행도 없다 — v_balance null → 0. begin_locked 가 재검증).\n--   (b) 그 외 본문은 B본(179 재정의)과 동일 — 잔액 0 → v_consented := 0 명시 기록 포함.\n--   (c) begin_locked 등 다른 함수 변경 0. 이 파일은 이 함수 하나만 담는다.\n--\n-- 선행: 175, 176, 177, 178, 179, 180, 181.\n\nbegin", "set local lock_timeout=''5s''", "create or replace function public.account_deletion_request_consented(\n  p_user_id uuid,\n  p_cancelable_minutes int default 30,\n  p_dry_run boolean default true,\n  p_forfeit_consent boolean default false,\n  p_acknowledged_balance_cents bigint default null\n) returns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_id uuid; v_state text; v_latest uuid; v_latest_state text;\n  v_balance bigint; v_consent_at timestamptz; v_consented bigint;\nbegin\n  -- 활성 job 이 있으면 멱등 반환(중복 요청에도 동의 기록·원장 중복 0).\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is not null then\n    select j.state into v_state from public.account_deletion_jobs j where j.id = v_id;\n    return jsonb_build_object(''ok'',true,''existing'',true,''job_id'',v_id,''state'',v_state);\n  end if;\n\n  select j.id, j.state into v_latest, v_latest_state\n    from public.account_deletion_jobs j\n    where j.user_id = p_user_id\n    order by j.requested_at desc, j.id desc\n    limit 1;\n  if v_latest_state = ''completed'' then\n    return jsonb_build_object(''ok'',false,''code'',''ALREADY_COMPLETED'',''job_id'',v_latest,''state'',''completed'');\n  end if;\n\n  -- 잔액은 **서버가 잠그고 읽는다**(182: FOR UPDATE — 동의 스냅샷이 기록되는 트랜잭션과\n  -- 충전 커밋이 서로 끼어들지 못한다. A라인 정정의 정본 이식). 지갑 행이 없으면 0.\n  select coalesce(w.balance_cents, 0) into v_balance\n    from public.cash_wallets w where w.user_id = p_user_id for update;\n  v_balance := coalesce(v_balance, 0);\n\n  if v_balance > 0 then\n    if not coalesce(p_forfeit_consent, false) then\n      -- 1층: job 자체를 만들지 않는다.\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_REQUIRED'',''balance_cents'',v_balance);\n    end if;\n    if p_acknowledged_balance_cents is not null and p_acknowledged_balance_cents <> v_balance then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_STALE'',\n        ''acknowledged_balance_cents'', p_acknowledged_balance_cents, ''current_balance_cents'', v_balance);\n    end if;\n    v_consent_at := now();\n    v_consented := v_balance;\n  else\n    -- 잔액 0 사용자는 별도 몰수 동의 없이 진행한다.\n    -- 179: NULL 방치 금지 — 0 을 명시 기록한다. 동의 행위 없음은 forfeit_consent_at null 로만 표현.\n    v_consent_at := null;\n    v_consented := 0;\n  end if;\n\n  insert into public.account_deletion_jobs\n      (user_id, state, cancelable_until, dry_run, forfeit_consent_at, consented_balance_cents)\n    values (p_user_id, ''pending'',\n            now() + make_interval(mins => greatest(0, coalesce(p_cancelable_minutes,30))),\n            coalesce(p_dry_run,true), v_consent_at, v_consented)\n    returning id into v_id;\n\n  return jsonb_build_object(''ok'',true,''existing'',false,''job_id'',v_id,''state'',''pending'',\n                            ''forfeit_consent_at'', v_consent_at,\n                            ''consented_balance_cents'', v_consented);\nend $$", "-- ACL 재확인 — create or replace 는 기존 ACL 을 보존하지만 명시로 고정한다(179 와 동일).\nrevoke all on function public.account_deletion_request_consented(uuid,int,boolean,boolean,bigint) from public, anon, authenticated", "grant execute on function public.account_deletion_request_consented(uuid,int,boolean,boolean,bigint) to service_role", "comment on function public.account_deletion_request_consented(uuid,int,boolean,boolean,bigint) is\n  ''182: 동의 스냅샷은 잠금 읽기(cash_wallets FOR UPDATE) — A라인 정정의 정본 이식. ''\n  ''그 외 본문은 179(B본)와 동일: 유일한 job insert 경로 · 잔액>0 은 서버가 잠그고 읽은 ''\n  ''금액으로 동의 박제 · 잔액 0 은 consented_balance_cents=0 명시 기록(forfeit_consent_at 은 null).''", "commit", "-- ── §V 검증(적용 후 실행 — T37~T39, 별도 begin; … rollback; 배치) ─────────────\n-- T37 pg_proc prosrc 에 ''for update'' 존재 (재정의 반영 확인)\n-- T38 T27 재실행 — 잔액 0 job 생성 → consented_balance_cents = 0 (NULL 아님)\n-- T39 T28b 재실행 — 동의 100 기록 → 충전 200 → begin_locked FORFEIT_CONSENT_STALE · pending 유지\n--\n-- ── ROLLBACK ────────────────────────────────────────────────────────────────\n--   179 (c) 절의 함수 정의 재적용(무잠금 읽기로 복귀 — 권장하지 않음).\n--   컬럼·다른 함수는 일절 변경하지 않았다.\n\n-- >>> NATIVE_BASELINE_PART 0188 | supabase/sql/183_p1_10_account_deletion_verify_object_owners.sql | 183_p1_10_account_deletion_verify_object_owners.sql <<<\n-- 183_p1_10_account_deletion_verify_object_owners.sql\n-- ⚠️ 기능 플래그 OFF 기본 · worker kill switch OFF 고정. 실제 사용자·객체 삭제 없음.\n--    기존 SQL 167~182 파일은 **수정하지 않는다** — 신규 함수 1개만 추가한다(W5-f F1).\n--\n-- W5-f F1: OWNERSHIP_CONFLICT 감지 복원 — 익명 owner verdict RPC.\n--\n-- ── 문제(W5-e E2 의 의미 후퇴 — 지시서 스펙 결함으로 판정) ──────────────────\n--   181 `account_deletion_storage_owner_refs` 는 **대상 uid 소유 객체만** 반환한다\n--   (least-exposure 는 옳았으나 owner 축이 그것뿐이면 관측이 부족하다).\n--   그 결과 owners 맵에 타인-owner 값이 실리지 않아, DB 조인 ref 의 타인-owner\n--   이상치가 OWNERSHIP_CONFLICT 차단 대신 \"owner 미기록 레거시\"와 구분되지 않고\n--   정상 삭제 대상으로 수렴했다(과삭제 위험 — 미삭제보다 나쁘다).\n--\n-- ── 채택 ──────────────────────────────────────────────────────────────────────\n--   177/180/181 동일 패턴의 SECURITY DEFINER RPC 를 하나 더 둔다. 워커가 수집한\n--   ref 목록(jsonb)을 받아 객체별 소유 상태를 **3값의 사실로만** 알린다:\n--     ''target'' — owner_id = 대상 uid           → 정상 삭제 대상\n--     ''other''  — owner_id 존재·대상 아님        → OWNERSHIP_CONFLICT (차단)\n--     ''none''   — 행 부재 또는 owner_id 미기록   → 현행 정상 삭제 경로 유지\n--   ''other'' 는 사실만 알린다 — **타인 owner 의 uid·값은 어떤 형태로도 반환·로그하지\n--   않는다**(반환 컬럼에 owner 계열 없음 · 예외 메시지에도 싣지 않는다).\n--\n-- ── 캐스팅 근거(181 §2-1 information_schema 실측과 동일) ─────────────────────\n--   storage.objects.owner_id 의 실제 타입은 **text** 다(구 `owner` 컬럼이 uuid).\n--   따라서 비교는 `o.owner_id = p_user_id::text` 로 한다 — 181 과 동일.\n--\n-- ── 방어 상한 ────────────────────────────────────────────────────────────────\n--   p_refs 배열 5,000 초과 시 예외. 호출측(어댑터)은 500 단위로 배치한다\n--   (DB_PAGE_SIZE 와 동일 — staging 전체 객체 84 로 현행 1배치).\n--\n-- 선행: 175, 176, 177, 178, 179, 180, 181, 182. (172 는 영구 결번)\n\nbegin", "set local lock_timeout=''5s''", "create or replace function public.account_deletion_verify_object_owners(p_user_id uuid, p_refs jsonb)\nreturns table(bucket_id text, name text, owner_state text)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path to ''public''\nas $$\nbegin\n  if p_user_id is null then\n    raise exception ''account_deletion_verify_object_owners: p_user_id is required'';\n  end if;\n  if p_refs is null or jsonb_typeof(p_refs) <> ''array'' then\n    raise exception ''account_deletion_verify_object_owners: p_refs must be a jsonb array'';\n  end if;\n  if jsonb_array_length(p_refs) > 5000 then\n    raise exception ''account_deletion_verify_object_owners: p_refs exceeds 5000 (got %)'',\n      jsonb_array_length(p_refs);\n  end if;\n\n  return query\n    select r.bucket_id,\n           r.name,\n           case\n             when o.name is null or o.owner_id is null then ''none''\n             when o.owner_id = p_user_id::text then ''target''\n             else ''other''\n           end as owner_state\n      from jsonb_to_recordset(p_refs) as r(bucket_id text, name text)\n      left join storage.objects o\n        on o.bucket_id = r.bucket_id and o.name = r.name\n     where r.bucket_id is not null and r.name is not null;\nend;\n$$", "comment on function public.account_deletion_verify_object_owners(uuid, jsonb) is\n  ''183: OWNERSHIP_CONFLICT 감지 복원 — 181 최소반환의 의미 후퇴 정정. 수집 ref 의 ''\n  ''storage.objects 소유 상태를 target/other/none 3값의 사실로만 반환한다 — 타인 owner ''\n  ''uid·값은 어떤 형태로도 반환·로그하지 않는다. owner_id 는 text 라 ::text 비교(181 동일). ''\n  ''배열 상한 5,000. service_role 전용.''", "revoke all on function public.account_deletion_verify_object_owners(uuid, jsonb) from public, anon, authenticated", "grant execute on function public.account_deletion_verify_object_owners(uuid, jsonb) to service_role", "commit", "-- ── §V 검증(적용 후 실행 — T40~T43, 공격 테스트는 별도 begin; … rollback; 배치) ──\n-- T40 ACL: has_function_privilege PUBLIC·anon·authenticated false · service_role true.\n--     proacl 에 ''=X''(PUBLIC) 엔트리 없음.\n-- T41 실데이터 배치(read-only): 최다 소유자(61객체) 소유 ref → ''target'' ·\n--     null-owner ref(individual-question-attachments) → ''none''.\n-- T42 rollback 배치에서 타 uid 소유 fixture 객체 1행을 storage.objects 에 심고 검증\n--     → ''other'' (uid 값은 결과에 없음) · TS 분류 계약 테스트로 워커 차단 고정.\n-- T43 상한 초과(5,001행) → 예외.\n--\n-- ── ROLLBACK ────────────────────────────────────────────────────────────────\n--   drop function if exists public.account_deletion_verify_object_owners(uuid, jsonb);\n--   (추가형 단일 함수 — 되돌림 무손실. storage 스키마 객체는 일절 변경하지 않았다.)"], "idempotency_key": null}, {"name": "add_users_notification_enabled", "version": "20260702065122", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["alter table public.users\n  add column if not exists notification_enabled boolean not null default true;"], "idempotency_key": null}, {"name": "create_connection_note_ink_bucket_and_policies", "version": "20260702083003", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- 연결노트 필기 저장용 버킷 (비공개) — scan-annotations와 동일한 방 참여자 정책 패턴\ninsert into storage.buckets (id, name, public)\nvalues (''connection-note-ink'', ''connection-note-ink'', false)\non conflict (id) do nothing;\n\ncreate policy connection_note_ink_obj_insert\non storage.objects for insert to authenticated\nwith check (\n  bucket_id = ''connection-note-ink''\n  and exists (\n    select 1 from mentor_student_rooms r\n    where r.id = ((storage.foldername(objects.name))[1])::uuid\n      and ((select auth.uid()) = r.student_id or (select auth.uid()) = r.mentor_id)\n  )\n);\n\ncreate policy connection_note_ink_obj_select\non storage.objects for select to authenticated\nusing (\n  bucket_id = ''connection-note-ink''\n  and exists (\n    select 1 from mentor_student_rooms r\n    where r.id = ((storage.foldername(objects.name))[1])::uuid\n      and ((select auth.uid()) = r.student_id or (select auth.uid()) = r.mentor_id)\n  )\n);\n\ncreate policy connection_note_ink_obj_update\non storage.objects for update to authenticated\nusing (\n  bucket_id = ''connection-note-ink''\n  and exists (\n    select 1 from mentor_student_rooms r\n    where r.id = ((storage.foldername(objects.name))[1])::uuid\n      and ((select auth.uid()) = r.student_id or (select auth.uid()) = r.mentor_id)\n  )\n)\nwith check (\n  bucket_id = ''connection-note-ink''\n  and exists (\n    select 1 from mentor_student_rooms r\n    where r.id = ((storage.foldername(objects.name))[1])::uuid\n      and ((select auth.uid()) = r.student_id or (select auth.uid()) = r.mentor_id)\n  )\n);"], "idempotency_key": null}, {"name": "add_ink_columns_to_connection_notes", "version": "20260702083017", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- 연결노트 필기 참조 컬럼 (기획서 5-1: 필기 JSON 위치 + 목록용 썸네일 위치)\n-- nullable — 기존 행·기존 웹 코드 무영향. 필기 존재 여부는 ink_path is not null 로 판정.\nalter table public.connection_notes\n  add column if not exists ink_path text,\n  add column if not exists ink_thumb_path text;\n\ncomment on column public.connection_notes.ink_path is\n  ''필기 원본(잉크 문서 JSON)의 Storage 경로. 버킷 connection-note-ink, 경로 첫 세그먼트는 room id'';\ncomment on column public.connection_notes.ink_thumb_path is\n  ''목록 표시용 필기 썸네일 PNG의 Storage 경로 (원본과 분리 저장)'';"], "idempotency_key": null}, {"name": "mentor_directory_v2_add_photo_highschool", "version": "20260703043452", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- B안: 공개 멘토 프로필 RPC에 안전 컬럼 2개(프로필 사진, 출신 고교)만 추가.\n-- PII(student_id_image_url)·정산 계좌(payout_*)는 계속 제외. 학번/태그는 원본 컬럼 없음.\ndrop function if exists public.mentor_profiles_for_directory_v2(uuid[]);\n\ncreate or replace function public.mentor_profiles_for_directory_v2(p_ids uuid[])\nreturns table (\n  user_id uuid,\n  university_name text,\n  department_name text,\n  teaching_subjects text[],\n  intro_line text,\n  verification_status text,\n  created_at timestamptz,\n  verified_university_name text,\n  verified_department_name text,\n  verified_major_category text,\n  school_tier text,\n  school_verified boolean,\n  high_school_name text,\n  profile_image_url text\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select\n    mp.user_id,\n    mp.university_name,\n    mp.department_name,\n    mp.teaching_subjects,\n    mp.intro_line,\n    mp.verification_status,\n    mp.created_at,\n    sv.verified_university_name,\n    sv.verified_department_name,\n    sv.verified_major_category,\n    sv.school_tier,\n    (sv.mentor_id is not null) as school_verified,\n    mp.high_school_name,\n    mp.profile_image_url\n  from public.mentor_profiles mp\n  left join lateral (\n    select\n      msv.mentor_id,\n      msv.verified_university_name,\n      msv.verified_department_name,\n      msv.verified_major_category,\n      msv.school_tier\n    from public.mentor_school_verifications msv\n    where msv.mentor_id = mp.user_id\n      and msv.status = ''approved''\n    order by coalesce(msv.reviewed_at, msv.updated_at, msv.created_at) desc, msv.created_at desc\n    limit 1\n  ) sv on true\n  where p_ids is not null\n    and array_length(p_ids, 1) is not null\n    and mp.user_id = any (p_ids);\n$$;\n\nrevoke all on function public.mentor_profiles_for_directory_v2(uuid[]) from public;\ngrant execute on function public.mentor_profiles_for_directory_v2(uuid[]) to anon, authenticated;\n\ncomment on function public.mentor_profiles_for_directory_v2(uuid[]) is\n  ''P0 public mentor directory whitelist (+ profile photo, high school). Excludes PII, consent, payout, and document paths.'';"], "idempotency_key": null}, {"name": "iq_open_list_filter_by_mentor_subjects", "version": "20260703083609", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["CREATE OR REPLACE FUNCTION public.list_open_individual_questions_for_mentor(p_limit integer DEFAULT 50)\n RETURNS TABLE(id uuid, subject text, topic text, title text, price_cents integer, expires_at timestamp with time zone, created_at timestamp with time zone)\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);\n  v_subjects text[];\nbegin\n  if not public.individual_question_user_is_approved_mentor((select auth.uid())) then\n    return;\n  end if;\n\n  -- 멘토 담당 과목(teaching_subjects)만 노출. 과목 없는(null) 질문은 일반 질문으로 모두에게 노출.\n  select mp.teaching_subjects into v_subjects\n  from public.mentor_profiles mp\n  where mp.user_id = (select auth.uid());\n\n  return query\n    select\n      q.id,\n      q.subject,\n      q.topic,\n      q.title,\n      q.price_cents,\n      q.expires_at,\n      q.created_at\n    from public.individual_questions q\n    where q.question_type = ''open''\n      and q.status = ''open''\n      and q.claimed_mentor_id is null\n      and (q.expires_at is null or q.expires_at > now())\n      and (q.subject is null or q.subject = any(coalesce(v_subjects, array[]::text[])))\n    order by q.created_at desc\n    limit v_limit;\nend;\n$function$;"], "idempotency_key": null}, {"name": "iq_claim_gate_by_mentor_subject", "version": "20260703083637", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["CREATE OR REPLACE FUNCTION public.claim_individual_question_v2(p_question_id uuid, p_mentor_id uuid)\n RETURNS individual_question_escrow_result\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_question public.individual_questions%rowtype;\n  v_required_school_tier text;\n  v_required_major_category text;\n  v_verified_school_tier text;\n  v_verified_major_category text;\n  v_question_subject text;\n  v_mentor_subjects text[];\nbegin\n  if p_question_id is null or p_mentor_id is null then\n    return (false, ''invalid_input'', ''question_id and mentor_id are required'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  if not public.individual_question_user_is_approved_mentor(p_mentor_id) then\n    return (false, ''mentor_not_approved'', ''mentor is not approved for individual questions'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  select\n    q.required_school_tier,\n    q.required_major_category,\n    q.subject\n    into v_required_school_tier, v_required_major_category, v_question_subject\n  from public.individual_questions q\n  where q.id = p_question_id\n    and q.question_type = ''open''\n    and q.status = ''open''\n    and q.claimed_mentor_id is null\n    and (q.expires_at is null or q.expires_at > now())\n    and q.student_id <> p_mentor_id;\n\n  if not found then\n    return (false, ''not_available'', ''question is already claimed, expired, or unavailable'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  -- [과목 게이트] 멘토 담당 과목(teaching_subjects)이 아닌 질문은 맡을 수 없다. 과목 없는(null) 질문은 허용.\n  if v_question_subject is not null then\n    select mp.teaching_subjects into v_mentor_subjects\n    from public.mentor_profiles mp\n    where mp.user_id = p_mentor_id;\n\n    if not (v_question_subject = any(coalesce(v_mentor_subjects, array[]::text[]))) then\n      return (false, ''mentor_subject_not_met'', ''mentor does not teach this subject'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n    end if;\n  end if;\n\n  if v_required_school_tier is not null or v_required_major_category is not null then\n    select\n      msv.school_tier,\n      msv.verified_major_category\n      into v_verified_school_tier, v_verified_major_category\n    from public.mentor_school_verifications msv\n    where msv.mentor_id = p_mentor_id\n      and msv.status = ''approved''\n    order by coalesce(msv.reviewed_at, msv.updated_at, msv.created_at) desc, msv.created_at desc\n    limit 1;\n\n    if not found then\n      return (false, ''mentor_school_verification_required'', ''mentor school verification is required for this question'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n    end if;\n\n    if v_required_school_tier is not null\n       and coalesce(v_verified_school_tier, '''') <> v_required_school_tier then\n      return (false, ''mentor_qualification_not_met'', ''mentor school tier does not match this question requirement'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n    end if;\n\n    if v_required_major_category is not null\n       and coalesce(v_verified_major_category, '''') <> v_required_major_category then\n      return (false, ''mentor_qualification_not_met'', ''mentor major category does not match this question requirement'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n    end if;\n  end if;\n\n  update public.individual_questions\n  set\n    claimed_mentor_id = p_mentor_id,\n    claimed_at = now(),\n    status = ''claimed''\n  where id = p_question_id\n    and question_type = ''open''\n    and status = ''open''\n    and claimed_mentor_id is null\n    and (expires_at is null or expires_at > now())\n    and student_id <> p_mentor_id\n  returning * into v_question;\n\n  if not found then\n    return (false, ''not_available'', ''question is already claimed, expired, or unavailable'', p_question_id, null, null, null)::public.individual_question_escrow_result;\n  end if;\n\n  return (true, ''claimed'', ''individual question claimed'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\nend;\n$function$;"], "idempotency_key": null}, {"name": "116_user_blocks", "version": "20260704135524", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 116_user_blocks.sql\n-- 적용: 2026-07-04 (플래그 NEXT_PUBLIC_FEATURE_USER_BLOCKS ON 배포와 동시)\n-- =============================================================================\n-- 목적(스펙 docs/plans/user-blocks-spec.md): 사용자간 차단 — Google Play UGC 정책\n-- (신고+차단 병존) 대응. 공유 DB이므로 앱·웹이 같은 목록을 사용한다.\n-- 차단 = 노출 필터(차단한 사람의 뷰에만 적용). 상대 기능 제한 아님.\n-- 신규 객체만 추가 — 기존 RLS/테이블 무수정. v1 적용 범위 = 커뮤니티 UGC.\n-- =============================================================================\n\ncreate table if not exists public.user_blocks (\n  blocker_id uuid not null references public.users (id) on delete cascade,\n  blocked_id uuid not null references public.users (id) on delete cascade,\n  created_at timestamptz not null default now(),\n  primary key (blocker_id, blocked_id),\n  check (blocker_id <> blocked_id)\n);\n\ncreate index if not exists idx_user_blocks_blocker on public.user_blocks (blocker_id);\n\ncomment on table public.user_blocks is\n  ''116: 사용자 차단(노출 필터). blocker의 뷰에서 blocked의 커뮤니티 UGC를 숨긴다. 불변 쌍(UPDATE 정책 없음).'';\n\nalter table public.user_blocks enable row level security;\n\ndrop policy if exists ub_select_own on public.user_blocks;\ncreate policy ub_select_own\n  on public.user_blocks for select\n  to authenticated\n  using (blocker_id = (select auth.uid()));\n\ndrop policy if exists ub_insert_own on public.user_blocks;\ncreate policy ub_insert_own\n  on public.user_blocks for insert\n  to authenticated\n  with check (blocker_id = (select auth.uid()));\n\ndrop policy if exists ub_delete_own on public.user_blocks;\ncreate policy ub_delete_own\n  on public.user_blocks for delete\n  to authenticated\n  using (blocker_id = (select auth.uid()));\n\ndrop policy if exists ub_select_admin on public.user_blocks;\ncreate policy ub_select_admin\n  on public.user_blocks for select\n  to authenticated\n  using (public.is_admin());"], "idempotency_key": null}, {"name": "102_account_status_management", "version": "20260704135705", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- 102_account_status_management.sql\n-- P0 #4 — 계정 상태 관리(active / suspended / banned)\n-- (레포 원문 그대로 — 2026-07-04 라이브 드리프트 보완 적용: 어드민 정지/차단 및 115 선행)\n\nalter table public.users\n  add column if not exists suspended_until timestamptz,\n  add column if not exists status_reason text,\n  add column if not exists status_changed_at timestamptz,\n  add column if not exists status_changed_by uuid references public.users (id) on delete set null;\n\ncomment on column public.users.suspended_until is ''정지 만료 시각(suspended 전용). null=영구/미설정. 이 시각 이후 앱 가드가 active로 간주'';\ncomment on column public.users.status_reason is ''정지/차단 사유(관리자 기록)'';\ncomment on column public.users.status_changed_at is ''상태 마지막 변경 시각'';\ncomment on column public.users.status_changed_by is ''상태를 변경한 관리자 user id'';\n\ncreate index if not exists users_status_blocked_idx\n  on public.users (status, suspended_until)\n  where status <> ''active'';"], "idempotency_key": null}, {"name": "115_account_deletion", "version": "20260704135803", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 115_account_deletion.sql (레포 원문 — 적용: 2026-07-04, 선행 102 적용 완료)\n-- =============================================================================\n\n-- ① 감사 로그 — service_role 전용\ncreate table if not exists public.user_deletion_log (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null unique references public.users (id),\n  requested_at timestamptz not null default now(),\n  reason text null,\n  snapshot jsonb not null default ''{}''::jsonb\n);\n\ncomment on table public.user_deletion_log is\n  ''115: 계정 삭제(익명화) 감사 로그. user_id unique = RPC 멱등 기준. snapshot은 비-PII 메타만.'';\n\nalter table public.user_deletion_log enable row level security;\nrevoke all on public.user_deletion_log from public, anon, authenticated;\n\n-- ② 익명화 RPC — service_role 전용\ncreate or replace function public.anonymize_user_for_deletion(\n  p_user_id uuid,\n  p_reason text default null\n)\nreturns table (already_deleted boolean, anonymized boolean)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_user public.users%rowtype;\n  v_has_mentor_profile boolean;\nbegin\n  select * into v_user from public.users where id = p_user_id;\n  if not found then\n    raise exception ''anonymize_user_for_deletion: user % not found'', p_user_id;\n  end if;\n\n  if exists (select 1 from public.user_deletion_log l where l.user_id = p_user_id)\n     or lower(coalesce(v_user.status, '''')) = ''deleted'' then\n    return query select true, false;\n    return;\n  end if;\n\n  select exists (select 1 from public.mentor_profiles mp where mp.user_id = p_user_id)\n    into v_has_mentor_profile;\n\n  -- users PII 익명화 (스펙 §1-2; email은 nullable 실측 → null)\n  update public.users\n  set full_name = ''탈퇴회원'',\n      nickname = ''탈퇴회원_'' || left(p_user_id::text, 8),\n      email = null,\n      grade_level = null,\n      student_status = null,\n      birth_date = null,\n      status = ''deleted'',\n      status_reason = coalesce(p_reason, ''user_requested_deletion''),\n      status_changed_at = now(),\n      updated_at = now()\n  where id = p_user_id;\n\n  -- mentor_profiles PII 익명화 (존재 시; NOT NULL 컬럼은 익명 문구, nullable은 null)\n  if v_has_mentor_profile then\n    update public.mentor_profiles\n    set university_name = ''(삭제됨)'',\n        department_name = ''(삭제됨)'',\n        high_school_name = ''(삭제됨)'',\n        teaching_subjects = ''{}''::text[],\n        intro_line = null,\n        answer_style = null,\n        student_id_image_url = null,\n        profile_image_url = null,\n        payout_bank_name = null,\n        payout_account_number = null,\n        updated_at = now()\n    where user_id = p_user_id;\n  end if;\n\n  -- 감사 로그 (snapshot은 비-PII 메타만 — PII 보관 시 익명화 취지 훼손)\n  insert into public.user_deletion_log (user_id, reason, snapshot)\n  values (\n    p_user_id,\n    p_reason,\n    jsonb_build_object(''role'', v_user.role, ''had_mentor_profile'', v_has_mentor_profile)\n  )\n  on conflict (user_id) do nothing;\n\n  return query select false, true;\nend;\n$function$;\n\ncomment on function public.anonymize_user_for_deletion(uuid, text) is\n  ''115: 계정 삭제 — users/mentor_profiles PII 익명화 + status=deleted + 감사 로그. 멱등(user_deletion_log unique). service_role 전용. 적용: 2026-07-04.'';\n\nrevoke all on function public.anonymize_user_for_deletion(uuid, text) from public, anon, authenticated;\ngrant execute on function public.anonymize_user_for_deletion(uuid, text) to service_role;"], "idempotency_key": null}, {"name": "add_iq_attachment_rpc_s17", "version": "20260707103325", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- S17: 개별질문 첨부 등록 RPC (PR #19 초안 — 사람 승인 후 적용)\ncreate or replace function public.add_individual_question_attachment(\n  p_question_id uuid,\n  p_storage_path text,\n  p_file_name text,\n  p_mime_type text,\n  p_message_id uuid default null\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_id uuid;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  if coalesce(btrim(p_storage_path), '''') = '''' then\n    raise exception ''INVALID_INPUT: storage_path is required'' using errcode = ''22023'';\n  end if;\n\n  -- 당사자(질문 학생 또는 배정 멘토)만 등록 가능.\n  if not public.user_is_individual_question_party(p_question_id) then\n    raise exception ''NOT_QUESTION_PARTY'' using errcode = ''42501'';\n  end if;\n\n  -- 경로 위조 차단: 첫 세그먼트가 이 질문의 uuid 가 아니면 거부.\n  if split_part(p_storage_path, ''/'', 1) <> p_question_id::text then\n    raise exception ''STORAGE_PATH_MISMATCH'' using errcode = ''22023'';\n  end if;\n\n  insert into public.individual_question_attachments\n    (question_id, message_id, storage_path, file_name, mime_type)\n  values\n    (p_question_id, p_message_id, p_storage_path, p_file_name, p_mime_type)\n  returning id into v_id;\n\n  return v_id;\nend;\n$function$;\n\nrevoke all on function public.add_individual_question_attachment(uuid, text, text, text, uuid) from public;\nrevoke all on function public.add_individual_question_attachment(uuid, text, text, text, uuid) from anon;\ngrant execute on function public.add_individual_question_attachment(uuid, text, text, text, uuid) to authenticated;"], "idempotency_key": null}, {"name": "add_iqa_storage_update_policy_annotations_s18", "version": "20260707115017", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- S18: 개별질문 첨삭 ink.json 재저장(upsert=UPDATE)용 스토리지 정책\n-- 스코프: annotations/ 프리픽스 한정 — 원본 첨부 덮어쓰기는 계속 불가(원본 불변 규약).\ncreate policy iqa_storage_update_party_annotations on storage.objects\n  for update to authenticated\n  using (\n    bucket_id = ''individual-question-attachments''\n    and split_part(name, ''/'', 2) = ''annotations''\n    and public.user_is_party_for_individual_question_storage_path(name)\n  )\n  with check (\n    bucket_id = ''individual-question-attachments''\n    and split_part(name, ''/'', 2) = ''annotations''\n    and public.user_is_party_for_individual_question_storage_path(name)\n  );"], "idempotency_key": null}, {"name": "iqa_rpc_message_id_check_v2", "version": "20260707205436", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- S19: add_individual_question_attachment v2 — p_message_id 소속 질문 검증 추가\n-- (앱 레포 supabase/migrations/20260707T1500_iqa_rpc_message_id_check.sql 과 동일 본문)\n\ncreate or replace function public.add_individual_question_attachment(\n  p_question_id uuid,\n  p_storage_path text,\n  p_file_name text,\n  p_mime_type text,\n  p_message_id uuid default null\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_id uuid;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  if coalesce(btrim(p_storage_path), '''') = '''' then\n    raise exception ''INVALID_INPUT: storage_path is required'' using errcode = ''22023'';\n  end if;\n\n  -- 당사자(질문 학생 또는 배정 멘토)만 등록 가능.\n  if not public.user_is_individual_question_party(p_question_id) then\n    raise exception ''NOT_QUESTION_PARTY'' using errcode = ''42501'';\n  end if;\n\n  -- 경로 위조 차단: 첫 세그먼트가 이 질문의 uuid 가 아니면 거부\n  -- (남의 질문 파일 경로를 내 질문 행으로 등록하는 것을 막는다).\n  if split_part(p_storage_path, ''/'', 1) <> p_question_id::text then\n    raise exception ''STORAGE_PATH_MISMATCH'' using errcode = ''22023'';\n  end if;\n\n  -- 메시지 소속 검증(v2): 다른 질문의 메시지를 이 질문의 첨부로 묶는 것을 막는다\n  -- (individual_question_attachments 에 (message_id, question_id) 복합 FK 부재 보완).\n  if p_message_id is not null and not exists (\n    select 1\n    from public.individual_question_messages m\n    where m.id = p_message_id\n      and m.question_id = p_question_id\n  ) then\n    raise exception ''MESSAGE_NOT_IN_QUESTION'' using errcode = ''22023'';\n  end if;\n\n  insert into public.individual_question_attachments\n    (question_id, message_id, storage_path, file_name, mime_type)\n  values\n    (p_question_id, p_message_id, p_storage_path, p_file_name, p_mime_type)\n  returning id into v_id;\n\n  return v_id;\nend;\n$function$;\n\nrevoke all on function public.add_individual_question_attachment(uuid, text, text, text, uuid) from public;\nrevoke all on function public.add_individual_question_attachment(uuid, text, text, text, uuid) from anon;\ngrant execute on function public.add_individual_question_attachment(uuid, text, text, text, uuid) to authenticated;"], "idempotency_key": null}, {"name": "iqa_bucket_allow_application_json", "version": "20260707205504", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- S19: individual-question-attachments 버킷 mime 화이트리스트에 application/json 1개 추가\n-- (앱 레포 supabase/migrations/20260707T1510_iqa_bucket_allow_application_json.sql 과 동일 본문)\n\nupdate storage.buckets\nset allowed_mime_types = allowed_mime_types || array[''application/json'']\nwhere id = ''individual-question-attachments''\n  and allowed_mime_types is not null\n  and not (''application/json'' = any(allowed_mime_types));"], "idempotency_key": null}, {"name": "103_mentor_activity_suspension", "version": "20260712051239", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- 103_mentor_activity_suspension.sql\n-- P0 #5 — 멘토 활동 중단 대안(완전 종료 / 일시 중단 / 무단 이탈)\n-- 운영 적용 대상: 예(컬럼 추가 + 신규 테이블, 파괴적 변경 없음).\n\n-- 1) mentor_profiles 활동 상태 컬럼\nalter table public.mentor_profiles\n  add column if not exists activity_status text not null default ''active'',\n  add column if not exists termination_requested_at timestamptz,\n  add column if not exists termination_effective_at timestamptz,\n  add column if not exists pause_started_at timestamptz,\n  add column if not exists pause_until timestamptz,\n  add column if not exists pause_reason text,\n  add column if not exists last_pause_at timestamptz,\n  add column if not exists abandonment_flagged_at timestamptz;\n\ncomment on column public.mentor_profiles.activity_status is ''active | terminating(2주 공지중) | terminated | paused'';\ncomment on column public.mentor_profiles.termination_effective_at is ''완전종료 유예 만료(요청+14일). 이후 잔여 환불 생성 대상'';\ncomment on column public.mentor_profiles.pause_until is ''일시중단 복귀 예정 시각(최대 +7일)'';\ncomment on column public.mentor_profiles.last_pause_at is ''마지막 일반휴식 시각(6개월 빈도 제한 판정)'';\ncomment on column public.mentor_profiles.abandonment_flagged_at is ''무단이탈 의심 플래그 시각'';\n\n-- 2) mentor_plans 비활성 플래그(중단 시 신규 노출 차단용 소프트 플래그)\nalter table public.mentor_plans\n  add column if not exists is_active boolean not null default true;\n\ncomment on column public.mentor_plans.is_active is ''멘토 활동 중단 시 false. 신규 구독 노출/허용 게이트(가격 계산값은 보존)'';\n\n-- 3) 멘토 활동 이벤트(관리자 검토 큐 + 감사)\ncreate table if not exists public.mentor_activity_events (\n  id uuid primary key default gen_random_uuid(),\n  mentor_id uuid not null references public.users (id) on delete cascade,\n  event_type text not null,\n  reason text,\n  detail jsonb,\n  status text not null default ''logged'',\n  created_at timestamptz not null default now(),\n  reviewed_by uuid references public.users (id) on delete set null,\n  reviewed_at timestamptz\n);\n\ncreate index if not exists mentor_activity_events_mentor_idx\n  on public.mentor_activity_events (mentor_id, created_at desc);\ncreate index if not exists mentor_activity_events_review_idx\n  on public.mentor_activity_events (status)\n  where status = ''pending_review'';\n\n-- RLS: 관리자 콘솔은 service_role 로 접근. 일반 사용자 직접 접근 차단(정책 없음 = 잠금).\nalter table public.mentor_activity_events enable row level security;"], "idempotency_key": null}, {"name": "101_community_comments_admin_moderation", "version": "20260712060703", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- 101_community_comments_admin_moderation.sql\n-- community_comments 모더레이션 활성화 — RLS only (파일 본문 그대로, begin/commit 래퍼는 마이그레이션 원자 실행이 대체)\n\n-- SELECT 정책 교체 — visible 댓글 누구나 / 본인 댓글 + admin 은 hidden 도 조회\ndrop policy if exists \"community_comments_select_visible\" on public.community_comments;\ncreate policy \"community_comments_select_visible\"\n  on public.community_comments\n  for select\n  to anon, authenticated\n  using (\n    status = ''visible''\n    or author_id = (select auth.uid())\n    or (select public.is_admin()) = true\n  );\n\n-- UPDATE 정책 — admin 전용\ndrop policy if exists \"community_comments_update_admin\" on public.community_comments;\ncreate policy \"community_comments_update_admin\"\n  on public.community_comments\n  for update\n  to authenticated\n  using ((select public.is_admin()) = true)\n  with check ((select public.is_admin()) = true);\n\n-- DELETE 정책 — admin 전용\ndrop policy if exists \"community_comments_delete_admin\" on public.community_comments;\ncreate policy \"community_comments_delete_admin\"\n  on public.community_comments\n  for delete\n  to authenticated\n  using ((select public.is_admin()) = true);\n\ncomment on policy \"community_comments_select_visible\" on public.community_comments is\n  ''community_comments: visible 댓글은 누구나 / 본인 댓글 또는 admin 은 hidden 도 조회'';\ncomment on policy \"community_comments_update_admin\" on public.community_comments is\n  ''community_comments: admin 만 status 등 변경(모더레이션) 가능'';\ncomment on policy \"community_comments_delete_admin\" on public.community_comments is\n  ''community_comments: admin 만 행 삭제 가능'';"], "idempotency_key": null}, {"name": "104_user_warnings", "version": "20260712060717", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- 104_user_warnings.sql\n-- P1 ② — 사용자 경고 누적 → N회(3회) 시 자동 일시정지\n-- 운영 적용 대상: 예(신규 테이블 + 인덱스).\n\ncreate table if not exists public.user_warnings (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete cascade,\n  issued_by uuid references public.users (id) on delete set null,\n  reason text not null,\n  severity text not null default ''normal'',  -- normal | severe\n  source text not null default ''admin'',     -- admin | dispute | report\n  is_active boolean not null default true,   -- 만료/철회 시 false\n  created_at timestamptz not null default now()\n);\n\ncreate index if not exists user_warnings_user_idx\n  on public.user_warnings (user_id, created_at desc);\ncreate index if not exists user_warnings_active_idx\n  on public.user_warnings (user_id)\n  where is_active = true;\n\ncomment on table public.user_warnings is ''사용자 경고 누적 로그. 활성 경고 3회 도달 시 앱이 자동 일시정지'';\n\n-- 관리자 콘솔은 service_role 로 접근. 일반 사용자 직접 접근 차단(정책 없음 = 잠금).\nalter table public.user_warnings enable row level security;"], "idempotency_key": null}, {"name": "168_iq_attachment_register_rpc_idempotent", "version": "20260715000000", "rollback": null, "created_by": null, "statements": ["-- 168_iq_attachment_register_rpc_idempotent.sql\n-- add_individual_question_attachment 명시적 멱등 계약 — 재시도·중복 제출이 행을 늘리지 않고,\n-- 호출자가 \"신규 등록 / 멱등 히트 / 실패\" 3상태를 구분할 수 있게 반환 계약을 명문화한다.\n--\n-- ⚠️ 이 파일은 웨이브 1(트랙 3)에서 **초안으로만** 작성되었다. staging 미적용.\n--\n-- ⚠️ 의존성(필수): 167 이 먼저 적용되어야 한다.\n--    167 의 UNIQUE (question_id, storage_path) 가 없으면 아래 ON CONFLICT 의 arbiter 를\n--    추론할 수 없어 런타임에 42P10 (there is no unique or exclusion constraint matching the\n--    ON CONFLICT specification) 로 **모든 등록이 실패**한다. 168 만 단독 적용하면 멱등이\n--    성립하지 않는 정도가 아니라 기능이 정지한다. 적용 순서 167 → 168 은 선택이 아니다.\n--\n-- 배경(2026-07-25 staging `lbeqxarxothkmzqvpudy` read-only 실조회 — pg_get_functiondef 전문 대조):\n--   - 현행 시그니처: add_individual_question_attachment(uuid, text, text, text, uuid)\n--       = (p_question_id, p_storage_path, p_file_name, p_mime_type, p_message_id DEFAULT null)\n--   - 현행 반환: uuid (신규 행 id). plpgsql · SECURITY DEFINER · search_path=''public'' · volatile.\n--   - 현행 본문: 가드 **5종**(raise exception 5곳 — 실측 재확인) 후 **plain INSERT** —\n--     ON CONFLICT 절 없음, 멱등 인자 없음.\n--     → 같은 (question_id, storage_path) 로 재호출하면 행이 계속 늘어난다(재시도 = 중복 생성).\n--   - 실효 EXECUTE(has_function_privilege): anon=false · authenticated=true · service_role=true.\n--     proacl = {postgres=X/postgres, authenticated=X/postgres, service_role=X/postgres}.\n--\n-- 조치:\n--   1) 반환 타입을 uuid → jsonb 로 바꾼다. PostgreSQL 은 CREATE OR REPLACE 로 반환 타입을\n--      변경할 수 없으므로 **DROP 후 CREATE** 한다(인자 시그니처는 이름·타입·기본값까지 동일 유지).\n--      DROP 은 OID 와 함께 기존 GRANT 를 소멸시키므로 아래에서 실측 ACL 과 동일하게 재부여한다.\n--   2) INSERT 에 ON CONFLICT (question_id, storage_path) DO NOTHING 을 붙이고, 미삽입 시\n--      기존 행을 조회해 멱등 히트로 반환한다.\n--   3) 저장 직전 storage_path 를 btrim 한다(167 주석의 정규화 한계 보완 — 미trim 유입 차단).\n--\n-- 의도적 비변경(스코프 밖 — 이 스크립트가 건드리지 않는 것):\n--   - 기존 가드 5종의 조건·예외 메시지·SQLSTATE 를 **한 글자도 바꾸지 않는다**.\n--     v19·v20 클라이언트가 이 토큰들로 분기하고 있으므로 문자열 안정성이 계약의 일부다.\n--   - 139(question-room-attachments) 처럼 storage 객체 존재·owner_id 대조를 추가하지 **않는다**.\n--     staging 실측상 individual-question-attachments 버킷 5개 객체는 owner·owner_id 가 전부\n--     NULL 이라(다른 7개 버킷은 100% 채워져 있음 — fixture 시드 흔적), 지금 그 검사를 넣으면\n--     정상 경로까지 막힌다. 업로더 소유 판정은 169 에서 별도로 다룬다.\n--   - individual_question_attachments 의 기존 행·컬럼·인덱스·FK 를 변경하지 않는다.\n--\n-- 선행: 070, 117, 167(필수). 후속: 169(조건부 DELETE 정책), App-A3(앱 배선 — 아래 반환 계약이 정본).\n\nbegin", "set local lock_timeout = ''5s''", "-- ── 0. 사전 검증: 167 의 arbiter 제약 존재 확인. 없으면 중단(168 단독 적용 방지) ──\n-- UNIQUE constraint 든 독립 UNIQUE index 든 pg_index 에 indisunique 행이 생기므로,\n-- 컬럼 집합을 직접 대조해 한 번에 판정한다(제약/인덱스 어느 형태로 적용됐든 통과).\ndo $$\ndeclare\n  v_q  smallint := (select attnum from pg_attribute\n                     where attrelid = ''public.individual_question_attachments''::regclass\n                       and attname = ''question_id'' and not attisdropped);\n  v_sp smallint := (select attnum from pg_attribute\n                     where attrelid = ''public.individual_question_attachments''::regclass\n                       and attname = ''storage_path'' and not attisdropped);\nbegin\n  if not exists (\n    select 1\n    from pg_index i\n    where i.indrelid = ''public.individual_question_attachments''::regclass\n      and i.indisunique\n      and i.indisvalid\n      and i.indpred is null                     -- partial 인덱스는 arbiter 로 부적합\n      and i.indnatts = 2\n      and i.indkey::smallint[] @> array[v_q, v_sp]\n  ) then\n    raise exception\n      ''ABORT_168: (question_id, storage_path) UNIQUE arbiter 부재 — 167 을 먼저 적용하라. 이 상태로 168 을 적용하면 모든 등록이 42P10 으로 실패한다.'';\n  end if;\n\n  raise notice ''168 preflight OK: (question_id, storage_path) UNIQUE arbiter 확인됨.'';\nend $$", "-- ── 1. 기존 함수 제거(반환 타입 변경 때문 — 인자 시그니처는 동일하게 재생성) ──\ndrop function if exists public.add_individual_question_attachment(uuid, text, text, text, uuid)", "-- ── 2. 멱등 등록 RPC 재생성 ──\ncreate function public.add_individual_question_attachment(\n  p_question_id uuid,\n  p_storage_path text,\n  p_file_name text,\n  p_mime_type text,\n  p_message_id uuid default null::uuid\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $function$\ndeclare\n  v_uid  uuid := (select auth.uid());\n  v_path text;\n  v_id   uuid;\n  v_existing_message_id uuid;\n  v_created boolean := false;\nbegin\n  -- 가드 1: 인증 (기존 토큰·SQLSTATE 유지)\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  -- 가드 2: 경로 필수 (기존 토큰·SQLSTATE 유지). 정규화는 여기서 1회 확정한다.\n  v_path := btrim(coalesce(p_storage_path, ''''));\n  if v_path = '''' then\n    raise exception ''INVALID_INPUT: storage_path is required'' using errcode = ''22023'';\n  end if;\n\n  -- 가드 3: 당사자(질문 학생 또는 배정·claim 멘토, admin)만 등록 가능 (기존 유지)\n  if not public.user_is_individual_question_party(p_question_id) then\n    raise exception ''NOT_QUESTION_PARTY'' using errcode = ''42501'';\n  end if;\n\n  -- 가드 4: 경로 위조 차단 — 첫 세그먼트가 이 질문의 uuid 여야 한다 (기존 유지)\n  if split_part(v_path, ''/'', 1) <> p_question_id::text then\n    raise exception ''STORAGE_PATH_MISMATCH'' using errcode = ''22023'';\n  end if;\n\n  -- 가드 5: 메시지 소속 검증 — 다른 질문의 메시지를 이 질문 첨부로 묶는 것 차단 (기존 유지)\n  if p_message_id is not null and not exists (\n    select 1\n    from public.individual_question_messages m\n    where m.id = p_message_id\n      and m.question_id = p_question_id\n  ) then\n    raise exception ''MESSAGE_NOT_IN_QUESTION'' using errcode = ''22023'';\n  end if;\n\n  -- 멱등 INSERT: 167 의 UNIQUE (question_id, storage_path) 를 arbiter 로 사용.\n  insert into public.individual_question_attachments\n    (question_id, message_id, storage_path, file_name, mime_type)\n  values\n    (p_question_id, p_message_id, v_path, p_file_name, p_mime_type)\n  on conflict (question_id, storage_path) do nothing\n  returning id into v_id;\n\n  if v_id is not null then\n    v_created := true;\n  else\n    -- 멱등 히트: 기존 행을 조회해 동일한 attachment_id 를 반환한다.\n    -- 기존 행은 **절대 UPDATE 하지 않는다** — file_name·mime_type·message_id 는 최초 등록값을\n    -- 정본으로 보존한다(재시도가 메타데이터를 덮어쓰는 사고 방지).\n    select a.id, a.message_id\n      into v_id, v_existing_message_id\n    from public.individual_question_attachments a\n    where a.question_id = p_question_id\n      and a.storage_path = v_path;\n\n    -- 방어: 경합으로 행이 사라진 극단 케이스(FK CASCADE 등)에서는 조용히 null 을 반환하지 않는다.\n    if v_id is null then\n      raise exception ''REGISTER_CONFLICT_UNRESOLVED'' using errcode = ''40001'';\n    end if;\n  end if;\n\n  return jsonb_build_object(\n    ''ok'',            true,\n    ''status'',        case when v_created then ''created'' else ''existing'' end,\n    ''idempotent_hit'', not v_created,\n    ''attachment_id'', v_id,\n    ''question_id'',   p_question_id,\n    ''storage_path'',  v_path,\n    -- 멱등 히트인데 호출자가 보낸 message_id 가 저장된 값과 다를 때만 true.\n    -- 호출자에게 \"요청은 반영되지 않았고 최초 등록값이 유지됐다\"를 알리는 신호.\n    ''message_id_mismatch'',\n      case when v_created then false\n           else coalesce(v_existing_message_id, ''00000000-0000-0000-0000-000000000000''::uuid)\n                is distinct from coalesce(p_message_id, ''00000000-0000-0000-0000-000000000000''::uuid)\n      end\n  );\nend;\n$function$", "-- ── 3. ACL 재부여(DROP 으로 소멸된 GRANT 복원 — staging 실측 proacl 과 동일하게) ──\n--    실측: anon=false / authenticated=true / service_role=true\nrevoke all on function public.add_individual_question_attachment(uuid, text, text, text, uuid)\n  from public, anon", "grant execute on function public.add_individual_question_attachment(uuid, text, text, text, uuid)\n  to authenticated, service_role", "commit", "-- ═══════════════════════════════════════════════════════════════════════════\n-- §반환 계약 (App-A3 앱 배선의 정본)\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 반환 타입: jsonb (구 uuid 스칼라에서 **파괴적 변경**).\n--   구 호출자는 반환값을 uuid 로 직접 읽었다 → 신 호출자는 `.attachment_id` 를 읽어야 한다.\n--   이 변경은 168 적용과 앱 배선(App-A3)이 **함께** 나가야 함을 뜻한다.\n--\n-- 성공 — 신규 등록:\n--   { \"ok\": true, \"status\": \"created\",  \"idempotent_hit\": false,\n--     \"attachment_id\": \"<uuid>\", \"question_id\": \"<uuid>\", \"storage_path\": \"<text>\",\n--     \"message_id_mismatch\": false }\n--\n-- 성공 — 멱등 히트(이미 같은 (question_id, storage_path) 행이 존재):\n--   { \"ok\": true, \"status\": \"existing\", \"idempotent_hit\": true,\n--     \"attachment_id\": \"<기존 행 uuid>\", \"question_id\": \"<uuid>\", \"storage_path\": \"<text>\",\n--     \"message_id_mismatch\": true|false }\n--   - attachment_id 는 최초 등록 행의 id — 재시도해도 같은 값이 돌아온다(멱등의 관측 가능한 증거).\n--   - 기존 행의 file_name·mime_type·message_id 는 갱신되지 않는다.\n--   - message_id_mismatch=true 는 \"보낸 message_id 가 저장값과 달라 무시됐다\"는 뜻이다.\n--     앱은 이를 오류로 처리하지 말고(등록 자체는 성공), 필요 시 로깅·재조회로만 다룬다.\n--\n-- 실패 — 예외(raise)로만 전달된다. 반환값에 ok:false 형태는 존재하지 않는다.\n--   SQLSTATE  | 메시지 토큰                        | 의미\n--   ----------|-----------------------------------|------------------------------------------\n--   28000     | AUTH_REQUIRED                     | 미인증 호출\n--   22023     | INVALID_INPUT: storage_path is required | 경로 누락·공백\n--   42501     | NOT_QUESTION_PARTY                | 질문 당사자(학생/배정·claim 멘토/admin) 아님\n--   22023     | STORAGE_PATH_MISMATCH             | 경로 첫 세그먼트 ≠ question_id (위조 차단)\n--   22023     | MESSAGE_NOT_IN_QUESTION           | message_id 가 이 질문 소속이 아님\n--   40001     | REGISTER_CONFLICT_UNRESOLVED      | 충돌 후 기존 행 조회 실패(경합) — 재시도 대상\n--   42P10     | (PostgreSQL 원문)                  | **167 미적용** — arbiter 부재. 배포 사고 신호\n--\n--   호출자 분기 규칙: 22023·42501 은 재시도 금지(입력·권한 문제). 40001 은 1회 재시도 허용.\n--   42P10 은 앱에서 복구 불가 — 즉시 알림 대상(167 누락 배포).\n--\n-- 3상태 구분 방법(요약): 예외 발생 = 실패 / status=''created'' = 신규 / status=''existing'' = 멱등 히트.\n--\n-- ── 경로 불변식 (A3 배선 필수 조건) ──\n-- 이 RPC 는 저장 직전 storage_path 를 btrim 한다. 따라서 앞뒤 공백이 있는 경로로 업로드하면\n-- **storage 객체명(원문)과 등록 행 storage_path(trim)가 갈라진다**. 그 상태에서 앱의\n-- findRegistered 가 `.eq(''storage_path'', 원문)` 으로 조회하면 0건을 보고 보상 삭제로 흐를 수 있다.\n--   → 앱은 **경로 무공백 불변식**(파일명·확장자 sanitize 포함)을 지키거나,\n--     업로드·조회에 쓰는 경로에 서버와 **동일한 정규화(btrim)** 를 적용해야 한다.\n--   → 반환된 `storage_path` 는 서버가 확정한 정규화 결과다. 앱은 이후 조회·삭제 판정에\n--     자신이 만든 원문이 아니라 **이 반환값을 정본으로 사용**하면 불일치가 원천 차단된다.\n-- 현 실위험 0: 앱 생성 경로는 `{questionId}/{ts}-{salt}.{ext}` 형식이고, preflight 실측\n-- 미trim 행 0건이다. 위 불변식은 회귀 방지용 명문화다.\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- ── §V 검증 SELECT (적용 후 별도 실행) ──\n-- select p.oid::regprocedure::text, pg_get_function_result(p.oid), p.proacl::text\n--   from pg_proc p join pg_namespace n on n.oid=p.pronamespace\n--  where n.nspname=''public'' and p.proname=''add_individual_question_attachment'';\n-- 기대: add_individual_question_attachment(uuid,text,text,text,uuid) | jsonb |\n--       {postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}\n--\n-- ── ROLLBACK 절차 ──\n-- 168 을 되돌리려면 함수를 구 정의(RETURNS uuid · plain INSERT)로 재생성한다.\n--   drop function if exists public.add_individual_question_attachment(uuid,text,text,text,uuid);\n--   -- 이후 staging 실측 원본 정의(이 파일 상단 ''배경'' 의 pg_get_functiondef 전문)를 그대로 재적용하고\n--   -- revoke all ... from public, anon; grant execute ... to authenticated, service_role; 을 재실행한다.\n-- 되돌림 순서: 앱 배선(App-A3) 되돌림 → 168 → 167. 167 을 먼저 지우면 안 된다."], "idempotency_key": null}, {"name": "fix_xv01_signup_admin_provisioning", "version": "20260717044250", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- XV-01 픽스: 미인증 사용자의 가입(INSERT) 경로 admin 자가 provisioning 차단.\n-- 2단 방어:\n--   (1) handle_new_auth_user(): 가입 메타 app_role=''admin'' 을 허용목록에서 제거\n--       (→ ''student'' 폴백). 이것이 실제 공격 벡터의 정본 차단.\n--   (2) public.users BEFORE INSERT 가드: RLS users_insert_own(id=auth.uid()) 를 통한\n--       클라이언트 직접 INSERT(role=''admin'') 2차 벡터 차단. 기존 UPDATE 가드\n--       (enforce_users_role_guard)와 동일한 예외 모델(service_role / JWT 없는 직접\n--       DB 세션 / 기존 admin)만 admin INSERT 허용.\n-- 불변: 테이블·기존 RLS·다른 트리거·시그니처 무변경. 멱등(재적용 안전).\n\n-- ── (1) 가입 트리거: admin 허용 제거 ─────────────────────────────\ncreate or replace function public.handle_new_auth_user()\n returns trigger\n language plpgsql\n security definer\n set search_path to ''public''\nas $function$\ndeclare\n  m jsonb;\n  r text;\n  subj text[];\n  subj_str text;\n  bdate date;\nbegin\n  m := coalesce(NEW.raw_user_meta_data, ''{}''::jsonb);\n  r := lower(trim(m->>''app_role''));\n  if r is null or r = '''' then\n    r := ''student'';\n  end if;\n  -- ★ XV-01: ''admin'' 제거 — 가입 메타로는 student/mentor 만 가능. 그 외 전부 student.\n  if r not in (''student'', ''mentor'') then\n    r := ''student'';\n  end if;\n\n  subj_str := nullif(trim(m->>''teaching_subjects_csv''), '''');\n  if subj_str is not null then\n    subj := array(\n      select trim(both '' '' from x)\n      from unnest(string_to_array(subj_str, '','')) as x\n      where length(trim(both '' '' from x)) > 0\n    );\n  else\n    subj := ''{}'';\n  end if;\n\n  begin\n    bdate := (m->>''birth_date'')::date;\n  exception when others then\n    bdate := null;\n  end;\n\n  insert into public.users (\n    id, role, status, full_name, nickname, email,\n    grade_level, student_status, birth_date,\n    terms_agreed_at, privacy_agreed_at, marketing_agreed, updated_at\n  ) values (\n    NEW.id, r, ''active'',\n    nullif(trim(m->>''full_name''), ''''),\n    nullif(trim(m->>''nickname''), ''''),\n    coalesce(NEW.email, ''''),\n    nullif(trim(m->>''grade_level''), ''''),\n    nullif(trim(m->>''student_status''), ''''),\n    bdate,\n    case when (m->>''terms_agreed'') = ''true'' then now() else null end,\n    case when (m->>''privacy_agreed'') = ''true'' then now() else null end,\n    case when (m->>''marketing_agreed'') = ''true'' then true else false end,\n    now()\n  )\n  on conflict (id) do update set\n    role = excluded.role,\n    full_name = coalesce(excluded.full_name, public.users.full_name),\n    nickname = coalesce(excluded.nickname, public.users.nickname),\n    email = excluded.email,\n    grade_level = coalesce(excluded.grade_level, public.users.grade_level),\n    student_status = coalesce(excluded.student_status, public.users.student_status),\n    birth_date = coalesce(excluded.birth_date, public.users.birth_date),\n    terms_agreed_at = coalesce(excluded.terms_agreed_at, public.users.terms_agreed_at),\n    privacy_agreed_at = coalesce(excluded.privacy_agreed_at, public.users.privacy_agreed_at),\n    marketing_agreed = excluded.marketing_agreed,\n    updated_at = now();\n\n  if r = ''mentor'' then\n    insert into public.mentor_profiles (\n      user_id, university_name, department_name, teaching_subjects, high_school_name, intro_line,\n      verification_status, student_id_image_url, updated_at\n    ) values (\n      NEW.id,\n      coalesce(nullif(trim(m->>''university_name''), ''''), ''(미입력)''),\n      coalesce(nullif(trim(m->>''department_name''), ''''), ''(미입력)''),\n      coalesce(subj, ''{}''),\n      coalesce(nullif(trim(m->>''high_school_name''), ''''), ''(미입력)''),\n      nullif(trim(m->>''intro_line''), ''''),\n      ''pending'',\n      null,\n      now()\n    )\n    on conflict (user_id) do update set\n      university_name = excluded.university_name,\n      department_name = excluded.department_name,\n      teaching_subjects = excluded.teaching_subjects,\n      high_school_name = excluded.high_school_name,\n      intro_line = coalesce(excluded.intro_line, public.mentor_profiles.intro_line),\n      updated_at = now();\n\n    insert into public.verification_logs (user_id, log_type, status, memo) values\n      (NEW.id, ''mentor_verification'', ''pending'', ''sign-up'');\n  end if;\n\n  return NEW;\nend;\n$function$;\n\n-- ── (2) INSERT 가드: 클라이언트 직접 admin INSERT 차단 ────────────\ncreate or replace function public.enforce_users_role_insert_guard()\n returns trigger\n language plpgsql\n security definer\n set search_path to ''public''\nas $function$\ndeclare\n  v_jwt_role text;\nbegin\n  if new.role = ''admin'' then\n    v_jwt_role := auth.jwt() ->> ''role'';\n\n    if v_jwt_role = ''service_role'' then\n      return new; -- 1) 서버(service key) 경유 — admin 프로비저닝 정상 경로\n    end if;\n\n    if v_jwt_role is null then\n      return new; -- 2) JWT 없는 직접 DB 세션(SQL Editor·마이그레이션·SECURITY DEFINER)\n    end if;\n\n    if exists (\n      select 1\n        from public.users u\n       where u.id = (select auth.uid())\n         and u.role = ''admin''\n    ) then\n      return new; -- 3) 기존 관리자\n    end if;\n\n    raise exception ''ADMIN_INSERT_FORBIDDEN''\n      using errcode = ''42501'', -- insufficient_privilege\n            detail  = format(''users.id=%s attempted role INSERT %L'', new.id, new.role),\n            hint    = ''admin 계정 생성은 service_role 또는 admin 만 가능합니다(가입 경로 불가).'';\n  end if;\n\n  return new;\nend;\n$function$;\n\ndrop trigger if exists trg_users_role_insert_guard on public.users;\ncreate trigger trg_users_role_insert_guard\n  before insert on public.users\n  for each row\n  when (new.role = ''admin'')\n  execute function public.enforce_users_role_insert_guard();\n"], "idempotency_key": null}, {"name": "fix_xv01_revoke_insert_guard_execute", "version": "20260717044741", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- XV-01 후속: INSERT 가드 트리거 함수의 직접 EXECUTE 권한 회수(기존 UPDATE 가드\n-- enforce_users_role_guard 와 동일한 위생). 트리거는 definer 로 실행되므로 회수해도\n-- 트리거 동작에는 영향 없음. anon/authenticated 의 직접 호출 표면만 제거.\nrevoke execute on function public.enforce_users_role_insert_guard() from public;\nrevoke execute on function public.enforce_users_role_insert_guard() from anon;\nrevoke execute on function public.enforce_users_role_insert_guard() from authenticated;"], "idempotency_key": null}, {"name": "admin_read_enablement_mentor_verification", "version": "20260717091247", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- 기능 복원: 관리자 콘솔이 service_role 없이(세션 폴백 시)에도 멘토 심사 데이터를 읽을 수 있도록\n-- 기존 msv_admin_select_all 패턴과 동일한 is_admin() 기반 SELECT 정책 추가 (additive).\n\ndrop policy if exists \"student_id_images_admin_select\" on storage.objects;\ncreate policy \"student_id_images_admin_select\" on storage.objects\n  for select to authenticated\n  using (bucket_id = ''student-id-images'' and (select is_admin()) = true);\n\ndrop policy if exists \"mp_admin_select_all\" on public.mentor_profiles;\ncreate policy \"mp_admin_select_all\" on public.mentor_profiles\n  for select to authenticated\n  using ((select is_admin()) = true);\n\ndrop policy if exists \"users_admin_select_all\" on public.users;\ncreate policy \"users_admin_select_all\" on public.users\n  for select to authenticated\n  using ((select is_admin()) = true);"], "idempotency_key": null}, {"name": "120_admin_console_fixes", "version": "20260717125606", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- 120_admin_console_fixes.sql (repo: supabase/sql/120_admin_console_fixes.sql)\nalter table public.content_reports\n  drop constraint if exists content_reports_status_allowed;\nalter table public.content_reports\n  add constraint content_reports_status_allowed\n  check (status = any (array[\n    ''pending'', ''reviewing'', ''resolved'', ''rejected'', ''dismissed'',\n    ''hidden'', ''removed''\n  ]));\n\nalter table public.disputes\n  drop constraint if exists disputes_status_check;\nalter table public.disputes\n  add constraint disputes_status_check\n  check (status = any (array[\n    ''open'', ''under_review'', ''resolved'', ''dismissed'', ''escalated'',\n    ''on_hold'', ''sanction_7d'', ''sanction_30d'', ''sanction_permanent''\n  ]));\n\ndrop policy if exists users_admin_select_all on public.users;\ncreate policy users_admin_select_all on public.users\n  for select to authenticated\n  using ((select public.is_admin()) = true);\n\ndrop policy if exists mp_admin_select_all on public.mentor_profiles;\ncreate policy mp_admin_select_all on public.mentor_profiles\n  for select to authenticated\n  using ((select public.is_admin()) = true);\n\ndrop policy if exists student_id_images_admin_select on storage.objects;\ncreate policy student_id_images_admin_select on storage.objects\n  for select to authenticated\n  using (bucket_id = ''student-id-images'' and (select public.is_admin()) = true);\n\ndrop policy if exists \"누구나 댓글 읽기\" on public.comments;\ndrop policy if exists \"로그인 유저 댓글 작성\" on public.comments;\ndrop policy if exists \"본인 댓글 삭제\" on public.comments;\n\ndrop policy if exists comments_admin_select_all on public.comments;\ncreate policy comments_admin_select_all on public.comments\n  for select to authenticated\n  using ((select public.is_admin()) = true);\n\ndrop policy if exists comments_admin_update on public.comments;\ncreate policy comments_admin_update on public.comments\n  for update to authenticated\n  using ((select public.is_admin()) = true)\n  with check ((select public.is_admin()) = true);\n\ndrop policy if exists comments_admin_delete on public.comments;\ncreate policy comments_admin_delete on public.comments\n  for delete to authenticated\n  using ((select public.is_admin()) = true);\n\ndrop policy if exists qra_storage_read_admin on storage.objects;\ncreate policy qra_storage_read_admin on storage.objects\n  for select to authenticated\n  using (bucket_id = ''question-room-attachments'' and (select public.is_admin()) = true);\n\ndrop policy if exists scan_annotations_obj_admin_select on storage.objects;\ncreate policy scan_annotations_obj_admin_select on storage.objects\n  for select to authenticated\n  using (bucket_id = ''scan-annotations'' and (select public.is_admin()) = true);\n\ndrop policy if exists scan_annotations_admin_select on public.scan_annotations;\ncreate policy scan_annotations_admin_select on public.scan_annotations\n  for select to authenticated\n  using ((select public.is_admin()) = true);\n\ncomment on constraint content_reports_status_allowed on public.content_reports is\n  ''120: hidden/removed 추가 — 검수 콘솔 숨김/삭제 처리와 정합.'';\ncomment on constraint disputes_status_check on public.disputes is\n  ''120: on_hold/sanction_7d/sanction_30d/sanction_permanent 추가 — 분쟁 제재 액션과 정합.'';"], "idempotency_key": null}, {"name": "mentor_plan_price_band_clamp", "version": "20260718094306", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["WITH band AS (\n  SELECT * FROM (VALUES\n    (''limited'',  2990000,  6990000),\n    (''standard'', 8490000, 14990000),\n    (''premium'', 17490000, 32990000)\n  ) AS t(plan_tier, min_cents, max_cents)\n)\nUPDATE mentor_plans mp\nSET amount_cents = LEAST(GREATEST(mp.amount_cents, b.min_cents), b.max_cents),\n    updated_at = now(),\n    price_updated_at = now()\nFROM band b\nWHERE mp.plan_tier = b.plan_tier\n  AND (mp.amount_cents < b.min_cents OR mp.amount_cents > b.max_cents);"], "idempotency_key": null}, {"name": "p2_2_community_board_idempotency_softdelete_147", "version": "20260720073848", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["begin;\nalter table public.community_posts add column if not exists create_idempotency_key uuid;\nalter table public.community_posts add column if not exists deleted_at timestamptz;\ncreate unique index if not exists community_posts_author_idem_key\n  on public.community_posts (author_id, create_idempotency_key);\ncreate index if not exists idx_cp_active_created\n  on public.community_posts (created_at desc) where deleted_at is null;\ncommit;"], "idempotency_key": null}, {"name": "p2_3_shortform_idempotency_148", "version": "20260720075436", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["begin;\nalter table public.shortform_posts add column if not exists create_idempotency_key uuid;\ncreate unique index if not exists shortform_posts_author_idem_key\n  on public.shortform_posts (author_id, create_idempotency_key);\ncommit;"], "idempotency_key": null}, {"name": "p1_8a_storage_insert_eligibility_149", "version": "20260720080527", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["begin;\nset local lock_timeout=''5s'';\n\ncreate or replace function public.qra_path_upload_eligible(p_name text)\nreturns boolean language plpgsql stable security definer set search_path to ''public'' as $$\ndeclare\n  v_uid uuid := auth.uid(); v_room uuid; v_thread uuid; v_student uuid; v_mentor uuid; v_sub_id uuid;\nbegin\n  if v_uid is null then return false; end if;\n  v_room := public.qra_room_uuid_from_path(p_name);\n  begin\n    v_thread := nullif(split_part(p_name, ''/'', 2), '''')::uuid;\n  exception when others then\n    return false;\n  end;\n  if v_room is null or v_thread is null then return false; end if;\n\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = v_room;\n  if v_student is null then return false; end if;\n\n  if v_uid = v_mentor then return true; end if;\n  if v_uid <> v_student then return false; end if;\n\n  if not exists (\n    select 1 from public.question_threads t where t.id = v_thread and t.mentor_student_room_id = v_room\n  ) then\n    return false;\n  end if;\n\n  select id into v_sub_id from public.subscriptions\n    where student_id = v_student and mentor_id = v_mentor and lower(coalesce(status,'''')) = ''active'' limit 1;\n  if v_sub_id is not null then\n    return not public.qna_subscription_has_live_refund(v_sub_id);\n  end if;\n\n  return exists (\n    select 1 from public.free_question_usage f where f.thread_id = v_thread and f.student_id = v_student\n  );\nend; $$;\nrevoke all on function public.qra_path_upload_eligible(text) from public, anon;\ngrant execute on function public.qra_path_upload_eligible(text) to authenticated, service_role;\n\ndrop policy if exists qra_storage_insert_party on storage.objects;\ncreate policy qra_storage_insert_party on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = ''question-room-attachments''\n    and public.user_is_room_party_for_qra_path(name)\n    and public.qra_thread_writable_for_path(name)\n    and public.qra_uploader_allowed_for_path(name)\n    and public.qra_path_upload_eligible(name)\n  );\n\ncommit;"], "idempotency_key": null}, {"name": "p1_13_refund_billing_event_fk_150", "version": "20260720080619", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["begin;\nset local lock_timeout=''5s'';\n\nalter table public.refunds add column if not exists billing_event_id uuid;\n\ndo $$\nbegin\n  if not exists (\n    select 1 from pg_constraint where conname = ''refunds_billing_event_id_fkey'' and conrelid = ''public.refunds''::regclass\n  ) then\n    alter table public.refunds\n      add constraint refunds_billing_event_id_fkey\n      foreign key (billing_event_id) references public.subscription_billing_events(id) on delete set null;\n  end if;\nend $$;\n\ncreate index if not exists idx_refunds_billing_event on public.refunds (billing_event_id) where billing_event_id is not null;\n\ncreate or replace function public.qna_subscription_has_live_refund(p_subscription_id uuid)\nreturns boolean language sql stable security definer set search_path to ''public'' as $$\n  select exists (\n    select 1\n    from public.refunds r\n    join public.subscriptions s on s.id = r.subscription_id\n    where r.subscription_id = p_subscription_id\n      and r.status = ''pending''\n      and r.request_type in (''subscription_prorated'',''subscription_mentor_suspended'')\n      and (r.billing_event_id is null or r.billing_event_id = s.last_billing_event_id)\n  );\n$$;\nrevoke all on function public.qna_subscription_has_live_refund(uuid) from public, anon;\ngrant execute on function public.qna_subscription_has_live_refund(uuid) to authenticated, service_role;\n\ncommit;"], "idempotency_key": null}, {"name": "p1_10_account_deletion_saga_151", "version": "20260720081121", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["begin;\nset local lock_timeout=''5s'';\n\ncreate table if not exists public.account_deletion_jobs (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null unique references public.users (id),\n  state text not null default ''pending''\n    check (state in (''pending'',''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted'',''completed'',''canceled'',''failed'')),\n  attempts int not null default 0,\n  last_error text,\n  next_attempt_at timestamptz,\n  cancelable_until timestamptz,\n  dry_run boolean not null default true,\n  requested_at timestamptz not null default now(),\n  locked_at timestamptz, purging_at timestamptz, storage_purged_at timestamptz,\n  finalized_at timestamptz, auth_soft_deleted_at timestamptz, completed_at timestamptz,\n  canceled_at timestamptz, failed_at timestamptz,\n  updated_at timestamptz not null default now()\n);\nalter table public.account_deletion_jobs enable row level security;\nrevoke all on public.account_deletion_jobs from public, anon, authenticated;\ngrant select, insert, update on public.account_deletion_jobs to service_role;\ncreate index if not exists idx_adj_state_next on public.account_deletion_jobs (state, next_attempt_at);\n\ncreate or replace function public.account_deletion_write_blocked(p_user_id uuid)\nreturns boolean language sql stable security definer set search_path to ''public'' as $$\n  select exists (\n    select 1 from public.account_deletion_jobs j\n    where j.user_id = p_user_id\n      and j.state in (''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted'')\n  );\n$$;\nrevoke all on function public.account_deletion_write_blocked(uuid) from public, anon;\ngrant execute on function public.account_deletion_write_blocked(uuid) to authenticated, service_role;\n\ncreate or replace function public.account_deletion_write_guard()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_col text := TG_ARGV[0]; v_uid uuid;\nbegin\n  v_uid := (to_jsonb(NEW) ->> v_col)::uuid;\n  if v_uid is not null and public.account_deletion_write_blocked(v_uid) then\n    raise exception ''ACCOUNT_DELETION_IN_PROGRESS'';\n  end if;\n  return NEW;\nend $$;\n\ndrop trigger if exists adg_cash_wallets on public.cash_wallets;\ncreate trigger adg_cash_wallets before insert or update on public.cash_wallets\n  for each row execute function public.account_deletion_write_guard(''user_id'');\ndrop trigger if exists adg_cash_ledger on public.cash_ledger;\ncreate trigger adg_cash_ledger before insert on public.cash_ledger\n  for each row execute function public.account_deletion_write_guard(''user_id'');\ndrop trigger if exists adg_payments on public.payments;\ncreate trigger adg_payments before insert on public.payments\n  for each row execute function public.account_deletion_write_guard(''user_id'');\ndrop trigger if exists adg_question_messages on public.question_messages;\ncreate trigger adg_question_messages before insert on public.question_messages\n  for each row execute function public.account_deletion_write_guard(''author_id'');\ndrop trigger if exists adg_community_posts on public.community_posts;\ncreate trigger adg_community_posts before insert on public.community_posts\n  for each row execute function public.account_deletion_write_guard(''author_id'');\ndrop trigger if exists adg_shortform_posts on public.shortform_posts;\ncreate trigger adg_shortform_posts before insert on public.shortform_posts\n  for each row execute function public.account_deletion_write_guard(''author_id'');\n\ndrop policy if exists qra_storage_insert_party on storage.objects;\ncreate policy qra_storage_insert_party on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = ''question-room-attachments''\n    and public.user_is_room_party_for_qra_path(name)\n    and public.qra_thread_writable_for_path(name)\n    and public.qra_uploader_allowed_for_path(name)\n    and public.qra_path_upload_eligible(name)\n    and not public.account_deletion_write_blocked(auth.uid())\n  );\n\ndrop policy if exists \"cpi_auth_insert_own\" on storage.objects;\ncreate policy \"cpi_auth_insert_own\" on storage.objects for insert to authenticated\n  with check (\n    bucket_id = ''community-post-images''\n    and (storage.foldername(name))[1] = (select auth.uid())::text\n    and not public.account_deletion_write_blocked(auth.uid())\n  );\n\ndrop policy if exists \"sfv_mentor_insert\" on storage.objects;\ncreate policy \"sfv_mentor_insert\" on storage.objects for insert to authenticated\n  with check (\n    bucket_id in (''shortform-videos'', ''shortform-thumbnails'')\n    and public.is_mentor()\n    and (storage.foldername(name))[1] = (select auth.uid())::text\n    and not public.account_deletion_write_blocked(auth.uid())\n  );\n\ncreate or replace function public.account_deletion_request(p_user_id uuid, p_cancelable_minutes int default 30, p_dry_run boolean default true)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_id uuid; v_state text;\nbegin\n  select id, state into v_id, v_state from public.account_deletion_jobs where user_id = p_user_id;\n  if v_id is not null then\n    return jsonb_build_object(''ok'',true,''existing'',true,''job_id'',v_id,''state'',v_state);\n  end if;\n  insert into public.account_deletion_jobs (user_id, state, cancelable_until, dry_run)\n    values (p_user_id, ''pending'', now() + make_interval(mins => greatest(0,p_cancelable_minutes)), coalesce(p_dry_run,true))\n    returning id into v_id;\n  return jsonb_build_object(''ok'',true,''existing'',false,''job_id'',v_id,''state'',''pending'');\nend $$;\n\ncreate or replace function public.account_deletion_cancel(p_user_id uuid)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_state text; v_cancelable timestamptz;\nbegin\n  select state, cancelable_until into v_state, v_cancelable\n    from public.account_deletion_jobs where user_id = p_user_id for update;\n  if not found then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n  if v_state <> ''pending'' then return jsonb_build_object(''ok'',false,''code'',''NOT_CANCELABLE'',''state'',v_state); end if;\n  if v_cancelable is not null and now() > v_cancelable then return jsonb_build_object(''ok'',false,''code'',''CANCEL_WINDOW_PASSED''); end if;\n  update public.account_deletion_jobs set state=''canceled'', canceled_at=now(), updated_at=now() where user_id=p_user_id;\n  return jsonb_build_object(''ok'',true,''state'',''canceled'');\nend $$;\n\ncreate or replace function public.account_deletion_advance(p_user_id uuid, p_from text, p_to text)\nreturns boolean language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_ok boolean := false; v_col text;\nbegin\n  if p_from=''pending'' and p_to=''locked'' then\n    update public.account_deletion_jobs\n      set state=''locked'', locked_at=now(), updated_at=now()\n      where user_id=p_user_id and state=''pending'' and (cancelable_until is null or now() >= cancelable_until);\n    get diagnostics v_ok = row_count;\n    return v_ok > 0;\n  end if;\n  if not (\n    (p_from=''locked'' and p_to=''purging'') or\n    (p_from=''purging'' and p_to=''storage_purged'') or\n    (p_from=''storage_purged'' and p_to=''finalized'') or\n    (p_from=''finalized'' and p_to=''auth_soft_deleted'') or\n    (p_from=''auth_soft_deleted'' and p_to=''completed'')\n  ) then\n    raise exception ''INVALID_TRANSITION % -> %'', p_from, p_to;\n  end if;\n  v_col := p_to || ''_at'';\n  execute format(\n    ''update public.account_deletion_jobs set state=$2, %I=now(), updated_at=now() where user_id=$1 and state=$3'',\n    v_col\n  ) using p_user_id, p_to, p_from;\n  get diagnostics v_ok = row_count;\n  return v_ok > 0;\nend $$;\n\ncreate or replace function public.account_deletion_record_error(p_user_id uuid, p_error text, p_backoff_seconds int default 60, p_max_attempts int default 8)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_attempts int;\nbegin\n  update public.account_deletion_jobs\n    set attempts = attempts + 1, last_error = left(coalesce(p_error,''''),1000),\n        next_attempt_at = now() + make_interval(secs => greatest(1,p_backoff_seconds)), updated_at = now()\n    where user_id = p_user_id\n    returning attempts into v_attempts;\n  if v_attempts is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n  if v_attempts >= p_max_attempts then\n    update public.account_deletion_jobs set state=''failed'', failed_at=now(), updated_at=now() where user_id=p_user_id;\n    return jsonb_build_object(''ok'',true,''state'',''failed'',''attempts'',v_attempts);\n  end if;\n  return jsonb_build_object(''ok'',true,''attempts'',v_attempts);\nend $$;\n\ncreate or replace function public.account_deletion_worker_claim(p_limit int default 10)\nreturns setof public.account_deletion_jobs language sql security definer set search_path to ''public'' as $$\n  select * from public.account_deletion_jobs\n  where state in (''pending'',''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted'')\n    and (next_attempt_at is null or next_attempt_at <= now())\n  order by requested_at asc\n  limit greatest(1, p_limit)\n  for update skip locked;\n$$;\n\nrevoke all on function public.account_deletion_request(uuid,int,boolean) from public, anon, authenticated;\nrevoke all on function public.account_deletion_cancel(uuid) from public, anon, authenticated;\nrevoke all on function public.account_deletion_advance(uuid,text,text) from public, anon, authenticated;\nrevoke all on function public.account_deletion_record_error(uuid,text,int,int) from public, anon, authenticated;\nrevoke all on function public.account_deletion_worker_claim(int) from public, anon, authenticated;\ngrant execute on function public.account_deletion_request(uuid,int,boolean) to service_role;\ngrant execute on function public.account_deletion_cancel(uuid) to service_role;\ngrant execute on function public.account_deletion_advance(uuid,text,text) to service_role;\ngrant execute on function public.account_deletion_record_error(uuid,text,int,int) to service_role;\ngrant execute on function public.account_deletion_worker_claim(int) to service_role;\n\ncommit;"], "idempotency_key": null}, {"name": "p1_11c_notification_delivery_worker_152", "version": "20260720081942", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["begin;\nset local lock_timeout=''5s'';\n\ncreate table if not exists public.device_tokens (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users(id) on delete cascade,\n  token text not null unique,\n  platform text not null default ''unknown'' check (platform in (''ios'',''android'',''web'',''unknown'')),\n  revoked_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index if not exists idx_device_tokens_user on public.device_tokens (user_id) where revoked_at is null;\nalter table public.device_tokens enable row level security;\nrevoke all on public.device_tokens from anon;\ndrop policy if exists device_tokens_select_own on public.device_tokens;\ncreate policy device_tokens_select_own on public.device_tokens for select to authenticated using (user_id = (select auth.uid()));\ndrop policy if exists device_tokens_modify_own on public.device_tokens;\ncreate policy device_tokens_modify_own on public.device_tokens for all to authenticated\n  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));\ngrant select, insert, update, delete on public.device_tokens to authenticated, service_role;\n\ncreate or replace function public.register_device_token(p_token text, p_platform text default ''unknown'')\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_uid uuid := auth.uid(); v_id uuid; v_plat text;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_token is null or btrim(p_token)='''' then raise exception ''TOKEN_REQUIRED''; end if;\n  v_plat := case when p_platform in (''ios'',''android'',''web'') then p_platform else ''unknown'' end;\n  insert into public.device_tokens (user_id, token, platform)\n    values (v_uid, btrim(p_token), v_plat)\n  on conflict (token) do update set user_id = v_uid, platform = v_plat, revoked_at = null, updated_at = now()\n  returning id into v_id;\n  return jsonb_build_object(''ok'', true, ''device_token_id'', v_id);\nend $$;\nrevoke all on function public.register_device_token(text,text) from public, anon;\ngrant execute on function public.register_device_token(text,text) to authenticated, service_role;\n\ncreate or replace function public.revoke_device_token(p_device_token_id uuid)\nreturns boolean language sql security definer set search_path to ''public'' as $$\n  update public.device_tokens set revoked_at = now(), updated_at = now()\n  where id = p_device_token_id and revoked_at is null returning true;\n$$;\nrevoke all on function public.revoke_device_token(uuid) from public, anon, authenticated;\ngrant execute on function public.revoke_device_token(uuid) to service_role;\n\ncreate table if not exists public.notification_settings (\n  user_id uuid primary key references public.users(id) on delete cascade,\n  push_enabled boolean not null default true,\n  groups jsonb not null default ''{}''::jsonb,\n  updated_at timestamptz not null default now()\n);\nalter table public.notification_settings enable row level security;\nrevoke all on public.notification_settings from anon;\ndrop policy if exists notif_settings_select_own on public.notification_settings;\ncreate policy notif_settings_select_own on public.notification_settings for select to authenticated using (user_id = (select auth.uid()));\ndrop policy if exists notif_settings_modify_own on public.notification_settings;\ncreate policy notif_settings_modify_own on public.notification_settings for all to authenticated\n  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));\ngrant select, insert, update on public.notification_settings to authenticated, service_role;\n\ncreate or replace function public.notification_event_group(p_event_type text)\nreturns text language sql immutable set search_path to ''public'' as $$\n  select case\n    when p_event_type like ''question_%'' or p_event_type like ''qna_%'' or p_event_type like ''connection_note%'' then ''qna''\n    when p_event_type like ''custom_%'' or p_event_type like ''order_%'' or p_event_type like ''individual_question%'' then ''order''\n    when p_event_type like ''%subscription%'' then ''subscription''\n    when p_event_type like ''%refund%'' then ''refund''\n    else ''system''\n  end;\n$$;\n\ncreate or replace function public.notification_delivery_allowed(p_user_id uuid, p_event_type text)\nreturns boolean language sql stable security definer set search_path to ''public'' as $$\n  select coalesce(\n    (select s.push_enabled and coalesce((s.groups ->> public.notification_event_group(p_event_type))::boolean, true)\n       from public.notification_settings s where s.user_id = p_user_id),\n    true\n  );\n$$;\nrevoke all on function public.notification_delivery_allowed(uuid,text) from public, anon;\ngrant execute on function public.notification_delivery_allowed(uuid,text) to authenticated, service_role;\n\ncreate table if not exists public.notification_deliveries (\n  id uuid primary key default gen_random_uuid(),\n  outbox_id uuid not null references public.notification_outbox(id) on delete cascade,\n  device_token_id uuid not null references public.device_tokens(id) on delete cascade,\n  status text not null default ''pending'' check (status in (''pending'',''sent'',''failed'',''dead'',''skipped'')),\n  attempt_count int not null default 0,\n  last_error text,\n  sent_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint notification_deliveries_uq unique (outbox_id, device_token_id)\n);\ncreate index if not exists idx_notif_deliveries_outbox on public.notification_deliveries (outbox_id);\nalter table public.notification_deliveries enable row level security;\nrevoke all on public.notification_deliveries from anon, authenticated;\ngrant select, insert, update, delete on public.notification_deliveries to service_role;\n\ncreate or replace function public.notification_outbox_claim(p_owner text, p_limit int default 10, p_lease_seconds int default 60)\nreturns setof public.notification_outbox language plpgsql security definer set search_path to ''public'' as $$\nbegin\n  return query\n  with cte as (\n    select o.id from public.notification_outbox o\n    where o.status in (''pending'',''failed'') and o.next_attempt_at <= now()\n    order by o.next_attempt_at asc\n    limit greatest(1, p_limit)\n    for update skip locked\n  )\n  update public.notification_outbox o\n    set status=''leased'', lease_owner=p_owner, leased_until=now() + make_interval(secs => greatest(1,p_lease_seconds)), updated_at=now()\n    from cte where o.id = cte.id\n    returning o.*;\nend $$;\n\ncreate or replace function public.notification_outbox_reclaim_expired()\nreturns int language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_n int;\nbegin\n  update public.notification_outbox set status=''pending'', lease_owner=null, leased_until=null, updated_at=now()\n    where status=''leased'' and leased_until is not null and leased_until < now();\n  get diagnostics v_n = row_count;\n  return v_n;\nend $$;\n\ncreate or replace function public.notification_outbox_mark_sent(p_id uuid)\nreturns boolean language sql security definer set search_path to ''public'' as $$\n  update public.notification_outbox set status=''sent'', lease_owner=null, leased_until=null, updated_at=now()\n  where id=p_id returning true;\n$$;\n\ncreate or replace function public.notification_outbox_mark_failed(p_id uuid, p_error text, p_backoff_seconds int default 60)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_attempt int; v_max int; v_dead boolean;\nbegin\n  update public.notification_outbox\n    set attempt_count = attempt_count + 1, last_error = left(coalesce(p_error,''''),1000),\n        lease_owner=null, leased_until=null,\n        next_attempt_at = now() + make_interval(secs => greatest(1,p_backoff_seconds)), updated_at=now()\n    where id=p_id\n    returning attempt_count, max_attempts into v_attempt, v_max;\n  if v_attempt is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n  v_dead := v_attempt >= v_max;\n  update public.notification_outbox set status = case when v_dead then ''dead'' else ''failed'' end where id=p_id;\n  return jsonb_build_object(''ok'',true,''attempt'',v_attempt,''dead'',v_dead);\nend $$;\n\ncreate or replace function public.notification_create_deliveries(p_outbox_id uuid)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_recipient uuid; v_etype text; v_allowed boolean; v_created int := 0;\nbegin\n  select recipient_user_id, event_type into v_recipient, v_etype from public.notification_outbox where id=p_outbox_id;\n  if v_recipient is null then return jsonb_build_object(''ok'',false,''code'',''OUTBOX_NOT_FOUND''); end if;\n  v_allowed := public.notification_delivery_allowed(v_recipient, v_etype);\n  if not v_allowed then\n    return jsonb_build_object(''ok'',true,''created'',0,''suppressed'',true);\n  end if;\n  insert into public.notification_deliveries (outbox_id, device_token_id)\n    select p_outbox_id, dt.id from public.device_tokens dt\n    where dt.user_id = v_recipient and dt.revoked_at is null\n  on conflict (outbox_id, device_token_id) do nothing;\n  get diagnostics v_created = row_count;\n  return jsonb_build_object(''ok'',true,''created'',v_created,''suppressed'',false);\nend $$;\n\ncreate or replace function public.notification_delivery_mark_sent(p_id uuid)\nreturns boolean language sql security definer set search_path to ''public'' as $$\n  update public.notification_deliveries set status=''sent'', sent_at=now(), updated_at=now() where id=p_id returning true;\n$$;\n\ncreate or replace function public.notification_delivery_mark_failed(p_id uuid, p_error text, p_invalid_token boolean default false)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_token_id uuid;\nbegin\n  update public.notification_deliveries\n    set attempt_count = attempt_count + 1, last_error = left(coalesce(p_error,''''),1000),\n        status = case when p_invalid_token then ''dead'' else ''failed'' end, updated_at=now()\n    where id=p_id returning device_token_id into v_token_id;\n  if v_token_id is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n  if p_invalid_token then perform public.revoke_device_token(v_token_id); end if;\n  return jsonb_build_object(''ok'',true,''invalid_token'',p_invalid_token);\nend $$;\n\nrevoke all on function public.notification_outbox_claim(text,int,int) from public, anon, authenticated;\nrevoke all on function public.notification_outbox_reclaim_expired() from public, anon, authenticated;\nrevoke all on function public.notification_outbox_mark_sent(uuid) from public, anon, authenticated;\nrevoke all on function public.notification_outbox_mark_failed(uuid,text,int) from public, anon, authenticated;\nrevoke all on function public.notification_create_deliveries(uuid) from public, anon, authenticated;\nrevoke all on function public.notification_delivery_mark_sent(uuid) from public, anon, authenticated;\nrevoke all on function public.notification_delivery_mark_failed(uuid,text,boolean) from public, anon, authenticated;\ngrant execute on function public.notification_outbox_claim(text,int,int) to service_role;\ngrant execute on function public.notification_outbox_reclaim_expired() to service_role;\ngrant execute on function public.notification_outbox_mark_sent(uuid) to service_role;\ngrant execute on function public.notification_outbox_mark_failed(uuid,text,int) to service_role;\ngrant execute on function public.notification_create_deliveries(uuid) to service_role;\ngrant execute on function public.notification_delivery_mark_sent(uuid) to service_role;\ngrant execute on function public.notification_delivery_mark_failed(uuid,text,boolean) to service_role;\n\ncommit;"], "idempotency_key": null}, {"name": "p2_25_pay_due_payouts_convergence_153", "version": "20260720083205", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["begin;\nset local lock_timeout=''5s'';\n\nalter table public.payout_run_items add column if not exists withholding_cents bigint not null default 0;\nalter table public.payout_run_items add column if not exists net_paid_cents bigint;\n\ndo $$\nbegin\n  if not exists (select 1 from pg_constraint where conname=''payout_run_items_source_global_uq'' and conrelid=''public.payout_run_items''::regclass) then\n    alter table public.payout_run_items add constraint payout_run_items_source_global_uq unique (source_type, source_id);\n  end if;\nend $$;\n\ncreate or replace function public.pay_due_payouts_for_run(\n  p_run_date date,\n  p_idempotency_key text default null,\n  p_dry_run boolean default true\n)\nreturns table (\n  run_id uuid,\n  paid_count integer,\n  skipped_no_account integer,\n  total_mentor_cents bigint,\n  total_withholding_cents bigint,\n  total_net_cents bigint,\n  dry_run boolean\n)\nlanguage plpgsql security definer set search_path = public\nas $function$\ndeclare\n  v_idem text := coalesce(p_idempotency_key, ''payout:'' || to_char(p_run_date, ''YYYY-MM''));\n  v_cutoff timestamptz := date_trunc(''month'', p_run_date::timestamp) - interval ''1 second'';\n  v_run public.payout_runs%rowtype;\n  v_run_id uuid;\n  rec record;\n  v_ledger_id uuid; v_item_id uuid; v_has_account boolean;\n  v_paid int := 0; v_skipped int := 0;\n  v_total bigint := 0; v_total_wh bigint := 0; v_total_net bigint := 0;\n  v_withholding bigint; v_net bigint; v_wh_ledger_id uuid;\nbegin\n  if not p_dry_run then\n    select * into v_run from public.payout_runs where idempotency_key = v_idem;\n    if found then\n      v_run_id := v_run.id;\n      if v_run.status = ''completed'' then\n        return query select v_run.id, v_run.mentor_count, 0, v_run.total_mentor_cents,\n          coalesce((select sum(withholding_cents) from public.payout_run_items where payout_run_id=v_run.id),0),\n          coalesce((select sum(net_paid_cents) from public.payout_run_items where payout_run_id=v_run.id),0), false;\n        return;\n      end if;\n    else\n      insert into public.payout_runs (run_date, cutoff_end, status, idempotency_key)\n      values (p_run_date, v_cutoff, ''executing'', v_idem) returning id into v_run_id;\n    end if;\n  end if;\n\n  for rec in\n    select d.* from public.due_payouts d\n    where d.completion_ts <= v_cutoff\n      and not exists (select 1 from public.payout_run_items i where i.source_type=d.source_type and i.source_id=d.source_id)\n    order by d.mentor_id, d.source_type, d.completion_ts\n  loop\n    select coalesce(nullif(trim(mp.payout_account_number), ''''), '''') <> '''' into v_has_account\n      from public.mentor_profiles mp where mp.user_id = rec.mentor_id;\n    if coalesce(v_has_account, false) = false then\n      v_skipped := v_skipped + 1; continue;\n    end if;\n\n    v_withholding := floor(rec.mentor_amount_cents::numeric * 0.033)::bigint;\n    v_net := rec.mentor_amount_cents - v_withholding;\n\n    if p_dry_run then\n      v_paid := v_paid + 1; v_total := v_total + rec.mentor_amount_cents;\n      v_total_wh := v_total_wh + v_withholding; v_total_net := v_total_net + v_net;\n      continue;\n    end if;\n\n    v_ledger_id := null;\n    if rec.source_type = ''custom_request'' then\n      perform public.record_custom_order_escrow_payout(rec.source_id);\n      select id into v_ledger_id from public.cash_ledger\n        where idempotency_key = ''cr_payout_'' || rec.source_id::text and reason=''custom_order_escrow_payout'' limit 1;\n    elsif rec.source_type = ''individual_question'' then\n      perform public.release_individual_question_payout(rec.source_id);\n      select id into v_ledger_id from public.cash_ledger\n        where idempotency_key = ''iq_payout:'' || rec.source_id::text and reason=''individual_question_payout'' limit 1;\n    elsif rec.source_type = ''subscription'' then\n      insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n      values (rec.mentor_id, rec.mentor_amount_cents, ''subscription_settlement_payout'',\n              ''subscription_settlement_items'', rec.source_id, ''sub_payout:'' || rec.source_id::text)\n      on conflict (idempotency_key) do nothing returning id into v_ledger_id;\n      if v_ledger_id is not null then\n        insert into public.cash_wallets (user_id, balance_cents) values (rec.mentor_id, 0) on conflict (user_id) do nothing;\n        update public.cash_wallets w set balance_cents = w.balance_cents + rec.mentor_amount_cents where w.user_id = rec.mentor_id;\n      else\n        select id into v_ledger_id from public.cash_ledger where idempotency_key=''sub_payout:'' || rec.source_id::text limit 1;\n      end if;\n      update public.subscription_settlement_items set status=''paid'', paid_at=coalesce(paid_at, now()), updated_at=now()\n        where id = rec.source_id and status <> ''paid'';\n    else\n      continue;\n    end if;\n\n    if v_withholding > 0 then\n      v_wh_ledger_id := null;\n      insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n      values (rec.mentor_id, -v_withholding, ''payout_withholding_3_3pct'', rec.source_type, rec.source_id,\n              ''wh:'' || rec.source_type || '':'' || rec.source_id::text)\n      on conflict (idempotency_key) do nothing returning id into v_wh_ledger_id;\n      if v_wh_ledger_id is not null then\n        update public.cash_wallets w set balance_cents = w.balance_cents - v_withholding where w.user_id = rec.mentor_id;\n      end if;\n    end if;\n\n    insert into public.payout_run_items (\n      payout_run_id, mentor_id, source_type, source_id,\n      gross_cents, platform_fee_cents, mentor_amount_cents, fee_rate, ledger_id,\n      withholding_cents, net_paid_cents\n    ) values (\n      v_run_id, rec.mentor_id, rec.source_type, rec.source_id,\n      rec.gross_cents, rec.platform_fee_cents, rec.mentor_amount_cents, rec.fee_rate, v_ledger_id,\n      v_withholding, v_net\n    )\n    on conflict (source_type, source_id) do nothing\n    returning id into v_item_id;\n\n    if v_item_id is not null then\n      v_paid := v_paid + 1;\n      v_total := v_total + rec.mentor_amount_cents;\n      v_total_wh := v_total_wh + v_withholding;\n      v_total_net := v_total_net + v_net;\n    end if;\n  end loop;\n\n  if not p_dry_run then\n    update public.payout_runs\n    set status=''completed'',\n        mentor_count=(select count(distinct mentor_id) from public.payout_run_items where payout_run_id=v_run_id),\n        total_mentor_cents=(select coalesce(sum(mentor_amount_cents),0) from public.payout_run_items where payout_run_id=v_run_id),\n        executed_at=now(), updated_at=now()\n    where id=v_run_id;\n  end if;\n\n  return query select v_run_id, v_paid, v_skipped, v_total, v_total_wh, v_total_net, p_dry_run;\nend;\n$function$;\n\nrevoke all on function public.pay_due_payouts_for_run(date, text, boolean) from public, anon, authenticated;\ngrant execute on function public.pay_due_payouts_for_run(date, text, boolean) to service_role;\n\ncommit;"], "idempotency_key": null}, {"name": "p1_10_deletion_operational_adapters_154", "version": "20260720085838", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["begin;\nset local lock_timeout=''5s'';\n\ndrop policy if exists adg_storage_block_insert_when_deleting on storage.objects;\ncreate policy adg_storage_block_insert_when_deleting on storage.objects\n  as restrictive for insert to authenticated\n  with check (not public.account_deletion_write_blocked(auth.uid()));\n\ndrop policy if exists adg_storage_block_update_when_deleting on storage.objects;\ncreate policy adg_storage_block_update_when_deleting on storage.objects\n  as restrictive for update to authenticated\n  using (not public.account_deletion_write_blocked(auth.uid()))\n  with check (not public.account_deletion_write_blocked(auth.uid()));\n\nalter table public.account_deletion_jobs add column if not exists lease_owner text;\nalter table public.account_deletion_jobs add column if not exists leased_until timestamptz;\n\ncreate or replace function public.account_deletion_claim(p_owner text, p_limit int default 5, p_lease_seconds int default 300)\nreturns setof public.account_deletion_jobs language plpgsql security definer set search_path to ''public'' as $$\nbegin\n  return query\n  with cte as (\n    select j.id from public.account_deletion_jobs j\n    where j.state in (''pending'',''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted'')\n      and (j.next_attempt_at is null or j.next_attempt_at <= now())\n      and (j.leased_until is null or j.leased_until < now())\n    order by j.requested_at asc\n    limit greatest(1, p_limit)\n    for update skip locked\n  )\n  update public.account_deletion_jobs j\n    set lease_owner = p_owner, leased_until = now() + make_interval(secs => greatest(1, p_lease_seconds)), updated_at = now()\n    from cte where j.id = cte.id\n    returning j.*;\nend $$;\n\ncreate or replace function public.account_deletion_reclaim_expired()\nreturns int language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_n int;\nbegin\n  update public.account_deletion_jobs set lease_owner=null, leased_until=null, updated_at=now()\n    where leased_until is not null and leased_until < now()\n      and state not in (''completed'',''canceled'',''failed'');\n  get diagnostics v_n = row_count;\n  return v_n;\nend $$;\n\ncreate or replace function public.account_deletion_forfeit_and_anonymize(p_user_id uuid)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_state text; v_balance bigint; v_ledger_id uuid;\nbegin\n  select state into v_state from public.account_deletion_jobs where user_id = p_user_id for update;\n  if v_state is null then return jsonb_build_object(''ok'',false,''code'',''JOB_NOT_FOUND''); end if;\n  if v_state <> ''storage_purged'' then return jsonb_build_object(''ok'',false,''code'',''WRONG_STATE'',''state'',v_state); end if;\n\n  select balance_cents into v_balance from public.cash_wallets where user_id = p_user_id for update;\n  if v_balance is not null and v_balance > 0 then\n    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n    values (p_user_id, -v_balance, ''account_deletion_forfeit'', ''account_deletion'', p_user_id, ''acct_del_forfeit:''||p_user_id::text)\n    on conflict (idempotency_key) do nothing\n    returning id into v_ledger_id;\n    if v_ledger_id is not null then\n      update public.cash_wallets set balance_cents = 0 where user_id = p_user_id;\n    end if;\n  end if;\n\n  perform public.anonymize_user_for_deletion(p_user_id, ''account_deletion'');\n  return jsonb_build_object(''ok'',true,''forfeited_cents'',coalesce(v_balance,0),''ledger_id'',v_ledger_id);\nend $$;\n\nrevoke all on function public.account_deletion_claim(text,int,int) from public, anon, authenticated;\nrevoke all on function public.account_deletion_reclaim_expired() from public, anon, authenticated;\nrevoke all on function public.account_deletion_forfeit_and_anonymize(uuid) from public, anon, authenticated;\ngrant execute on function public.account_deletion_claim(text,int,int) to service_role;\ngrant execute on function public.account_deletion_reclaim_expired() to service_role;\ngrant execute on function public.account_deletion_forfeit_and_anonymize(uuid) to service_role;\n\ncommit;"], "idempotency_key": null}, {"name": "p1_11_iq_notification_atomization_155", "version": "20260720090434", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["begin;\nset local lock_timeout=''5s'';\n\ncreate or replace function public.iq_notify_status_transition()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_recipient uuid; v_type text; v_title text; v_body text; v_mentor uuid;\nbegin\n  v_mentor := coalesce(NEW.claimed_mentor_id, NEW.designated_mentor_id);\n  if NEW.status = ''answered'' then\n    v_recipient := NEW.student_id; v_type := ''individual_question_answered'';\n    v_title := ''개별 질문 답변 도착''; v_body := ''요청한 개별 질문에 답변이 등록됐어요.'';\n  elsif NEW.status = ''released'' then\n    v_recipient := v_mentor; v_type := ''individual_question_released'';\n    v_title := ''개별 질문 정산 확정''; v_body := ''학생이 답변을 확정해 정산이 확정됐어요.'';\n  elsif NEW.status = ''claimed'' then\n    v_recipient := NEW.student_id; v_type := ''individual_question_claimed'';\n    v_title := ''개별 질문 수락됨''; v_body := ''멘토가 개별 질문을 수락했어요.'';\n  elsif NEW.status = ''refunded'' then\n    v_recipient := NEW.student_id; v_type := ''individual_question_expired_refunded'';\n    v_title := ''개별 질문 환불''; v_body := ''개별 질문이 만료되어 캐시가 환불됐어요.'';\n  else\n    return NEW;\n  end if;\n  if v_recipient is not null then\n    perform public.record_domain_notification(\n      v_recipient, v_type || '':'' || NEW.id::text, v_type || '':'' || NEW.id::text, v_type,\n      v_title, v_body, null,\n      jsonb_build_object(''question_id'', NEW.id, ''status'', NEW.status),\n      jsonb_build_object(''question_id'', NEW.id));\n  end if;\n  return NEW;\nend $$;\n\ndrop trigger if exists trg_iq_notify_status on public.individual_questions;\ncreate trigger trg_iq_notify_status\n  after update on public.individual_questions\n  for each row when (old.status is distinct from new.status)\n  execute function public.iq_notify_status_transition();\n\ncreate or replace function public.iq_notify_assigned()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\nbegin\n  if NEW.designated_mentor_id is not null then\n    perform public.record_domain_notification(\n      NEW.designated_mentor_id, ''individual_question_assigned:'' || NEW.id::text,\n      ''individual_question_assigned:'' || NEW.id::text, ''individual_question_assigned'',\n      ''새 지정 개별 질문'', ''학생이 나를 지정해 개별 질문을 보냈어요.'', null,\n      jsonb_build_object(''question_id'', NEW.id), jsonb_build_object(''question_id'', NEW.id));\n  end if;\n  return NEW;\nend $$;\n\ndrop trigger if exists trg_iq_notify_assigned on public.individual_questions;\ncreate trigger trg_iq_notify_assigned\n  after insert on public.individual_questions\n  for each row execute function public.iq_notify_assigned();\n\ncreate or replace function public.iqm_notify_message()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_student uuid; v_mentor uuid; v_recipient uuid;\nbegin\n  select student_id, coalesce(claimed_mentor_id, designated_mentor_id)\n    into v_student, v_mentor from public.individual_questions where id = NEW.question_id;\n  if NEW.author_id = v_student then v_recipient := v_mentor;\n  elsif NEW.author_id = v_mentor then v_recipient := v_student;\n  else v_recipient := null; end if;\n  if v_recipient is not null then\n    perform public.record_domain_notification(\n      v_recipient, ''individual_question_message:'' || NEW.id::text,\n      ''individual_question_message:'' || NEW.id::text, ''individual_question_message'',\n      ''개별 질문 새 메시지'', ''개별 질문에 새 메시지가 도착했어요.'', null,\n      jsonb_build_object(''question_id'', NEW.question_id, ''message_id'', NEW.id),\n      jsonb_build_object(''question_id'', NEW.question_id, ''message_id'', NEW.id));\n  end if;\n  return NEW;\nend $$;\n\ndrop trigger if exists trg_iqm_notify_message on public.individual_question_messages;\ncreate trigger trg_iqm_notify_message\n  after insert on public.individual_question_messages\n  for each row execute function public.iqm_notify_message();\n\ncommit;"], "idempotency_key": null}, {"name": "p2_25_payout_scheduler_foundation_156", "version": "20260720091401", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["begin;\nset local lock_timeout=''5s'';\n\ncreate table if not exists public.payout_settings (\n  id int primary key default 1 check (id = 1),\n  scheduler_enabled boolean not null default false,\n  updated_at timestamptz not null default now()\n);\ninsert into public.payout_settings (id, scheduler_enabled) values (1, false) on conflict (id) do nothing;\nalter table public.payout_settings enable row level security;\nrevoke all on public.payout_settings from anon, authenticated;\ngrant select, insert, update on public.payout_settings to service_role;\n\ncreate or replace function public.payout_reconciliation_report(p_run_date date)\nreturns table (\n  source_type text, source_id uuid, mentor_id uuid,\n  mentor_amount_cents bigint, withholding_cents bigint, net_paid_cents bigint,\n  eligible boolean, reason text\n) language sql stable security definer set search_path to ''public'' as $$\n  with cutoff as (select (date_trunc(''month'', p_run_date::timestamp) - interval ''1 second'') as ts)\n  select\n    d.source_type, d.source_id, d.mentor_id,\n    d.mentor_amount_cents,\n    floor(d.mentor_amount_cents::numeric * 0.033)::bigint as withholding_cents,\n    d.mentor_amount_cents - floor(d.mentor_amount_cents::numeric * 0.033)::bigint as net_paid_cents,\n    (case when exists (select 1 from public.payout_run_items i where i.source_type=d.source_type and i.source_id=d.source_id) then false\n          when d.completion_ts > (select ts from cutoff) then false\n          when coalesce(nullif(trim(mp.payout_account_number),''''),'''') = '''' then false\n          else true end) as eligible,\n    (case when exists (select 1 from public.payout_run_items i where i.source_type=d.source_type and i.source_id=d.source_id) then ''already_paid''\n          when d.completion_ts > (select ts from cutoff) then ''not_due''\n          when coalesce(nullif(trim(mp.payout_account_number),''''),'''') = '''' then ''no_payout_account''\n          else ''eligible'' end) as reason\n  from public.due_payouts d\n  left join public.mentor_profiles mp on mp.user_id = d.mentor_id\n  order by d.mentor_id, d.source_type;\n$$;\nrevoke all on function public.payout_reconciliation_report(date) from public, anon, authenticated;\ngrant execute on function public.payout_reconciliation_report(date) to service_role;\n\ncreate or replace function public.run_scheduled_payout(p_run_date date, p_force_dry_run boolean default false)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_enabled boolean; v_dry boolean; v_res record;\nbegin\n  select scheduler_enabled into v_enabled from public.payout_settings where id = 1;\n  v_enabled := coalesce(v_enabled, false);\n  v_dry := (not v_enabled) or coalesce(p_force_dry_run, false);\n  select * into v_res from public.pay_due_payouts_for_run(p_run_date, null, v_dry);\n  return jsonb_build_object(\n    ''ok'', true, ''scheduler_enabled'', v_enabled, ''dry_run'', v_res.dry_run,\n    ''run_id'', v_res.run_id, ''paid_count'', v_res.paid_count, ''skipped_no_account'', v_res.skipped_no_account,\n    ''total_mentor_cents'', v_res.total_mentor_cents, ''total_withholding_cents'', v_res.total_withholding_cents,\n    ''total_net_cents'', v_res.total_net_cents);\nend $$;\nrevoke all on function public.run_scheduled_payout(date, boolean) from public, anon, authenticated;\ngrant execute on function public.run_scheduled_payout(date, boolean) to service_role;\n\ncommit;"], "idempotency_key": null}, {"name": "public_defacl_functions_hardening", "version": "20260729000000", "rollback": null, "created_by": null, "statements": ["-- 20260729000000_public_defacl_functions_hardening.sql\n-- public 스키마 ''함수'' 기본 권한의 hardened 전환 — postgres 소유 defacl 행 기준.\n--\n-- 근거(preview branch 실측, 2026-08-04):\n--   * branch(부모 원장만 재생된 신규 프로젝트) defacl(f) =\n--     {postgres=X, anon=X, authenticated=X, service_role=X}  ← permissive 원본\n--   * 부모 ''현재'' defacl(f), grantor=postgres = {postgres=X}  ← hardened\n--     (grantor=supabase_admin 행은 permissive 그대로 — 함수 소유자가 postgres 이므로\n--      실제 신규 함수에 적용되는 것은 postgres 행이다)\n--   * 원장 M13(20260730095438_comments_author_label_denormalize)의 자체 검사 ③ 는\n--     신규 트리거 함수 2종에 anon/authenticated EXECUTE 가 **없어야** 통과한다.\n--     그런데 그 파일의 하드닝은 `REVOKE ALL ... FROM PUBLIC` 뿐이라 명시 역할 부여를\n--     제거하지 못한다 → permissive defacl 상태에서는 게이트가 구조적으로 통과 불가.\n--   * 실측: branch 재생 중 037(M13)이 `S2_M13_SELFCHECK: ... (matched=0)` 로 실패.\n--     따라서 이 전환은 **M13 이전**에 이미 적용돼 있었다(out-of-band, 정확 시각 UNRECOVERABLE).\n--\n-- ⚠️ UNVERIFIED_ON_REAL_PLATFORM: 이 배치·내용은 위 실패 증거로부터 도출했으나,\n--    실제 branch 재생으로 재검증하지 못했다(브랜치 시간 상한). 신규 branch 1회로 확인 필요.\nalter default privileges in schema public\n  revoke execute on functions from public, anon, authenticated, service_role"], "idempotency_key": null}, {"name": "20260729211929_mentor_profile_privileged_column_guard", "version": "20260731095050", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260729211929_mentor_profile_privileged_column_guard.sql (S2 M0)\n-- =============================================================================\n-- XW-02 선행 완화 — mentor_profiles 특권 컬럼(verification_status·cap_limit) 가드.\n-- 정본 계약: docs/contracts/api_web_v1_contract_v1_1.md §20.5 (rev 8 A-7 — 필수화).\n--   - BEFORE INSERT OR UPDATE 트리거로 특권 컬럼 변경을\n--     service_role / JWT 없는 직접 DB 세션 / 기존 admin 으로 제한한다.\n--   - TG_OP 선분기: INSERT 에서 OLD 는 NULL 이므로 OLD 비교 전에 반드시 분기한다.\n--   - 비교는 IS DISTINCT FROM 만 사용한다(일반 <> 금지 — NULL-safe).\n--   - 트리거 함수 생성과 같은 트랜잭션에서 PUBLIC EXECUTE 를 회수한다.\n--   - 119(enforce_users_role_guard)·리뷰 트리거의 기확립 관행을 복제한 심층 방어다.\n-- 범위 밖(금지): mentor_profiles GRANT 회수(전면 회수는 M11), 다른 트리거·컬럼 변경.\n-- rollback 정본: supabase/rollback/20260729211929_mentor_profile_privileged_column_guard_rollback.sql\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- A. 가드 함수 (계약 §20.5 — TG_OP 선분기 + 3분기 허용 구조)\n-- -----------------------------------------------------------------------------\nCREATE OR REPLACE FUNCTION public.enforce_mentor_profile_privileged_guard()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $$\nDECLARE\n  v_jwt_role  text;\n  v_sensitive boolean;\nBEGIN\n  -- TG_OP 선분기: INSERT 에서 OLD 는 NULL 이므로 OLD 비교 전에 반드시 분기한다.\n  IF tg_op = ''INSERT'' THEN\n    -- 기본값 대비 판정. 28 하드코딩은 컬럼 기본값 변경 시 드리프트하는 취약점이다 —\n    -- 기본값을 바꾸는 마이그레이션은 이 조건을 함께 갱신해야 한다(주석 의무).\n    v_sensitive := (new.verification_status IS DISTINCT FROM ''pending''\n                    OR new.cap_limit IS DISTINCT FROM 28);\n  ELSE  -- ''UPDATE''\n    v_sensitive := (new.verification_status IS DISTINCT FROM old.verification_status\n                    OR new.cap_limit IS DISTINCT FROM old.cap_limit);\n  END IF;\n\n  IF v_sensitive THEN\n    v_jwt_role := auth.jwt() ->> ''role'';\n    IF v_jwt_role = ''service_role'' THEN RETURN new; END IF;   -- 서버 경유\n    IF v_jwt_role IS NULL THEN RETURN new; END IF;            -- SQL Editor·migration\n    IF EXISTS (SELECT 1 FROM public.users u\n               WHERE u.id = (SELECT auth.uid()) AND u.role = ''admin'') THEN\n      RETURN new;                                             -- 기존 관리자\n    END IF;\n    RAISE EXCEPTION ''MENTOR_PROFILE_PRIVILEGED_COLUMN_FORBIDDEN''\n      USING errcode = ''42501'';\n  END IF;\n  RETURN new;\nEND $$;\n\nCOMMENT ON FUNCTION public.enforce_mentor_profile_privileged_guard() IS\n  ''S2 M0(계약 §20.5): mentor_profiles.verification_status·cap_limit 변경을 service_role/JWT 없는 세션/admin 으로 제한하는 BEFORE INSERT OR UPDATE 가드.'';\n\n-- [필수 — rev 8 A-7] 트리거 함수 생성과 동일 트랜잭션에서 PUBLIC EXECUTE 회수:\nREVOKE ALL ON FUNCTION public.enforce_mentor_profile_privileged_guard()\nFROM PUBLIC;\n\n-- -----------------------------------------------------------------------------\n-- B. 트리거 (이름·WHEN 조건은 계약 §20.5 와 동일 — 재실행 안전은 저장소 관행)\n-- -----------------------------------------------------------------------------\n-- UPDATE: 특권 컬럼이 바뀔 때만\ndrop trigger if exists trg_mentor_profile_privileged_guard_upd on public.mentor_profiles;\nCREATE TRIGGER trg_mentor_profile_privileged_guard_upd\n  BEFORE UPDATE ON public.mentor_profiles\n  FOR EACH ROW\n  WHEN (old.verification_status IS DISTINCT FROM new.verification_status\n        OR old.cap_limit IS DISTINCT FROM new.cap_limit)\n  EXECUTE FUNCTION public.enforce_mentor_profile_privileged_guard();\n\n-- INSERT: ''pending'' 이외의 verification_status 또는 기본값(28) 이외의 cap_limit 지정을 막는다 (C6)\n--   (구 WHEN 조건 new.cap_limit IS NOT NULL 은 기본값 28 NOT NULL 때문에 항상 참 — 폐기)\ndrop trigger if exists trg_mentor_profile_privileged_guard_ins on public.mentor_profiles;\nCREATE TRIGGER trg_mentor_profile_privileged_guard_ins\n  BEFORE INSERT ON public.mentor_profiles\n  FOR EACH ROW\n  WHEN (new.verification_status IS DISTINCT FROM ''pending''\n        OR new.cap_limit IS DISTINCT FROM 28)\n  EXECUTE FUNCTION public.enforce_mentor_profile_privileged_guard();\n\ncommit;\n"], "idempotency_key": null}, {"name": "20260729211941_weekly_usage_pair_party_guard", "version": "20260731095136", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260729211941_weekly_usage_pair_party_guard.sql (S2 M15)\n-- =============================================================================\n-- XW-01 레거시 하드닝 — public.get_weekly_question_usage(uuid,uuid) 에\n-- NULL-safe pair-party 가드를 추가한다(rev 8 A-8 — 오너 확정 형태 고정).\n-- 정본 계약: docs/contracts/api_web_v1_contract_v1_1.md §7 F1 · §20.2 M15.\n--   - 함수 첫 실행부에 가드만 추가한다. 그 외 본문은 098(현행 정본)과 문자 동일.\n--   - 비교는 IS DISTINCT FROM 만 사용한다(IN·NOT IN·<>·NOT(...) 대체 금지 — NULL-safe).\n--   - 허용: service_role JWT / 학생 본인(auth.uid()=p_student_id) /\n--           멘토 당사자(auth.uid()=p_mentor_id). 그 외(anon·제3자)는 42501 거부.\n--   - signature·return(json)·volatility·SECURITY DEFINER·search_path=public·\n--     owner·ACL 전부 불변. anon EXECUTE 는 이번 M15 에서 회수하지 않는다(U-08 별도).\n--   - 기존 NULL 인자 검사·한도 매핑(limited 4/standard 9/premium 999)·anchor 7일\n--     롤링·반환 JSON 의미 불변.\n-- 유지 확인 대상(계약 §7 F1): qna_create_question_thread(학생 본인) ·\n--   qt_direct_write_guard(학생 본인) · 웹 멘토 질문방(멘토 ID = auth.uid()) ·\n--   service_role 서버 경로(weeklyQuestionUsageServer.ts, e2e admin).\n-- rollback 정본: supabase/rollback/20260729211941_weekly_usage_pair_party_guard_rollback.sql\n--   (가드 없는 098 전체 정의를 명시적으로 복원)\n-- =============================================================================\n\nbegin;\n\ncreate or replace function public.get_weekly_question_usage(\n  p_student_id uuid,\n  p_mentor_id uuid\n)\nreturns json\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\ndeclare\n  v_anchor timestamptz;\n  v_week_start timestamptz;\n  v_week_end timestamptz;\n  v_elapsed_seconds numeric;\n  v_period_index integer;\n  v_used integer := 0;\n  v_plan_tier text;\n  v_limit integer := 0;\nbegin\n  -- [S2 M15] NULL-safe pair-party 가드 (계약 §7 F1 — 오너 확정 형태 고정).\n  IF (auth.jwt() ->> ''role'') IS DISTINCT FROM ''service_role''\n     AND auth.uid() IS DISTINCT FROM p_student_id\n     AND auth.uid() IS DISTINCT FROM p_mentor_id\n  THEN\n    RAISE EXCEPTION ''NOT_PAIR_PARTY''\n      USING ERRCODE = ''42501'';\n  END IF;\n\n  if p_student_id is null or p_mentor_id is null then\n    raise exception ''p_student_id and p_mentor_id are required'';\n  end if;\n\n  select\n    s.plan_tier,\n    coalesce(s.started_at, s.created_at)\n  into v_plan_tier, v_anchor\n  from public.subscriptions s\n  where s.student_id = p_student_id\n    and s.mentor_id = p_mentor_id\n    and lower(coalesce(s.status, '''')) = ''active''\n  order by s.created_at desc\n  limit 1;\n\n  v_limit := case lower(coalesce(v_plan_tier, ''''))\n    when ''limited'' then 4\n    when ''standard'' then 9\n    when ''premium'' then 999\n    else 0\n  end;\n\n  if v_anchor is not null then\n    v_elapsed_seconds := extract(epoch from (now() - v_anchor));\n    v_period_index := greatest(0, floor(v_elapsed_seconds / 604800.0)::integer);\n    v_week_start := v_anchor + (v_period_index * interval ''7 days'');\n    v_week_end := v_week_start + interval ''7 days'';\n\n    select count(*)::integer into v_used\n    from public.question_threads qt\n    inner join public.mentor_student_rooms r on r.id = qt.mentor_student_room_id\n    where r.student_id = p_student_id\n      and r.mentor_id = p_mentor_id\n      and lower(coalesce(qt.status, '''')) in (''pending'', ''answered'', ''confirmed'', ''closed'', ''archived'')\n      and qt.created_at >= v_week_start\n      and qt.created_at < v_week_end;\n  end if;\n\n  return json_build_object(\n    ''used'', coalesce(v_used, 0),\n    ''limit'', v_limit,\n    ''plan_tier'', v_plan_tier,\n    ''remaining'', greatest(0, v_limit - coalesce(v_used, 0)),\n    ''can_ask'', coalesce(v_used, 0) < v_limit,\n    ''week_start'', v_week_start,\n    ''week_end'', v_week_end\n  );\nend;\n$function$;\n\ncommit;\n"], "idempotency_key": null}, {"name": "20260730095435_api_web_v1_schemas", "version": "20260731100313", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260730095435_api_web_v1_schemas.sql (S2 M1)\n-- =============================================================================\n-- api_web_v1(외부 노출)·core_private(내부 전용) schema 2종 생성 + 권한 경계.\n-- 정본 계약: docs/contracts/api_web_v1_contract_v1_1.md §5.1~§5.3 · §10.1 · §20.2 M1.\n--   - 생성 schema 는 정확히 2개다. 이 단계에서 함수·view·테이블은 0건 생성한다.\n--   - api_web_v1 : PUBLIC 권한 전면 회수 → anon·authenticated·service_role USAGE.\n--   - core_private: PUBLIC 권한 전면 회수. PUBLIC·anon·authenticated·service_role\n--     어디에도 USAGE 를 주지 않는다(§10.1 — rev 8 A-2·A-6: 내부 구현부는 api_web_v1\n--     SECDEF wrapper 의 소유자 권한 문맥으로만 호출. service_role USAGE 부여 폐기).\n--   - 두 schema 모두 default privileges 에서 신규 함수의 PUBLIC EXECUTE 를 회수한다\n--     (§5.3.3 — migration 실행 역할(= 함수 소유 역할)이 앞으로 만드는 함수에 적용).\n--   - Data API(Exposed schemas)·PostgREST 설정은 변경하지 않는다 — D-API-W 는\n--     Batch B 이후 별도 플랫폼 단계다(§20.6). core_private 는 절대 노출 금지.\n--   - 부분 생성 상태 은닉 금지: CREATE SCHEMA 에 IF NOT EXISTS 를 쓰지 않고,\n--     사전 게이트에서 기존 동명 schema 발견 시 UNEXPECTED_EXISTING_CONTRACT_OBJECT\n--     로 수정 0건 중단한다(Batch B 지시 §7).\n-- 선행조건: M0(20260729211929) 적용 완료(§20.2.1 — M1 : M0).\n-- rollback 정본: supabase/rollback/20260730095435_api_web_v1_schemas_rollback.sql\n--   (M4 rollback 으로 schema 가 빈 뒤에만 실행 — DROP SCHEMA ... RESTRICT · CASCADE 금지)\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- A. 사전 게이트 — 동명 schema 선재 시 수정 0건 중단 (IF NOT EXISTS 은닉 금지)\n-- -----------------------------------------------------------------------------\nDO $$\nBEGIN\n  IF EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = ''api_web_v1'') THEN\n    RAISE EXCEPTION ''UNEXPECTED_EXISTING_CONTRACT_OBJECT: schema api_web_v1 already exists'';\n  END IF;\n  IF EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = ''core_private'') THEN\n    RAISE EXCEPTION ''UNEXPECTED_EXISTING_CONTRACT_OBJECT: schema core_private already exists'';\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- B. 외부 노출 schema — api_web_v1 (§5.3.1)\n-- -----------------------------------------------------------------------------\nCREATE SCHEMA api_web_v1;\nREVOKE ALL ON SCHEMA api_web_v1 FROM PUBLIC;\nGRANT USAGE ON SCHEMA api_web_v1 TO anon, authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- C. 내부 전용 schema — core_private (§5.3.2 — 외부 역할 완전 봉인)\n-- -----------------------------------------------------------------------------\nCREATE SCHEMA core_private;\nREVOKE ALL ON SCHEMA core_private FROM PUBLIC;\n-- PUBLIC·anon·authenticated·service_role 어디에도 USAGE 를 주지 않는다.\n-- (v1.0 의 GRANT USAGE ... TO service_role 은 폐기 — 계약 §5.3.2 주석 그대로)\n\n-- -----------------------------------------------------------------------------\n-- D. [필수] 신규 함수의 PUBLIC 기본 EXECUTE 차단 (§5.3.3 — 계약 DDL 원문 그대로)\n--    [PG17.6 로컬 실측 기록 — Batch B] per-schema default privilege 는 전역\n--    기본값에 「추가」되는 구조라, 선행 per-schema GRANT 가 없는 상태의 이\n--    REVOKE 는 pg_default_acl 행을 만들지 않으며(저장 no-op), 새 함수의\n--    proacl 은 NULL(= hardwired default, PUBLIC EXECUTE 포함)로 생성됨을\n--    프로브로 확인했다. 따라서 실효 방어선은 계약 §5.3 주의 1·§10.3 이 이미\n--    의무화한 「함수 생성과 같은 트랜잭션의 명시 REVOKE ALL ... FROM PUBLIC」\n--    (이중 방어의 2층)이다. 이 문장은 계약 DDL 원문 준수 + 전역 default 항목이\n--    생기는 미래 상태 대비로 유지한다. Batch B 는 두 schema 에 함수를 0건\n--    생성하므로 노출 표면이 없고, 함수를 만드는 후속 Batch(M5~)는 §10.3 의\n--    함수별 명시 REVOKE 를 반드시 동반해야 한다.\n-- -----------------------------------------------------------------------------\nALTER DEFAULT PRIVILEGES IN SCHEMA api_web_v1  REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;\nALTER DEFAULT PRIVILEGES IN SCHEMA core_private REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;\n\n-- -----------------------------------------------------------------------------\n-- E. 적용 직후 자가 검증 (§20.3 「M4 이전」 게이트 상당 — PUBLIC 권한 0건 실측)\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_acl text;\nBEGIN\n  -- api_web_v1: 3 role USAGE + PUBLIC 항목 0\n  IF NOT (has_schema_privilege(''anon'', ''api_web_v1'', ''USAGE'')\n          AND has_schema_privilege(''authenticated'', ''api_web_v1'', ''USAGE'')\n          AND has_schema_privilege(''service_role'', ''api_web_v1'', ''USAGE'')) THEN\n    RAISE EXCEPTION ''S2_M1_SELFCHECK: api_web_v1 role USAGE missing'';\n  END IF;\n  SELECT nspacl::text INTO v_acl FROM pg_namespace WHERE nspname = ''api_web_v1'';\n  IF v_acl LIKE ''{=%'' OR v_acl LIKE ''%,=%'' THEN\n    RAISE EXCEPTION ''S2_M1_SELFCHECK: api_web_v1 retains PUBLIC acl entry: %'', v_acl;\n  END IF;\n  -- core_private: 외부 role USAGE 0 + PUBLIC 항목 0\n  IF has_schema_privilege(''anon'', ''core_private'', ''USAGE'')\n     OR has_schema_privilege(''authenticated'', ''core_private'', ''USAGE'')\n     OR has_schema_privilege(''service_role'', ''core_private'', ''USAGE'') THEN\n    RAISE EXCEPTION ''S2_M1_SELFCHECK: core_private must have zero external USAGE'';\n  END IF;\n  SELECT nspacl::text INTO v_acl FROM pg_namespace WHERE nspname = ''core_private'';\n  IF v_acl LIKE ''{=%'' OR v_acl LIKE ''%,=%'' THEN\n    RAISE EXCEPTION ''S2_M1_SELFCHECK: core_private retains PUBLIC acl entry: %'', v_acl;\n  END IF;\n  -- default privileges: 두 schema 의 default ACL 이 PUBLIC 에 무언가를 부여하는\n  -- 행을 갖지 않아야 한다(PG17.6 실측 — 위 REVOKE 는 저장 no-op 이므로 행 0 이\n  -- 정상이며, 행이 있다면 PUBLIC 부여가 없어야 한다. 섹션 D 주석 참조).\n  IF (SELECT count(*)\n        FROM pg_default_acl d JOIN pg_namespace n ON n.oid = d.defaclnamespace\n       WHERE n.nspname IN (''api_web_v1'', ''core_private'')\n         AND (d.defaclacl::text LIKE ''{=%'' OR d.defaclacl::text LIKE ''%,=%'')) > 0 THEN\n    RAISE EXCEPTION ''S2_M1_SELFCHECK: default ACL grants PUBLIC'';\n  END IF;\n  -- 이 단계에서 두 schema 는 비어 있어야 한다(함수·view·테이블 0)\n  IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace\n       WHERE n.nspname IN (''api_web_v1'', ''core_private'')) > 0\n     OR (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n          WHERE n.nspname IN (''api_web_v1'', ''core_private'')) > 0 THEN\n    RAISE EXCEPTION ''S2_M1_SELFCHECK: schemas must be empty at M1'';\n  END IF;\nEND $$;\n\ncommit;\n"], "idempotency_key": null}, {"name": "20260730095436_comments_author_label_baseline_convergence", "version": "20260731100358", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260730095436_comments_author_label_baseline_convergence.sql (S2 MC)\n-- =============================================================================\n-- P0 D-1 해소 — comments.author_label baseline convergence (M13 직전 조건부 수렴).\n-- 정본 계약: docs/audit/s2_3_p0_d1_comments_author_label_remote_drift_contract_20260731.md\n--            §10 채택 계약 · §11 Forward Contract(S1~S5) · §13 멱등성 · §14 잠금.\n--   - 원격 public.comments 에 037 정본 컬럼 author_label 이 부재(드리프트 실측\n--     S2-3 §3.1)하여 M13 게이트 ①이 중단된다. 본 migration 은 M13 「직전」에\n--     실행되어 컬럼을 037 정본 형상(text NOT NULL DEFAULT ''쌤버십 회원'')으로\n--     조건부 수렴한다. M13·M4·기존 SQL 은 바이트 무수정 유지.\n--   - timestamp 20260730095436 은 S2-3 계약 §10 이 지정한 과거 삽입 슬롯의\n--     일회성 고정값이다(M1 20260730095435 < MC < M13 20260730095438 사전순\n--     불변식). 기존 timestamp 정책(§5 채번 절차)의 일반 변경이 아니라\n--     S2-3 P0 D-1 해소 계약에 따른 MC 단일 삽입 예외다.\n--   - 대상은 public.comments.author_label 단독. DML 0 · 다른 컬럼 변경 0 ·\n--     함수·트리거·정책·인덱스·GRANT 변경 0 · community_comments 무접촉 ·\n--     column comment 추가 0 · NOTIFY 없음(schema cache reload 는 운영 절차\n--     — S2-3 §15, 적용 러너 소관).\n--   - 상태 분기(S2-3 §11 — 재량 0 이식):\n--       S1 컬럼 부재(+author_role 부재)  → ADD COLUMN 정확히 1문장\n--       S2 037 정본 형상                 → NOTICE no-op (clean-install 경로)\n--       S3 M13 적용 후 형상              → NOTICE no-op (default 되돌림 절대 금지)\n--       S4 타입 ≠ text                   → 수정 0건 중단 (강제 변환 금지)\n--       S5 그 외 형상(nullable·예상 밖 default·부분 M13·generated/identity 등)\n--                                        → 수정 0건 중단 (자동 보정 금지 — 오너 회부)\n--   - 오류 식별자: BATCH_B_BASELINE_OBJECT_MISMATCH 재사용(신규 채번 금지 —\n--     Batch B 관행). 예외 시 단일 트랜잭션 전체 rollback — 부분 적용 상태 없음.\n--   - 멱등성(§13): 성공 후 상태는 항상 S2 또는 S3 로 판정되어 no-op. 몇 번을\n--     어떤 순서로 실행해도 S1 에서 정확히 1회만 효과.\n--   - 잠금(§14): ADD COLUMN constant default 는 PG11+ fast-path(table rewrite 0).\n--     ACCESS EXCLUSIVE 순간 보유 — lock_timeout 5s, 초과 실패 시 재실행 안전.\n-- 선행조건: 없음(MC 자체 선행 간선 없음 — 유일 필수 제약은 「M13 이전」 실행.\n--   위상 그래프 M13 : MC 신설, S2-3 §10).\n-- rollback 정본: supabase/rollback/20260730095436_comments_author_label_baseline_convergence_rollback.sql\n--   (CONDITIONAL — pre-state 컬럼 부재가 증명된 DB 한정·M13 이력 시 forward-fix only)\n-- =============================================================================\n\nbegin;\n\nset local lock_timeout = ''5s'';\n\n-- -----------------------------------------------------------------------------\n-- A. 테이블 게이트 + 상태 분기 S1~S5 (S2-3 §11 — 불일치 시 수정 0건 중단)\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_type      text;\n  v_null      text;\n  v_def       text;\n  v_gen       text;\n  v_ident     text;\n  v_role_ex   boolean;\nBEGIN\n  -- 테이블 게이트: public.comments 부재 시 수정 없이 중단\n  IF to_regclass(''public.comments'') IS NULL THEN\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: public.comments table missing'';\n  END IF;\n\n  SELECT EXISTS (SELECT 1 FROM information_schema.columns\n                  WHERE table_schema = ''public'' AND table_name = ''comments''\n                    AND column_name = ''author_role'')\n    INTO v_role_ex;\n\n  SELECT data_type, is_nullable, column_default, is_generated, is_identity\n    INTO v_type, v_null, v_def, v_gen, v_ident\n    FROM information_schema.columns\n   WHERE table_schema = ''public'' AND table_name = ''comments''\n     AND column_name = ''author_label'';\n\n  IF NOT FOUND THEN\n    IF v_role_ex THEN\n      -- 부분 M13 상태(author_label 부재 + author_role 존재) — 자동 수정 금지 (S5)\n      RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: comments.author_label absent but comments.author_role present (partial M13 state — manual review required)'';\n    END IF;\n    -- S1: 원격 드리프트 실측 상태 — 037 정본 형상으로 수렴 (정확히 1문장)\n    ALTER TABLE public.comments\n      ADD COLUMN author_label text NOT NULL DEFAULT ''쌤버십 회원'';\n    RAISE NOTICE ''S2_MC S1: comments.author_label added (text NOT NULL DEFAULT ''''쌤버십 회원'''') — baseline converged'';\n  ELSIF v_type <> ''text'' THEN\n    -- S4: 타입 불일치 — 강제 변환 금지, 수정 0건 중단\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: comments.author_label type=% null=% default=% (expected text — no coercion)'',\n      v_type, v_null, coalesce(v_def, ''<none>'');\n  ELSIF v_null = ''NO'' AND v_def IS NOT DISTINCT FROM ''''''쌤버십 회원''''::text''\n        AND NOT v_role_ex AND v_gen = ''NEVER'' AND v_ident = ''NO'' THEN\n    -- S2: 037 정본 baseline 형상 — no-op (clean-install·수렴 성공 후 재실행 경로)\n    RAISE NOTICE ''S2_MC S2: comments.author_label already at baseline shape — no-op'';\n  ELSIF v_null = ''NO'' AND v_def IS NOT DISTINCT FROM ''''''쌤버십 사용자''''::text''\n        AND v_role_ex AND v_gen = ''NEVER'' AND v_ident = ''NO'' THEN\n    -- S3: M13 적용 후 형상 — no-op. default 를 ''쌤버십 회원'' 으로 되돌리거나\n    --     author_role·M13 객체를 접촉하는 것을 절대 금지한다(M13 되돌림 방지).\n    RAISE NOTICE ''S2_MC S3: comments.author_label at post-M13 shape — no-op (default preserved)'';\n  ELSE\n    -- S5: 그 외 모든 형상(nullable·default 부재/예상 밖·S3 부분 충족·generated/identity)\n    --     — 자동 보정 금지, 수정 0건 중단 (오너 회부)\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: comments.author_label unexpected shape type=% null=% default=% generated=% identity=% author_role_present=%'',\n      v_type, v_null, coalesce(v_def, ''<none>''), v_gen, v_ident, v_role_ex;\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- B. 적용 직후 자가 검증 (S2-3 §11 post-check — commit 직전 A/B 두 형상만 허용)\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_label_ok_a boolean;\n  v_label_ok_b boolean;\n  v_role_ex    boolean;\nBEGIN\n  SELECT EXISTS (SELECT 1 FROM information_schema.columns\n                  WHERE table_schema = ''public'' AND table_name = ''comments''\n                    AND column_name = ''author_role'')\n    INTO v_role_ex;\n  -- A: baseline 정본 — text NOT NULL default ''쌤버십 회원'' ∧ author_role 부재\n  SELECT EXISTS (SELECT 1 FROM information_schema.columns\n                  WHERE table_schema = ''public'' AND table_name = ''comments''\n                    AND column_name = ''author_label''\n                    AND data_type = ''text'' AND is_nullable = ''NO''\n                    AND column_default = ''''''쌤버십 회원''''::text'')\n    INTO v_label_ok_a;\n  -- B: M13 이후 — text NOT NULL default ''쌤버십 사용자'' ∧ author_role 존재\n  SELECT EXISTS (SELECT 1 FROM information_schema.columns\n                  WHERE table_schema = ''public'' AND table_name = ''comments''\n                    AND column_name = ''author_label''\n                    AND data_type = ''text'' AND is_nullable = ''NO''\n                    AND column_default = ''''''쌤버십 사용자''''::text'')\n    INTO v_label_ok_b;\n  IF NOT ((v_label_ok_a AND NOT v_role_ex) OR (v_label_ok_b AND v_role_ex)) THEN\n    RAISE EXCEPTION ''S2_MC_SELFCHECK: comments.author_label post-state is neither baseline(A) nor post-M13(B) shape (label_a=% label_b=% author_role=%)'',\n      v_label_ok_a, v_label_ok_b, v_role_ex;\n  END IF;\nEND $$;\n\ncommit;\n"], "idempotency_key": null}, {"name": "20260730095438_comments_author_label_denormalize", "version": "20260731100540", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260730095438_comments_author_label_denormalize.sql (S2 M13)\n-- =============================================================================\n-- V2 선행 비정규화 — 댓글 author label/role 정본화 (baseline 정합 보정 2026-07-30).\n-- 정본 계약: docs/contracts/api_web_v1_contract_v1_1.md §6 V2 · §10.4 · §20.2 M13 ·\n--            §20.3 「M13 이전/적용 직후」 · §21.7 T-M13-01~16 · §22 #8 · 부록 C-2.\n--   - comments.author_label 은 037 기원 선재 컬럼을 재사용한다(ADD/DROP 금지 ·\n--     NOT NULL 유지). default 만 ''쌤버십 회원'' → ''쌤버십 사용자'' 정정.\n--   - M13 신규 컬럼은 public.comments.author_role text NULL 정확히 1개다.\n--   - 트리거 함수 2종(comments_set_author_label · community_comments_set_author_label):\n--     SECURITY DEFINER + 고정 search_path='''' + 완전 수식 + 같은 트랜잭션 PUBLIC\n--     EXECUTE 회수. TG_OP 분기 — INSERT 는 서버 규칙으로 무조건 덮어쓰고,\n--     UPDATE(snapshot 컬럼 대상) 는 명시적 오류로 거부한다(silent no-op 금지).\n--   - 트리거 역할 4종: canonical INSERT 설정 · canonical UPDATE OF author_label,\n--     author_role 보호 · legacy board INSERT 설정 · legacy board UPDATE OF\n--     author_label 보호. legacy 쪽은 post_type=''board'' 한정 — shortform 무영향.\n--   - 라벨 규칙: public.users.nickname 만 사용. NULL·trim 공백·사용자 행 부재 →\n--     정확히 ''쌤버십 사용자''. author_role 은 student/mentor 만 기록,\n--     admin·기타·사용자 부재 → NULL(관리자 신원 비노출).\n--     full_name·email·birth_date·grade_level 은 라벨 도출에 사용 금지.\n--   - 권위 사슬: DB BEFORE INSERT trigger > 163/164 bridge > 클라이언트 > default.\n--     163/164 브리지 함수 본문은 수정하지 않는다 — 브리지의 양방향 INSERT 가 각\n--     테이블의 BEFORE INSERT 트리거를 통과하며 양쪽 라벨이 동일 값으로 수렴한다.\n--   - 백필 1회(forward-only 보안 데이터 교정, §22 #8): comments 전행\n--     (author_label·author_role) + community_comments board 행(author_label).\n--     shortform 행 바이트 단위 불변 · 행 수 불변 · 비대상 컬럼 불변.\n--     * 백필 중 163 브리지의 자체 재귀 방지 스위치(GUC app.comment_sync)를 세워\n--       동기화 트리거의 2차 쓰기를 차단한다(양 테이블을 본 migration 이 직접\n--       정규화하므로 브리지 전파 불요 — 브리지 본문 무수정).\n--     * community_comments 의 016 updated_at 트리거(trg_community_comments_set_updated)\n--       는 백필 구간에서만 일시 DISABLE 후 즉시 ENABLE 한다(비대상 컬럼\n--       updated_at 불변 보장 — 같은 트랜잭션 내 원상복구, 기존 SQL 무수정).\n--   - snapshot 보호 오류 식별자: 계약 §10.4 는 「명시적 오류」만 요구하고 신규\n--     코드를 정의하지 않으므로(임의 신설 금지 — Batch B 지시 §8.4), 저장소 정본\n--     163/164 가 확립한 보호필드 불변 식별자 COMMENT_PROTECTED_FIELDS_IMMUTABLE\n--     (canonical) · CC_PROTECTED_FIELDS_IMMUTABLE(legacy) 를 재사용한다 —\n--     부록 C-2 가 진단한 「163/164 비교식에 author_label 부재」 결함을 같은 오류\n--     표면으로 닫는 정합 보정이다.\n-- 선행조건: M0(20260729211929) 적용 완료(§20.2.1 — M13 : M0).\n-- rollback 정본: supabase/rollback/20260730095438_comments_author_label_denormalize_rollback.sql\n--   (트리거 4종·함수 2종·author_role 제거 + default 복원까지만 — author_label 컬럼과\n--    정규화 라벨 데이터는 보존하는 forward-only 예외, §22 #8)\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- A. 사전 구조 게이트 (§20.3 「M13 이전」 — 불일치 시 수정 0건 중단)\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_type text;\n  v_null text;\n  v_def  text;\nBEGIN\n  -- ① comments.author_label: 존재 · text · NOT NULL · default ''쌤버십 회원''\n  SELECT data_type, is_nullable, column_default INTO v_type, v_null, v_def\n    FROM information_schema.columns\n   WHERE table_schema = ''public'' AND table_name = ''comments'' AND column_name = ''author_label'';\n  IF NOT FOUND THEN\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: comments.author_label missing'';\n  END IF;\n  IF v_type <> ''text'' OR v_null <> ''NO'' OR v_def IS DISTINCT FROM ''''''쌤버십 회원''''::text'' THEN\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: comments.author_label type=% null=% default=%'',\n      v_type, v_null, coalesce(v_def, ''<none>'');\n  END IF;\n  -- ② comments.author_role: 부재\n  IF EXISTS (SELECT 1 FROM information_schema.columns\n              WHERE table_schema = ''public'' AND table_name = ''comments'' AND column_name = ''author_role'') THEN\n    RAISE EXCEPTION ''UNEXPECTED_EXISTING_CONTRACT_OBJECT: comments.author_role already exists'';\n  END IF;\n  -- ③ community_comments.author_label: 존재 · text · NOT NULL · default ''쌤버십 회원''\n  SELECT data_type, is_nullable, column_default INTO v_type, v_null, v_def\n    FROM information_schema.columns\n   WHERE table_schema = ''public'' AND table_name = ''community_comments'' AND column_name = ''author_label'';\n  IF NOT FOUND THEN\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: community_comments.author_label missing'';\n  END IF;\n  IF v_type <> ''text'' OR v_null <> ''NO'' OR v_def IS DISTINCT FROM ''''''쌤버십 회원''''::text'' THEN\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: community_comments.author_label type=% null=% default=%'',\n      v_type, v_null, coalesce(v_def, ''<none>'');\n  END IF;\n  -- ④ 163/164 브리지 최종 함수·트리거·매핑 컬럼 존재\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname = ''public''\n         AND p.proname IN (''comment_sync_in_progress'', ''comments_write_guard'', ''cc_write_guard'',\n                           ''cc_sync_board_to_canonical'', ''cc_sync_board_delete_to_canonical'',\n                           ''comments_mirror_to_legacy'', ''comments_mirror_delete_to_legacy'')) <> 7 THEN\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: 163/164 bridge functions incomplete'';\n  END IF;\n  IF (SELECT count(*) FROM pg_trigger\n       WHERE tgrelid = ''public.comments''::regclass AND NOT tgisinternal\n         AND tgname IN (''trg_comments_write_guard'', ''trg_comments_mirror_to_legacy'',\n                        ''trg_comments_mirror_delete'')) <> 3\n     OR (SELECT count(*) FROM pg_trigger\n          WHERE tgrelid = ''public.community_comments''::regclass AND NOT tgisinternal\n            AND tgname IN (''trg_cc_write_guard'', ''trg_cc_sync_board_to_canonical'',\n                           ''trg_cc_sync_board_delete'', ''trg_community_comments_set_updated'')) <> 4 THEN\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: 163/164 bridge triggers incomplete'';\n  END IF;\n  IF (SELECT count(*) FROM information_schema.columns\n       WHERE table_schema = ''public''\n         AND ((table_name = ''comments'' AND column_name = ''legacy_comment_id'')\n              OR (table_name = ''community_comments'' AND column_name = ''canonical_comment_id''))) <> 2 THEN\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: bridge mapping columns incomplete'';\n  END IF;\n  -- ⑤ M13 신규 객체 선재 금지 (부분 생성 상태 은닉 금지)\n  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n              WHERE n.nspname = ''public''\n                AND p.proname IN (''comments_set_author_label'', ''community_comments_set_author_label''))\n     OR EXISTS (SELECT 1 FROM pg_trigger\n                 WHERE NOT tgisinternal\n                   AND tgname IN (''trg_comments_set_author_label_ins'', ''trg_comments_set_author_label_upd'',\n                                  ''trg_community_comments_set_author_label_ins'',\n                                  ''trg_community_comments_set_author_label_upd'')) THEN\n    RAISE EXCEPTION ''UNEXPECTED_EXISTING_CONTRACT_OBJECT: M13 trigger objects already exist'';\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- B. 컬럼 — 신규는 author_role 1개뿐 · 선재 author_label 은 default 정정만\n-- -----------------------------------------------------------------------------\nALTER TABLE public.comments ADD COLUMN author_role text;\nALTER TABLE public.comments ALTER COLUMN author_label SET DEFAULT ''쌤버십 사용자'';\n-- community_comments.author_label 의 default(''쌤버십 회원'')는 변경하지 않는다\n-- (§10.4 — default 정정 대상은 canonical comments 만).\n\nCOMMENT ON COLUMN public.comments.author_role IS\n  ''S2 M13(계약 §10.4): 서버 도출 작성자 역할 스냅샷 — student/mentor 만, admin·기타·사용자 부재는 NULL. 기록은 BEFORE INSERT 트리거 전용.'';\n\n-- -----------------------------------------------------------------------------\n-- C. 트리거 함수 2종 (§10.4 — SECDEF · search_path='''' · TG_OP 분기)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION public.comments_set_author_label()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $$\nDECLARE\n  v_nickname text;\n  v_role     text;\nBEGIN\n  IF tg_op = ''UPDATE'' THEN\n    -- snapshot(author_label·author_role) 변조 명시 거부 — silent no-op 금지 (§10.4 ③).\n    -- 식별자는 163 보호필드 정본(COMMENT_PROTECTED_FIELDS_IMMUTABLE) 재사용 — 헤더 참조.\n    RAISE EXCEPTION ''COMMENT_PROTECTED_FIELDS_IMMUTABLE'';\n  END IF;\n  -- INSERT: 클라이언트·브리지 입력을 신뢰하지 않고 서버 규칙으로 무조건 덮어쓴다.\n  SELECT u.nickname, u.role INTO v_nickname, v_role\n    FROM public.users u WHERE u.id = new.author_id;\n  IF FOUND THEN\n    new.author_label := coalesce(nullif(btrim(v_nickname), ''''), ''쌤버십 사용자'');\n    new.author_role  := CASE WHEN v_role IN (''student'', ''mentor'') THEN v_role END;\n  ELSE\n    -- 사용자 행 부재(이론상 FK 로 차단되나 규칙을 코드로 고정) → fallback.\n    new.author_label := ''쌤버십 사용자'';\n    new.author_role  := NULL;\n  END IF;\n  RETURN new;\nEND $$;\n\nCOMMENT ON FUNCTION public.comments_set_author_label() IS\n  ''S2 M13(계약 §10.4): canonical comments 의 author_label/author_role 서버 덮어쓰기(BEFORE INSERT) + snapshot UPDATE 명시 거부(BEFORE UPDATE OF). 라벨은 users.nickname 만 사용.'';\n\nCREATE FUNCTION public.community_comments_set_author_label()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $$\nDECLARE\n  v_nickname text;\nBEGIN\n  IF tg_op = ''UPDATE'' THEN\n    -- board 행 snapshot(author_label) 변조 명시 거부 — 식별자는 164 정본 재사용.\n    RAISE EXCEPTION ''CC_PROTECTED_FIELDS_IMMUTABLE'';\n  END IF;\n  -- INSERT(post_type=''board'' 한정 — 트리거 WHEN): 서버 규칙 덮어쓰기.\n  SELECT u.nickname INTO v_nickname\n    FROM public.users u WHERE u.id = new.author_id;\n  IF FOUND THEN\n    new.author_label := coalesce(nullif(btrim(v_nickname), ''''), ''쌤버십 사용자'');\n  ELSE\n    -- community_comments.author_id 는 auth.users FK — public.users 행 부재 가능 → fallback.\n    new.author_label := ''쌤버십 사용자'';\n  END IF;\n  RETURN new;\nEND $$;\n\nCOMMENT ON FUNCTION public.community_comments_set_author_label() IS\n  ''S2 M13(계약 §10.4): legacy community_comments board 행의 author_label 서버 덮어쓰기(BEFORE INSERT) + snapshot UPDATE 명시 거부. shortform 행 무영향(트리거 WHEN 한정).'';\n\n-- [필수] 함수 생성과 동일 트랜잭션에서 PUBLIC EXECUTE 회수 (§10.4 · T-M13-14)\nREVOKE ALL ON FUNCTION public.comments_set_author_label() FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.community_comments_set_author_label() FROM PUBLIC;\n\n-- -----------------------------------------------------------------------------\n-- D. 백필 1회 — forward-only 보안 데이터 교정 (§10.4 ④ · §22 #8)\n--    트리거 설치 전에 수행한다(UPDATE 보호 트리거가 백필을 막지 않도록 순서 고정).\n-- -----------------------------------------------------------------------------\n-- 비대상 컬럼(updated_at) 불변 보장 — 016 트리거를 백필 구간에서만 일시 정지.\nALTER TABLE public.community_comments DISABLE TRIGGER trg_community_comments_set_updated;\n\nDO $$\nBEGIN\n  -- 163 브리지 자체 재귀 방지 스위치 — 백필 중 동기화 트리거 2차 쓰기 차단\n  -- (양 테이블을 아래에서 직접 정규화하므로 전파 불요. 트랜잭션 로컬 GUC).\n  PERFORM set_config(''app.comment_sync'', ''1'', true);\n\n  -- comments 전행: author_label + author_role 정규화 (행 수 불변 — UPDATE only)\n  UPDATE public.comments c\n     SET author_label = coalesce(\n           (SELECT nullif(btrim(u.nickname), '''') FROM public.users u WHERE u.id = c.author_id),\n           ''쌤버십 사용자''),\n         author_role = (SELECT CASE WHEN u.role IN (''student'', ''mentor'') THEN u.role END\n                          FROM public.users u WHERE u.id = c.author_id);\n\n  -- community_comments 중 board 행만: author_label 정규화 (shortform 바이트 단위 불변)\n  UPDATE public.community_comments cc\n     SET author_label = coalesce(\n           (SELECT nullif(btrim(u.nickname), '''') FROM public.users u WHERE u.id = cc.author_id),\n           ''쌤버십 사용자'')\n   WHERE cc.post_type = ''board'';\n\n  PERFORM set_config(''app.comment_sync'', ''0'', true);\nEND $$;\n\nALTER TABLE public.community_comments ENABLE TRIGGER trg_community_comments_set_updated;\n\n-- -----------------------------------------------------------------------------\n-- E. 트리거 4종 (§10.4 — 백필 후 설치. 이름은 M0 확립 관행 trg_<함수명>_<ins/upd>)\n-- -----------------------------------------------------------------------------\n-- 1) canonical INSERT — 서버 라벨·역할 무조건 덮어쓰기\nCREATE TRIGGER trg_comments_set_author_label_ins\n  BEFORE INSERT ON public.comments\n  FOR EACH ROW\n  EXECUTE FUNCTION public.comments_set_author_label();\n\n-- 2) canonical snapshot UPDATE 보호 — author_label·author_role 대상 지정 시 명시 거부\nCREATE TRIGGER trg_comments_set_author_label_upd\n  BEFORE UPDATE OF author_label, author_role ON public.comments\n  FOR EACH ROW\n  EXECUTE FUNCTION public.comments_set_author_label();\n\n-- 3) legacy board INSERT — 서버 라벨 덮어쓰기 (shortform 은 트리거 미발화)\nCREATE TRIGGER trg_community_comments_set_author_label_ins\n  BEFORE INSERT ON public.community_comments\n  FOR EACH ROW\n  WHEN (new.post_type = ''board'')\n  EXECUTE FUNCTION public.community_comments_set_author_label();\n\n-- 4) legacy board snapshot UPDATE 보호 (shortform 행 라벨은 M13 무영향 — 기존 동작 유지)\nCREATE TRIGGER trg_community_comments_set_author_label_upd\n  BEFORE UPDATE OF author_label ON public.community_comments\n  FOR EACH ROW\n  WHEN (old.post_type = ''board'')\n  EXECUTE FUNCTION public.community_comments_set_author_label();\n\n-- -----------------------------------------------------------------------------\n-- F. 적용 직후 자가 검증 (§20.3 「M13 적용 직후」 게이트)\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_cnt int;\n  v_def text;\nBEGIN\n  -- ① comments.author_label: text NOT NULL · default ''쌤버십 사용자''\n  SELECT column_default INTO v_def FROM information_schema.columns\n   WHERE table_schema = ''public'' AND table_name = ''comments'' AND column_name = ''author_label''\n     AND data_type = ''text'' AND is_nullable = ''NO'';\n  IF NOT FOUND OR v_def IS DISTINCT FROM ''''''쌤버십 사용자''''::text'' THEN\n    RAISE EXCEPTION ''S2_M13_SELFCHECK: comments.author_label default not corrected (%)'', coalesce(v_def, ''<none>'');\n  END IF;\n  -- ② comments.author_role: text NULL(무 default)\n  IF NOT EXISTS (SELECT 1 FROM information_schema.columns\n                  WHERE table_schema = ''public'' AND table_name = ''comments'' AND column_name = ''author_role''\n                    AND data_type = ''text'' AND is_nullable = ''YES'' AND column_default IS NULL) THEN\n    RAISE EXCEPTION ''S2_M13_SELFCHECK: comments.author_role shape mismatch'';\n  END IF;\n  -- ③ 트리거 함수 정확히 2종 — SECDEF + 고정 search_path + PUBLIC/외부 EXECUTE 0\n  SELECT count(*) INTO v_cnt\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''public''\n     AND p.proname IN (''comments_set_author_label'', ''community_comments_set_author_label'')\n     AND p.prosecdef\n     AND p.proconfig::text LIKE ''%search_path=%''\n     AND NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n     AND NOT has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n     AND (p.proacl IS NULL OR (p.proacl::text NOT LIKE ''{=%'' AND p.proacl::text NOT LIKE ''%,=%''));\n  IF v_cnt <> 2 THEN\n    RAISE EXCEPTION ''S2_M13_SELFCHECK: trigger functions hardening mismatch (matched=%)'', v_cnt;\n  END IF;\n  -- ④ 계약된 트리거 역할 4개 존재\n  SELECT count(*) INTO v_cnt FROM pg_trigger\n   WHERE NOT tgisinternal\n     AND ((tgrelid = ''public.comments''::regclass\n           AND tgname IN (''trg_comments_set_author_label_ins'', ''trg_comments_set_author_label_upd''))\n          OR (tgrelid = ''public.community_comments''::regclass\n              AND tgname IN (''trg_community_comments_set_author_label_ins'',\n                             ''trg_community_comments_set_author_label_upd'')));\n  IF v_cnt <> 4 THEN\n    RAISE EXCEPTION ''S2_M13_SELFCHECK: expected 4 M13 triggers, found %'', v_cnt;\n  END IF;\n  -- ⑤ 016 updated_at 트리거 원상복구(ENABLE) 확인\n  IF NOT EXISTS (SELECT 1 FROM pg_trigger\n                  WHERE tgrelid = ''public.community_comments''::regclass\n                    AND tgname = ''trg_community_comments_set_updated'' AND tgenabled = ''O'') THEN\n    RAISE EXCEPTION ''S2_M13_SELFCHECK: trg_community_comments_set_updated not re-enabled'';\n  END IF;\n  -- ⑥ 백필 결과 — 라벨 규칙 위반 0 (comments 전행 · community_comments board 행)\n  SELECT count(*) INTO v_cnt\n    FROM public.comments c\n   WHERE c.author_label IS DISTINCT FROM coalesce(\n           (SELECT nullif(btrim(u.nickname), '''') FROM public.users u WHERE u.id = c.author_id),\n           ''쌤버십 사용자'')\n      OR c.author_role IS DISTINCT FROM (SELECT CASE WHEN u.role IN (''student'', ''mentor'') THEN u.role END\n                                           FROM public.users u WHERE u.id = c.author_id);\n  IF v_cnt <> 0 THEN\n    RAISE EXCEPTION ''S2_M13_SELFCHECK: comments backfill rule violations: %'', v_cnt;\n  END IF;\n  SELECT count(*) INTO v_cnt\n    FROM public.community_comments cc\n   WHERE cc.post_type = ''board''\n     AND cc.author_label IS DISTINCT FROM coalesce(\n           (SELECT nullif(btrim(u.nickname), '''') FROM public.users u WHERE u.id = cc.author_id),\n           ''쌤버십 사용자'');\n  IF v_cnt <> 0 THEN\n    RAISE EXCEPTION ''S2_M13_SELFCHECK: community_comments board backfill rule violations: %'', v_cnt;\n  END IF;\nEND $$;\n\ncommit;\n"], "idempotency_key": null}, {"name": "20260730095441_api_web_v1_read_views", "version": "20260731100708", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260730095441_api_web_v1_read_views.sql (S2 M4)\n-- =============================================================================\n-- api_web_v1 읽기 View 5종 (V1~V5) + View GRANT.\n-- 정본 계약: docs/contracts/api_web_v1_contract_v1_1.md §6 V1~V5 · §10.2 · §20.2 M4.\n--   - V1 community_posts_v1  : invoker 뷰. body=coalesce(content,body) ·\n--     image_refs=coalesce(image_urls,''{}'') · deleted_at IS NULL ·\n--     published 또는 본인 글만(XW-09 해소 — view 가 deleted_at 필터를 명시).\n--   - V2 community_comments_v1: invoker 뷰. 원천은 정본 public.comments 만\n--     (레거시 community_comments 는 읽지 않는다). body=content ·\n--     is_deleted=false · 라벨은 M13 비정규화 컬럼(author_label·author_role).\n--   - V3 mentor_directory_v1 : security_invoker=false — 계약이 승인한 유일한\n--     의도적 예외(§6 V3 — 타인 users·mentor_profiles 행은 RLS 상 본인·admin 만\n--     읽을 수 있어 invoker 로 성립 불가. 노출 조건이 view 정의에 하드코딩되고\n--     읽기 전용이라는 것이 안전장치). lint 의 security-definer view 경고는\n--     계약된 의도적 예외로 분류한다 — 경고 해소 목적의 invoker 전환 금지.\n--     · 노출 조건(모두 AND): users.role=''mentor'' ·\n--       lower(coalesce(users.status,''active''))=''active'' ·\n--       lower(coalesce(verification_status,'''')) IN (''approved'',''verified'',''active'')\n--       (individual_question_user_is_approved_mentor 와 동일 판정식 — 실측 대조).\n--     · nickname = users.nickname 만. full_name·email·birth_date 비노출(PII 0).\n--     · 학교 인증 4필드: mentor_school_verifications status=''approved'' 최신 1건을\n--       LEFT JOIN LATERAL — 정렬은 기존 mentor_profiles_for_directory_v2 와 동일\n--       (coalesce(reviewed_at, updated_at, created_at) DESC, created_at DESC).\n--     · avg_rating/review_count 는 reviews 실계산 — coalesce(is_hidden,false)=false\n--       AND coalesce(is_blinded,false)=false 행만(hidden/blinded 제외).\n--       (mentor_profiles 에는 avg_rating·review_count 컬럼이 없음 — 실측 §3.7 #7.)\n--   - V4 my_wallet_v1 : invoker 뷰. balance_krw = balance_cents / 100 (1캐시=1원).\n--   - V5 my_cash_ledger_v1: invoker 뷰. order_ref 는 ref_type=''topup'' 행의\n--     idempotency_key 만(CASE 한정 — rev 8 A-6). idempotency_key 자체를 별도\n--     필드로 전행 노출하지 않는다.\n--   - GRANT(§10.2): V1·V2·V3 SELECT → anon·authenticated·service_role /\n--     V4·V5 SELECT → authenticated·service_role (anon 0).\n--     전 View: PUBLIC 회수 선행 · INSERT/UPDATE/DELETE 등 DML 은 어떤 역할에도 0.\n--   - V6·V7 은 여기서 만들지 않는다(범위 제한 SECDEF RPC — M6 소유).\n--   - Data API 설정 변경 없음(D-API-W 는 별도 플랫폼 단계 — §20.6).\n-- 선행조건: M1(20260730095435) + M13(20260730095438) 적용 완료(§20.2.1 — M4 : M1+M13).\n-- rollback 정본: supabase/rollback/20260730095441_api_web_v1_read_views_rollback.sql\n--   (View 5종만 역순 DROP — schema 는 M1 rollback 소유 · CASCADE 금지)\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- A. 사전 게이트 (§20.3 「M4 이전」 — M1·M13 적용 + PUBLIC 권한 0건 + 기반 매핑 실측)\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_acl text;\n  v_missing text;\nBEGIN\n  -- M1 적용 확인: schema 2종 + PUBLIC 권한 0건 실측\n  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = ''api_web_v1'')\n     OR NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = ''core_private'') THEN\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: M1 schemas not applied'';\n  END IF;\n  SELECT nspacl::text INTO v_acl FROM pg_namespace WHERE nspname = ''api_web_v1'';\n  IF v_acl LIKE ''{=%'' OR v_acl LIKE ''%,=%'' THEN\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: api_web_v1 has PUBLIC acl entry'';\n  END IF;\n  SELECT nspacl::text INTO v_acl FROM pg_namespace WHERE nspname = ''core_private'';\n  IF v_acl LIKE ''{=%'' OR v_acl LIKE ''%,=%''\n     OR has_schema_privilege(''anon'', ''core_private'', ''USAGE'')\n     OR has_schema_privilege(''authenticated'', ''core_private'', ''USAGE'')\n     OR has_schema_privilege(''service_role'', ''core_private'', ''USAGE'') THEN\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: core_private boundary violated'';\n  END IF;\n  -- M13 적용 확인 (V2 가 author_role 비정규화 컬럼을 참조)\n  IF NOT EXISTS (SELECT 1 FROM information_schema.columns\n                  WHERE table_schema = ''public'' AND table_name = ''comments''\n                    AND column_name = ''author_role'') THEN\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: M13 comments.author_role not applied'';\n  END IF;\n  -- V1~V5 가 참조하는 기반 컬럼 전수 실측 — 불일치는 추정하지 않고 중단(V3 매핑 게이트)\n  SELECT string_agg(m.col, '', '') INTO v_missing FROM (\n    SELECT t.tbl || ''.'' || t.col AS col\n      FROM (VALUES\n        (''community_posts'',''id''), (''community_posts'',''author_id''), (''community_posts'',''title''),\n        (''community_posts'',''body''), (''community_posts'',''content''), (''community_posts'',''category''),\n        (''community_posts'',''image_urls''), (''community_posts'',''author_label''),\n        (''community_posts'',''author_role''), (''community_posts'',''like_count''),\n        (''community_posts'',''comment_count''), (''community_posts'',''view_count''),\n        (''community_posts'',''status''), (''community_posts'',''created_at''),\n        (''community_posts'',''updated_at''), (''community_posts'',''deleted_at''),\n        (''comments'',''id''), (''comments'',''post_id''), (''comments'',''author_id''),\n        (''comments'',''parent_id''), (''comments'',''content''), (''comments'',''like_count''),\n        (''comments'',''author_label''), (''comments'',''author_role''), (''comments'',''is_deleted''),\n        (''comments'',''created_at''),\n        (''users'',''id''), (''users'',''role''), (''users'',''status''), (''users'',''nickname''),\n        (''mentor_profiles'',''user_id''), (''mentor_profiles'',''university_name''),\n        (''mentor_profiles'',''department_name''), (''mentor_profiles'',''teaching_subjects''),\n        (''mentor_profiles'',''intro_line''), (''mentor_profiles'',''profile_image_url''),\n        (''mentor_profiles'',''high_school_name''), (''mentor_profiles'',''is_open_for_subscriptions''),\n        (''mentor_profiles'',''verification_status''), (''mentor_profiles'',''created_at''),\n        (''mentor_school_verifications'',''mentor_id''), (''mentor_school_verifications'',''status''),\n        (''mentor_school_verifications'',''school_tier''),\n        (''mentor_school_verifications'',''verified_major_category''),\n        (''mentor_school_verifications'',''verified_university_name''),\n        (''mentor_school_verifications'',''verified_department_name''),\n        (''mentor_school_verifications'',''reviewed_at''), (''mentor_school_verifications'',''updated_at''),\n        (''mentor_school_verifications'',''created_at''),\n        (''reviews'',''mentor_id''), (''reviews'',''rating''), (''reviews'',''is_hidden''), (''reviews'',''is_blinded''),\n        (''cash_wallets'',''user_id''), (''cash_wallets'',''balance_cents''),\n        (''cash_ledger'',''id''), (''cash_ledger'',''delta_cents''), (''cash_ledger'',''reason''),\n        (''cash_ledger'',''ref_type''), (''cash_ledger'',''ref_id''), (''cash_ledger'',''idempotency_key''),\n        (''cash_ledger'',''created_at'')\n      ) AS t(tbl, col)\n     WHERE NOT EXISTS (SELECT 1 FROM information_schema.columns ic\n                        WHERE ic.table_schema = ''public''\n                          AND ic.table_name = t.tbl AND ic.column_name = t.col)\n  ) m;\n  IF v_missing IS NOT NULL THEN\n    RAISE EXCEPTION ''BATCH_B_BASELINE_OBJECT_MISMATCH: base columns missing — %'', v_missing;\n  END IF;\n  -- View 5종 선재 금지 + api_web_v1 는 비어 있어야 한다(부분 생성 은닉 금지)\n  IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace\n       WHERE n.nspname = ''api_web_v1'') > 0 THEN\n    RAISE EXCEPTION ''UNEXPECTED_EXISTING_CONTRACT_OBJECT: api_web_v1 is not empty before M4'';\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- B. V1 api_web_v1.community_posts_v1 (invoker)\n-- -----------------------------------------------------------------------------\nCREATE VIEW api_web_v1.community_posts_v1\nWITH (security_invoker = true) AS\nSELECT\n  p.id,\n  p.author_id,\n  p.title,\n  coalesce(p.content, p.body)           AS body,\n  p.category,\n  coalesce(p.image_urls, ''{}''::text[])  AS image_refs,\n  p.author_label,\n  p.author_role,\n  p.like_count,\n  p.comment_count,\n  p.view_count,\n  p.status,\n  p.created_at,\n  p.updated_at\nFROM public.community_posts p\nWHERE p.deleted_at IS NULL\n  AND (p.status = ''published'' OR p.author_id = (SELECT auth.uid()));\n\nCOMMENT ON VIEW api_web_v1.community_posts_v1 IS\n  ''S2 M4 V1(계약 §6): 게시판 읽기 — body=coalesce(content,body) · image_refs=coalesce(image_urls,{}) · deleted_at IS NULL · published 또는 본인 글. security_invoker=true.'';\n\n-- -----------------------------------------------------------------------------\n-- C. V2 api_web_v1.community_comments_v1 (invoker · 원천 = 정본 comments 만)\n-- -----------------------------------------------------------------------------\nCREATE VIEW api_web_v1.community_comments_v1\nWITH (security_invoker = true) AS\nSELECT\n  c.id,\n  c.post_id,\n  c.author_id,\n  c.parent_id,\n  c.content AS body,\n  c.like_count,\n  c.author_label,\n  c.author_role,\n  c.created_at\nFROM public.comments c\nWHERE c.is_deleted = false;\n\nCOMMENT ON VIEW api_web_v1.community_comments_v1 IS\n  ''S2 M4 V2(계약 §6): 정본 comments 단일 원천 — body=content · is_deleted=false · 라벨은 M13 비정규화 컬럼. security_invoker=true.'';\n\n-- -----------------------------------------------------------------------------\n-- D. V3 api_web_v1.mentor_directory_v1 (security_invoker=false — 계약된 유일 예외)\n-- -----------------------------------------------------------------------------\nCREATE VIEW api_web_v1.mentor_directory_v1\nWITH (security_invoker = false) AS\nSELECT\n  mp.user_id                       AS mentor_id,\n  u.nickname,\n  mp.university_name,\n  mp.department_name,\n  mp.teaching_subjects,\n  mp.intro_line,\n  mp.profile_image_url,\n  mp.high_school_name,\n  (sv.mentor_id IS NOT NULL)       AS school_verified,\n  sv.school_tier,\n  sv.verified_major_category,\n  sv.verified_university_name,\n  sv.verified_department_name,\n  mp.is_open_for_subscriptions,\n  rv.avg_rating,\n  rv.review_count,\n  mp.created_at\nFROM public.mentor_profiles mp\nJOIN public.users u ON u.id = mp.user_id\nLEFT JOIN LATERAL (\n  SELECT\n    msv.mentor_id,\n    msv.school_tier,\n    msv.verified_major_category,\n    msv.verified_university_name,\n    msv.verified_department_name\n  FROM public.mentor_school_verifications msv\n  WHERE msv.mentor_id = mp.user_id\n    AND msv.status = ''approved''\n  ORDER BY coalesce(msv.reviewed_at, msv.updated_at, msv.created_at) DESC, msv.created_at DESC\n  LIMIT 1\n) sv ON true\nLEFT JOIN LATERAL (\n  SELECT\n    avg(r.rating)::numeric AS avg_rating,\n    count(*)::integer      AS review_count\n  FROM public.reviews r\n  WHERE r.mentor_id = mp.user_id\n    AND coalesce(r.is_hidden, false) = false\n    AND coalesce(r.is_blinded, false) = false\n) rv ON true\nWHERE u.role = ''mentor''\n  AND lower(coalesce(u.status, ''active'')) = ''active''\n  AND lower(coalesce(mp.verification_status, '''')) IN (''approved'', ''verified'', ''active'');\n\nCOMMENT ON VIEW api_web_v1.mentor_directory_v1 IS\n  ''S2 M4 V3(계약 §6 — 의도적 SECDEF 예외): 승인·활성 멘토만 공개(XW-02b 해소). PII 0(nickname 만). 노출 조건이 정의에 하드코딩된 읽기 전용 view.'';\n\n-- -----------------------------------------------------------------------------\n-- E. V4 api_web_v1.my_wallet_v1 (invoker — cwal_select 가 본인 행만 남긴다)\n-- -----------------------------------------------------------------------------\nCREATE VIEW api_web_v1.my_wallet_v1\nWITH (security_invoker = true) AS\nSELECT\n  w.user_id,\n  w.balance_cents,\n  (w.balance_cents / 100) AS balance_krw\nFROM public.cash_wallets w;\n\nCOMMENT ON VIEW api_web_v1.my_wallet_v1 IS\n  ''S2 M4 V4(계약 §6): 자기 지갑 — balance_krw = balance_cents/100 (1캐시=1원). security_invoker=true.'';\n\n-- -----------------------------------------------------------------------------\n-- F. V5 api_web_v1.my_cash_ledger_v1 (invoker — cled_select 가 본인 행만 남긴다)\n-- -----------------------------------------------------------------------------\nCREATE VIEW api_web_v1.my_cash_ledger_v1\nWITH (security_invoker = true) AS\nSELECT\n  l.id,\n  l.delta_cents,\n  (l.delta_cents / 100) AS delta_krw,\n  l.reason,\n  l.ref_type,\n  l.ref_id,\n  CASE WHEN l.ref_type = ''topup'' THEN l.idempotency_key END AS order_ref,\n  l.created_at\nFROM public.cash_ledger l;\n\nCOMMENT ON VIEW api_web_v1.my_cash_ledger_v1 IS\n  ''S2 M4 V5(계약 §6): 자기 캐시 원장 — order_ref 는 topup 행의 idempotency_key 만(CASE 한정, rev 8 A-6). security_invoker=true.'';\n\n-- -----------------------------------------------------------------------------\n-- G. GRANT (§10.2 — PUBLIC 회수 선행 · SELECT 만 · DML 0)\n-- -----------------------------------------------------------------------------\nREVOKE ALL ON ALL TABLES IN SCHEMA api_web_v1 FROM PUBLIC;\nGRANT SELECT ON api_web_v1.community_posts_v1,\n               api_web_v1.community_comments_v1,\n               api_web_v1.mentor_directory_v1        TO anon, authenticated, service_role;\nGRANT SELECT ON api_web_v1.my_wallet_v1,\n               api_web_v1.my_cash_ledger_v1          TO authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- H. 적용 직후 자가 검증 (view 5종 · 옵션 · GRANT 매트릭스 · PII 비노출)\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_cnt int;\n  v_bad text;\nBEGIN\n  -- 정확히 view 5종만 존재 (함수 0 · 테이블 0)\n  SELECT count(*) INTO v_cnt FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace\n   WHERE n.nspname = ''api_web_v1'';\n  IF v_cnt <> 5 OR (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace\n                     WHERE n.nspname = ''api_web_v1'' AND c.relkind <> ''v'') > 0 THEN\n    RAISE EXCEPTION ''S2_M4_SELFCHECK: api_web_v1 must contain exactly 5 views (found %)'', v_cnt;\n  END IF;\n  -- security_invoker 옵션: V1·V2·V4·V5 = true / V3 = 의도적 예외(false)\n  SELECT count(*) INTO v_cnt FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace\n   WHERE n.nspname = ''api_web_v1''\n     AND c.relname IN (''community_posts_v1'', ''community_comments_v1'', ''my_wallet_v1'', ''my_cash_ledger_v1'')\n     AND c.reloptions::text LIKE ''%security_invoker=true%'';\n  IF v_cnt <> 4 THEN\n    RAISE EXCEPTION ''S2_M4_SELFCHECK: invoker views expected 4, matched %'', v_cnt;\n  END IF;\n  IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace\n              WHERE n.nspname = ''api_web_v1'' AND c.relname = ''mentor_directory_v1''\n                AND c.reloptions::text LIKE ''%security_invoker=true%'') THEN\n    RAISE EXCEPTION ''S2_M4_SELFCHECK: mentor_directory_v1 must be the contracted SECDEF exception'';\n  END IF;\n  -- GRANT 매트릭스: anon 은 V1~V3 SELECT 만, V4·V5 는 권한 0\n  IF NOT (has_table_privilege(''anon'', ''api_web_v1.community_posts_v1'', ''SELECT'')\n          AND has_table_privilege(''anon'', ''api_web_v1.community_comments_v1'', ''SELECT'')\n          AND has_table_privilege(''anon'', ''api_web_v1.mentor_directory_v1'', ''SELECT''))\n     OR has_table_privilege(''anon'', ''api_web_v1.my_wallet_v1'', ''SELECT'')\n     OR has_table_privilege(''anon'', ''api_web_v1.my_cash_ledger_v1'', ''SELECT'') THEN\n    RAISE EXCEPTION ''S2_M4_SELFCHECK: anon grant matrix mismatch'';\n  END IF;\n  SELECT string_agg(v.relname, '', '') INTO v_bad\n    FROM pg_class v JOIN pg_namespace n ON n.oid = v.relnamespace\n   WHERE n.nspname = ''api_web_v1''\n     AND NOT (has_table_privilege(''authenticated'', v.oid, ''SELECT'')\n              AND has_table_privilege(''service_role'', v.oid, ''SELECT''));\n  IF v_bad IS NOT NULL THEN\n    RAISE EXCEPTION ''S2_M4_SELFCHECK: authenticated/service_role SELECT missing on %'', v_bad;\n  END IF;\n  -- DML 0: 세 역할 모두 INSERT/UPDATE/DELETE/TRUNCATE/REFERENCES/TRIGGER 부재 + PUBLIC 항목 0\n  SELECT string_agg(DISTINCT v.relname, '', '') INTO v_bad\n    FROM pg_class v JOIN pg_namespace n ON n.oid = v.relnamespace,\n         unnest(ARRAY[''anon'', ''authenticated'', ''service_role'']) AS r(role),\n         unnest(ARRAY[''INSERT'', ''UPDATE'', ''DELETE'', ''TRUNCATE'', ''REFERENCES'', ''TRIGGER'']) AS p(priv)\n   WHERE n.nspname = ''api_web_v1'' AND has_table_privilege(r.role, v.oid, p.priv);\n  IF v_bad IS NOT NULL THEN\n    RAISE EXCEPTION ''S2_M4_SELFCHECK: DML privilege leaked on %'', v_bad;\n  END IF;\n  SELECT string_agg(v.relname, '', '') INTO v_bad\n    FROM pg_class v JOIN pg_namespace n ON n.oid = v.relnamespace\n   WHERE n.nspname = ''api_web_v1''\n     AND (v.relacl::text LIKE ''{=%'' OR v.relacl::text LIKE ''%,=%'');\n  IF v_bad IS NOT NULL THEN\n    RAISE EXCEPTION ''S2_M4_SELFCHECK: PUBLIC acl entry on %'', v_bad;\n  END IF;\n  -- PII 비노출: V3 정의에 full_name·email·birth_date·grade_level 부재\n  IF pg_get_viewdef(''api_web_v1.mentor_directory_v1''::regclass) ~* ''(full_name|email|birth_date|grade_level)'' THEN\n    RAISE EXCEPTION ''S2_M4_SELFCHECK: mentor_directory_v1 references PII columns'';\n  END IF;\n  -- V5: idempotency_key 를 별도 필드로 노출하지 않는다(order_ref CASE 한정)\n  IF EXISTS (SELECT 1 FROM information_schema.columns\n              WHERE table_schema = ''api_web_v1'' AND table_name = ''my_cash_ledger_v1''\n                AND column_name = ''idempotency_key'') THEN\n    RAISE EXCEPTION ''S2_M4_SELFCHECK: my_cash_ledger_v1 must not expose idempotency_key column'';\n  END IF;\nEND $$;\n\ncommit;\n"], "idempotency_key": null}, {"name": "20260730105244_core_private_room_ensure", "version": "20260731101845", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260730105244_core_private_room_ensure.sql (S2 M5)\n-- =============================================================================\n-- F10 core_private.ensure_student_mentor_room — 방 확보 공용 구현부.\n-- 정본 계약: docs/contracts/api_web_v1_contract_v1_1.md §7 F10 · §13.1 · §10.3 ·\n--            §11.5(계정 상태 판정식) / 앱 계약 §4.2(원자성 순서 1~7)·§4.3(오류코드).\n--   - 웹 F2·앱 ensure_free_question_room·F12(구독 확정 내부 경로)가 전부 이 함수로\n--     수렴한다. 자격 판정 로직을 wrapper 마다 복제하지 않는다.\n--   - 원자성 순서(앱 §4.2 — 이 함수가 수행): ① 학생 역할 확인 ② 계정 상태·탈퇴\n--     write-block ③ 승인 멘토·상호 차단 ④ 학생 행 잠금 + 자격(활성 구독/무료질문)\n--     ⑤ 기존 방 조회 ⑥ INSERT … ON CONFLICT (student_id, mentor_id) DO NOTHING\n--     ⑦ 최종 방 재조회 반환. 근거 = uq_msr_pair UNIQUE INDEX 실측(§13.1).\n--   - 판정식은 정본 public.qna_create_question_thread 와 동일하게 고정한다:\n--     계정 상태(§11.5) · 승인(individual_question_user_is_approved_mentor) ·\n--     차단(user_blocks 양방향) · 활성 구독(lower(coalesce(status,''''))=''active'') ·\n--     무료 자격(가입 7일 / 전역 7회 / 멘토별 3회 — F3 free 분기와 동일 순서).\n--   - 방 확보는 무료질문권을 소비하지 않는다(소비는 F3 — §13.2 2단 구조).\n--   - p_require_entitlement=false(F12 구독 확정 경로)는 ④의 자격 검사만 건너뛰고\n--     entitlement=''subscription'' 으로 반환한다(§7 F10). room 참조(payment_id·\n--     subscription_id) 보정 규칙은 F12(M9) 소유 — 기존 방의 참조를 덮어쓰지 않는다.\n--   - 반환(내부 형상 — §8.1 예외): {ok,room_id,created,entitlement} / {ok:false,code}.\n--   - 보안: SECURITY DEFINER · SET search_path='''' · 완전 수식 · 같은 트랜잭션\n--     PUBLIC EXECUTE 회수. anon·authenticated·service_role EXECUTE 전부 미부여\n--     (§10.3 — 호출은 SECDEF wrapper 의 소유자 권한 문맥뿐, T-PERM-06).\n-- 선행조건: M1(20260730095435) 적용 완료(§20.2.1 — M5 : M1).\n-- rollback 정본: supabase/rollback/20260730105244_core_private_room_ensure_rollback.sql\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- A. 사전 게이트 — M1 경계·기반 객체 실측 (불일치 시 수정 0건 중단)\n-- -----------------------------------------------------------------------------\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = ''core_private'') THEN\n    RAISE EXCEPTION ''BATCH_C_BASELINE_OBJECT_MISMATCH: M1 core_private schema not applied'';\n  END IF;\n  IF has_schema_privilege(''anon'', ''core_private'', ''USAGE'')\n     OR has_schema_privilege(''authenticated'', ''core_private'', ''USAGE'')\n     OR has_schema_privilege(''service_role'', ''core_private'', ''USAGE'') THEN\n    RAISE EXCEPTION ''BATCH_C_BASELINE_OBJECT_MISMATCH: core_private boundary violated'';\n  END IF;\n  -- 기반: mentor_student_rooms 확정 컬럼 7종(§13.1 — 프로빙 금지) + uq_msr_pair\n  IF (SELECT count(*) FROM information_schema.columns\n       WHERE table_schema = ''public'' AND table_name = ''mentor_student_rooms''\n         AND column_name IN (''id'',''student_id'',''mentor_id'',''payment_id'',''subscription_id'',''created_at'',''updated_at'')) <> 7 THEN\n    RAISE EXCEPTION ''BATCH_C_BASELINE_OBJECT_MISMATCH: mentor_student_rooms columns mismatch'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = ''public''\n                  AND tablename = ''mentor_student_rooms'' AND indexname = ''uq_msr_pair'') THEN\n    RAISE EXCEPTION ''BATCH_C_BASELINE_OBJECT_MISMATCH: uq_msr_pair unique index missing'';\n  END IF;\n  -- 기반 헬퍼·테이블\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname = ''public''\n         AND p.proname IN (''individual_question_user_is_approved_mentor'', ''account_deletion_write_blocked'')) <> 2 THEN\n    RAISE EXCEPTION ''BATCH_C_BASELINE_OBJECT_MISMATCH: canonical helper functions missing'';\n  END IF;\n  IF (SELECT count(*) FROM information_schema.tables\n       WHERE table_schema = ''public''\n         AND table_name IN (''users'',''user_blocks'',''subscriptions'',''free_question_usage'')) <> 4 THEN\n    RAISE EXCEPTION ''BATCH_C_BASELINE_OBJECT_MISMATCH: base tables missing'';\n  END IF;\n  -- 대상 선재 금지 (부분 생성 은닉 금지)\n  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n              WHERE n.nspname = ''core_private'' AND p.proname = ''ensure_student_mentor_room'') THEN\n    RAISE EXCEPTION ''UNEXPECTED_EXISTING_CONTRACT_OBJECT: core_private.ensure_student_mentor_room already exists'';\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- B. F10 — 방 확보 공용 구현부\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION core_private.ensure_student_mentor_room(\n  p_student_id uuid,\n  p_mentor_id uuid,\n  p_payment_id uuid DEFAULT NULL,\n  p_subscription_id uuid DEFAULT NULL,\n  p_require_entitlement boolean DEFAULT true\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $$\nDECLARE\n  v_role       text;\n  v_status     text;\n  v_susp       timestamptz;\n  v_created_at timestamptz;\n  v_mrole      text;\n  v_total      int;\n  v_per        int;\n  v_entitlement text;\n  v_room       uuid;\n  v_created    boolean := false;\nBEGIN\n  -- 필수 인자(사전에 없는 예외는 전파 — §8.2. wrapper 가 NULL 을 넘기지 않는다)\n  IF p_student_id IS NULL OR p_mentor_id IS NULL THEN\n    RAISE EXCEPTION ''p_student_id and p_mentor_id are required'';\n  END IF;\n\n  -- ① 학생 역할 확인\n  SELECT u.role, u.status, u.suspended_until, u.created_at\n    INTO v_role, v_status, v_susp, v_created_at\n    FROM public.users u WHERE u.id = p_student_id;\n  IF NOT FOUND OR v_role IS DISTINCT FROM ''student'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ROLE_NOT_STUDENT'');\n  END IF;\n\n  -- ② 계정 상태·탈퇴 write-block (판정식 §11.5 — 정본 qna_create_question_thread 동일)\n  IF lower(coalesce(v_status, ''active'')) = ''banned'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_BANNED'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''suspended''\n     AND (v_susp IS NULL OR v_susp > now()) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_SUSPENDED'');\n  END IF;\n  IF public.account_deletion_write_blocked(p_student_id) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  END IF;\n\n  -- ③ 승인 멘토·상호 차단\n  SELECT u.role INTO v_mrole FROM public.users u WHERE u.id = p_mentor_id;\n  IF NOT FOUND OR v_mrole IS DISTINCT FROM ''mentor'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''MENTOR_NOT_FOUND'');\n  END IF;\n  IF NOT public.individual_question_user_is_approved_mentor(p_mentor_id) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''MENTOR_NOT_APPROVED'');\n  END IF;\n  IF EXISTS (SELECT 1 FROM public.user_blocks b\n              WHERE (b.blocker_id = p_student_id AND b.blocked_id = p_mentor_id)\n                 OR (b.blocker_id = p_mentor_id AND b.blocked_id = p_student_id)) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''BLOCKED'');\n  END IF;\n\n  -- ④ 학생 행 잠금 + 자격 확인 (동시 호출 직렬화 — T-CONC-01)\n  PERFORM 1 FROM public.users u WHERE u.id = p_student_id FOR UPDATE;\n  IF p_require_entitlement THEN\n    IF EXISTS (SELECT 1 FROM public.subscriptions s\n                WHERE s.student_id = p_student_id AND s.mentor_id = p_mentor_id\n                  AND lower(coalesce(s.status, '''')) = ''active'') THEN\n      v_entitlement := ''subscription'';\n    ELSE\n      -- 무료질문 자격 — 정본 F3 free 분기와 동일 규칙·동일 순서(가입 7일/전역 7회/멘토별 3회)\n      IF v_created_at IS NOT NULL AND now() >= v_created_at + interval ''7 days'' THEN\n        RETURN jsonb_build_object(''ok'', false, ''code'', ''FREE_QUOTA_EXPIRED'');\n      END IF;\n      SELECT count(*) INTO v_total FROM public.free_question_usage f\n       WHERE f.student_id = p_student_id;\n      IF v_total >= 7 THEN\n        RETURN jsonb_build_object(''ok'', false, ''code'', ''FREE_QUOTA_TOTAL_EXHAUSTED'');\n      END IF;\n      SELECT count(*) INTO v_per FROM public.free_question_usage f\n       WHERE f.student_id = p_student_id AND f.mentor_id = p_mentor_id;\n      IF v_per >= 3 THEN\n        RETURN jsonb_build_object(''ok'', false, ''code'', ''FREE_QUOTA_MENTOR_EXHAUSTED'');\n      END IF;\n      v_entitlement := ''free'';\n    END IF;\n  ELSE\n    -- F12 구독 확정 경로 — 구독이 방금 확정됐으므로 자격 재검사를 건너뛴다(§7 F10)\n    v_entitlement := ''subscription'';\n  END IF;\n\n  -- ⑤ 기존 방 조회\n  SELECT r.id INTO v_room FROM public.mentor_student_rooms r\n   WHERE r.student_id = p_student_id AND r.mentor_id = p_mentor_id;\n\n  -- ⑥ 없으면 원자 INSERT (uq_msr_pair 추론 — 동시 경합에서 방은 정확히 1개)\n  IF v_room IS NULL THEN\n    INSERT INTO public.mentor_student_rooms (student_id, mentor_id, payment_id, subscription_id)\n    VALUES (p_student_id, p_mentor_id, p_payment_id, p_subscription_id)\n    ON CONFLICT (student_id, mentor_id) DO NOTHING\n    RETURNING id INTO v_room;\n    v_created := v_room IS NOT NULL;\n  END IF;\n\n  -- ⑦ 최종 방 재조회 (경합 패자 경로 포함)\n  IF v_room IS NULL THEN\n    SELECT r.id INTO v_room FROM public.mentor_student_rooms r\n     WHERE r.student_id = p_student_id AND r.mentor_id = p_mentor_id;\n  END IF;\n  IF v_room IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ROOM_ENSURE_FAILED'');\n  END IF;\n\n  RETURN jsonb_build_object(''ok'', true, ''room_id'', v_room, ''created'', v_created,\n                            ''entitlement'', v_entitlement);\nEND $$;\n\nCOMMENT ON FUNCTION core_private.ensure_student_mentor_room(uuid, uuid, uuid, uuid, boolean) IS\n  ''S2 M5 F10(계약 §7): 방 확보 공용 구현부 — 웹 F2·앱 wrapper·F12 가 수렴. 외부 EXECUTE 0(SECDEF wrapper 소유자 문맥 전용).'';\n\n-- [필수] 같은 트랜잭션에서 PUBLIC EXECUTE 회수 — 외부 역할 EXECUTE 0 (§10.3)\nREVOKE ALL ON FUNCTION core_private.ensure_student_mentor_room(uuid, uuid, uuid, uuid, boolean) FROM PUBLIC;\n\n-- -----------------------------------------------------------------------------\n-- C. 적용 직후 자가 검증\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_oid oid;\nBEGIN\n  SELECT p.oid INTO v_oid\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''core_private'' AND p.proname = ''ensure_student_mentor_room''\n     AND pg_get_function_identity_arguments(p.oid)\n         = ''p_student_id uuid, p_mentor_id uuid, p_payment_id uuid, p_subscription_id uuid, p_require_entitlement boolean''\n     AND p.prosecdef AND p.proconfig::text LIKE ''%search_path=%'';\n  IF v_oid IS NULL THEN\n    RAISE EXCEPTION ''S2_M5_SELFCHECK: F10 identity/attributes mismatch'';\n  END IF;\n  IF has_function_privilege(''anon'', v_oid, ''EXECUTE'')\n     OR has_function_privilege(''authenticated'', v_oid, ''EXECUTE'')\n     OR has_function_privilege(''service_role'', v_oid, ''EXECUTE'') THEN\n    RAISE EXCEPTION ''S2_M5_SELFCHECK: F10 external EXECUTE must be 0'';\n  END IF;\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname = ''core_private'') <> 1 THEN\n    RAISE EXCEPTION ''S2_M5_SELFCHECK: core_private must contain exactly F10 after M5'';\n  END IF;\nEND $$;\n\ncommit;\n"], "idempotency_key": null}, {"name": "20260730105248_api_web_v1_self_rpc", "version": "20260731102007", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260730105248_api_web_v1_self_rpc.sql (S2 M6)\n-- =============================================================================\n-- api_web_v1 self RPC — F1·F2·F3·F9 + V6·V7 조회 RPC + GRANT.\n-- 정본 계약: docs/contracts/api_web_v1_contract_v1_1.md\n--   §7 F1(weekly_question_usage_self — XW-01 해소: 학생 id 를 인자로 받지 않고\n--     auth.uid() 도출, 계산부는 정본 get_weekly_question_usage 호출로 단일화) ·\n--   §7 F2(ensure_free_question_room — F10 얇은 wrapper, 앱 동명 함수와 시그니처·\n--     반환·오류코드 완전 동일) ·\n--   §7 F3(qna_create_question_thread — 정본 호출 + 예외→envelope 변환(XW-07),\n--     트리거 FREE_QUESTION_* 4종을 FREE_QUOTA_* 로 수렴(XW-08), 사전에 없는\n--     예외는 그대로 전파 — §8.2) ·\n--   §7 F9(account_deletion_status_self — 기존 public 함수 얇은 wrapper,\n--     envelope(ok/contract_version) 통일 + §8.3 job_id 필드) ·\n--   §6 V6(my_subscriptions_self — 범위 제한 SECDEF RPC, subscriptions_select_parties\n--     와 동일한 당사자 판정식, current_plan_amount_cents = 라이브 mentor_plans) ·\n--   §6 V7(mentor_settlement_self — ssi_select_mentor_own 동일 판정식,\n--     idempotency_key·ledger_id·payment_id 비노출) ·\n--   §8(envelope) · §9(오류코드 사전) · §10.3(GRANT — authenticated·service_role).\n--   라벨 규칙(§7 F0 승계): users.nickname 만, 비면 ''쌤버십 사용자''. PII 미반환.\n-- 선행조건: M5(20260730105244) 적용 완료(§20.2.1 — M6 : M5).\n-- rollback 정본: supabase/rollback/20260730105248_api_web_v1_self_rpc_rollback.sql\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- A. 사전 게이트\n-- -----------------------------------------------------------------------------\nDO $$\nBEGIN\n  -- M1·M5 적용 확인\n  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = ''api_web_v1'') THEN\n    RAISE EXCEPTION ''BATCH_C_BASELINE_OBJECT_MISMATCH: M1 api_web_v1 schema not applied'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''core_private'' AND p.proname = ''ensure_student_mentor_room'') THEN\n    RAISE EXCEPTION ''BATCH_C_BASELINE_OBJECT_MISMATCH: M5 F10 not applied'';\n  END IF;\n  -- 정본 함수 실측\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''public'' AND p.proname = ''get_weekly_question_usage''\n                    AND pg_get_function_identity_arguments(p.oid) = ''p_student_id uuid, p_mentor_id uuid'')\n     OR NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''public'' AND p.proname = ''qna_create_question_thread''\n                    AND pg_get_function_identity_arguments(p.oid)\n                        = ''p_room_id uuid, p_title text, p_subject text, p_topic text, p_first_message_body text'')\n     OR NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''public'' AND p.proname = ''account_deletion_status_self'')\n     OR (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n          WHERE n.nspname = ''public''\n            AND p.proname IN (''account_deletion_active_job_id'', ''account_deletion_latest_job_id'')) <> 2 THEN\n    RAISE EXCEPTION ''BATCH_C_BASELINE_OBJECT_MISMATCH: canonical public functions missing'';\n  END IF;\n  -- V6·V7 기반 컬럼 실측 (불일치는 추정하지 않고 중단)\n  IF (SELECT count(*) FROM information_schema.columns\n       WHERE table_schema = ''public'' AND table_name = ''subscriptions''\n         AND column_name IN (''id'',''student_id'',''mentor_id'',''plan_id'',''plan_tier'',''status'',''started_at'',\n                             ''current_period_start'',''current_period_end'',''next_billing_at'',\n                             ''cancel_at_period_end'',''grace_until'',''created_at'')) <> 13\n     OR (SELECT count(*) FROM information_schema.columns\n          WHERE table_schema = ''public'' AND table_name = ''mentor_plans''\n            AND column_name IN (''id'',''amount_cents'')) <> 2\n     OR (SELECT count(*) FROM information_schema.columns\n          WHERE table_schema = ''public'' AND table_name = ''subscription_settlement_items''\n            AND column_name IN (''id'',''subscription_id'',''mentor_id'',''student_id'',''event_type'',''billing_at'',\n                                ''period_start'',''period_end'',''gross_cents'',''platform_fee_cents'',\n                                ''mentor_amount_cents'',''fee_rate'',''status'',''hold_reason'',''paid_at'',''created_at'')) <> 16 THEN\n    RAISE EXCEPTION ''BATCH_C_BASELINE_OBJECT_MISMATCH: V6/V7 base columns mismatch'';\n  END IF;\n  -- 대상 선재 금지\n  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n              WHERE n.nspname = ''api_web_v1''\n                AND p.proname IN (''weekly_question_usage_self'',''ensure_free_question_room'',\n                                  ''qna_create_question_thread'',''account_deletion_status_self'',\n                                  ''my_subscriptions_self'',''mentor_settlement_self'')) THEN\n    RAISE EXCEPTION ''UNEXPECTED_EXISTING_CONTRACT_OBJECT: M6 target functions already exist'';\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- B. F1 weekly_question_usage_self (T2 — XW-01 해소)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_web_v1.weekly_question_usage_self(p_mentor_id uuid)\nRETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $$\nDECLARE\n  v_uid uuid := (SELECT auth.uid());\nBEGIN\n  -- 사전 검사 필수(§7 F1) — 정본의 원문 raise 가 새어 나가지 않게 선검사한다\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  IF p_mentor_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_ID_REQUIRED'');\n  END IF;\n  -- 계산부는 정본 단일화 — 한도 규칙을 두 곳에 만들지 않는다(§7 F1)\n  RETURN public.get_weekly_question_usage(v_uid, p_mentor_id)::jsonb\n         || jsonb_build_object(''ok'', true, ''contract_version'', 1);\nEND $$;\n\nCOMMENT ON FUNCTION api_web_v1.weekly_question_usage_self(uuid) IS\n  ''S2 M6 F1(계약 §7): 자기 주간 사용량 — 학생 id 는 auth.uid() 로만 도출(XW-01). 계산은 정본 get_weekly_question_usage 호출.'';\n\n-- -----------------------------------------------------------------------------\n-- C. F2 ensure_free_question_room (T2 — F10 얇은 wrapper, 앱 동명과 완전 동일)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_web_v1.ensure_free_question_room(p_mentor_id uuid)\nRETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $$\nDECLARE\n  v_uid uuid := (SELECT auth.uid());\nBEGIN\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  IF p_mentor_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_FOUND'');\n  END IF;\n  -- 자격 판정·원자성은 전부 F10 이 수행(§7 F2 — wrapper 는 auth.uid() 결합만)\n  RETURN core_private.ensure_student_mentor_room(v_uid, p_mentor_id, NULL, NULL, true)\n         || jsonb_build_object(''contract_version'', 1);\nEND $$;\n\nCOMMENT ON FUNCTION api_web_v1.ensure_free_question_room(uuid) IS\n  ''S2 M6 F2(계약 §7): 무료질문 방 확보 — core_private.ensure_student_mentor_room(F10) 얇은 wrapper. 앱 동명 함수와 시그니처·반환·오류코드 동일.'';\n\n-- -----------------------------------------------------------------------------\n-- D. F3 qna_create_question_thread (T2 — 정본 호출 + envelope 변환, XW-07/XW-08)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_web_v1.qna_create_question_thread(\n  p_room_id uuid,\n  p_title text,\n  p_subject text DEFAULT NULL,\n  p_topic text DEFAULT NULL,\n  p_first_message_body text DEFAULT NULL\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $$\nDECLARE\n  v_res  jsonb;\n  v_code text;\nBEGIN\n  -- 판정 로직을 복제하지 않는다 — 정본 호출 + 예외의 안정 코드 변환만(§13.2)\n  v_res := public.qna_create_question_thread(p_room_id, p_title, p_subject, p_topic, p_first_message_body);\n  RETURN v_res || jsonb_build_object(''contract_version'', 1);\nEXCEPTION WHEN OTHERS THEN\n  v_code := CASE SQLERRM\n    -- 트리거 코드 수렴(XW-08 — §9.8 매핑표)\n    WHEN ''FREE_QUESTION_EXPIRED''           THEN ''FREE_QUOTA_EXPIRED''\n    WHEN ''FREE_QUESTION_TOTAL_LIMIT''       THEN ''FREE_QUOTA_TOTAL_EXHAUSTED''\n    WHEN ''FREE_QUESTION_PER_MENTOR_LIMIT''  THEN ''FREE_QUOTA_MENTOR_EXHAUSTED''\n    WHEN ''FREE_QUESTION_STUDENT_NOT_FOUND'' THEN ''FREE_QUOTA_STUDENT_NOT_FOUND''\n    -- 정본 raise 14종(실측 전수 — §9.8 \"qna_* raise 14종 동명 유지\")\n    WHEN ''AUTH_REQUIRED''                 THEN ''AUTH_REQUIRED''\n    WHEN ''TITLE_REQUIRED''                THEN ''TITLE_REQUIRED''\n    WHEN ''ROOM_NOT_FOUND''                THEN ''ROOM_NOT_FOUND''\n    WHEN ''NOT_ROOM_PARTY''                THEN ''NOT_ROOM_PARTY''\n    WHEN ''MENTOR_CANNOT_CREATE_THREAD''   THEN ''MENTOR_CANNOT_CREATE_THREAD''\n    WHEN ''ACCOUNT_BANNED''                THEN ''ACCOUNT_BANNED''\n    WHEN ''ACCOUNT_SUSPENDED''             THEN ''ACCOUNT_SUSPENDED''\n    WHEN ''ACCOUNT_DELETION_IN_PROGRESS''  THEN ''ACCOUNT_DELETION_IN_PROGRESS''\n    WHEN ''BLOCKED''                       THEN ''BLOCKED''\n    WHEN ''MENTOR_NOT_APPROVED''           THEN ''MENTOR_NOT_APPROVED''\n    WHEN ''SUBSCRIPTION_REFUND_PENDING''   THEN ''SUBSCRIPTION_REFUND_PENDING''\n    WHEN ''WEEKLY_LIMIT_EXHAUSTED''        THEN ''WEEKLY_LIMIT_EXHAUSTED''\n    WHEN ''FREE_QUOTA_EXPIRED''            THEN ''FREE_QUOTA_EXPIRED''\n    WHEN ''FREE_QUOTA_TOTAL_EXHAUSTED''    THEN ''FREE_QUOTA_TOTAL_EXHAUSTED''\n    WHEN ''FREE_QUOTA_MENTOR_EXHAUSTED''   THEN ''FREE_QUOTA_MENTOR_EXHAUSTED''\n    ELSE NULL\n  END;\n  IF v_code IS NULL THEN\n    -- 사전에 없는 예외는 삼키지 않고 그대로 전파(§8.2 — T-CON-06)\n    RAISE;\n  END IF;\n  RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', v_code);\nEND $$;\n\nCOMMENT ON FUNCTION api_web_v1.qna_create_question_thread(uuid, text, text, text, text) IS\n  ''S2 M6 F3(계약 §7): 정본 스레드 생성 호출 + raise→안정 코드 envelope 변환(XW-07) + FREE_QUESTION_* 수렴(XW-08). 사전 밖 예외는 전파.'';\n\n-- -----------------------------------------------------------------------------\n-- E. F9 account_deletion_status_self (T2 — 얇은 wrapper, envelope 통일)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_web_v1.account_deletion_status_self()\nRETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $$\nDECLARE\n  v_uid uuid := (SELECT auth.uid());\n  v_res jsonb;\nBEGIN\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  v_res := public.account_deletion_status_self();\n  -- §8.3 F9 필드(state·cancelable_until·job_id) — job_id 는 정본이 쓰는 동일 헬퍼로 도출\n  RETURN v_res || jsonb_build_object(\n    ''contract_version'', 1,\n    ''job_id'', coalesce(public.account_deletion_active_job_id(v_uid),\n                       public.account_deletion_latest_job_id(v_uid)));\nEND $$;\n\nCOMMENT ON FUNCTION api_web_v1.account_deletion_status_self() IS\n  ''S2 M6 F9(계약 §7): 기존 public.account_deletion_status_self 얇은 wrapper — envelope(ok/contract_version)·job_id 통일. 신규 판정 로직 없음.'';\n\n-- -----------------------------------------------------------------------------\n-- F. V6 my_subscriptions_self() — 범위 제한 SECDEF 조회 RPC (§6 V6)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_web_v1.my_subscriptions_self()\nRETURNS TABLE (\n  subscription_id            uuid,\n  mentor_id                  uuid,\n  mentor_label               text,\n  plan_id                    uuid,\n  plan_tier                  text,\n  current_plan_amount_cents  integer,\n  status                     text,\n  started_at                 timestamptz,\n  current_period_start       timestamptz,\n  current_period_end         timestamptz,\n  next_billing_at            timestamptz,\n  cancel_at_period_end       boolean,\n  grace_until                timestamptz,\n  created_at                 timestamptz\n)\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '''' AS $$\nBEGIN\n  -- 빈 결과가 아니라 예외 42501 (§6 V6)\n  IF (SELECT auth.uid()) IS NULL THEN\n    RAISE EXCEPTION ''AUTH_REQUIRED'' USING errcode = ''42501'';\n  END IF;\n  RETURN QUERY\n  SELECT\n    s.id,\n    s.mentor_id,\n    coalesce(nullif(btrim(u.nickname), ''''), ''쌤버십 사용자''),  -- F0 승계 라벨 규칙(PII 미반환)\n    s.plan_id,\n    s.plan_tier,\n    mp.amount_cents,                                            -- 라이브 현재 플랜 가격(rev 8 §6.4 필드명 확정)\n    s.status,\n    s.started_at,\n    s.current_period_start,\n    s.current_period_end,\n    s.next_billing_at,\n    s.cancel_at_period_end,\n    s.grace_until,\n    s.created_at\n  FROM public.subscriptions s\n  LEFT JOIN public.users u ON u.id = s.mentor_id\n  LEFT JOIN public.mentor_plans mp ON mp.id = s.plan_id\n  WHERE (SELECT auth.uid()) IN (s.student_id, s.mentor_id);     -- subscriptions_select_parties 동일 판정식\nEND $$;\n\nCOMMENT ON FUNCTION api_web_v1.my_subscriptions_self() IS\n  ''S2 M6 V6(계약 §6): 자기 당사자 구독 조회 RPC — 당사자 판정식은 subscriptions_select_parties 와 동일. XW-10 프로빙 대체.'';\n\n-- -----------------------------------------------------------------------------\n-- G. V7 mentor_settlement_self() — 범위 제한 SECDEF 조회 RPC (§6 V7)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_web_v1.mentor_settlement_self()\nRETURNS TABLE (\n  item_id             uuid,\n  subscription_id     uuid,\n  student_label       text,\n  event_type          text,\n  billing_at          timestamptz,\n  period_start        timestamptz,\n  period_end          timestamptz,\n  gross_cents         bigint,\n  platform_fee_cents  bigint,\n  mentor_amount_cents bigint,\n  fee_rate            numeric,\n  status              text,\n  hold_reason         text,\n  paid_at             timestamptz,\n  created_at          timestamptz\n)\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '''' AS $$\nBEGIN\n  IF (SELECT auth.uid()) IS NULL THEN\n    RAISE EXCEPTION ''AUTH_REQUIRED'' USING errcode = ''42501'';\n  END IF;\n  RETURN QUERY\n  SELECT\n    i.id,\n    i.subscription_id,\n    coalesce(nullif(btrim(u.nickname), ''''), ''쌤버십 사용자''),  -- F0 승계 라벨 규칙\n    i.event_type,\n    i.billing_at,\n    i.period_start,\n    i.period_end,\n    i.gross_cents,\n    i.platform_fee_cents,\n    i.mentor_amount_cents,\n    i.fee_rate,\n    i.status,\n    i.hold_reason,\n    i.paid_at,\n    i.created_at\n  FROM public.subscription_settlement_items i\n  LEFT JOIN public.users u ON u.id = i.student_id\n  WHERE i.mentor_id = (SELECT auth.uid());                      -- ssi_select_mentor_own 동일 판정식\n  -- idempotency_key·ledger_id·payment_id 는 내부 참조 — 노출하지 않는다(§6 V7)\nEND $$;\n\nCOMMENT ON FUNCTION api_web_v1.mentor_settlement_self() IS\n  ''S2 M6 V7(계약 §6): 멘토 자기 정산 항목 조회 RPC — ssi_select_mentor_own 동일 판정식. idempotency_key/ledger_id/payment_id 비노출.'';\n\n-- -----------------------------------------------------------------------------\n-- H. GRANT (§10.3 — 명시 REVOKE 는 default privileges 와 이중 방어)\n-- -----------------------------------------------------------------------------\nREVOKE ALL ON FUNCTION api_web_v1.weekly_question_usage_self(uuid)                          FROM PUBLIC;\nREVOKE ALL ON FUNCTION api_web_v1.ensure_free_question_room(uuid)                            FROM PUBLIC;\nREVOKE ALL ON FUNCTION api_web_v1.qna_create_question_thread(uuid, text, text, text, text)   FROM PUBLIC;\nREVOKE ALL ON FUNCTION api_web_v1.account_deletion_status_self()                             FROM PUBLIC;\nREVOKE ALL ON FUNCTION api_web_v1.my_subscriptions_self()                                    FROM PUBLIC;\nREVOKE ALL ON FUNCTION api_web_v1.mentor_settlement_self()                                   FROM PUBLIC;\n\nGRANT EXECUTE ON FUNCTION api_web_v1.weekly_question_usage_self(uuid)                        TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION api_web_v1.ensure_free_question_room(uuid)                         TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION api_web_v1.qna_create_question_thread(uuid, text, text, text, text) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION api_web_v1.account_deletion_status_self()                          TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION api_web_v1.my_subscriptions_self()                                 TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION api_web_v1.mentor_settlement_self()                                TO authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- I. 적용 직후 자가 검증\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_cnt int;\nBEGIN\n  SELECT count(*) INTO v_cnt\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''api_web_v1''\n     AND p.prosecdef AND p.proconfig::text LIKE ''%search_path=%''\n     AND NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n     AND has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n     AND has_function_privilege(''service_role'', p.oid, ''EXECUTE'')\n     AND (p.proacl IS NULL OR (p.proacl::text NOT LIKE ''{=%'' AND p.proacl::text NOT LIKE ''%,=%''))\n     AND (pg_get_function_identity_arguments(p.oid), p.proname) IN\n         ((''p_mentor_id uuid'', ''weekly_question_usage_self''),\n          (''p_mentor_id uuid'', ''ensure_free_question_room''),\n          (''p_room_id uuid, p_title text, p_subject text, p_topic text, p_first_message_body text'', ''qna_create_question_thread''),\n          (('''', ''account_deletion_status_self'')),\n          (('''', ''my_subscriptions_self'')),\n          (('''', ''mentor_settlement_self'')));\n  IF v_cnt <> 6 THEN\n    RAISE EXCEPTION ''S2_M6_SELFCHECK: expected 6 hardened api_web_v1 functions, matched %'', v_cnt;\n  END IF;\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname = ''api_web_v1'') <> 6 THEN\n    RAISE EXCEPTION ''S2_M6_SELFCHECK: api_web_v1 must contain exactly 6 functions after M6'';\n  END IF;\nEND $$;\n\ncommit;\n"], "idempotency_key": null}, {"name": "20260730105252_api_web_v1_community_rpc", "version": "20260731113927", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260730105252_api_web_v1_community_rpc.sql (S2 M7)\n-- =============================================================================\n-- 커뮤니티 글 쓰기 — 공용 구현부 B-1~B-4(core_private) + 웹 wrapper F4·F5·F6.\n-- 정본 계약: docs/contracts/api_web_v1_contract_v1_1.md §7 F4·F5·F6(B-1~B-4) ·\n--   §9.4(오류코드 — 앱 계약 §6.4 와 동일 집합) · §14.3(이미지 5종 검증) ·\n--   §14.4(멱등 replay-first — 재호출 선행·보상 삭제 후행) · §10.3(GRANT) /\n--   앱 계약 §6.1~§6.5(웹·앱 동등 — 동일 공용 구현부 공유).\n--   - 작성 자격(rev 8 A-10): F4 create 는 승인 멘토 전용 — users.role=''mentor''\n--     (위반 ROLE_NOT_MENTOR) + individual_question_user_is_approved_mentor\n--     (미승인 MENTOR_NOT_APPROVED). 관리자도 일반 작성 경로에서는 거부.\n--     F5 는 작성자 본인 기준 + 학생 글 수정 거부(ROLE_NOT_MENTOR).\n--     F6 soft-delete 는 작성자 본인이면 역할 무관 허용(기존 학생 글 보존 규칙).\n--   - 멱등(replay-first — §7 F4 4단계): auth 결합 직후, 신규 쓰기 검증보다 먼저\n--     (author_id, create_idempotency_key) 기존 커밋 행을 조회해 있으면 즉시\n--     idempotent_replay:true 재생 반환(현재 시점 재검증에 좌우되지 않음).\n--     근거 = community_posts_author_idem_key UNIQUE INDEX 실측.\n--   - 본문 검증(rev 8 D — B-04 동결): 연락처 마스킹만 수행. 금지어 검사 폐지 —\n--     POLICY_RESTRICTED 는 예약 코드이며 발생하지 않는다. 마스킹 규칙은 웹 정본\n--     lib/customRequest/contactMasking.ts 를 문자 그대로 이식했다(전화/한글전화/\n--     난독화 이메일/이메일/메신저 링크/메신저 핸들 — 적용 순서 동일). 제목·본문\n--     모두 마스킹한다(웹 communityBoardActions 실측 동작 동일).\n--   - 이미지 ref 검증(B-4 — §14.3 5종): 허용 버킷 / path 첫 세그먼트 = 소유자 /\n--     storage.objects 실존 / 소유자·MIME·크기 일치 / 개수 ≤ 5.\n--   - INSERT 컬럼은 현행 웹 insertCommunityBoardPost 와 동일(body=content 병기,\n--     hashtags ''{}'', author_label·author_role 서버 도출 — 클라이언트 author_* 불수신).\n--     라벨 규칙 = §7 F0 승계(nickname → 비면 ''쌤버십 사용자'', student/mentor 외 NULL).\n--   - 보안: 구현부 4종은 SECURITY INVOKER + SET search_path='''' + 완전 수식 +\n--     외부 EXECUTE 0(§10.3 — SECDEF wrapper 의 소유자 권한 문맥에서만 실행).\n--     wrapper 3종은 SECURITY DEFINER + SET search_path=''''.\n-- 선행조건: M1(20260730095435) 적용 완료(§20.2.1 — M7 : M1).\n-- rollback 정본: supabase/rollback/20260730105252_api_web_v1_community_rpc_rollback.sql\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- A. 사전 게이트\n-- -----------------------------------------------------------------------------\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = ''api_web_v1'')\n     OR NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = ''core_private'') THEN\n    RAISE EXCEPTION ''BATCH_C_BASELINE_OBJECT_MISMATCH: M1 schemas not applied'';\n  END IF;\n  -- 기반 컬럼 실측 (community_posts — 현행 웹 insert 컬럼 집합)\n  IF (SELECT count(*) FROM information_schema.columns\n       WHERE table_schema = ''public'' AND table_name = ''community_posts''\n         AND column_name IN (''id'',''author_id'',''title'',''body'',''content'',''category'',''image_urls'',''hashtags'',\n                             ''status'',''author_label'',''author_role'',''create_idempotency_key'',\n                             ''deleted_at'',''updated_at'')) <> 14 THEN\n    RAISE EXCEPTION ''BATCH_C_BASELINE_OBJECT_MISMATCH: community_posts columns mismatch'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = ''public''\n                  AND indexname = ''community_posts_author_idem_key'') THEN\n    RAISE EXCEPTION ''BATCH_C_BASELINE_OBJECT_MISMATCH: community_posts_author_idem_key missing'';\n  END IF;\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname = ''public''\n         AND p.proname IN (''individual_question_user_is_approved_mentor'', ''account_deletion_write_blocked'')) <> 2 THEN\n    RAISE EXCEPTION ''BATCH_C_BASELINE_OBJECT_MISMATCH: canonical helper functions missing'';\n  END IF;\n  -- 대상 선재 금지\n  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n              WHERE (n.nspname = ''core_private''\n                     AND p.proname IN (''community_post_create_impl'',''community_post_update_impl'',\n                                       ''community_post_soft_delete_impl'',''community_image_refs_validate''))\n                 OR (n.nspname = ''api_web_v1''\n                     AND p.proname IN (''community_post_create'',''community_post_update'',''community_post_soft_delete''))) THEN\n    RAISE EXCEPTION ''UNEXPECTED_EXISTING_CONTRACT_OBJECT: M7 target functions already exist'';\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- B. B-4 core_private.community_image_refs_validate — 공용 이미지 ref 검증기 (§14.3)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION core_private.community_image_refs_validate(\n  p_owner_id uuid, p_image_refs text[]\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY INVOKER SET search_path = '''' AS $fn$\nDECLARE\n  v_refs  text[] := coalesce(p_image_refs, ''{}''::text[]);\n  v_ref   text;\n  v_path  text;\n  v_meta  jsonb;\n  v_owner uuid;\nBEGIN\n  IF p_owner_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  IF coalesce(array_length(v_refs, 1), 0) > 5 THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''IMAGE_COUNT_EXCEEDED'');\n  END IF;\n  FOREACH v_ref IN ARRAY v_refs LOOP\n    -- ① 허용 버킷 (정본 ref 형식: community-post-images/{uid}/{object} — §14.1)\n    IF v_ref IS NULL OR v_ref !~ ''^community-post-images/'' THEN\n      RETURN jsonb_build_object(''ok'', false, ''code'', ''IMAGE_REF_INVALID'');\n    END IF;\n    v_path := substring(v_ref FROM char_length(''community-post-images/'') + 1);\n    IF split_part(v_path, ''/'', 2) = '''' THEN\n      RETURN jsonb_build_object(''ok'', false, ''code'', ''IMAGE_REF_INVALID'');\n    END IF;\n    -- ② path 첫 세그먼트 = 소유자\n    IF split_part(v_path, ''/'', 1) IS DISTINCT FROM p_owner_id::text THEN\n      RETURN jsonb_build_object(''ok'', false, ''code'', ''IMAGE_NOT_OWNED'');\n    END IF;\n    -- ③ storage.objects 실존\n    SELECT o.metadata, coalesce(o.owner, nullif(o.owner_id, '''')::uuid)\n      INTO v_meta, v_owner\n      FROM storage.objects o\n     WHERE o.bucket_id = ''community-post-images'' AND o.name = v_path;\n    IF NOT FOUND THEN\n      RETURN jsonb_build_object(''ok'', false, ''code'', ''IMAGE_OBJECT_NOT_FOUND'');\n    END IF;\n    -- ④ 소유자·MIME·크기 (버킷 정책 실측값 — 5 MiB · 4종 MIME)\n    IF v_owner IS DISTINCT FROM p_owner_id THEN\n      RETURN jsonb_build_object(''ok'', false, ''code'', ''IMAGE_NOT_OWNED'');\n    END IF;\n    IF coalesce(v_meta ->> ''mimetype'', '''')\n       NOT IN (''image/jpeg'', ''image/png'', ''image/webp'', ''image/gif'') THEN\n      RETURN jsonb_build_object(''ok'', false, ''code'', ''IMAGE_MIME_NOT_ALLOWED'');\n    END IF;\n    IF coalesce((v_meta ->> ''size'')::bigint, 0) > 5242880 THEN\n      RETURN jsonb_build_object(''ok'', false, ''code'', ''IMAGE_SIZE_EXCEEDED'');\n    END IF;\n  END LOOP;\n  RETURN jsonb_build_object(''ok'', true);\nEND $fn$;\n\nCOMMENT ON FUNCTION core_private.community_image_refs_validate(uuid, text[]) IS\n  ''S2 M7 B-4(계약 §7): 커뮤니티 이미지 ref 공용 검증기(§14.3 5종). 외부 EXECUTE 0.'';\n\n-- -----------------------------------------------------------------------------\n-- C. B-1 core_private.community_post_create_impl (replay-first — §7 F4)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION core_private.community_post_create_impl(\n  p_author_id uuid, p_title text, p_body text, p_category text,\n  p_image_refs text[], p_status text, p_idempotency_key uuid\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY INVOKER SET search_path = '''' AS $fn$\nDECLARE\n  v_role     text;\n  v_status   text;\n  v_susp     timestamptz;\n  v_nickname text;\n  v_title    text;\n  v_body     text;\n  v_val      jsonb;\n  v_id       uuid;\nBEGIN\n  IF p_author_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  -- 멱등키 필수(§14.4) — 계약 밖 입력은 전파(§8.2)\n  IF p_idempotency_key IS NULL THEN\n    RAISE EXCEPTION ''p_idempotency_key is required'';\n  END IF;\n\n  -- [replay-first — 신규 쓰기 검증보다 먼저] 기존 커밋 행 재생 (§7 F4 1~2단계)\n  SELECT cp.id INTO v_id FROM public.community_posts cp\n   WHERE cp.author_id = p_author_id AND cp.create_idempotency_key = p_idempotency_key;\n  IF FOUND THEN\n    RETURN jsonb_build_object(''ok'', true, ''post_id'', v_id, ''idempotent_replay'', true);\n  END IF;\n\n  -- [신규 쓰기 검증 — 역할 → 승인 → 계정 → 본문 → 이미지 (§7 F4 3단계)]\n  SELECT u.role, u.status, u.suspended_until, u.nickname\n    INTO v_role, v_status, v_susp, v_nickname\n    FROM public.users u WHERE u.id = p_author_id;\n  IF NOT FOUND OR v_role IS DISTINCT FROM ''mentor'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ROLE_NOT_MENTOR'');\n  END IF;\n  IF NOT public.individual_question_user_is_approved_mentor(p_author_id) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''MENTOR_NOT_APPROVED'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''banned'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_BANNED'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''suspended'' AND (v_susp IS NULL OR v_susp > now()) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_SUSPENDED'');\n  END IF;\n  IF public.account_deletion_write_blocked(p_author_id) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  END IF;\n  IF p_status NOT IN (''draft'', ''published'') THEN\n    RAISE EXCEPTION ''p_status must be draft|published'';\n  END IF;\n  v_title := btrim(coalesce(p_title, ''''));\n  IF v_title = '''' THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''TITLE_REQUIRED'');\n  END IF;\n  IF p_category IS NULL OR p_category NOT IN (''study'', ''school'', ''career'', ''college'', ''free'') THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''CATEGORY_INVALID'');\n  END IF;\n  v_body := btrim(coalesce(p_body, ''''));\n  IF p_status = ''published'' AND char_length(v_body) < 10 THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''BODY_TOO_SHORT'');\n  END IF;\n\n  -- [연락처 마스킹 — lib/customRequest/contactMasking.ts 정본 이식, 적용 순서 동일.\n  --  제목·본문 모두 마스킹(웹 실측 동작). 금지어 검사 없음(rev 8 D — B-04 동결)]\n  v_title := regexp_replace(v_title, ''(^|[^0-9])(\\+82[-._\\s]?0?1[0-9][-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4}|0(?:10|11|16|17|18|19|2|[3-6][1-5]|50|70|80)[-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4})(?![0-9])'', ''\\1[연락처 비공개]'', ''g'');\n  v_body  := regexp_replace(v_body,  ''(^|[^0-9])(\\+82[-._\\s]?0?1[0-9][-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4}|0(?:10|11|16|17|18|19|2|[3-6][1-5]|50|70|80)[-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4})(?![0-9])'', ''\\1[연락처 비공개]'', ''g'');\n  v_title := regexp_replace(v_title, ''(공일공|영일영)[\\s\\-._]*[0-9공영일이삼사오육칠팔구][0-9공영일이삼사오육칠팔구\\s\\-._]{6,12}'', ''[연락처 비공개]'', ''g'');\n  v_body  := regexp_replace(v_body,  ''(공일공|영일영)[\\s\\-._]*[0-9공영일이삼사오육칠팔구][0-9공영일이삼사오육칠팔구\\s\\-._]{6,12}'', ''[연락처 비공개]'', ''g'');\n  v_title := regexp_replace(v_title, ''[A-Za-z0-9._%+-]+\\s*[\\[({（]\\s*at\\s*[\\])}）]\\s*[A-Za-z0-9.-]+\\s*(?:[\\[({（]\\s*dot\\s*[\\])}）]|\\.)\\s*[A-Za-z]{2,}'', ''[연락처 비공개]'', ''gi'');\n  v_body  := regexp_replace(v_body,  ''[A-Za-z0-9._%+-]+\\s*[\\[({（]\\s*at\\s*[\\])}）]\\s*[A-Za-z0-9.-]+\\s*(?:[\\[({（]\\s*dot\\s*[\\])}）]|\\.)\\s*[A-Za-z]{2,}'', ''[연락처 비공개]'', ''gi'');\n  v_title := regexp_replace(v_title, ''\\y[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}\\y'', ''[연락처 비공개]'', ''gi'');\n  v_body  := regexp_replace(v_body,  ''\\y[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}\\y'', ''[연락처 비공개]'', ''gi'');\n  v_title := regexp_replace(v_title, ''\\y(?:open\\.kakao\\.com|kakaotalk\\.com|t\\.me|telegram\\.me|instagram\\.com|instagr\\.am|linktr\\.ee)(?:/[^\\s<>\"'''']*)?'', ''[연락처 비공개]'', ''gi'');\n  v_body  := regexp_replace(v_body,  ''\\y(?:open\\.kakao\\.com|kakaotalk\\.com|t\\.me|telegram\\.me|instagram\\.com|instagr\\.am|linktr\\.ee)(?:/[^\\s<>\"'''']*)?'', ''[연락처 비공개]'', ''gi'');\n  v_title := regexp_replace(v_title, ''(카카오톡|카톡|오픈채팅|텔레그램|인스타그램|인스타|디엠)\\s*[:：=]?\\s*@?[A-Za-z0-9._-]{4,}'', ''[연락처 비공개]'', ''g'');\n  v_body  := regexp_replace(v_body,  ''(카카오톡|카톡|오픈채팅|텔레그램|인스타그램|인스타|디엠)\\s*[:：=]?\\s*@?[A-Za-z0-9._-]{4,}'', ''[연락처 비공개]'', ''g'');\n\n  -- 이미지 ref 검증 (B-4 공용 검증기)\n  v_val := core_private.community_image_refs_validate(p_author_id, coalesce(p_image_refs, ''{}''::text[]));\n  IF NOT coalesce((v_val ->> ''ok'')::boolean, false) THEN\n    RETURN v_val;\n  END IF;\n\n  -- INSERT (컬럼 집합 = 현행 웹 insertCommunityBoardPost 동일. author_label/role 서버 도출)\n  INSERT INTO public.community_posts\n    (author_id, title, body, content, category, image_urls, hashtags, status,\n     author_label, author_role, create_idempotency_key)\n  VALUES\n    (p_author_id, v_title, v_body, v_body, p_category,\n     coalesce(p_image_refs, ''{}''::text[]), ''{}''::text[], p_status,\n     coalesce(nullif(btrim(v_nickname), ''''), ''쌤버십 사용자''),\n     CASE WHEN v_role IN (''student'', ''mentor'') THEN v_role END,\n     p_idempotency_key)\n  ON CONFLICT (author_id, create_idempotency_key) DO NOTHING\n  RETURNING id INTO v_id;\n\n  -- 동시 경합 패자 → 재생 수렴 (T-CONC-06)\n  IF v_id IS NULL THEN\n    SELECT cp.id INTO v_id FROM public.community_posts cp\n     WHERE cp.author_id = p_author_id AND cp.create_idempotency_key = p_idempotency_key;\n    IF v_id IS NULL THEN\n      RAISE EXCEPTION ''community_post_create_impl: idempotent insert not observable'';\n    END IF;\n    RETURN jsonb_build_object(''ok'', true, ''post_id'', v_id, ''idempotent_replay'', true);\n  END IF;\n\n  RETURN jsonb_build_object(''ok'', true, ''post_id'', v_id, ''idempotent_replay'', false);\nEND $fn$;\n\nCOMMENT ON FUNCTION core_private.community_post_create_impl(uuid, text, text, text, text[], text, uuid) IS\n  ''S2 M7 B-1(계약 §7): 게시글 생성 공용 구현부 — replay-first 멱등·승인 멘토 전용·마스킹·B-4 이미지 검증. 외부 EXECUTE 0.'';\n\n-- -----------------------------------------------------------------------------\n-- D. B-2 core_private.community_post_update_impl (§7 F5)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION core_private.community_post_update_impl(\n  p_author_id uuid, p_post_id uuid, p_title text, p_body text, p_category text,\n  p_image_refs text[], p_status text, p_expected_updated_at timestamptz\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY INVOKER SET search_path = '''' AS $fn$\nDECLARE\n  v_role       text;\n  v_status     text;\n  v_susp       timestamptz;\n  v_post       record;\n  v_title      text;\n  v_body       text;\n  v_val        jsonb;\n  v_removed    text[];\n  v_updated_at timestamptz;\nBEGIN\n  IF p_author_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  IF p_post_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''POST_NOT_FOUND_OR_NOT_OWNED'');\n  END IF;\n\n  -- 소유 행 잠금 (비존재·타인 글·삭제 글 동일 코드 — §9.4)\n  SELECT cp.id, cp.image_urls, cp.updated_at INTO v_post\n    FROM public.community_posts cp\n   WHERE cp.id = p_post_id AND cp.author_id = p_author_id AND cp.deleted_at IS NULL\n   FOR UPDATE;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''POST_NOT_FOUND_OR_NOT_OWNED'');\n  END IF;\n\n  -- 역할·승인·계정 (학생 글 보존 규칙 — 학생은 수정 거부 ROLE_NOT_MENTOR)\n  SELECT u.role, u.status, u.suspended_until INTO v_role, v_status, v_susp\n    FROM public.users u WHERE u.id = p_author_id;\n  IF NOT FOUND OR v_role IS DISTINCT FROM ''mentor'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ROLE_NOT_MENTOR'');\n  END IF;\n  IF NOT public.individual_question_user_is_approved_mentor(p_author_id) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''MENTOR_NOT_APPROVED'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''banned'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_BANNED'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''suspended'' AND (v_susp IS NULL OR v_susp > now()) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_SUSPENDED'');\n  END IF;\n  IF public.account_deletion_write_blocked(p_author_id) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  END IF;\n\n  -- 낙관적 충돌 검사 (§7 F5)\n  IF v_post.updated_at IS DISTINCT FROM p_expected_updated_at THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''UPDATE_CONFLICT'');\n  END IF;\n\n  IF p_status NOT IN (''draft'', ''published'') THEN\n    RAISE EXCEPTION ''p_status must be draft|published'';\n  END IF;\n  v_title := btrim(coalesce(p_title, ''''));\n  IF v_title = '''' THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''TITLE_REQUIRED'');\n  END IF;\n  IF p_category IS NULL OR p_category NOT IN (''study'', ''school'', ''career'', ''college'', ''free'') THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''CATEGORY_INVALID'');\n  END IF;\n  v_body := btrim(coalesce(p_body, ''''));\n  IF p_status = ''published'' AND char_length(v_body) < 10 THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''BODY_TOO_SHORT'');\n  END IF;\n\n  -- [연락처 마스킹 — B-1 과 동일 정본 이식(contactMasking.ts) · 동일 순서]\n  v_title := regexp_replace(v_title, ''(^|[^0-9])(\\+82[-._\\s]?0?1[0-9][-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4}|0(?:10|11|16|17|18|19|2|[3-6][1-5]|50|70|80)[-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4})(?![0-9])'', ''\\1[연락처 비공개]'', ''g'');\n  v_body  := regexp_replace(v_body,  ''(^|[^0-9])(\\+82[-._\\s]?0?1[0-9][-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4}|0(?:10|11|16|17|18|19|2|[3-6][1-5]|50|70|80)[-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4})(?![0-9])'', ''\\1[연락처 비공개]'', ''g'');\n  v_title := regexp_replace(v_title, ''(공일공|영일영)[\\s\\-._]*[0-9공영일이삼사오육칠팔구][0-9공영일이삼사오육칠팔구\\s\\-._]{6,12}'', ''[연락처 비공개]'', ''g'');\n  v_body  := regexp_replace(v_body,  ''(공일공|영일영)[\\s\\-._]*[0-9공영일이삼사오육칠팔구][0-9공영일이삼사오육칠팔구\\s\\-._]{6,12}'', ''[연락처 비공개]'', ''g'');\n  v_title := regexp_replace(v_title, ''[A-Za-z0-9._%+-]+\\s*[\\[({（]\\s*at\\s*[\\])}）]\\s*[A-Za-z0-9.-]+\\s*(?:[\\[({（]\\s*dot\\s*[\\])}）]|\\.)\\s*[A-Za-z]{2,}'', ''[연락처 비공개]'', ''gi'');\n  v_body  := regexp_replace(v_body,  ''[A-Za-z0-9._%+-]+\\s*[\\[({（]\\s*at\\s*[\\])}）]\\s*[A-Za-z0-9.-]+\\s*(?:[\\[({（]\\s*dot\\s*[\\])}）]|\\.)\\s*[A-Za-z]{2,}'', ''[연락처 비공개]'', ''gi'');\n  v_title := regexp_replace(v_title, ''\\y[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}\\y'', ''[연락처 비공개]'', ''gi'');\n  v_body  := regexp_replace(v_body,  ''\\y[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}\\y'', ''[연락처 비공개]'', ''gi'');\n  v_title := regexp_replace(v_title, ''\\y(?:open\\.kakao\\.com|kakaotalk\\.com|t\\.me|telegram\\.me|instagram\\.com|instagr\\.am|linktr\\.ee)(?:/[^\\s<>\"'''']*)?'', ''[연락처 비공개]'', ''gi'');\n  v_body  := regexp_replace(v_body,  ''\\y(?:open\\.kakao\\.com|kakaotalk\\.com|t\\.me|telegram\\.me|instagram\\.com|instagr\\.am|linktr\\.ee)(?:/[^\\s<>\"'''']*)?'', ''[연락처 비공개]'', ''gi'');\n  v_title := regexp_replace(v_title, ''(카카오톡|카톡|오픈채팅|텔레그램|인스타그램|인스타|디엠)\\s*[:：=]?\\s*@?[A-Za-z0-9._-]{4,}'', ''[연락처 비공개]'', ''g'');\n  v_body  := regexp_replace(v_body,  ''(카카오톡|카톡|오픈채팅|텔레그램|인스타그램|인스타|디엠)\\s*[:：=]?\\s*@?[A-Za-z0-9._-]{4,}'', ''[연락처 비공개]'', ''g'');\n\n  v_val := core_private.community_image_refs_validate(p_author_id, coalesce(p_image_refs, ''{}''::text[]));\n  IF NOT coalesce((v_val ->> ''ok'')::boolean, false) THEN\n    RETURN v_val;\n  END IF;\n\n  -- 제거된 ref 차집합 (클라이언트가 commit 후 best-effort 삭제 — §14.4)\n  v_removed := ARRAY(SELECT unnest(coalesce(v_post.image_urls, ''{}''::text[]))\n                     EXCEPT\n                     SELECT unnest(coalesce(p_image_refs, ''{}''::text[])));\n\n  UPDATE public.community_posts cp\n     SET title = v_title, body = v_body, content = v_body, category = p_category,\n         image_urls = coalesce(p_image_refs, ''{}''::text[]), status = p_status,\n         updated_at = now()\n   WHERE cp.id = p_post_id\n   RETURNING cp.updated_at INTO v_updated_at;\n\n  RETURN jsonb_build_object(''ok'', true, ''post_id'', p_post_id, ''updated_at'', v_updated_at,\n                            ''removed_image_refs'', to_jsonb(coalesce(v_removed, ''{}''::text[])));\nEND $fn$;\n\nCOMMENT ON FUNCTION core_private.community_post_update_impl(uuid, uuid, text, text, text, text[], text, timestamptz) IS\n  ''S2 M7 B-2(계약 §7): 게시글 수정 공용 구현부 — 소유·낙관 충돌·마스킹·B-4 검증·removed_image_refs. 외부 EXECUTE 0.'';\n\n-- -----------------------------------------------------------------------------\n-- E. B-3 core_private.community_post_soft_delete_impl (§7 F6)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION core_private.community_post_soft_delete_impl(\n  p_author_id uuid, p_post_id uuid\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY INVOKER SET search_path = '''' AS $fn$\nDECLARE\n  v_status  text;\n  v_susp    timestamptz;\n  v_deleted timestamptz;\nBEGIN\n  IF p_author_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  IF p_post_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''POST_NOT_FOUND_OR_NOT_OWNED'');\n  END IF;\n\n  -- 소유 행 잠금 — 역할 게이트 없음(작성자 본인 soft-delete 는 학생 글 보존 규칙상 허용)\n  SELECT cp.deleted_at INTO v_deleted\n    FROM public.community_posts cp\n   WHERE cp.id = p_post_id AND cp.author_id = p_author_id\n   FOR UPDATE;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''POST_NOT_FOUND_OR_NOT_OWNED'');\n  END IF;\n\n  -- 계정 쓰기 게이트 (§11.5 fail-closed)\n  SELECT u.status, u.suspended_until INTO v_status, v_susp\n    FROM public.users u WHERE u.id = p_author_id;\n  IF lower(coalesce(v_status, ''active'')) = ''banned'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_BANNED'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''suspended'' AND (v_susp IS NULL OR v_susp > now()) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_SUSPENDED'');\n  END IF;\n  IF public.account_deletion_write_blocked(p_author_id) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  END IF;\n\n  -- 이미 삭제면 ok:true + already_deleted:true (§8.3 F6)\n  IF v_deleted IS NOT NULL THEN\n    RETURN jsonb_build_object(''ok'', true, ''post_id'', p_post_id, ''deleted_at'', v_deleted,\n                              ''already_deleted'', true);\n  END IF;\n\n  -- soft delete — 행·이미지 참조 보존, hard delete 금지 (§14.4)\n  UPDATE public.community_posts cp SET deleted_at = now()\n   WHERE cp.id = p_post_id\n   RETURNING cp.deleted_at INTO v_deleted;\n\n  RETURN jsonb_build_object(''ok'', true, ''post_id'', p_post_id, ''deleted_at'', v_deleted);\nEND $fn$;\n\nCOMMENT ON FUNCTION core_private.community_post_soft_delete_impl(uuid, uuid) IS\n  ''S2 M7 B-3(계약 §7): 게시글 soft-delete 공용 구현부 — 작성자 본인·행 보존·hard delete 금지. 외부 EXECUTE 0.'';\n\n-- -----------------------------------------------------------------------------\n-- F. F4·F5·F6 wrapper (SECDEF — auth.uid() 결합 + envelope 전달만)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_web_v1.community_post_create(\n  p_title text, p_body text, p_category text,\n  p_idempotency_key uuid,\n  p_image_refs text[] DEFAULT ''{}'', p_status text DEFAULT ''published''\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $fn$\nDECLARE\n  v_uid uuid := (SELECT auth.uid());\nBEGIN\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  RETURN core_private.community_post_create_impl(\n           v_uid, p_title, p_body, p_category,\n           coalesce(p_image_refs, ''{}''::text[]), p_status, p_idempotency_key)\n         || jsonb_build_object(''contract_version'', 1);\nEND $fn$;\n\nCOMMENT ON FUNCTION api_web_v1.community_post_create(text, text, text, uuid, text[], text) IS\n  ''S2 M7 F4(계약 §7 — rev 8 A-1 재배열): 게시글 생성 wrapper — 승인 멘토 전용·replay-first 멱등. 앱 동명 함수와 시그니처·오류코드 동일.'';\n\nCREATE FUNCTION api_web_v1.community_post_update(\n  p_post_id uuid, p_title text, p_body text, p_category text,\n  p_expected_updated_at timestamptz,\n  p_image_refs text[] DEFAULT ''{}'', p_status text DEFAULT ''published''\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $fn$\nDECLARE\n  v_uid uuid := (SELECT auth.uid());\nBEGIN\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  RETURN core_private.community_post_update_impl(\n           v_uid, p_post_id, p_title, p_body, p_category,\n           coalesce(p_image_refs, ''{}''::text[]), p_status, p_expected_updated_at)\n         || jsonb_build_object(''contract_version'', 1);\nEND $fn$;\n\nCOMMENT ON FUNCTION api_web_v1.community_post_update(uuid, text, text, text, timestamptz, text[], text) IS\n  ''S2 M7 F5(계약 §7 — rev 8 A-1 재배열): 게시글 수정 wrapper — 낙관 충돌 검사·removed_image_refs 반환.'';\n\nCREATE FUNCTION api_web_v1.community_post_soft_delete(p_post_id uuid)\nRETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $fn$\nDECLARE\n  v_uid uuid := (SELECT auth.uid());\nBEGIN\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  RETURN core_private.community_post_soft_delete_impl(v_uid, p_post_id)\n         || jsonb_build_object(''contract_version'', 1);\nEND $fn$;\n\nCOMMENT ON FUNCTION api_web_v1.community_post_soft_delete(uuid) IS\n  ''S2 M7 F6(계약 §7): 게시글 soft-delete wrapper — 작성자 본인, hard delete 금지.'';\n\n-- -----------------------------------------------------------------------------\n-- G. GRANT (§10.3) — 구현부 4종 외부 EXECUTE 0 · wrapper 3종 authenticated/service_role\n-- -----------------------------------------------------------------------------\nREVOKE ALL ON FUNCTION core_private.community_image_refs_validate(uuid, text[])                                        FROM PUBLIC;\nREVOKE ALL ON FUNCTION core_private.community_post_create_impl(uuid, text, text, text, text[], text, uuid)             FROM PUBLIC;\nREVOKE ALL ON FUNCTION core_private.community_post_update_impl(uuid, uuid, text, text, text, text[], text, timestamptz) FROM PUBLIC;\nREVOKE ALL ON FUNCTION core_private.community_post_soft_delete_impl(uuid, uuid)                                        FROM PUBLIC;\n\nREVOKE ALL ON FUNCTION api_web_v1.community_post_create(text, text, text, uuid, text[], text)                          FROM PUBLIC;\nREVOKE ALL ON FUNCTION api_web_v1.community_post_update(uuid, text, text, text, timestamptz, text[], text)             FROM PUBLIC;\nREVOKE ALL ON FUNCTION api_web_v1.community_post_soft_delete(uuid)                                                     FROM PUBLIC;\n\nGRANT EXECUTE ON FUNCTION api_web_v1.community_post_create(text, text, text, uuid, text[], text)              TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION api_web_v1.community_post_update(uuid, text, text, text, timestamptz, text[], text) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION api_web_v1.community_post_soft_delete(uuid)                                         TO authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- H. 적용 직후 자가 검증\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_cnt int;\nBEGIN\n  -- 구현부 4종: INVOKER + search_path + 외부(EXECUTE service_role 포함) 0\n  SELECT count(*) INTO v_cnt\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''core_private''\n     AND p.proname IN (''community_image_refs_validate'', ''community_post_create_impl'',\n                       ''community_post_update_impl'', ''community_post_soft_delete_impl'')\n     AND NOT p.prosecdef\n     AND p.proconfig::text LIKE ''%search_path=%''\n     AND NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n     AND NOT has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n     AND NOT has_function_privilege(''service_role'', p.oid, ''EXECUTE'')\n     AND (p.proacl IS NULL OR (p.proacl::text NOT LIKE ''{=%'' AND p.proacl::text NOT LIKE ''%,=%''));\n  IF v_cnt <> 4 THEN\n    RAISE EXCEPTION ''S2_M7_SELFCHECK: impl hardening mismatch (matched %)'', v_cnt;\n  END IF;\n  -- wrapper 3종: SECDEF + grant 매트릭스\n  SELECT count(*) INTO v_cnt\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''api_web_v1''\n     AND p.proname IN (''community_post_create'', ''community_post_update'', ''community_post_soft_delete'')\n     AND p.prosecdef AND p.proconfig::text LIKE ''%search_path=%''\n     AND NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n     AND has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n     AND has_function_privilege(''service_role'', p.oid, ''EXECUTE'');\n  IF v_cnt <> 3 THEN\n    RAISE EXCEPTION ''S2_M7_SELFCHECK: wrapper hardening mismatch (matched %)'', v_cnt;\n  END IF;\n  -- census: api_web_v1 = view 5 + fn 9 / core_private = fn 5 (F10 + 구현부 4)\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname = ''api_web_v1'') <> 9\n     OR (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n          WHERE n.nspname = ''core_private'') <> 5\n     OR (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace\n          WHERE n.nspname = ''core_private'') <> 0 THEN\n    RAISE EXCEPTION ''S2_M7_SELFCHECK: object census mismatch after M7'';\n  END IF;\nEND $$;\n\ncommit;\n"], "idempotency_key": null}, {"name": "20260730112525_api_app_v1_surface", "version": "20260731114120", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260730112525_api_app_v1_surface.sql (S2 M17)\n-- =============================================================================\n-- api_app_v1 DB 표면 — 소유 객체 정확히 7개: schema 1 + view 1 + wrapper 5.\n-- 정본 계약: 앱 계약 api_app_v1_contract_v1_1.md §3.1~§3.4 · §10 Gate 4 /\n--            웹 계약 §19.5 #9 · §20.2 M17 · §20.3 「M17 이전/적용 직후」 · §22.\n--   - schema: REVOKE ALL FROM PUBLIC, anon · GRANT USAGE → authenticated 만\n--     (service_role 은 앱 공개 계약의 호출자가 아니다 — 앱 계약 §3.3 주석.\n--      웹 api_web_v1 과의 의도적 차이).\n--   - view `api_app_v1.community_posts_v1`: 웹 V1 과 동일 필드·동일 규약\n--     (body=coalesce(content,body) · image_refs=coalesce(image_urls,{}) ·\n--      deleted_at IS NULL · published 또는 본인 글 · security_invoker=true ·\n--      SELECT → authenticated 만).\n--   - wrapper 5종(identity argument = 앱 계약 §3.3·§10 Gate 4 완전 동일):\n--     ensure_free_question_room(uuid) · qna_create_question_thread(uuid,text,\n--     text,text,text) · community_post_create(text,text,text,uuid,text[],text) ·\n--     community_post_update(uuid,text,text,text,timestamptz,text[],text) ·\n--     community_post_soft_delete(uuid). 전부 SECDEF + SET search_path='''' —\n--     웹 F2·F3·F4·F5·F6 과 동일한 얇은 껍데기로, 판정·검증은 전부 공용 정본\n--     (core_private.ensure_student_mentor_room(F10 — M5) · B-1~B-4(M7) ·\n--      public.qna_create_question_thread)이 수행한다. **복제 금지** — 이\n--     migration 은 core_private 에 어떤 객체도 만들지 않는다.\n--   - F3 상당 wrapper 의 raise→envelope 변환·FREE_QUESTION_* 4쌍 수렴은 웹 F3\n--     과 동일 매핑이다(앱 계약 §4.3 — 웹·앱이 같은 상황에서 같은 코드).\n--   - default privilege 방어: ALTER DEFAULT PRIVILEGES ... REVOKE EXECUTE FROM\n--     PUBLIC (계약 원문 유지 — PG17.6 실측상 선행 per-schema GRANT 부재 시 저장\n--     no-op 이며 실효 방어선은 함수별 명시 REVOKE. M1 forward 섹션 D 기록과 동일).\n--   - Data API(Exposed schemas) 추가는 SQL 이 아닌 플랫폼 단계 D-API-A 다\n--     (앱 계약 §3.1 순서 고정 — 본 migration 은 노출 설정을 변경하지 않는다).\n-- 선행조건: M5(20260730105244) + M7(20260730105252) 적용 완료(§20.2.1 —\n--   M17 : M5 + M7. M1 은 간접 충족 · M13 의존 없음).\n-- rollback 정본: supabase/rollback/20260730112525_api_app_v1_surface_rollback.sql\n--   (§22 M17 순서 — 운영에서는 노출 제거·config 반영 확인이 DROP 보다 선행.\n--    로컬 검증 단계에서는 D-API-A 미실행이므로 wrapper→view→schema DROP 만 해당)\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- A. 사전 게이트 (§20.3 「M17 이전」 5항 — 불일치 시 수정 0건 중단)\n-- -----------------------------------------------------------------------------\nDO $$\nBEGIN\n  -- ① M5 적용 (F10 identity 일치 — §7 F10)\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''core_private'' AND p.proname = ''ensure_student_mentor_room''\n                    AND pg_get_function_identity_arguments(p.oid)\n                        = ''p_student_id uuid, p_mentor_id uuid, p_payment_id uuid, p_subscription_id uuid, p_require_entitlement boolean'') THEN\n    RAISE EXCEPTION ''BATCH_D_BASELINE_OBJECT_MISMATCH: M5 F10 not applied or identity mismatch'';\n  END IF;\n  -- ② M7 적용 (B-1~B-4 identity 일치 — §7 표)\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname = ''core_private''\n         AND (p.proname, pg_get_function_identity_arguments(p.oid)) IN\n             ((''community_post_create_impl'', ''p_author_id uuid, p_title text, p_body text, p_category text, p_image_refs text[], p_status text, p_idempotency_key uuid''),\n              (''community_post_update_impl'', ''p_author_id uuid, p_post_id uuid, p_title text, p_body text, p_category text, p_image_refs text[], p_status text, p_expected_updated_at timestamp with time zone''),\n              (''community_post_soft_delete_impl'', ''p_author_id uuid, p_post_id uuid''),\n              (''community_image_refs_validate'', ''p_owner_id uuid, p_image_refs text[]''))) <> 4 THEN\n    RAISE EXCEPTION ''BATCH_D_BASELINE_OBJECT_MISMATCH: M7 impl functions not applied or identity mismatch'';\n  END IF;\n  -- ③ View 기반 컬럼 전수 대조 (앱 계약 §3.2 — community_posts)\n  IF (SELECT count(*) FROM information_schema.columns\n       WHERE table_schema = ''public'' AND table_name = ''community_posts''\n         AND column_name IN (''id'',''author_id'',''title'',''content'',''body'',''category'',''image_urls'',\n                             ''author_label'',''author_role'',''like_count'',''comment_count'',''view_count'',\n                             ''status'',''created_at'',''updated_at'',''deleted_at'')) <> 16 THEN\n    RAISE EXCEPTION ''BATCH_D_BASELINE_OBJECT_MISMATCH: community_posts base columns mismatch'';\n  END IF;\n  -- ④ 정본 qna_create_question_thread identity\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''public'' AND p.proname = ''qna_create_question_thread''\n                    AND pg_get_function_identity_arguments(p.oid)\n                        = ''p_room_id uuid, p_title text, p_subject text, p_topic text, p_first_message_body text'') THEN\n    RAISE EXCEPTION ''BATCH_D_BASELINE_OBJECT_MISMATCH: canonical qna_create_question_thread mismatch'';\n  END IF;\n  -- ⑤ 기존 api_app_v1 부분 객체 없음 (부분 생성 은닉 금지)\n  IF EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = ''api_app_v1'') THEN\n    RAISE EXCEPTION ''UNEXPECTED_EXISTING_CONTRACT_OBJECT: schema api_app_v1 already exists'';\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- B. schema (앱 계약 §3.1 — authenticated 만 USAGE)\n-- -----------------------------------------------------------------------------\nCREATE SCHEMA api_app_v1;\nREVOKE ALL ON SCHEMA api_app_v1 FROM PUBLIC, anon;\nGRANT USAGE ON SCHEMA api_app_v1 TO authenticated;\nALTER DEFAULT PRIVILEGES IN SCHEMA api_app_v1 REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;\n\n-- -----------------------------------------------------------------------------\n-- C. view api_app_v1.community_posts_v1 (앱 계약 §3.2 — 웹 V1 과 동일 규약)\n-- -----------------------------------------------------------------------------\nCREATE VIEW api_app_v1.community_posts_v1\nWITH (security_invoker = true) AS\nSELECT\n  p.id,\n  p.author_id,\n  p.title,\n  coalesce(p.content, p.body)           AS body,\n  p.category,\n  coalesce(p.image_urls, ''{}''::text[])  AS image_refs,\n  p.author_label,\n  p.author_role,\n  p.like_count,\n  p.comment_count,\n  p.view_count,\n  p.status,\n  p.created_at,\n  p.updated_at\nFROM public.community_posts p\nWHERE p.deleted_at IS NULL\n  AND (p.status = ''published'' OR p.author_id = (SELECT auth.uid()));\n\nCOMMENT ON VIEW api_app_v1.community_posts_v1 IS\n  ''S2 M17(앱 계약 §3.2): 앱 게시판 읽기 — 웹 V1 과 동일 필드·규약. security_invoker=true · SELECT → authenticated 만.'';\n\n-- -----------------------------------------------------------------------------\n-- D. wrapper 1 — ensure_free_question_room (웹 F2 와 동일 얇은 껍데기)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_app_v1.ensure_free_question_room(p_mentor_id uuid)\nRETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $fn$\nDECLARE\n  v_uid uuid := (SELECT auth.uid());\nBEGIN\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  IF p_mentor_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_FOUND'');\n  END IF;\n  RETURN core_private.ensure_student_mentor_room(v_uid, p_mentor_id, NULL, NULL, true)\n         || jsonb_build_object(''contract_version'', 1);\nEND $fn$;\n\nCOMMENT ON FUNCTION api_app_v1.ensure_free_question_room(uuid) IS\n  ''S2 M17(앱 계약 §3.3): 무료질문 방 확보 앱 wrapper — 웹 F2 와 이름·시그니처·반환·오류코드 완전 동일(F10 공용 구현부 호출).'';\n\n-- -----------------------------------------------------------------------------\n-- E. wrapper 2 — qna_create_question_thread (웹 F3 과 동일 변환 계약)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_app_v1.qna_create_question_thread(\n  p_room_id uuid,\n  p_title text,\n  p_subject text DEFAULT NULL,\n  p_topic text DEFAULT NULL,\n  p_first_message_body text DEFAULT NULL\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $fn$\nDECLARE\n  v_res  jsonb;\n  v_code text;\nBEGIN\n  v_res := public.qna_create_question_thread(p_room_id, p_title, p_subject, p_topic, p_first_message_body);\n  RETURN v_res || jsonb_build_object(''contract_version'', 1);\nEXCEPTION WHEN OTHERS THEN\n  v_code := CASE SQLERRM\n    WHEN ''FREE_QUESTION_EXPIRED''           THEN ''FREE_QUOTA_EXPIRED''\n    WHEN ''FREE_QUESTION_TOTAL_LIMIT''       THEN ''FREE_QUOTA_TOTAL_EXHAUSTED''\n    WHEN ''FREE_QUESTION_PER_MENTOR_LIMIT''  THEN ''FREE_QUOTA_MENTOR_EXHAUSTED''\n    WHEN ''FREE_QUESTION_STUDENT_NOT_FOUND'' THEN ''FREE_QUOTA_STUDENT_NOT_FOUND''\n    WHEN ''AUTH_REQUIRED''                 THEN ''AUTH_REQUIRED''\n    WHEN ''TITLE_REQUIRED''                THEN ''TITLE_REQUIRED''\n    WHEN ''ROOM_NOT_FOUND''                THEN ''ROOM_NOT_FOUND''\n    WHEN ''NOT_ROOM_PARTY''                THEN ''NOT_ROOM_PARTY''\n    WHEN ''MENTOR_CANNOT_CREATE_THREAD''   THEN ''MENTOR_CANNOT_CREATE_THREAD''\n    WHEN ''ACCOUNT_BANNED''                THEN ''ACCOUNT_BANNED''\n    WHEN ''ACCOUNT_SUSPENDED''             THEN ''ACCOUNT_SUSPENDED''\n    WHEN ''ACCOUNT_DELETION_IN_PROGRESS''  THEN ''ACCOUNT_DELETION_IN_PROGRESS''\n    WHEN ''BLOCKED''                       THEN ''BLOCKED''\n    WHEN ''MENTOR_NOT_APPROVED''           THEN ''MENTOR_NOT_APPROVED''\n    WHEN ''SUBSCRIPTION_REFUND_PENDING''   THEN ''SUBSCRIPTION_REFUND_PENDING''\n    WHEN ''WEEKLY_LIMIT_EXHAUSTED''        THEN ''WEEKLY_LIMIT_EXHAUSTED''\n    WHEN ''FREE_QUOTA_EXPIRED''            THEN ''FREE_QUOTA_EXPIRED''\n    WHEN ''FREE_QUOTA_TOTAL_EXHAUSTED''    THEN ''FREE_QUOTA_TOTAL_EXHAUSTED''\n    WHEN ''FREE_QUOTA_MENTOR_EXHAUSTED''   THEN ''FREE_QUOTA_MENTOR_EXHAUSTED''\n    ELSE NULL\n  END;\n  IF v_code IS NULL THEN\n    -- 사전에 없는 예외는 삼키지 않고 그대로 전파(앱 계약 §3.3 envelope 규약)\n    RAISE;\n  END IF;\n  RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', v_code);\nEND $fn$;\n\nCOMMENT ON FUNCTION api_app_v1.qna_create_question_thread(uuid, text, text, text, text) IS\n  ''S2 M17(앱 계약 §3.3): 정본 스레드 생성의 앱 wrapper — 웹 F3 과 동일한 raise→envelope 변환·FREE_QUESTION_* 수렴.'';\n\n-- -----------------------------------------------------------------------------\n-- F. wrapper 3·4·5 — community_post_create/update/soft_delete (웹 F4·F5·F6 동일)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_app_v1.community_post_create(\n  p_title text, p_body text, p_category text,\n  p_idempotency_key uuid,\n  p_image_refs text[] DEFAULT ''{}'', p_status text DEFAULT ''published''\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $fn$\nDECLARE\n  v_uid uuid := (SELECT auth.uid());\nBEGIN\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  RETURN core_private.community_post_create_impl(\n           v_uid, p_title, p_body, p_category,\n           coalesce(p_image_refs, ''{}''::text[]), p_status, p_idempotency_key)\n         || jsonb_build_object(''contract_version'', 1);\nEND $fn$;\n\nCOMMENT ON FUNCTION api_app_v1.community_post_create(text, text, text, uuid, text[], text) IS\n  ''S2 M17(앱 계약 §3.3 — rev 8 A-1 재배열): 게시글 생성 앱 wrapper — 웹 F4 와 동일(B-1 공용 구현부·replay-first 멱등).'';\n\nCREATE FUNCTION api_app_v1.community_post_update(\n  p_post_id uuid, p_title text, p_body text, p_category text,\n  p_expected_updated_at timestamptz,\n  p_image_refs text[] DEFAULT ''{}'', p_status text DEFAULT ''published''\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $fn$\nDECLARE\n  v_uid uuid := (SELECT auth.uid());\nBEGIN\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  RETURN core_private.community_post_update_impl(\n           v_uid, p_post_id, p_title, p_body, p_category,\n           coalesce(p_image_refs, ''{}''::text[]), p_status, p_expected_updated_at)\n         || jsonb_build_object(''contract_version'', 1);\nEND $fn$;\n\nCOMMENT ON FUNCTION api_app_v1.community_post_update(uuid, text, text, text, timestamptz, text[], text) IS\n  ''S2 M17(앱 계약 §3.3 — rev 8 A-1 재배열): 게시글 수정 앱 wrapper — 웹 F5 와 동일(B-2 공용 구현부).'';\n\nCREATE FUNCTION api_app_v1.community_post_soft_delete(p_post_id uuid)\nRETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $fn$\nDECLARE\n  v_uid uuid := (SELECT auth.uid());\nBEGIN\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  RETURN core_private.community_post_soft_delete_impl(v_uid, p_post_id)\n         || jsonb_build_object(''contract_version'', 1);\nEND $fn$;\n\nCOMMENT ON FUNCTION api_app_v1.community_post_soft_delete(uuid) IS\n  ''S2 M17(앱 계약 §3.3): 게시글 soft-delete 앱 wrapper — 웹 F6 과 동일(B-3 공용 구현부·hard delete 금지).'';\n\n-- -----------------------------------------------------------------------------\n-- G. GRANT (앱 계약 §3.2·§3.3 공통 권한 블록 원문 — authenticated 만)\n-- -----------------------------------------------------------------------------\nREVOKE ALL ON api_app_v1.community_posts_v1 FROM PUBLIC, anon;\nGRANT SELECT ON api_app_v1.community_posts_v1 TO authenticated;\n\nREVOKE ALL ON ALL FUNCTIONS IN SCHEMA api_app_v1 FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION api_app_v1.ensure_free_question_room(uuid) TO authenticated;\nGRANT EXECUTE ON FUNCTION api_app_v1.qna_create_question_thread(uuid,text,text,text,text) TO authenticated;\nGRANT EXECUTE ON FUNCTION api_app_v1.community_post_create(text,text,text,uuid,text[],text) TO authenticated;\nGRANT EXECUTE ON FUNCTION api_app_v1.community_post_update(uuid,text,text,text,timestamptz,text[],text) TO authenticated;\nGRANT EXECUTE ON FUNCTION api_app_v1.community_post_soft_delete(uuid) TO authenticated;\n\n-- -----------------------------------------------------------------------------\n-- H. 적용 직후 자가 검증 (§20.3 「M17 적용 직후」 7항)\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_cnt int;\n  v_acl text;\nBEGIN\n  -- ①② schema + View 1종\n  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = ''api_app_v1'')\n     OR (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace\n          WHERE n.nspname = ''api_app_v1'') <> 1\n     OR NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace\n                     WHERE n.nspname = ''api_app_v1'' AND c.relname = ''community_posts_v1''\n                       AND c.relkind = ''v'' AND c.reloptions::text LIKE ''%security_invoker=true%'') THEN\n    RAISE EXCEPTION ''S2_M17_SELFCHECK: schema/view census mismatch'';\n  END IF;\n  -- ③ wrapper 5종 identity argument 완전 일치 + SECDEF·search_path\n  SELECT count(*) INTO v_cnt\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''api_app_v1''\n     AND p.prosecdef AND p.proconfig::text LIKE ''%search_path=%''\n     AND (p.proname, pg_get_function_identity_arguments(p.oid)) IN\n         ((''ensure_free_question_room'', ''p_mentor_id uuid''),\n          (''qna_create_question_thread'', ''p_room_id uuid, p_title text, p_subject text, p_topic text, p_first_message_body text''),\n          (''community_post_create'', ''p_title text, p_body text, p_category text, p_idempotency_key uuid, p_image_refs text[], p_status text''),\n          (''community_post_update'', ''p_post_id uuid, p_title text, p_body text, p_category text, p_expected_updated_at timestamp with time zone, p_image_refs text[], p_status text''),\n          (''community_post_soft_delete'', ''p_post_id uuid''));\n  IF v_cnt <> 5 OR (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                     WHERE n.nspname = ''api_app_v1'') <> 5 THEN\n    RAISE EXCEPTION ''S2_M17_SELFCHECK: wrapper identity mismatch (matched %)'', v_cnt;\n  END IF;\n  -- ④ PUBLIC·anon 불필요 권한 0\n  SELECT nspacl::text INTO v_acl FROM pg_namespace WHERE nspname = ''api_app_v1'';\n  IF v_acl LIKE ''{=%'' OR v_acl LIKE ''%,=%'' OR v_acl LIKE ''%anon=%''\n     OR has_schema_privilege(''anon'', ''api_app_v1'', ''USAGE'') THEN\n    RAISE EXCEPTION ''S2_M17_SELFCHECK: PUBLIC/anon schema privilege leaked (%)'', v_acl;\n  END IF;\n  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n              WHERE n.nspname = ''api_app_v1''\n                AND (has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n                     OR p.proacl::text LIKE ''{=%'' OR p.proacl::text LIKE ''%,=%''))\n     OR has_table_privilege(''anon'', ''api_app_v1.community_posts_v1'', ''SELECT'') THEN\n    RAISE EXCEPTION ''S2_M17_SELFCHECK: PUBLIC/anon object privilege leaked'';\n  END IF;\n  -- ⑤ authenticated 최소 권한만 (USAGE + View SELECT + 함수 5 EXECUTE, DML 0)\n  IF NOT has_schema_privilege(''authenticated'', ''api_app_v1'', ''USAGE'')\n     OR NOT has_table_privilege(''authenticated'', ''api_app_v1.community_posts_v1'', ''SELECT'')\n     OR has_table_privilege(''authenticated'', ''api_app_v1.community_posts_v1'', ''INSERT'')\n     OR has_table_privilege(''authenticated'', ''api_app_v1.community_posts_v1'', ''UPDATE'')\n     OR has_table_privilege(''authenticated'', ''api_app_v1.community_posts_v1'', ''DELETE'')\n     OR (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n          WHERE n.nspname = ''api_app_v1''\n            AND has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')) <> 5 THEN\n    RAISE EXCEPTION ''S2_M17_SELFCHECK: authenticated minimal grant set mismatch'';\n  END IF;\n  -- ⑥ core_private 구현부 복제 0 (M5+M7 의 5객체 그대로 공유)\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname = ''core_private'') <> 5 THEN\n    RAISE EXCEPTION ''S2_M17_SELFCHECK: core_private duplication detected'';\n  END IF;\n  -- ⑦ default privilege 방어 — PUBLIC 부여 항목 0 (PG17.6 저장 no-op 실측은 헤더 기록)\n  IF (SELECT count(*) FROM pg_default_acl d JOIN pg_namespace n ON n.oid = d.defaclnamespace\n       WHERE n.nspname = ''api_app_v1''\n         AND (d.defaclacl::text LIKE ''{=%'' OR d.defaclacl::text LIKE ''%,=%'')) > 0 THEN\n    RAISE EXCEPTION ''S2_M17_SELFCHECK: default ACL grants PUBLIC'';\n  END IF;\nEND $$;\n\ncommit;\n"], "idempotency_key": null}, {"name": "20260730112528_api_web_v1_mentor_rpc", "version": "20260731125643", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260730112528_api_web_v1_mentor_rpc.sql (S2 M8)\n-- =============================================================================\n-- 멘토 자기 관리 RPC — F7 mentor_profile_update_self · F8 mentor_plan_prices_set_self.\n-- 정본 계약: docs/contracts/api_web_v1_contract_v1_1.md §7 F7·F8 · §9.5 · §10.3 ·\n--            §11.5 · §20.2 M8 (HD-1 을 얹지 않는다 — rev 8 C 불변).\n--   - F7(XW-02 해소): 쓰기 허용 컬럼 allowlist = 시그니처 9개 그 자체\n--     (university_name·department_name·high_school_name·teaching_subjects·\n--      intro_line·bio·answer_style·profile_image_url·is_open_for_subscriptions).\n--     verification_status·cap_limit·payout_*·activity_status 등 특권·분리 컬럼은\n--     절대 갱신하지 않는다(payout 은 F13/M14 분리 — rev 8 A-4).\n--     teaching_subjects 는 public.subjects.code 실존 값만 남기고 버린다(정본\n--     qna subject 검증과 동일 방식). 아바타 ref 는 profile-avatars 정본 형식\n--     (public URL 의 /profile-avatars/ marker 또는 순수 경로 — 실측\n--      lib/storage/mentorAvatarStorage.ts)에서 경로를 추출해 첫 세그먼트가\n--     auth.uid() 인지 검증한다 — 불일치 시 PROFILE_IMAGE_REF_INVALID.\n--   - F8(XW-03 해소): 캐시(원) 3값을 받아 amount_cents = cash_krw * 100 변환.\n--     가격 밴드를 DB 상수로 강제(정본 lib/subscribe/mentorPlanPricing.ts:13 과\n--     동일 — T-REG-02 회귀 감시 대상): limited 29,900~69,900 · standard\n--     84,900~149,900 · premium 174,900~329,900. 밴드 밖은 클램프하지 않고\n--     PLAN_PRICE_OUT_OF_BAND(tier·min_cash_krw·max_cash_krw·given_cash_krw) 거부.\n--     cap_weight 는 tier 고정값 1.0/2.5/4.5 로 함수가 강제(클라이언트 불가 —\n--     XW-03 cap 우회 차단). upsert 는 ON CONFLICT (mentor_id, plan_tier)\n--     (실측 UNIQUE INDEX uq_mentor_plans_mentor_tier) · 3 tier 단일 트랜잭션.\n--   - 공통: auth.uid() 자체 도출(§11.3) · SECDEF + SET search_path='''' ·\n--     같은 트랜잭션 PUBLIC EXECUTE 회수 · EXECUTE {authenticated, service_role}.\n-- 선행조건: M1(20260730095435) 적용 완료(§20.2.1 — M8 : M1).\n-- rollback 정본: supabase/rollback/20260730112528_api_web_v1_mentor_rpc_rollback.sql\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- A. 사전 게이트\n-- -----------------------------------------------------------------------------\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = ''api_web_v1'') THEN\n    RAISE EXCEPTION ''BATCH_D_BASELINE_OBJECT_MISMATCH: M1 api_web_v1 schema not applied'';\n  END IF;\n  IF (SELECT count(*) FROM information_schema.columns\n       WHERE table_schema = ''public'' AND table_name = ''mentor_profiles''\n         AND column_name IN (''user_id'',''university_name'',''department_name'',''high_school_name'',\n                             ''teaching_subjects'',''intro_line'',''bio'',''answer_style'',\n                             ''profile_image_url'',''is_open_for_subscriptions'',''updated_at'')) <> 11\n     OR (SELECT count(*) FROM information_schema.columns\n          WHERE table_schema = ''public'' AND table_name = ''mentor_plans''\n            AND column_name IN (''mentor_id'',''plan_tier'',''amount_cents'',''cap_weight'',''price_updated_at'')) <> 5\n     OR NOT EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = ''public''\n                     AND indexname = ''uq_mentor_plans_mentor_tier'')\n     OR NOT EXISTS (SELECT 1 FROM information_schema.tables\n                     WHERE table_schema = ''public'' AND table_name = ''subjects'') THEN\n    RAISE EXCEPTION ''BATCH_D_BASELINE_OBJECT_MISMATCH: mentor base objects mismatch'';\n  END IF;\n  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n              WHERE n.nspname = ''api_web_v1''\n                AND p.proname IN (''mentor_profile_update_self'', ''mentor_plan_prices_set_self'')) THEN\n    RAISE EXCEPTION ''UNEXPECTED_EXISTING_CONTRACT_OBJECT: M8 target functions already exist'';\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- B. F7 mentor_profile_update_self (allowlist = 시그니처 9컬럼)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_web_v1.mentor_profile_update_self(\n  p_university_name text, p_department_name text, p_high_school_name text,\n  p_teaching_subjects text[], p_intro_line text, p_bio text,\n  p_answer_style text, p_profile_image_url text,\n  p_is_open_for_subscriptions boolean\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $fn$\nDECLARE\n  v_uid      uuid := (SELECT auth.uid());\n  v_role     text;\n  v_status   text;\n  v_susp     timestamptz;\n  v_subjects text[];\n  v_avatar_path text;\n  v_updated  timestamptz;\nBEGIN\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  SELECT u.role, u.status, u.suspended_until INTO v_role, v_status, v_susp\n    FROM public.users u WHERE u.id = v_uid;\n  IF NOT FOUND OR v_role IS DISTINCT FROM ''mentor'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROLE_NOT_MENTOR'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''banned'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_BANNED'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''suspended'' AND (v_susp IS NULL OR v_susp > now()) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_SUSPENDED'');\n  END IF;\n  IF public.account_deletion_write_blocked(v_uid) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM public.mentor_profiles mp WHERE mp.user_id = v_uid) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_PROFILE_NOT_FOUND'');\n  END IF;\n  IF btrim(coalesce(p_university_name, '''')) = '''' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''UNIVERSITY_NAME_REQUIRED'');\n  END IF;\n  IF btrim(coalesce(p_department_name, '''')) = '''' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''DEPARTMENT_NAME_REQUIRED'');\n  END IF;\n\n  -- teaching_subjects: subjects.code 실존 값만 보존 (정본 subject 검증 방식 승계)\n  SELECT coalesce(array_agg(s.code ORDER BY ord), ''{}''::text[]) INTO v_subjects\n    FROM unnest(coalesce(p_teaching_subjects, ''{}''::text[])) WITH ORDINALITY AS t(code, ord)\n    JOIN public.subjects s ON s.code = t.code;\n\n  -- 아바타 ref: NULL 허용(해제). 값이 있으면 profile-avatars 경로 추출 +\n  -- 첫 세그먼트 = 본인 uid 검증 (실측 mentorAvatarStorage.ts 추출 규칙과 동일)\n  IF p_profile_image_url IS NOT NULL AND btrim(p_profile_image_url) <> '''' THEN\n    IF position(''/profile-avatars/'' IN p_profile_image_url) > 0 THEN\n      v_avatar_path := split_part(split_part(\n        substring(p_profile_image_url FROM position(''/profile-avatars/'' IN p_profile_image_url) + char_length(''/profile-avatars/'')),\n        ''?'', 1), ''#'', 1);\n    ELSIF p_profile_image_url !~ ''^https?:'' THEN\n      v_avatar_path := regexp_replace(btrim(p_profile_image_url), ''^/+'', '''');\n    ELSE\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PROFILE_IMAGE_REF_INVALID'');\n    END IF;\n    IF v_avatar_path IS NULL OR v_avatar_path = ''''\n       OR split_part(v_avatar_path, ''/'', 1) IS DISTINCT FROM v_uid::text\n       OR split_part(v_avatar_path, ''/'', 2) = '''' THEN\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PROFILE_IMAGE_REF_INVALID'');\n    END IF;\n  END IF;\n\n  UPDATE public.mentor_profiles mp\n     SET university_name = btrim(p_university_name),\n         department_name = btrim(p_department_name),\n         high_school_name = nullif(btrim(coalesce(p_high_school_name, '''')), ''''),\n         teaching_subjects = v_subjects,\n         intro_line = nullif(btrim(coalesce(p_intro_line, '''')), ''''),\n         bio = nullif(btrim(coalesce(p_bio, '''')), ''''),\n         answer_style = nullif(btrim(coalesce(p_answer_style, '''')), ''''),\n         profile_image_url = nullif(btrim(coalesce(p_profile_image_url, '''')), ''''),\n         is_open_for_subscriptions = coalesce(p_is_open_for_subscriptions, mp.is_open_for_subscriptions)\n   WHERE mp.user_id = v_uid\n   RETURNING mp.updated_at INTO v_updated;\n\n  RETURN jsonb_build_object(''ok'', true, ''contract_version'', 1, ''updated_at'', v_updated);\nEND $fn$;\n\nCOMMENT ON FUNCTION api_web_v1.mentor_profile_update_self(text, text, text, text[], text, text, text, text, boolean) IS\n  ''S2 M8 F7(계약 §7 — XW-02 해소): 멘토 자기 프로필 갱신 — allowlist 9컬럼만. 특권·payout 컬럼 불변(payout 은 F13/M14 분리).'';\n\n-- -----------------------------------------------------------------------------\n-- C. F8 mentor_plan_prices_set_self (밴드 DB 강제 — XW-03 해소)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_web_v1.mentor_plan_prices_set_self(\n  p_limited_cash_krw  integer,\n  p_standard_cash_krw integer,\n  p_premium_cash_krw  integer\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $fn$\nDECLARE\n  v_uid    uuid := (SELECT auth.uid());\n  v_role   text;\n  v_status text;\n  v_susp   timestamptz;\n  -- 밴드 상수 — 정본 lib/subscribe/mentorPlanPricing.ts:13 와 동일 (T-REG-02).\n  -- 잠금값 개정 시 두 정본을 같은 PR 에서 함께 변경한다(계약 §7 F8).\n  v_tiers  text[]  := ARRAY[''limited'', ''standard'', ''premium''];\n  v_mins   int[]   := ARRAY[29900, 84900, 174900];\n  v_maxs   int[]   := ARRAY[69900, 149900, 329900];\n  v_caps   numeric[] := ARRAY[1.0, 2.5, 4.5];\n  v_given  int[];\n  v_i      int;\n  v_amount int;\n  v_old    int;\n  v_updated   jsonb := ''[]''::jsonb;\n  v_unchanged jsonb := ''[]''::jsonb;\nBEGIN\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  SELECT u.role, u.status, u.suspended_until INTO v_role, v_status, v_susp\n    FROM public.users u WHERE u.id = v_uid;\n  IF NOT FOUND OR v_role IS DISTINCT FROM ''mentor'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROLE_NOT_MENTOR'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''banned'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_BANNED'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''suspended'' AND (v_susp IS NULL OR v_susp > now()) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_SUSPENDED'');\n  END IF;\n  IF public.account_deletion_write_blocked(v_uid) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  END IF;\n\n  v_given := ARRAY[p_limited_cash_krw, p_standard_cash_krw, p_premium_cash_krw];\n\n  -- 전건 검증 선행 → 전건 반영 또는 전건 실패 (3 tier 단일 트랜잭션 — T-CONC-07 상당)\n  FOR v_i IN 1..3 LOOP\n    IF v_given[v_i] IS NULL OR v_given[v_i] < 1 THEN\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1,\n                                ''code'', ''PLAN_PRICE_INVALID'', ''tier'', v_tiers[v_i]);\n    END IF;\n    IF v_given[v_i] < v_mins[v_i] OR v_given[v_i] > v_maxs[v_i] THEN\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1,\n                                ''code'', ''PLAN_PRICE_OUT_OF_BAND'', ''tier'', v_tiers[v_i],\n                                ''min_cash_krw'', v_mins[v_i], ''max_cash_krw'', v_maxs[v_i],\n                                ''given_cash_krw'', v_given[v_i]);\n    END IF;\n  END LOOP;\n\n  FOR v_i IN 1..3 LOOP\n    v_amount := v_given[v_i] * 100;   -- amountCentsFromCashKrw 동일 (1캐시 = 1원 = 100 cents)\n    SELECT mp.amount_cents INTO v_old FROM public.mentor_plans mp\n     WHERE mp.mentor_id = v_uid AND mp.plan_tier = v_tiers[v_i];\n    IF FOUND AND v_old = v_amount\n       AND EXISTS (SELECT 1 FROM public.mentor_plans mp\n                    WHERE mp.mentor_id = v_uid AND mp.plan_tier = v_tiers[v_i]\n                      AND mp.cap_weight = v_caps[v_i]) THEN\n      v_unchanged := v_unchanged || jsonb_build_object(''plan_tier'', v_tiers[v_i], ''amount_cents'', v_amount);\n    ELSE\n      INSERT INTO public.mentor_plans (mentor_id, plan_tier, amount_cents, cap_weight, is_active, price_updated_at)\n      VALUES (v_uid, v_tiers[v_i], v_amount, v_caps[v_i], true, now())\n      ON CONFLICT (mentor_id, plan_tier) DO UPDATE\n        SET amount_cents = excluded.amount_cents,\n            cap_weight = excluded.cap_weight,       -- tier 고정값 강제(클라이언트 불가)\n            price_updated_at = now();\n      v_updated := v_updated || jsonb_build_object(''plan_tier'', v_tiers[v_i], ''amount_cents'', v_amount);\n    END IF;\n  END LOOP;\n\n  RETURN jsonb_build_object(''ok'', true, ''contract_version'', 1,\n                            ''updated'', v_updated, ''unchanged'', v_unchanged);\nEND $fn$;\n\nCOMMENT ON FUNCTION api_web_v1.mentor_plan_prices_set_self(integer, integer, integer) IS\n  ''S2 M8 F8(계약 §7 — XW-03 해소): 멘토 플랜 가격 설정 — 밴드 DB 강제(클램프 없이 거부)·cap_weight tier 고정·3 tier 단일 트랜잭션.'';\n\n-- -----------------------------------------------------------------------------\n-- D. GRANT (§10.3)\n-- -----------------------------------------------------------------------------\nREVOKE ALL ON FUNCTION api_web_v1.mentor_profile_update_self(text, text, text, text[], text, text, text, text, boolean) FROM PUBLIC;\nREVOKE ALL ON FUNCTION api_web_v1.mentor_plan_prices_set_self(integer, integer, integer) FROM PUBLIC;\nGRANT EXECUTE ON FUNCTION api_web_v1.mentor_profile_update_self(text, text, text, text[], text, text, text, text, boolean) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION api_web_v1.mentor_plan_prices_set_self(integer, integer, integer) TO authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- E. 적용 직후 자가 검증\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_cnt int;\nBEGIN\n  SELECT count(*) INTO v_cnt\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''api_web_v1''\n     AND p.prosecdef AND p.proconfig::text LIKE ''%search_path=%''\n     AND NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n     AND has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n     AND has_function_privilege(''service_role'', p.oid, ''EXECUTE'')\n     AND (p.proacl IS NULL OR (p.proacl::text NOT LIKE ''{=%'' AND p.proacl::text NOT LIKE ''%,=%''))\n     AND (p.proname, pg_get_function_identity_arguments(p.oid)) IN\n         ((''mentor_profile_update_self'', ''p_university_name text, p_department_name text, p_high_school_name text, p_teaching_subjects text[], p_intro_line text, p_bio text, p_answer_style text, p_profile_image_url text, p_is_open_for_subscriptions boolean''),\n          (''mentor_plan_prices_set_self'', ''p_limited_cash_krw integer, p_standard_cash_krw integer, p_premium_cash_krw integer''));\n  IF v_cnt <> 2 THEN\n    RAISE EXCEPTION ''S2_M8_SELFCHECK: F7/F8 hardening mismatch (matched %)'', v_cnt;\n  END IF;\n  -- F7 본문이 특권·분리 컬럼을 참조하지 않는다 (allowlist 밖 갱신 0 — XW-02 방어)\n  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n              WHERE n.nspname = ''api_web_v1'' AND p.proname = ''mentor_profile_update_self''\n                AND p.prosrc ~* ''(verification_status|cap_limit|payout_bank_name|payout_account_number|activity_status|student_id_image_url)'') THEN\n    RAISE EXCEPTION ''S2_M8_SELFCHECK: F7 must not reference privileged/separated columns'';\n  END IF;\nEND $$;\n\ncommit;\n"], "idempotency_key": null}, {"name": "20260730112531_api_web_v1_payout_account_rpc", "version": "20260731125802", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260730112531_api_web_v1_payout_account_rpc.sql (S2 M14)\n-- =============================================================================\n-- F13 mentor_payout_account_update_self — 정산계좌 전용 RPC (rev 8 A-4, U-06 해소).\n-- 정본 계약: docs/contracts/api_web_v1_contract_v1_1.md §7 F13 · §9.5 · §10.3 ·\n--            §11.5 · §20.2 M14 (M11 게이트 ② 의 선행 조건).\n--   - 정산계좌(payout_*)는 자금 수취 대상이라 프로필 수정(F7)과 분리한다.\n--   - 대상 행은 auth.uid() 자체 도출(§11.3 — user_id 인자 없음).\n--   - 승인 멘토 판정 = individual_question_user_is_approved_mentor(auth.uid())\n--     (판정식 이원화 금지). 실패 시 MENTOR_NOT_APPROVED.\n--   - 은행명 allowlist = 웹 정본 BANK_OPTIONS 16종\n--     (components/mentor/payouts/MentorPayoutAccountPanel.tsx 실측) —\n--     밖이면 PAYOUT_BANK_NAME_INVALID.\n--   - 계좌번호는 숫자만·길이 8~24 — 위반 시 PAYOUT_ACCOUNT_NUMBER_INVALID\n--     (웹 정본 mentorPayoutAccountActions.ts 의 8~24 규칙과 동일).\n--   - 계좌 원문 비반환 — 성공 {ok, contract_version, updated_at, account_masked}\n--     (끝 4자리 외 ''*'' 마스킹 — §11.4).\n--   - 관리자/service_role 조회·수정 겸용 경로를 만들지 않는다(별도 계약).\n--   - SECDEF + SET search_path='''' · PUBLIC EXECUTE 회수 · EXECUTE\n--     {authenticated, service_role}(§10.3 — anon 0).\n-- 선행조건: M1(20260730095435) 적용 완료(§20.2.1 — M14 : M1).\n-- rollback 정본: supabase/rollback/20260730112531_api_web_v1_payout_account_rpc_rollback.sql\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- A. 사전 게이트\n-- -----------------------------------------------------------------------------\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = ''api_web_v1'') THEN\n    RAISE EXCEPTION ''BATCH_D_BASELINE_OBJECT_MISMATCH: M1 api_web_v1 schema not applied'';\n  END IF;\n  IF (SELECT count(*) FROM information_schema.columns\n       WHERE table_schema = ''public'' AND table_name = ''mentor_profiles''\n         AND column_name IN (''user_id'', ''payout_bank_name'', ''payout_account_number'', ''updated_at'')) <> 4\n     OR NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                     WHERE n.nspname = ''public''\n                       AND p.proname = ''individual_question_user_is_approved_mentor'') THEN\n    RAISE EXCEPTION ''BATCH_D_BASELINE_OBJECT_MISMATCH: payout base objects mismatch'';\n  END IF;\n  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n              WHERE n.nspname = ''api_web_v1'' AND p.proname = ''mentor_payout_account_update_self'') THEN\n    RAISE EXCEPTION ''UNEXPECTED_EXISTING_CONTRACT_OBJECT: F13 already exists'';\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- B. F13\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_web_v1.mentor_payout_account_update_self(\n  p_bank_name text, p_account_number text\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $fn$\nDECLARE\n  v_uid    uuid := (SELECT auth.uid());\n  v_role   text;\n  v_status text;\n  v_susp   timestamptz;\n  v_bank   text := btrim(coalesce(p_bank_name, ''''));\n  v_acct   text := btrim(coalesce(p_account_number, ''''));\n  v_updated timestamptz;\nBEGIN\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  SELECT u.role, u.status, u.suspended_until INTO v_role, v_status, v_susp\n    FROM public.users u WHERE u.id = v_uid;\n  IF NOT FOUND OR v_role IS DISTINCT FROM ''mentor'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROLE_NOT_MENTOR'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''banned'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_BANNED'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''suspended'' AND (v_susp IS NULL OR v_susp > now()) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_SUSPENDED'');\n  END IF;\n  IF public.account_deletion_write_blocked(v_uid) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  END IF;\n  IF NOT public.individual_question_user_is_approved_mentor(v_uid) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_APPROVED'');\n  END IF;\n\n  -- 은행명 allowlist (웹 정본 BANK_OPTIONS 16종 — MentorPayoutAccountPanel.tsx)\n  IF v_bank NOT IN (''KB국민은행'', ''신한은행'', ''우리은행'', ''하나은행'', ''NH농협은행'',\n                    ''IBK기업은행'', ''카카오뱅크'', ''토스뱅크'', ''케이뱅크'', ''SC제일은행'',\n                    ''씨티은행'', ''KDB산업은행'', ''수협은행'', ''신협'', ''새마을금고'', ''우체국'') THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAYOUT_BANK_NAME_INVALID'');\n  END IF;\n  -- 계좌번호 숫자만·길이 8~24\n  IF v_acct !~ ''^[0-9]{8,24}$'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAYOUT_ACCOUNT_NUMBER_INVALID'');\n  END IF;\n\n  UPDATE public.mentor_profiles mp\n     SET payout_bank_name = v_bank,\n         payout_account_number = v_acct\n   WHERE mp.user_id = v_uid\n   RETURNING mp.updated_at INTO v_updated;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_PROFILE_NOT_FOUND'');\n  END IF;\n\n  -- 계좌 원문 비반환 — 끝 4자리 외 마스킹(§11.4)\n  RETURN jsonb_build_object(''ok'', true, ''contract_version'', 1, ''updated_at'', v_updated,\n    ''account_masked'', repeat(''*'', greatest(char_length(v_acct) - 4, 0)) || right(v_acct, 4));\nEND $fn$;\n\nCOMMENT ON FUNCTION api_web_v1.mentor_payout_account_update_self(text, text) IS\n  ''S2 M14 F13(계약 §7 — rev 8 A-4, U-06 해소): 정산계좌 전용 RPC — 승인 멘토·은행 allowlist·계좌 8~24 숫자·원문 비반환(끝 4자리 마스킹). M11 게이트 ② 선행.'';\n\n-- -----------------------------------------------------------------------------\n-- C. GRANT (§10.3)\n-- -----------------------------------------------------------------------------\nREVOKE ALL ON FUNCTION api_web_v1.mentor_payout_account_update_self(text, text) FROM PUBLIC;\nGRANT EXECUTE ON FUNCTION api_web_v1.mentor_payout_account_update_self(text, text) TO authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- D. 적용 직후 자가 검증\n-- -----------------------------------------------------------------------------\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''api_web_v1'' AND p.proname = ''mentor_payout_account_update_self''\n                    AND pg_get_function_identity_arguments(p.oid) = ''p_bank_name text, p_account_number text''\n                    AND p.prosecdef AND p.proconfig::text LIKE ''%search_path=%''\n                    AND NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n                    AND has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n                    AND has_function_privilege(''service_role'', p.oid, ''EXECUTE'')\n                    AND (p.proacl IS NULL OR (p.proacl::text NOT LIKE ''{=%'' AND p.proacl::text NOT LIKE ''%,=%''))) THEN\n    RAISE EXCEPTION ''S2_M14_SELFCHECK: F13 hardening mismatch'';\n  END IF;\nEND $$;\n\ncommit;\n"], "idempotency_key": null}, {"name": "20260730120103_money_rpc", "version": "20260731134000", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260730120103_money_rpc.sql (S2 M9)\n-- =============================================================================\n-- 자금 RPC — F11 3층 + F12. 정본 계약: docs/contracts/api_web_v1_contract_v1_1.md\n--   §7 F11(3층 — rev 8 A-6) · §7 F12(rev 8 A-2·A-5 전면 재작성) · §8(envelope) ·\n--   §9.6(자금 코드) · §9.8(confirm raise 17종 동명 유지) · §10.3(service_role 전용) ·\n--   §12.2/[C3](잠금 순서 payments → advisory → mentor_plans) · §20.3(M9 이전 게이트) ·\n--   §21.3 T-CONC-02·03·04·08·09 · §21.4 T-FIN · §21.8 T-REP · §21.9 T-TOP.\n--\n-- 한 마이그레이션에서 전부 수행(§20.2 M9 행):\n--   [1층] core_private.record_cash_topup_impl — 공용 원자 구현부(SECURITY INVOKER,\n--         외부 EXECUTE 0). ON CONFLICT 원자 판정(사전 SELECT 추정 금지), 신규에만\n--         지갑 가산, duplicate 는 FOR UPDATE 재조회 후 8필드 내부 형상 반환.\n--   [2층] public.record_cash_topup — 기존 시그니처·void·SECDEF·service_role 전용·\n--         duplicate 무음 반환 불변. 내부 구현만 공용 구현부 위임으로 교체(T-REG-06:\n--         계약된 본문 교체 허용·신규 public 함수 0). 검증 4종은 impl 이 020 과\n--         동일 메시지·동일 순서로 수행한다.\n--   [3층] api_web_v1.record_cash_topup_v2 — strict wrapper(3인자,\n--         p_idempotency_key = p_order_ref). `^cash-(.+)-([0-9]+)$` 강제(ORDER_REF_INVALID),\n--         소유자 재검증(ORDER_REF_OWNER_MISMATCH), duplicate 6필드 NULL-safe 전건\n--         대조(LEDGER_FIELD_MISMATCH). service_role 전용 EXECUTE.\n--   [F12] api_web_v1.subscription_checkout_confirm_v2 — 최초 실행은 정본\n--         public.confirm_subscription_checkout 을 감싸고(재생 판정은 자체 수행 —\n--         정본 재호출 금지), 잠금 순서 [C3](payments FOR UPDATE → advisory →\n--         mentor_plans FOR UPDATE) 준수, 3자 일치(payments.amount×100 =\n--         p_expected_amount_cents = 잠근 mentor_plans.amount_cents, 불일치 =\n--         PLAN_AMOUNT_CHANGED 차감 0), 방 확보 실패 시 이번 트랜잭션 자금·원장·\n--         구독·결제 변경 전부 롤백(ROOM_ENSURE_FAILED). 재생은 Phase 1(검증 전용,\n--         9단계 우선순위·anomaly 기록만 허용) → Phase 2(room 확보·보정)로 분리하고\n--         현재 플랜 가격을 읽지 않는다. 정본 raise 17종은 동명 envelope 로 변환,\n--         사전 밖 예외는 그대로 전파(§8.2 — bare RAISE).\n--\n-- 구현 결정(사전에 없는 이름·코드 임의 생성 금지 — 기존 사전 재사용):\n--   * F12 의 결제 시점 불변 동의 금액 검증(§7 F12): kind ≠ ''subscription'' →\n--     `PAYMENT_KIND_INVALID`, currency ≠ ''KRW''·amount ≤ 0·비정수 →\n--     `PAYMENT_STATE_UNEXPECTED` (둘 다 §9.6 \"결제 행 상태\" 사전 동명 재사용,\n--     raise 변환 계열이므로 anomaly 미기록). 정본도 kind 검증을 succeeded 분기\n--     이전에 수행하므로 동일 위치(재생 분기 이전 공통부)에 둔다.\n--   * 최초 실행 경로에서 기존 방의 `subscription_id` 가 다른 값이면 §7 F12 room\n--     참조 규칙 표의 \"거부\" = `ROOM_REF_MISMATCH` + anomaly + subtransaction 전부\n--     롤백으로 구현한다(재생 9단계와 동일 코드 — §9.6 정의가 재생 한정이 아님).\n--   * §20.3 \"F12 배포 전 사전 검사\"는 이 파일의 사전 게이트가 **탐지만** 수행한다\n--     (>0 이면 중단 — 보정은 운영 절차(§20.3)이며 migration 이 무단 쓰기하지 않는다).\n--   * PG17.6 실측(M1 헤더 참조): 신규 함수는 하드와이어드 default 로 PUBLIC EXECUTE\n--     를 받으므로 함수별 명시 `REVOKE ALL … FROM PUBLIC` 이 유효한 방어층이다.\n-- 선행조건: M5(20260730105244 — F10) 적용 완료(§20.2.1 — M9 : M5).\n-- rollback 정본: supabase/rollback/20260730120103_money_rpc_rollback.sql\n--   (레거시 record_cash_topup 020 구 본문 문자 그대로 복원 포함 — §22 #3)\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- A. 사전 게이트 — 기반 실측 (불일치 시 수정 0건 중단)\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_cnt bigint;\nBEGIN\n  -- M1·M5 경계\n  IF (SELECT count(*) FROM pg_namespace WHERE nspname IN (''api_web_v1'',''core_private'')) <> 2 THEN\n    RAISE EXCEPTION ''BATCH_E_BASELINE_OBJECT_MISMATCH: M1 schemas not applied'';\n  END IF;\n  IF has_schema_privilege(''anon'', ''core_private'', ''USAGE'')\n     OR has_schema_privilege(''authenticated'', ''core_private'', ''USAGE'')\n     OR has_schema_privilege(''service_role'', ''core_private'', ''USAGE'') THEN\n    RAISE EXCEPTION ''BATCH_E_BASELINE_OBJECT_MISMATCH: core_private boundary violated'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''core_private'' AND p.proname = ''ensure_student_mentor_room''\n                    AND pg_get_function_identity_arguments(p.oid)\n                        = ''p_student_id uuid, p_mentor_id uuid, p_payment_id uuid, p_subscription_id uuid, p_require_entitlement boolean'') THEN\n    RAISE EXCEPTION ''BATCH_E_BASELINE_OBJECT_MISMATCH: M5 F10 missing or identity mismatch'';\n  END IF;\n  -- 자금 기반 테이블·제약 (§7 F11 — cash_ledger_idempotency_key_key UNIQUE 실재)\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint c JOIN pg_class r ON r.oid = c.conrelid\n                  JOIN pg_namespace n ON n.oid = r.relnamespace\n                  WHERE n.nspname = ''public'' AND r.relname = ''cash_ledger''\n                    AND c.conname = ''cash_ledger_idempotency_key_key'' AND c.contype = ''u'') THEN\n    RAISE EXCEPTION ''BATCH_E_BASELINE_OBJECT_MISMATCH: cash_ledger idempotency UNIQUE missing'';\n  END IF;\n  IF (SELECT count(*) FROM information_schema.columns\n       WHERE table_schema = ''public'' AND table_name = ''cash_ledger''\n         AND column_name IN (''id'',''user_id'',''delta_cents'',''reason'',''ref_type'',''ref_id'',''idempotency_key'')) <> 7\n     OR (SELECT count(*) FROM information_schema.columns\n          WHERE table_schema = ''public'' AND table_name = ''cash_wallets''\n            AND column_name IN (''user_id'',''balance_cents'')) <> 2 THEN\n    RAISE EXCEPTION ''BATCH_E_BASELINE_OBJECT_MISMATCH: cash tables columns mismatch'';\n  END IF;\n  -- ref_text 컬럼은 존재하지 않아야 한다(rev 8 A-6 — v1.0 ref_text·M2 폐기, T-FIN-01)\n  IF EXISTS (SELECT 1 FROM information_schema.columns\n              WHERE table_schema = ''public'' AND table_name = ''cash_ledger'' AND column_name = ''ref_text'') THEN\n    RAISE EXCEPTION ''BATCH_E_BASELINE_OBJECT_MISMATCH: cash_ledger.ref_text must not exist'';\n  END IF;\n  -- 결제·구독·방 기반 (131 payments.plan_id · 064 last_payment_id · uq 2종)\n  IF (SELECT count(*) FROM information_schema.columns\n       WHERE table_schema = ''public'' AND table_name = ''payments''\n         AND column_name IN (''id'',''user_id'',''mentor_id'',''amount'',''currency'',''status'',''kind'',''plan_id'',''metadata'',''created_at'')) <> 10 THEN\n    RAISE EXCEPTION ''BATCH_E_BASELINE_OBJECT_MISMATCH: payments columns mismatch'';\n  END IF;\n  IF (SELECT count(*) FROM information_schema.columns\n       WHERE table_schema = ''public'' AND table_name = ''subscriptions''\n         AND column_name IN (''id'',''student_id'',''mentor_id'',''plan_id'',''status'',''payment_id'',''last_payment_id'')) <> 7\n     OR NOT EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = ''public''\n                     AND tablename = ''subscriptions'' AND indexname = ''uq_subscriptions_pair'')\n     OR NOT EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = ''public''\n                     AND tablename = ''mentor_student_rooms'' AND indexname = ''uq_msr_pair'') THEN\n    RAISE EXCEPTION ''BATCH_E_BASELINE_OBJECT_MISMATCH: subscriptions/rooms baseline mismatch'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM information_schema.tables\n                  WHERE table_schema = ''public'' AND table_name = ''subscription_checkout_anomalies'') THEN\n    RAISE EXCEPTION ''BATCH_E_BASELINE_OBJECT_MISMATCH: 145 anomaly table missing'';\n  END IF;\n  -- 레거시 정본 함수 3종 (020·145·019)\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''public'' AND p.proname = ''record_cash_topup''\n                    AND pg_get_function_identity_arguments(p.oid) = ''p_user_id uuid, p_amount_cents bigint, p_idempotency_key text''\n                    AND p.prorettype = ''void''::regtype AND p.prosecdef) THEN\n    RAISE EXCEPTION ''BATCH_E_BASELINE_OBJECT_MISMATCH: legacy record_cash_topup mismatch'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''public'' AND p.proname = ''confirm_subscription_checkout''\n                    AND pg_get_function_identity_arguments(p.oid) = ''p_payment_id uuid, p_plan_id uuid, p_idempotency_key text''\n                    AND p.prorettype = ''jsonb''::regtype AND p.prosecdef) THEN\n    RAISE EXCEPTION ''BATCH_E_BASELINE_OBJECT_MISMATCH: legacy confirm_subscription_checkout mismatch'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''public'' AND p.proname = ''record_subscription_cash_debit'') THEN\n    RAISE EXCEPTION ''BATCH_E_BASELINE_OBJECT_MISMATCH: record_subscription_cash_debit missing'';\n  END IF;\n  -- 대상 선재 금지 (부분 생성 은닉 금지)\n  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n              WHERE (n.nspname = ''api_web_v1'' AND p.proname IN (''record_cash_topup_v2'',''subscription_checkout_confirm_v2''))\n                 OR (n.nspname = ''core_private'' AND p.proname = ''record_cash_topup_impl'')) THEN\n    RAISE EXCEPTION ''UNEXPECTED_EXISTING_CONTRACT_OBJECT: M9 target objects already exist'';\n  END IF;\n  -- §20.3 \"F12 배포 전 사전 검사\": 구독이 참조하는 succeeded 결제 중 방 없는 건 탐지.\n  -- 탐지만 한다 — >0 이면 중단하고 보정은 운영 절차로 수행한다(로컬 clean install = 0).\n  SELECT count(*) INTO v_cnt\n    FROM public.payments p\n   WHERE p.status IN (''succeeded'',''paid'',''success'',''complete'',''captured'')\n     AND p.user_id IS NOT NULL AND p.mentor_id IS NOT NULL\n     AND EXISTS (SELECT 1 FROM public.subscriptions s\n                  WHERE s.payment_id = p.id OR s.last_payment_id = p.id)\n     AND NOT EXISTS (SELECT 1 FROM public.mentor_student_rooms r\n                      WHERE r.student_id = p.user_id AND r.mentor_id = p.mentor_id);\n  IF v_cnt > 0 THEN\n    RAISE EXCEPTION ''S2_M9_PRE_CHECK_ROOMLESS_SUCCEEDED_SUBSCRIPTION_PAYMENTS: % 건 — §20.3 보정 후 재적용'', v_cnt;\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- B. [1층] core_private.record_cash_topup_impl — 공용 원자 구현부 (F11i)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION core_private.record_cash_topup_impl(\n  p_user_id uuid,\n  p_amount_cents bigint,\n  p_idempotency_key text\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY INVOKER SET search_path = '''' AS $$\nDECLARE\n  v_idem   text;\n  v_new_id uuid;\n  v_wu     int;\n  v_id     uuid;\n  v_user   uuid;\n  v_delta  bigint;\n  v_reason text;\n  v_rtype  text;\n  v_rid    uuid;\n  v_key    text;\nBEGIN\n  -- 검증 4종 — 020 레거시와 동일 메시지·동일 순서(2층 관측 계약 불변)\n  IF p_user_id IS NULL THEN\n    RAISE EXCEPTION ''p_user_id is required'';\n  END IF;\n  v_idem := nullif(trim(coalesce(p_idempotency_key, '''')), '''');\n  IF v_idem IS NULL OR length(v_idem) = 0 THEN\n    RAISE EXCEPTION ''p_idempotency_key is required'';\n  END IF;\n  IF p_amount_cents IS NULL OR p_amount_cents <= 0 THEN\n    RAISE EXCEPTION ''p_amount_cents must be positive'';\n  END IF;\n  IF p_amount_cents > 1000000000 THEN\n    RAISE EXCEPTION ''p_amount_too_large'';\n  END IF;\n\n  -- ① 원자 판정 — 사전 SELECT 로 신규/duplicate 를 추정하는 구현은 금지(§7 F11 1층)\n  INSERT INTO public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n  VALUES (p_user_id, p_amount_cents, ''cash_topup'', ''topup'', NULL, v_idem)\n  ON CONFLICT (idempotency_key) DO NOTHING\n  RETURNING id INTO v_new_id;\n\n  IF v_new_id IS NOT NULL THEN\n    -- ② 신규 INSERT 일 때만 지갑 upsert·잔액 가산 (row_count=0 → 예외 — 부분 실패 전파)\n    INSERT INTO public.cash_wallets (user_id, balance_cents)\n    VALUES (p_user_id, 0)\n    ON CONFLICT (user_id) DO NOTHING;\n    UPDATE public.cash_wallets w\n       SET balance_cents = w.balance_cents + p_amount_cents\n     WHERE w.user_id = p_user_id;\n    GET DIAGNOSTICS v_wu = ROW_COUNT;\n    IF coalesce(v_wu, 0) = 0 THEN\n      RAISE EXCEPTION ''CASH_WALLET_UPSERT_FAILED'' USING ERRCODE = ''P0001'';\n    END IF;\n    RETURN jsonb_build_object(\n      ''ledger_id'', v_new_id, ''inserted'', true, ''user_id'', p_user_id,\n      ''delta_cents'', p_amount_cents, ''reason'', ''cash_topup'', ''ref_type'', ''topup'',\n      ''ref_id'', NULL, ''idempotency_key'', v_idem);\n  END IF;\n\n  -- ③ duplicate: 지갑 갱신 금지 ④ 기존 행 FOR UPDATE 재조회 ⑤ 8필드 내부 형상 반환\n  SELECT l.id, l.user_id, l.delta_cents, l.reason, l.ref_type, l.ref_id, l.idempotency_key\n    INTO v_id, v_user, v_delta, v_reason, v_rtype, v_rid, v_key\n    FROM public.cash_ledger l\n   WHERE l.idempotency_key = v_idem\n   FOR UPDATE;\n  RETURN jsonb_build_object(\n    ''ledger_id'', v_id, ''inserted'', false, ''user_id'', v_user,\n    ''delta_cents'', v_delta, ''reason'', v_reason, ''ref_type'', v_rtype,\n    ''ref_id'', v_rid, ''idempotency_key'', v_key);\nEND $$;\n\nCOMMENT ON FUNCTION core_private.record_cash_topup_impl(uuid, bigint, text) IS\n  ''S2 M9 F11i(계약 §7 F11 1층): topup 공용 원자 구현부 — F11·레거시 record_cash_topup 이 수렴. SECURITY INVOKER·외부 EXECUTE 0(SECDEF wrapper 소유자 문맥 전용).'';\n\nREVOKE ALL ON FUNCTION core_private.record_cash_topup_impl(uuid, bigint, text) FROM PUBLIC;\n\n-- -----------------------------------------------------------------------------\n-- C. [2층] public.record_cash_topup — 내부 구현만 공용 구현부 위임으로 교체\n--    (시그니처·void·SECDEF·search_path·ACL·duplicate 무음 반환 전부 불변 — §7 F11 2층.\n--     CREATE OR REPLACE 는 기존 proacl 을 보존한다. GRANT/REVOKE 재실행 없음.)\n-- -----------------------------------------------------------------------------\ncreate or replace function public.record_cash_topup(\n  p_user_id uuid,\n  p_amount_cents bigint,\n  p_idempotency_key text\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $function$\nbegin\n  -- S2 M9(계약 §7 F11 2층): 검증·원자 판정·지갑 가산은 공용 구현부가 020 과 동일\n  -- 메시지·순서로 수행한다. 반환값은 폐기하며 duplicate(필드 불일치 포함)는 기존\n  -- 계약대로 무음 반환한다 — mismatch 를 새로 외부에 노출하지 않는다.\n  perform core_private.record_cash_topup_impl(p_user_id, p_amount_cents, p_idempotency_key);\nend;\n$function$;\n\n-- -----------------------------------------------------------------------------\n-- D. [3층] api_web_v1.record_cash_topup_v2 — strict wrapper (F11)\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_web_v1.record_cash_topup_v2(\n  p_user_id uuid,\n  p_amount_cents bigint,\n  p_order_ref text\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $$\nDECLARE\n  v_key     text;\n  v_m       text[];\n  v_uid     uuid;\n  v_res     jsonb;\n  v_balance bigint;\nBEGIN\n  -- 1. 입력 검증 (사전 밖 예외는 전파 — §8.2. 레거시와 동일 메시지)\n  IF p_user_id IS NULL THEN\n    RAISE EXCEPTION ''p_user_id is required'';\n  END IF;\n  IF p_amount_cents IS NULL OR p_amount_cents <= 0 THEN\n    RAISE EXCEPTION ''p_amount_cents must be positive'';\n  END IF;\n  IF p_amount_cents > 1000000000 THEN\n    RAISE EXCEPTION ''p_amount_too_large'';\n  END IF;\n\n  -- 2. Toss 주문 참조 형식 강제 — lib/toss/tossTopupCore.ts `^cash-(.+)-(\\d+)$` 동치\n  v_key := nullif(trim(coalesce(p_order_ref, '''')), '''');\n  IF v_key IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ORDER_REF_INVALID'');\n  END IF;\n  v_m := regexp_match(v_key, ''^cash-(.+)-([0-9]+)$'');\n  IF v_m IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ORDER_REF_INVALID'');\n  END IF;\n\n  -- 3. 소유자 재검증 — parseUserIdFromCashOrderId 동치(uuid 파싱 불가 = 불일치)\n  BEGIN\n    v_uid := v_m[1]::uuid;\n  EXCEPTION WHEN invalid_text_representation THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ORDER_REF_OWNER_MISMATCH'');\n  END;\n  IF v_uid IS DISTINCT FROM p_user_id THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ORDER_REF_OWNER_MISMATCH'');\n  END IF;\n\n  -- 4. 공용 원자 구현부 호출 (p_idempotency_key = p_order_ref — 별도 인자가 아니다)\n  v_res := core_private.record_cash_topup_impl(p_user_id, p_amount_cents, v_key);\n\n  -- 5. 신규 → 성공\n  IF coalesce((v_res->>''inserted'')::boolean, false) THEN\n    SELECT w.balance_cents INTO v_balance FROM public.cash_wallets w WHERE w.user_id = p_user_id;\n    RETURN jsonb_build_object(''ok'', true, ''contract_version'', 1, ''duplicate'', false,\n                              ''ledger_id'', (v_res->>''ledger_id'')::uuid,\n                              ''balance_cents'', v_balance);\n  END IF;\n\n  -- 5. duplicate → 기존 6필드 NULL-safe 전건 대조 (일반 =·<> 는 nullable 필드에 금지)\n  IF (v_res->>''user_id'')::uuid IS NOT DISTINCT FROM p_user_id\n     AND (v_res->>''delta_cents'')::bigint IS NOT DISTINCT FROM p_amount_cents\n     AND (v_res->>''reason'') IS NOT DISTINCT FROM ''cash_topup''\n     AND (v_res->>''ref_type'') IS NOT DISTINCT FROM ''topup''\n     AND (v_res->>''ref_id'') IS NULL\n     AND (v_res->>''idempotency_key'') IS NOT NULL\n     AND (v_res->>''idempotency_key'') = v_key THEN\n    SELECT w.balance_cents INTO v_balance FROM public.cash_wallets w WHERE w.user_id = p_user_id;\n    RETURN jsonb_build_object(''ok'', true, ''contract_version'', 1, ''duplicate'', true,\n                              ''ledger_id'', (v_res->>''ledger_id'')::uuid,\n                              ''balance_cents'', v_balance);\n  END IF;\n  RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''LEDGER_FIELD_MISMATCH'');\nEND $$;\n\nCOMMENT ON FUNCTION api_web_v1.record_cash_topup_v2(uuid, bigint, text) IS\n  ''S2 M9 F11(계약 §7 F11 3층): Toss 충전 strict wrapper — orderId 형식·소유자 재검증 + duplicate 6필드 NULL-safe 대조. service_role 전용(T4a).'';\n\n-- -----------------------------------------------------------------------------\n-- E. F12 api_web_v1.subscription_checkout_confirm_v2\n-- -----------------------------------------------------------------------------\nCREATE FUNCTION api_web_v1.subscription_checkout_confirm_v2(\n  p_payment_id uuid,\n  p_plan_id uuid,\n  p_expected_amount_cents integer,\n  p_idempotency_key text DEFAULT NULL\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $$\nDECLARE\n  v_succeeded    constant text[] := array[''succeeded'',''paid'',''success'',''complete'',''captured''];\n  -- 정본 confirm_subscription_checkout raise 17종(§9.8 — 동명 envelope 변환)\n  v_canon_raises constant text[] := array[\n    ''PAYMENT_NOT_FOUND'',''PAYMENT_NO_USER'',''PAYMENT_NO_MENTOR'',''PAYMENT_KIND_INVALID'',\n    ''PLAN_NOT_FOUND'',''PLAN_MENTOR_MISMATCH'',''PLAN_AMOUNT_INVALID'',\n    ''PAYMENT_PROCESSING'',''PAYMENT_NOT_PENDING'',''PAYMENT_STATE_UNEXPECTED'',''PAYMENT_STALE'',\n    ''ACCOUNT_BANNED'',''ACCOUNT_SUSPENDED'',\n    ''MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS'',''MENTOR_NOT_APPROVED'',''PLAN_INACTIVE'',''MENTOR_CAP_EXCEEDED''];\n  p_rec          record;      -- P = 이번 호출 payment\n  v_sub          record;      -- 잠근 subscription\n  v_led          record;      -- P 자신의 sub_debit_ 원장 행\n  v_c            record;      -- C = subscription.last_payment_id 가 가리키는 payment\n  v_room         record;\n  v_intent       bigint;      -- 결제 시점 불변 동의 금액 = payments.amount × 100\n  v_plan_amount  integer;\n  v_anom         uuid;\n  v_canon        jsonb;\n  v_roomres      jsonb;\n  v_room_id      uuid;\n  v_sub_id       uuid;\n  v_room_found   boolean := false;\n  v_room_new_sub uuid;        -- Phase 2 보정 후보(subscription_id)\n  v_room_new_pay uuid;        -- Phase 2 보정 후보(payment_id)\n  v_room_dirty   boolean := false;\nBEGIN\n  IF p_payment_id IS NULL OR p_plan_id IS NULL OR p_expected_amount_cents IS NULL THEN\n    RAISE EXCEPTION ''p_payment_id, p_plan_id, p_expected_amount_cents are required'';\n  END IF;\n\n  -- 1) payments FOR UPDATE — §12.2/[C3]: 레거시와 동일하게 payments 를 먼저 잠근다\n  SELECT p.id, p.user_id, p.mentor_id, p.status, p.kind, p.amount, p.currency, p.plan_id\n    INTO p_rec\n    FROM public.payments p WHERE p.id = p_payment_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAYMENT_NOT_FOUND'');\n  END IF;\n  IF p_rec.user_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAYMENT_NO_USER'');\n  END IF;\n  IF p_rec.mentor_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAYMENT_NO_MENTOR'');\n  END IF;\n  -- 결제 시점 불변 동의 금액 검증(§7 F12 — 구현 결정: 사전 동명 재사용, anomaly 미기록)\n  IF p_rec.kind IS DISTINCT FROM ''subscription'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAYMENT_KIND_INVALID'');\n  END IF;\n  IF p_rec.currency IS DISTINCT FROM ''KRW''\n     OR p_rec.amount IS NULL OR p_rec.amount <= 0 OR p_rec.amount <> trunc(p_rec.amount) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAYMENT_STATE_UNEXPECTED'');\n  END IF;\n  v_intent := (p_rec.amount * 100)::bigint;\n\n  -- 2) 재생 판정 — succeeded 계열이면 재생 계약(Phase 1/2)으로 분기(정본 재호출 금지)\n  IF p_rec.status = ANY(v_succeeded) THEN\n    -- ── Phase 1: 검증 전용 (business-state 쓰기 금지 · anomaly INSERT 만 허용) ──\n    -- 1·2. subscription 행 확인·잠금 (최신 결제 정본은 오직 last_payment_id — 추론 금지)\n    SELECT s.id, s.student_id, s.mentor_id, s.last_payment_id\n      INTO v_sub\n      FROM public.subscriptions s\n     WHERE s.student_id = p_rec.user_id AND s.mentor_id = p_rec.mentor_id\n     FOR UPDATE;\n    IF NOT FOUND THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, NULL, ''SUCCEEDED_NO_SUBSCRIPTION'', ''F12 replay: succeeded payment without subscription'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUCCEEDED_NO_SUBSCRIPTION'', ''anomaly_id'', v_anom);\n    END IF;\n    -- 3. P 자신의 원장 행 확인\n    SELECT l.user_id, l.delta_cents, l.reason, l.ref_type, l.ref_id\n      INTO v_led\n      FROM public.cash_ledger l\n     WHERE l.idempotency_key = ''sub_debit_'' || p_payment_id::text;\n    IF NOT FOUND THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, v_sub.id, ''SUCCEEDED_NO_LEDGER'', ''F12 replay: succeeded payment without ledger debit'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUCCEEDED_NO_LEDGER'', ''anomaly_id'', v_anom);\n    END IF;\n    -- 4. P 의 payment–plan 결속 (필수 관계 — NULL 은 일치가 아니라 명시 거부)\n    IF p_rec.plan_id IS NULL OR p_rec.plan_id <> p_plan_id THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)\n      VALUES (p_payment_id, v_sub.id, ''PLAN_BINDING_MISMATCH'', ''F12 replay: payments.plan_id <> p_plan_id'',\n              jsonb_build_object(''plan_id'', p_plan_id), jsonb_build_object(''plan_id'', p_rec.plan_id))\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_BINDING_MISMATCH'', ''anomaly_id'', v_anom);\n    END IF;\n    -- 5. P 의 payment–subscription 당사자 결속\n    IF p_rec.user_id <> v_sub.student_id OR p_rec.mentor_id <> v_sub.mentor_id THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, v_sub.id, ''PARTY_BINDING_MISMATCH'', ''F12 replay: P party mismatch'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PARTY_BINDING_MISMATCH'', ''anomaly_id'', v_anom);\n    END IF;\n    -- 6. ledger–subscription 결속 (필수 관계 — NULL 명시 거부)\n    IF v_led.user_id IS NULL OR v_led.user_id <> p_rec.user_id\n       OR v_led.ref_id IS NULL OR v_led.ref_id <> v_sub.id THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)\n      VALUES (p_payment_id, v_sub.id, ''LEDGER_BINDING_MISMATCH'', ''F12 replay: ledger user/ref binding mismatch'',\n              jsonb_build_object(''user_id'', p_rec.user_id, ''ref_id'', v_sub.id),\n              jsonb_build_object(''user_id'', v_led.user_id, ''ref_id'', v_led.ref_id))\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''LEDGER_BINDING_MISMATCH'', ''anomaly_id'', v_anom);\n    END IF;\n    -- 7. 원장 필드값 대조 — 기준은 결제 시점 불변 동의 금액(payments.amount×100).\n    --    현재 플랜 가격을 읽지 않는다(가격 변경 후 정당한 재시도 오탐 금지 — T-CONC-09).\n    IF v_led.delta_cents IS DISTINCT FROM -v_intent\n       OR coalesce(v_led.reason, '''') <> ''subscription_payment''\n       OR coalesce(v_led.ref_type, '''') <> ''subscriptions'' THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)\n      VALUES (p_payment_id, v_sub.id, ''LEDGER_FIELD_MISMATCH'', ''F12 replay: ledger field mismatch vs intent amount'',\n              jsonb_build_object(''user_id'', p_rec.user_id, ''ref_id'', v_sub.id, ''ref_type'', ''subscriptions'',\n                                 ''reason'', ''subscription_payment'', ''delta_cents'', -v_intent),\n              jsonb_build_object(''user_id'', v_led.user_id, ''ref_id'', v_led.ref_id, ''ref_type'', v_led.ref_type,\n                                 ''reason'', v_led.reason, ''delta_cents'', v_led.delta_cents))\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''LEDGER_FIELD_MISMATCH'', ''anomaly_id'', v_anom);\n    END IF;\n    -- 8. C = subscription.last_payment_id 유효성 (detail 은 anomaly 에만 — 코드는 1종 고정)\n    IF v_sub.last_payment_id IS NULL THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, v_sub.id, ''SUBSCRIPTION_REF_INVALID'', ''LAST_PAYMENT_ID_NULL'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_REF_INVALID'', ''anomaly_id'', v_anom);\n    END IF;\n    SELECT p2.id, p2.user_id, p2.mentor_id, p2.status\n      INTO v_c FROM public.payments p2 WHERE p2.id = v_sub.last_payment_id;\n    IF NOT FOUND THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, v_sub.id, ''SUBSCRIPTION_REF_INVALID'', ''LAST_PAYMENT_NOT_FOUND'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_REF_INVALID'', ''anomaly_id'', v_anom);\n    END IF;\n    IF NOT (v_c.status = ANY(v_succeeded)) THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, v_sub.id, ''SUBSCRIPTION_REF_INVALID'', ''LAST_PAYMENT_NOT_SUCCEEDED'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_REF_INVALID'', ''anomaly_id'', v_anom);\n    END IF;\n    -- C 당사자 불일치는 8단계 PARTY_BINDING_MISMATCH (LEDGER_BINDING 으로 뭉개지 않는다)\n    IF v_c.user_id IS NULL OR v_c.user_id <> v_sub.student_id\n       OR v_c.mentor_id IS NULL OR v_c.mentor_id <> v_sub.mentor_id THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, v_sub.id, ''PARTY_BINDING_MISMATCH'', ''F12 replay: C party mismatch'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PARTY_BINDING_MISMATCH'', ''anomaly_id'', v_anom);\n    END IF;\n    -- 9. room 참조 판정 (쓰기 없음 — 보정 예정값 후보만 계산)\n    SELECT r.id, r.subscription_id, r.payment_id\n      INTO v_room\n      FROM public.mentor_student_rooms r\n     WHERE r.student_id = v_sub.student_id AND r.mentor_id = v_sub.mentor_id\n     FOR UPDATE;\n    v_room_found := FOUND;\n    IF v_room_found THEN\n      IF v_room.subscription_id IS NULL THEN\n        v_room_new_sub := v_sub.id; v_room_dirty := true;\n      ELSIF v_room.subscription_id <> v_sub.id THEN\n        INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)\n        VALUES (p_payment_id, v_sub.id, ''ROOM_REF_MISMATCH'', ''F12 replay: room.subscription_id conflict'',\n                jsonb_build_object(''subscription_id'', v_sub.id),\n                jsonb_build_object(''subscription_id'', v_room.subscription_id))\n        RETURNING id INTO v_anom;\n        RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROOM_REF_MISMATCH'', ''anomaly_id'', v_anom);\n      ELSE\n        v_room_new_sub := v_room.subscription_id;\n      END IF;\n      IF v_room.payment_id IS NULL THEN\n        v_room_new_pay := v_sub.last_payment_id; v_room_dirty := true;                  -- NULL → C 로 복구 후보\n      ELSIF v_room.payment_id = v_sub.last_payment_id THEN\n        v_room_new_pay := v_room.payment_id;                                            -- C 동일 → 유지\n      ELSIF v_room.payment_id = p_payment_id AND p_payment_id <> v_sub.last_payment_id THEN\n        v_room_new_pay := v_sub.last_payment_id; v_room_dirty := true;                  -- stale → C 로 교체 후보\n      ELSE\n        INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)\n        VALUES (p_payment_id, v_sub.id, ''ROOM_REF_MISMATCH'', ''F12 replay: room.payment_id references third payment'',\n                jsonb_build_object(''payment_id_c'', v_sub.last_payment_id, ''payment_id_p'', p_payment_id),\n                jsonb_build_object(''payment_id'', v_room.payment_id))\n        RETURNING id INTO v_anom;\n        RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROOM_REF_MISMATCH'', ''anomaly_id'', v_anom);\n      END IF;\n    END IF;\n\n    -- ── Phase 2: 검증 전부 통과 후에만 room 확보·보정 (참조 복구 — 자금 반복 0) ──\n    BEGIN\n      IF NOT v_room_found THEN\n        v_roomres := core_private.ensure_student_mentor_room(\n                       v_sub.student_id, v_sub.mentor_id,\n                       p_payment_id => v_sub.last_payment_id,\n                       p_subscription_id => v_sub.id,\n                       p_require_entitlement => false);\n        IF NOT coalesce((v_roomres->>''ok'')::boolean, false) THEN\n          RAISE EXCEPTION ''S2_M9_ROOM_STEP_FAILED'';\n        END IF;\n        v_room_id := (v_roomres->>''room_id'')::uuid;\n        -- 동시 생성 경합 포함 재확인: NULL 참조만 채운다(F10 은 기존 방 참조를 덮어쓰지 않음)\n        UPDATE public.mentor_student_rooms r\n           SET subscription_id = coalesce(r.subscription_id, v_sub.id),\n               payment_id      = coalesce(r.payment_id, v_sub.last_payment_id)\n         WHERE r.id = v_room_id;\n      ELSE\n        v_room_id := v_room.id;\n        IF v_room_dirty THEN\n          UPDATE public.mentor_student_rooms r\n             SET subscription_id = v_room_new_sub,\n                 payment_id      = v_room_new_pay\n           WHERE r.id = v_room_id;\n        END IF;\n      END IF;\n    EXCEPTION WHEN OTHERS THEN\n      -- 운영 오류(9단계와 별도): 자금·원장·구독·결제 성공 상태는 건드리지 않고,\n      -- room 부분 변경은 이 블록에서 롤백되며, 재시도 가능하다(§7 F12 재생 결과)\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROOM_ENSURE_FAILED'');\n    END;\n\n    RETURN jsonb_build_object(''ok'', true, ''contract_version'', 1, ''idempotent'', true,\n                              ''subscription_id'', v_sub.id, ''payment_status'', ''succeeded'',\n                              ''room_id'', v_room_id);\n  END IF;\n\n  -- ── 최초 실행 경로 ──\n  -- 3) advisory (정본과 동일 인자 형식 — 전환기 잠금 순서 일치 [C3])\n  PERFORM pg_advisory_xact_lock(hashtext(p_rec.user_id::text), hashtext(p_rec.mentor_id::text));\n  -- 4) mentor_plans FOR UPDATE — 5)~6) 내내 유지되어 TOCTOU 차단(멘토 UPDATE 대기, T-CONC-04)\n  SELECT mp.amount_cents INTO v_plan_amount\n    FROM public.mentor_plans mp WHERE mp.id = p_plan_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_NOT_FOUND'');\n  END IF;\n  -- 5) 3자 일치: payments.amount×100 = p_expected_amount_cents = 잠근 amount_cents\n  IF v_intent <> p_expected_amount_cents OR v_intent <> v_plan_amount THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_AMOUNT_CHANGED'',\n                              ''expected_amount_cents'', p_expected_amount_cents,\n                              ''actual_amount_cents'', v_plan_amount);\n  END IF;\n  -- 6)~7) 정본 호출 + 방 확보 — 한 subtransaction: 방 확보 실패 시 자금·원장·구독·\n  --       결제 변경 전부 롤백(rev 8 A-2 §3). 정본 raise 는 잡아 동명 envelope 변환.\n  BEGIN\n    v_canon := public.confirm_subscription_checkout(p_payment_id, p_plan_id, p_idempotency_key);\n    IF NOT coalesce((v_canon->>''ok'')::boolean, false) THEN\n      -- 정본 envelope 실패(CASH_INSUFFICIENT·anomaly 계열): 금융 변경은 정본 내부에서\n      -- 이미 롤백됨 — anomaly 행만 유지한 채 그대로 승격 반환\n      RETURN v_canon || jsonb_build_object(''contract_version'', 1);\n    END IF;\n    v_sub_id := (v_canon->>''subscription_id'')::uuid;\n    v_roomres := core_private.ensure_student_mentor_room(\n                   p_rec.user_id, p_rec.mentor_id,\n                   p_payment_id => p_payment_id,\n                   p_subscription_id => v_sub_id,\n                   p_require_entitlement => false);\n    IF NOT coalesce((v_roomres->>''ok'')::boolean, false) THEN\n      RAISE EXCEPTION ''S2_M9_ROOM_STEP_FAILED'';\n    END IF;\n    v_room_id := (v_roomres->>''room_id'')::uuid;\n    -- room 참조 규칙(신규 결제 — §7 F12 표): pair 불변 · subscription_id NULL 이면\n    -- 채움/다른 값이면 거부 · payment_id 는 현재 결제로 갱신(최신 참조 의미론)\n    SELECT r.id, r.subscription_id, r.payment_id INTO v_room\n      FROM public.mentor_student_rooms r WHERE r.id = v_room_id FOR UPDATE;\n    IF v_room.subscription_id IS NOT NULL AND v_room.subscription_id <> v_sub_id THEN\n      RAISE EXCEPTION ''S2_M9_ROOM_REF_CONFLICT'';\n    END IF;\n    UPDATE public.mentor_student_rooms r\n       SET subscription_id = coalesce(r.subscription_id, v_sub_id),\n           payment_id      = p_payment_id\n     WHERE r.id = v_room_id;\n  EXCEPTION WHEN OTHERS THEN\n    IF sqlerrm LIKE ''%S2_M9_ROOM_REF_CONFLICT%'' THEN\n      -- 초기 경로 room 참조 충돌 = 거부(§7 F12 표) — 자금 변경은 위 블록에서 전부 롤백됨\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, v_sub_id, ''ROOM_REF_MISMATCH'', ''F12 initial: room.subscription_id conflict'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROOM_REF_MISMATCH'', ''anomaly_id'', v_anom);\n    ELSIF sqlerrm LIKE ''%S2_M9_ROOM_STEP_FAILED%'' THEN\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROOM_ENSURE_FAILED'');\n    ELSIF sqlerrm = ANY(v_canon_raises) THEN\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', sqlerrm);\n    ELSE\n      RAISE;  -- 사전 밖 예외는 그대로 전파(§8.2)\n    END IF;\n  END;\n\n  -- 8) 성공: 기존 정본 반환 + contract_version + room_id (§8.3 F12 행)\n  RETURN v_canon || jsonb_build_object(''contract_version'', 1, ''room_id'', v_room_id);\nEND $$;\n\nCOMMENT ON FUNCTION api_web_v1.subscription_checkout_confirm_v2(uuid, uuid, integer, text) IS\n  ''S2 M9 F12(계약 §7): 구독 checkout 확정 wrapper — 최초 실행은 정본 confirm_subscription_checkout + F10 방 확보(실패 시 전부 롤백), 재생은 Phase 1/2 자체 판정(9단계·불변 동의 금액). service_role 전용(T4a).'';\n\n-- -----------------------------------------------------------------------------\n-- F. 권한 — service_role 전용 진입점 + 내부 구현부 EXECUTE 0 (§10.3, 같은 마이그레이션)\n-- -----------------------------------------------------------------------------\nREVOKE ALL ON FUNCTION api_web_v1.record_cash_topup_v2(uuid, bigint, text) FROM PUBLIC;\nREVOKE ALL ON FUNCTION api_web_v1.subscription_checkout_confirm_v2(uuid, uuid, integer, text) FROM PUBLIC;\nGRANT EXECUTE ON FUNCTION api_web_v1.record_cash_topup_v2(uuid, bigint, text) TO service_role;\nGRANT EXECUTE ON FUNCTION api_web_v1.subscription_checkout_confirm_v2(uuid, uuid, integer, text) TO service_role;\n\n-- -----------------------------------------------------------------------------\n-- G. 적용 직후 자가 검증\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_oid oid;\nBEGIN\n  -- F11i: SECURITY INVOKER · search_path='''' · 외부 EXECUTE 전부 0\n  SELECT p.oid INTO v_oid\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''core_private'' AND p.proname = ''record_cash_topup_impl''\n     AND pg_get_function_identity_arguments(p.oid) = ''p_user_id uuid, p_amount_cents bigint, p_idempotency_key text''\n     AND NOT p.prosecdef AND p.proconfig::text LIKE ''%search_path=%'';\n  IF v_oid IS NULL THEN\n    RAISE EXCEPTION ''S2_M9_SELFCHECK: F11i identity/attributes mismatch'';\n  END IF;\n  IF has_function_privilege(''anon'', v_oid, ''EXECUTE'')\n     OR has_function_privilege(''authenticated'', v_oid, ''EXECUTE'')\n     OR has_function_privilege(''service_role'', v_oid, ''EXECUTE'') THEN\n    RAISE EXCEPTION ''S2_M9_SELFCHECK: F11i external EXECUTE must be 0'';\n  END IF;\n  -- F11·F12: SECDEF · search_path='''' · service_role 만 EXECUTE\n  FOR v_oid IN\n    SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n     WHERE n.nspname = ''api_web_v1'' AND p.proname IN (''record_cash_topup_v2'',''subscription_checkout_confirm_v2'')\n  LOOP\n    IF NOT (SELECT p.prosecdef AND p.proconfig::text LIKE ''%search_path=%'' FROM pg_proc p WHERE p.oid = v_oid) THEN\n      RAISE EXCEPTION ''S2_M9_SELFCHECK: F11/F12 attributes mismatch'';\n    END IF;\n    IF has_function_privilege(''anon'', v_oid, ''EXECUTE'')\n       OR has_function_privilege(''authenticated'', v_oid, ''EXECUTE'')\n       OR NOT has_function_privilege(''service_role'', v_oid, ''EXECUTE'') THEN\n      RAISE EXCEPTION ''S2_M9_SELFCHECK: F11/F12 must be service_role-only'';\n    END IF;\n  END LOOP;\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname = ''api_web_v1'' AND p.proname IN (''record_cash_topup_v2'',''subscription_checkout_confirm_v2'')) <> 2 THEN\n    RAISE EXCEPTION ''S2_M9_SELFCHECK: entrypoint census mismatch'';\n  END IF;\n  -- 2층 레거시: 시그니처·void·SECDEF·service_role 전용 불변 + impl 위임 확인\n  SELECT p.oid INTO v_oid\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''public'' AND p.proname = ''record_cash_topup''\n     AND pg_get_function_identity_arguments(p.oid) = ''p_user_id uuid, p_amount_cents bigint, p_idempotency_key text''\n     AND p.prorettype = ''void''::regtype AND p.prosecdef\n     AND p.prosrc LIKE ''%core_private.record_cash_topup_impl%'';\n  IF v_oid IS NULL THEN\n    RAISE EXCEPTION ''S2_M9_SELFCHECK: legacy record_cash_topup replacement mismatch'';\n  END IF;\n  IF has_function_privilege(''anon'', v_oid, ''EXECUTE'')\n     OR has_function_privilege(''authenticated'', v_oid, ''EXECUTE'')\n     OR NOT has_function_privilege(''service_role'', v_oid, ''EXECUTE'') THEN\n    RAISE EXCEPTION ''S2_M9_SELFCHECK: legacy record_cash_topup ACL must be unchanged (service_role only)'';\n  END IF;\n  -- census: api_web_v1 함수 14(M6 6 + M7 3 + M8 2 + M14 1 + M9 2) · core_private 6(F10+B4종+F11i)\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname = ''api_web_v1'') <> 14 THEN\n    RAISE EXCEPTION ''S2_M9_SELFCHECK: api_web_v1 function census must be 14'';\n  END IF;\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname = ''core_private'') <> 6 THEN\n    RAISE EXCEPTION ''S2_M9_SELFCHECK: core_private function census must be 6'';\n  END IF;\n  -- default privilege 방어: PUBLIC 에 EXECUTE 를 주는 defacl 행 부재(M1 실측 주석 참조)\n  IF EXISTS (SELECT 1 FROM pg_default_acl d JOIN pg_namespace n ON n.oid = d.defaclnamespace\n              WHERE n.nspname IN (''api_web_v1'',''core_private'') AND d.defaclacl::text LIKE ''%=X/%'') THEN\n    RAISE EXCEPTION ''S2_M9_SELFCHECK: unexpected PUBLIC-granting default acl'';\n  END IF;\nEND $$;\n\ncommit;\n"], "idempotency_key": null}, {"name": "20260730195147_revoke_mentor_profiles_write", "version": "20260731135324", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260730195147_revoke_mentor_profiles_write.sql (S2 M11)\n-- =============================================================================\n-- mentor_profiles 테이블 단위 권한 전면 회수 — XW-02 (가)·(나) 최종 잠금.\n-- 정본 계약: docs/contracts/api_web_v1_contract_v1_1.md §10.6 · §20.2 M11 ·\n--            §20.3 「M11 이전」 · §21 T-PERM-09·11·14 · §22 #6.\n--   - rev 8 A-3: 컬럼 단위 REVOKE는 테이블 단위 권한이 남아 있으면 실효가 없다\n--     (실측 확정) → 테이블 단위 REVOKE ALL + GRANT SELECT 로 교체.\n--   - SELECT 는 유지한다(공개 멘토 디렉터리·앱 SELECT 2곳 — §19.4-B 실측).\n--   - SECURITY DEFINER 경로(관리자 승인 RPC·가입 트리거 handle_new_auth_user·\n--     service_role 의도 경로)는 테이블 단위 REVOKE 의 영향을 받지 않는다(§5.3).\n-- 선행 게이트(§20.3 「M11 이전」 — 적용 세션에서 증명 완료):\n--   ① M8(F7 mentor_profile_update_self) 적용 + W2 C6 전환 완료\n--     (lib/mentor/mentorProfileMutations.ts·mentorSubscribeOpen.ts → F7 RPC)\n--   ② M14(F13 mentor_payout_account_update_self) 적용 + C11 전환 완료\n--     (lib/mentor/mentorPayoutAccountActions.ts → F13 RPC)\n--   ③ syncAfterSignUpWithSession 의 mentor_profiles 백업 upsert 제거 완료\n--     (lib/auth/syncAfterSignUpSession.ts — W2(C6) 주석 박제)\n--   ④ 웹 anon/authenticated 제품 경로의 mentor_profiles 직접 쓰기 0건 실측.\n--     service_role 의도 경로(회수 대상 아님 — 목록화):\n--       lib/mentor/mentorActivityService.ts (activity_status·pause 관리)\n--       lib/mentor/mentorStudentIdActions.ts (학생증 storedRef 반영)\n--       lib/auth/mentorSignupStudentIdAction.ts (가입 창구 학생증 반영)\n--       lib/admin/mentorAcademicRecordChangeReviewActions.ts (학적 변경 승인)\n--       + 관리자 승인 SECDEF RPC(approve_mentor_school_verification_admin)\n--   ⑤ 앱의 mentor_profiles 사용은 SELECT 2곳뿐(§19.4-B + 앱 Gate 4 감사\n--     docs/audit/S2_2_APP_TRANSITION_GATE4_20260730.md, commit 1c5d6c019).\n-- 사전 ACL 게이트: anon·authenticated 가 테이블 권한 7종(SELECT, INSERT, UPDATE,\n--   DELETE, TRUNCATE, REFERENCES, TRIGGER)을 전부 보유해야 한다(§10.6 실측 baseline).\n--   다른 ACL 이면 BATCH_F_M11_BASELINE_ACL_MISMATCH 로 중단한다(숨김 금지).\n--   * 로컬 검증 스택은 신규 클라우드 기본(auto-expose OFF)이라 fresh clean-install\n--     직후 write 권한이 없다 — 로컬 왕복 검증은 적용 전에 운영 baseline(7종)을\n--     재현한 뒤 실행한다(scripts/verify/s2_2_batch_f_verify.sql 러너 절차 참조).\n-- 금지: service_role·postgres 권한 변경 / RLS 정책 변경 / 테이블·컬럼·데이터 변경 /\n--       컬럼 단위 REVOKE 로 축소.\n-- rollback 정본: supabase/rollback/20260730195147_revoke_mentor_profiles_write_rollback.sql\n--   (§22 #6 — 비SELECT 6종·역할 2종 문자 그대로 대칭 복원. SELECT 는 forward 이후에도\n--    존재하므로 복원 대상이 아니다)\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- A. 사전 게이트 — 대상 실재 + baseline ACL 7종 실측 (읽기 전용)\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_role text;\n  v_priv text;\n  v_has  boolean;\nBEGIN\n  IF to_regclass(''public.mentor_profiles'') IS NULL THEN\n    RAISE EXCEPTION ''BATCH_F_M11_BASELINE_ACL_MISMATCH: public.mentor_profiles not found'';\n  END IF;\n  -- 선행 migration 실재(M8 F7 / M14 F13) — §20.2.1 M11 간선\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname = ''api_web_v1''\n         AND p.proname IN (''mentor_profile_update_self'', ''mentor_payout_account_update_self'')) <> 2 THEN\n    RAISE EXCEPTION ''BATCH_F_M11_BASELINE_ACL_MISMATCH: predecessor RPC (F7/F13) missing — M8/M14 not applied'';\n  END IF;\n  -- baseline ACL: anon·authenticated × 7종 전부 true 여야 한다(§10.6 실측 기준선).\n  FOR v_role, v_priv IN\n    SELECT r.rolname, p.priv\n      FROM (VALUES (''anon''), (''authenticated'')) AS r(rolname)\n     CROSS JOIN (VALUES (''SELECT''), (''INSERT''), (''UPDATE''), (''DELETE''),\n                        (''TRUNCATE''), (''REFERENCES''), (''TRIGGER'')) AS p(priv)\n  LOOP\n    v_has := has_table_privilege(v_role, ''public.mentor_profiles'', v_priv);\n    IF NOT v_has THEN\n      RAISE EXCEPTION\n        ''BATCH_F_M11_BASELINE_ACL_MISMATCH: expected % % on public.mentor_profiles = true, measured false'',\n        v_role, v_priv;\n    END IF;\n  END LOOP;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- B. 회수 정본 (§10.6 — 문자 그대로)\n-- -----------------------------------------------------------------------------\nREVOKE ALL ON public.mentor_profiles FROM anon, authenticated;\nGRANT SELECT ON public.mentor_profiles TO anon, authenticated;\n\n-- -----------------------------------------------------------------------------\n-- C. 적용 직후 게이트 — SELECT 만 true·비SELECT 전부 false·컬럼 단위 잔여 0\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_role text;\n  v_priv text;\n  v_has  boolean;\n  v_cnt  int;\nBEGIN\n  FOR v_role, v_priv IN\n    SELECT r.rolname, p.priv\n      FROM (VALUES (''anon''), (''authenticated'')) AS r(rolname)\n     CROSS JOIN (VALUES (''SELECT''), (''INSERT''), (''UPDATE''), (''DELETE''),\n                        (''TRUNCATE''), (''REFERENCES''), (''TRIGGER''), (''MAINTAIN'')) AS p(priv)\n  LOOP\n    v_has := has_table_privilege(v_role, ''public.mentor_profiles'', v_priv);\n    IF v_priv = ''SELECT'' AND NOT v_has THEN\n      RAISE EXCEPTION ''M11_POST_ACL_MISMATCH: % SELECT expected true, measured false'', v_role;\n    ELSIF v_priv <> ''SELECT'' AND v_has THEN\n      RAISE EXCEPTION ''M11_POST_ACL_MISMATCH: % % expected false, measured true'', v_role, v_priv;\n    END IF;\n  END LOOP;\n  -- 컬럼 단위 잔여 write privilege 0 (rev 8 A-3 — T-PERM-09 컬럼 단위 확인)\n  SELECT count(*) INTO v_cnt\n    FROM information_schema.column_privileges\n   WHERE table_schema = ''public'' AND table_name = ''mentor_profiles''\n     AND grantee IN (''anon'', ''authenticated'')\n     AND privilege_type <> ''SELECT'';\n  IF v_cnt <> 0 THEN\n    RAISE EXCEPTION ''M11_POST_ACL_MISMATCH: residual column-level write privileges = % (expected 0)'', v_cnt;\n  END IF;\n  -- 가입 트리거·관리자 승인 SECDEF 경로 실재(기능 동작 검증은 §21.10 로컬 검증기 소유)\n  IF NOT EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid\n                  JOIN pg_namespace n ON n.oid = c.relnamespace\n                 WHERE n.nspname = ''auth'' AND c.relname = ''users''\n                   AND NOT t.tgisinternal\n                   AND t.tgfoid = ''public.handle_new_auth_user''::regproc) THEN\n    RAISE EXCEPTION ''M11_POST_ACL_MISMATCH: signup trigger (handle_new_auth_user) missing'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''public''\n                    AND p.proname = ''approve_mentor_school_verification_admin''\n                    AND p.prosecdef) THEN\n    RAISE EXCEPTION ''M11_POST_ACL_MISMATCH: admin approval SECDEF RPC missing'';\n  END IF;\nEND $$;\n\ncommit;\n"], "idempotency_key": null}, {"name": "20260730195150_revoke_mentor_plans_write", "version": "20260731135445", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260730195150_revoke_mentor_plans_write.sql (S2 M12)\n-- =============================================================================\n-- mentor_plans 테이블 단위 권한 전면 회수 — XW-03 최종 잠금.\n-- 정본 계약: docs/contracts/api_web_v1_contract_v1_1.md §10.6 · §20.2 M12 ·\n--            §20.3 「M12 이전」 · §21 T-PERM-10 · §22 #6.\n--   - SELECT 는 유지한다(공개 플랜 조회·구독 화면 가격 표시 — §10.6).\n--   - DELETE 까지 회수해 authenticated 가 자기 플랜 행을 직접 지워\n--     confirm_subscription_checkout / F12 를 PLAN_NOT_FOUND 로 실패시키는 경로를\n--     원천 차단한다(T-PERM-10 명시 근거).\n-- 선행 게이트(§20.3 「M12 이전」 — 적용 세션에서 증명 완료):\n--   ① M8(F8 mentor_plan_prices_set_self) 적용 + W2 C6 전환 완료\n--     (lib/mentor/mentorProfileMutations.ts → F8 RPC, 클라 선판정 제거)\n--   ② 웹 anon/authenticated 제품 경로의 mentor_plans 직접 쓰기 0건 실측.\n--     service_role 의도 경로(회수 대상 아님 — 목록화):\n--       lib/subscribe/subscribeCheckoutService.ts:397 (권장가 seed INSERT — admin)\n--       lib/mentor/mentorActivityService.ts:91·95 (is_active 토글 — admin)\n--   ③ 앱의 mentor_plans 사용은 SELECT 뿐(§19.4-B + 앱 Gate 4 감사, commit 1c5d6c019).\n-- 사전 ACL 게이트: anon·authenticated 가 테이블 권한 7종을 전부 보유해야 한다\n--   (§10.6 실측 baseline). 다르면 BATCH_F_M12_BASELINE_ACL_MISMATCH 로 중단.\n--   * 로컬 fresh clean-install 은 auto-expose OFF 라 write 권한이 없다 — 로컬 왕복\n--     검증은 운영 baseline(7종) 재현 후 실행한다(M11 헤더와 동일 절차).\n-- 금지: service_role·postgres 권한 변경 / RLS 정책 변경 / 테이블·컬럼·데이터 변경 /\n--       컬럼 단위 REVOKE 로 축소.\n-- rollback 정본: supabase/rollback/20260730195150_revoke_mentor_plans_write_rollback.sql\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- A. 사전 게이트 — 대상 실재 + baseline ACL 7종 실측 (읽기 전용)\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_role text;\n  v_priv text;\nBEGIN\n  IF to_regclass(''public.mentor_plans'') IS NULL THEN\n    RAISE EXCEPTION ''BATCH_F_M12_BASELINE_ACL_MISMATCH: public.mentor_plans not found'';\n  END IF;\n  -- 선행 migration 실재(M8 F8) — §20.2.1 M12 간선\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''api_web_v1'' AND p.proname = ''mentor_plan_prices_set_self'') THEN\n    RAISE EXCEPTION ''BATCH_F_M12_BASELINE_ACL_MISMATCH: predecessor RPC (F8) missing — M8 not applied'';\n  END IF;\n  FOR v_role, v_priv IN\n    SELECT r.rolname, p.priv\n      FROM (VALUES (''anon''), (''authenticated'')) AS r(rolname)\n     CROSS JOIN (VALUES (''SELECT''), (''INSERT''), (''UPDATE''), (''DELETE''),\n                        (''TRUNCATE''), (''REFERENCES''), (''TRIGGER'')) AS p(priv)\n  LOOP\n    IF NOT has_table_privilege(v_role, ''public.mentor_plans'', v_priv) THEN\n      RAISE EXCEPTION\n        ''BATCH_F_M12_BASELINE_ACL_MISMATCH: expected % % on public.mentor_plans = true, measured false'',\n        v_role, v_priv;\n    END IF;\n  END LOOP;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- B. 회수 정본 (§10.6 — 문자 그대로)\n-- -----------------------------------------------------------------------------\nREVOKE ALL ON public.mentor_plans FROM anon, authenticated;\nGRANT SELECT ON public.mentor_plans TO anon, authenticated;\n\n-- -----------------------------------------------------------------------------\n-- C. 적용 직후 게이트 — SELECT 만 true·비SELECT 전부 false·컬럼 단위 잔여 0\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_role text;\n  v_priv text;\n  v_has  boolean;\n  v_cnt  int;\nBEGIN\n  FOR v_role, v_priv IN\n    SELECT r.rolname, p.priv\n      FROM (VALUES (''anon''), (''authenticated'')) AS r(rolname)\n     CROSS JOIN (VALUES (''SELECT''), (''INSERT''), (''UPDATE''), (''DELETE''),\n                        (''TRUNCATE''), (''REFERENCES''), (''TRIGGER''), (''MAINTAIN'')) AS p(priv)\n  LOOP\n    v_has := has_table_privilege(v_role, ''public.mentor_plans'', v_priv);\n    IF v_priv = ''SELECT'' AND NOT v_has THEN\n      RAISE EXCEPTION ''M12_POST_ACL_MISMATCH: % SELECT expected true, measured false'', v_role;\n    ELSIF v_priv <> ''SELECT'' AND v_has THEN\n      RAISE EXCEPTION ''M12_POST_ACL_MISMATCH: % % expected false, measured true'', v_role, v_priv;\n    END IF;\n  END LOOP;\n  SELECT count(*) INTO v_cnt\n    FROM information_schema.column_privileges\n   WHERE table_schema = ''public'' AND table_name = ''mentor_plans''\n     AND grantee IN (''anon'', ''authenticated'')\n     AND privilege_type <> ''SELECT'';\n  IF v_cnt <> 0 THEN\n    RAISE EXCEPTION ''M12_POST_ACL_MISMATCH: residual column-level write privileges = % (expected 0)'', v_cnt;\n  END IF;\n  -- F12 플랜 조회·확정 경로 실재(기능 동작 검증은 §21.10 로컬 검증기 소유)\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''api_web_v1'' AND p.proname = ''subscription_checkout_confirm_v2'') THEN\n    RAISE EXCEPTION ''M12_POST_ACL_MISMATCH: F12 subscription_checkout_confirm_v2 missing'';\n  END IF;\nEND $$;\n\ncommit;\n"], "idempotency_key": null}, {"name": "community_direct_write_lockdown", "version": "20260731170632", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["begin;\ncreate temporary table m16_pre_state on commit drop as\nselect p.priv, has_table_privilege(''service_role'',''public.community_posts'',p.priv) as has\nfrom (values (''SELECT''),(''INSERT''),(''UPDATE''),(''DELETE''),(''TRUNCATE''),(''REFERENCES''),(''TRIGGER''),(''MAINTAIN'')) p(priv);\ncreate temporary table m16_pre_select_policies on commit drop as\nselect policyname from pg_policies where schemaname=''public'' and tablename=''community_posts'' and cmd=''SELECT'';\ndo $$\ndeclare v_role text; v_priv text; v_cnt int;\nbegin\nif to_regclass(''public.community_posts'') is null then raise exception ''BATCH_F_M16_POLICY_BASELINE_MISMATCH: public.community_posts not found''; end if;\nif not (select relrowsecurity from pg_class where oid=''public.community_posts''::regclass) then raise exception ''BATCH_F_M16_POLICY_BASELINE_MISMATCH: RLS not enabled on community_posts''; end if;\nif (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname=''api_web_v1'' and p.proname in (''community_post_create'',''community_post_update'',''community_post_soft_delete''))<>3\nor (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname=''api_app_v1'' and p.proname in (''community_post_create'',''community_post_update'',''community_post_soft_delete''))<>3\nthen raise exception ''BATCH_F_M16_POLICY_BASELINE_MISMATCH: F4/F5/F6 wrappers (M7/M17) missing''; end if;\nselect count(*) into v_cnt from pg_policies where schemaname=''public'' and tablename=''community_posts'' and cmd in (''INSERT'',''UPDATE'',''DELETE'');\nif v_cnt<>6 then raise exception ''BATCH_F_M16_POLICY_BASELINE_MISMATCH: write policies expected 6, measured %'',v_cnt; end if;\nselect count(*) into v_cnt from pg_policies where schemaname=''public'' and tablename=''community_posts'' and ((policyname=''cp_write_self'' and cmd=''INSERT'' and roles=''{authenticated}'') or (policyname=''로그인 유저 게시글 작성'' and cmd=''INSERT'' and roles=''{public}'') or (policyname=''cp_update_own'' and cmd=''UPDATE'' and roles=''{authenticated}'') or (policyname=''cp_update_self'' and cmd=''UPDATE'' and roles=''{authenticated}'') or (policyname=''본인 게시글 수정'' and cmd=''UPDATE'' and roles=''{public}'') or (policyname=''cp_delete_own'' and cmd=''DELETE'' and roles=''{authenticated}''));\nif v_cnt<>6 then raise exception ''BATCH_F_M16_POLICY_BASELINE_MISMATCH: write policy identity set mismatch (matched %/6)'',v_cnt; end if;\nif (select count(*) from pg_policies where schemaname=''public'' and tablename=''community_posts'' and cmd=''SELECT'' and policyname in (''cp_select_own'',''cp_select_published''))<>2 then raise exception ''BATCH_F_M16_POLICY_BASELINE_MISMATCH: cp_select_own/cp_select_published missing''; end if;\nfor v_role,v_priv in select r.rolname,p.priv from (values (''anon''),(''authenticated'')) r(rolname) cross join (values (''SELECT''),(''INSERT''),(''UPDATE''),(''DELETE''),(''TRUNCATE''),(''REFERENCES''),(''TRIGGER'')) p(priv)\nloop if not has_table_privilege(v_role,''public.community_posts'',v_priv) then raise exception ''BATCH_F_M16_POLICY_BASELINE_MISMATCH: expected % % on public.community_posts = true, measured false'',v_role,v_priv; end if; end loop;\nend $$;\nrevoke all on public.community_posts from anon, authenticated;\ngrant select on public.community_posts to anon, authenticated;\ndrop policy \"cp_write_self\" on public.community_posts;\ndrop policy \"로그인 유저 게시글 작성\" on public.community_posts;\ndrop policy \"cp_update_own\" on public.community_posts;\ndrop policy \"cp_update_self\" on public.community_posts;\ndrop policy \"본인 게시글 수정\" on public.community_posts;\ndrop policy \"cp_delete_own\" on public.community_posts;\ndo $$\ndeclare v_role text; v_priv text; v_has boolean; v_cnt int;\nbegin\nfor v_role,v_priv in select r.rolname,p.priv from (values (''anon''),(''authenticated'')) r(rolname) cross join (values (''SELECT''),(''INSERT''),(''UPDATE''),(''DELETE''),(''TRUNCATE''),(''REFERENCES''),(''TRIGGER''),(''MAINTAIN'')) p(priv)\nloop v_has:=has_table_privilege(v_role,''public.community_posts'',v_priv); if v_priv=''SELECT'' and not v_has then raise exception ''M16_POST_MISMATCH: % SELECT expected true, measured false'',v_role; elsif v_priv<>''SELECT'' and v_has then raise exception ''M16_POST_MISMATCH: % % expected false, measured true'',v_role,v_priv; end if; end loop;\nselect count(*) into v_cnt from pg_policies where schemaname=''public'' and tablename=''community_posts'' and cmd in (''INSERT'',''UPDATE'',''DELETE''); if v_cnt<>0 then raise exception ''M16_POST_MISMATCH: write policies expected 0, measured %'',v_cnt; end if;\nif exists (select policyname from m16_pre_select_policies except select policyname from pg_policies where schemaname=''public'' and tablename=''community_posts'' and cmd=''SELECT'') or exists (select policyname from pg_policies where schemaname=''public'' and tablename=''community_posts'' and cmd=''SELECT'' except select policyname from m16_pre_select_policies) then raise exception ''M16_POST_MISMATCH: SELECT policy set changed''; end if;\nselect count(*) into v_cnt from m16_pre_state s where s.has is distinct from has_table_privilege(''service_role'',''public.community_posts'',s.priv); if v_cnt<>0 then raise exception ''M16_POST_MISMATCH: service_role privilege drift = % entries'',v_cnt; end if;\nend $$;\ncommit;"], "idempotency_key": null}, {"name": "contract_permission_assertions", "version": "20260731170758", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["begin;\nDO $$\nDECLARE v_role text; v_cnt int;\nBEGIN\n  FOREACH v_role IN ARRAY ARRAY[''api_web_v1'',''api_app_v1'',''core_private''] LOOP\n    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = v_role) THEN RAISE EXCEPTION ''M10_A_SCHEMA: schema % expected present, measured absent'', v_role; END IF;\n  END LOOP;\n  FOREACH v_role IN ARRAY ARRAY[''anon'',''authenticated'',''service_role''] LOOP\n    IF has_schema_privilege(v_role, ''core_private'', ''USAGE'') THEN RAISE EXCEPTION ''M10_A_SCHEMA: core_private USAGE for % expected false, measured true'', v_role; END IF;\n  END LOOP;\n  SELECT count(*) INTO v_cnt FROM pg_namespace n, aclexplode(coalesce(n.nspacl, ''{}''::aclitem[])) a WHERE n.nspname IN (''api_web_v1'',''api_app_v1'',''core_private'') AND a.grantee = 0;\n  IF v_cnt <> 0 THEN RAISE EXCEPTION ''M10_A_SCHEMA: PUBLIC schema acl entries expected 0, measured %'', v_cnt; END IF;\nEND $$;\nDO $$\nDECLARE v_cnt int; r record;\nBEGIN\n  SELECT count(*) INTO v_cnt FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = ''api_web_v1'';\n  IF v_cnt <> 5 THEN RAISE EXCEPTION ''M10_B_WEB: api_web_v1 pg_class census expected 5, measured %'', v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = ''api_web_v1'' AND c.relkind = ''v'' AND c.relname IN (''community_posts_v1'',''community_comments_v1'',''mentor_directory_v1'',''my_wallet_v1'',''my_cash_ledger_v1'');\n  IF v_cnt <> 5 THEN RAISE EXCEPTION ''M10_B_WEB: V1~V5 identity set expected 5, measured %'', v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = ''api_web_v1'' AND c.relkind = ''v'' AND ((c.relname = ''mentor_directory_v1'' AND ''security_invoker=false'' = ANY (coalesce(c.reloptions, ''{}''))) OR (c.relname <> ''mentor_directory_v1'' AND ''security_invoker=true'' = ANY (coalesce(c.reloptions, ''{}''))));\n  IF v_cnt <> 5 THEN RAISE EXCEPTION ''M10_B_WEB: security_invoker matrix expected 5 conforming, measured %'', v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = ''api_web_v1'';\n  IF v_cnt <> 14 THEN RAISE EXCEPTION ''M10_B_WEB: function census expected 14, measured %'', v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = ''api_web_v1'' AND (p.proname, pg_get_function_identity_arguments(p.oid)) IN ((''my_subscriptions_self'',''''),(''mentor_settlement_self'',''''),(''account_deletion_status_self'',''''),(''weekly_question_usage_self'',''p_mentor_id uuid''),(''ensure_free_question_room'',''p_mentor_id uuid''),(''qna_create_question_thread'',''p_room_id uuid, p_title text, p_subject text, p_topic text, p_first_message_body text''),(''community_post_create'',''p_title text, p_body text, p_category text, p_idempotency_key uuid, p_image_refs text[], p_status text''),(''community_post_update'',''p_post_id uuid, p_title text, p_body text, p_category text, p_expected_updated_at timestamp with time zone, p_image_refs text[], p_status text''),(''community_post_soft_delete'',''p_post_id uuid''),(''mentor_profile_update_self'',''p_university_name text, p_department_name text, p_high_school_name text, p_teaching_subjects text[], p_intro_line text, p_bio text, p_answer_style text, p_profile_image_url text, p_is_open_for_subscriptions boolean''),(''mentor_plan_prices_set_self'',''p_limited_cash_krw integer, p_standard_cash_krw integer, p_premium_cash_krw integer''),(''mentor_payout_account_update_self'',''p_bank_name text, p_account_number text''),(''record_cash_topup_v2'',''p_user_id uuid, p_amount_cents bigint, p_order_ref text''),(''subscription_checkout_confirm_v2'',''p_payment_id uuid, p_plan_id uuid, p_expected_amount_cents integer, p_idempotency_key text''));\n  IF v_cnt <> 14 THEN RAISE EXCEPTION ''M10_B_WEB: identity argument set expected 14, measured %'', v_cnt; END IF;\n  FOR r IN SELECT p.oid,p.proname,p.prosecdef,p.proconfig,p.proacl,pg_get_userbyid(p.proowner) AS owner FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''api_web_v1'' LOOP\n    IF NOT r.prosecdef THEN RAISE EXCEPTION ''M10_B_WEB: % prosecdef expected true, measured false'', r.proname; END IF;\n    IF NOT (coalesce(r.proconfig,''{}'') @> ARRAY[''search_path=\"\"'']) THEN RAISE EXCEPTION ''M10_B_WEB: % proconfig expected pinned empty search_path, measured %'', r.proname,r.proconfig; END IF;\n    IF r.owner <> ''postgres'' THEN RAISE EXCEPTION ''M10_B_WEB: % owner expected postgres, measured %'', r.proname,r.owner; END IF;\n    IF r.proacl IS NULL THEN RAISE EXCEPTION ''M10_B_WEB: % proacl NULL(기본 PUBLIC EXECUTE) — expected explicit acl'', r.proname; END IF;\n    IF EXISTS (SELECT 1 FROM aclexplode(r.proacl) a WHERE a.grantee=0) THEN RAISE EXCEPTION ''M10_B_WEB: % PUBLIC EXECUTE expected 0, measured present'', r.proname; END IF;\n  END LOOP;\n  SELECT count(*) INTO v_cnt FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''api_web_v1'' AND p.proname NOT IN (''record_cash_topup_v2'',''subscription_checkout_confirm_v2'') AND NOT has_function_privilege(''anon'',p.oid,''EXECUTE'') AND has_function_privilege(''authenticated'',p.oid,''EXECUTE'') AND has_function_privilege(''service_role'',p.oid,''EXECUTE'');\n  IF v_cnt <> 12 THEN RAISE EXCEPTION ''M10_B_WEB: T2 EXECUTE matrix expected 12 conforming, measured %'',v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''api_web_v1'' AND p.proname IN (''record_cash_topup_v2'',''subscription_checkout_confirm_v2'') AND NOT has_function_privilege(''anon'',p.oid,''EXECUTE'') AND NOT has_function_privilege(''authenticated'',p.oid,''EXECUTE'') AND has_function_privilege(''service_role'',p.oid,''EXECUTE'');\n  IF v_cnt <> 2 THEN RAISE EXCEPTION ''M10_B_WEB: F11/F12 EXECUTE matrix expected 2 conforming, measured %'',v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=''api_web_v1'' AND c.relkind=''v'' AND CASE WHEN c.relname IN (''my_wallet_v1'',''my_cash_ledger_v1'') THEN NOT has_table_privilege(''anon'',c.oid,''SELECT'') ELSE has_table_privilege(''anon'',c.oid,''SELECT'') END AND has_table_privilege(''authenticated'',c.oid,''SELECT'') AND has_table_privilege(''service_role'',c.oid,''SELECT'');\n  IF v_cnt <> 5 THEN RAISE EXCEPTION ''M10_B_WEB: view SELECT matrix expected 5 conforming, measured %'',v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN (VALUES (''anon''),(''authenticated''),(''service_role'')) rl(rolname) CROSS JOIN (VALUES (''INSERT''),(''UPDATE''),(''DELETE'')) pv(priv) WHERE n.nspname=''api_web_v1'' AND c.relkind=''v'' AND has_table_privilege(rl.rolname,c.oid,pv.priv);\n  IF v_cnt <> 0 THEN RAISE EXCEPTION ''M10_B_WEB: view DML privileges expected 0, measured %'',v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace, aclexplode(coalesce(c.relacl,''{}''::aclitem[])) a WHERE n.nspname=''api_web_v1'' AND a.grantee=0;\n  IF v_cnt <> 0 THEN RAISE EXCEPTION ''M10_B_WEB: PUBLIC view acl entries expected 0, measured %'',v_cnt; END IF;\nEND $$;\nDO $$\nDECLARE v_cnt int; r record;\nBEGIN\n  SELECT count(*) INTO v_cnt FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''core_private'';\n  IF v_cnt <> 6 THEN RAISE EXCEPTION ''M10_C_PRIV: function census expected 6, measured %'',v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''core_private'' AND (p.proname,pg_get_function_identity_arguments(p.oid)) IN ((''ensure_student_mentor_room'',''p_student_id uuid, p_mentor_id uuid, p_payment_id uuid, p_subscription_id uuid, p_require_entitlement boolean''),(''record_cash_topup_impl'',''p_user_id uuid, p_amount_cents bigint, p_idempotency_key text''),(''community_post_create_impl'',''p_author_id uuid, p_title text, p_body text, p_category text, p_image_refs text[], p_status text, p_idempotency_key uuid''),(''community_post_update_impl'',''p_author_id uuid, p_post_id uuid, p_title text, p_body text, p_category text, p_image_refs text[], p_status text, p_expected_updated_at timestamp with time zone''),(''community_post_soft_delete_impl'',''p_author_id uuid, p_post_id uuid''),(''community_image_refs_validate'',''p_owner_id uuid, p_image_refs text[]''));\n  IF v_cnt <> 6 THEN RAISE EXCEPTION ''M10_C_PRIV: identity argument set expected 6, measured %'',v_cnt; END IF;\n  FOR r IN SELECT p.oid,p.proname,p.proacl FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''core_private'' LOOP\n    IF has_function_privilege(''anon'',r.oid,''EXECUTE'') OR has_function_privilege(''authenticated'',r.oid,''EXECUTE'') OR has_function_privilege(''service_role'',r.oid,''EXECUTE'') THEN RAISE EXCEPTION ''M10_C_PRIV: % external EXECUTE expected all false, measured true'',r.proname; END IF;\n    IF r.proacl IS NULL OR EXISTS (SELECT 1 FROM aclexplode(r.proacl) a WHERE a.grantee=0) THEN RAISE EXCEPTION ''M10_C_PRIV: % PUBLIC EXECUTE expected 0, measured NULL-or-present'',r.proname; END IF;\n  END LOOP;\n  SELECT count(*) INTO v_cnt FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=''core_private'';\n  IF v_cnt <> 0 THEN RAISE EXCEPTION ''M10_C_PRIV: pg_class census expected 0, measured %'',v_cnt; END IF;\nEND $$;\nDO $$\nDECLARE v_cnt int; r record;\nBEGIN\n  SELECT count(*) INTO v_cnt FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=''api_app_v1'';\n  IF v_cnt<>1 OR NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=''api_app_v1'' AND c.relkind=''v'' AND c.relname=''community_posts_v1'' AND ''security_invoker=true''=ANY(coalesce(c.reloptions,''{}''))) THEN RAISE EXCEPTION ''M10_D_APP: relation census expected exactly community_posts_v1(invoker), measured %'',v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''api_app_v1''; IF v_cnt<>5 THEN RAISE EXCEPTION ''M10_D_APP: wrapper census expected 5, measured %'',v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''api_app_v1'' AND (p.proname,pg_get_function_identity_arguments(p.oid)) IN ((''ensure_free_question_room'',''p_mentor_id uuid''),(''qna_create_question_thread'',''p_room_id uuid, p_title text, p_subject text, p_topic text, p_first_message_body text''),(''community_post_create'',''p_title text, p_body text, p_category text, p_idempotency_key uuid, p_image_refs text[], p_status text''),(''community_post_update'',''p_post_id uuid, p_title text, p_body text, p_category text, p_expected_updated_at timestamp with time zone, p_image_refs text[], p_status text''),(''community_post_soft_delete'',''p_post_id uuid''));\n  IF v_cnt<>5 THEN RAISE EXCEPTION ''M10_D_APP: wrapper identity argument set expected 5, measured %'',v_cnt; END IF;\n  IF NOT has_schema_privilege(''authenticated'',''api_app_v1'',''USAGE'') OR has_schema_privilege(''anon'',''api_app_v1'',''USAGE'') OR has_schema_privilege(''service_role'',''api_app_v1'',''USAGE'') THEN RAISE EXCEPTION ''M10_D_APP: schema USAGE matrix mismatch (expected authenticated only)''; END IF;\n  IF NOT has_table_privilege(''authenticated'',''api_app_v1.community_posts_v1'',''SELECT'') OR has_table_privilege(''anon'',''api_app_v1.community_posts_v1'',''SELECT'') OR has_table_privilege(''service_role'',''api_app_v1.community_posts_v1'',''SELECT'') THEN RAISE EXCEPTION ''M10_D_APP: view SELECT matrix mismatch (expected authenticated only)''; END IF;\n  SELECT count(*) INTO v_cnt FROM (VALUES (''anon''),(''authenticated''),(''service_role'')) rl(rolname) CROSS JOIN (VALUES (''INSERT''),(''UPDATE''),(''DELETE'')) pv(priv) WHERE has_table_privilege(rl.rolname,''api_app_v1.community_posts_v1'',pv.priv);\n  IF v_cnt<>0 THEN RAISE EXCEPTION ''M10_D_APP: view DML privileges expected 0, measured %'',v_cnt; END IF;\n  FOR r IN SELECT p.oid,p.proname,p.proacl FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''api_app_v1'' LOOP\n    IF NOT has_function_privilege(''authenticated'',r.oid,''EXECUTE'') OR has_function_privilege(''anon'',r.oid,''EXECUTE'') OR has_function_privilege(''service_role'',r.oid,''EXECUTE'') THEN RAISE EXCEPTION ''M10_D_APP: % EXECUTE matrix mismatch (expected authenticated only)'',r.proname; END IF;\n    IF r.proacl IS NULL OR EXISTS (SELECT 1 FROM aclexplode(r.proacl) a WHERE a.grantee=0) THEN RAISE EXCEPTION ''M10_D_APP: % PUBLIC EXECUTE expected 0, measured NULL-or-present'',r.proname; END IF;\n  END LOOP;\nEND $$;\nDO $$\nDECLARE v_views int; v_fns int; v_schemas int; v_cnt int;\nBEGIN\n  SELECT count(*) INTO v_views FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN (''api_web_v1'',''api_app_v1'') AND c.relkind=''v'';\n  SELECT count(*) INTO v_fns FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN (''api_web_v1'',''core_private'',''api_app_v1'');\n  SELECT count(*) INTO v_schemas FROM pg_namespace WHERE nspname IN (''api_web_v1'',''api_app_v1'',''core_private'');\n  IF v_views<>6 OR v_fns<>25 OR v_schemas<>3 THEN RAISE EXCEPTION ''M10_E_TOTAL: expected view 6/function 25/schema 3, measured %/%/%'',v_views,v_fns,v_schemas; END IF;\n  SELECT count(*) INTO v_cnt FROM information_schema.columns WHERE table_schema=''public'' AND table_name=''comments'' AND column_name=''author_role'' AND data_type=''text'' AND is_nullable=''YES'';\n  IF v_cnt<>1 THEN RAISE EXCEPTION ''M10_E_TOTAL: comments.author_role expected text NULL x1, measured %'',v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN (''api_web_v1'',''core_private'',''api_app_v1'',''public'') AND p.proname IN (''user_display_label'',''user_display_role'');\n  IF v_cnt<>0 THEN RAISE EXCEPTION ''M10_E_TOTAL: F0 label functions expected absent, measured %'',v_cnt; END IF;\nEND $$;\nDO $$\nDECLARE v_cnt int;\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''public'' AND p.proname=''enforce_mentor_profile_privileged_guard'' AND p.prosecdef AND coalesce(p.proconfig,''{}'') @> ARRAY[''search_path=\"\"'']) THEN RAISE EXCEPTION ''M10_F_LEGACY: M0 guard function expected present(SECDEF, pinned), measured absent''; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_trigger t WHERE t.tgrelid=''public.mentor_profiles''::regclass AND NOT t.tgisinternal AND t.tgname IN (''trg_mentor_profile_privileged_guard_ins'',''trg_mentor_profile_privileged_guard_upd''); IF v_cnt<>2 THEN RAISE EXCEPTION ''M10_F_LEGACY: M0 guard triggers expected 2, measured %'',v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''public'' AND p.proname IN (''comments_set_author_label'',''community_comments_set_author_label'') AND p.prosecdef AND coalesce(p.proconfig,''{}'') @> ARRAY[''search_path=\"\"''] AND p.proacl IS NOT NULL AND NOT EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee=0); IF v_cnt<>2 THEN RAISE EXCEPTION ''M10_F_LEGACY: M13 trigger functions expected 2 conforming, measured %'',v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_trigger t WHERE NOT t.tgisinternal AND t.tgname IN (''trg_comments_set_author_label_ins'',''trg_comments_set_author_label_upd'',''trg_community_comments_set_author_label_ins'',''trg_community_comments_set_author_label_upd''); IF v_cnt<>4 THEN RAISE EXCEPTION ''M10_F_LEGACY: M13 triggers expected 4, measured %'',v_cnt; END IF;\n  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=''public'' AND table_name=''comments'' AND column_name=''author_label'' AND is_nullable=''NO'' AND column_default LIKE ''%쌤버십 사용자%'') THEN RAISE EXCEPTION ''M10_F_LEGACY: comments.author_label default expected 쌤버십 사용자, measured otherwise''; END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''public'' AND p.proname=''get_weekly_question_usage'' AND position(''[S2 M15]'' in p.prosrc)>0) THEN RAISE EXCEPTION ''M10_F_LEGACY: M15 pair-party guard marker expected present, measured absent''; END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''public'' AND p.proname=''record_cash_topup'' AND position(''core_private.record_cash_topup_impl'' in p.prosrc)>0) THEN RAISE EXCEPTION ''M10_F_LEGACY: M9 record_cash_topup delegation marker expected present, measured absent''; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''public'' AND p.proname IN (''weekly_question_usage_self'',''ensure_free_question_room'',''community_post_create'',''community_post_update'',''community_post_soft_delete'',''mentor_profile_update_self'',''mentor_plan_prices_set_self'',''mentor_payout_account_update_self'',''my_subscriptions_self'',''mentor_settlement_self'',''record_cash_topup_v2'',''subscription_checkout_confirm_v2'',''ensure_student_mentor_room'',''record_cash_topup_impl'',''community_post_create_impl'',''community_post_update_impl'',''community_post_soft_delete_impl'',''community_image_refs_validate''); IF v_cnt<>0 THEN RAISE EXCEPTION ''M10_F_LEGACY: S2 function names in public expected 0, measured %'',v_cnt; END IF;\nEND $$;\nDO $$\nDECLARE v_tbl text; v_role text; v_priv text; v_has boolean; v_cnt int;\nBEGIN\n  FOREACH v_tbl IN ARRAY ARRAY[''mentor_profiles'',''mentor_plans''] LOOP\n    FOR v_role,v_priv IN SELECT r.rolname,p.priv FROM (VALUES (''anon''),(''authenticated'')) r(rolname) CROSS JOIN (VALUES (''SELECT''),(''INSERT''),(''UPDATE''),(''DELETE''),(''TRUNCATE''),(''REFERENCES''),(''TRIGGER''),(''MAINTAIN'')) p(priv) LOOP\n      v_has:=has_table_privilege(v_role,format(''public.%I'',v_tbl),v_priv);\n      IF v_priv=''SELECT'' AND NOT v_has THEN RAISE EXCEPTION ''M10_GH_REVOKE: %.% SELECT expected true, measured false'',v_tbl,v_role; ELSIF v_priv<>''SELECT'' AND v_has THEN RAISE EXCEPTION ''M10_GH_REVOKE: %.% % expected false, measured true'',v_tbl,v_role,v_priv; END IF;\n    END LOOP;\n    SELECT count(*) INTO v_cnt FROM information_schema.column_privileges WHERE table_schema=''public'' AND table_name=v_tbl AND grantee IN (''anon'',''authenticated'') AND privilege_type<>''SELECT''; IF v_cnt<>0 THEN RAISE EXCEPTION ''M10_GH_REVOKE: % residual column write privileges expected 0, measured %'',v_tbl,v_cnt; END IF;\n  END LOOP;\nEND $$;\nDO $$\nDECLARE v_role text; v_priv text; v_has boolean; v_cnt int;\nBEGIN\n  FOR v_role,v_priv IN SELECT r.rolname,p.priv FROM (VALUES (''anon''),(''authenticated'')) r(rolname) CROSS JOIN (VALUES (''SELECT''),(''INSERT''),(''UPDATE''),(''DELETE''),(''TRUNCATE''),(''REFERENCES''),(''TRIGGER''),(''MAINTAIN'')) p(priv) LOOP\n    v_has:=has_table_privilege(v_role,''public.community_posts'',v_priv);\n    IF v_priv=''SELECT'' AND NOT v_has THEN RAISE EXCEPTION ''M10_I_HD1: community_posts % SELECT expected true, measured false'',v_role; ELSIF v_priv<>''SELECT'' AND v_has THEN RAISE EXCEPTION ''M10_I_HD1: community_posts % % expected false, measured true'',v_role,v_priv; END IF;\n  END LOOP;\n  SELECT count(*) INTO v_cnt FROM pg_policies WHERE schemaname=''public'' AND tablename=''community_posts'' AND cmd IN (''INSERT'',''UPDATE'',''DELETE''); IF v_cnt<>0 THEN RAISE EXCEPTION ''M10_I_HD1: write policies expected 0, measured %'',v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_policies WHERE schemaname=''public'' AND tablename=''community_posts'' AND policyname IN (''cp_write_self'',''로그인 유저 게시글 작성'',''cp_update_own'',''cp_update_self'',''본인 게시글 수정'',''cp_delete_own''); IF v_cnt<>0 THEN RAISE EXCEPTION ''M10_I_HD1: dropped policy names expected absent, measured %'',v_cnt; END IF;\n  IF (SELECT count(*) FROM pg_policies WHERE schemaname=''public'' AND tablename=''community_posts'' AND cmd=''SELECT'' AND policyname IN (''cp_select_own'',''cp_select_published''))<>2 THEN RAISE EXCEPTION ''M10_I_HD1: SELECT policies cp_select_own/cp_select_published expected present''; END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_class c, aclexplode(coalesce(c.relacl,''{}''::aclitem[])) a WHERE c.oid=''public.community_posts''::regclass AND a.grantee=''service_role''::regrole) THEN RAISE EXCEPTION ''M10_I_HD1: service_role acl entry expected present, measured absent''; END IF;\nEND $$;\nDO $$\nDECLARE v_cnt int;\nBEGIN\n  SELECT count(*) INTO v_cnt FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN (''api_web_v1'',''api_app_v1'',''core_private'') AND p.prosecdef; IF v_cnt<>20 THEN RAISE EXCEPTION ''M10_J_SECDEF: SECDEF census expected 20, measured %'',v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''core_private'' AND p.prosecdef; IF v_cnt<>1 OR NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=''core_private'' AND p.prosecdef AND p.proname=''ensure_student_mentor_room'') THEN RAISE EXCEPTION ''M10_J_SECDEF: core_private SECDEF expected F10 only, measured %'',v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN (''api_web_v1'',''api_app_v1'') AND c.relkind=''v'' AND NOT (''security_invoker=true''=ANY(coalesce(c.reloptions,''{}''))); IF v_cnt<>1 THEN RAISE EXCEPTION ''M10_J_SECDEF: SECDEF view census expected 1(mentor_directory_v1), measured %'',v_cnt; END IF;\n  SELECT count(*) INTO v_cnt FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN (''api_web_v1'',''api_app_v1'',''core_private'') AND p.prosecdef AND NOT (coalesce(p.proconfig,''{}'') @> ARRAY[''search_path=\"\"''] AND pg_get_userbyid(p.proowner)=''postgres'' AND p.proacl IS NOT NULL AND NOT EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee=0)); IF v_cnt<>0 THEN RAISE EXCEPTION ''M10_J_SECDEF: nonconforming contract SECDEF functions expected 0, measured %'',v_cnt; END IF;\nEND $$;\ncommit;"], "idempotency_key": null}, {"name": "20260801040844_qna_answer_notification_per_event", "version": "20260801054636", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- 20260801040844_qna_answer_notification_per_event.sql\n-- F2(D-12): 구독 질문방 답변 알림을 \"스레드당 1회\" → \"멘토 답변 이벤트당 정확히 1회\"로 수정.\n--\n-- 결함(운영 QA D-12):\n--   1) 136/139/142/144 의 question_answered 알림은 최초 답변 상태 전이(first_answered_at IS NULL)\n--      분기 안에서만 발행돼, 후속 멘토 답변은 알림 생성 함수 자체가 실행되지 않았다.\n--   2) event_key/dedup_key 가 ''question_answered:<thread_id>'' 스레드 단위라, 최초 답변 조건만\n--      제거해도 후속 알림이 UNIQUE(recipient,event_key)/(recipient,dedup_key) 에 무음 흡수된다.\n--\n-- 수정 후 계약:\n--   * 상태 전이(pending/open→answered + first_answered_at): 스레드당 exactly-once — 기존 유지.\n--   * 답변 알림: 멘토 답변 이벤트(메시지 행 / 단독 첨부 행)당 exactly-once — 행 단위 멱등 키.\n--       - 멘토 메시지 1건        → event_key = ''question_answer_message:<message_id>''   → 알림 +1\n--       - 멘토 단독 첨부 1건     → event_key = ''question_answer_attachment:<attachment_id>'' → 알림 +1\n--         (message_id IS NULL 인 첨부만 독립 이벤트)\n--       - 메시지 연결 첨부       → 메시지 이벤트에 합류, 추가 알림 +0 (텍스트+첨부 한 답변 = 알림 1)\n--       - 학생 메시지/첨부·저장 실패·비당사자·잠금 스레드 거부·기존 과거 행·동일 행 재처리 → 알림 +0\n--   * 알림 책임 단일화 (R1 보정 반영): 알림은 question_messages/question_attachments 의\n--     신규 AFTER INSERT 알림 트리거(qm/qa_answer_notification_after — SECURITY DEFINER)가\n--     내부 helper `qna_emit_answer_notification` 을 호출해서만 발행한다.\n--     RPC 경로(qna_append_message/qna_register_attachment)와 허용된 direct-write 경로 모두\n--     같은 INSERT 행이 같은 트리거를 정확히 1회 발화 → 이중 발행 경로 없음.\n--   * helper 외부 호출 차단 (R1): `qna_emit_answer_notification` 은 Data API 호출 표면이 아니다.\n--     PUBLIC/anon/authenticated/service_role EXECUTE 전면 회수 — owner(postgres) 내부\n--     (SECURITY DEFINER 알림 트리거 함수) 실행만 가능하다. 과거 message_id/attachment_id 를\n--     직접 전달하는 수동 RPC 는 permission denied 로 거부되며 소급 알림을 만들 수 없다.\n--     알림 발생 출처는 canonical INSERT 트랜잭션(위 4경로)으로 한정된다.\n--   * 원자성: 알림 트리거는 INSERT 와 같은 트랜잭션에서 실행되므로(132 결정 C 계약 동일)\n--     record_domain_notification 실패 시 메시지/첨부 저장까지 전체 롤백된다. 부분 성공 없음.\n--   * 함수 identity 불변: qna_append_message(uuid,text)·qna_register_attachment(uuid,text,text,text,uuid)·\n--     qna_apply_answered_transition(uuid) 의 이름/인자/반환형/SECURITY DEFINER/search_path/EXECUTE ACL 유지.\n--     144 의 qm_direct_answered_after/qa_direct_answered_after(전이 트리거)는 수정하지 않는다.\n--   * 기존 ''question_answered:<thread_id>'' 키로 적재된 과거 알림 행은 백필·삭제하지 않는다.\n--\n-- 선행: 132(record_domain_notification/outbox) · 136 · 139 · 141 · 142 · 144.\n-- rollback: supabase/rollback/20260801040844_qna_answer_notification_per_event_rollback.sql\n\nbegin;\nset local lock_timeout = ''5s'';\n\n-- ── 0) 기준선 사전 게이트: 정본 함수 identity + 멱등 UNIQUE 계약 확인 ──\ndo $$\nbegin\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                 where n.nspname = ''public'' and p.proname = ''qna_append_message''\n                   and pg_get_function_identity_arguments(p.oid) = ''p_thread_id uuid, p_body text'') then\n    raise exception ''F2_BASELINE_OBJECT_MISMATCH: canonical qna_append_message missing'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                 where n.nspname = ''public'' and p.proname = ''qna_register_attachment''\n                   and pg_get_function_identity_arguments(p.oid)\n                       = ''p_thread_id uuid, p_storage_path text, p_file_name text, p_mime_type text, p_message_id uuid'') then\n    raise exception ''F2_BASELINE_OBJECT_MISMATCH: canonical qna_register_attachment missing'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                 where n.nspname = ''public'' and p.proname = ''qna_apply_answered_transition''\n                   and pg_get_function_identity_arguments(p.oid) = ''p_thread_id uuid'') then\n    raise exception ''F2_BASELINE_OBJECT_MISMATCH: canonical qna_apply_answered_transition missing'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                 where n.nspname = ''public'' and p.proname = ''record_domain_notification'') then\n    raise exception ''F2_BASELINE_OBJECT_MISMATCH: record_domain_notification missing (132 선행)'';\n  end if;\n  if not exists (select 1 from pg_indexes\n                 where schemaname = ''public'' and indexname = ''uq_notifications_recipient_event'') then\n    raise exception ''F2_BASELINE_OBJECT_MISMATCH: uq_notifications_recipient_event missing (132 선행)'';\n  end if;\n  if not exists (select 1 from pg_constraint\n                 where conname = ''notification_outbox_recipient_dedup_uq''\n                   and conrelid = ''public.notification_outbox''::regclass) then\n    raise exception ''F2_BASELINE_OBJECT_MISMATCH: notification_outbox_recipient_dedup_uq missing (132 선행)'';\n  end if;\nend$$;\n\n-- ── 1) 신규 내부 helper: 멘토 답변 이벤트(행 단위) → 학생 question_answered 알림 exactly-once ──\n--   ⚠️ owner-only 내부 함수(R1): 외부 EXECUTE 0 — 아래 AFTER INSERT 알림 트리거 함수\n--   (SECURITY DEFINER, owner=postgres)에서만 호출된다. Data API 직접 RPC 는 permission denied.\n--   self-gating(144 계약 동형): 호출 세션 auth.uid() = room 멘토 AND 대상 행의 author = room 멘토.\n--   메시지 스코프: 해당 스레드의 멘토 메시지 행. 첨부 스코프: message_id IS NULL 인 멘토 단독 첨부 행만\n--   (메시지 연결 첨부는 메시지 이벤트에 합류 — 추가 알림 없음). 조건 불충족 시 무발화 no-op.\n--   멱등: record_domain_notification 의 UNIQUE(recipient,event_key)/(recipient,dedup_key)\n--   ON CONFLICT DO NOTHING — 같은 행 재처리 시 알림/outbox +0.\ncreate or replace function public.qna_emit_answer_notification(\n  p_thread_id uuid,\n  p_message_id uuid default null,\n  p_attachment_id uuid default null\n) returns void\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_room uuid; v_student uuid; v_mentor uuid; v_name text;\n  v_key text; v_body_suffix text; v_meta jsonb;\nbegin\n  if p_thread_id is null then return; end if;\n  -- 정확히 하나의 행 스코프(메시지 XOR 단독첨부)만 허용 — 호출 계약 위반은 즉시 실패(무음 금지).\n  if (p_message_id is null) = (p_attachment_id is null) then\n    raise exception ''ANSWER_EVENT_SCOPE_REQUIRED'';\n  end if;\n\n  select t.mentor_student_room_id into v_room\n  from public.question_threads t where t.id = p_thread_id;\n  if v_room is null then return; end if;\n\n  select student_id, mentor_id into v_student, v_mentor\n  from public.mentor_student_rooms where id = v_room;\n  if v_student is null then return; end if;\n\n  if auth.uid() is distinct from v_mentor then return; end if;  -- 멘토 세션만\n\n  if p_message_id is not null then\n    if not exists (\n      select 1 from public.question_messages m\n      where m.id = p_message_id and m.thread_id = p_thread_id and m.author_id = v_mentor\n    ) then return; end if;\n    v_key := ''question_answer_message:'' || p_message_id::text;\n    v_body_suffix := ''님이 답변을 남겼습니다.'';\n    v_meta := jsonb_build_object(''room_id'', v_room, ''thread_id'', p_thread_id, ''message_id'', p_message_id);\n  else\n    if not exists (\n      select 1 from public.question_attachments a\n      where a.id = p_attachment_id and a.thread_id = p_thread_id\n        and a.author_id = v_mentor and a.message_id is null\n    ) then return; end if;\n    v_key := ''question_answer_attachment:'' || p_attachment_id::text;\n    v_body_suffix := ''님이 파일을 보냈습니다.'';\n    v_meta := jsonb_build_object(''room_id'', v_room, ''thread_id'', p_thread_id, ''attachment_id'', p_attachment_id);\n  end if;\n\n  select coalesce(nullif(btrim(full_name),''''), nullif(btrim(nickname),''''), ''멘토'')\n    into v_name from public.users where id = v_mentor;\n\n  perform public.record_domain_notification(\n    v_student,\n    v_key,\n    v_key,\n    ''question_answered'',\n    ''새 답변이 도착했어요'',\n    coalesce(v_name,''멘토'') || v_body_suffix,\n    ''/question-room/'' || v_room::text || ''?thread='' || p_thread_id::text,\n    v_meta,\n    v_meta\n  );\nend;\n$$;\n\ncomment on function public.qna_emit_answer_notification(uuid, uuid, uuid) is\n  ''F2(D-12)+R1: 멘토 답변 이벤트(메시지 행/단독 첨부 행)당 학생 question_answered 알림 exactly-once. event_key = question_answer_message:<message_id> | question_answer_attachment:<attachment_id>. 메시지 연결 첨부는 메시지 이벤트에 합류(추가 알림 0). self-gating: auth.uid()=room 멘토 AND 행 author=멘토. owner-only 내부 함수 — 외부(PUBLIC/anon/authenticated/service_role) EXECUTE 0, AFTER INSERT 알림 트리거(qm/qa_answer_notification_after)에서만 실행. Data API 호출 표면 아님 — 과거 행 ID 수동 전달로 소급 알림 생성 불가.'';\n\n-- R1: 외부 EXECUTE 전면 회수 — owner(postgres) 내부 실행만 허용. GRANT 없음.\nrevoke all on function public.qna_emit_answer_notification(uuid, uuid, uuid)\n  from public, anon, authenticated, service_role;\n\n-- ── 2) qna_apply_answered_transition: 상태 전이 전용으로 축소(알림 책임 제거) ──\n--   144 계약 유지: 멘토 첫 실제 콘텐츠에서만 pending/open→answered + first_answered_at exactly-once.\n--   알림은 본 함수에서 더 이상 발행하지 않는다(호출측이 qna_emit_answer_notification 사용).\ncreate or replace function public.qna_apply_answered_transition(p_thread_id uuid)\nreturns void language plpgsql security definer set search_path to ''public'' as $$\ndeclare v_room uuid; v_status text; v_first timestamptz; v_student uuid; v_mentor uuid;\nbegin\n  select mentor_student_room_id, status, first_answered_at into v_room, v_status, v_first from public.question_threads where id=p_thread_id;\n  if v_room is null then return; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;\n  if auth.uid() is distinct from v_mentor then return; end if;          -- 멘토만\n  if v_first is not null or v_status not in (''pending'',''open'') then return; end if;\n  if not exists (select 1 from public.question_messages m where m.thread_id=p_thread_id and m.author_id=v_mentor)\n     and not exists (select 1 from public.question_attachments a where a.thread_id=p_thread_id and a.author_id=v_mentor) then\n    return; -- content-less: no-op\n  end if;\n  update public.question_threads set status=''answered'', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;\nend; $$;\n\ncomment on function public.qna_apply_answered_transition(uuid) is\n  ''P1-8A(144)→F2(D-12): 멘토 첫 실제 콘텐츠 → pending/open→answered + first_answered_at 스레드당 exactly-once. 알림 발행 책임은 F2 에서 qna_emit_answer_notification 로 분리됐다(본 함수는 전이 전용).'';\n\nrevoke all on function public.qna_apply_answered_transition(uuid) from public, anon;\ngrant execute on function public.qna_apply_answered_transition(uuid) to authenticated, service_role;\n\n-- ── 3) qna_append_message: 142 본문 유지 — 전이 분기에서 알림 발행 제거(전이만 수행) ──\n--   알림은 본 RPC 가 직접 발행하지 않는다(R1) — INSERT 가 AFTER INSERT 알림 트리거(§5)를\n--   정확히 1회 발화해 행 단위 알림이 발생한다(최초/후속 무관).\ncreate or replace function public.qna_append_message(p_thread_id uuid, p_body text)\nreturns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_status text; v_thread_status text;\n  v_first_answered timestamptz; v_message_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_sub_id uuid;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_body is null or btrim(p_body)='''' then raise exception ''BODY_REQUIRED''; end if;\n  select t.mentor_student_room_id, t.status, t.first_answered_at into v_room, v_thread_status, v_first_answered\n    from public.question_threads t where t.id=p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;\n  if v_uid=v_mentor then v_is_mentor:=true; elsif v_uid=v_student then v_is_mentor:=false; else raise exception ''NOT_ROOM_PARTY''; end if;\n  select status into v_status from public.users where id=v_uid;\n  if lower(coalesce(v_status,''active''))=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if v_thread_status in (''confirmed'',''closed'',''archived'') then raise exception ''THREAD_LOCKED''; end if;\n  if v_is_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  -- 학생 후속 메시지: 활성 구독 FOR UPDATE + live pending refund 게이트(142 유지).\n  if not v_is_mentor then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n  end if;\n\n  -- F2(D-12)+R1: 아래 INSERT 가 AFTER INSERT 알림 트리거를 발화 — 멘토 메시지 행 1건 = 알림 정확히 1건.\n  insert into public.question_messages (thread_id, author_id, body) values (p_thread_id, v_uid, btrim(p_body)) returning id into v_message_id;\n  if v_is_mentor and v_first_answered is null then\n    update public.question_threads set status=''answered'', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;\n    v_transitioned := true;\n  end if;\n  return jsonb_build_object(''ok'',true,''message_id'',v_message_id,''answered_transition'',v_transitioned);\nend; $$;\n\nrevoke all on function public.qna_append_message(uuid,text) from public, anon;\ngrant execute on function public.qna_append_message(uuid,text) to authenticated, service_role;\n\n-- ── 4) qna_register_attachment: 142 본문 유지 — 전이 분기에서 알림 발행 제거(전이만 수행) ──\n--   알림은 본 RPC 가 직접 발행하지 않는다(R1) — INSERT 가 AFTER INSERT 알림 트리거(§5)를\n--   정확히 1회 발화한다. 멘토 단독 첨부(message_id IS NULL)만 알림 +1,\n--   메시지 연결 첨부는 해당 메시지 이벤트에 합류 — 추가 알림 없음(helper self-gate).\ncreate or replace function public.qna_register_attachment(\n  p_thread_id uuid, p_storage_path text, p_file_name text default null, p_mime_type text default null, p_message_id uuid default null\n) returns jsonb language plpgsql security definer set search_path to ''public'' as $$\ndeclare\n  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_thread_status text;\n  v_first_answered timestamptz; v_att_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_sub_id uuid;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_storage_path is null or btrim(p_storage_path)='''' then raise exception ''STORAGE_PATH_REQUIRED''; end if;\n  select t.mentor_student_room_id, t.status, t.first_answered_at into v_room, v_thread_status, v_first_answered\n    from public.question_threads t where t.id=p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;\n  if v_uid=v_mentor then v_is_mentor:=true; elsif v_uid=v_student then v_is_mentor:=false; else raise exception ''NOT_ROOM_PARTY''; end if;\n  if v_thread_status in (''confirmed'',''closed'',''archived'') then raise exception ''THREAD_LOCKED''; end if;\n  if p_storage_path not like (v_room::text || ''/'' || p_thread_id::text || ''/%'') then raise exception ''STORAGE_PATH_MISMATCH''; end if;\n  if not exists (select 1 from storage.objects o where o.bucket_id=''question-room-attachments'' and o.name = btrim(p_storage_path) and o.owner_id = v_uid::text) then raise exception ''STORAGE_OBJECT_NOT_OWNED''; end if;\n  if p_message_id is not null and not exists (select 1 from public.question_messages m where m.id=p_message_id and m.thread_id=p_thread_id) then raise exception ''MESSAGE_THREAD_MISMATCH''; end if;\n  if not v_is_mentor then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n  end if;\n\n  -- F2(D-12)+R1: 아래 INSERT 가 AFTER INSERT 알림 트리거를 발화 — 멘토 단독 첨부 행 1건 = 알림 정확히 1건.\n  insert into public.question_attachments (thread_id, message_id, author_id, storage_path, file_name, mime_type)\n  values (p_thread_id, p_message_id, v_uid, btrim(p_storage_path), p_file_name, p_mime_type) returning id into v_att_id;\n  if v_is_mentor and v_first_answered is null then\n    update public.question_threads set status=''answered'', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;\n    v_transitioned := true;\n  end if;\n  return jsonb_build_object(''ok'',true,''attachment_id'',v_att_id,''answered_transition'',v_transitioned);\nend; $$;\n\nrevoke all on function public.qna_register_attachment(uuid,text,text,text,uuid) from public, anon;\ngrant execute on function public.qna_register_attachment(uuid,text,text,text,uuid) to authenticated, service_role;\n\n-- ── 5) AFTER INSERT 알림 트리거 (R1 — 단일 알림 발행 경로) ──\n--   RPC INSERT(정의자 postgres)와 허용된 direct-write INSERT(authenticated) 모두\n--   같은 AFTER INSERT 알림 트리거를 정확히 1회 통과한다. 트리거 함수는 SECURITY DEFINER\n--   (owner=postgres)라 owner-only helper 를 호출할 수 있고, helper 의 self-gate 가\n--   학생 행·연결 첨부·비멘토 세션(service_role 단독 INSERT 포함)을 무발화 no-op 처리한다.\n--   INSERT 없는 알림 생성 경로는 존재하지 않는다(helper 외부 EXECUTE 0).\n--   144 의 전이 트리거(trg_qm/qa_direct_answered_after — 상태 전이 전용)는 수정하지 않는다.\ncreate or replace function public.qm_answer_notification_after()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\nbegin\n  perform public.qna_emit_answer_notification(NEW.thread_id, NEW.id, null);\n  return NEW;\nend; $$;\nrevoke all on function public.qm_answer_notification_after()\n  from public, anon, authenticated, service_role;\n\ncreate or replace function public.qa_answer_notification_after()\nreturns trigger language plpgsql security definer set search_path to ''public'' as $$\nbegin\n  perform public.qna_emit_answer_notification(NEW.thread_id, null, NEW.id);\n  return NEW;\nend; $$;\nrevoke all on function public.qa_answer_notification_after()\n  from public, anon, authenticated, service_role;\n\ndrop trigger if exists trg_qm_answer_notification_after on public.question_messages;\ncreate trigger trg_qm_answer_notification_after\n  after insert on public.question_messages\n  for each row execute function public.qm_answer_notification_after();\n\ndrop trigger if exists trg_qa_answer_notification_after on public.question_attachments;\ncreate trigger trg_qa_answer_notification_after\n  after insert on public.question_attachments\n  for each row execute function public.qa_answer_notification_after();\n\ncommit;\n\n-- §V (rollback-only fixture: scripts/verify/fixtures/qna_answer_notification_per_event_fixture.sql):\n--   최초 멘토 메시지(전이 1·알림 1·message 키) · 후속 메시지 2건(전이 0·알림 각 +1·키 상이) ·\n--   동일 행 재처리(+0) · 단독 첨부(+1·attachment 키) · 연결 첨부(+0, 텍스트+첨부 합계 1) ·\n--   학생 메시지/첨부(+0) · 비당사자/잠금 스레드 거부(행 0·알림 0) · 직접쓰기 경로 동일 계약 ·\n--   기존 회귀(생성/무료소비/confirm/wrong/차단/미승인) 무변 ·\n--   R1: helper/알림 트리거 함수 외부 EXECUTE 0(anon/authenticated/service_role/PUBLIC) ·\n--   과거 멘토 메시지/단독 첨부 ID 수동 RPC = permission denied·알림 delta 0 ·\n--   RPC INSERT 1회당 알림 정확히 1(이중 발행 0).\n"], "idempotency_key": null}, {"name": "public_defacl_hardening", "version": "20260802000000", "rollback": null, "created_by": null, "statements": ["-- interleave_20260802000000_public_defacl_hardening.sql\n-- 부모 pg_default_acl 실측(role postgres, schema public)으로의 전환을 원장 시점에 재현.\n-- 근거: build13(20260802054930) 이후 생성 객체들이 hardened 기본 ACL 흔적을 보인다\n--   (notification_transport_config·shortform_view_events 에 anon/auth/service_role CRUD 부재,\n--    이후 public 함수들이 proacl 비-NULL·owner-only) — 반면 그 이전 생성 객체는 permissive.\n-- 전환 주체·정확 시각은 저장소·원장 어디에도 없음(out-of-band; UNRECOVERABLE_EXACT_TIME).\n-- 목표 상태(부모 현재): tables anon/auth/service_role = D,x,t(,m) ·\n--   (functions 하드닝은 20260729000000 로 분리 — M13 이전이어야 함이 실측으로 확정)\n--   sequences anon/auth/service_role = w(update) 만.\nalter default privileges in schema public\n  revoke select, insert, update, delete on tables from anon, authenticated, service_role", "alter default privileges in schema public\n  revoke select, usage on sequences from anon, authenticated, service_role"], "idempotency_key": null}, {"name": "20260802024641_build13_db_contract_convergence", "version": "20260802054930", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260802024641_build13_db_contract_convergence.sql (S3-C)\n-- =============================================================================\n-- Build 13 앱이 사용할 서버 정본 수렴 — 범위 A~E 단일 forward.\n--\n-- 배경(실기기 재현 · 2026-08-02):\n--   - 학생 게시판 새 글 등록 FAIL · 멘토 게시판 새 글 등록 FAIL\n--   - 앱은 public.community_posts 에 직접 INSERT 하지만 M16(20260730195153)\n--     이후 authenticated INSERT 권한·INSERT 정책이 모두 없다(= 직접 쓰기 잠금 유지).\n--   - 정본 경로 api_app_v1.community_post_create RPC 는 존재하나 내부 구현부\n--     core_private.community_post_create_impl 이 **승인 멘토 전용**이라\n--     학생 작성이 계약과 불일치한다.\n--   → 본 migration 은 직접 쓰기 잠금을 유지한 채 RPC 역할 계약만 제품 계약\n--     (학생·멘토 모두 게시판 작성 가능)으로 수렴시킨다.\n--\n-- 범위(9종 — 세션 S3-C 지시서 §2~§6 + 교차세션 보정 §1~§4):\n--   A. community_post_create 역할 계약 — active student + active mentor 허용,\n--      guest/anon·admin·unknown role·banned·유효 suspended·삭제 진행 계정 거부.\n--      승인 멘토 전용 제한(MENTOR_NOT_APPROVED) 제거.\n--   B. 직접 UGC write 계정 상태 게이트 — comments INSERT/UPDATE ·\n--      community_comments INSERT · post_reactions INSERT/DELETE ·\n--      shortform_reactions INSERT/DELETE 에 계정 상태 게이트.\n--      (community post RPC 는 구현부에서 동일 게이트를 수행한다 — 보존)\n--   C. content_reports 필드 무결성 — 일반 사용자 INSERT 시 reporter_id·status·\n--      admin_note·resolved_by·resolved_at·target_type 를 서버가 강제(위조 거부).\n--   D. account_deletion_write_blocked self 제한 — 일반 authenticated 는 자기\n--      UUID만 조회, 타인 UUID 는 명시적 거부. 내부/서비스 문맥은 무제한 유지.\n--   E. latent custom-order 공개 SELECT 정책 4종 제거(당사자·관리자 정책 유지).\n--   F. [보정 §1] ugc_write_allowed() fail-closed 전환 — \"차단 목록\"이 아니라\n--      **허용 목록**으로 뒤집는다. users 자기 행 부재·admin·deleted·unknown\n--      status·status NULL 이 전부 false 다(comments/community_comments/\n--      post_reactions 는 users FK 가 없어 helper 자체가 fail-closed 여야 한다).\n--   G. [보정 §2] community_post_update 역할 계약 수렴 — F5 도 create 와 동일하게\n--      active student + active mentor 자기 글 수정 허용, 승인 요구 제거.\n--   H. [보정 §3] 질문방 서버 차단·계정 상태 게이트 — public.qna_append_message /\n--      public.qna_register_attachment 에 상호 차단(qna_users_blocked) + 계정\n--      상태 4종 게이트를 **당사자 확정 직후·모든 INSERT/상태 전이 이전**에 삽입.\n--   I. [보정 §4] target_type=''user'' 신고 무결성 — 자기 신고 거부 + 대상 사용자\n--      실재 강제(public.report_target_user_valid).\n--\n-- 보존 불변(변경 금지 — 지시서 §2 「반드시 보존」 + 보정 §2·§3 「반드시 보존」):\n--   [create] replay-first · idempotency key · 동시 경합 수렴 · title/body/\n--     category/draft·published 검증 · 연락처 마스킹 · image_refs 검증 ·\n--     author_label·author_role 서버 도출.\n--   [update] post row FOR UPDATE · p_expected_updated_at 낙관적 충돌\n--     (UPDATE_CONFLICT) · title/body/category/status 검증 · 연락처 마스킹 ·\n--     image_refs 검증 · removed_image_refs 차집합 반환.\n--   [qna] thread FOR UPDATE · NOT_ROOM_PARTY · THREAD_LOCKED · mentor approval ·\n--     구독/환불 게이트 · storage path·소유권 검증 · message/thread 정합 ·\n--     INSERT · answered 전이 · 알림 트리거 의미 · 반환 envelope.\n--   community_posts direct INSERT/UPDATE 권한 미복구.\n--   RPC 시그니처 전부 불변(api_web_v1 / api_app_v1 wrapper 3종 · public qna 2종)\n--   — 본 파일은 wrapper 를 건드리지 않고 구현부·정본 함수 본문만\n--   CREATE OR REPLACE 한다. contract_version 도 불변(1).\n--\n-- 재실행 안전성(§7):\n--   모든 DDL 이 CREATE OR REPLACE / DROP POLICY IF EXISTS + CREATE POLICY 이며,\n--   사전 게이트는 **pre-state 와 post-state 양쪽에서 참인 구조적 사실**만\n--   단언한다(정책 실재·cmd·roles·컬럼·RLS). 최종 상태의 정확한 정의는 섹션 I\n--   자가 검증이 보증한다 — drift 은닉이 아니라 \"게이트는 구조, 보증은 사후검증\"\n--   분리다. 범위 E 의 제거 대상 4종만 예외적으로 identity(cmd·roles·qual=''true'')\n--   까지 단언하고 부분 집합(1~3개 잔존)이면 즉시 중단한다.\n--\n-- 선행조건: M7(20260730105252) · M17(20260730112525) · M16(20260730195153) 적용 완료.\n-- rollback 정본: supabase/rollback/20260802024641_build13_db_contract_convergence_rollback.sql\n-- 운영 적용: 금지(본 세션은 파일 생성·로컬 검증까지). PRODUCTION_APPLIED = NO.\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- A. 사전 게이트 (수정 0건 중단 원칙)\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_cnt int;\nBEGIN\n  -- ① 선행 표면 실재 — M7 공용 구현부 identity + M17 앱 wrapper\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''core_private'' AND p.proname = ''community_post_create_impl''\n                    AND pg_get_function_identity_arguments(p.oid)\n                        = ''p_author_id uuid, p_title text, p_body text, p_category text, p_image_refs text[], p_status text, p_idempotency_key uuid'') THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: core_private.community_post_create_impl identity mismatch (M7 미적용?)'';\n  END IF;\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname IN (''api_web_v1'', ''api_app_v1'')\n         AND p.proname = ''community_post_create''\n         AND pg_get_function_identity_arguments(p.oid)\n             = ''p_title text, p_body text, p_category text, p_idempotency_key uuid, p_image_refs text[], p_status text'') <> 2 THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: community_post_create wrapper 2종(web·app) identity mismatch'';\n  END IF;\n  -- 보정 G — update 구현부·wrapper identity\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''core_private'' AND p.proname = ''community_post_update_impl''\n                    AND pg_get_function_identity_arguments(p.oid)\n                        = ''p_author_id uuid, p_post_id uuid, p_title text, p_body text, p_category text, p_image_refs text[], p_status text, p_expected_updated_at timestamp with time zone'') THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: core_private.community_post_update_impl identity mismatch'';\n  END IF;\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname IN (''api_web_v1'', ''api_app_v1'')\n         AND p.proname = ''community_post_update''\n         AND pg_get_function_identity_arguments(p.oid)\n             = ''p_post_id uuid, p_title text, p_body text, p_category text, p_expected_updated_at timestamp with time zone, p_image_refs text[], p_status text'') <> 2 THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: community_post_update wrapper 2종(web·app) identity mismatch'';\n  END IF;\n\n  -- 보정 H — 질문방 정본 RPC identity + 게이트가 의존하는 helper 실재\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''public'' AND p.proname = ''qna_append_message''\n                    AND pg_get_function_identity_arguments(p.oid) = ''p_thread_id uuid, p_body text''\n                    AND p.prosecdef) THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: public.qna_append_message(uuid,text) identity mismatch'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''public'' AND p.proname = ''qna_register_attachment''\n                    AND pg_get_function_identity_arguments(p.oid)\n                        = ''p_thread_id uuid, p_storage_path text, p_file_name text, p_mime_type text, p_message_id uuid''\n                    AND p.prosecdef) THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: public.qna_register_attachment identity mismatch'';\n  END IF;\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname = ''public''\n         AND (p.proname, pg_get_function_identity_arguments(p.oid)) IN\n             ((''qna_users_blocked'', ''p_a uuid, p_b uuid''),\n              (''qna_subscription_has_live_refund'', ''p_subscription_id uuid''),\n              (''individual_question_user_is_approved_mentor'', ''p_user_id uuid''))) <> 3 THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: qna 게이트 helper 3종 identity mismatch'';\n  END IF;\n\n  -- 보정 F/I — 상태 판정에 쓰는 users 컬럼 + 신고 대상 검증에 쓰는 users PK\n  IF (SELECT count(*) FROM information_schema.columns\n       WHERE table_schema = ''public'' AND table_name = ''users''\n         AND column_name IN (''id'', ''role'', ''status'', ''suspended_until'')) <> 4 THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: users 상태 판정 컬럼 집합 불일치'';\n  END IF;\n\n  -- ② community_posts 직접 쓰기 잠금 실재(M16) — 본 migration 은 이를 복구하지 않는다\n  IF has_table_privilege(''authenticated'', ''public.community_posts'', ''INSERT'')\n     OR has_table_privilege(''anon'', ''public.community_posts'', ''INSERT'')\n     OR (SELECT count(*) FROM pg_policies\n          WHERE schemaname = ''public'' AND tablename = ''community_posts''\n            AND cmd IN (''INSERT'', ''UPDATE'', ''DELETE'')) <> 0 THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: community_posts 직접 쓰기 잠금(M16) 미충족'';\n  END IF;\n\n  -- ③ 범위 D 대상 함수 identity\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''public'' AND p.proname = ''account_deletion_write_blocked''\n                    AND pg_get_function_identity_arguments(p.oid) = ''p_user_id uuid''\n                    AND p.prosecdef) THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: public.account_deletion_write_blocked(uuid) SECDEF 부재'';\n  END IF;\n  IF to_regclass(''public.account_deletion_jobs'') IS NULL THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: public.account_deletion_jobs 부재'';\n  END IF;\n\n  -- ④ 범위 B 대상 테이블·정책 구조(pre/post 공통 참) — RLS 활성 + 대상 정책 실재\n  FOR v_cnt IN\n    SELECT 1 FROM (VALUES (''comments''), (''community_comments''),\n                          (''post_reactions''), (''shortform_reactions''), (''content_reports'')) AS t(rel)\n     WHERE NOT coalesce((SELECT c.relrowsecurity FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace\n                          WHERE n.nspname = ''public'' AND c.relname = t.rel), false)\n  LOOP\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: 범위 B/C 대상 테이블에 RLS 미활성'';\n  END LOOP;\n  SELECT count(*) INTO v_cnt FROM pg_policies\n   WHERE schemaname = ''public''\n     AND (tablename, policyname, cmd, roles::text) IN\n         ((''comments'',             ''comments_insert_own'',                    ''INSERT'', ''{authenticated}''),\n          (''comments'',             ''comments_update_own'',                    ''UPDATE'', ''{authenticated}''),\n          (''community_comments'',   ''community_comments_insert_authenticated'',''INSERT'', ''{authenticated}''),\n          (''post_reactions'',       ''post_reactions_insert_own'',              ''INSERT'', ''{authenticated}''),\n          (''post_reactions'',       ''post_reactions_delete_own'',              ''DELETE'', ''{authenticated}''),\n          (''shortform_reactions'',  ''shortform_reactions_insert_own'',         ''INSERT'', ''{authenticated}''),\n          (''shortform_reactions'',  ''shortform_reactions_delete_own'',         ''DELETE'', ''{authenticated}''),\n          (''content_reports'',      ''content_reports_insert_reporter'',        ''INSERT'', ''{authenticated}''));\n  IF v_cnt <> 8 THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: 범위 B/C 대상 정책 8종 identity 불일치(matched %/8)'', v_cnt;\n  END IF;\n\n  -- ⑤ 범위 B — post_reactions 한글명 중복 정책(대시보드 생성분)은 permissive OR 로\n  --    게이트를 무력화하므로 제거 대상이다. 2종 전부 또는 전무만 허용(부분 = drift).\n  SELECT count(*) INTO v_cnt FROM pg_policies\n   WHERE schemaname = ''public'' AND tablename = ''post_reactions''\n     AND (policyname, cmd, roles::text) IN\n         ((''로그인 유저 반응 추가'', ''INSERT'', ''{public}''),\n          (''본인 반응 삭제'',        ''DELETE'', ''{public}''));\n  IF v_cnt NOT IN (0, 2) THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: post_reactions 한글명 중복 쓰기 정책 부분 존재(measured %)'', v_cnt;\n  END IF;\n\n  -- ⑥ 범위 C — content_reports 관리 필드 컬럼 전수\n  IF (SELECT count(*) FROM information_schema.columns\n       WHERE table_schema = ''public'' AND table_name = ''content_reports''\n         AND column_name IN (''reporter_id'',''target_type'',''target_id'',''status'',\n                             ''admin_note'',''resolved_by'',''resolved_at'')) <> 7 THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: content_reports 관리 필드 컬럼 집합 불일치'';\n  END IF;\n  -- 관리자 UPDATE 경로 보존 대상 실재\n  IF NOT EXISTS (SELECT 1 FROM pg_policies\n                  WHERE schemaname = ''public'' AND tablename = ''content_reports''\n                    AND policyname = ''content_reports_update_admin'' AND cmd = ''UPDATE'') THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: content_reports_update_admin 부재(관리자 경로 유실)'';\n  END IF;\n\n  -- ⑦ 범위 E — 제거 대상 permissive public SELECT 4종. 전부(4) 또는 전무(0)만 허용.\n  SELECT count(*) INTO v_cnt FROM pg_policies\n   WHERE schemaname = ''public'' AND cmd = ''SELECT'' AND roles::text = ''{public}''\n     AND btrim(coalesce(qual, '''')) = ''true''\n     AND (tablename, policyname) IN\n         ((''custom_order_deliverables'',    ''누구나 납품 읽기''),\n          (''custom_order_messages'',        ''누구나 메시지 읽기''),\n          (''custom_request_applications'',  ''누구나 지원서 읽기''),\n          (''custom_request_posts'',         ''누구나 의뢰 읽기''));\n  IF v_cnt NOT IN (0, 4) THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: custom_* public SELECT 정책 부분 존재(measured %/4)'', v_cnt;\n  END IF;\n  -- 유지 대상(당사자·관리자) 4종 실재 — 제거로 정당 경로가 끊기지 않음을 사전 증명\n  IF (SELECT count(*) FROM pg_policies\n       WHERE schemaname = ''public'' AND cmd = ''SELECT''\n         AND (tablename, policyname) IN\n             ((''custom_order_deliverables'',   ''cdel_select''),\n              (''custom_order_messages'',       ''cmsg_all_party''),\n              (''custom_request_applications'', ''cra_select''),\n              (''custom_request_posts'',        ''crp_select''))) <> 4 THEN\n    RAISE EXCEPTION ''S3C_BASELINE_MISMATCH: custom_* 당사자·관리자 SELECT 정책 4종 부재'';\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- B. 범위 D — account_deletion_write_blocked self 제한\n-- -----------------------------------------------------------------------------\n-- 기존: SECDEF + authenticated EXECUTE → 로그인 사용자가 **타인 UUID** 를 넘겨\n--   삭제 진행 여부를 probe 할 수 있었다(정보 유출).\n-- 신규 계약:\n--   - auth.uid() IS NOT NULL(= 최종 사용자 JWT 문맥): p_user_id 는 자기 UUID 만\n--     허용. 그 외(타인·NULL)는 ACCOUNT_DELETION_PROBE_FORBIDDEN(SQLSTATE 42501) 거부.\n--   - auth.uid() IS NULL(= service_role 키·내부 worker·postgres 직결 문맥):\n--     JWT sub 가 없으므로 종전대로 임의 UUID 조회 허용(worker 계약 보존).\n--   - 시그니처·반환형·EXECUTE 대상(authenticated·service_role) 불변 →\n--     현행 앱의 \"자기 userId\" 호출과 기존 호출자 전건이 그대로 동작한다.\n-- 기존 호출자 실측(2026-08-02): storage.objects 정책 5종 · public.account_deletion_write_guard()\n--   · core_private.ensure_student_mentor_room · community_post_{create,update,soft_delete}_impl\n--   · api_web_v1.mentor_{profile_update_self,plan_prices_set_self,payout_account_update_self}\n--   — **전건이 auth.uid() 또는 그와 동일한 자기 UUID 를 전달**하므로 회귀 없음.\nCREATE OR REPLACE FUNCTION public.account_deletion_write_blocked(p_user_id uuid)\nRETURNS boolean\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '''' AS $fn$\nDECLARE\n  v_uid uuid := (SELECT auth.uid());\nBEGIN\n  IF v_uid IS NOT NULL AND p_user_id IS DISTINCT FROM v_uid THEN\n    RAISE EXCEPTION ''ACCOUNT_DELETION_PROBE_FORBIDDEN'' USING ERRCODE = ''42501'';\n  END IF;\n  RETURN EXISTS (\n    SELECT 1 FROM public.account_deletion_jobs j\n     WHERE j.user_id = p_user_id\n       AND j.state IN (''locked'', ''purging'', ''storage_purged'', ''finalized'', ''auth_soft_deleted'')\n  );\nEND $fn$;\n\nCOMMENT ON FUNCTION public.account_deletion_write_blocked(uuid) IS\n  ''S3-C 범위 D: 삭제 진행 write 차단 판정. 최종 사용자 JWT 문맥에서는 self UUID 만 허용(타인 probe 는 42501 ACCOUNT_DELETION_PROBE_FORBIDDEN). service_role·내부 문맥(auth.uid() IS NULL)은 종전대로 무제한.'';\n\nREVOKE ALL ON FUNCTION public.account_deletion_write_blocked(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.account_deletion_write_blocked(uuid) TO authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- C. 범위 B 공용 helper — public.ugc_write_allowed()\n-- -----------------------------------------------------------------------------\n-- 인자 없는 self 전용 판정기다. **UUID 인자를 두지 않는 것이 설계의 핵심** —\n--   호출자가 타인 상태를 probe 할 수 있는 표면 자체를 만들지 않는다(범위 D 와 동일 원칙).\n-- SECURITY DEFINER 근거: public.users 는 RLS 대상이라 invoker 문맥에서는 자기 행조차\n--   정책에 좌우된다. 게이트가 RLS 에 재귀 의존하지 않도록 definer 로 고정하고,\n--   search_path='''' + 완전 수식 + PUBLIC/anon EXECUTE 0 으로 표면을 최소화한다.\n-- [보정 §1] **fail-closed 허용 목록**이다. 종전 \"차단 목록\"(명시 3상태만 막고 나머지는\n--   허용) 구현은 폐기한다 — comments·community_comments·post_reactions 는 users 로의\n--   FK 가 없어 \"users 행이 없으면 허용\"이 곧 우회로가 되기 때문이다.\n-- true 조건(전건 AND):\n--   ① auth.uid() non-null\n--   ② public.users 에 자기 행이 실재\n--   ③ role IN (''student'',''mentor'')\n--   ④ status = ''active''  또는  status = ''suspended'' 이면서 suspended_until <= now()\n--      (= 정지 만료)\n--   ⑤ account_deletion_write_blocked(self) = false\n-- 따라서 다음은 전부 false: users 행 부재 · admin · deleted · unknown status ·\n--   status NULL · banned · 유효 suspended(suspended_until NULL 또는 미래) ·\n--   삭제 write-blocked · 미인증.\n-- SECURITY DEFINER 근거: public.users 는 RLS 대상(자기 행 SELECT 만 허용)이므로\n--   invoker 문맥에서는 게이트가 RLS 에 재귀 의존한다. definer 로 고정하고\n--   search_path='''' + 완전 수식 + PUBLIC/anon EXECUTE 0 으로 표면을 최소화한다.\n-- auth.uid() 가 NULL 이면 ② 가 false 라 EXISTS 가 false 이고,\n--   account_deletion_write_blocked(NULL) 은 JWT 없는 문맥에서 예외 없이 false 를\n--   반환하므로 전체가 false 로 수렴한다(예외 전파 없음).\nCREATE OR REPLACE FUNCTION public.ugc_write_allowed()\nRETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = '''' AS $fn$\n  SELECT EXISTS (\n           SELECT 1 FROM public.users u\n            WHERE u.id = (SELECT auth.uid())\n              AND u.role IN (''student'', ''mentor'')\n              AND ( lower(btrim(coalesce(u.status, ''''))) = ''active''\n                 OR ( lower(btrim(coalesce(u.status, ''''))) = ''suspended''\n                      AND u.suspended_until IS NOT NULL\n                      AND u.suspended_until <= now() ) )\n         )\n         AND NOT public.account_deletion_write_blocked((SELECT auth.uid()))\n$fn$;\n\nCOMMENT ON FUNCTION public.ugc_write_allowed() IS\n  ''S3-C 범위 B(보정 §1): 직접 UGC write(댓글·반응) 계정 상태 게이트. self 전용(인자 없음) · **fail-closed 허용 목록** — users 자기 행 실재 + role student|mentor + (active | 정지 만료) + 삭제 write-blocked 아님 일 때만 true. users 행 부재·admin·deleted·unknown·NULL status 는 전부 false. 신고·차단·계정삭제·고객지원 경로에는 적용하지 않는다.'';\n\nREVOKE ALL ON FUNCTION public.ugc_write_allowed() FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.ugc_write_allowed() TO authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- C-2. 보정 §4 helper — public.report_target_user_valid(uuid)\n-- -----------------------------------------------------------------------------\n-- target_type=''user'' 신고의 대상 무결성 판정기.\n--   true 조건: p_target_id non-null · auth.uid() 와 다름(자기 신고 금지) ·\n--              public.users 에 실재.\n-- SECURITY DEFINER 근거: public.users RLS 는 authenticated 에게 **자기 행만** 보인다\n--   (users_select_own · users_admin_select_all 실측). invoker 문맥의 EXISTS 는\n--   타인 UUID 에 대해 항상 false 가 되어 계약이 정반대로 뒤집힌다.\n-- 표면 최소화: 두 판정(비-self · 실재)을 하나의 boolean 으로 묶어, 신고 기능이\n--   본질적으로 노출할 수밖에 없는 \"이 UUID 를 신고 대상으로 쓸 수 있는가\" 외의\n--   정보를 반환하지 않는다. PUBLIC/anon EXECUTE 0.\nCREATE OR REPLACE FUNCTION public.report_target_user_valid(p_target_id uuid)\nRETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = '''' AS $fn$\n  SELECT p_target_id IS NOT NULL\n     AND p_target_id IS DISTINCT FROM (SELECT auth.uid())\n     AND EXISTS (SELECT 1 FROM public.users u WHERE u.id = p_target_id)\n$fn$;\n\nCOMMENT ON FUNCTION public.report_target_user_valid(uuid) IS\n  ''S3-C 보정 §4: content_reports target_type=''''user'''' 대상 무결성 — 자기 신고 거부 + 대상 사용자 실재 강제. users RLS(자기 행만 조회) 때문에 SECDEF 필수.'';\n\nREVOKE ALL ON FUNCTION public.report_target_user_valid(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.report_target_user_valid(uuid) TO authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- D. 범위 A — core_private.community_post_create_impl 역할 계약 수렴\n-- -----------------------------------------------------------------------------\n-- 변경점은 **역할 게이트 1블록**뿐이다.\n--   구: users.role = ''mentor'' 아니면 ROLE_NOT_MENTOR\n--       + individual_question_user_is_approved_mentor() 아니면 MENTOR_NOT_APPROVED\n--   신: users.role IN (''student'',''mentor'') 아니면 ROLE_NOT_ALLOWED\n--       (승인 여부는 게시판 작성 자격과 무관 — 제품 계약)\n-- 그 외 전부 문자 그대로 보존: replay-first · 멱등키 필수 · 계정 3상태 게이트 ·\n--   status(draft|published) · title · category · body 최소 길이 · 연락처 마스킹\n--   6단계(순서 동일) · B-4 이미지 검증 · INSERT 컬럼·author_label/author_role 도출 ·\n--   ON CONFLICT DO NOTHING 후 동시 경합 재생 수렴.\n-- 오류코드 영향(S3-D·S3-E 인수인계):\n--   - 신설: ROLE_NOT_ALLOWED (admin·unknown role·users 행 부재)\n--   - create 경로에서 더 이상 발생하지 않음: ROLE_NOT_MENTOR · MENTOR_NOT_APPROVED\n--     (두 코드는 update 경로 F5 에서 계속 유효 — 본 세션 범위는 create 뿐이다)\nCREATE OR REPLACE FUNCTION core_private.community_post_create_impl(\n  p_author_id uuid, p_title text, p_body text, p_category text,\n  p_image_refs text[], p_status text, p_idempotency_key uuid\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY INVOKER SET search_path = '''' AS $fn$\nDECLARE\n  v_role     text;\n  v_status   text;\n  v_susp     timestamptz;\n  v_nickname text;\n  v_title    text;\n  v_body     text;\n  v_val      jsonb;\n  v_id       uuid;\n  v_norm     text;\nBEGIN\n  IF p_author_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  -- 멱등키 필수(§14.4) — 계약 밖 입력은 전파(§8.2)\n  IF p_idempotency_key IS NULL THEN\n    RAISE EXCEPTION ''p_idempotency_key is required'';\n  END IF;\n\n  -- [replay-first — 신규 쓰기 검증보다 먼저] 기존 커밋 행 재생 (§7 F4 1~2단계)\n  SELECT cp.id INTO v_id FROM public.community_posts cp\n   WHERE cp.author_id = p_author_id AND cp.create_idempotency_key = p_idempotency_key;\n  IF FOUND THEN\n    RETURN jsonb_build_object(''ok'', true, ''post_id'', v_id, ''idempotent_replay'', true);\n  END IF;\n\n  -- [신규 쓰기 검증 — 역할 → 계정 → 본문 → 이미지]\n  SELECT u.role, u.status, u.suspended_until, u.nickname\n    INTO v_role, v_status, v_susp, v_nickname\n    FROM public.users u WHERE u.id = p_author_id;\n  -- S3-C 범위 A: 게시판 작성 자격 = active student + active mentor.\n  -- admin·unknown role·users 행 부재는 ROLE_NOT_ALLOWED 로 거부한다.\n  IF NOT FOUND OR v_role IS NULL OR v_role NOT IN (''student'', ''mentor'') THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ROLE_NOT_ALLOWED'');\n  END IF;\n  -- [보정 2차 §1] 계정 상태는 **positive allowlist** 다(fail-open 금지).\n  --   허용: ''active'' | (''suspended'' 이고 suspended_until <= now() = 정지 만료)\n  --   그 외(deleted·dormant·빈 문자열·NULL·미지 값)는 ACCOUNT_NOT_ACTIVE.\n  --   banned·유효 suspended 는 기존 전용 코드를 유지한다(먼저 판정).\n  v_norm := lower(btrim(coalesce(v_status, '''')));\n  IF v_norm = ''banned'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_BANNED'');\n  END IF;\n  IF v_norm = ''suspended'' AND (v_susp IS NULL OR v_susp > now()) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_SUSPENDED'');\n  END IF;\n  IF NOT (v_norm = ''active''\n          OR (v_norm = ''suspended'' AND v_susp IS NOT NULL AND v_susp <= now())) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_NOT_ACTIVE'');\n  END IF;\n  IF public.account_deletion_write_blocked(p_author_id) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  END IF;\n  IF p_status NOT IN (''draft'', ''published'') THEN\n    RAISE EXCEPTION ''p_status must be draft|published'';\n  END IF;\n  v_title := btrim(coalesce(p_title, ''''));\n  IF v_title = '''' THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''TITLE_REQUIRED'');\n  END IF;\n  IF p_category IS NULL OR p_category NOT IN (''study'', ''school'', ''career'', ''college'', ''free'') THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''CATEGORY_INVALID'');\n  END IF;\n  v_body := btrim(coalesce(p_body, ''''));\n  IF p_status = ''published'' AND char_length(v_body) < 10 THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''BODY_TOO_SHORT'');\n  END IF;\n\n  -- [연락처 마스킹 — lib/customRequest/contactMasking.ts 정본 이식, 적용 순서 동일.\n  --  제목·본문 모두 마스킹(웹 실측 동작). 금지어 검사 없음(rev 8 D — B-04 동결)]\n  v_title := regexp_replace(v_title, ''(^|[^0-9])(\\+82[-._\\s]?0?1[0-9][-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4}|0(?:10|11|16|17|18|19|2|[3-6][1-5]|50|70|80)[-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4})(?![0-9])'', ''\\1[연락처 비공개]'', ''g'');\n  v_body  := regexp_replace(v_body,  ''(^|[^0-9])(\\+82[-._\\s]?0?1[0-9][-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4}|0(?:10|11|16|17|18|19|2|[3-6][1-5]|50|70|80)[-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4})(?![0-9])'', ''\\1[연락처 비공개]'', ''g'');\n  v_title := regexp_replace(v_title, ''(공일공|영일영)[\\s\\-._]*[0-9공영일이삼사오육칠팔구][0-9공영일이삼사오육칠팔구\\s\\-._]{6,12}'', ''[연락처 비공개]'', ''g'');\n  v_body  := regexp_replace(v_body,  ''(공일공|영일영)[\\s\\-._]*[0-9공영일이삼사오육칠팔구][0-9공영일이삼사오육칠팔구\\s\\-._]{6,12}'', ''[연락처 비공개]'', ''g'');\n  v_title := regexp_replace(v_title, ''[A-Za-z0-9._%+-]+\\s*[\\[({（]\\s*at\\s*[\\])}）]\\s*[A-Za-z0-9.-]+\\s*(?:[\\[({（]\\s*dot\\s*[\\])}）]|\\.)\\s*[A-Za-z]{2,}'', ''[연락처 비공개]'', ''gi'');\n  v_body  := regexp_replace(v_body,  ''[A-Za-z0-9._%+-]+\\s*[\\[({（]\\s*at\\s*[\\])}）]\\s*[A-Za-z0-9.-]+\\s*(?:[\\[({（]\\s*dot\\s*[\\])}）]|\\.)\\s*[A-Za-z]{2,}'', ''[연락처 비공개]'', ''gi'');\n  v_title := regexp_replace(v_title, ''\\y[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}\\y'', ''[연락처 비공개]'', ''gi'');\n  v_body  := regexp_replace(v_body,  ''\\y[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}\\y'', ''[연락처 비공개]'', ''gi'');\n  v_title := regexp_replace(v_title, ''\\y(?:open\\.kakao\\.com|kakaotalk\\.com|t\\.me|telegram\\.me|instagram\\.com|instagr\\.am|linktr\\.ee)(?:/[^\\s<>\"'''']*)?'', ''[연락처 비공개]'', ''gi'');\n  v_body  := regexp_replace(v_body,  ''\\y(?:open\\.kakao\\.com|kakaotalk\\.com|t\\.me|telegram\\.me|instagram\\.com|instagr\\.am|linktr\\.ee)(?:/[^\\s<>\"'''']*)?'', ''[연락처 비공개]'', ''gi'');\n  v_title := regexp_replace(v_title, ''(카카오톡|카톡|오픈채팅|텔레그램|인스타그램|인스타|디엠)\\s*[:：=]?\\s*@?[A-Za-z0-9._-]{4,}'', ''[연락처 비공개]'', ''g'');\n  v_body  := regexp_replace(v_body,  ''(카카오톡|카톡|오픈채팅|텔레그램|인스타그램|인스타|디엠)\\s*[:：=]?\\s*@?[A-Za-z0-9._-]{4,}'', ''[연락처 비공개]'', ''g'');\n\n  -- 이미지 ref 검증 (B-4 공용 검증기)\n  v_val := core_private.community_image_refs_validate(p_author_id, coalesce(p_image_refs, ''{}''::text[]));\n  IF NOT coalesce((v_val ->> ''ok'')::boolean, false) THEN\n    RETURN v_val;\n  END IF;\n\n  -- INSERT (컬럼 집합 = 현행 웹 insertCommunityBoardPost 동일. author_label/role 서버 도출)\n  INSERT INTO public.community_posts\n    (author_id, title, body, content, category, image_urls, hashtags, status,\n     author_label, author_role, create_idempotency_key)\n  VALUES\n    (p_author_id, v_title, v_body, v_body, p_category,\n     coalesce(p_image_refs, ''{}''::text[]), ''{}''::text[], p_status,\n     coalesce(nullif(btrim(v_nickname), ''''), ''쌤버십 사용자''),\n     CASE WHEN v_role IN (''student'', ''mentor'') THEN v_role END,\n     p_idempotency_key)\n  ON CONFLICT (author_id, create_idempotency_key) DO NOTHING\n  RETURNING id INTO v_id;\n\n  -- 동시 경합 패자 → 재생 수렴 (T-CONC-06)\n  IF v_id IS NULL THEN\n    SELECT cp.id INTO v_id FROM public.community_posts cp\n     WHERE cp.author_id = p_author_id AND cp.create_idempotency_key = p_idempotency_key;\n    IF v_id IS NULL THEN\n      RAISE EXCEPTION ''community_post_create_impl: idempotent insert not observable'';\n    END IF;\n    RETURN jsonb_build_object(''ok'', true, ''post_id'', v_id, ''idempotent_replay'', true);\n  END IF;\n\n  RETURN jsonb_build_object(''ok'', true, ''post_id'', v_id, ''idempotent_replay'', false);\nEND $fn$;\n\nCOMMENT ON FUNCTION core_private.community_post_create_impl(uuid, text, text, text, text[], text, uuid) IS\n  ''S3-C 범위 A(M7 B-1 승계): 게시글 생성 공용 구현부 — replay-first 멱등 · **active student + active mentor** 작성 허용(admin·unknown = ROLE_NOT_ALLOWED) · 계정 3상태 게이트 · 마스킹 · B-4 이미지 검증. 외부 EXECUTE 0.'';\n\n-- -----------------------------------------------------------------------------\n-- D-2. 보정 §2(범위 G) — core_private.community_post_update_impl 역할 계약 수렴\n-- -----------------------------------------------------------------------------\n-- 제품 정본은 \"학생·멘토 모두 커뮤니티 전 기능\"이다. create 만 수렴시키고 update 를\n-- 승인 멘토 전용으로 남기면 학생이 **자기 글을 쓰고 지울 수는 있으나 고칠 수 없는**\n-- 비대칭이 생기므로, F5 도 create 와 동일한 역할 게이트로 수렴한다.\n--   구: role = ''mentor'' 아니면 ROLE_NOT_MENTOR + 미승인이면 MENTOR_NOT_APPROVED\n--   신: role IN (''student'',''mentor'') 아니면 ROLE_NOT_ALLOWED (승인 요구 없음)\n-- 그 외 전부 문자 그대로 보존: 소유 행 FOR UPDATE(비존재·타인 글·삭제 글 모두\n--   POST_NOT_FOUND_OR_NOT_OWNED 단일 코드) · 계정 3상태 게이트 · 낙관적 충돌\n--   (p_expected_updated_at → UPDATE_CONFLICT) · status/title/category/body 검증 ·\n--   연락처 마스킹 6단계(순서 동일) · B-4 이미지 검증 · removed_image_refs 차집합 ·\n--   UPDATE 컬럼 집합. wrapper 시그니처·contract_version 불변.\nCREATE OR REPLACE FUNCTION core_private.community_post_update_impl(\n  p_author_id uuid, p_post_id uuid, p_title text, p_body text, p_category text,\n  p_image_refs text[], p_status text, p_expected_updated_at timestamptz\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY INVOKER SET search_path = '''' AS $fn$\nDECLARE\n  v_role       text;\n  v_status     text;\n  v_susp       timestamptz;\n  v_post       record;\n  v_title      text;\n  v_body       text;\n  v_val        jsonb;\n  v_removed    text[];\n  v_updated_at timestamptz;\n  v_norm       text;\nBEGIN\n  IF p_author_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  IF p_post_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''POST_NOT_FOUND_OR_NOT_OWNED'');\n  END IF;\n\n  -- 소유 행 잠금 (비존재·타인 글·삭제 글 동일 코드 — §9.4)\n  SELECT cp.id, cp.image_urls, cp.updated_at INTO v_post\n    FROM public.community_posts cp\n   WHERE cp.id = p_post_id AND cp.author_id = p_author_id AND cp.deleted_at IS NULL\n   FOR UPDATE;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''POST_NOT_FOUND_OR_NOT_OWNED'');\n  END IF;\n\n  -- 역할·계정 (S3-C 보정 §2: 학생 글 수정 거부 규칙 폐기 — create 와 **문자 그대로 동일** 계약)\n  SELECT u.role, u.status, u.suspended_until INTO v_role, v_status, v_susp\n    FROM public.users u WHERE u.id = p_author_id;\n  IF NOT FOUND OR v_role IS NULL OR v_role NOT IN (''student'', ''mentor'') THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ROLE_NOT_ALLOWED'');\n  END IF;\n  -- [보정 2차 §1] create 와 동일한 positive allowlist (fail-open 금지)\n  v_norm := lower(btrim(coalesce(v_status, '''')));\n  IF v_norm = ''banned'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_BANNED'');\n  END IF;\n  IF v_norm = ''suspended'' AND (v_susp IS NULL OR v_susp > now()) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_SUSPENDED'');\n  END IF;\n  IF NOT (v_norm = ''active''\n          OR (v_norm = ''suspended'' AND v_susp IS NOT NULL AND v_susp <= now())) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_NOT_ACTIVE'');\n  END IF;\n  IF public.account_deletion_write_blocked(p_author_id) THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  END IF;\n\n  -- 낙관적 충돌 검사 (§7 F5)\n  IF v_post.updated_at IS DISTINCT FROM p_expected_updated_at THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''UPDATE_CONFLICT'');\n  END IF;\n\n  IF p_status NOT IN (''draft'', ''published'') THEN\n    RAISE EXCEPTION ''p_status must be draft|published'';\n  END IF;\n  v_title := btrim(coalesce(p_title, ''''));\n  IF v_title = '''' THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''TITLE_REQUIRED'');\n  END IF;\n  IF p_category IS NULL OR p_category NOT IN (''study'', ''school'', ''career'', ''college'', ''free'') THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''CATEGORY_INVALID'');\n  END IF;\n  v_body := btrim(coalesce(p_body, ''''));\n  IF p_status = ''published'' AND char_length(v_body) < 10 THEN\n    RETURN jsonb_build_object(''ok'', false, ''code'', ''BODY_TOO_SHORT'');\n  END IF;\n\n  -- [연락처 마스킹 — B-1 과 동일 정본 이식(contactMasking.ts) · 동일 순서]\n  v_title := regexp_replace(v_title, ''(^|[^0-9])(\\+82[-._\\s]?0?1[0-9][-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4}|0(?:10|11|16|17|18|19|2|[3-6][1-5]|50|70|80)[-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4})(?![0-9])'', ''\\1[연락처 비공개]'', ''g'');\n  v_body  := regexp_replace(v_body,  ''(^|[^0-9])(\\+82[-._\\s]?0?1[0-9][-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4}|0(?:10|11|16|17|18|19|2|[3-6][1-5]|50|70|80)[-._\\s]?[0-9]{3,4}[-._\\s]?[0-9]{4})(?![0-9])'', ''\\1[연락처 비공개]'', ''g'');\n  v_title := regexp_replace(v_title, ''(공일공|영일영)[\\s\\-._]*[0-9공영일이삼사오육칠팔구][0-9공영일이삼사오육칠팔구\\s\\-._]{6,12}'', ''[연락처 비공개]'', ''g'');\n  v_body  := regexp_replace(v_body,  ''(공일공|영일영)[\\s\\-._]*[0-9공영일이삼사오육칠팔구][0-9공영일이삼사오육칠팔구\\s\\-._]{6,12}'', ''[연락처 비공개]'', ''g'');\n  v_title := regexp_replace(v_title, ''[A-Za-z0-9._%+-]+\\s*[\\[({（]\\s*at\\s*[\\])}）]\\s*[A-Za-z0-9.-]+\\s*(?:[\\[({（]\\s*dot\\s*[\\])}）]|\\.)\\s*[A-Za-z]{2,}'', ''[연락처 비공개]'', ''gi'');\n  v_body  := regexp_replace(v_body,  ''[A-Za-z0-9._%+-]+\\s*[\\[({（]\\s*at\\s*[\\])}）]\\s*[A-Za-z0-9.-]+\\s*(?:[\\[({（]\\s*dot\\s*[\\])}）]|\\.)\\s*[A-Za-z]{2,}'', ''[연락처 비공개]'', ''gi'');\n  v_title := regexp_replace(v_title, ''\\y[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}\\y'', ''[연락처 비공개]'', ''gi'');\n  v_body  := regexp_replace(v_body,  ''\\y[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}\\y'', ''[연락처 비공개]'', ''gi'');\n  v_title := regexp_replace(v_title, ''\\y(?:open\\.kakao\\.com|kakaotalk\\.com|t\\.me|telegram\\.me|instagram\\.com|instagr\\.am|linktr\\.ee)(?:/[^\\s<>\"'''']*)?'', ''[연락처 비공개]'', ''gi'');\n  v_body  := regexp_replace(v_body,  ''\\y(?:open\\.kakao\\.com|kakaotalk\\.com|t\\.me|telegram\\.me|instagram\\.com|instagr\\.am|linktr\\.ee)(?:/[^\\s<>\"'''']*)?'', ''[연락처 비공개]'', ''gi'');\n  v_title := regexp_replace(v_title, ''(카카오톡|카톡|오픈채팅|텔레그램|인스타그램|인스타|디엠)\\s*[:：=]?\\s*@?[A-Za-z0-9._-]{4,}'', ''[연락처 비공개]'', ''g'');\n  v_body  := regexp_replace(v_body,  ''(카카오톡|카톡|오픈채팅|텔레그램|인스타그램|인스타|디엠)\\s*[:：=]?\\s*@?[A-Za-z0-9._-]{4,}'', ''[연락처 비공개]'', ''g'');\n\n  v_val := core_private.community_image_refs_validate(p_author_id, coalesce(p_image_refs, ''{}''::text[]));\n  IF NOT coalesce((v_val ->> ''ok'')::boolean, false) THEN\n    RETURN v_val;\n  END IF;\n\n  -- 제거된 ref 차집합 (클라이언트가 commit 후 best-effort 삭제 — §14.4)\n  v_removed := ARRAY(SELECT unnest(coalesce(v_post.image_urls, ''{}''::text[]))\n                     EXCEPT\n                     SELECT unnest(coalesce(p_image_refs, ''{}''::text[])));\n\n  UPDATE public.community_posts cp\n     SET title = v_title, body = v_body, content = v_body, category = p_category,\n         image_urls = coalesce(p_image_refs, ''{}''::text[]), status = p_status,\n         updated_at = now()\n   WHERE cp.id = p_post_id\n   RETURNING cp.updated_at INTO v_updated_at;\n\n  RETURN jsonb_build_object(''ok'', true, ''post_id'', p_post_id, ''updated_at'', v_updated_at,\n                            ''removed_image_refs'', to_jsonb(coalesce(v_removed, ''{}''::text[])));\nEND $fn$;\n\nCOMMENT ON FUNCTION core_private.community_post_update_impl(uuid, uuid, text, text, text, text[], text, timestamptz) IS\n  ''S3-C 보정 §2(M7 B-2 승계): 게시글 수정 공용 구현부 — **active student + active mentor** 자기 글 수정 허용(admin·unknown = ROLE_NOT_ALLOWED, 승인 요구 없음) · 소유·낙관 충돌·마스킹·B-4 검증·removed_image_refs. 외부 EXECUTE 0.'';\n\n-- -----------------------------------------------------------------------------\n-- D-3. 보정 §3(범위 H) — 질문방 서버 차단·계정 상태 게이트\n-- -----------------------------------------------------------------------------\n-- S3-E 실측 결과 해소:\n--   - qna_append_message: 상호 차단 검사 없음 · banned 만 검사(suspended/삭제 누락)\n--   - qna_register_attachment: 계정 상태 검사 자체가 없음 · 상호 차단 검사 없음\n-- 게이트 위치: **방 당사자를 확정한 직후**(v_is_mentor 결정 후), THREAD_LOCKED ·\n--   mentor approval · 구독/환불 · storage 검증 · 어떤 INSERT/상태 전이보다도 먼저.\n--   → 차단 시 message row 0 · attachment row 0 · answered 전이 0 · 알림 0 이 보장된다\n--     (알림은 question_messages/question_attachments AFTER INSERT 트리거이므로\n--      INSERT 에 도달하지 않으면 발화 자체가 없다).\n-- 오류코드(모두 RAISE — 두 함수의 기존 규약과 동일):\n--   ACCOUNT_BANNED · ACCOUNT_SUSPENDED · ACCOUNT_DELETION_IN_PROGRESS · BLOCKED\n--   + ACCOUNT_NOT_ACTIVE — users 자기 행 부재 / status 가 active·suspended 외\n--     (deleted·unknown·NULL). 지시서 4종으로는 \"자기 행 존재\" 요구를 표현할 수 없어\n--     fail-closed 코드 1종을 신설했다(계약 문서 §7 에 기록).\n-- 그 외 본문은 2026-08-02 운영 pg_get_functiondef 실측과 **문자 그대로 동일**하다 —\n--   thread FOR UPDATE · THREAD_NOT_FOUND · NOT_ROOM_PARTY · THREAD_LOCKED ·\n--   mentor approval · 구독 FOR UPDATE + live pending refund 게이트 ·\n--   storage path/소유권 검증 · message·thread 정합 · INSERT · answered 전이 ·\n--   반환 envelope · SECDEF · search_path=''public'' · ACL.\nCREATE OR REPLACE FUNCTION public.qna_append_message(p_thread_id uuid, p_body text)\nRETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''public'' AS $function$\ndeclare\n  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_status text; v_thread_status text;\n  v_first_answered timestamptz; v_message_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_sub_id uuid;\n  v_susp timestamptz; v_norm text;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_body is null or btrim(p_body)='''' then raise exception ''BODY_REQUIRED''; end if;\n  select t.mentor_student_room_id, t.status, t.first_answered_at into v_room, v_thread_status, v_first_answered\n    from public.question_threads t where t.id=p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;\n  if v_uid=v_mentor then v_is_mentor:=true; elsif v_uid=v_student then v_is_mentor:=false; else raise exception ''NOT_ROOM_PARTY''; end if;\n\n  -- [S3-C 보정 §3] 당사자 확정 직후 — 계정 상태 4종 + 상호 차단. 이 아래로는\n  -- 어떤 INSERT·상태 전이도 없으므로 차단 시 부수효과 0 이다.\n  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id=v_uid;\n  if not found then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  v_norm := lower(btrim(coalesce(v_status,'''')));\n  if v_norm=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if v_norm=''suspended'' and (v_susp is null or v_susp > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if v_norm not in (''active'',''suspended'') then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  if public.account_deletion_write_blocked(v_uid) then raise exception ''ACCOUNT_DELETION_IN_PROGRESS''; end if;\n  if public.qna_users_blocked(v_student, v_mentor) then raise exception ''BLOCKED''; end if;\n\n  if v_thread_status in (''confirmed'',''closed'',''archived'') then raise exception ''THREAD_LOCKED''; end if;\n  if v_is_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  -- 학생 후속 메시지: 활성 구독 FOR UPDATE + live pending refund 게이트(142 유지).\n  if not v_is_mentor then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n  end if;\n\n  -- F2(D-12)+R1: 아래 INSERT 가 AFTER INSERT 알림 트리거를 발화 — 멘토 메시지 행 1건 = 알림 정확히 1건.\n  insert into public.question_messages (thread_id, author_id, body) values (p_thread_id, v_uid, btrim(p_body)) returning id into v_message_id;\n  if v_is_mentor and v_first_answered is null then\n    update public.question_threads set status=''answered'', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;\n    v_transitioned := true;\n  end if;\n  return jsonb_build_object(''ok'',true,''message_id'',v_message_id,''answered_transition'',v_transitioned);\nend; $function$;\n\nCOMMENT ON FUNCTION public.qna_append_message(uuid, text) IS\n  ''S3-C 보정 §3: 질문방 메시지 추가 — 당사자 확정 직후 계정 상태(ACCOUNT_NOT_ACTIVE/ACCOUNT_BANNED/ACCOUNT_SUSPENDED/ACCOUNT_DELETION_IN_PROGRESS) + 상호 차단(BLOCKED) 게이트. 그 외 thread lock·mentor approval·구독/환불·알림 트리거 의미 전부 보존.'';\n\nREVOKE ALL ON FUNCTION public.qna_append_message(uuid, text) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.qna_append_message(uuid, text) TO authenticated, service_role;\n\nCREATE OR REPLACE FUNCTION public.qna_register_attachment(\n  p_thread_id uuid, p_storage_path text, p_file_name text DEFAULT NULL::text,\n  p_mime_type text DEFAULT NULL::text, p_message_id uuid DEFAULT NULL::uuid\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''public'' AS $function$\ndeclare\n  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_thread_status text;\n  v_first_answered timestamptz; v_att_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_sub_id uuid;\n  v_status text; v_susp timestamptz; v_norm text;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_storage_path is null or btrim(p_storage_path)='''' then raise exception ''STORAGE_PATH_REQUIRED''; end if;\n  select t.mentor_student_room_id, t.status, t.first_answered_at into v_room, v_thread_status, v_first_answered\n    from public.question_threads t where t.id=p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;\n  if v_uid=v_mentor then v_is_mentor:=true; elsif v_uid=v_student then v_is_mentor:=false; else raise exception ''NOT_ROOM_PARTY''; end if;\n\n  -- [S3-C 보정 §3] 당사자 확정 직후 — 계정 상태 4종 + 상호 차단(종전 계정 검사 전무).\n  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id=v_uid;\n  if not found then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  v_norm := lower(btrim(coalesce(v_status,'''')));\n  if v_norm=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if v_norm=''suspended'' and (v_susp is null or v_susp > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if v_norm not in (''active'',''suspended'') then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  if public.account_deletion_write_blocked(v_uid) then raise exception ''ACCOUNT_DELETION_IN_PROGRESS''; end if;\n  if public.qna_users_blocked(v_student, v_mentor) then raise exception ''BLOCKED''; end if;\n\n  if v_thread_status in (''confirmed'',''closed'',''archived'') then raise exception ''THREAD_LOCKED''; end if;\n  -- [S3-C 보정 2차 §2] 미승인 멘토가 **첨부-only 답변**으로 승인 게이트를 우회하지 못하게 한다.\n  --   attachment INSERT · answered 전이 · first_answered_at 기록 · 알림 트리거보다 앞이며,\n  --   append 와 동일한 코드·동일한 판정기를 쓴다(THREAD_LOCKED 우선순위는 유지).\n  if v_is_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  if p_storage_path not like (v_room::text || ''/'' || p_thread_id::text || ''/%'') then raise exception ''STORAGE_PATH_MISMATCH''; end if;\n  if not exists (select 1 from storage.objects o where o.bucket_id=''question-room-attachments'' and o.name = btrim(p_storage_path) and o.owner_id = v_uid::text) then raise exception ''STORAGE_OBJECT_NOT_OWNED''; end if;\n  if p_message_id is not null and not exists (select 1 from public.question_messages m where m.id=p_message_id and m.thread_id=p_thread_id) then raise exception ''MESSAGE_THREAD_MISMATCH''; end if;\n  if not v_is_mentor then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n  end if;\n\n  -- F2(D-12)+R1: 아래 INSERT 가 AFTER INSERT 알림 트리거를 발화 — 멘토 단독 첨부 행 1건 = 알림 정확히 1건.\n  insert into public.question_attachments (thread_id, message_id, author_id, storage_path, file_name, mime_type)\n  values (p_thread_id, p_message_id, v_uid, btrim(p_storage_path), p_file_name, p_mime_type) returning id into v_att_id;\n  if v_is_mentor and v_first_answered is null then\n    update public.question_threads set status=''answered'', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;\n    v_transitioned := true;\n  end if;\n  return jsonb_build_object(''ok'',true,''attachment_id'',v_att_id,''answered_transition'',v_transitioned);\nend; $function$;\n\nCOMMENT ON FUNCTION public.qna_register_attachment(uuid, text, text, text, uuid) IS\n  ''S3-C 보정 §3+2차 §2: 질문방 첨부 등록 — 당사자 확정 직후 계정 상태 + 상호 차단 게이트(종전 계정 검사 전무) + 미승인 멘토 첨부-only 답변 차단(MENTOR_NOT_APPROVED). 그 외 thread lock·storage path/소유권·message 정합·구독/환불·알림 트리거 의미 전부 보존.'';\n\nREVOKE ALL ON FUNCTION public.qna_register_attachment(uuid, text, text, text, uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.qna_register_attachment(uuid, text, text, text, uuid) TO authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- E. 범위 B — 직접 UGC write 정책에 계정 상태 게이트 결합\n-- -----------------------------------------------------------------------------\n-- 원 조건식은 문자 그대로 보존하고 `AND (SELECT public.ugc_write_allowed())` 만 결합한다.\n-- (SELECT ...) 래핑은 Supabase 정본 idiom — 행마다 재평가하지 않고 InitPlan 1회로 접는다.\n\n-- E-1. comments INSERT / UPDATE\nDROP POLICY IF EXISTS \"comments_insert_own\" ON public.comments;\nCREATE POLICY \"comments_insert_own\" ON public.comments\n  FOR INSERT TO authenticated\n  WITH CHECK (author_id = (SELECT auth.uid()) AND (SELECT public.ugc_write_allowed()));\n\nDROP POLICY IF EXISTS \"comments_update_own\" ON public.comments;\nCREATE POLICY \"comments_update_own\" ON public.comments\n  FOR UPDATE TO authenticated\n  USING (author_id = (SELECT auth.uid()) AND (SELECT public.ugc_write_allowed()))\n  WITH CHECK (author_id = (SELECT auth.uid()) AND (SELECT public.ugc_write_allowed()));\n\n-- E-2. community_comments INSERT (본문 길이 1~1000 조건 보존)\nDROP POLICY IF EXISTS \"community_comments_insert_authenticated\" ON public.community_comments;\nCREATE POLICY \"community_comments_insert_authenticated\" ON public.community_comments\n  FOR INSERT TO authenticated\n  WITH CHECK (\n    author_id = (SELECT auth.uid())\n    AND (SELECT auth.uid()) IS NOT NULL\n    AND char_length(btrim(body)) >= 1\n    AND char_length(btrim(body)) <= 1000\n    AND (SELECT public.ugc_write_allowed())\n  );\n\n-- E-3. post_reactions INSERT / DELETE\n--   한글명 중복 정책 2종은 permissive OR 로 게이트를 무력화한다. 두 정책의 조건은\n--   `auth.uid() = user_id` 로 authenticated 정책의 **진부분집합**이므로, 제거해도\n--   정당 사용자가 잃는 권한은 없다(role=public 의 anon 분기는 auth.uid() NULL 로 이미 사문).\nDROP POLICY IF EXISTS \"로그인 유저 반응 추가\" ON public.post_reactions;\nDROP POLICY IF EXISTS \"본인 반응 삭제\"        ON public.post_reactions;\n\nDROP POLICY IF EXISTS \"post_reactions_insert_own\" ON public.post_reactions;\nCREATE POLICY \"post_reactions_insert_own\" ON public.post_reactions\n  FOR INSERT TO authenticated\n  WITH CHECK (user_id = (SELECT auth.uid()) AND (SELECT public.ugc_write_allowed()));\n\nDROP POLICY IF EXISTS \"post_reactions_delete_own\" ON public.post_reactions;\nCREATE POLICY \"post_reactions_delete_own\" ON public.post_reactions\n  FOR DELETE TO authenticated\n  USING (user_id = (SELECT auth.uid()) AND (SELECT public.ugc_write_allowed()));\n\n-- E-4. shortform_reactions INSERT / DELETE (type 허용값 조건 보존)\nDROP POLICY IF EXISTS \"shortform_reactions_insert_own\" ON public.shortform_reactions;\nCREATE POLICY \"shortform_reactions_insert_own\" ON public.shortform_reactions\n  FOR INSERT TO authenticated\n  WITH CHECK (\n    user_id = (SELECT auth.uid())\n    AND type = ANY (ARRAY[''like''::text, ''scrap''::text])\n    AND (SELECT public.ugc_write_allowed())\n  );\n\nDROP POLICY IF EXISTS \"shortform_reactions_delete_own\" ON public.shortform_reactions;\nCREATE POLICY \"shortform_reactions_delete_own\" ON public.shortform_reactions\n  FOR DELETE TO authenticated\n  USING (user_id = (SELECT auth.uid()) AND (SELECT public.ugc_write_allowed()));\n\n-- -----------------------------------------------------------------------------\n-- F. 범위 C — content_reports 필드 무결성\n-- -----------------------------------------------------------------------------\n-- 커스텀 REST 호출이 관리 필드를 실어 보내면 WITH CHECK 위반(42501)으로 **명시 거부**한다\n--   (조용한 정규화 대신 거부 — 위조 시도가 성공한 것처럼 보이지 않게 한다).\n-- status 는 DEFAULT ''pending'' 이므로 정상 클라이언트(필드 미지정)는 영향 없다.\n-- target_type 은 화이트리스트로 고정한다 — 임의 자유 텍스트 확장 금지(S3-E 계약).\n--   허용값: community_post · shortform · shortform_post · community_comment ·\n--           board_comment · user\n--   ''user'' 는 질문방 신고(S3-E)가 사용할 값이다. DB 제약은 nonempty 뿐이라 별도\n--   CHECK 추가 없이 이미 저장 가능하며(관리자 콘솔은 normalize 실패 시 신고 상태만\n--   변경 — lib/admin/communityModerationCore.ts), 본 정책이 그 집합의 정본이다.\n-- [보정 §4] target_type=''user'' 일 때만 추가로 대상 무결성을 강제한다 —\n--   자기 신고 금지 + 대상 사용자 실재(public.report_target_user_valid).\n--   다른 target_type 계약은 그대로 유지한다(대상 실재 검사 없음 — 콘텐츠 신고는\n--   soft-delete·삭제 레이스에서 접수 자체가 막히면 안 되기 때문).\n-- **계정 상태 게이트는 붙이지 않는다** — 신고는 과잉 차단 금지 대상(지시서 §3).\n--   banned reporter 도 정상 상대를 신고할 수 있다.\nDROP POLICY IF EXISTS \"content_reports_insert_reporter\" ON public.content_reports;\nCREATE POLICY \"content_reports_insert_reporter\" ON public.content_reports\n  FOR INSERT TO authenticated\n  WITH CHECK (\n    reporter_id = (SELECT auth.uid())\n    AND status = ''pending''\n    AND admin_note IS NULL\n    AND resolved_by IS NULL\n    AND resolved_at IS NULL\n    AND target_type = ANY (ARRAY[''community_post''::text, ''shortform''::text, ''shortform_post''::text,\n                                 ''community_comment''::text, ''board_comment''::text, ''user''::text])\n    AND (target_type <> ''user'' OR public.report_target_user_valid(target_id))\n  );\n\n-- -----------------------------------------------------------------------------\n-- G. 범위 E — latent custom-order 공개 SELECT 정책 제거\n-- -----------------------------------------------------------------------------\n-- 4종 모두 `USING (true)` · role=public 이라 **anon 포함 전원이 전 행을 읽는다**.\n-- 당사자·관리자 정책(cdel_select · cmsg_all_party · cra_select · crp_select)은\n-- 그대로 두므로 정당 경로는 불변이다. 현재 행 수가 0이라는 사실에는 의존하지 않는다\n-- (섹션 A ⑦ 에서 identity 를 단언했고, 여기서는 그 4종만 정확히 제거한다).\nDROP POLICY IF EXISTS \"누구나 납품 읽기\"     ON public.custom_order_deliverables;\nDROP POLICY IF EXISTS \"누구나 메시지 읽기\"   ON public.custom_order_messages;\nDROP POLICY IF EXISTS \"누구나 지원서 읽기\"   ON public.custom_request_applications;\nDROP POLICY IF EXISTS \"누구나 의뢰 읽기\"     ON public.custom_request_posts;\n\n-- -----------------------------------------------------------------------------\n-- H. 적용 직후 자가 검증 (최종 상태 보증)\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE\n  v_cnt int;\n  v_src text;\nBEGIN\n  -- ① 범위 A — 구현부 본문 계약\n  SELECT p.prosrc INTO v_src FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''core_private'' AND p.proname = ''community_post_create_impl'';\n  IF v_src IS NULL\n     OR position(''ROLE_NOT_ALLOWED'' IN v_src) = 0\n     OR position(''MENTOR_NOT_APPROVED'' IN v_src) > 0\n     OR position(''ROLE_NOT_MENTOR'' IN v_src) > 0 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: create_impl 역할 계약 수렴 실패'';\n  END IF;\n  -- 보존 불변 — replay-first · 멱등 · 계정 3상태 · 검증 · 마스킹 · 이미지 · author 도출\n  IF position(''create_idempotency_key'' IN v_src) = 0\n     OR position(''idempotent_replay'' IN v_src) = 0\n     OR position(''ON CONFLICT (author_id, create_idempotency_key) DO NOTHING'' IN v_src) = 0\n     OR position(''ACCOUNT_BANNED'' IN v_src) = 0\n     OR position(''ACCOUNT_SUSPENDED'' IN v_src) = 0\n     OR position(''ACCOUNT_DELETION_IN_PROGRESS'' IN v_src) = 0\n     -- [보정 2차 §1] 계정 상태 positive allowlist (fail-open 잔재 0)\n     OR position(''ACCOUNT_NOT_ACTIVE'' IN v_src) = 0\n     OR position(''v_norm = ''''active'''''' IN v_src) = 0\n     OR position(''coalesce(v_status, ''''active'''')'' IN v_src) > 0\n     OR position(''TITLE_REQUIRED'' IN v_src) = 0\n     OR position(''CATEGORY_INVALID'' IN v_src) = 0\n     OR position(''BODY_TOO_SHORT'' IN v_src) = 0\n     OR position(''[연락처 비공개]'' IN v_src) = 0\n     OR position(''community_image_refs_validate'' IN v_src) = 0\n     OR position(''author_label'' IN v_src) = 0\n     OR position(''author_role'' IN v_src) = 0 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: create_impl 보존 불변 손실'';\n  END IF;\n  -- 구현부 하드닝 불변 (INVOKER + search_path + 외부 EXECUTE 0)\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''core_private'' AND p.proname = ''community_post_create_impl''\n                    AND NOT p.prosecdef AND p.proconfig::text LIKE ''%search_path=%''\n                    AND NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n                    AND NOT has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n                    AND NOT has_function_privilege(''service_role'', p.oid, ''EXECUTE'')) THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: create_impl 하드닝(INVOKER·search_path·외부 EXECUTE 0) 손실'';\n  END IF;\n  -- wrapper 시그니처 불변 (web·app 2종)\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname IN (''api_web_v1'', ''api_app_v1'') AND p.proname = ''community_post_create''\n         AND pg_get_function_identity_arguments(p.oid)\n             = ''p_title text, p_body text, p_category text, p_idempotency_key uuid, p_image_refs text[], p_status text''\n         AND p.prosecdef AND has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')) <> 2 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: community_post_create wrapper 시그니처·권한 변동'';\n  END IF;\n\n  -- ①-2 보정 §2(범위 G) — update 구현부 역할 계약 + 보존 불변\n  SELECT p.prosrc INTO v_src FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''core_private'' AND p.proname = ''community_post_update_impl'';\n  IF v_src IS NULL\n     OR position(''ROLE_NOT_ALLOWED'' IN v_src) = 0\n     OR position(''MENTOR_NOT_APPROVED'' IN v_src) > 0\n     OR position(''ROLE_NOT_MENTOR'' IN v_src) > 0 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: update_impl 역할 계약 수렴 실패'';\n  END IF;\n  IF position(''FOR UPDATE'' IN v_src) = 0\n     OR position(''UPDATE_CONFLICT'' IN v_src) = 0\n     OR position(''p_expected_updated_at'' IN v_src) = 0\n     OR position(''POST_NOT_FOUND_OR_NOT_OWNED'' IN v_src) = 0\n     OR position(''removed_image_refs'' IN v_src) = 0\n     OR position(''[연락처 비공개]'' IN v_src) = 0\n     OR position(''community_image_refs_validate'' IN v_src) = 0\n     OR position(''ACCOUNT_BANNED'' IN v_src) = 0\n     OR position(''ACCOUNT_SUSPENDED'' IN v_src) = 0\n     OR position(''ACCOUNT_DELETION_IN_PROGRESS'' IN v_src) = 0\n     -- [보정 2차 §1] create 와 동일한 positive allowlist\n     OR position(''ACCOUNT_NOT_ACTIVE'' IN v_src) = 0\n     OR position(''v_norm = ''''active'''''' IN v_src) = 0\n     OR position(''coalesce(v_status, ''''active'''')'' IN v_src) > 0 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: update_impl 보존 불변·allowlist 손실'';\n  END IF;\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname IN (''api_web_v1'', ''api_app_v1'') AND p.proname = ''community_post_update''\n         AND pg_get_function_identity_arguments(p.oid)\n             = ''p_post_id uuid, p_title text, p_body text, p_category text, p_expected_updated_at timestamp with time zone, p_image_refs text[], p_status text''\n         AND p.prosecdef AND has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')) <> 2 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: community_post_update wrapper 시그니처·권한 변동'';\n  END IF;\n\n  -- ①-3 보정 §3(범위 H) — 질문방 RPC 게이트 + 보존 불변\n  SELECT p.prosrc INTO v_src FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''public'' AND p.proname = ''qna_append_message'';\n  IF v_src IS NULL\n     OR position(''qna_users_blocked'' IN v_src) = 0\n     OR position(''BLOCKED'' IN v_src) = 0\n     OR position(''ACCOUNT_SUSPENDED'' IN v_src) = 0\n     OR position(''ACCOUNT_DELETION_IN_PROGRESS'' IN v_src) = 0\n     OR position(''ACCOUNT_NOT_ACTIVE'' IN v_src) = 0\n     OR position(''ACCOUNT_BANNED'' IN v_src) = 0\n     -- 보존 불변\n     OR position(''for update'' IN v_src) = 0\n     OR position(''NOT_ROOM_PARTY'' IN v_src) = 0\n     OR position(''THREAD_LOCKED'' IN v_src) = 0\n     OR position(''MENTOR_NOT_APPROVED'' IN v_src) = 0\n     OR position(''SUBSCRIPTION_REFUND_PENDING'' IN v_src) = 0\n     OR position(''insert into public.question_messages'' IN v_src) = 0\n     OR position(''answered_transition'' IN v_src) = 0 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: qna_append_message 게이트·보존 불변 불일치'';\n  END IF;\n  -- 게이트가 INSERT 보다 앞에 있어야 한다(부수효과 0 보장)\n  IF position(''qna_users_blocked'' IN v_src) > position(''insert into public.question_messages'' IN v_src) THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: qna_append_message 차단 게이트가 INSERT 뒤에 있다'';\n  END IF;\n\n  SELECT p.prosrc INTO v_src FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''public'' AND p.proname = ''qna_register_attachment'';\n  IF v_src IS NULL\n     OR position(''qna_users_blocked'' IN v_src) = 0\n     OR position(''BLOCKED'' IN v_src) = 0\n     OR position(''ACCOUNT_BANNED'' IN v_src) = 0\n     OR position(''ACCOUNT_SUSPENDED'' IN v_src) = 0\n     OR position(''ACCOUNT_DELETION_IN_PROGRESS'' IN v_src) = 0\n     OR position(''ACCOUNT_NOT_ACTIVE'' IN v_src) = 0\n     -- 보존 불변\n     OR position(''for update'' IN v_src) = 0\n     OR position(''NOT_ROOM_PARTY'' IN v_src) = 0\n     OR position(''THREAD_LOCKED'' IN v_src) = 0\n     OR position(''STORAGE_PATH_MISMATCH'' IN v_src) = 0\n     OR position(''STORAGE_OBJECT_NOT_OWNED'' IN v_src) = 0\n     OR position(''MESSAGE_THREAD_MISMATCH'' IN v_src) = 0\n     OR position(''SUBSCRIPTION_REFUND_PENDING'' IN v_src) = 0\n     OR position(''insert into public.question_attachments'' IN v_src) = 0\n     OR position(''answered_transition'' IN v_src) = 0\n     -- [보정 2차 §2] 첨부-only 답변의 멘토 승인 게이트\n     OR position(''MENTOR_NOT_APPROVED'' IN v_src) = 0\n     OR position(''individual_question_user_is_approved_mentor'' IN v_src) = 0 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: qna_register_attachment 게이트·보존 불변 불일치'';\n  END IF;\n  IF position(''qna_users_blocked'' IN v_src) > position(''insert into public.question_attachments'' IN v_src)\n     OR position(''MENTOR_NOT_APPROVED'' IN v_src) > position(''insert into public.question_attachments'' IN v_src) THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: qna_register_attachment 차단·승인 게이트가 INSERT 뒤에 있다'';\n  END IF;\n  -- 두 RPC 의 SECDEF·search_path·ACL 불변\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n       WHERE n.nspname = ''public'' AND p.proname IN (''qna_append_message'', ''qna_register_attachment'')\n         AND p.prosecdef AND p.proconfig::text LIKE ''%search_path=%''\n         AND has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n         AND has_function_privilege(''service_role'', p.oid, ''EXECUTE'')\n         AND NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')) <> 2 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: qna RPC 2종 SECDEF·search_path·ACL 불일치'';\n  END IF;\n\n  -- ② 직접 INSERT/UPDATE 잠금 유지 (미복구 증명)\n  IF has_table_privilege(''authenticated'', ''public.community_posts'', ''INSERT'')\n     OR has_table_privilege(''authenticated'', ''public.community_posts'', ''UPDATE'')\n     OR has_table_privilege(''anon'', ''public.community_posts'', ''INSERT'')\n     OR has_table_privilege(''anon'', ''public.community_posts'', ''UPDATE'')\n     OR (SELECT count(*) FROM pg_policies\n          WHERE schemaname = ''public'' AND tablename = ''community_posts''\n            AND cmd IN (''INSERT'', ''UPDATE'', ''DELETE'')) <> 0 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: community_posts 직접 쓰기 권한이 복구됨(금지)'';\n  END IF;\n\n  -- ③ 범위 D — self 제한 + 권한 매트릭스\n  SELECT p.prosrc INTO v_src FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''public'' AND p.proname = ''account_deletion_write_blocked'';\n  IF v_src IS NULL OR position(''ACCOUNT_DELETION_PROBE_FORBIDDEN'' IN v_src) = 0 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: account_deletion_write_blocked self 제한 미적용'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''public'' AND p.proname = ''account_deletion_write_blocked''\n                    AND p.prosecdef AND p.proconfig::text LIKE ''%search_path=%''\n                    AND has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n                    AND has_function_privilege(''service_role'', p.oid, ''EXECUTE'')\n                    AND NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')) THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: account_deletion_write_blocked 권한 매트릭스 불일치'';\n  END IF;\n\n  -- ④ 범위 B — helper 하드닝 + 게이트 결합 정책 7종\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''public'' AND p.proname = ''ugc_write_allowed''\n                    AND pg_get_function_identity_arguments(p.oid) = ''''\n                    AND p.prosecdef AND p.proconfig::text LIKE ''%search_path=%''\n                    AND has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n                    AND NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n                    AND (p.proacl IS NULL OR (p.proacl::text NOT LIKE ''{=%'' AND p.proacl::text NOT LIKE ''%,=%''))) THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: ugc_write_allowed() 하드닝·권한 불일치'';\n  END IF;\n  -- ④-2 보정 §1 — helper 가 fail-closed 허용 목록 형태인지(부정 목록 잔재 0)\n  SELECT p.prosrc INTO v_src FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''public'' AND p.proname = ''ugc_write_allowed'';\n  IF v_src IS NULL\n     OR position(''EXISTS'' IN v_src) = 0\n     OR position(''NOT EXISTS'' IN v_src) > 0                      -- 구 \"차단 목록\" 구현 잔재\n     OR position(''u.role IN (''''student'''', ''''mentor'''')'' IN v_src) = 0\n     OR position(''''''active'''''' IN v_src) = 0\n     OR position(''u.suspended_until IS NOT NULL'' IN v_src) = 0\n     OR position(''account_deletion_write_blocked'' IN v_src) = 0 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: ugc_write_allowed() 가 fail-closed 허용 목록이 아니다'';\n  END IF;\n  -- ④-3 보정 §4 — report_target_user_valid 하드닝·권한\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''public'' AND p.proname = ''report_target_user_valid''\n                    AND pg_get_function_identity_arguments(p.oid) = ''p_target_id uuid''\n                    AND p.prosecdef AND p.proconfig::text LIKE ''%search_path=%''\n                    AND has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n                    AND NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n                    AND (p.proacl IS NULL OR (p.proacl::text NOT LIKE ''{=%'' AND p.proacl::text NOT LIKE ''%,=%''))) THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: report_target_user_valid(uuid) 하드닝·권한 불일치'';\n  END IF;\n  SELECT count(*) INTO v_cnt FROM pg_policies\n   WHERE schemaname = ''public''\n     AND (tablename, policyname) IN\n         ((''comments'',            ''comments_insert_own''),\n          (''comments'',            ''comments_update_own''),\n          (''community_comments'',  ''community_comments_insert_authenticated''),\n          (''post_reactions'',      ''post_reactions_insert_own''),\n          (''post_reactions'',      ''post_reactions_delete_own''),\n          (''shortform_reactions'', ''shortform_reactions_insert_own''),\n          (''shortform_reactions'', ''shortform_reactions_delete_own''))\n     AND roles::text = ''{authenticated}''\n     AND coalesce(qual, '''') || coalesce(with_check, '''') LIKE ''%ugc_write_allowed%'';\n  IF v_cnt <> 7 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: UGC 상태 게이트 결합 정책 7종 미충족(matched %/7)'', v_cnt;\n  END IF;\n  -- 중복 우회 경로 0 — post_reactions 쓰기 정책은 authenticated 2종만 남는다\n  IF (SELECT count(*) FROM pg_policies\n       WHERE schemaname = ''public'' AND tablename = ''post_reactions''\n         AND cmd IN (''INSERT'', ''UPDATE'', ''DELETE'')) <> 2 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: post_reactions 쓰기 정책 우회 경로 잔존'';\n  END IF;\n  -- 과잉 차단 금지 — 신고·차단·계정삭제 경로에는 게이트가 붙지 않았다\n  IF EXISTS (SELECT 1 FROM pg_policies\n              WHERE schemaname = ''public'' AND tablename IN (''content_reports'', ''user_blocks'')\n                AND coalesce(qual, '''') || coalesce(with_check, '''') LIKE ''%ugc_write_allowed%'') THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: 신고·차단 경로에 UGC 게이트가 잘못 결합됨(과잉 차단)'';\n  END IF;\n\n  -- ⑤ 범위 C — 관리 필드 강제 + 관리자 UPDATE 보존\n  SELECT coalesce(with_check, '''') INTO v_src FROM pg_policies\n   WHERE schemaname = ''public'' AND tablename = ''content_reports''\n     AND policyname = ''content_reports_insert_reporter'';\n  IF v_src IS NULL\n     OR v_src NOT LIKE ''%reporter_id%''\n     OR v_src NOT LIKE ''%pending%''\n     OR v_src NOT LIKE ''%admin_note IS NULL%''\n     OR v_src NOT LIKE ''%resolved_by IS NULL%''\n     OR v_src NOT LIKE ''%resolved_at IS NULL%''\n     OR v_src NOT LIKE ''%target_type%''\n     OR v_src NOT LIKE ''%report_target_user_valid%'' THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: content_reports INSERT 필드·user 대상 무결성 강제 불일치'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_policies\n                  WHERE schemaname = ''public'' AND tablename = ''content_reports''\n                    AND policyname = ''content_reports_update_admin'' AND cmd = ''UPDATE'') THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: content_reports 관리자 UPDATE 경로 유실'';\n  END IF;\n\n  -- ⑥ 범위 E — 공개 정책 0 · 당사자 정책 4종 유지\n  IF (SELECT count(*) FROM pg_policies\n       WHERE schemaname = ''public''\n         AND tablename IN (''custom_order_deliverables'', ''custom_order_messages'',\n                           ''custom_request_applications'', ''custom_request_posts'')\n         AND cmd = ''SELECT'' AND roles::text = ''{public}'') <> 0 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: custom_* public SELECT 정책 잔존'';\n  END IF;\n  IF (SELECT count(*) FROM pg_policies\n       WHERE schemaname = ''public'' AND cmd = ''SELECT''\n         AND (tablename, policyname) IN\n             ((''custom_order_deliverables'',   ''cdel_select''),\n              (''custom_order_messages'',       ''cmsg_all_party''),\n              (''custom_request_applications'', ''cra_select''),\n              (''custom_request_posts'',        ''crp_select''))) <> 4 THEN\n    RAISE EXCEPTION ''S3C_SELFCHECK: custom_* 당사자·관리자 SELECT 정책이 함께 제거됨'';\n  END IF;\nEND $$;\n\ncommit;"], "idempotency_key": null}, {"name": "iq_append_message_v1", "version": "20260803142534", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- 개별질문 양방향 대화 RPC. qna_append_message 와 동일한 계정·차단 게이트를 적용하고,\n-- 당사자(학생·지정/선점 멘토) 모두 메시지를 보낼 수 있게 한다.\n-- 멘토의 첫 메시지는 기존 answer_individual_question 과 동일하게 answered 전이를 수행한다.\ncreate or replace function public.iq_append_message(p_question_id uuid, p_body text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_q public.individual_questions%rowtype;\n  v_mentor uuid;\n  v_is_mentor boolean;\n  v_status text; v_susp timestamptz; v_norm text;\n  v_message_id uuid;\n  v_transitioned boolean := false;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED'' using errcode = ''28000''; end if;\n  if coalesce(btrim(p_body), '''') = '''' then raise exception ''BODY_REQUIRED'' using errcode = ''22023''; end if;\n\n  select * into v_q from public.individual_questions where id = p_question_id for update;\n  if not found then raise exception ''QUESTION_NOT_FOUND'' using errcode = ''P0001''; end if;\n\n  v_mentor := coalesce(v_q.claimed_mentor_id, v_q.designated_mentor_id);\n  if v_uid = v_q.student_id then v_is_mentor := false;\n  elsif v_mentor is not null and v_uid = v_mentor then v_is_mentor := true;\n  else raise exception ''NOT_QUESTION_PARTY'' using errcode = ''42501'';\n  end if;\n\n  -- 계정 상태 4종 + 삭제 진행 + 상호 차단 (qna_append_message 와 동일 게이트)\n  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id = v_uid;\n  if not found then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  v_norm := lower(btrim(coalesce(v_status,'''')));\n  if v_norm = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if v_norm not in (''active'',''suspended'') then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  if public.account_deletion_write_blocked(v_uid) then raise exception ''ACCOUNT_DELETION_IN_PROGRESS''; end if;\n  if v_mentor is not null and public.qna_users_blocked(v_q.student_id, v_mentor) then raise exception ''BLOCKED''; end if;\n\n  -- 상태 게이트: 종결(released/refunded/expired/canceled)은 잠금.\n  -- escrowed(공개·미선점)는 멘토 미확정이라 학생만 추가 설명 가능.\n  if v_q.status in (''released'',''refunded'',''expired'',''canceled'') then\n    raise exception ''QUESTION_LOCKED'' using errcode = ''P0001'';\n  end if;\n  if v_q.status = ''escrowed'' and v_is_mentor then\n    raise exception ''NOT_ANSWERABLE_STATUS:%'', v_q.status using errcode = ''P0001'';\n  end if;\n  if v_is_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then\n    raise exception ''MENTOR_NOT_APPROVED'';\n  end if;\n\n  insert into public.individual_question_messages (question_id, author_id, body)\n  values (p_question_id, v_uid, btrim(p_body))\n  returning id into v_message_id;\n\n  -- 멘토 첫 답변 = answered 전이 (answer_individual_question 의 의미 보존)\n  if v_is_mentor and v_q.status in (''claimed'',''assigned'') then\n    update public.individual_questions\n      set status = ''answered'', answered_at = coalesce(answered_at, now())\n      where id = p_question_id;\n    v_transitioned := true;\n  end if;\n\n  return jsonb_build_object(''ok'', true, ''message_id'', v_message_id, ''answered_transition'', v_transitioned);\nend;\n$$;"], "idempotency_key": null}, {"name": "iq_attachment_author_v1", "version": "20260803142559", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- 첨부 귀속(누가 올렸는가) 기록. 기존 행은 author 미상(null) 유지 — 화면은 null 을\n-- 종전처럼 질문 말풍선 그룹으로 렌더한다.\nalter table public.individual_question_attachments\n  add column if not exists author_id uuid references public.users(id) on delete set null;\n\n-- add_individual_question_attachment: INSERT 시 auth.uid() 를 author_id 로 기록.\n-- 반환 계약(jsonb 키·의미)·멱등 계약(on conflict do nothing)·가드 순서는 전부 불변.\ncreate or replace function public.add_individual_question_attachment(p_question_id uuid, p_storage_path text, p_file_name text, p_mime_type text, p_message_id uuid default null::uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_uid  uuid := (select auth.uid());\n  v_path text;\n  v_id   uuid;\n  v_existing_message_id uuid;\n  v_created boolean := false;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  v_path := btrim(coalesce(p_storage_path, ''''));\n  if v_path = '''' then\n    raise exception ''INVALID_INPUT: storage_path is required'' using errcode = ''22023'';\n  end if;\n\n  if not public.user_is_individual_question_party(p_question_id) then\n    raise exception ''NOT_QUESTION_PARTY'' using errcode = ''42501'';\n  end if;\n\n  if split_part(v_path, ''/'', 1) <> p_question_id::text then\n    raise exception ''STORAGE_PATH_MISMATCH'' using errcode = ''22023'';\n  end if;\n\n  if p_message_id is not null and not exists (\n    select 1\n    from public.individual_question_messages m\n    where m.id = p_message_id\n      and m.question_id = p_question_id\n  ) then\n    raise exception ''MESSAGE_NOT_IN_QUESTION'' using errcode = ''22023'';\n  end if;\n\n  insert into public.individual_question_attachments\n    (question_id, message_id, storage_path, file_name, mime_type, author_id)\n  values\n    (p_question_id, p_message_id, v_path, p_file_name, p_mime_type, v_uid)\n  on conflict (question_id, storage_path) do nothing\n  returning id into v_id;\n\n  if v_id is not null then\n    v_created := true;\n  else\n    select a.id, a.message_id\n      into v_id, v_existing_message_id\n    from public.individual_question_attachments a\n    where a.question_id = p_question_id\n      and a.storage_path = v_path;\n\n    if v_id is null then\n      raise exception ''REGISTER_CONFLICT_UNRESOLVED'' using errcode = ''40001'';\n    end if;\n  end if;\n\n  return jsonb_build_object(\n    ''ok'',            true,\n    ''status'',        case when v_created then ''created'' else ''existing'' end,\n    ''idempotent_hit'', not v_created,\n    ''attachment_id'', v_id,\n    ''question_id'',   p_question_id,\n    ''storage_path'',  v_path,\n    ''message_id_mismatch'',\n      case when v_created then false\n           else coalesce(v_existing_message_id, ''00000000-0000-0000-0000-000000000000''::uuid)\n                is distinct from coalesce(p_message_id, ''00000000-0000-0000-0000-000000000000''::uuid)\n      end\n  );\nend;\n$$;"], "idempotency_key": null}, {"name": "20260803162257_security_identity_profile_lockdown", "version": "20260803170552", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260803162257_security_identity_profile_lockdown.sql (수렴 M1)\n-- =============================================================================\n-- 목적: 계정·프로필 보안 수렴 (지시서 §5 — 전체 작업의 최우선 P0).\n--   현재 결함: users_update_own 정책이 본인 행 **전체** UPDATE 를 허용하고,\n--   anon/authenticated 가 public.users 테이블 레벨 UPDATE 권한을 가진다.\n--   역할 변경 트리거(trg_users_role_guard)는 role 만 방어 → status/suspended_until/\n--   status_reason/status_changed_*/동의 시각을 사용자가 직접 Data API 로 변조 가능.\n--\n-- 이 migration 의 소유 객체 (§23.1):\n--   A. public.users 테이블 권한 회수 (anon: INSERT/UPDATE/DELETE/TRUNCATE/REFERENCES/TRIGGER,\n--      authenticated: UPDATE/DELETE/TRUNCATE/REFERENCES/TRIGGER — SELECT 및\n--      authenticated INSERT(가입 self-insert 정책 경로)는 유지)\n--   B. protected-column trigger: public.users_protected_columns_guard() +\n--      trg_users_protected_columns (defense-in-depth — 권한 회수와 독립적으로\n--      클라이언트 역할의 보호 컬럼 변경을 거부)\n--   C. users.status CHECK (active/suspended/banned/deleted — 사전 게이트에서\n--      위반 행 0 확인. ''deleted'' 는 anonymize_user_for_deletion 이 기록하는 정본값)\n--   D. core_private.user_profile_update_self_impl — self 프로필 수정 공용 정본\n--   E. api_app_v1.user_profile_update_self(p_nickname, p_grade_level) — 앱 self RPC\n--   F. api_web_v1.user_profile_update_self(p_nickname, p_grade_level) — 웹 self RPC\n--   G. api_web_v1.user_marketing_consent_set_self(p_agreed) — 마케팅 동의는 일반\n--      프로필 RPC 에 섞지 않는다(§5.6). 동의 원장(user_consent_records) append +\n--      users.marketing_agreed 반영을 단일 트랜잭션으로 수행.\n--\n-- null 의미 규약 (§5.4 \"null 구분\"):\n--   p_nickname:    null=기존값 유지 · ''''(trim 후 빈 값)=오류(NICKNAME_REQUIRED)\n--   p_grade_level: null=기존값 유지 · ''''(trim 후 빈 값)=값 제거(NULL 저장, 학생만)\n--\n-- grade_level 어휘: 제품 전체(웹 가입·앱 편집 \"예: 고2, 재수생\")에서 자유 텍스트다.\n--   폐쇄 어휘가 존재하지 않으므로 서버 검증은 trim + 최대 20자 + 학생 한정으로 강제\n--   (실측 근거: app profile_edit_screen.dart hint, users.grade_level 기존 자유값).\n--\n-- RLS 는 유지한다(defense-in-depth). 관리자 status 변경(service_role)·정본\n-- SECURITY DEFINER RPC 경로는 영향 없음 — 트리거는 클라이언트 역할(anon/\n-- authenticated, 비관리자)에서만 보호 컬럼 변경을 거부한다.\n--\n-- rollback 정본: supabase/rollback/20260803162257_security_identity_profile_lockdown_rollback.sql\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- 사전 게이트 — 불일치 시 수정 0건 중단\n-- -----------------------------------------------------------------------------\nDO $$\nBEGIN\n  -- ① users 필수 컬럼 존재\n  IF (SELECT count(*) FROM information_schema.columns\n       WHERE table_schema=''public'' AND table_name=''users''\n         AND column_name IN (''id'',''role'',''status'',''suspended_until'',''status_reason'',\n                             ''status_changed_at'',''status_changed_by'',''terms_agreed_at'',\n                             ''privacy_agreed_at'',''marketing_agreed'',''created_at'',\n                             ''nickname'',''grade_level'',''updated_at'')) <> 14 THEN\n    RAISE EXCEPTION ''M1_BASELINE_MISMATCH: users columns'';\n  END IF;\n  -- ② status CHECK 대상 외 값 0 (unknown status 허용 채 CHECK 금지 — §5.7)\n  IF EXISTS (SELECT 1 FROM public.users\n              WHERE lower(btrim(coalesce(status,''''))) NOT IN (''active'',''suspended'',''banned'',''deleted'')) THEN\n    RAISE EXCEPTION ''M1_BASELINE_MISMATCH: users.status outside allowlist — CHECK 추가 불가'';\n  END IF;\n  -- ③ 대상 스키마 존재 (M17/api_web_v1 시리즈 선행)\n  IF (SELECT count(*) FROM pg_namespace WHERE nspname IN (''api_app_v1'',''api_web_v1'',''core_private'')) <> 3 THEN\n    RAISE EXCEPTION ''M1_BASELINE_MISMATCH: api schemas missing'';\n  END IF;\n  -- ④ 신규 객체 선점 없음\n  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace\n              WHERE (n.nspname,p.proname) IN ((''api_app_v1'',''user_profile_update_self''),\n                                              (''api_web_v1'',''user_profile_update_self''),\n                                              (''api_web_v1'',''user_marketing_consent_set_self''),\n                                              (''core_private'',''user_profile_update_self_impl''),\n                                              (''public'',''users_protected_columns_guard''))) THEN\n    RAISE EXCEPTION ''M1_BASELINE_MISMATCH: target function already exists'';\n  END IF;\n  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''public.users''::regclass AND conname=''users_status_allowed'') THEN\n    RAISE EXCEPTION ''M1_BASELINE_MISMATCH: users_status_allowed already exists'';\n  END IF;\n  -- ⑤ consent 원장 계약 (marketing 허용 + actor ''user'')\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint\n                  WHERE conrelid=''public.user_consent_records''::regclass\n                    AND conname=''user_consent_records_consent_type_check''\n                    AND pg_get_constraintdef(oid) LIKE ''%marketing%'') THEN\n    RAISE EXCEPTION ''M1_BASELINE_MISMATCH: user_consent_records marketing consent type'';\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- A. users 테이블 권한 회수\n--    (SELECT 는 RLS(users_select_own/users_admin_select_all) 게이트로 유지,\n--     authenticated INSERT 는 users_insert_own 가입 경로로 유지)\n-- -----------------------------------------------------------------------------\nrevoke insert, update, delete, truncate, references, trigger on table public.users from anon;\nrevoke update, delete, truncate, references, trigger on table public.users from authenticated;\n\n-- -----------------------------------------------------------------------------\n-- B. protected-column trigger (defense-in-depth)\n--    클라이언트 역할(anon/authenticated)에서 비관리자가 보호 컬럼을 변경하면 거부.\n--    service_role·SECURITY DEFINER(owner 실행)·관리자 세션은 통과.\n-- -----------------------------------------------------------------------------\ncreate function public.users_protected_columns_guard()\nreturns trigger\nlanguage plpgsql\nsecurity invoker\nset search_path = ''''\nas $fn$\nbegin\n  -- SECURITY INVOKER 필수: current_user 가 실제 DML 수행 역할이어야 한다\n  -- (DEFINER 면 owner 로 바뀌어 아래 게이트가 항상 우회된다 — cc_write_guard 와 동일 패턴).\n  -- service_role / definer(owner) / 내부 role 실행 경로는 정본 서버 경로다.\n  if current_user not in (''anon'', ''authenticated'') then\n    return new;\n  end if;\n  -- 관리자 세션의 직접 수정은 관리자 경로로 허용 (RLS 가 행 범위를 계속 제한한다).\n  if coalesce((select public.is_admin()), false) then\n    return new;\n  end if;\n  if new.id                is distinct from old.id\n     or new.role              is distinct from old.role\n     or new.status            is distinct from old.status\n     or new.suspended_until   is distinct from old.suspended_until\n     or new.status_reason     is distinct from old.status_reason\n     or new.status_changed_at is distinct from old.status_changed_at\n     or new.status_changed_by is distinct from old.status_changed_by\n     or new.terms_agreed_at   is distinct from old.terms_agreed_at\n     or new.privacy_agreed_at is distinct from old.privacy_agreed_at\n     or new.marketing_agreed  is distinct from old.marketing_agreed\n     or new.created_at        is distinct from old.created_at then\n    raise exception ''USERS_PROTECTED_COLUMNS'' using errcode = ''42501'';\n  end if;\n  return new;\nend\n$fn$;\n\nrevoke execute on function public.users_protected_columns_guard() from public, anon, authenticated;\n\ncreate trigger trg_users_protected_columns\n  before update on public.users\n  for each row execute function public.users_protected_columns_guard();\n\n-- -----------------------------------------------------------------------------\n-- C. users.status CHECK (사전 게이트 ②에서 위반 0 확인)\n-- -----------------------------------------------------------------------------\nalter table public.users\n  add constraint users_status_allowed\n  check (status in (''active'',''suspended'',''banned'',''deleted'')) not valid;\nalter table public.users validate constraint users_status_allowed;\n\n-- -----------------------------------------------------------------------------\n-- D. self 프로필 수정 공용 정본 (core_private — 판정·검증 단일화, 복제 금지)\n-- -----------------------------------------------------------------------------\ncreate function core_private.user_profile_update_self_impl(\n  p_user_id     uuid,\n  p_nickname    text,\n  p_grade_level text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity invoker\nset search_path = ''''\nas $fn$\ndeclare\n  v_role text;\n  v_status text;\n  v_susp timestamptz;\n  v_norm text;\n  v_nick text;\n  v_grade text;\n  v_set_grade boolean := false;\n  v_updated_at timestamptz;\n  v_out_nick text;\n  v_out_grade text;\nbegin\n  if p_user_id is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  select u.role, u.status, u.suspended_until\n    into v_role, v_status, v_susp\n    from public.users u where u.id = p_user_id\n    for update;\n  if not found then\n    raise exception ''ACCOUNT_NOT_ACTIVE'';\n  end if;\n\n  if v_role not in (''student'',''mentor'') then\n    raise exception ''ROLE_NOT_ALLOWED'';\n  end if;\n\n  -- 계정 상태 게이트 (Build 13 UGC 게이트와 동일 판정: banned 차단 · 유효 suspended\n  -- 차단 · 만료 suspended 허용 · unknown/deleted/빈 status 차단)\n  v_norm := lower(btrim(coalesce(v_status, '''')));\n  if v_norm = ''banned'' then\n    raise exception ''ACCOUNT_BANNED'';\n  end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then\n    raise exception ''ACCOUNT_SUSPENDED'';\n  end if;\n  if v_norm not in (''active'',''suspended'') then\n    raise exception ''ACCOUNT_NOT_ACTIVE'';\n  end if;\n  if public.account_deletion_write_blocked(p_user_id) then\n    raise exception ''ACCOUNT_DELETION_IN_PROGRESS'';\n  end if;\n\n  -- nickname: null=유지 · trim 후 빈 값=오류 · 최대 30자\n  if p_nickname is not null then\n    v_nick := btrim(p_nickname);\n    if v_nick = '''' then\n      raise exception ''NICKNAME_REQUIRED'' using errcode = ''22023'';\n    end if;\n    if char_length(v_nick) > 30 then\n      raise exception ''NICKNAME_TOO_LONG'' using errcode = ''22023'';\n    end if;\n  end if;\n\n  -- grade_level: null=유지 · ''''=값 제거 · 학생만 · 자유 텍스트 최대 20자\n  if p_grade_level is not null then\n    if v_role <> ''student'' then\n      raise exception ''GRADE_LEVEL_NOT_ALLOWED'' using errcode = ''22023'';\n    end if;\n    v_grade := nullif(btrim(p_grade_level), '''');\n    if v_grade is not null and char_length(v_grade) > 20 then\n      raise exception ''GRADE_LEVEL_TOO_LONG'' using errcode = ''22023'';\n    end if;\n    v_set_grade := true;\n  end if;\n\n  update public.users u\n     set nickname    = coalesce(v_nick, u.nickname),\n         grade_level = case when v_set_grade then v_grade else u.grade_level end,\n         updated_at  = now()\n   where u.id = p_user_id\n   returning u.updated_at, u.nickname, u.grade_level\n     into v_updated_at, v_out_nick, v_out_grade;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''contract_version'', 1,\n    ''nickname'', v_out_nick,\n    ''grade_level'', v_out_grade,\n    ''updated_at'', v_updated_at\n  );\nend\n$fn$;\n\nrevoke execute on function core_private.user_profile_update_self_impl(uuid, text, text) from public, anon, authenticated;\n\n-- -----------------------------------------------------------------------------\n-- E. 앱 self RPC (api_app_v1 — authenticated 만, M17 노출 계약과 동일)\n-- -----------------------------------------------------------------------------\ncreate function api_app_v1.user_profile_update_self(\n  p_nickname    text default null,\n  p_grade_level text default null\n)\nreturns jsonb\nlanguage sql\nsecurity definer\nset search_path = ''''\nas $fn$\n  select core_private.user_profile_update_self_impl((select auth.uid()), p_nickname, p_grade_level);\n$fn$;\n\nrevoke execute on function api_app_v1.user_profile_update_self(text, text) from public, anon;\ngrant execute on function api_app_v1.user_profile_update_self(text, text) to authenticated;\n\n-- -----------------------------------------------------------------------------\n-- F. 웹 self RPC (api_web_v1 — authenticated + service_role, 기존 표면 계약과 동일)\n-- -----------------------------------------------------------------------------\ncreate function api_web_v1.user_profile_update_self(\n  p_nickname    text default null,\n  p_grade_level text default null\n)\nreturns jsonb\nlanguage sql\nsecurity definer\nset search_path = ''''\nas $fn$\n  select core_private.user_profile_update_self_impl((select auth.uid()), p_nickname, p_grade_level);\n$fn$;\n\nrevoke execute on function api_web_v1.user_profile_update_self(text, text) from public, anon;\ngrant execute on function api_web_v1.user_profile_update_self(text, text) to authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- G. 마케팅 동의 — 동의 원장 append + users 반영 (일반 프로필 RPC 와 분리, §5.6)\n-- -----------------------------------------------------------------------------\ncreate function api_web_v1.user_marketing_consent_set_self(p_agreed boolean)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_status text;\n  v_susp timestamptz;\n  v_norm text;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n  if p_agreed is null then\n    raise exception ''CONSENT_VALUE_REQUIRED'' using errcode = ''22023'';\n  end if;\n\n  select u.status, u.suspended_until into v_status, v_susp\n    from public.users u where u.id = v_uid for update;\n  if not found then\n    raise exception ''ACCOUNT_NOT_ACTIVE'';\n  end if;\n  v_norm := lower(btrim(coalesce(v_status,'''')));\n  if v_norm = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if v_norm not in (''active'',''suspended'') then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  if public.account_deletion_write_blocked(v_uid) then raise exception ''ACCOUNT_DELETION_IN_PROGRESS''; end if;\n\n  -- append-only 원장: 기존 행 UPDATE/DELETE 없음 (§18.2)\n  insert into public.user_consent_records\n    (user_id, consent_type, consent_actor, consent_version, agreed_at, source, metadata)\n  values\n    (v_uid, ''marketing'', ''user'', ''v1'', now(), ''self_rpc'', jsonb_build_object(''agreed'', p_agreed));\n\n  update public.users set marketing_agreed = p_agreed, updated_at = now() where id = v_uid;\n\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''marketing_agreed'', p_agreed);\nend\n$fn$;\n\nrevoke execute on function api_web_v1.user_marketing_consent_set_self(boolean) from public, anon;\ngrant execute on function api_web_v1.user_marketing_consent_set_self(boolean) to authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- 자가 검증 — 실패 시 트랜잭션 전체 rollback\n-- -----------------------------------------------------------------------------\nDO $$\nBEGIN\n  -- users 테이블 레벨 UPDATE 회수 확인\n  IF EXISTS (SELECT 1 FROM information_schema.role_table_grants\n              WHERE table_schema=''public'' AND table_name=''users''\n                AND grantee IN (''anon'',''authenticated'') AND privilege_type=''UPDATE'') THEN\n    RAISE EXCEPTION ''M1_SELFCHECK: users UPDATE grant still present'';\n  END IF;\n  -- authenticated INSERT/SELECT 유지 확인 (가입·본인 조회 경로 보존)\n  IF (SELECT count(*) FROM information_schema.role_table_grants\n       WHERE table_schema=''public'' AND table_name=''users''\n         AND grantee=''authenticated'' AND privilege_type IN (''INSERT'',''SELECT'')) <> 2 THEN\n    RAISE EXCEPTION ''M1_SELFCHECK: users INSERT/SELECT for authenticated lost'';\n  END IF;\n  -- 트리거·CHECK·RPC 존재 확인\n  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid=''public.users''::regclass AND tgname=''trg_users_protected_columns'') THEN\n    RAISE EXCEPTION ''M1_SELFCHECK: protected trigger missing'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''public.users''::regclass\n                  AND conname=''users_status_allowed'' AND convalidated) THEN\n    RAISE EXCEPTION ''M1_SELFCHECK: status CHECK missing/not validated'';\n  END IF;\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace\n       WHERE (n.nspname,p.proname) IN ((''api_app_v1'',''user_profile_update_self''),\n                                       (''api_web_v1'',''user_profile_update_self''),\n                                       (''api_web_v1'',''user_marketing_consent_set_self''),\n                                       (''core_private'',''user_profile_update_self_impl''))) <> 4 THEN\n    RAISE EXCEPTION ''M1_SELFCHECK: profile RPC set incomplete'';\n  END IF;\n  -- 앱 RPC 는 anon EXECUTE 금지\n  IF has_function_privilege(''anon'', ''api_app_v1.user_profile_update_self(text,text)'', ''EXECUTE'') THEN\n    RAISE EXCEPTION ''M1_SELFCHECK: anon can execute app profile RPC'';\n  END IF;\nEND $$;\n\ncommit;"], "idempotency_key": null}, {"name": "20260803162808_domain_contract_convergence", "version": "20260803170916", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260803162808_domain_contract_convergence.sql (수렴 M2)\n-- =============================================================================\n-- 공용 도메인 계약 수렴 (지시서 §6~§13). 선행조건: 수렴 M1(20260803162257) 적용.\n-- 섹션은 독립 검증 가능하게 주석으로 구분하며, 전체는 단일 트랜잭션이다.\n--\n-- 소유 객체 (§23.2):\n--   S1. 멘토 찾기 정본: api_web_v1.mentor_directory_v1 보강(리뷰 집계\n--       moderation_state=''visible'' + 삭제 진행 계정 제외) + legacy RPC 3종\n--       (mentor_directory_list_v2 / mentor_profiles_for_directory_v2 /\n--        mentor_user_public_v2) anon·authenticated EXECUTE 회수\n--   S2. 리뷰 공개 predicate 단일화: RLS(reviews_select_public_visible) ·\n--       get_mentor_review_stats · directory 집계 전부\n--       moderation_state=''visible'' AND coalesce(is_hidden,false)=false AND\n--       coalesce(is_blinded,false)=false\n--   S3. 신고 target 계약: content_reports INSERT allowlist 에서 모호한\n--       ''shortform'' 제거 (신규 쓰기 정본 5종: community_post / shortform_post /\n--       board_comment / community_comment / user). 기존 legacy 행은 보존.\n--   S4. 숏폼 무결성: INSERT/UPDATE/DELETE 정책에 ugc_write_allowed() 결합,\n--       protected-column trigger, view 이벤트 원장 + shortform_view_record_v2,\n--       legacy increment_shortform_post_view EXECUTE 회수\n--   S5. 숏폼 댓글: author_label 서버 파생 트리거를 shortform 으로 확장 +\n--       본인 댓글 soft-delete RPC(community_comment_soft_delete_self) +\n--       status CHECK 에 ''deleted'' 추가\n--   S6. IQ 쓰기 게이트: answer_individual_question 에 계정 4종·삭제 진행·차단·\n--       멘토 승인 게이트 추가(서명·반환형 불변),\n--       add_individual_question_attachment 신규 등록 Storage 검증 fail-closed\n--       (object 존재·소유·MIME·크기 — 기존 등록 행 멱등 경로는 불변)\n--   S7. 금융 ACL 정리: 정책상 클라이언트 쓰기가 없는 금융 테이블의 잉여\n--       write grant 회수 (payments pending intent INSERT ·\n--        refunds INSERT(refund_ins) · withdrawals requested INSERT 는 유지)\n--   S8. 경고 3회 자동정지 원자 RPC: admin_issue_user_warning\n--   S9. favorites 중복(영·한) 정책 정리 — 영문 정본 3종만 유지\n--\n-- 판단 기록:\n--   - release/refund_individual_question 은 학생의 금융 정산 권리 경로라\n--     계정상태 차단을 추가하지 않는다(자금 동결 위험 — 당사자·상태·멱등 가드는\n--     기존 유지). 콘텐츠 생산 경로(answer)에만 전체 게이트를 추가한다.\n--   - increment_community_post_view(게시판)는 이번 지시 범위(§10.5 — 숏폼) 밖이라\n--     유지한다.\n--\n-- rollback 정본: supabase/rollback/20260803162808_domain_contract_convergence_rollback.sql\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- 사전 게이트\n-- -----------------------------------------------------------------------------\nDO $$\nBEGIN\n  -- M1 적용 확인 (protected trigger + status CHECK)\n  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid=''public.users''::regclass AND tgname=''trg_users_protected_columns'') THEN\n    RAISE EXCEPTION ''M2_BASELINE_MISMATCH: M1 not applied'';\n  END IF;\n  -- 대상 뷰·함수 존재\n  IF to_regclass(''api_web_v1.mentor_directory_v1'') IS NULL THEN\n    RAISE EXCEPTION ''M2_BASELINE_MISMATCH: mentor_directory_v1 missing'';\n  END IF;\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace\n       WHERE n.nspname=''public'' AND (p.proname, pg_get_function_identity_arguments(p.oid)) IN\n         ((''mentor_directory_list_v2'',''p_limit integer''),\n          (''mentor_profiles_for_directory_v2'',''p_ids uuid[]''),\n          (''mentor_user_public_v2'',''p_mentor_id uuid''),\n          (''get_mentor_review_stats'',''p_mentor_id uuid, p_include_hidden boolean''),\n          (''increment_shortform_post_view'',''p_post_id uuid''),\n          (''answer_individual_question'',''p_question_id uuid, p_body text''),\n          (''add_individual_question_attachment'',''p_question_id uuid, p_storage_path text, p_file_name text, p_mime_type text, p_message_id uuid''),\n          (''ugc_write_allowed'',''''),\n          (''qna_users_blocked'',''p_a uuid, p_b uuid''),\n          (''individual_question_user_is_approved_mentor'',''p_user_id uuid''))) <> 10 THEN\n    RAISE EXCEPTION ''M2_BASELINE_MISMATCH: expected function set mismatch'';\n  END IF;\n  -- 신규 객체 선점 없음\n  IF to_regclass(''public.shortform_view_events'') IS NOT NULL\n     OR EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace\n                 WHERE n.nspname=''public'' AND p.proname IN\n                   (''shortform_view_record_v2'',''community_comment_soft_delete_self'',\n                    ''admin_issue_user_warning'',''shortform_posts_protected_guard'',\n                    ''account_deletion_request_self_v2'',''account_deletion_request_self_consented_v2'')) THEN\n    RAISE EXCEPTION ''M2_BASELINE_MISMATCH: target object already exists'';\n  END IF;\n  -- S10 대상 구 self RPC 존재 (identity 고정)\n  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace\n       WHERE n.nspname=''public'' AND (p.proname, pg_get_function_identity_arguments(p.oid)) IN\n         ((''account_deletion_request_self'',''p_cancelable_minutes integer, p_dry_run boolean''),\n          (''account_deletion_request_self_consented'',''p_cancelable_minutes integer, p_dry_run boolean, p_acknowledged_balance_cents bigint''),\n          (''account_deletion_request_consented'',''p_user_id uuid, p_cancelable_minutes integer, p_dry_run boolean, p_forfeit_consent boolean, p_acknowledged_balance_cents bigint''))) <> 3 THEN\n    RAISE EXCEPTION ''M2_BASELINE_MISMATCH: account deletion self RPC set mismatch'';\n  END IF;\n  -- content_reports 기존 INSERT 정책 존재 (교체 대상)\n  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname=''public'' AND tablename=''content_reports''\n                  AND policyname=''content_reports_insert_reporter'') THEN\n    RAISE EXCEPTION ''M2_BASELINE_MISMATCH: content_reports insert policy missing'';\n  END IF;\n  -- community_comments status CHECK (visible/hidden — ''deleted'' 확장 대상)\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''public.community_comments''::regclass\n                  AND pg_get_constraintdef(oid) LIKE ''%visible%hidden%'') THEN\n    RAISE EXCEPTION ''M2_BASELINE_MISMATCH: community_comments status CHECK shape'';\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- S2(선행). 리뷰 공개 predicate — moderation_state 정본화\n--   (S1 의 directory 집계가 같은 predicate 를 쓰므로 먼저 정의)\n-- -----------------------------------------------------------------------------\n-- 신규 리뷰가 기본 노출되도록 default 정본화 + NULL 백필(스테이징 0행 — no-op).\n-- 백필은 reviews_enforce_update 트리거를 잠시 비활성해 수행한다(마이그레이션 소유자\n-- 경로 — 트리거는 클라이언트 액터 판정 전용이라 NULL 백필을 액터 없음으로 거부한다).\nalter table public.reviews alter column moderation_state set default ''visible'';\nalter table public.reviews disable trigger trg_reviews_enforce_update;\nupdate public.reviews set moderation_state = ''visible'' where moderation_state is null;\nalter table public.reviews enable trigger trg_reviews_enforce_update;\n\ndrop policy if exists reviews_select_public_visible on public.reviews;\ncreate policy reviews_select_public_visible on public.reviews\n  for select to anon, authenticated\n  using (\n    moderation_state = ''visible''\n    and coalesce(is_hidden, false) = false\n    and coalesce(is_blinded, false) = false\n  );\n\ncreate or replace function public.get_mentor_review_stats(p_mentor_id uuid, p_include_hidden boolean default false)\nreturns table(review_count integer, avg_rating numeric, d1 integer, d2 integer, d3 integer, d4 integer, d5 integer)\nlanguage plpgsql stable security definer\nset search_path to ''public''\nas $fn$\ndeclare v_include_hidden boolean := coalesce(p_include_hidden, false);\nbegin\n  if v_include_hidden and not coalesce(public.is_admin(), false) then v_include_hidden := false; end if;\n  return query\n  select count(*)::integer,\n    case when count(*) > 0 then round(avg(r.rating)::numeric, 1) else null end,\n    count(*) filter (where round(r.rating)=1)::integer, count(*) filter (where round(r.rating)=2)::integer,\n    count(*) filter (where round(r.rating)=3)::integer, count(*) filter (where round(r.rating)=4)::integer,\n    count(*) filter (where round(r.rating)=5)::integer\n  from public.reviews r\n  where r.mentor_id = p_mentor_id\n    and (v_include_hidden\n         or (r.moderation_state = ''visible''\n             and coalesce(r.is_hidden,false)=false\n             and coalesce(r.is_blinded,false)=false));\nend;\n$fn$;\n\n-- -----------------------------------------------------------------------------\n-- S1. 멘토 찾기 정본 뷰 보강 + legacy RPC 회수\n--   projection·노출 조건은 기존 그대로(role=mentor · status=active ·\n--   verification approved/verified/active · full_name 등 비공개 필드 없음).\n--   추가: 리뷰 집계 S2 predicate 일치 + 삭제 진행 계정 제외.\n-- -----------------------------------------------------------------------------\ncreate or replace view api_web_v1.mentor_directory_v1 as\n SELECT mp.user_id AS mentor_id,\n    u.nickname,\n    mp.university_name,\n    mp.department_name,\n    mp.teaching_subjects,\n    mp.intro_line,\n    mp.profile_image_url,\n    mp.high_school_name,\n    sv.mentor_id IS NOT NULL AS school_verified,\n    sv.school_tier,\n    sv.verified_major_category,\n    sv.verified_university_name,\n    sv.verified_department_name,\n    mp.is_open_for_subscriptions,\n    rv.avg_rating,\n    rv.review_count,\n    mp.created_at\n   FROM mentor_profiles mp\n     JOIN users u ON u.id = mp.user_id\n     LEFT JOIN LATERAL ( SELECT msv.mentor_id,\n            msv.school_tier,\n            msv.verified_major_category,\n            msv.verified_university_name,\n            msv.verified_department_name\n           FROM mentor_school_verifications msv\n          WHERE msv.mentor_id = mp.user_id AND msv.status = ''approved''::text\n          ORDER BY (COALESCE(msv.reviewed_at, msv.updated_at, msv.created_at)) DESC, msv.created_at DESC\n         LIMIT 1) sv ON true\n     LEFT JOIN LATERAL ( SELECT avg(r.rating) AS avg_rating,\n            count(*)::integer AS review_count\n           FROM reviews r\n          WHERE r.mentor_id = mp.user_id\n            AND r.moderation_state = ''visible''::text\n            AND COALESCE(r.is_hidden, false) = false\n            AND COALESCE(r.is_blinded, false) = false) rv ON true\n  WHERE u.role = ''mentor''::text\n    AND lower(COALESCE(u.status, ''active''::text)) = ''active''::text\n    AND (lower(COALESCE(mp.verification_status, ''''::text)) = ANY (ARRAY[''approved''::text, ''verified''::text, ''active''::text]))\n    -- 삭제 진행 중 계정 제외 (state 목록 = account_deletion_active_states() 정본과 일치;\n    -- definer 뷰에서 함수 EXECUTE 의존을 피하려 리터럴로 고정)\n    AND NOT EXISTS (\n      SELECT 1 FROM account_deletion_jobs j\n       WHERE j.user_id = mp.user_id\n         AND j.state = ANY (ARRAY[''pending'',''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted'']));\n\nalter view api_web_v1.mentor_directory_v1 set (security_invoker = false);\n\n-- legacy RPC 회수 — 웹·앱 신규 코드 호출부 0 (이번 수렴에서 앱 전환 완료).\n-- service_role/postgres EXECUTE 는 유지(내부·비상 경로).\nrevoke execute on function public.mentor_directory_list_v2(integer) from public, anon, authenticated;\nrevoke execute on function public.mentor_profiles_for_directory_v2(uuid[]) from public, anon, authenticated;\nrevoke execute on function public.mentor_user_public_v2(uuid) from public, anon, authenticated;\n\n-- -----------------------------------------------------------------------------\n-- S3. 신고 target 계약 — INSERT allowlist 에서 ''shortform'' 제거\n-- -----------------------------------------------------------------------------\ndrop policy if exists content_reports_insert_reporter on public.content_reports;\ncreate policy content_reports_insert_reporter on public.content_reports\n  for insert to authenticated\n  with check (\n    reporter_id = (select auth.uid())\n    and status = ''pending''::text\n    and admin_note is null\n    and resolved_by is null\n    and resolved_at is null\n    and target_type = any (array[''community_post''::text, ''shortform_post''::text,\n                                 ''community_comment''::text, ''board_comment''::text, ''user''::text])\n    and (target_type <> ''user''::text or public.report_target_user_valid(target_id))\n  );\n\n-- -----------------------------------------------------------------------------\n-- S4. 숏폼 무결성\n-- -----------------------------------------------------------------------------\n-- (a) 계정 게이트 결합 정책 교체\ndrop policy if exists sf_insert_mentor on public.shortform_posts;\ncreate policy sf_insert_mentor on public.shortform_posts\n  for insert to authenticated\n  with check (\n    (select public.is_mentor()) = true\n    and (author_id = (select auth.uid()) or creator_id = (select auth.uid()))\n    and (select public.ugc_write_allowed())\n  );\n\ndrop policy if exists sf_update_own on public.shortform_posts;\ndrop policy if exists sp_update_self on public.shortform_posts;\ncreate policy sf_update_own on public.shortform_posts\n  for update to authenticated\n  using (\n    (author_id = (select auth.uid()) or creator_id = (select auth.uid()))\n    and (select public.ugc_write_allowed())\n  )\n  with check (\n    (author_id = (select auth.uid()) or creator_id = (select auth.uid()))\n  );\ncreate policy sf_update_admin on public.shortform_posts\n  for update to authenticated\n  using ((select public.is_admin()) = true)\n  with check ((select public.is_admin()) = true);\n\ndrop policy if exists sf_delete_own on public.shortform_posts;\ncreate policy sf_delete_own on public.shortform_posts\n  for delete to authenticated\n  using (\n    (author_id = (select auth.uid()) or creator_id = (select auth.uid()))\n    and (select public.ugc_write_allowed())\n  );\n\n-- (b) protected-column trigger — 클라이언트 역할 비관리자의 소유 행 UPDATE 에서\n--     식별·귀속·카운터·서버 관리 필드 변조 거부. 허용 콘텐츠 필드:\n--     title/body/description/category/tags/video_url/thumbnail_url +\n--     status 는 draft<->published 전이만. updated_at 은 서버 강제.\ncreate function public.shortform_posts_protected_guard()\nreturns trigger\nlanguage plpgsql\nsecurity invoker\nset search_path = ''''\nas $fn$\nbegin\n  -- SECURITY INVOKER 필수 — current_user 게이트가 실제 클라이언트 역할을 봐야 한다.\n  if current_user not in (''anon'',''authenticated'') then\n    return new;\n  end if;\n  if coalesce((select public.is_admin()), false) then\n    return new;\n  end if;\n  if new.id                   is distinct from old.id\n     or new.author_id            is distinct from old.author_id\n     or new.creator_id           is distinct from old.creator_id\n     or new.author_role          is distinct from old.author_role\n     or new.author_label         is distinct from old.author_label\n     or new.source               is distinct from old.source\n     or new.created_at           is distinct from old.created_at\n     or new.view_count           is distinct from old.view_count\n     or new.like_count           is distinct from old.like_count\n     or new.create_idempotency_key is distinct from old.create_idempotency_key then\n    raise exception ''SHORTFORM_PROTECTED_COLUMNS'' using errcode = ''42501'';\n  end if;\n  if new.status is distinct from old.status then\n    if not (old.status in (''draft'',''published'') and new.status in (''draft'',''published'')) then\n      raise exception ''SHORTFORM_STATUS_TRANSITION_FORBIDDEN'' using errcode = ''42501'';\n    end if;\n  end if;\n  new.updated_at := now();\n  return new;\nend\n$fn$;\n\nrevoke execute on function public.shortform_posts_protected_guard() from public, anon, authenticated;\n\ncreate trigger trg_shortform_posts_protected\n  before update on public.shortform_posts\n  for each row execute function public.shortform_posts_protected_guard();\n\n-- (c) view 이벤트 원장 + v2 RPC (한 impression 당 event key 1개 — 멱등)\ncreate table public.shortform_view_events (\n  post_id        uuid not null references public.shortform_posts(id) on delete cascade,\n  event_key      uuid not null,\n  viewer_user_id uuid,\n  created_at     timestamptz not null default now(),\n  primary key (post_id, event_key)\n);\nalter table public.shortform_view_events enable row level security;\n-- 클라이언트 정책 없음 — 쓰기·읽기 전부 RPC/서버 경로 (definer)\nrevoke all on table public.shortform_view_events from public, anon, authenticated;\n\ncreate function public.shortform_view_record_v2(p_post_id uuid, p_event_key uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_inserted boolean := false;\nbegin\n  if p_post_id is null or p_event_key is null then\n    raise exception ''INVALID_INPUT'' using errcode = ''22023'';\n  end if;\n  -- 게시 상태 공개 글만 계수\n  if not exists (select 1 from public.shortform_posts sp\n                  where sp.id = p_post_id and sp.status = ''published'') then\n    raise exception ''POST_NOT_FOUND'' using errcode = ''P0001'';\n  end if;\n\n  insert into public.shortform_view_events (post_id, event_key, viewer_user_id)\n  values (p_post_id, p_event_key, v_uid)\n  on conflict (post_id, event_key) do nothing;\n  v_inserted := found;\n\n  if v_inserted then\n    update public.shortform_posts\n       set view_count = view_count + 1\n     where id = p_post_id;\n  end if;\n\n  -- 중복 key 는 idempotent success (계수 증가 없음)\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''incremented'', v_inserted);\nend\n$fn$;\n\nrevoke execute on function public.shortform_view_record_v2(uuid, uuid) from public;\ngrant execute on function public.shortform_view_record_v2(uuid, uuid) to anon, authenticated;\n\n-- legacy 무제한 +1 RPC 회수 (정의는 rollback 을 위해 남기되 클라이언트 호출 불가)\nrevoke execute on function public.increment_shortform_post_view(uuid) from public, anon, authenticated;\n\n-- -----------------------------------------------------------------------------\n-- S5. 숏폼 댓글 — 서버 파생 author_label 확장 + 본인 soft-delete\n-- -----------------------------------------------------------------------------\n-- (a) label 트리거를 shortform 에도 적용 (기존 board 트리거는 불변 — bridge 순수성 유지)\ncreate trigger trg_cc_set_author_label_shortform_ins\n  before insert on public.community_comments\n  for each row when (new.post_type = ''shortform''::text)\n  execute function public.community_comments_set_author_label();\n\ncreate trigger trg_cc_set_author_label_shortform_upd\n  before update of author_label on public.community_comments\n  for each row when (old.post_type = ''shortform''::text)\n  execute function public.community_comments_set_author_label();\n\n-- (b) status CHECK 확장: ''deleted'' (본인 삭제) — 관리자 ''hidden'' 과 구분\nalter table public.community_comments drop constraint if exists community_comments_status_check;\nalter table public.community_comments\n  add constraint community_comments_status_check\n  check (status = any (array[''visible''::text, ''hidden''::text, ''deleted''::text]));\n\n-- (c) 본인 숏폼 댓글 soft-delete RPC (hard delete 금지 — §10.6)\n--     board 댓글은 기존 웹 계약(comments.is_deleted soft-delete)을 그대로 사용하며\n--     이 RPC 는 shortform 전용이다(bridge 에 숏폼 미혼입).\ncreate function public.community_comment_soft_delete_self(p_comment_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_row public.community_comments%rowtype;\n  v_status text;\n  v_susp timestamptz;\n  v_norm text;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  select * into v_row from public.community_comments where id = p_comment_id for update;\n  if not found then\n    raise exception ''COMMENT_NOT_FOUND'' using errcode = ''P0001'';\n  end if;\n  if v_row.post_type <> ''shortform'' then\n    raise exception ''COMMENT_TYPE_NOT_SUPPORTED'' using errcode = ''22023'';\n  end if;\n  if v_row.author_id is distinct from v_uid then\n    raise exception ''COMMENT_NOT_OWNED'' using errcode = ''42501'';\n  end if;\n\n  -- 계정 게이트 (Build 13 판정과 동일: banned·유효 suspended·unknown/deleted·삭제 진행 차단)\n  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id = v_uid;\n  if not found then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  v_norm := lower(btrim(coalesce(v_status,'''')));\n  if v_norm = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if v_norm not in (''active'',''suspended'') then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  if public.account_deletion_write_blocked(v_uid) then raise exception ''ACCOUNT_DELETION_IN_PROGRESS''; end if;\n\n  if v_row.status = ''deleted'' then\n    return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''comment_id'', p_comment_id, ''idempotent_hit'', true);\n  end if;\n  if v_row.status <> ''visible'' then\n    -- 관리자 hidden 처리된 댓글은 본인이 삭제로 덮지 못한다 (moderation 유지)\n    raise exception ''COMMENT_MODERATED'' using errcode = ''42501'';\n  end if;\n\n  update public.community_comments set status = ''deleted'' where id = p_comment_id;\n\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''comment_id'', p_comment_id, ''idempotent_hit'', false);\nend\n$fn$;\n\nrevoke execute on function public.community_comment_soft_delete_self(uuid) from public, anon;\ngrant execute on function public.community_comment_soft_delete_self(uuid) to authenticated;\n\n-- -----------------------------------------------------------------------------\n-- S6. IQ 쓰기 게이트\n-- -----------------------------------------------------------------------------\n-- (a) answer_individual_question — 계정·차단·승인 게이트 추가 (서명·반환형·기존\n--     당사자/상태/멱등 의미 불변; iq_append_message 와 동일 게이트 순서)\ncreate or replace function public.answer_individual_question(p_question_id uuid, p_body text)\nreturns setof public.individual_questions\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_question public.individual_questions%rowtype;\n  v_mentor_id uuid;\n  v_status text; v_susp timestamptz; v_norm text;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  if coalesce(btrim(p_body), '''') = '''' then\n    raise exception ''INVALID_INPUT: body is required'' using errcode = ''22023'';\n  end if;\n\n  select *\n    into v_question\n  from public.individual_questions\n  where id = p_question_id\n  for update;\n\n  if not found then\n    raise exception ''QUESTION_NOT_FOUND'' using errcode = ''P0001'';\n  end if;\n\n  -- payout 과 동일한 멘토 해석(open=claimed, direct=designated).\n  v_mentor_id := coalesce(v_question.claimed_mentor_id, v_question.designated_mentor_id);\n  if v_mentor_id is null or v_mentor_id <> v_uid then\n    raise exception ''NOT_QUESTION_MENTOR'' using errcode = ''42501'';\n  end if;\n\n  -- 계정 상태 4종 + 삭제 진행 + 상호 차단 + 멘토 승인 (수렴 M2 — iq_append_message 동일 게이트)\n  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id = v_uid;\n  if not found then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  v_norm := lower(btrim(coalesce(v_status,'''')));\n  if v_norm = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if v_norm not in (''active'',''suspended'') then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  if public.account_deletion_write_blocked(v_uid) then raise exception ''ACCOUNT_DELETION_IN_PROGRESS''; end if;\n  if public.qna_users_blocked(v_question.student_id, v_mentor_id) then raise exception ''BLOCKED''; end if;\n  if not public.individual_question_user_is_approved_mentor(v_mentor_id) then\n    raise exception ''MENTOR_NOT_APPROVED'';\n  end if;\n\n  if v_question.status not in (''claimed'', ''assigned'') then\n    raise exception ''NOT_ANSWERABLE_STATUS:%'', v_question.status using errcode = ''P0001'';\n  end if;\n\n  insert into public.individual_question_messages (question_id, author_id, body)\n  values (p_question_id, v_uid, p_body);\n\n  update public.individual_questions\n  set status = ''answered'',\n      answered_at = coalesce(answered_at, now())\n  where id = p_question_id\n  returning * into v_question;\n\n  return next v_question;\nend;\n$function$;\n\n-- (b) add_individual_question_attachment — 신규 등록만 Storage fail-closed 강화.\n--     기존 등록 행의 멱등 경로(선조회 → existing 봉투)는 Storage 검증 없이 그대로\n--     통과시켜 §12.1 멱등·수렴 계약을 보존한다. 반환 봉투 키·의미 전부 불변.\ncreate or replace function public.add_individual_question_attachment(p_question_id uuid, p_storage_path text, p_file_name text, p_mime_type text, p_message_id uuid default null::uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $function$\ndeclare\n  v_uid  uuid := (select auth.uid());\n  v_path text;\n  v_id   uuid;\n  v_existing_message_id uuid;\n  v_created boolean := false;\n  v_status text; v_susp timestamptz; v_norm text;\n  v_obj_owner text;\n  v_obj_meta jsonb;\n  v_obj_found boolean := false;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  v_path := btrim(coalesce(p_storage_path, ''''));\n  if v_path = '''' then\n    raise exception ''INVALID_INPUT: storage_path is required'' using errcode = ''22023'';\n  end if;\n\n  if not public.user_is_individual_question_party(p_question_id) then\n    raise exception ''NOT_QUESTION_PARTY'' using errcode = ''42501'';\n  end if;\n\n  if split_part(v_path, ''/'', 1) <> p_question_id::text then\n    raise exception ''STORAGE_PATH_MISMATCH'' using errcode = ''22023'';\n  end if;\n\n  if p_message_id is not null and not exists (\n    select 1\n    from public.individual_question_messages m\n    where m.id = p_message_id\n      and m.question_id = p_question_id\n  ) then\n    raise exception ''MESSAGE_NOT_IN_QUESTION'' using errcode = ''22023'';\n  end if;\n\n  -- 멱등 선조회: 이미 등록된 (question_id, storage_path) 는 기존 계약 그대로 반환\n  -- (legacy 객체 읽기·기존 등록 행을 깨지 않는다 — 신규 등록만 아래에서 fail-closed)\n  select a.id, a.message_id\n    into v_id, v_existing_message_id\n  from public.individual_question_attachments a\n  where a.question_id = p_question_id\n    and a.storage_path = v_path;\n\n  if v_id is null then\n    -- === 신규 등록 검증 (수렴 M2 §12.6) ===\n    -- 계정 상태 4종 + 삭제 진행\n    select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id = v_uid;\n    if not found then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n    v_norm := lower(btrim(coalesce(v_status,'''')));\n    if v_norm = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n    if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n    if v_norm not in (''active'',''suspended'') then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n    if public.account_deletion_write_blocked(v_uid) then raise exception ''ACCOUNT_DELETION_IN_PROGRESS''; end if;\n\n    -- Storage object 존재·소유·MIME·크기 (bucket=individual-question-attachments 고정)\n    select o.owner_id, o.metadata into v_obj_owner, v_obj_meta\n      from storage.objects o\n     where o.bucket_id = ''individual-question-attachments''\n       and o.name = v_path;\n    v_obj_found := found;\n    if not v_obj_found then\n      raise exception ''STORAGE_OBJECT_NOT_FOUND'' using errcode = ''22023'';\n    end if;\n    if v_obj_owner is null or v_obj_owner <> v_uid::text then\n      raise exception ''STORAGE_OBJECT_NOT_OWNED'' using errcode = ''42501'';\n    end if;\n    if v_obj_meta ? ''mimetype''\n       and coalesce(nullif(btrim(p_mime_type), ''''), ''(none)'') <> (v_obj_meta->>''mimetype'') then\n      raise exception ''MIME_MISMATCH'' using errcode = ''22023'';\n    end if;\n    if p_mime_type is not null and btrim(p_mime_type) <> '''' and not exists (\n      select 1 from storage.buckets b\n       where b.id = ''individual-question-attachments''\n         and (b.allowed_mime_types is null or btrim(p_mime_type) = any (b.allowed_mime_types))\n    ) then\n      raise exception ''MIME_NOT_ALLOWED'' using errcode = ''22023'';\n    end if;\n    if v_obj_meta ? ''size'' and (v_obj_meta->>''size'')::bigint > 20971520 then\n      raise exception ''SIZE_EXCEEDED'' using errcode = ''22023'';\n    end if;\n\n    insert into public.individual_question_attachments\n      (question_id, message_id, storage_path, file_name, mime_type, author_id)\n    values\n      (p_question_id, p_message_id, v_path, p_file_name, p_mime_type, v_uid)\n    on conflict (question_id, storage_path) do nothing\n    returning id into v_id;\n\n    if v_id is not null then\n      v_created := true;\n    else\n      select a.id, a.message_id\n        into v_id, v_existing_message_id\n      from public.individual_question_attachments a\n      where a.question_id = p_question_id\n        and a.storage_path = v_path;\n\n      if v_id is null then\n        raise exception ''REGISTER_CONFLICT_UNRESOLVED'' using errcode = ''40001'';\n      end if;\n    end if;\n  end if;\n\n  return jsonb_build_object(\n    ''ok'',            true,\n    ''status'',        case when v_created then ''created'' else ''existing'' end,\n    ''idempotent_hit'', not v_created,\n    ''attachment_id'', v_id,\n    ''question_id'',   p_question_id,\n    ''storage_path'',  v_path,\n    ''message_id_mismatch'',\n      case when v_created then false\n           else coalesce(v_existing_message_id, ''00000000-0000-0000-0000-000000000000''::uuid)\n                is distinct from coalesce(p_message_id, ''00000000-0000-0000-0000-000000000000''::uuid)\n      end\n  );\nend;\n$function$;\n\n-- -----------------------------------------------------------------------------\n-- S7. 금융 ACL 정리 — RLS 가 이미 거부하는 잉여 write grant 회수 (defense-in-depth)\n--     유지: payments INSERT(pending intent 정책) · refunds INSERT(refund_ins) ·\n--           withdrawals INSERT(requested 정책) — 제품 계약상 필요한 클라이언트 쓰기\n-- -----------------------------------------------------------------------------\nrevoke insert, update, delete, truncate, references, trigger on table\n  public.cash_wallets, public.cash_ledger, public.subscriptions,\n  public.cash_topup_packages, public.subscription_billing_events, public.order_payments,\n  public.payments, public.refunds, public.withdrawals, public.user_warnings\nfrom anon;\n\nrevoke update, delete, truncate, references, trigger on table\n  public.cash_wallets, public.cash_ledger, public.subscriptions,\n  public.cash_topup_packages, public.subscription_billing_events, public.order_payments,\n  public.payments, public.refunds, public.withdrawals\nfrom authenticated;\n\nrevoke insert on table\n  public.cash_wallets, public.cash_ledger, public.subscriptions,\n  public.cash_topup_packages, public.subscription_billing_events, public.order_payments\nfrom authenticated;\n\n-- user_warnings: 클라이언트 정책 0 — 쓰기는 admin_issue_user_warning/service 경로만\nrevoke insert, update, delete, truncate, references, trigger on table public.user_warnings from authenticated;\n\n-- -----------------------------------------------------------------------------\n-- S8. 경고 3회 자동정지 원자 RPC (§18.3)\n-- -----------------------------------------------------------------------------\ncreate function public.admin_issue_user_warning(\n  p_user_id  uuid,\n  p_reason   text,\n  p_severity text default ''normal''\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = ''''\nas $fn$\ndeclare\n  v_actor uuid := (select auth.uid());\n  v_is_service boolean := (coalesce((select auth.role()), '''') = ''service_role'');\n  v_target_role text;\n  v_reason text;\n  v_severity text;\n  v_warning_id uuid;\n  v_active_count integer;\n  v_auto_suspended boolean := false;\n  v_suspended_until timestamptz;\nbegin\n  -- caller: admin 세션 또는 service_role\n  if not v_is_service and not coalesce((select public.is_admin()), false) then\n    raise exception ''ADMIN_ONLY'' using errcode = ''42501'';\n  end if;\n  if p_user_id is null then\n    raise exception ''TARGET_REQUIRED'' using errcode = ''22023'';\n  end if;\n  if v_actor is not null and v_actor = p_user_id then\n    raise exception ''SELF_WARNING_FORBIDDEN'' using errcode = ''42501'';\n  end if;\n\n  v_reason := nullif(btrim(coalesce(p_reason, '''')), '''');\n  if v_reason is null then\n    raise exception ''REASON_REQUIRED'' using errcode = ''22023'';\n  end if;\n  v_severity := lower(btrim(coalesce(p_severity, ''normal'')));\n  if v_severity not in (''normal'',''severe'') then\n    raise exception ''SEVERITY_INVALID'' using errcode = ''22023'';\n  end if;\n\n  select u.role into v_target_role from public.users u where u.id = p_user_id for update;\n  if not found then\n    raise exception ''TARGET_NOT_FOUND'' using errcode = ''P0001'';\n  end if;\n  if v_target_role = ''admin'' then\n    raise exception ''ADMIN_TARGET_FORBIDDEN'' using errcode = ''42501'';\n  end if;\n\n  insert into public.user_warnings (user_id, issued_by, reason, severity, source, is_active)\n  values (p_user_id, v_actor, v_reason, v_severity, ''admin'', true)\n  returning id into v_warning_id;\n\n  select count(*) into v_active_count\n    from public.user_warnings w\n   where w.user_id = p_user_id and w.is_active = true;\n\n  -- 3회 이상 → 7일 suspended (경고 INSERT 와 동일 트랜잭션 — 부분 성공 불가)\n  if v_active_count >= 3 then\n    v_suspended_until := now() + interval ''7 days'';\n    update public.users\n       set status = ''suspended'',\n           suspended_until = v_suspended_until,\n           status_reason = ''auto_suspend_warnings_'' || v_active_count,\n           status_changed_at = now(),\n           status_changed_by = v_actor,\n           updated_at = now()\n     where id = p_user_id;\n    v_auto_suspended := true;\n  end if;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''contract_version'', 1,\n    ''warning_id'', v_warning_id,\n    ''active_warning_count'', v_active_count,\n    ''auto_suspended'', v_auto_suspended,\n    ''suspended_until'', v_suspended_until\n  );\nend\n$fn$;\n\nrevoke execute on function public.admin_issue_user_warning(uuid, text, text) from public, anon;\ngrant execute on function public.admin_issue_user_warning(uuid, text, text) to authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- S9. favorites 중복 정책 정리 — 영문 정본 3종 유지, 한글 중복 3종 제거\n-- -----------------------------------------------------------------------------\ndrop policy if exists \"본인 찜만 조회\" on public.favorites;\ndrop policy if exists \"본인만 찜 삭제\" on public.favorites;\ndrop policy if exists \"본인만 찜 추가\" on public.favorites;\n\n-- -----------------------------------------------------------------------------\n-- S10. 계정 삭제 self v2 — 취소창 30분·dry_run=false 서버 고정 (§16.4)\n--      구 self RPC(클라이언트 p_cancelable_minutes/p_dry_run 수용)는\n--      authenticated EXECUTE 회수(운영 도구용 service_role 경로만 유지).\n-- -----------------------------------------------------------------------------\ncreate function public.account_deletion_request_self_v2()\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_raw jsonb;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED'' using errcode = ''28000''; end if;\n  perform pg_advisory_xact_lock(hashtextextended(''account_deletion_self:'' || v_uid::text, 0));\n  -- 취소창·dry_run 은 서버 고정값 — 클라이언트 입력 없음\n  v_raw := public.account_deletion_request_consented(v_uid, 30, false, false, null);\n  return public.account_deletion_self_response(v_uid, v_raw);\nend\n$fn$;\n\nrevoke execute on function public.account_deletion_request_self_v2() from public, anon;\ngrant execute on function public.account_deletion_request_self_v2() to authenticated, service_role;\n\ncreate function public.account_deletion_request_self_consented_v2(p_acknowledged_balance_cents bigint)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_raw jsonb;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED'' using errcode = ''28000''; end if;\n  perform pg_advisory_xact_lock(hashtextextended(''account_deletion_self:'' || v_uid::text, 0));\n  v_raw := public.account_deletion_request_consented(v_uid, 30, false, true, p_acknowledged_balance_cents);\n  return public.account_deletion_self_response(v_uid, v_raw);\nend\n$fn$;\n\nrevoke execute on function public.account_deletion_request_self_consented_v2(bigint) from public, anon;\ngrant execute on function public.account_deletion_request_self_consented_v2(bigint) to authenticated, service_role;\n\nrevoke execute on function public.account_deletion_request_self(integer, boolean) from public, anon, authenticated;\nrevoke execute on function public.account_deletion_request_self_consented(integer, boolean, bigint) from public, anon, authenticated;\n\n-- -----------------------------------------------------------------------------\n-- 자가 검증\n-- -----------------------------------------------------------------------------\nDO $$\nBEGIN\n  -- S1: legacy RPC 회수\n  IF has_function_privilege(''anon'', ''public.mentor_directory_list_v2(integer)'', ''EXECUTE'')\n     OR has_function_privilege(''authenticated'', ''public.mentor_directory_list_v2(integer)'', ''EXECUTE'')\n     OR has_function_privilege(''anon'', ''public.mentor_profiles_for_directory_v2(uuid[])'', ''EXECUTE'')\n     OR has_function_privilege(''authenticated'', ''public.mentor_user_public_v2(uuid)'', ''EXECUTE'') THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: legacy mentor RPC still executable'';\n  END IF;\n  -- S1: 뷰 projection 에 full_name 부재\n  IF EXISTS (SELECT 1 FROM information_schema.columns\n              WHERE table_schema=''api_web_v1'' AND table_name=''mentor_directory_v1''\n                AND column_name IN (''full_name'',''email'',''birth_date'',''status_reason'')) THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: mentor_directory_v1 leaks private columns'';\n  END IF;\n  -- S2: 리뷰 공개 정책에 moderation_state 포함\n  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname=''public'' AND tablename=''reviews''\n                  AND policyname=''reviews_select_public_visible''\n                  AND qual LIKE ''%moderation_state%'') THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: reviews public policy missing moderation_state'';\n  END IF;\n  -- S3: allowlist 에서 shortform 제거·5종 유지\n  IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname=''public'' AND tablename=''content_reports''\n              AND policyname=''content_reports_insert_reporter''\n              AND with_check LIKE ''%''''shortform''''%'') THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: ambiguous shortform still allowed'';\n  END IF;\n  -- S4: 정책·트리거·RPC\n  IF (SELECT count(*) FROM pg_policies WHERE schemaname=''public'' AND tablename=''shortform_posts''\n       AND coalesce(qual,'''')||coalesce(with_check,'''') LIKE ''%ugc_write_allowed%'') < 3 THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: shortform ugc gate missing'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid=''public.shortform_posts''::regclass\n                  AND tgname=''trg_shortform_posts_protected'') THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: shortform protected trigger missing'';\n  END IF;\n  IF has_function_privilege(''anon'', ''public.increment_shortform_post_view(uuid)'', ''EXECUTE'')\n     OR has_function_privilege(''authenticated'', ''public.increment_shortform_post_view(uuid)'', ''EXECUTE'') THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: legacy view increment still executable'';\n  END IF;\n  IF NOT has_function_privilege(''anon'', ''public.shortform_view_record_v2(uuid,uuid)'', ''EXECUTE'') THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: view record v2 not executable'';\n  END IF;\n  -- S5: 트리거 2 + CHECK deleted + RPC\n  IF (SELECT count(*) FROM pg_trigger WHERE tgrelid=''public.community_comments''::regclass\n       AND tgname IN (''trg_cc_set_author_label_shortform_ins'',''trg_cc_set_author_label_shortform_upd'')) <> 2 THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: shortform label triggers missing'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=''public.community_comments''::regclass\n                  AND conname=''community_comments_status_check''\n                  AND pg_get_constraintdef(oid) LIKE ''%deleted%'') THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: community_comments deleted status missing'';\n  END IF;\n  -- S7: 금융 write 회수 (인가 예외 3종 유지)\n  IF EXISTS (SELECT 1 FROM information_schema.role_table_grants\n              WHERE table_schema=''public'' AND grantee=''authenticated'' AND privilege_type=''UPDATE''\n                AND table_name IN (''cash_wallets'',''cash_ledger'',''subscriptions'',''payments'',''refunds'',''withdrawals'')) THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: financial UPDATE grant still present'';\n  END IF;\n  IF (SELECT count(*) FROM information_schema.role_table_grants\n       WHERE table_schema=''public'' AND grantee=''authenticated'' AND privilege_type=''INSERT''\n         AND table_name IN (''payments'',''refunds'',''withdrawals'')) <> 3 THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: contract-required INSERT grants lost'';\n  END IF;\n  -- S8\n  IF NOT has_function_privilege(''authenticated'', ''public.admin_issue_user_warning(uuid,text,text)'', ''EXECUTE'') THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: warning RPC not executable'';\n  END IF;\n  -- S10: 삭제 self v2 존재 + 구 RPC authenticated 회수\n  IF NOT has_function_privilege(''authenticated'', ''public.account_deletion_request_self_v2()'', ''EXECUTE'')\n     OR NOT has_function_privilege(''authenticated'', ''public.account_deletion_request_self_consented_v2(bigint)'', ''EXECUTE'') THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: deletion self v2 not executable'';\n  END IF;\n  IF has_function_privilege(''authenticated'', ''public.account_deletion_request_self(integer,boolean)'', ''EXECUTE'')\n     OR has_function_privilege(''authenticated'', ''public.account_deletion_request_self_consented(integer,boolean,bigint)'', ''EXECUTE'') THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: legacy deletion self RPC still executable'';\n  END IF;\n  -- S9\n  IF (SELECT count(*) FROM pg_policies WHERE schemaname=''public'' AND tablename=''favorites'') <> 3 THEN\n    RAISE EXCEPTION ''M2_SELFCHECK: favorites policy count != 3'';\n  END IF;\nEND $$;\n\ncommit;"], "idempotency_key": null}, {"name": "20260803163322_realtime_notification_convergence", "version": "20260803171053", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260803163322_realtime_notification_convergence.sql (수렴 M3)\n-- =============================================================================\n-- Realtime·알림 수렴 (지시서 §14). 선행조건: 수렴 M1(20260803162257) ·\n-- M2(20260803162808) 적용.\n--\n-- 소유 객체 (§23.3):\n--   N1. supabase_realtime publication 멱등 추가: notifications ·\n--       individual_questions · individual_question_messages ·\n--       individual_question_attachments (기존 question_* 3종 보존)\n--   N2. 알림 RLS·CHECK 수신자 정본화: recipient_user_id 를 SELECT/UPDATE 정책과\n--       notifications_at_least_one_recipient CHECK 에 포함 (레거시 컬럼 OR 유지)\n--   N3. 읽음 상태 단일화: 정본 is_read + read_at. 호환 기간 동안 `read` 미러\n--       트리거 + backfill. 개별 읽음 canonical RPC(mark_notification_read).\n--       기존 mark_all_notifications_read 는 유지(미러는 트리거가 수렴).\n--   N4. notification_unread_count_self() — 서버 전체 unread count.\n--       앱 분류 정책과 일치: 앱 제외 타입(new_order_message·new_application —\n--       앱 kGatedNotificationTypeCodes 정본)과 동일 목록을 count 에서 제외.\n--   N5. notification_transport_config (단일행) — push_transport_enabled 기본 false.\n--       record_domain_notification 은 인앱 알림 행을 항상 생성하되 outbox 는\n--       push_transport_enabled=true 일 때만 생성.\n--   N6. 기존 pending outbox 43행(attempt_count=0 · delivery 0) → status=''suppressed''\n--       (사유 last_error=''PUSH_TRANSPORT_DISABLED''). 삭제 0 · 총행수 불변.\n--   N7. users.notification_enabled 제거 — DB(proc/view/policy/index/trigger)·웹·앱\n--       소스 참조 0 실측(문서 주석 제외). 정본은 notification_settings.\n--   N8. OS push 비활성 부수: register_device_token authenticated EXECUTE 회수,\n--       notifications/notification_outbox 잉여 클라이언트 grant 정리\n--       (notifications 의 authenticated SELECT/UPDATE 는 기존 배포 웹 호환으로 유지)\n--\n-- rollback 정본: supabase/rollback/20260803163322_realtime_notification_convergence_rollback.sql\n-- =============================================================================\n\nbegin;\n\n-- -----------------------------------------------------------------------------\n-- 사전 게이트\n-- -----------------------------------------------------------------------------\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid=''public.users''::regclass AND tgname=''trg_users_protected_columns'') THEN\n    RAISE EXCEPTION ''M3_BASELINE_MISMATCH: M1 not applied'';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_publication WHERE pubname=''supabase_realtime'') THEN\n    RAISE EXCEPTION ''M3_BASELINE_MISMATCH: supabase_realtime publication missing'';\n  END IF;\n  -- 기존 question_* 3종 포함 확인 (보존 대상)\n  IF (SELECT count(*) FROM pg_publication_tables WHERE pubname=''supabase_realtime''\n       AND schemaname=''public'' AND tablename IN (''question_threads'',''question_messages'',''question_attachments'')) <> 3 THEN\n    RAISE EXCEPTION ''M3_BASELINE_MISMATCH: question realtime tables missing'';\n  END IF;\n  IF to_regclass(''public.notification_transport_config'') IS NOT NULL\n     OR EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace\n                 WHERE n.nspname=''public'' AND p.proname IN\n                   (''mark_notification_read'',''notification_unread_count_self'',''notifications_read_state_sync'')) THEN\n    RAISE EXCEPTION ''M3_BASELINE_MISMATCH: target object already exists'';\n  END IF;\n  -- outbox 상태 분포: suppress 대상 외 상태 존재 시 검토 필요 (pending 외 상태는 건드리지 않음)\n  IF EXISTS (SELECT 1 FROM public.notification_outbox WHERE status NOT IN (''pending'',''leased'',''sent'',''failed'',''dead'')) THEN\n    RAISE EXCEPTION ''M3_BASELINE_MISMATCH: unexpected outbox status'';\n  END IF;\n  -- users.notification_enabled 참조 0 확인 (DB 객체)\n  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace\n              WHERE n.nspname NOT IN (''pg_catalog'',''information_schema'')\n                AND p.prosrc ILIKE ''%notification_enabled%'')\n     OR EXISTS (SELECT 1 FROM pg_views WHERE schemaname NOT IN (''pg_catalog'',''information_schema'')\n                 AND definition ILIKE ''%notification_enabled%'')\n     OR EXISTS (SELECT 1 FROM pg_policies WHERE coalesce(qual,'''')||coalesce(with_check,'''') ILIKE ''%notification_enabled%'') THEN\n    RAISE EXCEPTION ''M3_BASELINE_MISMATCH: notification_enabled still referenced — drop 보류(BLOCKED)'';\n  END IF;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- N1. Realtime publication 멱등 추가\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE t text;\nBEGIN\n  FOREACH t IN ARRAY ARRAY[''notifications'',''individual_questions'',\n                           ''individual_question_messages'',''individual_question_attachments''] LOOP\n    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables\n                    WHERE pubname=''supabase_realtime'' AND schemaname=''public'' AND tablename=t) THEN\n      EXECUTE format(''alter publication supabase_realtime add table public.%I'', t);\n    END IF;\n  END LOOP;\nEND $$;\n\n-- -----------------------------------------------------------------------------\n-- N2. 알림 수신자 정본화 (recipient_user_id 포함 — 레거시 OR 유지)\n-- -----------------------------------------------------------------------------\nalter table public.notifications drop constraint if exists notifications_at_least_one_recipient;\nalter table public.notifications\n  add constraint notifications_at_least_one_recipient\n  check (recipient_user_id is not null or user_id is not null or recipient_id is not null\n         or student_id is not null or mentor_id is not null\n         or target_user_id is not null or owner_id is not null);\n\ndrop policy if exists notif_select_recipient on public.notifications;\ncreate policy notif_select_recipient on public.notifications\n  for select to authenticated\n  using (\n    ((recipient_user_id is not null) and ((select auth.uid()) = recipient_user_id))\n    or ((user_id is not null) and ((select auth.uid()) = user_id))\n    or ((recipient_id is not null) and ((select auth.uid()) = recipient_id))\n    or ((student_id is not null) and ((select auth.uid()) = student_id))\n    or ((mentor_id is not null) and ((select auth.uid()) = mentor_id))\n    or ((target_user_id is not null) and ((select auth.uid()) = target_user_id))\n    or ((owner_id is not null) and ((select auth.uid()) = owner_id))\n  );\n\ndrop policy if exists notif_update_recipient_read on public.notifications;\ncreate policy notif_update_recipient_read on public.notifications\n  for update to authenticated\n  using (\n    ((recipient_user_id is not null) and ((select auth.uid()) = recipient_user_id))\n    or ((user_id is not null) and ((select auth.uid()) = user_id))\n    or ((recipient_id is not null) and ((select auth.uid()) = recipient_id))\n    or ((student_id is not null) and ((select auth.uid()) = student_id))\n    or ((mentor_id is not null) and ((select auth.uid()) = mentor_id))\n    or ((target_user_id is not null) and ((select auth.uid()) = target_user_id))\n    or ((owner_id is not null) and ((select auth.uid()) = owner_id))\n  )\n  with check (\n    ((recipient_user_id is not null) and ((select auth.uid()) = recipient_user_id))\n    or ((user_id is not null) and ((select auth.uid()) = user_id))\n    or ((recipient_id is not null) and ((select auth.uid()) = recipient_id))\n    or ((student_id is not null) and ((select auth.uid()) = student_id))\n    or ((mentor_id is not null) and ((select auth.uid()) = mentor_id))\n    or ((target_user_id is not null) and ((select auth.uid()) = target_user_id))\n    or ((owner_id is not null) and ((select auth.uid()) = owner_id))\n  );\n\n-- -----------------------------------------------------------------------------\n-- N3. 읽음 상태 단일화 — 정본 is_read/read_at, `read` 미러 트리거 + backfill\n-- -----------------------------------------------------------------------------\ncreate function public.notifications_read_state_sync()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = ''''\nas $fn$\nbegin\n  if tg_op = ''INSERT'' then\n    if new.is_read is null then new.is_read := coalesce(new.read, false); end if;\n    new.read := new.is_read;\n    if new.is_read and new.read_at is null then new.read_at := now(); end if;\n    return new;\n  end if;\n  -- UPDATE: 어느 쪽이 갱신되든 정본(is_read)으로 수렴 후 미러\n  if new.is_read is distinct from old.is_read then\n    new.read := new.is_read;\n  elsif coalesce(new.read, false) is distinct from coalesce(old.read, false) then\n    new.is_read := coalesce(new.read, false);\n    new.read := new.is_read;\n  else\n    new.read := new.is_read;\n  end if;\n  if new.is_read then\n    if new.read_at is null then new.read_at := now(); end if;\n  else\n    new.read_at := null;\n  end if;\n  return new;\nend\n$fn$;\n\nrevoke execute on function public.notifications_read_state_sync() from public, anon, authenticated;\n\ncreate trigger trg_notifications_read_state_sync\n  before insert or update on public.notifications\n  for each row execute function public.notifications_read_state_sync();\n\n-- backfill (허용 데이터 변화 — read flag 정합화, 행 수 불변)\nupdate public.notifications set is_read = true\n where coalesce(read, false) = true and is_read is distinct from true;\nupdate public.notifications\n   set read_at = coalesce(read_at, read_at_utc, acknowledged_at, opened_at, viewed_at, seen_at, updated_at)\n where is_read = true and read_at is null;\nupdate public.notifications set read = is_read\n where read is distinct from is_read;\n\n-- 개별 읽음 canonical RPC\ncreate function public.mark_notification_read(p_notification_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_row public.notifications%rowtype;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n  select * into v_row from public.notifications where id = p_notification_id for update;\n  if not found then\n    raise exception ''NOTIFICATION_NOT_FOUND'' using errcode = ''P0001'';\n  end if;\n  if not coalesce(\n      (v_row.recipient_user_id = v_uid or v_row.user_id = v_uid or v_row.recipient_id = v_uid\n       or v_row.student_id = v_uid or v_row.mentor_id = v_uid\n       or v_row.target_user_id = v_uid or v_row.owner_id = v_uid), false) then\n    raise exception ''NOT_RECIPIENT'' using errcode = ''42501'';\n  end if;\n  if coalesce(v_row.is_read, false) then\n    return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''idempotent_hit'', true);\n  end if;\n  update public.notifications\n     set is_read = true, read_at = coalesce(read_at, now()), updated_at = now()\n   where id = p_notification_id;\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''idempotent_hit'', false);\nend\n$fn$;\n\nrevoke execute on function public.mark_notification_read(uuid) from public, anon;\ngrant execute on function public.mark_notification_read(uuid) to authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- N4. 서버 전체 unread count (앱 배지 정본)\n-- -----------------------------------------------------------------------------\ncreate function public.notification_unread_count_self()\nreturns jsonb\nlanguage sql stable\nsecurity definer\nset search_path = ''''\nas $fn$\n  select jsonb_build_object(\n    ''ok'', true,\n    ''contract_version'', 1,\n    ''count'', (\n      select count(*)\n        from public.notifications n\n       where n.is_read is distinct from true\n         and ((n.recipient_user_id is not null and n.recipient_user_id = (select auth.uid()))\n              or (n.user_id is not null and n.user_id = (select auth.uid()))\n              or (n.recipient_id is not null and n.recipient_id = (select auth.uid()))\n              or (n.student_id is not null and n.student_id = (select auth.uid()))\n              or (n.mentor_id is not null and n.mentor_id = (select auth.uid()))\n              or (n.target_user_id is not null and n.target_user_id = (select auth.uid()))\n              or (n.owner_id is not null and n.owner_id = (select auth.uid())))\n         -- 앱 제외 타입 — 앱 classifier(kGatedNotificationTypeCodes)와 단일 정본.\n         -- 목록·count 가 같은 predicate 를 쓰도록 앱 계약 테스트가 고정한다.\n         and coalesce(n.type, '''') not in (''new_order_message'', ''new_application'')\n    )\n  );\n$fn$;\n\nrevoke execute on function public.notification_unread_count_self() from public, anon;\ngrant execute on function public.notification_unread_count_self() to authenticated, service_role;\n\n-- -----------------------------------------------------------------------------\n-- N5. 전역 전달 설정 + record_domain_notification outbox 게이트\n-- -----------------------------------------------------------------------------\ncreate table public.notification_transport_config (\n  id boolean primary key default true check (id),\n  push_transport_enabled boolean not null default false,\n  updated_at timestamptz not null default now()\n);\nalter table public.notification_transport_config enable row level security;\nrevoke all on table public.notification_transport_config from public, anon, authenticated;\ninsert into public.notification_transport_config (id, push_transport_enabled) values (true, false);\n\ncreate or replace function public.record_domain_notification(\n  p_recipient_user_id uuid, p_event_key text, p_dedup_key text, p_event_type text,\n  p_title text, p_body text, p_link text default null, p_metadata jsonb default ''{}''::jsonb, p_payload jsonb default ''{}''::jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = ''''\nas $fn$\ndeclare\n  v_notif_id uuid; v_outbox_id uuid;\n  v_notif_created boolean := false; v_outbox_created boolean := false;\n  v_push_enabled boolean := false;\nbegin\n  if p_recipient_user_id is null then raise exception ''RECIPIENT_REQUIRED''; end if;\n  if p_event_key is null or p_dedup_key is null or p_event_type is null then raise exception ''EVENT_KEYS_REQUIRED''; end if;\n  insert into public.notifications (recipient_user_id, user_id, event_key, type, body, metadata, data, is_read)\n  values (p_recipient_user_id, p_recipient_user_id, p_event_key, p_event_type, p_body,\n     coalesce(p_metadata,''{}''::jsonb) || jsonb_build_object(''event_key'', p_event_key, ''link'', p_link),\n     jsonb_build_object(''title'', p_title, ''link'', p_link), false)\n  on conflict (recipient_user_id, event_key) where recipient_user_id is not null and event_key is not null\n  do nothing returning id into v_notif_id;\n  v_notif_created := v_notif_id is not null;\n  if v_notif_id is null then\n    select id into v_notif_id from public.notifications where recipient_user_id = p_recipient_user_id and event_key = p_event_key limit 1;\n  end if;\n\n  -- OS push 전송로가 꺼져 있으면 outbox 를 새로 적재하지 않는다 (§14.6).\n  -- 인앱 알림 행·멱등 계약은 위에서 그대로 유지됐다.\n  select c.push_transport_enabled into v_push_enabled\n    from public.notification_transport_config c where c.id is true;\n  if coalesce(v_push_enabled, false) then\n    insert into public.notification_outbox (recipient_user_id, notification_id, event_key, dedup_key, event_type, payload)\n    values (p_recipient_user_id, v_notif_id, p_event_key, p_dedup_key, p_event_type,\n       coalesce(p_payload,''{}''::jsonb) || jsonb_build_object(''event_key'', p_event_key, ''notification_id'', v_notif_id))\n    on conflict (recipient_user_id, dedup_key) do nothing returning id into v_outbox_id;\n    v_outbox_created := v_outbox_id is not null;\n    if v_outbox_id is null then\n      select id into v_outbox_id from public.notification_outbox where recipient_user_id = p_recipient_user_id and dedup_key = p_dedup_key limit 1;\n    end if;\n  end if;\n\n  return jsonb_build_object(''ok'',true,''notification_id'',v_notif_id,''outbox_id'',v_outbox_id,\n    ''notification_created'',v_notif_created,''outbox_created'',v_outbox_created);\nend;\n$fn$;\n\n-- -----------------------------------------------------------------------------\n-- N6. 기존 pending outbox suppress (삭제 0 · 총행수 불변)\n-- -----------------------------------------------------------------------------\nalter table public.notification_outbox drop constraint if exists notification_outbox_status_chk;\nalter table public.notification_outbox\n  add constraint notification_outbox_status_chk\n  check (status = any (array[''pending''::text,''leased''::text,''sent''::text,''failed''::text,''dead''::text,''suppressed''::text]));\n\nupdate public.notification_outbox o\n   set status = ''suppressed'',\n       last_error = ''PUSH_TRANSPORT_DISABLED'',\n       updated_at = now()\n where o.status = ''pending''\n   and o.attempt_count = 0\n   and not exists (select 1 from public.notification_deliveries d where d.outbox_id = o.id);\n\n-- -----------------------------------------------------------------------------\n-- N7. users.notification_enabled 제거 (참조 0 — 사전 게이트에서 재확인)\n-- -----------------------------------------------------------------------------\nalter table public.users drop column notification_enabled;\n\n-- -----------------------------------------------------------------------------\n-- N8. OS push 비활성 부수 정리\n-- -----------------------------------------------------------------------------\nrevoke execute on function public.register_device_token(text, text) from public, anon, authenticated;\nrevoke all on table public.notification_outbox from anon, authenticated;\nrevoke insert, delete, truncate, references, trigger on table public.notifications from anon, authenticated;\nrevoke select, update on table public.notifications from anon;\n\n-- -----------------------------------------------------------------------------\n-- 자가 검증\n-- -----------------------------------------------------------------------------\nDO $$\nDECLARE v_pending int; v_suppressed int; v_total int;\nBEGIN\n  -- N1: publication 7테이블\n  IF (SELECT count(*) FROM pg_publication_tables WHERE pubname=''supabase_realtime'' AND schemaname=''public''\n       AND tablename IN (''question_threads'',''question_messages'',''question_attachments'',\n                         ''notifications'',''individual_questions'',''individual_question_messages'',\n                         ''individual_question_attachments'')) <> 7 THEN\n    RAISE EXCEPTION ''M3_SELFCHECK: publication tables incomplete'';\n  END IF;\n  -- N2: recipient_user_id 포함\n  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname=''public'' AND tablename=''notifications''\n                  AND policyname=''notif_select_recipient'' AND qual LIKE ''%recipient_user_id%'') THEN\n    RAISE EXCEPTION ''M3_SELFCHECK: select policy missing recipient_user_id'';\n  END IF;\n  -- N3: 미러 일치\n  IF EXISTS (SELECT 1 FROM public.notifications WHERE read IS DISTINCT FROM is_read) THEN\n    RAISE EXCEPTION ''M3_SELFCHECK: read mirror mismatch'';\n  END IF;\n  IF EXISTS (SELECT 1 FROM public.notifications WHERE is_read = true AND read_at IS NULL) THEN\n    RAISE EXCEPTION ''M3_SELFCHECK: read_at backfill incomplete'';\n  END IF;\n  -- N4/N3: RPC 존재·권한\n  IF NOT has_function_privilege(''authenticated'', ''public.notification_unread_count_self()'', ''EXECUTE'')\n     OR NOT has_function_privilege(''authenticated'', ''public.mark_notification_read(uuid)'', ''EXECUTE'') THEN\n    RAISE EXCEPTION ''M3_SELFCHECK: notification RPC grants'';\n  END IF;\n  -- N5/N6: push disabled 상태에서 pending=0, suppressed>=0, 총행수 불변식은\n  --        migration 전후 카운트 비교(외부 검증 스크립트)로 재확인한다.\n  SELECT count(*) FILTER (WHERE status=''pending''), count(*) FILTER (WHERE status=''suppressed''), count(*)\n    INTO v_pending, v_suppressed, v_total FROM public.notification_outbox;\n  IF v_pending <> 0 THEN\n    RAISE EXCEPTION ''M3_SELFCHECK: pending outbox remains (%). push disabled 상태에서 0 이어야 함'', v_pending;\n  END IF;\n  -- N7\n  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=''public'' AND table_name=''users'' AND column_name=''notification_enabled'') THEN\n    RAISE EXCEPTION ''M3_SELFCHECK: notification_enabled still present'';\n  END IF;\n  -- N8\n  IF has_function_privilege(''authenticated'', ''public.register_device_token(text,text)'', ''EXECUTE'') THEN\n    RAISE EXCEPTION ''M3_SELFCHECK: register_device_token still executable'';\n  END IF;\nEND $$;\n\ncommit;"], "idempotency_key": null}, {"name": "20260804035019_iq_append_message_execute_acl_hardening", "version": "20260804040019", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- DB-GRANT-HYGIENE-001: iq_append_message(uuid,text) execute-ACL hardening.\n--权限만 조정 (revoke PUBLIC/anon, grant authenticated/service_role). 본문·시그니처·\n-- SECURITY DEFINER·search_path 불변. 정합 표준 = M2 shortform_view_record_v2 위생.\nbegin;\n\ndo $$\nbegin\n  if to_regprocedure(''public.iq_append_message(uuid,text)'') is null then\n    raise exception ''target function public.iq_append_message(uuid,text) not found'';\n  end if;\nend\n$$;\n\nrevoke all privileges on function public.iq_append_message(uuid, text) from public, anon;\ngrant execute on function public.iq_append_message(uuid, text) to authenticated, service_role;\n\ndo $$\ndeclare\n  v_oid oid := to_regprocedure(''public.iq_append_message(uuid,text)'')::oid;\nbegin\n  if v_oid is null then\n    raise exception ''iq_append_message target function not found'';\n  end if;\n  if has_function_privilege(''anon'', v_oid, ''EXECUTE'') then\n    raise exception ''anon must not execute iq_append_message'';\n  end if;\n  if not has_function_privilege(''authenticated'', v_oid, ''EXECUTE'') then\n    raise exception ''authenticated execute missing'';\n  end if;\n  if not has_function_privilege(''service_role'', v_oid, ''EXECUTE'') then\n    raise exception ''service_role execute missing'';\n  end if;\nend\n$$;\n\ncommit;"], "idempotency_key": null}, {"name": "post_ledger_acl_convergence", "version": "20260804100000", "rollback": null, "created_by": null, "statements": ["-- interleave_20260804100000_post_ledger_acl_convergence.sql\n-- 원장 재생 종료 시점의 함수 EXECUTE ACL 을 부모 실측(functions.json)으로 수렴.\n-- 각 항목은 as-applied 발산(원장·저장소 밖 ACL 변경)의 문서화이자 복원이다.\n-- 방식: 4역할 전면 revoke 후 부모 실측 역할만 grant (postgres/owner 는 불변).\n-- public._cro_transition_actor_is_mentor(o custom_request_orders, p_actor uuid): local=[] -> parent=[''service_role'']\nrevoke all on function public._cro_transition_actor_is_mentor(o custom_request_orders, p_actor uuid) from public, anon, authenticated, service_role", "grant execute on function public._cro_transition_actor_is_mentor(o custom_request_orders, p_actor uuid) to service_role", "-- public._cro_transition_actor_is_student(o custom_request_orders, p_actor uuid): local=[] -> parent=[''service_role'']\nrevoke all on function public._cro_transition_actor_is_student(o custom_request_orders, p_actor uuid) from public, anon, authenticated, service_role", "grant execute on function public._cro_transition_actor_is_student(o custom_request_orders, p_actor uuid) to service_role", "-- public._cro_transition_deliverable_count(p_order_id uuid): local=[] -> parent=[''service_role'']\nrevoke all on function public._cro_transition_deliverable_count(p_order_id uuid) from public, anon, authenticated, service_role", "grant execute on function public._cro_transition_deliverable_count(p_order_id uuid) to service_role", "-- public._cro_transition_has_active_dispute(p_order_id uuid): local=[] -> parent=[''service_role'']\nrevoke all on function public._cro_transition_has_active_dispute(p_order_id uuid) from public, anon, authenticated, service_role", "grant execute on function public._cro_transition_has_active_dispute(p_order_id uuid) to service_role", "-- public._cro_transition_is_terminal(o custom_request_orders): local=[] -> parent=[''service_role'']\nrevoke all on function public._cro_transition_is_terminal(o custom_request_orders) from public, anon, authenticated, service_role", "grant execute on function public._cro_transition_is_terminal(o custom_request_orders) to service_role", "-- public._cro_transition_payment_confirmed(o custom_request_orders): local=[] -> parent=[''service_role'']\nrevoke all on function public._cro_transition_payment_confirmed(o custom_request_orders) from public, anon, authenticated, service_role", "grant execute on function public._cro_transition_payment_confirmed(o custom_request_orders) to service_role", "-- public._cro_transition_primary_status_col(o custom_request_orders): local=[] -> parent=[''service_role'']\nrevoke all on function public._cro_transition_primary_status_col(o custom_request_orders) from public, anon, authenticated, service_role", "grant execute on function public._cro_transition_primary_status_col(o custom_request_orders) to service_role", "-- public._cro_transition_primary_status_norm(o custom_request_orders): local=[] -> parent=[''service_role'']\nrevoke all on function public._cro_transition_primary_status_norm(o custom_request_orders) from public, anon, authenticated, service_role", "grant execute on function public._cro_transition_primary_status_norm(o custom_request_orders) to service_role", "-- public._cro_transition_revision_count(p_order_id uuid): local=[] -> parent=[''service_role'']\nrevoke all on function public._cro_transition_revision_count(p_order_id uuid) from public, anon, authenticated, service_role", "grant execute on function public._cro_transition_revision_count(p_order_id uuid) to service_role", "-- public.account_deletion_worker_claim(p_limit integer): local=[''service_role''] -> parent=[]\nrevoke all on function public.account_deletion_worker_claim(p_limit integer) from public, anon, authenticated, service_role", "-- public.answer_individual_question(p_question_id uuid, p_body text): local=[''authenticated''] -> parent=[''authenticated'', ''service_role'']\nrevoke all on function public.answer_individual_question(p_question_id uuid, p_body text) from public, anon, authenticated, service_role", "grant execute on function public.answer_individual_question(p_question_id uuid, p_body text) to authenticated, service_role", "-- public.check_free_question_usage_limits(): local=[''authenticated''] -> parent=[''authenticated'', ''service_role'']\nrevoke all on function public.check_free_question_usage_limits() from public, anon, authenticated, service_role", "grant execute on function public.check_free_question_usage_limits() to authenticated, service_role", "-- public.check_review_eligibility(p_mentor_id uuid, p_student_id uuid): local=[''authenticated''] -> parent=[''authenticated'', ''service_role'']\nrevoke all on function public.check_review_eligibility(p_mentor_id uuid, p_student_id uuid) from public, anon, authenticated, service_role", "grant execute on function public.check_review_eligibility(p_mentor_id uuid, p_student_id uuid) to authenticated, service_role", "-- public.claim_individual_question_as_mentor(p_question_id uuid): local=[''authenticated''] -> parent=[''authenticated'', ''service_role'']\nrevoke all on function public.claim_individual_question_as_mentor(p_question_id uuid) from public, anon, authenticated, service_role", "grant execute on function public.claim_individual_question_as_mentor(p_question_id uuid) to authenticated, service_role", "-- public.create_individual_question_as_student(p_question_type text, p_title text, p_body text, p_amount_cents integer, p_designated_mentor_id uuid, p_idempotency_key text): local=[''authenticated''] -> parent=[''authenticated'', ''service_role'']\nrevoke all on function public.create_individual_question_as_student(p_question_type text, p_title text, p_body text, p_amount_cents integer, p_designated_mentor_id uuid, p_idempotency_key text) from public, anon, authenticated, service_role", "grant execute on function public.create_individual_question_as_student(p_question_type text, p_title text, p_body text, p_amount_cents integer, p_designated_mentor_id uuid, p_idempotency_key text) to authenticated, service_role", "-- public.enforce_users_role_guard(): local=[] -> parent=[''service_role'']\nrevoke all on function public.enforce_users_role_guard() from public, anon, authenticated, service_role", "grant execute on function public.enforce_users_role_guard() to service_role", "-- public.enforce_users_role_insert_guard(): local=[] -> parent=[''service_role'']\nrevoke all on function public.enforce_users_role_insert_guard() from public, anon, authenticated, service_role", "grant execute on function public.enforce_users_role_insert_guard() to service_role", "-- public.get_public_custom_request_post_for_browse(p_post_id uuid): local=[''authenticated''] -> parent=[''anon'', ''authenticated'', ''service_role'']\nrevoke all on function public.get_public_custom_request_post_for_browse(p_post_id uuid) from public, anon, authenticated, service_role", "grant execute on function public.get_public_custom_request_post_for_browse(p_post_id uuid) to anon, authenticated, service_role", "-- public.get_weekly_question_usage(p_student_id uuid, p_mentor_id uuid): local=[''authenticated'', ''service_role''] -> parent=[''anon'', ''authenticated'', ''service_role'']\nrevoke all on function public.get_weekly_question_usage(p_student_id uuid, p_mentor_id uuid) from public, anon, authenticated, service_role", "grant execute on function public.get_weekly_question_usage(p_student_id uuid, p_mentor_id uuid) to anon, authenticated, service_role", "-- public.increment_shortform_post_view(p_post_id uuid): local=[] -> parent=[''service_role'']\nrevoke all on function public.increment_shortform_post_view(p_post_id uuid) from public, anon, authenticated, service_role", "grant execute on function public.increment_shortform_post_view(p_post_id uuid) to service_role", "-- public.list_open_custom_request_posts_for_mentor_browse(p_limit integer): local=[''authenticated''] -> parent=[''anon'', ''authenticated'', ''service_role'']\nrevoke all on function public.list_open_custom_request_posts_for_mentor_browse(p_limit integer) from public, anon, authenticated, service_role", "grant execute on function public.list_open_custom_request_posts_for_mentor_browse(p_limit integer) to anon, authenticated, service_role", "-- public.list_open_individual_questions_for_mentor(p_limit integer): local=[''authenticated''] -> parent=[''authenticated'', ''service_role'']\nrevoke all on function public.list_open_individual_questions_for_mentor(p_limit integer) from public, anon, authenticated, service_role", "grant execute on function public.list_open_individual_questions_for_mentor(p_limit integer) to authenticated, service_role", "-- public.mentor_directory_list(p_limit integer): local=[] -> parent=[''service_role'']\nrevoke all on function public.mentor_directory_list(p_limit integer) from public, anon, authenticated, service_role", "grant execute on function public.mentor_directory_list(p_limit integer) to service_role", "-- public.mentor_directory_list_v2(p_limit integer): local=[] -> parent=[''service_role'']\nrevoke all on function public.mentor_directory_list_v2(p_limit integer) from public, anon, authenticated, service_role", "grant execute on function public.mentor_directory_list_v2(p_limit integer) to service_role", "-- public.mentor_profiles_for_directory(p_ids uuid[]): local=[] -> parent=[''service_role'']\nrevoke all on function public.mentor_profiles_for_directory(p_ids uuid[]) from public, anon, authenticated, service_role", "grant execute on function public.mentor_profiles_for_directory(p_ids uuid[]) to service_role", "-- public.mentor_profiles_for_directory_v2(p_ids uuid[]): local=[] -> parent=[''service_role'']\nrevoke all on function public.mentor_profiles_for_directory_v2(p_ids uuid[]) from public, anon, authenticated, service_role", "grant execute on function public.mentor_profiles_for_directory_v2(p_ids uuid[]) to service_role", "-- public.mentor_school_verification_storage_path(p_ref text): local=[] -> parent=[''service_role'']\nrevoke all on function public.mentor_school_verification_storage_path(p_ref text) from public, anon, authenticated, service_role", "grant execute on function public.mentor_school_verification_storage_path(p_ref text) to service_role", "-- public.mentor_user_public(p_mentor_id uuid): local=[] -> parent=[''service_role'']\nrevoke all on function public.mentor_user_public(p_mentor_id uuid) from public, anon, authenticated, service_role", "grant execute on function public.mentor_user_public(p_mentor_id uuid) to service_role", "-- public.mentor_user_public_v2(p_mentor_id uuid): local=[] -> parent=[''service_role'']\nrevoke all on function public.mentor_user_public_v2(p_mentor_id uuid) from public, anon, authenticated, service_role", "grant execute on function public.mentor_user_public_v2(p_mentor_id uuid) to service_role", "-- public.mp_seed_default_plans_on_approval(): local=[] -> parent=[''service_role'']\nrevoke all on function public.mp_seed_default_plans_on_approval() from public, anon, authenticated, service_role", "grant execute on function public.mp_seed_default_plans_on_approval() to service_role", "-- public.notification_cash_label(p_amount_cents bigint): local=[] -> parent=[''anon'', ''authenticated'', ''service_role'']\nrevoke all on function public.notification_cash_label(p_amount_cents bigint) from public, anon, authenticated, service_role", "grant execute on function public.notification_cash_label(p_amount_cents bigint) to anon, authenticated, service_role", "-- public.notification_date_label(p_at timestamp with time zone): local=[] -> parent=[''anon'', ''authenticated'', ''service_role'']\nrevoke all on function public.notification_date_label(p_at timestamp with time zone) from public, anon, authenticated, service_role", "grant execute on function public.notification_date_label(p_at timestamp with time zone) to anon, authenticated, service_role", "-- public.notification_display_name(p_user_id uuid): local=[] -> parent=[''service_role'']\nrevoke all on function public.notification_display_name(p_user_id uuid) from public, anon, authenticated, service_role", "grant execute on function public.notification_display_name(p_user_id uuid) to service_role", "-- public.notification_mentor_label(p_user_id uuid): local=[] -> parent=[''service_role'']\nrevoke all on function public.notification_mentor_label(p_user_id uuid) from public, anon, authenticated, service_role", "grant execute on function public.notification_mentor_label(p_user_id uuid) to service_role", "-- public.refund_individual_question(p_question_id uuid): local=[''authenticated''] -> parent=[''authenticated'', ''service_role'']\nrevoke all on function public.refund_individual_question(p_question_id uuid) from public, anon, authenticated, service_role", "grant execute on function public.refund_individual_question(p_question_id uuid) to authenticated, service_role", "-- public.release_individual_question(p_question_id uuid): local=[''authenticated''] -> parent=[''authenticated'', ''service_role'']\nrevoke all on function public.release_individual_question(p_question_id uuid) from public, anon, authenticated, service_role", "grant execute on function public.release_individual_question(p_question_id uuid) to authenticated, service_role", "-- public.set_individual_question_price(p_amount_cents integer): local=[''authenticated''] -> parent=[''authenticated'', ''service_role'']\nrevoke all on function public.set_individual_question_price(p_amount_cents integer) from public, anon, authenticated, service_role", "grant execute on function public.set_individual_question_price(p_amount_cents integer) to authenticated, service_role", "-- 부모 부재 함수 정리 (as-applied 발산: 로컬 재구축만 생성)\ndrop function if exists public.pay_due_payouts_for_run(date, text)", "drop function if exists public.mark_individual_question_released(uuid)"], "idempotency_key": null}, {"name": "post_ledger_attr_convergence", "version": "20260804100001", "rollback": null, "created_by": null, "statements": ["-- interleave_20260804100001_post_ledger_attr_convergence.sql\n-- as-applied 속성 발산 수렴: 컬럼 null/default · FK 정의 · due_payouts 뷰 (부모 실측 원문).\n-- [컬럼 null/default — 부모 실측으로]\nalter table public.admin_action_logs alter column created_at drop not null", "alter table public.comments alter column author_id drop not null", "alter table public.comments alter column created_at drop not null", "alter table public.comments alter column is_deleted drop not null", "alter table public.comments alter column like_count drop not null", "alter table public.comments alter column post_id drop not null", "alter table public.community_hashtags alter column count drop not null", "alter table public.community_posts alter column comment_count drop not null", "alter table public.community_posts alter column hashtags drop not null", "alter table public.community_posts alter column image_urls drop not null", "alter table public.community_posts alter column like_count drop not null", "alter table public.community_posts alter column status drop not null", "alter table public.community_posts alter column updated_at set default now()", "alter table public.community_posts alter column view_count drop not null", "alter table public.custom_request_applications alter column estimated_days set default 7", "alter table public.custom_request_applications alter column portfolio_urls drop not null", "alter table public.custom_request_posts alter column file_urls drop not null", "alter table public.favorites alter column created_at drop not null", "alter table public.favorites alter column mentor_id drop not null", "alter table public.favorites alter column user_id drop not null", "alter table public.payout_run_items alter column withholding_cents set not null", "alter table public.payout_run_items alter column withholding_cents set default 0", "alter table public.post_reactions alter column created_at drop not null", "alter table public.post_reactions alter column post_id drop not null", "alter table public.post_reactions alter column type drop not null", "alter table public.post_reactions alter column user_id drop not null", "alter table public.scan_annotations alter column annotation_json drop not null", "alter table public.scan_annotations alter column annotation_json drop default", "alter table public.scan_annotations alter column scan_image_path set not null", "alter table public.shortform_posts alter column like_count drop not null", "alter table public.shortform_posts alter column status drop not null", "alter table public.shortform_posts alter column tags drop not null", "alter table public.shortform_posts alter column updated_at set default now()", "alter table public.shortform_posts alter column view_count drop not null", "-- [FK 정의 — 부모 실측으로 drop 후 재생성]\nalter table public.admin_action_logs drop constraint admin_action_logs_admin_id_fkey", "alter table public.admin_action_logs add constraint admin_action_logs_admin_id_fkey FOREIGN KEY (admin_id) REFERENCES auth.users(id)", "alter table public.comments drop constraint comments_author_id_fkey", "alter table public.comments add constraint comments_author_id_fkey FOREIGN KEY (author_id) REFERENCES auth.users(id) ON DELETE CASCADE", "alter table public.disputes drop constraint disputes_submitted_by_fkey", "alter table public.disputes add constraint disputes_submitted_by_fkey FOREIGN KEY (submitted_by) REFERENCES auth.users(id)", "alter table public.favorites drop constraint favorites_mentor_id_fkey", "alter table public.favorites add constraint favorites_mentor_id_fkey FOREIGN KEY (mentor_id) REFERENCES mentor_profiles(user_id) ON DELETE CASCADE", "alter table public.favorites drop constraint favorites_user_id_fkey", "alter table public.favorites add constraint favorites_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE", "alter table public.post_reactions drop constraint post_reactions_user_id_fkey", "alter table public.post_reactions add constraint post_reactions_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE", "alter table public.scan_annotations drop constraint scan_annotations_author_id_fkey", "alter table public.scan_annotations add constraint scan_annotations_author_id_fkey FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE CASCADE", "alter table public.shortform_posts drop constraint shortform_posts_creator_id_fkey", "alter table public.shortform_posts add constraint shortform_posts_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES auth.users(id)", "-- [due_payouts 뷰 — 부모 as-applied 정의로 재생성 (or-replace 는 컬럼 축소 불가)]\ndrop view if exists public.due_payouts", "create view public.due_payouts as  SELECT ''subscription''::text AS source_type,\n    ssi.id AS source_id,\n    ssi.mentor_id,\n    ssi.mentor_amount_cents,\n    ssi.gross_cents,\n    ssi.platform_fee_cents,\n    ssi.fee_rate,\n    ssi.period_end AS completion_ts\n   FROM subscription_settlement_items ssi\n  WHERE ((ssi.period_end IS NOT NULL) AND (ssi.period_end <= now()) AND (ssi.status <> ALL (ARRAY[''paid''::text, ''hold''::text, ''canceled''::text])))\nUNION ALL\n SELECT ''custom_request''::text AS source_type,\n    cs.id AS source_id,\n    cs.mentor_id,\n    ((cs.mentor_amount)::bigint * 100) AS mentor_amount_cents,\n    ((cs.gross_amount)::bigint * 100) AS gross_cents,\n    ((cs.platform_fee_amount)::bigint * 100) AS platform_fee_cents,\n    cs.fee_rate,\n    o.accepted_at AS completion_ts\n   FROM (custom_order_settlement_items cs\n     JOIN custom_request_orders o ON ((o.id = cs.custom_request_order_id)))\n  WHERE ((cs.status = ANY (ARRAY[''pending''::text, ''on_hold''::text, ''payable''::text])) AND (o.accepted_at IS NOT NULL) AND (o.accepted_at <= now()) AND (COALESCE(lower(TRIM(BOTH FROM o.payment_status)), ''''::text) <> ''refunded''::text) AND (COALESCE(lower(TRIM(BOTH FROM o.status)), ''''::text) <> ALL (ARRAY[''cancelled''::text, ''canceled''::text, ''refunded''::text])) AND (NOT (EXISTS ( SELECT 1\n           FROM disputes d\n          WHERE ((d.custom_request_order_id = o.id) AND (d.status = ANY (ARRAY[''open''::text, ''under_review''::text, ''escalated''::text])))))))\nUNION ALL\n SELECT ''individual_question''::text AS source_type,\n    q.id AS source_id,\n    COALESCE(q.claimed_mentor_id, q.designated_mentor_id) AS mentor_id,\n    (floor(((q.price_cents)::numeric * 0.85)))::bigint AS mentor_amount_cents,\n    (q.price_cents)::bigint AS gross_cents,\n    (q.price_cents - (floor(((q.price_cents)::numeric * 0.85)))::bigint) AS platform_fee_cents,\n    0.15 AS fee_rate,\n    q.released_at AS completion_ts\n   FROM individual_questions q\n  WHERE ((q.released_at IS NOT NULL) AND (q.released_at <= now()) AND (q.release_ledger_id IS NULL) AND (q.refund_ledger_id IS NULL) AND (q.status <> ALL (ARRAY[''refunded''::text, ''expired''::text, ''canceled''::text])) AND (COALESCE(q.claimed_mentor_id, q.designated_mentor_id) IS NOT NULL))", "grant DELETE, INSERT, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE on public.due_payouts to service_role", "-- 부모 실측: anon/authenticated 는 due_payouts 에 어떤 권한도 없다(hardened 기본 잔여분 제거)\nrevoke all on public.due_payouts from anon, authenticated"], "idempotency_key": null}, {"name": "as_applied_function_bodies", "version": "20260804100002", "rollback": null, "created_by": null, "statements": ["-- postledger_as_applied_function_bodies.sql — 부모 as-applied 함수 본문 32건 (pg_get_functiondef 원문). 저장소 파일과 CR 제거 후에도 불일치하는 실측 정본.\n\n-- public.accept_custom_order_deliverable_atomic(p_order_id uuid, p_student_id uuid, p_require_payment boolean)\nCREATE OR REPLACE FUNCTION public.accept_custom_order_deliverable_atomic(p_order_id uuid, p_student_id uuid, p_require_payment boolean DEFAULT true)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\r\ndeclare\r\n  o public.custom_request_orders%rowtype;\r\n  app public.custom_request_applications%rowtype;\r\n  v_norm text;\r\n  v_pay text;\r\n  v_dispute_cnt integer;\r\n  v_deliverable_cnt integer;\r\n  v_existing_settlement uuid;\r\n  v_gross integer;\r\n  v_platform_fee integer;\r\n  v_mentor_amount integer;\r\n  v_settlement_id uuid;\r\n  v_settlement_created boolean := false;\r\n  v_payout_done boolean := false;\r\n  v_now timestamptz := now();\r\n  v_fee_rate numeric := 0.05;  -- 252: 맞춤의뢰 수수료 5%\r\nbegin\r\n  if p_order_id is null then\r\n    return jsonb_build_object(''ok'', false, ''message'', ''orderId가 필요합니다.'');\r\n  end if;\r\n  if p_student_id is null then\r\n    return jsonb_build_object(''ok'', false, ''message'', ''학생 ID가 필요합니다.'');\r\n  end if;\r\n\r\n  select * into o\r\n  from public.custom_request_orders\r\n  where id = p_order_id\r\n  for update;\r\n\r\n  if not found then\r\n    return jsonb_build_object(''ok'', false, ''message'', ''주문을 찾을 수 없어요.'');\r\n  end if;\r\n\r\n  if o.student_id is distinct from p_student_id then\r\n    return jsonb_build_object(''ok'', false, ''message'', ''의뢰자(학생) 본인만 납품을 수락할 수 있습니다.'');\r\n  end if;\r\n\r\n  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''''), '''')));\r\n  -- escrowed(예치 완료) 또는 paid(멱등·수리) 만 허용. unpaid 등 레거시 무예치 차단.\r\n  if p_require_payment and v_pay not in (''paid'', ''escrowed'') then\r\n    return jsonb_build_object(''ok'', false, ''message'', ''결제(예치)가 완료되지 않은 주문은 수락할 수 없습니다.'');\r\n  end if;\r\n\r\n  if o.completed_at is not null\r\n     or o.closed_at is not null\r\n     or o.finished_at is not null\r\n     or lower(trim(coalesce(o.status, ''''))) in (\r\n       ''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',\r\n       ''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved''\r\n     )\r\n     or lower(trim(coalesce(o.state, ''''))) in (\r\n       ''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',\r\n       ''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved''\r\n     )\r\n     or lower(trim(coalesce(o.order_status, ''''))) in (\r\n       ''completed'',''accepted'',''closed'',''finished'',''cancelled'',''canceled'',\r\n       ''refunded'',''rejected'',''done'',''resolved'',''dispute_resolved''\r\n     )\r\n  then\r\n    return jsonb_build_object(''ok'', false, ''message'', ''이미 완료된 주문입니다.'');\r\n  end if;\r\n\r\n  v_norm := public._order_primary_status_norm(o);\r\n  if v_norm = '''' then\r\n    return jsonb_build_object(''ok'', false, ''message'', ''주문 상태를 확인할 수 없어 수락할 수 없습니다.'');\r\n  end if;\r\n\r\n  if v_norm not in (\r\n    ''delivered'',''delivered_pending_review'',''waiting_review'',''pending_review'',\r\n    ''redelivered'',''delivery_submitted'',''in_review''\r\n  ) then\r\n    return jsonb_build_object(\r\n      ''ok'', false,\r\n      ''message'', format(''현재 상태(%s)에서는 납품 수락을 할 수 없습니다.'', v_norm)\r\n    );\r\n  end if;\r\n\r\n  select count(*)::integer into v_dispute_cnt\r\n  from public.disputes d\r\n  where d.custom_request_order_id = p_order_id\r\n    and d.status in (''open'', ''under_review'', ''escalated'');\r\n\r\n  if v_dispute_cnt > 0 then\r\n    return jsonb_build_object(''ok'', false, ''message'', ''진행 중인 분쟁이 있어 납품 수락을 할 수 없습니다.'');\r\n  end if;\r\n\r\n  select count(*)::integer into v_deliverable_cnt\r\n  from public.custom_order_deliverables d\r\n  where d.custom_request_order_id = p_order_id;\r\n\r\n  if v_deliverable_cnt < 1 then\r\n    return jsonb_build_object(''ok'', false, ''message'', ''등록된 납품이 없어 수락할 수 없습니다.'');\r\n  end if;\r\n\r\n  select id into v_existing_settlement\r\n  from public.custom_order_settlement_items s\r\n  where s.custom_request_order_id = p_order_id;\r\n\r\n  select a.* into app\r\n  from public.custom_request_applications a\r\n  where a.id = coalesce(o.application_id, o.custom_request_application_id, o.selected_application_id)\r\n  limit 1;\r\n\r\n  if v_existing_settlement is null then\r\n    v_gross := public._pick_custom_order_gross_won(o, app);\r\n    if v_gross is not null and v_gross > 0 then\r\n      v_platform_fee := floor(v_gross * v_fee_rate)::integer;\r\n      v_mentor_amount := v_gross - v_platform_fee;\r\n\r\n      insert into public.custom_order_settlement_items (\r\n        custom_request_order_id,\r\n        mentor_id,\r\n        student_id,\r\n        gross_amount,\r\n        platform_fee_amount,\r\n        mentor_amount,\r\n        fee_rate,\r\n        status\r\n      ) values (\r\n        p_order_id,\r\n        o.mentor_id,\r\n        o.student_id,\r\n        v_gross,\r\n        v_platform_fee,\r\n        v_mentor_amount,\r\n        v_fee_rate,\r\n        ''pending''\r\n      )\r\n      returning id into v_settlement_id;\r\n\r\n      v_settlement_created := true;\r\n    end if;\r\n  else\r\n    v_settlement_id := v_existing_settlement;\r\n  end if;\r\n\r\n  update public.custom_request_orders\r\n  set\r\n    status = ''completed'',\r\n    state = ''completed'',\r\n    order_status = ''completed'',\r\n    accepted_at = coalesce(accepted_at, v_now),\r\n    completed_at = coalesce(completed_at, v_now),\r\n    updated_at = v_now\r\n  where id = p_order_id;\r\n\r\n  if v_settlement_id is not null then\r\n    perform public.record_custom_order_escrow_payout(p_order_id);\r\n    v_payout_done := true;\r\n  end if;\r\n\r\n  return jsonb_build_object(\r\n    ''ok'', true,\r\n    ''settlement_created'', v_settlement_created,\r\n    ''settlement_id'', v_settlement_id,\r\n    ''gross'', v_gross,\r\n    ''fee_rate'', v_fee_rate,\r\n    ''payout_done'', v_payout_done\r\n  );\r\nexception\r\n  when others then\r\n    if sqlstate = ''23505'' then\r\n      select id into v_existing_settlement\r\n      from public.custom_order_settlement_items s\r\n      where s.custom_request_order_id = p_order_id;\r\n\r\n      update public.custom_request_orders\r\n      set\r\n        status = ''completed'',\r\n        state = ''completed'',\r\n        order_status = ''completed'',\r\n        accepted_at = coalesce(accepted_at, v_now),\r\n        completed_at = coalesce(completed_at, v_now),\r\n        updated_at = v_now\r\n      where id = p_order_id;\r\n\r\n      if v_existing_settlement is not null then\r\n        perform public.record_custom_order_escrow_payout(p_order_id);\r\n        v_payout_done := true;\r\n      end if;\r\n\r\n      return jsonb_build_object(\r\n        ''ok'', true,\r\n        ''settlement_created'', false,\r\n        ''settlement_id'', v_existing_settlement,\r\n        ''payout_done'', v_payout_done,\r\n        ''reason'', ''already_exists''\r\n      );\r\n    end if;\r\n    raise;\r\nend;\r\n$function$", "-- public.account_deletion_advance(p_user_id uuid, p_from text, p_to text)\nCREATE OR REPLACE FUNCTION public.account_deletion_advance(p_user_id uuid, p_from text, p_to text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_rows int := 0; v_col text; v_id uuid;\nbegin\n  if p_from=''pending'' and p_to=''locked'' then\n    raise exception ''USE_BEGIN_LOCKED: pending->locked must go through account_deletion_begin_locked''\n      using errcode = ''42501'';\n  end if;\n\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is null then return false; end if;\n\n  if not (\n    (p_from=''locked'' and p_to=''purging'') or\n    (p_from=''purging'' and p_to=''storage_purged'') or\n    (p_from=''storage_purged'' and p_to=''finalized'') or\n    (p_from=''finalized'' and p_to=''auth_soft_deleted'') or\n    (p_from=''auth_soft_deleted'' and p_to=''completed'')\n  ) then\n    raise exception ''INVALID_TRANSITION % -> %'', p_from, p_to;\n  end if;\n\n  v_col := p_to || ''_at'';\n  execute format(\n    ''update public.account_deletion_jobs set state=$2, %I=now(), updated_at=now() where id=$1 and state=$3'',\n    v_col\n  ) using v_id, p_to, p_from;\n  get diagnostics v_rows = row_count;\n  return v_rows > 0;\nend $function$", "-- public.account_deletion_begin_locked(p_user_id uuid)\nCREATE OR REPLACE FUNCTION public.account_deletion_begin_locked(p_user_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_id uuid; v_state text; v_cancelable timestamptz;\n  v_consent_at timestamptz; v_consented bigint; v_balance bigint; v_rows int;\nbegin\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is null then return jsonb_build_object(''ok'',false,''code'',''JOB_NOT_FOUND''); end if;\n\n  select j.state, j.cancelable_until, j.forfeit_consent_at, j.consented_balance_cents\n    into v_state, v_cancelable, v_consent_at, v_consented\n    from public.account_deletion_jobs j where j.id = v_id for update;\n  if not found then return jsonb_build_object(''ok'',false,''code'',''JOB_NOT_FOUND''); end if;\n  if v_state <> ''pending'' then\n    return jsonb_build_object(''ok'',false,''code'',''NOT_PENDING'',''state'',v_state);\n  end if;\n  if v_cancelable is not null and now() < v_cancelable then\n    return jsonb_build_object(''ok'',false,''code'',''CANCEL_WINDOW_OPEN'',''cancelable_until'',v_cancelable);\n  end if;\n\n  select coalesce(w.balance_cents, 0) into v_balance\n    from public.cash_wallets w where w.user_id = p_user_id for update;\n  v_balance := coalesce(v_balance, 0);\n\n  if v_balance > 0 then\n    if v_consent_at is null then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_REQUIRED'',''current_balance_cents'',v_balance);\n    end if;\n    if v_balance > coalesce(v_consented, 0) then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_STALE'',\n        ''consented_balance_cents'', v_consented, ''current_balance_cents'', v_balance);\n    end if;\n  end if;\n\n  update public.account_deletion_jobs\n    set state=''locked'', locked_at=now(), updated_at=now()\n    where id = v_id and state=''pending'';\n  get diagnostics v_rows = row_count;\n  if v_rows = 0 then return jsonb_build_object(''ok'',false,''code'',''NOT_PENDING''); end if;\n\n  return jsonb_build_object(''ok'',true,''state'',''locked'',''job_id'',v_id,''balance_cents'',v_balance);\nend $function$", "-- public.account_deletion_cancel(p_user_id uuid)\nCREATE OR REPLACE FUNCTION public.account_deletion_cancel(p_user_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_id uuid; v_state text; v_cancelable timestamptz; v_rows int;\nbegin\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n\n  select j.state, j.cancelable_until into v_state, v_cancelable\n    from public.account_deletion_jobs j where j.id = v_id for update;\n  if not found then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n  if v_state <> ''pending'' then return jsonb_build_object(''ok'',false,''code'',''NOT_CANCELABLE'',''state'',v_state); end if;\n  if v_cancelable is not null and now() > v_cancelable then\n    return jsonb_build_object(''ok'',false,''code'',''CANCEL_WINDOW_PASSED'');\n  end if;\n\n  update public.account_deletion_jobs\n    set state=''canceled'', canceled_at=now(), updated_at=now()\n    where id = v_id and state = ''pending'';\n  get diagnostics v_rows = row_count;\n  if v_rows = 0 then return jsonb_build_object(''ok'',false,''code'',''NOT_CANCELABLE''); end if;\n  return jsonb_build_object(''ok'',true,''state'',''canceled'',''job_id'',v_id);\nend $function$", "-- public.account_deletion_cancel_self()\nCREATE OR REPLACE FUNCTION public.account_deletion_cancel_self()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_uid uuid := (select auth.uid());\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n  perform pg_advisory_xact_lock(hashtextextended(''account_deletion_self:'' || v_uid::text, 0));\n  return public.account_deletion_cancel(v_uid);\nend;\n$function$", "-- public.account_deletion_forfeit_and_anonymize(p_user_id uuid)\nCREATE OR REPLACE FUNCTION public.account_deletion_forfeit_and_anonymize(p_user_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_id uuid; v_state text; v_balance bigint; v_ledger_id uuid;\n  v_consent_at timestamptz; v_consented bigint; v_legacy_key text;\nbegin\n  perform set_config(''ssambership.deletion_worker'', ''on'', true);\n\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is null then return jsonb_build_object(''ok'',false,''code'',''JOB_NOT_FOUND''); end if;\n  select j.state, j.forfeit_consent_at, j.consented_balance_cents\n    into v_state, v_consent_at, v_consented\n    from public.account_deletion_jobs j where j.id = v_id for update;\n  if v_state is null then return jsonb_build_object(''ok'',false,''code'',''JOB_NOT_FOUND''); end if;\n  if v_state <> ''storage_purged'' then\n    return jsonb_build_object(''ok'',false,''code'',''WRONG_STATE'',''state'',v_state);\n  end if;\n\n  select w.balance_cents into v_balance from public.cash_wallets w\n    where w.user_id = p_user_id for update;\n\n  if v_balance is not null and v_balance > 0 then\n    if v_consent_at is null then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_REQUIRED'',''current_balance_cents'',v_balance);\n    end if;\n    if v_balance > coalesce(v_consented, 0) then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_STALE'',\n        ''consented_balance_cents'', v_consented, ''current_balance_cents'', v_balance);\n    end if;\n\n    v_legacy_key := ''forfeit_on_deletion:'' || p_user_id::text;\n    if exists (select 1 from public.cash_ledger l where l.idempotency_key = v_legacy_key) then\n      perform public.account_deletion_record_error(\n        p_user_id, ''LEGACY_FORFEIT_LEDGER_PRESENT: 운영자 검토 필요 — 레거시 몰수 원장 존재, 재몰수 차단'');\n      return jsonb_build_object(''ok'',false,''code'',''LEGACY_FORFEIT_LEDGER_PRESENT'',\n        ''current_balance_cents'', v_balance,\n        ''legacy_idempotency_key'', v_legacy_key);\n    end if;\n\n    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n    values (p_user_id, -v_balance, ''account_deletion_forfeit'', ''account_deletion'', p_user_id,\n            ''acct_del_forfeit:''||p_user_id::text)\n    on conflict (idempotency_key) do nothing\n    returning id into v_ledger_id;\n    if v_ledger_id is not null then\n      update public.cash_wallets set balance_cents = 0 where user_id = p_user_id;\n    end if;\n  end if;\n\n  perform public.anonymize_user_for_deletion(p_user_id, ''account_deletion'');\n  return jsonb_build_object(''ok'',true,''forfeited_cents'',coalesce(v_balance,0),''ledger_id'',v_ledger_id,''job_id'',v_id);\nend $function$", "-- public.account_deletion_record_error(p_user_id uuid, p_error text, p_backoff_seconds integer, p_max_attempts integer)\nCREATE OR REPLACE FUNCTION public.account_deletion_record_error(p_user_id uuid, p_error text, p_backoff_seconds integer DEFAULT 60, p_max_attempts integer DEFAULT 8)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_attempts int; v_id uuid;\nbegin\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n\n  update public.account_deletion_jobs\n    set attempts = attempts + 1, last_error = left(coalesce(p_error,''''),1000),\n        next_attempt_at = now() + make_interval(secs => greatest(1, coalesce(p_backoff_seconds,60))),\n        updated_at = now()\n    where id = v_id\n    returning attempts into v_attempts;\n  if v_attempts is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n\n  if v_attempts >= p_max_attempts then\n    update public.account_deletion_jobs\n      set state=''failed'', failed_at=now(), updated_at=now()\n      where id = v_id;\n    return jsonb_build_object(''ok'',true,''state'',''failed'',''attempts'',v_attempts,''job_id'',v_id);\n  end if;\n  return jsonb_build_object(''ok'',true,''attempts'',v_attempts,''job_id'',v_id);\nend $function$", "-- public.account_deletion_request(p_user_id uuid, p_cancelable_minutes integer, p_dry_run boolean)\nCREATE OR REPLACE FUNCTION public.account_deletion_request(p_user_id uuid, p_cancelable_minutes integer DEFAULT 30, p_dry_run boolean DEFAULT true)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin\n  return public.account_deletion_request_consented(\n    p_user_id, p_cancelable_minutes, p_dry_run, false, null);\nend $function$", "-- public.account_deletion_revoke_sessions(p_user_id uuid)\nCREATE OR REPLACE FUNCTION public.account_deletion_revoke_sessions(p_user_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_sessions int := 0; v_tokens int := 0;\nbegin\n  if p_user_id is null then\n    return jsonb_build_object(''ok'', false, ''code'', ''USER_REQUIRED'');\n  end if;\n\n  delete from auth.refresh_tokens rt\n   where rt.session_id in (select s.id from auth.sessions s where s.user_id = p_user_id)\n      or rt.user_id = p_user_id::text;\n  get diagnostics v_tokens = row_count;\n\n  delete from auth.sessions s where s.user_id = p_user_id;\n  get diagnostics v_sessions = row_count;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''sessions_deleted'', v_sessions,\n    ''refresh_tokens_deleted'', v_tokens\n  );\nend $function$", "-- public.account_deletion_status_self()\nCREATE OR REPLACE FUNCTION public.account_deletion_status_self()\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_id uuid;\n  v_job record;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED'' using errcode = ''28000''; end if;\n\n  v_id := coalesce(public.account_deletion_active_job_id(v_uid), public.account_deletion_latest_job_id(v_uid));\n  if v_id is null then\n    return jsonb_build_object(\n      ''ok'', true, ''exists'', false, ''state'', null,\n      ''cancelable_until'', null, ''write_blocked'', false, ''can_cancel'', false);\n  end if;\n\n  select j.state, j.cancelable_until into v_job\n    from public.account_deletion_jobs j where j.id = v_id;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''exists'', true,\n    ''state'', v_job.state,\n    ''cancelable_until'', v_job.cancelable_until,\n    ''write_blocked'', v_job.state in\n      (''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted''),\n    ''can_cancel'', v_job.state = ''pending''\n      and (v_job.cancelable_until is null or now() <= v_job.cancelable_until)\n  );\nend $function$", "-- public.account_deletion_write_guard()\nCREATE OR REPLACE FUNCTION public.account_deletion_write_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_col text := TG_ARGV[0]; v_uid uuid;\nbegin\n  if current_setting(''ssambership.deletion_worker'', true) = ''on'' then\n    return NEW;\n  end if;\n  v_uid := (to_jsonb(NEW) ->> v_col)::uuid;\n  if v_uid is not null and public.account_deletion_write_blocked(v_uid) then\n    raise exception ''ACCOUNT_DELETION_IN_PROGRESS'';\n  end if;\n  return NEW;\nend $function$", "-- public.approve_mentor_school_verification_admin(p_verification_id uuid, p_university_name text, p_university_id text, p_department_name text, p_major_category text, p_school_tier text)\nCREATE OR REPLACE FUNCTION public.approve_mentor_school_verification_admin(p_verification_id uuid, p_university_name text, p_university_id text, p_department_name text, p_major_category text, p_school_tier text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_admin uuid := (select auth.uid());\n  v_row public.mentor_school_verifications;\n  v_path text;\n  v_owner_segment text;\n  v_superseded integer := 0;\nbegin\n  if not coalesce(public.is_admin(), false) then\n    raise exception ''NOT_ADMIN'' using errcode = ''42501'';\n  end if;\n\n  if p_verification_id is null then\n    raise exception ''INVALID_INPUT: verification_id is required'' using errcode = ''22023'';\n  end if;\n  if btrim(coalesce(p_university_name, '''')) = ''''\n     or btrim(coalesce(p_university_id, '''')) = ''''\n     or btrim(coalesce(p_department_name, '''')) = ''''\n     or btrim(coalesce(p_major_category, '''')) = ''''\n     or btrim(coalesce(p_school_tier, '''')) = '''' then\n    raise exception ''INVALID_INPUT: university/department/major/tier are required'' using errcode = ''22023'';\n  end if;\n\n  select * into v_row from public.mentor_school_verifications where id = p_verification_id;\n  if not found then\n    raise exception ''VERIFICATION_NOT_FOUND'' using errcode = ''P0002'';\n  end if;\n  perform pg_advisory_xact_lock(hashtextextended(''msv_approve:'' || v_row.mentor_id::text, 0));\n\n  select * into v_row from public.mentor_school_verifications\n   where id = p_verification_id for update;\n  if v_row.status not in (''pending'', ''resubmit_required'') then\n    raise exception ''NOT_REVIEWABLE: %'', v_row.status using errcode = ''22023'';\n  end if;\n\n  if btrim(coalesce(v_row.document_storage_ref, '''')) = '''' then\n    raise exception ''DOCUMENT_REF_MISSING'' using errcode = ''22023'';\n  end if;\n  v_path := public.mentor_school_verification_storage_path(v_row.document_storage_ref);\n  if v_path is null then\n    raise exception ''DOCUMENT_REF_UNPARSEABLE'' using errcode = ''22023'';\n  end if;\n\n  v_owner_segment := split_part(v_path, ''/'', 1);\n  if v_owner_segment is distinct from v_row.mentor_id::text then\n    raise exception ''DOCUMENT_REF_OWNER_MISMATCH'' using errcode = ''42501'';\n  end if;\n\n  if not exists (\n    select 1 from storage.objects o\n     where o.bucket_id = ''student-id-images''\n       and o.name = v_path\n  ) then\n    raise exception ''DOCUMENT_OBJECT_NOT_FOUND'' using errcode = ''22023'';\n  end if;\n\n  update public.mentor_school_verifications\n     set status = ''superseded'',\n         updated_at = now()\n   where mentor_id = v_row.mentor_id\n     and status = ''approved''\n     and id <> v_row.id;\n  get diagnostics v_superseded = row_count;\n\n  update public.mentor_school_verifications\n     set status = ''approved'',\n         verified_university_name = btrim(p_university_name),\n         verified_university_id = btrim(p_university_id),\n         verified_department_name = btrim(p_department_name),\n         verified_major_category = btrim(p_major_category),\n         school_tier = btrim(p_school_tier),\n         reviewed_by = v_admin,\n         reviewed_at = now(),\n         reject_reason = null\n   where id = v_row.id;\n\n  return jsonb_build_object(\n    ''verification_id'', v_row.id,\n    ''mentor_id'', v_row.mentor_id,\n    ''status'', ''approved'',\n    ''superseded_count'', v_superseded,\n    ''reviewed_by'', v_admin\n  );\nend;\n$function$", "-- public.approve_refund_request_admin(p_refund_id uuid, p_admin_id uuid, p_admin_note text)\nCREATE OR REPLACE FUNCTION public.approve_refund_request_admin(p_refund_id uuid, p_admin_id uuid, p_admin_note text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  r public.refunds%rowtype; v_amount bigint; v_settlement_status text;\n  v_idem text := ''refund_credit:'' || p_refund_id::text; v_ledger_id uuid; v_existing_delta bigint; v_wu int; v_admin_ok boolean;\nbegin\n  if p_refund_id is null then return jsonb_build_object(''ok'', false, ''message'', ''환불 ID가 필요합니다.''); end if;\n  if p_admin_id is null then return jsonb_build_object(''ok'', false, ''message'', ''관리자 ID가 필요합니다.''); end if;\n  select exists(select 1 from public.users u where u.id = p_admin_id and u.role = ''admin'') into v_admin_ok;\n  if not coalesce(v_admin_ok, false) then raise exception ''ADMIN_REQUIRED''; end if;\n  select * into r from public.refunds where id = p_refund_id for update;\n  if not found then return jsonb_build_object(''ok'', false, ''message'', ''환불 요청을 찾을 수 없습니다.''); end if;\n  if r.status is distinct from ''pending'' then\n    return jsonb_build_object(''ok'', true, ''noop'', true, ''refund_id'', p_refund_id, ''message'', ''이미 처리되었거나 대기 상태가 아닙니다.'', ''status'', r.status);\n  end if;\n  if r.custom_request_order_id is not null then\n    select s.status into v_settlement_status from public.custom_order_settlement_items s where s.custom_request_order_id = r.custom_request_order_id limit 1;\n    if found and v_settlement_status = ''paid'' then\n      return jsonb_build_object(''ok'', false, ''message'', ''이미 정산 지급이 완료된 건은 자동 환불할 수 없습니다. 수동 조정이 필요합니다.'');\n    end if;\n  end if;\n  if r.payment_id is not null and (r.subscription_id is not null or coalesce(r.request_type, '''') = ''subscription_prorated'') then\n    select s.status into v_settlement_status from public.subscription_settlement_items s where s.payment_id = r.payment_id and s.status = ''paid'' limit 1;\n    if found then return jsonb_build_object(''ok'', false, ''message'', ''이미 멘토 정산 지급이 완료된 구독 건은 자동 환불할 수 없습니다. 수동 조정이 필요합니다.''); end if;\n  end if;\n  if r.custom_request_order_id is not null then\n    perform public.record_custom_order_escrow_refund(r.custom_request_order_id);\n    update public.refunds set status=''succeeded'', processed_at=now(), processed_by=p_admin_id, admin_note=p_admin_note, updated_at=now() where id=r.id;\n    return jsonb_build_object(''ok'', true, ''noop'', false, ''refund_id'', r.id, ''kind'', ''custom_order_escrow'', ''message'', ''맞춤의뢰 환불이 승인되었습니다.'');\n  end if;\n  if r.amount_cents is null or r.amount_cents <= 0 then raise exception ''환불 금액이 설정되지 않아 자동 승인할 수 없습니다.''; end if;\n  v_amount := r.amount_cents;\n  if v_amount > 1000000000 then return jsonb_build_object(''ok'', false, ''message'', ''환불 금액이 허용 한도를 초과합니다.''); end if;\n  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n  values (r.user_id, v_amount, ''refund_approved'', ''refunds'', r.id, v_idem) on conflict (idempotency_key) do nothing returning id into v_ledger_id;\n  if v_ledger_id is null then\n    select cl.delta_cents into v_existing_delta from public.cash_ledger cl where cl.idempotency_key = v_idem limit 1;\n    if not found then raise exception ''REFUND_LEDGER_IDEMPOTENT_MISS'' using errcode = ''P0001''; end if;\n    if v_existing_delta is distinct from v_amount then raise exception ''REFUND_LEDGER_AMOUNT_MISMATCH'' using errcode = ''P0001''; end if;\n  end if;\n  if v_ledger_id is not null then\n    insert into public.cash_wallets (user_id, balance_cents) values (r.user_id, 0) on conflict (user_id) do nothing;\n    update public.cash_wallets w set balance_cents = w.balance_cents + v_amount where w.user_id = r.user_id;\n    get diagnostics v_wu = row_count;\n    if coalesce(v_wu, 0) = 0 then raise exception ''CASH_WALLET_UPDATE_FAILED'' using errcode = ''P0001''; end if;\n  end if;\n  update public.refunds set status=''succeeded'', processed_at=now(), processed_by=p_admin_id, admin_note=p_admin_note, updated_at=now() where id=r.id;\n  if r.payment_id is not null then update public.payments p set status=''refunded'', updated_at=now() where p.id = r.payment_id; end if;\n  if r.payment_id is not null then update public.subscriptions s set status=''canceled'', updated_at=now() where s.payment_id = r.payment_id and s.status is distinct from ''canceled''; end if;\n  return jsonb_build_object(''ok'', true, ''noop'', false, ''refund_id'', r.id, ''ledger_inserted'', (v_ledger_id is not null), ''amount_cents'', v_amount, ''message'', ''환불이 승인되었습니다.'');\nend; $function$", "-- public.cc_sync_board_delete_to_canonical()\nCREATE OR REPLACE FUNCTION public.cc_sync_board_delete_to_canonical()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_rows int;\nbegin\n  if public.comment_sync_in_progress() then return old; end if;\n  perform set_config(''app.comment_sync'', ''1'', true);\n\n  if old.canonical_comment_id is not null then\n    update public.comments set is_deleted = true where id = old.canonical_comment_id;\n  else\n    update public.comments set is_deleted = true where legacy_comment_id = old.id;\n  end if;\n  get diagnostics v_rows = row_count;\n  if v_rows = 0 then\n    raise exception ''COMMENT_BRIDGE_TARGET_MISSING'';\n  end if;\n\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return old;\nend;\n$function$", "-- public.cc_sync_board_to_canonical()\nCREATE OR REPLACE FUNCTION public.cc_sync_board_to_canonical()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_canonical uuid;\n  v_target public.comments;\nbegin\n  if public.comment_sync_in_progress() then return new; end if;\n  perform set_config(''app.comment_sync'', ''1'', true);\n\n  if new.canonical_comment_id is not null then\n    select * into v_target from public.comments\n    where id = new.canonical_comment_id for update;\n    if not found then\n      raise exception ''COMMENT_BRIDGE_TARGET_MISSING'';\n    end if;\n    if v_target.post_id is distinct from new.post_id then\n      raise exception ''COMMENT_BRIDGE_POST_MISMATCH'';\n    end if;\n    if v_target.author_id is distinct from new.author_id then\n      raise exception ''COMMENT_BRIDGE_AUTHOR_MISMATCH'';\n    end if;\n    update public.comments\n      set content = new.body, is_deleted = (new.status <> ''visible'')\n    where id = new.canonical_comment_id;\n  else\n    insert into public.comments (post_id, author_id, content, is_deleted, created_at, legacy_comment_id)\n    values (new.post_id, new.author_id, new.body, new.status <> ''visible'', new.created_at, new.id)\n    on conflict (legacy_comment_id) where legacy_comment_id is not null\n    do update set content = excluded.content, is_deleted = excluded.is_deleted\n    returning id into v_canonical;\n    if v_canonical is null then\n      select id into v_canonical from public.comments where legacy_comment_id = new.id;\n    end if;\n    update public.community_comments set canonical_comment_id = v_canonical where id = new.id;\n  end if;\n\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return new;\nend;\n$function$", "-- public.cc_write_guard()\nCREATE OR REPLACE FUNCTION public.cc_write_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''public''\nAS $function$\nbegin\n  if public.comment_sync_in_progress() then return new; end if;\n  if current_user not in (''authenticated'', ''anon'') then return new; end if;\n\n  if tg_op = ''INSERT'' then\n    if new.canonical_comment_id is not null then\n      raise exception ''CC_CANONICAL_ID_FORBIDDEN'';\n    end if;\n    return new;\n  end if;\n\n  if new.canonical_comment_id is distinct from old.canonical_comment_id\n     or new.id is distinct from old.id\n     or new.post_id is distinct from old.post_id\n     or new.post_type is distinct from old.post_type\n     or new.author_id is distinct from old.author_id\n     or new.created_at is distinct from old.created_at then\n    raise exception ''CC_PROTECTED_FIELDS_IMMUTABLE'';\n  end if;\n  return new;\nend;\n$function$", "-- public.check_review_eligibility(p_mentor_id uuid, p_student_id uuid)\nCREATE OR REPLACE FUNCTION public.check_review_eligibility(p_mentor_id uuid, p_student_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin\n  if p_mentor_id is null or p_student_id is null then\n    return false;\n  end if;\n\n  -- (B) 구독 관계\n  if exists (\n    select 1\n    from public.subscriptions s\n    where s.student_id = p_student_id\n      and s.mentor_id = p_mentor_id\n      and s.status in (''active'', ''expired'', ''cancel_scheduled'')\n  ) then\n    return true;\n  end if;\n\n  -- (C) 완료된 개별질문\n  if exists (\n    select 1\n    from public.individual_questions q\n    where q.student_id = p_student_id\n      and coalesce(q.claimed_mentor_id, q.designated_mentor_id) = p_mentor_id\n      and q.status in (''answered'', ''released'')\n  ) then\n    return true;\n  end if;\n\n  return false;\nend;\n$function$", "-- public.comments_mirror_to_legacy()\nCREATE OR REPLACE FUNCTION public.comments_mirror_to_legacy()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_body text;\n  v_rows int;\nbegin\n  if public.comment_sync_in_progress() then return new; end if;\n  perform set_config(''app.comment_sync'', ''1'', true);\n\n  v_body := left(coalesce(new.content, ''''), 1000);\n\n  if new.legacy_comment_id is not null then\n    if char_length(btrim(v_body)) >= 1 then\n      update public.community_comments\n        set body = v_body,\n            status = case when coalesce(new.is_deleted, false) then ''hidden'' else ''visible'' end,\n            canonical_comment_id = new.id\n      where id = new.legacy_comment_id\n        and (canonical_comment_id = new.id or canonical_comment_id is null);\n    else\n      update public.community_comments\n        set status = case when coalesce(new.is_deleted, false) then ''hidden'' else ''visible'' end,\n            canonical_comment_id = new.id\n      where id = new.legacy_comment_id\n        and (canonical_comment_id = new.id or canonical_comment_id is null);\n    end if;\n    get diagnostics v_rows = row_count;\n    if v_rows = 0 then\n      raise exception ''COMMENT_BRIDGE_LEGACY_MISSING'';\n    end if;\n  else\n    if char_length(btrim(v_body)) >= 1 then\n      insert into public.community_comments (post_id, post_type, author_id, body, status, created_at, canonical_comment_id)\n      values (new.post_id, ''board'', new.author_id, v_body,\n              case when coalesce(new.is_deleted, false) then ''hidden'' else ''visible'' end,\n              coalesce(new.created_at, now()), new.id)\n      on conflict (canonical_comment_id) where canonical_comment_id is not null\n      do update set body = excluded.body, status = excluded.status;\n    end if;\n  end if;\n\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return new;\nend;\n$function$", "-- public.comments_write_guard()\nCREATE OR REPLACE FUNCTION public.comments_write_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''public''\nAS $function$\ndeclare v_parent public.comments;\nbegin\n  if public.comment_sync_in_progress() then\n    return coalesce(new, old);\n  end if;\n  if current_user not in (''authenticated'', ''anon'') then\n    return coalesce(new, old);\n  end if;\n\n  if tg_op = ''DELETE'' then\n    if coalesce((select public.is_admin()), false) then return old; end if;\n    raise exception ''COMMENT_HARD_DELETE_FORBIDDEN'';\n  end if;\n\n  if tg_op = ''INSERT'' then\n    if new.legacy_comment_id is not null then\n      raise exception ''COMMENT_LEGACY_ID_FORBIDDEN'';\n    end if;\n    if new.parent_id is not null then\n      select * into v_parent from public.comments where id = new.parent_id;\n      if not found then raise exception ''COMMENT_PARENT_NOT_FOUND''; end if;\n      if v_parent.post_id is distinct from new.post_id then\n        raise exception ''COMMENT_PARENT_POST_MISMATCH'';\n      end if;\n      if v_parent.parent_id is not null then\n        raise exception ''COMMENT_DEPTH_EXCEEDED'';\n      end if;\n    end if;\n    return new;\n  end if;\n\n  if new.id is distinct from old.id\n     or new.post_id is distinct from old.post_id\n     or new.author_id is distinct from old.author_id\n     or new.parent_id is distinct from old.parent_id\n     or new.created_at is distinct from old.created_at\n     or new.legacy_comment_id is distinct from old.legacy_comment_id\n     or new.like_count is distinct from old.like_count then\n    raise exception ''COMMENT_PROTECTED_FIELDS_IMMUTABLE'';\n  end if;\n  return new;\nend;\n$function$", "-- public.confirm_subscription_checkout(p_payment_id uuid, p_plan_id uuid, p_idempotency_key text)\nCREATE OR REPLACE FUNCTION public.confirm_subscription_checkout(p_payment_id uuid, p_plan_id uuid, p_idempotency_key text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_student uuid; v_mentor uuid; v_pay_status text; v_created_at timestamptz; v_kind text;\n  v_plan_mentor uuid; v_plan_tier text; v_plan_active boolean; v_amount_cents int;\n  v_is_open boolean; v_sub_id uuid; v_reactivated boolean := false;\n  v_status text; v_suspended_until timestamptz;\n  v_l_user uuid; v_l_delta bigint; v_l_reason text; v_l_reftype text; v_l_refid uuid;\n  v_succeeded_aliases text[] := array[''succeeded'',''paid'',''success'',''complete'',''captured''];\n  v_anom uuid; v_err text; v_errcode text;\nbegin\n  select user_id, mentor_id, status, created_at, kind into v_student, v_mentor, v_pay_status, v_created_at, v_kind\n    from public.payments where id = p_payment_id for update;\n  if not found then raise exception ''PAYMENT_NOT_FOUND''; end if;\n  if v_student is null then raise exception ''PAYMENT_NO_USER''; end if;\n  if v_mentor is null then raise exception ''PAYMENT_NO_MENTOR''; end if;\n  if lower(coalesce(v_kind,'''')) in (''cash_topup'',''topup'',''cash'',''individual_question'',''iq'',''custom_order'',''custom_request'',''deliverable'') then raise exception ''PAYMENT_KIND_INVALID''; end if;\n  perform pg_advisory_xact_lock(hashtext(v_student::text), hashtext(v_mentor::text));\n  select mentor_id, plan_tier, is_active, amount_cents into v_plan_mentor, v_plan_tier, v_plan_active, v_amount_cents\n    from public.mentor_plans where id = p_plan_id for update;\n  if not found then raise exception ''PLAN_NOT_FOUND''; end if;\n  if v_plan_mentor <> v_mentor then raise exception ''PLAN_MENTOR_MISMATCH''; end if;\n  if v_amount_cents is null or v_amount_cents <= 0 then raise exception ''PLAN_AMOUNT_INVALID''; end if;\n  if v_pay_status = any(v_succeeded_aliases) then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor;\n    if v_sub_id is null then\n      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n        values (p_payment_id, null, ''SUCCEEDED_NO_SUBSCRIPTION'', ''succeeded payment without subscription'') returning id into v_anom;\n      return jsonb_build_object(''ok'',false,''code'',''SUCCEEDED_NO_SUBSCRIPTION'',''anomaly_id'',v_anom);\n    end if;\n    select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid\n      from public.cash_ledger where idempotency_key = ''sub_debit_'' || p_payment_id::text;\n    if v_l_user is null then\n      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n        values (p_payment_id, v_sub_id, ''SUCCEEDED_NO_LEDGER'', ''succeeded payment without ledger debit'') returning id into v_anom;\n      return jsonb_build_object(''ok'',false,''code'',''SUCCEEDED_NO_LEDGER'',''anomaly_id'',v_anom);\n    end if;\n    if v_l_user <> v_student or v_l_refid is distinct from v_sub_id or coalesce(v_l_reftype,'''') <> ''subscriptions''\n       or coalesce(v_l_reason,'''') <> ''subscription_payment'' or v_l_delta <> -v_amount_cents then\n      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)\n        values (p_payment_id, v_sub_id, ''LEDGER_FIELD_MISMATCH'', ''idempotent re-check field mismatch'',\n          jsonb_build_object(''user_id'',v_student,''ref_id'',v_sub_id,''ref_type'',''subscriptions'',''reason'',''subscription_payment'',''delta_cents'',-v_amount_cents),\n          jsonb_build_object(''user_id'',v_l_user,''ref_id'',v_l_refid,''ref_type'',v_l_reftype,''reason'',v_l_reason,''delta_cents'',v_l_delta))\n        returning id into v_anom;\n      return jsonb_build_object(''ok'',false,''code'',''LEDGER_FIELD_MISMATCH'',''anomaly_id'',v_anom);\n    end if;\n    return jsonb_build_object(''ok'',true,''idempotent'',true,''subscription_id'',v_sub_id,''payment_status'',''succeeded'');\n  end if;\n  if v_pay_status = ''processing'' then raise exception ''PAYMENT_PROCESSING''; end if;\n  if v_pay_status in (''failed'',''canceled'',''refunded'') then raise exception ''PAYMENT_NOT_PENDING''; end if;\n  if v_pay_status <> ''pending'' then raise exception ''PAYMENT_STATE_UNEXPECTED''; end if;\n  if v_created_at is null or now() > v_created_at + interval ''30 minutes'' then raise exception ''PAYMENT_STALE''; end if;\n  select status, suspended_until into v_status, v_suspended_until from public.users where id = v_student for update;\n  if lower(coalesce(v_status,''active'')) = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if lower(coalesce(v_status,''active'')) = ''suspended'' and (v_suspended_until is null or v_suspended_until > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  perform 1 from public.mentor_profiles where user_id = v_mentor for update;\n  select is_open_for_subscriptions into v_is_open from public.mentor_profiles where user_id = v_mentor;\n  if not coalesce(v_is_open, true) then raise exception ''MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS''; end if;\n  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  if not coalesce(v_plan_active, true) then raise exception ''PLAN_INACTIVE''; end if;\n  if not exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'') then\n    if public.mentor_cap_used(v_mentor) + public.subscription_cap_weight(v_plan_tier) > public.mentor_cap_limit(v_mentor) then raise exception ''MENTOR_CAP_EXCEEDED''; end if;\n  end if;\n  v_reactivated := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor);\n  begin\n    insert into public.subscriptions (student_id, mentor_id, plan_id, plan_tier, status, payment_id,\n      started_at, current_period_start, current_period_end, next_billing_at, billing_cycle, cancel_at_period_end, last_payment_id)\n    values (v_student, v_mentor, p_plan_id, v_plan_tier, ''active'', p_payment_id,\n      now(), now(), now()+interval ''1 month'', now()+interval ''1 month'', ''monthly'', false, p_payment_id)\n    on conflict (student_id, mentor_id) do update set\n      plan_id=excluded.plan_id, plan_tier=excluded.plan_tier, status=''active'', payment_id=excluded.payment_id,\n      last_payment_id=excluded.last_payment_id, started_at=coalesce(public.subscriptions.started_at, now()),\n      current_period_start=now(), current_period_end=now()+interval ''1 month'', next_billing_at=now()+interval ''1 month'',\n      cancel_at_period_end=false, cancel_requested_at=null, canceled_at=null, expired_at=null, grace_until=null,\n      last_renewed_at=now(), updated_at=now()\n    returning id into v_sub_id;\n    select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid\n      from public.cash_ledger where idempotency_key = ''sub_debit_'' || p_payment_id::text;\n    if v_l_user is not null and (v_l_user <> v_student or v_l_refid is distinct from v_sub_id\n       or coalesce(v_l_reftype,'''') <> ''subscriptions'' or coalesce(v_l_reason,'''') <> ''subscription_payment'' or v_l_delta <> -v_amount_cents) then\n      raise exception ''LEDGER_FIELD_MISMATCH'';\n    end if;\n    perform public.record_subscription_cash_debit(v_student, v_sub_id, p_payment_id, v_amount_cents::bigint);\n    update public.payments set status=''succeeded'', plan_id=p_plan_id,\n      metadata=coalesce(metadata,''{}''::jsonb) || jsonb_build_object(''planId'',p_plan_id::text,''subscription_id'',v_sub_id::text),\n      updated_at=now() where id=p_payment_id;\n  exception when others then\n    get stacked diagnostics v_errcode = returned_sqlstate;\n    v_err := sqlerrm;\n  end;\n  if v_err is not null then\n    if v_err like ''%CASH_INSUFFICIENT%'' then return jsonb_build_object(''ok'',false,''code'',''CASH_INSUFFICIENT''); end if;\n    insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      values (p_payment_id, v_sub_id, case when v_err like ''%LEDGER_FIELD_MISMATCH%'' then ''LEDGER_FIELD_MISMATCH'' else ''FINANCIAL_WRITE_ERROR'' end, left(v_err,500)) returning id into v_anom;\n    return jsonb_build_object(''ok'',false,''code'', case when v_err like ''%LEDGER_FIELD_MISMATCH%'' then ''LEDGER_FIELD_MISMATCH'' else ''FINANCIAL_WRITE_ERROR'' end, ''sqlstate'',v_errcode,''anomaly_id'',v_anom);\n  end if;\n  return jsonb_build_object(''ok'',true,''subscription_id'',v_sub_id,''payment_status'',''succeeded'',''amount_cents'',v_amount_cents,''reactivated'',v_reactivated);\nend; $function$", "-- public.get_mentor_student_nicknames(p_student_ids uuid[])\nCREATE OR REPLACE FUNCTION public.get_mentor_student_nicknames(p_student_ids uuid[])\n RETURNS TABLE(id uuid, nickname text, full_name text)\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select u.id, u.nickname, u.full_name\n  from public.users u\n  where p_student_ids is not null and array_length(p_student_ids, 1) is not null\n    and u.id = any (p_student_ids) and (select auth.uid()) is not null\n    and (\n      exists (select 1 from public.subscriptions s where s.mentor_id=(select auth.uid()) and s.student_id=u.id and lower(coalesce(s.status,''''))=''active'')\n      or exists (select 1 from public.mentor_student_rooms r where r.mentor_id=(select auth.uid()) and r.student_id=u.id)\n    );\n$function$", "-- public.get_mobile_app_version_policy(p_platform text)\nCREATE OR REPLACE FUNCTION public.get_mobile_app_version_policy(p_platform text)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_row public.mobile_app_version_policies;\nbegin\n  if p_platform is null or lower(btrim(p_platform)) not in (''android'',''ios'') then\n    raise exception ''INVALID_PLATFORM'' using errcode = ''22023'';\n  end if;\n  select * into v_row from public.mobile_app_version_policies\n  where platform = lower(btrim(p_platform));\n  if not found then\n    return jsonb_build_object(\n      ''platform'', lower(btrim(p_platform)),\n      ''min_supported_build'', 1,\n      ''latest_build'', 1,\n      ''minimum_version_name'', null,\n      ''store_url'', null,\n      ''message'', null);\n  end if;\n  return jsonb_build_object(\n    ''platform'', v_row.platform,\n    ''min_supported_build'', v_row.min_supported_build,\n    ''latest_build'', v_row.latest_build,\n    ''minimum_version_name'', v_row.minimum_version_name,\n    ''store_url'', v_row.store_url,\n    ''message'', v_row.message);\nend;\n$function$", "-- public.mark_all_notifications_read()\nCREATE OR REPLACE FUNCTION public.mark_all_notifications_read()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_uid uuid := (select auth.uid()); v_count int;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED'' using errcode = ''28000''; end if;\n  update public.notifications\n  set is_read = true, read_at = coalesce(read_at, now()), updated_at = now()\n  where is_read is distinct from true\n    and (user_id = v_uid or recipient_id = v_uid or student_id = v_uid or mentor_id = v_uid or target_user_id = v_uid or owner_id = v_uid or recipient_user_id = v_uid);\n  get diagnostics v_count = row_count;\n  return coalesce(v_count, 0);\nend; $function$", "-- public.process_subscription_renewal(p_subscription_id uuid, p_period_end timestamp with time zone, p_amount_cents bigint, p_idempotency_key text, p_processed_at timestamp with time zone)\nCREATE OR REPLACE FUNCTION public.process_subscription_renewal(p_subscription_id uuid, p_period_end timestamp with time zone, p_amount_cents bigint, p_idempotency_key text, p_processed_at timestamp with time zone DEFAULT now())\n RETURNS TABLE(ok boolean, code text, message text, billing_event_id uuid, ledger_id uuid, next_period_start timestamp with time zone, next_period_end timestamp with time zone, wallet_balance_cents bigint, attempt_count integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\r\ndeclare\r\n  v_sub public.subscriptions%rowtype;\r\n  v_event public.subscription_billing_events%rowtype;\r\n  v_event_id uuid;\r\n  v_ledger_id uuid;\r\n  v_wallet_balance bigint;\r\n  v_period_start timestamptz;\r\n  v_period_end timestamptz;\r\n  v_attempt_count int;\r\nbegin\r\n  if p_subscription_id is null then\r\n    return query select false, ''invalid_subscription''::text, ''subscription_id is required''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\r\n    return;\r\n  end if;\r\n\r\n  if p_amount_cents is null or p_amount_cents <= 0 then\r\n    return query select false, ''invalid_amount''::text, ''p_amount_cents must be positive''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\r\n    return;\r\n  end if;\r\n\r\n  if p_idempotency_key is null or length(trim(p_idempotency_key)) = 0 then\r\n    return query select false, ''invalid_idempotency_key''::text, ''idempotency_key is required''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\r\n    return;\r\n  end if;\r\n\r\n  select *\r\n    into v_sub\r\n  from public.subscriptions\r\n  where id = p_subscription_id\r\n  for update;\r\n\r\n  if not found then\r\n    return query select false, ''not_found''::text, ''subscription not found''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\r\n    return;\r\n  end if;\r\n\r\n  if coalesce(v_sub.status, '''') not in (''active'', ''past_due'') then\r\n    return query select false, ''not_renewable_status''::text, ''subscription status is not renewable''::text, null::uuid, null::uuid, v_sub.current_period_start, v_sub.current_period_end, null::bigint, 0::int;\r\n    return;\r\n  end if;\r\n\r\n  select *\r\n    into v_event\r\n  from public.subscription_billing_events\r\n  where idempotency_key = p_idempotency_key\r\n  for update;\r\n\r\n  if found then\r\n    if v_event.status = ''succeeded'' then\r\n      return query select true, ''already_succeeded''::text, ''renewal already processed''::text, v_event.id, v_event.ledger_id, v_event.period_start, v_event.period_end, null::bigint, coalesce(v_event.attempt_count, 0);\r\n      return;\r\n    end if;\r\n\r\n    if v_event.status in (''pending'', ''processing'') then\r\n      return query select false, ''already_processing''::text, ''renewal is already processing''::text, v_event.id, v_event.ledger_id, v_event.period_start, v_event.period_end, null::bigint, coalesce(v_event.attempt_count, 0);\r\n      return;\r\n    end if;\r\n\r\n    update public.subscription_billing_events as e\r\n    set\r\n      event_type = ''renewal'',\r\n      status = ''processing'',\r\n      failure_code = null,\r\n      failure_message = null,\r\n      amount_cents = p_amount_cents::int,\r\n      billing_at = p_processed_at,\r\n      attempt_count = coalesce(attempt_count, 0) + 1,\r\n      processed_at = null\r\n    where e.id = v_event.id\r\n    returning e.* into v_event;\r\n\r\n    v_event_id := v_event.id;\r\n    v_attempt_count := coalesce(v_event.attempt_count, 1);\r\n  else\r\n    v_period_start := coalesce(v_sub.current_period_end, p_period_end, p_processed_at);\r\n    v_period_end := v_period_start + interval ''1 month'';\r\n\r\n    insert into public.subscription_billing_events (\r\n      subscription_id,\r\n      student_id,\r\n      mentor_id,\r\n      event_type,\r\n      status,\r\n      period_start,\r\n      period_end,\r\n      billing_at,\r\n      amount_cents,\r\n      plan_tier,\r\n      plan_id,\r\n      idempotency_key,\r\n      attempt_count,\r\n      created_at\r\n    )\r\n    values (\r\n      v_sub.id,\r\n      v_sub.student_id,\r\n      v_sub.mentor_id,\r\n      ''renewal'',\r\n      ''processing'',\r\n      v_period_start,\r\n      v_period_end,\r\n      p_processed_at,\r\n      p_amount_cents::int,\r\n      v_sub.plan_tier,\r\n      v_sub.plan_id,\r\n      p_idempotency_key,\r\n      1,\r\n      p_processed_at\r\n    )\r\n    returning * into v_event;\r\n\r\n    v_event_id := v_event.id;\r\n    v_attempt_count := 1;\r\n  end if;\r\n\r\n  insert into public.cash_wallets (user_id, balance_cents)\r\n  values (v_sub.student_id, 0)\r\n  on conflict (user_id) do nothing;\r\n\r\n  update public.cash_wallets\r\n  set balance_cents = balance_cents - p_amount_cents\r\n  where user_id = v_sub.student_id\r\n    and balance_cents >= p_amount_cents\r\n  returning balance_cents into v_wallet_balance;\r\n\r\n  if not found then\r\n    update public.subscription_billing_events as e\r\n    set\r\n      event_type = ''renewal_failed'',\r\n      status = ''failed'',\r\n      failure_code = ''insufficient_cash'',\r\n      failure_message = ''CASH_INSUFFICIENT'',\r\n      processed_at = p_processed_at\r\n    where e.id = v_event_id\r\n    returning e.attempt_count into v_attempt_count;\r\n\r\n    update public.subscriptions\r\n    set\r\n      status = ''past_due'',\r\n      grace_until = coalesce(grace_until, p_processed_at + interval ''2 days''),\r\n      updated_at = p_processed_at,\r\n      last_billing_event_id = v_event_id\r\n    where id = v_sub.id;\r\n\r\n    return query select false, ''insufficient_cash''::text, ''CASH_INSUFFICIENT''::text, v_event_id, null::uuid, v_event.period_start, v_event.period_end, null::bigint, coalesce(v_attempt_count, 1);\r\n    return;\r\n  end if;\r\n\r\n  insert into public.cash_ledger (\r\n    user_id,\r\n    delta_cents,\r\n    reason,\r\n    ref_type,\r\n    ref_id,\r\n    idempotency_key,\r\n    created_at\r\n  )\r\n  values (\r\n    v_sub.student_id,\r\n    -p_amount_cents,\r\n    ''subscription_renewal'',\r\n    ''subscriptions'',\r\n    v_sub.id,\r\n    p_idempotency_key,\r\n    p_processed_at\r\n  )\r\n  on conflict (idempotency_key) do nothing\r\n  returning id into v_ledger_id;\r\n\r\n  if v_ledger_id is null then\r\n    select id\r\n      into v_ledger_id\r\n    from public.cash_ledger\r\n    where idempotency_key = p_idempotency_key;\r\n  end if;\r\n\r\n  v_period_start := coalesce(v_event.period_start, v_sub.current_period_end, p_period_end, p_processed_at);\r\n  v_period_end := coalesce(v_event.period_end, v_period_start + interval ''1 month'');\r\n\r\n  update public.subscription_billing_events as e\r\n  set\r\n    event_type = ''renewal'',\r\n    status = ''succeeded'',\r\n    ledger_id = v_ledger_id,\r\n    processed_at = p_processed_at,\r\n    failure_code = null,\r\n    failure_message = null,\r\n    period_start = v_period_start,\r\n    period_end = v_period_end,\r\n    amount_cents = p_amount_cents::int\r\n  where e.id = v_event_id\r\n  returning e.attempt_count into v_attempt_count;\r\n\r\n  update public.subscriptions\r\n  set\r\n    status = ''active'',\r\n    current_period_start = v_period_start,\r\n    current_period_end = v_period_end,\r\n    next_billing_at = v_period_end,\r\n    last_renewed_at = p_processed_at,\r\n    last_billing_event_id = v_event_id,\r\n    grace_until = null,\r\n    updated_at = p_processed_at\r\n  where id = v_sub.id;\r\n\r\n  return query select true, ''succeeded''::text, ''renewal processed''::text, v_event_id, v_ledger_id, v_period_start, v_period_end, v_wallet_balance, coalesce(v_attempt_count, 1);\r\nend;\r\n$function$", "-- public.qna_confirm_thread(p_thread_id uuid)\nCREATE OR REPLACE FUNCTION public.qna_confirm_thread(p_thread_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_status text;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  select t.mentor_student_room_id, t.status into v_room, v_status from public.question_threads t where t.id=p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n  select student_id into v_student from public.mentor_student_rooms where id=v_room;\n  if v_uid <> v_student then raise exception ''STUDENT_ONLY''; end if;\n  if v_status=''confirmed'' then return jsonb_build_object(''ok'',true,''thread_id'',p_thread_id); end if;\n  if v_status <> ''answered'' then raise exception ''NOT_ANSWERED''; end if;\n  update public.question_threads set status=''confirmed'', confirmed_at=coalesce(confirmed_at,now()), updated_at=now() where id=p_thread_id;\n  return jsonb_build_object(''ok'',true,''thread_id'',p_thread_id);\nend; $function$", "-- public.qna_create_free_question_thread(p_room_id uuid, p_title text, p_subject text, p_topic text, p_first_message_body text)\nCREATE OR REPLACE FUNCTION public.qna_create_free_question_thread(p_room_id uuid, p_title text, p_subject text DEFAULT NULL::text, p_topic text DEFAULT NULL::text, p_first_message_body text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin return public.qna_create_question_thread(p_room_id, p_title, p_subject, p_topic, p_first_message_body); end; $function$", "-- public.qna_create_question_thread(p_room_id uuid, p_title text, p_subject text, p_topic text, p_first_message_body text)\nCREATE OR REPLACE FUNCTION public.qna_create_question_thread(p_room_id uuid, p_title text, p_subject text DEFAULT NULL::text, p_topic text DEFAULT NULL::text, p_first_message_body text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid; v_status text; v_suspended_until timestamptz;\n  v_created_at timestamptz; v_total int; v_per int; v_subject text; v_thread_id uuid; v_message_id uuid;\n  v_has_active_sub boolean; v_usage json; v_path text; v_sub_id uuid;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_title is null or btrim(p_title)='''' then raise exception ''TITLE_REQUIRED''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=p_room_id;\n  if not found then raise exception ''ROOM_NOT_FOUND''; end if;\n  if v_uid <> v_student then\n    if v_uid = v_mentor then raise exception ''MENTOR_CANNOT_CREATE_THREAD''; else raise exception ''NOT_ROOM_PARTY''; end if;\n  end if;\n  perform 1 from public.users where id=v_student for update;\n  select status, suspended_until, created_at into v_status, v_suspended_until, v_created_at from public.users where id=v_student;\n  if lower(coalesce(v_status,''active''))=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if lower(coalesce(v_status,''active''))=''suspended'' and (v_suspended_until is null or v_suspended_until > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if exists (select 1 from public.user_blocks where (blocker_id=v_student and blocked_id=v_mentor) or (blocker_id=v_mentor and blocked_id=v_student)) then raise exception ''BLOCKED''; end if;\n  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  v_has_active_sub := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'');\n  if v_has_active_sub then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n    v_usage := public.get_weekly_question_usage(v_student, v_mentor);\n    if not coalesce((v_usage->>''can_ask'')::boolean, false) then raise exception ''WEEKLY_LIMIT_EXHAUSTED''; end if;\n    v_path := ''subscription'';\n  else\n    if v_created_at is not null and now() >= v_created_at + interval ''7 days'' then raise exception ''FREE_QUOTA_EXPIRED''; end if;\n    select count(*) into v_total from public.free_question_usage where student_id=v_student;\n    if v_total >= 7 then raise exception ''FREE_QUOTA_TOTAL_EXHAUSTED''; end if;\n    select count(*) into v_per from public.free_question_usage where student_id=v_student and mentor_id=v_mentor;\n    if v_per >= 3 then raise exception ''FREE_QUOTA_MENTOR_EXHAUSTED''; end if;\n    v_path := ''free'';\n  end if;\n  v_subject := nullif(btrim(coalesce(p_subject,'''')),'''');\n  if v_subject is not null and not exists (select 1 from public.subjects where code=v_subject) then v_subject := null; end if;\n  insert into public.question_threads (mentor_student_room_id, title, status, subject, topic)\n  values (p_room_id, btrim(p_title), ''pending'', v_subject, nullif(btrim(coalesce(p_topic,'''')),'''')) returning id into v_thread_id;\n  if p_first_message_body is not null and btrim(p_first_message_body) <> '''' then\n    insert into public.question_messages (thread_id, author_id, body) values (v_thread_id, v_student, btrim(p_first_message_body)) returning id into v_message_id;\n  end if;\n  if v_path=''free'' then insert into public.free_question_usage (student_id, mentor_id, thread_id) values (v_student, v_mentor, v_thread_id); end if;\n  return jsonb_build_object(''ok'',true,''thread_id'',v_thread_id,''message_id'',v_message_id,''path'',v_path,''used_free_quota'',(v_path=''free''));\nend; $function$", "-- public.qna_flag_wrong_answer(p_thread_id uuid, p_is_wrong boolean)\nCREATE OR REPLACE FUNCTION public.qna_flag_wrong_answer(p_thread_id uuid, p_is_wrong boolean DEFAULT true)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_uid uuid := auth.uid();\n  v_room uuid;\n  v_student uuid;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n\n  select t.mentor_student_room_id into v_room\n  from public.question_threads t where t.id = p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n\n  select student_id into v_student from public.mentor_student_rooms where id = v_room;\n  if v_uid <> v_student then raise exception ''STUDENT_ONLY''; end if;\n\n  update public.question_threads\n    set is_wrong_answer = coalesce(p_is_wrong, true),\n        mastery_status = case when coalesce(p_is_wrong, true) then ''wrong'' else ''unknown'' end,\n        updated_at = now()\n  where id = p_thread_id;\n\n  return jsonb_build_object(''ok'', true, ''thread_id'', p_thread_id, ''is_wrong_answer'', coalesce(p_is_wrong, true));\nend;\n$function$", "-- public.qna_is_direct_untrusted_writer()\nCREATE OR REPLACE FUNCTION public.qna_is_direct_untrusted_writer()\n RETURNS boolean\n LANGUAGE sql\n STABLE\nAS $function$ select current_user in (''authenticated'',''anon''); $function$", "-- public.qra_thread_writable_for_path(p_name text)\nCREATE OR REPLACE FUNCTION public.qra_thread_writable_for_path(p_name text)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select exists (\n    select 1 from public.question_threads t\n    where t.id = nullif(split_part(p_name, ''/'', 2), '''')::uuid\n      and t.mentor_student_room_id = public.qra_room_uuid_from_path(p_name)\n      and coalesce(t.status, '''') in (''pending'',''open'',''answered'')\n  );\n$function$", "-- public.refund_individual_question(p_question_id uuid)\nCREATE OR REPLACE FUNCTION public.refund_individual_question(p_question_id uuid)\n RETURNS individual_question_escrow_result\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_owner uuid;\n  v_status text;\n  v_refund_ledger uuid;\n  v_res public.individual_question_escrow_result;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n  if p_question_id is null then\n    raise exception ''INVALID_INPUT: question_id is required'' using errcode = ''22023'';\n  end if;\n\n  select q.student_id, q.status, q.refund_ledger_id\n    into v_owner, v_status, v_refund_ledger\n  from public.individual_questions q\n  where q.id = p_question_id\n  for update;\n\n  if not found or v_owner is distinct from v_uid then\n    raise exception ''NOT_QUESTION_OWNER'' using errcode = ''42501'';\n  end if;\n\n  if v_status = ''refunded'' or v_refund_ledger is not null then\n    return public.refund_individual_question_hold(p_question_id);\n  end if;\n\n  if v_status not in (''escrowed'', ''open'', ''assigned'', ''claimed'') then\n    raise exception ''REFUND_NOT_ALLOWED: status=%'', v_status using errcode = ''P0001'';\n  end if;\n\n  v_res := public.refund_individual_question_hold(p_question_id);\n  if not v_res.ok then\n    raise exception ''INDIVIDUAL_QUESTION_REFUND_FAILED:%:%'', v_res.code, v_res.message\n      using errcode = ''P0001'';\n  end if;\n  return v_res;\nend;\n$function$", "-- public.release_individual_question_payout(p_question_id uuid)\nCREATE OR REPLACE FUNCTION public.release_individual_question_payout(p_question_id uuid)\n RETURNS individual_question_escrow_result\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\r\ndeclare\r\n  v_question public.individual_questions%rowtype;\r\n  v_mentor_id uuid;\r\n  v_ledger_id uuid;\r\n  v_wallet_balance bigint;\r\n  v_new_ledger boolean := false;\r\n  v_mentor_cents bigint;  -- 255: 멘토 지급 = floor(price_cents * 0.85), 플랫폼 15% 차액 implicit\r\nbegin\r\n  if p_question_id is null then\r\n    return (false, ''invalid_question'', ''question_id is required'', null, null, null, null)::public.individual_question_escrow_result;\r\n  end if;\r\n\r\n  select *\r\n    into v_question\r\n  from public.individual_questions\r\n  where id = p_question_id\r\n  for update;\r\n\r\n  if not found then\r\n    return (false, ''not_found'', ''individual question not found'', p_question_id, null, null, null)::public.individual_question_escrow_result;\r\n  end if;\r\n\r\n  if v_question.release_ledger_id is not null or v_question.status = ''released'' then\r\n    return (true, ''already_released'', ''individual question already released'', v_question.id, v_question.status, v_question.release_ledger_id, null)::public.individual_question_escrow_result;\r\n  end if;\r\n\r\n  if v_question.refund_ledger_id is not null or v_question.status = ''refunded'' then\r\n    return (false, ''already_refunded'', ''individual question already refunded'', v_question.id, v_question.status, v_question.refund_ledger_id, null)::public.individual_question_escrow_result;\r\n  end if;\r\n\r\n  if v_question.status <> ''answered'' then\r\n    return (false, ''not_answered'', ''question must be answered before payout'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\r\n  end if;\r\n\r\n  if v_question.hold_ledger_id is null then\r\n    return (false, ''hold_missing'', ''escrow hold ledger is missing'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\r\n  end if;\r\n\r\n  v_mentor_id := coalesce(v_question.claimed_mentor_id, v_question.designated_mentor_id);\r\n  if v_mentor_id is null then\r\n    return (false, ''mentor_missing'', ''mentor is missing'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.cash_ledger l\r\n    where l.idempotency_key = ''iq_refund:'' || v_question.id::text\r\n      and l.reason = ''individual_question_refund''\r\n  ) then\r\n    return (false, ''already_refunded'', ''refund ledger already exists'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\r\n  end if;\r\n\r\n  -- 멘토 몫 85% (플랫폼 15%는 price_cents - v_mentor_cents = hold 차액으로 남김)\r\n  v_mentor_cents := floor(v_question.price_cents::numeric * 0.85)::bigint;\r\n  if v_mentor_cents <= 0 then\r\n    return (false, ''invalid_payout'', ''mentor payout amount must be positive'', v_question.id, v_question.status, null, null)::public.individual_question_escrow_result;\r\n  end if;\r\n\r\n  insert into public.cash_ledger (\r\n    user_id,\r\n    delta_cents,\r\n    reason,\r\n    ref_type,\r\n    ref_id,\r\n    idempotency_key\r\n  )\r\n  values (\r\n    v_mentor_id,\r\n    v_mentor_cents,\r\n    ''individual_question_payout'',\r\n    ''individual_questions'',\r\n    v_question.id,\r\n    ''iq_payout:'' || v_question.id::text\r\n  )\r\n  on conflict (idempotency_key) do nothing\r\n  returning id into v_ledger_id;\r\n\r\n  if v_ledger_id is not null then\r\n    v_new_ledger := true;\r\n  else\r\n    select id\r\n      into v_ledger_id\r\n    from public.cash_ledger\r\n    where idempotency_key = ''iq_payout:'' || v_question.id::text\r\n      and reason = ''individual_question_payout'';\r\n  end if;\r\n\r\n  if v_ledger_id is null then\r\n    raise exception ''INDIVIDUAL_QUESTION_PAYOUT_LEDGER_MISSING'';\r\n  end if;\r\n\r\n  if v_new_ledger then\r\n    insert into public.cash_wallets (user_id, balance_cents)\r\n    values (v_mentor_id, 0)\r\n    on conflict (user_id) do nothing;\r\n\r\n    update public.cash_wallets\r\n    set balance_cents = balance_cents + v_mentor_cents\r\n    where user_id = v_mentor_id\r\n    returning balance_cents into v_wallet_balance;\r\n\r\n    if not found then\r\n      raise exception ''INDIVIDUAL_QUESTION_MENTOR_WALLET_CREDIT_FAILED'';\r\n    end if;\r\n  end if;\r\n\r\n  update public.individual_questions\r\n  set\r\n    status = ''released'',\r\n    released_at = coalesce(released_at, now()),\r\n    release_ledger_id = v_ledger_id\r\n  where id = v_question.id\r\n  returning * into v_question;\r\n\r\n  return (true, ''released'', ''individual question payout released'', v_question.id, v_question.status, v_ledger_id, v_wallet_balance)::public.individual_question_escrow_result;\r\nend;\r\n$function$"], "idempotency_key": null}, {"name": "iq_attachment_message_author_guard", "version": "20260804113000", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 20260804113000_iq_attachment_message_author_guard.sql\n-- =============================================================================\n-- DB-IQ-ATTR-001. public.add_individual_question_attachment 은 p_message_id 의\n-- ''질문 소속''(MESSAGE_NOT_IN_QUESTION)만 검증하고 ''메시지 작성자 = 호출자''는\n-- 검증하지 않았다. 같은 질문의 당사자라면 자기 업로드를 **상대방 메시지**에\n-- 연결해 상대가 보낸 것처럼 보이게 할 수 있다(앱 타임라인 §2-1 은 연결 메시지\n-- 작성자를 표시 방향·라벨의 정본으로 쓴다 — 위장 벡터).\n--\n-- 이 migration 은 가드 1건만 ''추가''한다(additive):\n--   p_message_id is not null → individual_question_messages.author_id = auth.uid()\n--   위반 시 MESSAGE_AUTHOR_MISMATCH (errcode 42501).\n--\n-- 불변 계약:\n--   * 시그니처·반환 봉투(jsonb 키·의미: ok/status/idempotent_hit/attachment_id/\n--     question_id/storage_path/message_id_mismatch)·멱등(on conflict do nothing +\n--     선조회 existing 경로)·author_id 기록(auth.uid())·Storage fail-closed 검증\n--     (수렴 M2 §12.6)·경로 첫 세그먼트 검증 전부 그대로.\n--   * grant 도 그대로(CREATE OR REPLACE 는 기존 ACL 보존 — authenticated·\n--     service_role EXECUTE, anon/PUBLIC 없음). GRANT/REVOKE 문 없음.\n--   * 정상 클라이언트 흐름(자기 메시지에만 연결: 멘토 첫 답변·양측 후속 메시지·\n--     멘토 첨삭본)은 영향 0 — 구버전 앱의 p_message_id null 등록도 영향 0.\n--\n-- 선행: 20260803142559(author_id) → 20260803162808(M2 §12.6 Storage fail-closed).\n-- 롤백: supabase/rollback/20260804113000_iq_attachment_message_author_guard_rollback.sql\n-- =============================================================================\nbegin", "-- 사전 게이트: 대상이 배포 정본(메시지 소속 검증 + author_id 기록)이어야 하고,\n-- 가드가 이미 적용돼 있으면 중단한다(이중 적용 방지 — 멱등 재실행은 rollback 후).\ndo $$\ndeclare\n  v_oid oid := to_regprocedure(''public.add_individual_question_attachment(uuid,text,text,text,uuid)'')::oid;\n  v_src text;\nbegin\n  if v_oid is null then\n    raise exception ''target function public.add_individual_question_attachment(uuid,text,text,text,uuid) not found'';\n  end if;\n  select prosrc into v_src from pg_proc where oid = v_oid;\n  if position(''MESSAGE_NOT_IN_QUESTION'' in v_src) = 0\n     or position(''author_id'' in v_src) = 0\n     or position(''idempotent_hit'' in v_src) = 0 then\n    raise exception ''baseline mismatch: expected 20260803162808 deployed body (message check + author_id + idempotent envelope)'';\n  end if;\n  if position(''MESSAGE_AUTHOR_MISMATCH'' in v_src) > 0 then\n    raise exception ''MESSAGE_AUTHOR_MISMATCH guard already applied'';\n  end if;\nend\n$$", "-- 본문 = 배포 정본(20260803162808, prosrc md5 58f0c2411d40b2ce3bcec23efa0c88a1)\n-- + 메시지 작성자 가드 1블록. 그 외 문자 그대로 동일.\ncreate or replace function public.add_individual_question_attachment(p_question_id uuid, p_storage_path text, p_file_name text, p_mime_type text, p_message_id uuid default null::uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $function$\ndeclare\n  v_uid  uuid := (select auth.uid());\n  v_path text;\n  v_id   uuid;\n  v_existing_message_id uuid;\n  v_created boolean := false;\n  v_status text; v_susp timestamptz; v_norm text;\n  v_obj_owner text;\n  v_obj_meta jsonb;\n  v_obj_found boolean := false;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  v_path := btrim(coalesce(p_storage_path, ''''));\n  if v_path = '''' then\n    raise exception ''INVALID_INPUT: storage_path is required'' using errcode = ''22023'';\n  end if;\n\n  if not public.user_is_individual_question_party(p_question_id) then\n    raise exception ''NOT_QUESTION_PARTY'' using errcode = ''42501'';\n  end if;\n\n  if split_part(v_path, ''/'', 1) <> p_question_id::text then\n    raise exception ''STORAGE_PATH_MISMATCH'' using errcode = ''22023'';\n  end if;\n\n  if p_message_id is not null and not exists (\n    select 1\n    from public.individual_question_messages m\n    where m.id = p_message_id\n      and m.question_id = p_question_id\n  ) then\n    raise exception ''MESSAGE_NOT_IN_QUESTION'' using errcode = ''22023'';\n  end if;\n\n  -- 메시지 작성자 = 호출자 가드(20260804113000): 상대방 메시지에 내 첨부를\n  -- 연결하는 것을 막는다 — 타임라인 표시 방향은 연결 메시지 작성자가 정본이라\n  -- 위장으로 이어진다. 자기 메시지 연결(정상 흐름 전부)은 그대로 통과한다.\n  if p_message_id is not null and not exists (\n    select 1\n    from public.individual_question_messages m\n    where m.id = p_message_id\n      and m.author_id = v_uid\n  ) then\n    raise exception ''MESSAGE_AUTHOR_MISMATCH'' using errcode = ''42501'';\n  end if;\n\n  -- 멱등 선조회: 이미 등록된 (question_id, storage_path) 는 기존 계약 그대로 반환\n  -- (legacy 객체 읽기·기존 등록 행을 깨지 않는다 — 신규 등록만 아래에서 fail-closed)\n  select a.id, a.message_id\n    into v_id, v_existing_message_id\n  from public.individual_question_attachments a\n  where a.question_id = p_question_id\n    and a.storage_path = v_path;\n\n  if v_id is null then\n    -- === 신규 등록 검증 (수렴 M2 §12.6) ===\n    -- 계정 상태 4종 + 삭제 진행\n    select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id = v_uid;\n    if not found then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n    v_norm := lower(btrim(coalesce(v_status,'''')));\n    if v_norm = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n    if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n    if v_norm not in (''active'',''suspended'') then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n    if public.account_deletion_write_blocked(v_uid) then raise exception ''ACCOUNT_DELETION_IN_PROGRESS''; end if;\n\n    -- Storage object 존재·소유·MIME·크기 (bucket=individual-question-attachments 고정)\n    select o.owner_id, o.metadata into v_obj_owner, v_obj_meta\n      from storage.objects o\n     where o.bucket_id = ''individual-question-attachments''\n       and o.name = v_path;\n    v_obj_found := found;\n    if not v_obj_found then\n      raise exception ''STORAGE_OBJECT_NOT_FOUND'' using errcode = ''22023'';\n    end if;\n    if v_obj_owner is null or v_obj_owner <> v_uid::text then\n      raise exception ''STORAGE_OBJECT_NOT_OWNED'' using errcode = ''42501'';\n    end if;\n    if v_obj_meta ? ''mimetype''\n       and coalesce(nullif(btrim(p_mime_type), ''''), ''(none)'') <> (v_obj_meta->>''mimetype'') then\n      raise exception ''MIME_MISMATCH'' using errcode = ''22023'';\n    end if;\n    if p_mime_type is not null and btrim(p_mime_type) <> '''' and not exists (\n      select 1 from storage.buckets b\n       where b.id = ''individual-question-attachments''\n         and (b.allowed_mime_types is null or btrim(p_mime_type) = any (b.allowed_mime_types))\n    ) then\n      raise exception ''MIME_NOT_ALLOWED'' using errcode = ''22023'';\n    end if;\n    if v_obj_meta ? ''size'' and (v_obj_meta->>''size'')::bigint > 20971520 then\n      raise exception ''SIZE_EXCEEDED'' using errcode = ''22023'';\n    end if;\n\n    insert into public.individual_question_attachments\n      (question_id, message_id, storage_path, file_name, mime_type, author_id)\n    values\n      (p_question_id, p_message_id, v_path, p_file_name, p_mime_type, v_uid)\n    on conflict (question_id, storage_path) do nothing\n    returning id into v_id;\n\n    if v_id is not null then\n      v_created := true;\n    else\n      select a.id, a.message_id\n        into v_id, v_existing_message_id\n      from public.individual_question_attachments a\n      where a.question_id = p_question_id\n        and a.storage_path = v_path;\n\n      if v_id is null then\n        raise exception ''REGISTER_CONFLICT_UNRESOLVED'' using errcode = ''40001'';\n      end if;\n    end if;\n  end if;\n\n  return jsonb_build_object(\n    ''ok'',            true,\n    ''status'',        case when v_created then ''created'' else ''existing'' end,\n    ''idempotent_hit'', not v_created,\n    ''attachment_id'', v_id,\n    ''question_id'',   p_question_id,\n    ''storage_path'',  v_path,\n    ''message_id_mismatch'',\n      case when v_created then false\n           else coalesce(v_existing_message_id, ''00000000-0000-0000-0000-000000000000''::uuid)\n                is distinct from coalesce(p_message_id, ''00000000-0000-0000-0000-000000000000''::uuid)\n      end\n  );\nend;\n$function$", "-- 자가 검증: 가드 존재 + 기존 계약 마커 보존 + 최소권한 ACL 불변.\ndo $$\ndeclare\n  v_oid oid := to_regprocedure(''public.add_individual_question_attachment(uuid,text,text,text,uuid)'')::oid;\n  v_src text;\nbegin\n  select prosrc into v_src from pg_proc where oid = v_oid;\n  if position(''MESSAGE_AUTHOR_MISMATCH'' in v_src) = 0 then\n    raise exception ''guard missing after replace'';\n  end if;\n  if position(''MESSAGE_NOT_IN_QUESTION'' in v_src) = 0\n     or position(''idempotent_hit'' in v_src) = 0\n     or position(''author_id'' in v_src) = 0 then\n    raise exception ''existing contract markers lost'';\n  end if;\n  if has_function_privilege(''anon'', v_oid, ''EXECUTE'') then\n    raise exception ''anon must not execute add_individual_question_attachment'';\n  end if;\n  if not has_function_privilege(''authenticated'', v_oid, ''EXECUTE'') then\n    raise exception ''authenticated execute missing'';\n  end if;\n  if not has_function_privilege(''service_role'', v_oid, ''EXECUTE'') then\n    raise exception ''service_role execute missing'';\n  end if;\nend\n$$", "commit"], "idempotency_key": null}, {"name": "qna_question_received_notification", "version": "20260805162500", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["set local lock_timeout = ''5s'';\n\ncreate or replace function public.qna_create_question_thread(\n  p_room_id uuid,\n  p_title text,\n  p_subject text default null,\n  p_topic text default null,\n  p_first_message_body text default null\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid; v_status text; v_suspended_until timestamptz;\n  v_created_at timestamptz; v_total int; v_per int; v_subject text; v_thread_id uuid; v_message_id uuid;\n  v_has_active_sub boolean; v_usage json; v_path text; v_sub_id uuid;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_title is null or btrim(p_title)='''' then raise exception ''TITLE_REQUIRED''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=p_room_id;\n  if not found then raise exception ''ROOM_NOT_FOUND''; end if;\n  if v_uid <> v_student then\n    if v_uid = v_mentor then raise exception ''MENTOR_CANNOT_CREATE_THREAD''; else raise exception ''NOT_ROOM_PARTY''; end if;\n  end if;\n  perform 1 from public.users where id=v_student for update;\n  select status, suspended_until, created_at into v_status, v_suspended_until, v_created_at from public.users where id=v_student;\n  if lower(coalesce(v_status,''active''))=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if lower(coalesce(v_status,''active''))=''suspended'' and (v_suspended_until is null or v_suspended_until > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if exists (select 1 from public.user_blocks where (blocker_id=v_student and blocked_id=v_mentor) or (blocker_id=v_mentor and blocked_id=v_student)) then raise exception ''BLOCKED''; end if;\n  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  v_has_active_sub := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'');\n  if v_has_active_sub then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n    v_usage := public.get_weekly_question_usage(v_student, v_mentor);\n    if not coalesce((v_usage->>''can_ask'')::boolean, false) then raise exception ''WEEKLY_LIMIT_EXHAUSTED''; end if;\n    v_path := ''subscription'';\n  else\n    if v_created_at is not null and now() >= v_created_at + interval ''7 days'' then raise exception ''FREE_QUOTA_EXPIRED''; end if;\n    select count(*) into v_total from public.free_question_usage where student_id=v_student;\n    if v_total >= 7 then raise exception ''FREE_QUOTA_TOTAL_EXHAUSTED''; end if;\n    select count(*) into v_per from public.free_question_usage where student_id=v_student and mentor_id=v_mentor;\n    if v_per >= 3 then raise exception ''FREE_QUOTA_MENTOR_EXHAUSTED''; end if;\n    v_path := ''free'';\n  end if;\n  v_subject := nullif(btrim(coalesce(p_subject,'''')),'''');\n  if v_subject is not null and not exists (select 1 from public.subjects where code=v_subject) then v_subject := null; end if;\n  insert into public.question_threads (mentor_student_room_id, title, status, subject, topic)\n  values (p_room_id, btrim(p_title), ''pending'', v_subject, nullif(btrim(coalesce(p_topic,'''')),'''')) returning id into v_thread_id;\n  if p_first_message_body is not null and btrim(p_first_message_body) <> '''' then\n    insert into public.question_messages (thread_id, author_id, body) values (v_thread_id, v_student, btrim(p_first_message_body)) returning id into v_message_id;\n  end if;\n  if v_path=''free'' then insert into public.free_question_usage (student_id, mentor_id, thread_id) values (v_student, v_mentor, v_thread_id); end if;\n\n  -- ── 신규(20260805): 구독 경로 새 질문 → 방 멘토 인앱 알림(question_received) ──\n  -- 같은 트랜잭션 안 — 위 생성이 롤백되면 알림도 롤백(원자), record_domain_notification\n  -- 이 (recipient,event_key) 멱등 + outbox 게이트를 기존 계약대로 처리한다.\n  if v_path = ''subscription'' then\n    perform public.record_domain_notification(\n      v_mentor,\n      ''question_received:'' || v_thread_id::text,\n      ''question_received:'' || v_thread_id::text,\n      ''question_received'',\n      ''새 질문이 도착했어요'',\n      ''학생이 새 질문을 등록했어요.'',\n      ''/mentor/question-room/'' || p_room_id::text || ''?thread='' || v_thread_id::text,\n      jsonb_build_object(''room_id'', p_room_id, ''thread_id'', v_thread_id, ''student_id'', v_student),\n      jsonb_build_object(''room_id'', p_room_id, ''thread_id'', v_thread_id, ''student_id'', v_student)\n    );\n  end if;\n\n  return jsonb_build_object(''ok'',true,''thread_id'',v_thread_id,''message_id'',v_message_id,''path'',v_path,''used_free_quota'',(v_path=''free''));\nend;\n$$;"], "idempotency_key": null}, {"name": "post_reactions_select_own_only", "version": "20260806033409", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- N25: post_reactions SELECT 가 anon 포함 전체공개(USING true)였다 — 전\n-- 사용자의 좋아요·스크랩(user_id, post_id) 쌍이 익명 열람 가능. 표시용\n-- 카운트는 community_posts.like_count(트리거 정본) 경유라 행 노출이 필요\n-- 없고, 앱·웹 모두 본인 행만 조회한다. 숏폼 쌍둥이 테이블\n-- (shortform_reactions_select_own)과 동일 규약으로 정렬한다.\ndrop policy if exists post_reactions_select_all on public.post_reactions;\n-- roles 가 비어 있어 아무에게도 적용되지 않던 고아 정책 정리.\ndrop policy if exists \"본인 반응만 조회\" on public.post_reactions;\ncreate policy post_reactions_select_own on public.post_reactions\n  for select to authenticated\n  using (user_id = (select auth.uid()));"], "idempotency_key": null}, {"name": "connection_notes_room_author_unique", "version": "20260806033452", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- C16: 연결노트는 (방, 작성자)당 1장이 계약인데 DB 제약이 없어 앱이\n-- 중복 내성·자가치유 삭제(e9f1311)로 방어하고 있었다. 유일성 정본을 DB 로\n-- 올린다(현재 행 0건 — 정리 불요). 앱의 upsert/중복 방어는 그대로 동작.\nalter table public.connection_notes\n  add constraint connection_notes_room_author_unique\n  unique (mentor_student_room_id, author_id);"], "idempotency_key": null}, {"name": "community_post_view_record_v2", "version": "20260806033556", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- C7: 게시판 조회수 RPC(increment_community_post_view)는 멱등키가 없어\n-- 같은 진입의 재시도·재빌드마다 무한 가산됐다. 숏폼 v2 규약\n-- (shortform_view_record_v2 — (post, event_key) 멱등)을 게시판에 그대로\n-- 복제한다. 구 RPC 는 웹 호환을 위해 당장 유지(N6 구버전 정리 레인에서 처리).\ncreate table public.community_post_view_events (\n  post_id uuid not null references public.community_posts(id) on delete cascade,\n  event_key uuid not null,\n  viewer_user_id uuid,\n  created_at timestamptz not null default now(),\n  primary key (post_id, event_key)\n);\n-- 정의자 함수만 쓴다 — RLS on + 정책 0개(직접 접근 전면 차단).\nalter table public.community_post_view_events enable row level security;\n\ncreate or replace function public.community_post_view_record_v2(\n  p_post_id uuid, p_event_key uuid\n) returns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_inserted boolean := false;\nbegin\n  if p_post_id is null or p_event_key is null then\n    raise exception ''INVALID_INPUT'' using errcode = ''22023'';\n  end if;\n  -- 게시 상태 공개 글만 계수(숏폼 v2 와 동일 규약)\n  if not exists (select 1 from public.community_posts cp\n                  where cp.id = p_post_id and cp.status = ''published''\n                    and cp.deleted_at is null) then\n    raise exception ''POST_NOT_FOUND'' using errcode = ''P0001'';\n  end if;\n\n  insert into public.community_post_view_events (post_id, event_key, viewer_user_id)\n  values (p_post_id, p_event_key, v_uid)\n  on conflict (post_id, event_key) do nothing;\n  v_inserted := found;\n\n  if v_inserted then\n    update public.community_posts\n       set view_count = view_count + 1\n     where id = p_post_id;\n  end if;\n\n  -- 중복 key 는 idempotent success (계수 증가 없음)\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''incremented'', v_inserted);\nend\n$function$;\n\nrevoke all on function public.community_post_view_record_v2(uuid, uuid) from public;\ngrant execute on function public.community_post_view_record_v2(uuid, uuid) to anon, authenticated;"], "idempotency_key": null}, {"name": "report_target_content_validation", "version": "20260806033833", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- N26: content_reports INSERT 가 user 타입만 실존 검증(report_target_user_valid)\n-- 하고 콘텐츠 4종은 target_id 를 검증하지 않았다 — 존재하지 않는 id 로 신고\n-- 큐 스팸/노이즈 가능. user 검증과 같은 규약(STABLE SECURITY DEFINER)의\n-- 콘텐츠 실존 검증을 추가하고 INSERT 정책에 결합한다.\ncreate or replace function public.report_target_content_valid(\n  p_target_type text, p_target_id uuid\n) returns boolean\nlanguage sql\nstable security definer\nset search_path to ''''\nas $function$\n  select p_target_id is not null and case p_target_type\n    when ''community_post''    then exists (select 1 from public.community_posts   t where t.id = p_target_id)\n    when ''shortform_post''    then exists (select 1 from public.shortform_posts   t where t.id = p_target_id)\n    when ''community_comment'' then exists (select 1 from public.community_comments t where t.id = p_target_id)\n    when ''board_comment''     then exists (select 1 from public.comments          t where t.id = p_target_id)\n    else false\n  end\n$function$;\n\nrevoke all on function public.report_target_content_valid(text, uuid) from public;\ngrant execute on function public.report_target_content_valid(text, uuid) to authenticated;\n\ndrop policy content_reports_insert_reporter on public.content_reports;\ncreate policy content_reports_insert_reporter on public.content_reports\n  for insert to authenticated\n  with check (\n    reporter_id = (select auth.uid())\n    and status = ''pending''\n    and admin_note is null and resolved_by is null and resolved_at is null\n    and target_type = any (array[''community_post'',''shortform_post'',''community_comment'',''board_comment'',''user''])\n    and case when target_type = ''user''\n         then report_target_user_valid(target_id)\n         else report_target_content_valid(target_type, target_id)\n        end\n  );"], "idempotency_key": null}, {"name": "weekly_question_usage_self_batch", "version": "20260806041547", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- C15: 학생 질문방 목록·마이페이지가 멘토 수만큼 사용량 RPC 를 병렬\n-- 호출(N회 왕복)하던 것을 1회로 묶는 배치 self RPC. 계산부는 정본\n-- public.get_weekly_question_usage 재사용(한도 규칙 이원화 금지 —\n-- weekly_question_usage_self 와 동일 원칙), 학생은 auth.uid() 로 확정.\ncreate or replace function api_web_v1.weekly_question_usage_self_batch(\n  p_mentor_ids uuid[]\n) returns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_items jsonb := ''[]''::jsonb;\n  v_mid uuid;\nbegin\n  if v_uid is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  end if;\n  if p_mentor_ids is null or coalesce(array_length(p_mentor_ids, 1), 0) = 0 then\n    return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''items'', ''[]''::jsonb);\n  end if;\n  if array_length(p_mentor_ids, 1) > 50 then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''TOO_MANY_MENTORS'');\n  end if;\n  for v_mid in select distinct m from unnest(p_mentor_ids) m where m is not null loop\n    v_items := v_items || jsonb_build_array(\n      public.get_weekly_question_usage(v_uid, v_mid)::jsonb\n        || jsonb_build_object(''mentor_id'', v_mid));\n  end loop;\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''items'', v_items);\nend $function$;\n\nrevoke all on function api_web_v1.weekly_question_usage_self_batch(uuid[]) from public;\ngrant execute on function api_web_v1.weekly_question_usage_self_batch(uuid[]) to authenticated;"], "idempotency_key": null}, {"name": "report_target_content_valid_rpc_unexposed", "version": "20260806075316", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- 리뷰 후속: report_target_content_valid 는 content_reports INSERT 정책\n-- 내부용 헬퍼인데 public 스키마 + authenticated EXECUTE 라 Data API(/rpc)로\n-- 직접 호출 가능했다(RLS 우회 콘텐츠 id 존재 탐지 표면). PostgREST 에\n-- 노출되지 않는 전용 스키마(rls_private)로 옮겨 정책 평가 권한만 남긴다.\n-- (동일 노출인 기존 public.report_target_user_valid 는 정본 팩 소관 — 별도 과제.)\ncreate schema if not exists rls_private;\nrevoke all on schema rls_private from public;\ngrant usage on schema rls_private to authenticated, service_role;\n\ncreate or replace function rls_private.report_target_content_valid(\n  p_target_type text, p_target_id uuid\n) returns boolean\nlanguage sql\nstable security definer\nset search_path to ''''\nas $function$\n  select p_target_id is not null and case p_target_type\n    when ''community_post''    then exists (select 1 from public.community_posts   t where t.id = p_target_id)\n    when ''shortform_post''    then exists (select 1 from public.shortform_posts   t where t.id = p_target_id)\n    when ''community_comment'' then exists (select 1 from public.community_comments t where t.id = p_target_id)\n    when ''board_comment''     then exists (select 1 from public.comments          t where t.id = p_target_id)\n    else false\n  end\n$function$;\n\nrevoke all on function rls_private.report_target_content_valid(text, uuid) from public, anon;\ngrant execute on function rls_private.report_target_content_valid(text, uuid) to authenticated, service_role;\n\ndrop policy content_reports_insert_reporter on public.content_reports;\ncreate policy content_reports_insert_reporter on public.content_reports\n  for insert to authenticated\n  with check (\n    reporter_id = (select auth.uid())\n    and status = ''pending''\n    and admin_note is null and resolved_by is null and resolved_at is null\n    and target_type = any (array[''community_post'',''shortform_post'',''community_comment'',''board_comment'',''user''])\n    and case when target_type = ''user''\n         then public.report_target_user_valid(target_id)\n         else rls_private.report_target_content_valid(target_type, target_id)\n        end\n  );\n\ndrop function public.report_target_content_valid(text, uuid);"], "idempotency_key": null}, {"name": "mobile_version_policy_latest_build_16", "version": "20260806075353", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- G2 데이터 정합의 멱등 마이그레이션화(리뷰 후속): 2026-08-06 콘솔 직접\n-- UPDATE 로 반영했던 버전 정책 데이터를 재생 가능한 형태로 원장에 기록한다.\n-- 조건부라 재실행·클린 DB 재생 모두 안전(행이 없으면 no-op — 정책 행 시드는\n-- 운영 데이터 소관).\nupdate public.mobile_app_version_policies\n   set latest_build = greatest(coalesce(latest_build, 0), 16),\n       minimum_version_name = coalesce(minimum_version_name, ''1.0.0''),\n       updated_at = now()\n where platform in (''ios'',''android'')\n   and (coalesce(latest_build, 0) < 16 or minimum_version_name is null);"], "idempotency_key": null}, {"name": "deletion_guard_internal_state_probe", "version": "20260806200000", "rollback": null, "created_by": null, "statements": ["-- [S1-1 2026-08-06] QA-A1 — 개별질문 정산 지급 불가(403) 해소.\n--\n-- 증상: 학생이 ''해결 완료(멘토에게 정산)''를 누르면 POST /rpc/release_individual_question\n--       이 403 으로 실패하고 DB 오류 ACCOUNT_DELETION_PROBE_FORBIDDEN 이 남는다.\n--       실기기 QA 2026-08-06 에서 3회 전부 재현, 묶인 금액 5,999원.\n--\n-- 원인: public.account_deletion_write_blocked(p_user_id) 가 두 책임을 겸직한다.\n--   ① 앱용 self-probe 제한 — auth.uid() 와 다른 id 를 물으면 42501 로 거부\n--      (타인의 탈퇴 진행 여부를 캐내는 오라클 방지)\n--   ② 실제 상태 조회 — 그 사용자의 탈퇴 잡이 진행 중인가\n--   트리거 가드 public.account_deletion_write_guard() 는 ② 만 필요한데,\n--   NEW 행의 소유자 id(= 지급 대상 멘토)를 넘기므로 학생 세션에서는 ① 에 걸린다.\n--   → cash_ledger INSERT(멘토 앞)와 cash_wallets UPDATE(멘토 잔액)가 모두 42501,\n--     PostgREST 403, 트랜잭션 전체 롤백. **멘토에게 돈이 가는 모든 경로가 막힌다.**\n--   그동안 안 터진 이유: 돈 이동이 전부 본인 계좌였고(충전 +, 구독 결제 −,\n--   에스크로 보관 −) 타인 계좌 입금이 이번이 처음이다.\n--\n-- 수정: ② 전용 내부 함수를 분리하고 트리거 가드만 그쪽을 보게 한다.\n--   - 앱 계약인 account_deletion_write_blocked 는 **시그니처·동작·권한 모두 불변**\n--     (앱 부팅 프로필 로드가 이 RPC 를 쓴다 — 지도 A1-R9). 다른 호출부 16곳도\n--     전부 본인 id 를 넘기는 self-check 라 영향 없음.\n--   - 새 내부 함수는 아무에게도 EXECUTE 를 주지 않는다(REVOKE ALL). 트리거\n--     함수가 SECURITY DEFINER 로 소유자 권한에서 호출하므로 grant 가 불필요하고,\n--     grant 를 주면 ① 이 막던 ''타인 탈퇴상태 조회 오라클''이 되살아난다.\n--\n-- 보존되는 보호: 대상 사용자의 탈퇴가 진행 중이면 종전대로\n--   ACCOUNT_DELETION_IN_PROGRESS 로 차단된다(가드 6개 트리거 전부 동일).\n--   탈퇴 워커의 우회(ssambership.deletion_worker=''on'')도 그대로다.\n\n-- ── ② 전용: probe 제한 없는 상태 조회(내부 전용) ───────────────────────────\ncreate or replace function public.account_deletion_state_blocked(p_user_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path to ''''\nas $function$\n  select exists (\n    select 1\n      from public.account_deletion_jobs j\n     where j.user_id = p_user_id\n       and j.state in (''locked'', ''purging'', ''storage_purged'', ''finalized'', ''auth_soft_deleted'')\n  );\n$function$", "comment on function public.account_deletion_state_blocked(uuid) is\n  ''내부 전용(트리거 가드) — 탈퇴 진행 여부만 반환한다. auth.uid() probe 제한이 ''\n  ''없으므로 어떤 role 에도 EXECUTE 를 주지 않는다. 앱·웹은 반드시 ''\n  ''account_deletion_write_blocked(자기 id 전용)를 쓴다.''", "revoke all on function public.account_deletion_state_blocked(uuid) from public", "revoke all on function public.account_deletion_state_blocked(uuid) from anon", "revoke all on function public.account_deletion_state_blocked(uuid) from authenticated", "-- ── 트리거 가드: 내부 함수를 보도록 교체(그 외 동작 불변) ──────────────────\ncreate or replace function public.account_deletion_write_guard()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $function$\ndeclare v_col text := TG_ARGV[0]; v_uid uuid;\nbegin\n  if current_setting(''ssambership.deletion_worker'', true) = ''on'' then\n    return NEW;\n  end if;\n  v_uid := (to_jsonb(NEW) ->> v_col)::uuid;\n  -- ★ account_deletion_write_blocked 가 아니라 내부 상태 함수를 쓴다.\n  --   행 소유자가 세션 사용자와 다른 정당한 쓰기(멘토 정산 입금 등)를\n  --   self-probe 제한이 막아버리던 회귀를 해소한다.\n  if v_uid is not null and public.account_deletion_state_blocked(v_uid) then\n    raise exception ''ACCOUNT_DELETION_IN_PROGRESS'';\n  end if;\n  return NEW;\nend $function$", "-- ── 가드 트리거를 BEFORE → AFTER 로 옮긴다(탈퇴상태 오라클 차단) ────────────\n--\n-- 왜 필요한가: 위에서 self-probe 제한을 뺐기 때문에 가드는 이제 **남의 id** 에\n--   대해서도 탈퇴 상태를 판정한다. 그런데 BEFORE 트리거는 RLS WITH CHECK 보다\n--   먼저 실행된다. 그래서 공격자가 소유자 컬럼에 임의의 uuid 를 넣고 INSERT 를\n--   시도하면, 원래 RLS 가 42501 로 끝냈을 요청이\n--     · 그 사용자가 탈퇴 진행 중 → P0001 ACCOUNT_DELETION_IN_PROGRESS\n--     · 아니면                   → 42501 (RLS 거부)\n--   로 갈라져 **임의 uuid 의 탈퇴 진행 여부를 알아내는 오라클**이 된다.\n--   수정 전에는 self-probe 제한이 두 경우를 모두 42501 로 만들어 구분이 없었다.\n--   (authenticated 가 INSERT 를 시도할 수 있는 payments · question_messages ·\n--    shortform_posts 3개 테이블에서 실제로 재현된다.)\n--\n-- 어떻게 막는가: AFTER ROW 트리거는 RLS WITH CHECK 통과 **이후**에만 실행된다.\n--   권한 없는 시도는 가드에 닿기 전에 42501 로 끝나 상태가 새지 않는다.\n--   권한 있는 정당한 쓰기(멘토 정산 입금 등)는 종전대로 가드가 판정해\n--   ACCOUNT_DELETION_IN_PROGRESS 로 막는다 — 보호 강도는 그대로다.\n--\n-- 안전성: 가드는 NEW 를 읽기만 하고 고치지 않으므로 BEFORE 일 이유가 없다\n--   (AFTER 에서 반환값은 무시되지만 이 함수는 행을 바꾸지 않는다). 예외가 나면\n--   문 전체가 롤백되므로 잠깐 들어갔다 사라지는 행도 남지 않는다.\n--   워커 우회(ssambership.deletion_worker=''on'')와 대상 컬럼 인자(TG_ARGV[0])는 불변.\n--\n-- 멱등: 각 트리거를 drop if exists 후 재생성한다.\n\ndrop trigger if exists adg_cash_wallets on public.cash_wallets", "create trigger adg_cash_wallets after insert or update on public.cash_wallets\n  for each row execute function public.account_deletion_write_guard(''user_id'')", "drop trigger if exists adg_cash_ledger on public.cash_ledger", "create trigger adg_cash_ledger after insert on public.cash_ledger\n  for each row execute function public.account_deletion_write_guard(''user_id'')", "drop trigger if exists adg_payments on public.payments", "create trigger adg_payments after insert on public.payments\n  for each row execute function public.account_deletion_write_guard(''user_id'')", "drop trigger if exists adg_question_messages on public.question_messages", "create trigger adg_question_messages after insert on public.question_messages\n  for each row execute function public.account_deletion_write_guard(''author_id'')", "drop trigger if exists adg_community_posts on public.community_posts", "create trigger adg_community_posts after insert on public.community_posts\n  for each row execute function public.account_deletion_write_guard(''author_id'')", "drop trigger if exists adg_shortform_posts on public.shortform_posts", "create trigger adg_shortform_posts after insert on public.shortform_posts\n  for each row execute function public.account_deletion_write_guard(''author_id'')"], "idempotency_key": null}, {"name": "community_posts_select_deleted_filter", "version": "20260806200500", "rollback": null, "created_by": null, "statements": ["-- [S1-2 2026-08-06] QA-A4 — 삭제한 글이 서버 권한상 계속 조회 가능.\n--\n-- 증상: 게시글을 삭제해도 `deleted_at` 만 찍히고 `status` 는 published 로 남는다.\n--       목록에서 안 보이는 것은 앱·웹이 뷰(api_web_v1.community_posts_v1)를\n--       쓰기 때문일 뿐, 베이스 테이블에 직접 요청하면 삭제한 글이 그대로 응답된다.\n--       DB 실측: deleted_at 이 찍힌 published 글 1건 존재.\n--\n-- 원인: public.community_posts 의 SELECT 정책 3개가 **전부 deleted_at 을 보지\n--       않는다**. RLS 정책은 permissive OR 결합이라 가장 느슨한 하나만 통과해도\n--       행이 나간다.\n--         · \"누구나 게시글 읽기\" (public)            : status=''published''\n--         · cp_select_own       (public)             : author_id=auth.uid() OR is_admin()\n--         · cp_select_published (anon,authenticated) : published OR author OR admin\n--       합집합 = published OR 본인 OR admin — 즉 cp_select_published 는 다른\n--       둘의 합집합에 완전히 포함되는 중복이다. 필터를 한 곳에만 추가하면\n--       나머지가 그대로 새기 때문에, 이번 결함이 재발하지 않도록 **하나로 통합**한다.\n--\n-- 수정 후 가시성:\n--   일반 사용자·비로그인 : deleted_at IS NULL AND (published OR 본인 글)\n--   admin                : 제한 없음(검수·모더레이션 목적으로 삭제분도 조회 가능)\n--   service_role         : BYPASSRLS 라 정책 무관(실측 rolbypassrls=true)\n-- 앱·웹이 쓰는 뷰의 조건(deleted_at IS NULL AND (published OR 본인))과 정확히\n-- 일치시켜, 뷰 경유와 직접 조회의 결과가 어긋나지 않게 한다.\n--\n-- 적용 범위: deleted_at 컬럼을 가진 public 테이블은 community_posts 하나뿐이므로\n--            (실측) 다른 테이블에 동일 결함은 없다.\n--\n-- 정책 이름이 바뀌므로 이름을 하드 어설트하던 과거 검증 스크립트\n-- (scripts/verify/s2_2_batch_f_verify.sql F-03·R-02)를 통합본도 통과하도록 함께 고쳤다.\n\ndrop policy if exists \"누구나 게시글 읽기\" on public.community_posts", "drop policy if exists cp_select_own on public.community_posts", "drop policy if exists cp_select_published on public.community_posts", "-- 재적용 안전(멱등): CREATE POLICY 에는 OR REPLACE 가 없다. 이 줄이 없으면\n-- 두 번째 적용이 42710 duplicate_object 로 실패해 pack 재생·부분 재적용이 깨진다\n-- — 이 배치에서 유일하게 멱등하지 않던 파일이었다.\ndrop policy if exists cp_select_visible on public.community_posts", "create policy cp_select_visible on public.community_posts\n  for select\n  using (\n    (deleted_at is null\n      and (status = ''published'' or author_id = (select auth.uid())))\n    or (select public.is_admin()) = true\n  )", "comment on policy cp_select_visible on public.community_posts is\n  ''S1-2/QA-A4: 삭제(soft-delete)된 글은 작성자에게도 보이지 않는다. admin 은 ''\n  ''검수 목적으로 제한 없이 조회한다. 종전 3중 중복 정책(누구나 게시글 읽기 · ''\n  ''cp_select_own · cp_select_published)을 하나로 통합 — 필터가 한 정책에만 ''\n  ''추가돼 나머지로 새는 재발을 막는다.''"], "idempotency_key": null}, {"name": "content_reports_idempotent_open", "version": "20260806201000", "rollback": null, "created_by": null, "statements": ["-- [S1-3 2026-08-06] QA-B4 — 중복 신고가 무제한으로 저장된다.\n--\n-- 증상: 동일 신고자·동일 대상·동일 사유가 그대로 중복 저장된다.\n--       DB 실측: content_reports 3건 중 (reporter, target_type, target_id, reason)\n--       distinct 2 — 같은 사용자를 external_contact 로 1분 30초 간격 2회 신고한\n--       조합이 그대로 남아 있다.\n--\n-- 원인: content_reports 에 중복 방지 장치가 없다(제약 = pkey + fk 2 + check 2,\n--       유니크 인덱스 0, 나머지 인덱스도 전부 비유니크).\n--\n-- 결정(오너 판단 2026-08-06): **차단이 아니라 멱등 처리**.\n--   재신고를 오류로 되돌리면 앱이 실패 문구를 띄워야 하고, 사용자는 자기 신고가\n--   접수되지 않았다고 오해한다. 대신 조용히 기존 신고를 갱신하고 새 행을 만들지\n--   않는다 — 사용자 경험은 ''접수됨'' 그대로이고 모더레이션 큐에는 중복이 쌓이지\n--   않는다. 앱은 direct INSERT(community_write_repository.dart:423)만 하고\n--   반환 행을 검사하지 않으므로 **앱 수정 없이** 적용된다.\n--\n-- 중복 판정 범위: **아직 처리 중인 신고(pending·reviewing)** 에 한한다.\n--   이미 처리(resolved/dismissed/rejected/hidden/removed)된 뒤의 재신고는\n--   새 사건으로 보고 정상 접수한다 — 시간이 지나 재발한 행위를 신고할 수\n--   없게 되면 모더레이션 신호를 잃는다.\n--   ※ 이 범위를 ''영구''로 바꾸려면 아래 status 조건만 제거하면 된다.\n--\n-- 기존 중복 1쌍은 삭제하지 않는다 — 사용자 신고 기록을 지시 없이 지우지 않으며,\n-- 멱등 방식은 유니크 인덱스와 달리 기존 데이터 정리를 요구하지 않는다.\n--\n-- ★ 본인성 게이트(적대적 검증 2026-08-06 에서 발견한 RLS 우회를 막는 핵심) ★\n--   BEFORE INSERT 트리거는 RLS WITH CHECK **보다 먼저** 실행되고, 트리거가\n--   NULL 을 반환하면 WITH CHECK 는 아예 평가되지 않는다. 그래서 reporter_id 를\n--   가리지 않고 개입하면 이 SECURITY DEFINER 함수가 INSERT 정책\n--   (content_reports_insert_reporter: reporter_id = auth.uid() · status=''pending'' ·\n--    대상 실존 검증)과 admin 전용 UPDATE 정책을 **통째로 우회**한다 —\n--   공격자가 reporter_id 에 남의 uuid 를 넣어 그 사람의 신고 본문을 덮어쓸 수 있다\n--   (실제로 재현했다: 사용자 C 가 사용자 A 의 신고 description 을 교체).\n--   따라서 **세션 사용자 본인의 신고에만** 개입하고, 그 외에는 손대지 않고\n--   RLS 가 판정하게 넘긴다. auth.uid() 가 없는 세션(service_role·워커·마이그레이션)도\n--   동일하게 통과시킨다 — 그 경로는 애초에 중복 방지 대상이 아니다.\n--\n-- ★ 동시성: lookup → INSERT 사이에는 TOCTOU 창이 있어, 같은 신고를 동시에 두 번\n--   보내면 양쪽 다 \"없음\"을 보고 둘 다 삽입된다. 기존 중복 1쌍 때문에 부분 유니크\n--   인덱스는 만들 수 없으므로(생성 자체가 실패) 트랜잭션 advisory lock 으로\n--   같은 키의 동시 삽입을 직렬화한다.\n\ncreate or replace function public.content_reports_dedupe_open()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_existing uuid;\nbegin\n  -- ① 본인 신고가 아니면 개입하지 않는다 → RLS WITH CHECK 가 정상 평가된다.\n  if v_uid is null or NEW.reporter_id is distinct from v_uid then\n    return NEW;\n  end if;\n\n  -- ② 같은 (신고자·대상·사유) 키의 동시 삽입 직렬화 — 먼저 온 트랜잭션이\n  --    커밋될 때까지 뒤 트랜잭션이 대기하므로 ③ 의 lookup 이 최신 상태를 본다.\n  perform pg_advisory_xact_lock(\n    hashtextextended(\n      ''content_reports_dedupe_open|'' || v_uid::text\n        || ''|'' || coalesce(NEW.target_type, '''')\n        || ''|'' || coalesce(NEW.target_id::text, '''')\n        || ''|'' || coalesce(NEW.reason, ''''),\n      0\n    )\n  );\n\n  -- ③ 열려 있는 본인 신고만 찾는다(reporter_id = 세션 사용자로 고정).\n  select r.id\n    into v_existing\n    from public.content_reports r\n   where r.reporter_id = v_uid\n     and r.target_type = NEW.target_type\n     and r.target_id is not distinct from NEW.target_id\n     and r.reason is not distinct from NEW.reason\n     and r.status in (''pending'', ''reviewing'')\n   order by r.created_at desc\n   limit 1;\n\n  if v_existing is null then\n    return NEW;                       -- 첫 신고(또는 이전 건이 처리 완료) → 정상 삽입\n  end if;\n\n  -- ④ 열려 있는 같은 신고가 있다 → 새로 쓰지 않고 기존 건을 갱신(멱등).\n  --    새 설명이 있으면 살리고, 없으면 기존 설명을 보존한다.\n  --    WHERE 에 reporter_id 를 한 번 더 건다 — ①·③ 이 무너져도 남의 행에\n  --    UPDATE 가 닿지 않도록 하는 이중 방어다.\n  update public.content_reports\n     set description = coalesce(nullif(btrim(coalesce(NEW.description, '''')), ''''), description),\n         updated_at  = now()\n   where id = v_existing\n     and reporter_id = v_uid;\n\n  return null;                        -- 삽입 생략 — 클라이언트에는 성공으로 보인다\nend\n$function$", "comment on function public.content_reports_dedupe_open() is\n  ''S1-3/QA-B4: 처리 중(pending·reviewing)인 **본인** 신고가 있으면 새 행을 만들지 ''\n  ''않고 기존 건을 갱신한다(멱등). reporter_id 가 auth.uid() 와 다르거나 세션이 ''\n  ''없으면 아무것도 하지 않고 그대로 통과시킨다 — BEFORE 트리거의 return null 이 ''\n  ''RLS WITH CHECK 평가를 건너뛰므로, 본인성 게이트가 없으면 이 함수가 INSERT·UPDATE ''\n  ''정책을 우회하는 통로가 된다. 동시 중복은 advisory xact lock 으로 직렬화한다.''", "drop trigger if exists content_reports_dedupe_open_before_insert on public.content_reports", "create trigger content_reports_dedupe_open_before_insert\n  before insert on public.content_reports\n  for each row execute function public.content_reports_dedupe_open()", "-- 조회 효율(중복 판정 lookup) — 유니크가 아니다.\ncreate index if not exists content_reports_dedupe_lookup_idx\n  on public.content_reports (reporter_id, target_type, target_id, reason)\n  where status in (''pending'', ''reviewing'')"], "idempotency_key": null}, {"name": "qna_student_message_notifies_mentor", "version": "20260806201500", "rollback": null, "created_by": null, "statements": ["-- [S1-4 2026-08-06] QA-B1 — 학생이 메시지를 보내도 멘토에게 알림이 가지 않는다.\n--\n-- 증상: 질문방에서 학생이 메시지를 보내도 멘토는 아무 알림을 받지 못한다.\n--       멘토가 받는 건 ''새 질문 등록''(스레드 생성) 하나뿐이라, 이후 대화는\n--       멘토가 목록을 직접 열어봐야 안다.\n--       DB 실측: question_received 2건(스레드 생성분) · question_answered 13건\n--       (멘토→학생) — 학생 발신에서 생성된 멘토 수신 알림 0건.\n--\n-- 원인: 트리거 trg_qm_answer_notification_after 는 학생 INSERT 에도 매번\n--       발화하지만, 함수 public.qna_emit_answer_notification 이\n--         if auth.uid() is distinct from v_mentor then return;   -- 멘토 세션만\n--       로 즉시 빠져나간다. 수신자도 v_student 로 고정돼 있고 작성자=멘토 검증도\n--       걸려 있어 학생 발신은 무음 처리된다.\n--       (개별질문 경로는 양방향 알림이 정상 작동한다 — 질문방만의 결함)\n--\n-- 수정: 발신자에 따라 방향을 나눈다.\n--   · 멘토 발신 → 학생에게 question_answered  (기존 동작 그대로, 회귀 없음)\n--   · 학생 발신 → 멘토에게 question_received  (신규)\n--\n-- 알림 타입 결정(오너 판단 2026-08-06): **기존 question_received 재사용**.\n--   현재 출시 후보 앱(1.0.0+18)은 알림 타입을 정확 일치 18종으로만 인식하고\n--   목록 밖 타입은 unknown → ''일반 알림'' + 이동 없음으로 처리한다. 새 타입을\n--   지금 넣으면 앱이 업데이트되기 전까지 탭해도 이동하지 않는다. question_received\n--   를 쓰면 질문방 종류로 분류되고 딥링크도 정상 동작하며, **앱 수정이 필요 없다**.\n--   문구는 행의 title/body 를 그대로 렌더하므로 ''새 메시지''로 정확히 구분된다.\n--   유형 라벨까지 분리하려면 다음 앱 버전에서 전용 타입을 추가하면 된다.\n--\n-- 멱등: event_key 를 message_id 기준으로 잡아 스레드 생성 알림\n--   (question_received:<thread_id>)과 절대 충돌하지 않는다.\n--\n-- 중복 방지: 스레드의 **첫 메시지**는 이 경로에서 알리지 않는다. 질문 생성 RPC\n--   (qna_create_question_thread)가 이미 ''새 질문'' 알림을 보내기 때문이다 —\n--   검증에서 무료질문 1건에 멘토 알림이 2건 생기는 것을 확인하고 막았다.\n--   판정은 \"이 스레드에 더 앞선 메시지가 있는가\"로 하며, 첫 메시지를 스레드와\n--   같은 트랜잭션에서 만들든(p_first_message_body 제공) 나중에 따로 보내든\n--   (nullable — 무료질문 진입점이 그렇다) 동일하게 성립한다.\n--   두 번째 메시지부터 이 경로가 동작한다.\n\ncreate or replace function public.qna_emit_answer_notification(\n  p_thread_id uuid,\n  p_message_id uuid default null::uuid,\n  p_attachment_id uuid default null::uuid\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $function$\ndeclare\n  v_room uuid; v_student uuid; v_mentor uuid; v_name text;\n  v_key text; v_body_suffix text; v_meta jsonb;\n  v_actor uuid;\nbegin\n  if p_thread_id is null then return; end if;\n  -- 정확히 하나의 행 스코프(메시지 XOR 단독첨부)만 허용 — 호출 계약 위반은 즉시 실패(무음 금지).\n  if (p_message_id is null) = (p_attachment_id is null) then\n    raise exception ''ANSWER_EVENT_SCOPE_REQUIRED'';\n  end if;\n\n  select t.mentor_student_room_id into v_room\n  from public.question_threads t where t.id = p_thread_id;\n  if v_room is null then return; end if;\n\n  select student_id, mentor_id into v_student, v_mentor\n  from public.mentor_student_rooms where id = v_room;\n  if v_student is null then return; end if;\n\n  v_actor := (select auth.uid());\n\n  -- ── 멘토 발신 → 학생 (기존 동작 · 불변) ────────────────────────────────\n  if v_actor is not distinct from v_mentor then\n    if p_message_id is not null then\n      if not exists (\n        select 1 from public.question_messages m\n        where m.id = p_message_id and m.thread_id = p_thread_id and m.author_id = v_mentor\n      ) then return; end if;\n      v_key := ''question_answer_message:'' || p_message_id::text;\n      v_body_suffix := ''님이 답변을 남겼습니다.'';\n      v_meta := jsonb_build_object(''room_id'', v_room, ''thread_id'', p_thread_id, ''message_id'', p_message_id);\n    else\n      if not exists (\n        select 1 from public.question_attachments a\n        where a.id = p_attachment_id and a.thread_id = p_thread_id\n          and a.author_id = v_mentor and a.message_id is null\n      ) then return; end if;\n      v_key := ''question_answer_attachment:'' || p_attachment_id::text;\n      v_body_suffix := ''님이 파일을 보냈습니다.'';\n      v_meta := jsonb_build_object(''room_id'', v_room, ''thread_id'', p_thread_id, ''attachment_id'', p_attachment_id);\n    end if;\n\n    select coalesce(nullif(btrim(full_name),''''), nullif(btrim(nickname),''''), ''멘토'')\n      into v_name from public.users where id = v_mentor;\n\n    perform public.record_domain_notification(\n      v_student,\n      v_key,\n      v_key,\n      ''question_answered'',\n      ''새 답변이 도착했어요'',\n      coalesce(v_name,''멘토'') || v_body_suffix,\n      ''/question-room/'' || v_room::text || ''?thread='' || p_thread_id::text,\n      v_meta,\n      v_meta\n    );\n    return;\n  end if;\n\n  -- ── 학생 발신 → 멘토 (S1-4 신규) ──────────────────────────────────────\n  if v_actor is not distinct from v_student then\n    if p_message_id is not null then\n      if not exists (\n        select 1 from public.question_messages m\n        where m.id = p_message_id and m.thread_id = p_thread_id and m.author_id = v_student\n      ) then return; end if;\n      -- ★ 스레드의 **첫 메시지**는 이 경로에서 알리지 않는다.\n      --   질문 생성 RPC(qna_create_question_thread)가 이미 ''새 질문이 도착했어요''\n      --   (question_received:<thread_id>)를 보내므로, 여기서 또 보내면 질문\n      --   1건에 멘토 알림이 2건 생긴다(무료·구독 공통 — 검증에서 실제 확인).\n      --\n      --   판정 기준은 **이 스레드에 이보다 앞선 메시지가 있는가**다.\n      --   앞선 것이 없으면 곧 첫 메시지 → 침묵, 있으면 → 알림.\n      --   (초안이던 ''스레드와 같은 트랜잭션인가''(m2.created_at = t2.created_at)는\n      --    p_first_message_body 를 주지 않고 스레드만 만드는 경로에서 무너진다 —\n      --    free_question_entry.createFreeThread 의 firstMessageBody 는 nullable 이라\n      --    학생의 진짜 첫 메시지가 별도 트랜잭션으로 들어오고, 그러면 생성 알림과\n      --    이 알림이 겹쳐 다시 2건이 된다. 그 경로까지 덮으려면 순서 비교가 맞다.)\n      --   동률 created_at 도 (created_at, id) 튜플 비교로 전순서가 되어\n      --   2번째 메시지를 잘못 삼키지 않는다.\n      if not exists (\n        select 1\n          from public.question_messages m_prev\n          join public.question_messages m_self on m_self.id = p_message_id\n         where m_prev.thread_id = p_thread_id\n           and (m_prev.created_at, m_prev.id) < (m_self.created_at, m_self.id)\n      ) then return; end if;\n      v_key := ''question_student_message:'' || p_message_id::text;\n      v_body_suffix := ''님이 메시지를 보냈어요.'';\n      v_meta := jsonb_build_object(''room_id'', v_room, ''thread_id'', p_thread_id, ''message_id'', p_message_id);\n    else\n      if not exists (\n        select 1 from public.question_attachments a\n        where a.id = p_attachment_id and a.thread_id = p_thread_id\n          and a.author_id = v_student and a.message_id is null\n      ) then return; end if;\n      v_key := ''question_student_attachment:'' || p_attachment_id::text;\n      v_body_suffix := ''님이 파일을 보냈어요.'';\n      v_meta := jsonb_build_object(''room_id'', v_room, ''thread_id'', p_thread_id, ''attachment_id'', p_attachment_id);\n    end if;\n\n    select coalesce(nullif(btrim(full_name),''''), nullif(btrim(nickname),''''), ''학생'')\n      into v_name from public.users where id = v_student;\n\n    perform public.record_domain_notification(\n      v_mentor,\n      v_key,\n      v_key,\n      ''question_received'',\n      ''새 메시지가 도착했어요'',\n      coalesce(v_name,''학생'') || v_body_suffix,\n      ''/mentor/question-room/'' || v_room::text || ''?thread='' || p_thread_id::text,\n      v_meta,\n      v_meta\n    );\n    return;\n  end if;\n\n  -- 방 당사자가 아닌 세션(관리자·워커 등)은 알림을 만들지 않는다.\n  return;\nend;\n$function$"], "idempotency_key": null}, {"name": "subscription_settlement_hourly_schedule", "version": "20260806202000", "rollback": null, "created_by": null, "statements": ["-- [S1-6 2026-08-06] QA-A2 — 구독 정산 항목이 생성되지 않는다.\n--\n-- 증상: 결제가 succeeded 인데 subscription_settlement_items 가 0건이고 멘토\n--       정산 화면이 0원으로 보인다.\n--       DB 실측: active 구독 1건 · subscription_billing_events 1건(94,900원,\n--       initial/succeeded) · settlement_items **0건** · cron.job **0건**.\n--\n-- 원인: 계산 함수 public.refresh_subscription_settlement_items(p_from, p_to) 는\n--       완성돼 있으나 **호출자가 없다**. subscription_billing_events 의 트리거\n--       2개는 이름 그대로 알림 발송용(trg_sbe_notify_*)이고, pg_cron 확장은\n--       설치돼 있는데 등록된 스케줄이 0건이다.\n--\n-- 결정(오너 판단 2026-08-06): **매시간 실행**.\n--\n-- 선행 조건: S1-1(탈퇴 가드 분리, 20260806200000)이 먼저 적용돼야 한다.\n--   정산 항목이 생겨 실제 지급 단계로 넘어가면 멘토 앞 cash_ledger INSERT 가\n--   같은 가드에 다시 막힌다.\n--\n-- 재계산 창(window): 최근 45일. 구독 주기(월 단위)와 적립중(accruing) 기간을\n--   덮으면서, 전 기간을 매시간 훑지 않도록 제한한다. 함수는 멱등이라 같은 구간을\n--   반복 계산해도 결과가 누적되지 않는다.\n--\n-- ★ 로컬 재생 안전: 스크래치 PG 에는 pg_cron 이 없다. 확장 존재를 확인하고\n--   없으면 조용히 건너뛴다 — migration pack 의 fresh replay 가 깨지지 않는다.\n\ndo $do$\nbegin\n  if not exists (select 1 from pg_extension where extname = ''pg_cron'') then\n    raise notice ''S1-6: pg_cron 미설치 — 스케줄 등록을 건너뛴다(로컬 재생 환경).'';\n    return;\n  end if;\n\n  -- 같은 이름의 기존 잡이 있으면 제거(멱등 — 재적용 시 중복 등록 방지)\n  perform cron.unschedule(jobid) from cron.job\n   where jobname = ''subscription_settlement_refresh_hourly'';\n\n  perform cron.schedule(\n    ''subscription_settlement_refresh_hourly'',\n    ''0 * * * *'',\n    $job$select public.refresh_subscription_settlement_items(now() - interval ''45 days'', now());$job$\n  );\n\n  raise notice ''S1-6: subscription_settlement_refresh_hourly 등록 완료(매시 정각).'';\nend\n$do$"], "idempotency_key": null}, {"name": "deletion_storage_refs_multisource", "version": "20260806202500", "rollback": null, "created_by": null, "statements": ["-- [S1-5 2026-08-06] QA-C11 — 탈퇴 시 스토리지 파일 삭제 누락.\n--\n-- QA 는 \"주석 파일이 scan-annotations 버킷에만 있고 scan_annotations 테이블\n-- 색인이 없다\"를 원인으로 봤으나, 실측 결과 **원인도 대상도 다르다**.\n--\n-- 실제 구조: 탈퇴 워커의 수집 함수 account_deletion_storage_owner_refs 는\n--   버킷과 무관하게 storage.objects.owner_id = uid 로만 수집한다. 색인 테이블\n--   유무는 삭제 여부를 좌우하지 않고, **owner_id 기록 여부**가 좌우한다.\n--\n-- 실측(2026-08-06) owner_id NULL 객체:\n--   · individual-question-attachments  4 / 7\n--   · student-id-images                2 / 6\n--   · shortform-videos                 1 / 1\n--   · scan-annotations                 0 / 7   ← QA 가 지목한 버킷은 오히려 무혐의\n--   · question-room-attachments        0 / 17\n--   · community-post-images            0 / 3\n--\n-- 패턴: 파일명이 `<uuid>-_.ext` 인 객체만 owner_id 가 비어 있고, 앱이 올린\n--   `<epoch>-<hash>.ext` 는 전부 채워져 있다. 즉 **서버 사이드(service role)\n--   업로드 경로가 소유자를 남기지 않는다**. 근본 수정은 그 업로드 경로가\n--   업로더를 기록하게 하는 것이며 이 migration 범위 밖(웹)이다.\n--\n-- 더 나쁜 사실: individual_question_attachments 의 같은 4건은 **author_id 까지\n--   NULL** 이다. 이 4건은 DB 안에 소유자 단서가 전혀 없어 소급 구제가 불가능하다\n--   — 웹 업로드 경로 수정 후에도 기존 4건은 수동 판정이 필요하다(후속 과제).\n--\n-- 이 migration 이 하는 일: 수집을 owner_id 단일 근거에서 **3중 근거**로 넓혀,\n--   owner_id 가 비어도 소유자를 알 수 있는 객체는 탈퇴 시 함께 지워지게 한다.\n--     ① storage.objects.owner_id = uid                     (기존)\n--     ② 도메인 테이블의 author_id = uid 인 첨부의 storage_path\n--        (question_attachments · individual_question_attachments)\n--     ③ `<uid>/...` 경로 규약이 성립하는 **버킷 한정** 접두 매칭\n--        (student-id-images · shortform-videos — 실측으로 첫 세그먼트가\n--         사용자 id 임을 확인한 버킷만. IQ 첨부는 첫 세그먼트가 question_id\n--         라 이 규칙을 적용하면 남의 파일을 지울 수 있어 **제외**한다.)\n--\n-- 반환 계약(bucket_id, name)과 호출부는 그대로다. 중복은 union 으로 제거된다.\n--\n-- ★ 이 migration 만으로는 QA-C11 이 닫히지 않는다(적대적 검증 2026-08-06) ★\n--   워커는 181 로 귀속을 넓힌 직후 183(account_deletion_verify_object_owners)의\n--   verdict 를 덮어쓴다. owner_id 가 비어 있는 객체는 183 이 ''none'' 을 돌려주고,\n--   종전 TS 매핑은 그 값을 **null 로 덮어** 여기서 넓힌 귀속 근거를 지웠다.\n--   그러면 buildDeletionPlan 이 그 객체를 `unattributable` 로 분류하고, 계획이\n--   오염 판정돼 탈퇴 워커가 real-run 을 아예 시작하지 못한다(§3-4).\n--   그래서 짝이 되는 수정이 함께 들어간다:\n--     lib/account/accountDeletionPurgePlan.ts — applyOwnerVerdicts 의 ''none'' 은\n--     \"storage 소유자 기록 부재\"라는 사실일 뿐이므로 base 의 대상 귀속을 덮지 않는다.\n--   계약 테스트: lib/account/__contract__/accountDeletionOwnerRefsMapping.contract.test.ts\n--   (S1-5 3건 — 귀속 유지 · 무근거 객체의 null 유지 · ''other'' 우선 불변).\n\ncreate or replace function public.account_deletion_storage_owner_refs(p_user_id uuid)\nreturns table(bucket_id text, name text)\nlanguage sql\nstable\nsecurity definer\nset search_path to ''''\nas $function$\n  -- ① 스토리지 소유자 기록(정본)\n  select o.bucket_id, o.name\n    from storage.objects o\n   where o.owner_id = p_user_id::text\n\n  union\n\n  -- ② 질문방 첨부 — 도메인 테이블이 작성자를 안다\n  select ''question-room-attachments''::text, a.storage_path\n    from public.question_attachments a\n   where a.author_id = p_user_id\n     and a.storage_path is not null\n\n  union\n\n  -- ② 개별질문 첨부 — 동일\n  select ''individual-question-attachments''::text, a.storage_path\n    from public.individual_question_attachments a\n   where a.author_id = p_user_id\n     and a.storage_path is not null\n\n  union\n\n  -- ③ `<uid>/` 경로 규약이 성립하는 버킷 한정(실측 확인분만)\n  select o.bucket_id, o.name\n    from storage.objects o\n   where o.bucket_id in (''student-id-images'', ''shortform-videos'')\n     and o.name like p_user_id::text || ''/%''\n$function$", "comment on function public.account_deletion_storage_owner_refs(uuid) is\n  ''S1-5/QA-C11: 탈퇴 대상 사용자의 스토리지 객체를 3중 근거로 수집한다 — ''\n  ''① owner_id ② 첨부 도메인 테이블의 author_id ③ <uid>/ 경로 규약이 확인된 ''\n  ''버킷 한정 접두 매칭. 서버 사이드 업로드가 owner_id 를 남기지 않아 수집에서 ''\n  ''누락되던 객체를 덮는다. IQ 첨부는 첫 경로 세그먼트가 question_id 라 ③ 대상이 ''\n  ''아니다(타인 파일 오삭제 방지).''"], "idempotency_key": null}, {"name": "free_question_notifies_mentor", "version": "20260806203000", "rollback": null, "created_by": null, "statements": ["-- [S1-7 2026-08-06] QA-C13 — 무료질문은 멘토에게 알림이 가지 않는다.\n--\n-- 현상: qna_create_question_thread 가 새 질문 알림(question_received)을\n--       `if v_path = ''subscription''` 일 때만 기록한다. 무료질문 경로(v_path=''free'')\n--       는 제외돼 있어, 멘토가 목록을 직접 열어보지 않으면 무료질문이 방치된다.\n--       (qna_create_free_question_thread 는 이 함수에 위임만 한다)\n--\n-- 결정(오너 판단 2026-08-06): **무료질문도 멘토에게 알린다.**\n--   구독 알림 확장(C17 멘토용 구독 알림 · C18 구독 시작 알림)은 이번 배치에\n--   넣지 않고 다음 라운드로 미룬다.\n--\n-- 수정: 알림 기록을 감싸던 경로 조건(if v_path=''subscription'' … end if)만 제거한다.\n--       그 외 본문은 정본(20260805162500 as-applied)과 한 글자도 다르지 않다.\n--       문구(''새 질문이 도착했어요'' / ''학생이 새 질문을 등록했어요.'')는 두 경로\n--       모두에 정확하므로 그대로 쓴다. event_key 는 종전대로\n--       question_received:<thread_id> — 스레드당 1회 멱등이고 타입도 기존\n--       question_received 라 앱 수정이 필요 없다.\nCREATE OR REPLACE FUNCTION public.qna_create_question_thread(p_room_id uuid, p_title text, p_subject text DEFAULT NULL::text, p_topic text DEFAULT NULL::text, p_first_message_body text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid; v_status text; v_suspended_until timestamptz;\n  v_created_at timestamptz; v_total int; v_per int; v_subject text; v_thread_id uuid; v_message_id uuid;\n  v_has_active_sub boolean; v_usage json; v_path text; v_sub_id uuid;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_title is null or btrim(p_title)='''' then raise exception ''TITLE_REQUIRED''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=p_room_id;\n  if not found then raise exception ''ROOM_NOT_FOUND''; end if;\n  if v_uid <> v_student then\n    if v_uid = v_mentor then raise exception ''MENTOR_CANNOT_CREATE_THREAD''; else raise exception ''NOT_ROOM_PARTY''; end if;\n  end if;\n  perform 1 from public.users where id=v_student for update;\n  select status, suspended_until, created_at into v_status, v_suspended_until, v_created_at from public.users where id=v_student;\n  if lower(coalesce(v_status,''active''))=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if lower(coalesce(v_status,''active''))=''suspended'' and (v_suspended_until is null or v_suspended_until > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if exists (select 1 from public.user_blocks where (blocker_id=v_student and blocked_id=v_mentor) or (blocker_id=v_mentor and blocked_id=v_student)) then raise exception ''BLOCKED''; end if;\n  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  v_has_active_sub := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'');\n  if v_has_active_sub then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n    v_usage := public.get_weekly_question_usage(v_student, v_mentor);\n    if not coalesce((v_usage->>''can_ask'')::boolean, false) then raise exception ''WEEKLY_LIMIT_EXHAUSTED''; end if;\n    v_path := ''subscription'';\n  else\n    if v_created_at is not null and now() >= v_created_at + interval ''7 days'' then raise exception ''FREE_QUOTA_EXPIRED''; end if;\n    select count(*) into v_total from public.free_question_usage where student_id=v_student;\n    if v_total >= 7 then raise exception ''FREE_QUOTA_TOTAL_EXHAUSTED''; end if;\n    select count(*) into v_per from public.free_question_usage where student_id=v_student and mentor_id=v_mentor;\n    if v_per >= 3 then raise exception ''FREE_QUOTA_MENTOR_EXHAUSTED''; end if;\n    v_path := ''free'';\n  end if;\n  v_subject := nullif(btrim(coalesce(p_subject,'''')),'''');\n  if v_subject is not null and not exists (select 1 from public.subjects where code=v_subject) then v_subject := null; end if;\n  insert into public.question_threads (mentor_student_room_id, title, status, subject, topic)\n  values (p_room_id, btrim(p_title), ''pending'', v_subject, nullif(btrim(coalesce(p_topic,'''')),'''')) returning id into v_thread_id;\n  if p_first_message_body is not null and btrim(p_first_message_body) <> '''' then\n    insert into public.question_messages (thread_id, author_id, body) values (v_thread_id, v_student, btrim(p_first_message_body)) returning id into v_message_id;\n  end if;\n  if v_path=''free'' then insert into public.free_question_usage (student_id, mentor_id, thread_id) values (v_student, v_mentor, v_thread_id); end if;\n\n  -- ── 새 질문 → 방 멘토 인앱 알림(question_received) ──\n  -- 20260805 도입(구독 한정) → S1-7/QA-C13 에서 무료 경로까지 확장.\n  -- 같은 트랜잭션 안 — 위 생성이 롤백되면 알림도 롤백(원자), record_domain_notification\n  -- 이 (recipient,event_key) 멱등 + outbox 게이트를 기존 계약대로 처리한다.\n  -- S1-7/QA-C13: 무료·구독 경로 모두 알린다(종전에는 subscription 한정 조건이 있었다).\n    perform public.record_domain_notification(\n      v_mentor,\n      ''question_received:'' || v_thread_id::text,\n      ''question_received:'' || v_thread_id::text,\n      ''question_received'',\n      ''새 질문이 도착했어요'',\n      ''학생이 새 질문을 등록했어요.'',\n      ''/mentor/question-room/'' || p_room_id::text || ''?thread='' || v_thread_id::text,\n      jsonb_build_object(''room_id'', p_room_id, ''thread_id'', v_thread_id, ''student_id'', v_student),\n      jsonb_build_object(''room_id'', p_room_id, ''thread_id'', v_thread_id, ''student_id'', v_student)\n    );\n\n  return jsonb_build_object(''ok'',true,''thread_id'',v_thread_id,''message_id'',v_message_id,''path'',v_path,''used_free_quota'',(v_path=''free''));\nend;\n$function$"], "idempotency_key": null}, {"name": "iq_open_list_exposes_requirements", "version": "20260807010000", "rollback": null, "created_by": null, "statements": ["-- [S3-1 2026-08-07] QA-B6 — 공개형 대기 목록에 요구 조건이 보이지 않는다.\n--\n-- 증상: 멘토가 공개형 대기 질문을 \"조건을 못 본 채\" 수락해야 한다.\n--       과목·요구 학교·요구 계열이 화면 어디에도 없다(웹은 정상 표시).\n--\n-- 원인 분해: QA 는 앱 결함으로 봤고 실제로 앱 모델에 필드가 없는 것도 맞다.\n--   다만 그것만 고쳐도 **대기 목록은 여전히 못 본다** —\n--   list_open_individual_questions_for_mentor 의 반환 계약이\n--   (id, subject, topic, title, price_cents, expires_at, created_at) 7종이라\n--   required_school_tier·required_major_category 가 애초에 내려오지 않는다.\n--   앱은 없는 값을 그릴 수 없다. 그래서 서버·앱을 같이 고친다.\n--\n-- 노출 판단: 이 두 값은 **학생이 \"누가 답변할 수 있는지\"를 정한 조건**이다.\n--   대상 멘토에게 보여주는 것이 이 값의 존재 이유이며, 학생 개인정보가 아니다.\n--   이 RPC 의 위생 규칙(본문·학생 식별자 미노출)은 그대로다 — 두 조건 컬럼만 더한다.\n--   웹은 이미 같은 값을 멘토에게 보여주고 있다(표시 계약 일치).\n--\n-- 그 외 동작(승인 멘토 게이트 · 담당 과목 필터 · 정렬 · limit 클램프)은 불변.\n-- 반환 컬럼이 늘어나므로 create or replace 로는 바꿀 수 없다(42P13) — drop 후 재생성한다.\n-- 멱등: drop if exists.\n\ndrop function if exists public.list_open_individual_questions_for_mentor(integer)", "create function public.list_open_individual_questions_for_mentor(p_limit integer default 50)\nreturns table(\n  id uuid,\n  subject text,\n  topic text,\n  title text,\n  price_cents integer,\n  expires_at timestamp with time zone,\n  created_at timestamp with time zone,\n  required_school_tier text,\n  required_major_category text\n)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path to ''public''\nas $function$\ndeclare\n  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);\n  v_subjects text[];\nbegin\n  if not public.individual_question_user_is_approved_mentor((select auth.uid())) then\n    return;\n  end if;\n\n  -- 멘토 담당 과목(teaching_subjects)만 노출. 과목 없는(null) 질문은 일반 질문으로 모두에게 노출.\n  select mp.teaching_subjects into v_subjects\n  from public.mentor_profiles mp\n  where mp.user_id = (select auth.uid());\n\n  return query\n    select\n      q.id,\n      q.subject,\n      q.topic,\n      q.title,\n      q.price_cents,\n      q.expires_at,\n      q.created_at,\n      q.required_school_tier,\n      q.required_major_category\n    from public.individual_questions q\n    where q.question_type = ''open''\n      and q.status = ''open''\n      and q.claimed_mentor_id is null\n      and (q.expires_at is null or q.expires_at > now())\n      and (q.subject is null or q.subject = any(coalesce(v_subjects, array[]::text[])))\n    order by q.created_at desc\n    limit v_limit;\nend;\n$function$", "comment on function public.list_open_individual_questions_for_mentor(integer) is\n  ''S3-1/QA-B6: 공개형 대기 질문 목록(위생 RPC). 멘토가 수락 전에 조건을 볼 수 있도록 ''\n  ''required_school_tier·required_major_category 를 반환에 포함한다 — 학생이 정한 ''\n  ''답변 자격 조건이며 개인정보가 아니다. 본문·학생 식별자 미노출 규칙은 그대로다.''", "-- 실행 권한 재부여 — drop 으로 ACL 이 함께 사라진다.\nrevoke all on function public.list_open_individual_questions_for_mentor(integer) from public", "revoke all on function public.list_open_individual_questions_for_mentor(integer) from anon", "grant execute on function public.list_open_individual_questions_for_mentor(integer) to authenticated", "grant execute on function public.list_open_individual_questions_for_mentor(integer) to service_role"], "idempotency_key": null}, {"name": "my_blocked_users_rpc", "version": "20260807020000", "rollback": null, "created_by": null, "statements": ["-- [S5-1 2026-08-07] QA-C7 — 차단 목록에 상대가 \"사용자\"로만 표시된다.\n--\n-- 현상: 차단 관리 화면에서 누구를 차단했는지 식별할 수 없어 해제 대상을 고를 수 없다.\n--\n-- 원인: 앱은 이미 표시명 조회와 폴백을 구현해 뒀다\n--       (user_blocks_repository: users(id, nickname, full_name) 조회 → 실패 시 ''사용자'').\n--       그런데 public.users 의 SELECT 정책이 **본인 + admin** 뿐이라 타인 행이\n--       0건으로 돌아온다. 앱 결함이 아니라 서버가 표시명을 내줄 경로가 없다.\n--\n-- 결정(오너 판단 2026-08-06 → 노출 경로 2026-08-07): **내가 차단한 사람에 한해\n--   닉네임만**, **뷰가 아니라 SECURITY DEFINER RPC 로** 제공한다.\n--   · users 테이블 정책은 넓히지 않는다(이메일·상태 등 전체 행 노출 금지).\n--   · api_web_v1 의 \"정의자 뷰는 mentor_directory_v1 하나\" 계약을 건드리지 않는다 —\n--     함수는 뷰 인구조사 대상이 아니라 계약 검증 스크립트 수정이 필요 없다.\n--\n-- 노출 범위(엄격):\n--   · blocker_id = auth.uid() 인 행만 — 인자를 받지 않으므로 타인 목록을 물을 수 없다.\n--   · 반환 컬럼은 blocked_id · nickname · created_at 뿐(email·full_name·role 제외).\n--   · 세션이 없으면 빈 결과(예외 대신 조용한 빈 목록 — 목록 화면이 오류로 깨지지 않게).\n--\n-- 알려진 성질(수용): 차단→조회→해제로 임의 uuid 의 닉네임을 확인할 수 있다.\n--   차단 자체가 사용자 행위이고 닉네임은 커뮤니티 글·댓글에서 이미 보이는 값이라\n--   새 정보를 주지는 않는다. 그래도 확대되지 않도록 반환 컬럼을 닉네임으로 좁혔다.\n--\n-- 멱등: create or replace + 명시 ACL 재설정.\n\ncreate or replace function public.my_blocked_users()\nreturns table(blocked_id uuid, nickname text, created_at timestamptz)\nlanguage sql\nstable\nsecurity definer\nset search_path to ''''\nas $function$\n  select\n    b.blocked_id,\n    coalesce(nullif(btrim(u.nickname), ''''), ''사용자'') as nickname,\n    b.created_at\n  from public.user_blocks b\n  join public.users u on u.id = b.blocked_id\n  where b.blocker_id = (select auth.uid())\n    and (select auth.uid()) is not null\n  order by b.created_at desc;\n$function$", "comment on function public.my_blocked_users() is\n  ''S5-1/QA-C7: 본인이 차단한 사용자의 닉네임만 돌려준다. 인자가 없어 타인 목록을 ''\n  ''물을 수 없고, blocker_id = auth.uid() 로 스코프가 고정된다. email·full_name·role 은 ''\n  ''내보내지 않는다. users 테이블 정책은 변경하지 않았고, api_web_v1 정의자 뷰 계약도 ''\n  ''건드리지 않는다(함수는 뷰 인구조사 대상이 아니다).''", "revoke all on function public.my_blocked_users() from public", "revoke all on function public.my_blocked_users() from anon", "grant execute on function public.my_blocked_users() to authenticated"], "idempotency_key": null}, {"name": "20260808030000_iq_attachment_author_backfill", "version": "20260808075333", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260808030000_iq_attachment_author_backfill.sql (F1 backfill)\n-- =============================================================================\n-- individual_question_attachments.author_id NULL 행의 작성자 backfill.\n-- 판별 규칙(FK 단일 조인 — 파생 유일 보장):\n--   ① message 첨부:  a.message_id → individual_question_messages.author_id\n--   ② 최초 질문 첨부: a.message_id IS NULL → a.question_id → individual_questions.student_id\n-- 파생 결과가 NULL 인 행은 건드리지 않는다. 멱등(author_id IS NULL 조건).\n-- =============================================================================\n\nbegin;\n\nDO $$\nDECLARE\n  v_null_before integer;\n  v_msg_updated integer;\n  v_initial_updated integer;\n  v_null_after integer;\nBEGIN\n  IF to_regclass(''public.individual_question_attachments'') IS NULL THEN\n    RAISE EXCEPTION ''IQ_ATTACH_BACKFILL_ABORT: public.individual_question_attachments not found'';\n  END IF;\n\n  SELECT count(*) INTO v_null_before\n    FROM public.individual_question_attachments WHERE author_id IS NULL;\n\n  UPDATE public.individual_question_attachments a\n     SET author_id = m.author_id\n    FROM public.individual_question_messages m\n   WHERE a.author_id IS NULL\n     AND a.message_id IS NOT NULL\n     AND m.id = a.message_id\n     AND m.author_id IS NOT NULL;\n  GET DIAGNOSTICS v_msg_updated = ROW_COUNT;\n\n  UPDATE public.individual_question_attachments a\n     SET author_id = q.student_id\n    FROM public.individual_questions q\n   WHERE a.author_id IS NULL\n     AND a.message_id IS NULL\n     AND q.id = a.question_id\n     AND q.student_id IS NOT NULL;\n  GET DIAGNOSTICS v_initial_updated = ROW_COUNT;\n\n  SELECT count(*) INTO v_null_after\n    FROM public.individual_question_attachments WHERE author_id IS NULL;\n\n  RAISE NOTICE ''IQ_ATTACH_BACKFILL: null_before=% msg_backfilled=% initial_backfilled=% null_after=%'',\n    v_null_before, v_msg_updated, v_initial_updated, v_null_after;\nEND $$;\n\ncommit;"], "idempotency_key": null}, {"name": "20260808031000_iq_attachments_direct_write_revoke", "version": "20260808075345", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260808031000_iq_attachments_direct_write_revoke.sql (F4 hardening)\n-- =============================================================================\n-- individual_question_attachments 테이블의 anon/authenticated 직접 write 권한 회수.\n-- 유지: anon/authenticated SELECT(당사자 RLS), service_role·postgres 권한 전부.\n-- 패턴 정본: 20260730195150_revoke_mentor_plans_write.sql (REVOKE ALL + SELECT 복원).\n-- =============================================================================\n\nbegin;\n\nDO $$\nBEGIN\n  IF to_regclass(''public.individual_question_attachments'') IS NULL THEN\n    RAISE EXCEPTION ''IQA_REVOKE_ABORT: public.individual_question_attachments not found'';\n  END IF;\nEND $$;\n\nREVOKE ALL ON public.individual_question_attachments FROM anon, authenticated;\nGRANT SELECT ON public.individual_question_attachments TO anon, authenticated;\n\nDO $$\nDECLARE\n  v_bad text;\nBEGIN\n  SELECT string_agg(grantee || '':'' || privilege_type, '', '')\n    INTO v_bad\n    FROM information_schema.role_table_grants\n   WHERE table_schema = ''public''\n     AND table_name = ''individual_question_attachments''\n     AND grantee IN (''anon'', ''authenticated'')\n     AND privilege_type <> ''SELECT'';\n  IF v_bad IS NOT NULL THEN\n    RAISE EXCEPTION ''IQA_REVOKE_INCOMPLETE: %'', v_bad;\n  END IF;\n  IF (SELECT count(*)\n        FROM information_schema.role_table_grants\n       WHERE table_schema = ''public''\n         AND table_name = ''individual_question_attachments''\n         AND grantee IN (''anon'', ''authenticated'')\n         AND privilege_type = ''SELECT'') <> 2 THEN\n    RAISE EXCEPTION ''IQA_REVOKE_SELECT_LOST: anon/authenticated SELECT must remain'';\n  END IF;\nEND $$;\n\ncommit;"], "idempotency_key": null}, {"name": "20260808032000_mavp_store_url_platform_host_chk", "version": "20260808080056", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- =============================================================================\n-- 20260808032000_mavp_store_url_platform_host_chk.sql (F2 적대적 검증 후속)\n-- =============================================================================\n-- ADV-F2-3 실측: 기존 mavp_store_url_chk 는 https+스토어 호스트만 보므로\n-- android 행에 apps.apple.com URL(플랫폼 뒤바뀜)을 넣어도 통과했다.\n-- platform↔host 일치 CHECK 를 추가해 뒤바뀐 저장 자체를 거부한다.\n-- 충돌 없음: 현재 staging 두 행 모두 store_url IS NULL(제약 통과).\n-- =============================================================================\n\nbegin;\n\nDO $$\nBEGIN\n  IF to_regclass(''public.mobile_app_version_policies'') IS NULL THEN\n    RAISE EXCEPTION ''MAVP_PLATFORM_CHK_ABORT: table not found'';\n  END IF;\n  IF EXISTS (\n    SELECT 1 FROM pg_constraint\n     WHERE conrelid = ''public.mobile_app_version_policies''::regclass\n       AND conname = ''mavp_store_url_platform_chk''\n  ) THEN\n    RAISE NOTICE ''MAVP_PLATFORM_CHK: already present — skip'';\n  ELSE\n    ALTER TABLE public.mobile_app_version_policies\n      ADD CONSTRAINT mavp_store_url_platform_chk CHECK (\n        store_url IS NULL\n        OR (platform = ''android'' AND store_url LIKE ''https://play.google.com/%'')\n        OR (platform = ''ios'' AND (\n              store_url LIKE ''https://apps.apple.com/%''\n              OR store_url LIKE ''https://itunes.apple.com/%''\n        ))\n      );\n  END IF;\nEND $$;\n\ncommit;"], "idempotency_key": null}, {"name": "account_deletion_server_cancel_window_30d", "version": "20260808092007", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["create or replace function public.account_deletion_request_consented(\n  p_user_id uuid,\n  p_cancelable_minutes integer default 30,\n  p_dry_run boolean default true,\n  p_forfeit_consent boolean default false,\n  p_acknowledged_balance_cents bigint default null::bigint\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $function$\ndeclare\n  v_id uuid; v_state text; v_latest uuid; v_latest_state text;\n  v_balance bigint; v_consent_at timestamptz; v_consented bigint;\nbegin\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is not null then\n    select j.state into v_state from public.account_deletion_jobs j where j.id = v_id;\n    return jsonb_build_object(''ok'',true,''existing'',true,''job_id'',v_id,''state'',v_state);\n  end if;\n\n  select j.id, j.state into v_latest, v_latest_state\n    from public.account_deletion_jobs j\n    where j.user_id = p_user_id\n    order by j.requested_at desc, j.id desc\n    limit 1;\n  if v_latest_state = ''completed'' then\n    return jsonb_build_object(''ok'',false,''code'',''ALREADY_COMPLETED'',''job_id'',v_latest,''state'',''completed'');\n  end if;\n\n  select coalesce(w.balance_cents, 0) into v_balance\n    from public.cash_wallets w where w.user_id = p_user_id for update;\n  v_balance := coalesce(v_balance, 0);\n\n  if v_balance > 0 then\n    if not coalesce(p_forfeit_consent, false) then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_REQUIRED'',''balance_cents'',v_balance);\n    end if;\n    if p_acknowledged_balance_cents is not null and p_acknowledged_balance_cents <> v_balance then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_STALE'',\n        ''acknowledged_balance_cents'', p_acknowledged_balance_cents, ''current_balance_cents'', v_balance);\n    end if;\n    v_consent_at := now();\n    v_consented := v_balance;\n  else\n    v_consent_at := null;\n    v_consented := 0;\n  end if;\n\n  insert into public.account_deletion_jobs\n      (user_id, state, cancelable_until, dry_run, forfeit_consent_at, consented_balance_cents)\n    values (\n      p_user_id,\n      ''pending'',\n      now() + interval ''30 days'',\n      coalesce(p_dry_run,true),\n      v_consent_at,\n      v_consented\n    )\n    returning id into v_id;\n\n  return jsonb_build_object(''ok'',true,''existing'',false,''job_id'',v_id,''state'',''pending'',\n                            ''forfeit_consent_at'', v_consent_at,\n                            ''consented_balance_cents'', v_consented);\nend\n$function$;\n\ncomment on function public.account_deletion_request_consented(uuid, integer, boolean, boolean, bigint)\nis ''Account deletion request. p_cancelable_minutes is retained for backward compatibility but ignored; server policy fixes the cancellation/deletion grace window at 30 days.'';\n\nupdate public.account_deletion_jobs\n   set cancelable_until = requested_at + interval ''30 days'',\n       updated_at = now()\n where state = ''pending''\n   and (cancelable_until is null or cancelable_until < requested_at + interval ''30 days'');"], "idempotency_key": null}, {"name": "nice_auth_tokens", "version": "20260820100100", "rollback": null, "created_by": "joseph@byite.co.kr", "statements": ["-- [S-B 2026-08-20] m1 — NICE 본인인증 기관토큰 캐시 `nice_auth_tokens` + 일일 스윕.\n--\n-- 용도: NICE 표준창 연동(S-C 구현 예정)이 기관토큰(access_token/ticket/iterators)을\n--       서버에서 캐시하는 저장소. 유저 귀속 데이터가 아니므로(user FK 없음) 탈퇴 사가\n--       비대상 — 수명 관리는 아래 pg_cron 스윕이 대신한다.\n--\n-- 접근 경계: `account_deletion_jobs` 선례(151) — RLS enable + 정책 0 +\n--       anon/authenticated GRANT 0 = service_role 전용. 클라이언트 노출 금지.\n--\n-- pg_cron 스윕 `nice_auth_token_sweep_daily` (일 1회, 16:20 UTC = 01:20 KST):\n--   ① expires_at < now() - interval ''1 day'' 인 토큰 행 DELETE\n--   ② identity_verifications 의 stale pending(생성 24h 초과)을 status=''expired'' 로 UPDATE\n--   ②의 대상 테이블은 m2(20260820100200)가 만든다 — cron 잡 본문은 실행 시점에만\n--   해석되는 텍스트이고 스케줄(일 1회)상 첫 실행 전에 m2 적용이 선행되므로 안전하다.\n--   로컬 재생 스크래치 PG 에는 pg_cron 이 없으므로 확장 존재를 확인하고 없으면 건너뛴다\n--   (20260806202000 settlement 스케줄 선례와 동일 — fresh replay 가 깨지지 않는다).\n--\n-- 롤백 노트 (실행 금지 — 참고용):\n--   -- select cron.unschedule(''nice_auth_token_sweep_daily'');\n--   -- drop table if exists public.nice_auth_tokens;\n\ncreate table if not exists public.nice_auth_tokens (\n  id uuid primary key default gen_random_uuid(),\n  access_token text not null,\n  ticket text not null,\n  iterators int not null,\n  expires_at timestamptz not null,\n  created_at timestamptz not null default now()\n);\n\ncomment on table public.nice_auth_tokens is\n  ''S-B m1: NICE 본인인증 기관토큰 캐시. service_role 전용(RLS on·정책 0·클라이언트 GRANT 0). 수명은 nice_auth_token_sweep_daily 크론이 관리(탈퇴 사가 비대상 — 유저 귀속 아님).'';\n\nalter table public.nice_auth_tokens enable row level security;\nrevoke all on public.nice_auth_tokens from public, anon, authenticated;\ngrant select, insert, update, delete on public.nice_auth_tokens to service_role;\n\n-- 일일 스윕 등록 — pg_cron 이 있는 환경(라이브)에서만. 멱등(동명 잡 제거 후 재등록).\ndo $do$\nbegin\n  if not exists (select 1 from pg_extension where extname = ''pg_cron'') then\n    raise notice ''S-B m1: pg_cron 미설치 — 스윕 등록을 건너뛴다(로컬 재생 환경).'';\n    return;\n  end if;\n\n  perform cron.unschedule(jobid) from cron.job\n   where jobname = ''nice_auth_token_sweep_daily'';\n\n  perform cron.schedule(\n    ''nice_auth_token_sweep_daily'',\n    ''20 16 * * *'',\n    $job$\n      delete from public.nice_auth_tokens\n       where expires_at < now() - interval ''1 day'';\n      update public.identity_verifications\n         set status = ''expired'', updated_at = now()\n       where status = ''pending''\n         and created_at < now() - interval ''24 hours'';\n    $job$\n  );\n\n  raise notice ''S-B m1: nice_auth_token_sweep_daily 등록 완료(매일 16:20 UTC).'';\nend\n$do$;\n"], "idempotency_key": null}, {"name": "identity_verifications", "version": "20260820100200", "rollback": null, "created_by": "joseph@byite.co.kr", "statements": ["-- [S-B 2026-08-20] m2 — 본인인증 결과 `identity_verifications` + `users.identity_verified_at`.\n--\n-- 용도: NICE 표준창 본인인증(S-C 구현 예정) 요청·결과 저장. 최소수집 원칙 —\n--       raw 응답 jsonb 컬럼은 만들지 않는다.\n--\n-- 암호화 계약(앱 계층 — S-C 에서 구현, DB 는 컬럼만 제공):\n--   *_enc  = ''v1:'' + base64(iv || ciphertext || tag), AES-256-GCM (ci_enc/di_enc/mobile_no_enc)\n--   di_hash = HMAC-SHA256 hex (결정적) — 중복계정 차단 키.\n--   평문 CI/DI/전화번호 컬럼 금지(이 파일에 존재하지 않음이 계약이다).\n--\n-- 중복계정 차단: 부분 유니크 `identity_verifications_di_hash_verified_uniq`\n--   ON (di_hash) WHERE status=''verified'' AND di_hash IS NOT NULL —\n--   같은 실명인(동일 DI)의 verified 행은 시스템 전체에 1개만 허용.\n--\n-- users.identity_verified_at (nullable·무DEFAULT — B5: 부분-컬럼 INSERT 4지점 보존):\n--   users ACL 은 테이블 단위 GRANT(컬럼 attacl 전무 — C2 실측)이므로 신규 컬럼은\n--   authenticated SELECT 범위에 자동 포함된다(클라이언트에게 보인다 — 민감도 낮음, 허용 결정).\n--   UPDATE 는 여전히 불가(users 에 authenticated UPDATE GRANT 자체가 없음 — 갱신은\n--   service_role 경로 전용, IMPACT 수정 제안 #7).\n--\n-- 접근 경계: service_role 전용(RLS on·정책 0·anon/authenticated GRANT 0 — 151 선례).\n-- 탈퇴 파기: m7 `account_deletion_purge_identity_payment_artifacts` 가 전행 DELETE.\n-- adg 가드: 151 의 `account_deletion_write_guard` 패턴 그대로 — 탈퇴 진행(locked 이상)\n--   유저 앞으로 신규 인증 행 삽입을 차단한다.\n--\n-- 롤백 노트 (실행 금지 — 참고용):\n--   -- drop trigger if exists adg_identity_verifications on public.identity_verifications;\n--   -- drop trigger if exists trg_iv_set_updated on public.identity_verifications;\n--   -- drop table if exists public.identity_verifications;\n--   -- alter table public.users drop column if exists identity_verified_at;\n\ncreate table if not exists public.identity_verifications (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id) on delete cascade,\n  request_no text not null unique,\n  transaction_id text,\n  token_id uuid references public.nice_auth_tokens (id) on delete set null,\n  status text not null default ''pending''\n    check (status in (''pending'',''verified'',''failed'',''expired'')),\n  verified_name text,\n  birthdate date,\n  gender text,\n  national_info text,\n  mobile_co text,\n  ci_enc text,\n  di_enc text,\n  mobile_no_enc text,\n  di_hash text,\n  failure_code text,\n  verified_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncomment on table public.identity_verifications is\n  ''S-B m2: NICE 본인인증 요청·결과. service_role 전용. ci/di/mobile_no 는 앱 계층 AES-256-GCM(v1: 접두) 암호문만, di_hash 는 HMAC-SHA256 hex. verified 행은 di_hash 부분 유니크로 중복계정 차단. 탈퇴 시 m7 RPC 가 전행 파기.'';\n\ncreate unique index if not exists identity_verifications_di_hash_verified_uniq\n  on public.identity_verifications (di_hash)\n  where status = ''verified'' and di_hash is not null;\n\ncreate index if not exists identity_verifications_user_id_idx\n  on public.identity_verifications (user_id);\n\nalter table public.identity_verifications enable row level security;\nrevoke all on public.identity_verifications from public, anon, authenticated;\ngrant select, insert, update, delete on public.identity_verifications to service_role;\n\n-- updated_at 유지 — 정본 set_updated_at() (001) · trg_<약어>_set_updated 관례.\ndrop trigger if exists trg_iv_set_updated on public.identity_verifications;\ncreate trigger trg_iv_set_updated before update on public.identity_verifications\n  for each row execute function public.set_updated_at();\n\n-- 탈퇴 진행 유저 write 차단 — 151 adg_* 부착 패턴 그대로(TG_ARGV[0]=유저 컬럼명).\ndrop trigger if exists adg_identity_verifications on public.identity_verifications;\ncreate trigger adg_identity_verifications before insert on public.identity_verifications\n  for each row execute function public.account_deletion_write_guard(''user_id'');\n\n-- 게이트 판독 컬럼 — nullable·무DEFAULT (기존 부분-컬럼 INSERT·트리거와 무충돌).\nalter table public.users add column if not exists identity_verified_at timestamptz;\n\ncomment on column public.users.identity_verified_at is\n  ''S-B m2: 본인인증(NICE) 완료 시각. NULL = 미인증. 기록은 service_role 경로 전용(S-C).'';\n"], "idempotency_key": null}, {"name": "billing_keys", "version": "20260820100300", "rollback": null, "created_by": "joseph@byite.co.kr", "statements": ["-- [S-B 2026-08-20] m3 — 포트원 빌링키 `billing_keys` (구독 정기결제 전용).\n--\n-- 스코프: 포트원 = **구독 전용**(빌링키). Toss 캐시 생태계(충전·IQ 에스크로)와\n--   `cash-` orderId 규약은 이 테이블과 무관하다 — 건드리지 않는다.\n--\n-- 평문 저장 결정: **빌링키는 포트원 V2 API Secret 없이는 단독 사용 불가**(빌링키만으로는\n--   청구를 일으킬 수 없고, 청구 API 호출에 서버 보관 Secret 이 반드시 필요하다) →\n--   service_role 전용 테이블(RLS on·정책 0·anon/authenticated GRANT 0 — 151 선례)에\n--   평문 저장한다. 카드 정보는 마스킹값(card_masked_no)만 보관한다.\n--\n-- 활성 1키 계약: 부분 유니크 `billing_keys_user_id_active_uniq` ON (user_id)\n--   WHERE status=''active'' — 유저당 active 빌링키는 1개. 교체는 기존 키를\n--   status=''deleted''(+deleted_at) 로 내린 뒤 새 행 삽입(S-D 구현 예정).\n--\n-- 탈퇴 파기: m7 `account_deletion_purge_identity_payment_artifacts` 가 전행 DELETE\n--   (삭제 전 active 키 개수를 반환값에 포함 — S-D 에서 포트원 빌링키 해지 API 를\n--   DB 삭제 **앞에** 삽입할 것).\n-- adg 가드: 탈퇴 진행(locked 이상) 유저 앞 빌링키 발급 삽입 차단(151 패턴).\n--\n-- 롤백 노트 (실행 금지 — 참고용):\n--   -- drop trigger if exists adg_billing_keys on public.billing_keys;\n--   -- drop table if exists public.billing_keys;  -- (m4 payments.billing_key_id FK 선삭제 필요)\n\ncreate table if not exists public.billing_keys (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id),\n  billing_key text not null,\n  card_brand text,\n  card_masked_no text,\n  channel_key text,\n  status text not null default ''active''\n    check (status in (''active'',''deleted'')),\n  issued_at timestamptz,\n  deleted_at timestamptz,\n  created_at timestamptz not null default now()\n);\n\ncomment on table public.billing_keys is\n  ''S-B m3: 포트원 V2 빌링키(구독 정기결제 전용). service_role 전용 — V2 API Secret 없이는 단독 사용 불가하여 평문 저장 결정. 유저당 active 1키(부분 유니크). 탈퇴 시 m7 RPC 가 전행 파기(S-D: 해지 API 선행 예정).'';\n\ncreate unique index if not exists billing_keys_user_id_active_uniq\n  on public.billing_keys (user_id)\n  where status = ''active'';\n\ncreate index if not exists billing_keys_user_id_idx\n  on public.billing_keys (user_id);\n\nalter table public.billing_keys enable row level security;\nrevoke all on public.billing_keys from public, anon, authenticated;\ngrant select, insert, update, delete on public.billing_keys to service_role;\n\n-- 탈퇴 진행 유저 write 차단 — 151 adg_* 부착 패턴 그대로.\ndrop trigger if exists adg_billing_keys on public.billing_keys;\ncreate trigger adg_billing_keys before insert on public.billing_keys\n  for each row execute function public.account_deletion_write_guard(''user_id'');\n"], "idempotency_key": null}, {"name": "payments_refunds_pg_columns", "version": "20260820100400", "rollback": null, "created_by": "joseph@byite.co.kr", "statements": ["-- [S-B 2026-08-20] m4 — `payments` 포트원 8컬럼 + `refunds` PG 취소 2컬럼.\n--\n-- 전부 nullable·무DEFAULT (B5 확정치): 기존 부분-컬럼 INSERT 4지점\n--   (lib/subscribe/subscribeCheckoutService.ts:324-344, e2e 3곳)이 즉시 실패하지 않는다.\n--\n-- external_id ↔ pg_tx_id 매핑 규칙 (별개 도메인 — 혼용 금지):\n--   * `payments.external_id`(기존) = Toss/내부 참조 도메인. 실측 용례: 구독 intent\n--     `sub_intent_<intentKey>`, Toss 충전 paymentKey 계열. 포트원 값을 넣지 않는다.\n--   * `pg_tx_id`(신규) = 포트원 V2 트랜잭션 ID(paymentId/txId). 포트원 결제 행에서만\n--     기록하며, Toss·캐시 행에서는 항상 NULL 이다.\n--   * `pg_provider` = ''portone'' 등 PG 식별 문자열. NULL = 기존 Toss/캐시 도메인 행.\n--\n-- #4 방어 규칙 (IMPACT 수정 제안 #4 — 클라이언트 인텐트 선입력 불신):\n--   `payments_insert_intent` 정책(authenticated INSERT)은 행 술어만 검사하고 테이블 단위\n--   INSERT GRANT 라 클라이언트가 인텐트 생성 시 pg_* 컬럼을 임의 선입력할 수 있다.\n--   → **pg_* 는 서버 확정 경로가 포트원 단건조회(승인 결과) 값으로 전량 덮어쓴다.**\n--   클라이언트 인텐트가 실은 pg_* 선입력 값은 신뢰·보존하지 않는다(S-D 확정 경로 계약).\n--\n-- billing_key_id FK: m3(20260820100300) 이 먼저 적용된다 — 같은 스프린트 내\n--   테이블 생성(m3) → 컬럼 추가(m4) 순서 보장(IMPACT 수정 제안 #6).\n--\n-- refunds.pg_cancellation_id/pg_cancelled_at: 포트원 취소 연계(S-D~F 신규 표면)의\n--   기록 컬럼. 현행 환불은 DB 캐시 환급 전용이라 이번 회차에는 기록 주체가 없다(스키마만).\n--\n-- 롤백 노트 (실행 금지 — 참고용):\n--   -- alter table public.payments\n--   --   drop column if exists pg_provider, drop column if exists pg_tx_id,\n--   --   drop column if exists pg_method, drop column if exists pg_receipt_url,\n--   --   drop column if exists pg_paid_at, drop column if exists pg_fail_code,\n--   --   drop column if exists pg_fail_message, drop column if exists billing_key_id;\n--   -- alter table public.refunds\n--   --   drop column if exists pg_cancellation_id, drop column if exists pg_cancelled_at;\n\nalter table public.payments\n  add column if not exists pg_provider text,\n  add column if not exists pg_tx_id text,\n  add column if not exists pg_method text,\n  add column if not exists pg_receipt_url text,\n  add column if not exists pg_paid_at timestamptz,\n  add column if not exists pg_fail_code text,\n  add column if not exists pg_fail_message text,\n  add column if not exists billing_key_id uuid references public.billing_keys (id);\n\ncomment on column public.payments.pg_provider is\n  ''S-B m4: PG 식별자(예 portone). NULL = 기존 Toss/캐시 도메인 행.'';\ncomment on column public.payments.pg_tx_id is\n  ''S-B m4: 포트원 V2 트랜잭션 ID. external_id(Toss/내부 참조 도메인)와 별개 — 혼용 금지. 서버 확정 경로가 포트원 단건조회 값으로 전량 덮어쓴다(클라이언트 선입력 불신).'';\ncomment on column public.payments.billing_key_id is\n  ''S-B m4: 이 결제를 일으킨 빌링키(billing_keys FK). 구독 정기결제 전용.'';\n\nalter table public.refunds\n  add column if not exists pg_cancellation_id text,\n  add column if not exists pg_cancelled_at timestamptz;\n\ncomment on column public.refunds.pg_cancellation_id is\n  ''S-B m4: 포트원 취소 트랜잭션 ID(S-D~F 취소 연계 신규 표면에서 기록). NULL = DB 캐시 환급 행.'';\n"], "idempotency_key": null}, {"name": "portone_webhook_events", "version": "20260820100500", "rollback": null, "created_by": "joseph@byite.co.kr", "statements": ["-- [S-B 2026-08-20] m5 — 포트원 웹훅 수신 원장 `portone_webhook_events`.\n--\n-- 용도: 포트원 V2 웹훅(Standard Webhooks) 수신 기록 + 멱등 처리 기반.\n--   webhook_id UNIQUE 가 재전송 중복 처리를 구조적으로 차단한다(수신 라우트는 S-D 구현).\n--   processed_at/process_result 로 수신(항상 성공해야 함)과 처리(재시도 가능)를 분리한다.\n--\n-- adg 비부착 (의도적): 감사 로그 성격 — 수신 자체는 항상 성공해야 한다.\n--   탈퇴 진행 중 유저의 결제 이벤트도 **수신 기록은 남아야** 원인 추적이 가능하다.\n--   실제 자금 반영 단계(payments 등)는 기존 adg_payments 가드가 이미 막는다\n--   (ACCOUNT_DELETION_IN_PROGRESS — 웹훅 처리기가 이 예외를 다뤄야 한다, IMPACT W5-(f)).\n--   user FK 도 두지 않는다(수신 시점에 유저 귀속이 불확정일 수 있음 — payload 로 추적).\n--\n-- 접근 경계: service_role 전용(RLS on·정책 0·anon/authenticated GRANT 0 — 151 선례).\n--\n-- 롤백 노트 (실행 금지 — 참고용):\n--   -- drop table if exists public.portone_webhook_events;\n\ncreate table if not exists public.portone_webhook_events (\n  id uuid primary key default gen_random_uuid(),\n  webhook_id text not null unique,\n  event_type text,\n  portone_payment_id text,\n  payload jsonb not null,\n  received_at timestamptz not null default now(),\n  processed_at timestamptz,\n  process_result text\n);\n\ncomment on table public.portone_webhook_events is\n  ''S-B m5: 포트원 V2 웹훅 수신 원장(감사 로그 성격 — adg 비부착, 수신은 항상 성공). webhook_id UNIQUE 로 재전송 멱등. service_role 전용.'';\n\nalter table public.portone_webhook_events enable row level security;\nrevoke all on public.portone_webhook_events from public, anon, authenticated;\ngrant select, insert, update on public.portone_webhook_events to service_role;\n"], "idempotency_key": null}, {"name": "subscriptions_funding_source", "version": "20260820100600", "rollback": null, "created_by": "joseph@byite.co.kr", "statements": ["-- [S-B 2026-08-20] m6 — `subscriptions.funding_source` (cash | pg) + 기존 행 ''cash'' 백필.\n--\n-- 용도: 구독별 결제수단 관할 분리(IMPACT 차단 이슈 B2 — 갱신 이중화 방지)의 스키마 기반.\n--   기존 캐시 갱신 크론(process_subscription_renewal)과 신규 빌링키 크론(S-E)이\n--   같은 구독을 경쟁 갱신하지 않도록, 구독마다 결제수단을 하나로 못박는다.\n--   소비 분기(갱신 배치 필터·RPC 가드)는 S-C~E 후속 — 이번 회차는 컬럼만.\n--\n-- **NULL 은 ''cash'' 로 해석한다(방어적).** 백필 이후 신규 행이 funding_source 없이\n--   생기더라도(기존 INSERT 경로는 이 컬럼을 모른다) 기존 동작 = 캐시 차감 갱신이\n--   그대로 유지되어야 한다. ''pg'' 는 S-D~E 의 빌링키 경로가 명시적으로 기록할 때만.\n--\n-- 컬럼은 nullable·무DEFAULT (B5 확정치 — 부분-컬럼 INSERT 무영향).\n-- 백필 UPDATE: 기존 행 전부 ''cash'' (적용 시점 실측 2행 — 현행 구독은 전부 캐시 차감).\n--   subscriptions 의 BEFORE UPDATE 트리거 중 발화하는 것은 trg_subs_set_updated\n--   (updated_at 갱신)뿐 — trg_enforce_mentor_cap 은 UPDATE OF status·plan_tier,\n--   trg_sub_notify_expired 는 status 전이 시에만 발화한다(DB 트리거 실측).\n--   웹 정렬 컬럼은 created_at(SUBSCRIPTIONS_ORDER_COLUMN)이라 updated_at 변경 무영향.\n--\n-- 롤백 노트 (실행 금지 — 참고용):\n--   -- alter table public.subscriptions drop constraint if exists subscriptions_funding_source_check;\n--   -- alter table public.subscriptions drop column if exists funding_source;\n\nalter table public.subscriptions\n  add column if not exists funding_source text;\n\ncomment on column public.subscriptions.funding_source is\n  ''S-B m6: 구독 결제수단 관할(cash=캐시 지갑 차감, pg=포트원 빌링키). NULL 은 cash 로 해석(방어적). 갱신 크론 관할 분리(B2)의 기반 — 소비 분기는 S-C~E.'';\n\ndo $do$\nbegin\n  if not exists (\n    select 1 from pg_constraint\n    where conname = ''subscriptions_funding_source_check''\n      and conrelid = ''public.subscriptions''::regclass\n  ) then\n    alter table public.subscriptions\n      add constraint subscriptions_funding_source_check\n      check (funding_source in (''cash'',''pg''));\n  end if;\nend\n$do$;\n\n-- 기존 행 전부 ''cash'' 백필 — 현행 구독은 전부 캐시 차감 경로다(W5 실측).\nupdate public.subscriptions\n   set funding_source = ''cash''\n where funding_source is null;\n"], "idempotency_key": null}, {"name": "account_deletion_purge_identity_payment_artifacts", "version": "20260820100700", "rollback": null, "created_by": "joseph@byite.co.kr", "statements": ["-- [S-B 2026-08-20] m7 — 탈퇴 파기 RPC `account_deletion_purge_identity_payment_artifacts`.\n--\n-- 용도: 회원탈퇴 사가의 DB 파기 스텝(웹 워커 storage_purged 단계에서 호출 — 익명화 직전).\n--   현행 사가는 users/mentor_profiles 익명화 + Storage 파기뿐이라 신규 테이블\n--   identity_verifications(실명·CI/DI 암호문)·billing_keys(결제수단)의 행을 어떤 스텝도\n--   건드리지 않는다(IMPACT W1 부수 판정) — 이 RPC 가 그 공백을 메운다.\n--\n-- 동작: 해당 유저의 identity_verifications 전행 DELETE + billing_keys 전행 DELETE.\n--   삭제 전 active 빌링키 개수를 반환값에 포함한다 — S-D 이전에는 해지 클라이언트가\n--   없으므로, active 키가 미해지 상태로 파기되는 사실을 워커 로그로 남기기 위함.\n--\n-- 파기 게이트(fail-closed): `account_deletion_write_blocked(p_user_id)` = true\n--   (= 취소 불가 시점 locked 이상 진행 중 job 존재)일 때만 파기한다. 탈퇴 진행 중이\n--   아닌 유저를 향한 오호출은 NO_ACTIVE_DELETION 으로 거부 — 과삭제는 미삭제보다 나쁘다.\n--   워커 호출 지점(storage_purged 단계)은 항상 이 게이트를 통과한다.\n--\n-- 멱등: 전행 DELETE 는 재호출 시 0행 삭제로 수렴한다(워커 backoff 재시도 안전).\n-- nice_auth_tokens 는 파기 대상이 아니다 — 유저 귀속 데이터가 아니며(user FK 없음)\n--   수명은 m1 스윕이 관리한다.\n--\n-- ★ S-D TODO: 포트원 빌링키 해지 API 호출을 이 RPC 의 DB 삭제 **앞에**(워커 스텝에서)\n--   삽입할 것 — 지금은 해지 클라이언트가 없어 DB 파기만 수행한다.\n--\n-- 롤백 노트 (실행 금지 — 참고용):\n--   -- drop function if exists public.account_deletion_purge_identity_payment_artifacts(uuid);\n\ncreate or replace function public.account_deletion_purge_identity_payment_artifacts(p_user_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $function$\ndeclare\n  v_active_billing_keys bigint := 0;\n  v_iv_deleted bigint := 0;\n  v_bk_deleted bigint := 0;\nbegin\n  if p_user_id is null then\n    return jsonb_build_object(''ok'', false, ''code'', ''USER_ID_REQUIRED'');\n  end if;\n\n  -- 파기 게이트: 취소 불가 시점(locked 이상) 진행 중 탈퇴 job 이 있을 때만.\n  if not public.account_deletion_write_blocked(p_user_id) then\n    return jsonb_build_object(''ok'', false, ''code'', ''NO_ACTIVE_DELETION'');\n  end if;\n\n  select count(*) into v_active_billing_keys\n    from public.billing_keys\n   where user_id = p_user_id and status = ''active'';\n\n  delete from public.identity_verifications where user_id = p_user_id;\n  get diagnostics v_iv_deleted = row_count;\n\n  delete from public.billing_keys where user_id = p_user_id;\n  get diagnostics v_bk_deleted = row_count;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''identity_verifications_deleted'', v_iv_deleted,\n    ''billing_keys_deleted'', v_bk_deleted,\n    ''billing_keys_active_at_delete'', v_active_billing_keys\n  );\nend $function$;\n\ncomment on function public.account_deletion_purge_identity_payment_artifacts(uuid) is\n  ''S-B m7: 탈퇴 사가 DB 파기 스텝 — identity_verifications·billing_keys 전행 DELETE(멱등). write_blocked 게이트 통과 시에만. active 빌링키 개수 반환(S-D: 포트원 해지 API 를 DB 삭제 앞에 삽입 예정).'';\n\nrevoke all on function public.account_deletion_purge_identity_payment_artifacts(uuid) from public, anon, authenticated;\ngrant execute on function public.account_deletion_purge_identity_payment_artifacts(uuid) to service_role;\n"], "idempotency_key": null}, {"name": "identity_verifications_kind_guardian", "version": "20260821100100", "rollback": null, "created_by": "joseph@byite.co.kr", "statements": ["-- [S-C 2026-08-21] m8 — identity_verifications 보호자 체인·CAS 락 지원 (S-C 부록 A).\n--\n-- 라이브 실측(2026-08-21) 기준 현행 스키마(S-B m2)가 S-C 지시서를 지원하지 못하는 3점 보정:\n--   ① kind 컬럼 부재 — self(본인)/guardian(보호자) 인증 행 구분 불가.\n--      현재 0행이므로 NOT NULL DEFAULT ''self'' 추가가 안전하다.\n--   ② status CHECK 에 ''processing'' 없음 — return 핸들러의 CAS 락\n--      (pending→processing 원자 전환, NICE result 1회성·3033 재호출 방지)이\n--      첫 실행부터 23514 로 깨진다. CHECK 를 재정의한다.\n--   ③ di_hash 부분 유니크가 kind 무구분 — 보호자(guardian)는 자녀 복수 인증이\n--      가능해야 하고, 본인 가입 학부모의 self 행과도 충돌하면 안 된다.\n--      중복계정 차단은 kind=''self'' 한정으로 재정의한다.\n--\n-- user_consent_records 는 무변경 — consent_type CHECK ''minor_guardian_consent'',\n-- consent_actor CHECK ''guardian'', guardian_ref·idempotency_key UNIQUE 실재를\n-- 실측 확인(087). S-C §3 스펙이 그대로 사용한다.\n--\n-- ④ di_hash 인코딩 확정(오너 승인 2026-08-21): base64url 무패딩 HMAC-SHA256.\n--    m2(20260820100200) 헤더·테이블 코멘트의 ''HMAC-SHA256 hex'' 표기는 폐기 —\n--    m2 파일은 원장 바이트 불변이므로 정정은 이 파일의 카탈로그 코멘트로만 반영한다.\n--\n-- 구조 카운트 축(테이블·함수·정책·버킷) 불변 — CI 기대치 수정 불요.\n-- columns.json +1행(kind), contracts 스냅샷 $.migrations +1 (적용 회차 후속 절차).\n--\n-- 롤백 노트 (실행 금지 — 참고용):\n--   -- comment on column public.identity_verifications.di_hash is null;  -- (코멘트 정정 원복은 m2 문구 재기입)\n--   -- drop index if exists public.identity_verifications_di_hash_verified_uniq;\n--   -- create unique index if not exists identity_verifications_di_hash_verified_uniq\n--   --   on public.identity_verifications (di_hash)\n--   --   where status = ''verified'' and di_hash is not null;\n--   -- alter table public.identity_verifications\n--   --   drop constraint if exists identity_verifications_status_check;\n--   -- alter table public.identity_verifications\n--   --   add constraint identity_verifications_status_check\n--   --   check (status in (''pending'',''verified'',''failed'',''expired''));\n--   -- alter table public.identity_verifications drop column if exists kind;\n\n-- ① kind — self(본인) / guardian(보호자). 현재 0행 실측이라 NOT NULL 즉시 부여 안전.\nalter table public.identity_verifications\n  add column if not exists kind text not null default ''self''\n  check (kind in (''self'', ''guardian''));\n\ncomment on column public.identity_verifications.kind is\n  ''S-C m8: self=가입자 본인 인증, guardian=만 14세 미만 가입자의 법정대리인 인증. 중복계정 차단(di_hash 유니크)은 self 한정.'';\n\n-- ② status CHECK 재정의 — CAS 락 상태 ''processing'' 추가.\n--    (m2 인라인 CHECK 의 자동 이름 identity_verifications_status_check 를 교체)\nalter table public.identity_verifications\n  drop constraint if exists identity_verifications_status_check;\nalter table public.identity_verifications\n  add constraint identity_verifications_status_check\n  check (status in (''pending'', ''processing'', ''verified'', ''failed'', ''expired''));\n\n-- ③ di_hash 부분 유니크 재정의 — kind=''self'' 한정.\n--    guardian 행은 (자녀 2명 이상 → 동일 보호자 DI verified 복수 행) 허용해야 하고,\n--    본인 명의로 가입한 학부모의 self verified 행과도 충돌하면 안 된다.\ndrop index if exists public.identity_verifications_di_hash_verified_uniq;\ncreate unique index if not exists identity_verifications_di_hash_verified_uniq\n  on public.identity_verifications (di_hash)\n  where status = ''verified'' and di_hash is not null and kind = ''self'';\n\n-- ④ di_hash 인코딩 확정 코멘트 정정 — base64url 무패딩 (m2 의 hex 표기 폐기).\ncomment on column public.identity_verifications.di_hash is\n  ''S-C m8: 결정적 base64url 무패딩 HMAC-SHA256(di, IDENTITY_HASH_KEY). 중복계정 차단 키 — status=verified·kind=self 한정 부분 유니크.'';\n\ncomment on table public.identity_verifications is\n  ''S-B m2·S-C m8: NICE 본인인증 요청·결과. service_role 전용. ci/di/mobile_no 는 앱 계층 AES-256-GCM(v1: 접두) 암호문만, di_hash 는 base64url 무패딩 HMAC-SHA256. kind=self 의 verified 행은 di_hash 부분 유니크로 중복계정 차단(guardian 은 자녀 복수 인증 허용). 탈퇴 시 m7 RPC 가 전행 파기.'';\n"], "idempotency_key": null}, {"name": "device_token_register_grant", "version": "20260827100100", "rollback": null, "created_by": "joseph@byite.co.kr", "statements": ["-- ⚠️ 라이브 미적용 — 오너 \"적용 승인\"(PUSH 지시문 O-7) 후 CLAUDE.md 절차로 적용 (114 패턴).\n--   적용 후: npm run contracts:export 로 스냅샷 재수출 + contracts:verify green +\n--   인벤토리(grants) 갱신 — S-B/S-C-APPLY 선례 형식으로 docs/sprint-push/PUSH-APPLY.md 증적.\n--\n-- App-F1(푸시 재도입): 앱(authenticated)이 자기 FCM 토큰을 등록할 수 있게 EXECUTE 부여.\n-- register_device_token 은 SECURITY DEFINER + auth.uid() 강제 + on conflict(token) 소유권 이전 내장(재검토 2026-08-25).\n-- revoke_device_token 은 소유권 검사가 없고 notification_delivery_mark_failed 가 내부 호출하므로 authenticated 에 열지 않는다(앱은 RLS 본인 행 UPDATE 로 철회).\ngrant execute on function public.register_device_token(text, text) to authenticated;\n"], "idempotency_key": null}, {"name": "withholding_cash_unit_and_mentor_settlement_rpc", "version": "20260827100200", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- 원천징수 계산 단일화(캐시 단위 절사) + 지급 cutoff KST 고정 + 멘토 정산 RPC\n-- 검증된 전제: payout_runs 0건, payout_settings.scheduler_enabled=false (첫 지급 실행 전)\n\n------------------------------------------------------------------\n-- 1) 원천징수 단일 계산 함수 — 규칙 A: 3.3% 를 캐시(원) 단위에서 절사, 결과는 항상 100 cents 배수\n------------------------------------------------------------------\ncreate or replace function public.calc_withholding_cents(p_mentor_amount_cents bigint)\nreturns bigint\nlanguage sql\nimmutable\nparallel safe\nset search_path = public\nas $$\n  select (floor(floor(coalesce(p_mentor_amount_cents, 0) / 100.0) * 0.033))::bigint * 100;\n$$;\n\ncomment on function public.calc_withholding_cents(bigint) is\n  ''원천징수 3.3% — 캐시(원) 단위 절사. 지급 함수/리포트/멘토 화면이 모두 이 함수를 사용한다.'';\n\nrevoke all on function public.calc_withholding_cents(bigint) from public;\ngrant execute on function public.calc_withholding_cents(bigint) to authenticated, service_role;\n\n------------------------------------------------------------------\n-- 2) pay_due_payouts_for_run: 원천징수 식 치환 + cutoff KST 월말 고정 (본문 나머지 그대로, 기대 문자열 없으면 중단)\n------------------------------------------------------------------\ndo $$\ndeclare\n  v_def text;\n  v_needle_wh  text := ''floor(rec.mentor_amount_cents::numeric * 0.033)::bigint'';\n  v_needle_cut text := ''date_trunc(''''month'''', p_run_date::timestamp) - interval ''''1 second'''''';\nbegin\n  select pg_get_functiondef(p.oid) into v_def\n    from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''public'' and p.proname = ''pay_due_payouts_for_run'';\n  if v_def is null or position(v_needle_wh in v_def) = 0 then\n    raise exception ''pay_due_payouts_for_run: withholding line not found - abort'';\n  end if;\n  if position(v_needle_cut in v_def) = 0 then\n    raise exception ''pay_due_payouts_for_run: cutoff expr not found - abort'';\n  end if;\n  v_def := replace(v_def, v_needle_wh,  ''public.calc_withholding_cents(rec.mentor_amount_cents)'');\n  v_def := replace(v_def, v_needle_cut, ''(date_trunc(''''month'''', p_run_date::timestamp) at time zone ''''Asia/Seoul'''') - interval ''''1 second'''''');\n  execute v_def;\nend $$;\n\n------------------------------------------------------------------\n-- 3) payout_reconciliation_report: 동일 치환\n------------------------------------------------------------------\ndo $$\ndeclare\n  v_def text;\n  v_needle_wh  text := ''floor(d.mentor_amount_cents::numeric * 0.033)::bigint'';\n  v_needle_cut text := ''date_trunc(''''month'''', p_run_date::timestamp) - interval ''''1 second'''''';\nbegin\n  select pg_get_functiondef(p.oid) into v_def\n    from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''public'' and p.proname = ''payout_reconciliation_report'';\n  if v_def is null or position(v_needle_wh in v_def) = 0 then\n    raise exception ''payout_reconciliation_report: withholding expr not found - abort'';\n  end if;\n  if position(v_needle_cut in v_def) = 0 then\n    raise exception ''payout_reconciliation_report: cutoff expr not found - abort'';\n  end if;\n  v_def := replace(v_def, v_needle_wh,  ''public.calc_withholding_cents(d.mentor_amount_cents)'');\n  v_def := replace(v_def, v_needle_cut, ''(date_trunc(''''month'''', p_run_date::timestamp) at time zone ''''Asia/Seoul'''') - interval ''''1 second'''''');\n  execute v_def;\nend $$;\n\n------------------------------------------------------------------\n-- 4) 멘토용 RPC — 프론트 계산 제거. security definer + auth.uid() 고정\n------------------------------------------------------------------\ncreate or replace function public.mentor_settlement_lines(\n  p_from timestamptz default null,\n  p_to   timestamptz default null\n)\nreturns table (\n  source_type         text,\n  source_id           uuid,\n  occurred_at         timestamptz,\n  period_start        timestamptz,\n  period_end          timestamptz,\n  gross_cents         bigint,\n  platform_fee_cents  bigint,\n  mentor_amount_cents bigint,\n  fee_rate            numeric,\n  withholding_cents   bigint,\n  net_cents           bigint,\n  status              text,\n  hold_reason         text,\n  completion_ts       timestamptz,\n  expected_run_date   date,\n  paid_run_date       date,\n  paid_at             timestamptz\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  with base as (\n    select ''subscription''::text as source_type, i.id as source_id, i.mentor_id,\n           i.billing_at as occurred_at, i.period_start, i.period_end,\n           i.gross_cents, i.platform_fee_cents, i.mentor_amount_cents, i.fee_rate,\n           i.status, i.hold_reason, i.period_end as completion_ts, i.paid_at\n      from public.subscription_settlement_items i\n    union all\n    select ''custom_request'', c.id, c.mentor_id,\n           c.created_at, null::timestamptz, null::timestamptz,\n           c.gross_amount::bigint * 100, c.platform_fee_amount::bigint * 100, c.mentor_amount::bigint * 100, c.fee_rate,\n           c.status, c.reason, o.accepted_at, c.paid_at\n      from public.custom_order_settlement_items c\n      join public.custom_request_orders o on o.id = c.custom_request_order_id\n    union all\n    select ''individual_question'', q.id, coalesce(q.claimed_mentor_id, q.designated_mentor_id),\n           q.released_at, null::timestamptz, null::timestamptz,\n           q.price_cents::bigint,\n           q.price_cents::bigint - floor(q.price_cents::numeric * 0.85)::bigint,\n           floor(q.price_cents::numeric * 0.85)::bigint, 0.15::numeric,\n           case when q.release_ledger_id is not null then ''paid''\n                when q.refund_ledger_id is not null or q.status in (''refunded'',''expired'',''canceled'') then ''canceled''\n                else ''pending'' end,\n           null::text, q.released_at, null::timestamptz\n      from public.individual_questions q\n     where q.released_at is not null\n       and coalesce(q.claimed_mentor_id, q.designated_mentor_id) is not null\n  )\n  select b.source_type, b.source_id, b.occurred_at, b.period_start, b.period_end,\n         b.gross_cents, b.platform_fee_cents, b.mentor_amount_cents, b.fee_rate,\n         coalesce(pri.withholding_cents, public.calc_withholding_cents(b.mentor_amount_cents))                        as withholding_cents,\n         coalesce(pri.net_paid_cents,   b.mentor_amount_cents - public.calc_withholding_cents(b.mentor_amount_cents)) as net_cents,\n         case when pri.id is not null then ''paid'' else b.status end                                                   as status,\n         b.hold_reason,\n         b.completion_ts,\n         case when pri.id is not null or b.completion_ts is null then null\n              else (date_trunc(''month'', b.completion_ts at time zone ''Asia/Seoul'') + interval ''1 month'' + interval ''22 days'')::date\n         end                                                                                                          as expected_run_date,\n         pr.run_date                                                                                                  as paid_run_date,\n         coalesce(pri.created_at, b.paid_at)                                                                          as paid_at\n    from base b\n    left join public.payout_run_items pri\n           on pri.source_type = b.source_type and pri.source_id = b.source_id\n    left join public.payout_runs pr on pr.id = pri.payout_run_id\n   where b.mentor_id = auth.uid()\n     and (p_from is null or b.occurred_at >= p_from)\n     and (p_to   is null or b.occurred_at <  p_to)\n   order by b.occurred_at desc;\n$$;\n\ncreate or replace function public.mentor_settlement_summary(p_month date default null)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  with m as (\n    select date_trunc(''month'', coalesce(p_month, (now() at time zone ''Asia/Seoul'')::date))::date                        as m_start,\n           (date_trunc(''month'', coalesce(p_month, (now() at time zone ''Asia/Seoul'')::date)) + interval ''1 month'')::date as m_next\n  ),\n  l as (select * from public.mentor_settlement_lines(null, null)),\n  confirmed as (  -- 이번 달 확정분 = 완료시점이 이번 달 말(KST) 이전 & 미지급 & 보류/취소 아님 → 다음 달 23일 지급 대상\n    select coalesce(sum(gross_cents),0) g, coalesce(sum(platform_fee_cents),0) f,\n           coalesce(sum(mentor_amount_cents),0) a, coalesce(sum(withholding_cents),0) w,\n           coalesce(sum(net_cents),0) n, count(*) c\n      from l, m\n     where l.status not in (''paid'',''hold'',''on_hold'',''canceled'')\n       and l.completion_ts is not null\n       and l.completion_ts < (m.m_next::timestamp at time zone ''Asia/Seoul'')\n  ),\n  accruing as (\n    select coalesce(sum(mentor_amount_cents),0) a, coalesce(sum(withholding_cents),0) w,\n           coalesce(sum(net_cents),0) n, count(*) c,\n           max(completion_ts) as last_period_end, max(expected_run_date) as expected_run_date\n      from l where l.status = ''accruing''\n  ),\n  held as (\n    select coalesce(sum(mentor_amount_cents),0) a, count(*) c\n      from l where l.status in (''hold'',''on_hold'')\n  ),\n  paid as (\n    select coalesce(sum(net_cents),0) n, coalesce(sum(mentor_amount_cents),0) a, count(*) c\n      from l where l.status = ''paid''\n  ),\n  by_source_month as (  -- 카드 하단 소스별 수익: 이번 달 발생 기준\n    select l.source_type, coalesce(sum(mentor_amount_cents),0) a, count(*) c\n      from l, m\n     where l.occurred_at >= (m.m_start::timestamp at time zone ''Asia/Seoul'')\n       and l.occurred_at <  (m.m_next::timestamp  at time zone ''Asia/Seoul'')\n       and l.status <> ''canceled''\n     group by l.source_type\n  )\n  select jsonb_build_object(\n    ''month'',      to_char(m.m_start, ''YYYY-MM''),\n    ''run_date'',   (m.m_next + interval ''22 days'')::date,\n    ''confirmed'',  (select jsonb_build_object(''count'',c,''gross_cents'',g,''platform_fee_cents'',f,\n                                             ''mentor_amount_cents'',a,''withholding_cents'',w,''net_cents'',n) from confirmed),\n    ''accruing'',   (select jsonb_build_object(''count'',c,''mentor_amount_cents'',a,''withholding_cents'',w,''net_cents'',n,\n                                             ''last_period_end'',last_period_end,''expected_run_date'',expected_run_date) from accruing),\n    ''held'',       (select jsonb_build_object(''count'',c,''mentor_amount_cents'',a) from held),\n    ''paid_total'', (select jsonb_build_object(''count'',c,''mentor_amount_cents'',a,''net_cents'',n) from paid),\n    ''by_source_this_month'',\n                  (select coalesce(jsonb_object_agg(source_type, jsonb_build_object(''mentor_amount_cents'',a,''count'',c)), ''{}''::jsonb)\n                     from by_source_month),\n    ''withholding_rule'', ''calc_withholding_cents''\n  )\n  from m;\n$$;\n\nrevoke all on function public.mentor_settlement_lines(timestamptz, timestamptz) from public;\nrevoke all on function public.mentor_settlement_summary(date)                   from public;\ngrant execute on function public.mentor_settlement_lines(timestamptz, timestamptz) to authenticated;\ngrant execute on function public.mentor_settlement_summary(date)                   to authenticated;\n\n------------------------------------------------------------------\n-- 5) 검증 (실패 시 전체 롤백)\n------------------------------------------------------------------\ndo $$\ndeclare v_cnt int;\nbegin\n  if public.calc_withholding_cents(14866500) <> 490500 then\n    raise exception ''calc_withholding_cents check failed: %'', public.calc_withholding_cents(14866500);\n  end if;\n  if public.calc_withholding_cents(0) <> 0 or public.calc_withholding_cents(null) <> 0 then\n    raise exception ''calc_withholding_cents zero/null check failed'';\n  end if;\n  select count(*) into v_cnt\n    from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''public''\n     and p.proname in (''pay_due_payouts_for_run'',''payout_reconciliation_report'')\n     and p.prosrc like ''%calc_withholding_cents%''\n     and p.prosrc like ''%at time zone ''''Asia/Seoul''''%''\n     and p.prosrc not like ''%0.033%'';\n  if v_cnt <> 2 then\n    raise exception ''withholding/cutoff patch verification failed (matched % of 2)'', v_cnt;\n  end if;\nend $$;"], "idempotency_key": null}, {"name": "mentor_settlement_rpc_v2_due_payouts_parity", "version": "20260827100300", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- 멘토 정산 RPC v2 — 지급 함수 모집단(due_payouts)과 동기화. 지급 함수/원천징수 함수 변경 없음.\n--  · 맞춤의뢰: on_hold 는 지급 대상(=pending), 활성 분쟁은 hold(active_dispute), 미수락(accepted_at null)은 accruing,\n--    cancelled/canceled 철자 및 주문 환불·취소는 canceled 로 통일\n--  · 구독: period_end 경과 후 cron 반영 전(accruing 잔존)도 due_payouts 기준으로 pending 처리\n--  · summary.confirmed 는 due_payouts ∩ completion_ts ≤ cutoff ∩ 미지급 + 해당 월 run 에서 지급된 건\n--  · summary 에 payout_account_registered / cutoff 추가 (계좌 미등록 시 run 이 skip → 이월 안내용)\n\ncreate or replace function public.mentor_settlement_lines(\n  p_from timestamptz default null,\n  p_to   timestamptz default null\n)\nreturns table (\n  source_type         text,\n  source_id           uuid,\n  occurred_at         timestamptz,\n  period_start        timestamptz,\n  period_end          timestamptz,\n  gross_cents         bigint,\n  platform_fee_cents  bigint,\n  mentor_amount_cents bigint,\n  fee_rate            numeric,\n  withholding_cents   bigint,\n  net_cents           bigint,\n  status              text,\n  hold_reason         text,\n  completion_ts       timestamptz,\n  expected_run_date   date,\n  paid_run_date       date,\n  paid_at             timestamptz\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  with base as (\n    select ''subscription''::text as source_type, i.id as source_id, i.mentor_id,\n           i.billing_at as occurred_at, i.period_start, i.period_end,\n           i.gross_cents, i.platform_fee_cents, i.mentor_amount_cents, i.fee_rate,\n           i.status as raw_status, i.hold_reason as raw_hold_reason,\n           i.period_end as completion_ts, i.paid_at,\n           false as active_dispute, false as order_dead\n      from public.subscription_settlement_items i\n    union all\n    select ''custom_request'', c.id, c.mentor_id,\n           c.created_at, null::timestamptz, null::timestamptz,\n           c.gross_amount::bigint * 100, c.platform_fee_amount::bigint * 100, c.mentor_amount::bigint * 100, c.fee_rate,\n           c.status, c.reason,\n           o.accepted_at, c.paid_at,\n           exists (select 1 from public.disputes d\n                    where d.custom_request_order_id = o.id\n                      and d.status in (''open'',''under_review'',''escalated'')),\n           (coalesce(lower(trim(o.payment_status)), '''') = ''refunded''\n            or coalesce(lower(trim(o.status)), '''') in (''cancelled'',''canceled'',''refunded''))\n      from public.custom_order_settlement_items c\n      join public.custom_request_orders o on o.id = c.custom_request_order_id\n    union all\n    select ''individual_question'', q.id, coalesce(q.claimed_mentor_id, q.designated_mentor_id),\n           q.released_at, null::timestamptz, null::timestamptz,\n           q.price_cents::bigint,\n           q.price_cents::bigint - floor(q.price_cents::numeric * 0.85)::bigint,\n           floor(q.price_cents::numeric * 0.85)::bigint, 0.15::numeric,\n           case when q.release_ledger_id is not null then ''paid'' else coalesce(q.status, '''') end, null::text,\n           q.released_at, null::timestamptz,\n           false, false\n      from public.individual_questions q\n     where q.released_at is not null\n       and coalesce(q.claimed_mentor_id, q.designated_mentor_id) is not null\n  ),\n  norm as (\n    select b.*,\n           pri.id as pri_id, pri.withholding_cents as pri_wh, pri.net_paid_cents as pri_net,\n           pri.created_at as pri_created_at, pr.run_date as pri_run_date,\n           case\n             when pri.id is not null or b.raw_status = ''paid'' then ''paid''\n             when exists (select 1 from public.due_payouts d\n                           where d.source_type = b.source_type and d.source_id = b.source_id) then ''pending''\n             when b.source_type = ''subscription'' then\n               case when b.raw_status = ''accruing'' then ''accruing''\n                    when b.raw_status = ''hold''     then ''hold''\n                    when b.raw_status = ''pending''  then ''pending''\n                    else ''canceled'' end\n             when b.source_type = ''custom_request'' then\n               case when b.raw_status not in (''pending'',''on_hold'',''payable'') then ''canceled''\n                    when b.order_dead then ''canceled''\n                    when b.active_dispute then ''hold''\n                    when b.completion_ts is null then ''accruing''\n                    else ''pending'' end\n             else ''canceled''\n           end as status,\n           case when b.source_type = ''custom_request'' and b.active_dispute then ''active_dispute''\n                else b.raw_hold_reason end as hold_reason\n      from base b\n      left join public.payout_run_items pri\n             on pri.source_type = b.source_type and pri.source_id = b.source_id\n      left join public.payout_runs pr on pr.id = pri.payout_run_id\n     where b.mentor_id = auth.uid()\n  )\n  select n.source_type, n.source_id, n.occurred_at, n.period_start, n.period_end,\n         n.gross_cents, n.platform_fee_cents, n.mentor_amount_cents, n.fee_rate,\n         coalesce(n.pri_wh,  public.calc_withholding_cents(n.mentor_amount_cents))                        as withholding_cents,\n         coalesce(n.pri_net, n.mentor_amount_cents - public.calc_withholding_cents(n.mentor_amount_cents)) as net_cents,\n         n.status,\n         n.hold_reason,\n         n.completion_ts,\n         case when n.status in (''paid'',''canceled'',''hold'') or n.completion_ts is null then null\n              else (date_trunc(''month'', n.completion_ts at time zone ''Asia/Seoul'') + interval ''1 month'' + interval ''22 days'')::date\n         end as expected_run_date,\n         n.pri_run_date as paid_run_date,\n         coalesce(n.pri_created_at, n.paid_at) as paid_at\n    from norm n\n   where (p_from is null or n.occurred_at >= p_from)\n     and (p_to   is null or n.occurred_at <  p_to)\n   order by n.occurred_at desc;\n$$;\n\ncreate or replace function public.mentor_settlement_summary(p_month date default null)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  with m as (\n    select date_trunc(''month'', coalesce(p_month, (now() at time zone ''Asia/Seoul'')::date))::date                        as m_start,\n           (date_trunc(''month'', coalesce(p_month, (now() at time zone ''Asia/Seoul'')::date)) + interval ''1 month'')::date as m_next\n  ),\n  cut as (  -- pay_due_payouts_for_run 과 동일한 cutoff: 다음 달 1일 00:00 KST − 1초, run_date = 다음 달 23일\n    select ((m.m_next::timestamp) at time zone ''Asia/Seoul'') - interval ''1 second'' as ts,\n           (m.m_next + interval ''22 days'')::date as run_date\n      from m\n  ),\n  l as (select * from public.mentor_settlement_lines(null, null)),\n  confirmed_rows as (\n    -- (a) 지급 함수 모집단 그대로: due_payouts ∩ completion_ts ≤ cutoff ∩ 미지급\n    select d.gross_cents, d.platform_fee_cents, d.mentor_amount_cents,\n           public.calc_withholding_cents(d.mentor_amount_cents) as withholding_cents,\n           d.mentor_amount_cents - public.calc_withholding_cents(d.mentor_amount_cents) as net_cents\n      from public.due_payouts d, cut\n     where d.mentor_id = auth.uid()\n       and d.completion_ts <= cut.ts\n       and not exists (select 1 from public.payout_run_items i\n                        where i.source_type = d.source_type and i.source_id = d.source_id)\n    union all\n    -- (b) 해당 월 run 에서 이미 지급된 건 (과거 월 조회 시 카드가 비지 않도록)\n    select i.gross_cents, i.platform_fee_cents, i.mentor_amount_cents, i.withholding_cents, i.net_paid_cents\n      from public.payout_run_items i\n      join public.payout_runs r on r.id = i.payout_run_id, cut\n     where i.mentor_id = auth.uid()\n       and r.run_date = cut.run_date\n  ),\n  confirmed as (\n    select coalesce(sum(gross_cents),0) g, coalesce(sum(platform_fee_cents),0) f,\n           coalesce(sum(mentor_amount_cents),0) a, coalesce(sum(withholding_cents),0) w,\n           coalesce(sum(net_cents),0) n, count(*) c\n      from confirmed_rows\n  ),\n  accruing as (\n    select coalesce(sum(mentor_amount_cents),0) a, coalesce(sum(withholding_cents),0) w,\n           coalesce(sum(net_cents),0) n, count(*) c,\n           max(completion_ts) as last_period_end, max(expected_run_date) as expected_run_date\n      from l where l.status = ''accruing''\n  ),\n  held as (\n    select coalesce(sum(mentor_amount_cents),0) a, count(*) c\n      from l where l.status = ''hold''\n  ),\n  paid as (\n    select coalesce(sum(net_cents),0) n, coalesce(sum(mentor_amount_cents),0) a, count(*) c\n      from l where l.status = ''paid''\n  ),\n  by_source_month as (  -- 카드 하단 소스별 수익: 이번 달 발생 기준, 취소 제외\n    select l.source_type, coalesce(sum(mentor_amount_cents),0) a, count(*) c\n      from l, m\n     where l.occurred_at >= (m.m_start::timestamp at time zone ''Asia/Seoul'')\n       and l.occurred_at <  (m.m_next::timestamp  at time zone ''Asia/Seoul'')\n       and l.status <> ''canceled''\n     group by l.source_type\n  ),\n  acct as (\n    select coalesce(nullif(trim(mp.payout_account_number), ''''), '''') <> '''' as registered\n      from public.mentor_profiles mp\n     where mp.user_id = auth.uid()\n  )\n  select jsonb_build_object(\n    ''month'',      to_char(m.m_start, ''YYYY-MM''),\n    ''run_date'',   cut.run_date,\n    ''cutoff'',     cut.ts,\n    ''payout_account_registered'', coalesce((select registered from acct), false),\n    ''confirmed'',  (select jsonb_build_object(''count'',c,''gross_cents'',g,''platform_fee_cents'',f,\n                                             ''mentor_amount_cents'',a,''withholding_cents'',w,''net_cents'',n) from confirmed),\n    ''accruing'',   (select jsonb_build_object(''count'',c,''mentor_amount_cents'',a,''withholding_cents'',w,''net_cents'',n,\n                                             ''last_period_end'',last_period_end,''expected_run_date'',expected_run_date) from accruing),\n    ''held'',       (select jsonb_build_object(''count'',c,''mentor_amount_cents'',a) from held),\n    ''paid_total'', (select jsonb_build_object(''count'',c,''mentor_amount_cents'',a,''net_cents'',n) from paid),\n    ''by_source_this_month'',\n                  (select coalesce(jsonb_object_agg(source_type, jsonb_build_object(''mentor_amount_cents'',a,''count'',c)), ''{}''::jsonb)\n                     from by_source_month),\n    ''withholding_rule'', ''calc_withholding_cents''\n  )\n  from m, cut;\n$$;\n\nrevoke all on function public.mentor_settlement_lines(timestamptz, timestamptz) from public;\nrevoke all on function public.mentor_settlement_summary(date)                   from public;\ngrant execute on function public.mentor_settlement_lines(timestamptz, timestamptz) to authenticated;\ngrant execute on function public.mentor_settlement_summary(date)                   to authenticated;\n\n-- 검증 (구조만, 데이터 무의존 — CI 재생에서도 통과해야 함)\ndo $$\nbegin\n  if (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n       where n.nspname = ''public'' and p.proname = ''mentor_settlement_lines''\n         and p.prosrc like ''%due_payouts%'' and p.prosrc like ''%active_dispute%'') <> 1 then\n    raise exception ''mentor_settlement_lines v2 verification failed'';\n  end if;\n  if (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n       where n.nspname = ''public'' and p.proname = ''mentor_settlement_summary''\n         and p.prosrc like ''%payout_account_registered%'' and p.prosrc like ''%confirmed_rows%'') <> 1 then\n    raise exception ''mentor_settlement_summary v2 verification failed'';\n  end if;\n  if has_function_privilege(''anon'', ''public.mentor_settlement_summary(date)'', ''execute'')\n     or not has_function_privilege(''authenticated'', ''public.mentor_settlement_summary(date)'', ''execute'') then\n    raise exception ''grant verification failed'';\n  end if;\nend $$;"], "idempotency_key": null}, {"name": "tz_fix_subscription_month_kst", "version": "20260829100100", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 185_tz_fix_subscription_month_kst.sql  (TZ-FIX R1 — 감사 보고서 버그표 #1)\n--\n-- Purpose: 구독 결제·갱신의 +1개월 기간 산출을 UTC(세션 달력)에서 KST 달력으로 교정.\n--   `timestamptz + interval ''1 month''` 는 세션 TZ(UTC) 달력으로 계산되어\n--   KST 00~09시 결제 구독의 이용기간이 같은 날 09시 이후 결제보다 최대 3일 짧다\n--   (2026-03-01 02:00 KST 결제 = 28일 / 09:00 결제 = 31일).\n--\n-- Base: 라이브(lbeqxarxothkmzqvpudy) pg_get_functiondef 원문 2026-08-29 추출.\n--   confirm_subscription_checkout  def md5 1c378160aec0e4d0a321da340e246b65 (8,468 bytes)\n--   process_subscription_renewal   def md5 ff4fb7f274d10a55be66ad3c554eb3d9 (7,293 bytes)\n--   (라이브는 저장소 131·143·145·068·100 보다 최신 패치 상태 — 저장소 구본을 베이스로 쓰지 않았다.\n--    라이브 본문은 supabase/baseline/interleaves/20260804100002_as_applied_function_bodies.sql\n--    의 두 함수 본문과 바이트 단위 일치를 확인했다.)\n--\n-- Fix (월 산술 식만 치환 — 그 외 라인은 라이브 원문 바이트 그대로):\n--   confirm_subscription_checkout  4곳:\n--     now()+interval ''1 month''\n--       -> ((now() at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul'')\n--   process_subscription_renewal   2곳:\n--     v_period_start + interval ''1 month''\n--       -> ((v_period_start at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul'')\n--   변경 없음: PAYMENT_STALE 30분·grace 2일(순수 상대 간격) · 함수 시그니처 · 반환 스키마 ·\n--   멱등 키 · 돈 흐름 로직.\n--\n-- 동시 배포 제약(감사 §6 R1): 체크아웃·갱신 2본은 반드시 같은 파일·같은 적용 단위.\n--   한쪽만 고치면 최초 기간은 KST / 갱신 체이닝은 UTC 로 갈린다.\n--\n-- Apply: 저장소 표준 경로(db-apply-pending) — MCP apply_migration 직접 적용 금지.\n--   TS 폴백(lib/subscribe/subscriptionsTable.ts addMonthsClampedKst)과 같은 배포로 나간다.\n--\n-- Rollback: 위 Base md5 의 라이브 원문(create or replace) 재적용으로 원복.\n-- =============================================================================\n\nCREATE OR REPLACE FUNCTION public.confirm_subscription_checkout(p_payment_id uuid, p_plan_id uuid, p_idempotency_key text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_student uuid; v_mentor uuid; v_pay_status text; v_created_at timestamptz; v_kind text;\n  v_plan_mentor uuid; v_plan_tier text; v_plan_active boolean; v_amount_cents int;\n  v_is_open boolean; v_sub_id uuid; v_reactivated boolean := false;\n  v_status text; v_suspended_until timestamptz;\n  v_l_user uuid; v_l_delta bigint; v_l_reason text; v_l_reftype text; v_l_refid uuid;\n  v_succeeded_aliases text[] := array[''succeeded'',''paid'',''success'',''complete'',''captured''];\n  v_anom uuid; v_err text; v_errcode text;\nbegin\n  select user_id, mentor_id, status, created_at, kind into v_student, v_mentor, v_pay_status, v_created_at, v_kind\n    from public.payments where id = p_payment_id for update;\n  if not found then raise exception ''PAYMENT_NOT_FOUND''; end if;\n  if v_student is null then raise exception ''PAYMENT_NO_USER''; end if;\n  if v_mentor is null then raise exception ''PAYMENT_NO_MENTOR''; end if;\n  if lower(coalesce(v_kind,'''')) in (''cash_topup'',''topup'',''cash'',''individual_question'',''iq'',''custom_order'',''custom_request'',''deliverable'') then raise exception ''PAYMENT_KIND_INVALID''; end if;\n  perform pg_advisory_xact_lock(hashtext(v_student::text), hashtext(v_mentor::text));\n  select mentor_id, plan_tier, is_active, amount_cents into v_plan_mentor, v_plan_tier, v_plan_active, v_amount_cents\n    from public.mentor_plans where id = p_plan_id for update;\n  if not found then raise exception ''PLAN_NOT_FOUND''; end if;\n  if v_plan_mentor <> v_mentor then raise exception ''PLAN_MENTOR_MISMATCH''; end if;\n  if v_amount_cents is null or v_amount_cents <= 0 then raise exception ''PLAN_AMOUNT_INVALID''; end if;\n  if v_pay_status = any(v_succeeded_aliases) then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor;\n    if v_sub_id is null then\n      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n        values (p_payment_id, null, ''SUCCEEDED_NO_SUBSCRIPTION'', ''succeeded payment without subscription'') returning id into v_anom;\n      return jsonb_build_object(''ok'',false,''code'',''SUCCEEDED_NO_SUBSCRIPTION'',''anomaly_id'',v_anom);\n    end if;\n    select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid\n      from public.cash_ledger where idempotency_key = ''sub_debit_'' || p_payment_id::text;\n    if v_l_user is null then\n      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n        values (p_payment_id, v_sub_id, ''SUCCEEDED_NO_LEDGER'', ''succeeded payment without ledger debit'') returning id into v_anom;\n      return jsonb_build_object(''ok'',false,''code'',''SUCCEEDED_NO_LEDGER'',''anomaly_id'',v_anom);\n    end if;\n    if v_l_user <> v_student or v_l_refid is distinct from v_sub_id or coalesce(v_l_reftype,'''') <> ''subscriptions''\n       or coalesce(v_l_reason,'''') <> ''subscription_payment'' or v_l_delta <> -v_amount_cents then\n      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)\n        values (p_payment_id, v_sub_id, ''LEDGER_FIELD_MISMATCH'', ''idempotent re-check field mismatch'',\n          jsonb_build_object(''user_id'',v_student,''ref_id'',v_sub_id,''ref_type'',''subscriptions'',''reason'',''subscription_payment'',''delta_cents'',-v_amount_cents),\n          jsonb_build_object(''user_id'',v_l_user,''ref_id'',v_l_refid,''ref_type'',v_l_reftype,''reason'',v_l_reason,''delta_cents'',v_l_delta))\n        returning id into v_anom;\n      return jsonb_build_object(''ok'',false,''code'',''LEDGER_FIELD_MISMATCH'',''anomaly_id'',v_anom);\n    end if;\n    return jsonb_build_object(''ok'',true,''idempotent'',true,''subscription_id'',v_sub_id,''payment_status'',''succeeded'');\n  end if;\n  if v_pay_status = ''processing'' then raise exception ''PAYMENT_PROCESSING''; end if;\n  if v_pay_status in (''failed'',''canceled'',''refunded'') then raise exception ''PAYMENT_NOT_PENDING''; end if;\n  if v_pay_status <> ''pending'' then raise exception ''PAYMENT_STATE_UNEXPECTED''; end if;\n  if v_created_at is null or now() > v_created_at + interval ''30 minutes'' then raise exception ''PAYMENT_STALE''; end if;\n  select status, suspended_until into v_status, v_suspended_until from public.users where id = v_student for update;\n  if lower(coalesce(v_status,''active'')) = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if lower(coalesce(v_status,''active'')) = ''suspended'' and (v_suspended_until is null or v_suspended_until > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  perform 1 from public.mentor_profiles where user_id = v_mentor for update;\n  select is_open_for_subscriptions into v_is_open from public.mentor_profiles where user_id = v_mentor;\n  if not coalesce(v_is_open, true) then raise exception ''MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS''; end if;\n  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  if not coalesce(v_plan_active, true) then raise exception ''PLAN_INACTIVE''; end if;\n  if not exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'') then\n    if public.mentor_cap_used(v_mentor) + public.subscription_cap_weight(v_plan_tier) > public.mentor_cap_limit(v_mentor) then raise exception ''MENTOR_CAP_EXCEEDED''; end if;\n  end if;\n  v_reactivated := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor);\n  begin\n    insert into public.subscriptions (student_id, mentor_id, plan_id, plan_tier, status, payment_id,\n      started_at, current_period_start, current_period_end, next_billing_at, billing_cycle, cancel_at_period_end, last_payment_id)\n    values (v_student, v_mentor, p_plan_id, v_plan_tier, ''active'', p_payment_id,\n      now(), now(), ((now() at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul''), ((now() at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul''), ''monthly'', false, p_payment_id)\n    on conflict (student_id, mentor_id) do update set\n      plan_id=excluded.plan_id, plan_tier=excluded.plan_tier, status=''active'', payment_id=excluded.payment_id,\n      last_payment_id=excluded.last_payment_id, started_at=coalesce(public.subscriptions.started_at, now()),\n      current_period_start=now(), current_period_end=((now() at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul''), next_billing_at=((now() at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul''),\n      cancel_at_period_end=false, cancel_requested_at=null, canceled_at=null, expired_at=null, grace_until=null,\n      last_renewed_at=now(), updated_at=now()\n    returning id into v_sub_id;\n    select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid\n      from public.cash_ledger where idempotency_key = ''sub_debit_'' || p_payment_id::text;\n    if v_l_user is not null and (v_l_user <> v_student or v_l_refid is distinct from v_sub_id\n       or coalesce(v_l_reftype,'''') <> ''subscriptions'' or coalesce(v_l_reason,'''') <> ''subscription_payment'' or v_l_delta <> -v_amount_cents) then\n      raise exception ''LEDGER_FIELD_MISMATCH'';\n    end if;\n    perform public.record_subscription_cash_debit(v_student, v_sub_id, p_payment_id, v_amount_cents::bigint);\n    update public.payments set status=''succeeded'', plan_id=p_plan_id,\n      metadata=coalesce(metadata,''{}''::jsonb) || jsonb_build_object(''planId'',p_plan_id::text,''subscription_id'',v_sub_id::text),\n      updated_at=now() where id=p_payment_id;\n  exception when others then\n    get stacked diagnostics v_errcode = returned_sqlstate;\n    v_err := sqlerrm;\n  end;\n  if v_err is not null then\n    if v_err like ''%CASH_INSUFFICIENT%'' then return jsonb_build_object(''ok'',false,''code'',''CASH_INSUFFICIENT''); end if;\n    insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      values (p_payment_id, v_sub_id, case when v_err like ''%LEDGER_FIELD_MISMATCH%'' then ''LEDGER_FIELD_MISMATCH'' else ''FINANCIAL_WRITE_ERROR'' end, left(v_err,500)) returning id into v_anom;\n    return jsonb_build_object(''ok'',false,''code'', case when v_err like ''%LEDGER_FIELD_MISMATCH%'' then ''LEDGER_FIELD_MISMATCH'' else ''FINANCIAL_WRITE_ERROR'' end, ''sqlstate'',v_errcode,''anomaly_id'',v_anom);\n  end if;\n  return jsonb_build_object(''ok'',true,''subscription_id'',v_sub_id,''payment_status'',''succeeded'',''amount_cents'',v_amount_cents,''reactivated'',v_reactivated);\nend; $function$", "-- ---------------------------------------------------------------------------\n-- process_subscription_renewal: v_period_start + 1 month (KST) 2곳 치환\n-- ---------------------------------------------------------------------------\n\nCREATE OR REPLACE FUNCTION public.process_subscription_renewal(p_subscription_id uuid, p_period_end timestamp with time zone, p_amount_cents bigint, p_idempotency_key text, p_processed_at timestamp with time zone DEFAULT now())\n RETURNS TABLE(ok boolean, code text, message text, billing_event_id uuid, ledger_id uuid, next_period_start timestamp with time zone, next_period_end timestamp with time zone, wallet_balance_cents bigint, attempt_count integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\r\ndeclare\r\n  v_sub public.subscriptions%rowtype;\r\n  v_event public.subscription_billing_events%rowtype;\r\n  v_event_id uuid;\r\n  v_ledger_id uuid;\r\n  v_wallet_balance bigint;\r\n  v_period_start timestamptz;\r\n  v_period_end timestamptz;\r\n  v_attempt_count int;\r\nbegin\r\n  if p_subscription_id is null then\r\n    return query select false, ''invalid_subscription''::text, ''subscription_id is required''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\r\n    return;\r\n  end if;\r\n\r\n  if p_amount_cents is null or p_amount_cents <= 0 then\r\n    return query select false, ''invalid_amount''::text, ''p_amount_cents must be positive''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\r\n    return;\r\n  end if;\r\n\r\n  if p_idempotency_key is null or length(trim(p_idempotency_key)) = 0 then\r\n    return query select false, ''invalid_idempotency_key''::text, ''idempotency_key is required''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\r\n    return;\r\n  end if;\r\n\r\n  select *\r\n    into v_sub\r\n  from public.subscriptions\r\n  where id = p_subscription_id\r\n  for update;\r\n\r\n  if not found then\r\n    return query select false, ''not_found''::text, ''subscription not found''::text, null::uuid, null::uuid, null::timestamptz, null::timestamptz, null::bigint, 0::int;\r\n    return;\r\n  end if;\r\n\r\n  if coalesce(v_sub.status, '''') not in (''active'', ''past_due'') then\r\n    return query select false, ''not_renewable_status''::text, ''subscription status is not renewable''::text, null::uuid, null::uuid, v_sub.current_period_start, v_sub.current_period_end, null::bigint, 0::int;\r\n    return;\r\n  end if;\r\n\r\n  select *\r\n    into v_event\r\n  from public.subscription_billing_events\r\n  where idempotency_key = p_idempotency_key\r\n  for update;\r\n\r\n  if found then\r\n    if v_event.status = ''succeeded'' then\r\n      return query select true, ''already_succeeded''::text, ''renewal already processed''::text, v_event.id, v_event.ledger_id, v_event.period_start, v_event.period_end, null::bigint, coalesce(v_event.attempt_count, 0);\r\n      return;\r\n    end if;\r\n\r\n    if v_event.status in (''pending'', ''processing'') then\r\n      return query select false, ''already_processing''::text, ''renewal is already processing''::text, v_event.id, v_event.ledger_id, v_event.period_start, v_event.period_end, null::bigint, coalesce(v_event.attempt_count, 0);\r\n      return;\r\n    end if;\r\n\r\n    update public.subscription_billing_events as e\r\n    set\r\n      event_type = ''renewal'',\r\n      status = ''processing'',\r\n      failure_code = null,\r\n      failure_message = null,\r\n      amount_cents = p_amount_cents::int,\r\n      billing_at = p_processed_at,\r\n      attempt_count = coalesce(attempt_count, 0) + 1,\r\n      processed_at = null\r\n    where e.id = v_event.id\r\n    returning e.* into v_event;\r\n\r\n    v_event_id := v_event.id;\r\n    v_attempt_count := coalesce(v_event.attempt_count, 1);\r\n  else\r\n    v_period_start := coalesce(v_sub.current_period_end, p_period_end, p_processed_at);\r\n    v_period_end := ((v_period_start at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul'');\r\n\r\n    insert into public.subscription_billing_events (\r\n      subscription_id,\r\n      student_id,\r\n      mentor_id,\r\n      event_type,\r\n      status,\r\n      period_start,\r\n      period_end,\r\n      billing_at,\r\n      amount_cents,\r\n      plan_tier,\r\n      plan_id,\r\n      idempotency_key,\r\n      attempt_count,\r\n      created_at\r\n    )\r\n    values (\r\n      v_sub.id,\r\n      v_sub.student_id,\r\n      v_sub.mentor_id,\r\n      ''renewal'',\r\n      ''processing'',\r\n      v_period_start,\r\n      v_period_end,\r\n      p_processed_at,\r\n      p_amount_cents::int,\r\n      v_sub.plan_tier,\r\n      v_sub.plan_id,\r\n      p_idempotency_key,\r\n      1,\r\n      p_processed_at\r\n    )\r\n    returning * into v_event;\r\n\r\n    v_event_id := v_event.id;\r\n    v_attempt_count := 1;\r\n  end if;\r\n\r\n  insert into public.cash_wallets (user_id, balance_cents)\r\n  values (v_sub.student_id, 0)\r\n  on conflict (user_id) do nothing;\r\n\r\n  update public.cash_wallets\r\n  set balance_cents = balance_cents - p_amount_cents\r\n  where user_id = v_sub.student_id\r\n    and balance_cents >= p_amount_cents\r\n  returning balance_cents into v_wallet_balance;\r\n\r\n  if not found then\r\n    update public.subscription_billing_events as e\r\n    set\r\n      event_type = ''renewal_failed'',\r\n      status = ''failed'',\r\n      failure_code = ''insufficient_cash'',\r\n      failure_message = ''CASH_INSUFFICIENT'',\r\n      processed_at = p_processed_at\r\n    where e.id = v_event_id\r\n    returning e.attempt_count into v_attempt_count;\r\n\r\n    update public.subscriptions\r\n    set\r\n      status = ''past_due'',\r\n      grace_until = coalesce(grace_until, p_processed_at + interval ''2 days''),\r\n      updated_at = p_processed_at,\r\n      last_billing_event_id = v_event_id\r\n    where id = v_sub.id;\r\n\r\n    return query select false, ''insufficient_cash''::text, ''CASH_INSUFFICIENT''::text, v_event_id, null::uuid, v_event.period_start, v_event.period_end, null::bigint, coalesce(v_attempt_count, 1);\r\n    return;\r\n  end if;\r\n\r\n  insert into public.cash_ledger (\r\n    user_id,\r\n    delta_cents,\r\n    reason,\r\n    ref_type,\r\n    ref_id,\r\n    idempotency_key,\r\n    created_at\r\n  )\r\n  values (\r\n    v_sub.student_id,\r\n    -p_amount_cents,\r\n    ''subscription_renewal'',\r\n    ''subscriptions'',\r\n    v_sub.id,\r\n    p_idempotency_key,\r\n    p_processed_at\r\n  )\r\n  on conflict (idempotency_key) do nothing\r\n  returning id into v_ledger_id;\r\n\r\n  if v_ledger_id is null then\r\n    select id\r\n      into v_ledger_id\r\n    from public.cash_ledger\r\n    where idempotency_key = p_idempotency_key;\r\n  end if;\r\n\r\n  v_period_start := coalesce(v_event.period_start, v_sub.current_period_end, p_period_end, p_processed_at);\r\n  v_period_end := coalesce(v_event.period_end, ((v_period_start at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul''));\r\n\r\n  update public.subscription_billing_events as e\r\n  set\r\n    event_type = ''renewal'',\r\n    status = ''succeeded'',\r\n    ledger_id = v_ledger_id,\r\n    processed_at = p_processed_at,\r\n    failure_code = null,\r\n    failure_message = null,\r\n    period_start = v_period_start,\r\n    period_end = v_period_end,\r\n    amount_cents = p_amount_cents::int\r\n  where e.id = v_event_id\r\n  returning e.attempt_count into v_attempt_count;\r\n\r\n  update public.subscriptions\r\n  set\r\n    status = ''active'',\r\n    current_period_start = v_period_start,\r\n    current_period_end = v_period_end,\r\n    next_billing_at = v_period_end,\r\n    last_renewed_at = p_processed_at,\r\n    last_billing_event_id = v_event_id,\r\n    grace_until = null,\r\n    updated_at = p_processed_at\r\n  where id = v_sub.id;\r\n\r\n  return query select true, ''succeeded''::text, ''renewal processed''::text, v_event_id, v_ledger_id, v_period_start, v_period_end, v_wallet_balance, coalesce(v_attempt_count, 1);\r\nend;\r\n$function$"], "idempotency_key": null}, {"name": "tz_fix_mentor_notification_body_kst", "version": "20260829100200", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 186_tz_fix_mentor_notification_body_kst.sql  (TZ-FIX R2 — 감사 보고서 버그표 #14)\n--\n-- Purpose: 멘토 활동종료·휴식 알림 ''본문'' 날짜를 UTC 박제(at time zone ''UTC'')에서\n--   157 정본 notification_date_label(KST, ''YYYY년 M월 D일'')로 교정.\n--   KST 새벽 신청 건은 학생 push·알림함 본문이 하루 이른 날짜로 나가던 결함.\n--\n-- Base: 라이브(lbeqxarxothkmzqvpudy) pg_get_functiondef 원문 2026-08-29 추출.\n--   mp_notify_activity_transition  def md5 11b614c5a2acd21558f2e0684f7a9101 (2,215 bytes)\n--   (라이브 본문은 supabase/sql/158_p1_11_mentor_notification_atomization.sql 의\n--    동일 함수 본문과 바이트 단위 일치 확인 — 158 파일 자체는 무수정 역사 파일.)\n--\n-- Fix (본문 날짜만 — 멱등 키 포맷 보존, §0-3):\n--   1) v_body_date 변수 신설, 각 분기에서\n--      public.notification_date_label(coalesce(NEW.termination_effective_at|pause_until, now()))\n--   2) 알림 본문 문자열의 v_date_key 2곳 → v_body_date\n--   변경 없음: v_date_key 산출식(UTC ''YYYY-MM-DD'') · v_key 멱등 키 조립식 2곳 ·\n--   함수 시그니처(trigger) · SECURITY DEFINER · search_path · 그 외 전 라인.\n--\n-- Apply: 저장소 표준 경로(db-apply-pending) — MCP apply_migration 직접 적용 금지.\n--   pack 등재: supabase/baseline/post_ledger_backfills/20260829100200_... (v1.1 보정).\n--\n-- Rollback: 위 Base md5 의 라이브 원문(create or replace) 재적용으로 원복.\n-- =============================================================================\n\nCREATE OR REPLACE FUNCTION public.mp_notify_activity_transition()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_sub record;\n  v_key text;\n  v_date_key text;\n  v_body_date text;\nbegin\n  if NEW.activity_status = ''terminating'' then\n    v_date_key := to_char(coalesce(NEW.termination_effective_at, now()) at time zone ''UTC'', ''YYYY-MM-DD'');\n    v_body_date := public.notification_date_label(coalesce(NEW.termination_effective_at, now()));\n    for v_sub in\n      select s.id, s.student_id from public.subscriptions s\n      where s.mentor_id = NEW.user_id and s.status in (''active'', ''past_due'')\n    loop\n      v_key := ''mentor_termination_notice:'' || v_sub.id::text || '':'' || v_date_key;\n      perform public.record_domain_notification(\n        v_sub.student_id, v_key, v_key, ''mentor_termination_notice'',\n        ''멘토 활동 종료 예정'',\n        ''구독 중인 멘토가 활동을 종료합니다. 2주 후('' || v_body_date\n          || '') 구독이 정리되며 남은 기간은 환불됩니다. 그때까지는 정상 이용할 수 있어요.'',\n        ''/subscriptions'',\n        jsonb_build_object(''mentor_id'', NEW.user_id, ''effective_at'', NEW.termination_effective_at,\n          ''subscription_id'', v_sub.id),\n        jsonb_build_object(''mentor_id'', NEW.user_id, ''subscription_id'', v_sub.id));\n    end loop;\n  elsif NEW.activity_status = ''paused'' then\n    v_date_key := to_char(coalesce(NEW.pause_until, now()) at time zone ''UTC'', ''YYYY-MM-DD'');\n    v_body_date := public.notification_date_label(coalesce(NEW.pause_until, now()));\n    for v_sub in\n      select s.id, s.student_id from public.subscriptions s\n      where s.mentor_id = NEW.user_id and s.status in (''active'', ''past_due'')\n    loop\n      v_key := ''mentor_pause_notice:'' || v_sub.id::text || '':'' || v_date_key;\n      perform public.record_domain_notification(\n        v_sub.student_id, v_key, v_key, ''mentor_pause_notice'',\n        ''멘토 일시 휴식 안내'',\n        ''구독 중인 멘토가 '' || v_body_date || ''까지 일시 휴식합니다. 쉰 기간만큼 구독 기간이 자동 연장됩니다.'',\n        ''/subscriptions'',\n        jsonb_build_object(''mentor_id'', NEW.user_id, ''pause_until'', NEW.pause_until,\n          ''subscription_id'', v_sub.id),\n        jsonb_build_object(''mentor_id'', NEW.user_id, ''subscription_id'', v_sub.id));\n    end loop;\n  end if;\n  return NEW;\nend $function$"], "idempotency_key": null}, {"name": "tz_fix_consent_minor_age_kst", "version": "20260829100300", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 187_tz_fix_consent_minor_age_kst.sql  (TZ-FIX R3 — 감사 보고서 버그표 #25)\n--\n-- Purpose: 동의원장 트리거의 만 14세 폴백 판정 기준일을 current_date(세션 TZ=UTC 달력)\n--   에서 KST 달력 ''오늘''로 교정. 웹 경로가 is_minor 를 항상 채워 현재 도달 불가한\n--   잠재 결함이나, 폴백 경로가 살아나는 순간 KST 새벽 가입 건이 하루 어긋난다.\n--\n-- Base: 라이브(lbeqxarxothkmzqvpudy) pg_get_functiondef 원문 2026-08-29 추출.\n--   handle_new_auth_user_consent_records  def md5 833a94c880ea8000d049d67eb83a1f46 (3,300 bytes)\n--   (라이브는 저장소 087 원문(3,044 B)보다 최신 패치 상태 — 087 을 베이스로 쓰지 않았다.\n--    본문은 base64 2분할 추출 후 재조립 md5 대조(86f4512b04f460f6e980e21ba5049cf8)로 무결 확인.)\n--\n-- Fix (판정 기준일 식 1곳만 — 그 외 라인 라이브 원문 바이트 그대로, CRLF 보존):\n--   current_date < (v_birth_date + interval ''14 years'')::date\n--     -> (now() at time zone ''Asia/Seoul'')::date < (v_birth_date + interval ''14 years'')::date\n--   변경 없음: 멱등 키(''signup:…'' 조립식) · consent 행 구성 · 함수 시그니처(trigger) ·\n--   SECURITY DEFINER · search_path.\n--\n-- Apply: 저장소 표준 경로(db-apply-pending) — MCP apply_migration 직접 적용 금지.\n--   pack 등재: supabase/baseline/post_ledger_backfills/20260829100300_... (v1.1 보정).\n--\n-- Rollback: 위 Base md5 의 라이브 원문(create or replace) 재적용으로 원복.\n-- =============================================================================\n\nCREATE OR REPLACE FUNCTION public.handle_new_auth_user_consent_records()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\r\ndeclare\r\n  m jsonb;\r\n  v_role text;\r\n  v_birth_date date;\r\n  v_is_minor boolean := false;\r\n  v_version text;\r\n  v_agreed_at timestamptz := now();\r\n  v_metadata jsonb;\r\nbegin\r\n  m := coalesce(new.raw_user_meta_data, ''{}''::jsonb);\r\n  v_role := lower(coalesce(nullif(trim(m->>''app_role''), ''''), ''student''));\r\n  v_version := coalesce(nullif(trim(m->>''consent_version''), ''''), ''legal-placeholder-2026-06-20'');\r\n\r\n  begin\r\n    v_birth_date := nullif(trim(m->>''birth_date''), '''')::date;\r\n  exception when others then\r\n    v_birth_date := null;\r\n  end;\r\n\r\n  v_is_minor := coalesce(\r\n    nullif(trim(m->>''is_minor''), '''')::boolean,\r\n    case when v_birth_date is not null\r\n         then ((now() at time zone ''Asia/Seoul'')::date < (v_birth_date + interval ''14 years'')::date)\r\n         else false end\r\n  );\r\n\r\n  v_metadata := jsonb_build_object(\r\n    ''role'', v_role,\r\n    ''birth_date'', case when v_birth_date is not null then v_birth_date::text else null end,\r\n    ''age_gate_checked_at'', nullif(trim(m->>''age_gate_checked_at''), ''''),\r\n    ''verification_method'', coalesce(nullif(trim(m->>''guardian_verification_method''), ''''), ''legal_review_pending'')\r\n  );\r\n\r\n  if (m->>''terms_agreed'') = ''true'' then\r\n    insert into public.user_consent_records (\r\n      user_id, consent_type, consent_actor, is_minor, guardian_consent,\r\n      consent_version, agreed_at, source, metadata, idempotency_key\r\n    ) values (\r\n      new.id, ''terms'', ''user'', v_is_minor, false,\r\n      v_version, v_agreed_at, ''signup'', v_metadata, ''signup:'' || new.id::text || '':terms:'' || v_version\r\n    ) on conflict (idempotency_key) do nothing;\r\n  end if;\r\n\r\n  if (m->>''privacy_agreed'') = ''true'' then\r\n    insert into public.user_consent_records (\r\n      user_id, consent_type, consent_actor, is_minor, guardian_consent,\r\n      consent_version, agreed_at, source, metadata, idempotency_key\r\n    ) values (\r\n      new.id, ''privacy'', ''user'', v_is_minor, false,\r\n      v_version, v_agreed_at, ''signup'', v_metadata, ''signup:'' || new.id::text || '':privacy:'' || v_version\r\n    ) on conflict (idempotency_key) do nothing;\r\n  end if;\r\n\r\n  if (m->>''marketing_agreed'') = ''true'' then\r\n    insert into public.user_consent_records (\r\n      user_id, consent_type, consent_actor, is_minor, guardian_consent,\r\n      consent_version, agreed_at, source, metadata, idempotency_key\r\n    ) values (\r\n      new.id, ''marketing'', ''user'', v_is_minor, false,\r\n      v_version, v_agreed_at, ''signup'', v_metadata, ''signup:'' || new.id::text || '':marketing:'' || v_version\r\n    ) on conflict (idempotency_key) do nothing;\r\n  end if;\r\n\r\n  if v_is_minor and (m->>''guardian_consent'') = ''true'' then\r\n    insert into public.user_consent_records (\r\n      user_id, consent_type, consent_actor, is_minor, guardian_consent,\r\n      consent_version, guardian_ref, agreed_at, source, metadata, idempotency_key\r\n    ) values (\r\n      new.id, ''minor_guardian_consent'', ''guardian'', true, true,\r\n      v_version, nullif(trim(m->>''guardian_ref''), ''''), v_agreed_at, ''signup'', v_metadata,\r\n      ''signup:'' || new.id::text || '':minor_guardian_consent:'' || v_version\r\n    ) on conflict (idempotency_key) do nothing;\r\n  end if;\r\n\r\n  return new;\r\nend;\r\n$function$"], "idempotency_key": null}, {"name": "paysync_invoices", "version": "20260830100100", "rollback": null, "created_by": null, "statements": ["-- [Phase 2 2026-08-30] 페이싱크 무통장입금 주문 원장 `paysync_invoices`.\n--\n-- 용도: 우리가 선발급한 페이싱크 주문(`ivc_...`)의 로컬 정본. 웹훅·보정 크론이\n--   \"이 주문이 우리 것인가 · 누구 것인가 · 얼마인가\"를 이 테이블로 대조한 뒤에만\n--   적립한다. 페이로드의 metadata 만 믿고 적립하지 않는다(대시보드 수기 발행 주문의\n--   metadata 로 임의 계정에 캐시를 넣는 경로 차단).\n--\n-- ledger_order_ref 가 있는 이유 (F11 계약과의 정합):\n--   F11 `api_web_v1.record_cash_topup_v2` 는 `p_order_ref` 에 Toss 주문 형식\n--   `^cash-(.+)-(\\d+)$` 를 **강제**하고, 캡처한 uuid 가 `p_user_id` 와 일치해야 한다\n--   (계약 §7 F11 2·3항). 따라서 `ivc_...` 를 그대로 멱등키로 넘길 수 없다 —\n--   항상 `ORDER_REF_INVALID` 로 거부된다. 새 원장 RPC 신설은 금지(킥오프 §1)이므로,\n--   주문 발급 시점에 F11 이 받아들이는 형식의 참조를 만들어 이 컬럼에 고정 저장하고\n--   그 값을 멱등키로 쓴다. 주문당 1개로 고정되므로 웹훅이 몇 번 재전송돼도 멱등하다.\n--\n--   `paysync_invoices_ledger_ref_shape` CHECK 가 ref 형식을 행의 user_id 와 묶어\n--   구조적으로 강제한다 — F11 의 ORDER_REF_INVALID·ORDER_REF_OWNER_MISMATCH 가\n--   이 테이블을 거친 적립 경로에서는 발생할 수 없다.\n--\n--   `ivc_...` ↔ 원장 멱등키의 대응은 이 테이블이 유일한 정본이다\n--   (cash_ledger.idempotency_key 만 보면 Toss 주문과 형식이 같아 구분되지 않는다).\n--\n-- 토스 채널과의 충돌 불가 논증 (중요 — 이 분리가 깨지면 적립이 조용히 삼켜진다):\n--   두 채널의 ref 는 같은 `cash_ledger.idempotency_key` 네임스페이스를 공유한다.\n--   같은 값이 두 번 오면 F11 은 ON CONFLICT DO NOTHING 후 6필드 대조를 거쳐\n--   `duplicate: true` 로 **성공 응답**한다 — 뒤에 온 결제는 적립 없이 성공으로\n--   보고되고 돈만 사라진다. 따라서 충돌은 ''드물어야'' 하는 게 아니라 ''불가능''해야 한다.\n--\n--   분리자: 숫자부의 **선행 0**.\n--     토스    `cash-{uuid}-{Date.now()}`   — components/cash/CashChargeWidget.tsx\n--     페이싱크 `cash-{uuid}-0{Date.now()}`  — lib/paysync/paysyncLedgerRef.ts\n--   `Date.now()` 는 양의 정수이고, 자바스크립트의 Number→string 변환은 선행 0 을\n--   만들지 않는다. 즉 토스 숫자부는 **절대** ''0'' 으로 시작할 수 없고, 페이싱크 숫자부는\n--   **항상** ''0'' 으로 시작한다. 두 집합은 문자열로서 교집합이 공집합이다 — 시각·난수·\n--   자릿수 같은 확률적 근거가 아니라 표현 형식에서 나오는 구조적 분리다.\n--\n--   F11 은 숫자부(`v_m[2]`)를 캡처만 하고 쓰지 않으며 소유자 판정에 `v_m[1]`(uuid)만\n--   쓴다. `parseUserIdFromCashOrderId` 도 동일하다 — 선행 0 은 양쪽 모두 무해하다.\n--   아래 CHECK 가 선행 0 없는 ref 의 저장을 거부하고, 반대편(토스 생성기가 선행 0 을\n--   만들지 않음)은 lib/paysync/__contract__/paysyncLedgerRef.contract.test.ts 가 고정한다.\n--   (테스트 충전 `walletTopupActions` 의 `cash_topup_...` 키는 접두사부터 달라 무관.)\n--\n-- 금액 단위: 이 테이블은 **원(KRW)** 으로 보관한다. cash_ledger 의 cents(원×100)\n--   환산은 기존 krwWonToCents 경로가 담당한다 — 여기서 미리 곱하지 않는다.\n--\n-- 접근 경계: 본인 row SELECT 만 열고 쓰기는 service_role 전용\n--   (cash_ledger/cash_wallets 의 cled_select·cwal_select 선례와 동일 형태).\n--\n-- adg 가드: 탈퇴 진행(locked 이상) 유저 앞 **신규 주문 발급**만 차단한다(billing_keys 선례).\n--   INSERT 에만 부착하고 UPDATE 에는 부착하지 않는다 — 이미 발급된 주문에 입금이\n--   도착했는데 탈퇴 진행 중이라는 이유로 paid 전이가 막히면 돈만 들어오고 상태가\n--   갱신되지 않아 대사가 불가능해진다.\n--\n-- 롤백 노트 (실행 금지 — 참고용):\n--   -- drop trigger if exists adg_paysync_invoices on public.paysync_invoices;\n--   -- drop policy if exists paysync_invoices_select_own on public.paysync_invoices;\n--   -- drop table if exists public.paysync_invoices;\n\ncreate table if not exists public.paysync_invoices (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.users (id),\n  -- 페이싱크 주문 ID(`ivc_...`) — 웹훅 멱등 판정의 도메인 키.\n  paysync_invoice_id text not null unique,\n  -- F11 에 넘길 원장 멱등키. 발급 시점에 확정하고 이후 불변.\n  ledger_order_ref text not null unique,\n  pay_krw integer not null check (pay_krw > 0),\n  cash_krw integer not null check (cash_krw > 0),\n  bonus_krw integer not null default 0 check (bonus_krw >= 0),\n  -- 입금자명 — 페이싱크 자동 매칭 키(입금자명 + 금액 정확 일치).\n  -- 1~5자·공백 불가(킥오프 §5). 공백이 섞이면 매칭이 어긋나므로 형식으로 막는다.\n  depositor_name text not null check (depositor_name ~ ''^[^[:space:]]{1,5}$''),\n  status text not null default ''pending''\n    check (status in (''pending'', ''paid'', ''expired'', ''canceled'')),\n  issued_at timestamptz not null default now(),\n  expires_at timestamptz,\n  paid_at timestamptz,\n  -- 문서상 AUTOMATIC_MATCHING / MANUAL_MATCHING / MANUAL_APPROVE / API_CALL.\n  -- 로직 분기 없이 감사용이라 CHECK 로 잠그지 않는다(값이 늘어도 수신이 깨지지 않게).\n  paid_trigger text,\n  created_at timestamptz not null default now(),\n  -- F11 형식 + 소유자 일치 + **토스 채널과의 네임스페이스 분리**를 행 안에서 강제한다.\n  -- 숫자부 선행 `0` 이 분리자다 — 아래 헤더 주석의 충돌 불가 논증 참조.\n  constraint paysync_invoices_ledger_ref_shape\n    check (ledger_order_ref ~ (''^cash-'' || user_id::text || ''-0[0-9]+$'')),\n  -- 지급 캐시 = 결제 금액 + 보너스 (CASH_CHARGE_PACKAGES 정본과 동치).\n  constraint paysync_invoices_cash_krw_sum\n    check (cash_krw = pay_krw + bonus_krw)\n)", "comment on table public.paysync_invoices is\n  ''Phase 2: 페이싱크 무통장입금 주문 로컬 정본. 웹훅·보정 크론이 소유자·금액을 이 표로 대조한 뒤 적립한다. ledger_order_ref 는 F11 record_cash_topup_v2 의 p_order_ref(= 원장 멱등키) — F11 이 Toss 형식만 받으므로 ivc_ 를 직접 쓸 수 없어 발급 시점에 고정한다. 금액은 원(KRW) 단위.''", "comment on column public.paysync_invoices.ledger_order_ref is\n  ''F11 p_order_ref(원장 idempotency_key). `cash-{user_id}-{digits}` 고정 형식 — CHECK 로 소유자까지 강제. cash_ledger 만 보면 Toss 주문과 구분되지 않으므로 ivc_ 대응은 이 표가 정본이다.''", "create index if not exists paysync_invoices_user_id_idx\n  on public.paysync_invoices (user_id)", "-- 보정 크론이 \"pending 인데 N분 경과\" 를 훑는 경로.\ncreate index if not exists paysync_invoices_pending_issued_at_idx\n  on public.paysync_invoices (issued_at)\n  where status = ''pending''", "alter table public.paysync_invoices enable row level security", "revoke all on public.paysync_invoices from public, anon, authenticated", "grant select on public.paysync_invoices to authenticated", "grant select, insert, update on public.paysync_invoices to service_role", "-- 본인 row SELECT 만 (cled_select·cwal_select 와 동일 형태 — auth.uid() 는 select 로 감싼다).\ndrop policy if exists paysync_invoices_select_own on public.paysync_invoices", "create policy paysync_invoices_select_own\n  on public.paysync_invoices for select to authenticated\n  using (user_id = (select auth.uid()))", "-- 탈퇴 진행 유저 앞 신규 주문 발급 차단 — billing_keys 선례. UPDATE 는 막지 않는다.\ndrop trigger if exists adg_paysync_invoices on public.paysync_invoices", "create trigger adg_paysync_invoices before insert on public.paysync_invoices\n  for each row execute function public.account_deletion_write_guard(''user_id'')"], "idempotency_key": null}, {"name": "add_display_mode_to_app_notices", "version": "20260830140804", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["alter table public.app_notices\n  add column display_mode text not null default ''page''\n  constraint app_notices_display_mode_allowed check (display_mode in (''page'', ''popup''));\n\ncomment on column public.app_notices.display_mode is ''노출 방식: page=공지 목록에만, popup=전역 팝업 모달로도 노출'';"], "idempotency_key": null}, {"name": "tmp_auto_school_verification_trigger", "version": "20260830150838", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- [임시/스테이징 전용] 멘토 승인 시 학교·전공 인증 자동 처리\n-- 목적: 정식 학교인증 플로우 운영 전까지 신규 멘토에게 \"참고·미인증\" 배지가 붙지 않도록\n--       승인 시점에 approved 인증 행(+학교군/계열 분류)을 자동 삽입.\n-- 제거(정식 플로우 전환 시):\n--   drop trigger if exists trg_tmp_auto_school_verification on public.mentor_profiles;\n--   drop function if exists public.tmp_auto_school_verification();\n\ncreate or replace function public.tmp_auto_school_verification()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if lower(coalesce(new.verification_status, '''')) in (''approved'', ''verified'', ''active'') then\n    insert into public.mentor_school_verifications\n      (mentor_id, status, verified_university_name, verified_department_name,\n       school_tier, verified_major_category, reviewed_at)\n    select\n      new.user_id,\n      ''approved'',\n      nullif(trim(new.university_name), ''''),\n      nullif(trim(new.department_name), ''''),\n      case\n        when new.university_name like ''서울대%'' or new.university_name like ''연세대%'' or new.university_name like ''고려대%''\n          then ''서연고''\n        when new.university_name like ''서강대%'' or new.university_name like ''성균관대%'' or new.university_name like ''한양대%''\n          then ''서성한''\n        when new.university_name like ''중앙대%'' or new.university_name like ''경희대%''\n          or new.university_name like ''한국외%'' or new.university_name like ''서울시립대%''\n          then ''중경외시''\n        when new.university_name like ''건국대%'' or new.university_name like ''동국대%'' or new.university_name like ''홍익대%''\n          then ''건동홍''\n        else ''미분류''\n      end,\n      case\n        when new.department_name like ''%의예%'' or new.department_name like ''%의학%''\n          or new.department_name like ''%치의%'' or new.department_name like ''%약학%'' or new.department_name like ''%한의%''\n          or new.department_name like ''%수의%'' or new.department_name like ''%간호%''\n          then ''메디컬''\n        when new.department_name like ''%교육%'' then ''교육''\n        when new.department_name like ''%국어국문%'' or new.department_name like ''%문헌정보%''\n          or new.department_name like ''%철학%'' or new.department_name like ''%사학%'' or new.department_name like ''%어문%''\n          then ''인문''\n        when new.department_name like ''%경영%'' or new.department_name like ''%경제%''\n          or new.department_name like ''%미디어%'' or new.department_name like ''%정치%'' or new.department_name like ''%사회학%''\n          or new.department_name like ''%행정%'' or new.department_name like ''%심리%''\n          then ''사회상경''\n        when new.department_name like ''%수학%'' or new.department_name like ''%물리%''\n          or new.department_name like ''%화학%'' or new.department_name like ''%생명%'' or new.department_name like ''%통계%''\n          then ''자연''\n        when new.department_name like ''%공학%'' or new.department_name like ''%컴퓨터%''\n          or new.department_name like ''%전자%'' or new.department_name like ''%기계%'' or new.department_name like ''%소프트웨어%''\n          or new.department_name like ''%모빌리티%'' or new.department_name like ''%융합%''\n          then ''공학''\n        when new.department_name like ''%음악%'' or new.department_name like ''%미술%''\n          or new.department_name like ''%체육%'' or new.department_name like ''%디자인%''\n          then ''예체능''\n        else ''기타''\n      end,\n      now()\n    where not exists (\n      select 1 from public.mentor_school_verifications v\n      where v.mentor_id = new.user_id and v.status = ''approved''\n    );\n  end if;\n  return new;\nend;\n$$;\n\ncomment on function public.tmp_auto_school_verification() is\n  ''[임시/스테이징] 멘토 승인 시 학교인증 자동 approved 처리 — 정식 학교인증 플로우 전환 시 트리거와 함께 제거할 것'';\n\ndrop trigger if exists trg_tmp_auto_school_verification on public.mentor_profiles;\ncreate trigger trg_tmp_auto_school_verification\n  after insert or update of verification_status on public.mentor_profiles\n  for each row execute function public.tmp_auto_school_verification();"], "idempotency_key": null}, {"name": "payout_bank_allowlist_add_im_bank", "version": "20260831100100", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 189_payout_bank_allowlist_add_im_bank.sql  (2026-08-31)\n--\n-- Purpose: F13 `api_web_v1.mentor_payout_account_update_self` 은행명 allowlist\n--   16종 → 17종. `iM뱅크` 추가 (DGB대구은행 → iM뱅크 명칭 전환 반영).\n--   웹 정본 components/mentor/payouts/MentorPayoutAccountPanel.tsx BANK_OPTIONS 와\n--   바이트 단위 동일 문자열 유지 (양쪽 동시 반영 — 본 PR).\n--\n-- Base: supabase/sql/20260730112531_api_web_v1_payout_account_rpc.sql (S2 M14) 본문.\n--   이후 이 함수를 재정의한 migration 없음 (20260730195147·20260730195156 은 참조만).\n--\n-- 변경 없음: 시그니처(text, text) · SECURITY DEFINER · search_path '''' · 오류코드 ·\n--   상태 게이트 · 계좌 정규식 ^[0-9]{8,24}$ · 마스킹 식 · ACL(authenticated, service_role).\n--\n-- Apply: 저장소 표준 경로(db-apply-pending) — MCP apply_migration 직접 적용 금지.\n--   pack 등재: supabase/baseline/post_ledger_backfills/20260831100100_payout_bank_allowlist_add_im_bank.sql\n--\n-- Rollback: 위 Base 파일의 함수 본문(16종)을 CREATE OR REPLACE 로 재적용. 데이터 무접촉.\n--   (이미 ''iM뱅크'' 로 저장된 mentor_profiles 행은 남으며, UI customBankOption 으로\n--    표시되고 재저장 시에만 PAYOUT_BANK_NAME_INVALID 로 거부됨.)\n-- =============================================================================\n\nbegin", "-- A. 사전 게이트 — 함수가 실재하고 아직 iM뱅크가 없는 상태여야 한다\nDO $$\nDECLARE v_src text;\nBEGIN\n  SELECT p.prosrc INTO v_src\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = ''api_web_v1'' AND p.proname = ''mentor_payout_account_update_self''\n     AND pg_get_function_identity_arguments(p.oid) = ''p_bank_name text, p_account_number text'';\n  IF v_src IS NULL THEN\n    RAISE EXCEPTION ''189_GATE: F13 mentor_payout_account_update_self not present'';\n  END IF;\n  IF v_src LIKE ''%''''iM뱅크''''%'' THEN\n    RAISE EXCEPTION ''189_GATE: iM뱅크 already in allowlist — nothing to do'';\n  END IF;\n  IF v_src NOT LIKE ''%''''우체국''''%'' THEN\n    RAISE EXCEPTION ''189_GATE: base allowlist shape mismatch (우체국 not found)'';\n  END IF;\nEND $$", "-- B. F13 재정의 — allowlist 에 ''iM뱅크'' 추가 외 원본과 동일\nCREATE OR REPLACE FUNCTION api_web_v1.mentor_payout_account_update_self(\n  p_bank_name text, p_account_number text\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $fn$\nDECLARE\n  v_uid    uuid := (SELECT auth.uid());\n  v_role   text;\n  v_status text;\n  v_susp   timestamptz;\n  v_bank   text := btrim(coalesce(p_bank_name, ''''));\n  v_acct   text := btrim(coalesce(p_account_number, ''''));\n  v_updated timestamptz;\nBEGIN\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  SELECT u.role, u.status, u.suspended_until INTO v_role, v_status, v_susp\n    FROM public.users u WHERE u.id = v_uid;\n  IF NOT FOUND OR v_role IS DISTINCT FROM ''mentor'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROLE_NOT_MENTOR'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''banned'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_BANNED'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''suspended'' AND (v_susp IS NULL OR v_susp > now()) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_SUSPENDED'');\n  END IF;\n  IF public.account_deletion_write_blocked(v_uid) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  END IF;\n  IF NOT public.individual_question_user_is_approved_mentor(v_uid) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_APPROVED'');\n  END IF;\n\n  -- 은행명 allowlist (웹 정본 BANK_OPTIONS 17종 — MentorPayoutAccountPanel.tsx)\n  IF v_bank NOT IN (''KB국민은행'', ''신한은행'', ''우리은행'', ''하나은행'', ''NH농협은행'',\n                    ''IBK기업은행'', ''카카오뱅크'', ''토스뱅크'', ''케이뱅크'', ''SC제일은행'',\n                    ''씨티은행'', ''KDB산업은행'', ''수협은행'', ''신협'', ''새마을금고'', ''우체국'',\n                    ''iM뱅크'') THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAYOUT_BANK_NAME_INVALID'');\n  END IF;\n  -- 계좌번호 숫자만·길이 8~24\n  IF v_acct !~ ''^[0-9]{8,24}$'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAYOUT_ACCOUNT_NUMBER_INVALID'');\n  END IF;\n\n  UPDATE public.mentor_profiles mp\n     SET payout_bank_name = v_bank,\n         payout_account_number = v_acct\n   WHERE mp.user_id = v_uid\n   RETURNING mp.updated_at INTO v_updated;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_PROFILE_NOT_FOUND'');\n  END IF;\n\n  -- 계좌 원문 비반환 — 끝 4자리 외 마스킹(§11.4)\n  RETURN jsonb_build_object(''ok'', true, ''contract_version'', 1, ''updated_at'', v_updated,\n    ''account_masked'', repeat(''*'', greatest(char_length(v_acct) - 4, 0)) || right(v_acct, 4));\nEND $fn$", "COMMENT ON FUNCTION api_web_v1.mentor_payout_account_update_self(text, text) IS\n  ''S2 M14 F13(계약 §7 — rev 8 A-4, U-06 해소): 정산계좌 전용 RPC — 승인 멘토·은행 allowlist 17종(189: +iM뱅크)·계좌 8~24 숫자·원문 비반환(끝 4자리 마스킹). M11 게이트 ② 선행.''", "-- C. GRANT 재선언 (§10.3 — 멱등, ACL 집합 불변 확인용)\nREVOKE ALL ON FUNCTION api_web_v1.mentor_payout_account_update_self(text, text) FROM PUBLIC", "GRANT EXECUTE ON FUNCTION api_web_v1.mentor_payout_account_update_self(text, text) TO authenticated, service_role", "-- D. 적용 직후 자가 검증 — 원본 M14 §D 와 동일 조건 + iM뱅크 실재\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n                  WHERE n.nspname = ''api_web_v1'' AND p.proname = ''mentor_payout_account_update_self''\n                    AND pg_get_function_identity_arguments(p.oid) = ''p_bank_name text, p_account_number text''\n                    AND p.prosecdef AND p.proconfig::text LIKE ''%search_path=%''\n                    AND p.prosrc LIKE ''%''''iM뱅크''''%''\n                    AND NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n                    AND has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n                    AND has_function_privilege(''service_role'', p.oid, ''EXECUTE'')\n                    AND (p.proacl IS NULL OR (p.proacl::text NOT LIKE ''{=%'' AND p.proacl::text NOT LIKE ''%,=%''))) THEN\n    RAISE EXCEPTION ''189_SELFCHECK: F13 hardening/allowlist mismatch'';\n  END IF;\nEND $$", "commit"], "idempotency_key": null}, {"name": "cap_structure_limit_50_weights", "version": "20260903100100", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 190_cap_structure_limit_50_weights.sql  (2026-09-03 · DB-1 묶음 A — 캡 구조)\n--\n-- Purpose: 멘토 정원(cap) 구조를 오너 확정값으로 갱신한다.\n--   · 한도   mentor_cap_limit() 폴백 28 → 50 · mentor_profiles.cap_limit 기본값 28 → 50 ·\n--            기존 행 28 → 50 (관리자가 개별 조정해 28 이 아닌 행은 건드리지 않는다)\n--   · 가중치 subscription_cap_weight(): limited 1.0 (유지) · standard 2.5 → 2.25 · premium 4.5 → 4.75\n--\n-- A-2 확인 결과 — 두 함수를 호출하는 곳(자동 반영): enforce_mentor_cap(트리거) · mentor_cap_used ·\n--   confirm_subscription_checkout. cap_limit CHECK 제약 없음(50 허용). 활성 구독 0건 → 사용량 영향 0.\n--\n-- A-2 확인 결과 — 함수를 호출하지 않고 리터럴 사본을 가진 곳(이 파일이 함께 갱신한다):\n--   1) enforce_mentor_profile_privileged_guard() INSERT 분기 `IS DISTINCT FROM 28` +\n--      trg_mentor_profile_privileged_guard_ins WHEN 절의 28. M0(20260729211929) 자체 주석이\n--      \"기본값을 바꾸는 마이그레이션은 이 조건을 함께 갱신해야 한다\"고 못박았다. 갱신하지 않으면\n--      기본값 50 으로 들어오는 모든 mentor_profiles INSERT 가 ''특권 변경''으로 판정돼 authenticated\n--      가입 경로가 42501(MENTOR_PROFILE_PRIVILEGED_COLUMN_FORBIDDEN)로 막힌다.\n--   2) mp_seed_default_plans_on_approval() — 승인 시 mentor_plans.cap_weight 를 1.0/2.5/4.5 리터럴로 시드.\n--   3) api_web_v1.mentor_plan_prices_set_self (S2 M8 F8) — v_caps ARRAY[1.0, 2.5, 4.5] 로 cap_weight 강제.\n--   4) mentor_plans.cap_weight 참조 컬럼(73 멘토 × 3 tier) — 2)·3) 이 쓰는 값. 실차감·cap 판정은\n--      subscription_cap_weight() 만 쓰므로 계산에는 영향 없지만 두 정본이 어긋난 채 두지 않는다.\n--   → 2)·3) 은 리터럴을 버리고 public.subscription_cap_weight(tier) 를 호출한다(단일 정본).\n--      4) 는 함수값으로 백필한다(146 행 = standard·premium × 73).\n--\n-- 부수효과 억제: mentor_profiles·mentor_plans 의 updated_at 트리거를 해당 UPDATE 동안만 끈다\n--   (시스템 설정 변경이 ''최근 수정'' 으로 관리자 활동 로그에 잡히지 않게). 같은 트랜잭션 안에서 복원·자가 검증.\n--   mentor_plans 가격 알림 트리거는 amount_cents 변경에만 반응하므로 알림 fan-out 0.\n--\n-- Apply: 저장소 표준 경로(db-apply-pending) — MCP apply_migration·SQL Editor 즉석 실행 금지.\n--   pack 등재: supabase/baseline/post_ledger_backfills/20260903100100_cap_structure_limit_50_weights.sql\n-- Rollback: supabase/rollback/20260903100100_cap_structure_limit_50_weights_rollback.sql\n-- 검증(§5): select distinct cap_limit from mentor_profiles;\n--           select subscription_cap_weight(''limited''), subscription_cap_weight(''standard''), subscription_cap_weight(''premium'');\n-- =============================================================================\n\nbegin", "-- ── 0. 사전 게이트 — 예상 상태와 다르면 중단(임의 정정 금지) ──────────────────\ndo $$\ndeclare\n  v_guard_src text;\n  v_f8_src    text;\n  v_seed_src  text;\n  v_default   text;\nbegin\n  if public.subscription_cap_weight(''standard'') <> 2.5 or public.subscription_cap_weight(''premium'') <> 4.5 then\n    raise exception ''190_GATE: subscription_cap_weight 가 2.5/4.5 가 아니다(%/%) — 이미 적용됐거나 전제 불일치'',\n      public.subscription_cap_weight(''standard''), public.subscription_cap_weight(''premium'');\n  end if;\n\n  select column_default into v_default\n    from information_schema.columns\n   where table_schema = ''public'' and table_name = ''mentor_profiles'' and column_name = ''cap_limit'';\n  if v_default is distinct from ''28'' then\n    raise exception ''190_GATE: mentor_profiles.cap_limit 기본값이 28 이 아니다(%)'', v_default;\n  end if;\n\n  select p.prosrc into v_guard_src\n    from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''public'' and p.proname = ''enforce_mentor_profile_privileged_guard'';\n  if v_guard_src is null or v_guard_src not like ''%IS DISTINCT FROM 28%'' then\n    raise exception ''190_GATE: enforce_mentor_profile_privileged_guard 본문에 `IS DISTINCT FROM 28` 이 없다 — M0 전제 불일치'';\n  end if;\n  if not exists (select 1 from pg_trigger where tgname = ''trg_mentor_profile_privileged_guard_ins''\n                   and tgrelid = ''public.mentor_profiles''::regclass) then\n    raise exception ''190_GATE: trg_mentor_profile_privileged_guard_ins 부재'';\n  end if;\n\n  select p.prosrc into v_f8_src\n    from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''api_web_v1'' and p.proname = ''mentor_plan_prices_set_self''\n     and pg_get_function_identity_arguments(p.oid) = ''p_limited_cash_krw integer, p_standard_cash_krw integer, p_premium_cash_krw integer'';\n  if v_f8_src is null or v_f8_src not like ''%ARRAY[1.0, 2.5, 4.5]%'' then\n    raise exception ''190_GATE: api_web_v1.mentor_plan_prices_set_self 의 v_caps 리터럴(ARRAY[1.0, 2.5, 4.5]) 을 찾지 못했다'';\n  end if;\n\n  select p.prosrc into v_seed_src\n    from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''public'' and p.proname = ''mp_seed_default_plans_on_approval'';\n  if v_seed_src is null or v_seed_src not like ''%8490000, 2.5,%'' or v_seed_src not like ''%17490000, 4.5,%'' then\n    raise exception ''190_GATE: mp_seed_default_plans_on_approval 의 cap_weight 리터럴(2.5/4.5) 을 찾지 못했다'';\n  end if;\n\n  if not exists (select 1 from pg_trigger where tgname = ''trg_mentor_profiles_set_updated''\n                   and tgrelid = ''public.mentor_profiles''::regclass)\n     or not exists (select 1 from pg_trigger where tgname = ''trg_mp_set_updated''\n                   and tgrelid = ''public.mentor_plans''::regclass) then\n    raise exception ''190_GATE: updated_at 트리거(trg_mentor_profiles_set_updated / trg_mp_set_updated) 부재'';\n  end if;\nend $$", "-- ── 1. 가중치 정본 — 1.0 / 2.25 / 4.75 (050 본문 · search_path 고정 072 그대로) ──\ncreate or replace function public.subscription_cap_weight(p_tier text)\nreturns numeric\nlanguage sql\nimmutable\nset search_path = public\nas $$\n  select case lower(coalesce(p_tier, ''''))\n    when ''limited'' then 1.0\n    when ''standard'' then 2.25\n    when ''premium'' then 4.75\n    else 0\n  end::numeric;\n$$", "comment on function public.subscription_cap_weight(text) is\n  ''190: 플랜 tier → cap 가중치 정본 (limited 1.0 · standard 2.25 · premium 4.75). 다른 곳에 리터럴 사본을 두지 않는다.''", "-- ── 2. 한도 폴백 28 → 50 (050 본문 그대로, 상수만) ─────────────────────────────\ncreate or replace function public.mentor_cap_limit(p_mentor_id uuid)\nreturns numeric\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce(\n    (select mp.cap_limit from public.mentor_profiles mp where mp.user_id = p_mentor_id),\n    50\n  )::numeric;\n$$", "comment on function public.mentor_cap_limit(uuid) is\n  ''190: 멘토 cap 상한 — mentor_profiles.cap_limit, 행이 없으면 50.''", "-- ── 3. 컬럼 기본값 28 → 50 + 기존 행 백필(28 인 행만 · updated_at 불변) ───────\nalter table public.mentor_profiles\n  alter column cap_limit set default 50", "alter table public.mentor_profiles disable trigger trg_mentor_profiles_set_updated", "update public.mentor_profiles\n   set cap_limit = 50\n where cap_limit = 28", "alter table public.mentor_profiles enable trigger trg_mentor_profiles_set_updated", "-- ── 4. M0 특권 컬럼 가드 — INSERT 기본값 판정 28 → 50 (본문·ACL 그 외 불변) ─────\nCREATE OR REPLACE FUNCTION public.enforce_mentor_profile_privileged_guard()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $$\nDECLARE\n  v_jwt_role  text;\n  v_sensitive boolean;\nBEGIN\n  -- TG_OP 선분기: INSERT 에서 OLD 는 NULL 이므로 OLD 비교 전에 반드시 분기한다.\n  IF tg_op = ''INSERT'' THEN\n    -- 기본값 대비 판정. 50 하드코딩은 컬럼 기본값 변경 시 드리프트하는 취약점이다 —\n    -- 기본값을 바꾸는 마이그레이션은 이 조건을 함께 갱신해야 한다(주석 의무). 190: 28 → 50.\n    v_sensitive := (new.verification_status IS DISTINCT FROM ''pending''\n                    OR new.cap_limit IS DISTINCT FROM 50);\n  ELSE  -- ''UPDATE''\n    v_sensitive := (new.verification_status IS DISTINCT FROM old.verification_status\n                    OR new.cap_limit IS DISTINCT FROM old.cap_limit);\n  END IF;\n\n  IF v_sensitive THEN\n    v_jwt_role := auth.jwt() ->> ''role'';\n    IF v_jwt_role = ''service_role'' THEN RETURN new; END IF;   -- 서버 경유\n    IF v_jwt_role IS NULL THEN RETURN new; END IF;            -- SQL Editor·migration\n    IF EXISTS (SELECT 1 FROM public.users u\n               WHERE u.id = (SELECT auth.uid()) AND u.role = ''admin'') THEN\n      RETURN new;                                             -- 기존 관리자\n    END IF;\n    RAISE EXCEPTION ''MENTOR_PROFILE_PRIVILEGED_COLUMN_FORBIDDEN''\n      USING errcode = ''42501'';\n  END IF;\n  RETURN new;\nEND $$", "COMMENT ON FUNCTION public.enforce_mentor_profile_privileged_guard() IS\n  ''S2 M0(계약 §20.5): mentor_profiles.verification_status·cap_limit 변경을 service_role/JWT 없는 세션/admin 으로 제한하는 BEFORE INSERT OR UPDATE 가드. 190: INSERT 기본값 판정 28 → 50.''", "REVOKE ALL ON FUNCTION public.enforce_mentor_profile_privileged_guard() FROM PUBLIC", "drop trigger if exists trg_mentor_profile_privileged_guard_ins on public.mentor_profiles", "CREATE TRIGGER trg_mentor_profile_privileged_guard_ins\n  BEFORE INSERT ON public.mentor_profiles\n  FOR EACH ROW\n  WHEN (new.verification_status IS DISTINCT FROM ''pending''\n        OR new.cap_limit IS DISTINCT FROM 50)\n  EXECUTE FUNCTION public.enforce_mentor_profile_privileged_guard()", "-- ── 5. 승인 시 기본 플랜 시드 — cap_weight 리터럴 → subscription_cap_weight() (166 본문 그 외 동일) ──\ncreate or replace function public.mp_seed_default_plans_on_approval()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\nbegin\n  insert into public.mentor_plans\n    (mentor_id, plan_tier, amount_cents, cap_weight, label, is_active,\n     created_at, updated_at, price_updated_at)\n  values\n    (new.user_id, ''limited'',   2990000, public.subscription_cap_weight(''limited''),  null, true, now(), now(), now()),\n    (new.user_id, ''standard'',  8490000, public.subscription_cap_weight(''standard''), null, true, now(), now(), now()),\n    (new.user_id, ''premium'',  17490000, public.subscription_cap_weight(''premium''),  null, true, now(), now(), now())\n  on conflict (mentor_id, plan_tier) do nothing;\n  return new;\nend;\n$$", "comment on function public.mp_seed_default_plans_on_approval() is\n  ''SQL166: 멘토 승인 전이 시 기본 플랜 3종 시드(ON CONFLICT DO NOTHING). 190: cap_weight 는 subscription_cap_weight() 정본.''", "-- ── 6. F8 mentor_plan_prices_set_self — v_caps 리터럴 → subscription_cap_weight() (M8 본문 그 외 동일) ──\nCREATE OR REPLACE FUNCTION api_web_v1.mentor_plan_prices_set_self(\n  p_limited_cash_krw  integer,\n  p_standard_cash_krw integer,\n  p_premium_cash_krw  integer\n) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS $fn$\nDECLARE\n  v_uid    uuid := (SELECT auth.uid());\n  v_role   text;\n  v_status text;\n  v_susp   timestamptz;\n  -- 밴드 상수 — 정본 lib/subscribe/mentorPlanPricing.ts:13 와 동일 (T-REG-02).\n  -- 잠금값 개정 시 두 정본을 같은 PR 에서 함께 변경한다(계약 §7 F8).\n  v_tiers  text[]  := ARRAY[''limited'', ''standard'', ''premium''];\n  v_mins   int[]   := ARRAY[29900, 84900, 174900];\n  v_maxs   int[]   := ARRAY[69900, 149900, 329900];\n  -- 190: cap 가중치는 public.subscription_cap_weight() 단일 정본 — 리터럴 사본을 두지 않는다.\n  v_caps   numeric[] := ARRAY[public.subscription_cap_weight(''limited''),\n                              public.subscription_cap_weight(''standard''),\n                              public.subscription_cap_weight(''premium'')];\n  v_given  int[];\n  v_i      int;\n  v_amount int;\n  v_old    int;\n  v_updated   jsonb := ''[]''::jsonb;\n  v_unchanged jsonb := ''[]''::jsonb;\nBEGIN\n  IF v_uid IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  END IF;\n  SELECT u.role, u.status, u.suspended_until INTO v_role, v_status, v_susp\n    FROM public.users u WHERE u.id = v_uid;\n  IF NOT FOUND OR v_role IS DISTINCT FROM ''mentor'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROLE_NOT_MENTOR'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''banned'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_BANNED'');\n  END IF;\n  IF lower(coalesce(v_status, ''active'')) = ''suspended'' AND (v_susp IS NULL OR v_susp > now()) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_SUSPENDED'');\n  END IF;\n  IF public.account_deletion_write_blocked(v_uid) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  END IF;\n\n  v_given := ARRAY[p_limited_cash_krw, p_standard_cash_krw, p_premium_cash_krw];\n\n  -- 전건 검증 선행 → 전건 반영 또는 전건 실패 (3 tier 단일 트랜잭션 — T-CONC-07 상당)\n  FOR v_i IN 1..3 LOOP\n    IF v_given[v_i] IS NULL OR v_given[v_i] < 1 THEN\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1,\n                                ''code'', ''PLAN_PRICE_INVALID'', ''tier'', v_tiers[v_i]);\n    END IF;\n    IF v_given[v_i] < v_mins[v_i] OR v_given[v_i] > v_maxs[v_i] THEN\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1,\n                                ''code'', ''PLAN_PRICE_OUT_OF_BAND'', ''tier'', v_tiers[v_i],\n                                ''min_cash_krw'', v_mins[v_i], ''max_cash_krw'', v_maxs[v_i],\n                                ''given_cash_krw'', v_given[v_i]);\n    END IF;\n  END LOOP;\n\n  FOR v_i IN 1..3 LOOP\n    v_amount := v_given[v_i] * 100;   -- amountCentsFromCashKrw 동일 (1캐시 = 1원 = 100 cents)\n    SELECT mp.amount_cents INTO v_old FROM public.mentor_plans mp\n     WHERE mp.mentor_id = v_uid AND mp.plan_tier = v_tiers[v_i];\n    IF FOUND AND v_old = v_amount\n       AND EXISTS (SELECT 1 FROM public.mentor_plans mp\n                    WHERE mp.mentor_id = v_uid AND mp.plan_tier = v_tiers[v_i]\n                      AND mp.cap_weight = v_caps[v_i]) THEN\n      v_unchanged := v_unchanged || jsonb_build_object(''plan_tier'', v_tiers[v_i], ''amount_cents'', v_amount);\n    ELSE\n      INSERT INTO public.mentor_plans (mentor_id, plan_tier, amount_cents, cap_weight, is_active, price_updated_at)\n      VALUES (v_uid, v_tiers[v_i], v_amount, v_caps[v_i], true, now())\n      ON CONFLICT (mentor_id, plan_tier) DO UPDATE\n        SET amount_cents = excluded.amount_cents,\n            cap_weight = excluded.cap_weight,       -- tier 고정값 강제(클라이언트 불가)\n            price_updated_at = now();\n      v_updated := v_updated || jsonb_build_object(''plan_tier'', v_tiers[v_i], ''amount_cents'', v_amount);\n    END IF;\n  END LOOP;\n\n  RETURN jsonb_build_object(''ok'', true, ''contract_version'', 1,\n                            ''updated'', v_updated, ''unchanged'', v_unchanged);\nEND $fn$", "COMMENT ON FUNCTION api_web_v1.mentor_plan_prices_set_self(integer, integer, integer) IS\n  ''S2 M8 F8(계약 §7 — XW-03 해소): 멘토 플랜 가격 설정 — 밴드 DB 강제(클램프 없이 거부)·cap_weight tier 고정·3 tier 단일 트랜잭션. 190: cap_weight 는 subscription_cap_weight() 정본.''", "-- ── 7. mentor_plans.cap_weight 참조 컬럼 백필 — 함수값과 다른 행만 · updated_at 불변 ──\nalter table public.mentor_plans disable trigger trg_mp_set_updated", "update public.mentor_plans mp\n   set cap_weight = public.subscription_cap_weight(mp.plan_tier)\n where lower(coalesce(mp.plan_tier, '''')) in (''limited'', ''standard'', ''premium'')\n   and mp.cap_weight is distinct from public.subscription_cap_weight(mp.plan_tier)", "alter table public.mentor_plans enable trigger trg_mp_set_updated", "-- ── 8. 적용 직후 자가 검증 ─────────────────────────────────────────────────────\ndo $$\ndeclare\n  v_n integer;\n  v_def text;\nbegin\n  if public.subscription_cap_weight(''limited'') <> 1.0\n     or public.subscription_cap_weight(''standard'') <> 2.25\n     or public.subscription_cap_weight(''premium'') <> 4.75 then\n    raise exception ''190_SELFCHECK: 가중치 불일치'';\n  end if;\n  if public.mentor_cap_limit(''00000000-0000-0000-0000-000000000000''::uuid) <> 50 then\n    raise exception ''190_SELFCHECK: mentor_cap_limit 폴백이 50 이 아니다'';\n  end if;\n  select count(*) into v_n from public.mentor_profiles where cap_limit = 28;\n  if v_n > 0 then\n    raise exception ''190_SELFCHECK: cap_limit = 28 인 행이 % 건 남아 있다'', v_n;\n  end if;\n  select column_default into v_def from information_schema.columns\n   where table_schema = ''public'' and table_name = ''mentor_profiles'' and column_name = ''cap_limit'';\n  if v_def is distinct from ''50'' then\n    raise exception ''190_SELFCHECK: cap_limit 기본값이 50 이 아니다(%)'', v_def;\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''public'' and p.proname = ''enforce_mentor_profile_privileged_guard''\n                    and p.prosrc like ''%IS DISTINCT FROM 50%'' and p.prosrc not like ''%IS DISTINCT FROM 28%''\n                    and p.prosecdef\n                    and (p.proacl IS NULL OR (p.proacl::text NOT LIKE ''{=%'' AND p.proacl::text NOT LIKE ''%,=%''))) then\n    raise exception ''190_SELFCHECK: 특권 가드 본문/ACL 불일치'';\n  end if;\n  select pg_get_triggerdef(t.oid) into v_def from pg_trigger t\n   where t.tgname = ''trg_mentor_profile_privileged_guard_ins'' and t.tgrelid = ''public.mentor_profiles''::regclass;\n  if v_def is null or v_def not like ''%IS DISTINCT FROM (50)::numeric%'' then\n    raise exception ''190_SELFCHECK: INSERT 가드 트리거 WHEN 절이 50 이 아니다(%)'', v_def;\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''api_web_v1'' and p.proname = ''mentor_plan_prices_set_self''\n                    and p.prosrc like ''%public.subscription_cap_weight(''''premium'''')%''\n                    and p.prosrc not like ''%ARRAY[1.0, 2.5, 4.5]%''\n                    and p.prosecdef\n                    and NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n                    and has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n                    and has_function_privilege(''service_role'', p.oid, ''EXECUTE'')) then\n    raise exception ''190_SELFCHECK: F8 본문/ACL 불일치'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''public'' and p.proname = ''mp_seed_default_plans_on_approval''\n                    and p.prosrc like ''%public.subscription_cap_weight(''''standard'''')%''\n                    and NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n                    and NOT has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')) then\n    raise exception ''190_SELFCHECK: 시드 함수 본문/ACL 불일치'';\n  end if;\n  select count(*) into v_n from public.mentor_plans mp\n   where lower(coalesce(mp.plan_tier, '''')) in (''limited'', ''standard'', ''premium'')\n     and mp.cap_weight is distinct from public.subscription_cap_weight(mp.plan_tier);\n  if v_n > 0 then\n    raise exception ''190_SELFCHECK: mentor_plans.cap_weight 가 함수값과 다른 행 % 건'', v_n;\n  end if;\n  if exists (select 1 from pg_trigger where tgname in (''trg_mentor_profiles_set_updated'', ''trg_mp_set_updated'')\n               and tgenabled <> ''O'') then\n    raise exception ''190_SELFCHECK: updated_at 트리거가 다시 켜지지 않았다'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "dispute_split_fee_from_settlement", "version": "20260903100200", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 191_dispute_split_fee_from_settlement.sql  (2026-09-03 · DB-1 묶음 C — 분쟁 분배 수수료)\n--\n-- Purpose: record_custom_order_dispute_split 의 내부 상수 `v_fee_rate := 0.05` 를 제거하고\n--   해당 주문의 정산 행 `custom_order_settlement_items.fee_rate` 를 읽는다(PR-1b 원칙 완성 —\n--   요율 정본은 DB 정산 행. 웹 미리보기(disputeConsole.buildDisputeSplitPreview)도 같은 행을 읽는다).\n--   정산 행이 없거나 fee_rate 가 NULL 이면 `SETTLEMENT_FEE_RATE_MISSING` 예외 — 추측하지 않는다.\n--   반환 jsonb 의 ''fee_rate'' 키(적용 요율 — PR-1b 감사 로그 기록)는 유지하며 값이 정산 행 요율이 된다.\n--\n-- Base: supabase/sql/125_dispute_split_fee_5pct.sql 본문(운영 실행본 def md5 c60df394… 과 동일 로직).\n--   이후 이 함수를 재정의한 migration 없음.\n-- 변경 없음: 시그니처(uuid, integer, integer, uuid) · SECURITY DEFINER · search_path public · 계산 순서 ·\n--   반올림(floor) · 멱등키 · 원장 사유/참조 · 상태 전이 · 반환 계약 · ACL(service_role 전용).\n-- 변경 3곳: ① v_fee_rate 초기값 제거 + v_settlement_found 선언 ② 정산 행 SELECT 직후 found 보존 +\n--   요율 부재 예외 + v_fee_rate := s.fee_rate ③ COMMENT 문구. (기존 `if found then` 게이트는 손대지 않는다.)\n--   요율 게이트는 멱등 noop 분기보다 앞이다 — 이미 분배된 주문은 정산 행이 반드시 있으므로(분배 시\n--   ESCROW_HOLD_AMOUNT_MISMATCH 게이트 통과 = 정산 행 존재) 재호출 noop 동작은 그대로다.\n--\n-- 운영 영향: 분쟁 0건 · 기존 정산 행 fee_rate NULL 0건(컬럼 NOT NULL · default 0.05).\n-- Apply: 저장소 표준 경로(db-apply-pending) — 즉석 실행 금지.\n--   pack 등재: supabase/baseline/post_ledger_backfills/20260903100200_dispute_split_fee_from_settlement.sql\n-- Rollback: supabase/rollback/20260903100200_dispute_split_fee_from_settlement_rollback.sql (125 본문 복원)\n-- 검증(§5): select prosrc like ''%0.05%'' as 상수잔존 from pg_proc where proname=''record_custom_order_dispute_split'';  → false\n-- =============================================================================\n\nbegin", "-- ── 0. 사전 게이트 — 125 본문(상수 0.05)이 실재해야 한다 ────────────────────────\ndo $$\ndeclare v_src text;\nbegin\n  select p.prosrc into v_src\n    from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''public'' and p.proname = ''record_custom_order_dispute_split''\n     and pg_get_function_identity_arguments(p.oid) = ''p_order_id uuid, p_mentor_gross_won integer, p_student_refund_won integer, p_admin_id uuid'';\n  if v_src is null then\n    raise exception ''191_GATE: record_custom_order_dispute_split(uuid, integer, integer, uuid) 부재'';\n  end if;\n  if v_src not like ''%v_fee_rate numeric := 0.05;%'' then\n    raise exception ''191_GATE: 내부 상수 `v_fee_rate numeric := 0.05` 를 찾지 못했다 — 이미 적용됐거나 125 전제 불일치'';\n  end if;\nend $$", "-- ── 1. 재정의 — 125 본문 + 요율을 정산 행에서 ──────────────────────────────────\nCREATE OR REPLACE FUNCTION public.record_custom_order_dispute_split(p_order_id uuid, p_mentor_gross_won integer, p_student_refund_won integer, p_admin_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  o public.custom_request_orders%rowtype;\n  s public.custom_order_settlement_items%rowtype;\n  v_hold_idem text := ''cr_hold_'' || p_order_id::text;\n  v_payout_idem text := ''cr_payout_'' || p_order_id::text;\n  v_refund_idem text := ''cr_refund_'' || p_order_id::text;\n  v_dispute_payout_idem text := ''cr_dispute_payout_'' || p_order_id::text;\n  v_dispute_refund_idem text := ''cr_dispute_refund_'' || p_order_id::text;\n  v_hold_cents bigint;\n  v_hold_gross_won integer;\n  v_settlement_gross integer;\n  v_fee_rate numeric;                 -- 191: 정산 행(custom_order_settlement_items.fee_rate)에서 읽는다 — 내부 상수 없음\n  v_settlement_found boolean := false;\n  v_platform_fee_won integer;\n  v_mentor_net_won integer;\n  v_mentor_cents bigint;\n  v_student_cents bigint;\n  v_pay text;\n  v_norm text;\n  v_admin_ok boolean;\n  v_new_mentor_ledger uuid;\n  v_new_student_ledger uuid;\n  v_wu int;\n  v_now timestamptz := now();\n  v_disputes_resolved int := 0;\nbegin\n  if p_order_id is null then\n    raise exception ''p_order_id is required'';\n  end if;\n  if p_admin_id is null then\n    raise exception ''ADMIN_REQUIRED'';\n  end if;\n  if p_mentor_gross_won is null or p_student_refund_won is null then\n    raise exception ''DISPUTE_SPLIT_AMOUNTS_REQUIRED'';\n  end if;\n  if p_mentor_gross_won < 0 or p_student_refund_won < 0 then\n    raise exception ''DISPUTE_SPLIT_AMOUNTS_INVALID'';\n  end if;\n\n  select exists(\n    select 1 from public.users u where u.id = p_admin_id and u.role = ''admin''\n  ) into v_admin_ok;\n  if not coalesce(v_admin_ok, false) then\n    raise exception ''ADMIN_REQUIRED'';\n  end if;\n\n  select * into o\n  from public.custom_request_orders\n  where id = p_order_id\n  for update;\n\n  if not found then\n    raise exception ''ORDER_NOT_FOUND'';\n  end if;\n\n  if o.student_id is null or o.mentor_id is null then\n    raise exception ''ORDER_PARTIES_MISSING'';\n  end if;\n\n  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''''), '''')));\n  v_norm := public._order_primary_status_norm(o);\n\n  -- payout / refund / dispute-split 상호 배타\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key = v_payout_idem\n      and l.reason = ''custom_order_escrow_payout''\n  ) then\n    raise exception ''ALREADY_PAID_OUT'';\n  end if;\n\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key = v_refund_idem\n      and l.reason = ''custom_order_escrow_refund''\n  ) then\n    raise exception ''ALREADY_REFUNDED'';\n  end if;\n\n  select * into s\n  from public.custom_order_settlement_items\n  where custom_request_order_id = p_order_id\n  for update;\n  v_settlement_found := found;\n\n  if v_settlement_found and s.status = ''paid'' then\n    raise exception ''ALREADY_PAID_OUT'';\n  end if;\n\n  -- 191: 플랫폼 수수료율은 해당 주문의 정산 행 요율만 쓴다. 정산 행이 없거나 요율이 NULL 이면\n  --      추측하지 않고 예외(부분 반영 0 — 트랜잭션 전체 rollback).\n  if not v_settlement_found or s.fee_rate is null then\n    raise exception ''SETTLEMENT_FEE_RATE_MISSING'';\n  end if;\n  v_fee_rate := s.fee_rate;\n\n  select abs(l.delta_cents) into v_hold_cents\n  from public.cash_ledger l\n  where l.idempotency_key = v_hold_idem\n    and l.reason = ''custom_order_escrow_hold''\n  limit 1;\n\n  if v_hold_cents is null then\n    raise exception ''ESCROW_HOLD_MISSING'';\n  end if;\n\n  if v_hold_cents <= 0 or v_hold_cents > 1000000000 then\n    raise exception ''ESCROW_HOLD_AMOUNT_INVALID'';\n  end if;\n\n  if v_hold_cents % 100 <> 0 then\n    raise exception ''ESCROW_HOLD_AMOUNT_INVALID'';\n  end if;\n\n  v_hold_gross_won := (v_hold_cents / 100)::integer;\n\n  if found then\n    v_settlement_gross := s.gross_amount;\n    if v_settlement_gross is distinct from v_hold_gross_won then\n      raise exception ''ESCROW_HOLD_AMOUNT_MISMATCH'';\n    end if;\n  end if;\n\n  -- 멱등: 분배 ledger 가 하나라도 있으면 상태 수리 후 종료\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key in (v_dispute_payout_idem, v_dispute_refund_idem)\n      and l.reason in (''custom_order_dispute_payout'', ''custom_order_dispute_refund'')\n  ) then\n    update public.custom_order_settlement_items\n    set status = ''cancelled'', updated_at = v_now\n    where custom_request_order_id = p_order_id\n      and status in (''pending'', ''on_hold'', ''payable'');\n\n    update public.custom_request_orders\n    set\n      payment_status = ''dispute_resolved'',\n      status = ''dispute_resolved'',\n      state = ''dispute_resolved'',\n      order_status = ''dispute_resolved'',\n      updated_at = v_now\n    where id = p_order_id;\n\n    update public.disputes d\n    set\n      status = ''resolved'',\n      resolved_at = coalesce(d.resolved_at, v_now),\n      resolved_by = coalesce(d.resolved_by, p_admin_id),\n      updated_at = v_now\n    where d.custom_request_order_id = p_order_id\n      and d.status in (''open'', ''under_review'', ''escalated'');\n\n    get diagnostics v_disputes_resolved = row_count;\n\n    return jsonb_build_object(\n      ''ok'', true,\n      ''noop'', true,\n      ''order_id'', p_order_id,\n      ''hold_gross_won'', v_hold_gross_won,\n      ''disputes_resolved'', v_disputes_resolved\n    );\n  end if;\n\n  if p_mentor_gross_won + p_student_refund_won is distinct from v_hold_gross_won then\n    raise exception ''DISPUTE_SPLIT_MISMATCH'';\n  end if;\n\n  if v_pay not in (''escrowed'', ''dispute_resolved'') then\n    raise exception ''PAYMENT_NOT_ESCROWED'';\n  end if;\n\n  v_platform_fee_won := floor(p_mentor_gross_won * v_fee_rate)::integer;\n  v_mentor_net_won := p_mentor_gross_won - v_platform_fee_won;\n  v_mentor_cents := v_mentor_net_won::bigint * 100;\n  v_student_cents := p_student_refund_won::bigint * 100;\n\n  if v_mentor_cents > 1000000000 or v_student_cents > 1000000000 then\n    raise exception ''p_amount_too_large'';\n  end if;\n\n  if v_mentor_cents > 0 then\n    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n    values (\n      o.mentor_id,\n      v_mentor_cents,\n      ''custom_order_dispute_payout'',\n      ''custom_request_orders'',\n      p_order_id,\n      v_dispute_payout_idem\n    )\n    on conflict (idempotency_key) do nothing\n    returning id into v_new_mentor_ledger;\n\n    if v_new_mentor_ledger is not null then\n      insert into public.cash_wallets (user_id, balance_cents)\n      values (o.mentor_id, 0)\n      on conflict (user_id) do nothing;\n\n      update public.cash_wallets w\n      set balance_cents = w.balance_cents + v_mentor_cents\n      where w.user_id = o.mentor_id;\n      get diagnostics v_wu = row_count;\n      if coalesce(v_wu, 0) = 0 then\n        raise exception ''CASH_WALLET_UPDATE_FAILED'' using errcode = ''P0001'';\n      end if;\n    end if;\n  end if;\n\n  if v_student_cents > 0 then\n    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n    values (\n      o.student_id,\n      v_student_cents,\n      ''custom_order_dispute_refund'',\n      ''custom_request_orders'',\n      p_order_id,\n      v_dispute_refund_idem\n    )\n    on conflict (idempotency_key) do nothing\n    returning id into v_new_student_ledger;\n\n    if v_new_student_ledger is not null then\n      insert into public.cash_wallets (user_id, balance_cents)\n      values (o.student_id, 0)\n      on conflict (user_id) do nothing;\n\n      update public.cash_wallets w\n      set balance_cents = w.balance_cents + v_student_cents\n      where w.user_id = o.student_id;\n      get diagnostics v_wu = row_count;\n      if coalesce(v_wu, 0) = 0 then\n        raise exception ''CASH_WALLET_UPDATE_FAILED'' using errcode = ''P0001'';\n      end if;\n    end if;\n  end if;\n\n  update public.custom_order_settlement_items\n  set status = ''cancelled'', updated_at = v_now\n  where custom_request_order_id = p_order_id\n    and status in (''pending'', ''on_hold'', ''payable'');\n\n  update public.custom_request_orders\n  set\n    payment_status = ''dispute_resolved'',\n    status = ''dispute_resolved'',\n    state = ''dispute_resolved'',\n    order_status = ''dispute_resolved'',\n    updated_at = v_now\n  where id = p_order_id;\n\n  update public.disputes d\n  set\n    status = ''resolved'',\n    resolved_at = coalesce(d.resolved_at, v_now),\n    resolved_by = coalesce(d.resolved_by, p_admin_id),\n    updated_at = v_now\n  where d.custom_request_order_id = p_order_id\n    and d.status in (''open'', ''under_review'', ''escalated'');\n\n  get diagnostics v_disputes_resolved = row_count;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''noop'', false,\n    ''order_id'', p_order_id,\n    ''hold_gross_won'', v_hold_gross_won,\n    ''mentor_gross_won'', p_mentor_gross_won,\n    ''mentor_platform_fee_won'', v_platform_fee_won,\n    ''mentor_net_won'', v_mentor_net_won,\n    ''mentor_cents'', v_mentor_cents,\n    ''student_refund_won'', p_student_refund_won,\n    ''student_cents'', v_student_cents,\n    ''fee_rate'', v_fee_rate,\n    ''disputes_resolved'', v_disputes_resolved\n  );\nend;\n$function$", "-- ── 2. COMMENT · ACL 재확정(멱등 — service_role 전용) ──────────────────────────\ncomment on function public.record_custom_order_dispute_split(\n  uuid, integer, integer, uuid\n) is\n  ''P0: Custom order dispute escrow split — mentor net (gross − settlement fee_rate) + student refund; hold gross must match sum. 191: fee_rate from custom_order_settlement_items (SETTLEMENT_FEE_RATE_MISSING if absent). service_role only.''", "revoke all on function public.record_custom_order_dispute_split(\n  uuid, integer, integer, uuid\n) from public, anon, authenticated", "grant execute on function public.record_custom_order_dispute_split(\n  uuid, integer, integer, uuid\n) to service_role", "-- ── 3. 적용 직후 자가 검증 ─────────────────────────────────────────────────────\ndo $$\nbegin\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''public'' and p.proname = ''record_custom_order_dispute_split''\n                    and p.prosecdef and p.proconfig::text like ''%search_path=%''\n                    and p.prosrc not like ''%0.05%''\n                    and p.prosrc like ''%SETTLEMENT_FEE_RATE_MISSING%''\n                    and p.prosrc like ''%v_fee_rate := s.fee_rate;%''\n                    and NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n                    and NOT has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n                    and has_function_privilege(''service_role'', p.oid, ''EXECUTE'')\n                    and (p.proacl IS NULL OR (p.proacl::text NOT LIKE ''{=%'' AND p.proacl::text NOT LIKE ''%,=%''))) then\n    raise exception ''191_SELFCHECK: 본문/ACL 불일치'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "school_verification_provisional_rule", "version": "20260903100300", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 192_school_verification_provisional_rule.sql  (2026-09-03 · DB-1 묶음 B — 학교 인증 규칙 ★)\n--\n-- 원칙: \"잠정\" = reviewed_by IS NULL. 자동 판정은 pending 으로 만들고, 관리자가 확정해야 approved 가 된다.\n--\n-- B-1 기존 건 일괄 확정 (오너 결정 2026-09-03): status=''approved'' · reviewed_by IS NULL · 멘토 프로필\n--     verification_status=''approved'' 인 행 전부에 reviewed_by = 9bf48819-1dd2-40dd-96a3-d64bcca2e60c\n--     (byite1226@gmail.com) · reviewed_at = now(). 승인 대기(pending) 멘토는 조건으로 자연히 제외된다.\n--     admin_action_logs 에 1건 기록(action_type = school_verification_bulk_confirmed · detail.count).\n--     적용 전 실측(2026-09-03 운영 read-only): 대상 67건 · 이미 확정 6건 · superseded 1건 · 대기 멘토 행 0건.\n-- B-2 트리거: tmp_auto_school_verification / trg_tmp_auto_school_verification 을 auto_school_verification /\n--     trg_auto_school_verification 으로 교체(더 이상 임시가 아니다). 생성 행 status ''approved'' → ''pending'' ·\n--     reviewed_by/at NULL · verified/active 동의어 분기 제거(approved 만) · LIKE 매칭 로직은 헬퍼 2종\n--     (school_tier_suggest · major_category_suggest)으로 분리해 B-4 와 공유(같은 규칙).\n-- B-3 RPC approve_mentor_school_verification_admin: 허용 status = pending / resubmit_required /\n--     (approved AND reviewed_by IS NULL). 서류 유무·경로·객체 실재 조건 제거(서류는 판단 재료 — 화면이\n--     ''서류 없음''을 보여준다). 확정 시 status approved · reviewed_by/at · 등급·계열은 관리자가 넘긴 값.\n--     is_admin() 게이트 · mentor 단위 advisory lock · 재승인 승계(superseded) · 반환 계약 · ACL 불변.\n-- B-4 학적 변경 재판정: mentor_profiles.university_name / department_name 이 실제로 바뀌면\n--     (IS DISTINCT FROM) 그 멘토의 approved·pending 행을 같은 LIKE 규칙으로 재판정하고 status ''pending'' ·\n--     reviewed_by/at NULL 로 되돌린다. approved 멘토인데 approved·pending 행이 하나도 없으면 pending 행을 새로 만든다.\n--\n-- 의도된 비용(오너 확인): 새로 승인되는 멘토·학적이 바뀐 멘토는 관리자가 PR-2 화면에서 등급을 확정하기\n--   전까지 개별질문 등급 필터에서 빠진다.\n-- 참고: 멘토 자기 프로필 편집(F7 mentor_profile_update_self)으로 학교/학과가 바뀌어도 B-4 가 돈다. 이때는\n--   호출자 JWT 가 멘토 본인이라 077 guard_self_review 가 verified_* 제안값을 NULL 로 비우지만, 상태는\n--   똑같이 pending · reviewed_by NULL(잠정)이 된다 — 관리자 확정 흐름은 동일.\n--\n-- Apply: 저장소 표준 경로(db-apply-pending) — 즉석 실행 금지. 적용 순서 A(190) → C(191) → B(192).\n--   ★ B-1 은 데이터 변경이다 — 적용 직전 `select * from mentor_school_verifications` 전체 덤프를 PR 코멘트에 남긴다.\n--   pack 등재: supabase/baseline/post_ledger_backfills/20260903100300_school_verification_provisional_rule.sql\n-- Rollback: supabase/rollback/20260903100300_school_verification_provisional_rule_rollback.sql\n-- 검증(§5): select status, (reviewed_by is null) as 미확정, count(*) from mentor_school_verifications group by 1,2;\n--           select tgname from pg_trigger where tgname like ''%school_verification%'';\n-- =============================================================================\n\nbegin", "-- ── 0. 사전 게이트 — 예상 상태와 다르면 중단(임의 정정 금지) ──────────────────\ndo $$\ndeclare\n  v_rpc_src text;\n  v_check   text;\nbegin\n  if not exists (select 1 from pg_trigger where tgname = ''trg_tmp_auto_school_verification''\n                   and tgrelid = ''public.mentor_profiles''::regclass) then\n    raise exception ''192_GATE: trg_tmp_auto_school_verification 부재 — 이미 적용됐거나 20260830150838 전제 불일치'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''public'' and p.proname = ''tmp_auto_school_verification'') then\n    raise exception ''192_GATE: tmp_auto_school_verification() 부재'';\n  end if;\n\n  select p.prosrc into v_rpc_src\n    from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''public'' and p.proname = ''approve_mentor_school_verification_admin''\n     and pg_get_function_identity_arguments(p.oid) =\n         ''p_verification_id uuid, p_university_name text, p_university_id text, p_department_name text, p_major_category text, p_school_tier text'';\n  if v_rpc_src is null then\n    raise exception ''192_GATE: approve_mentor_school_verification_admin(uuid, text ×5) 부재'';\n  end if;\n  if v_rpc_src not like ''%not in (''''pending'''', ''''resubmit_required'''')%'' or v_rpc_src not like ''%DOCUMENT_REF_MISSING%'' then\n    raise exception ''192_GATE: RPC 본문이 174 형태가 아니다(이미 적용됐거나 전제 불일치)'';\n  end if;\n\n  select pg_get_constraintdef(c.oid) into v_check\n    from pg_constraint c\n   where c.conrelid = ''public.mentor_school_verifications''::regclass\n     and c.conname = ''mentor_school_verifications_status_check'';\n  if v_check is null or v_check not like ''%pending%'' or v_check not like ''%approved%'' or v_check not like ''%superseded%'' then\n    raise exception ''192_GATE: status CHECK 정의가 예상과 다르다(%)'', v_check;\n  end if;\n  if not exists (select 1 from pg_indexes where schemaname = ''public''\n                   and tablename = ''mentor_school_verifications'' and indexname = ''uq_msv_one_approved_per_mentor'') then\n    raise exception ''192_GATE: uq_msv_one_approved_per_mentor 부재(174 전제)'';\n  end if;\nend $$", "-- ── B-1. 기존 자동 판정 건 일괄 확정 ────────────────────────────────────────────\ndo $$\ndeclare\n  v_admin   constant uuid := ''9bf48819-1dd2-40dd-96a3-d64bcca2e60c'';  -- byite1226@gmail.com (오너 지정)\n  v_target  integer;\n  v_updated integer;\n  v_now     timestamptz := now();\nbegin\n  select count(*) into v_target\n    from public.mentor_school_verifications v\n    join public.mentor_profiles p on p.user_id = v.mentor_id\n   where v.status = ''approved''\n     and v.reviewed_by is null\n     and p.verification_status = ''approved'';\n\n  if v_target = 0 then\n    raise notice ''192 B-1: 일괄 확정 대상 0건 — 건너뜀(로그 미기록)'';\n    return;\n  end if;\n\n  -- 대상이 있으면 확정 주체가 실재하는 admin 이어야 한다. 아니면 확정하지 않고 중단(추측 금지).\n  if not exists (select 1 from public.users u where u.id = v_admin and u.role = ''admin'') then\n    raise exception ''192_ABORT: 일괄 확정 admin 계정 % 이 public.users 에 admin 으로 없다 — 대상 % 건을 확정하지 않고 중단'', v_admin, v_target;\n  end if;\n  if not exists (select 1 from auth.users au where au.id = v_admin) then\n    raise exception ''192_ABORT: 일괄 확정 admin 계정 % 이 auth.users 에 없다(admin_action_logs FK) — 중단'', v_admin;\n  end if;\n\n  update public.mentor_school_verifications v\n     set reviewed_by = v_admin,\n         reviewed_at = v_now\n    from public.mentor_profiles p\n   where v.mentor_id = p.user_id\n     and v.status = ''approved''\n     and v.reviewed_by is null\n     and p.verification_status = ''approved'';\n  get diagnostics v_updated = row_count;\n\n  if v_updated <> v_target then\n    raise exception ''192_ABORT: 일괄 확정 대상 % 건 ≠ 갱신 % 건'', v_target, v_updated;\n  end if;\n\n  insert into public.admin_action_logs (admin_id, action_type, target_type, target_id, detail, created_at)\n  values (\n    v_admin,\n    ''school_verification_bulk_confirmed'',\n    ''mentor_school_verification'',\n    null,\n    jsonb_build_object(\n      ''count'', v_updated,\n      ''note'', ''2026-09-03 오너 결정에 따른 자동 판정 건 일괄 확정'',\n      ''rule'', ''mentor_school_verifications.status = approved AND reviewed_by IS NULL AND mentor_profiles.verification_status = approved'',\n      ''reviewed_at'', v_now,\n      ''migration'', ''20260903100300_school_verification_provisional_rule''\n    ),\n    v_now\n  );\n  raise notice ''192 B-1: % 건 일괄 확정 (reviewed_by = %, reviewed_at = %)'', v_updated, v_admin, v_now;\nend $$", "-- ── B-2a. 판정 규칙 헬퍼 — 20260830150838 의 LIKE 규칙을 그대로 분리(B-2·B-4 공유) ──\ncreate or replace function public.school_tier_suggest(p_university_name text)\nreturns text\nlanguage sql\nimmutable\nset search_path = public\nas $$\n  select case\n    when p_university_name like ''서울대%'' or p_university_name like ''연세대%'' or p_university_name like ''고려대%''\n      then ''서연고''\n    when p_university_name like ''서강대%'' or p_university_name like ''성균관대%'' or p_university_name like ''한양대%''\n      then ''서성한''\n    when p_university_name like ''중앙대%'' or p_university_name like ''경희대%''\n      or p_university_name like ''한국외%'' or p_university_name like ''서울시립대%''\n      then ''중경외시''\n    when p_university_name like ''건국대%'' or p_university_name like ''동국대%'' or p_university_name like ''홍익대%''\n      then ''건동홍''\n    else ''미분류''\n  end;\n$$", "comment on function public.school_tier_suggest(text) is\n  ''192: 대학명 → 학교군 제안값(자동 판정 · 잠정). 정본 확정은 관리자 RPC. 규칙은 20260830150838 과 동일.''", "create or replace function public.major_category_suggest(p_department_name text)\nreturns text\nlanguage sql\nimmutable\nset search_path = public\nas $$\n  select case\n    when p_department_name like ''%의예%'' or p_department_name like ''%의학%''\n      or p_department_name like ''%치의%'' or p_department_name like ''%약학%'' or p_department_name like ''%한의%''\n      or p_department_name like ''%수의%'' or p_department_name like ''%간호%''\n      then ''메디컬''\n    when p_department_name like ''%교육%'' then ''교육''\n    when p_department_name like ''%국어국문%'' or p_department_name like ''%문헌정보%''\n      or p_department_name like ''%철학%'' or p_department_name like ''%사학%'' or p_department_name like ''%어문%''\n      then ''인문''\n    when p_department_name like ''%경영%'' or p_department_name like ''%경제%''\n      or p_department_name like ''%미디어%'' or p_department_name like ''%정치%'' or p_department_name like ''%사회학%''\n      or p_department_name like ''%행정%'' or p_department_name like ''%심리%''\n      then ''사회상경''\n    when p_department_name like ''%수학%'' or p_department_name like ''%물리%''\n      or p_department_name like ''%화학%'' or p_department_name like ''%생명%'' or p_department_name like ''%통계%''\n      then ''자연''\n    when p_department_name like ''%공학%'' or p_department_name like ''%컴퓨터%''\n      or p_department_name like ''%전자%'' or p_department_name like ''%기계%'' or p_department_name like ''%소프트웨어%''\n      or p_department_name like ''%모빌리티%'' or p_department_name like ''%융합%''\n      then ''공학''\n    when p_department_name like ''%음악%'' or p_department_name like ''%미술%''\n      or p_department_name like ''%체육%'' or p_department_name like ''%디자인%''\n      then ''예체능''\n    else ''기타''\n  end;\n$$", "comment on function public.major_category_suggest(text) is\n  ''192: 학과명 → 전공 계열 제안값(자동 판정 · 잠정). 정본 확정은 관리자 RPC. 규칙은 20260830150838 과 동일.''", "revoke all on function public.school_tier_suggest(text) from public, anon, authenticated", "revoke all on function public.major_category_suggest(text) from public, anon, authenticated", "-- ── B-2b. 자동 생성 트리거 — tmp_ 제거 · pending · approved 만 ───────────────────\ndrop trigger if exists trg_tmp_auto_school_verification on public.mentor_profiles", "drop function if exists public.tmp_auto_school_verification()", "create or replace function public.auto_school_verification()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if new.verification_status = ''approved'' then\n    insert into public.mentor_school_verifications\n      (mentor_id, status, verified_university_name, verified_department_name,\n       school_tier, verified_major_category, reviewed_by, reviewed_at)\n    select\n      new.user_id,\n      ''pending'',\n      nullif(trim(new.university_name), ''''),\n      nullif(trim(new.department_name), ''''),\n      public.school_tier_suggest(new.university_name),\n      public.major_category_suggest(new.department_name),\n      null,\n      null\n    where not exists (\n      select 1 from public.mentor_school_verifications v\n      where v.mentor_id = new.user_id and v.status in (''pending'', ''approved'')\n    );\n  end if;\n  return new;\nend;\n$$", "comment on function public.auto_school_verification() is\n  ''192: 멘토 승인(verification_status = approved) 시 학교·전공 인증 행을 pending(잠정 · reviewed_by NULL)으로 자동 생성 — 등급·계열은 제안값. 관리자가 approve_mentor_school_verification_admin 으로 확정해야 approved.''", "revoke all on function public.auto_school_verification() from public, anon, authenticated", "drop trigger if exists trg_auto_school_verification on public.mentor_profiles", "create trigger trg_auto_school_verification\n  after insert or update of verification_status on public.mentor_profiles\n  for each row execute function public.auto_school_verification()", "-- ── B-3. 확정 RPC — 잠정 approved 행 허용 · 서류 조건 제거 (174 본문 그 외 동일) ──\ncreate or replace function public.approve_mentor_school_verification_admin(\n  p_verification_id uuid,\n  p_university_name text,\n  p_university_id text,\n  p_department_name text,\n  p_major_category text,\n  p_school_tier text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_admin uuid := (select auth.uid());\n  v_row public.mentor_school_verifications;\n  v_superseded integer := 0;\nbegin\n  -- (a) 관리자 전용. mentor·student·anon 은 여기서 종료된다.\n  if not coalesce(public.is_admin(), false) then\n    raise exception ''NOT_ADMIN'' using errcode = ''42501'';\n  end if;\n\n  if p_verification_id is null then\n    raise exception ''INVALID_INPUT: verification_id is required'' using errcode = ''22023'';\n  end if;\n  if btrim(coalesce(p_university_name, '''')) = ''''\n     or btrim(coalesce(p_university_id, '''')) = ''''\n     or btrim(coalesce(p_department_name, '''')) = ''''\n     or btrim(coalesce(p_major_category, '''')) = ''''\n     or btrim(coalesce(p_school_tier, '''')) = '''' then\n    raise exception ''INVALID_INPUT: university/department/major/tier are required'' using errcode = ''22023'';\n  end if;\n\n  -- (b) mentor 단위 직렬화 — 같은 멘토의 서로 다른 요청이 동시에 승인되지 않도록.\n  select * into v_row from public.mentor_school_verifications where id = p_verification_id;\n  if not found then\n    raise exception ''VERIFICATION_NOT_FOUND'' using errcode = ''P0002'';\n  end if;\n  perform pg_advisory_xact_lock(hashtextextended(''msv_approve:'' || v_row.mentor_id::text, 0));\n\n  -- 락 획득 후 재조회(대기 중 다른 트랜잭션이 상태를 바꿨을 수 있다).\n  select * into v_row from public.mentor_school_verifications\n   where id = p_verification_id for update;\n  -- 192: 확정 가능 = 심사 대상(pending·resubmit_required) 또는 잠정 승인(approved + reviewed_by IS NULL).\n  if not (v_row.status in (''pending'', ''resubmit_required'')\n          or (v_row.status = ''approved'' and v_row.reviewed_by is null)) then\n    raise exception ''NOT_REVIEWABLE: %'', v_row.status using errcode = ''22023'';\n  end if;\n\n  -- (c) 192: 서류 유무·경로·객체 실재는 확정 조건이 아니다 — 서류는 판단 재료이며 화면이 ''서류 없음''을 보여준다.\n\n  -- (d) 재승인 수명주기 — 같은 트랜잭션에서 기존 approved 를 먼저 종료시킨다.\n  update public.mentor_school_verifications\n     set status = ''superseded'',\n         updated_at = now()\n   where mentor_id = v_row.mentor_id\n     and status = ''approved''\n     and id <> v_row.id;\n  get diagnostics v_superseded = row_count;\n\n  -- (e) 대상 행 확정.\n  update public.mentor_school_verifications\n     set status = ''approved'',\n         verified_university_name = btrim(p_university_name),\n         verified_university_id = btrim(p_university_id),\n         verified_department_name = btrim(p_department_name),\n         verified_major_category = btrim(p_major_category),\n         school_tier = btrim(p_school_tier),\n         reviewed_by = v_admin,\n         reviewed_at = now(),\n         reject_reason = null\n   where id = v_row.id;\n\n  -- 감사 가능 최소 정보만 반환한다(서류 내용·signed URL·토큰 미포함).\n  return jsonb_build_object(\n    ''verification_id'', v_row.id,\n    ''mentor_id'', v_row.mentor_id,\n    ''status'', ''approved'',\n    ''superseded_count'', v_superseded,\n    ''reviewed_by'', v_admin\n  );\nend;\n$$", "comment on function public.approve_mentor_school_verification_admin(uuid, text, text, text, text, text) is\n  ''SQL174 → 192: 학교·전공 인증 확정 정본. is_admin() 전용 · 확정 가능 = pending / resubmit_required / (approved AND reviewed_by IS NULL) · 서류 조건 없음 · 재승인 시 기존 approved → superseded 를 같은 트랜잭션에서 수행. 실패는 전부 예외(부분 반영 없음).''", "revoke all on function public.approve_mentor_school_verification_admin(uuid, text, text, text, text, text) from public", "revoke all on function public.approve_mentor_school_verification_admin(uuid, text, text, text, text, text) from anon", "grant execute on function public.approve_mentor_school_verification_admin(uuid, text, text, text, text, text)\n  to authenticated, service_role", "-- ── B-4. 학적 변경 시 재판정(잠정으로 되돌림) ───────────────────────────────────\ncreate or replace function public.school_verification_reassess_on_academic_change()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_tier text := public.school_tier_suggest(new.university_name);\n  v_cat  text := public.major_category_suggest(new.department_name);\n  v_n    integer := 0;\nbegin\n  update public.mentor_school_verifications v\n     set status = ''pending'',\n         school_tier = v_tier,\n         verified_major_category = v_cat,\n         verified_university_name = nullif(trim(new.university_name), ''''),\n         verified_university_id = null,\n         verified_department_name = nullif(trim(new.department_name), ''''),\n         reviewed_by = null,\n         reviewed_at = null\n   where v.mentor_id = new.user_id\n     and v.status in (''approved'', ''pending'');\n  get diagnostics v_n = row_count;\n\n  -- 승인 멘토인데 재판정할 행이 없으면(예: superseded/rejected 만 남음) 잠정 행을 새로 만든다.\n  if v_n = 0 and new.verification_status = ''approved'' then\n    insert into public.mentor_school_verifications\n      (mentor_id, status, verified_university_name, verified_department_name,\n       school_tier, verified_major_category, reviewed_by, reviewed_at)\n    values\n      (new.user_id, ''pending'',\n       nullif(trim(new.university_name), ''''), nullif(trim(new.department_name), ''''),\n       v_tier, v_cat, null, null);\n  end if;\n  return new;\nend;\n$$", "comment on function public.school_verification_reassess_on_academic_change() is\n  ''192 B-4: mentor_profiles.university_name/department_name 이 실제로 바뀌면 그 멘토의 approved·pending 인증 행을 같은 LIKE 규칙으로 재판정하고 pending(잠정 · reviewed_by NULL)으로 되돌린다. 관리자는 학적 변경 승인 후 등급을 다시 확정한다.''", "revoke all on function public.school_verification_reassess_on_academic_change() from public, anon, authenticated", "drop trigger if exists trg_school_verification_reassess_on_academic_change on public.mentor_profiles", "create trigger trg_school_verification_reassess_on_academic_change\n  after update of university_name, department_name on public.mentor_profiles\n  for each row\n  when (old.university_name is distinct from new.university_name\n        or old.department_name is distinct from new.department_name)\n  execute function public.school_verification_reassess_on_academic_change()", "-- ── 적용 직후 자가 검증 ───────────────────────────────────────────────────────\ndo $$\ndeclare v_n integer;\nbegin\n  select count(*) into v_n\n    from public.mentor_school_verifications v\n    join public.mentor_profiles p on p.user_id = v.mentor_id\n   where v.status = ''approved'' and v.reviewed_by is null and p.verification_status = ''approved'';\n  if v_n > 0 then\n    raise exception ''192_SELFCHECK: 잠정 approved 행 % 건 잔존'', v_n;\n  end if;\n\n  if exists (select 1 from pg_trigger where tgname = ''trg_tmp_auto_school_verification'')\n     or exists (select 1 from pg_proc where proname = ''tmp_auto_school_verification'') then\n    raise exception ''192_SELFCHECK: tmp_ 트리거/함수 잔존'';\n  end if;\n  if not exists (select 1 from pg_trigger where tgname = ''trg_auto_school_verification''\n                   and tgrelid = ''public.mentor_profiles''::regclass)\n     or not exists (select 1 from pg_trigger where tgname = ''trg_school_verification_reassess_on_academic_change''\n                   and tgrelid = ''public.mentor_profiles''::regclass) then\n    raise exception ''192_SELFCHECK: 신규 트리거 부재'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''public'' and p.proname = ''approve_mentor_school_verification_admin''\n                    and p.prosecdef and p.proconfig::text like ''%search_path=%''\n                    and p.prosrc like ''%v_row.reviewed_by is null%''\n                    and p.prosrc not like ''%DOCUMENT_REF_MISSING%''\n                    and NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n                    and has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n                    and has_function_privilege(''service_role'', p.oid, ''EXECUTE'')) then\n    raise exception ''192_SELFCHECK: RPC 본문/ACL 불일치'';\n  end if;\n  if public.school_tier_suggest(''성균관대학교'') <> ''서성한'' or public.school_tier_suggest(null) <> ''미분류''\n     or public.major_category_suggest(''의예과'') <> ''메디컬'' or public.major_category_suggest(null) <> ''기타'' then\n    raise exception ''192_SELFCHECK: 판정 헬퍼 규칙 불일치'';\n  end if;\n  for v_n in select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n              where n.nspname = ''public''\n                and p.proname in (''auto_school_verification'', ''school_verification_reassess_on_academic_change'',\n                                  ''school_tier_suggest'', ''major_category_suggest'')\n                and (has_function_privilege(''anon'', p.oid, ''EXECUTE'') or has_function_privilege(''authenticated'', p.oid, ''EXECUTE''))\n  loop\n    raise exception ''192_SELFCHECK: 트리거/헬퍼 함수에 anon·authenticated EXECUTE 잔존'';\n  end loop;\nend $$", "commit"], "idempotency_key": null}, {"name": "school_tier_fallback_other_and_correction", "version": "20260903200100", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 193_school_tier_fallback_other_and_correction.sql  (2026-09-03 · DB-2 묶음 A — 등급 정정 ★)\n--\n-- 오너 결정(2026-09-03): 확정된 등급도 관리자가 정정할 수 있어야 하고, 자동 판정 폴백은 ''미분류'' 가 아니라 ''그외'' 다.\n--   ''미분류'' 는 이제 **대학명을 못 읽은 경우(NULL · 공백)** 에만 남는다.\n--\n-- A-1 school_tier_suggest(): university_name NULL·공백 → ''미분류'' · LIKE 미매칭(이름은 있음) → ''그외''.\n--     LIKE 패턴 13종·순서는 192 그대로. 192 의 auto_school_verification()(승인 시 자동 생성) ·\n--     school_verification_reassess_on_academic_change()(학적 변경 재판정)가 이 함수를 호출하므로 자동 반영된다.\n-- A-2 RPC approve_mentor_school_verification_admin: 허용 status = pending / resubmit_required / approved\n--     (**approved 는 reviewed_by 유무와 무관** — 192 의 \"approved AND reviewed_by IS NULL\" 을 넓힌다).\n--     rejected · superseded 는 여전히 NOT_REVIEWABLE. 이미 확정된 approved 행(reviewed_by NOT NULL)을 다시 확정하면\n--     \"정정\" 이다: reviewed_by · reviewed_at 을 새로 채우고, 이전 값(이전 등급 · 이전 계열 · 이전 확정자 · 이전 확정 시각)을\n--     admin_action_logs(action_type = school_tier_corrected) 상세에 남긴다. 반환 jsonb 에 corrected ·\n--     previous_school_tier · previous_reviewed_by 를 additive 로 더한다(기존 키 불변 — 웹 파서는 추가 키를 무시한다).\n--     is_admin() 게이트 · mentor 단위 advisory lock · 재승인 승계(superseded) · ACL 불변.\n-- A-3 미분류 일괄 정정(오너 결정): status = approved · school_tier = ''미분류'' · verified_university_name 이 비어 있지 않은\n--     행 전부 → school_tier = ''그외'' · reviewed_by = 9bf48819-1dd2-40dd-96a3-d64bcca2e60c · reviewed_at = now().\n--     verified_major_category 는 그대로. admin_action_logs 1건(school_tier_bulk_reassigned · detail.count ·\n--     detail.note = ''폴백 규칙 변경(미분류→그외)에 따른 일괄 정정'' · detail.rows = 행별 이전 reviewed_by/at — 롤백 정본).\n--     적용 전 실측(2026-09-03 운영 read-only): 대상 19건(가천대 13 · 계명대 4 · 원광대 1 · 충북대 1) · 대학명 없는 approved\n--     행 0건 · 대상 전부 reviewed_by = 위 계정(그중 2건은 2026-08-31 · 2026-09-01 개별 확정, 17건은 192 B-1 일괄 확정).\n--\n-- Apply: 저장소 표준 경로(db-apply-pending) — 즉석 실행 금지. 적용 순서 A(193) → B(194) → C(195).\n--   ★ A-3 은 데이터 변경이다 — 적용 직전 대상 행 SELECT 덤프를 PR 코멘트에 남긴다.\n--   pack 등재: supabase/baseline/post_ledger_backfills/20260903200100_school_tier_fallback_other_and_correction.sql\n-- Rollback: supabase/rollback/20260903200100_school_tier_fallback_other_and_correction_rollback.sql\n-- 검증(§6): select school_tier, count(*) from mentor_school_verifications where status=''approved'' group by 1;\n--           select school_tier_suggest(''가천대학교''), school_tier_suggest(''''), school_tier_suggest(null);\n-- =============================================================================\n\nbegin", "-- ── 0. 사전 게이트 — 192(20260903100300) 적용 상태여야 한다. 다르면 중단(임의 정정 금지) ──\ndo $$\ndeclare\n  v_src text;\n  v_rpc text;\n  v_check text;\nbegin\n  select p.prosrc into v_src\n    from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''public'' and p.proname = ''school_tier_suggest''\n     and pg_get_function_identity_arguments(p.oid) = ''p_university_name text'';\n  if v_src is null then\n    raise exception ''193_GATE: school_tier_suggest(text) 부재 — 192 미적용'';\n  end if;\n  if v_src not like ''%else ''''미분류''''%'' or v_src like ''%''''그외''''%'' then\n    raise exception ''193_GATE: school_tier_suggest 본문이 192 형태가 아니다(이미 적용됐거나 전제 불일치)'';\n  end if;\n\n  select p.prosrc into v_rpc\n    from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''public'' and p.proname = ''approve_mentor_school_verification_admin''\n     and pg_get_function_identity_arguments(p.oid) =\n         ''p_verification_id uuid, p_university_name text, p_university_id text, p_department_name text, p_major_category text, p_school_tier text'';\n  if v_rpc is null then\n    raise exception ''193_GATE: approve_mentor_school_verification_admin(uuid, text ×5) 부재'';\n  end if;\n  if v_rpc not like ''%or (v_row.status = ''''approved'''' and v_row.reviewed_by is null)%'' or v_rpc like ''%school_tier_corrected%'' then\n    raise exception ''193_GATE: RPC 본문이 192 형태가 아니다(이미 적용됐거나 전제 불일치)'';\n  end if;\n\n  if not exists (select 1 from pg_trigger where tgname = ''trg_auto_school_verification''\n                   and tgrelid = ''public.mentor_profiles''::regclass)\n     or not exists (select 1 from pg_trigger where tgname = ''trg_school_verification_reassess_on_academic_change''\n                   and tgrelid = ''public.mentor_profiles''::regclass) then\n    raise exception ''193_GATE: 192 트리거 부재'';\n  end if;\n\n  select pg_get_constraintdef(c.oid) into v_check\n    from pg_constraint c\n   where c.conrelid = ''public.mentor_school_verifications''::regclass\n     and c.conname = ''mentor_school_verifications_school_tier_check'';\n  if v_check is null or v_check not like ''%그외%'' or v_check not like ''%미분류%'' then\n    raise exception ''193_GATE: school_tier CHECK 에 그외·미분류가 없다(%)'', v_check;\n  end if;\nend $$", "-- ── A-1. 판정 헬퍼 — 폴백 변경: NULL·공백 → 미분류 · LIKE 미매칭 → 그외 (패턴·순서 192 동일) ──\ncreate or replace function public.school_tier_suggest(p_university_name text)\nreturns text\nlanguage sql\nimmutable\nset search_path = public\nas $$\n  select case\n    when p_university_name is null or btrim(p_university_name) = ''''\n      then ''미분류''\n    when p_university_name like ''서울대%'' or p_university_name like ''연세대%'' or p_university_name like ''고려대%''\n      then ''서연고''\n    when p_university_name like ''서강대%'' or p_university_name like ''성균관대%'' or p_university_name like ''한양대%''\n      then ''서성한''\n    when p_university_name like ''중앙대%'' or p_university_name like ''경희대%''\n      or p_university_name like ''한국외%'' or p_university_name like ''서울시립대%''\n      then ''중경외시''\n    when p_university_name like ''건국대%'' or p_university_name like ''동국대%'' or p_university_name like ''홍익대%''\n      then ''건동홍''\n    else ''그외''\n  end;\n$$", "comment on function public.school_tier_suggest(text) is\n  ''192 → 193: 대학명 → 학교군 제안값(자동 판정 · 잠정). NULL·공백 → 미분류(대학명을 못 읽은 경우만) · LIKE 미매칭 → 그외. 패턴은 20260830150838 과 동일. 정본 확정은 관리자 RPC.''", "revoke all on function public.school_tier_suggest(text) from public, anon, authenticated", "-- ── A-2. 확정 RPC — approved 는 reviewed_by 유무와 무관하게 허용 · 확정된 행 재확정 = 정정(감사 로그) ──\ncreate or replace function public.approve_mentor_school_verification_admin(\n  p_verification_id uuid,\n  p_university_name text,\n  p_university_id text,\n  p_department_name text,\n  p_major_category text,\n  p_school_tier text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_admin uuid := (select auth.uid());\n  v_row public.mentor_school_verifications;\n  v_superseded integer := 0;\n  v_correction boolean := false;\n  v_previous jsonb := null;\nbegin\n  -- (a) 관리자 전용. mentor·student·anon 은 여기서 종료된다.\n  if not coalesce(public.is_admin(), false) then\n    raise exception ''NOT_ADMIN'' using errcode = ''42501'';\n  end if;\n\n  if p_verification_id is null then\n    raise exception ''INVALID_INPUT: verification_id is required'' using errcode = ''22023'';\n  end if;\n  if btrim(coalesce(p_university_name, '''')) = ''''\n     or btrim(coalesce(p_university_id, '''')) = ''''\n     or btrim(coalesce(p_department_name, '''')) = ''''\n     or btrim(coalesce(p_major_category, '''')) = ''''\n     or btrim(coalesce(p_school_tier, '''')) = '''' then\n    raise exception ''INVALID_INPUT: university/department/major/tier are required'' using errcode = ''22023'';\n  end if;\n\n  -- (b) mentor 단위 직렬화 — 같은 멘토의 서로 다른 요청이 동시에 승인되지 않도록.\n  select * into v_row from public.mentor_school_verifications where id = p_verification_id;\n  if not found then\n    raise exception ''VERIFICATION_NOT_FOUND'' using errcode = ''P0002'';\n  end if;\n  perform pg_advisory_xact_lock(hashtextextended(''msv_approve:'' || v_row.mentor_id::text, 0));\n\n  -- 락 획득 후 재조회(대기 중 다른 트랜잭션이 상태를 바꿨을 수 있다).\n  select * into v_row from public.mentor_school_verifications\n   where id = p_verification_id for update;\n  -- 193: 확정 가능 = 심사 대상(pending·resubmit_required) 또는 approved(잠정·확정 무관 — 확정된 행은 \"정정\").\n  if v_row.status not in (''pending'', ''resubmit_required'', ''approved'') then\n    raise exception ''NOT_REVIEWABLE: %'', v_row.status using errcode = ''22023'';\n  end if;\n\n  -- (c) 192: 서류 유무·경로·객체 실재는 확정 조건이 아니다 — 서류는 판단 재료이며 화면이 ''서류 없음''을 보여준다.\n\n  -- 193: 이미 확정된 approved 행(reviewed_by NOT NULL)의 재확정 = 정정. 이전 값을 감사 로그 상세에 남긴다.\n  v_correction := (v_row.status = ''approved'' and v_row.reviewed_by is not null);\n  if v_correction then\n    v_previous := jsonb_build_object(\n      ''school_tier'', v_row.school_tier,\n      ''verified_major_category'', v_row.verified_major_category,\n      ''verified_university_name'', v_row.verified_university_name,\n      ''verified_university_id'', v_row.verified_university_id,\n      ''verified_department_name'', v_row.verified_department_name,\n      ''reviewed_by'', v_row.reviewed_by,\n      ''reviewed_at'', v_row.reviewed_at\n    );\n  end if;\n\n  -- (d) 재승인 수명주기 — 같은 트랜잭션에서 기존 approved 를 먼저 종료시킨다.\n  update public.mentor_school_verifications\n     set status = ''superseded'',\n         updated_at = now()\n   where mentor_id = v_row.mentor_id\n     and status = ''approved''\n     and id <> v_row.id;\n  get diagnostics v_superseded = row_count;\n\n  -- (e) 대상 행 확정(정정 시 reviewed_by · reviewed_at 이 새로 채워진다).\n  update public.mentor_school_verifications\n     set status = ''approved'',\n         verified_university_name = btrim(p_university_name),\n         verified_university_id = btrim(p_university_id),\n         verified_department_name = btrim(p_department_name),\n         verified_major_category = btrim(p_major_category),\n         school_tier = btrim(p_school_tier),\n         reviewed_by = v_admin,\n         reviewed_at = now(),\n         reject_reason = null\n   where id = v_row.id;\n\n  -- (f) 193: 정정 감사 로그 — 이전 등급 · 이전 확정자(웹 액션의 mentor_school_verification_approve 기록과 별개).\n  if v_correction then\n    insert into public.admin_action_logs (admin_id, action_type, target_type, target_id, detail)\n    values (\n      v_admin,\n      ''school_tier_corrected'',\n      ''mentor_school_verification'',\n      v_row.id,\n      jsonb_build_object(\n        ''mentor_id'', v_row.mentor_id,\n        ''previous'', v_previous,\n        ''next'', jsonb_build_object(\n          ''school_tier'', btrim(p_school_tier),\n          ''verified_major_category'', btrim(p_major_category),\n          ''verified_university_name'', btrim(p_university_name),\n          ''verified_university_id'', btrim(p_university_id),\n          ''verified_department_name'', btrim(p_department_name),\n          ''reviewed_by'', v_admin\n        ),\n        ''note'', ''확정된 학교 등급 정정(193 A-2) — 이전 등급·이전 확정자 보존''\n      )\n    );\n  end if;\n\n  -- 감사 가능 최소 정보만 반환한다(서류 내용·signed URL·토큰 미포함). corrected · previous_* 는 193 additive 키.\n  return jsonb_build_object(\n    ''verification_id'', v_row.id,\n    ''mentor_id'', v_row.mentor_id,\n    ''status'', ''approved'',\n    ''superseded_count'', v_superseded,\n    ''reviewed_by'', v_admin,\n    ''corrected'', v_correction,\n    ''previous_school_tier'', case when v_correction then v_row.school_tier end,\n    ''previous_reviewed_by'', case when v_correction then v_row.reviewed_by end\n  );\nend;\n$$", "comment on function public.approve_mentor_school_verification_admin(uuid, text, text, text, text, text) is\n  ''SQL174 → 192 → 193: 학교·전공 인증 확정 정본. is_admin() 전용 · 확정 가능 = pending / resubmit_required / approved(잠정·확정 무관 — 확정된 행은 정정: reviewed_by/at 갱신 + admin_action_logs school_tier_corrected 에 이전 등급·확정자 기록) · 서류 조건 없음 · 재승인 시 기존 approved → superseded 를 같은 트랜잭션에서 수행. 실패는 전부 예외(부분 반영 없음).''", "revoke all on function public.approve_mentor_school_verification_admin(uuid, text, text, text, text, text) from public", "revoke all on function public.approve_mentor_school_verification_admin(uuid, text, text, text, text, text) from anon", "grant execute on function public.approve_mentor_school_verification_admin(uuid, text, text, text, text, text)\n  to authenticated, service_role", "-- ── A-3. 미분류 일괄 정정 (대학명이 있는 approved 행만 · 이전 값은 로그 detail.rows 에 보존) ──\ndo $$\ndeclare\n  v_admin   constant uuid := ''9bf48819-1dd2-40dd-96a3-d64bcca2e60c'';  -- byite1226@gmail.com (오너 지정 · 192 B-1 과 동일)\n  v_target  integer;\n  v_updated integer;\n  v_rows    jsonb;\n  v_now     timestamptz := now();\nbegin\n  select count(*),\n         coalesce(jsonb_agg(jsonb_build_object(\n           ''id'', v.id,\n           ''mentor_id'', v.mentor_id,\n           ''verified_university_name'', v.verified_university_name,\n           ''reviewed_by'', v.reviewed_by,\n           ''reviewed_at'', v.reviewed_at\n         ) order by v.verified_university_name, v.created_at), ''[]''::jsonb)\n    into v_target, v_rows\n    from public.mentor_school_verifications v\n   where v.status = ''approved''\n     and v.school_tier = ''미분류''\n     and v.verified_university_name is not null\n     and btrim(v.verified_university_name) <> '''';\n\n  if v_target = 0 then\n    raise notice ''193 A-3: 일괄 정정 대상 0건 — 건너뜀(로그 미기록)'';\n    return;\n  end if;\n\n  -- 대상이 있으면 정정 주체가 실재하는 admin 이어야 한다. 아니면 정정하지 않고 중단(추측 금지).\n  if not exists (select 1 from public.users u where u.id = v_admin and u.role = ''admin'') then\n    raise exception ''193_ABORT: 일괄 정정 admin 계정 % 이 public.users 에 admin 으로 없다 — 대상 % 건을 정정하지 않고 중단'', v_admin, v_target;\n  end if;\n  if not exists (select 1 from auth.users au where au.id = v_admin) then\n    raise exception ''193_ABORT: 일괄 정정 admin 계정 % 이 auth.users 에 없다(admin_action_logs FK) — 중단'', v_admin;\n  end if;\n\n  update public.mentor_school_verifications v\n     set school_tier = ''그외'',\n         reviewed_by = v_admin,\n         reviewed_at = v_now\n   where v.status = ''approved''\n     and v.school_tier = ''미분류''\n     and v.verified_university_name is not null\n     and btrim(v.verified_university_name) <> '''';\n  get diagnostics v_updated = row_count;\n\n  if v_updated <> v_target then\n    raise exception ''193_ABORT: 일괄 정정 대상 % 건 ≠ 갱신 % 건'', v_target, v_updated;\n  end if;\n\n  insert into public.admin_action_logs (admin_id, action_type, target_type, target_id, detail, created_at)\n  values (\n    v_admin,\n    ''school_tier_bulk_reassigned'',\n    ''mentor_school_verification'',\n    null,\n    jsonb_build_object(\n      ''count'', v_updated,\n      ''from_tier'', ''미분류'',\n      ''to_tier'', ''그외'',\n      ''note'', ''폴백 규칙 변경(미분류→그외)에 따른 일괄 정정'',\n      ''rule'', ''mentor_school_verifications.status = approved AND school_tier = 미분류 AND verified_university_name 비어 있지 않음'',\n      ''reviewed_at'', v_now,\n      ''rows'', v_rows,\n      ''migration'', ''20260903200100_school_tier_fallback_other_and_correction''\n    ),\n    v_now\n  );\n  raise notice ''193 A-3: % 건 미분류 → 그외 (reviewed_by = %, reviewed_at = %)'', v_updated, v_admin, v_now;\nend $$", "-- ── 적용 직후 자가 검증 ───────────────────────────────────────────────────────\ndo $$\ndeclare v_n integer;\nbegin\n  if public.school_tier_suggest(''가천대학교'') <> ''그외''\n     or public.school_tier_suggest('''') <> ''미분류''\n     or public.school_tier_suggest(''   '') <> ''미분류''\n     or public.school_tier_suggest(null) <> ''미분류''\n     or public.school_tier_suggest(''성균관대학교'') <> ''서성한''\n     or public.school_tier_suggest(''연세대학교 미래캠퍼스'') <> ''서연고'' then\n    raise exception ''193_SELFCHECK: 판정 헬퍼 규칙 불일치'';\n  end if;\n\n  select count(*) into v_n\n    from public.mentor_school_verifications v\n   where v.status = ''approved'' and v.school_tier = ''미분류''\n     and v.verified_university_name is not null and btrim(v.verified_university_name) <> '''';\n  if v_n > 0 then\n    raise exception ''193_SELFCHECK: 대학명이 있는 미분류 approved 행 % 건 잔존'', v_n;\n  end if;\n\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''public'' and p.proname = ''approve_mentor_school_verification_admin''\n                    and p.prosecdef and p.proconfig::text like ''%search_path=%''\n                    and p.prosrc like ''%school_tier_corrected%''\n                    and p.prosrc like ''%not in (''''pending'''', ''''resubmit_required'''', ''''approved'''')%''\n                    and p.prosrc not like ''%DOCUMENT_REF_MISSING%''\n                    and NOT has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n                    and has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n                    and has_function_privilege(''service_role'', p.oid, ''EXECUTE'')) then\n    raise exception ''193_SELFCHECK: RPC 본문/ACL 불일치'';\n  end if;\n  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n              where n.nspname = ''public'' and p.proname = ''school_tier_suggest''\n                and (has_function_privilege(''anon'', p.oid, ''EXECUTE'') or has_function_privilege(''authenticated'', p.oid, ''EXECUTE''))) then\n    raise exception ''193_SELFCHECK: school_tier_suggest 에 anon·authenticated EXECUTE 잔존'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "community_soft_delete_deleted_at", "version": "20260903200200", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 194_community_soft_delete_deleted_at.sql  (2026-09-03 · DB-2 묶음 B — 소프트 삭제 ★)\n--\n-- 오너 결정(2026-09-03): 숏폼(shortform_posts) · 숏폼 댓글(community_comments post_type=shortform) · 게시판 댓글\n--   (정본 comments ↔ 레거시 community_comments post_type=board)의 하드 DELETE 를 게시판 글(community_posts)과 같은\n--   deleted_at 방식으로 통일한다. \"언제 지웠는지\" 가 남고 복원이 가능해진다.\n--\n-- B-1 적용 전 실측(2026-09-03 운영 read-only): community_posts = deleted_at 있음(deleted_by 없음) ·\n--     shortform_posts / comments / community_comments = deleted_at·deleted_by 없음 · comments.is_deleted boolean 있음 ·\n--     네 테이블 전부 0행(콘텐츠 없음 → 데이터 영향 0).\n-- B-2 컬럼: shortform_posts · comments · community_comments 에 deleted_at timestamptz null + deleted_by uuid null,\n--     community_posts 에 deleted_by uuid null. deleted_by 는 FK 없는 uuid(auth.users 삭제 시 기록을 잃지 않기 위해 —\n--     admin_action_logs.admin_id 와 다르게 감사 대상이 아니라 감사 기록이다).\n--     comments.is_deleted 는 유지한다(\"안 보임\" = 숨김 OR 삭제 플래그). 둘의 동기화는 **DB 트리거**\n--     (comments_sync_deleted_flag · BEFORE INSERT OR UPDATE OF is_deleted, deleted_at)가 한다 — 앱 코드가 아니다:\n--       · deleted_at 이 바뀌면 is_deleted 는 그 결과(삭제 → true · 복원 → false)를 따른다\n--       · deleted_at 이 남아 있는 행은 is_deleted 를 false 로 되돌려도 true 로 고정된다(삭제가 숨김보다 강하다)\n--       · deleted_at 이 NULL 이면 is_deleted 는 숨김 플래그로 자유롭게 바뀐다(관리자 숨김·복원 경로 불변)\n--       · 브리지(app.comment_sync) 안에서는 브리지가 두 값을 함께 계산하므로 개입하지 않는다\n-- B-3 읽기 경로 전수(★ 하나라도 빠지면 학생 화면에 지운 숏폼이 보인다) — 아래 본문 순서:\n--     [정책] sf_select_published · comments_select_visible · community_comments_select_visible 에 deleted_at IS NULL.\n--            관리자(is_admin())는 삭제된 것도 읽는다(복원하려면 보여야 한다). comments_admin_select_all · cp_select_visible 불변.\n--     [뷰]   api_web_v1.community_comments_v1 — is_deleted = false AND deleted_at IS NULL (security_invoker 유지).\n--            mentor_directory_v1 · community_posts_v1(web/app) 은 이 세 테이블을 참조하지 않는다(실측).\n--     [RPC]  shortform_view_record_v2 · increment_shortform_post_view(삭제된 숏폼 조회수 미계수) ·\n--            rls_private.report_target_content_valid(삭제된 콘텐츠는 신고 대상 아님 — community_posts 포함) ·\n--            community_comment_soft_delete_self(본인 삭제 = deleted_at/deleted_by. 구 본문은 status=''deleted'' 를 쓰는데\n--            community_comments_status_chk(visible·hidden)가 막아 실제로는 실패하던 경로 — 함께 정합화).\n--     [트리거] community_refresh_post_comment_count 가 삭제 댓글을 세지 않고, trg_comments_refresh_count 가 deleted_at\n--            변경에도 재계산한다(UPDATE OF is_deleted, deleted_at — BEFORE 트리거가 바꾼 컬럼은 UPDATE OF 를 발화하지 않으므로\n--            deleted_at 을 목록에 넣어야 한다).\n--     [댓글 동기화 트리거] cc_sync_board_to_canonical · comments_mirror_to_legacy (+ DELETE 미러 2종) 가 deleted_at·deleted_by 를\n--            양방향으로 옮긴다. 정본 is_deleted = 숨김(status<>visible) OR 삭제(deleted_at) · 레거시 status 는 숨김 전용\n--            (삭제는 deleted_at 으로만 전달 — 복원하면 숨김이 아니었던 댓글은 그대로 보인다).\n--     [쓰기 가드] shortform_posts_protected_guard · comments_write_guard — deleted_by 단독 변경 금지 · deleted_by 는 auth.uid() 만 ·\n--            복원(deleted_at → NULL)은 관리자만(위조 방지 · 심층 방어). 작성자 본인의 직접 UPDATE soft delete 는 그 앞단에서\n--            RLS 가 거부한다 — UPDATE 의 새 행도 SELECT 정책(deleted_at IS NULL)을 통과해야 하므로(community_posts 와 같은 성질).\n--            본인 삭제는 SECURITY DEFINER RPC 경로(숏폼 댓글 community_comment_soft_delete_self · 게시판 글 community_post_soft_delete).\n-- B-4 하드 DELETE 차단 트리거는 두지 않는다(오너 결정 2026-09-03 — 지시서 B-4 \"권고하되 오너가 거부하면 뺀다\"). 하드 DELETE 는\n--     기존 경로 그대로(comments_write_guard 가 비관리자 DELETE 를 거부 · 정본/레거시 DELETE 미러는 상대 행에 deleted_at 을 남긴다).\n--     PR-W2 가 관리자 삭제 액션 3종을 UPDATE(deleted_at) 로 바꾼다.\n--\n-- Apply: 저장소 표준 경로(db-apply-pending) — 즉석 실행 금지. 적용 순서 A(193) → B(194) → C(195).\n--   pack 등재: supabase/baseline/post_ledger_backfills/20260903200200_community_soft_delete_deleted_at.sql\n-- Rollback: supabase/rollback/20260903200200_community_soft_delete_deleted_at_rollback.sql\n-- 검증(§6): select table_name, column_name from information_schema.columns\n--            where table_name in (''shortform_posts'',''comments'',''community_comments'') and column_name in (''deleted_at'',''deleted_by'');\n--           select polname, pg_get_expr(polqual, polrelid) from pg_policy\n--            where polrelid in (''shortform_posts''::regclass,''comments''::regclass) and polcmd=''r'';\n-- =============================================================================\n\nbegin", "-- ── 0. 사전 게이트 — 예상 상태와 다르면 중단(임의 정정 금지) ──────────────────\ndo $$\ndeclare v_missing text;\nbegin\n  if exists (select 1 from information_schema.columns\n              where table_schema = ''public''\n                and ((table_name = ''shortform_posts'' and column_name in (''deleted_at'', ''deleted_by''))\n                  or (table_name = ''comments'' and column_name in (''deleted_at'', ''deleted_by''))\n                  or (table_name = ''community_comments'' and column_name in (''deleted_at'', ''deleted_by''))\n                  or (table_name = ''community_posts'' and column_name = ''deleted_by''))) then\n    raise exception ''194_GATE: deleted_at/deleted_by 컬럼이 이미 있다(이미 적용됐거나 전제 불일치)'';\n  end if;\n  if not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''community_posts'' and column_name = ''deleted_at'')\n     or not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''comments'' and column_name = ''is_deleted'') then\n    raise exception ''194_GATE: community_posts.deleted_at / comments.is_deleted 부재(기준 컬럼)'';\n  end if;\n\n  select string_agg(p, '', '') into v_missing from unnest(array[\n    ''shortform_posts.sf_select_published'', ''comments.comments_select_visible'', ''comments.comments_admin_select_all'',\n    ''community_comments.community_comments_select_visible'', ''community_posts.cp_select_visible'']) p\n   where not exists (select 1 from pg_policies where schemaname = ''public''\n                       and tablename = split_part(p, ''.'', 1) and policyname = split_part(p, ''.'', 2));\n  if v_missing is not null then\n    raise exception ''194_GATE: SELECT 정책 부재 — %'', v_missing;\n  end if;\n  if exists (select 1 from pg_policies where schemaname = ''public''\n              and policyname in (''sf_select_published'', ''comments_select_visible'', ''community_comments_select_visible'')\n              and qual like ''%deleted_at%'') then\n    raise exception ''194_GATE: SELECT 정책에 deleted_at 이 이미 있다(이미 적용)'';\n  end if;\n\n  if to_regclass(''api_web_v1.community_comments_v1'') is null\n     or pg_get_viewdef(''api_web_v1.community_comments_v1''::regclass) not like ''%is_deleted = false%'' then\n    raise exception ''194_GATE: api_web_v1.community_comments_v1 부재 또는 정의 불일치'';\n  end if;\n\n  select string_agg(p, '', '') into v_missing from unnest(array[\n    ''public.cc_sync_board_to_canonical'', ''public.cc_sync_board_delete_to_canonical'', ''public.comments_mirror_to_legacy'',\n    ''public.comments_mirror_delete_to_legacy'', ''public.comments_write_guard'', ''public.shortform_posts_protected_guard'',\n    ''public.community_refresh_post_comment_count'', ''public.shortform_view_record_v2'', ''public.increment_shortform_post_view'',\n    ''public.community_comment_soft_delete_self'', ''public.comment_sync_in_progress'', ''rls_private.report_target_content_valid'']) p\n   where not exists (select 1 from pg_proc f join pg_namespace n on n.oid = f.pronamespace\n                       where n.nspname = split_part(p, ''.'', 1) and f.proname = split_part(p, ''.'', 2));\n  if v_missing is not null then\n    raise exception ''194_GATE: 함수 부재 — %'', v_missing;\n  end if;\n\n  select string_agg(t, '', '') into v_missing from unnest(array[\n    ''comments.trg_comments_refresh_count'', ''comments.trg_comments_mirror_to_legacy'', ''comments.trg_comments_mirror_delete'',\n    ''comments.trg_comments_write_guard'', ''community_comments.trg_cc_sync_board_to_canonical'',\n    ''community_comments.trg_cc_sync_board_delete'', ''shortform_posts.trg_shortform_posts_protected'']) t\n   where not exists (select 1 from pg_trigger g where g.tgname = split_part(t, ''.'', 2)\n                       and g.tgrelid = (''public.'' || split_part(t, ''.'', 1))::regclass);\n  if v_missing is not null then\n    raise exception ''194_GATE: 트리거 부재 — %'', v_missing;\n  end if;\n  if exists (select 1 from pg_proc where proname = ''comments_sync_deleted_flag'') then\n    raise exception ''194_GATE: 194 함수가 이미 있다(이미 적용)'';\n  end if;\nend $$", "-- ── B-2. 컬럼 ─────────────────────────────────────────────────────────────────\nalter table public.shortform_posts\n  add column deleted_at timestamptz null,\n  add column deleted_by uuid null", "alter table public.comments\n  add column deleted_at timestamptz null,\n  add column deleted_by uuid null", "alter table public.community_comments\n  add column deleted_at timestamptz null,\n  add column deleted_by uuid null", "alter table public.community_posts\n  add column deleted_by uuid null", "comment on column public.shortform_posts.deleted_at is ''194: 소프트 삭제 시각(NULL = 살아 있음). 하드 DELETE 금지 — anon·authenticated 읽기 정책이 deleted_at IS NULL 을 건다. 관리자(is_admin)는 삭제된 것도 읽는다.''", "comment on column public.shortform_posts.deleted_by is ''194: 삭제한 사용자 uuid(관리자 또는 작성자 본인). FK 없음(감사 기록).''", "comment on column public.comments.deleted_at is ''194: 소프트 삭제 시각(NULL = 살아 있음). is_deleted 는 \"안 보임\"(숨김 OR 삭제) 플래그로 유지 — comments_sync_deleted_flag 트리거가 동기화한다.''", "comment on column public.comments.deleted_by is ''194: 삭제한 사용자 uuid. FK 없음(감사 기록).''", "comment on column public.community_comments.deleted_at is ''194: 소프트 삭제 시각(NULL = 살아 있음). status 는 숨김 전용(visible·hidden). 게시판 댓글은 브리지가 정본 comments 와 양방향 동기화한다.''", "comment on column public.community_comments.deleted_by is ''194: 삭제한 사용자 uuid. FK 없음(감사 기록).''", "comment on column public.community_posts.deleted_by is ''194: 삭제한 사용자 uuid(deleted_at 과 짝). FK 없음(감사 기록).''", "-- ── B-3a. comments.is_deleted ↔ deleted_at 동기화 트리거 ───────────────────────\ncreate or replace function public.comments_sync_deleted_flag()\nreturns trigger\nlanguage plpgsql\nset search_path = public\nas $$\nbegin\n  -- 브리지 안에서는 브리지가 is_deleted 를 (숨김 OR 삭제) 로 직접 계산한다.\n  if public.comment_sync_in_progress() then return new; end if;\n\n  if tg_op = ''INSERT'' then\n    if new.deleted_at is not null then new.is_deleted := true; end if;\n    return new;\n  end if;\n\n  if new.deleted_at is distinct from old.deleted_at then\n    -- 삭제/복원이 명시된 갱신: 플래그가 결과를 따른다(복원 = 다시 보임).\n    new.is_deleted := (new.deleted_at is not null);\n  elsif new.deleted_at is not null then\n    -- 삭제된 행은 숨김 플래그를 풀어도 계속 안 보인다(삭제가 숨김보다 강하다).\n    new.is_deleted := true;\n  end if;\n  return new;\nend;\n$$", "comment on function public.comments_sync_deleted_flag() is\n  ''194: comments.deleted_at ↔ is_deleted 동기화. deleted_at 변경 → is_deleted 추종 · deleted_at 잔존 행은 is_deleted 고정 true · deleted_at NULL 이면 is_deleted 는 숨김 플래그(관리자 숨김·복원 경로 불변). 브리지(app.comment_sync) 안에서는 개입하지 않는다.''", "revoke all on function public.comments_sync_deleted_flag() from public, anon, authenticated", "drop trigger if exists trg_comments_sync_deleted_flag on public.comments", "create trigger trg_comments_sync_deleted_flag\n  before insert or update of is_deleted, deleted_at on public.comments\n  for each row execute function public.comments_sync_deleted_flag()", "-- ── B-3b. 댓글 수 — 삭제 댓글 제외 · deleted_at 변경에도 재계산 ───────────────\ncreate or replace function public.community_refresh_post_comment_count()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  pid uuid;\nbegin\n  pid := coalesce(new.post_id, old.post_id);\n  update public.community_posts p\n  set comment_count = (\n    select count(*)::int from public.comments c\n    where c.post_id = pid and c.is_deleted = false and c.deleted_at is null\n  )\n  where p.id = pid;\n  return coalesce(new, old);\nend;\n$$", "drop trigger if exists trg_comments_refresh_count on public.comments", "create trigger trg_comments_refresh_count\n  after insert or delete or update of is_deleted, deleted_at on public.comments\n  for each row execute function public.community_refresh_post_comment_count()", "-- ── B-3c. 게시판 댓글 브리지(163·164) — deleted_at·deleted_by 양방향 동기화 ────\n-- legacy(board) → canonical: 포인터 우선 수렴(164 본문) + deleted_at/deleted_by · is_deleted = 숨김 OR 삭제\ncreate or replace function public.cc_sync_board_to_canonical()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_canonical uuid;\n  v_target public.comments;\nbegin\n  if public.comment_sync_in_progress() then return new; end if;\n  perform set_config(''app.comment_sync'', ''1'', true);\n\n  if new.canonical_comment_id is not null then\n    select * into v_target from public.comments\n    where id = new.canonical_comment_id for update;\n    if not found then\n      raise exception ''COMMENT_BRIDGE_TARGET_MISSING'';\n    end if;\n    if v_target.post_id is distinct from new.post_id then\n      raise exception ''COMMENT_BRIDGE_POST_MISMATCH'';\n    end if;\n    if v_target.author_id is distinct from new.author_id then\n      raise exception ''COMMENT_BRIDGE_AUTHOR_MISMATCH'';\n    end if;\n    update public.comments\n      set content = new.body,\n          deleted_at = new.deleted_at,\n          deleted_by = new.deleted_by,\n          is_deleted = (new.status <> ''visible'' or new.deleted_at is not null)\n    where id = new.canonical_comment_id;\n  else\n    insert into public.comments (post_id, author_id, content, is_deleted, created_at, legacy_comment_id, deleted_at, deleted_by)\n    values (new.post_id, new.author_id, new.body, (new.status <> ''visible'' or new.deleted_at is not null), new.created_at, new.id,\n            new.deleted_at, new.deleted_by)\n    on conflict (legacy_comment_id) where legacy_comment_id is not null\n    do update set content = excluded.content, is_deleted = excluded.is_deleted,\n                  deleted_at = excluded.deleted_at, deleted_by = excluded.deleted_by\n    returning id into v_canonical;\n    if v_canonical is null then\n      select id into v_canonical from public.comments where legacy_comment_id = new.id;\n    end if;\n    update public.community_comments set canonical_comment_id = v_canonical where id = new.id;\n  end if;\n\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return new;\nend;\n$$", "-- legacy DELETE → canonical soft delete(163·164 정책 유지) + deleted_at 기록\ncreate or replace function public.cc_sync_board_delete_to_canonical()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare v_rows int;\nbegin\n  if public.comment_sync_in_progress() then return old; end if;\n  perform set_config(''app.comment_sync'', ''1'', true);\n\n  if old.canonical_comment_id is not null then\n    update public.comments\n       set is_deleted = true,\n           deleted_at = coalesce(deleted_at, old.deleted_at, now()),\n           deleted_by = coalesce(deleted_by, old.deleted_by)\n     where id = old.canonical_comment_id;\n  else\n    update public.comments\n       set is_deleted = true,\n           deleted_at = coalesce(deleted_at, old.deleted_at, now()),\n           deleted_by = coalesce(deleted_by, old.deleted_by)\n     where legacy_comment_id = old.id;\n  end if;\n  get diagnostics v_rows = row_count;\n  if v_rows = 0 then\n    raise exception ''COMMENT_BRIDGE_TARGET_MISSING'';\n  end if;\n\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return old;\nend;\n$$", "-- canonical → legacy 미러(164 본문): deleted_at/deleted_by 전달 · status 는 숨김 전용(삭제는 status 를 건드리지 않는다)\ncreate or replace function public.comments_mirror_to_legacy()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\ndeclare\n  v_body text;\n  v_rows int;\n  v_status text;\nbegin\n  if public.comment_sync_in_progress() then return new; end if;\n  perform set_config(''app.comment_sync'', ''1'', true);\n\n  v_body := left(coalesce(new.content, ''''), 1000);\n  -- 194: 숨김(is_deleted 이면서 삭제는 아님)만 hidden. 삭제는 deleted_at 으로만 전달한다.\n  v_status := case when coalesce(new.is_deleted, false) and new.deleted_at is null then ''hidden'' else ''visible'' end;\n\n  if new.legacy_comment_id is not null then\n    if char_length(btrim(v_body)) >= 1 then\n      update public.community_comments\n        set body = v_body,\n            status = v_status,\n            deleted_at = new.deleted_at,\n            deleted_by = new.deleted_by,\n            canonical_comment_id = new.id\n      where id = new.legacy_comment_id\n        and (canonical_comment_id = new.id or canonical_comment_id is null);\n    else\n      update public.community_comments\n        set status = v_status,\n            deleted_at = new.deleted_at,\n            deleted_by = new.deleted_by,\n            canonical_comment_id = new.id\n      where id = new.legacy_comment_id\n        and (canonical_comment_id = new.id or canonical_comment_id is null);\n    end if;\n    get diagnostics v_rows = row_count;\n    if v_rows = 0 then\n      raise exception ''COMMENT_BRIDGE_LEGACY_MISSING'';\n    end if;\n  else\n    if char_length(btrim(v_body)) >= 1 then\n      insert into public.community_comments (post_id, post_type, author_id, body, status, created_at, canonical_comment_id, deleted_at, deleted_by)\n      values (new.post_id, ''board'', new.author_id, v_body, v_status,\n              coalesce(new.created_at, now()), new.id, new.deleted_at, new.deleted_by)\n      on conflict (canonical_comment_id) where canonical_comment_id is not null\n      do update set body = excluded.body, status = excluded.status,\n                    deleted_at = excluded.deleted_at, deleted_by = excluded.deleted_by;\n    end if;\n  end if;\n\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return new;\nend;\n$$", "-- canonical DELETE → legacy hidden(163 정책 유지) + deleted_at 기록\ncreate or replace function public.comments_mirror_delete_to_legacy()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $$\nbegin\n  if public.comment_sync_in_progress() then return old; end if;\n  perform set_config(''app.comment_sync'', ''1'', true);\n  update public.community_comments\n     set status = ''hidden'',\n         deleted_at = coalesce(deleted_at, old.deleted_at, now()),\n         deleted_by = coalesce(deleted_by, old.deleted_by)\n  where canonical_comment_id = old.id\n     or (old.legacy_comment_id is not null and id = old.legacy_comment_id);\n  perform set_config(''app.comment_sync'', ''0'', true);\n  return old;\nend;\n$$", "-- ── B-3d. 뷰 — api_web_v1.community_comments_v1: 삭제 댓글 제외 ─────────────────\ncreate or replace view api_web_v1.community_comments_v1\nwith (security_invoker = true) as\n select id,\n        post_id,\n        author_id,\n        parent_id,\n        content as body,\n        like_count,\n        author_label,\n        author_role,\n        created_at\n   from public.comments c\n  where is_deleted = false and deleted_at is null", "comment on view api_web_v1.community_comments_v1 is\n  ''S2 M4 V2(계약 §6) + 194: 정본 comments 단일 원천 — body=content · is_deleted=false AND deleted_at IS NULL · 라벨은 M13 비정규화 컬럼. security_invoker=true.''", "-- ── B-3e. RLS SELECT 정책 — anon·authenticated 는 deleted_at IS NULL · 관리자는 전부 ───\ndrop policy if exists sf_select_published on public.shortform_posts", "create policy sf_select_published\n  on public.shortform_posts\n  for select\n  to anon, authenticated\n  using (\n    (deleted_at is null\n      and (status = ''published''\n           or author_id = (select auth.uid())\n           or creator_id = (select auth.uid())))\n    or (select public.is_admin())\n  )", "drop policy if exists comments_select_visible on public.comments", "create policy comments_select_visible\n  on public.comments\n  for select\n  to anon, authenticated\n  using (is_deleted = false and deleted_at is null)", "-- comments_admin_select_all(is_admin) 불변 — 관리자는 삭제된 것도 읽는다.\n\ndrop policy if exists community_comments_select_visible on public.community_comments", "create policy community_comments_select_visible\n  on public.community_comments\n  for select\n  to anon, authenticated\n  using (\n    (deleted_at is null\n      and (status = ''visible''\n           or author_id = (select auth.uid())))\n    or ((select public.is_admin()) = true)\n  )", "comment on policy sf_select_published on public.shortform_posts is\n  ''053b → 194: 살아 있는(deleted_at IS NULL) published 또는 본인 글 · 관리자는 삭제된 것도 읽는다.''", "comment on policy comments_select_visible on public.comments is\n  ''037 → 194: is_deleted = false AND deleted_at IS NULL. 관리자 전체 읽기는 comments_admin_select_all.''", "comment on policy community_comments_select_visible on public.community_comments is\n  ''101 → 194: 살아 있는(deleted_at IS NULL) visible 또는 본인 댓글 · 관리자는 삭제된 것도 읽는다.''", "-- ── B-3f. RPC — 삭제된 콘텐츠는 조회수 미계수 · 신고 대상 아님 · 본인 삭제 = deleted_at ───\ncreate or replace function public.shortform_view_record_v2(p_post_id uuid, p_event_key uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_inserted boolean := false;\nbegin\n  if p_post_id is null or p_event_key is null then\n    raise exception ''INVALID_INPUT'' using errcode = ''22023'';\n  end if;\n  -- 게시 상태 공개 글만 계수(194: 삭제된 글 제외)\n  if not exists (select 1 from public.shortform_posts sp\n                  where sp.id = p_post_id and sp.status = ''published'' and sp.deleted_at is null) then\n    raise exception ''POST_NOT_FOUND'' using errcode = ''P0001'';\n  end if;\n\n  insert into public.shortform_view_events (post_id, event_key, viewer_user_id)\n  values (p_post_id, p_event_key, v_uid)\n  on conflict (post_id, event_key) do nothing;\n  v_inserted := found;\n\n  if v_inserted then\n    update public.shortform_posts\n       set view_count = view_count + 1\n     where id = p_post_id;\n  end if;\n\n  -- 중복 key 는 idempotent success (계수 증가 없음)\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''incremented'', v_inserted);\nend\n$$", "create or replace function public.increment_shortform_post_view(p_post_id uuid)\nreturns void\nlanguage sql\nsecurity definer\nset search_path to ''public''\nas $$\n  update public.shortform_posts set view_count = view_count + 1\n  where id = p_post_id and status = ''published'' and deleted_at is null;\n$$", "create or replace function rls_private.report_target_content_valid(p_target_type text, p_target_id uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path to ''''\nas $$\n  select p_target_id is not null and case p_target_type\n    when ''community_post''    then exists (select 1 from public.community_posts   t where t.id = p_target_id and t.deleted_at is null)\n    when ''shortform_post''    then exists (select 1 from public.shortform_posts   t where t.id = p_target_id and t.deleted_at is null)\n    when ''community_comment'' then exists (select 1 from public.community_comments t where t.id = p_target_id and t.deleted_at is null)\n    when ''board_comment''     then exists (select 1 from public.comments          t where t.id = p_target_id and t.deleted_at is null)\n    else false\n  end\n$$", "create or replace function public.community_comment_soft_delete_self(p_comment_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_row public.community_comments%rowtype;\n  v_status text;\n  v_susp timestamptz;\n  v_norm text;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  select * into v_row from public.community_comments where id = p_comment_id for update;\n  if not found then\n    raise exception ''COMMENT_NOT_FOUND'' using errcode = ''P0001'';\n  end if;\n  if v_row.post_type <> ''shortform'' then\n    raise exception ''COMMENT_TYPE_NOT_SUPPORTED'' using errcode = ''22023'';\n  end if;\n  if v_row.author_id is distinct from v_uid then\n    raise exception ''COMMENT_NOT_OWNED'' using errcode = ''42501'';\n  end if;\n\n  -- 계정 게이트 (Build 13 판정과 동일: banned·유효 suspended·unknown/deleted·삭제 진행 차단)\n  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id = v_uid;\n  if not found then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  v_norm := lower(btrim(coalesce(v_status,'''')));\n  if v_norm = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if v_norm not in (''active'',''suspended'') then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  if public.account_deletion_write_blocked(v_uid) then raise exception ''ACCOUNT_DELETION_IN_PROGRESS''; end if;\n\n  -- 194: 삭제 = deleted_at/deleted_by (구 본문이 status 에 쓰던 삭제 값은 status CHECK(visible·hidden)가 막던 경로)\n  if v_row.deleted_at is not null then\n    return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''comment_id'', p_comment_id, ''idempotent_hit'', true);\n  end if;\n  if v_row.status <> ''visible'' then\n    -- 관리자 hidden 처리된 댓글은 본인이 삭제로 덮지 못한다 (moderation 유지)\n    raise exception ''COMMENT_MODERATED'' using errcode = ''42501'';\n  end if;\n\n  update public.community_comments set deleted_at = now(), deleted_by = v_uid where id = p_comment_id;\n\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''comment_id'', p_comment_id, ''idempotent_hit'', false);\nend\n$$", "-- ── B-3g. 쓰기 가드 — deleted_at/deleted_by 위조 방지(deleted_by = auth.uid() · 복원은 관리자만 · 심층 방어: 작성자 직접 UPDATE 는 RLS 가 먼저 거부) ───\ncreate or replace function public.shortform_posts_protected_guard()\nreturns trigger\nlanguage plpgsql\nset search_path to ''''\nas $$\nbegin\n  -- SECURITY INVOKER 필수 — current_user 게이트가 실제 클라이언트 역할을 봐야 한다.\n  if current_user not in (''anon'',''authenticated'') then\n    return new;\n  end if;\n  if coalesce((select public.is_admin()), false) then\n    return new;\n  end if;\n  if new.id                   is distinct from old.id\n     or new.author_id            is distinct from old.author_id\n     or new.creator_id           is distinct from old.creator_id\n     or new.author_role          is distinct from old.author_role\n     or new.author_label         is distinct from old.author_label\n     or new.source               is distinct from old.source\n     or new.created_at           is distinct from old.created_at\n     or new.view_count           is distinct from old.view_count\n     or new.like_count           is distinct from old.like_count\n     or new.create_idempotency_key is distinct from old.create_idempotency_key then\n    raise exception ''SHORTFORM_PROTECTED_COLUMNS'' using errcode = ''42501'';\n  end if;\n  if new.status is distinct from old.status then\n    if not (old.status in (''draft'',''published'') and new.status in (''draft'',''published'')) then\n      raise exception ''SHORTFORM_STATUS_TRANSITION_FORBIDDEN'' using errcode = ''42501'';\n    end if;\n  end if;\n  -- 194: deleted_by = auth.uid() 만 · 복원은 관리자만 · deleted_by 단독 변경 금지(RLS 가 작성자 직접 soft delete 를 먼저 거부하므로 심층 방어)\n  if new.deleted_at is distinct from old.deleted_at then\n    if new.deleted_at is null then\n      raise exception ''SHORTFORM_RESTORE_ADMIN_ONLY'' using errcode = ''42501'';\n    end if;\n    if new.deleted_by is distinct from (select auth.uid()) then\n      raise exception ''SHORTFORM_DELETED_BY_MISMATCH'' using errcode = ''42501'';\n    end if;\n  elsif new.deleted_by is distinct from old.deleted_by then\n    raise exception ''SHORTFORM_PROTECTED_COLUMNS'' using errcode = ''42501'';\n  end if;\n  new.updated_at := now();\n  return new;\nend\n$$", "create or replace function public.comments_write_guard()\nreturns trigger\nlanguage plpgsql\nset search_path to ''public''\nas $$\ndeclare v_parent public.comments;\nbegin\n  if public.comment_sync_in_progress() then\n    return coalesce(new, old);\n  end if;\n  if current_user not in (''authenticated'', ''anon'') then\n    return coalesce(new, old);\n  end if;\n\n  if tg_op = ''DELETE'' then\n    if coalesce((select public.is_admin()), false) then return old; end if;\n    raise exception ''COMMENT_HARD_DELETE_FORBIDDEN'';\n  end if;\n\n  if tg_op = ''INSERT'' then\n    if new.legacy_comment_id is not null then\n      raise exception ''COMMENT_LEGACY_ID_FORBIDDEN'';\n    end if;\n    if new.parent_id is not null then\n      select * into v_parent from public.comments where id = new.parent_id;\n      if not found then raise exception ''COMMENT_PARENT_NOT_FOUND''; end if;\n      if v_parent.post_id is distinct from new.post_id then\n        raise exception ''COMMENT_PARENT_POST_MISMATCH'';\n      end if;\n      if v_parent.parent_id is not null then\n        raise exception ''COMMENT_DEPTH_EXCEEDED'';\n      end if;\n    end if;\n    return new;\n  end if;\n\n  if new.id is distinct from old.id\n     or new.post_id is distinct from old.post_id\n     or new.author_id is distinct from old.author_id\n     or new.parent_id is distinct from old.parent_id\n     or new.created_at is distinct from old.created_at\n     or new.legacy_comment_id is distinct from old.legacy_comment_id\n     or new.like_count is distinct from old.like_count then\n    raise exception ''COMMENT_PROTECTED_FIELDS_IMMUTABLE'';\n  end if;\n  -- 194: deleted_by = auth.uid() 만 · 복원은 관리자만 · deleted_by 단독 변경 금지(RLS 가 작성자 직접 soft delete 를 먼저 거부하므로 심층 방어)\n  if new.deleted_at is distinct from old.deleted_at then\n    if new.deleted_at is null then\n      if not coalesce((select public.is_admin()), false) then\n        raise exception ''COMMENT_RESTORE_ADMIN_ONLY'';\n      end if;\n    elsif new.deleted_by is distinct from (select auth.uid()) then\n      raise exception ''COMMENT_DELETED_BY_MISMATCH'';\n    end if;\n  elsif new.deleted_by is distinct from old.deleted_by then\n    raise exception ''COMMENT_PROTECTED_FIELDS_IMMUTABLE'';\n  end if;\n  return new;\nend;\n$$", "-- ── 적용 직후 자가 검증 ───────────────────────────────────────────────────────\ndo $$\ndeclare v_n integer;\nbegin\n  select count(*) into v_n from information_schema.columns\n   where table_schema = ''public''\n     and ((table_name in (''shortform_posts'', ''comments'', ''community_comments'') and column_name in (''deleted_at'', ''deleted_by''))\n       or (table_name = ''community_posts'' and column_name in (''deleted_at'', ''deleted_by'')));\n  if v_n <> 8 then\n    raise exception ''194_SELFCHECK: deleted_at/deleted_by 컬럼 % 개(8 기대)'', v_n;\n  end if;\n\n  select count(*) into v_n from pg_policies\n   where schemaname = ''public'' and cmd = ''SELECT'' and qual like ''%deleted_at IS NULL%''\n     and ((tablename = ''shortform_posts'' and policyname = ''sf_select_published'')\n       or (tablename = ''comments'' and policyname = ''comments_select_visible'')\n       or (tablename = ''community_comments'' and policyname = ''community_comments_select_visible'')\n       or (tablename = ''community_posts'' and policyname = ''cp_select_visible''));\n  if v_n <> 4 then\n    raise exception ''194_SELFCHECK: deleted_at 필터 SELECT 정책 % 개(4 기대)'', v_n;\n  end if;\n  if not exists (select 1 from pg_policies where schemaname = ''public'' and tablename = ''comments'' and policyname = ''comments_admin_select_all'') then\n    raise exception ''194_SELFCHECK: comments_admin_select_all 부재'';\n  end if;\n\n  if pg_get_viewdef(''api_web_v1.community_comments_v1''::regclass) not like ''%deleted_at IS NULL%''\n     or coalesce((select reloptions::text from pg_class where oid = ''api_web_v1.community_comments_v1''::regclass), '''') not like ''%security_invoker=true%'' then\n    raise exception ''194_SELFCHECK: community_comments_v1 정의/security_invoker 불일치'';\n  end if;\n\n  select count(*) into v_n from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where ((n.nspname = ''public'' and p.proname in (''cc_sync_board_to_canonical'', ''cc_sync_board_delete_to_canonical'',\n                                                  ''comments_mirror_to_legacy'', ''comments_mirror_delete_to_legacy'',\n                                                  ''comments_write_guard'', ''shortform_posts_protected_guard'',\n                                                  ''community_refresh_post_comment_count'', ''shortform_view_record_v2'',\n                                                  ''increment_shortform_post_view'', ''community_comment_soft_delete_self''))\n       or (n.nspname = ''rls_private'' and p.proname = ''report_target_content_valid''))\n     and p.prosrc like ''%deleted_at%'';\n  if v_n <> 11 then\n    raise exception ''194_SELFCHECK: deleted_at 을 반영한 함수 % 개(11 기대)'', v_n;\n  end if;\n  if exists (select 1 from pg_proc where proname = ''community_comment_soft_delete_self'' and prosrc like ''%''''deleted''''%'') then\n    raise exception ''194_SELFCHECK: community_comment_soft_delete_self 에 status=deleted 잔존'';\n  end if;\n\n  if not exists (select 1 from pg_trigger where tgname = ''trg_comments_sync_deleted_flag'' and tgrelid = ''public.comments''::regclass)\n     or pg_get_triggerdef((select oid from pg_trigger where tgname = ''trg_comments_refresh_count'' and tgrelid = ''public.comments''::regclass))\n        not like ''%UPDATE OF is_deleted, deleted_at%'' then\n    raise exception ''194_SELFCHECK: comments 트리거 불일치'';\n  end if;\n  for v_n in select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n              where n.nspname = ''public'' and p.proname = ''comments_sync_deleted_flag''\n                and (has_function_privilege(''anon'', p.oid, ''EXECUTE'') or has_function_privilege(''authenticated'', p.oid, ''EXECUTE''))\n  loop\n    raise exception ''194_SELFCHECK: 트리거 함수에 anon·authenticated EXECUTE 잔존'';\n  end loop;\n  -- 기존 ACL 불변 확인(CREATE OR REPLACE 는 ACL 을 보존한다)\n  if has_function_privilege(''anon'', ''public.community_comment_soft_delete_self(uuid)'', ''EXECUTE'')\n     or not has_function_privilege(''authenticated'', ''public.community_comment_soft_delete_self(uuid)'', ''EXECUTE'')\n     or has_function_privilege(''anon'', ''public.increment_shortform_post_view(uuid)'', ''EXECUTE'')\n     or not has_function_privilege(''anon'', ''public.shortform_view_record_v2(uuid, uuid)'', ''EXECUTE'')\n     or has_function_privilege(''anon'', ''rls_private.report_target_content_valid(text, uuid)'', ''EXECUTE'') then\n    raise exception ''194_SELFCHECK: 기존 함수 ACL 변경됨'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "drop_school_tier_mappings", "version": "20260903200300", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 195_drop_school_tier_mappings.sql  (2026-09-03 · DB-2 묶음 C — 매핑 테이블 정리 · 권고)\n--\n-- school_tier_mappings(079) 는 행 0 · 코드 참조 0(판정 트리거·RPC 는 192 의 LIKE 하드코딩 헬퍼를 쓴다) · 뷰/FK 의존 0 이다.\n--   적용 전 실측(2026-09-03 운영 read-only): 행 0 · 참조 함수 0 · 의존 뷰 0 · 참조 FK 0. 웹에서 이 표를 읽는 곳은 등급 분류\n--   화면의 \"읽기 전용 매핑 표\" 섹션뿐이며(PR-11 §0-B-1) PR-W2 가 그 섹션을 내린다(그 전까지는 섹션이 \"불러오지 못했습니다\" 로 보인다).\n-- DROP TABLE(RESTRICT · CASCADE 금지). 정책·인덱스·updated_at 트리거는 테이블과 함께 사라진다.\n-- 오너가 거부하면 이 파일(pack 사본 · rollback 포함)만 뺀다.\n--\n-- Apply: 저장소 표준 경로(db-apply-pending) — 즉석 실행 금지. 적용 순서 A(193) → B(194) → C(195).\n--   pack 등재: supabase/baseline/post_ledger_backfills/20260903200300_drop_school_tier_mappings.sql\n-- Rollback: supabase/rollback/20260903200300_drop_school_tier_mappings_rollback.sql (079 원문 재생성)\n-- 검증(§6): select to_regclass(''public.school_tier_mappings'');   -- NULL 기대\n-- =============================================================================\n\nbegin", "-- ── 0. 사전 게이트 — 비어 있고 아무도 참조하지 않을 때만 지운다 ──────────────\ndo $$\ndeclare v_n bigint;\nbegin\n  if to_regclass(''public.school_tier_mappings'') is null then\n    raise exception ''195_GATE: school_tier_mappings 부재(이미 적용됐거나 전제 불일치)'';\n  end if;\n  execute ''select count(*) from public.school_tier_mappings'' into v_n;\n  if v_n <> 0 then\n    raise exception ''195_ABORT: school_tier_mappings 에 % 행이 있다 — 비어 있지 않으면 지우지 않는다'', v_n;\n  end if;\n  if exists (select 1 from pg_depend d join pg_rewrite r on r.oid = d.objid\n              where d.refobjid = ''public.school_tier_mappings''::regclass\n                and r.ev_class <> ''public.school_tier_mappings''::regclass) then\n    raise exception ''195_ABORT: school_tier_mappings 를 참조하는 뷰가 있다'';\n  end if;\n  if exists (select 1 from pg_constraint where confrelid = ''public.school_tier_mappings''::regclass) then\n    raise exception ''195_ABORT: school_tier_mappings 를 참조하는 FK 가 있다'';\n  end if;\n  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n              where n.nspname not in (''pg_catalog'', ''information_schema'') and p.prosrc ilike ''%school_tier_mappings%'') then\n    raise exception ''195_ABORT: school_tier_mappings 를 참조하는 함수가 있다'';\n  end if;\n  if to_regclass(''public.school_tier_catalog'') is null then\n    raise exception ''195_GATE: school_tier_catalog 부재(079 전제)'';\n  end if;\nend $$", "drop table public.school_tier_mappings", "-- ── 적용 직후 자가 검증 ───────────────────────────────────────────────────────\ndo $$\nbegin\n  if to_regclass(''public.school_tier_mappings'') is not null then\n    raise exception ''195_SELFCHECK: school_tier_mappings 잔존'';\n  end if;\n  if exists (select 1 from pg_policies where schemaname = ''public'' and tablename = ''school_tier_mappings'')\n     or exists (select 1 from pg_class where relname in (''school_tier_mappings_school_name_unique'', ''school_tier_mappings_active_order_idx'')) then\n    raise exception ''195_SELFCHECK: 정책/인덱스 잔존'';\n  end if;\n  if to_regclass(''public.school_tier_catalog'') is null or to_regclass(''public.major_category_catalog'') is null then\n    raise exception ''195_SELFCHECK: 카탈로그 테이블이 사라졌다'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "soft_delete_own_content_rpc", "version": "20260903230100", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 196_soft_delete_own_content_rpc.sql  (2026-09-03 · DB-3 묶음 A — 작성자 본인 삭제 RPC ★)\n--\n-- 왜: 게시판 댓글 본인 삭제가 지금 실패한다. 웹은 `UPDATE comments SET is_deleted = true … WHERE id = ? AND author_id = auth.uid()`\n--   (RETURNING id) 를 직접 보내는데, UPDATE 의 새 행이 SELECT 정책 comments_select_visible(is_deleted = false AND deleted_at IS NULL)\n--   을 통과하지 못해 \"new row violates row-level security policy\" 로 거부된다(194 이전부터 is_deleted = false 였으므로 194 와 무관하게\n--   실패하던 경로 — 로컬 재현: scripts/verify/fixtures/db3_batch_pre_fixture.sql). 숏폼·숏폼 댓글·게시판 글의 본인 삭제도 같은 성질이라\n--   SECURITY DEFINER RPC 하나로 경로를 통일한다(194 B-3 주석 \"본인 삭제는 SECURITY DEFINER RPC 경로\" 의 구현).\n--\n-- A-1 함수: public.soft_delete_own_content(p_kind text, p_id uuid) returns void · SECURITY DEFINER · search_path ''''.\n--     p_kind ∈ (''shortform'' → shortform_posts · ''shortform_comment'' → community_comments(post_type = ''shortform'') ·\n--              ''board_comment'' → comments(정본) · ''board_post'' → community_posts).\n--     · auth.uid() 가 없으면 AUTH_REQUIRED(28000) · p_kind 밖이면 INVALID_KIND(22023) · 행이 없으면 CONTENT_NOT_FOUND(P0001)\n--     · 작성자가 아니면 CONTENT_NOT_OWNED(42501) — 숏폼은 기존 정책(sf_update_own · sf_delete_own)과 같은 \"본인\" 정의(author_id 또는 creator_id)\n--     · ''shortform_comment'' 인데 post_type 이 ''shortform'' 이 아니면 CONTENT_KIND_MISMATCH(22023) — 게시판 댓글은 ''board_comment''(정본) 로만\n--     · 계정 게이트는 community_comment_soft_delete_self(20260803162808 · 194)와 동일: ACCOUNT_BANNED · ACCOUNT_SUSPENDED · ACCOUNT_NOT_ACTIVE ·\n--       ACCOUNT_DELETION_IN_PROGRESS\n--     · 이미 deleted_at 이 있으면 아무것도 하지 않고 정상 반환(멱등)\n--     · 관리자가 숨긴 행(글·숏폼 status = ''hidden'' · 숏폼 댓글 status <> ''visible'' · 게시판 댓글 is_deleted AND deleted_at IS NULL)은\n--       CONTENT_MODERATED(42501) — community_comment_soft_delete_self 의 \"moderation 유지\" 규칙을 네 종류에 같이 적용한다\n--       (게시판 글의 기존 F6 community_post_soft_delete 는 숨김 글도 지우게 두는데, 이 RPC 는 더 엄격하다 — 웹 게시판 글 삭제는 F6 그대로)\n--     · deleted_at = now() · deleted_by = auth.uid(). 게시판 댓글의 is_deleted 는 194 동기화 트리거(comments_sync_deleted_flag)가 true 로 올리고,\n--       레거시 미러(comments_mirror_to_legacy)가 deleted_at/deleted_by 를 옮기며, 댓글 수 트리거가 재계산한다 — 본문(content)은 보존한다\n--       (관리자 복원 대비 · 읽기 경로가 삭제 행을 전부 제외하므로 노출되지 않는다).\n--     · 감사 로그를 남기지 않는다(사용자 행위 — 관리자 삭제와 구분). 관리자 화면은 deleted_by = author_id 를 `작성자 삭제` 로 표시한다(PR-W3).\n--     · 작성자 복원 RPC 는 만들지 않는다(지운 건 관리자만 복원 — PR-W2 · 지시서 A-3).\n--     · 기존 community_comment_soft_delete_self(앱 계약 · outbound_api_manifest)는 그대로 둔다 — 앱은 앱 트랙에서 전환한다.\n-- A-2 권한: REVOKE public·anon · GRANT EXECUTE authenticated(+ service_role — 151 패턴). anon 은 호출 자체가 42501.\n-- SECURITY DEFINER 근거: 작성자 본인의 직접 UPDATE 는 RLS 가 새 행(SELECT 정책 미통과)을 거부한다. 소유자(postgres) 권한으로 실행해\n--   RLS 를 지나되, 작성자·계정 상태·moderation 판정을 함수 안에서 강제한다. 194 쓰기 가드 2종은 current_user 가 클라이언트 역할이\n--   아니면 개입하지 않는다(SECURITY DEFINER 내부 = postgres).\n--\n-- 적용 전 실측(2026-09-03 운영 read-only): 원장 DB-1(20260903100100~100300) · DB-2(20260903200100~200300) 적용 완료 ·\n--   soft_delete_own_content 부재 · comments_select_visible qual = ((is_deleted = false) AND (deleted_at IS NULL)) ·\n--   community_comment_soft_delete_self ACL anon=false / authenticated=true · 네 콘텐츠 테이블 0행(데이터 영향 0) ·\n--   public functions 226 · policies 175 · tables 84.\n--\n-- Apply: 저장소 표준 경로(db-apply-pending) — 즉석 실행 금지. 적용 순서 A(196) → B(197) → C(198).\n--   pack 등재: supabase/baseline/post_ledger_backfills/20260903230100_soft_delete_own_content_rpc.sql\n-- Rollback: supabase/rollback/20260903230100_soft_delete_own_content_rpc_rollback.sql\n-- 검증(§6): select proname, prosecdef, proconfig, has_function_privilege(''anon'', oid, ''EXECUTE'') anon,\n--                  has_function_privilege(''authenticated'', oid, ''EXECUTE'') authenticated\n--             from pg_proc where proname = ''soft_delete_own_content'';\n-- =============================================================================\n\nbegin", "-- ── 0. 사전 게이트 — 예상 상태와 다르면 중단(임의 정정 금지) ──────────────────\ndo $$\ndeclare v_n integer;\nbegin\n  select count(*) into v_n from information_schema.columns\n   where table_schema = ''public''\n     and ((table_name in (''shortform_posts'', ''comments'', ''community_comments'') and column_name in (''deleted_at'', ''deleted_by''))\n       or (table_name = ''community_posts'' and column_name in (''deleted_at'', ''deleted_by'')));\n  if v_n <> 8 then\n    raise exception ''196_GATE: deleted_at/deleted_by 컬럼 % 개(8 기대) — 194 미적용'', v_n;\n  end if;\n  if not exists (select 1 from pg_trigger where tgname = ''trg_comments_sync_deleted_flag'' and tgrelid = ''public.comments''::regclass) then\n    raise exception ''196_GATE: trg_comments_sync_deleted_flag 부재(194)'';\n  end if;\n  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''public'' and p.proname = ''soft_delete_own_content'') then\n    raise exception ''196_GATE: soft_delete_own_content 가 이미 있다(이미 적용됐거나 전제 불일치)'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''public'' and p.proname = ''account_deletion_write_blocked'') then\n    raise exception ''196_GATE: account_deletion_write_blocked 부재(151)'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''public'' and p.proname = ''community_comment_soft_delete_self'') then\n    raise exception ''196_GATE: community_comment_soft_delete_self 부재(앱 계약 — 그대로 둬야 한다)'';\n  end if;\n  if not exists (select 1 from pg_policies where schemaname = ''public'' and tablename = ''comments'' and policyname = ''comments_select_visible'' and qual like ''%deleted_at IS NULL%'') then\n    raise exception ''196_GATE: comments_select_visible 에 deleted_at 필터가 없다(194 불일치)'';\n  end if;\nend $$", "-- ── A-1. 함수 ─────────────────────────────────────────────────────────────────\ncreate function public.soft_delete_own_content(p_kind text, p_id uuid)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_author uuid;\n  v_creator uuid;\n  v_deleted_at timestamptz;\n  v_hidden boolean;\n  v_post_type text;\n  v_status text;\n  v_susp timestamptz;\n  v_norm text;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n  if p_id is null or p_kind is null or p_kind not in (''shortform'', ''shortform_comment'', ''board_comment'', ''board_post'') then\n    raise exception ''INVALID_KIND'' using errcode = ''22023'';\n  end if;\n\n  -- 대상 행 잠금 + 작성자 · 삭제 · 숨김(moderation) 상태\n  if p_kind = ''shortform'' then\n    select sp.author_id, sp.creator_id, sp.deleted_at, (sp.status = ''hidden'')\n      into v_author, v_creator, v_deleted_at, v_hidden\n      from public.shortform_posts sp where sp.id = p_id for update;\n  elsif p_kind = ''shortform_comment'' then\n    select cc.author_id, null::uuid, cc.deleted_at, (cc.status <> ''visible''), cc.post_type\n      into v_author, v_creator, v_deleted_at, v_hidden, v_post_type\n      from public.community_comments cc where cc.id = p_id for update;\n  elsif p_kind = ''board_comment'' then\n    select c.author_id, null::uuid, c.deleted_at, (c.is_deleted and c.deleted_at is null)\n      into v_author, v_creator, v_deleted_at, v_hidden\n      from public.comments c where c.id = p_id for update;\n  else\n    select cp.author_id, null::uuid, cp.deleted_at, (cp.status = ''hidden'')\n      into v_author, v_creator, v_deleted_at, v_hidden\n      from public.community_posts cp where cp.id = p_id for update;\n  end if;\n  if not found then\n    raise exception ''CONTENT_NOT_FOUND'' using errcode = ''P0001'';\n  end if;\n  if p_kind = ''shortform_comment'' and v_post_type is distinct from ''shortform'' then\n    raise exception ''CONTENT_KIND_MISMATCH'' using errcode = ''22023'';\n  end if;\n  -- 본인 판정 — 숏폼은 author_id 또는 creator_id(sf_update_own · sf_delete_own 과 같다) · 나머지는 author_id\n  if v_author is distinct from v_uid and v_creator is distinct from v_uid then\n    raise exception ''CONTENT_NOT_OWNED'' using errcode = ''42501'';\n  end if;\n\n  -- 계정 게이트 (community_comment_soft_delete_self 와 동일: banned · 유효 suspended · unknown/deleted · 삭제 진행 차단)\n  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id = v_uid;\n  if not found then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  v_norm := lower(btrim(coalesce(v_status, '''')));\n  if v_norm = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if v_norm not in (''active'', ''suspended'') then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  if public.account_deletion_write_blocked(v_uid) then raise exception ''ACCOUNT_DELETION_IN_PROGRESS''; end if;\n\n  -- 멱등: 이미 삭제된 행은 그대로 둔다(누가 지웠든)\n  if v_deleted_at is not null then\n    return;\n  end if;\n  -- 관리자가 숨긴 행은 본인이 삭제로 덮지 못한다(moderation 유지)\n  if coalesce(v_hidden, false) then\n    raise exception ''CONTENT_MODERATED'' using errcode = ''42501'';\n  end if;\n\n  if p_kind = ''shortform'' then\n    update public.shortform_posts set deleted_at = now(), deleted_by = v_uid where id = p_id;\n  elsif p_kind = ''shortform_comment'' then\n    update public.community_comments set deleted_at = now(), deleted_by = v_uid where id = p_id;\n  elsif p_kind = ''board_comment'' then\n    -- is_deleted 는 comments_sync_deleted_flag(194)가 true 로 · 레거시 미러 · 댓글 수 재계산은 기존 트리거\n    update public.comments set deleted_at = now(), deleted_by = v_uid where id = p_id;\n  else\n    update public.community_posts set deleted_at = now(), deleted_by = v_uid where id = p_id;\n  end if;\nend\n$$", "comment on function public.soft_delete_own_content(text, uuid) is\n  ''196(DB-3 A): 작성자 본인 소프트 삭제 단일 경로 — p_kind shortform|shortform_comment|board_comment|board_post. auth.uid() = 작성자(숏폼은 author_id|creator_id) · 계정 게이트 · 이미 삭제면 멱등 · 관리자 숨김 행은 CONTENT_MODERATED · deleted_at/deleted_by 만 기록(감사 로그 없음 — 관리자 삭제와 구분). 복원은 관리자만.''", "-- ── A-2. 권한 — authenticated 만(anon 금지) ────────────────────────────────────\nrevoke all on function public.soft_delete_own_content(text, uuid) from public, anon", "grant execute on function public.soft_delete_own_content(text, uuid) to authenticated, service_role", "-- ── 적용 직후 자가 검증 ───────────────────────────────────────────────────────\ndo $$\ndeclare v_oid oid;\nbegin\n  select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''public'' and p.proname = ''soft_delete_own_content''\n     and pg_get_function_identity_arguments(p.oid) = ''p_kind text, p_id uuid'';\n  if v_oid is null then\n    raise exception ''196_SELFCHECK: soft_delete_own_content(text, uuid) 부재'';\n  end if;\n  if not (select prosecdef from pg_proc where oid = v_oid)\n     or coalesce((select proconfig::text from pg_proc where oid = v_oid), '''') not like ''%search_path=%'' then\n    raise exception ''196_SELFCHECK: SECURITY DEFINER / search_path 설정 불일치'';\n  end if;\n  if (select prorettype::regtype::text from pg_proc where oid = v_oid) <> ''void'' then\n    raise exception ''196_SELFCHECK: 반환형이 void 가 아니다'';\n  end if;\n  if has_function_privilege(''anon'', v_oid, ''EXECUTE'')\n     or not has_function_privilege(''authenticated'', v_oid, ''EXECUTE'')\n     or not has_function_privilege(''service_role'', v_oid, ''EXECUTE'') then\n    raise exception ''196_SELFCHECK: ACL 불일치(anon 금지 · authenticated/service_role 허용)'';\n  end if;\n  if (select prosrc from pg_proc where oid = v_oid) not like ''%''''shortform'''', ''''shortform_comment'''', ''''board_comment'''', ''''board_post''''%'' then\n    raise exception ''196_SELFCHECK: p_kind 4종 목록 불일치'';\n  end if;\n  -- 기존 본인 삭제 RPC(앱 계약) 불변\n  if has_function_privilege(''anon'', ''public.community_comment_soft_delete_self(uuid)'', ''EXECUTE'')\n     or not has_function_privilege(''authenticated'', ''public.community_comment_soft_delete_self(uuid)'', ''EXECUTE'') then\n    raise exception ''196_SELFCHECK: community_comment_soft_delete_self ACL 변경됨'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "realtime_admin_topic_private", "version": "20260903230200", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 197_realtime_admin_topic_private.sql  (2026-09-03 · DB-3 묶음 B — Realtime 관리자 채널 비공개 ★)\n--\n-- 왜: PR-2b(멘토 승인 동시 심사 표시)의 Presence 채널 `admin:mentor-approval` 이 public 채널이다. public 채널은\n--   `realtime.messages` RLS 를 검사하지 않으므로 anon 키만 있으면 누구나 join 해 관리자 표시명·지금 보는 지원자 id 를 볼 수 있다.\n--   private 채널(`config.private = true`)은 join 시 Realtime 이 `realtime.messages` 의 RLS 정책(SELECT = 수신 · INSERT = 송신/presence track)\n--   을 그 사용자의 JWT 로 평가한다 — 정책이 0 개이면 전부 거부. 따라서 정책을 먼저 두고(이 파일), 그 다음 웹이 private 로 바꾼다(PR-W3).\n--\n-- B-1 정책: `admin:` 으로 시작하는 토픽은 is_admin() 인 authenticated 만 SELECT · INSERT.\n--   · realtime.topic() = current_setting(''realtime.topic'') — Realtime 이 인가 검사 트랜잭션에서 채널 토픽을 넣어 준다(운영 실측 본문 동일).\n--   · 그 외 토픽은 정책을 두지 않는다 = 현재 동작 유지. 실측(2026-09-03): 웹·앱 어느 쪽도 `realtime.messages` 를 쓰는 private 채널이 없다.\n--       웹: Realtime 사용처는 PR-2b Presence 채널 하나(public). 질문방·개별질문·알림 실시간은 웹에 없다.\n--       앱: question_thread_<id> · iq_<id> · notifications_<uid> 채널 = postgres_changes(public 채널 · 발행 supabase_realtime + 테이블 RLS) —\n--           `realtime.messages` 와 무관하다(Broadcast/Presence 인가 테이블). 이 정책은 그 채널들에 영향이 없다.\n--   · anon 은 정책 대상이 아니다(private 채널 join 거부 유지) · service_role 은 RLS 우회.\n-- B-2 클라이언트(PR-W3): PR-2b 채널 구독을 `config: { private: true }` + 구독 전 `supabase.realtime.setAuth()`. 정책이 없으면 구독이 실패하므로\n--   **이 파일 적용 후** 배포. 실패 시 조용히 unavailable(PR-2b 가 이미 그렇게 한다).\n--\n-- 적용 전 실측(2026-09-03 운영 read-only): realtime.messages 실재 · owner supabase_realtime_admin · RLS on(force off) · 정책 0 개 ·\n--   realtime.topic() 실재 · 컬럼 topic/extension/payload/event/private/updated_at/inserted_at/id/binary_payload ·\n--   GRANT anon/authenticated/service_role = SELECT·INSERT·UPDATE · postgres 는 owner 가 아니지만 supautils.policy_grants 에\n--   realtime.messages 가 등재돼 있어 CREATE POLICY 가 허용된다(storage.objects 정책 42 개가 같은 경로로 만들어졌다).\n--\n-- Apply: 저장소 표준 경로(db-apply-pending) — 즉석 실행 금지. 적용 순서 A(196) → B(197) → C(198).\n--   pack 등재: supabase/baseline/post_ledger_backfills/20260903230200_realtime_admin_topic_private.sql\n-- Rollback: supabase/rollback/20260903230200_realtime_admin_topic_private_rollback.sql\n-- 검증(§6): select policyname, cmd, roles, qual, with_check from pg_policies where schemaname = ''realtime'' and tablename = ''messages'';\n-- =============================================================================\n\nbegin", "-- ── 0. 사전 게이트 — 예상 상태와 다르면 중단(임의 정정 금지) ──────────────────\ndo $$\nbegin\n  if to_regclass(''realtime.messages'') is null then\n    raise exception ''197_GATE: realtime.messages 부재(Realtime 인가 테이블)'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''realtime'' and p.proname = ''topic'') then\n    raise exception ''197_GATE: realtime.topic() 부재'';\n  end if;\n  if not (select relrowsecurity from pg_class where oid = ''realtime.messages''::regclass) then\n    raise exception ''197_GATE: realtime.messages RLS 비활성(플랫폼 전제 불일치)'';\n  end if;\n  if exists (select 1 from pg_policies where schemaname = ''realtime'' and tablename = ''messages''\n              and policyname in (''realtime_admin_topic_select'', ''realtime_admin_topic_insert'')) then\n    raise exception ''197_GATE: 정책이 이미 있다(이미 적용됐거나 전제 불일치)'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''public'' and p.proname = ''is_admin'')\n     or not has_function_privilege(''authenticated'', ''public.is_admin()'', ''EXECUTE'') then\n    raise exception ''197_GATE: public.is_admin() 부재 또는 authenticated EXECUTE 불가'';\n  end if;\n  raise notice ''197 pre: realtime.messages 기존 정책 % 개'', (select count(*) from pg_policies where schemaname = ''realtime'' and tablename = ''messages'');\nend $$", "-- ── B-1. 정책 — admin:* 토픽은 관리자만 ───────────────────────────────────────\ncreate policy realtime_admin_topic_select on realtime.messages\n  for select\n  to authenticated\n  using (\n    realtime.topic() like ''admin:%''\n    and coalesce((select public.is_admin()), false)\n  )", "create policy realtime_admin_topic_insert on realtime.messages\n  for insert\n  to authenticated\n  with check (\n    realtime.topic() like ''admin:%''\n    and coalesce((select public.is_admin()), false)\n  )", "comment on policy realtime_admin_topic_select on realtime.messages is\n  ''197(DB-3 B): admin:* 토픽(private 채널)의 수신(Broadcast/Presence)은 관리자(is_admin())만. 그 외 토픽은 정책 없음(현 동작 유지).''", "comment on policy realtime_admin_topic_insert on realtime.messages is\n  ''197(DB-3 B): admin:* 토픽(private 채널)의 송신·presence track 은 관리자(is_admin())만.''", "-- ── 적용 직후 자가 검증 ───────────────────────────────────────────────────────\ndo $$\nbegin\n  if (select count(*) from pg_policies where schemaname = ''realtime'' and tablename = ''messages''\n       and ((policyname = ''realtime_admin_topic_select'' and cmd = ''SELECT'' and roles = ''{authenticated}''::name[]\n             and qual like ''%admin:%'' and qual like ''%is_admin()%'')\n         or (policyname = ''realtime_admin_topic_insert'' and cmd = ''INSERT'' and roles = ''{authenticated}''::name[]\n             and with_check like ''%admin:%'' and with_check like ''%is_admin()%''))) <> 2 then\n    raise exception ''197_SELFCHECK: realtime.messages 정책 2종 불일치'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "ugc_block_hard_delete", "version": "20260903230300", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 198_ugc_block_hard_delete.sql  (2026-09-03 · DB-3 묶음 C — 하드 DELETE 차단 ★ · §0 판정 후 포함)\n--\n-- 왜: DB-2(194 B-4)에서 오너 결정으로 뺐던 하드 DELETE 차단을, 작성자 본인 삭제 RPC(196)가 생긴 뒤 다시 넣는다.\n--   숏폼·게시판 댓글·숏폼 댓글은 deleted_at/deleted_by 로만 지운다.\n--\n-- §0 웹·앱 삭제 경로표(2026-09-03 실측 — 이 파일을 넣는 근거):\n--   | 대상            | 웹                                                      | 앱(byite-co/ssambership-app @635ae73)                     |\n--   | 숏폼 본인 삭제   | 없음(삭제 UI·액션 없음 — shortform_posts .delete() 0)    | 없음(읽기 중심 — shortform_posts .delete() 0)              |\n--   | 숏폼 댓글 본인   | RPC community_comment_soft_delete_self                  | RPC community_comment_soft_delete_self(outbound manifest)  |\n--   | 게시판 댓글 본인 | UPDATE comments SET is_deleted = true(RLS 거부 · 실패 중) | 없음(게시판 댓글 읽기 뷰만 · 삭제 UI 없음)                  |\n--   앱의 .delete() 는 post_reactions · shortform_reactions · mentor_favorites · user_blocks · connection_notes 뿐 — 세 테이블 직접 DELETE 0.\n--   웹 관리자 코드는 PR-W2 로 소프트 삭제 UPDATE 만(communitySoftDeleteReadPaths 트립와이어 · 하드 DELETE 0).\n--   → \"앱이 직접 DELETE 를 안 쓴다\" 조건 충족 — C 포함.\n--\n-- C-1 트리거: shortform_posts · comments · community_comments 에 BEFORE DELETE 트리거(ugc_block_hard_delete).\n--   · current_user 가 anon · authenticated(관리자 세션 포함)이면 UGC_HARD_DELETE_FORBIDDEN(42501).\n--   · service_role 은 통과(관리자 코어 · 배치용 — 지시서). 같은 이유로 postgres(SECURITY DEFINER 함수 내부 · pg_cron · 마이그레이션)와\n--     supabase_auth_admin(auth.users 삭제 → public.users → author_id ON DELETE CASCADE)도 통과한다 — 194 쓰기 가드 2종과 같은\n--     \"클라이언트 역할만 차단\" 판정이라 cascade · 배치 · 탈퇴 purge 를 깨지 않는다(탈퇴 purge 는 이 세 표를 DELETE 하지 않고\n--     auth 는 soft delete — deleteUser(uid, true)).\n--   · 기존 comments_write_guard 의 DELETE 분기(관리자 세션 허용)는 그대로 두되, 이 트리거가 이름순(trg_comments_no_delete <\n--     trg_comments_write_guard)으로 먼저 발화해 관리자 세션도 거부한다 — 관리자 삭제는 service_role 코어(PR-W2 UPDATE) 경로다.\n--   · 정본·레거시 DELETE 미러(cc_sync_board_delete_to_canonical · comments_mirror_delete_to_legacy)는 service_role/postgres 경로에서만\n--     발화하게 되며 동작은 불변.\n--\n-- 적용 전 실측(2026-09-03 운영 read-only): ugc_block_hard_delete 부재 · *_no_delete 트리거 0 · 세 테이블 0행 ·\n--   기존 트리거: shortform_posts(adg_shortform_posts · trg_shortform_posts_protected) · comments(mirror 2 · refresh_count · author_label 2 ·\n--   sync_deleted_flag · write_guard) · community_comments(author_label 4 · cc_sync 2 · cc_write_guard · set_updated).\n--\n-- Apply: 저장소 표준 경로(db-apply-pending) — 즉석 실행 금지. 적용 순서 A(196) → B(197) → C(198). **앱·웹 새 버전이 RPC 를 쓰기 전에\n--   적용해도 되는 근거는 §0(세 테이블 직접 DELETE 0)** 이다.\n--   pack 등재: supabase/baseline/post_ledger_backfills/20260903230300_ugc_block_hard_delete.sql\n-- Rollback: supabase/rollback/20260903230300_ugc_block_hard_delete_rollback.sql\n-- 검증(§6): select tgrelid::regclass, tgname from pg_trigger where tgname like ''trg_%_no_delete'' order by 1;\n-- =============================================================================\n\nbegin", "-- ── 0. 사전 게이트 — 예상 상태와 다르면 중단(임의 정정 금지) ──────────────────\ndo $$\nbegin\n  if (select count(*) from information_schema.columns where table_schema = ''public''\n       and table_name in (''shortform_posts'', ''comments'', ''community_comments'') and column_name in (''deleted_at'', ''deleted_by'')) <> 6 then\n    raise exception ''198_GATE: deleted_at/deleted_by 컬럼 6 개가 아니다 — 194 미적용'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''public'' and p.proname = ''soft_delete_own_content'') then\n    raise exception ''198_GATE: soft_delete_own_content 부재 — 196 먼저(작성자 삭제 경로 없이 하드 DELETE 를 막지 않는다)'';\n  end if;\n  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''public'' and p.proname = ''ugc_block_hard_delete'') then\n    raise exception ''198_GATE: ugc_block_hard_delete 가 이미 있다(이미 적용됐거나 전제 불일치)'';\n  end if;\n  if exists (select 1 from pg_trigger where tgname in (''trg_shortform_posts_no_delete'', ''trg_comments_no_delete'', ''trg_community_comments_no_delete'')) then\n    raise exception ''198_GATE: *_no_delete 트리거가 이미 있다'';\n  end if;\n  if not exists (select 1 from pg_trigger where tgname = ''trg_comments_write_guard'' and tgrelid = ''public.comments''::regclass) then\n    raise exception ''198_GATE: trg_comments_write_guard 부재(164)'';\n  end if;\nend $$", "-- ── C-1. 트리거 함수 — 클라이언트 역할의 하드 DELETE 거부 ─────────────────────\ncreate function public.ugc_block_hard_delete()\nreturns trigger\nlanguage plpgsql\nset search_path to ''''\nas $$\nbegin\n  -- SECURITY INVOKER 필수 — current_user 게이트가 실제 클라이언트 역할을 봐야 한다(194 가드와 동일).\n  -- service_role · postgres(SECURITY DEFINER 내부 · pg_cron · 마이그레이션) · supabase_auth_admin(cascade)은 통과.\n  if current_user in (''anon'', ''authenticated'') then\n    raise exception ''UGC_HARD_DELETE_FORBIDDEN: %.% is soft-delete only (deleted_at/deleted_by · soft_delete_own_content)'', tg_table_schema, tg_table_name\n      using errcode = ''42501'';\n  end if;\n  return old;\nend\n$$", "comment on function public.ugc_block_hard_delete() is\n  ''198(DB-3 C): shortform_posts · comments · community_comments 의 하드 DELETE 를 클라이언트 역할(anon · authenticated — 관리자 세션 포함)에 거부한다. service_role · postgres · supabase_auth_admin 은 통과(관리자 코어 · 배치 · cascade). 삭제는 deleted_at/deleted_by 로만.''", "revoke all on function public.ugc_block_hard_delete() from public, anon, authenticated", "create trigger trg_shortform_posts_no_delete\n  before delete on public.shortform_posts\n  for each row execute function public.ugc_block_hard_delete()", "create trigger trg_comments_no_delete\n  before delete on public.comments\n  for each row execute function public.ugc_block_hard_delete()", "create trigger trg_community_comments_no_delete\n  before delete on public.community_comments\n  for each row execute function public.ugc_block_hard_delete()", "-- ── 적용 직후 자가 검증 ───────────────────────────────────────────────────────\ndo $$\ndeclare v_n integer;\nbegin\n  select count(*) into v_n from pg_trigger t\n   where not t.tgisinternal and t.tgfoid = ''public.ugc_block_hard_delete()''::regprocedure\n     and ((t.tgrelid = ''public.shortform_posts''::regclass and t.tgname = ''trg_shortform_posts_no_delete'')\n       or (t.tgrelid = ''public.comments''::regclass and t.tgname = ''trg_comments_no_delete'')\n       or (t.tgrelid = ''public.community_comments''::regclass and t.tgname = ''trg_community_comments_no_delete''))\n     and pg_get_triggerdef(t.oid) like ''%BEFORE DELETE%FOR EACH ROW%'';\n  if v_n <> 3 then\n    raise exception ''198_SELFCHECK: no_delete 트리거 % 개(3 기대)'', v_n;\n  end if;\n  if (select prosecdef from pg_proc where oid = ''public.ugc_block_hard_delete()''::regprocedure) then\n    raise exception ''198_SELFCHECK: 트리거 함수가 SECURITY DEFINER 다(current_user 게이트 무력화)'';\n  end if;\n  if has_function_privilege(''anon'', ''public.ugc_block_hard_delete()'', ''EXECUTE'')\n     or has_function_privilege(''authenticated'', ''public.ugc_block_hard_delete()'', ''EXECUTE'') then\n    raise exception ''198_SELFCHECK: 트리거 함수에 anon·authenticated EXECUTE 잔존'';\n  end if;\n  -- 기존 트리거 불변\n  if not exists (select 1 from pg_trigger where tgname = ''trg_comments_write_guard'' and tgrelid = ''public.comments''::regclass)\n     or not exists (select 1 from pg_trigger where tgname = ''trg_comments_sync_deleted_flag'' and tgrelid = ''public.comments''::regclass) then\n    raise exception ''198_SELFCHECK: comments 기존 트리거 소실'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "api_app_v1_subscribe_with_cash", "version": "20260905100100", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 199_api_app_v1_subscribe_with_cash.sql  (2026-09-05 · DB-4 묶음 A — 앱 구독 결제 · 해지 예약 ★)\n--\n-- 왜: 앱은 service_role 이 없어 구독 결제(F12 `api_web_v1.subscription_checkout_confirm_v2` — service_role 전용)와\n--   구독 해지 예약(`subscriptions` UPDATE — authenticated 정책 028 에서 DROP)을 부를 수 없다(A-4a 판정표 #8 · DB-4 지시서 §A).\n--   `authenticated` 만 실행하는 SECURITY DEFINER 래퍼를 `api_app_v1` 에 둔다. 핵심 로직은 복제하지 않고 위임한다.\n--\n-- 0-A 부수 효과 대조(웹 `lib/subscribe/subscribeCheckoutService.ts` 캐시 지갑 경로 전수 — 이 래퍼가 수행하는 것):\n--   ① TS 사전 게이트(학생 역할·계정 상태·멘토 승인·활동 상태(paused/terminating)·구독 열림·중복 구독·cap·잔액) → 이 함수 §게이트\n--   ② `payments` intent 행(pending · kind subscription · amount KRW · metadata expected_amount_cents) → 이 함수가 INSERT\n--   ③ F12 `api_web_v1.subscription_checkout_confirm_v2(payment, plan, expected, ''sub_checkout_<payment>'')` → 그대로 호출\n--        └ 정본 `confirm_subscription_checkout`(subscriptions upsert · `enforce_mentor_cap` 트리거 · `record_subscription_cash_debit` 원장+지갑 · payments succeeded)\n--        └ `core_private.ensure_student_mentor_room`(방 확보 · 참조 보정 · 실패 시 자금 전부 롤백)\n--   ④ TS `recordInitialSubscriptionBillingEvent`(subscription_billing_events initial/succeeded upsert `sub_initial:<sub>` +\n--        subscriptions.last_billing_event_id/last_payment_id) → 이 함수가 같은 키·같은 필드로 수행(정산 항목 배치 `refresh_subscription_settlement_items` 의 원천)\n--   ⑤ 알림: 최초 구독은 웹도 알림 0(157 트리거는 renewal/expired 만) → 동일\n--   ⑥ 웹 부가(best-effort) `transferReleasedIndividualQuestionsToRoom` 은 Storage 파일 복제가 필요해 SQL 밖 — 이 래퍼는 수행하지 않는다(보고서 §0-A)\n--   ⑦ 웹 라우트의 본인인증 게이트(`requireVerifiedIdentity` · IDENTITY_GATE_ENABLED env 종속)는 S-C 정책상 \"DB/RPC 레벨 가드 0\" 이라\n--        DB 에 두지 않는다(보고서 오너 결정 항목)\n--\n-- A-1 api_app_v1.subscribe_with_cash(p_mentor_id uuid, p_tier text, p_idempotency_key text) returns jsonb\n--   · 게이트 순서: AUTH_REQUIRED → MENTOR_NOT_FOUND(인자) → PLAN_TIER_INVALID → IDEMPOTENCY_KEY_INVALID → (잠금) → 멱등 재생 →\n--     ROLE_NOT_STUDENT → ACCOUNT_BANNED / ACCOUNT_SUSPENDED / ACCOUNT_NOT_ACTIVE / ACCOUNT_DELETION_IN_PROGRESS →\n--     MENTOR_NOT_FOUND → MENTOR_NOT_APPROVED → MENTOR_TERMINATED / MENTOR_PAUSED → MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS → BLOCKED(상호 차단 · F10 동일) →\n--     ALREADY_SUBSCRIBED → PLAN_NOT_FOUND / PLAN_INACTIVE / PLAN_AMOUNT_INVALID → MENTOR_CAP_EXCEEDED → CASH_INSUFFICIENT(shortfall_cents)\n--   · 실차감액 = `mentor_plans.amount_cents`(멘토가 정한 값 · 행이 없으면 PLAN_NOT_FOUND — 권장가 시드는 하지 않는다: 승인 시 166 트리거가 3 tier 를 만든다)\n--   · 멱등: `payments.external_id = ''sub_app_'' || p_idempotency_key` + (학생, 키) advisory xact lock. 같은 키 재호출은 첫 결과(`payments.metadata.app_result`)를\n--     `idempotent: true` 로 그대로 돌려준다(차감 0). 같은 키·다른 멘토/tier 는 IDEMPOTENCY_KEY_CONFLICT.\n--     실패한 시도는 payments 행을 남기지 않는다(subtransaction rollback) — 재시도는 새로 판정된다.\n--   · F12 envelope 실패는 같은 코드로 승격한다. 이상(anomaly) 계열 코드는 롤백 후 `subscription_checkout_anomalies` 에 payment_id NULL 로 다시 기록한다.\n--   · 반환: {ok, contract_version:1, idempotent, subscription_id, room_id, payment_id, plan_id, plan_tier, debited_cents, balance_after_cents,\n--            reactivated, current_period_start, current_period_end, next_billing_at}\n-- A-2 api_app_v1.subscription_cancel_at_period_end(p_subscription_id uuid) · api_app_v1.subscription_cancel_undo(p_subscription_id uuid) returns jsonb\n--   · 웹 `lib/subscribe/subscriptionCancelActions.ts` 동일: 본인 구독 · status ∈ {active, past_due} · cancel_at_period_end/cancel_requested_at 만 갱신.\n--   · 코드: AUTH_REQUIRED · ROLE_NOT_STUDENT · SUBSCRIPTION_NOT_FOUND · NOT_SUBSCRIPTION_OWNER · SUBSCRIPTION_NOT_CURRENT(status).\n--   · 멱등(이미 예약/이미 해제면 그대로 ok). 트리거 대조: enforce_mentor_cap(status·plan_tier 만) · keep_subscription_refunded_status(status 만) ·\n--     sub_notify_expired(status→expired 만) · sync_subscription_refunded_from_refund(refunds 표) — 어느 것도 이 두 컬럼 변경에 발화하지 않는다.\n-- 권한: 세 함수 모두 REVOKE public·anon · GRANT EXECUTE authenticated 만(M17 앱 계약 §3.3 — service_role 미부여). 웹은 자기 경로(F12) 그대로.\n--\n-- 적용 전 실측(2026-09-05 운영 read-only): 구독 0 · 환불 0 · 분쟁 0 → 데이터 영향 0. api_app_v1 함수 6(M17 5 + user_profile_update_self).\n-- Apply: 저장소 표준 경로(db-apply-pending) — 즉석 실행 금지. 순서 A(199) → B(200) → C(201) → D(202) → E(203) → F(204).\n--   pack 등재: supabase/baseline/post_ledger_backfills/20260905100100_api_app_v1_subscribe_with_cash.sql\n-- Rollback: supabase/rollback/20260905100100_api_app_v1_subscribe_with_cash_rollback.sql\n-- 검증(§6): select p.proname, p.prosecdef, has_function_privilege(''anon'', p.oid, ''EXECUTE'') anon,\n--                  has_function_privilege(''authenticated'', p.oid, ''EXECUTE'') authenticated\n--             from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n--            where n.nspname = ''api_app_v1'' and p.proname in (''subscribe_with_cash'',''subscription_cancel_at_period_end'',''subscription_cancel_undo'');\n-- =============================================================================\n\nbegin", "-- ── 0. 사전 게이트 — 예상 상태와 다르면 중단(임의 정정 금지) ──────────────────\ndo $$\nbegin\n  if not exists (select 1 from pg_namespace where nspname = ''api_app_v1'') then\n    raise exception ''199_GATE: api_app_v1 스키마 부재(M17)'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''api_web_v1'' and p.proname = ''subscription_checkout_confirm_v2''\n                    and pg_get_function_identity_arguments(p.oid) = ''p_payment_id uuid, p_plan_id uuid, p_expected_amount_cents integer, p_idempotency_key text'') then\n    raise exception ''199_GATE: api_web_v1.subscription_checkout_confirm_v2 identity 불일치(M9)'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''public'' and p.proname = ''confirm_subscription_checkout''\n                    and p.prosrc like ''%record_subscription_cash_debit%'') then\n    raise exception ''199_GATE: confirm_subscription_checkout 정본 부재'';\n  end if;\n  if (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n       where n.nspname = ''public'' and p.proname in (''mentor_cap_used'', ''mentor_cap_limit'', ''subscription_cap_weight'',\n                                                    ''individual_question_user_is_approved_mentor'', ''account_deletion_write_blocked'')) <> 5 then\n    raise exception ''199_GATE: cap·승인·탈퇴 헬퍼 5종 부재'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''payments''\n       and column_name in (''id'',''user_id'',''mentor_id'',''amount'',''currency'',''status'',''kind'',''plan_id'',''external_id'',''metadata'')) <> 10 then\n    raise exception ''199_GATE: payments 컬럼 불일치'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''subscriptions''\n       and column_name in (''id'',''student_id'',''mentor_id'',''plan_id'',''plan_tier'',''status'',''payment_id'',''started_at'',''current_period_start'',''current_period_end'',\n                           ''next_billing_at'',''cancel_at_period_end'',''cancel_requested_at'',''last_billing_event_id'',''last_payment_id'',''created_at'')) <> 16 then\n    raise exception ''199_GATE: subscriptions 컬럼 불일치'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''subscription_billing_events''\n       and column_name in (''subscription_id'',''student_id'',''mentor_id'',''event_type'',''status'',''period_start'',''period_end'',''billing_at'',''amount_cents'',\n                           ''plan_tier'',''plan_id'',''idempotency_key'',''ledger_id'',''payment_id'',''processed_at'')) <> 15\n     or not exists (select 1 from pg_constraint where conrelid = ''public.subscription_billing_events''::regclass and contype = ''u''\n                     and pg_get_constraintdef(oid) like ''%idempotency_key%'') then\n    raise exception ''199_GATE: subscription_billing_events 컬럼/idempotency UNIQUE 불일치'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''mentor_profiles''\n       and column_name in (''user_id'',''activity_status'',''pause_until'',''is_open_for_subscriptions'')) <> 4 then\n    raise exception ''199_GATE: mentor_profiles 활동·열림 컬럼 불일치(103·131)'';\n  end if;\n  if not exists (select 1 from pg_indexes where schemaname = ''public'' and tablename = ''mentor_plans'' and indexname = ''uq_mentor_plans_mentor_tier'') then\n    raise exception ''199_GATE: uq_mentor_plans_mentor_tier 부재(067)'';\n  end if;\n  if not exists (select 1 from information_schema.tables where table_schema = ''public'' and table_name = ''subscription_checkout_anomalies'') then\n    raise exception ''199_GATE: subscription_checkout_anomalies 부재(145)'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''user_blocks'' and column_name in (''blocker_id'',''blocked_id'')) <> 2 then\n    raise exception ''199_GATE: user_blocks(blocker_id, blocked_id) 부재'';\n  end if;\n  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n              where n.nspname = ''api_app_v1'' and p.proname in (''subscribe_with_cash'', ''subscription_cancel_at_period_end'', ''subscription_cancel_undo'')) then\n    raise exception ''199_GATE: 대상 함수가 이미 있다(이미 적용됐거나 전제 불일치)'';\n  end if;\nend $$", "-- ── A-1. subscribe_with_cash ─────────────────────────────────────────────────\ncreate function api_app_v1.subscribe_with_cash(\n  p_mentor_id uuid,\n  p_tier text,\n  p_idempotency_key text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_tier text := lower(btrim(coalesce(p_tier, '''')));\n  v_key text := btrim(coalesce(p_idempotency_key, ''''));\n  v_ext text;\n  v_succeeded constant text[] := array[''succeeded'',''paid'',''success'',''complete'',''captured''];\n  -- 롤백 후에도 운영 진단을 위해 anomaly 를 다시 기록할 코드(정본·F12 anomaly 계열)\n  v_anomaly_codes constant text[] := array[''FINANCIAL_WRITE_ERROR'',''LEDGER_FIELD_MISMATCH'',''ROOM_ENSURE_FAILED'',''ROOM_REF_MISMATCH'',\n    ''PLAN_AMOUNT_CHANGED'',''SUCCEEDED_NO_SUBSCRIPTION'',''SUCCEEDED_NO_LEDGER'',''PLAN_BINDING_MISMATCH'',''PARTY_BINDING_MISMATCH'',\n    ''LEDGER_BINDING_MISMATCH'',''SUBSCRIPTION_REF_INVALID'',''LEDGER_AMOUNT_MISMATCH''];\n  v_role text; v_status text; v_susp timestamptz; v_norm text;\n  v_mrole text;\n  v_act text; v_pause_until timestamptz; v_open boolean;\n  v_dup uuid;\n  v_plan_id uuid; v_plan_active boolean; v_amount integer;\n  v_cap_used numeric; v_cap_limit numeric; v_cap_weight numeric;\n  v_balance bigint;\n  v_pay record;\n  v_payment_id uuid;\n  v_res jsonb;\n  v_abort_code text;\n  v_abort_detail jsonb;\n  v_sub_id uuid; v_room_id uuid; v_reactivated boolean;\n  v_sub record; v_ledger record;\n  v_period_start timestamptz; v_period_end timestamptz;\n  v_event_id uuid;\n  v_balance_after bigint;\n  v_result jsonb;\n  v_anom uuid;\nbegin\n  if v_uid is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  end if;\n  if p_mentor_id is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_FOUND'');\n  end if;\n  if v_tier not in (''limited'', ''standard'', ''premium'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_TIER_INVALID'');\n  end if;\n  if v_key = '''' or char_length(v_key) > 128 then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''IDEMPOTENCY_KEY_INVALID'');\n  end if;\n  v_ext := ''sub_app_'' || v_key;\n\n  -- 직렬화: (학생, 키) — 같은 키 동시 재시도는 첫 호출 커밋 뒤 재생으로 수렴 · (학생, 멘토) — 정본과 같은 pair 잠금(재진입)\n  perform pg_advisory_xact_lock(hashtext(''app_sub_key:'' || v_uid::text), hashtext(v_key));\n  perform pg_advisory_xact_lock(hashtext(v_uid::text), hashtext(p_mentor_id::text));\n\n  -- 멱등 재생 — 성공한 첫 결과를 그대로(차감 0). 실패 시도는 행을 남기지 않으므로 여기 오면 성공 행뿐이다.\n  select p.id, p.status, p.mentor_id, p.metadata into v_pay\n    from public.payments p\n   where p.user_id = v_uid and p.external_id = v_ext\n   order by p.created_at desc\n   limit 1\n   for update;\n  if found then\n    if v_pay.status = any(v_succeeded) and (v_pay.metadata ? ''app_result'') then\n      if v_pay.mentor_id is distinct from p_mentor_id or (v_pay.metadata ->> ''planTier'') is distinct from v_tier then\n        return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''IDEMPOTENCY_KEY_CONFLICT'',\n                                  ''payment_id'', v_pay.id);\n      end if;\n      return (v_pay.metadata -> ''app_result'') || jsonb_build_object(''idempotent'', true);\n    end if;\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''IDEMPOTENCY_KEY_CONFLICT'',\n                              ''payment_id'', v_pay.id, ''payment_status'', v_pay.status);\n  end if;\n\n  -- 학생 · 계정 상태 (F10·정본과 동일 판정식)\n  select u.role, u.status, u.suspended_until into v_role, v_status, v_susp from public.users u where u.id = v_uid;\n  if not found or v_role is distinct from ''student'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROLE_NOT_STUDENT'');\n  end if;\n  v_norm := lower(btrim(coalesce(v_status, '''')));\n  if v_norm = ''banned'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_BANNED'');\n  end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_SUSPENDED'');\n  end if;\n  if v_norm not in (''active'', ''suspended'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_NOT_ACTIVE'');\n  end if;\n  if public.account_deletion_write_blocked(v_uid) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  end if;\n\n  -- 멘토: 역할 · 승인 · 활동 상태(웹 mentorActivityState 동일) · 구독 열림\n  select u.role into v_mrole from public.users u where u.id = p_mentor_id;\n  if not found or v_mrole is distinct from ''mentor'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_FOUND'');\n  end if;\n  if not public.individual_question_user_is_approved_mentor(p_mentor_id) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_APPROVED'');\n  end if;\n  select mp.activity_status, mp.pause_until, mp.is_open_for_subscriptions into v_act, v_pause_until, v_open\n    from public.mentor_profiles mp where mp.user_id = p_mentor_id;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_FOUND'');\n  end if;\n  v_act := lower(btrim(coalesce(v_act, ''active'')));\n  if v_act in (''terminating'', ''terminated'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_TERMINATED'');\n  end if;\n  if v_act = ''paused'' and (v_pause_until is null or v_pause_until > now()) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_PAUSED'', ''pause_until'', v_pause_until);\n  end if;\n  if not coalesce(v_open, true) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS'');\n  end if;\n  -- 상호 차단(F10 ③ 과 같은 판정) — 웹은 이 경우 F12 의 방 확보 단계에서 ROOM_ENSURE_FAILED 로 실패한다(차감 0). 앱에는 코드로 먼저 알린다.\n  if exists (select 1 from public.user_blocks b\n              where (b.blocker_id = v_uid and b.blocked_id = p_mentor_id) or (b.blocker_id = p_mentor_id and b.blocked_id = v_uid)) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''BLOCKED'');\n  end if;\n\n  -- 중복 구독 (활성 pair 1행 모델)\n  select s.id into v_dup from public.subscriptions s\n   where s.student_id = v_uid and s.mentor_id = p_mentor_id and lower(coalesce(s.status, '''')) = ''active'';\n  if v_dup is not null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ALREADY_SUBSCRIBED'', ''subscription_id'', v_dup);\n  end if;\n\n  -- 요금제 행 = 실차감액 (멘토가 정한 값 · 잠금은 F12 가 다시 건다)\n  select mp.id, mp.is_active, mp.amount_cents into v_plan_id, v_plan_active, v_amount\n    from public.mentor_plans mp where mp.mentor_id = p_mentor_id and mp.plan_tier = v_tier;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_NOT_FOUND'', ''plan_tier'', v_tier);\n  end if;\n  if not coalesce(v_plan_active, true) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_INACTIVE'', ''plan_tier'', v_tier);\n  end if;\n  if v_amount is null or v_amount <= 0 or v_amount % 100 <> 0 then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_AMOUNT_INVALID'', ''plan_tier'', v_tier);\n  end if;\n\n  -- 정원 (정본 판정식 그대로 — DB 함수 3종 · 최종 방어는 enforce_mentor_cap 트리거)\n  v_cap_used := public.mentor_cap_used(p_mentor_id);\n  v_cap_weight := public.subscription_cap_weight(v_tier);\n  v_cap_limit := public.mentor_cap_limit(p_mentor_id);\n  if v_cap_used + v_cap_weight > v_cap_limit then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_CAP_EXCEEDED'',\n                              ''cap_used'', v_cap_used, ''cap_weight'', v_cap_weight, ''cap_limit'', v_cap_limit);\n  end if;\n\n  -- 잔액 (사전 판정 — 실제 차감의 원자 판정은 record_subscription_cash_debit)\n  select w.balance_cents into v_balance from public.cash_wallets w where w.user_id = v_uid;\n  v_balance := coalesce(v_balance, 0);\n  if v_balance < v_amount then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''CASH_INSUFFICIENT'',\n                              ''required_cents'', v_amount, ''balance_cents'', v_balance, ''shortfall_cents'', v_amount - v_balance);\n  end if;\n\n  -- 자금 단계 — 한 subtransaction: intent → F12(정본 confirm + 방) → initial billing event. 실패 시 전부 롤백.\n  begin\n    insert into public.payments (user_id, mentor_id, status, amount, currency, kind, plan_id, external_id, metadata)\n    values (v_uid, p_mentor_id, ''pending'', (v_amount::numeric / 100), ''KRW'', ''subscription'', v_plan_id, v_ext,\n            jsonb_build_object(''planTier'', v_tier, ''planId'', v_plan_id::text, ''source'', ''app_subscribe_with_cash'',\n                               ''expected_amount_cents'', v_amount, ''idempotency_key'', v_key))\n    returning id into v_payment_id;\n\n    v_res := api_web_v1.subscription_checkout_confirm_v2(v_payment_id, v_plan_id, v_amount, ''sub_checkout_'' || v_payment_id::text);\n    if not coalesce((v_res ->> ''ok'')::boolean, false) then\n      v_abort_code := coalesce(v_res ->> ''code'', ''FINANCIAL_WRITE_ERROR'');\n      v_abort_detail := v_res - ''ok'' - ''contract_version'' - ''code'';\n      raise exception ''APP_SUB_ABORT'';\n    end if;\n    v_sub_id := (v_res ->> ''subscription_id'')::uuid;\n    v_room_id := (v_res ->> ''room_id'')::uuid;\n    v_reactivated := coalesce((v_res ->> ''reactivated'')::boolean, false);\n\n    -- ④ initial billing event — 웹 recordInitialSubscriptionBillingEvent 와 같은 키·필드(upsert)\n    select s.student_id, s.mentor_id, s.plan_tier, s.plan_id, s.created_at, s.started_at,\n           s.current_period_start, s.current_period_end, s.next_billing_at, s.payment_id\n      into v_sub\n      from public.subscriptions s where s.id = v_sub_id;\n    select l.id, l.created_at into v_ledger\n      from public.cash_ledger l where l.idempotency_key = ''sub_debit_'' || v_payment_id::text;\n    v_period_start := coalesce(v_sub.current_period_start, v_sub.started_at, v_sub.created_at, now());\n    v_period_end := coalesce(v_sub.current_period_end,\n                             ((v_period_start at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul''));\n    insert into public.subscription_billing_events\n      (subscription_id, student_id, mentor_id, event_type, status, period_start, period_end, billing_at, amount_cents,\n       plan_tier, plan_id, idempotency_key, ledger_id, payment_id, processed_at)\n    values\n      (v_sub_id, coalesce(v_sub.student_id, v_uid), coalesce(v_sub.mentor_id, p_mentor_id), ''initial'', ''succeeded'',\n       v_period_start, v_period_end, coalesce(v_ledger.created_at, v_sub.created_at, now()), v_amount,\n       coalesce(v_sub.plan_tier, v_tier), v_sub.plan_id, ''sub_initial:'' || v_sub_id::text, v_ledger.id,\n       coalesce(v_sub.payment_id, v_payment_id), coalesce(v_ledger.created_at, now()))\n    on conflict (idempotency_key) do update\n      set subscription_id = excluded.subscription_id, student_id = excluded.student_id, mentor_id = excluded.mentor_id,\n          event_type = excluded.event_type, status = excluded.status, period_start = excluded.period_start,\n          period_end = excluded.period_end, billing_at = excluded.billing_at, amount_cents = excluded.amount_cents,\n          plan_tier = excluded.plan_tier, plan_id = excluded.plan_id, ledger_id = excluded.ledger_id,\n          payment_id = excluded.payment_id, processed_at = excluded.processed_at\n    returning id into v_event_id;\n    update public.subscriptions s\n       set last_billing_event_id = v_event_id, last_payment_id = v_payment_id\n     where s.id = v_sub_id;\n\n    select w.balance_cents into v_balance_after from public.cash_wallets w where w.user_id = v_uid;\n    v_result := jsonb_build_object(\n      ''ok'', true, ''contract_version'', 1, ''idempotent'', false,\n      ''subscription_id'', v_sub_id, ''room_id'', v_room_id, ''payment_id'', v_payment_id,\n      ''plan_id'', v_plan_id, ''plan_tier'', v_tier,\n      ''debited_cents'', v_amount, ''balance_after_cents'', coalesce(v_balance_after, 0),\n      ''reactivated'', v_reactivated,\n      ''current_period_start'', v_sub.current_period_start, ''current_period_end'', v_sub.current_period_end,\n      ''next_billing_at'', v_sub.next_billing_at);\n    -- 재생용 첫 결과 보존 (정본이 넣은 planId/subscription_id 는 그대로 두고 app_result 만 덧붙인다)\n    update public.payments p\n       set metadata = coalesce(p.metadata, ''{}''::jsonb) || jsonb_build_object(''app_result'', v_result)\n     where p.id = v_payment_id;\n  exception when others then\n    if sqlerrm <> ''APP_SUB_ABORT'' then\n      raise;   -- 사전 밖 예외는 그대로 전파(§8.2)\n    end if;\n  end;\n\n  if v_abort_code is not null then\n    -- 이 시도의 payments·anomaly 행은 위 블록과 함께 롤백됐다. 이상 계열은 운영 진단용으로 다시 기록한다(payment_id 없음).\n    if v_abort_code = any(v_anomaly_codes) then\n      insert into public.subscription_checkout_anomalies (payment_id, subscription_id, code, detail, expected, found)\n      values (null, null, v_abort_code, ''api_app_v1.subscribe_with_cash aborted (intent rolled back)'',\n              jsonb_build_object(''student_id'', v_uid, ''mentor_id'', p_mentor_id, ''plan_id'', v_plan_id, ''plan_tier'', v_tier,\n                                 ''amount_cents'', v_amount, ''idempotency_key'', v_key),\n              v_abort_detail)\n      returning id into v_anom;\n      return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', v_abort_code, ''anomaly_id'', v_anom);\n    end if;\n    if v_abort_code = ''CASH_INSUFFICIENT'' then\n      select w.balance_cents into v_balance from public.cash_wallets w where w.user_id = v_uid;\n      v_balance := coalesce(v_balance, 0);\n      return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''CASH_INSUFFICIENT'',\n                                ''required_cents'', v_amount, ''balance_cents'', v_balance,\n                                ''shortfall_cents'', greatest(0, v_amount - v_balance));\n    end if;\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', v_abort_code) || coalesce(v_abort_detail, ''{}''::jsonb);\n  end if;\n\n  return v_result;\nend\n$fn$", "comment on function api_app_v1.subscribe_with_cash(uuid, text, text) is\n  ''199(DB-4 A-1): 앱 캐시 구독 결제 — 게이트(학생·계정·멘토 승인/활동/열림·중복·요금제·cap·잔액) 후 payments intent → F12 subscription_checkout_confirm_v2(정본 confirm+방) → initial billing event. (학생,키) 멱등 재생 · 실패 시 intent 롤백. authenticated 만.''", "-- ── A-2. 해지 예약 · 취소 ──────────────────────────────────────────────────────\ncreate function api_app_v1.subscription_cancel_at_period_end(p_subscription_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_role text;\n  v_sub record;\n  v_already boolean := false;\nbegin\n  if v_uid is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  end if;\n  select u.role into v_role from public.users u where u.id = v_uid;\n  if not found or v_role is distinct from ''student'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROLE_NOT_STUDENT'');\n  end if;\n  if p_subscription_id is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_NOT_FOUND'');\n  end if;\n  select s.id, s.student_id, s.status, s.cancel_at_period_end, s.cancel_requested_at, s.current_period_end\n    into v_sub from public.subscriptions s where s.id = p_subscription_id for update;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_NOT_FOUND'');\n  end if;\n  if v_sub.student_id is distinct from v_uid then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''NOT_SUBSCRIPTION_OWNER'');\n  end if;\n  if lower(btrim(coalesce(v_sub.status, ''''))) not in (''active'', ''past_due'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_NOT_CURRENT'', ''status'', v_sub.status);\n  end if;\n  if coalesce(v_sub.cancel_at_period_end, false) then\n    v_already := true;\n  else\n    update public.subscriptions s\n       set cancel_at_period_end = true, cancel_requested_at = now(), updated_at = now()\n     where s.id = p_subscription_id and s.student_id = v_uid;\n    select s.cancel_requested_at into v_sub.cancel_requested_at from public.subscriptions s where s.id = p_subscription_id;\n  end if;\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''subscription_id'', p_subscription_id,\n                            ''cancel_at_period_end'', true, ''already_scheduled'', v_already,\n                            ''cancel_requested_at'', v_sub.cancel_requested_at, ''current_period_end'', v_sub.current_period_end);\nend\n$fn$", "comment on function api_app_v1.subscription_cancel_at_period_end(uuid) is\n  ''199(DB-4 A-2): 본인 구독(active/past_due) 해지 예약 — cancel_at_period_end=true · cancel_requested_at=now(). 기간 말까지 유지, 다음 결제 중단. 멱등. 웹 requestSubscriptionCancelAtPeriodEndAction 동일.''", "create function api_app_v1.subscription_cancel_undo(p_subscription_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_role text;\n  v_sub record;\n  v_was boolean := false;\nbegin\n  if v_uid is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  end if;\n  select u.role into v_role from public.users u where u.id = v_uid;\n  if not found or v_role is distinct from ''student'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROLE_NOT_STUDENT'');\n  end if;\n  if p_subscription_id is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_NOT_FOUND'');\n  end if;\n  select s.id, s.student_id, s.status, s.cancel_at_period_end, s.current_period_end, s.next_billing_at\n    into v_sub from public.subscriptions s where s.id = p_subscription_id for update;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_NOT_FOUND'');\n  end if;\n  if v_sub.student_id is distinct from v_uid then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''NOT_SUBSCRIPTION_OWNER'');\n  end if;\n  if lower(btrim(coalesce(v_sub.status, ''''))) not in (''active'', ''past_due'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_NOT_CURRENT'', ''status'', v_sub.status);\n  end if;\n  v_was := coalesce(v_sub.cancel_at_period_end, false);\n  update public.subscriptions s\n     set cancel_at_period_end = false, cancel_requested_at = null, updated_at = now()\n   where s.id = p_subscription_id and s.student_id = v_uid;\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''subscription_id'', p_subscription_id,\n                            ''cancel_at_period_end'', false, ''was_scheduled'', v_was,\n                            ''current_period_end'', v_sub.current_period_end, ''next_billing_at'', v_sub.next_billing_at);\nend\n$fn$", "comment on function api_app_v1.subscription_cancel_undo(uuid) is\n  ''199(DB-4 A-2): 본인 구독(active/past_due) 해지 예약 취소 — cancel_at_period_end=false · cancel_requested_at=null. 멱등. 웹 undoSubscriptionCancelAtPeriodEndAction 동일.''", "-- ── 권한 — authenticated 만(anon·PUBLIC·service_role 0 — M17 앱 계약) ────────────\nrevoke all on function api_app_v1.subscribe_with_cash(uuid, text, text) from public, anon", "revoke all on function api_app_v1.subscription_cancel_at_period_end(uuid) from public, anon", "revoke all on function api_app_v1.subscription_cancel_undo(uuid) from public, anon", "grant execute on function api_app_v1.subscribe_with_cash(uuid, text, text) to authenticated", "grant execute on function api_app_v1.subscription_cancel_at_period_end(uuid) to authenticated", "grant execute on function api_app_v1.subscription_cancel_undo(uuid) to authenticated", "-- ── 적용 직후 자가 검증 ───────────────────────────────────────────────────────\ndo $$\ndeclare v_n integer;\nbegin\n  select count(*) into v_n\n    from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''api_app_v1''\n     and p.prosecdef and coalesce(p.proconfig::text, '''') like ''%search_path=%''\n     and p.prorettype = ''jsonb''::regtype\n     and not has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n     and has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n     and not has_function_privilege(''service_role'', p.oid, ''EXECUTE'')\n     and (p.proacl is null or (p.proacl::text not like ''{=%'' and p.proacl::text not like ''%,=%''))\n     and (p.proname, pg_get_function_identity_arguments(p.oid)) in\n         ((''subscribe_with_cash'', ''p_mentor_id uuid, p_tier text, p_idempotency_key text''),\n          (''subscription_cancel_at_period_end'', ''p_subscription_id uuid''),\n          (''subscription_cancel_undo'', ''p_subscription_id uuid''));\n  if v_n <> 3 then\n    raise exception ''199_SELFCHECK: 함수 3종 identity/SECDEF/ACL 불일치(matched %)'', v_n;\n  end if;\n  -- 위임 확인 — 정본 재구현 금지(F12·정본 confirm 호출이 본문에 있어야 한다)\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''api_app_v1'' and p.proname = ''subscribe_with_cash''\n                    and p.prosrc like ''%api_web_v1.subscription_checkout_confirm_v2(%''\n                    and p.prosrc not like ''%record_subscription_cash_debit(%''\n                    and p.prosrc not like ''%insert into public.cash_ledger%'') then\n    raise exception ''199_SELFCHECK: subscribe_with_cash 가 F12 에 위임하지 않거나 자금 로직을 복제했다'';\n  end if;\n  -- 웹 표면 불변: F12 ACL(service_role 전용) 그대로\n  if has_function_privilege(''authenticated'', ''api_web_v1.subscription_checkout_confirm_v2(uuid, uuid, integer, text)'', ''EXECUTE'')\n     or not has_function_privilege(''service_role'', ''api_web_v1.subscription_checkout_confirm_v2(uuid, uuid, integer, text)'', ''EXECUTE'') then\n    raise exception ''199_SELFCHECK: F12 ACL 변경됨'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "api_app_v1_refund_request", "version": "20260905100200", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 200_api_app_v1_refund_request.sql  (2026-09-05 · DB-4 묶음 B — 앱 환불 예상액 · 환불 신청)\n--\n-- 왜: `refunds` INSERT 는 `refund_ins` 정책(021)이 관리자만 허용해 앱이 환불을 신청할 수 없다(A-4a 판정표 #9).\n--   웹은 `lib/subscribe/subscriptionCancelActions.ts` `requestSubscriptionProratedRefundAction`(service_role)이\n--   학원법 시행령 별표 4 계산(`lib/subscribe/subscriptionRefundProration.ts` computeProratedRefundEstimate · student_voluntary)과\n--   이용 개시 판정(`lib/subscribe/subscriptionUsageStarted.ts` — 기간 시작 이후 질문 스레드 1건 이상)을 TS 로 수행한다.\n--   같은 계산을 SQL 로 옮기고(경계값 픽스처로 웹 TS 와 일치 검증 — scripts/verify/fixtures/db4_batch_post_fixture.sql · db4_refund_parity_expected.mjs)\n--   앱이 부를 래퍼 2종을 `api_app_v1` 에 둔다. 웹 액션은 바꾸지 않는다(지시서 원칙 7).\n--\n-- B-0 core_private.subscription_refund_estimate_impl(p_subscription_id uuid, p_now timestamptz) returns jsonb  (외부 EXECUTE 0)\n--   · 입력: subscriptions.current_period_start/end(없으면 최신 succeeded initial/renewal billing event 의 period) · 금액 = 그 billing event 의 amount_cents\n--   · 이용 개시: mentor_id 없음 → true(보수) · 기간 시작 없음 → false · 방 없음 → false · 방의 question_threads.created_at >= 기간 시작 1건 이상 → true\n--   · 분기(별표 4 · TS 와 동일): 금액 0 / 기간 없음 / end<=start → invalid(0) · 이용 개시 전 → 전액 · 경과 < 1/3 → floor(×2/3) · 경과 < 1/2 → floor(×1/2) · 그 외 0\n--     경과율 비교는 ms 정수 교차곱(elapsed×3 < total · elapsed×2 < total)으로 JS 부동소수 결과와 정확히 같다. period_days = max(1, ceil(total/1일)) · remaining_days = ceil(remaining/1일).\n--   · rule: ''이용 개시 전'' | ''1/3 전'' | ''1/2 전'' | ''1/2 후'' | ''계산 불가'' · bracket_reason: before_usage | lt_1_3 | lt_1_2 | ge_1_2 | invalid (TS 이름)\n-- B-1 api_app_v1.refund_estimate(p_subscription_id uuid) returns jsonb — 본인 구독만(NOT_SUBSCRIPTION_OWNER) · impl(now())\n-- B-2 api_app_v1.refund_request_create(p_subscription_id uuid, p_reason text) returns jsonb\n--   · AUTH_REQUIRED → ROLE_NOT_STUDENT → ACCOUNT_BANNED / ACCOUNT_SUSPENDED / ACCOUNT_NOT_ACTIVE / ACCOUNT_DELETION_IN_PROGRESS →\n--     REASON_TOO_SHORT(5자 미만 · 웹 동일) / REASON_TOO_LONG(2000자 초과 — 서버 위생 상한) → SUBSCRIPTION_NOT_FOUND / NOT_SUBSCRIPTION_OWNER →\n--     SUBSCRIPTION_NOT_CURRENT(active/past_due 아님) → ALREADY_REQUESTED(pending 환불 존재 · refund_id) → REFUND_NOT_AVAILABLE(예상액 0 · rule 동봉)\n--   · INSERT refunds {user_id, amount_cents=예상액, status ''pending'', payment_id=billing event→구독, subscription_id, billing_event_id=billing event→last_billing_event_id,\n--     request_type ''subscription_prorated'', reason} — 웹 INSERT 와 동일 필드. 승인은 관리자(approve_refund_request_admin) 그대로.\n--   · 부수 효과(웹과 동일): pending 환불이 생기면 142 게이트가 그 구독의 새 질문·후속 메시지·첨부를 SUBSCRIPTION_REFUND_PENDING 으로 잠근다. 알림 0(158 은 mentor_suspended 만).\n--   · 반환 {ok, contract_version:1, refund_id, subscription_id, amount_cents, rule, bracket_reason, status:''pending''} — 지시서의 `returns uuid` 대신\n--     api_app_v1 envelope 규약(§8)을 따른다(앱 오류 처리 통일 — 보고서에 명시).\n-- 권한: 래퍼 2종 REVOKE public·anon · GRANT authenticated 만. impl 은 외부 EXECUTE 0(SECDEF 래퍼 소유자 문맥 전용).\n--\n-- 적용 전 실측(2026-09-05 운영 read-only): 환불 0 · 구독 0 → 데이터 영향 0.\n-- Apply: 저장소 표준 경로(db-apply-pending). 순서 A(199) → B(200). pack 등재: supabase/baseline/post_ledger_backfills/20260905100200_api_app_v1_refund_request.sql\n-- Rollback: supabase/rollback/20260905100200_api_app_v1_refund_request_rollback.sql\n-- =============================================================================\n\nbegin", "-- ── 0. 사전 게이트 ─────────────────────────────────────────────────────────────\ndo $$\nbegin\n  if (select count(*) from pg_namespace where nspname in (''api_app_v1'', ''core_private'')) <> 2 then\n    raise exception ''200_GATE: api_app_v1/core_private 스키마 부재'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''refunds''\n       and column_name in (''user_id'',''amount_cents'',''status'',''payment_id'',''subscription_id'',''billing_event_id'',''request_type'',''reason'')) <> 8 then\n    raise exception ''200_GATE: refunds 컬럼 불일치(004·069·150)'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''subscriptions''\n       and column_name in (''id'',''student_id'',''mentor_id'',''status'',''current_period_start'',''current_period_end'',''payment_id'',''last_billing_event_id'')) <> 8 then\n    raise exception ''200_GATE: subscriptions 컬럼 불일치'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''subscription_billing_events''\n       and column_name in (''id'',''subscription_id'',''amount_cents'',''payment_id'',''period_start'',''period_end'',''billing_at'',''event_type'',''status'')) <> 9 then\n    raise exception ''200_GATE: subscription_billing_events 컬럼 불일치(064)'';\n  end if;\n  if not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''question_threads'' and column_name = ''mentor_student_room_id'') then\n    raise exception ''200_GATE: question_threads.mentor_student_room_id 부재'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''public'' and p.proname = ''account_deletion_write_blocked'') then\n    raise exception ''200_GATE: account_deletion_write_blocked 부재(151)'';\n  end if;\n  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n              where (n.nspname = ''api_app_v1'' and p.proname in (''refund_estimate'', ''refund_request_create''))\n                 or (n.nspname = ''core_private'' and p.proname = ''subscription_refund_estimate_impl'')) then\n    raise exception ''200_GATE: 대상 함수가 이미 있다'';\n  end if;\nend $$", "-- ── B-0. 별표 4 계산 정본(SQL) — 웹 computeProratedRefundEstimate(student_voluntary) + hasSubscriptionUsageStartedForPair 이식 ──\ncreate function core_private.subscription_refund_estimate_impl(p_subscription_id uuid, p_now timestamptz)\nreturns jsonb\nlanguage plpgsql\nsecurity invoker\nset search_path to ''''\nas $fn$\ndeclare\n  v_sub record;\n  v_ev record;\n  v_room uuid;\n  v_now timestamptz;\n  v_start timestamptz;\n  v_end timestamptz;\n  v_amount bigint;\n  v_usage boolean;\n  v_total_ms numeric;\n  v_elapsed_ms numeric;\n  v_remaining_ms numeric;\n  v_refund bigint;\n  v_bracket text;\n  v_rule text;\nbegin\n  if p_subscription_id is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_NOT_FOUND'');\n  end if;\n  select s.id, s.student_id, s.mentor_id, s.status, s.current_period_start, s.current_period_end, s.payment_id, s.last_billing_event_id\n    into v_sub from public.subscriptions s where s.id = p_subscription_id;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_NOT_FOUND'');\n  end if;\n\n  -- 최신 succeeded initial/renewal (웹 latestSucceededBillingEvent: billing_at desc limit 1)\n  select e.id, e.amount_cents, e.payment_id, e.period_start, e.period_end\n    into v_ev\n    from public.subscription_billing_events e\n   where e.subscription_id = v_sub.id and e.status = ''succeeded'' and e.event_type in (''initial'', ''renewal'')\n   order by e.billing_at desc\n   limit 1;\n\n  v_start := coalesce(v_sub.current_period_start, v_ev.period_start);\n  v_end := coalesce(v_sub.current_period_end, v_ev.period_end);\n  v_amount := greatest(0, coalesce(v_ev.amount_cents, 0));\n\n  -- 이용 개시(첫 질문 작성) — 웹 hasSubscriptionUsageStartedForPair 동일 순서\n  if v_sub.mentor_id is null then\n    v_usage := true;   -- 멘토 미상(이상 데이터)은 보수적으로 개시로 본다(웹 동일)\n  elsif v_start is null then\n    v_usage := false;\n  else\n    select r.id into v_room from public.mentor_student_rooms r\n     where r.student_id = v_sub.student_id and r.mentor_id = v_sub.mentor_id limit 1;\n    if v_room is null then\n      v_usage := false;\n    else\n      v_usage := exists (select 1 from public.question_threads t\n                          where t.mentor_student_room_id = v_room and t.created_at >= v_start);\n    end if;\n  end if;\n\n  -- JS Date 는 ms 정밀도 — 동일하게 ms 로 절단한다\n  v_now := date_trunc(''milliseconds'', coalesce(p_now, now()));\n  v_start := date_trunc(''milliseconds'', v_start);\n  v_end := date_trunc(''milliseconds'', v_end);\n\n  if v_amount = 0 or v_start is null or v_end is null or v_end <= v_start then\n    return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''subscription_id'', v_sub.id,\n      ''refundable_cents'', 0, ''amount_cents'', v_amount, ''rule'', ''계산 불가'', ''bracket_reason'', ''invalid'',\n      ''usage_started'', v_usage, ''elapsed_days'', 0, ''period_days'', 0, ''remaining_days'', 0,\n      ''remaining_ratio'', 0, ''elapsed_ratio'', 0, ''period_start'', v_start, ''period_end'', v_end,\n      ''billing_event_id'', v_ev.id, ''billing_payment_id'', v_ev.payment_id, ''as_of'', v_now);\n  end if;\n\n  v_total_ms := (extract(epoch from v_end) - extract(epoch from v_start)) * 1000;\n  v_elapsed_ms := greatest(0, (extract(epoch from v_now) - extract(epoch from v_start)) * 1000);\n  v_remaining_ms := greatest(0, (extract(epoch from v_end) - extract(epoch from v_now)) * 1000);\n\n  if v_usage = false then\n    v_refund := v_amount; v_bracket := ''before_usage''; v_rule := ''이용 개시 전'';\n  elsif v_elapsed_ms * 3 < v_total_ms then\n    v_refund := (v_amount * 2) / 3; v_bracket := ''lt_1_3''; v_rule := ''1/3 전'';\n  elsif v_elapsed_ms * 2 < v_total_ms then\n    v_refund := v_amount / 2; v_bracket := ''lt_1_2''; v_rule := ''1/2 전'';\n  else\n    v_refund := 0; v_bracket := ''ge_1_2''; v_rule := ''1/2 후'';\n  end if;\n\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''subscription_id'', v_sub.id,\n    ''refundable_cents'', v_refund, ''amount_cents'', v_amount, ''rule'', v_rule, ''bracket_reason'', v_bracket,\n    ''usage_started'', v_usage,\n    ''elapsed_days'', floor(v_elapsed_ms / 86400000)::int,\n    ''period_days'', greatest(1, ceil(v_total_ms / 86400000)::int),\n    ''remaining_days'', ceil(v_remaining_ms / 86400000)::int,\n    ''remaining_ratio'', round(least(1, v_remaining_ms / v_total_ms), 6),\n    ''elapsed_ratio'', round(least(1, v_elapsed_ms / v_total_ms), 6),\n    ''period_start'', v_start, ''period_end'', v_end,\n    ''billing_event_id'', v_ev.id, ''billing_payment_id'', v_ev.payment_id, ''as_of'', v_now);\nend\n$fn$", "comment on function core_private.subscription_refund_estimate_impl(uuid, timestamptz) is\n  ''200(DB-4 B-0): 학원법 별표 4 구독 환불 예상액 — 웹 computeProratedRefundEstimate(student_voluntary)·hasSubscriptionUsageStartedForPair 의 SQL 이식(경계 교차곱 비교). 외부 EXECUTE 0.''", "revoke all on function core_private.subscription_refund_estimate_impl(uuid, timestamptz) from public, anon, authenticated, service_role", "-- ── B-1. refund_estimate ──────────────────────────────────────────────────────\ncreate function api_app_v1.refund_estimate(p_subscription_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_owner uuid;\nbegin\n  if v_uid is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  end if;\n  if p_subscription_id is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_NOT_FOUND'');\n  end if;\n  select s.student_id into v_owner from public.subscriptions s where s.id = p_subscription_id;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_NOT_FOUND'');\n  end if;\n  if v_owner is distinct from v_uid then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''NOT_SUBSCRIPTION_OWNER'');\n  end if;\n  return core_private.subscription_refund_estimate_impl(p_subscription_id, now());\nend\n$fn$", "comment on function api_app_v1.refund_estimate(uuid) is\n  ''200(DB-4 B-1): 본인 구독 환불 예상액(별표 4) — {refundable_cents, rule, bracket_reason, elapsed_days, period_days, remaining_days, usage_started …}. 캐시 충전 유도 없음.''", "-- ── B-2. refund_request_create ────────────────────────────────────────────────\ncreate function api_app_v1.refund_request_create(p_subscription_id uuid, p_reason text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_role text; v_status text; v_susp timestamptz; v_norm text;\n  v_reason text := btrim(coalesce(p_reason, ''''));\n  v_sub record;\n  v_pending uuid;\n  v_est jsonb;\n  v_amount bigint;\n  v_refund_id uuid;\nbegin\n  if v_uid is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  end if;\n  select u.role, u.status, u.suspended_until into v_role, v_status, v_susp from public.users u where u.id = v_uid;\n  if not found or v_role is distinct from ''student'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROLE_NOT_STUDENT'');\n  end if;\n  v_norm := lower(btrim(coalesce(v_status, '''')));\n  if v_norm = ''banned'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_BANNED'');\n  end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_SUSPENDED'');\n  end if;\n  if v_norm not in (''active'', ''suspended'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_NOT_ACTIVE'');\n  end if;\n  if public.account_deletion_write_blocked(v_uid) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  end if;\n  if char_length(v_reason) < 5 then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''REASON_TOO_SHORT'', ''min_length'', 5);\n  end if;\n  if char_length(v_reason) > 2000 then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''REASON_TOO_LONG'', ''max_length'', 2000);\n  end if;\n  if p_subscription_id is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_NOT_FOUND'');\n  end if;\n\n  -- 본인 구독 잠금(동시 중복 신청 직렬화) · 현재 구독만\n  select s.id, s.student_id, s.status, s.payment_id, s.last_billing_event_id\n    into v_sub from public.subscriptions s where s.id = p_subscription_id for update;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_NOT_FOUND'');\n  end if;\n  if v_sub.student_id is distinct from v_uid then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''NOT_SUBSCRIPTION_OWNER'');\n  end if;\n  if lower(btrim(coalesce(v_sub.status, ''''))) not in (''active'', ''past_due'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_NOT_CURRENT'', ''status'', v_sub.status);\n  end if;\n  select r.id into v_pending from public.refunds r\n   where r.user_id = v_uid and r.subscription_id = p_subscription_id and r.status = ''pending''\n   order by r.created_at desc limit 1;\n  if v_pending is not null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ALREADY_REQUESTED'', ''refund_id'', v_pending);\n  end if;\n\n  v_est := core_private.subscription_refund_estimate_impl(p_subscription_id, now());\n  if not coalesce((v_est ->> ''ok'')::boolean, false) then\n    return v_est;\n  end if;\n  v_amount := coalesce((v_est ->> ''refundable_cents'')::bigint, 0);\n  if v_amount <= 0 then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''REFUND_NOT_AVAILABLE'',\n                              ''rule'', v_est ->> ''rule'', ''bracket_reason'', v_est ->> ''bracket_reason'');\n  end if;\n\n  insert into public.refunds (user_id, amount_cents, status, payment_id, subscription_id, billing_event_id, request_type, reason)\n  values (v_uid, v_amount, ''pending'',\n          coalesce((v_est ->> ''billing_payment_id'')::uuid, v_sub.payment_id),\n          p_subscription_id,\n          coalesce((v_est ->> ''billing_event_id'')::uuid, v_sub.last_billing_event_id),\n          ''subscription_prorated'', v_reason)\n  returning id into v_refund_id;\n\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''refund_id'', v_refund_id,\n                            ''subscription_id'', p_subscription_id, ''amount_cents'', v_amount,\n                            ''rule'', v_est ->> ''rule'', ''bracket_reason'', v_est ->> ''bracket_reason'', ''status'', ''pending'');\nend\n$fn$", "comment on function api_app_v1.refund_request_create(uuid, text) is\n  ''200(DB-4 B-2): 본인 구독(active/past_due) 환불 신청 — 사유 5자 이상 · pending 중복 ALREADY_REQUESTED · 예상액 0 REFUND_NOT_AVAILABLE · refunds pending INSERT(subscription_prorated). 승인은 관리자. 웹 requestSubscriptionProratedRefundAction 동일.''", "-- ── 권한 ───────────────────────────────────────────────────────────────────────\nrevoke all on function api_app_v1.refund_estimate(uuid) from public, anon", "revoke all on function api_app_v1.refund_request_create(uuid, text) from public, anon", "grant execute on function api_app_v1.refund_estimate(uuid) to authenticated", "grant execute on function api_app_v1.refund_request_create(uuid, text) to authenticated", "-- ── 적용 직후 자가 검증 ───────────────────────────────────────────────────────\ndo $$\ndeclare v_n integer; v_oid oid;\nbegin\n  select count(*) into v_n\n    from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''api_app_v1''\n     and p.prosecdef and coalesce(p.proconfig::text, '''') like ''%search_path=%''\n     and not has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n     and has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n     and not has_function_privilege(''service_role'', p.oid, ''EXECUTE'')\n     and (p.proacl is null or (p.proacl::text not like ''{=%'' and p.proacl::text not like ''%,=%''))\n     and (p.proname, pg_get_function_identity_arguments(p.oid)) in\n         ((''refund_estimate'', ''p_subscription_id uuid''),\n          (''refund_request_create'', ''p_subscription_id uuid, p_reason text''));\n  if v_n <> 2 then\n    raise exception ''200_SELFCHECK: 래퍼 2종 identity/SECDEF/ACL 불일치(matched %)'', v_n;\n  end if;\n  select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''core_private'' and p.proname = ''subscription_refund_estimate_impl''\n     and pg_get_function_identity_arguments(p.oid) = ''p_subscription_id uuid, p_now timestamp with time zone''\n     and not p.prosecdef and coalesce(p.proconfig::text, '''') like ''%search_path=%'';\n  if v_oid is null then\n    raise exception ''200_SELFCHECK: impl identity/attributes 불일치'';\n  end if;\n  if has_function_privilege(''anon'', v_oid, ''EXECUTE'') or has_function_privilege(''authenticated'', v_oid, ''EXECUTE'')\n     or has_function_privilege(''service_role'', v_oid, ''EXECUTE'') then\n    raise exception ''200_SELFCHECK: impl 외부 EXECUTE 는 0 이어야 한다'';\n  end if;\n  -- refund_ins 정책(관리자만) 불변 — 앱 직접 INSERT 는 여전히 거부된다\n  if not exists (select 1 from pg_policies where schemaname = ''public'' and tablename = ''refunds'' and policyname = ''refund_ins''\n                   and with_check like ''%is_admin()%'' and with_check not like ''%auth.uid()%'') then\n    raise exception ''200_SELFCHECK: refund_ins 정책이 바뀌었다'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "api_app_v1_mentor_activity_set", "version": "20260905100300", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 201_api_app_v1_mentor_activity_set.sql  (2026-09-05 · DB-4 묶음 C — 멘토 활동 상태)\n--\n-- 왜: 멘토 활동 일시 중단/복귀/종료 예약은 웹이 service_role 로 4개 표(mentor_profiles · mentor_plans · subscriptions · mentor_activity_events)를\n--   갱신한다(`lib/mentor/mentorActivityService.ts`). 앱은 어느 표도 쓸 수 없다(A-4a 판정표 #6). 규칙을 SQL 로 옮긴 래퍼 하나를 둔다.\n--   DB 에는 활동 상태 코어 함수가 없어 이식이 불가피하다(웹 TS 가 정본 — 상수: 일시 중단 최대 7일 · 일반 휴식 6개월 1회(KST 달력) · 종료 공지 14일).\n--\n-- C-1 api_app_v1.mentor_activity_set(p_status text, p_pause_until timestamptz default null, p_termination_effective_at timestamptz default null,\n--                                    p_reason text default ''rest'') returns jsonb\n--   · 공통 게이트: AUTH_REQUIRED → ROLE_NOT_MENTOR → ACCOUNT_BANNED / ACCOUNT_SUSPENDED / ACCOUNT_NOT_ACTIVE / ACCOUNT_DELETION_IN_PROGRESS →\n--     ACTIVITY_STATUS_INVALID(active·paused·terminating 밖 — terminated 는 관리자/배치 전용) → MENTOR_PROFILE_NOT_FOUND\n--   · 현재 상태 판정 = 웹 mentorActivityState: terminated / terminating / paused(pause_until 경과면 active) / active\n--   · paused (웹 startMentorPause): 현재 active 만(ACTIVITY_STATE_INVALID · current_state) · p_pause_until 필수(PAUSE_UNTIL_REQUIRED) · 미래(PAUSE_UNTIL_INVALID) ·\n--     일수 = ceil((pause_until − now)/1일) ≤ 7(PAUSE_TOO_LONG · max_days) · p_reason ∈ {rest, illness}(PAUSE_REASON_INVALID) ·\n--     rest 는 last_pause_at 이 KST 달력 6개월 이전이어야 함(REST_FREQUENCY_LIMIT — 질병은 예외·관리자 확인 pending_review) ·\n--     활성/past_due 구독의 current_period_end·next_billing_at 를 일수만큼 연장(과금 보호 · 웹 동일) · mentor_activity_events pause_started ·\n--     학생 알림은 158 트리거(activity_status → paused)가 원자 fan-out\n--     **paused 는 새 구독만 막는다(199 MENTOR_PAUSED)** — 질문방 RPC(qna_*)는 activity_status 를 보지 않으므로 기존 학생 질문은 계속 받는다(웹 동일 · 검증 픽스처).\n--   · active (웹 resumeMentorActivity): 현재 raw activity_status = ''paused'' 만 · pause_until NULL · mentor_plans.is_active 전부 true(웹 동일 — 202 토글과의 상호작용은 보고서) ·\n--     이벤트 pause_resumed\n--   · terminating (웹 startMentorTermination): terminating/terminated 가 아니면 · 효력일 = max(p_termination_effective_at, now+14일)(웹은 정확히 +14일 —\n--     더 늦은 날짜만 허용 · now+90일 초과 TERMINATION_DATE_TOO_FAR) · mentor_plans.is_active 전부 false(신규 구독 즉시 차단) · 이벤트 termination_requested ·\n--     학생 알림은 158 트리거. **효력일 이후 처리기**: 웹 `finalizeMentorTermination`(관리자 콘솔 액션 `lib/admin/mentorActivityAdminActions.ts` — 수동, cron 없음)이\n--     잔여 100% 환불·구독 정리·terminated 전이를 한다. 이 래퍼는 상태만 바꾼다(지시서 §C — 확정·환불 생성 없음).\n--   · 반환 {ok, contract_version:1, activity_status, …상태별 필드}\n-- 권한: REVOKE public·anon · GRANT authenticated 만. 웹 액션은 그대로(service_role 경로).\n-- 트리거 대조: trg_mp_notify_activity(158 · terminating/paused 전이 알림 ✓ 의도) · trg_mentor_profile_privileged_guard(verification_status·cap_limit 변경만 · 미발화) ·\n--   trg_school_verification_reassess_on_academic_change(대학·학과 변경만 · 미발화) · trg_mplan_notify_price_*(amount_cents 변경만 · is_active 토글 미발화) ·\n--   subscriptions: enforce_mentor_cap(status·plan_tier 만) · keep_subscription_refunded_status(status 만) — 기간 연장 UPDATE 에 미발화.\n--\n-- Apply: 저장소 표준 경로(db-apply-pending). pack 등재: supabase/baseline/post_ledger_backfills/20260905100300_api_app_v1_mentor_activity_set.sql\n-- Rollback: supabase/rollback/20260905100300_api_app_v1_mentor_activity_set_rollback.sql\n-- =============================================================================\n\nbegin", "-- ── 0. 사전 게이트 ─────────────────────────────────────────────────────────────\ndo $$\nbegin\n  if not exists (select 1 from pg_namespace where nspname = ''api_app_v1'') then\n    raise exception ''201_GATE: api_app_v1 스키마 부재'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''mentor_profiles''\n       and column_name in (''user_id'',''activity_status'',''termination_requested_at'',''termination_effective_at'',''pause_started_at'',''pause_until'',''pause_reason'',''last_pause_at'')) <> 8 then\n    raise exception ''201_GATE: mentor_profiles 활동 컬럼 8종 불일치(103)'';\n  end if;\n  if not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''mentor_plans'' and column_name = ''is_active'') then\n    raise exception ''201_GATE: mentor_plans.is_active 부재(103)'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''mentor_activity_events''\n       and column_name in (''mentor_id'',''event_type'',''reason'',''detail'',''status'')) <> 5 then\n    raise exception ''201_GATE: mentor_activity_events 컬럼 불일치(103)'';\n  end if;\n  if not exists (select 1 from pg_trigger where tgname = ''trg_mp_notify_activity'' and tgrelid = ''public.mentor_profiles''::regclass) then\n    raise exception ''201_GATE: trg_mp_notify_activity 부재(158) — 학생 알림 fan-out 전제'';\n  end if;\n  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''api_app_v1'' and p.proname = ''mentor_activity_set'') then\n    raise exception ''201_GATE: 대상 함수가 이미 있다'';\n  end if;\nend $$", "-- ── C-1. mentor_activity_set ──────────────────────────────────────────────────\ncreate function api_app_v1.mentor_activity_set(\n  p_status text,\n  p_pause_until timestamptz default null,\n  p_termination_effective_at timestamptz default null,\n  p_reason text default ''rest''\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_role text; v_status text; v_susp timestamptz; v_norm text;\n  v_target text := lower(btrim(coalesce(p_status, '''')));\n  v_reason text := lower(btrim(coalesce(p_reason, ''rest'')));\n  v_mp record;\n  v_state text;\n  v_days integer;\n  v_threshold timestamptz;\n  v_s record;\n  v_new_end timestamptz; v_new_next timestamptz;\n  v_extended integer := 0;\n  v_plans integer := 0;\n  v_notified integer := 0;\n  v_eff timestamptz;\n  v_event_status text;\n  v_event_id uuid;\nbegin\n  if v_uid is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  end if;\n  select u.role, u.status, u.suspended_until into v_role, v_status, v_susp from public.users u where u.id = v_uid;\n  if not found or v_role is distinct from ''mentor'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROLE_NOT_MENTOR'');\n  end if;\n  v_norm := lower(btrim(coalesce(v_status, '''')));\n  if v_norm = ''banned'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_BANNED'');\n  end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_SUSPENDED'');\n  end if;\n  if v_norm not in (''active'', ''suspended'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_NOT_ACTIVE'');\n  end if;\n  if public.account_deletion_write_blocked(v_uid) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  end if;\n  if v_target not in (''active'', ''paused'', ''terminating'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACTIVITY_STATUS_INVALID'');\n  end if;\n\n  select mp.user_id, mp.activity_status, mp.pause_until, mp.last_pause_at, mp.termination_effective_at\n    into v_mp from public.mentor_profiles mp where mp.user_id = v_uid for update;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_PROFILE_NOT_FOUND'');\n  end if;\n\n  -- 웹 mentorActivityState\n  v_state := lower(btrim(coalesce(v_mp.activity_status, ''active'')));\n  if v_state = ''paused'' and v_mp.pause_until is not null and v_mp.pause_until <= now() then\n    v_state := ''active'';\n  elsif v_state not in (''terminated'', ''terminating'', ''paused'') then\n    v_state := ''active'';\n  end if;\n\n  if v_target = ''paused'' then\n    if v_state <> ''active'' then\n      return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACTIVITY_STATE_INVALID'', ''current_state'', v_state);\n    end if;\n    if p_pause_until is null then\n      return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAUSE_UNTIL_REQUIRED'');\n    end if;\n    if p_pause_until <= now() then\n      return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAUSE_UNTIL_INVALID'');\n    end if;\n    v_days := greatest(1, ceil(extract(epoch from (p_pause_until - now())) / 86400.0)::int);\n    if v_days > 7 then\n      return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAUSE_TOO_LONG'', ''max_days'', 7);\n    end if;\n    if v_reason not in (''rest'', ''illness'') then\n      return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAUSE_REASON_INVALID'');\n    end if;\n    if v_reason = ''rest'' and v_mp.last_pause_at is not null then\n      -- 웹 canRequestNormalRest: last <= addMonthsClampedKst(now, -6) 이어야 허용(KST 달력 · 말일 clamp = PG 월 산술과 동일)\n      v_threshold := (((now() at time zone ''Asia/Seoul'') - interval ''6 months'') at time zone ''Asia/Seoul'');\n      if v_mp.last_pause_at > v_threshold then\n        return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''REST_FREQUENCY_LIMIT'',\n                                  ''last_pause_at'', v_mp.last_pause_at,\n                                  ''next_available_at'', (((v_mp.last_pause_at at time zone ''Asia/Seoul'') + interval ''6 months'') at time zone ''Asia/Seoul''));\n      end if;\n    end if;\n\n    update public.mentor_profiles mp\n       set activity_status = ''paused'', pause_started_at = now(), pause_until = p_pause_until, pause_reason = v_reason,\n           last_pause_at = case when v_reason = ''rest'' then now() else mp.last_pause_at end\n     where mp.user_id = v_uid;\n\n    -- 쉰 일수만큼 구독 기간 연장(과금 보호) — 웹 startMentorPause 동일\n    for v_s in select s.id, s.current_period_end, s.next_billing_at from public.subscriptions s\n                where s.mentor_id = v_uid and s.status in (''active'', ''past_due'') loop\n      v_new_end := coalesce(v_s.current_period_end, now()) + (v_days * interval ''1 day'');\n      v_new_next := case when v_s.next_billing_at is not null then v_s.next_billing_at + (v_days * interval ''1 day'') else v_new_end end;\n      update public.subscriptions s set current_period_end = v_new_end, next_billing_at = v_new_next, updated_at = now() where s.id = v_s.id;\n      v_extended := v_extended + 1;\n    end loop;\n\n    v_event_status := case when v_reason = ''illness'' then ''pending_review'' else ''logged'' end;\n    insert into public.mentor_activity_events (mentor_id, event_type, reason, detail, status)\n    values (v_uid, ''pause_started'', v_reason,\n            jsonb_build_object(''pause_until'', p_pause_until, ''days'', v_days, ''subscriptions_extended'', v_extended, ''source'', ''api_app_v1''),\n            v_event_status)\n    returning id into v_event_id;\n\n    return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''activity_status'', ''paused'',\n                              ''pause_until'', p_pause_until, ''pause_days'', v_days, ''pause_reason'', v_reason,\n                              ''subscriptions_extended'', v_extended, ''event_status'', v_event_status, ''event_id'', v_event_id);\n  end if;\n\n  if v_target = ''active'' then\n    if lower(btrim(coalesce(v_mp.activity_status, ''''))) <> ''paused'' then\n      return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACTIVITY_STATE_INVALID'', ''current_state'', v_state);\n    end if;\n    update public.mentor_profiles mp set activity_status = ''active'', pause_until = null where mp.user_id = v_uid;\n    update public.mentor_plans mp set is_active = true where mp.mentor_id = v_uid and mp.is_active is distinct from true;\n    get diagnostics v_plans = row_count;\n    insert into public.mentor_activity_events (mentor_id, event_type, reason, detail, status)\n    values (v_uid, ''pause_resumed'', null, jsonb_build_object(''source'', ''api_app_v1''), ''logged'')\n    returning id into v_event_id;\n    return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''activity_status'', ''active'',\n                              ''plans_reactivated'', v_plans, ''event_id'', v_event_id);\n  end if;\n\n  -- terminating\n  if v_state in (''terminating'', ''terminated'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACTIVITY_STATE_INVALID'', ''current_state'', v_state);\n  end if;\n  v_eff := greatest(coalesce(p_termination_effective_at, now() + interval ''14 days''), now() + interval ''14 days'');\n  if v_eff > now() + interval ''90 days'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''TERMINATION_DATE_TOO_FAR'', ''max_days'', 90);\n  end if;\n  update public.mentor_profiles mp\n     set activity_status = ''terminating'', termination_requested_at = now(), termination_effective_at = v_eff\n   where mp.user_id = v_uid;\n  update public.mentor_plans mp set is_active = false where mp.mentor_id = v_uid and mp.is_active is distinct from false;\n  get diagnostics v_plans = row_count;\n  select count(*) into v_notified from public.subscriptions s where s.mentor_id = v_uid and s.status in (''active'', ''past_due'');\n  insert into public.mentor_activity_events (mentor_id, event_type, reason, detail, status)\n  values (v_uid, ''termination_requested'', null,\n          jsonb_build_object(''effective_at'', v_eff, ''notified_subscribers'', v_notified, ''source'', ''api_app_v1''), ''logged'')\n  returning id into v_event_id;\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''activity_status'', ''terminating'',\n                            ''termination_effective_at'', v_eff, ''notified_subscribers'', v_notified,\n                            ''plans_deactivated'', v_plans, ''event_id'', v_event_id);\nend\n$fn$", "comment on function api_app_v1.mentor_activity_set(text, timestamptz, timestamptz, text) is\n  ''201(DB-4 C-1): 본인 멘토 활동 상태 — paused(≤7일 · rest 6개월 1회 · 구독 기간 연장 · 새 구독만 차단) / active(복귀 · 플랜 재활성) / terminating(효력일 ≥ +14일 · 플랜 비활성 · 확정·환불은 관리자 finalize). 웹 mentorActivityService 규칙 이식 · 알림은 158 트리거.''", "revoke all on function api_app_v1.mentor_activity_set(text, timestamptz, timestamptz, text) from public, anon", "grant execute on function api_app_v1.mentor_activity_set(text, timestamptz, timestamptz, text) to authenticated", "-- ── 적용 직후 자가 검증 ───────────────────────────────────────────────────────\ndo $$\ndeclare v_oid oid;\nbegin\n  select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''api_app_v1'' and p.proname = ''mentor_activity_set''\n     and pg_get_function_identity_arguments(p.oid) = ''p_status text, p_pause_until timestamp with time zone, p_termination_effective_at timestamp with time zone, p_reason text''\n     and p.prosecdef and coalesce(p.proconfig::text, '''') like ''%search_path=%'';\n  if v_oid is null then\n    raise exception ''201_SELFCHECK: mentor_activity_set identity/attributes 불일치'';\n  end if;\n  if has_function_privilege(''anon'', v_oid, ''EXECUTE'') or not has_function_privilege(''authenticated'', v_oid, ''EXECUTE'')\n     or has_function_privilege(''service_role'', v_oid, ''EXECUTE'') then\n    raise exception ''201_SELFCHECK: ACL 불일치(authenticated 만)'';\n  end if;\n  if (select prosrc from pg_proc where oid = v_oid) not like ''%interval ''''6 months''''%''\n     or (select prosrc from pg_proc where oid = v_oid) not like ''%interval ''''14 days''''%'' then\n    raise exception ''201_SELFCHECK: 웹 상수(6개월·14일) 이식 불일치'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "api_app_v1_mentor_plan_active_set", "version": "20260905100400", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 202_api_app_v1_mentor_plan_active_set.sql  (2026-09-05 · DB-4 묶음 D — 요금제 활성 여부)\n--\n-- 왜: `api_web_v1.mentor_plan_prices_set_self`(F8)는 가격 3종만 받고 항상 is_active=true 로 upsert 한다. 활성 토글은 웹에서도\n--   활동 중단/종료의 부수 효과(service_role)뿐이라 멘토가 tier 하나만 닫을 길이 없다(A-4a 판정표 #2 · DB-4 지시서 §D).\n--   웹 규칙: 활성 구독이 있는 요금제를 끄는 규칙은 없다(`mentor_plans.is_active` 는 정본 confirm 의 신규 결제 게이트 PLAN_INACTIVE 에만 쓰이고,\n--   갱신 `process_subscription_renewal` 은 is_active 를 보지 않는다) → 지시서 정의대로 **기존 구독은 유지하고 신규만 막는다**.\n--\n-- D-1 api_app_v1.mentor_plan_active_set(p_tier text, p_is_active boolean) returns jsonb\n--   · AUTH_REQUIRED → ROLE_NOT_MENTOR → ACCOUNT_BANNED / ACCOUNT_SUSPENDED / ACCOUNT_NOT_ACTIVE / ACCOUNT_DELETION_IN_PROGRESS →\n--     PLAN_TIER_INVALID → PLAN_ACTIVE_VALUE_REQUIRED → MENTOR_PROFILE_NOT_FOUND → MENTOR_TERMINATED(terminating/terminated 는 종료 절차가 플랜을 소유) →\n--     PLAN_NOT_FOUND(행은 승인 시 166 트리거·F8 이 만든다 — 시드하지 않음) → LAST_ACTIVE_PLAN(마지막 활성 tier 는 끌 수 없음)\n--   · 멱등(값 동일이면 changed:false) · 반환 {ok, contract_version:1, plan_tier, is_active, changed, active_tiers[]}\n--   · 트리거 대조: trg_mplan_notify_price_update 는 amount_cents 변경만(158 주석 \"is_active 토글 무발화\") · trg_mp_set_updated 로 updated_at 만.\n--   · 201 과의 상호작용: terminating 이 전 tier 를 끄고, active 복귀가 전 tier 를 켠다(웹 동일). 이 토글은 그 사이(active/paused)에서만 동작한다.\n-- 권한: REVOKE public·anon · GRANT authenticated 만. F8 은 그대로(가격 upsert 가 is_active 를 건드리지 않는 ON CONFLICT 동작 불변).\n--\n-- Apply: 저장소 표준 경로(db-apply-pending). pack 등재: supabase/baseline/post_ledger_backfills/20260905100400_api_app_v1_mentor_plan_active_set.sql\n-- Rollback: supabase/rollback/20260905100400_api_app_v1_mentor_plan_active_set_rollback.sql\n-- =============================================================================\n\nbegin", "do $$\nbegin\n  if not exists (select 1 from pg_namespace where nspname = ''api_app_v1'') then\n    raise exception ''202_GATE: api_app_v1 스키마 부재'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''mentor_plans''\n       and column_name in (''id'',''mentor_id'',''plan_tier'',''is_active'',''amount_cents'')) <> 5 then\n    raise exception ''202_GATE: mentor_plans 컬럼 불일치(103)'';\n  end if;\n  if not exists (select 1 from pg_indexes where schemaname = ''public'' and tablename = ''mentor_plans'' and indexname = ''uq_mentor_plans_mentor_tier'') then\n    raise exception ''202_GATE: uq_mentor_plans_mentor_tier 부재(067)'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''public'' and p.proname = ''confirm_subscription_checkout'' and p.prosrc like ''%PLAN_INACTIVE%'') then\n    raise exception ''202_GATE: 정본 confirm 의 PLAN_INACTIVE 게이트 부재 — 신규 차단 전제'';\n  end if;\n  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''api_app_v1'' and p.proname = ''mentor_plan_active_set'') then\n    raise exception ''202_GATE: 대상 함수가 이미 있다'';\n  end if;\nend $$", "create function api_app_v1.mentor_plan_active_set(p_tier text, p_is_active boolean)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_role text; v_status text; v_susp timestamptz; v_norm text;\n  v_tier text := lower(btrim(coalesce(p_tier, '''')));\n  v_act text;\n  v_plan record;\n  v_others integer;\n  v_changed boolean := false;\n  v_active_tiers text[];\nbegin\n  if v_uid is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  end if;\n  select u.role, u.status, u.suspended_until into v_role, v_status, v_susp from public.users u where u.id = v_uid;\n  if not found or v_role is distinct from ''mentor'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROLE_NOT_MENTOR'');\n  end if;\n  v_norm := lower(btrim(coalesce(v_status, '''')));\n  if v_norm = ''banned'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_BANNED'');\n  end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_SUSPENDED'');\n  end if;\n  if v_norm not in (''active'', ''suspended'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_NOT_ACTIVE'');\n  end if;\n  if public.account_deletion_write_blocked(v_uid) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  end if;\n  if v_tier not in (''limited'', ''standard'', ''premium'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_TIER_INVALID'');\n  end if;\n  if p_is_active is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_ACTIVE_VALUE_REQUIRED'');\n  end if;\n\n  select mp.activity_status into v_act from public.mentor_profiles mp where mp.user_id = v_uid for update;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_PROFILE_NOT_FOUND'');\n  end if;\n  if lower(btrim(coalesce(v_act, ''active''))) in (''terminating'', ''terminated'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_TERMINATED'');\n  end if;\n\n  select mp.id, mp.is_active into v_plan from public.mentor_plans mp\n   where mp.mentor_id = v_uid and mp.plan_tier = v_tier for update;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_NOT_FOUND'', ''plan_tier'', v_tier);\n  end if;\n\n  if p_is_active = false then\n    select count(*) into v_others from public.mentor_plans mp\n     where mp.mentor_id = v_uid and mp.plan_tier in (''limited'', ''standard'', ''premium'')\n       and mp.plan_tier <> v_tier and coalesce(mp.is_active, true);\n    if v_others = 0 then\n      return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''LAST_ACTIVE_PLAN'', ''plan_tier'', v_tier);\n    end if;\n  end if;\n\n  if coalesce(v_plan.is_active, true) is distinct from p_is_active then\n    update public.mentor_plans mp set is_active = p_is_active where mp.id = v_plan.id;\n    v_changed := true;\n  end if;\n\n  select coalesce(array_agg(mp.plan_tier order by case mp.plan_tier when ''limited'' then 1 when ''standard'' then 2 else 3 end), ''{}''::text[])\n    into v_active_tiers\n    from public.mentor_plans mp\n   where mp.mentor_id = v_uid and mp.plan_tier in (''limited'', ''standard'', ''premium'') and coalesce(mp.is_active, true);\n\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''plan_tier'', v_tier, ''is_active'', p_is_active,\n                            ''changed'', v_changed, ''active_tiers'', to_jsonb(v_active_tiers));\nend\n$fn$", "comment on function api_app_v1.mentor_plan_active_set(text, boolean) is\n  ''202(DB-4 D-1): 본인 요금제 tier 활성 토글 — 마지막 활성 tier 는 끌 수 없음(LAST_ACTIVE_PLAN) · terminating/terminated 는 MENTOR_TERMINATED · 기존 구독 유지, 신규 결제만 PLAN_INACTIVE 로 차단. 가격은 F8 그대로.''", "revoke all on function api_app_v1.mentor_plan_active_set(text, boolean) from public, anon", "grant execute on function api_app_v1.mentor_plan_active_set(text, boolean) to authenticated", "do $$\ndeclare v_oid oid;\nbegin\n  select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''api_app_v1'' and p.proname = ''mentor_plan_active_set''\n     and pg_get_function_identity_arguments(p.oid) = ''p_tier text, p_is_active boolean''\n     and p.prosecdef and coalesce(p.proconfig::text, '''') like ''%search_path=%'';\n  if v_oid is null then\n    raise exception ''202_SELFCHECK: identity/attributes 불일치'';\n  end if;\n  if has_function_privilege(''anon'', v_oid, ''EXECUTE'') or not has_function_privilege(''authenticated'', v_oid, ''EXECUTE'')\n     or has_function_privilege(''service_role'', v_oid, ''EXECUTE'') then\n    raise exception ''202_SELFCHECK: ACL 불일치(authenticated 만)'';\n  end if;\n  -- F8 불변(가격 함수의 identity·ACL)\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''api_web_v1'' and p.proname = ''mentor_plan_prices_set_self''\n                    and pg_get_function_identity_arguments(p.oid) = ''p_limited_cash_krw integer, p_standard_cash_krw integer, p_premium_cash_krw integer''\n                    and has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')) then\n    raise exception ''202_SELFCHECK: F8 변경됨'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "api_app_v1_student_status_student_id_document", "version": "20260905100500", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 203_api_app_v1_student_status_student_id_document.sql  (2026-09-05 · DB-4 묶음 E — 재학 상태 · 학생증 사후 제출)\n--\n-- 왜:\n--   E-1 학생 재학 상태 = `users.student_status`(text · 가입 메타 `handle_new_auth_user` 로만 채움). 변경 RPC 가 없고 `users` UPDATE 는\n--       20260803162257 A 절이 회수 + 보호 컬럼 트리거 → 앱이 못 바꾼다(A-4a 판정표 #12). 웹에도 편집 UI 없음(마이페이지 표시만).\n--       어휘 정본: 없음 — 웹 가입 폼(`components/auth/StudentSignupForm.tsx`)은 `studentStatus` 를 타입에만 두고 입력을 그리지 않는다(자유 텍스트 계약).\n--       → 서버는 grade_level 과 같은 규칙(trim · 최대 20자 · 학생만 · ''''=값 제거)만 강제한다.\n--       기존 `api_app_v1.user_profile_update_self(p_nickname, p_grade_level)` 의 시그니처는 바꾸지 않는다(지시서 \"하지 말 것\" 2 · PostgREST 오버로드 모호성 회피)\n--       → `_v2` 를 만들어 `p_student_status` 를 더한다. 닉네임·학년·계정 게이트는 정본 `core_private.user_profile_update_self_impl` 에 위임(복제 0).\n--       오류는 v1 과 같은 raise 규약(AUTH_REQUIRED 28000 · NICKNAME_* / GRADE_LEVEL_* 22023 · 추가: STUDENT_STATUS_NOT_ALLOWED · STUDENT_STATUS_TOO_LONG 22023) —\n--       앱의 v1 오류 매퍼가 그대로 동작한다.\n--   E-2 학생증 사후 제출(A-4a α8): 웹 `lib/mentor/mentorStudentIdActions.ts` 는 세션 클라이언트로 `student-id-images/{uid}/…` 업로드 후\n--       service_role 로 `mentor_profiles.student_id_image_url` 을 갱신한다(F7 allowlist 밖 컬럼 · 테이블 쓰기 회수). 앱은 업로드까지는 Storage RLS\n--       (`student_id_images_insert_own` — 첫 세그먼트 = uid)로 가능하지만 컬럼 반영 경로가 없다.\n--       → `api_app_v1.mentor_student_id_document_set_self(p_object_path)`: 경로 `{uid}/…`(하위 폴더 허용 · `..` 금지 · jpg/jpeg/png/pdf) +\n--         `storage.objects` 실재·소유(bucket ''student-id-images'' · name = 경로 · owner_id = uid — 139 qna_register_attachment 와 같은 검증) →\n--         `student_id_image_url = ''student-id-images/'' || 경로`(웹 formatStudentIdImageStoredRef 형식). 덮어쓰기 허용(웹 사후 제출 동일 — \"다른 서류로 바꾸려면\").\n--       크기·매직바이트(웹 20MB · JPG/PNG/PDF)는 서버 액션 검증이라 앱은 클라이언트 검증으로 내려간다(A-4a 3-4 와 같은 신뢰도 · 보고서 기재).\n--       트리거 대조: enforce_mentor_profile_privileged_guard(verification_status·cap_limit 만) · 192 재판정(대학·학과만) — 미발화.\n-- 권한: 두 함수 REVOKE public·anon · GRANT authenticated 만.\n--\n-- Apply: 저장소 표준 경로(db-apply-pending). pack 등재: supabase/baseline/post_ledger_backfills/20260905100500_api_app_v1_student_status_student_id_document.sql\n-- Rollback: supabase/rollback/20260905100500_api_app_v1_student_status_student_id_document_rollback.sql\n-- =============================================================================\n\nbegin", "do $$\nbegin\n  if (select count(*) from pg_namespace where nspname in (''api_app_v1'', ''core_private'')) <> 2 then\n    raise exception ''203_GATE: api_app_v1/core_private 스키마 부재'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''core_private'' and p.proname = ''user_profile_update_self_impl''\n                    and pg_get_function_identity_arguments(p.oid) = ''p_user_id uuid, p_nickname text, p_grade_level text'') then\n    raise exception ''203_GATE: core_private.user_profile_update_self_impl identity 불일치(20260803162257)'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''api_app_v1'' and p.proname = ''user_profile_update_self''\n                    and pg_get_function_identity_arguments(p.oid) = ''p_nickname text, p_grade_level text'') then\n    raise exception ''203_GATE: api_app_v1.user_profile_update_self(v1) 부재 — 그대로 둬야 한다'';\n  end if;\n  if not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''users'' and column_name = ''student_status'') then\n    raise exception ''203_GATE: users.student_status 부재(001)'';\n  end if;\n  if not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''mentor_profiles'' and column_name = ''student_id_image_url'') then\n    raise exception ''203_GATE: mentor_profiles.student_id_image_url 부재(001)'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''storage'' and table_name = ''objects'' and column_name in (''bucket_id'',''name'',''owner_id'')) <> 3 then\n    raise exception ''203_GATE: storage.objects 컬럼 불일치'';\n  end if;\n  if not exists (select 1 from storage.buckets b where b.id = ''student-id-images'' and b.public = false) then\n    raise exception ''203_GATE: 비공개 버킷 student-id-images 부재(039)'';\n  end if;\n  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n              where n.nspname = ''api_app_v1'' and p.proname in (''user_profile_update_self_v2'', ''mentor_student_id_document_set_self'')) then\n    raise exception ''203_GATE: 대상 함수가 이미 있다'';\n  end if;\nend $$", "-- ── E-1. user_profile_update_self_v2 ─────────────────────────────────────────\ncreate function api_app_v1.user_profile_update_self_v2(\n  p_nickname text default null,\n  p_grade_level text default null,\n  p_student_status text default null\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_res jsonb;\n  v_role text;\n  v_ss text;\n  v_out text;\nbegin\n  -- 닉네임·학년·계정 게이트·행 잠금은 정본 impl(v1 과 동일 raise 규약 — AUTH_REQUIRED 포함)\n  v_res := core_private.user_profile_update_self_impl(v_uid, p_nickname, p_grade_level);\n\n  if p_student_status is not null then\n    select u.role into v_role from public.users u where u.id = v_uid;\n    if v_role is distinct from ''student'' then\n      raise exception ''STUDENT_STATUS_NOT_ALLOWED'' using errcode = ''22023'';\n    end if;\n    -- grade_level 과 동일 규칙: null=유지 · ''''=값 제거 · trim · 최대 20자(자유 텍스트 — 어휘 정본 없음)\n    v_ss := nullif(btrim(p_student_status), '''');\n    if v_ss is not null and char_length(v_ss) > 20 then\n      raise exception ''STUDENT_STATUS_TOO_LONG'' using errcode = ''22023'';\n    end if;\n    update public.users u set student_status = v_ss, updated_at = now() where u.id = v_uid\n      returning u.student_status into v_out;\n  else\n    select u.student_status into v_out from public.users u where u.id = v_uid;\n  end if;\n\n  return v_res || jsonb_build_object(''student_status'', v_out);\nend\n$fn$", "comment on function api_app_v1.user_profile_update_self_v2(text, text, text) is\n  ''203(DB-4 E-1): v1(user_profile_update_self) + p_student_status(users.student_status · 학생만 · trim · ≤20자 · ''''=제거). 닉네임·학년·게이트는 core_private impl 위임. v1 은 그대로.''", "-- ── E-2. mentor_student_id_document_set_self ──────────────────────────────────\ncreate function api_app_v1.mentor_student_id_document_set_self(p_object_path text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_role text; v_status text; v_susp timestamptz; v_norm text;\n  v_path text := regexp_replace(btrim(coalesce(p_object_path, '''')), ''^/+'', '''');\n  v_ext text;\n  v_ref text;\n  v_updated timestamptz;\nbegin\n  if v_uid is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  end if;\n  select u.role, u.status, u.suspended_until into v_role, v_status, v_susp from public.users u where u.id = v_uid;\n  if not found or v_role is distinct from ''mentor'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROLE_NOT_MENTOR'');\n  end if;\n  v_norm := lower(btrim(coalesce(v_status, '''')));\n  if v_norm = ''banned'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_BANNED'');\n  end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_SUSPENDED'');\n  end if;\n  if v_norm not in (''active'', ''suspended'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_NOT_ACTIVE'');\n  end if;\n  if public.account_deletion_write_blocked(v_uid) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  end if;\n  if not exists (select 1 from public.mentor_profiles mp where mp.user_id = v_uid) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_PROFILE_NOT_FOUND'');\n  end if;\n\n  -- 저장값 형식(student-id-images/…)으로 넘어와도 받는다 — 객체 경로만 남긴다\n  if v_path like ''student-id-images/%'' then\n    v_path := substr(v_path, char_length(''student-id-images/'') + 1);\n  end if;\n  if v_path = '''' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''STORAGE_PATH_REQUIRED'');\n  end if;\n  if split_part(v_path, ''/'', 1) is distinct from v_uid::text\n     or split_part(v_path, ''/'', 2) = ''''\n     or v_path ~ ''(^|/)\\.\\.(/|$)''\n     or v_path like ''%//%'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''STORAGE_PATH_INVALID'');\n  end if;\n  v_ext := lower(coalesce((regexp_match(v_path, ''\\.([A-Za-z0-9]+)$''))[1], ''''));\n  if v_ext not in (''jpg'', ''jpeg'', ''png'', ''pdf'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''STORAGE_FILE_TYPE_INVALID'');\n  end if;\n  -- 객체 실재 + 정확한 버킷 + 소유(owner_id = auth.uid()) — 139 qna_register_attachment 동일 검증\n  if not exists (select 1 from storage.objects o\n                  where o.bucket_id = ''student-id-images'' and o.name = v_path and o.owner_id = v_uid::text) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''STORAGE_OBJECT_NOT_OWNED'');\n  end if;\n\n  v_ref := ''student-id-images/'' || v_path;\n  update public.mentor_profiles mp\n     set student_id_image_url = v_ref\n   where mp.user_id = v_uid\n   returning mp.updated_at into v_updated;\n\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''stored_ref'', v_ref, ''updated_at'', v_updated);\nend\n$fn$", "comment on function api_app_v1.mentor_student_id_document_set_self(text) is\n  ''203(DB-4 E-2): 학생증 사후 제출 반영 — student-id-images/{uid}/… 객체 실재·소유 검증 후 mentor_profiles.student_id_image_url 갱신(웹 submitMentorStudentIdImageAction 의 service_role UPDATE 와 동일 형식). 덮어쓰기 허용.''", "-- ── 권한 ───────────────────────────────────────────────────────────────────────\nrevoke all on function api_app_v1.user_profile_update_self_v2(text, text, text) from public, anon", "revoke all on function api_app_v1.mentor_student_id_document_set_self(text) from public, anon", "grant execute on function api_app_v1.user_profile_update_self_v2(text, text, text) to authenticated", "grant execute on function api_app_v1.mentor_student_id_document_set_self(text) to authenticated", "do $$\ndeclare v_n integer;\nbegin\n  select count(*) into v_n\n    from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''api_app_v1''\n     and p.prosecdef and coalesce(p.proconfig::text, '''') like ''%search_path=%''\n     and not has_function_privilege(''anon'', p.oid, ''EXECUTE'')\n     and has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n     and not has_function_privilege(''service_role'', p.oid, ''EXECUTE'')\n     and (p.proacl is null or (p.proacl::text not like ''{=%'' and p.proacl::text not like ''%,=%''))\n     and (p.proname, pg_get_function_identity_arguments(p.oid)) in\n         ((''user_profile_update_self_v2'', ''p_nickname text, p_grade_level text, p_student_status text''),\n          (''mentor_student_id_document_set_self'', ''p_object_path text''));\n  if v_n <> 2 then\n    raise exception ''203_SELFCHECK: 함수 2종 identity/SECDEF/ACL 불일치(matched %)'', v_n;\n  end if;\n  -- v1 불변 · impl 위임\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''api_app_v1'' and p.proname = ''user_profile_update_self''\n                    and pg_get_function_identity_arguments(p.oid) = ''p_nickname text, p_grade_level text''\n                    and has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')) then\n    raise exception ''203_SELFCHECK: v1 user_profile_update_self 변경됨'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''api_app_v1'' and p.proname = ''user_profile_update_self_v2''\n                    and p.prosrc like ''%core_private.user_profile_update_self_impl(%''\n                    and p.prosrc not like ''%NICKNAME_TOO_LONG%'') then\n    raise exception ''203_SELFCHECK: v2 가 impl 에 위임하지 않거나 닉네임 규칙을 복제했다'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''api_app_v1'' and p.proname = ''mentor_student_id_document_set_self''\n                    and p.prosrc like ''%storage.objects%'' and p.prosrc like ''%owner_id = v_uid::text%'') then\n    raise exception ''203_SELFCHECK: 학생증 함수의 객체 소유 검증 부재'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "api_app_v1_individual_question_create_v2", "version": "20260905100600", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 204_api_app_v1_individual_question_create_v2.sql  (2026-09-05 · DB-4 묶음 F — 개별질문 과목 인자)\n--\n-- 왜: 앱이 부르는 `public.create_individual_question_as_student`(092)는 과목을 받지 않고 코어 `create_individual_question_with_hold_v2` 에\n--   p_subject NULL 을 고정 전달한다. `individual_questions` 에 본인 UPDATE 정책도 없어(iq_select_party SELECT 뿐) 등록 뒤에도 못 채운다\n--   (A-4a 보고서 §6 · 판정표 §5-3). 공개형 질문은 멘토가 과목으로 거르므로 과목 없는 등록은 라우팅되지 않는다.\n--   기존 함수는 바꾸지 않는다(웹·구 앱이 쓴다 — \"하지 말 것\" 2). `_v2` 를 `api_app_v1` 에 만들어 `p_subject` 를 더한다(나머지 시그니처·반환·오류 규약 동일).\n--\n-- F-1 api_app_v1.create_individual_question_as_student_v2(p_question_type text, p_title text, p_body text, p_amount_cents int default null,\n--        p_designated_mentor_id uuid default null, p_idempotency_key text default null, p_subject text default null) returns setof public.individual_questions\n--   · v1 과 동일: AUTH_REQUIRED(28000) · INVALID_INPUT(22023 — type/title/body/amount/designated) · MENTOR_PRICE_NOT_SET(P0001) · 코어 실패\n--     INDIVIDUAL_QUESTION_CREATE_FAILED:<code>:<message>(P0001 — 잔액 부족 = CASH_INSUFFICIENT · 멘토 미승인 = mentor_not_approved 등) · 직접 가격은\n--     `mentor_individual_question_pricing`(앱 표시가와 같은 소스) · 앱이 키를 안 보내면 랜덤 키(코어 NOT NULL 충족용 — 진짜 멱등은 앱이 안정 키를 보내야 한다 · 092 주석 승계)\n--   · 추가: p_subject 는 코드 정본 `public.subjects.code`(074 — lib/subjects/subjectCatalog.ts 와 동일 집합) 실존 값만 — 아니면 INVALID_SUBJECT(22023) ·\n--     **open(공개형)은 과목 필수**(SUBJECT_REQUIRED 22023 — 라우팅 전제) · direct(지정형)는 선택(NULL 허용 · 웹 지정형과 동일).\n--   · 자금·자격 판정은 전부 코어 v2(service_role 전용)에 위임 — 이 래퍼는 가격 조회·키 생성·과목 검증만(092 와 같은 얇은 껍데기 · 금액 계산 0).\n--   · 만료(expires_at)는 v1 과 같이 설정하지 않는다(웹은 서버 액션이 env 기반 시간으로 best-effort 설정 — 앱 트랙 별도 · 보고서 기재).\n-- 권한: REVOKE public·anon · GRANT authenticated 만(v1 과 동일). 앱은 A-4b 에서 `api_app_v1` 스키마의 `_v2` 로 전환한다.\n--\n-- Apply: 저장소 표준 경로(db-apply-pending). pack 등재: supabase/baseline/post_ledger_backfills/20260905100600_api_app_v1_individual_question_create_v2.sql\n-- Rollback: supabase/rollback/20260905100600_api_app_v1_individual_question_create_v2_rollback.sql\n-- =============================================================================\n\nbegin", "do $$\nbegin\n  if not exists (select 1 from pg_namespace where nspname = ''api_app_v1'') then\n    raise exception ''204_GATE: api_app_v1 스키마 부재'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''public'' and p.proname = ''create_individual_question_as_student''\n                    and pg_get_function_identity_arguments(p.oid) = ''p_question_type text, p_title text, p_body text, p_amount_cents integer, p_designated_mentor_id uuid, p_idempotency_key text'') then\n    raise exception ''204_GATE: v1 create_individual_question_as_student identity 불일치(092) — 그대로 둬야 한다'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''public'' and p.proname = ''create_individual_question_with_hold_v2''\n                    and pg_get_function_identity_arguments(p.oid) = ''p_student_id uuid, p_question_type text, p_mentor_id uuid, p_subject text, p_topic text, p_title text, p_body text, p_price_cents integer, p_idempotency_key text, p_required_school_tier text, p_required_major_category text'') then\n    raise exception ''204_GATE: 코어 create_individual_question_with_hold_v2 identity 불일치(080_c)'';\n  end if;\n  if not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''individual_questions'' and column_name = ''subject'') then\n    raise exception ''204_GATE: individual_questions.subject 부재(070)'';\n  end if;\n  if not exists (select 1 from information_schema.tables where table_schema = ''public'' and table_name = ''subjects'')\n     or not exists (select 1 from public.subjects where code = ''math_calculus'') then\n    raise exception ''204_GATE: subjects 정본(074 소분류) 부재'';\n  end if;\n  if not exists (select 1 from information_schema.tables where table_schema = ''public'' and table_name = ''mentor_individual_question_pricing'') then\n    raise exception ''204_GATE: mentor_individual_question_pricing 부재(094)'';\n  end if;\n  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''api_app_v1'' and p.proname = ''create_individual_question_as_student_v2'') then\n    raise exception ''204_GATE: 대상 함수가 이미 있다'';\n  end if;\nend $$", "create function api_app_v1.create_individual_question_as_student_v2(\n  p_question_type text,\n  p_title text,\n  p_body text,\n  p_amount_cents int default null,\n  p_designated_mentor_id uuid default null,\n  p_idempotency_key text default null,\n  p_subject text default null\n)\nreturns setof public.individual_questions\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_type text := lower(btrim(coalesce(p_question_type, '''')));\n  v_idem text := nullif(btrim(coalesce(p_idempotency_key, '''')), '''');\n  v_subject text := nullif(btrim(coalesce(p_subject, '''')), '''');\n  v_price int;\n  v_res public.individual_question_escrow_result;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  if v_type not in (''direct'', ''open'') then\n    raise exception ''INVALID_INPUT: question_type must be direct or open'' using errcode = ''22023'';\n  end if;\n\n  if char_length(btrim(coalesce(p_title, ''''))) = 0 or char_length(btrim(coalesce(p_body, ''''))) = 0 then\n    raise exception ''INVALID_INPUT: title and body are required'' using errcode = ''22023'';\n  end if;\n\n  -- 과목: 코드 정본(subjects.code) 실존 값만 · 공개형은 필수(멘토 라우팅 전제) · 지정형은 선택\n  if v_subject is not null and not exists (select 1 from public.subjects s where s.code = v_subject) then\n    raise exception ''INVALID_SUBJECT'' using errcode = ''22023'';\n  end if;\n  if v_type = ''open'' and v_subject is null then\n    raise exception ''SUBJECT_REQUIRED'' using errcode = ''22023'';\n  end if;\n\n  -- 가격 결정(v1 동일): open 은 앱이 보낸 금액, direct 는 멘토 가격표에서 조회 — 임의 계산 없음\n  if v_type = ''direct'' then\n    if p_designated_mentor_id is null then\n      raise exception ''INVALID_INPUT: designated_mentor_id is required for direct'' using errcode = ''22023'';\n    end if;\n    select mp.amount_cents into v_price from public.mentor_individual_question_pricing mp where mp.mentor_id = p_designated_mentor_id;\n    if v_price is null then\n      raise exception ''MENTOR_PRICE_NOT_SET'' using errcode = ''P0001'';\n    end if;\n  else\n    v_price := p_amount_cents;\n    if v_price is null or v_price <= 0 then\n      raise exception ''INVALID_INPUT: amount_cents must be positive for open'' using errcode = ''22023'';\n    end if;\n  end if;\n\n  -- 멱등성 키: 앱이 안 보내면 랜덤 생성(코어 NOT NULL 충족용 — v1 동일)\n  if v_idem is null then\n    v_idem := ''iqc:'' || gen_random_uuid()::text;\n  end if;\n\n  -- 코어 v2(service_role 전용)에 위임 — 자격 파라미터는 v1 과 같이 NULL\n  v_res := public.create_individual_question_with_hold_v2(\n    v_uid, v_type, p_designated_mentor_id, v_subject, null, p_title, p_body, v_price, v_idem, null, null);\n\n  if not v_res.ok then\n    raise exception ''INDIVIDUAL_QUESTION_CREATE_FAILED:%:%'', v_res.code, v_res.message using errcode = ''P0001'';\n  end if;\n\n  return query select q.* from public.individual_questions q where q.id = v_res.question_id;\nend\n$fn$", "comment on function api_app_v1.create_individual_question_as_student_v2(text, text, text, int, uuid, text, text) is\n  ''204(DB-4 F-1): create_individual_question_as_student(092) + p_subject(subjects.code 정본 · open 필수 · direct 선택). 나머지 시그니처·반환·오류 규약 v1 동일. 자금·자격은 코어 v2 위임. v1 은 그대로.''", "revoke all on function api_app_v1.create_individual_question_as_student_v2(text, text, text, int, uuid, text, text) from public, anon", "grant execute on function api_app_v1.create_individual_question_as_student_v2(text, text, text, int, uuid, text, text) to authenticated", "do $$\ndeclare v_oid oid;\nbegin\n  select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''api_app_v1'' and p.proname = ''create_individual_question_as_student_v2''\n     and pg_get_function_identity_arguments(p.oid) = ''p_question_type text, p_title text, p_body text, p_amount_cents integer, p_designated_mentor_id uuid, p_idempotency_key text, p_subject text''\n     and p.prosecdef and coalesce(p.proconfig::text, '''') like ''%search_path=%'' and p.proretset;\n  if v_oid is null then\n    raise exception ''204_SELFCHECK: identity/attributes 불일치'';\n  end if;\n  if has_function_privilege(''anon'', v_oid, ''EXECUTE'') or not has_function_privilege(''authenticated'', v_oid, ''EXECUTE'')\n     or has_function_privilege(''service_role'', v_oid, ''EXECUTE'') then\n    raise exception ''204_SELFCHECK: ACL 불일치(authenticated 만)'';\n  end if;\n  if (select prosrc from pg_proc where oid = v_oid) not like ''%public.create_individual_question_with_hold_v2(%''\n     or (select prosrc from pg_proc where oid = v_oid) like ''%insert into public.cash_ledger%'' then\n    raise exception ''204_SELFCHECK: 코어 위임 아님 또는 자금 로직 복제'';\n  end if;\n  -- v1 불변(identity·ACL)\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''public'' and p.proname = ''create_individual_question_as_student''\n                    and has_function_privilege(''authenticated'', p.oid, ''EXECUTE'')\n                    and not has_function_privilege(''anon'', p.oid, ''EXECUTE'')) then\n    raise exception ''204_SELFCHECK: v1 ACL 변경됨'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "plan_price_stats", "version": "20260906100100", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 205_plan_price_stats.sql  (2026-09-06 · DB-5 묶음 A — 요금제 평균가 함수)\n--\n-- 왜: 웹 메인·요금제 페이지가 \"실제 멘토들이 정한 요금제의 평균가\"를 표시한다. 정본 데이터는 `mentor_plans`(멘토별 tier 행 · F8 저장값)이며\n--   웹이 표를 직접 집계하면 anon 에게 멘토별 단가 전체가 열린다. 집계만 돌려주는 SECURITY DEFINER 함수를 두고, 갱신 주기(매일)는 웹 캐시가 맡는다.\n--\n-- 확정 사양(오너 2026-09-06):\n--   · 평균(중앙값 아님) · 원 단위 100원 반올림 · 표본 5명 미만이면 평균 대신 **최소값**을 돌려주고 fallback = true\n--   · 대상: `mentor_profiles.verification_status = ''approved''` AND `mentor_plans.is_active = true` (+ amount_cents 양수 · tier 3종)\n--   · `amount_cents` 는 원×100 저장(29,900원 = 2,990,000) → avg_won = round(avg(amount_cents) / 10000) × 100\n--     (검산 2026-09-06 운영 read-only 실측: limited 30,000 · standard 85,300 · premium 175,600 · 각 표본 75 — 세 값 일치)\n--\n-- A-1 public.plan_price_stats() returns table(plan_tier text, sample_count int, avg_won int, min_won int, max_won int, fallback boolean)\n--   · SECURITY DEFINER · STABLE · search_path '''' · 항상 3행(limited · standard · premium 순) — 표본 0이면 sample_count 0 · 금액 NULL · fallback true\n--     (웹은 NULL 이면 카탈로그 표시가 `lib/subscribe/subscribePlanCatalog.ts` 로 폴백)\n--   · GRANT EXECUTE anon · authenticated(메인은 비로그인) · service_role(서버 캐시 갱신 경로). 개별 멘토 단가는 노출하지 않는다(집계 6열만).\n--\n-- Apply: 저장소 표준 경로(db-apply-pending). pack 등재: supabase/baseline/post_ledger_backfills/20260906100100_plan_price_stats.sql\n-- Rollback: supabase/rollback/20260906100100_plan_price_stats_rollback.sql\n-- =============================================================================\n\nbegin", "do $$\nbegin\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''mentor_plans''\n       and column_name in (''mentor_id'', ''plan_tier'', ''amount_cents'', ''is_active'')) <> 4 then\n    raise exception ''205_GATE: mentor_plans 컬럼(mentor_id·plan_tier·amount_cents·is_active) 불일치(004·103)'';\n  end if;\n  if not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''mentor_profiles'' and column_name = ''verification_status'') then\n    raise exception ''205_GATE: mentor_profiles.verification_status 부재(001)'';\n  end if;\n  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''public'' and p.proname = ''plan_price_stats'') then\n    raise exception ''205_GATE: public.plan_price_stats 가 이미 있다'';\n  end if;\nend $$", "create function public.plan_price_stats()\nreturns table (\n  plan_tier    text,\n  sample_count int,\n  avg_won      int,\n  min_won      int,\n  max_won      int,\n  fallback     boolean\n)\nlanguage sql\nstable\nsecurity definer\nset search_path to ''''\nas $fn$\n  with base as (\n    select mp.plan_tier, mp.amount_cents\n      from public.mentor_plans mp\n      join public.mentor_profiles p on p.user_id = mp.mentor_id\n     where p.verification_status = ''approved''\n       and mp.is_active = true\n       and mp.plan_tier in (''limited'', ''standard'', ''premium'')\n       and mp.amount_cents is not null\n       and mp.amount_cents > 0\n  ),\n  agg as (\n    select b.plan_tier,\n           count(*)::int                                   as sample_count,\n           (round(avg(b.amount_cents) / 10000.0) * 100)::int as avg_won_r100,   -- cents → 원(÷100) → 100원 단위 반올림\n           (min(b.amount_cents) / 100)::int                as min_won,\n           (max(b.amount_cents) / 100)::int                as max_won\n      from base b\n     group by b.plan_tier\n  )\n  select t.tier                                     as plan_tier,\n         coalesce(a.sample_count, 0)                 as sample_count,\n         case when coalesce(a.sample_count, 0) >= 5 then a.avg_won_r100 else a.min_won end as avg_won,\n         a.min_won,\n         a.max_won,\n         (coalesce(a.sample_count, 0) < 5)           as fallback\n    from (values (''limited'', 1), (''standard'', 2), (''premium'', 3)) as t(tier, ord)\n    left join agg a on a.plan_tier = t.tier\n   order by t.ord;\n$fn$", "comment on function public.plan_price_stats() is\n  ''205(DB-5 A-1): 승인 멘토 · 활성 요금제의 tier 별 평균가(100원 반올림 · cents÷100) · 최소 · 최대 · 표본 수. 표본 5명 미만이면 avg_won = 최소값 + fallback true. 항상 3행. anon/authenticated/service_role 읽기 — 개별 단가 비노출.''", "revoke all on function public.plan_price_stats() from public", "grant execute on function public.plan_price_stats() to anon, authenticated, service_role", "do $$\ndeclare v_oid oid; v_rows int; v_bad int;\nbegin\n  select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''public'' and p.proname = ''plan_price_stats'' and pg_get_function_identity_arguments(p.oid) = ''''\n     and p.prosecdef and p.provolatile = ''s'' and coalesce(p.proconfig::text, '''') like ''%search_path=%'' and p.proretset;\n  if v_oid is null then\n    raise exception ''205_SELFCHECK: identity/attributes 불일치(SECDEF · STABLE · search_path · setof)'';\n  end if;\n  if not has_function_privilege(''anon'', v_oid, ''EXECUTE'') or not has_function_privilege(''authenticated'', v_oid, ''EXECUTE'')\n     or not has_function_privilege(''service_role'', v_oid, ''EXECUTE'') then\n    raise exception ''205_SELFCHECK: ACL 불일치(anon·authenticated·service_role EXECUTE)'';\n  end if;\n  -- 형태: 항상 3행 · tier 순서 고정 · fallback 은 표본 수와 정합\n  select count(*) into v_rows from public.plan_price_stats();\n  if v_rows <> 3 then\n    raise exception ''205_SELFCHECK: 3행이 아니다(%)'', v_rows;\n  end if;\n  select count(*) into v_bad from public.plan_price_stats() s\n   where s.fallback is distinct from (s.sample_count < 5)\n      or (s.sample_count >= 5 and s.avg_won is null)\n      or (s.avg_won is not null and s.avg_won % 100 <> 0)\n      or (s.sample_count = 0 and (s.avg_won is not null or s.min_won is not null or s.max_won is not null));\n  if v_bad <> 0 then\n    raise exception ''205_SELFCHECK: 결과 정합성 위반 % 행'', v_bad;\n  end if;\n  if (select string_agg(s.plan_tier, '','' order by s.plan_tier) from public.plan_price_stats() s) <> ''limited,premium,standard'' then\n    raise exception ''205_SELFCHECK: tier 집합 불일치'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "social_signup_profile_completion", "version": "20260906100200", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 206_social_signup_profile_completion.sql  (2026-09-06 · DB-5 묶음 B+C — 가입 트리거 소셜 대응 + 프로필 완성 RPC)\n--\n-- 왜(B): `handle_new_auth_user`(001 → 122/20260717044250 라이브 본문 md5 297616fe…)는 `auth.signUp` 메타의 `app_role` 로 역할을 정하고\n--   `users`(+ 멘토면 `mentor_profiles`·`verification_logs`) 행을 만든다. **소셜(OAuth) 가입은 앱 메타(`app_role` 등 20키)가 없고 provider 메타(name·avatar·email)만 온다.**\n--   현재 동작(실측): `app_role` 없음 → `r := ''student''` 폴백 → **약관 동의 시각·생년월일·닉네임 없는 학생 행을 조용히 만든다**(실패도 스킵도 아님).\n--   운영 실측 2026-09-06: 소셜 identity 0(email 83) · `app_role` 없는 auth 행 2건(2026-05-01 대시보드 생성 관리자 — 같은 폴백으로 student 생성 후 수동 승격).\n--   분기 기준은 \"메타 없음\"이 아니라 **`raw_user_meta_data ? ''app_role''` 유무**다(정정 B).\n--\n-- 설계:\n--   소셜 가입(app_role 없음) → users 행: role NULL · profile_completed_at NULL · email = auth.users(없으면 NULL) · full_name/nickname = provider 이름 · 나머지 NULL\n--                            → student_profiles 는 없다(테이블 자체가 없음 — DB-4 §2-E) · mentor_profiles 는 만들지 않는다(역할 모름)\n--   이메일 가입(app_role 있음) → 지금 그대로(122 정규화 동일) + profile_completed_at = now()\n--   · `users.profile_completed_at timestamptz null` 추가 — \"완성 전\" 판정 컬럼. 기존 가입자 전원 created_at 으로 백필(운영 83명 = admin 3 · mentor 76 · student 4).\n--   · `users.role` NOT NULL 은 **완화**(DROP NOT NULL) + CHECK `users_role_required_when_completed (role is not null or profile_completed_at is null)`\n--     — 임시 역할값(''pending'')은 두지 않는다(다른 CHECK·RLS·is_admin()·ugc_write_allowed() 에 걸린다 — \"하지 말 것\" 3). `users_role_check` 는 그대로(NULL 허용).\n--   · 트리거 로직을 `core_private.user_signup_provision_impl(...)` 로 빼서 트리거(이메일·소셜)와 C 의 `complete_profile` 이 **한 벌**을 공유한다.\n--   · 119 `enforce_users_role_guard`: 완성 전(role NULL · profile_completed_at NULL) 행에 student/mentor 를 처음 채우는 전이만 추가 허용\n--     (그 외 분기 원문 그대로). 완성 전 행은 이 배치 이후에만 생기며, users 테이블 UPDATE 권한은 authenticated 에 없고(20260803162257 A)\n--     `users_protected_columns_guard` 가 클라이언트 역할의 role 변경을 거부하므로 이 전이는 SECURITY DEFINER 경로(complete_profile)로만 도달한다.\n--\n-- 왜(C): api_app_v1.complete_profile(p_role, p_display_name, p_birthdate, p_terms_agreed, p_marketing_agreed, p_grade_level, p_university_name, p_department_name) returns jsonb\n--   · auth.uid() 의 users.profile_completed_at IS NULL 일 때만 · 이미 완성이면 ALREADY_COMPLETED · 필수 약관(이용약관+개인정보) 미동의 TERMS_REQUIRED ·\n--     학생인데 학년 없음 GRADE_REQUIRED · 멘토인데 대학 없음 UNIVERSITY_REQUIRED · 그 외 AUTH_REQUIRED · ROLE_INVALID · DISPLAY_NAME_REQUIRED/TOO_LONG(30자) ·\n--     BIRTHDATE_REQUIRED/INVALID(미래·1900 이전) · GRADE_LEVEL_TOO_LONG(20자) · 계정 게이트 ACCOUNT_BANNED/SUSPENDED/NOT_ACTIVE/DELETION_IN_PROGRESS · USER_NOT_FOUND\n--   · 수행 = 이메일 가입 트리거와 같은 결과(공유 impl): users 갱신(role · nickname=표시명 · birth_date · grade_level · terms/privacy_agreed_at=now() · marketing_agreed ·\n--     profile_completed_at=now()) · 멘토면 mentor_profiles(pending · 대학·학과 · 나머지 ''(미입력)'') + verification_logs. full_name 은 provider 이름 유지.\n--     약관 동의 기록 = users 컬럼 + **동의 원장 `user_consent_records`**(후속 a · 정정 C 철회): 이메일 가입 트리거 187 이 남기는 행과 같은 모양 —\n--     consent_type terms/privacy(+marketing) · consent_actor ''user'' · is_minor(만 14세 판정) · guardian_consent false · consent_version ''legal-placeholder-2026-06-20''(메타 없을 때의 187 기본값) ·\n--     source ''signup'' · metadata {role, birth_date, age_gate_checked_at, verification_method} · idempotency_key ''signup:<uid>:<type>:<version>''(운영 실측 2026-09-06: 80명 189행 전부 이 모양).\n--     원장 로직은 `core_private.user_consent_signup_impl(p_user_id, p_meta, p_source)` **한 벌**: 프로비저닝 impl 이 호출(이메일 가입 트리거 경로 · complete_profile)하고,\n--     187 트리거 함수 본문은 같은 impl 위임으로 교체(멱등 키 충돌 → 무해 no-op · 트리거 부착 그대로 · 원문 md5 게이트 · rollback 원문 복원).\n--   · 만 14세 판정: KST 달력 오늘 < 생년월일+14년(187 과 같은 식) → is_minor true · next ''guardian_consent''(기존 보호자 인증 WebView 흐름) ·\n--     아니면 멘토 → ''identity_verification'' · 그 외 ''home''. 반환 {ok, contract_version, role, is_minor, next, nickname, profile_completed_at}.\n--   · SECURITY DEFINER · search_path '''' · authenticated 만.\n--\n-- 완성 전 사용자의 접근(B): RLS 점검(pack 118본 · 정책 283행 · authenticated 실행 가능 SECDEF 함수 124종) 결과 —\n--   역할 검사가 있는 정책·RPC(is_admin · ugc_write_allowed · 승인 멘토 · 방/주문 당사자 · ROLE_NOT_STUDENT …)는 role NULL 을 거부한다.\n--   **auth.uid() 만 보는(또는 `OR is_admin()` 만 덧붙은) 쓰기 정책 18종**(favorites · user_blocks · content_reports · free_question_usage · payments intent · verification_logs ·\n--   device_tokens · notification_settings · ai_drafts · withdrawals · custom_request_posts crp_insert · custom_request_applications cra_insert · custom_request_orders cro_insert ·\n--   레거시 `to public` 5종: custom_request_posts/applications · custom_order_messages/deliverables · admin_action_logs)은 완성 전 사용자가 통과한다(테이블 INSERT 권한 authenticated 있음 — 실측).\n--   → 각 정책에 `public.user_profile_completed()` 조건을 추가한다(이름·명령·역할 불변 · 원문 + AND). 정책 96행 전수 수동 검토 · 스크래치 실측(scripts/verify/fixtures/db5_batch_post_fixture.sql B-4).\n--   RPC 쪽: `core_private.user_profile_update_self_impl`(20260803162257 D — 앱 v1/v2·웹 self 프로필 RPC 의 정본)의 `v_role not in (...)` 은 role NULL 을 통과시킨다(NULL not in → NULL)\n--   → `v_role is null or …` 한 줄만 보강(B-7 · 그 외 원문 그대로 · 시그니처·ACL 불변). 다른 authenticated SECDEF 함수는 역할 검사(ROLE_NOT_STUDENT 등)·관계 검사·ugc_write_allowed() 가 NULL 을 거부한다(실측).\n--   자기 users 행 읽기(users_select_own)는 그대로 · complete_profile 은 이 파일이 연다. SELECT 정책은 바꾸지 않는다(공개 데이터는 anon 도 읽고, 본인 데이터는 없다).\n--\n-- Apply: 저장소 표준 경로(db-apply-pending). pack 등재: supabase/baseline/post_ledger_backfills/20260906100200_social_signup_profile_completion.sql\n-- Rollback: supabase/rollback/20260906100200_social_signup_profile_completion_rollback.sql (트리거·동의 트리거·가드·impl 원문 복원 · 정책 18종 원문 복원 · 컬럼/CHECK 제거 ·\n--   NOT NULL 복원 · impl 원문 복원 — role NULL 행(소셜 미완성)이 있으면 롤백 게이트가 중단한다)\n-- =============================================================================\n\nbegin", "do $$\ndeclare v_md5 text; r record;\nbegin\n  if not exists (select 1 from pg_namespace where nspname = ''api_app_v1'') or not exists (select 1 from pg_namespace where nspname = ''core_private'') then\n    raise exception ''206_GATE: api_app_v1/core_private 스키마 부재'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''users''\n       and column_name in (''id'',''role'',''status'',''full_name'',''nickname'',''email'',''grade_level'',''student_status'',''birth_date'',''terms_agreed_at'',''privacy_agreed_at'',''marketing_agreed'',''suspended_until'',''created_at'',''updated_at'')) <> 15 then\n    raise exception ''206_GATE: users 컬럼 불일치(001·102)'';\n  end if;\n  if exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''users'' and column_name = ''profile_completed_at'') then\n    raise exception ''206_GATE: users.profile_completed_at 이 이미 있다'';\n  end if;\n  if (select is_nullable from information_schema.columns where table_schema = ''public'' and table_name = ''users'' and column_name = ''role'') <> ''NO'' then\n    raise exception ''206_GATE: users.role 이 이미 NULL 허용이다 — 전제(001 NOT NULL) 불일치'';\n  end if;\n  if not exists (select 1 from pg_constraint where conrelid = ''public.users''::regclass and conname = ''users_role_check'') then\n    raise exception ''206_GATE: users_role_check 부재(001)'';\n  end if;\n  if exists (select 1 from pg_constraint where conrelid = ''public.users''::regclass and conname = ''users_role_required_when_completed'') then\n    raise exception ''206_GATE: users_role_required_when_completed 가 이미 있다'';\n  end if;\n  if exists (select 1 from public.users where role is null) then\n    raise exception ''206_GATE: role NULL 행이 이미 있다'';\n  end if;\n  -- 정책 수 스냅샷(자가 검증에서 불변 확인)\n  create temp table db5_206_pre on commit drop as select count(*)::int as policies from pg_policies where schemaname = ''public'';\n  -- 트리거·가드 본문 전제(2026-09-06 운영 실측 md5). 119 가드는 운영 본문이 CRLF(SQL Editor 적용본 · 운영 함수 82개 동일)라 운영 실측값은\n  --   b0fe6f75… 이고(정본 · 2026-09-06 apply 가 pack 값만 기대하던 게이트에서 중단), pack 의 119(pre_ledger_baseline 번들 · LF)를 빈 DB 에 재생하면\n  --   702ddc29… 다(replace(E''\\r\\n'', E''\\n'') 후 동일 = 본문 같고 줄바꿈만 상이). 둘 다 허용해야 운영 apply 와 팩 재생(CI db-migration-pack-verify · 신규 환경)이 함께 통과한다.\n  select md5(pg_get_functiondef(''public.handle_new_auth_user()''::regprocedure)) into v_md5;\n  if v_md5 <> ''297616fe4e28f0dbda3b24244763a917'' then\n    raise exception ''206_GATE: handle_new_auth_user 본문 md5 불일치(122/20260717044250) — 현재 %'', v_md5;\n  end if;\n  select md5(pg_get_functiondef(''public.enforce_users_role_guard()''::regprocedure)) into v_md5;\n  if v_md5 not in (''b0fe6f758260c82ab3c342951cba6dc0'', ''702ddc298e6892306e796cae22f60201'') then\n    raise exception ''206_GATE: enforce_users_role_guard 본문 md5 불일치(119 · 운영 CRLF b0fe6f75… / pack LF 재생 702ddc29…) — 현재 %'', v_md5;\n  end if;\n  select md5(pg_get_functiondef(''public.handle_new_auth_user_consent_records()''::regprocedure)) into v_md5;\n  if v_md5 <> ''abc7c96e8d5707a6d8324a75d4b14815'' then\n    raise exception ''206_GATE: handle_new_auth_user_consent_records 본문 md5 불일치(187) — 현재 %'', v_md5;\n  end if;\n  if not exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace\n                  where n.nspname = ''auth'' and c.relname = ''users'' and t.tgname = ''zz_on_auth_user_created_consent_records'' and t.tgfoid = ''public.handle_new_auth_user_consent_records''::regproc) then\n    raise exception ''206_GATE: zz_on_auth_user_created_consent_records 트리거 부재(087)'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''user_consent_records''\n       and column_name in (''user_id'',''consent_type'',''consent_actor'',''is_minor'',''guardian_consent'',''consent_version'',''guardian_ref'',''agreed_at'',''source'',''metadata'',''idempotency_key'')) <> 11\n     or not exists (select 1 from pg_constraint where conrelid = ''public.user_consent_records''::regclass and conname = ''user_consent_records_consent_type_check''\n                      and pg_get_constraintdef(oid) like ''%''''terms''''%''''privacy''''%''''marketing''''%''''minor_guardian_consent''''%'')\n     or not exists (select 1 from pg_constraint where conrelid = ''public.user_consent_records''::regclass and contype = ''u'' and pg_get_constraintdef(oid) like ''%idempotency_key%'') then\n    raise exception ''206_GATE: user_consent_records 형태(컬럼 11 · consent_type CHECK 4종 · idempotency_key UNIQUE) 불일치(087)'';\n  end if;\n  select md5(pg_get_functiondef(''core_private.user_profile_update_self_impl(uuid,text,text)''::regprocedure)) into v_md5;\n  if v_md5 <> ''a0cb1b7f37b8195cc9ca370bfb5e90e7'' then\n    raise exception ''206_GATE: user_profile_update_self_impl 본문 md5 불일치(20260803162257 D) — 현재 %'', v_md5;\n  end if;\n  if not exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace\n                  where n.nspname = ''auth'' and c.relname = ''users'' and t.tgname = ''on_auth_user_created'' and t.tgfoid = ''public.handle_new_auth_user''::regproc) then\n    raise exception ''206_GATE: on_auth_user_created 트리거 부재'';\n  end if;\n  if not exists (select 1 from pg_trigger where tgrelid = ''public.users''::regclass and tgname = ''trg_users_role_guard'')\n     or not exists (select 1 from pg_trigger where tgrelid = ''public.users''::regclass and tgname = ''trg_users_protected_columns'')\n     or not exists (select 1 from pg_trigger where tgrelid = ''public.users''::regclass and tgname = ''trg_users_set_updated'') then\n    raise exception ''206_GATE: users 트리거(role guard · protected columns · set_updated) 부재'';\n  end if;\n  if has_table_privilege(''authenticated'', ''public.users'', ''UPDATE'') then\n    raise exception ''206_GATE: authenticated 가 users UPDATE 권한을 가진다(20260803162257 A 전제 불일치) — 완성 전 role 전이 허용을 열 수 없다'';\n  end if;\n  if not exists (select 1 from information_schema.tables where table_schema = ''public'' and table_name = ''mentor_profiles'')\n     or not exists (select 1 from information_schema.tables where table_schema = ''public'' and table_name = ''verification_logs'') then\n    raise exception ''206_GATE: mentor_profiles/verification_logs 부재(001)'';\n  end if;\n  if exists (select 1 from information_schema.tables where table_schema = ''public'' and table_name = ''student_profiles'') then\n    raise exception ''206_GATE: student_profiles 테이블이 존재한다 — 이 파일은 없음을 전제한다(DB-4 §2-E)'';\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''public'' and p.proname = ''account_deletion_write_blocked'') then\n    raise exception ''206_GATE: account_deletion_write_blocked 부재(151)'';\n  end if;\n  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n              where (n.nspname, p.proname) in ((''api_app_v1'', ''complete_profile''), (''core_private'', ''user_signup_provision_impl''), (''core_private'', ''user_consent_signup_impl''), (''public'', ''user_profile_completed''))) then\n    raise exception ''206_GATE: 대상 함수가 이미 있다'';\n  end if;\n  -- 정책 18종 원문 전제(cmd|roles|qual|with_check md5 · pack 118본 실측) — 다르면 원문 보존 복제가 어긋나므로 중단\n  for r in select * from (values\n    (''admin_action_logs'', ''관리자만 로그 기록'', ''61730a1a972b0a133083c6758b9100a5''),\n    (''ai_drafts'', ''ai_drafts_insert_own'', ''22786adbfea6dc265e7de4d6666a70c1''),\n    (''content_reports'', ''content_reports_insert_reporter'', ''3483c8d184a65671dce25208ce154412''),\n    (''custom_order_deliverables'', ''멘토만 납품 업로드'', ''512176700a7778900fb2a81691a1eb90''),\n    (''custom_order_messages'', ''당사자만 메시지 전송'', ''c1b3a9b4ccdcccda3dfa7cbdbbc4203f''),\n    (''custom_request_applications'', ''cra_insert'', ''a51a1a0859a59ea2f5426bc4483655b2''),\n    (''custom_request_applications'', ''멘토만 지원'', ''512176700a7778900fb2a81691a1eb90''),\n    (''custom_request_orders'', ''cro_insert'', ''a8eb37e64992df6f7e975d8d8c720964''),\n    (''custom_request_posts'', ''crp_insert'', ''42111e025e26fa48c5ae622048150c77''),\n    (''custom_request_posts'', ''학생만 의뢰 등록'', ''c1b3a9b4ccdcccda3dfa7cbdbbc4203f''),\n    (''device_tokens'', ''device_tokens_modify_own'', ''cd792c6be978266a76dd2ce37b454e21''),\n    (''favorites'', ''favorites_insert_own'', ''120bed7de2110c2a51917b1457fa7410''),\n    (''free_question_usage'', ''fqu_insert_own'', ''55c6e4a73e924acc92b6d9245cdefcc9''),\n    (''notification_settings'', ''notif_settings_modify_own'', ''cd792c6be978266a76dd2ce37b454e21''),\n    (''payments'', ''payments_insert_intent'', ''cea1288300e0aa57260f803e4b272ae5''),\n    (''user_blocks'', ''ub_insert_own'', ''ab4f2df30ce645b81654385e71159798''),\n    (''verification_logs'', ''ver_logs_insert_own'', ''cc88f9f4a4c7f44b5d1035d68cf326f5''),\n    (''withdrawals'', ''withdrawals_insert_self_requested'', ''9a869556a18b5708819f6f46f997113d'')\n  ) v(t, p, h) loop\n    if not exists (select 1 from pg_policies pp where pp.schemaname = ''public'' and pp.tablename = r.t and pp.policyname = r.p\n                     and md5(pp.cmd || ''|'' || array_to_string(pp.roles, '','') || ''|'' || coalesce(pp.qual, '''') || ''|'' || coalesce(pp.with_check, '''')) = r.h) then\n      raise exception ''206_GATE: 정책 %.% 원문 불일치(또는 부재)'', r.t, r.p;\n    end if;\n  end loop;\nend $$", "-- -----------------------------------------------------------------------------\n-- B-1. users.profile_completed_at + 백필 + role NOT NULL 완화\n-- -----------------------------------------------------------------------------\nalter table public.users add column profile_completed_at timestamptz null", "comment on column public.users.profile_completed_at is\n  ''206(DB-5 B): 프로필 완성 시각. NULL = 소셜 가입 후 역할·약관·생년월일 미입력(완성 전 — role NULL). 이메일 가입은 트리거가 now() 로 채우고, 소셜 가입은 api_app_v1.complete_profile 이 채운다. 기존 가입자는 created_at 으로 백필.''", "-- 백필: updated_at 은 건드리지 않는다(190 의 mentor_plans 백필과 같은 방식으로 touch 트리거를 잠시 끈다)\nalter table public.users disable trigger trg_users_set_updated", "update public.users set profile_completed_at = created_at where profile_completed_at is null", "alter table public.users enable trigger trg_users_set_updated", "alter table public.users alter column role drop not null", "alter table public.users\n  add constraint users_role_required_when_completed\n  check (role is not null or profile_completed_at is null)", "comment on constraint users_role_required_when_completed on public.users is\n  ''206(DB-5 B): role NULL 은 완성 전(profile_completed_at NULL)에만 허용. 완성된 행은 반드시 역할을 가진다.''", "-- -----------------------------------------------------------------------------\n-- B-2. 완성 여부 판정 헬퍼 (RLS 정책용 · anon/authenticated)\n-- -----------------------------------------------------------------------------\ncreate function public.user_profile_completed()\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path to ''''\nas $fn$\n  select exists (\n    select 1 from public.users u\n     where u.id = (select auth.uid())\n       and u.profile_completed_at is not null\n  );\n$fn$", "comment on function public.user_profile_completed() is\n  ''206(DB-5 B): 호출자(auth.uid()) 의 프로필이 완성됐는가(users.profile_completed_at IS NOT NULL). auth.uid() 만 보는 쓰기 정책 15종의 추가 조건.''", "revoke all on function public.user_profile_completed() from public", "grant execute on function public.user_profile_completed() to anon, authenticated", "-- -----------------------------------------------------------------------------\n-- B-3a. 동의 원장 공용 정본 (core_private — 187 트리거 본문의 인자화 · 외부 EXECUTE 0)\n--       p_meta 는 가입 메타(raw_user_meta_data) 와 같은 키 집합을 읽는다: app_role · birth_date · is_minor · consent_version · terms_agreed · privacy_agreed ·\n--       marketing_agreed · age_gate_checked_at · guardian_verification_method · guardian_consent · guardian_ref. 값·키 조립·멱등 키는 187 원문과 동일.\n-- -----------------------------------------------------------------------------\ncreate function core_private.user_consent_signup_impl(p_user_id uuid, p_meta jsonb, p_source text default ''signup'')\nreturns void\nlanguage plpgsql\nsecurity invoker\nset search_path to ''''\nas $fn$\ndeclare\n  m jsonb := coalesce(p_meta, ''{}''::jsonb);\n  v_role text;\n  v_birth_date date;\n  v_is_minor boolean := false;\n  v_version text;\n  v_agreed_at timestamptz := now();\n  v_metadata jsonb;\n  v_source text := coalesce(nullif(btrim(p_source), ''''), ''signup'');\nbegin\n  if p_user_id is null then\n    raise exception ''USER_ID_REQUIRED'' using errcode = ''22023'';\n  end if;\n  v_role := lower(coalesce(nullif(trim(m->>''app_role''), ''''), ''student''));\n  v_version := coalesce(nullif(trim(m->>''consent_version''), ''''), ''legal-placeholder-2026-06-20'');\n\n  begin\n    v_birth_date := nullif(trim(m->>''birth_date''), '''')::date;\n  exception when others then\n    v_birth_date := null;\n  end;\n\n  v_is_minor := coalesce(\n    nullif(trim(m->>''is_minor''), '''')::boolean,\n    case when v_birth_date is not null\n         then ((now() at time zone ''Asia/Seoul'')::date < (v_birth_date + interval ''14 years'')::date)\n         else false end\n  );\n\n  v_metadata := jsonb_build_object(\n    ''role'', v_role,\n    ''birth_date'', case when v_birth_date is not null then v_birth_date::text else null end,\n    ''age_gate_checked_at'', nullif(trim(m->>''age_gate_checked_at''), ''''),\n    ''verification_method'', coalesce(nullif(trim(m->>''guardian_verification_method''), ''''), ''legal_review_pending'')\n  );\n\n  if (m->>''terms_agreed'') = ''true'' then\n    insert into public.user_consent_records (\n      user_id, consent_type, consent_actor, is_minor, guardian_consent,\n      consent_version, agreed_at, source, metadata, idempotency_key\n    ) values (\n      p_user_id, ''terms'', ''user'', v_is_minor, false,\n      v_version, v_agreed_at, v_source, v_metadata, ''signup:'' || p_user_id::text || '':terms:'' || v_version\n    ) on conflict (idempotency_key) do nothing;\n  end if;\n\n  if (m->>''privacy_agreed'') = ''true'' then\n    insert into public.user_consent_records (\n      user_id, consent_type, consent_actor, is_minor, guardian_consent,\n      consent_version, agreed_at, source, metadata, idempotency_key\n    ) values (\n      p_user_id, ''privacy'', ''user'', v_is_minor, false,\n      v_version, v_agreed_at, v_source, v_metadata, ''signup:'' || p_user_id::text || '':privacy:'' || v_version\n    ) on conflict (idempotency_key) do nothing;\n  end if;\n\n  if (m->>''marketing_agreed'') = ''true'' then\n    insert into public.user_consent_records (\n      user_id, consent_type, consent_actor, is_minor, guardian_consent,\n      consent_version, agreed_at, source, metadata, idempotency_key\n    ) values (\n      p_user_id, ''marketing'', ''user'', v_is_minor, false,\n      v_version, v_agreed_at, v_source, v_metadata, ''signup:'' || p_user_id::text || '':marketing:'' || v_version\n    ) on conflict (idempotency_key) do nothing;\n  end if;\n\n  if v_is_minor and (m->>''guardian_consent'') = ''true'' then\n    insert into public.user_consent_records (\n      user_id, consent_type, consent_actor, is_minor, guardian_consent,\n      consent_version, guardian_ref, agreed_at, source, metadata, idempotency_key\n    ) values (\n      p_user_id, ''minor_guardian_consent'', ''guardian'', true, true,\n      v_version, nullif(trim(m->>''guardian_ref''), ''''), v_agreed_at, v_source, v_metadata,\n      ''signup:'' || p_user_id::text || '':minor_guardian_consent:'' || v_version\n    ) on conflict (idempotency_key) do nothing;\n  end if;\nend\n$fn$", "comment on function core_private.user_consent_signup_impl(uuid, jsonb, text) is\n  ''206(DB-5 B-3a · 후속 a): 가입 동의 원장 정본 — 187 트리거 본문의 인자화(terms/privacy/marketing + 미성년 guardian · 멱등 키 signup:<uid>:<type>:<version>). user_signup_provision_impl(이메일 가입 · complete_profile) 과 zz 트리거가 공유. 외부 EXECUTE 0.''", "revoke all on function core_private.user_consent_signup_impl(uuid, jsonb, text) from public, anon, authenticated", "-- -----------------------------------------------------------------------------\n-- B-3. 가입 프로비저닝 공용 정본 (core_private — 트리거 두 경로 + complete_profile 이 공유 · 외부 EXECUTE 0)\n--      본문은 122 트리거의 users upsert · mentor_profiles upsert · verification_logs 를 인자화한 것(의미 동일).\n-- -----------------------------------------------------------------------------\ncreate function core_private.user_signup_provision_impl(\n  p_user_id             uuid,\n  p_role                text,          -- ''student'' | ''mentor'' | NULL(소셜 · 완성 전)\n  p_email               text,\n  p_full_name           text,\n  p_nickname            text,\n  p_grade_level         text,\n  p_student_status      text,\n  p_birth_date          date,\n  p_terms_agreed        boolean,\n  p_privacy_agreed      boolean,\n  p_marketing_agreed    boolean,\n  p_university_name     text,\n  p_department_name     text,\n  p_teaching_subjects   text[],\n  p_high_school_name    text,\n  p_intro_line          text,\n  p_profile_completed_at timestamptz,\n  p_consent_meta        jsonb           -- 동의 원장 입력(187 메타 키) · NULL = 원장 기록 없음(소셜 가입 시점)\n)\nreturns void\nlanguage plpgsql\nsecurity invoker\nset search_path to ''''\nas $fn$\nbegin\n  if p_user_id is null then\n    raise exception ''USER_ID_REQUIRED'' using errcode = ''22023'';\n  end if;\n  if p_role is not null and p_role not in (''student'', ''mentor'') then\n    raise exception ''ROLE_INVALID'' using errcode = ''22023'';\n  end if;\n\n  insert into public.users (\n    id, role, status, full_name, nickname, email,\n    grade_level, student_status, birth_date,\n    terms_agreed_at, privacy_agreed_at, marketing_agreed, profile_completed_at, updated_at\n  ) values (\n    p_user_id, p_role, ''active'',\n    nullif(btrim(p_full_name), ''''),\n    nullif(btrim(p_nickname), ''''),\n    p_email,\n    nullif(btrim(p_grade_level), ''''),\n    nullif(btrim(p_student_status), ''''),\n    p_birth_date,\n    case when coalesce(p_terms_agreed, false) then now() else null end,\n    case when coalesce(p_privacy_agreed, false) then now() else null end,\n    coalesce(p_marketing_agreed, false),\n    p_profile_completed_at,\n    now()\n  )\n  on conflict (id) do update set\n    role = coalesce(excluded.role, public.users.role),\n    full_name = coalesce(excluded.full_name, public.users.full_name),\n    nickname = coalesce(excluded.nickname, public.users.nickname),\n    email = coalesce(excluded.email, public.users.email),\n    grade_level = coalesce(excluded.grade_level, public.users.grade_level),\n    student_status = coalesce(excluded.student_status, public.users.student_status),\n    birth_date = coalesce(excluded.birth_date, public.users.birth_date),\n    terms_agreed_at = coalesce(excluded.terms_agreed_at, public.users.terms_agreed_at),\n    privacy_agreed_at = coalesce(excluded.privacy_agreed_at, public.users.privacy_agreed_at),\n    marketing_agreed = excluded.marketing_agreed,\n    profile_completed_at = coalesce(excluded.profile_completed_at, public.users.profile_completed_at),\n    updated_at = now();\n\n  if p_role = ''mentor'' then\n    insert into public.mentor_profiles (\n      user_id, university_name, department_name, teaching_subjects, high_school_name, intro_line,\n      verification_status, student_id_image_url, updated_at\n    ) values (\n      p_user_id,\n      coalesce(nullif(btrim(p_university_name), ''''), ''(미입력)''),\n      coalesce(nullif(btrim(p_department_name), ''''), ''(미입력)''),\n      coalesce(p_teaching_subjects, ''{}''),\n      coalesce(nullif(btrim(p_high_school_name), ''''), ''(미입력)''),\n      nullif(btrim(p_intro_line), ''''),\n      ''pending'',\n      null,\n      now()\n    )\n    on conflict (user_id) do update set\n      university_name = excluded.university_name,\n      department_name = excluded.department_name,\n      teaching_subjects = excluded.teaching_subjects,\n      high_school_name = excluded.high_school_name,\n      intro_line = coalesce(excluded.intro_line, public.mentor_profiles.intro_line),\n      updated_at = now();\n\n    insert into public.verification_logs (user_id, log_type, status, memo) values\n      (p_user_id, ''mentor_verification'', ''pending'', ''sign-up'');\n  end if;\n\n  -- 동의 원장(후속 a): 이메일 가입 메타 또는 complete_profile 이 조립한 메타 → B-3a 정본(187 과 같은 행 · 멱등)\n  if p_consent_meta is not null then\n    perform core_private.user_consent_signup_impl(p_user_id, p_consent_meta, ''signup'');\n  end if;\nend\n$fn$", "comment on function core_private.user_signup_provision_impl(uuid, text, text, text, text, text, text, date, boolean, boolean, boolean, text, text, text[], text, text, timestamptz, jsonb) is\n  ''206(DB-5 B-3): 가입 프로비저닝 정본 — users upsert(+ 멘토면 mentor_profiles pending + verification_logs) + 동의 원장(B-3a · p_consent_meta). handle_new_auth_user(이메일·소셜) 와 api_app_v1.complete_profile 이 공유. 외부 EXECUTE 0.''", "revoke all on function core_private.user_signup_provision_impl(uuid, text, text, text, text, text, text, date, boolean, boolean, boolean, text, text, text[], text, text, timestamptz, jsonb) from public, anon, authenticated", "-- -----------------------------------------------------------------------------\n-- B-4. 가입 트리거 — app_role 유무로 분기 (헤더·속성은 122 와 동일: SECURITY DEFINER · search_path public)\n-- -----------------------------------------------------------------------------\ncreate or replace function public.handle_new_auth_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  m jsonb;\n  r text;\n  subj text[];\n  subj_str text;\n  bdate date;\n  v_name text;\nbegin\n  m := coalesce(NEW.raw_user_meta_data, ''{}''::jsonb);\n\n  -- ── 소셜(OAuth) 가입: app_role 키 없음 → 역할 미정 · 완성 전. 프로필 행(mentor_profiles)은 만들지 않는다(정정 B) ──\n  if not (m ? ''app_role'') then\n    v_name := coalesce(\n      nullif(trim(m->>''full_name''), ''''),\n      nullif(trim(m->>''name''), ''''),\n      nullif(trim(m->>''preferred_username''), ''''),\n      nullif(trim(m->>''nickname''), ''''),\n      nullif(trim(m->>''user_name''), '''')\n    );\n    perform core_private.user_signup_provision_impl(\n      NEW.id, null, nullif(NEW.email, ''''), v_name, v_name,\n      null, null, null,\n      false, false, false,\n      null, null, null, null, null,\n      null,\n      null);   -- 소셜: 가입 시점 동의 없음 → 원장 기록 없음(complete_profile 이 남긴다)\n    return NEW;\n  end if;\n\n  -- ── 이메일 가입(app_role 있음): 122 정규화 그대로 ──\n  r := lower(trim(m->>''app_role''));\n  if r is null or r = '''' then\n    r := ''student'';\n  end if;\n  -- ★ XV-01: ''admin'' 제거 — 가입 메타로는 student/mentor 만 가능. 그 외 전부 student.\n  if r not in (''student'', ''mentor'') then\n    r := ''student'';\n  end if;\n\n  subj_str := nullif(trim(m->>''teaching_subjects_csv''), '''');\n  if subj_str is not null then\n    subj := array(\n      select trim(both '' '' from x)\n      from unnest(string_to_array(subj_str, '','')) as x\n      where length(trim(both '' '' from x)) > 0\n    );\n  else\n    subj := ''{}'';\n  end if;\n\n  begin\n    bdate := (m->>''birth_date'')::date;\n  exception when others then\n    bdate := null;\n  end;\n\n  perform core_private.user_signup_provision_impl(\n    NEW.id, r, coalesce(NEW.email, ''''),\n    m->>''full_name'', m->>''nickname'',\n    m->>''grade_level'', m->>''student_status'', bdate,\n    (m->>''terms_agreed'') = ''true'', (m->>''privacy_agreed'') = ''true'', (m->>''marketing_agreed'') = ''true'',\n    m->>''university_name'', m->>''department_name'', coalesce(subj, ''{}''), m->>''high_school_name'', m->>''intro_line'',\n    now(),\n    m);   -- 이메일: 가입 메타 그대로 → 동의 원장(187 과 같은 행 · zz 트리거는 멱등 no-op)\n\n  return NEW;\nend;\n$$", "comment on function public.handle_new_auth_user() is\n  ''206(DB-5 B-4): auth.users INSERT → raw_user_meta_data ? ''''app_role'''' 이면 이메일 가입(122 정규화 · profile_completed_at now() · 동의 원장), 아니면 소셜 가입(role NULL · profile_completed_at NULL · provider 이름 · 프로필 행 없음). 본문은 core_private.user_signup_provision_impl 공유.''", "-- B-4a. 187 동의 트리거 함수 — 본문을 B-3a 정본 위임으로 교체(헤더·속성 187 동일 · 트리거 부착 그대로 · 이메일 가입은 B-4 가 먼저 쓰므로 멱등 no-op)\ncreate or replace function public.handle_new_auth_user_consent_records()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to ''public''\nas $function$\nbegin\n  -- 206(DB-5 후속 a): 원장 로직은 core_private.user_consent_signup_impl 한 벌 — on_auth_user_created(handle_new_auth_user) 가 같은 멱등 키로 먼저 기록한다.\n  perform core_private.user_consent_signup_impl(new.id, coalesce(new.raw_user_meta_data, ''{}''::jsonb), ''signup'');\n  return new;\nend;\n$function$", "comment on function public.handle_new_auth_user_consent_records() is\n  ''Signup consent ledger trigger (087/187) — 206(DB-5 후속 a) 부터 core_private.user_consent_signup_impl 위임(멱등). 원문 로직은 그 impl 로 이동.''", "-- -----------------------------------------------------------------------------\n-- B-5. 119 role 가드 — 완성 전 행의 최초 역할 부여 전이만 추가 허용(그 외 원문 그대로)\n-- -----------------------------------------------------------------------------\ncreate or replace function public.enforce_users_role_guard()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_jwt_role text;\nbegin\n  -- 트리거를 WHEN 절 없이 재생성해도 안전하도록 함수 안에서도 재확인\n  if new.role is distinct from old.role then\n    -- 206(DB-5 B): 소셜 가입 완성 — 역할이 없는(완성 전) 행에 student/mentor 를 처음 채우는 전이는 허용.\n    --   (authenticated 는 users UPDATE 권한이 없고 users_protected_columns_guard 가 클라이언트 역할의 role 변경을 거부하므로\n    --    이 전이는 SECURITY DEFINER 경로 api_app_v1.complete_profile 로만 도달한다.)\n    if old.role is null and old.profile_completed_at is null and new.role in (''student'', ''mentor'') then\n      return new;\n    end if;\n\n    v_jwt_role := auth.jwt() ->> ''role'';\n\n    if v_jwt_role = ''service_role'' then\n      return new; -- 1) 서버(service key) 경유\n    end if;\n\n    if v_jwt_role is null then\n      return new; -- 2) JWT 없는 직접 DB 세션(SQL Editor·마이그레이션)\n    end if;\n\n    if exists (\n      select 1\n        from public.users u\n       where u.id = (select auth.uid())\n         and u.role = ''admin''\n    ) then\n      return new; -- 3) 관리자\n    end if;\n\n    raise exception ''ROLE_CHANGE_FORBIDDEN''\n      using errcode = ''42501'', -- insufficient_privilege\n            detail  = format(''users.id=%s role %L -> %L'', old.id, old.role, new.role),\n            hint    = ''role 변경은 service_role 또는 admin 만 가능합니다.'';\n  end if;\n\n  return new;\nend;\n$$", "-- -----------------------------------------------------------------------------\n-- B-7. core_private.user_profile_update_self_impl — role NULL 명시 거부(한 줄 보강 · 그 외 20260803162257 D 원문 그대로 · 시그니처·ACL 불변)\n--      앱 api_app_v1.user_profile_update_self(v1)/_v2 · 웹 api_web_v1.user_profile_update_self 가 위임하는 정본. 완성 전 사용자의 닉네임·학년 변경 통과(실측)를 닫는다.\n-- -----------------------------------------------------------------------------\nCREATE OR REPLACE FUNCTION core_private.user_profile_update_self_impl(p_user_id uuid, p_nickname text, p_grade_level text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_role text;\n  v_status text;\n  v_susp timestamptz;\n  v_norm text;\n  v_nick text;\n  v_grade text;\n  v_set_grade boolean := false;\n  v_updated_at timestamptz;\n  v_out_nick text;\n  v_out_grade text;\nbegin\n  if p_user_id is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  select u.role, u.status, u.suspended_until\n    into v_role, v_status, v_susp\n    from public.users u where u.id = p_user_id\n    for update;\n  if not found then\n    raise exception ''ACCOUNT_NOT_ACTIVE'';\n  end if;\n\n  -- 206(DB-5 B): role NULL(소셜 가입 · 완성 전)은 `not in` 을 NULL 로 통과하므로 명시적으로 거부한다(그 외 원문 그대로).\n  if v_role is null or v_role not in (''student'',''mentor'') then\n    raise exception ''ROLE_NOT_ALLOWED'';\n  end if;\n\n  -- 계정 상태 게이트 (Build 13 UGC 게이트와 동일 판정: banned 차단 · 유효 suspended\n  -- 차단 · 만료 suspended 허용 · unknown/deleted/빈 status 차단)\n  v_norm := lower(btrim(coalesce(v_status, '''')));\n  if v_norm = ''banned'' then\n    raise exception ''ACCOUNT_BANNED'';\n  end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then\n    raise exception ''ACCOUNT_SUSPENDED'';\n  end if;\n  if v_norm not in (''active'',''suspended'') then\n    raise exception ''ACCOUNT_NOT_ACTIVE'';\n  end if;\n  if public.account_deletion_write_blocked(p_user_id) then\n    raise exception ''ACCOUNT_DELETION_IN_PROGRESS'';\n  end if;\n\n  -- nickname: null=유지 · trim 후 빈 값=오류 · 최대 30자\n  if p_nickname is not null then\n    v_nick := btrim(p_nickname);\n    if v_nick = '''' then\n      raise exception ''NICKNAME_REQUIRED'' using errcode = ''22023'';\n    end if;\n    if char_length(v_nick) > 30 then\n      raise exception ''NICKNAME_TOO_LONG'' using errcode = ''22023'';\n    end if;\n  end if;\n\n  -- grade_level: null=유지 · ''''=값 제거 · 학생만 · 자유 텍스트 최대 20자\n  if p_grade_level is not null then\n    if v_role <> ''student'' then\n      raise exception ''GRADE_LEVEL_NOT_ALLOWED'' using errcode = ''22023'';\n    end if;\n    v_grade := nullif(btrim(p_grade_level), '''');\n    if v_grade is not null and char_length(v_grade) > 20 then\n      raise exception ''GRADE_LEVEL_TOO_LONG'' using errcode = ''22023'';\n    end if;\n    v_set_grade := true;\n  end if;\n\n  update public.users u\n     set nickname    = coalesce(v_nick, u.nickname),\n         grade_level = case when v_set_grade then v_grade else u.grade_level end,\n         updated_at  = now()\n   where u.id = p_user_id\n   returning u.updated_at, u.nickname, u.grade_level\n     into v_updated_at, v_out_nick, v_out_grade;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''contract_version'', 1,\n    ''nickname'', v_out_nick,\n    ''grade_level'', v_out_grade,\n    ''updated_at'', v_updated_at\n  );\nend\n$function$", "-- -----------------------------------------------------------------------------\n-- C-1. 프로필 완성 RPC (api_app_v1 · authenticated 만)\n-- -----------------------------------------------------------------------------\ncreate function api_app_v1.complete_profile(\n  p_role             text,\n  p_display_name     text,\n  p_birthdate        date,\n  p_terms_agreed     boolean,\n  p_marketing_agreed boolean default false,\n  p_grade_level      text default null,\n  p_university_name  text default null,\n  p_department_name  text default null\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_role text := lower(btrim(coalesce(p_role, '''')));\n  v_name text := btrim(coalesce(p_display_name, ''''));\n  v_grade text := nullif(btrim(coalesce(p_grade_level, '''')), '''');\n  v_univ text := nullif(btrim(coalesce(p_university_name, '''')), '''');\n  v_dept text := nullif(btrim(coalesce(p_department_name, '''')), '''');\n  v_today date := (now() at time zone ''Asia/Seoul'')::date;\n  v_row public.users%rowtype;\n  v_norm text;\n  v_minor boolean;\n  v_next text;\n  v_completed_at timestamptz;\nbegin\n  if v_uid is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  end if;\n\n  select * into v_row from public.users u where u.id = v_uid for update;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''USER_NOT_FOUND'');\n  end if;\n  if v_row.profile_completed_at is not null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ALREADY_COMPLETED'', ''role'', v_row.role, ''profile_completed_at'', v_row.profile_completed_at);\n  end if;\n\n  -- 계정 게이트(core_private.user_profile_update_self_impl 과 같은 판정)\n  v_norm := lower(btrim(coalesce(v_row.status, '''')));\n  if v_norm = ''banned'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_BANNED'');\n  end if;\n  if v_norm = ''suspended'' and (v_row.suspended_until is null or v_row.suspended_until > now()) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_SUSPENDED'');\n  end if;\n  if v_norm not in (''active'', ''suspended'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_NOT_ACTIVE'');\n  end if;\n  if public.account_deletion_write_blocked(v_uid) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  end if;\n\n  -- 입력 검증\n  if v_role not in (''student'', ''mentor'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROLE_INVALID'');\n  end if;\n  if v_name = '''' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''DISPLAY_NAME_REQUIRED'');\n  end if;\n  if char_length(v_name) > 30 then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''DISPLAY_NAME_TOO_LONG'', ''max_length'', 30);\n  end if;\n  if p_birthdate is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''BIRTHDATE_REQUIRED'');\n  end if;\n  if p_birthdate > v_today or p_birthdate < date ''1900-01-01'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''BIRTHDATE_INVALID'');\n  end if;\n  if not coalesce(p_terms_agreed, false) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''TERMS_REQUIRED'');\n  end if;\n  if v_role = ''student'' then\n    if v_grade is null then\n      return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''GRADE_REQUIRED'');\n    end if;\n    if char_length(v_grade) > 20 then\n      return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''GRADE_LEVEL_TOO_LONG'', ''max_length'', 20);\n    end if;\n  else\n    if v_univ is null then\n      return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''UNIVERSITY_REQUIRED'');\n    end if;\n  end if;\n\n  -- 만 14세 판정(187 과 같은 식 · KST 달력)\n  v_minor := v_today < (p_birthdate + interval ''14 years'')::date;\n  v_completed_at := now();\n\n  -- 이메일 가입 트리거와 같은 결과(공유 impl): 역할·표시명(nickname)·생년월일·학년·약관(users 컬럼)·완성 시각 · 멘토면 프로필 행 + 로그\n  perform core_private.user_signup_provision_impl(\n    v_uid, v_role, v_row.email,\n    null, v_name,\n    case when v_role = ''student'' then v_grade else null end, null, p_birthdate,\n    true, true, coalesce(p_marketing_agreed, false),\n    case when v_role = ''mentor'' then v_univ else null end,\n    case when v_role = ''mentor'' then v_dept else null end,\n    null, null, null,\n    v_completed_at,\n    jsonb_build_object(                      -- 동의 원장 입력(187 메타 키 · 이메일 가입과 같은 행이 남는다)\n      ''app_role'', v_role,\n      ''birth_date'', p_birthdate::text,\n      ''is_minor'', v_minor::text,\n      ''terms_agreed'', ''true'',\n      ''privacy_agreed'', ''true'',\n      ''marketing_agreed'', case when coalesce(p_marketing_agreed, false) then ''true'' else ''false'' end\n    ));\n\n  v_next := case when v_minor then ''guardian_consent''\n                 when v_role = ''mentor'' then ''identity_verification''\n                 else ''home'' end;\n\n  return jsonb_build_object(\n    ''ok'', true, ''contract_version'', 1,\n    ''role'', v_role, ''is_minor'', v_minor, ''next'', v_next,\n    ''nickname'', v_name, ''profile_completed_at'', v_completed_at\n  );\nend\n$fn$", "comment on function api_app_v1.complete_profile(text, text, date, boolean, boolean, text, text, text) is\n  ''206(DB-5 C-1): 소셜 가입 후 프로필 완성 — profile_completed_at NULL 인 본인 행만(ALREADY_COMPLETED). 이메일 가입 트리거와 같은 결과(core_private.user_signup_provision_impl 공유 · 동의 원장 terms/privacy/marketing 행 포함). 만 14세 미만 → next guardian_consent · 멘토 → identity_verification · 그 외 home. TERMS_REQUIRED · GRADE_REQUIRED · UNIVERSITY_REQUIRED. authenticated 만.''", "revoke all on function api_app_v1.complete_profile(text, text, date, boolean, boolean, text, text, text) from public, anon", "grant execute on function api_app_v1.complete_profile(text, text, date, boolean, boolean, text, text, text) to authenticated", "-- -----------------------------------------------------------------------------\n-- B-6. auth.uid() 만 보는(또는 OR is_admin() 만 덧붙은) 쓰기 정책 18종 — 원문 + AND public.user_profile_completed() (이름·명령·역할·permissive 불변)\n--      원문은 pack 118본 pg_policies 에서 그대로 옮겼다(rollback 이 같은 원문을 복원한다).\n-- -----------------------------------------------------------------------------\n-- admin_action_logs.관리자만 로그 기록 (INSERT · public)\ndrop policy if exists \"관리자만 로그 기록\" on public.admin_action_logs", "create policy \"관리자만 로그 기록\" on public.admin_action_logs\n  as permissive for insert to public\n  with check ((auth.uid() = admin_id) and public.user_profile_completed())", "-- ai_drafts.ai_drafts_insert_own (INSERT · authenticated)\ndrop policy if exists ai_drafts_insert_own on public.ai_drafts", "create policy ai_drafts_insert_own on public.ai_drafts\n  as permissive for insert to authenticated\n  with check ((mentor_id = ( SELECT auth.uid() AS uid)) and public.user_profile_completed())", "-- content_reports.content_reports_insert_reporter (INSERT · authenticated)\ndrop policy if exists content_reports_insert_reporter on public.content_reports", "create policy content_reports_insert_reporter on public.content_reports\n  as permissive for insert to authenticated\n  with check (((reporter_id = ( SELECT auth.uid() AS uid)) AND (status = ''pending''::text) AND (admin_note IS NULL) AND (resolved_by IS NULL) AND (resolved_at IS NULL) AND (target_type = ANY (ARRAY[''community_post''::text, ''shortform_post''::text, ''community_comment''::text, ''board_comment''::text, ''user''::text])) AND\nCASE\n    WHEN (target_type = ''user''::text) THEN report_target_user_valid(target_id)\n    ELSE rls_private.report_target_content_valid(target_type, target_id)\nEND) and public.user_profile_completed())", "-- custom_order_deliverables.멘토만 납품 업로드 (INSERT · public)\ndrop policy if exists \"멘토만 납품 업로드\" on public.custom_order_deliverables", "create policy \"멘토만 납품 업로드\" on public.custom_order_deliverables\n  as permissive for insert to public\n  with check ((auth.uid() = mentor_id) and public.user_profile_completed())", "-- custom_order_messages.당사자만 메시지 전송 (INSERT · public)\ndrop policy if exists \"당사자만 메시지 전송\" on public.custom_order_messages", "create policy \"당사자만 메시지 전송\" on public.custom_order_messages\n  as permissive for insert to public\n  with check ((auth.uid() = author_id) and public.user_profile_completed())", "-- custom_request_applications.cra_insert (INSERT · authenticated)\ndrop policy if exists cra_insert on public.custom_request_applications", "create policy cra_insert on public.custom_request_applications\n  as permissive for insert to authenticated\n  with check (((mentor_id = ( SELECT auth.uid() AS uid)) OR (( SELECT is_admin() AS is_admin) = true)) and public.user_profile_completed())", "-- custom_request_applications.멘토만 지원 (INSERT · public)\ndrop policy if exists \"멘토만 지원\" on public.custom_request_applications", "create policy \"멘토만 지원\" on public.custom_request_applications\n  as permissive for insert to public\n  with check ((auth.uid() = mentor_id) and public.user_profile_completed())", "-- custom_request_orders.cro_insert (INSERT · authenticated)\ndrop policy if exists cro_insert on public.custom_request_orders", "create policy cro_insert on public.custom_request_orders\n  as permissive for insert to authenticated\n  with check (((student_id = ( SELECT auth.uid() AS uid)) OR (buyer_id = ( SELECT auth.uid() AS uid)) OR (client_id = ( SELECT auth.uid() AS uid)) OR (user_id = ( SELECT auth.uid() AS uid)) OR (author_id = ( SELECT auth.uid() AS uid)) OR (requester_id = ( SELECT auth.uid() AS uid)) OR (( SELECT is_admin() AS is_admin) = true)) and public.user_profile_completed())", "-- custom_request_posts.crp_insert (INSERT · authenticated)\ndrop policy if exists crp_insert on public.custom_request_posts", "create policy crp_insert on public.custom_request_posts\n  as permissive for insert to authenticated\n  with check (((author_id = ( SELECT auth.uid() AS uid)) OR (user_id = ( SELECT auth.uid() AS uid)) OR (student_id = ( SELECT auth.uid() AS uid)) OR (requester_id = ( SELECT auth.uid() AS uid)) OR (client_id = ( SELECT auth.uid() AS uid)) OR (( SELECT is_admin() AS is_admin) = true)) and public.user_profile_completed())", "-- custom_request_posts.학생만 의뢰 등록 (INSERT · public)\ndrop policy if exists \"학생만 의뢰 등록\" on public.custom_request_posts", "create policy \"학생만 의뢰 등록\" on public.custom_request_posts\n  as permissive for insert to public\n  with check ((auth.uid() = author_id) and public.user_profile_completed())", "-- device_tokens.device_tokens_modify_own (ALL · authenticated)\ndrop policy if exists device_tokens_modify_own on public.device_tokens", "create policy device_tokens_modify_own on public.device_tokens\n  as permissive for all to authenticated\n  using ((user_id = ( SELECT auth.uid() AS uid)) and public.user_profile_completed())\n  with check ((user_id = ( SELECT auth.uid() AS uid)) and public.user_profile_completed())", "-- favorites.favorites_insert_own (INSERT · public)\ndrop policy if exists favorites_insert_own on public.favorites", "create policy favorites_insert_own on public.favorites\n  as permissive for insert to public\n  with check ((auth.uid() = user_id) and public.user_profile_completed())", "-- free_question_usage.fqu_insert_own (INSERT · authenticated)\ndrop policy if exists fqu_insert_own on public.free_question_usage", "create policy fqu_insert_own on public.free_question_usage\n  as permissive for insert to authenticated\n  with check ((student_id = ( SELECT auth.uid() AS uid)) and public.user_profile_completed())", "-- notification_settings.notif_settings_modify_own (ALL · authenticated)\ndrop policy if exists notif_settings_modify_own on public.notification_settings", "create policy notif_settings_modify_own on public.notification_settings\n  as permissive for all to authenticated\n  using ((user_id = ( SELECT auth.uid() AS uid)) and public.user_profile_completed())\n  with check ((user_id = ( SELECT auth.uid() AS uid)) and public.user_profile_completed())", "-- payments.payments_insert_intent (INSERT · authenticated)\ndrop policy if exists payments_insert_intent on public.payments", "create policy payments_insert_intent on public.payments\n  as permissive for insert to authenticated\n  with check (((( SELECT auth.uid() AS uid) = user_id) AND (status = ANY (ARRAY[''pending''::text, ''processing''::text]))) and public.user_profile_completed())", "-- user_blocks.ub_insert_own (INSERT · authenticated)\ndrop policy if exists ub_insert_own on public.user_blocks", "create policy ub_insert_own on public.user_blocks\n  as permissive for insert to authenticated\n  with check ((blocker_id = ( SELECT auth.uid() AS uid)) and public.user_profile_completed())", "-- verification_logs.ver_logs_insert_own (INSERT · authenticated)\ndrop policy if exists ver_logs_insert_own on public.verification_logs", "create policy ver_logs_insert_own on public.verification_logs\n  as permissive for insert to authenticated\n  with check ((user_id = ( SELECT auth.uid() AS uid)) and public.user_profile_completed())", "-- withdrawals.withdrawals_insert_self_requested (INSERT · authenticated)\ndrop policy if exists withdrawals_insert_self_requested on public.withdrawals", "create policy withdrawals_insert_self_requested on public.withdrawals\n  as permissive for insert to authenticated\n  with check (((( SELECT auth.uid() AS uid) = mentor_id) AND (status = ''requested''::text)) and public.user_profile_completed())", "-- -----------------------------------------------------------------------------\n-- 자가 검증\n-- -----------------------------------------------------------------------------\ndo $$\ndeclare v_oid oid; v_n int; r record;\nbegin\n  -- 컬럼·백필·제약\n  if not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''users'' and column_name = ''profile_completed_at'') then\n    raise exception ''206_SELFCHECK: profile_completed_at 부재'';\n  end if;\n  if exists (select 1 from public.users where profile_completed_at is null) then\n    raise exception ''206_SELFCHECK: 백필 누락 행 존재'';\n  end if;\n  if exists (select 1 from public.users where profile_completed_at is distinct from created_at) then\n    raise exception ''206_SELFCHECK: 백필 값 불일치(created_at)'';\n  end if;\n  if (select is_nullable from information_schema.columns where table_schema = ''public'' and table_name = ''users'' and column_name = ''role'') <> ''YES'' then\n    raise exception ''206_SELFCHECK: role NOT NULL 완화 실패'';\n  end if;\n  if not exists (select 1 from pg_constraint where conrelid = ''public.users''::regclass and conname = ''users_role_required_when_completed'')\n     or not exists (select 1 from pg_constraint where conrelid = ''public.users''::regclass and conname = ''users_role_check'') then\n    raise exception ''206_SELFCHECK: CHECK 제약 불일치'';\n  end if;\n  if (select tgenabled from pg_trigger where tgrelid = ''public.users''::regclass and tgname = ''trg_users_set_updated'') = ''D'' then\n    raise exception ''206_SELFCHECK: trg_users_set_updated 가 꺼진 채 남았다'';\n  end if;\n  -- 트리거 본문·부착\n  if md5(pg_get_functiondef(''public.handle_new_auth_user()''::regprocedure)) = ''297616fe4e28f0dbda3b24244763a917''\n     or (select prosrc from pg_proc where oid = ''public.handle_new_auth_user()''::regprocedure) not like ''%m ? ''''app_role''''%''\n     or (select prosrc from pg_proc where oid = ''public.handle_new_auth_user()''::regprocedure) not like ''%core_private.user_signup_provision_impl(%'' then\n    raise exception ''206_SELFCHECK: handle_new_auth_user 교체 실패'';\n  end if;\n  if not exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace\n                  where n.nspname = ''auth'' and c.relname = ''users'' and t.tgname = ''on_auth_user_created'' and t.tgfoid = ''public.handle_new_auth_user''::regproc and t.tgenabled <> ''D'') then\n    raise exception ''206_SELFCHECK: on_auth_user_created 부착 상태 변경됨'';\n  end if;\n  if (select prosrc from pg_proc where oid = ''public.enforce_users_role_guard()''::regprocedure) not like ''%old.role is null and old.profile_completed_at is null%''\n     or (select prosrc from pg_proc where oid = ''public.enforce_users_role_guard()''::regprocedure) not like ''%ROLE_CHANGE_FORBIDDEN%'' then\n    raise exception ''206_SELFCHECK: enforce_users_role_guard 교체 실패'';\n  end if;\n  -- impl(NULL 거부 보강) · 공용 impl · helper · RPC ACL\n  if md5(pg_get_functiondef(''core_private.user_profile_update_self_impl(uuid,text,text)''::regprocedure)) = ''a0cb1b7f37b8195cc9ca370bfb5e90e7''\n     or (select prosrc from pg_proc where oid = ''core_private.user_profile_update_self_impl(uuid,text,text)''::regprocedure) not like ''%v_role is null or v_role not in%'' then\n    raise exception ''206_SELFCHECK: user_profile_update_self_impl 보강 실패'';\n  end if;\n  if has_function_privilege(''anon'', ''core_private.user_profile_update_self_impl(uuid,text,text)''::regprocedure, ''EXECUTE'')\n     or has_function_privilege(''authenticated'', ''core_private.user_profile_update_self_impl(uuid,text,text)''::regprocedure, ''EXECUTE'') then\n    raise exception ''206_SELFCHECK: user_profile_update_self_impl ACL 변경됨'';\n  end if;\n  select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''core_private'' and p.proname = ''user_signup_provision_impl'';\n  if v_oid is null or has_function_privilege(''anon'', v_oid, ''EXECUTE'') or has_function_privilege(''authenticated'', v_oid, ''EXECUTE'') or has_function_privilege(''service_role'', v_oid, ''EXECUTE'') then\n    raise exception ''206_SELFCHECK: impl 부재 또는 외부 EXECUTE 잔존'';\n  end if;\n  select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''public'' and p.proname = ''user_profile_completed'' and p.prosecdef and p.provolatile = ''s'';\n  if v_oid is null or not has_function_privilege(''anon'', v_oid, ''EXECUTE'') or not has_function_privilege(''authenticated'', v_oid, ''EXECUTE'') then\n    raise exception ''206_SELFCHECK: user_profile_completed 부재 또는 ACL 불일치'';\n  end if;\n  select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''api_app_v1'' and p.proname = ''complete_profile''\n     and pg_get_function_identity_arguments(p.oid) = ''p_role text, p_display_name text, p_birthdate date, p_terms_agreed boolean, p_marketing_agreed boolean, p_grade_level text, p_university_name text, p_department_name text''\n     and p.prosecdef and coalesce(p.proconfig::text, '''') like ''%search_path=%'';\n  if v_oid is null or has_function_privilege(''anon'', v_oid, ''EXECUTE'') or not has_function_privilege(''authenticated'', v_oid, ''EXECUTE'') or has_function_privilege(''service_role'', v_oid, ''EXECUTE'') then\n    raise exception ''206_SELFCHECK: complete_profile identity/ACL 불일치(authenticated 만)'';\n  end if;\n  if (select prosrc from pg_proc where oid = v_oid) not like ''%core_private.user_signup_provision_impl(%'' or (select prosrc from pg_proc where oid = v_oid) like ''%user_consent_records%''\n     or (select prosrc from pg_proc where oid = v_oid) not like ''%''''terms_agreed'''', ''''true''''%'' then\n    raise exception ''206_SELFCHECK: complete_profile 이 impl 을 공유하지 않거나 원장을 직접 쓰거나 동의 메타를 넘기지 않는다'';\n  end if;\n  -- 동의 원장 정본(B-3a) · 프로비저닝 impl 이 그것을 호출 · 187 트리거 함수는 위임으로 교체됐다\n  select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''core_private'' and p.proname = ''user_consent_signup_impl'';\n  if v_oid is null or has_function_privilege(''anon'', v_oid, ''EXECUTE'') or has_function_privilege(''authenticated'', v_oid, ''EXECUTE'') or has_function_privilege(''service_role'', v_oid, ''EXECUTE'')\n     or (select prosrc from pg_proc where oid = v_oid) not like ''%''''signup:'''' || p_user_id::text || '''':terms:'''' || v_version%'' then\n    raise exception ''206_SELFCHECK: user_consent_signup_impl 부재/외부 EXECUTE 잔존/멱등 키 형식 불일치'';\n  end if;\n  if (select prosrc from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''core_private'' and p.proname = ''user_signup_provision_impl'') not like ''%core_private.user_consent_signup_impl(%'' then\n    raise exception ''206_SELFCHECK: user_signup_provision_impl 이 동의 원장 정본을 호출하지 않는다'';\n  end if;\n  if md5(pg_get_functiondef(''public.handle_new_auth_user_consent_records()''::regprocedure)) = ''abc7c96e8d5707a6d8324a75d4b14815''\n     or (select prosrc from pg_proc where oid = ''public.handle_new_auth_user_consent_records()''::regprocedure) not like ''%core_private.user_consent_signup_impl(%''\n     or not exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace\n                     where n.nspname = ''auth'' and c.relname = ''users'' and t.tgname = ''zz_on_auth_user_created_consent_records'' and t.tgfoid = ''public.handle_new_auth_user_consent_records''::regproc and t.tgenabled <> ''D'') then\n    raise exception ''206_SELFCHECK: 187 동의 트리거 위임 교체 실패 또는 부착 상태 변경'';\n  end if;\n  -- 정책 18종: 이름·명령·역할 유지 + 완성 조건\n  select count(*) into v_n from pg_policies pp\n   where pp.schemaname = ''public''\n     and (pp.tablename, pp.policyname) in ((''admin_action_logs'',''관리자만 로그 기록''),(''ai_drafts'',''ai_drafts_insert_own''),(''content_reports'',''content_reports_insert_reporter''),(''custom_order_deliverables'',''멘토만 납품 업로드''),(''custom_order_messages'',''당사자만 메시지 전송''),(''custom_request_applications'',''cra_insert''),(''custom_request_applications'',''멘토만 지원''),(''custom_request_orders'',''cro_insert''),(''custom_request_posts'',''crp_insert''),(''custom_request_posts'',''학생만 의뢰 등록''),(''device_tokens'',''device_tokens_modify_own''),(''favorites'',''favorites_insert_own''),(''free_question_usage'',''fqu_insert_own''),(''notification_settings'',''notif_settings_modify_own''),(''payments'',''payments_insert_intent''),(''user_blocks'',''ub_insert_own''),(''verification_logs'',''ver_logs_insert_own''),(''withdrawals'',''withdrawals_insert_self_requested''))\n     and coalesce(pp.with_check, '''') || coalesce(pp.qual, '''') like ''%user_profile_completed()%''\n     and (pp.cmd <> ''ALL'' or (pp.qual like ''%user_profile_completed()%'' and pp.with_check like ''%user_profile_completed()%''));\n  if v_n <> 18 then\n    raise exception ''206_SELFCHECK: 완성 조건이 붙은 정책 % (18 기대)'', v_n;\n  end if;\n  if (select count(*) from pg_policies where schemaname = ''public'') <> (select policies from db5_206_pre) then\n    raise exception ''206_SELFCHECK: public 정책 수 변동(% ≠ 적용 전 %)'', (select count(*) from pg_policies where schemaname = ''public''), (select policies from db5_206_pre);\n  end if;\n  -- users_select_own 은 그대로(완성 전 사용자의 자기 행 읽기)\n  if not exists (select 1 from pg_policies where schemaname = ''public'' and tablename = ''users'' and policyname = ''users_select_own'' and cmd = ''SELECT'') then\n    raise exception ''206_SELFCHECK: users_select_own 부재'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "api_app_v1_individual_question_create_v3", "version": "20260906100300", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 207_api_app_v1_individual_question_create_v3.sql  (2026-09-06 · DB-5 묶음 D — 개별질문 v3 래퍼: 단원·개념 + 자격 조건 · 후속 b: 정지 계정 등록 차단)\n--\n-- 왜: 앱 A-4c 전수 대조가 찾은 유일한 서버 선행 항목. 공개형 질문의 단원·개념(`topic`)과 자격 조건(학교군·전공계열)을 웹은\n--   `create_individual_question_with_hold_v2`(service_role 전용 코어)에 직접 넣지만, 앱이 부르는 204 v2 래퍼는 `p_subject` 까지만 받아\n--   코어에 NULL 을 고정 전달한다. `individual_questions` 에 본인 UPDATE 정책도 없어 등록 뒤 보정도 못 한다.\n--   v1(092 public)은 그대로 둔다. `_v3` 는 **v2 본문을 그대로 복제**한 뒤 인자 3개만 더한다.\n--\n-- 후속 b(2026-09-06 · DB-5 보고서 §5-4): v2(204)·코어 v2 는 계정 상태를 보지 않아 **정지(suspended)·차단(banned)·탈퇴 진행 중 학생도 개별질문을 등록**할 수\n--   있었다(스크래치 실측 · 웹은 서버 액션 `assertAccountActive` 가 막는다). 계정 상태 검사를 함수 하나(D-0)로 빼고 **v2 와 v3 둘 다** 호출한다.\n--   \"v2 변경 금지\"는 호환성 규칙이므로 v2 의 시그니처·반환·오류 규약은 그대로 두고 검사 한 곳만 더한다(create or replace · 원문 md5 게이트 · rollback 원문 복원).\n--   막는 상태 집합 = 앱 `entry_guard.dart`/`AccountStatusReader`(auth_service.dart:97-121 · account_status.dart) · 웹 `lib/auth/accountStatus.ts`(assertAccountActive)\n--   가 막는 것과 같다: banned · suspended(suspended_until NULL 또는 미래) · deleted · 탈퇴 진행 중(`account_deletion_write_blocked` = locked~auth_soft_deleted) ·\n--   그 외 알 수 없는 status · users 행 부재(확인 불가 = 거부). 탈퇴 **대기**(pending · 취소 가능 창)는 앱·DB 관례대로 허용.\n--   오류: `ACCOUNT_BLOCKED`(P0001) · `PG_EXCEPTION_DETAIL` = 상태값(banned · suspended · deleted · deletion_in_progress · status_unknown · row_missing).\n--\n-- D-0 core_private.account_blocked_state(p_user_id uuid) returns text — NULL 이면 허용, 아니면 차단 상태값. 외부 EXECUTE 0.\n-- D-1 api_app_v1.create_individual_question_as_student_v2(...) — 204 본문 그대로 + AUTH_REQUIRED 직후 D-0 검사 1곳. 시그니처·반환·ACL·오류 규약 불변.\n-- D-2 api_app_v1.create_individual_question_as_student_v3(\n--        p_question_type text, p_title text, p_body text, p_amount_cents int default null, p_designated_mentor_id uuid default null,\n--        p_idempotency_key text default null, p_subject text default null,\n--        p_topic text default null, p_required_school_tier text default null, p_required_major_category text default null)\n--      returns setof public.individual_questions\n--   · v2 와 동일(복제): AUTH_REQUIRED(28000) · ACCOUNT_BLOCKED(P0001 · detail 상태값) · INVALID_INPUT(22023) · INVALID_SUBJECT · SUBJECT_REQUIRED(open 필수) ·\n--     MENTOR_PRICE_NOT_SET(P0001) · 코어 실패 INDIVIDUAL_QUESTION_CREATE_FAILED:<code>:<message>(P0001) · 가격 결정 · 키 미전달 시 랜덤 키 · 자금·자격 판정은 코어 v2 위임.\n--   · 추가: p_topic — 단원·개념 자유 텍스트(trim · 빈 값 NULL · 200자 초과 TOPIC_TOO_LONG 22023) · direct/open 모두 허용.\n--   · 추가: p_required_school_tier / p_required_major_category — **open(공개형)에만**. 지정형은 값을 무시하고 NULL 로 넘긴다. 공개형은 DB 정본으로 검증:\n--       학교군  = `school_tier_catalog`(079_b · is_active) ∩ `individual_questions_required_school_tier_check` 목록 − **''미분류''** → 아니면 INVALID_TIER(22023)\n--       전공계열 = `major_category_catalog`(079_b · is_active) ∩ `individual_questions_required_major_category_check` 목록 → 아니면 INVALID_MAJOR(22023)\n-- 권한: REVOKE public·anon · GRANT authenticated 만(204 와 동일 · service_role 0). v1 `public.create_individual_question_as_student` 는 손대지 않는다.\n--\n-- Apply: 저장소 표준 경로(db-apply-pending). pack 등재: supabase/baseline/post_ledger_backfills/20260906100300_api_app_v1_individual_question_create_v3.sql\n-- Rollback: supabase/rollback/20260906100300_api_app_v1_individual_question_create_v3_rollback.sql (v3·D-0 DROP + v2 204 원문 복원)\n-- =============================================================================\n\nbegin", "do $$\ndeclare v_def text;\nbegin\n  if not exists (select 1 from pg_namespace where nspname = ''api_app_v1'') or not exists (select 1 from pg_namespace where nspname = ''core_private'') then\n    raise exception ''207_GATE: api_app_v1/core_private 스키마 부재'';\n  end if;\n  -- v2(204) 본문이 복제 원본과 같은지(md5) — 다르면 이 파일의 복제본·교체본이 v2 와 어긋난 것이므로 중단\n  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''api_app_v1'' and p.proname = ''create_individual_question_as_student_v2''\n     and pg_get_function_identity_arguments(p.oid) = ''p_question_type text, p_title text, p_body text, p_amount_cents integer, p_designated_mentor_id uuid, p_idempotency_key text, p_subject text'';\n  if v_def is null then\n    raise exception ''207_GATE: v2 create_individual_question_as_student_v2 identity 불일치(204)'';\n  end if;\n  if md5(v_def) <> ''aa8c27d2dcaa1c9cbfe5ae852f1c2dcc'' then\n    raise exception ''207_GATE: v2 본문 md5 불일치(복제 원본 204 · 2026-09-06 운영 실측 aa8c27d2…) — 현재 %'', md5(v_def);\n  end if;\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''public'' and p.proname = ''create_individual_question_with_hold_v2''\n                    and pg_get_function_identity_arguments(p.oid) = ''p_student_id uuid, p_question_type text, p_mentor_id uuid, p_subject text, p_topic text, p_title text, p_body text, p_price_cents integer, p_idempotency_key text, p_required_school_tier text, p_required_major_category text'') then\n    raise exception ''207_GATE: 코어 create_individual_question_with_hold_v2 identity 불일치(080_c)'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''individual_questions''\n       and column_name in (''subject'', ''topic'', ''required_school_tier'', ''required_major_category'')) <> 4 then\n    raise exception ''207_GATE: individual_questions 컬럼(subject·topic·required_*) 부재(070·080_c)'';\n  end if;\n  if (select pg_get_constraintdef(oid) from pg_constraint where conrelid = ''public.individual_questions''::regclass and conname = ''individual_questions_required_school_tier_check'')\n       not like ''%''''서연고''''%''''서성한''''%''''중경외시''''%''''건동홍''''%''''그외''''%''''미분류''''%'' then\n    raise exception ''207_GATE: required_school_tier CHECK 목록 불일치(080_c)'';\n  end if;\n  if (select pg_get_constraintdef(oid) from pg_constraint where conrelid = ''public.individual_questions''::regclass and conname = ''individual_questions_required_major_category_check'')\n       not like ''%''''메디컬''''%''''교육''''%''''인문''''%''''사회상경''''%''''자연''''%''''공학''''%''''예체능''''%''''기타''''%'' then\n    raise exception ''207_GATE: required_major_category CHECK 목록 불일치(080_c)'';\n  end if;\n  if not exists (select 1 from information_schema.tables where table_schema = ''public'' and table_name = ''school_tier_catalog'')\n     or not exists (select 1 from information_schema.tables where table_schema = ''public'' and table_name = ''major_category_catalog'') then\n    raise exception ''207_GATE: 분류 카탈로그(school_tier_catalog · major_category_catalog · 079_b) 부재'';\n  end if;\n  if not exists (select 1 from public.school_tier_catalog where code = ''서연고'' and is_active)\n     or not exists (select 1 from public.major_category_catalog where code = ''공학'' and is_active) then\n    raise exception ''207_GATE: 분류 카탈로그 행 부재'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''users'' and column_name in (''status'', ''suspended_until'')) <> 2\n     or not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = ''public'' and p.proname = ''account_deletion_write_blocked'') then\n    raise exception ''207_GATE: users.status/suspended_until 또는 account_deletion_write_blocked(151) 부재'';\n  end if;\n  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n              where (n.nspname, p.proname) in ((''api_app_v1'', ''create_individual_question_as_student_v3''), (''core_private'', ''account_blocked_state''))) then\n    raise exception ''207_GATE: 대상 함수가 이미 있다'';\n  end if;\n  -- v1 불변 확인용 스냅샷\n  create temp table db5_207_pre on commit drop as\n    select md5(pg_get_functiondef(''public.create_individual_question_as_student(text,text,text,int,uuid,text)''::regprocedure)) as v1_md5;\nend $$", "-- -----------------------------------------------------------------------------\n-- D-0. 계정 차단 상태 판정 (core_private · 외부 EXECUTE 0) — v2·v3 공유\n-- -----------------------------------------------------------------------------\ncreate function core_private.account_blocked_state(p_user_id uuid)\nreturns text\nlanguage plpgsql\nstable\nsecurity invoker\nset search_path to ''''\nas $fn$\ndeclare\n  v_status text;\n  v_susp timestamptz;\n  v_norm text;\nbegin\n  if p_user_id is null then\n    return ''row_missing'';\n  end if;\n  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id = p_user_id;\n  if not found then\n    return ''row_missing'';\n  end if;\n  v_norm := lower(btrim(coalesce(v_status, '''')));\n  if v_norm = ''banned'' then\n    return ''banned'';\n  end if;\n  if v_norm = ''suspended'' then\n    if v_susp is null or v_susp > now() then\n      return ''suspended'';\n    end if;\n    -- 만료된 정지 → 허용(앱·웹 동일)\n  elsif v_norm = ''deleted'' then\n    return ''deleted'';\n  elsif v_norm <> ''active'' then\n    return ''status_unknown'';\n  end if;\n  if public.account_deletion_write_blocked(p_user_id) then\n    return ''deletion_in_progress'';\n  end if;\n  return null;\nend\n$fn$", "comment on function core_private.account_blocked_state(uuid) is\n  ''207(DB-5 후속 b): 계정 차단 상태 — NULL 이면 허용. banned · suspended(무기한/미래) · deleted · deletion_in_progress(account_deletion_write_blocked) · status_unknown · row_missing. 앱 entry_guard/웹 assertAccountActive 와 같은 집합. 개별질문 v2·v3 가 공유. 외부 EXECUTE 0.''", "revoke all on function core_private.account_blocked_state(uuid) from public, anon, authenticated", "-- -----------------------------------------------------------------------------\n-- D-1. v2 — 204 본문 그대로 + AUTH_REQUIRED 직후 계정 검사 1곳 (시그니처·반환·오류 규약·ACL 불변)\n-- -----------------------------------------------------------------------------\ncreate or replace function api_app_v1.create_individual_question_as_student_v2(\n  p_question_type text,\n  p_title text,\n  p_body text,\n  p_amount_cents int default null,\n  p_designated_mentor_id uuid default null,\n  p_idempotency_key text default null,\n  p_subject text default null\n)\nreturns setof public.individual_questions\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_type text := lower(btrim(coalesce(p_question_type, '''')));\n  v_idem text := nullif(btrim(coalesce(p_idempotency_key, '''')), '''');\n  v_subject text := nullif(btrim(coalesce(p_subject, '''')), '''');\n  v_blocked text;\n  v_price int;\n  v_res public.individual_question_escrow_result;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  -- 207(DB-5 후속 b): 정지·차단·탈퇴 진행 중 계정은 등록 불가 — 앱 entry_guard/웹 assertAccountActive 와 같은 집합\n  v_blocked := core_private.account_blocked_state(v_uid);\n  if v_blocked is not null then\n    raise exception ''ACCOUNT_BLOCKED'' using errcode = ''P0001'', detail = v_blocked;\n  end if;\n\n  if v_type not in (''direct'', ''open'') then\n    raise exception ''INVALID_INPUT: question_type must be direct or open'' using errcode = ''22023'';\n  end if;\n\n  if char_length(btrim(coalesce(p_title, ''''))) = 0 or char_length(btrim(coalesce(p_body, ''''))) = 0 then\n    raise exception ''INVALID_INPUT: title and body are required'' using errcode = ''22023'';\n  end if;\n\n  -- 과목: 코드 정본(subjects.code) 실존 값만 · 공개형은 필수(멘토 라우팅 전제) · 지정형은 선택\n  if v_subject is not null and not exists (select 1 from public.subjects s where s.code = v_subject) then\n    raise exception ''INVALID_SUBJECT'' using errcode = ''22023'';\n  end if;\n  if v_type = ''open'' and v_subject is null then\n    raise exception ''SUBJECT_REQUIRED'' using errcode = ''22023'';\n  end if;\n\n  -- 가격 결정(v1 동일): open 은 앱이 보낸 금액, direct 는 멘토 가격표에서 조회 — 임의 계산 없음\n  if v_type = ''direct'' then\n    if p_designated_mentor_id is null then\n      raise exception ''INVALID_INPUT: designated_mentor_id is required for direct'' using errcode = ''22023'';\n    end if;\n    select mp.amount_cents into v_price from public.mentor_individual_question_pricing mp where mp.mentor_id = p_designated_mentor_id;\n    if v_price is null then\n      raise exception ''MENTOR_PRICE_NOT_SET'' using errcode = ''P0001'';\n    end if;\n  else\n    v_price := p_amount_cents;\n    if v_price is null or v_price <= 0 then\n      raise exception ''INVALID_INPUT: amount_cents must be positive for open'' using errcode = ''22023'';\n    end if;\n  end if;\n\n  -- 멱등성 키: 앱이 안 보내면 랜덤 생성(코어 NOT NULL 충족용 — v1 동일)\n  if v_idem is null then\n    v_idem := ''iqc:'' || gen_random_uuid()::text;\n  end if;\n\n  -- 코어 v2(service_role 전용)에 위임 — 자격 파라미터는 v1 과 같이 NULL\n  v_res := public.create_individual_question_with_hold_v2(\n    v_uid, v_type, p_designated_mentor_id, v_subject, null, p_title, p_body, v_price, v_idem, null, null);\n\n  if not v_res.ok then\n    raise exception ''INDIVIDUAL_QUESTION_CREATE_FAILED:%:%'', v_res.code, v_res.message using errcode = ''P0001'';\n  end if;\n\n  return query select q.* from public.individual_questions q where q.id = v_res.question_id;\nend\n$fn$", "comment on function api_app_v1.create_individual_question_as_student_v2(text, text, text, int, uuid, text, text) is\n  ''204(DB-4 F-1) + 207(DB-5 후속 b): create_individual_question_as_student(092) + p_subject(subjects.code 정본 · open 필수 · direct 선택) + 계정 차단 검사(ACCOUNT_BLOCKED · core_private.account_blocked_state). 나머지 시그니처·반환·오류 규약 동일. 자금·자격은 코어 v2 위임. v1 은 그대로.''", "-- -----------------------------------------------------------------------------\n-- D-2. v3 — v2 본문 복제 + topic · 자격 조건\n-- -----------------------------------------------------------------------------\ncreate function api_app_v1.create_individual_question_as_student_v3(\n  p_question_type text,\n  p_title text,\n  p_body text,\n  p_amount_cents int default null,\n  p_designated_mentor_id uuid default null,\n  p_idempotency_key text default null,\n  p_subject text default null,\n  p_topic text default null,\n  p_required_school_tier text default null,\n  p_required_major_category text default null\n)\nreturns setof public.individual_questions\nlanguage plpgsql\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_type text := lower(btrim(coalesce(p_question_type, '''')));\n  v_idem text := nullif(btrim(coalesce(p_idempotency_key, '''')), '''');\n  v_subject text := nullif(btrim(coalesce(p_subject, '''')), '''');\n  v_topic text := nullif(btrim(coalesce(p_topic, '''')), '''');\n  v_tier text := nullif(btrim(coalesce(p_required_school_tier, '''')), '''');\n  v_major text := nullif(btrim(coalesce(p_required_major_category, '''')), '''');\n  v_blocked text;\n  v_price int;\n  v_res public.individual_question_escrow_result;\nbegin\n  -- ── 이하 v2(204 + 207 D-1) 본문 복제 — 권한·계정·상태·과목·가격·키 검사 동일 ──\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n\n  -- 207(DB-5 후속 b): 정지·차단·탈퇴 진행 중 계정은 등록 불가 — v2 와 같은 판정 함수\n  v_blocked := core_private.account_blocked_state(v_uid);\n  if v_blocked is not null then\n    raise exception ''ACCOUNT_BLOCKED'' using errcode = ''P0001'', detail = v_blocked;\n  end if;\n\n  if v_type not in (''direct'', ''open'') then\n    raise exception ''INVALID_INPUT: question_type must be direct or open'' using errcode = ''22023'';\n  end if;\n\n  if char_length(btrim(coalesce(p_title, ''''))) = 0 or char_length(btrim(coalesce(p_body, ''''))) = 0 then\n    raise exception ''INVALID_INPUT: title and body are required'' using errcode = ''22023'';\n  end if;\n\n  -- 과목: 코드 정본(subjects.code) 실존 값만 · 공개형은 필수(멘토 라우팅 전제) · 지정형은 선택\n  if v_subject is not null and not exists (select 1 from public.subjects s where s.code = v_subject) then\n    raise exception ''INVALID_SUBJECT'' using errcode = ''22023'';\n  end if;\n  if v_type = ''open'' and v_subject is null then\n    raise exception ''SUBJECT_REQUIRED'' using errcode = ''22023'';\n  end if;\n\n  -- 가격 결정(v1 동일): open 은 앱이 보낸 금액, direct 는 멘토 가격표에서 조회 — 임의 계산 없음\n  if v_type = ''direct'' then\n    if p_designated_mentor_id is null then\n      raise exception ''INVALID_INPUT: designated_mentor_id is required for direct'' using errcode = ''22023'';\n    end if;\n    select mp.amount_cents into v_price from public.mentor_individual_question_pricing mp where mp.mentor_id = p_designated_mentor_id;\n    if v_price is null then\n      raise exception ''MENTOR_PRICE_NOT_SET'' using errcode = ''P0001'';\n    end if;\n  else\n    v_price := p_amount_cents;\n    if v_price is null or v_price <= 0 then\n      raise exception ''INVALID_INPUT: amount_cents must be positive for open'' using errcode = ''22023'';\n    end if;\n  end if;\n\n  -- 멱등성 키: 앱이 안 보내면 랜덤 생성(코어 NOT NULL 충족용 — v1 동일)\n  if v_idem is null then\n    v_idem := ''iqc:'' || gen_random_uuid()::text;\n  end if;\n  -- ── v2 복제 끝 ──\n\n  -- v3 추가 ①: 단원·개념 — 자유 텍스트(웹 지정형·공개형 모두 허용) · 200자 상한\n  if v_topic is not null and char_length(v_topic) > 200 then\n    raise exception ''TOPIC_TOO_LONG'' using errcode = ''22023'';\n  end if;\n\n  -- v3 추가 ②: 자격 조건 — 공개형만. 지정형은 멘토가 이미 정해졌으므로 무시(NULL)\n  if v_type <> ''open'' then\n    v_tier := null;\n    v_major := null;\n  else\n    if v_tier is not null and (\n         v_tier = ''미분류''\n      or not exists (select 1 from public.school_tier_catalog c where c.code = v_tier and c.is_active)\n      or v_tier not in (''서연고'', ''서성한'', ''중경외시'', ''건동홍'', ''그외'')\n    ) then\n      raise exception ''INVALID_TIER'' using errcode = ''22023'';\n    end if;\n    if v_major is not null and (\n         not exists (select 1 from public.major_category_catalog c where c.code = v_major and c.is_active)\n      or v_major not in (''메디컬'', ''교육'', ''인문'', ''사회상경'', ''자연'', ''공학'', ''예체능'', ''기타'')\n    ) then\n      raise exception ''INVALID_MAJOR'' using errcode = ''22023'';\n    end if;\n  end if;\n\n  -- 코어 v2(service_role 전용)에 위임 — v2 와 같은 호출에 topic·자격 3인자만 채운다\n  v_res := public.create_individual_question_with_hold_v2(\n    v_uid, v_type, p_designated_mentor_id, v_subject, v_topic, p_title, p_body, v_price, v_idem, v_tier, v_major);\n\n  if not v_res.ok then\n    raise exception ''INDIVIDUAL_QUESTION_CREATE_FAILED:%:%'', v_res.code, v_res.message using errcode = ''P0001'';\n  end if;\n\n  return query select q.* from public.individual_questions q where q.id = v_res.question_id;\nend\n$fn$", "comment on function api_app_v1.create_individual_question_as_student_v3(text, text, text, int, uuid, text, text, text, text, text) is\n  ''207(DB-5 D-2): create_individual_question_as_student_v2 본문 복제(계정 차단 검사 포함) + p_topic(≤200자) + p_required_school_tier/p_required_major_category(공개형만 · 카탈로그 079_b ∩ CHECK 080_c · 미분류 불가 · INVALID_TIER/INVALID_MAJOR · 지정형은 무시). 나머지 시그니처·반환·오류 규약 v2 동일. 자금·자격은 코어 v2 위임. v1 은 그대로.''", "revoke all on function api_app_v1.create_individual_question_as_student_v3(text, text, text, int, uuid, text, text, text, text, text) from public, anon", "grant execute on function api_app_v1.create_individual_question_as_student_v3(text, text, text, int, uuid, text, text, text, text, text) to authenticated", "do $$\ndeclare v_oid oid; v_src text; v2_oid oid; v2_src text; v_gate oid;\nbegin\n  -- D-0\n  select p.oid into v_gate from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''core_private'' and p.proname = ''account_blocked_state'' and pg_get_function_identity_arguments(p.oid) = ''p_user_id uuid'' and p.provolatile = ''s'';\n  if v_gate is null or has_function_privilege(''anon'', v_gate, ''EXECUTE'') or has_function_privilege(''authenticated'', v_gate, ''EXECUTE'') or has_function_privilege(''service_role'', v_gate, ''EXECUTE'') then\n    raise exception ''207_SELFCHECK: account_blocked_state 부재 또는 외부 EXECUTE 잔존'';\n  end if;\n  -- D-1 v2: identity·ACL 불변 · 본문은 검사 1곳만 추가\n  select p.oid, p.prosrc into v2_oid, v2_src from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''api_app_v1'' and p.proname = ''create_individual_question_as_student_v2''\n     and pg_get_function_identity_arguments(p.oid) = ''p_question_type text, p_title text, p_body text, p_amount_cents integer, p_designated_mentor_id uuid, p_idempotency_key text, p_subject text''\n     and p.prosecdef and coalesce(p.proconfig::text, '''') like ''%search_path=%'' and p.proretset;\n  if v2_oid is null then\n    raise exception ''207_SELFCHECK: v2 identity/attributes 변경됨'';\n  end if;\n  if has_function_privilege(''anon'', v2_oid, ''EXECUTE'') or not has_function_privilege(''authenticated'', v2_oid, ''EXECUTE'') or has_function_privilege(''service_role'', v2_oid, ''EXECUTE'') then\n    raise exception ''207_SELFCHECK: v2 ACL 변경됨(authenticated 만)'';\n  end if;\n  if md5(pg_get_functiondef(v2_oid)) = ''aa8c27d2dcaa1c9cbfe5ae852f1c2dcc'' or v2_src not like ''%core_private.account_blocked_state(%'' or v2_src not like ''%ACCOUNT_BLOCKED%''\n     or v2_src not like ''%public.create_individual_question_with_hold_v2(%'' or v2_src like ''%insert into public.cash_ledger%'' then\n    raise exception ''207_SELFCHECK: v2 교체 실패(검사 미포함 또는 위임 아님)'';\n  end if;\n  -- D-2 v3\n  select p.oid, p.prosrc into v_oid, v_src from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''api_app_v1'' and p.proname = ''create_individual_question_as_student_v3''\n     and pg_get_function_identity_arguments(p.oid) = ''p_question_type text, p_title text, p_body text, p_amount_cents integer, p_designated_mentor_id uuid, p_idempotency_key text, p_subject text, p_topic text, p_required_school_tier text, p_required_major_category text''\n     and p.prosecdef and coalesce(p.proconfig::text, '''') like ''%search_path=%'' and p.proretset;\n  if v_oid is null then\n    raise exception ''207_SELFCHECK: v3 identity/attributes 불일치'';\n  end if;\n  if has_function_privilege(''anon'', v_oid, ''EXECUTE'') or not has_function_privilege(''authenticated'', v_oid, ''EXECUTE'') or has_function_privilege(''service_role'', v_oid, ''EXECUTE'') then\n    raise exception ''207_SELFCHECK: v3 ACL 불일치(authenticated 만)'';\n  end if;\n  if v_src not like ''%public.create_individual_question_with_hold_v2(%'' or v_src like ''%insert into public.cash_ledger%'' then\n    raise exception ''207_SELFCHECK: v3 코어 위임 아님 또는 자금 로직 복제'';\n  end if;\n  if v_src not like ''%AUTH_REQUIRED%'' or v_src not like ''%core_private.account_blocked_state(%'' or v_src not like ''%ACCOUNT_BLOCKED%'' or v_src not like ''%SUBJECT_REQUIRED%''\n     or v_src not like ''%INVALID_SUBJECT%'' or v_src not like ''%MENTOR_PRICE_NOT_SET%'' or v_src not like ''%''''iqc:'''' || gen_random_uuid()%'' then\n    raise exception ''207_SELFCHECK: v3 검사부(v2 복제 + 계정 검사) 누락'';\n  end if;\n  -- v1 불변(identity·ACL·md5)\n  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n                  where n.nspname = ''public'' and p.proname = ''create_individual_question_as_student''\n                    and has_function_privilege(''authenticated'', p.oid, ''EXECUTE'') and not has_function_privilege(''anon'', p.oid, ''EXECUTE'')) then\n    raise exception ''207_SELFCHECK: v1 ACL 변경됨'';\n  end if;\n  if md5(pg_get_functiondef(''public.create_individual_question_as_student(text,text,text,int,uuid,text)''::regprocedure)) <> (select v1_md5 from db5_207_pre) then\n    raise exception ''207_SELFCHECK: v1 본문 변경됨'';\n  end if;\n  -- 판정 함수: 존재하지 않는 사용자 → row_missing\n  if core_private.account_blocked_state(gen_random_uuid()) is distinct from ''row_missing'' or core_private.account_blocked_state(null) is distinct from ''row_missing'' then\n    raise exception ''207_SELFCHECK: account_blocked_state 판정 불일치'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "review_eligibility_paid_twice", "version": "20260906100400", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 208_review_eligibility_paid_twice.sql  (2026-09-06 · DB-5 묶음 E — 리뷰 자격 정본화: 같은 멘토 구독 결제 2회 이상)\n--\n-- 왜: 문서가 정본이다(오너 확정 2026-09-06) — \"같은 멘토에게 2회 결제하면 후기 작성 가능\"(학생 이용안내서 · CLAUDE.md 잠금값 \"동일 멘토 2회 연속 결제 성공\").\n--   현재 `check_review_eligibility`(170)는 \"구독 이력 있음(active/expired/cancel_scheduled) 또는 완료 개별질문 있음\"으로 더 느슨하다.\n--   \"연속\"은 **누적 2회**로 해석한다(초기 결제 + 갱신 1회 = 2회 · 같은 멘토를 두 번 구독해도 2회) — 갱신 연속성은 세지 않는다.\n--   정본 표는 `subscription_billing_events`(064 · 정산 배치의 원천): `status = ''succeeded''` AND `event_type in (''initial'',''renewal'')` AND `amount_cents > 0`.\n--   개별질문 결제는 세지 않는다. 066 의 cash_ledger/payments 폴백 집계는 되살리지 않는다(운영 구독 0 · 리뷰 0 → 레거시 데이터 없음).\n--\n-- E-1 core_private.review_eligibility_impl(p_mentor_id uuid, p_student_id uuid) returns jsonb  {eligible, paid_count, required_count: 2}\n--     · 판정 정본 하나 — 아래 두 함수가 공유한다. 외부 EXECUTE 0(anon/authenticated/service_role 전부 없음).\n-- E-2 public.check_review_eligibility(p_mentor_id uuid, p_student_id uuid) returns boolean  — **시그니처·반환형·속성·ACL 유지**(126 정책 `reviews_insert_student`\n--     가 boolean 식으로 쓴다 · 인자 순서 (멘토, 학생) 고정 — 170 경고 승계). 본문만 E-1 위임으로 교체.\n-- E-3 api_app_v1.review_eligibility_self(p_mentor_id uuid) returns jsonb — 앱 후기 화면용 사유 포함 판정\n--     · `{ok:true, contract_version:1, eligible, reason: ''OK'' | ''NOT_ENOUGH_PAYMENTS'' | ''ALREADY_REVIEWED'', paid_count, required_count, existing_review_id}`\n--       (ALREADY_REVIEWED 는 본인 기존 후기 → 수정 경로 · 171 `reviews_update_author` · 숨김/블라인드면 `can_edit false`)\n--     · 오류 envelope `{ok:false, contract_version:1, code}`: AUTH_REQUIRED · MENTOR_NOT_FOUND(NULL · 멘토 역할 아님)\n--     · SECURITY DEFINER · search_path '''' · authenticated 만(DB-4 계약 동일).\n-- 웹: `lib/reviews/reviewEligibilityPolicy.ts`(UI 사전 판정 · 170 과 1:1)는 이 배치에서 바꾸지 않는다(원칙 — 웹 PR 이 같은 규칙으로 갱신해야 화면과 INSERT 정책이 일치한다 · 보고서).\n--\n-- Apply: 저장소 표준 경로(db-apply-pending). pack 등재: supabase/baseline/post_ledger_backfills/20260906100400_review_eligibility_paid_twice.sql\n-- Rollback: supabase/rollback/20260906100400_review_eligibility_paid_twice_rollback.sql (170 본문 원문 복원 + E-1·E-3 DROP)\n-- =============================================================================\n\nbegin", "do $$\ndeclare v_md5 text;\nbegin\n  if not exists (select 1 from pg_namespace where nspname = ''api_app_v1'') or not exists (select 1 from pg_namespace where nspname = ''core_private'') then\n    raise exception ''208_GATE: api_app_v1/core_private 스키마 부재'';\n  end if;\n  select md5(pg_get_functiondef(p.oid)) into v_md5 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''public'' and p.proname = ''check_review_eligibility'' and pg_get_function_identity_arguments(p.oid) = ''p_mentor_id uuid, p_student_id uuid'';\n  if v_md5 is null then\n    raise exception ''208_GATE: check_review_eligibility(uuid,uuid) identity 불일치(170)'';\n  end if;\n  if v_md5 <> ''7f458145b70b0eb239a0c67f265a4c93'' then\n    raise exception ''208_GATE: check_review_eligibility 본문 md5 불일치(170 · 2026-09-06 운영 실측 7f458145…) — 현재 %'', v_md5;\n  end if;\n  if not exists (select 1 from pg_policies where schemaname = ''public'' and tablename = ''reviews'' and policyname = ''reviews_insert_student''\n                   and with_check like ''%check_review_eligibility(mentor_id%'') then\n    raise exception ''208_GATE: reviews_insert_student 정책(126) 이 check_review_eligibility(mentor_id, …) 를 쓰지 않는다'';\n  end if;\n  if (select count(*) from information_schema.columns where table_schema = ''public'' and table_name = ''subscription_billing_events''\n       and column_name in (''student_id'', ''mentor_id'', ''status'', ''event_type'', ''amount_cents'')) <> 5 then\n    raise exception ''208_GATE: subscription_billing_events 컬럼 불일치(064)'';\n  end if;\n  if not exists (select 1 from pg_indexes where schemaname = ''public'' and tablename = ''reviews'' and indexname = ''uq_reviews_mentor_author'') then\n    raise exception ''208_GATE: uq_reviews_mentor_author 부재(042/123)'';\n  end if;\n  if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n              where (n.nspname, p.proname) in ((''core_private'', ''review_eligibility_impl''), (''api_app_v1'', ''review_eligibility_self''))) then\n    raise exception ''208_GATE: 대상 함수가 이미 있다'';\n  end if;\nend $$", "-- -----------------------------------------------------------------------------\n-- E-1. 판정 정본 (core_private · 외부 EXECUTE 0)\n-- -----------------------------------------------------------------------------\ncreate function core_private.review_eligibility_impl(p_mentor_id uuid, p_student_id uuid)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_required constant int := 2;   -- 같은 멘토 구독 결제 성공 2회(누적) — CLAUDE.md 잠금값\n  v_paid int := 0;\nbegin\n  if p_mentor_id is not null and p_student_id is not null then\n    select count(*)::int into v_paid\n      from public.subscription_billing_events e\n     where e.student_id = p_student_id\n       and e.mentor_id = p_mentor_id\n       and e.status = ''succeeded''\n       and e.event_type in (''initial'', ''renewal'')\n       and coalesce(e.amount_cents, 0) > 0;\n  end if;\n  return jsonb_build_object(''eligible'', v_paid >= v_required, ''paid_count'', v_paid, ''required_count'', v_required);\nend\n$fn$", "comment on function core_private.review_eligibility_impl(uuid, uuid) is\n  ''208(DB-5 E-1): 리뷰 자격 판정 정본 — 같은 (학생, 멘토) 의 subscription_billing_events succeeded·initial/renewal·amount>0 누적 2건 이상. check_review_eligibility 와 api_app_v1.review_eligibility_self 가 공유. 외부 EXECUTE 0.''", "revoke all on function core_private.review_eligibility_impl(uuid, uuid) from public, anon, authenticated", "-- -----------------------------------------------------------------------------\n-- E-2. RLS 판정 함수 — 시그니처·반환형·속성 유지(170 과 동일 헤더) · 본문만 교체 · ACL 은 replace 로 보존\n-- -----------------------------------------------------------------------------\ncreate or replace function public.check_review_eligibility(\n  p_mentor_id uuid,\n  p_student_id uuid\n) returns boolean\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  -- 208(DB-5 E): 같은 멘토 구독 결제 성공 2회 이상(누적) — 판정 정본은 core_private.review_eligibility_impl.\n  -- 인자 순서 (p_mentor_id, p_student_id) 는 126 reviews_insert_student 가 고정한다(170 경고 승계).\n  if p_mentor_id is null or p_student_id is null then\n    return false;\n  end if;\n  return coalesce((core_private.review_eligibility_impl(p_mentor_id, p_student_id) ->> ''eligible'')::boolean, false);\nend;\n$$", "comment on function public.check_review_eligibility(uuid, uuid) is\n  ''Review eligibility (DB-5 208, owner decision 2026-09-06): eligible when the same (student, mentor) pair has >= 2 succeeded paid subscription billing events (initial/renewal, amount > 0, cumulative). Individual-question payments do not count. Replaces the relationship-based rule (170). Argument order (p_mentor_id, p_student_id) is fixed by 126 reviews_insert_student.''", "-- -----------------------------------------------------------------------------\n-- E-3. 앱 self 판정(사유 포함)\n-- -----------------------------------------------------------------------------\ncreate function api_app_v1.review_eligibility_self(p_mentor_id uuid)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path to ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_existing_id uuid;\n  v_moderated boolean := false;\n  v_res jsonb;\nbegin\n  if v_uid is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  end if;\n  if p_mentor_id is null or not exists (select 1 from public.users u where u.id = p_mentor_id and u.role = ''mentor'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_FOUND'');\n  end if;\n\n  -- ① 본인 기존 후기(숨김·블라인드 포함 — 171 reviews_select_author) → 수정 경로. 자격을 재검사하지 않는다(171 정본).\n  select r.id, (coalesce(r.is_hidden, false) or coalesce(r.is_blinded, false))\n    into v_existing_id, v_moderated\n    from public.reviews r\n   where r.mentor_id = p_mentor_id and r.author_id = v_uid\n   limit 1;\n  if v_existing_id is not null then\n    return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''eligible'', false, ''reason'', ''ALREADY_REVIEWED'',\n                              ''existing_review_id'', v_existing_id, ''can_edit'', not v_moderated,\n                              ''paid_count'', null, ''required_count'', 2);\n  end if;\n\n  -- ② 신규 작성 자격 — E-1 정본\n  v_res := core_private.review_eligibility_impl(p_mentor_id, v_uid);\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1,\n                            ''eligible'', (v_res ->> ''eligible'')::boolean,\n                            ''reason'', case when (v_res ->> ''eligible'')::boolean then ''OK'' else ''NOT_ENOUGH_PAYMENTS'' end,\n                            ''existing_review_id'', null, ''can_edit'', false,\n                            ''paid_count'', (v_res ->> ''paid_count'')::int, ''required_count'', (v_res ->> ''required_count'')::int);\nend\n$fn$", "comment on function api_app_v1.review_eligibility_self(uuid) is\n  ''208(DB-5 E-3): 앱 후기 화면 자격 판정 — 본인 기존 후기 ALREADY_REVIEWED(existing_review_id · can_edit) → 아니면 E-1 정본(OK / NOT_ENOUGH_PAYMENTS · paid_count · required_count 2). AUTH_REQUIRED · MENTOR_NOT_FOUND 는 ok:false. authenticated 만.''", "revoke all on function api_app_v1.review_eligibility_self(uuid) from public, anon", "grant execute on function api_app_v1.review_eligibility_self(uuid) to authenticated", "do $$\ndeclare v_oid oid; v_impl oid; v_self oid;\nbegin\n  select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''public'' and p.proname = ''check_review_eligibility''\n     and pg_get_function_identity_arguments(p.oid) = ''p_mentor_id uuid, p_student_id uuid''\n     and p.prorettype = ''boolean''::regtype and p.prosecdef and p.provolatile = ''s'';\n  if v_oid is null then\n    raise exception ''208_SELFCHECK: check_review_eligibility 시그니처/속성 변경됨'';\n  end if;\n  if has_function_privilege(''anon'', v_oid, ''EXECUTE'') or not has_function_privilege(''authenticated'', v_oid, ''EXECUTE'') then\n    raise exception ''208_SELFCHECK: check_review_eligibility ACL 변경됨(170: anon 0 · authenticated)'';\n  end if;\n  if (select prosrc from pg_proc where oid = v_oid) not like ''%core_private.review_eligibility_impl(%''\n     or (select prosrc from pg_proc where oid = v_oid) like ''%individual_questions%'' then\n    raise exception ''208_SELFCHECK: check_review_eligibility 본문이 정본 위임이 아니거나 개별질문 경로가 남아 있다'';\n  end if;\n  select p.oid into v_impl from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''core_private'' and p.proname = ''review_eligibility_impl'' and p.prosecdef and p.provolatile = ''s'';\n  if v_impl is null or has_function_privilege(''anon'', v_impl, ''EXECUTE'') or has_function_privilege(''authenticated'', v_impl, ''EXECUTE'')\n     or has_function_privilege(''service_role'', v_impl, ''EXECUTE'') then\n    raise exception ''208_SELFCHECK: impl 부재 또는 외부 EXECUTE 잔존'';\n  end if;\n  select p.oid into v_self from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''api_app_v1'' and p.proname = ''review_eligibility_self'' and pg_get_function_identity_arguments(p.oid) = ''p_mentor_id uuid''\n     and p.prosecdef and coalesce(p.proconfig::text, '''') like ''%search_path=%'';\n  if v_self is null or has_function_privilege(''anon'', v_self, ''EXECUTE'') or not has_function_privilege(''authenticated'', v_self, ''EXECUTE'')\n     or has_function_privilege(''service_role'', v_self, ''EXECUTE'') then\n    raise exception ''208_SELFCHECK: review_eligibility_self 부재 또는 ACL 불일치(authenticated 만)'';\n  end if;\n  if (select prosrc from pg_proc where oid = v_self) not like ''%core_private.review_eligibility_impl(%'' then\n    raise exception ''208_SELFCHECK: review_eligibility_self 가 정본을 공유하지 않는다'';\n  end if;\n  -- 정책 불변(126)\n  if not exists (select 1 from pg_policies where schemaname = ''public'' and tablename = ''reviews'' and policyname = ''reviews_insert_student''\n                   and with_check like ''%check_review_eligibility(mentor_id%'') then\n    raise exception ''208_SELFCHECK: reviews_insert_student 정책 변경됨'';\n  end if;\n  -- 판정: NULL 인자 → false · 존재하지 않는 쌍 → false (impl paid_count 0)\n  if public.check_review_eligibility(null, null) or public.check_review_eligibility(gen_random_uuid(), gen_random_uuid()) then\n    raise exception ''208_SELFCHECK: 빈 쌍 판정이 true'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "marketing_consent_idempotency_key", "version": "20260906100500", "rollback": null, "created_by": null, "statements": ["-- =============================================================================\n-- 209_marketing_consent_idempotency_key.sql  (2026-09-06 · DB-5 후속 d — 마케팅 동의 RPC NOT NULL 결함)\n--\n-- 왜: `api_web_v1.user_marketing_consent_set_self(p_agreed boolean)`(20260803162257 G)의 `user_consent_records` INSERT 가 **`idempotency_key`(NOT NULL · UNIQUE · 기본값 없음)를\n--   넣지 않아 모든 사용자에게 `null value in column \"idempotency_key\"` 로 실패**한다(DB-5 보고서 §2-2 관찰 ② · 스크래치 실측). 운영 실측 2026-09-06: `source = ''self_rpc''` 행 0 ·\n--   웹·앱 호출자 0(grep) — 즉 이 RPC 는 한 번도 성공한 적이 없다.\n--\n-- 원인 컬럼 판단(실측 후): 원장의 다른 두 작성자(가입 트리거 187 `signup:<uid>:<type>:<version>` · 본인인증 서비스 guardian 행 `idempotency_key = verification id`)는 모두\n--   호출자가 키를 명시한다. 컬럼 DEFAULT(예: gen_random_uuid())로 고치면 이 결함은 사라지지만 키를 빠뜨린 다른 작성자까지 조용히 통과시키고 \"멱등 키\" 의미가 사라진다.\n--   → **RPC 가 키를 명시**하는 쪽으로 고친다(COALESCE 형). 키 = `self_rpc:<uid>:marketing:<uuid>` — 토글 원장은 append-only(on/off 이력)라 호출마다 새 행이어야 하므로\n--   호출 단위 무작위 접미(같은 값 재시도는 중복 행 · 무해). 그 외 본문(게이트·컬럼·값·반환)은 원문 그대로 · 시그니처·ACL(authenticated · service_role) 불변.\n--\n-- Apply: 저장소 표준 경로(db-apply-pending). pack 등재: supabase/baseline/post_ledger_backfills/20260906100500_marketing_consent_idempotency_key.sql\n-- Rollback: supabase/rollback/20260906100500_marketing_consent_idempotency_key_rollback.sql (20260803162257 G 원문 복원)\n-- =============================================================================\n\nbegin", "do $$\ndeclare v_md5 text;\nbegin\n  select md5(pg_get_functiondef(p.oid)) into v_md5 from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''api_web_v1'' and p.proname = ''user_marketing_consent_set_self'' and pg_get_function_identity_arguments(p.oid) = ''p_agreed boolean'';\n  if v_md5 is null then\n    raise exception ''209_GATE: api_web_v1.user_marketing_consent_set_self(boolean) 부재'';\n  end if;\n  if v_md5 <> ''9a84375f8ae7662f0f20f5ac76a4d2c4'' then\n    raise exception ''209_GATE: user_marketing_consent_set_self 본문 md5 불일치(20260803162257 G · 2026-09-06 운영 실측 9a84375f…) — 현재 %'', v_md5;\n  end if;\n  if not exists (select 1 from information_schema.columns where table_schema = ''public'' and table_name = ''user_consent_records''\n                   and column_name = ''idempotency_key'' and is_nullable = ''NO'' and column_default is null) then\n    raise exception ''209_GATE: user_consent_records.idempotency_key 전제(NOT NULL · 기본값 없음) 불일치'';\n  end if;\n  if not exists (select 1 from pg_constraint where conrelid = ''public.user_consent_records''::regclass and contype = ''u''\n                   and pg_get_constraintdef(oid) like ''%idempotency_key%'') then\n    raise exception ''209_GATE: idempotency_key UNIQUE 부재'';\n  end if;\nend $$", "-- 20260803162257 G 원문 + idempotency_key 한 열 (그 외 동일)\ncreate or replace function api_web_v1.user_marketing_consent_set_self(p_agreed boolean)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = ''''\nas $fn$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_status text;\n  v_susp timestamptz;\n  v_norm text;\nbegin\n  if v_uid is null then\n    raise exception ''AUTH_REQUIRED'' using errcode = ''28000'';\n  end if;\n  if p_agreed is null then\n    raise exception ''CONSENT_VALUE_REQUIRED'' using errcode = ''22023'';\n  end if;\n\n  select u.status, u.suspended_until into v_status, v_susp\n    from public.users u where u.id = v_uid for update;\n  if not found then\n    raise exception ''ACCOUNT_NOT_ACTIVE'';\n  end if;\n  v_norm := lower(btrim(coalesce(v_status,'''')));\n  if v_norm = ''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if v_norm not in (''active'',''suspended'') then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  if public.account_deletion_write_blocked(v_uid) then raise exception ''ACCOUNT_DELETION_IN_PROGRESS''; end if;\n\n  -- append-only 원장: 기존 행 UPDATE/DELETE 없음 (§18.2)\n  -- 209(DB-5 후속 d): idempotency_key(NOT NULL · UNIQUE) 명시 — 토글 이력은 호출마다 새 행(무작위 접미)\n  insert into public.user_consent_records\n    (user_id, consent_type, consent_actor, consent_version, agreed_at, source, metadata, idempotency_key)\n  values\n    (v_uid, ''marketing'', ''user'', ''v1'', now(), ''self_rpc'', jsonb_build_object(''agreed'', p_agreed),\n     format(''self_rpc:%s:marketing:%s'', v_uid, gen_random_uuid()));\n\n  update public.users set marketing_agreed = p_agreed, updated_at = now() where id = v_uid;\n\n  return jsonb_build_object(''ok'', true, ''contract_version'', 1, ''marketing_agreed'', p_agreed);\nend\n$fn$", "comment on function api_web_v1.user_marketing_consent_set_self(boolean) is\n  ''20260803162257 G + 209(DB-5 후속 d): 마케팅 동의 원장 append(idempotency_key self_rpc:<uid>:marketing:<uuid>) + users.marketing_agreed 반영. 시그니처·ACL 불변.''", "do $$\ndeclare v_oid oid;\nbegin\n  select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace\n   where n.nspname = ''api_web_v1'' and p.proname = ''user_marketing_consent_set_self'' and pg_get_function_identity_arguments(p.oid) = ''p_agreed boolean''\n     and p.prosecdef and coalesce(p.proconfig::text, '''') like ''%search_path=%'' and p.prorettype = ''jsonb''::regtype;\n  if v_oid is null then\n    raise exception ''209_SELFCHECK: identity/attributes 불일치'';\n  end if;\n  if md5(pg_get_functiondef(v_oid)) = ''9a84375f8ae7662f0f20f5ac76a4d2c4'' then\n    raise exception ''209_SELFCHECK: 본문이 바뀌지 않았다'';\n  end if;\n  if (select prosrc from pg_proc where oid = v_oid) not like ''%idempotency_key)%''\n     or (select prosrc from pg_proc where oid = v_oid) not like ''%format(''''self_rpc:%'' then\n    raise exception ''209_SELFCHECK: idempotency_key 명시 누락'';\n  end if;\n  if has_function_privilege(''anon'', v_oid, ''EXECUTE'') or not has_function_privilege(''authenticated'', v_oid, ''EXECUTE'')\n     or not has_function_privilege(''service_role'', v_oid, ''EXECUTE'') then\n    raise exception ''209_SELFCHECK: ACL 변경됨(authenticated · service_role)'';\n  end if;\nend $$", "commit"], "idempotency_key": null}, {"name": "subscription_financial_boundaries", "version": "20261008003644", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- Subscription writes: DB price authority and atomic billing. Old RPC contracts stay callable.\nbegin;\nset local lock_timeout = ''5s'';\n\ncreate or replace function core_private.record_initial_subscription_billing_event(\n  p_payment_id uuid, p_subscription_id uuid, p_set_latest boolean default false\n) returns uuid language plpgsql security invoker set search_path = '''' as $fn$\ndeclare\n  p public.payments%rowtype; s public.subscriptions%rowtype; l public.cash_ledger%rowtype;\n  e public.subscription_billing_events%rowtype;\n  v_tier text; v_key text := ''sub_initial:'' || p_subscription_id::text;\n  v_start timestamptz; v_end timestamptz;\nbegin\n  select * into strict p from public.payments where id = p_payment_id;\n  select * into strict s from public.subscriptions where id = p_subscription_id for update;\n  select * into l from public.cash_ledger where idempotency_key = ''sub_debit_'' || p_payment_id::text;\n  if l.id is null or l.user_id is distinct from p.user_id or l.ref_id is distinct from s.id\n     or l.ref_type is distinct from ''subscriptions'' or l.reason is distinct from ''subscription_payment''\n     or l.delta_cents is distinct from -(p.amount * 100)::bigint\n     or s.student_id is distinct from p.user_id or s.mentor_id is distinct from p.mentor_id\n     or p.status not in (''succeeded'',''paid'',''success'',''complete'',''captured'') then\n    raise exception ''BILLING_EVENT_BINDING_MISMATCH'';\n  end if;\n  select plan_tier into v_tier from public.mentor_plans where id = p.plan_id and mentor_id = p.mentor_id;\n  if v_tier is null then raise exception ''PLAN_BINDING_MISMATCH''; end if;\n  select * into e from public.subscription_billing_events\n    where payment_id = p.id and event_type = ''initial'' order by created_at, id limit 1;\n  if e.id is not null then\n    if e.subscription_id is distinct from s.id or e.ledger_id is distinct from l.id\n       or e.amount_cents is distinct from -l.delta_cents or e.plan_id is distinct from p.plan_id\n       or e.status not in (''succeeded'', ''refunded'') then\n      raise exception ''BILLING_EVENT_BINDING_MISMATCH'';\n    end if;\n    return e.id;\n  end if;\n  -- Preserve the previous payment''s event on reactivation. The current payment keeps the\n  -- legacy key so web versions still doing their post-RPC upsert remain compatible.\n  update public.subscription_billing_events\n     set idempotency_key = v_key || '':'' || payment_id::text\n   where idempotency_key = v_key and payment_id is not null and payment_id <> p.id;\n  if exists (select 1 from public.subscription_billing_events where idempotency_key = v_key) then\n    raise exception ''BILLING_EVENT_BINDING_MISMATCH'';\n  end if;\n  v_start := case when s.last_payment_id = p.id then coalesce(s.current_period_start,l.created_at) else l.created_at end;\n  v_end := case when s.last_payment_id = p.id then s.current_period_end else null end;\n  v_end := coalesce(v_end, ((v_start at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul''));\n  insert into public.subscription_billing_events\n    (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,\n     amount_cents,plan_tier,plan_id,idempotency_key,ledger_id,payment_id,processed_at)\n  values (s.id,p.user_id,p.mentor_id,''initial'',''succeeded'',v_start,v_end,l.created_at,\n          -l.delta_cents,v_tier,p.plan_id,v_key,l.id,p.id,l.created_at)\n  returning * into e;\n  if p_set_latest and s.last_payment_id = p.id then\n    update public.subscriptions set last_billing_event_id = e.id where id = s.id;\n  end if;\n  return e.id;\nend $fn$;\nrevoke all on function core_private.record_initial_subscription_billing_event(uuid,uuid,boolean) from public,anon,authenticated,service_role;\n\ndo $gate$ begin if md5(replace(pg_get_functiondef(''api_web_v1.subscription_checkout_confirm_v2(uuid,uuid,integer,text)''::regprocedure),chr(13),'''')) <> ''8655ffd516d3a4034a465eb15c1061c2'' then raise exception ''FINANCIAL_SOURCE_DRIFT: api_web_v1.subscription_checkout_confirm_v2''; end if; end $gate$;\ndo $gate$ begin if md5(replace(pg_get_functiondef(''api_app_v1.subscribe_with_cash(uuid,text,text)''::regprocedure),chr(13),'''')) <> ''1fa39311718b47163783362daecaff9d'' then raise exception ''FINANCIAL_SOURCE_DRIFT: api_app_v1.subscribe_with_cash''; end if; end $gate$;\nCREATE OR REPLACE FUNCTION core_private.subscription_checkout_confirm_impl(p_payment_id uuid, p_plan_id uuid, p_expected_amount_cents integer, p_idempotency_key text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY INVOKER\n SET search_path TO ''''\nAS $function$\nDECLARE\n  v_succeeded    constant text[] := array[''succeeded'',''paid'',''success'',''complete'',''captured''];\n  -- 정본 confirm_subscription_checkout raise 17종(§9.8 — 동명 envelope 변환)\n  v_canon_raises constant text[] := array[\n    ''PAYMENT_NOT_FOUND'',''PAYMENT_NO_USER'',''PAYMENT_NO_MENTOR'',''PAYMENT_KIND_INVALID'',\n    ''PLAN_NOT_FOUND'',''PLAN_MENTOR_MISMATCH'',''PLAN_AMOUNT_INVALID'',\n    ''PAYMENT_PROCESSING'',''PAYMENT_NOT_PENDING'',''PAYMENT_STATE_UNEXPECTED'',''PAYMENT_STALE'',\n    ''ACCOUNT_BANNED'',''ACCOUNT_SUSPENDED'',\n    ''MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS'',''MENTOR_NOT_APPROVED'',''PLAN_INACTIVE'',''MENTOR_CAP_EXCEEDED''];\n  p_rec          record;      -- P = 이번 호출 payment\n  v_sub          record;      -- 잠근 subscription\n  v_led          record;      -- P 자신의 sub_debit_ 원장 행\n  v_c            record;      -- C = subscription.last_payment_id 가 가리키는 payment\n  v_room         record;\n  v_intent       bigint;      -- 결제 시점 불변 동의 금액 = payments.amount × 100\n  v_plan_amount  integer;\n  v_anom         uuid;\n  v_canon        jsonb;\n  v_roomres      jsonb;\n  v_room_id      uuid;\n  v_sub_id       uuid;\n  v_room_found   boolean := false;\n  v_room_new_sub uuid;        -- Phase 2 보정 후보(subscription_id)\n  v_room_new_pay uuid;        -- Phase 2 보정 후보(payment_id)\n  v_room_dirty   boolean := false;\nBEGIN\n  IF p_payment_id IS NULL OR p_plan_id IS NULL OR p_expected_amount_cents IS NULL THEN\n    RAISE EXCEPTION ''p_payment_id, p_plan_id, p_expected_amount_cents are required'';\n  END IF;\n\n  -- 1) payments FOR UPDATE — §12.2/[C3]: 레거시와 동일하게 payments 를 먼저 잠근다\n  SELECT p.id, p.user_id, p.mentor_id, p.status, p.kind, p.amount, p.currency, p.plan_id\n    INTO p_rec\n    FROM public.payments p WHERE p.id = p_payment_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAYMENT_NOT_FOUND'');\n  END IF;\n  IF p_rec.user_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAYMENT_NO_USER'');\n  END IF;\n  IF p_rec.mentor_id IS NULL THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAYMENT_NO_MENTOR'');\n  END IF;\n  -- 결제 시점 불변 동의 금액 검증(§7 F12 — 구현 결정: 사전 동명 재사용, anomaly 미기록)\n  IF p_rec.kind IS DISTINCT FROM ''subscription'' THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAYMENT_KIND_INVALID'');\n  END IF;\n  IF p_rec.currency IS DISTINCT FROM ''KRW''\n     OR p_rec.amount IS NULL OR p_rec.amount <= 0 OR p_rec.amount <> trunc(p_rec.amount) THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PAYMENT_STATE_UNEXPECTED'');\n  END IF;\n  v_intent := (p_rec.amount * 100)::bigint;\n\n  -- 2) 재생 판정 — succeeded 계열이면 재생 계약(Phase 1/2)으로 분기(정본 재호출 금지)\n  IF p_rec.status = ANY(v_succeeded) THEN\n    -- ── Phase 1: 검증 전용 (business-state 쓰기 금지 · anomaly INSERT 만 허용) ──\n    -- 1·2. subscription 행 확인·잠금 (최신 결제 정본은 오직 last_payment_id — 추론 금지)\n    SELECT s.id, s.student_id, s.mentor_id, s.last_payment_id\n      INTO v_sub\n      FROM public.subscriptions s\n     WHERE s.student_id = p_rec.user_id AND s.mentor_id = p_rec.mentor_id\n     FOR UPDATE;\n    IF NOT FOUND THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, NULL, ''SUCCEEDED_NO_SUBSCRIPTION'', ''F12 replay: succeeded payment without subscription'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUCCEEDED_NO_SUBSCRIPTION'', ''anomaly_id'', v_anom);\n    END IF;\n    -- 3. P 자신의 원장 행 확인\n    SELECT l.user_id, l.delta_cents, l.reason, l.ref_type, l.ref_id\n      INTO v_led\n      FROM public.cash_ledger l\n     WHERE l.idempotency_key = ''sub_debit_'' || p_payment_id::text;\n    IF NOT FOUND THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, v_sub.id, ''SUCCEEDED_NO_LEDGER'', ''F12 replay: succeeded payment without ledger debit'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUCCEEDED_NO_LEDGER'', ''anomaly_id'', v_anom);\n    END IF;\n    -- 4. P 의 payment–plan 결속 (필수 관계 — NULL 은 일치가 아니라 명시 거부)\n    IF p_rec.plan_id IS NULL OR p_rec.plan_id <> p_plan_id THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)\n      VALUES (p_payment_id, v_sub.id, ''PLAN_BINDING_MISMATCH'', ''F12 replay: payments.plan_id <> p_plan_id'',\n              jsonb_build_object(''plan_id'', p_plan_id), jsonb_build_object(''plan_id'', p_rec.plan_id))\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_BINDING_MISMATCH'', ''anomaly_id'', v_anom);\n    END IF;\n    -- 5. P 의 payment–subscription 당사자 결속\n    IF p_rec.user_id <> v_sub.student_id OR p_rec.mentor_id <> v_sub.mentor_id THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, v_sub.id, ''PARTY_BINDING_MISMATCH'', ''F12 replay: P party mismatch'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PARTY_BINDING_MISMATCH'', ''anomaly_id'', v_anom);\n    END IF;\n    -- 6. ledger–subscription 결속 (필수 관계 — NULL 명시 거부)\n    IF v_led.user_id IS NULL OR v_led.user_id <> p_rec.user_id\n       OR v_led.ref_id IS NULL OR v_led.ref_id <> v_sub.id THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)\n      VALUES (p_payment_id, v_sub.id, ''LEDGER_BINDING_MISMATCH'', ''F12 replay: ledger user/ref binding mismatch'',\n              jsonb_build_object(''user_id'', p_rec.user_id, ''ref_id'', v_sub.id),\n              jsonb_build_object(''user_id'', v_led.user_id, ''ref_id'', v_led.ref_id))\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''LEDGER_BINDING_MISMATCH'', ''anomaly_id'', v_anom);\n    END IF;\n    -- 7. 원장 필드값 대조 — 기준은 결제 시점 불변 동의 금액(payments.amount×100).\n    --    현재 플랜 가격을 읽지 않는다(가격 변경 후 정당한 재시도 오탐 금지 — T-CONC-09).\n    IF v_led.delta_cents IS DISTINCT FROM -v_intent\n       OR coalesce(v_led.reason, '''') <> ''subscription_payment''\n       OR coalesce(v_led.ref_type, '''') <> ''subscriptions'' THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)\n      VALUES (p_payment_id, v_sub.id, ''LEDGER_FIELD_MISMATCH'', ''F12 replay: ledger field mismatch vs intent amount'',\n              jsonb_build_object(''user_id'', p_rec.user_id, ''ref_id'', v_sub.id, ''ref_type'', ''subscriptions'',\n                                 ''reason'', ''subscription_payment'', ''delta_cents'', -v_intent),\n              jsonb_build_object(''user_id'', v_led.user_id, ''ref_id'', v_led.ref_id, ''ref_type'', v_led.ref_type,\n                                 ''reason'', v_led.reason, ''delta_cents'', v_led.delta_cents))\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''LEDGER_FIELD_MISMATCH'', ''anomaly_id'', v_anom);\n    END IF;\n    -- 8. C = subscription.last_payment_id 유효성 (detail 은 anomaly 에만 — 코드는 1종 고정)\n    IF v_sub.last_payment_id IS NULL THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, v_sub.id, ''SUBSCRIPTION_REF_INVALID'', ''LAST_PAYMENT_ID_NULL'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_REF_INVALID'', ''anomaly_id'', v_anom);\n    END IF;\n    SELECT p2.id, p2.user_id, p2.mentor_id, p2.status\n      INTO v_c FROM public.payments p2 WHERE p2.id = v_sub.last_payment_id;\n    IF NOT FOUND THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, v_sub.id, ''SUBSCRIPTION_REF_INVALID'', ''LAST_PAYMENT_NOT_FOUND'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_REF_INVALID'', ''anomaly_id'', v_anom);\n    END IF;\n    IF NOT (v_c.status = ANY(v_succeeded)) THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, v_sub.id, ''SUBSCRIPTION_REF_INVALID'', ''LAST_PAYMENT_NOT_SUCCEEDED'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''SUBSCRIPTION_REF_INVALID'', ''anomaly_id'', v_anom);\n    END IF;\n    -- C 당사자 불일치는 8단계 PARTY_BINDING_MISMATCH (LEDGER_BINDING 으로 뭉개지 않는다)\n    IF v_c.user_id IS NULL OR v_c.user_id <> v_sub.student_id\n       OR v_c.mentor_id IS NULL OR v_c.mentor_id <> v_sub.mentor_id THEN\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, v_sub.id, ''PARTY_BINDING_MISMATCH'', ''F12 replay: C party mismatch'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PARTY_BINDING_MISMATCH'', ''anomaly_id'', v_anom);\n    END IF;\n    -- 9. room 참조 판정 (쓰기 없음 — 보정 예정값 후보만 계산)\n    SELECT r.id, r.subscription_id, r.payment_id\n      INTO v_room\n      FROM public.mentor_student_rooms r\n     WHERE r.student_id = v_sub.student_id AND r.mentor_id = v_sub.mentor_id\n     FOR UPDATE;\n    v_room_found := FOUND;\n    IF v_room_found THEN\n      IF v_room.subscription_id IS NULL THEN\n        v_room_new_sub := v_sub.id; v_room_dirty := true;\n      ELSIF v_room.subscription_id <> v_sub.id THEN\n        INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)\n        VALUES (p_payment_id, v_sub.id, ''ROOM_REF_MISMATCH'', ''F12 replay: room.subscription_id conflict'',\n                jsonb_build_object(''subscription_id'', v_sub.id),\n                jsonb_build_object(''subscription_id'', v_room.subscription_id))\n        RETURNING id INTO v_anom;\n        RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROOM_REF_MISMATCH'', ''anomaly_id'', v_anom);\n      ELSE\n        v_room_new_sub := v_room.subscription_id;\n      END IF;\n      IF v_room.payment_id IS NULL THEN\n        v_room_new_pay := v_sub.last_payment_id; v_room_dirty := true;                  -- NULL → C 로 복구 후보\n      ELSIF v_room.payment_id = v_sub.last_payment_id THEN\n        v_room_new_pay := v_room.payment_id;                                            -- C 동일 → 유지\n      ELSIF v_room.payment_id = p_payment_id AND p_payment_id <> v_sub.last_payment_id THEN\n        v_room_new_pay := v_sub.last_payment_id; v_room_dirty := true;                  -- stale → C 로 교체 후보\n      ELSE\n        INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)\n        VALUES (p_payment_id, v_sub.id, ''ROOM_REF_MISMATCH'', ''F12 replay: room.payment_id references third payment'',\n                jsonb_build_object(''payment_id_c'', v_sub.last_payment_id, ''payment_id_p'', p_payment_id),\n                jsonb_build_object(''payment_id'', v_room.payment_id))\n        RETURNING id INTO v_anom;\n        RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROOM_REF_MISMATCH'', ''anomaly_id'', v_anom);\n      END IF;\n    END IF;\n\n    -- ── Phase 2: 검증 전부 통과 후에만 room 확보·보정 (참조 복구 — 자금 반복 0) ──\n    BEGIN\n      IF NOT v_room_found THEN\n        v_roomres := core_private.ensure_student_mentor_room(\n                       v_sub.student_id, v_sub.mentor_id,\n                       p_payment_id => v_sub.last_payment_id,\n                       p_subscription_id => v_sub.id,\n                       p_require_entitlement => false);\n        IF NOT coalesce((v_roomres->>''ok'')::boolean, false) THEN\n          RAISE EXCEPTION ''S2_M9_ROOM_STEP_FAILED'';\n        END IF;\n        v_room_id := (v_roomres->>''room_id'')::uuid;\n        -- 동시 생성 경합 포함 재확인: NULL 참조만 채운다(F10 은 기존 방 참조를 덮어쓰지 않음)\n        UPDATE public.mentor_student_rooms r\n           SET subscription_id = coalesce(r.subscription_id, v_sub.id),\n               payment_id      = coalesce(r.payment_id, v_sub.last_payment_id)\n         WHERE r.id = v_room_id;\n      ELSE\n        v_room_id := v_room.id;\n        IF v_room_dirty THEN\n          UPDATE public.mentor_student_rooms r\n             SET subscription_id = v_room_new_sub,\n                 payment_id      = v_room_new_pay\n           WHERE r.id = v_room_id;\n        END IF;\n      END IF;\n      PERFORM core_private.record_initial_subscription_billing_event(p_payment_id, v_sub.id, false);\n    EXCEPTION WHEN OTHERS THEN\n      IF SQLERRM = ''BILLING_EVENT_BINDING_MISMATCH'' THEN RAISE; END IF;\n      -- 운영 오류(9단계와 별도): 자금·원장·구독·결제 성공 상태는 건드리지 않고,\n      -- room 부분 변경은 이 블록에서 롤백되며, 재시도 가능하다(§7 F12 재생 결과)\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROOM_ENSURE_FAILED'');\n    END;\n\n    RETURN jsonb_build_object(''ok'', true, ''contract_version'', 1, ''idempotent'', true,\n                              ''subscription_id'', v_sub.id, ''payment_status'', ''succeeded'',\n                              ''room_id'', v_room_id);\n  END IF;\n\n  -- ── 최초 실행 경로 ──\n  -- 3) advisory (정본과 동일 인자 형식 — 전환기 잠금 순서 일치 [C3])\n  PERFORM pg_advisory_xact_lock(hashtext(p_rec.user_id::text), hashtext(p_rec.mentor_id::text));\n  -- 4) mentor_plans FOR UPDATE — 5)~6) 내내 유지되어 TOCTOU 차단(멘토 UPDATE 대기, T-CONC-04)\n  SELECT mp.amount_cents INTO v_plan_amount\n    FROM public.mentor_plans mp WHERE mp.id = p_plan_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_NOT_FOUND'');\n  END IF;\n  -- 5) 3자 일치: payments.amount×100 = p_expected_amount_cents = 잠근 amount_cents\n  IF v_intent <> p_expected_amount_cents OR v_intent <> v_plan_amount THEN\n    RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_AMOUNT_CHANGED'',\n                              ''expected_amount_cents'', p_expected_amount_cents,\n                              ''actual_amount_cents'', v_plan_amount);\n  END IF;\n  -- 6)~7) 정본 호출 + 방 확보 — 한 subtransaction: 방 확보 실패 시 자금·원장·구독·\n  --       결제 변경 전부 롤백(rev 8 A-2 §3). 정본 raise 는 잡아 동명 envelope 변환.\n  BEGIN\n    v_canon := public.confirm_subscription_checkout(p_payment_id, p_plan_id, p_idempotency_key);\n    IF NOT coalesce((v_canon->>''ok'')::boolean, false) THEN\n      -- 정본 envelope 실패(CASH_INSUFFICIENT·anomaly 계열): 금융 변경은 정본 내부에서\n      -- 이미 롤백됨 — anomaly 행만 유지한 채 그대로 승격 반환\n      RETURN v_canon || jsonb_build_object(''contract_version'', 1);\n    END IF;\n    v_sub_id := (v_canon->>''subscription_id'')::uuid;\n    v_roomres := core_private.ensure_student_mentor_room(\n                   p_rec.user_id, p_rec.mentor_id,\n                   p_payment_id => p_payment_id,\n                   p_subscription_id => v_sub_id,\n                   p_require_entitlement => false);\n    IF NOT coalesce((v_roomres->>''ok'')::boolean, false) THEN\n      RAISE EXCEPTION ''S2_M9_ROOM_STEP_FAILED'';\n    END IF;\n    v_room_id := (v_roomres->>''room_id'')::uuid;\n    -- room 참조 규칙(신규 결제 — §7 F12 표): pair 불변 · subscription_id NULL 이면\n    -- 채움/다른 값이면 거부 · payment_id 는 현재 결제로 갱신(최신 참조 의미론)\n    SELECT r.id, r.subscription_id, r.payment_id INTO v_room\n      FROM public.mentor_student_rooms r WHERE r.id = v_room_id FOR UPDATE;\n    IF v_room.subscription_id IS NOT NULL AND v_room.subscription_id <> v_sub_id THEN\n      RAISE EXCEPTION ''S2_M9_ROOM_REF_CONFLICT'';\n    END IF;\n    UPDATE public.mentor_student_rooms r\n       SET subscription_id = coalesce(r.subscription_id, v_sub_id),\n           payment_id      = p_payment_id\n     WHERE r.id = v_room_id;\n    PERFORM core_private.record_initial_subscription_billing_event(p_payment_id, v_sub_id, true);\n  EXCEPTION WHEN OTHERS THEN\n    IF sqlerrm LIKE ''%S2_M9_ROOM_REF_CONFLICT%'' THEN\n      -- 초기 경로 room 참조 충돌 = 거부(§7 F12 표) — 자금 변경은 위 블록에서 전부 롤백됨\n      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)\n      VALUES (p_payment_id, v_sub_id, ''ROOM_REF_MISMATCH'', ''F12 initial: room.subscription_id conflict'')\n      RETURNING id INTO v_anom;\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROOM_REF_MISMATCH'', ''anomaly_id'', v_anom);\n    ELSIF sqlerrm LIKE ''%S2_M9_ROOM_STEP_FAILED%'' THEN\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROOM_ENSURE_FAILED'');\n    ELSIF sqlerrm = ANY(v_canon_raises) THEN\n      RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', sqlerrm);\n    ELSE\n      RAISE;  -- 사전 밖 예외는 그대로 전파(§8.2)\n    END IF;\n  END;\n\n  -- 8) 성공: 기존 정본 반환 + contract_version + room_id (§8.3 F12 행)\n  RETURN v_canon || jsonb_build_object(''contract_version'', 1, ''room_id'', v_room_id);\nEND $function$\n;\nrevoke all on function core_private.subscription_checkout_confirm_impl(uuid,uuid,integer,text) from public,anon,authenticated,service_role;\n\ncreate or replace function api_web_v1.subscription_checkout_confirm_v2(p_payment_id uuid,p_plan_id uuid,p_expected_amount_cents integer,p_idempotency_key text default null)\n returns jsonb language sql security definer set search_path = '''' as $fn$\n select core_private.subscription_checkout_confirm_impl(p_payment_id,p_plan_id,p_expected_amount_cents,p_idempotency_key)\n $fn$;\n revoke all on function api_web_v1.subscription_checkout_confirm_v2(uuid,uuid,integer,text) from public,anon,authenticated;\n grant execute on function api_web_v1.subscription_checkout_confirm_v2(uuid,uuid,integer,text) to service_role;\n\ncreate or replace function api_web_v1.subscription_checkout_confirm_v3(p_payment_id uuid,p_plan_id uuid,p_expected_amount_cents integer,p_idempotency_key text default null)\n returns jsonb language sql security definer set search_path = '''' as $fn$\n select core_private.subscription_checkout_confirm_impl(p_payment_id,p_plan_id,p_expected_amount_cents,p_idempotency_key)\n $fn$;\n revoke all on function api_web_v1.subscription_checkout_confirm_v3(uuid,uuid,integer,text) from public,anon,authenticated;\n grant execute on function api_web_v1.subscription_checkout_confirm_v3(uuid,uuid,integer,text) to service_role;\nCREATE OR REPLACE FUNCTION api_app_v1.subscribe_with_cash(p_mentor_id uuid, p_tier text, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_tier text := lower(btrim(coalesce(p_tier, '''')));\n  v_key text := btrim(coalesce(p_idempotency_key, ''''));\n  v_ext text;\n  v_succeeded constant text[] := array[''succeeded'',''paid'',''success'',''complete'',''captured''];\n  -- 롤백 후에도 운영 진단을 위해 anomaly 를 다시 기록할 코드(정본·F12 anomaly 계열)\n  v_anomaly_codes constant text[] := array[''FINANCIAL_WRITE_ERROR'',''LEDGER_FIELD_MISMATCH'',''ROOM_ENSURE_FAILED'',''ROOM_REF_MISMATCH'',\n    ''PLAN_AMOUNT_CHANGED'',''SUCCEEDED_NO_SUBSCRIPTION'',''SUCCEEDED_NO_LEDGER'',''PLAN_BINDING_MISMATCH'',''PARTY_BINDING_MISMATCH'',\n    ''LEDGER_BINDING_MISMATCH'',''SUBSCRIPTION_REF_INVALID'',''LEDGER_AMOUNT_MISMATCH''];\n  v_role text; v_status text; v_susp timestamptz; v_norm text;\n  v_mrole text;\n  v_act text; v_pause_until timestamptz; v_open boolean;\n  v_dup uuid;\n  v_plan_id uuid; v_plan_active boolean; v_amount integer;\n  v_cap_used numeric; v_cap_limit numeric; v_cap_weight numeric;\n  v_balance bigint;\n  v_pay record;\n  v_payment_id uuid;\n  v_res jsonb;\n  v_abort_code text;\n  v_abort_detail jsonb;\n  v_sub_id uuid; v_room_id uuid; v_reactivated boolean;\n  v_sub record; v_ledger record;\n  v_period_start timestamptz; v_period_end timestamptz;\n  v_event_id uuid;\n  v_balance_after bigint;\n  v_result jsonb;\n  v_anom uuid;\nbegin\n  if v_uid is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''AUTH_REQUIRED'');\n  end if;\n  if p_mentor_id is null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_FOUND'');\n  end if;\n  if v_tier not in (''limited'', ''standard'', ''premium'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_TIER_INVALID'');\n  end if;\n  if v_key = '''' or char_length(v_key) > 128 then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''IDEMPOTENCY_KEY_INVALID'');\n  end if;\n  v_ext := ''sub_app_'' || v_key;\n\n  -- 직렬화: (학생, 키) — 같은 키 동시 재시도는 첫 호출 커밋 뒤 재생으로 수렴 · (학생, 멘토) — 정본과 같은 pair 잠금(재진입)\n  perform pg_advisory_xact_lock(hashtext(''app_sub_key:'' || v_uid::text), hashtext(v_key));\n  perform pg_advisory_xact_lock(hashtext(v_uid::text), hashtext(p_mentor_id::text));\n\n  -- 멱등 재생 — 성공한 첫 결과를 그대로(차감 0). 실패 시도는 행을 남기지 않으므로 여기 오면 성공 행뿐이다.\n  select p.id, p.status, p.mentor_id, p.metadata into v_pay\n    from public.payments p\n   where p.user_id = v_uid and p.external_id = v_ext\n   order by p.created_at desc\n   limit 1\n   for update;\n  if found then\n    if v_pay.status = any(v_succeeded) and (v_pay.metadata ? ''app_result'') then\n      if v_pay.mentor_id is distinct from p_mentor_id or (v_pay.metadata ->> ''planTier'') is distinct from v_tier then\n        return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''IDEMPOTENCY_KEY_CONFLICT'',\n                                  ''payment_id'', v_pay.id);\n      end if;\n      return (v_pay.metadata -> ''app_result'') || jsonb_build_object(''idempotent'', true);\n    end if;\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''IDEMPOTENCY_KEY_CONFLICT'',\n                              ''payment_id'', v_pay.id, ''payment_status'', v_pay.status);\n  end if;\n\n  -- 학생 · 계정 상태 (F10·정본과 동일 판정식)\n  select u.role, u.status, u.suspended_until into v_role, v_status, v_susp from public.users u where u.id = v_uid;\n  if not found or v_role is distinct from ''student'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ROLE_NOT_STUDENT'');\n  end if;\n  v_norm := lower(btrim(coalesce(v_status, '''')));\n  if v_norm = ''banned'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_BANNED'');\n  end if;\n  if v_norm = ''suspended'' and (v_susp is null or v_susp > now()) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_SUSPENDED'');\n  end if;\n  if v_norm not in (''active'', ''suspended'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_NOT_ACTIVE'');\n  end if;\n  if public.account_deletion_write_blocked(v_uid) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ACCOUNT_DELETION_IN_PROGRESS'');\n  end if;\n\n  -- 멘토: 역할 · 승인 · 활동 상태(웹 mentorActivityState 동일) · 구독 열림\n  select u.role into v_mrole from public.users u where u.id = p_mentor_id;\n  if not found or v_mrole is distinct from ''mentor'' then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_FOUND'');\n  end if;\n  if not public.individual_question_user_is_approved_mentor(p_mentor_id) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_APPROVED'');\n  end if;\n  select mp.activity_status, mp.pause_until, mp.is_open_for_subscriptions into v_act, v_pause_until, v_open\n    from public.mentor_profiles mp where mp.user_id = p_mentor_id;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_FOUND'');\n  end if;\n  v_act := lower(btrim(coalesce(v_act, ''active'')));\n  if v_act in (''terminating'', ''terminated'') then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_TERMINATED'');\n  end if;\n  if v_act = ''paused'' and (v_pause_until is null or v_pause_until > now()) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_PAUSED'', ''pause_until'', v_pause_until);\n  end if;\n  if not coalesce(v_open, true) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS'');\n  end if;\n  -- 상호 차단(F10 ③ 과 같은 판정) — 웹은 이 경우 F12 의 방 확보 단계에서 ROOM_ENSURE_FAILED 로 실패한다(차감 0). 앱에는 코드로 먼저 알린다.\n  if exists (select 1 from public.user_blocks b\n              where (b.blocker_id = v_uid and b.blocked_id = p_mentor_id) or (b.blocker_id = p_mentor_id and b.blocked_id = v_uid)) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''BLOCKED'');\n  end if;\n\n  -- 중복 구독 (활성 pair 1행 모델)\n  select s.id into v_dup from public.subscriptions s\n   where s.student_id = v_uid and s.mentor_id = p_mentor_id and lower(coalesce(s.status, '''')) = ''active'';\n  if v_dup is not null then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''ALREADY_SUBSCRIBED'', ''subscription_id'', v_dup);\n  end if;\n\n  -- 요금제 행 = 실차감액 (멘토가 정한 값 · 잠금은 F12 가 다시 건다)\n  select mp.id, mp.is_active, mp.amount_cents into v_plan_id, v_plan_active, v_amount\n    from public.mentor_plans mp where mp.mentor_id = p_mentor_id and mp.plan_tier = v_tier;\n  if not found then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_NOT_FOUND'', ''plan_tier'', v_tier);\n  end if;\n  if not coalesce(v_plan_active, true) then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_INACTIVE'', ''plan_tier'', v_tier);\n  end if;\n  if v_amount is null or v_amount <= 0 or v_amount % 100 <> 0 then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''PLAN_AMOUNT_INVALID'', ''plan_tier'', v_tier);\n  end if;\n\n  -- 정원 (정본 판정식 그대로 — DB 함수 3종 · 최종 방어는 enforce_mentor_cap 트리거)\n  v_cap_used := public.mentor_cap_used(p_mentor_id);\n  v_cap_weight := public.subscription_cap_weight(v_tier);\n  v_cap_limit := public.mentor_cap_limit(p_mentor_id);\n  if v_cap_used + v_cap_weight > v_cap_limit then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''MENTOR_CAP_EXCEEDED'',\n                              ''cap_used'', v_cap_used, ''cap_weight'', v_cap_weight, ''cap_limit'', v_cap_limit);\n  end if;\n\n  -- 잔액 (사전 판정 — 실제 차감의 원자 판정은 record_subscription_cash_debit)\n  select w.balance_cents into v_balance from public.cash_wallets w where w.user_id = v_uid;\n  v_balance := coalesce(v_balance, 0);\n  if v_balance < v_amount then\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''CASH_INSUFFICIENT'',\n                              ''required_cents'', v_amount, ''balance_cents'', v_balance, ''shortfall_cents'', v_amount - v_balance);\n  end if;\n\n  -- 자금 단계 — 한 subtransaction: intent → F12(정본 confirm + 방) → initial billing event. 실패 시 전부 롤백.\n  begin\n    insert into public.payments (user_id, mentor_id, status, amount, currency, kind, plan_id, external_id, metadata)\n    values (v_uid, p_mentor_id, ''pending'', (v_amount::numeric / 100), ''KRW'', ''subscription'', v_plan_id, v_ext,\n            jsonb_build_object(''planTier'', v_tier, ''planId'', v_plan_id::text, ''source'', ''app_subscribe_with_cash'',\n                               ''expected_amount_cents'', v_amount, ''idempotency_key'', v_key))\n    returning id into v_payment_id;\n\n    v_res := api_web_v1.subscription_checkout_confirm_v3(v_payment_id, v_plan_id, v_amount, ''sub_checkout_'' || v_payment_id::text);\n    if not coalesce((v_res ->> ''ok'')::boolean, false) then\n      v_abort_code := coalesce(v_res ->> ''code'', ''FINANCIAL_WRITE_ERROR'');\n      v_abort_detail := v_res - ''ok'' - ''contract_version'' - ''code'';\n      raise exception ''APP_SUB_ABORT'';\n    end if;\n    v_sub_id := (v_res ->> ''subscription_id'')::uuid;\n    v_room_id := (v_res ->> ''room_id'')::uuid;\n    v_reactivated := coalesce((v_res ->> ''reactivated'')::boolean, false);\n\n    -- Same external app contract; the common checkout implementation owns the billing event.\n    select s.current_period_start, s.current_period_end, s.next_billing_at into v_sub\n      from public.subscriptions s where s.id = v_sub_id;\n\n    select w.balance_cents into v_balance_after from public.cash_wallets w where w.user_id = v_uid;\n    v_result := jsonb_build_object(\n      ''ok'', true, ''contract_version'', 1, ''idempotent'', false,\n      ''subscription_id'', v_sub_id, ''room_id'', v_room_id, ''payment_id'', v_payment_id,\n      ''plan_id'', v_plan_id, ''plan_tier'', v_tier,\n      ''debited_cents'', v_amount, ''balance_after_cents'', coalesce(v_balance_after, 0),\n      ''reactivated'', v_reactivated,\n      ''current_period_start'', v_sub.current_period_start, ''current_period_end'', v_sub.current_period_end,\n      ''next_billing_at'', v_sub.next_billing_at);\n    -- 재생용 첫 결과 보존 (정본이 넣은 planId/subscription_id 는 그대로 두고 app_result 만 덧붙인다)\n    update public.payments p\n       set metadata = coalesce(p.metadata, ''{}''::jsonb) || jsonb_build_object(''app_result'', v_result)\n     where p.id = v_payment_id;\n  exception when others then\n    if sqlerrm <> ''APP_SUB_ABORT'' then\n      raise;   -- 사전 밖 예외는 그대로 전파(§8.2)\n    end if;\n  end;\n\n  if v_abort_code is not null then\n    -- 이 시도의 payments·anomaly 행은 위 블록과 함께 롤백됐다. 이상 계열은 운영 진단용으로 다시 기록한다(payment_id 없음).\n    if v_abort_code = any(v_anomaly_codes) then\n      insert into public.subscription_checkout_anomalies (payment_id, subscription_id, code, detail, expected, found)\n      values (null, null, v_abort_code, ''api_app_v1.subscribe_with_cash aborted (intent rolled back)'',\n              jsonb_build_object(''student_id'', v_uid, ''mentor_id'', p_mentor_id, ''plan_id'', v_plan_id, ''plan_tier'', v_tier,\n                                 ''amount_cents'', v_amount, ''idempotency_key'', v_key),\n              v_abort_detail)\n      returning id into v_anom;\n      return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', v_abort_code, ''anomaly_id'', v_anom);\n    end if;\n    if v_abort_code = ''CASH_INSUFFICIENT'' then\n      select w.balance_cents into v_balance from public.cash_wallets w where w.user_id = v_uid;\n      v_balance := coalesce(v_balance, 0);\n      return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', ''CASH_INSUFFICIENT'',\n                                ''required_cents'', v_amount, ''balance_cents'', v_balance,\n                                ''shortfall_cents'', greatest(0, v_amount - v_balance));\n    end if;\n    return jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', v_abort_code) || coalesce(v_abort_detail, ''{}''::jsonb);\n  end if;\n\n  return v_result;\nend\n$function$\n;\n\n\ncreate or replace function public.subscription_renewal_quote(p_subscription_id uuid)\nreturns table(subscription_id uuid,plan_id uuid,plan_tier text,amount_cents bigint,next_billing_at timestamptz)\nlanguage sql stable security definer set search_path = '''' as $fn$\n select s.id,p.id,p.plan_tier,p.amount_cents::bigint,s.next_billing_at\n from public.subscriptions s join public.mentor_plans p\n on p.id=s.plan_id and p.mentor_id=s.mentor_id and p.plan_tier=s.plan_tier\n where s.id=p_subscription_id and p.amount_cents>0 and p.amount_cents%100=0\n$fn$;\nrevoke all on function public.subscription_renewal_quote(uuid) from public,anon,authenticated;\ngrant execute on function public.subscription_renewal_quote(uuid) to service_role;\n\ncreate or replace function public.record_subscription_renewal_notice(\n p_subscription_id uuid,p_period_end timestamptz,p_at timestamptz default now()) returns jsonb language plpgsql security definer set search_path = '''' as $fn$\ndeclare s public.subscriptions%rowtype; p public.mentor_plans%rowtype; v_id uuid; v_key text;\nbegin\n select * into s from public.subscriptions where id=p_subscription_id for update;\n if s.id is null or p_period_end is null or p_at is null or s.status <> ''active''\n    or s.cancel_at_period_end or s.current_period_end is distinct from p_period_end\n    or s.next_billing_at is null or s.next_billing_at<=p_at then\n   return jsonb_build_object(''ok'',false,''code'',''not_notice_eligible'');\n end if;\n select * into p from public.mentor_plans where id=s.plan_id for share;\n if p.id is null or p.mentor_id is distinct from s.mentor_id or p.plan_tier is distinct from s.plan_tier\n    or p.amount_cents is null or p.amount_cents<=0 or p.amount_cents%100<>0 then\n   return jsonb_build_object(''ok'',false,''code'',''price_unavailable'');\n end if;\n v_key := ''sub_renewal_notice:''||s.id::text||'':''||to_char(p_period_end at time zone ''UTC'',''YYYY-MM-DD'');\n insert into public.subscription_billing_events\n   (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,amount_cents,\n    plan_tier,plan_id,idempotency_key,failure_code,failure_message,attempt_count,created_at,processed_at)\n values(s.id,s.student_id,s.mentor_id,''renewal'',''skipped'',s.current_period_start,s.current_period_end,s.next_billing_at,\n        p.amount_cents,p.plan_tier,p.id,v_key,''pre_renewal_notice_sent'',''pre-renewal notice marker'',0,p_at,p_at)\n on conflict(idempotency_key) do nothing returning id into v_id;\n return jsonb_build_object(''ok'',true,''code'',case when v_id is null then ''already'' else ''sent'' end);\nend $fn$;\nrevoke all on function public.record_subscription_renewal_notice(uuid,timestamptz,timestamptz) from public,anon,authenticated;\ngrant execute on function public.record_subscription_renewal_notice(uuid,timestamptz,timestamptz) to service_role;\n\ncreate or replace function public.process_subscription_renewal_v2(\n p_subscription_id uuid,p_period_end timestamptz,p_idempotency_key text,p_processed_at timestamptz default now()) returns table(ok boolean,code text,message text,billing_event_id uuid,ledger_id uuid,\n next_period_start timestamptz,next_period_end timestamptz,wallet_balance_cents bigint,attempt_count integer)\nlanguage plpgsql security definer set search_path = '''' as $fn$\ndeclare\n s public.subscriptions%rowtype; p public.mentor_plans%rowtype;\n e public.subscription_billing_events%rowtype; l public.cash_ledger%rowtype;\n v_student uuid; v_mentor uuid; v_amount bigint; v_balance bigint; v_end timestamptz;\n v_key text; v_notice public.subscription_billing_events%rowtype;\nbegin\n if p_subscription_id is null or p_period_end is null or p_processed_at is null then\n   return query select false,''invalid_subscription''::text,''subscription, period and time are required''::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;\n end if;\n v_key := ''sub_renewal:''||p_subscription_id::text||'':''||to_char(p_period_end at time zone ''UTC'',''YYYY-MM-DD'');\n if p_idempotency_key is distinct from v_key or char_length(p_idempotency_key)>128 then\n   return query select false,''invalid_idempotency_key''::text,''key must identify this subscription period''::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;\n end if;\n -- Match checkout''s pair mutex before row locks. No stale client snapshot decides eligibility.\n select student_id,mentor_id into v_student,v_mentor from public.subscriptions where id=p_subscription_id;\n if v_student is null then\n   return query select false,''not_found''::text,''subscription not found''::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;\n end if;\n perform pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));\n select * into s from public.subscriptions where id=p_subscription_id for update;\n if s.id is null or s.student_id is distinct from v_student or s.mentor_id is distinct from v_mentor then\n   raise exception ''SUBSCRIPTION_BINDING_MISMATCH'';\n end if;\n select * into e from public.subscription_billing_events where idempotency_key=v_key for update;\n if e.id is not null then\n   if e.subscription_id is distinct from s.id or e.student_id is distinct from s.student_id\n      or e.mentor_id is distinct from s.mentor_id or e.period_start is distinct from p_period_end\n      or e.event_type not in (''renewal'',''renewal_failed'') then\n     raise exception ''BILLING_EVENT_BINDING_MISMATCH'';\n   end if;\n   if e.status=''succeeded'' then\n     select * into l from public.cash_ledger where id=e.ledger_id;\n     if l.id is null or l.delta_cents is distinct from -e.amount_cents::bigint\n        or l.user_id is distinct from s.student_id or l.ref_id is distinct from s.id\n        or l.idempotency_key is distinct from v_key or l.reason is distinct from ''subscription_renewal'' then\n       raise exception ''LEDGER_BINDING_MISMATCH'';\n     end if;\n     return query select true,''already_succeeded''::text,''renewal already processed''::text,e.id,l.id,e.period_start,e.period_end,null::bigint,e.attempt_count; return;\n   end if;\n   if e.status not in (''failed'',''skipped'') then\n     return query select false,''already_processing''::text,''renewal is already processing''::text,e.id,e.ledger_id,e.period_start,e.period_end,null::bigint,e.attempt_count; return;\n   end if;\n end if;\n if s.status not in (''active'',''past_due'') or s.cancel_at_period_end\n    or (s.status=''past_due'' and s.grace_until is not null and s.grace_until<=p_processed_at)\n    or s.current_period_end is distinct from p_period_end or s.next_billing_at is null\n    or s.next_billing_at>p_processed_at or p_period_end>p_processed_at then\n   return query select false,''not_renewal_eligible''::text,''subscription state or period changed''::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;\n end if;\n select * into p from public.mentor_plans where id=s.plan_id for share;\n if p.id is null or p.mentor_id is distinct from s.mentor_id or p.plan_tier is distinct from s.plan_tier\n    or p.amount_cents is null or p.amount_cents<=0 or p.amount_cents%100<>0 then\n   return query select false,''price_unavailable''::text,''plan price or binding unavailable''::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;\n end if;\n -- is_active controls NEW subscriptions only. Existing subscriptions may renew.\n v_amount := p.amount_cents;\n select * into v_notice from public.subscription_billing_events\n  where idempotency_key=''sub_renewal_notice:''||s.id::text||'':''||to_char(p_period_end at time zone ''UTC'',''YYYY-MM-DD'');\n if v_notice.id is not null and (v_notice.amount_cents is distinct from v_amount\n    or v_notice.plan_id is distinct from p.id or v_notice.plan_tier is distinct from p.plan_tier) then\n   return query select false,''price_changed_since_notice''::text,''renewal price differs from the sent notice''::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;\n end if;\n if exists(select 1 from public.cash_ledger where idempotency_key=v_key) then\n   raise exception ''LEDGER_WITHOUT_SUCCEEDED_EVENT'';\n end if;\n v_end := ((p_period_end at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul'');\n if e.id is null then\n   insert into public.subscription_billing_events\n    (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,\n     amount_cents,plan_tier,plan_id,idempotency_key,attempt_count,created_at)\n   values(s.id,s.student_id,s.mentor_id,''renewal'',''processing'',p_period_end,v_end,p_processed_at,\n          v_amount,p.plan_tier,p.id,v_key,1,p_processed_at) returning * into e;\n else\n   update public.subscription_billing_events b set event_type=''renewal'',status=''processing'',\n     amount_cents=v_amount,plan_id=p.id,plan_tier=p.plan_tier,billing_at=p_processed_at,\n     attempt_count=b.attempt_count+1,processed_at=null,failure_code=null,failure_message=null\n   where b.id=e.id returning b.* into e;\n end if;\n insert into public.cash_wallets(user_id,balance_cents) values(s.student_id,0) on conflict(user_id) do nothing;\n update public.cash_wallets w set balance_cents=w.balance_cents-v_amount\n   where w.user_id=s.student_id and w.balance_cents>=v_amount returning w.balance_cents into v_balance;\n if not found then\n   update public.subscription_billing_events b set event_type=''renewal_failed'',status=''failed'',\n     failure_code=''insufficient_cash'',failure_message=''CASH_INSUFFICIENT'',processed_at=p_processed_at where b.id=e.id;\n   update public.subscriptions set status=''past_due'',grace_until=coalesce(grace_until,p_processed_at+interval ''2 days''),\n     updated_at=p_processed_at,last_billing_event_id=e.id where id=s.id;\n   return query select false,''insufficient_cash''::text,''CASH_INSUFFICIENT''::text,e.id,null::uuid,p_period_end,v_end,null::bigint,e.attempt_count; return;\n end if;\n insert into public.cash_ledger(user_id,delta_cents,reason,ref_type,ref_id,idempotency_key,created_at)\n values(s.student_id,-v_amount,''subscription_renewal'',''subscriptions'',s.id,v_key,p_processed_at) returning * into l;\n update public.subscription_billing_events b set event_type=''renewal'',status=''succeeded'',ledger_id=l.id,\n   processed_at=p_processed_at,failure_code=null,failure_message=null where b.id=e.id;\n update public.subscriptions set status=''active'',current_period_start=p_period_end,current_period_end=v_end,\n   next_billing_at=v_end,last_renewed_at=p_processed_at,last_billing_event_id=e.id,grace_until=null,updated_at=p_processed_at where id=s.id;\n return query select true,''succeeded''::text,''renewal processed''::text,e.id,l.id,p_period_end,v_end,v_balance,e.attempt_count;\nend $fn$;\nrevoke all on function public.process_subscription_renewal_v2(uuid,timestamptz,text,timestamptz) from public,anon,authenticated;\ngrant execute on function public.process_subscription_renewal_v2(uuid,timestamptz,text,timestamptz) to service_role;\n\ndo $gate$ begin if md5(replace(pg_get_functiondef(''public.process_subscription_renewal(uuid,timestamptz,bigint,text,timestamptz)''::regprocedure),chr(13),'''')) <> ''f212d344d7dd8b51ac6b0860cfee9cff'' then raise exception ''FINANCIAL_SOURCE_DRIFT: public.process_subscription_renewal''; end if; end $gate$;\n\n-- Old web deployments retain their signature; caller supplied prices are ignored.\ncreate or replace function public.process_subscription_renewal(p_subscription_id uuid,p_period_end timestamptz,\n p_amount_cents bigint,p_idempotency_key text,p_processed_at timestamptz default now())\nreturns table(ok boolean,code text,message text,billing_event_id uuid,ledger_id uuid,next_period_start timestamptz,\n next_period_end timestamptz,wallet_balance_cents bigint,attempt_count integer)\nlanguage sql security definer set search_path = '''' as $fn$\n select * from public.process_subscription_renewal_v2(p_subscription_id,p_period_end,p_idempotency_key,p_processed_at)\n$fn$;\nrevoke all on function public.process_subscription_renewal(uuid,timestamptz,bigint,text,timestamptz) from public,anon,authenticated;\ngrant execute on function public.process_subscription_renewal(uuid,timestamptz,bigint,text,timestamptz) to service_role;\n\n\ncreate or replace function public.finalize_subscription_terminal_transition(\n p_subscription_id uuid,p_transition text,p_at timestamptz,p_idempotency_key text\n) returns jsonb language plpgsql security definer set search_path = '''' as $fn$\ndeclare s public.subscriptions%rowtype; e public.subscription_billing_events%rowtype; v_type text; v_key text;\nbegin\n if p_subscription_id is null or p_at is null or p_transition is null\n    or p_transition not in (''cancel_at_period_end'',''grace_expired'') then\n   return jsonb_build_object(''ok'',false,''code'',''invalid_transition'');\n end if;\n select * into s from public.subscriptions where id=p_subscription_id for update;\n if s.id is null then return jsonb_build_object(''ok'',false,''code'',''not_found''); end if;\n v_type := case p_transition when ''cancel_at_period_end'' then ''canceled'' else ''expired'' end;\n v_key := case p_transition when ''cancel_at_period_end'' then ''sub_cancel:'' else ''sub_expired:'' end\n          ||s.id::text||'':''||to_char(s.current_period_end at time zone ''UTC'',''YYYY-MM-DD'');\n if p_idempotency_key is distinct from v_key then\n   return jsonb_build_object(''ok'',false,''code'',''stale_transition'');\n end if;\n select * into e from public.subscription_billing_events where idempotency_key=v_key for update;\n if e.id is not null and (e.subscription_id is distinct from s.id or e.event_type is distinct from v_type\n    or e.period_end is distinct from s.current_period_end or e.status is distinct from ''succeeded'') then\n   raise exception ''BILLING_EVENT_BINDING_MISMATCH'';\n end if;\n if s.status=''expired'' and e.id is not null then\n   return jsonb_build_object(''ok'',true,''code'',''already_succeeded'',''billing_event_id'',e.id);\n end if;\n if s.status not in (''active'',''past_due'') or s.current_period_end is null or s.current_period_end>p_at\n    or (p_transition=''cancel_at_period_end'' and not coalesce(s.cancel_at_period_end,false))\n    or (p_transition=''grace_expired'' and (s.status<>''past_due'' or s.grace_until is null or s.grace_until>p_at or s.cancel_at_period_end)) then\n   return jsonb_build_object(''ok'',false,''code'',''not_terminal_eligible'');\n end if;\n if e.id is null then\n   insert into public.subscription_billing_events\n    (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,plan_tier,plan_id,idempotency_key,processed_at)\n   values(s.id,s.student_id,s.mentor_id,v_type,''succeeded'',s.current_period_start,s.current_period_end,p_at,s.plan_tier,s.plan_id,v_key,p_at)\n   returning * into e;\n end if;\n update public.subscriptions set status=''expired'',expired_at=p_at,next_billing_at=null,\n   canceled_at=case when p_transition=''cancel_at_period_end'' then p_at else canceled_at end,\n   last_billing_event_id=e.id,updated_at=p_at where id=s.id;\n return jsonb_build_object(''ok'',true,''code'',''succeeded'',''billing_event_id'',e.id);\nend $fn$;\nrevoke all on function public.finalize_subscription_terminal_transition(uuid,text,timestamptz,text) from public,anon,authenticated;\ngrant execute on function public.finalize_subscription_terminal_transition(uuid,text,timestamptz,text) to service_role;\n\n\nnotify pgrst, ''reload schema'';\ncommit;\n"], "idempotency_key": null}, {"name": "subscription_compatible_hardening", "version": "20261008003700", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- Compatible hardening: no app signature, navigation, or payment entry-point changes.\nbegin;\nset local lock_timeout=''5s'';\ndo $gate$ begin if md5(replace(pg_get_functiondef(''public.qna_create_question_thread(uuid,text,text,text,text)''::regprocedure),chr(13),'''')) <> ''18ec99f1b887daf3bfc6193cb0697d47'' then raise exception ''HARDENING_SOURCE_DRIFT: public.qna_create_question_thread''; end if; end $gate$;\nCREATE OR REPLACE FUNCTION public.qna_create_question_thread(p_room_id uuid, p_title text, p_subject text DEFAULT NULL::text, p_topic text DEFAULT NULL::text, p_first_message_body text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid; v_status text; v_suspended_until timestamptz;\n  v_created_at timestamptz; v_total int; v_per int; v_subject text; v_thread_id uuid; v_message_id uuid;\n  v_has_active_sub boolean; v_usage json; v_path text; v_sub_id uuid;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_title is null or btrim(p_title)='''' then raise exception ''TITLE_REQUIRED''; end if;\n  if char_length(p_title)>120 then raise exception ''TITLE_TOO_LONG''; end if;\n  if char_length(p_topic)>80 then raise exception ''TOPIC_TOO_LONG''; end if;\n  if char_length(p_first_message_body)>10000 then raise exception ''MESSAGE_TOO_LONG''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=p_room_id;\n  if not found then raise exception ''ROOM_NOT_FOUND''; end if;\n  if v_uid <> v_student then\n    if v_uid = v_mentor then raise exception ''MENTOR_CANNOT_CREATE_THREAD''; else raise exception ''NOT_ROOM_PARTY''; end if;\n  end if;\n  perform 1 from public.users where id=v_student for update;\n  select status, suspended_until, created_at into v_status, v_suspended_until, v_created_at from public.users where id=v_student;\n  if lower(coalesce(v_status,''active''))=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if lower(coalesce(v_status,''active''))=''suspended'' and (v_suspended_until is null or v_suspended_until > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if exists (select 1 from public.user_blocks where (blocker_id=v_student and blocked_id=v_mentor) or (blocker_id=v_mentor and blocked_id=v_student)) then raise exception ''BLOCKED''; end if;\n  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  v_has_active_sub := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'');\n  if v_has_active_sub then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n    v_usage := public.get_weekly_question_usage(v_student, v_mentor);\n    if not coalesce((v_usage->>''can_ask'')::boolean, false) then raise exception ''WEEKLY_LIMIT_EXHAUSTED''; end if;\n    v_path := ''subscription'';\n  else\n    if v_created_at is not null and now() >= v_created_at + interval ''7 days'' then raise exception ''FREE_QUOTA_EXPIRED''; end if;\n    select count(*) into v_total from public.free_question_usage where student_id=v_student;\n    if v_total >= 7 then raise exception ''FREE_QUOTA_TOTAL_EXHAUSTED''; end if;\n    select count(*) into v_per from public.free_question_usage where student_id=v_student and mentor_id=v_mentor;\n    if v_per >= 3 then raise exception ''FREE_QUOTA_MENTOR_EXHAUSTED''; end if;\n    v_path := ''free'';\n  end if;\n  v_subject := nullif(btrim(coalesce(p_subject,'''')),'''');\n  if v_subject is not null and not exists (select 1 from public.subjects where code=v_subject) then raise exception ''SUBJECT_INVALID''; end if;\n  insert into public.question_threads (mentor_student_room_id, title, status, subject, topic)\n  values (p_room_id, btrim(p_title), ''pending'', v_subject, nullif(btrim(coalesce(p_topic,'''')),'''')) returning id into v_thread_id;\n  if p_first_message_body is not null and btrim(p_first_message_body) <> '''' then\n    insert into public.question_messages (thread_id, author_id, body) values (v_thread_id, v_student, btrim(p_first_message_body)) returning id into v_message_id;\n  end if;\n  if v_path=''free'' then insert into public.free_question_usage (student_id, mentor_id, thread_id) values (v_student, v_mentor, v_thread_id); end if;\n\n  -- ── 새 질문 → 방 멘토 인앱 알림(question_received) ──\n  -- 20260805 도입(구독 한정) → S1-7/QA-C13 에서 무료 경로까지 확장.\n  -- 같은 트랜잭션 안 — 위 생성이 롤백되면 알림도 롤백(원자), record_domain_notification\n  -- 이 (recipient,event_key) 멱등 + outbox 게이트를 기존 계약대로 처리한다.\n  -- S1-7/QA-C13: 무료·구독 경로 모두 알린다(종전에는 subscription 한정 조건이 있었다).\n    perform public.record_domain_notification(\n      v_mentor,\n      ''question_received:'' || v_thread_id::text,\n      ''question_received:'' || v_thread_id::text,\n      ''question_received'',\n      ''새 질문이 도착했어요'',\n      ''학생이 새 질문을 등록했어요.'',\n      ''/mentor/question-room/'' || p_room_id::text || ''?thread='' || v_thread_id::text,\n      jsonb_build_object(''room_id'', p_room_id, ''thread_id'', v_thread_id, ''student_id'', v_student),\n      jsonb_build_object(''room_id'', p_room_id, ''thread_id'', v_thread_id, ''student_id'', v_student)\n    );\n\n  return jsonb_build_object(''ok'',true,''thread_id'',v_thread_id,''message_id'',v_message_id,''path'',v_path,''used_free_quota'',(v_path=''free''));\nend;\n$function$\n;\ndo $gate$ begin if md5(replace(pg_get_functiondef(''public.qna_append_message(uuid,text)''::regprocedure),chr(13),'''')) <> ''d3b9fafabe67cd8656cf3aa897bc7447'' then raise exception ''HARDENING_SOURCE_DRIFT: public.qna_append_message''; end if; end $gate$;\nCREATE OR REPLACE FUNCTION public.qna_append_message(p_thread_id uuid, p_body text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_status text; v_thread_status text;\n  v_first_answered timestamptz; v_message_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_sub_id uuid;\n  v_susp timestamptz; v_norm text;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_body is null or btrim(p_body)='''' then raise exception ''BODY_REQUIRED''; end if;\n  if char_length(p_body)>10000 then raise exception ''MESSAGE_TOO_LONG''; end if;\n  select t.mentor_student_room_id, t.status, t.first_answered_at into v_room, v_thread_status, v_first_answered\n    from public.question_threads t where t.id=p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;\n  if v_uid=v_mentor then v_is_mentor:=true; elsif v_uid=v_student then v_is_mentor:=false; else raise exception ''NOT_ROOM_PARTY''; end if;\n\n  -- [S3-C 보정 §3] 당사자 확정 직후 — 계정 상태 4종 + 상호 차단. 이 아래로는\n  -- 어떤 INSERT·상태 전이도 없으므로 차단 시 부수효과 0 이다.\n  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id=v_uid;\n  if not found then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  v_norm := lower(btrim(coalesce(v_status,'''')));\n  if v_norm=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if v_norm=''suspended'' and (v_susp is null or v_susp > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if v_norm not in (''active'',''suspended'') then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  if public.account_deletion_write_blocked(v_uid) then raise exception ''ACCOUNT_DELETION_IN_PROGRESS''; end if;\n  if public.qna_users_blocked(v_student, v_mentor) then raise exception ''BLOCKED''; end if;\n\n  if v_thread_status in (''confirmed'',''closed'',''archived'') then raise exception ''THREAD_LOCKED''; end if;\n  if v_is_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  -- 학생 후속 메시지: 활성 구독 FOR UPDATE + live pending refund 게이트(142 유지).\n  if not v_is_mentor then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n  end if;\n\n  -- F2(D-12)+R1: 아래 INSERT 가 AFTER INSERT 알림 트리거를 발화 — 멘토 메시지 행 1건 = 알림 정확히 1건.\n  insert into public.question_messages (thread_id, author_id, body) values (p_thread_id, v_uid, btrim(p_body)) returning id into v_message_id;\n  if v_is_mentor and v_first_answered is null then\n    update public.question_threads set status=''answered'', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;\n    v_transitioned := true;\n  end if;\n  return jsonb_build_object(''ok'',true,''message_id'',v_message_id,''answered_transition'',v_transitioned);\nend; $function$\n;\ndo $gate$ begin if md5(replace(pg_get_functiondef(''api_web_v1.qna_create_question_thread(uuid,text,text,text,text)''::regprocedure),chr(13),'''')) <> ''d30630a9bdfd2b6dd5039884a97b0f21'' then raise exception ''HARDENING_SOURCE_DRIFT: api_web_v1.qna_create_question_thread''; end if; end $gate$;\nCREATE OR REPLACE FUNCTION api_web_v1.qna_create_question_thread(p_room_id uuid, p_title text, p_subject text DEFAULT NULL::text, p_topic text DEFAULT NULL::text, p_first_message_body text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nDECLARE\n  v_res  jsonb;\n  v_code text;\nBEGIN\n  -- 판정 로직을 복제하지 않는다 — 정본 호출 + 예외의 안정 코드 변환만(§13.2)\n  v_res := public.qna_create_question_thread(p_room_id, p_title, p_subject, p_topic, p_first_message_body);\n  RETURN v_res || jsonb_build_object(''contract_version'', 1);\nEXCEPTION WHEN OTHERS THEN\n  v_code := CASE SQLERRM\n    -- 트리거 코드 수렴(XW-08 — §9.8 매핑표)\n    WHEN ''FREE_QUESTION_EXPIRED''           THEN ''FREE_QUOTA_EXPIRED''\n    WHEN ''FREE_QUESTION_TOTAL_LIMIT''       THEN ''FREE_QUOTA_TOTAL_EXHAUSTED''\n    WHEN ''FREE_QUESTION_PER_MENTOR_LIMIT''  THEN ''FREE_QUOTA_MENTOR_EXHAUSTED''\n    WHEN ''FREE_QUESTION_STUDENT_NOT_FOUND'' THEN ''FREE_QUOTA_STUDENT_NOT_FOUND''\n    -- 정본 raise 14종(실측 전수 — §9.8 \"qna_* raise 14종 동명 유지\")\n    WHEN ''AUTH_REQUIRED''                 THEN ''AUTH_REQUIRED''\n    WHEN ''TITLE_REQUIRED''                THEN ''TITLE_REQUIRED''\n    WHEN ''ROOM_NOT_FOUND''                THEN ''ROOM_NOT_FOUND''\n    WHEN ''NOT_ROOM_PARTY''                THEN ''NOT_ROOM_PARTY''\n    WHEN ''MENTOR_CANNOT_CREATE_THREAD''   THEN ''MENTOR_CANNOT_CREATE_THREAD''\n    WHEN ''ACCOUNT_BANNED''                THEN ''ACCOUNT_BANNED''\n    WHEN ''ACCOUNT_SUSPENDED''             THEN ''ACCOUNT_SUSPENDED''\n    WHEN ''ACCOUNT_DELETION_IN_PROGRESS''  THEN ''ACCOUNT_DELETION_IN_PROGRESS''\n    WHEN ''BLOCKED''                       THEN ''BLOCKED''\n    WHEN ''MENTOR_NOT_APPROVED''           THEN ''MENTOR_NOT_APPROVED''\n    WHEN ''SUBSCRIPTION_REFUND_PENDING''   THEN ''SUBSCRIPTION_REFUND_PENDING''\n    WHEN ''WEEKLY_LIMIT_EXHAUSTED''        THEN ''WEEKLY_LIMIT_EXHAUSTED''\n    WHEN ''FREE_QUOTA_EXPIRED''            THEN ''FREE_QUOTA_EXPIRED''\n    WHEN ''FREE_QUOTA_TOTAL_EXHAUSTED''    THEN ''FREE_QUOTA_TOTAL_EXHAUSTED''\n    WHEN ''FREE_QUOTA_MENTOR_EXHAUSTED''   THEN ''FREE_QUOTA_MENTOR_EXHAUSTED''\n    WHEN ''TITLE_TOO_LONG'' THEN ''TITLE_TOO_LONG''\n    WHEN ''TOPIC_TOO_LONG'' THEN ''TOPIC_TOO_LONG''\n    WHEN ''MESSAGE_TOO_LONG'' THEN ''MESSAGE_TOO_LONG''\n    WHEN ''SUBJECT_INVALID'' THEN ''SUBJECT_INVALID''\n    ELSE NULL\n  END;\n  IF v_code IS NULL THEN\n    -- 사전에 없는 예외는 삼키지 않고 그대로 전파(§8.2 — T-CON-06)\n    RAISE;\n  END IF;\n  RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', v_code);\nEND $function$\n;\ndo $gate$ begin if md5(replace(pg_get_functiondef(''api_app_v1.qna_create_question_thread(uuid,text,text,text,text)''::regprocedure),chr(13),'''')) <> ''3266b156de0c77aa0fd75c1c94fea8fb'' then raise exception ''HARDENING_SOURCE_DRIFT: api_app_v1.qna_create_question_thread''; end if; end $gate$;\nCREATE OR REPLACE FUNCTION api_app_v1.qna_create_question_thread(p_room_id uuid, p_title text, p_subject text DEFAULT NULL::text, p_topic text DEFAULT NULL::text, p_first_message_body text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nDECLARE\n  v_res  jsonb;\n  v_code text;\nBEGIN\n  v_res := public.qna_create_question_thread(p_room_id, p_title, p_subject, p_topic, p_first_message_body);\n  RETURN v_res || jsonb_build_object(''contract_version'', 1);\nEXCEPTION WHEN OTHERS THEN\n  v_code := CASE SQLERRM\n    WHEN ''FREE_QUESTION_EXPIRED''           THEN ''FREE_QUOTA_EXPIRED''\n    WHEN ''FREE_QUESTION_TOTAL_LIMIT''       THEN ''FREE_QUOTA_TOTAL_EXHAUSTED''\n    WHEN ''FREE_QUESTION_PER_MENTOR_LIMIT''  THEN ''FREE_QUOTA_MENTOR_EXHAUSTED''\n    WHEN ''FREE_QUESTION_STUDENT_NOT_FOUND'' THEN ''FREE_QUOTA_STUDENT_NOT_FOUND''\n    WHEN ''AUTH_REQUIRED''                 THEN ''AUTH_REQUIRED''\n    WHEN ''TITLE_REQUIRED''                THEN ''TITLE_REQUIRED''\n    WHEN ''ROOM_NOT_FOUND''                THEN ''ROOM_NOT_FOUND''\n    WHEN ''NOT_ROOM_PARTY''                THEN ''NOT_ROOM_PARTY''\n    WHEN ''MENTOR_CANNOT_CREATE_THREAD''   THEN ''MENTOR_CANNOT_CREATE_THREAD''\n    WHEN ''ACCOUNT_BANNED''                THEN ''ACCOUNT_BANNED''\n    WHEN ''ACCOUNT_SUSPENDED''             THEN ''ACCOUNT_SUSPENDED''\n    WHEN ''ACCOUNT_DELETION_IN_PROGRESS''  THEN ''ACCOUNT_DELETION_IN_PROGRESS''\n    WHEN ''BLOCKED''                       THEN ''BLOCKED''\n    WHEN ''MENTOR_NOT_APPROVED''           THEN ''MENTOR_NOT_APPROVED''\n    WHEN ''SUBSCRIPTION_REFUND_PENDING''   THEN ''SUBSCRIPTION_REFUND_PENDING''\n    WHEN ''WEEKLY_LIMIT_EXHAUSTED''        THEN ''WEEKLY_LIMIT_EXHAUSTED''\n    WHEN ''FREE_QUOTA_EXPIRED''            THEN ''FREE_QUOTA_EXPIRED''\n    WHEN ''FREE_QUOTA_TOTAL_EXHAUSTED''    THEN ''FREE_QUOTA_TOTAL_EXHAUSTED''\n    WHEN ''FREE_QUOTA_MENTOR_EXHAUSTED''   THEN ''FREE_QUOTA_MENTOR_EXHAUSTED''\n    WHEN ''TITLE_TOO_LONG'' THEN ''TITLE_TOO_LONG''\n    WHEN ''TOPIC_TOO_LONG'' THEN ''TOPIC_TOO_LONG''\n    WHEN ''MESSAGE_TOO_LONG'' THEN ''MESSAGE_TOO_LONG''\n    WHEN ''SUBJECT_INVALID'' THEN ''SUBJECT_INVALID''\n    ELSE NULL\n  END;\n  IF v_code IS NULL THEN\n    -- 사전에 없는 예외는 삼키지 않고 그대로 전파(앱 계약 §3.3 envelope 규약)\n    RAISE;\n  END IF;\n  RETURN jsonb_build_object(''ok'', false, ''contract_version'', 1, ''code'', v_code);\nEND $function$\n;\n\n-- Existing data was checked before rollout. NOT VALID avoids an initial write lock scan;\n-- VALIDATE below proves historical rows satisfy the same bounds without rewriting content.\nalter table public.question_threads add constraint question_threads_title_size check(char_length(title)<=120) not valid;\nalter table public.question_threads add constraint question_threads_topic_size check(char_length(topic)<=80) not valid;\nalter table public.question_messages add constraint question_messages_body_size check(char_length(body)<=10000) not valid;\nalter table public.question_threads validate constraint question_threads_title_size;\nalter table public.question_threads validate constraint question_threads_topic_size;\nalter table public.question_messages validate constraint question_messages_body_size;\n\n-- Trigger-only functions have no supported direct RPC invocation. Keep all other API,\n-- RLS helper, storage helper and legacy ACLs intact pending a separate dependency review.\ndo $acl$ declare r record; begin\n for r in select n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args\n   from pg_proc p join pg_namespace n on n.oid=p.pronamespace\n   where n.nspname in (''public'',''api_web_v1'',''api_app_v1'',''core_private'')\n     and p.prorettype=''trigger''::regtype\n loop\n   execute format(''revoke execute on function %I.%I(%s) from public,anon,authenticated'',r.nspname,r.proname,r.args);\n end loop;\nend $acl$;\nalter default privileges for role postgres revoke execute on functions from public;\nalter default privileges for role postgres in schema public,api_web_v1,api_app_v1,core_private\n revoke execute on functions from anon,authenticated;\ndo $gate$ begin if md5(replace(pg_get_functiondef(''public.comment_sync_in_progress()''::regprocedure),chr(13),'''')) <> ''23d50ce7b8421517a63fbb9e7619ca0e'' then raise exception ''HARDENING_SOURCE_DRIFT: public.comment_sync_in_progress''; end if; end $gate$;\nalter function public.comment_sync_in_progress() set search_path = '''';\ndo $gate$ begin if md5(replace(pg_get_functiondef(''public.notification_cash_label(bigint)''::regprocedure),chr(13),'''')) <> ''c38f604ca2d8ff741bf7409368d42d94'' then raise exception ''HARDENING_SOURCE_DRIFT: public.notification_cash_label''; end if; end $gate$;\nalter function public.notification_cash_label(bigint) set search_path = '''';\ndo $gate$ begin if md5(replace(pg_get_functiondef(''public.notification_date_label(timestamptz)''::regprocedure),chr(13),'''')) <> ''adf5b5bcdef8a96eda25fb845ffcfb0d'' then raise exception ''HARDENING_SOURCE_DRIFT: public.notification_date_label''; end if; end $gate$;\nalter function public.notification_date_label(timestamptz) set search_path = '''';\ndo $gate$ begin if md5(replace(pg_get_functiondef(''public.payout_run_items_block_mutation()''::regprocedure),chr(13),'''')) <> ''2374bb2b16b58318397b837475a5506e'' then raise exception ''HARDENING_SOURCE_DRIFT: public.payout_run_items_block_mutation''; end if; end $gate$;\nalter function public.payout_run_items_block_mutation() set search_path = '''';\ndo $gate$ begin if md5(replace(pg_get_functiondef(''public.qna_is_direct_untrusted_writer()''::regprocedure),chr(13),'''')) <> ''8e2d7b36085f28ae2a590d9c1edc265c'' then raise exception ''HARDENING_SOURCE_DRIFT: public.qna_is_direct_untrusted_writer''; end if; end $gate$;\nalter function public.qna_is_direct_untrusted_writer() set search_path = '''';\n\n-- Same 17 columns, role/approval/deletion/review filters. The invoker view never grants\n-- anon table access; the unexposed function returns only the public projection.\ncreate or replace function core_private.mentor_directory_public_rows()\nreturns table(mentor_id uuid,nickname text,university_name text,department_name text,\n teaching_subjects text[],intro_line text,profile_image_url text,high_school_name text,\n school_verified boolean,school_tier text,verified_major_category text,verified_university_name text,\n verified_department_name text,is_open_for_subscriptions boolean,avg_rating numeric,review_count integer,created_at timestamptz)\nlanguage sql stable security definer set search_path = '''' as $fn$\n select mp.user_id,u.nickname,mp.university_name,mp.department_name,mp.teaching_subjects,mp.intro_line,\n   mp.profile_image_url,mp.high_school_name,sv.mentor_id is not null,sv.school_tier,sv.verified_major_category,\n   sv.verified_university_name,sv.verified_department_name,mp.is_open_for_subscriptions,rv.avg_rating,rv.review_count,mp.created_at\n from public.mentor_profiles mp join public.users u on u.id=mp.user_id\n left join lateral (select msv.mentor_id,msv.school_tier,msv.verified_major_category,msv.verified_university_name,msv.verified_department_name\n    from public.mentor_school_verifications msv where msv.mentor_id=mp.user_id and msv.status=''approved''\n    order by coalesce(msv.reviewed_at,msv.updated_at,msv.created_at) desc,msv.created_at desc limit 1) sv on true\n left join lateral (select avg(r.rating) avg_rating,count(*)::integer review_count from public.reviews r\n    where r.mentor_id=mp.user_id and r.moderation_state=''visible'' and not coalesce(r.is_hidden,false) and not coalesce(r.is_blinded,false)) rv on true\n where u.role=''mentor'' and lower(coalesce(u.status,''active''))=''active''\n   and lower(coalesce(mp.verification_status,'''')) in (''approved'',''verified'',''active'')\n   and not exists(select 1 from public.account_deletion_jobs j where j.user_id=mp.user_id\n     and j.state in (''pending'',''locked'',''purging'',''storage_purged'',''finalized'',''auth_soft_deleted''))\n$fn$;\nrevoke all on function core_private.mentor_directory_public_rows() from public;\ngrant execute on function core_private.mentor_directory_public_rows() to anon,authenticated,service_role;\ndo $gate$ begin if md5(pg_get_viewdef(''api_web_v1.mentor_directory_v1''::regclass,true)) <> ''61c8b399a23f74c5012cd337bdfcc29d'' then raise exception ''HARDENING_SOURCE_DRIFT: mentor_directory_v1''; end if; end $gate$;\ncreate or replace view api_web_v1.mentor_directory_v1 with (security_invoker=true) as\n select * from core_private.mentor_directory_public_rows();\n\n-- Bound the renewal scans and support their FK/ledger joins. No unrelated index removals.\ncreate index if not exists subscriptions_renewal_due_idx on public.subscriptions(next_billing_at)\n where status in (''active'',''past_due'');\ncreate index if not exists subscription_billing_events_payment_idx on public.subscription_billing_events(payment_id);\ncreate index if not exists subscription_billing_events_ledger_idx on public.subscription_billing_events(ledger_id);\nnotify pgrst, ''reload schema'';\ncommit;\n"], "idempotency_key": null}, {"name": "subscription_review_fixes", "version": "20261008020145", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- Follow-up to the adversarial review. Preserve existing web/app RPC signatures.\nbegin;\nset local lock_timeout=''5s'';\ndo $gate$ begin\n if md5(replace(pg_get_functiondef(''core_private.record_initial_subscription_billing_event(uuid,uuid,boolean)''::regprocedure),chr(13),'''')) <> ''36b9bfb79ce8959b1b4f337420db8cec'' then\n  raise exception ''FINANCIAL_SOURCE_DRIFT: record_initial_subscription_billing_event''; end if;\n if md5(replace(pg_get_functiondef(''public.process_subscription_renewal_v2(uuid,timestamptz,text,timestamptz)''::regprocedure),chr(13),'''')) <> ''f80b82cc158f80659ae7fe37f29be8b9'' then\n  raise exception ''FINANCIAL_SOURCE_DRIFT: process_subscription_renewal_v2''; end if;\nend $gate$;\n\n-- Immutable identity is payment-scoped, including overlapping checkouts/reactivation.\n-- Fail migration on ambiguous historical duplicates; never delete financial history.\ncreate unique index subscription_initial_payment_uidx\n on public.subscription_billing_events(payment_id) where event_type=''initial'' and payment_id is not null;\nupdate public.subscription_billing_events\n set idempotency_key=''sub_initial:''||subscription_id::text||'':''||payment_id::text\n where event_type=''initial'' and payment_id is not null\n and idempotency_key is distinct from ''sub_initial:''||subscription_id::text||'':''||payment_id::text;\n\ncreate function core_private.guard_initial_subscription_billing_event()\nreturns trigger language plpgsql security invoker set search_path='''' as $fn$\nbegin\n if TG_OP=''INSERT'' and NEW.event_type=''initial'' and NEW.payment_id is not null then\n  NEW.idempotency_key := ''sub_initial:''||NEW.subscription_id::text||'':''||NEW.payment_id::text;\n  -- Old web has already committed via v2, then sends a redundant service-role upsert.\n  -- A zero-row result makes that old best-effort writer stop before its pointer update.\n  if current_user in (''service_role'',''authenticated'',''anon'') and exists(\n   select 1 from public.subscription_billing_events where payment_id=NEW.payment_id and event_type=''initial'') then\n   return null;\n  end if;\n elsif TG_OP=''UPDATE'' and OLD.event_type=''initial'' and OLD.status in (''succeeded'',''refunded'') then\n  if row(NEW.subscription_id,NEW.student_id,NEW.mentor_id,NEW.event_type,NEW.period_start,NEW.period_end,\n         NEW.billing_at,NEW.amount_cents,NEW.plan_tier,NEW.plan_id,NEW.ledger_id,NEW.payment_id,NEW.idempotency_key)\n   is distinct from\n     row(OLD.subscription_id,OLD.student_id,OLD.mentor_id,OLD.event_type,OLD.period_start,OLD.period_end,\n         OLD.billing_at,OLD.amount_cents,OLD.plan_tier,OLD.plan_id,OLD.ledger_id,OLD.payment_id,OLD.idempotency_key) then\n   raise exception ''INITIAL_BILLING_EVENT_IMMUTABLE'';\n  end if;\n end if;\n return NEW;\nend $fn$;\nrevoke all on function core_private.guard_initial_subscription_billing_event() from public,anon,authenticated,service_role;\ncreate trigger guard_initial_subscription_billing_event before insert or update on public.subscription_billing_events\n for each row execute function core_private.guard_initial_subscription_billing_event();\n\ncreate function core_private.guard_subscription_billing_links()\nreturns trigger language plpgsql security invoker set search_path='''' as $fn$\nbegin\n -- Definer domain RPCs run as their owner. Direct PostgREST service-role writes are\n -- legacy follow-ups and must not rewind canonical pointers, even after another renewal.\n if current_user in (''service_role'',''authenticated'',''anon'') then\n  NEW.last_payment_id := OLD.last_payment_id;\n  NEW.last_billing_event_id := OLD.last_billing_event_id;\n end if;\n return NEW;\nend $fn$;\nrevoke all on function core_private.guard_subscription_billing_links() from public,anon,authenticated,service_role;\ncreate trigger guard_subscription_billing_links before update of last_payment_id,last_billing_event_id on public.subscriptions\n for each row execute function core_private.guard_subscription_billing_links();\n\n-- Existing status/grace contract: no paid access while price is unresolved. A retry\n-- cannot extend grace; expiry uses the same terminal RPC as insufficient-cash expiry.\ncreate function core_private.record_subscription_renewal_block(p_subscription_id uuid,p_code text,p_key text,p_at timestamptz)\nreturns public.subscription_billing_events language plpgsql security invoker set search_path='''' as $fn$\ndeclare s public.subscriptions%rowtype; e public.subscription_billing_events%rowtype;\nbegin\n if p_code not in (''price_unavailable'',''price_changed_since_notice'') then raise exception ''INVALID_RENEWAL_BLOCK''; end if;\n select * into strict s from public.subscriptions where id=p_subscription_id for update;\n insert into public.subscription_billing_events as b\n  (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,\n   plan_tier,plan_id,idempotency_key,failure_code,failure_message,attempt_count,created_at,processed_at)\n values(s.id,s.student_id,s.mentor_id,''renewal_failed'',''failed'',s.current_period_end,\n   ((s.current_period_end at time zone ''Asia/Seoul''+interval ''1 month'') at time zone ''Asia/Seoul''),p_at,\n   s.plan_tier,s.plan_id,p_key,p_code,''renewal blocked until the bound price is safe'',1,p_at,p_at)\n on conflict(idempotency_key) do update set event_type=''renewal_failed'',status=''failed'',\n  failure_code=excluded.failure_code,failure_message=excluded.failure_message,\n  processed_at=excluded.processed_at,attempt_count=b.attempt_count+1\n where b.status in (''failed'',''skipped'')\n returning * into e;\n if e.id is null then raise exception ''BILLING_EVENT_BINDING_MISMATCH''; end if;\n update public.subscriptions set status=''past_due'',grace_until=coalesce(grace_until,p_at+interval ''2 days''),\n  last_billing_event_id=e.id,updated_at=p_at where id=s.id;\n return e;\nend $fn$;\nrevoke all on function core_private.record_subscription_renewal_block(uuid,text,text,timestamptz) from public,anon,authenticated,service_role;\n\n-- A committed selection timestamp survives a later RPC failure. One blocked batch\n-- cannot permanently monopolize the queue. Claims do not hold locks across HTTP calls.\nalter table public.subscriptions add column renewal_batch_attempted_at timestamptz;\ncreate index subscriptions_renewal_batch_fair_idx\n on public.subscriptions(renewal_batch_attempted_at asc nulls first,next_billing_at,id)\n where status in (''active'',''past_due'') and next_billing_at is not null;\ncreate function public.claim_subscription_renewal_batch(p_at timestamptz,p_limit integer default 50)\nreturns setof public.subscriptions language plpgsql security definer set search_path='''' as $fn$\nbegin\n if p_at is null or p_limit is null or p_limit<1 or p_limit>100 then raise exception ''INVALID_BATCH_PARAMETERS''; end if;\n return query\n with candidates as (\n  select s.id from public.subscriptions s\n  where s.next_billing_at<=p_at and s.status in (''active'',''past_due'')\n  order by s.renewal_batch_attempted_at asc nulls first,s.next_billing_at,s.id\n  limit p_limit for update skip locked\n )\n update public.subscriptions s set renewal_batch_attempted_at=clock_timestamp()\n from candidates c where s.id=c.id returning s.*;\nend $fn$;\nrevoke all on function public.claim_subscription_renewal_batch(timestamptz,integer) from public,anon,authenticated;\ngrant execute on function public.claim_subscription_renewal_batch(timestamptz,integer) to service_role;\n\ncreate or replace function core_private.record_initial_subscription_billing_event(\n  p_payment_id uuid, p_subscription_id uuid, p_set_latest boolean default false\n) returns uuid language plpgsql security invoker set search_path = '''' as $fn$\ndeclare\n  p public.payments%rowtype; s public.subscriptions%rowtype; l public.cash_ledger%rowtype;\n  e public.subscription_billing_events%rowtype;\n  v_tier text; v_key text := ''sub_initial:'' || p_subscription_id::text || '':'' || p_payment_id::text;\n  v_start timestamptz; v_end timestamptz;\nbegin\n  select * into strict p from public.payments where id = p_payment_id;\n  select * into strict s from public.subscriptions where id = p_subscription_id for update;\n  select * into l from public.cash_ledger where idempotency_key = ''sub_debit_'' || p_payment_id::text;\n  if l.id is null or l.user_id is distinct from p.user_id or l.ref_id is distinct from s.id\n     or l.ref_type is distinct from ''subscriptions'' or l.reason is distinct from ''subscription_payment''\n     or l.delta_cents is distinct from -(p.amount * 100)::bigint\n     or s.student_id is distinct from p.user_id or s.mentor_id is distinct from p.mentor_id\n     or p.status not in (''succeeded'',''paid'',''success'',''complete'',''captured'') then\n    raise exception ''BILLING_EVENT_BINDING_MISMATCH'';\n  end if;\n  select plan_tier into v_tier from public.mentor_plans where id = p.plan_id and mentor_id = p.mentor_id;\n  if v_tier is null then raise exception ''PLAN_BINDING_MISMATCH''; end if;\n  select * into e from public.subscription_billing_events\n    where payment_id = p.id and event_type = ''initial'' order by created_at, id limit 1;\n  if e.id is not null then\n    if e.subscription_id is distinct from s.id or e.ledger_id is distinct from l.id\n       or e.amount_cents is distinct from -l.delta_cents or e.plan_id is distinct from p.plan_id\n       or e.status not in (''succeeded'', ''refunded'') then\n      raise exception ''BILLING_EVENT_BINDING_MISMATCH'';\n    end if;\n    return e.id;\n  end if;\n  -- Checkout and its debit both use transaction now(). Never infer an old payment''s\n  -- period from subscriptions.current_period_*: cash renewals do not change last_payment_id.\n  v_start := l.created_at;\n  v_end := ((v_start at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul'');\n  insert into public.subscription_billing_events\n    (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,\n     amount_cents,plan_tier,plan_id,idempotency_key,ledger_id,payment_id,processed_at)\n  values (s.id,p.user_id,p.mentor_id,''initial'',''succeeded'',v_start,v_end,l.created_at,\n          -l.delta_cents,v_tier,p.plan_id,v_key,l.id,p.id,l.created_at)\n  returning * into e;\n  if p_set_latest and s.last_payment_id = p.id then\n    update public.subscriptions set last_billing_event_id = e.id where id = s.id;\n  end if;\n  return e.id;\nend $fn$;\nrevoke all on function core_private.record_initial_subscription_billing_event(uuid,uuid,boolean) from public,anon,authenticated,service_role;\n\ncreate or replace function public.process_subscription_renewal_v2(\n p_subscription_id uuid,p_period_end timestamptz,p_idempotency_key text,p_processed_at timestamptz default now()) returns table(ok boolean,code text,message text,billing_event_id uuid,ledger_id uuid,\n next_period_start timestamptz,next_period_end timestamptz,wallet_balance_cents bigint,attempt_count integer)\nlanguage plpgsql security definer set search_path = '''' as $fn$\ndeclare\n s public.subscriptions%rowtype; p public.mentor_plans%rowtype;\n e public.subscription_billing_events%rowtype; l public.cash_ledger%rowtype;\n v_student uuid; v_mentor uuid; v_amount bigint; v_balance bigint; v_end timestamptz;\n v_key text; v_notice public.subscription_billing_events%rowtype;\nbegin\n if p_subscription_id is null or p_period_end is null or p_processed_at is null then\n   return query select false,''invalid_subscription''::text,''subscription, period and time are required''::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;\n end if;\n v_key := ''sub_renewal:''||p_subscription_id::text||'':''||to_char(p_period_end at time zone ''UTC'',''YYYY-MM-DD'');\n if p_idempotency_key is distinct from v_key or char_length(p_idempotency_key)>128 then\n   return query select false,''invalid_idempotency_key''::text,''key must identify this subscription period''::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;\n end if;\n -- Match checkout''s pair mutex before row locks. No stale client snapshot decides eligibility.\n select student_id,mentor_id into v_student,v_mentor from public.subscriptions where id=p_subscription_id;\n if v_student is null then\n   return query select false,''not_found''::text,''subscription not found''::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;\n end if;\n perform pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));\n select * into s from public.subscriptions where id=p_subscription_id for update;\n if s.id is null or s.student_id is distinct from v_student or s.mentor_id is distinct from v_mentor then\n   raise exception ''SUBSCRIPTION_BINDING_MISMATCH'';\n end if;\n select * into e from public.subscription_billing_events where idempotency_key=v_key for update;\n if e.id is not null then\n   if e.subscription_id is distinct from s.id or e.student_id is distinct from s.student_id\n      or e.mentor_id is distinct from s.mentor_id or e.period_start is distinct from p_period_end\n      or e.event_type not in (''renewal'',''renewal_failed'') then\n     raise exception ''BILLING_EVENT_BINDING_MISMATCH'';\n   end if;\n   if e.status=''succeeded'' then\n     select * into l from public.cash_ledger where id=e.ledger_id;\n     if l.id is null or l.delta_cents is distinct from -e.amount_cents::bigint\n        or l.user_id is distinct from s.student_id or l.ref_id is distinct from s.id\n        or l.idempotency_key is distinct from v_key or l.reason is distinct from ''subscription_renewal'' then\n       raise exception ''LEDGER_BINDING_MISMATCH'';\n     end if;\n     return query select true,''already_succeeded''::text,''renewal already processed''::text,e.id,l.id,e.period_start,e.period_end,null::bigint,e.attempt_count; return;\n   end if;\n   if e.status not in (''failed'',''skipped'') then\n     return query select false,''already_processing''::text,''renewal is already processing''::text,e.id,e.ledger_id,e.period_start,e.period_end,null::bigint,e.attempt_count; return;\n   end if;\n end if;\n if s.status not in (''active'',''past_due'') or s.cancel_at_period_end\n    or (s.status=''past_due'' and s.grace_until is not null and s.grace_until<=p_processed_at)\n    or s.current_period_end is distinct from p_period_end or s.next_billing_at is null\n    or s.next_billing_at>p_processed_at or p_period_end>p_processed_at then\n   return query select false,''not_renewal_eligible''::text,''subscription state or period changed''::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;\n end if;\n select * into p from public.mentor_plans where id=s.plan_id for share;\n if p.id is null or p.mentor_id is distinct from s.mentor_id or p.plan_tier is distinct from s.plan_tier\n    or p.amount_cents is null or p.amount_cents<=0 or p.amount_cents%100<>0 then\n   e := core_private.record_subscription_renewal_block(s.id,''price_unavailable'',v_key,p_processed_at);\n   return query select false,''price_unavailable''::text,''plan price or binding unavailable''::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;\n end if;\n -- is_active controls NEW subscriptions only. Existing subscriptions may renew.\n v_amount := p.amount_cents;\n select * into v_notice from public.subscription_billing_events\n  where idempotency_key=''sub_renewal_notice:''||s.id::text||'':''||to_char(p_period_end at time zone ''UTC'',''YYYY-MM-DD'');\n if v_notice.id is not null and (v_notice.amount_cents is distinct from v_amount\n    or v_notice.plan_id is distinct from p.id or v_notice.plan_tier is distinct from p.plan_tier) then\n   e := core_private.record_subscription_renewal_block(s.id,''price_changed_since_notice'',v_key,p_processed_at);\n   return query select false,''price_changed_since_notice''::text,''renewal price differs from the sent notice''::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;\n end if;\n if exists(select 1 from public.cash_ledger where idempotency_key=v_key) then\n   raise exception ''LEDGER_WITHOUT_SUCCEEDED_EVENT'';\n end if;\n v_end := ((p_period_end at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul'');\n if e.id is null then\n   insert into public.subscription_billing_events\n    (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,\n     amount_cents,plan_tier,plan_id,idempotency_key,attempt_count,created_at)\n   values(s.id,s.student_id,s.mentor_id,''renewal'',''processing'',p_period_end,v_end,p_processed_at,\n          v_amount,p.plan_tier,p.id,v_key,1,p_processed_at) returning * into e;\n else\n   update public.subscription_billing_events b set event_type=''renewal'',status=''processing'',\n     amount_cents=v_amount,plan_id=p.id,plan_tier=p.plan_tier,billing_at=p_processed_at,\n     attempt_count=b.attempt_count+1,processed_at=null,failure_code=null,failure_message=null\n   where b.id=e.id returning b.* into e;\n end if;\n insert into public.cash_wallets(user_id,balance_cents) values(s.student_id,0) on conflict(user_id) do nothing;\n update public.cash_wallets w set balance_cents=w.balance_cents-v_amount\n   where w.user_id=s.student_id and w.balance_cents>=v_amount returning w.balance_cents into v_balance;\n if not found then\n   update public.subscription_billing_events b set event_type=''renewal_failed'',status=''failed'',\n     failure_code=''insufficient_cash'',failure_message=''CASH_INSUFFICIENT'',processed_at=p_processed_at where b.id=e.id;\n   update public.subscriptions set status=''past_due'',grace_until=coalesce(grace_until,p_processed_at+interval ''2 days''),\n     updated_at=p_processed_at,last_billing_event_id=e.id where id=s.id;\n   return query select false,''insufficient_cash''::text,''CASH_INSUFFICIENT''::text,e.id,null::uuid,p_period_end,v_end,null::bigint,e.attempt_count; return;\n end if;\n insert into public.cash_ledger(user_id,delta_cents,reason,ref_type,ref_id,idempotency_key,created_at)\n values(s.student_id,-v_amount,''subscription_renewal'',''subscriptions'',s.id,v_key,p_processed_at) returning * into l;\n update public.subscription_billing_events b set event_type=''renewal'',status=''succeeded'',ledger_id=l.id,\n   processed_at=p_processed_at,failure_code=null,failure_message=null where b.id=e.id;\n update public.subscriptions set status=''active'',current_period_start=p_period_end,current_period_end=v_end,\n   next_billing_at=v_end,last_renewed_at=p_processed_at,last_billing_event_id=e.id,grace_until=null,updated_at=p_processed_at where id=s.id;\n return query select true,''succeeded''::text,''renewal processed''::text,e.id,l.id,p_period_end,v_end,v_balance,e.attempt_count;\nend $fn$;\nrevoke all on function public.process_subscription_renewal_v2(uuid,timestamptz,text,timestamptz) from public,anon,authenticated;\ngrant execute on function public.process_subscription_renewal_v2(uuid,timestamptz,text,timestamptz) to service_role;\n\nnotify pgrst, ''reload schema'';\ncommit;\n"], "idempotency_key": null}, {"name": "subscription_timestamp_compatibility", "version": "20261008021536", "rollback": null, "created_by": "21jundragon@gmail.com", "statements": ["-- Preserve PostgreSQL microseconds and support the existing JS millisecond contract.\nbegin;\nset local lock_timeout=''5s'';\ndo $gate$ begin\n if md5(replace(pg_get_functiondef(''public.process_subscription_renewal_v2(uuid,timestamptz,text,timestamptz)''::regprocedure),chr(13),'''')) <> ''8c2fe0b419f409a43d2448b3a2d5318b'' then\n  raise exception ''FINANCIAL_SOURCE_DRIFT: process_subscription_renewal_v2''; end if;\n if md5(replace(pg_get_functiondef(''public.record_subscription_renewal_notice(uuid,timestamptz,timestamptz)''::regprocedure),chr(13),'''')) <> ''84e2e415b699d410ab2e79b9dac78152'' then\n  raise exception ''FINANCIAL_SOURCE_DRIFT: record_subscription_renewal_notice''; end if;\nend $gate$;\n\ncreate or replace function public.record_subscription_renewal_notice(\n p_subscription_id uuid,p_period_end timestamptz,p_at timestamptz default now()) returns jsonb language plpgsql security definer set search_path = '''' as $fn$\ndeclare s public.subscriptions%rowtype; p public.mentor_plans%rowtype; v_id uuid; v_key text;\nbegin\n select * into s from public.subscriptions where id=p_subscription_id for update;\n -- Accept JS millisecond round trips but always persist the locked DB timestamp.\n if date_trunc(''milliseconds'',s.current_period_end)=date_trunc(''milliseconds'',p_period_end) then\n  p_period_end := s.current_period_end;\n end if;\n if s.id is null or p_period_end is null or p_at is null or s.status <> ''active''\n    or s.cancel_at_period_end or s.current_period_end is distinct from p_period_end\n    or s.next_billing_at is null or s.next_billing_at<=p_at then\n   return jsonb_build_object(''ok'',false,''code'',''not_notice_eligible'');\n end if;\n select * into p from public.mentor_plans where id=s.plan_id for share;\n if p.id is null or p.mentor_id is distinct from s.mentor_id or p.plan_tier is distinct from s.plan_tier\n    or p.amount_cents is null or p.amount_cents<=0 or p.amount_cents%100<>0 then\n   return jsonb_build_object(''ok'',false,''code'',''price_unavailable'');\n end if;\n v_key := ''sub_renewal_notice:''||s.id::text||'':''||to_char(p_period_end at time zone ''UTC'',''YYYY-MM-DD'');\n insert into public.subscription_billing_events\n   (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,amount_cents,\n    plan_tier,plan_id,idempotency_key,failure_code,failure_message,attempt_count,created_at,processed_at)\n values(s.id,s.student_id,s.mentor_id,''renewal'',''skipped'',s.current_period_start,s.current_period_end,s.next_billing_at,\n        p.amount_cents,p.plan_tier,p.id,v_key,''pre_renewal_notice_sent'',''pre-renewal notice marker'',0,p_at,p_at)\n on conflict(idempotency_key) do nothing returning id into v_id;\n return jsonb_build_object(''ok'',true,''code'',case when v_id is null then ''already'' else ''sent'' end);\nend $fn$;\nrevoke all on function public.record_subscription_renewal_notice(uuid,timestamptz,timestamptz) from public,anon,authenticated;\ngrant execute on function public.record_subscription_renewal_notice(uuid,timestamptz,timestamptz) to service_role;\n\ncreate or replace function public.process_subscription_renewal_v2(\n p_subscription_id uuid,p_period_end timestamptz,p_idempotency_key text,p_processed_at timestamptz default now()) returns table(ok boolean,code text,message text,billing_event_id uuid,ledger_id uuid,\n next_period_start timestamptz,next_period_end timestamptz,wallet_balance_cents bigint,attempt_count integer)\nlanguage plpgsql security definer set search_path = '''' as $fn$\ndeclare\n s public.subscriptions%rowtype; p public.mentor_plans%rowtype;\n e public.subscription_billing_events%rowtype; l public.cash_ledger%rowtype;\n v_student uuid; v_mentor uuid; v_amount bigint; v_balance bigint; v_end timestamptz;\n v_key text; v_notice public.subscription_billing_events%rowtype;\nbegin\n if p_subscription_id is null or p_period_end is null or p_processed_at is null then\n   return query select false,''invalid_subscription''::text,''subscription, period and time are required''::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;\n end if;\n v_key := ''sub_renewal:''||p_subscription_id::text||'':''||to_char(p_period_end at time zone ''UTC'',''YYYY-MM-DD'');\n if p_idempotency_key is distinct from v_key or char_length(p_idempotency_key)>128 then\n   return query select false,''invalid_idempotency_key''::text,''key must identify this subscription period''::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;\n end if;\n -- Match checkout''s pair mutex before row locks. No stale client snapshot decides eligibility.\n select student_id,mentor_id into v_student,v_mentor from public.subscriptions where id=p_subscription_id;\n if v_student is null then\n   return query select false,''not_found''::text,''subscription not found''::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;\n end if;\n perform pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));\n select * into s from public.subscriptions where id=p_subscription_id for update;\n if s.id is null or s.student_id is distinct from v_student or s.mentor_id is distinct from v_mentor then\n   raise exception ''SUBSCRIPTION_BINDING_MISMATCH'';\n end if;\n select * into e from public.subscription_billing_events where idempotency_key=v_key for update;\n -- Older web normalizes timestamps through JS Date (millisecond precision). Bind\n -- to the locked subscription, or the original event on replay, without rounding\n -- stored financial periods. A different millisecond is still a stale request.\n if e.id is not null and e.subscription_id=s.id\n    and date_trunc(''milliseconds'',e.period_start)=date_trunc(''milliseconds'',p_period_end) then\n  p_period_end := e.period_start;\n elsif e.id is null\n    and date_trunc(''milliseconds'',s.current_period_end)=date_trunc(''milliseconds'',p_period_end) then\n  p_period_end := s.current_period_end;\n end if;\n if e.id is not null then\n   if e.subscription_id is distinct from s.id or e.student_id is distinct from s.student_id\n      or e.mentor_id is distinct from s.mentor_id or e.period_start is distinct from p_period_end\n      or e.event_type not in (''renewal'',''renewal_failed'') then\n     raise exception ''BILLING_EVENT_BINDING_MISMATCH'';\n   end if;\n   if e.status=''succeeded'' then\n     select * into l from public.cash_ledger where id=e.ledger_id;\n     if l.id is null or l.delta_cents is distinct from -e.amount_cents::bigint\n        or l.user_id is distinct from s.student_id or l.ref_id is distinct from s.id\n        or l.idempotency_key is distinct from v_key or l.reason is distinct from ''subscription_renewal'' then\n       raise exception ''LEDGER_BINDING_MISMATCH'';\n     end if;\n     return query select true,''already_succeeded''::text,''renewal already processed''::text,e.id,l.id,e.period_start,e.period_end,null::bigint,e.attempt_count; return;\n   end if;\n   if e.status not in (''failed'',''skipped'') then\n     return query select false,''already_processing''::text,''renewal is already processing''::text,e.id,e.ledger_id,e.period_start,e.period_end,null::bigint,e.attempt_count; return;\n   end if;\n end if;\n if s.status not in (''active'',''past_due'') or s.cancel_at_period_end\n    or (s.status=''past_due'' and s.grace_until is not null and s.grace_until<=p_processed_at)\n    or s.current_period_end is distinct from p_period_end or s.next_billing_at is null\n    or s.next_billing_at>p_processed_at or p_period_end>p_processed_at then\n   return query select false,''not_renewal_eligible''::text,''subscription state or period changed''::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;\n end if;\n select * into p from public.mentor_plans where id=s.plan_id for share;\n if p.id is null or p.mentor_id is distinct from s.mentor_id or p.plan_tier is distinct from s.plan_tier\n    or p.amount_cents is null or p.amount_cents<=0 or p.amount_cents%100<>0 then\n   e := core_private.record_subscription_renewal_block(s.id,''price_unavailable'',v_key,p_processed_at);\n   return query select false,''price_unavailable''::text,''plan price or binding unavailable''::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;\n end if;\n -- is_active controls NEW subscriptions only. Existing subscriptions may renew.\n v_amount := p.amount_cents;\n select * into v_notice from public.subscription_billing_events\n  where idempotency_key=''sub_renewal_notice:''||s.id::text||'':''||to_char(p_period_end at time zone ''UTC'',''YYYY-MM-DD'');\n if v_notice.id is not null and (v_notice.amount_cents is distinct from v_amount\n    or v_notice.plan_id is distinct from p.id or v_notice.plan_tier is distinct from p.plan_tier) then\n   e := core_private.record_subscription_renewal_block(s.id,''price_changed_since_notice'',v_key,p_processed_at);\n   return query select false,''price_changed_since_notice''::text,''renewal price differs from the sent notice''::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;\n end if;\n if exists(select 1 from public.cash_ledger where idempotency_key=v_key) then\n   raise exception ''LEDGER_WITHOUT_SUCCEEDED_EVENT'';\n end if;\n v_end := ((p_period_end at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul'');\n if e.id is null then\n   insert into public.subscription_billing_events\n    (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,\n     amount_cents,plan_tier,plan_id,idempotency_key,attempt_count,created_at)\n   values(s.id,s.student_id,s.mentor_id,''renewal'',''processing'',p_period_end,v_end,p_processed_at,\n          v_amount,p.plan_tier,p.id,v_key,1,p_processed_at) returning * into e;\n else\n   update public.subscription_billing_events b set event_type=''renewal'',status=''processing'',\n     amount_cents=v_amount,plan_id=p.id,plan_tier=p.plan_tier,billing_at=p_processed_at,\n     attempt_count=b.attempt_count+1,processed_at=null,failure_code=null,failure_message=null\n   where b.id=e.id returning b.* into e;\n end if;\n insert into public.cash_wallets(user_id,balance_cents) values(s.student_id,0) on conflict(user_id) do nothing;\n update public.cash_wallets w set balance_cents=w.balance_cents-v_amount\n   where w.user_id=s.student_id and w.balance_cents>=v_amount returning w.balance_cents into v_balance;\n if not found then\n   update public.subscription_billing_events b set event_type=''renewal_failed'',status=''failed'',\n     failure_code=''insufficient_cash'',failure_message=''CASH_INSUFFICIENT'',processed_at=p_processed_at where b.id=e.id;\n   update public.subscriptions set status=''past_due'',grace_until=coalesce(grace_until,p_processed_at+interval ''2 days''),\n     updated_at=p_processed_at,last_billing_event_id=e.id where id=s.id;\n   return query select false,''insufficient_cash''::text,''CASH_INSUFFICIENT''::text,e.id,null::uuid,p_period_end,v_end,null::bigint,e.attempt_count; return;\n end if;\n insert into public.cash_ledger(user_id,delta_cents,reason,ref_type,ref_id,idempotency_key,created_at)\n values(s.student_id,-v_amount,''subscription_renewal'',''subscriptions'',s.id,v_key,p_processed_at) returning * into l;\n update public.subscription_billing_events b set event_type=''renewal'',status=''succeeded'',ledger_id=l.id,\n   processed_at=p_processed_at,failure_code=null,failure_message=null where b.id=e.id;\n update public.subscriptions set status=''active'',current_period_start=p_period_end,current_period_end=v_end,\n   next_billing_at=v_end,last_renewed_at=p_processed_at,last_billing_event_id=e.id,grace_until=null,updated_at=p_processed_at where id=s.id;\n return query select true,''succeeded''::text,''renewal processed''::text,e.id,l.id,p_period_end,v_end,v_balance,e.attempt_count;\nend $fn$;\nrevoke all on function public.process_subscription_renewal_v2(uuid,timestamptz,text,timestamptz) from public,anon,authenticated;\ngrant execute on function public.process_subscription_renewal_v2(uuid,timestamptz,text,timestamptz) to service_role;\n\nnotify pgrst, ''reload schema'';\ncommit;\n"], "idempotency_key": null}]'::jsonb value;
