d": true}, "identity": "storage.allow_any_operation(text[])", "definition": "CREATE OR REPLACE FUNCTION storage.allow_any_operation(expected_operations text[])\n RETURNS boolean\n LANGUAGE sql\n STABLE\nAS $function$\n  WITH current_operation AS (\n    SELECT storage.operation() AS raw_operation\n  ),\n  normalized AS (\n    SELECT CASE\n      WHEN raw_operation LIKE ''storage.%'' THEN substr(raw_operation, 9)\n      ELSE raw_operation\n    END AS current_operation\n    FROM current_operation\n  )\n  SELECT EXISTS (\n    SELECT 1\n    FROM normalized n\n    CROSS JOIN LATERAL unnest(expected_operations) AS expected_operation\n    WHERE expected_operation IS NOT NULL\n      AND expected_operation <> ''''\n      AND n.current_operation = CASE\n        WHEN expected_operation LIKE ''storage.%'' THEN substr(expected_operation, 9)\n        ELSE expected_operation\n      END\n  );\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.allow_only_operation(text)\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.allow_only_operation(text)", "definition": "CREATE OR REPLACE FUNCTION storage.allow_only_operation(expected_operation text)\n RETURNS boolean\n LANGUAGE sql\n STABLE\nAS $function$\n  WITH current_operation AS (\n    SELECT storage.operation() AS raw_operation\n  ),\n  normalized AS (\n    SELECT\n      CASE\n        WHEN raw_operation LIKE ''storage.%'' THEN substr(raw_operation, 9)\n        ELSE raw_operation\n      END AS current_operation,\n      CASE\n        WHEN expected_operation LIKE ''storage.%'' THEN substr(expected_operation, 9)\n        ELSE expected_operation\n      END AS requested_operation\n    FROM current_operation\n  )\n  SELECT CASE\n    WHEN requested_operation IS NULL OR requested_operation = '''' THEN FALSE\n    ELSE COALESCE(current_operation = requested_operation, FALSE)\n  END\n  FROM normalized;\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.can_insert_object(text,text,uuid,jsonb)\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.can_insert_object(text,text,uuid,jsonb)", "definition": "CREATE OR REPLACE FUNCTION storage.can_insert_object(bucketid text, name text, owner uuid, metadata jsonb)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  INSERT INTO \"storage\".\"objects\" (\"bucket_id\", \"name\", \"owner\", \"metadata\") VALUES (bucketid, name, owner, metadata);\n  -- hack to rollback the successful insert\n  RAISE sqlstate ''PT200'' using\n  message = ''ROLLBACK'',\n  detail = ''rollback successful insert'';\nEND\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.enforce_bucket_lifecycle_service_role()\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.enforce_bucket_lifecycle_service_role()", "definition": "CREATE OR REPLACE FUNCTION storage.enforce_bucket_lifecycle_service_role()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog''\nAS $function$\nBEGIN\n  IF current_user::text IS DISTINCT FROM TG_ARGV[0]\n     AND (\n       OLD.lifecycle_configuration IS DISTINCT FROM NEW.lifecycle_configuration\n       OR OLD.lifecycle_configuration_generation IS DISTINCT FROM NEW.lifecycle_configuration_generation\n     ) THEN\n    -- AFTER runs only after caller RLS has accepted the proposed row. The API\n    -- recognizes this specific error after rolling back its permission probe;\n    -- direct non-service writes still fail and cannot persist the change.\n    RAISE EXCEPTION ''bucket control columns may only be changed by the configured storage service role''\n      USING ERRCODE = ''PST01'',\n            SCHEMA = TG_TABLE_SCHEMA,\n            TABLE = TG_TABLE_NAME,\n            CONSTRAINT = TG_NAME;\n  END IF;\n\n  RETURN NULL;\nEND;\n$function$\n", "configuration": ["search_path=pg_catalog"], "security_definer": false}, "[\"storage\", \"storage.enforce_bucket_name_length()\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.enforce_bucket_name_length()", "definition": "CREATE OR REPLACE FUNCTION storage.enforce_bucket_name_length()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nbegin\n    if length(new.name) > 100 then\n        raise exception ''bucket name \"%\" is too long (% characters). Max is 100.'', new.name, length(new.name);\n    end if;\n    return new;\nend;\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.extension(text)\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.extension(text)", "definition": "CREATE OR REPLACE FUNCTION storage.extension(name text)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    _parts text[];\n    _filename text;\nBEGIN\n    -- Split on \"/\" to get path segments\n    SELECT string_to_array(name, ''/'') INTO _parts;\n    -- Get the last path segment (the actual filename)\n    SELECT _parts[array_length(_parts, 1)] INTO _filename;\n    -- Extract extension: reverse, split on ''.'', then reverse again\n    RETURN reverse(split_part(reverse(_filename), ''.'', 1));\nEND\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.filename(text)\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.filename(text)", "definition": "CREATE OR REPLACE FUNCTION storage.filename(name text)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    _parts text[];\nBEGIN\n    SELECT string_to_array(name, ''/'') INTO _parts;\n    RETURN _parts[array_length(_parts, 1)];\nEND\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.foldername(text)\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.foldername(text)", "definition": "CREATE OR REPLACE FUNCTION storage.foldername(name text)\n RETURNS text[]\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    _parts text[];\nBEGIN\n    -- Split on \"/\" to get path segments\n    SELECT string_to_array(name, ''/'') INTO _parts;\n    -- Return everything except the last segment\n    RETURN _parts[1 : array_length(_parts,1) - 1];\nEND\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.get_common_prefix(text,text,text)\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.get_common_prefix(text,text,text)", "definition": "CREATE OR REPLACE FUNCTION storage.get_common_prefix(p_key text, p_prefix text, p_delimiter text)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\nAS $function$\nSELECT CASE\n    WHEN p_delimiter <> ''''\n         AND position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1)) > 0\n    THEN left(\n        p_key,\n        length(p_prefix)\n            + position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1))\n            + length(p_delimiter) - 1\n    )\n    ELSE NULL\nEND;\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.get_size_by_bucket(text,text)\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.get_size_by_bucket(text,text)", "definition": "CREATE OR REPLACE FUNCTION storage.get_size_by_bucket(noncurrent_versions text DEFAULT ''include''::text, delete_markers text DEFAULT ''include''::text)\n RETURNS TABLE(size bigint, bucket_id text)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nBEGIN\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, ''include'');\n    delete_markers := COALESCE(delete_markers, ''include'');\n    IF noncurrent_versions NOT IN (''exclude'', ''only'', ''include'') THEN\n        noncurrent_versions := ''include'';\n    END IF;\n    IF delete_markers NOT IN (''exclude'', ''only'', ''include'') THEN\n        delete_markers := ''include'';\n    END IF;\n\n    return query\n        select sum((metadata->>''size'')::bigint)::bigint as size, obj.bucket_id\n        from \"storage\".objects as obj\n        where (noncurrent_versions != ''exclude'' OR obj.archived_at IS NULL)\n          and (noncurrent_versions != ''only'' OR obj.archived_at IS NOT NULL)\n          and (delete_markers != ''exclude'' OR NOT obj.is_delete_marker)\n          and (delete_markers != ''only'' OR obj.is_delete_marker)\n        group by obj.bucket_id;\nEND\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.list_multipart_uploads_with_delimiter(text,text,text,integer,text,text,text)\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.list_multipart_uploads_with_delimiter(text,text,text,integer,text,text,text)", "definition": "CREATE OR REPLACE FUNCTION storage.list_multipart_uploads_with_delimiter(bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, next_key_token text DEFAULT ''''::text, next_upload_token text DEFAULT ''''::text, raw_prefix_param text DEFAULT NULL::text)\n RETURNS TABLE(key text, id text, created_at timestamp with time zone)\n LANGUAGE sql\n STABLE\nAS $function$\nWITH candidates AS (\n    SELECT\n        upload.key AS object_key,\n        CASE\n            WHEN position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1)) > 0\n            THEN left(\n                upload.key,\n                length(coalesce($7, $2))\n                    + position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1))\n                    + length($3) - 1\n            )\n            ELSE upload.key\n        END AS result_key,\n        upload.id,\n        upload.created_at,\n        position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1)) > 0 AS is_common_prefix\n    FROM storage.s3_multipart_uploads AS upload\n    WHERE upload.bucket_id = $1\n      AND upload.key COLLATE \"C\" LIKE $2 || ''%''\n), filtered AS (\n    SELECT candidate.*\n    FROM candidates AS candidate\n    WHERE $5 = ''''\n       OR candidate.result_key COLLATE \"C\" > $5\n       OR (\n           candidate.result_key COLLATE \"C\" = $5\n           AND NOT candidate.is_common_prefix\n           AND $6 <> ''''\n           -- A completed or aborted marker repeats the remaining same-key uploads.\n           AND COALESCE(\n               (candidate.created_at, candidate.id COLLATE \"C\") > (\n                   SELECT marker.created_at, marker.id COLLATE \"C\"\n                   FROM storage.s3_multipart_uploads AS marker\n                   WHERE marker.bucket_id = $1\n                     AND marker.key COLLATE \"C\" = $5\n                     AND marker.id = $6\n               ),\n               TRUE\n           )\n       )\n), ranked AS (\n    SELECT\n        filtered.*,\n        row_number() OVER (\n            PARTITION BY filtered.result_key COLLATE \"C\"\n            ORDER BY filtered.created_at, filtered.id COLLATE \"C\"\n        ) AS prefix_rank\n    FROM filtered\n)\nSELECT ranked.result_key, ranked.id, ranked.created_at\nFROM ranked\nWHERE NOT ranked.is_common_prefix OR ranked.prefix_rank = 1\nORDER BY ranked.result_key COLLATE \"C\", ranked.created_at, ranked.id COLLATE \"C\"\nLIMIT $4;\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.list_objects_with_delimiter(text,text,text,integer,text,text,text,text,text,timestamp with time zone,text)\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.list_objects_with_delimiter(text,text,text,integer,text,text,text,text,text,timestamp with time zone,text)", "definition": "CREATE OR REPLACE FUNCTION storage.list_objects_with_delimiter(_bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, start_after text DEFAULT ''''::text, next_token text DEFAULT ''''::text, sort_order text DEFAULT ''asc''::text, noncurrent_versions text DEFAULT ''exclude''::text, delete_markers text DEFAULT ''exclude''::text, next_token_archived_at timestamp with time zone DEFAULT NULL::timestamp with time zone, next_token_version text DEFAULT ''''::text)\n RETURNS TABLE(name text, id uuid, metadata jsonb, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n    v_peek_name TEXT;\n    v_current RECORD;\n    v_common_prefix TEXT;\n\n    -- Configuration\n    v_is_asc BOOLEAN;\n    v_prefix TEXT;\n    v_start TEXT;\n    v_start_relative TEXT;\n    v_upper_bound TEXT;\n    v_file_batch_size INT;\n    v_version_filter TEXT;\n\n    -- true when noncurrent_versions can return >1 row per name; keeps them\n    -- ordered most-recent-first and lets pagination resume mid-key\n    v_multi_row BOOLEAN;\n    v_name_order TEXT;\n    v_exact_range_predicate TEXT;\n    v_strict_range_predicate TEXT;\n    v_inclusive_range_predicate TEXT;\n\n    -- Seek state for the current name. archived_at is normalized to JavaScript''s\n    -- millisecond precision and version breaks ties within the same millisecond.\n    -- Current rows use ''infinity''; NULL means no tiebreak has been established.\n    v_next_seek TEXT;\n    v_next_seek_at TIMESTAMPTZ;\n    v_next_seek_version TEXT;\n    v_next_seek_strict BOOLEAN := false;\n    v_cursor_is_folder BOOLEAN;\n    v_count INT := 0;\n    v_previous_seek TEXT;\n    v_previous_seek_at TIMESTAMPTZ;\n    v_previous_seek_version TEXT;\n    v_previous_count INT;\n\n    -- Dynamic SQL for batch query only\n    v_batch_query TEXT;\n    v_batch_query_strict TEXT;\n    v_delete_marker_peek_query TEXT;\n    v_delete_marker_peek_query_strict TEXT;\n\nBEGIN\n    -- ========================================================================\n    -- INITIALIZATION\n    -- ========================================================================\n    v_is_asc := lower(coalesce(sort_order, ''asc'')) = ''asc'';\n    v_prefix := coalesce(prefix_param, '''');\n    v_start := CASE WHEN coalesce(next_token, '''') <> '''' THEN next_token ELSE coalesce(start_after, '''') END;\n    v_file_batch_size := LEAST(GREATEST(max_keys * 2, 100), 1000);\n    v_next_seek_at := NULL;\n    v_next_seek_version := '''';\n\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, ''exclude'');\n    delete_markers := COALESCE(delete_markers, ''exclude'');\n    IF noncurrent_versions NOT IN (''exclude'', ''only'', ''include'') THEN\n        noncurrent_versions := ''exclude'';\n    END IF;\n    IF delete_markers NOT IN (''exclude'', ''only'', ''include'') THEN\n        delete_markers := ''exclude'';\n    END IF;\n\n    v_multi_row := noncurrent_versions IN (''only'', ''include'');\n    v_name_order := CASE WHEN v_is_asc THEN ''ASC'' ELSE ''DESC'' END;\n\n    v_version_filter := '''';\n    IF noncurrent_versions = ''exclude'' THEN\n        v_version_filter := v_version_filter || '' AND o.archived_at IS NULL'';\n    ELSIF noncurrent_versions = ''only'' THEN\n        v_version_filter := v_version_filter || '' AND o.archived_at IS NOT NULL'';\n    END IF;\n    IF delete_markers = ''exclude'' THEN\n        v_version_filter := v_version_filter || '' AND NOT o.is_delete_marker'';\n    ELSIF delete_markers = ''only'' THEN\n        v_version_filter := v_version_filter || '' AND o.is_delete_marker'';\n    END IF;\n\n    -- Calculate upper bound for prefix filtering (bytewise, using COLLATE \"C\")\n    IF v_prefix = '''' THEN\n        v_upper_bound := NULL;\n    ELSE\n        v_upper_bound := left(v_prefix, -1) || chr(ascii(right(v_prefix, 1)) + 1);\n    END IF;\n\n    -- Keep caller-provided cursors inside the requested prefix range.\n    IF v_start <> '''' AND v_upper_bound IS NOT NULL THEN\n        IF v_is_asc THEN\n            IF v_start COLLATE \"C\" < v_prefix COLLATE \"C\" THEN\n                v_start := '''';\n            ELSIF v_start COLLATE \"C\" >= v_upper_bound COLLATE \"C\" THEN\n                RETURN;\n            END IF;\n        ELSE\n            IF v_start COLLATE \"C\" < v_prefix COLLATE \"C\" THEN\n                RETURN;\n            ELSIF v_start COLLATE \"C\" >= v_upper_bound COLLATE \"C\" THEN\n                v_start := '''';\n            END IF;\n        END IF;\n    END IF;\n\n    v_start_relative := substring(v_start FROM length(v_prefix) + 1);\n\n    -- Direction affects only the indexed name range and its ordering. Cursor\n    -- state transitions and within-key version ordering stay shared.\n    IF v_is_asc THEN\n        v_exact_range_predicate := ''TRUE'';\n        v_strict_range_predicate := ''o.name COLLATE \"C\" > $2'';\n        v_inclusive_range_predicate := ''o.name COLLATE \"C\" >= $2'';\n        IF v_upper_bound IS NOT NULL THEN\n            v_exact_range_predicate := ''o.name COLLATE \"C\" < $3'';\n            v_strict_range_predicate := v_strict_range_predicate || '' AND o.name COLLATE \"C\" < $3'';\n            v_inclusive_range_predicate := v_inclusive_range_predicate || '' AND o.name COLLATE \"C\" < $3'';\n        END IF;\n    ELSE\n        v_exact_range_predicate := ''TRUE'';\n        v_strict_range_predicate := ''o.name COLLATE \"C\" < $2'';\n        v_inclusive_range_predicate := ''o.name COLLATE \"C\" < $2'';\n        IF v_prefix <> '''' THEN\n            v_exact_range_predicate := ''o.name COLLATE \"C\" >= $3'';\n            v_strict_range_predicate := v_strict_range_predicate || '' AND o.name COLLATE \"C\" >= $3'';\n            v_inclusive_range_predicate := v_inclusive_range_predicate || '' AND o.name COLLATE \"C\" >= $3'';\n        END IF;\n    END IF;\n\n    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)\n    -- The multi-row order matches the externally serialized cursor exactly:\n    -- archived_at at millisecond precision, then version as the final tiebreak.\n    --\n    -- When v_multi_row, the seek is a keyset tuple comparison (\"name > $2 OR\n    -- (name = $2 AND tiebreak)\") - Postgres won''t split that OR into indexable\n    -- form (confirmed even with fully literal values), so as one WHERE clause\n    -- it forces a full bucket scan filtered row-by-row. Splitting it into two\n    -- independently-indexable branches (exact name match with the tiebreak\n    -- filter, vs. strictly-past names) combined with UNION ALL lets each\n    -- branch keep name as a real index condition; the outer ORDER BY/LIMIT\n    -- re-merges them into the same page the single query used to produce.\n    IF v_multi_row THEN\n        v_batch_query := format(\n            $sql$\n            SELECT *\n            FROM (\n                (\n                    SELECT o.name, o.id, o.updated_at, o.created_at,\n                           o.last_accessed_at, o.metadata, o.version,\n                           o.archived_at, o.is_delete_marker, o.is_versioned\n                    FROM storage.objects o\n                    WHERE o.bucket_id = $1\n                      AND o.name COLLATE \"C\" = $2\n                      AND %s\n                      AND NOT $7::boolean\n                      AND (\n                          $5::timestamptz IS NULL\n                          OR COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) < $5\n                          OR (\n                              COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) = $5\n                              AND COALESCE(o.version, '''') > $6\n                          )\n                      )\n                      %s\n                    ORDER BY\n                        COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) DESC,\n                        COALESCE(o.version, '''') ASC\n                    LIMIT $4\n                )\n                UNION ALL\n                (\n                    SELECT o.name, o.id, o.updated_at, o.created_at,\n                           o.last_accessed_at, o.metadata, o.version,\n                           o.archived_at, o.is_delete_marker, o.is_versioned\n                    FROM storage.objects o\n                    WHERE o.bucket_id = $1\n                      AND %s\n                      %s\n                    ORDER BY\n                        o.name COLLATE \"C\" %s,\n                        COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) DESC,\n                        COALESCE(o.version, '''') ASC\n                    LIMIT $4\n                )\n            ) sub\n            ORDER BY\n                sub.name COLLATE \"C\" %s,\n                COALESCE(date_trunc(''milliseconds'', sub.archived_at), ''infinity''::timestamptz) DESC,\n                COALESCE(sub.version, '''') ASC\n            LIMIT $4\n            $sql$,\n            v_exact_range_predicate,\n            v_version_filter,\n            v_strict_range_predicate,\n            v_version_filter,\n            v_name_order,\n            v_name_order\n        );\n    ELSE\n        v_batch_query := format(\n            $sql$\n            SELECT o.name, o.id, o.updated_at, o.created_at,\n                   o.last_accessed_at, o.metadata, o.version,\n                   o.archived_at, o.is_delete_marker, o.is_versioned\n            FROM storage.objects o\n            WHERE o.bucket_id = $1\n              AND %s\n              %s\n            ORDER BY o.name COLLATE \"C\" %s, o.archived_at DESC\n            LIMIT $4\n            $sql$,\n            v_inclusive_range_predicate,\n            v_version_filter,\n            v_name_order\n        );\n\n        -- Strict counterpart of the query above: used once the single-row\n        -- ASC batch advance (below) has left v_next_seek pointing at the\n        -- last row already emitted, so an inclusive predicate would\n        -- re-match it forever. Only single-row mode ever sets strict mode,\n        -- so this variant is never needed when v_multi_row.\n        v_batch_query_strict := format(\n            $sql$\n            SELECT o.name, o.id, o.updated_at, o.created_at,\n                   o.last_accessed_at, o.metadata, o.version,\n                   o.archived_at, o.is_delete_marker, o.is_versioned\n            FROM storage.objects o\n            WHERE o.bucket_id = $1\n              AND %s\n              %s\n            ORDER BY o.name COLLATE \"C\" %s, o.archived_at DESC\n            LIMIT $4\n            $sql$,\n            v_strict_range_predicate,\n            v_version_filter,\n            v_name_order\n        );\n    END IF;\n\n    -- The static peek predicates cannot use the partial delete-marker index\n    -- once PL/pgSQL switches to a generic plan because whether\n    -- is_delete_marker is required remains parameter-dependent. Reuse the\n    -- already-specialized batch query with a one-row limit for this sparse\n    -- filter so the plan sees a literal `o.is_delete_marker` predicate.\n    IF delete_markers = ''only'' THEN\n        v_delete_marker_peek_query :=\n            ''SELECT marker_page.name FROM ('' || v_batch_query || '') marker_page LIMIT 1'';\n        IF NOT v_multi_row THEN\n            v_delete_marker_peek_query_strict :=\n                ''SELECT marker_page.name FROM ('' || v_batch_query_strict || '') marker_page LIMIT 1'';\n        END IF;\n    END IF;\n\n    -- ========================================================================\n    -- SEEK INITIALIZATION: Determine starting position\n    -- ========================================================================\n    IF v_start = '''' THEN\n        IF v_is_asc THEN\n            v_next_seek := v_prefix;\n        ELSE\n            -- DESC without cursor performs one specialized initial seek so\n            -- partial current-version and delete-marker indexes remain available.\n            EXECUTE format(\n                ''SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1%s%s ORDER BY o.name COLLATE \"C\" DESC LIMIT 1'',\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN '' AND o.name COLLATE \"C\" >= $2 AND o.name COLLATE \"C\" < $3''\n                    ELSE ''''\n                END,\n                v_version_filter\n            )\n            INTO v_next_seek\n            USING _bucket_id, v_prefix, v_upper_bound;\n\n            IF v_next_seek IS NOT NULL THEN\n                v_next_seek := v_next_seek || delimiter_param;\n            ELSE\n                RETURN;\n            END IF;\n        END IF;\n    ELSE\n        -- Folder continuation tokens retain their trailing delimiter. A\n        -- delimiter-less startAfter is always a literal key boundary.\n        v_cursor_is_folder := delimiter_param <> ''''\n            AND v_start_relative <> ''''\n            AND right(v_start_relative, length(delimiter_param)) = delimiter_param;\n\n        IF v_cursor_is_folder THEN\n            v_next_seek := CASE\n                WHEN right(v_start, length(delimiter_param)) = delimiter_param\n                    THEN v_start\n                ELSE v_start || delimiter_param\n            END;\n            IF v_is_asc THEN\n                v_next_seek := left(v_next_seek, -1)\n                    || chr(ascii(right(v_next_seek, 1)) + 1);\n            END IF;\n            v_next_seek_strict := NOT v_is_asc;\n        ELSE\n            -- leaf object: when v_multi_row, stay on v_start with the\n            -- caller-supplied tiebreak so a page boundary mid-key resumes\n            -- that key''s remaining rows instead of skipping them. Truncate\n            -- to milliseconds like every other v_next_seek_at assignment -\n            -- harmless today since object.ts''s cursor always round-trips\n            -- through JS Date first, but this shouldn''t rely on that.\n            IF v_multi_row THEN\n                v_next_seek := v_start;\n                v_next_seek_at := date_trunc(''milliseconds'', next_token_archived_at);\n                v_next_seek_version := coalesce(next_token_version, '''');\n                v_next_seek_strict := coalesce(next_token, '''') = '''';\n            ELSIF v_is_asc THEN\n                v_next_seek := v_start;\n                v_next_seek_strict := true;\n            ELSE\n                v_next_seek := v_start;\n            END IF;\n        END IF;\n    END IF;\n\n    -- ========================================================================\n    -- MAIN LOOP: Hybrid peek-then-batch algorithm\n    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch\n    -- ========================================================================\n    LOOP\n        EXIT WHEN v_count >= max_keys;\n\n        v_previous_seek := v_next_seek;\n        v_previous_seek_at := v_next_seek_at;\n        v_previous_seek_version := v_next_seek_version;\n        v_previous_count := v_count;\n\n        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)\n        -- v_multi_row is branched here (rather than folded into the WHERE\n        -- clause as a bound parameter) so each concrete query keeps an\n        -- unconditional seek predicate - once PL/pgSQL switches to its\n        -- cached generic plan (after 5 calls), a parameter-gated\n        -- \"(NOT v_multi_row AND name >= $x) OR (v_multi_row AND ...)\"\n        -- predicate stops the planner from using name as an index\n        -- condition at all, degrading every subsequent peek to a full\n        -- index scan filtered row-by-row instead of a bounded range scan.\n        -- v_multi_row''s seek predicate is a keyset tuple comparison\n        -- (\"name > x OR (name = x AND tiebreak)\") - Postgres does not\n        -- split this OR into indexable form even with fully literal\n        -- values, so it falls back to a full scan filtered row-by-row.\n        -- Splitting it into two independently-indexable branches (exact\n        -- name match with the tiebreak filter, vs. strictly-past name)\n        -- combined with UNION ALL lets each branch keep name as a real\n        -- index condition; the outer ORDER BY/LIMIT picks whichever of\n        -- the (at most 2) rows sorts first.\n        IF delete_markers = ''only'' THEN\n            EXECUTE CASE WHEN v_next_seek_strict AND NOT v_multi_row\n                THEN v_delete_marker_peek_query_strict\n                ELSE v_delete_marker_peek_query\n            END\n                INTO v_peek_name\n                USING _bucket_id, v_next_seek,\n                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END,\n                    1, v_next_seek_at, v_next_seek_version, v_next_seek_strict;\n        ELSIF v_multi_row THEN\n            IF v_is_asc THEN\n                IF v_upper_bound IS NOT NULL THEN\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND o.name COLLATE \"C\" < v_upper_bound\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '''') > v_next_seek_version))\n                           AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                           AND (delete_markers != ''only'' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" > v_next_seek AND o.name COLLATE \"C\" < v_upper_bound\n                           AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                           AND (delete_markers != ''only'' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" ASC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" ASC LIMIT 1;\n                ELSE\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '''') > v_next_seek_version))\n                           AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                           AND (delete_markers != ''only'' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" > v_next_seek\n                           AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                           AND (delete_markers != ''only'' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" ASC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" ASC LIMIT 1;\n                END IF;\n            ELSE\n                IF v_upper_bound IS NOT NULL THEN\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND o.name COLLATE \"C\" >= v_prefix\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '''') > v_next_seek_version))\n                           AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                           AND (delete_markers != ''only'' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" < v_next_seek AND o.name COLLATE \"C\" >= v_prefix\n                           AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                           AND (delete_markers != ''only'' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" DESC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" DESC LIMIT 1;\n                ELSE\n                    SELECT sub.name INTO v_peek_name FROM (\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" = v_next_seek\n                           AND NOT v_next_seek_strict\n                           AND (v_next_seek_at IS NULL\n                                OR COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) < v_next_seek_at\n                                OR (COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) = v_next_seek_at\n                                    AND COALESCE(o.version, '''') > v_next_seek_version))\n                           AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                           AND (delete_markers != ''only'' OR o.is_delete_marker)\n                         ORDER BY COALESCE(date_trunc(''milliseconds'', o.archived_at), ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT 1)\n                        UNION ALL\n                        (SELECT o.name FROM storage.objects o\n                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE \"C\" < v_next_seek\n                           AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n                           AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n                           AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                           AND (delete_markers != ''only'' OR o.is_delete_marker)\n                         ORDER BY o.name COLLATE \"C\" DESC LIMIT 1)\n                    ) sub ORDER BY sub.name COLLATE \"C\" DESC LIMIT 1;\n                END IF;\n            END IF;\n        ELSE\n            -- Single-row mode is always noncurrent_versions=''exclude''. Keep\n            -- this predicate literal so generic plans use the current index.\n            IF v_is_asc THEN\n                IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" > v_next_seek\n                      AND o.name COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                      AND (delete_markers != ''only'' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_next_seek_strict THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" > v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                      AND (delete_markers != ''only'' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" >= v_next_seek\n                      AND o.name COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                      AND (delete_markers != ''only'' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                ELSE\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" >= v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                      AND (delete_markers != ''only'' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" ASC LIMIT 1;\n                END IF;\n            ELSE\n                IF v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" < v_next_seek\n                      AND o.name COLLATE \"C\" >= v_prefix\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                      AND (delete_markers != ''only'' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" DESC LIMIT 1;\n                ELSE\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = _bucket_id\n                      AND o.name COLLATE \"C\" < v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                      AND (delete_markers != ''only'' OR o.is_delete_marker)\n                    ORDER BY o.name COLLATE \"C\" DESC LIMIT 1;\n                END IF;\n            END IF;\n        END IF;\n\n        EXIT WHEN v_peek_name IS NULL;\n\n        -- STEP 2: Check if this is a FOLDER or FILE\n        v_common_prefix := storage.get_common_prefix(v_peek_name, v_prefix, delimiter_param);\n\n        IF v_common_prefix IS NOT NULL THEN\n            -- FOLDER: Emit and skip to next folder (no heap access needed)\n            name := v_common_prefix;\n            id := NULL;\n            updated_at := NULL;\n            created_at := NULL;\n            last_accessed_at := NULL;\n            metadata := NULL;\n            version := NULL;\n            archived_at := NULL;\n            is_delete_marker := NULL;\n            is_versioned := NULL;\n            RETURN NEXT;\n            v_count := v_count + 1;\n\n            -- Advance seek past the folder range\n            IF v_is_asc THEN\n                v_next_seek := left(v_common_prefix, -1)\n                    || chr(ascii(right(v_common_prefix, 1)) + 1);\n            ELSE\n                v_next_seek := v_common_prefix;\n            END IF;\n            v_next_seek_at := NULL;\n            v_next_seek_version := '''';\n            v_next_seek_strict := NOT v_is_asc;\n        ELSE\n            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)\n            -- For ASC: upper_bound is the exclusive upper limit (< condition)\n            -- For DESC: prefix is the inclusive lower limit (>= condition)\n            FOR v_current IN EXECUTE CASE WHEN v_next_seek_strict AND NOT v_multi_row THEN v_batch_query_strict ELSE v_batch_query END\n                USING _bucket_id, v_next_seek,\n                CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END, v_file_batch_size, v_next_seek_at, v_next_seek_version,\n                v_next_seek_strict\n            LOOP\n                v_common_prefix := storage.get_common_prefix(v_current.name, v_prefix, delimiter_param);\n\n                IF v_common_prefix IS NOT NULL THEN\n                    -- Hit a folder: exit batch, let peek handle it. Reset\n                    -- strict mode too it may have been set by an earlier\n                    -- row in this same batch (see the single-row ASC advance\n                    -- below), and v_next_seek here is the folder-triggering\n                    -- row''s own name, which the next peek must find inclusively.\n                    v_next_seek := CASE\n                        WHEN v_is_asc THEN v_current.name\n                        ELSE v_current.name || delimiter_param\n                    END;\n                    v_next_seek_at := NULL;\n                    v_next_seek_version := '''';\n                    v_next_seek_strict := false;\n                    EXIT;\n                END IF;\n\n                -- Emit file\n                name := v_current.name;\n                id := v_current.id;\n                updated_at := v_current.updated_at;\n                created_at := v_current.created_at;\n                last_accessed_at := v_current.last_accessed_at;\n                metadata := v_current.metadata;\n                version := v_current.version;\n                archived_at := v_current.archived_at;\n                is_delete_marker := v_current.is_delete_marker;\n                is_versioned := v_current.is_versioned;\n                RETURN NEXT;\n                v_count := v_count + 1;\n\n                -- when v_multi_row, stay on this name and record its\n                -- archived_at as the new tiebreak so remaining rows for the\n                -- same key are picked up before moving to the next name\n                IF v_multi_row THEN\n                    v_next_seek := v_current.name;\n                    v_next_seek_at := COALESCE(date_trunc(''milliseconds'', v_current.archived_at), ''infinity''::timestamptz);\n                    v_next_seek_version := COALESCE(v_current.version, '''');\n                    v_next_seek_strict := false;\n                ELSIF v_is_asc THEN\n                    -- Appending the delimiter as a fake lexical successor\n                    -- would skip a real key like `name || ''!''` (or any\n                    -- character sorting below the delimiter), which sorts\n                    -- between `name` and `name || delimiter`. Track the real\n                    -- name and mark the next comparison strict instead.\n                    v_next_seek := v_current.name;\n                    v_next_seek_strict := true;\n                ELSE\n                    v_next_seek := v_current.name;\n                END IF;\n\n                EXIT WHEN v_count >= max_keys;\n            END LOOP;\n        END IF;\n\n        IF v_count = v_previous_count\n           AND v_next_seek IS NOT DISTINCT FROM v_previous_seek\n           AND v_next_seek_at IS NOT DISTINCT FROM v_previous_seek_at\n           AND v_next_seek_version IS NOT DISTINCT FROM v_previous_seek_version THEN\n            RAISE EXCEPTION ''storage.list_objects_with_delimiter made no progress at seek (%, %, %)'',\n                v_next_seek, v_next_seek_at, v_next_seek_version;\n        END IF;\n    END LOOP;\nEND;\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.operation()\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.operation()", "definition": "CREATE OR REPLACE FUNCTION storage.operation()\n RETURNS text\n LANGUAGE plpgsql\n STABLE\nAS $function$\nBEGIN\n    RETURN current_setting(''storage.operation'', true);\nEND;\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.protect_bucket_control_columns()\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.protect_bucket_control_columns()", "definition": "CREATE OR REPLACE FUNCTION storage.protect_bucket_control_columns()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog''\nAS $function$\nDECLARE\n  configuration_changed boolean;\nBEGIN\n  IF TG_OP = ''INSERT'' THEN\n    IF NEW.lifecycle_configuration IS NOT NULL\n       OR NEW.lifecycle_configuration_generation IS NOT NULL THEN\n      IF NOT pg_has_role(current_user, TG_ARGV[0], ''MEMBER'') THEN\n        RAISE EXCEPTION ''only members of the configured storage service role may insert lifecycle policy state''\n          USING ERRCODE = ''42501'',\n                HINT = format(\n                  ''Insert with both lifecycle columns NULL and configure lifecycle through the Storage API afterward, or insert as a member of %I.'',\n                  TG_ARGV[0]\n                );\n      END IF;\n    END IF;\n\n    RETURN NEW;\n  END IF;\n\n  configuration_changed =\n    OLD.lifecycle_configuration IS DISTINCT FROM NEW.lifecycle_configuration\n    OR OLD.lifecycle_configuration_generation IS DISTINCT FROM NEW.lifecycle_configuration_generation;\n\n  IF NOT configuration_changed THEN\n    RETURN NEW;\n  END IF;\n\n  IF NEW.type IS DISTINCT FROM ''STANDARD'' THEN\n    RAISE EXCEPTION ''bucket versioning and lifecycle controls require a Standard bucket''\n      USING ERRCODE = ''0A000'';\n  END IF;\n\n  IF NEW.lifecycle_configuration IS NULL\n     AND NEW.lifecycle_configuration_generation IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  IF NEW.lifecycle_configuration IS NULL\n     OR NEW.lifecycle_configuration_generation IS NULL\n     OR OLD.lifecycle_configuration IS NOT DISTINCT FROM NEW.lifecycle_configuration\n     OR OLD.lifecycle_configuration_generation IS NOT DISTINCT FROM NEW.lifecycle_configuration_generation THEN\n    RAISE EXCEPTION ''a changed lifecycle policy requires a new non-null generation''\n      USING ERRCODE = ''22023'';\n  END IF;\n\n  RETURN NEW;\nEND;\n$function$\n", "configuration": ["search_path=pg_catalog"], "security_definer": false}, "[\"storage\", \"storage.protect_delete()\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.protect_delete()", "definition": "CREATE OR REPLACE FUNCTION storage.protect_delete()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Check if storage.allow_delete_query is set to ''true''\n    IF COALESCE(current_setting(''storage.allow_delete_query'', true), ''false'') != ''true'' THEN\n        RAISE EXCEPTION ''Direct deletion from storage tables is not allowed. Use the Storage API instead.''\n            USING HINT = ''This prevents accidental data loss from orphaned objects.'',\n                  ERRCODE = ''42501'';\n    END IF;\n    RETURN NULL;\nEND;\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.search_by_timestamp(text,text,integer,integer,text,text,text,text,text,text,text)\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.search_by_timestamp(text,text,integer,integer,text,text,text,text,text,text,text)", "definition": "CREATE OR REPLACE FUNCTION storage.search_by_timestamp(p_prefix text, p_bucket_id text, p_limit integer, p_level integer, p_start_after text, p_sort_order text, p_sort_column text, p_sort_column_after text, noncurrent_versions text DEFAULT ''exclude''::text, delete_markers text DEFAULT ''exclude''::text, p_start_after_version text DEFAULT ''''::text)\n RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n    v_cursor_op text;\n    v_query text;\n    v_prefix text;\n    v_prefix_pattern text;\n    v_sort_order text;\n    v_sort_column text;\n    v_version_tiebreak text;\nBEGIN\n    v_prefix := coalesce(p_prefix, '''');\n    -- Keep the raw prefix for common-prefix calculations and escape only LIKE metacharacters.\n    v_prefix_pattern := replace(v_prefix, chr(92), chr(92) || chr(92));\n    v_prefix_pattern := replace(v_prefix_pattern, ''%'', chr(92) || ''%'');\n    v_prefix_pattern := replace(v_prefix_pattern, ''_'', chr(92) || ''_'');\n\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, ''exclude'');\n    delete_markers := COALESCE(delete_markers, ''exclude'');\n    IF noncurrent_versions NOT IN (''exclude'', ''only'', ''include'') THEN\n        noncurrent_versions := ''exclude'';\n    END IF;\n    IF delete_markers NOT IN (''exclude'', ''only'', ''include'') THEN\n        delete_markers := ''exclude'';\n    END IF;\n\n    -- $9 is only populated in multi-row mode; it''s always '''' otherwise, so\n    -- only use each row''s real version as a tiebreak in multi-row mode.\n    v_version_tiebreak := CASE WHEN noncurrent_versions IN (''only'', ''include'') THEN ''COALESCE(version, '''''''')'' ELSE '''''''''''' END;\n\n    -- Defense-in-depth: this function is independently reachable and must\n    -- not trust p_sort_order/p_sort_column to already be validated by a\n    -- caller. Normalize to the same strict allow-list storage.search_v2\n    -- uses before interpolating anything into dynamic SQL below.\n    v_sort_order := lower(coalesce(p_sort_order, ''asc''));\n    IF v_sort_order NOT IN (''asc'', ''desc'') THEN\n        v_sort_order := ''asc'';\n    END IF;\n\n    v_sort_column := lower(coalesce(p_sort_column, ''updated_at''));\n    IF v_sort_column NOT IN (''updated_at'', ''created_at'') THEN\n        v_sort_column := ''updated_at'';\n    END IF;\n\n    IF v_sort_order = ''asc'' THEN\n        v_cursor_op := ''>'';\n    ELSE\n        v_cursor_op := ''<'';\n    END IF;\n\n    v_query := format($sql$\n        WITH raw_objects AS (\n            SELECT\n                o.name AS obj_name,\n                o.id AS obj_id,\n                o.updated_at AS obj_updated_at,\n                o.created_at AS obj_created_at,\n                o.last_accessed_at AS obj_last_accessed_at,\n                o.metadata AS obj_metadata,\n                o.version AS obj_version,\n                o.archived_at AS obj_archived_at,\n                o.is_delete_marker AS obj_is_delete_marker,\n                o.is_versioned AS obj_is_versioned,\n                storage.get_common_prefix(o.name, $1, ''/'') AS common_prefix\n            FROM storage.objects o\n            WHERE o.bucket_id = $2\n              AND o.name COLLATE \"C\" LIKE $10 || ''%%''\n              AND ($7 != ''exclude'' OR o.archived_at IS NULL)\n              AND ($7 != ''only'' OR o.archived_at IS NOT NULL)\n              AND ($8 != ''exclude'' OR NOT o.is_delete_marker)\n              AND ($8 != ''only'' OR o.is_delete_marker)\n        ),\n        -- Aggregate common prefixes (folders)\n        -- Both created_at and updated_at use MIN(obj_created_at) to match the old prefixes table behavior\n        aggregated_prefixes AS (\n            SELECT\n                common_prefix AS name,\n                NULL::uuid AS id,\n                MIN(obj_created_at) AS updated_at,\n                MIN(obj_created_at) AS created_at,\n                NULL::timestamptz AS last_accessed_at,\n                NULL::jsonb AS metadata,\n                NULL::text AS version,\n                NULL::timestamptz AS archived_at,\n                NULL::boolean AS is_delete_marker,\n                NULL::boolean AS is_versioned,\n                TRUE AS is_prefix\n            FROM raw_objects\n            WHERE common_prefix IS NOT NULL\n            GROUP BY common_prefix\n        ),\n        leaf_objects AS (\n            SELECT\n                obj_name AS name,\n                obj_id AS id,\n                obj_updated_at AS updated_at,\n                obj_created_at AS created_at,\n                obj_last_accessed_at AS last_accessed_at,\n                obj_metadata AS metadata,\n                obj_version AS version,\n                obj_archived_at AS archived_at,\n                obj_is_delete_marker AS is_delete_marker,\n                obj_is_versioned AS is_versioned,\n                FALSE AS is_prefix\n            FROM raw_objects\n            WHERE common_prefix IS NULL\n        ),\n        combined AS (\n            SELECT * FROM aggregated_prefixes\n            UNION ALL\n            SELECT * FROM leaf_objects\n        ),\n        filtered AS (\n            SELECT *\n            FROM combined\n            WHERE (\n                $5 = ''''\n                OR ROW(\n                    COALESCE(date_trunc(''milliseconds'', %I), ''epoch''::timestamptz),\n                    name COLLATE \"C\",\n                    %s\n                ) %s ROW(\n                    -- truncated the same way as the stored value above\n                    date_trunc(''milliseconds'', COALESCE(NULLIF($6, '''')::timestamptz, ''epoch''::timestamptz)),\n                    $5,\n                    $9\n                )\n            )\n        )\n        SELECT\n            split_part(name, ''/'', $3) AS key,\n            name,\n            id,\n            updated_at,\n            created_at,\n            last_accessed_at,\n            metadata,\n            version,\n            archived_at,\n            is_delete_marker,\n            is_versioned\n        FROM filtered\n        ORDER BY\n            COALESCE(date_trunc(''milliseconds'', %I), ''epoch''::timestamptz) %s,\n            name COLLATE \"C\" %s,\n            COALESCE(version, '''') %s\n        LIMIT $4\n    $sql$,\n        v_sort_column,\n        v_version_tiebreak,\n        v_cursor_op,\n        v_sort_column,\n        v_sort_order,\n        v_sort_order,\n        v_sort_order\n    );\n\n    -- version is the third tiebreak component for two versions of the same\n    -- key tying on both timestamp and name (see filtered CTE / ORDER BY above)\n    RETURN QUERY EXECUTE v_query\n    USING v_prefix, p_bucket_id, p_level, p_limit, p_start_after, p_sort_column_after, noncurrent_versions, delete_markers, coalesce(p_start_after_version, ''''), v_prefix_pattern;\nEND;\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.search_v2(text,text,integer,integer,text,text,text,text,text,text,timestamp with time zone,text,boolean)\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.search_v2(text,text,integer,integer,text,text,text,text,text,text,timestamp with time zone,text,boolean)", "definition": "CREATE OR REPLACE FUNCTION storage.search_v2(prefix text, bucket_name text, limits integer DEFAULT 100, levels integer DEFAULT 1, start_after text DEFAULT ''''::text, sort_order text DEFAULT ''asc''::text, sort_column text DEFAULT ''name''::text, sort_column_after text DEFAULT ''''::text, noncurrent_versions text DEFAULT ''exclude''::text, delete_markers text DEFAULT ''exclude''::text, start_after_archived_at timestamp with time zone DEFAULT NULL::timestamp with time zone, start_after_version text DEFAULT ''''::text, start_after_is_continuation boolean DEFAULT false)\n RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n    v_sort_col text;\n    v_sort_ord text;\n    v_limit int;\nBEGIN\n    -- Cap limit to maximum of 1500 records\n    v_limit := LEAST(coalesce(limits, 100), 1500);\n\n    -- Validate and normalize sort_order\n    v_sort_ord := lower(coalesce(sort_order, ''asc''));\n    IF v_sort_ord NOT IN (''asc'', ''desc'') THEN\n        v_sort_ord := ''asc'';\n    END IF;\n\n    -- Validate and normalize sort_column\n    v_sort_col := lower(coalesce(sort_column, ''name''));\n    IF v_sort_col NOT IN (''name'', ''updated_at'', ''created_at'') THEN\n        v_sort_col := ''name'';\n    END IF;\n\n    -- Route to appropriate implementation\n    IF v_sort_col = ''name'' THEN\n        -- Use list_objects_with_delimiter for name sorting (most efficient: O(k * log n))\n        RETURN QUERY\n        SELECT\n            split_part(l.name, ''/'', levels) AS key,\n            l.name AS name,\n            l.id,\n            l.updated_at,\n            l.created_at,\n            l.last_accessed_at,\n            l.metadata,\n            l.version,\n            l.archived_at,\n            l.is_delete_marker,\n            l.is_versioned\n        FROM storage.list_objects_with_delimiter(\n            bucket_name,\n            coalesce(prefix, ''''),\n            ''/'',\n            v_limit,\n            CASE WHEN start_after_is_continuation THEN '''' ELSE start_after END,\n            CASE WHEN start_after_is_continuation THEN start_after ELSE '''' END,\n            v_sort_ord,\n            noncurrent_versions,\n            delete_markers,\n            start_after_archived_at,\n            start_after_version\n        ) l;\n    ELSE\n        -- Use aggregation approach for timestamp sorting\n        -- Not efficient for large datasets but supports correct pagination\n        RETURN QUERY SELECT * FROM storage.search_by_timestamp(\n            prefix, bucket_name, v_limit, levels, start_after,\n            v_sort_ord, v_sort_col, sort_column_after,\n            noncurrent_versions, delete_markers, start_after_version\n        );\n    END IF;\nEND;\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.search(text,text,integer,integer,integer,text,text,text,text,text)\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.search(text,text,integer,integer,integer,text,text,text,text,text)", "definition": "CREATE OR REPLACE FUNCTION storage.search(prefix text, bucketname text, limits integer DEFAULT 100, levels integer DEFAULT 1, offsets integer DEFAULT 0, search text DEFAULT ''''::text, sortcolumn text DEFAULT ''name''::text, sortorder text DEFAULT ''asc''::text, noncurrent_versions text DEFAULT ''exclude''::text, delete_markers text DEFAULT ''exclude''::text)\n RETURNS TABLE(name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n    v_peek_name TEXT;\n    v_current RECORD;\n    v_common_prefix TEXT;\n    v_delimiter CONSTANT TEXT := ''/'';\n\n    -- Configuration\n    v_limit INT;\n    v_prefix TEXT;\n    v_prefix_lower TEXT;\n    v_prefix_len INT;\n    v_prefix_start INT;\n    v_combined_levels INT;\n    v_is_asc BOOLEAN;\n    v_order_by TEXT;\n    v_sort_order TEXT;\n    v_upper_bound TEXT;\n    v_file_batch_size INT;\n    v_version_filter TEXT;\n    v_multi_row BOOLEAN;\n\n    -- Dynamic SQL for batch query only\n    v_batch_query TEXT;\n    v_delete_marker_peek_query TEXT;\n    v_delete_marker_peek_query_strict TEXT;\n\n    -- Seek state\n    v_next_seek TEXT;\n    v_next_seek_at TIMESTAMPTZ;\n    v_next_seek_version TEXT;\n    v_next_seek_strict BOOLEAN := false;\n    v_count INT := 0;\n    v_skipped INT := 0;\n    v_previous_seek TEXT;\n    v_previous_seek_at TIMESTAMPTZ;\n    v_previous_seek_version TEXT;\n    v_previous_count INT;\n    v_previous_skipped INT;\nBEGIN\n    -- ========================================================================\n    -- INITIALIZATION\n    -- ========================================================================\n    v_limit := LEAST(coalesce(limits, 100), 1500);\n    v_prefix := coalesce(prefix, '''') || coalesce(search, '''');\n    v_prefix_lower := lower(v_prefix);\n    v_prefix_len := length(coalesce(prefix, ''''));\n    v_prefix_start := coalesce(array_length(string_to_array(coalesce(prefix, ''''), v_delimiter), 1), 1);\n    v_combined_levels := coalesce(array_length(string_to_array(v_prefix, v_delimiter), 1), 1);\n    v_is_asc := lower(coalesce(sortorder, ''asc'')) = ''asc'';\n    v_file_batch_size := LEAST(GREATEST(v_limit * 2, 100), 1000);\n    v_next_seek_at := NULL;\n    v_next_seek_version := '''';\n\n    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a\n    -- bare NOT IN check silently leaves an explicit NULL argument unreset.\n    noncurrent_versions := COALESCE(noncurrent_versions, ''exclude'');\n    delete_markers := COALESCE(delete_markers, ''exclude'');\n    IF noncurrent_versions NOT IN (''exclude'', ''only'', ''include'') THEN\n        noncurrent_versions := ''exclude'';\n    END IF;\n    IF delete_markers NOT IN (''exclude'', ''only'', ''include'') THEN\n        delete_markers := ''exclude'';\n    END IF;\n\n    v_multi_row := noncurrent_versions IN (''only'', ''include'');\n\n    v_version_filter := '''';\n    IF noncurrent_versions = ''exclude'' THEN\n        v_version_filter := v_version_filter || '' AND o.archived_at IS NULL'';\n    ELSIF noncurrent_versions = ''only'' THEN\n        v_version_filter := v_version_filter || '' AND o.archived_at IS NOT NULL'';\n    END IF;\n    IF delete_markers = ''exclude'' THEN\n        v_version_filter := v_version_filter || '' AND NOT o.is_delete_marker'';\n    ELSIF delete_markers = ''only'' THEN\n        v_version_filter := v_version_filter || '' AND o.is_delete_marker'';\n    END IF;\n\n    -- Validate sort column\n    CASE lower(coalesce(sortcolumn, ''name''))\n        WHEN ''name'' THEN v_order_by := ''name'';\n        WHEN ''updated_at'' THEN v_order_by := ''updated_at'';\n        WHEN ''created_at'' THEN v_order_by := ''created_at'';\n        WHEN ''last_accessed_at'' THEN v_order_by := ''last_accessed_at'';\n        ELSE v_order_by := ''name'';\n    END CASE;\n\n    v_sort_order := CASE WHEN v_is_asc THEN ''asc'' ELSE ''desc'' END;\n\n    -- ========================================================================\n    -- NON-NAME SORTING: Use path_tokens approach\n    -- ========================================================================\n    IF v_order_by != ''name'' THEN\n        RETURN QUERY EXECUTE format(\n            $sql$\n            WITH folders AS (\n                SELECT array_to_string(path_tokens[$1:$2], ''/'') AS folder\n                FROM storage.objects\n                WHERE objects.name ILIKE $3 || ''%%''\n                  AND bucket_id = $4\n                  AND array_length(objects.path_tokens, 1) <> $2\n                  AND ($7 != ''exclude'' OR objects.archived_at IS NULL)\n                  AND ($7 != ''only'' OR objects.archived_at IS NOT NULL)\n                  AND ($8 != ''exclude'' OR NOT objects.is_delete_marker)\n                  AND ($8 != ''only'' OR objects.is_delete_marker)\n                GROUP BY folder\n                ORDER BY folder %s\n            )\n            (SELECT folder AS \"name\",\n                   NULL::uuid AS id,\n                   NULL::timestamptz AS updated_at,\n                   NULL::timestamptz AS created_at,\n                   NULL::timestamptz AS last_accessed_at,\n                   NULL::jsonb AS metadata,\n                   NULL::text AS version,\n                   NULL::timestamptz AS archived_at,\n                   NULL::boolean AS is_delete_marker,\n                   NULL::boolean AS is_versioned FROM folders)\n            UNION ALL\n            (SELECT array_to_string(path_tokens[$1:$2], ''/'') AS \"name\",\n                   id, updated_at, created_at, last_accessed_at, metadata,\n                   version, archived_at, is_delete_marker, is_versioned\n             FROM storage.objects\n             WHERE objects.name ILIKE $3 || ''%%''\n               AND bucket_id = $4\n               AND array_length(objects.path_tokens, 1) = $2\n               AND ($7 != ''exclude'' OR objects.archived_at IS NULL)\n               AND ($7 != ''only'' OR objects.archived_at IS NOT NULL)\n               AND ($8 != ''exclude'' OR NOT objects.is_delete_marker)\n               AND ($8 != ''only'' OR objects.is_delete_marker)\n             -- name, then version, as tiebreaks so two versions of the same\n             -- key tying on the sort column still sort deterministically\n             ORDER BY %I %s, name COLLATE \"C\" %s, COALESCE(version, '''') %s)\n            LIMIT $5 OFFSET $6\n            $sql$, v_sort_order, v_order_by, v_sort_order, v_sort_order, v_sort_order\n        ) USING v_prefix_start, v_combined_levels, v_prefix, bucketname, v_limit, offsets, noncurrent_versions, delete_markers;\n        RETURN;\n    END IF;\n\n    -- ========================================================================\n    -- NAME SORTING: Hybrid skip-scan with batch optimization\n    -- ========================================================================\n\n    -- Calculate upper bound for prefix filtering\n    IF v_prefix_lower = '''' THEN\n        v_upper_bound := NULL;\n    ELSIF right(v_prefix_lower, 1) = v_delimiter THEN\n        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(v_delimiter) + 1);\n    ELSE\n        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(right(v_prefix_lower, 1)) + 1);\n    END IF;\n\n    -- Build a resume-safe batch query. The exact-name branch returns remaining\n    -- versions after the current (archived_at, version) boundary; the strict\n    -- name branch returns subsequent keys. UNION ALL keeps both predicates\n    -- independently indexable.\n    IF v_is_asc THEN\n        IF v_upper_bound IS NOT NULL THEN\n            v_batch_query := ''SELECT * FROM ('' ||\n                ''(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o '' ||\n                ''WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''''infinity''''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''''infinity''''::timestamptz) = $5 AND COALESCE(o.version, '''''''') > $6))'' ||\n                v_version_filter || '' ORDER BY COALESCE(o.archived_at, ''''infinity''''::timestamptz) DESC, COALESCE(o.version, '''''''') ASC LIMIT $4) UNION ALL '' ||\n                ''(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o '' ||\n                ''WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" > $2 AND lower(o.name) COLLATE \"C\" < $3'' || v_version_filter ||\n                '' ORDER BY lower(o.name) COLLATE \"C\" ASC, COALESCE(o.archived_at, ''''infinity''''::timestamptz) DESC, COALESCE(o.version, '''''''') ASC LIMIT $4)'' ||\n                '') sub ORDER BY lower(sub.name) COLLATE \"C\" ASC, COALESCE(sub.archived_at, ''''infinity''''::timestamptz) DESC, COALESCE(sub.version, '''''''') ASC LIMIT $4'';\n        ELSE\n            v_batch_query := ''SELECT * FROM ('' ||\n                ''(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o '' ||\n                ''WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''''infinity''''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''''infinity''''::timestamptz) = $5 AND COALESCE(o.version, '''''''') > $6))'' ||\n                v_version_filter || '' ORDER BY COALESCE(o.archived_at, ''''infinity''''::timestamptz) DESC, COALESCE(o.version, '''''''') ASC LIMIT $4) UNION ALL '' ||\n                ''(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o '' ||\n                ''WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" > $2'' || v_version_filter ||\n                '' ORDER BY lower(o.name) COLLATE \"C\" ASC, COALESCE(o.archived_at, ''''infinity''''::timestamptz) DESC, COALESCE(o.version, '''''''') ASC LIMIT $4)'' ||\n                '') sub ORDER BY lower(sub.name) COLLATE \"C\" ASC, COALESCE(sub.archived_at, ''''infinity''''::timestamptz) DESC, COALESCE(sub.version, '''''''') ASC LIMIT $4'';\n        END IF;\n    ELSE\n        IF v_upper_bound IS NOT NULL THEN\n            v_batch_query := ''SELECT * FROM ('' ||\n                ''(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o '' ||\n                ''WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''''infinity''''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''''infinity''''::timestamptz) = $5 AND COALESCE(o.version, '''''''') > $6))'' ||\n                v_version_filter || '' ORDER BY COALESCE(o.archived_at, ''''infinity''''::timestamptz) DESC, COALESCE(o.version, '''''''') ASC LIMIT $4) UNION ALL '' ||\n                ''(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o '' ||\n                ''WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" < $2 AND lower(o.name) COLLATE \"C\" >= $3'' || v_version_filter ||\n                '' ORDER BY lower(o.name) COLLATE \"C\" DESC, COALESCE(o.archived_at, ''''infinity''''::timestamptz) DESC, COALESCE(o.version, '''''''') ASC LIMIT $4)'' ||\n                '') sub ORDER BY lower(sub.name) COLLATE \"C\" DESC, COALESCE(sub.archived_at, ''''infinity''''::timestamptz) DESC, COALESCE(sub.version, '''''''') ASC LIMIT $4'';\n        ELSE\n            v_batch_query := ''SELECT * FROM ('' ||\n                ''(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o '' ||\n                ''WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''''infinity''''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''''infinity''''::timestamptz) = $5 AND COALESCE(o.version, '''''''') > $6))'' ||\n                v_version_filter || '' ORDER BY COALESCE(o.archived_at, ''''infinity''''::timestamptz) DESC, COALESCE(o.version, '''''''') ASC LIMIT $4) UNION ALL '' ||\n                ''(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o '' ||\n                ''WHERE o.bucket_id = $1 AND lower(o.name) COLLATE \"C\" < $2'' || v_version_filter ||\n                '' ORDER BY lower(o.name) COLLATE \"C\" DESC, COALESCE(o.archived_at, ''''infinity''''::timestamptz) DESC, COALESCE(o.version, '''''''') ASC LIMIT $4)'' ||\n                '') sub ORDER BY lower(sub.name) COLLATE \"C\" DESC, COALESCE(sub.archived_at, ''''infinity''''::timestamptz) DESC, COALESCE(sub.version, '''''''') ASC LIMIT $4'';\n        END IF;\n    END IF;\n\n    -- Keep the delete-marker predicate literal so the cached generic\n    -- plan can use idx_objects_delete_markers during the main-loop peek.\n    IF delete_markers = ''only'' THEN\n        IF v_multi_row THEN\n            v_delete_marker_peek_query :=\n                ''SELECT marker_page.name FROM ('' || v_batch_query || '') marker_page LIMIT 1'';\n        ELSIF v_is_asc THEN\n            -- Two separate literal query strings, not one gated by a bound\n            -- boolean: folding \"$n AND op1 OR NOT $n AND op2\" into a single\n            -- query defeats the generic plan''s ability to push either\n            -- comparison into the index. Branching in PL/pgSQL control flow\n            -- instead keeps each query''s index condition intact.\n            v_delete_marker_peek_query :=\n                ''SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 '' ||\n                ''AND lower(o.name) COLLATE \"C\" >= $2'' ||\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN '' AND lower(o.name) COLLATE \"C\" < $3''\n                    ELSE ''''\n                END ||\n                v_version_filter ||\n                '' ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1'';\n            -- Strict variant: used once the single-row ASC batch advance\n            -- (below) has left v_next_seek pointing at the last row already\n            -- emitted, so a plain >= would re-match it forever.\n            v_delete_marker_peek_query_strict :=\n                ''SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 '' ||\n                ''AND lower(o.name) COLLATE \"C\" > $2'' ||\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN '' AND lower(o.name) COLLATE \"C\" < $3''\n                    ELSE ''''\n                END ||\n                v_version_filter ||\n                '' ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1'';\n        ELSE\n            v_delete_marker_peek_query :=\n                ''SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 '' ||\n                ''AND lower(o.name) COLLATE \"C\" < $2'' ||\n                CASE WHEN v_upper_bound IS NOT NULL\n                    THEN '' AND lower(o.name) COLLATE \"C\" >= $3''\n                    ELSE ''''\n                END ||\n                v_version_filter ||\n                '' ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1'';\n        END IF;\n    END IF;\n\n    -- Initialize seek position\n    IF v_is_asc THEN\n        v_next_seek := v_prefix_lower;\n    ELSE\n        -- DESC performs one specialized initial seek so partial current-version\n        -- and delete-marker indexes remain available.\n        EXECUTE format(\n            ''SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1%s%s ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1'',\n            CASE WHEN v_upper_bound IS NOT NULL\n                THEN '' AND lower(o.name) COLLATE \"C\" >= $2 AND lower(o.name) COLLATE \"C\" < $3''\n                ELSE ''''\n            END,\n            v_version_filter\n        )\n        INTO v_peek_name\n        USING bucketname, v_prefix_lower, v_upper_bound;\n\n        IF v_peek_name IS NOT NULL THEN\n            v_next_seek := lower(v_peek_name) || v_delimiter;\n        ELSE\n            RETURN;\n        END IF;\n    END IF;\n\n    -- ========================================================================\n    -- MAIN LOOP: Hybrid peek-then-batch algorithm\n    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch and\n    -- the delete-marker-only path\n    -- ========================================================================\n    LOOP\n        EXIT WHEN v_count >= v_limit;\n\n        v_previous_seek := v_next_seek;\n        v_previous_seek_at := v_next_seek_at;\n        v_previous_seek_version := v_next_seek_version;\n        v_previous_count := v_count;\n        v_previous_skipped := v_skipped;\n\n        -- STEP 1: PEEK\n        v_peek_name := NULL;\n        IF delete_markers = ''only'' THEN\n            EXECUTE CASE WHEN v_next_seek_strict\n                THEN v_delete_marker_peek_query_strict\n                ELSE v_delete_marker_peek_query\n            END\n                INTO v_peek_name\n                USING bucketname, v_next_seek,\n                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END,\n                    1, v_next_seek_at, v_next_seek_version;\n        ELSIF v_multi_row AND v_next_seek_at IS NOT NULL THEN\n            SELECT o.name INTO v_peek_name\n            FROM storage.objects o\n            WHERE o.bucket_id = bucketname\n              AND lower(o.name) COLLATE \"C\" = v_next_seek\n              AND (COALESCE(o.archived_at, ''infinity''::timestamptz) < v_next_seek_at\n                   OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = v_next_seek_at\n                       AND COALESCE(o.version, '''') > v_next_seek_version))\n              AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n              AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n              AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n              AND (delete_markers != ''only'' OR o.is_delete_marker)\n            ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC,\n                     COALESCE(o.version, '''') ASC\n            LIMIT 1;\n\n            -- The current key is exhausted. Clear its version boundary and\n            -- make the following ASC name peek strict. Appending ''/'' is not a\n            -- valid lexical successor because keys ending in characters such\n            -- as ''!'' sort between the exhausted name and name || ''/''.\n            IF v_peek_name IS NULL THEN\n                IF v_is_asc THEN\n                    v_next_seek_strict := true;\n                END IF;\n                v_next_seek_at := NULL;\n                v_next_seek_version := '''';\n            END IF;\n        END IF;\n\n        -- Single-row mode is always noncurrent_versions=''exclude''. Keep the\n        -- current-row predicate literal so generic plans use the current index.\n        IF delete_markers != ''only'' AND v_peek_name IS NULL AND NOT v_multi_row THEN\n            IF v_is_asc THEN\n                IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_next_seek_strict THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                ELSIF v_upper_bound IS NOT NULL THEN\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                ELSE\n                    SELECT o.name INTO v_peek_name FROM storage.objects o\n                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek\n                      AND o.archived_at IS NULL\n                      AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                    ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n                END IF;\n            ELSIF v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek AND lower(o.name) COLLATE \"C\" >= v_prefix_lower\n                  AND o.archived_at IS NULL\n                  AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            ELSE\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek\n                  AND o.archived_at IS NULL\n                  AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            END IF;\n        ELSIF delete_markers != ''only'' AND v_peek_name IS NULL AND v_is_asc THEN\n            IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                  AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                  AND (delete_markers != ''only'' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            ELSIF v_next_seek_strict THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" > v_next_seek\n                  AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                  AND (delete_markers != ''only'' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            ELSIF v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek AND lower(o.name) COLLATE \"C\" < v_upper_bound\n                  AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                  AND (delete_markers != ''only'' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            ELSE\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" >= v_next_seek\n                  AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                  AND (delete_markers != ''only'' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" ASC LIMIT 1;\n            END IF;\n        ELSIF delete_markers != ''only'' AND v_peek_name IS NULL THEN\n            IF v_upper_bound IS NOT NULL THEN\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek AND lower(o.name) COLLATE \"C\" >= v_prefix_lower\n                  AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                  AND (delete_markers != ''only'' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            ELSE\n                SELECT o.name INTO v_peek_name FROM storage.objects o\n                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE \"C\" < v_next_seek\n                  AND (noncurrent_versions != ''exclude'' OR o.archived_at IS NULL)\n                  AND (noncurrent_versions != ''only'' OR o.archived_at IS NOT NULL)\n                  AND (delete_markers != ''exclude'' OR NOT o.is_delete_marker)\n                  AND (delete_markers != ''only'' OR o.is_delete_marker)\n                ORDER BY lower(o.name) COLLATE \"C\" DESC LIMIT 1;\n            END IF;\n        END IF;\n\n        EXIT WHEN v_peek_name IS NULL;\n\n        -- If the peek landed on a different key than we were tracking, any\n        -- version boundary belongs to the OLD key and must not leak into the\n        -- new one - e.g. the deleteMarkers=''only'' peek doesn''t know or care\n        -- whether it''s continuing the same key or jumping to a new one, so\n        -- it never clears these itself.\n        IF lower(v_peek_name) IS DISTINCT FROM v_next_seek THEN\n            v_next_seek_at := NULL;\n            v_next_seek_version := '''';\n        END IF;\n\n        -- The peek is authoritative for the next key to process. This is\n        -- especially important after exhausting a multi-version key: the\n        -- version boundary has been cleared, so executing the batch against\n        -- a stale v_next_seek would replay every version of that old key.\n        v_next_seek := lower(v_peek_name);\n        v_next_seek_strict := false;\n\n        -- STEP 2: Check if this is a FOLDER or FILE\n        v_common_prefix := storage.get_common_prefix(lower(v_peek_name), v_prefix_lower, v_delimiter);\n\n        IF v_common_prefix IS NOT NULL THEN\n            -- FOLDER: Handle offset, emit if needed, skip to next folder\n            IF v_skipped < offsets THEN\n                v_skipped := v_skipped + 1;\n            ELSE\n                name := substring(rtrim(storage.get_common_prefix(v_peek_name, v_prefix, v_delimiter), v_delimiter) from v_prefix_len + 1);\n                id := NULL;\n                updated_at := NULL;\n                created_at := NULL;\n                last_accessed_at := NULL;\n                metadata := NULL;\n                version := NULL;\n                archived_at := NULL;\n                is_delete_marker := NULL;\n                is_versioned := NULL;\n                RETURN NEXT;\n                v_count := v_count + 1;\n            END IF;\n\n            -- Advance seek past the folder range\n            IF v_is_asc THEN\n                v_next_seek := lower(left(v_common_prefix, -1)) || chr(ascii(v_delimiter) + 1);\n            ELSE\n                v_next_seek := lower(v_common_prefix);\n            END IF;\n            v_next_seek_at := NULL;\n            v_next_seek_version := '''';\n        ELSE\n            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)\n            -- For ASC: upper_bound is the exclusive upper limit (< condition)\n            -- For DESC: prefix_lower is the inclusive lower limit (>= condition)\n            FOR v_current IN EXECUTE v_batch_query\n                USING bucketname, v_next_seek,\n                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END, v_file_batch_size,\n                    v_next_seek_at, v_next_seek_version\n            LOOP\n                v_common_prefix := storage.get_common_prefix(lower(v_current.name), v_prefix_lower, v_delimiter);\n\n                IF v_common_prefix IS NOT NULL THEN\n                    -- Hit a folder: exit batch, let peek handle it. Reset\n                    -- strict mode too - it may have been set by an earlier\n                    -- row in this same batch (see the single-row ASC advance\n                    -- below), and v_next_seek here is the folder-triggering\n                    -- row''s own name, which the next peek must find inclusively.\n                    v_next_seek := CASE\n                        WHEN v_is_asc THEN lower(v_current.name)\n                        ELSE lower(v_current.name) || v_delimiter\n                    END;\n                    v_next_seek_at := NULL;\n                    v_next_seek_version := '''';\n                    v_next_seek_strict := false;\n                    EXIT;\n                END IF;\n\n                -- Handle offset skipping\n                IF v_skipped < offsets THEN\n                    v_skipped := v_skipped + 1;\n                ELSE\n                    -- Emit file\n                    name := substring(v_current.name from v_prefix_len + 1);\n                    id := v_current.id;\n                    updated_at := v_current.updated_at;\n                    created_at := v_current.created_at;\n                    last_accessed_at := v_current.last_accessed_at;\n                    metadata := v_current.metadata;\n                    version := v_current.version;\n                    archived_at := v_current.archived_at;\n                    is_delete_marker := v_current.is_delete_marker;\n                    is_versioned := v_current.is_versioned;\n                    RETURN NEXT;\n                    v_count := v_count + 1;\n                END IF;\n\n                -- Multi-row mode must remain on this key until all of its\n                -- versions have crossed the internal batch boundary.\n                IF v_multi_row THEN\n                    v_next_seek := lower(v_current.name);\n                    v_next_seek_at := COALESCE(v_current.archived_at, ''infinity''::timestamptz);\n                    v_next_seek_version := COALESCE(v_current.version, '''');\n                ELSIF v_is_asc THEN\n                    -- Appending the delimiter as a fake lexical successor would\n                    -- skip a real key like `name || ''!''` (or any character\n                    -- sorting below the delimiter), which sorts between `name`\n                    -- and `name || delimiter`. Track the real name and mark the\n                    -- next comparison strict instead - same fix as the\n                    -- exhausted-key case above.\n                    v_next_seek := lower(v_current.name);\n                    v_next_seek_strict := true;\n                ELSE\n                    v_next_seek := lower(v_current.name);\n                END IF;\n\n                EXIT WHEN v_count >= v_limit;\n            END LOOP;\n        END IF;\n\n        IF v_count = v_previous_count\n           AND v_skipped = v_previous_skipped\n           AND v_next_seek IS NOT DISTINCT FROM v_previous_seek\n           AND v_next_seek_at IS NOT DISTINCT FROM v_previous_seek_at\n           AND v_next_seek_version IS NOT DISTINCT FROM v_previous_seek_version THEN\n            RAISE EXCEPTION ''storage.search made no progress at seek (%, %, %)'',\n                v_next_seek, v_next_seek_at, v_next_seek_version;\n        END IF;\n    END LOOP;\nEND;\n$function$\n", "configuration": null, "security_definer": false}, "[\"storage\", \"storage.update_updated_at_column()\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "supabase_storage_admin", "grantor": "supabase_storage_admin", "grantable": false, "privilege": "EXECUTE"}], "is_null": true}, "owner": "supabase_storage_admin", "schema": "storage", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "storage.update_updated_at_column()", "definition": "CREATE OR REPLACE FUNCTION storage.update_updated_at_column()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW; \nEND;\n$function$\n", "configuration": null, "security_definer": false}}'::jsonb value;
DO $integration_guard$ BEGIN IF (SELECT jsonb_object_agg(jsonb_build_array(f->'schema',f->'identity')::text,f) FROM (SELECT jsonb_build_object(
 'format_version',2,
 'server_version_num',current_setting('server_version_num'),
 'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object(
   'schema',n.nspname,'identity',p.oid::regprocedure::text,
   'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),
   'acl',jsonb_build_object('is_null',(p.proacl) IS NULL,'entries',
      (SELECT coalesce(jsonb_agg(jsonb_build_object(
        'grantor',pg_get_userbyid(a.grantor),
        'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
        'privilege',a.privilege_type,'grantable',a.is_grantable)
        ORDER BY pg_get_userbyid(a.grantor),
          CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
          a.privilege_type,a.is_grantable),'[]'::jsonb)
       FROM aclexplode(CASE WHEN cardinality(coalesce(p.proacl,acldefault('f',p.proowner)))>0
         THEN coalesce(p.proacl,acldefault('f',p.proowner)) ELSE NULL::aclitem[] END) a)),'comment',obj_description(p.oid,'pg_proc'),'security_definer',p.prosecdef,'configuration',p.proconfig,
   'execute',jsonb_build_object(
      'anon',has_function_privilege('anon',p.oid,'EXECUTE'),
      'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),
      'service_role',has_function_privilege('service_role',p.oid,'EXECUTE')))
   ORDER BY n.nspname,p.oid::regprocedure::text),'[]'::jsonb)
   FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
   WHERE n.nspname IN ('auth','storage','rls_private') AND p.prokind='f'),
 'relations',(SELECT coalesce(jsonb_agg(jsonb_build_object(
   'schema',n.nspname,'name',c.relname,'kind',c.relkind,
   'owner',pg_get_userbyid(c.relowner),'acl',jsonb_build_object('is_null',(c.relacl) IS NULL,'entries',
      (SELECT coalesce(jsonb_agg(jsonb_build_object(
        'grantor',pg_get_userbyid(a.grantor),
        'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
        'privilege',a.privilege_type,'grantable',a.is_grantable)
        ORDER BY pg_get_userbyid(a.grantor),
          CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
          a.privilege_type,a.is_grantable),'[]'::jsonb)
       FROM aclexplode(CASE WHEN cardinality(coalesce(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 'S'::"char" ELSE 'r'::"char" END,c.relowner)))>0
         THEN coalesce(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 'S'::"char" ELSE 'r'::"char" END,c.relowner)) ELSE NULL::aclitem[] END) a)),
   'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',c.reloptions,
   'view_definition',CASE WHEN c.relkind IN ('v','m') THEN pg_get_viewdef(c.oid,false) END)
   ORDER BY n.nspname,c.relname),'[]'::jsonb)
   FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
   WHERE n.nspname IN ('public','core_private','api_web_v1','api_app_v1','storage') AND c.relkind IN ('r','p','v','m','S')),
 'columns',(SELECT coalesce(jsonb_agg(jsonb_build_object(
   'schema',n.nspname,'table',c.relname,'name',a.attname,'position',a.attnum,
   'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,
   'identity',a.attidentity,'generated',a.attgenerated,
   'default',pg_get_expr(d.adbin,d.adrelid),'acl',jsonb_build_object('is_null',(a.attacl) IS NULL,'entries',
      (SELECT coalesce(jsonb_agg(jsonb_build_object(
        'grantor',pg_get_userbyid(a.grantor),
        'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
        'privilege',a.privilege_type,'grantable',a.is_grantable)
        ORDER BY pg_get_userbyid(a.grantor),
          CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
          a.privilege_type,a.is_grantable),'[]'::jsonb)
       FROM aclexplode(CASE WHEN cardinality(coalesce(a.attacl,'{}'::aclitem[]))>0
         THEN coalesce(a.attacl,'{}'::aclitem[]) ELSE NULL::aclitem[] END) a)))
   ORDER BY n.nspname,c.relname,a.attnum),'[]'::jsonb)
   FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid
   JOIN pg_namespace n ON n.oid=c.relnamespace
   LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
   WHERE n.nspname IN ('public','core_private','api_web_v1','api_app_v1','storage') AND c.relkind IN ('r','p','v','m')
   AND a.attnum>0 AND NOT a.attisdropped),
 'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object(
   'schema',n.nspname,'table',c.relname,'name',p.polname,'command',p.polcmd,
   'permissive',p.polpermissive,
   'roles',(SELECT jsonb_agg(CASE WHEN role_oid=0 THEN 'PUBLIC' ELSE pg_get_userbyid(role_oid) END
      ORDER BY CASE WHEN role_oid=0 THEN 'PUBLIC' ELSE pg_get_userbyid(role_oid) END)
      FROM unnest(p.polroles) role_oid),
   'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid))
   ORDER BY n.nspname,c.relname,p.polname),'[]'::jsonb)
   FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid
   JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','core_private','api_web_v1','api_app_v1','storage')),
 'default_acl',(SELECT coalesce(jsonb_agg(jsonb_build_object(
   'owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,
   'object_type',d.defaclobjtype,'acl',jsonb_build_object('is_null',(d.defaclacl) IS NULL,'entries',
      (SELECT coalesce(jsonb_agg(jsonb_build_object(
        'grantor',pg_get_userbyid(a.grantor),
        'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
        'privilege',a.privilege_type,'grantable',a.is_grantable)
        ORDER BY pg_get_userbyid(a.grantor),
          CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
          a.privilege_type,a.is_grantable),'[]'::jsonb)
       FROM aclexplode(CASE WHEN cardinality(coalesce(d.defaclacl,'{}'::aclitem[]))>0
         THEN coalesce(d.defaclacl,'{}'::aclitem[]) ELSE NULL::aclitem[] END) a)))
   ORDER BY pg_get_userbyid(d.defaclrole),coalesce(n.nspname,''),d.defaclobjtype),'[]'::jsonb)
   FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace
   WHERE d.defaclnamespace=0 OR n.nspname IN ('public','core_private','api_web_v1','api_app_v1','storage')),
 'schemas',(SELECT coalesce(jsonb_agg(jsonb_build_object(
   'schema',n.nspname,'owner',pg_get_userbyid(n.nspowner),'acl',jsonb_build_object('is_null',(n.nspacl) IS NULL,'entries',
      (SELECT coalesce(jsonb_agg(jsonb_build_object(
        'grantor',pg_get_userbyid(a.grantor),
        'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
        'privilege',a.privilege_type,'grantable',a.is_grantable)
        ORDER BY pg_get_userbyid(a.grantor),
          CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
          a.privilege_type,a.is_grantable),'[]'::jsonb)
       FROM aclexplode(CASE WHEN cardinality(coalesce(n.nspacl,acldefault('n',n.nspowner)))>0
         THEN coalesce(n.nspacl,acldefault('n',n.nspowner)) ELSE NULL::aclitem[] END) a)))
   ORDER BY n.nspname),'[]'::jsonb) FROM pg_namespace n WHERE n.nspname IN ('public','core_private','api_web_v1','api_app_v1','storage')),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object(
   'schema',n.nspname,'table',c.relname,'name',k.conname,
   'definition',pg_get_constraintdef(k.oid,false),'validated',k.convalidated)
   ORDER BY n.nspname,c.relname,k.conname),'[]'::jsonb)
   FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid
   JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','core_private','api_web_v1','api_app_v1','storage')),
 'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_object(
   'schema',n.nspname,'table',c.relname,'name',ic.relname,'definition',pg_get_indexdef(i.indexrelid),
   'valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique)
   ORDER BY n.nspname,ic.relname),'[]'::jsonb)
   FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid
   JOIN pg_class ic ON ic.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace
   WHERE n.nspname IN ('public','core_private','api_web_v1','api_app_v1','storage')),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object(
   'schema',n.nspname,'table',c.relname,'name',t.tgname,
   'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,false))
   ORDER BY n.nspname,c.relname,t.tgname),'[]'::jsonb)
   FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid
   JOIN pg_namespace n ON n.oid=c.relnamespace
   WHERE n.nspname IN ('public','core_private','api_web_v1','api_app_v1','storage') AND NOT t.tgisinternal)
)) raw(c) CROSS JOIN LATERAL jsonb_array_elements(c->'functions') f) IS DISTINCT FROM (SELECT value FROM staging_expected_helpers) THEN RAISE EXCEPTION 'STAGING_AUTH_STORAGE_HELPER_DRIFT'; END IF; END $integration_guard$;
