ok'', false, ''code'', ''USER_ID_REQUIRED'');\n  end if;\n\n  -- 파기 게이트: 취소 불가 시점(locked 이상) 진행 중 탈퇴 job 이 있을 때만.\n  if not public.account_deletion_write_blocked(p_user_id) then\n    return jsonb_build_object(''ok'', false, ''code'', ''NO_ACTIVE_DELETION'');\n  end if;\n\n  select count(*) into v_active_billing_keys\n    from public.billing_keys\n   where user_id = p_user_id and status = ''active'';\n\n  delete from public.identity_verifications where user_id = p_user_id;\n  get diagnostics v_iv_deleted = row_count;\n\n  delete from public.billing_keys where user_id = p_user_id;\n  get diagnostics v_bk_deleted = row_count;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''identity_verifications_deleted'', v_iv_deleted,\n    ''billing_keys_deleted'', v_bk_deleted,\n    ''billing_keys_active_at_delete'', v_active_billing_keys\n  );\nend $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"account_deletion_reclaim_expired()\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "account_deletion_reclaim_expired()", "definition": "CREATE OR REPLACE FUNCTION public.account_deletion_reclaim_expired()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_n int;\nbegin\n  update public.account_deletion_jobs set lease_owner=null, leased_until=null, updated_at=now()\n    where leased_until is not null and leased_until < now()\n      and state not in (''completed'',''canceled'',''failed'');\n  get diagnostics v_n = row_count;\n  return v_n;\nend $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"account_deletion_record_error(uuid,text,integer,integer)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "account_deletion_record_error(uuid,text,integer,integer)", "definition": "CREATE OR REPLACE FUNCTION public.account_deletion_record_error(p_user_id uuid, p_error text, p_backoff_seconds integer DEFAULT 60, p_max_attempts integer DEFAULT 8)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_attempts int; v_id uuid;\nbegin\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n\n  update public.account_deletion_jobs\n    set attempts = attempts + 1, last_error = left(coalesce(p_error,''''),1000),\n        next_attempt_at = now() + make_interval(secs => greatest(1, coalesce(p_backoff_seconds,60))),\n        updated_at = now()\n    where id = v_id\n    returning attempts into v_attempts;\n  if v_attempts is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n\n  if v_attempts >= p_max_attempts then\n    update public.account_deletion_jobs\n      set state=''failed'', failed_at=now(), updated_at=now()\n      where id = v_id;\n    return jsonb_build_object(''ok'',true,''state'',''failed'',''attempts'',v_attempts,''job_id'',v_id);\n  end if;\n  return jsonb_build_object(''ok'',true,''attempts'',v_attempts,''job_id'',v_id);\nend $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"account_deletion_request_consented(uuid,integer,boolean,boolean,bigint)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": "Account deletion request. p_cancelable_minutes is retained for backward compatibility but ignored; server policy fixes the cancellation/deletion grace window at 30 days.", "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "account_deletion_request_consented(uuid,integer,boolean,boolean,bigint)", "definition": "CREATE OR REPLACE FUNCTION public.account_deletion_request_consented(p_user_id uuid, p_cancelable_minutes integer DEFAULT 30, p_dry_run boolean DEFAULT true, p_forfeit_consent boolean DEFAULT false, p_acknowledged_balance_cents bigint DEFAULT NULL::bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_id uuid; v_state text; v_latest uuid; v_latest_state text;\n  v_balance bigint; v_consent_at timestamptz; v_consented bigint;\nbegin\n  v_id := public.account_deletion_active_job_id(p_user_id);\n  if v_id is not null then\n    select j.state into v_state from public.account_deletion_jobs j where j.id = v_id;\n    return jsonb_build_object(''ok'',true,''existing'',true,''job_id'',v_id,''state'',v_state);\n  end if;\n\n  select j.id, j.state into v_latest, v_latest_state\n    from public.account_deletion_jobs j\n    where j.user_id = p_user_id\n    order by j.requested_at desc, j.id desc\n    limit 1;\n  if v_latest_state = ''completed'' then\n    return jsonb_build_object(''ok'',false,''code'',''ALREADY_COMPLETED'',''job_id'',v_latest,''state'',''completed'');\n  end if;\n\n  select coalesce(w.balance_cents, 0) into v_balance\n    from public.cash_wallets w where w.user_id = p_user_id for update;\n  v_balance := coalesce(v_balance, 0);\n\n  if v_balance > 0 then\n    if not coalesce(p_forfeit_consent, false) then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_REQUIRED'',''balance_cents'',v_balance);\n    end if;\n    if p_acknowledged_balance_cents is not null and p_acknowledged_balance_cents <> v_balance then\n      return jsonb_build_object(''ok'',false,''code'',''FORFEIT_CONSENT_STALE'',\n        ''acknowledged_balance_cents'', p_acknowledged_balance_cents, ''current_balance_cents'', v_balance);\n    end if;\n    v_consent_at := now();\n    v_consented := v_balance;\n  else\n    v_consent_at := null;\n    v_consented := 0;\n  end if;\n\n  insert into public.account_deletion_jobs\n      (user_id, state, cancelable_until, dry_run, forfeit_consent_at, consented_balance_cents)\n    values (\n      p_user_id,\n      ''pending'',\n      now() + interval ''30 days'',\n      coalesce(p_dry_run,true),\n      v_consent_at,\n      v_consented\n    )\n    returning id into v_id;\n\n  return jsonb_build_object(''ok'',true,''existing'',false,''job_id'',v_id,''state'',''pending'',\n                            ''forfeit_consent_at'', v_consent_at,\n                            ''consented_balance_cents'', v_consented);\nend\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"account_deletion_request_self_consented_v2(bigint)\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": true}, "identity": "account_deletion_request_self_consented_v2(bigint)", "definition": "CREATE OR REPLACE FUNCTION public.account_deletion_request_self_consented_v2(p_acknowledged_balance_cents bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO '