update public.notification_deliveries\n    set attempt_count = attempt_count + 1, last_error = left(coalesce(p_error,''''),1000),\n        status = case when p_invalid_token then ''dead'' else ''failed'' end, updated_at=now()\n    where id=p_id returning device_token_id into v_token_id;\n  if v_token_id is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n  if p_invalid_token then perform public.revoke_device_token(v_token_id); end if;\n  return jsonb_build_object(''ok'',true,''invalid_token'',p_invalid_token);\nend $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"notification_delivery_mark_sent(uuid)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "notification_delivery_mark_sent(uuid)", "definition": "CREATE OR REPLACE FUNCTION public.notification_delivery_mark_sent(p_id uuid)\n RETURNS boolean\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  update public.notification_deliveries set status=''sent'', sent_at=now(), updated_at=now() where id=p_id returning true;\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"notification_display_name(uuid)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "notification_display_name(uuid)", "definition": "CREATE OR REPLACE FUNCTION public.notification_display_name(p_user_id uuid)\n RETURNS text\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select coalesce((\n    select coalesce(\n      nullif(trim(coalesce(u.full_name, '''')), ''''),\n      nullif(trim(coalesce(u.nickname, '''')), ''''))\n    from public.users u where u.id = p_user_id\n  ), ''멘토'');\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"notification_event_group(text)\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "anon", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "notification_event_group(text)", "definition": "CREATE OR REPLACE FUNCTION public.notification_event_group(p_event_type text)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\n  select case\n    when p_event_type like ''question_%'' or p_event_type like ''qna_%'' or p_event_type like ''connection_note%'' then ''qna''\n    when p_event_type like ''custom_%'' or p_event_type like ''order_%'' or p_event_type like ''individual_question%'' then ''order''\n    when p_event_type like ''%subscription%'' then ''subscription''\n    when p_event_type like ''%refund%'' then ''refund''\n    else ''system''\n  end;\n$function$\n", "configuration": ["search_path=public"], "security_definer": false}, "[\"public\", \"notification_mentor_label(uuid)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "notification_mentor_label(uuid)", "definition": "CREATE OR REPLACE FUNCTION public.notification_mentor_label(p_user_id uuid)\n RETURNS text\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select case when n like ''%멘토'' then n else n || '' 멘토'' end\n  from (select public.notification_display_name(p_user_id) as n) s;\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"notification_outbox_claim(text,integer,integer)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "notification_outbox_claim(text,integer,integer)", "definition": "CREATE OR REPLACE FUNCTION public.notification_outbox_claim(p_owner text, p_limit integer DEFAULT 10, p_lease_seconds integer DEFAULT 60)\n RETURNS SETOF notification_outbox\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin\n  return query\n  with cte as (\n    select o.id from public.notification_outbox o\n    where o.status in (''pending'',''failed'') and o.next_attempt_at <= now()\n    order by o.next_attempt_at asc\n    limit greatest(1, p_limit)\n    for update skip locked\n  )\n  update public.notification_outbox o\n    set status=''leased'', lease_owner=p_owner, leased_until=now() + make_interval(secs => greatest(1,p_lease_seconds)), updated_at=now()\n    from cte where o.id = cte.id\n    returning o.*;\nend $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"notification_outbox_mark_failed(uuid,text,integer)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "notification_outbox_mark_failed(uuid,text,integer)", "definition": "CREATE OR REPLACE FUNCTION public.notification_outbox_mark_failed(p_id uuid, p_error text, p_backoff_seconds integer DEFAULT 60)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_attempt int; v_max int; v_dead boolean;\nbegin\n  update public.notification_outbox\n    set attempt_count = attempt_count + 1, last_error = left(coalesce(p_error,''''),1000),\n        lease_owner=null, leased_until=null,\n        next_attempt_at = now() + make_interval(secs => greatest(1,p_backoff_seconds)), updated_at=now()\n    where id=p_id\n    returning attempt_count, max_attempts into v_attempt, v_max;\n  if v_attempt is null then return jsonb_build_object(''ok'',false,''code'',''NOT_FOUND''); end if;\n  v_dead := v_attempt >= v_max;\n  update public.notification_outbox set status = case when v_dead then ''dead'' else ''failed'' end where id=p_id;\n  return jsonb_build_object(''ok'',true,''attempt'',v_attempt,''dead'',v_dead);\nend $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"notification_outbox_mark_sent(uuid)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "notification_outbox_mark_sent(uuid)", "definition": "CREATE OR REPLACE FUNCTION public.notification_outbox_mark_sent(p_id uuid)\n RETURNS boolean\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  update public.notification_outbox set status=''sent'', lease_owner=null, leased_until=null, updated_at=now()\n  where id=p_id returning true;\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"notification_outbox_reclaim_expired()\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "notification_outbox_reclaim_expired()", "definition": "CREATE OR REPLACE FUNCTION public.notification_outbox_reclaim_expired()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_n int;\nbegin\n  update public.notification_outbox set status=''pending'', lease_owner=null, leased_until=null, updated_at=now()\n    where status=''leased'' and leased_until is not null and leased_until < now();\n  get diagnostics v_n = row_count;\n  return v_n;\nend $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"notification_unread_count_self()\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": true}, "identity": "notification_unread_count_self()", "definition": "CREATE OR REPLACE FUNCTION public.notification_unread_count_self()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\n  select jsonb_build_object(\n    ''ok'', true,\n    ''contract_version'', 1,\n    ''count'', (\n      select count(*)\n        from public.notifications n\n       where n.is_read is distinct from true\n         and ((n.recipient_user_id is not null and n.recipient_user_id = (select auth.uid()))\n              or (n.user_id is not null and n.user_id = (select auth.uid()))\n              or (n.recipient_id is not null and n.recipient_id = (select auth.uid()))\n              or (n.student_id is not null and n.student_id = (select auth.uid()))\n              or (n.mentor_id is not null and n.mentor_id = (select auth.uid()))\n              or (n.target_user_id is not null and n.target_user_id = (select auth.uid()))\n              or (n.owner_id is not null and n.owner_id = (select auth.uid())))\n         -- 앱 제외 타입 — 앱 classifier(kGatedNotificationTypeCodes)와 단일 정본.\n         -- 목록·count 가 같은 predicate 를 쓰도록 앱 계약 테스트가 고정한다.\n         and coalesce(n.type, '''') not in (''new_order_message'', ''new_application'')\n    )\n  );\n$function$\n", "configuration": ["search_path=\"\""], "security_definer": true}, "[\"public\", \"notifications_read_state_sync()\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": false, "authenticated": false}, "identity": "notifications_read_state_sync()", "definition": "CREATE OR REPLACE FUNCTION public.notifications_read_state_sync()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n  if tg_op = ''INSERT'' then\n    if new.is_read is null then new.is_read := coalesce(new.read, false); end if;\n    new.read := new.is_read;\n    if new.is_read and new.read_at is null then new.read_at := now(); end if;\n    return new;\n  end if;\n  -- UPDATE: 어느 쪽이 갱신되든 정본(is_read)으로 수렴 후 미러\n  if new.is_read is distinct from old.is_read then\n    new.read := new.is_read;\n  elsif coalesce(new.read, false) is distinct from coalesce(old.read, false) then\n    new.is_read := coalesce(new.read, false);\n    new.read := new.is_read;\n  else\n    new.read := new.is_read;\n  end if;\n  if new.is_read then\n    if new.read_at is null then new.read_at := now(); end if;\n  else\n    new.read_at := null;\n  end if;\n  return new;\nend\n$function$\n", "configuration": ["search_path=\"\""], "security_definer": true}, "[\"public\", \"pay_due_payouts_for_run(date,text,boolean)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "pay_due_payouts_for_run(date,text,boolean)", "definition": "CREATE OR REPLACE FUNCTION public.pay_due_payouts_for_run(p_run_date date, p_idempotency_key text DEFAULT NULL::text, p_dry_run boolean DEFAULT true)\n RETURNS TABLE(run_id uuid, paid_count integer, skipped_no_account integer, total_mentor_cents bigint, total_withholding_cents bigint, total_net_cents bigint, dry_run boolean)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_idem text := coalesce(p_idempotency_key, ''payout:'' || to_char(p_run_date, ''YYYY-MM''));\n  v_cutoff timestamptz := (date_trunc(''month'', p_run_date::timestamp) at time zone ''Asia/Seoul'') - interval ''1 second'';\n  v_run public.payout_runs%rowtype;\n  v_run_id uuid;\n  rec record;\n  v_ledger_id uuid; v_item_id uuid; v_has_account boolean;\n  v_paid int := 0; v_skipped int := 0;\n  v_total bigint := 0; v_total_wh bigint := 0; v_total_net bigint := 0;\n  v_withholding bigint; v_net bigint; v_wh_ledger_id uuid;\nbegin\n  if not p_dry_run then\n    select * into v_run from public.payout_runs where idempotency_key = v_idem;\n    if found then\n      v_run_id := v_run.id;\n      if v_run.status = ''completed'' then\n        return query select v_run.id, v_run.mentor_count, 0, v_run.total_mentor_cents,\n          coalesce((select sum(withholding_cents) from public.payout_run_items where payout_run_id=v_run.id),0),\n          coalesce((select sum(net_paid_cents) from public.payout_run_items where payout_run_id=v_run.id),0), false;\n        return;\n      end if;\n    else\n      insert into public.payout_runs (run_date, cutoff_end, status, idempotency_key)\n      values (p_run_date, v_cutoff, ''executing'', v_idem) returning id into v_run_id;\n    end if;\n  end if;\n\n  for rec in\n    select d.* from public.due_payouts d\n    where d.completion_ts <= v_cutoff\n      and not exists (select 1 from public.payout_run_items i where i.source_type=d.source_type and i.source_id=d.source_id)\n    order by d.mentor_id, d.source_type, d.completion_ts\n  loop\n    select coalesce(nullif(trim(mp.payout_account_number), ''''), '''') <> '''' into v_has_account\n      from public.mentor_profiles mp where mp.user_id = rec.mentor_id;\n    if coalesce(v_has_account, false) = false then\n      v_skipped := v_skipped + 1; continue;\n    end if;\n\n    v_withholding := public.calc_withholding_cents(rec.mentor_amount_cents);\n    v_net := rec.mentor_amount_cents - v_withholding;\n\n    if p_dry_run then\n      v_paid := v_paid + 1; v_total := v_total + rec.mentor_amount_cents;\n      v_total_wh := v_total_wh + v_withholding; v_total_net := v_total_net + v_net;\n      continue;\n    end if;\n\n    v_ledger_id := null;\n    if rec.source_type = ''custom_request'' then\n      perform public.record_custom_order_escrow_payout(rec.source_id);\n      select id into v_ledger_id from public.cash_ledger\n        where idempotency_key = ''cr_payout_'' || rec.source_id::text and reason=''custom_order_escrow_payout'' limit 1;\n    elsif rec.source_type = ''individual_question'' then\n      perform public.release_individual_question_payout(rec.source_id);\n      select id into v_ledger_id from public.cash_ledger\n        where idempotency_key = ''iq_payout:'' || rec.source_id::text and reason=''individual_question_payout'' limit 1;\n    elsif rec.source_type = ''subscription'' then\n      insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n      values (rec.mentor_id, rec.mentor_amount_cents, ''subscription_settlement_payout'',\n              ''subscription_settlement_items'', rec.source_id, ''sub_payout:'' || rec.source_id::text)\n      on conflict (idempotency_key) do nothing returning id into v_ledger_id;\n      if v_ledger_id is not null then\n        insert into public.cash_wallets (user_id, balance_cents) values (rec.mentor_id, 0) on conflict (user_id) do nothing;\n        update public.cash_wallets w set balance_cents = w.balance_cents + rec.mentor_amount_cents where w.user_id = rec.mentor_id;\n      else\n        select id into v_ledger_id from public.cash_ledger where idempotency_key=''sub_payout:'' || rec.source_id::text limit 1;\n      end if;\n      update public.subscription_settlement_items set status=''paid'', paid_at=coalesce(paid_at, now()), updated_at=now()\n        where id = rec.source_id and status <> ''paid'';\n    else\n      continue;\n    end if;\n\n    if v_withholding > 0 then\n      v_wh_ledger_id := null;\n      insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n      values (rec.mentor_id, -v_withholding, ''payout_withholding_3_3pct'', rec.source_type, rec.source_id,\n              ''wh:'' || rec.source_type || '':'' || rec.source_id::text)\n      on conflict (idempotency_key) do nothing returning id into v_wh_ledger_id;\n      if v_wh_ledger_id is not null then\n        update public.cash_wallets w set balance_cents = w.balance_cents - v_withholding where w.user_id = rec.mentor_id;\n      end if;\n    end if;\n\n    insert into public.payout_run_items (\n      payout_run_id, mentor_id, source_type, source_id,\n      gross_cents, platform_fee_cents, mentor_amount_cents, fee_rate, ledger_id,\n      withholding_cents, net_paid_cents\n    ) values (\n      v_run_id, rec.mentor_id, rec.source_type, rec.source_id,\n      rec.gross_cents, rec.platform_fee_cents, rec.mentor_amount_cents, rec.fee_rate, v_ledger_id,\n      v_withholding, v_net\n    )\n    on conflict (source_type, source_id) do nothing\n    returning id into v_item_id;\n\n    if v_item_id is not null then\n      v_paid := v_paid + 1;\n      v_total := v_total + rec.mentor_amount_cents;\n      v_total_wh := v_total_wh + v_withholding;\n      v_total_net := v_total_net + v_net;\n    end if;\n  end loop;\n\n  if not p_dry_run then\n    update public.payout_runs\n    set status=''completed'',\n        mentor_count=(select count(distinct mentor_id) from public.payout_run_items where payout_run_id=v_run_id),\n        total_mentor_cents=(select coalesce(sum(mentor_amount_cents),0) from public.payout_run_items where payout_run_id=v_run_id),\n        executed_at=now(), updated_at=now()\n    where id=v_run_id;\n  end if;\n\n  return query select v_run_id, v_paid, v_skipped, v_total, v_total_wh, v_total_net, p_dry_run;\nend;\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"payout_reconciliation_report(date)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "payout_reconciliation_report(date)", "definition": "CREATE OR REPLACE FUNCTION public.payout_reconciliation_report(p_run_date date)\n RETURNS TABLE(source_type text, source_id uuid, mentor_id uuid, mentor_amount_cents bigint, withholding_cents bigint, net_paid_cents bigint, eligible boolean, reason text)\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  with cutoff as (select ((date_trunc(''month'', p_run_date::timestamp) at time zone ''Asia/Seoul'') - interval ''1 second'') as ts)\n  select\n    d.source_type, d.source_id, d.mentor_id,\n    d.mentor_amount_cents,\n    public.calc_withholding_cents(d.mentor_amount_cents) as withholding_cents,\n    d.mentor_amount_cents - public.calc_withholding_cents(d.mentor_amount_cents) as net_paid_cents,\n    (case when exists (select 1 from public.payout_run_items i where i.source_type=d.source_type and i.source_id=d.source_id) then false\n          when d.completion_ts > (select ts from cutoff) then false\n          when coalesce(nullif(trim(mp.payout_account_number),''''),'''') = '''' then false\n          else true end) as eligible,\n    (case when exists (select 1 from public.payout_run_items i where i.source_type=d.source_type and i.source_id=d.source_id) then ''already_paid''\n          when d.completion_ts > (select ts from cutoff) then ''not_due''\n          when coalesce(nullif(trim(mp.payout_account_number),''''),'''') = '''' then ''no_payout_account''\n          else ''eligible'' end) as reason\n  from public.due_payouts d\n  left join public.mentor_profiles mp on mp.user_id = d.mentor_id\n  order by d.mentor_id, d.source_type;\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"payout_run_items_block_mutation()\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "payout_run_items_block_mutation()", "definition": "CREATE OR REPLACE FUNCTION public.payout_run_items_block_mutation()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\r\nbegin\r\n  raise exception ''payout_run_items is append-only (immutable); % not allowed'', tg_op\r\n    using errcode = ''P0001'';\r\nend;\r\n$function$\n", "configuration": ["search_path=\"\""], "security_definer": false}, "[\"public\", \"plan_price_stats()\"]": {"acl": {"entries": [{"grantee": "anon", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": "205(DB-5 A-1): 승인 멘토 · 활성 요금제의 tier 별 평균가(100원 반올림 · cents÷100) · 최소 · 최대 · 표본 수. 표본 5명 미만이면 avg_won = 최소값 + fallback true. 항상 3행. anon/authenticated/service_role 읽기 — 개별 단가 비노출.", "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "plan_price_stats()", "definition": "CREATE OR REPLACE FUNCTION public.plan_price_stats()\n RETURNS TABLE(plan_tier text, sample_count integer, avg_won integer, min_won integer, max_won integer, fallback boolean)\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\n  with base as (\n    select mp.plan_tier, mp.amount_cents\n      from public.mentor_plans mp\n      join public.mentor_profiles p on p.user_id = mp.mentor_id\n     where p.verification_status = ''approved''\n       and mp.is_active = true\n       and mp.plan_tier in (''limited'', ''standard'', ''premium'')\n       and mp.amount_cents is not null\n       and mp.amount_cents > 0\n  ),\n  agg as (\n    select b.plan_tier,\n           count(*)::int                                   as sample_count,\n           (round(avg(b.amount_cents) / 10000.0) * 100)::int as avg_won_r100,   -- cents → 원(÷100) → 100원 단위 반올림\n           (min(b.amount_cents) / 100)::int                as min_won,\n           (max(b.amount_cents) / 100)::int                as max_won\n      from base b\n     group by b.plan_tier\n  )\n  select t.tier                                     as plan_tier,\n         coalesce(a.sample_count, 0)                 as sample_count,\n         case when coalesce(a.sample_count, 0) >= 5 then a.avg_won_r100 else a.min_won end as avg_won,\n         a.min_won,\n         a.max_won,\n         (coalesce(a.sample_count, 0) < 5)           as fallback\n    from (values (''limited'', 1), (''standard'', 2), (''premium'', 3)) as t(tier, ord)\n    left join agg a on a.plan_tier = t.tier\n   order by t.ord;\n$function$\n", "configuration": ["search_path=\"\""], "security_definer": true}, "[\"public\", \"process_subscription_renewal_v2(uuid,timestamp with time zone,text,timestamp with time zone)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "process_subscription_renewal_v2(uuid,timestamp with time zone,text,timestamp with time zone)", "definition": "CREATE OR REPLACE FUNCTION public.process_subscription_renewal_v2(p_subscription_id uuid, p_period_end timestamp with time zone, p_idempotency_key text, p_processed_at timestamp with time zone DEFAULT now())\n RETURNS TABLE(ok boolean, code text, message text, billing_event_id uuid, ledger_id uuid, next_period_start timestamp with time zone, next_period_end timestamp with time zone, wallet_balance_cents bigint, attempt_count integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n s public.subscriptions%rowtype; p public.mentor_plans%rowtype;\n e public.subscription_billing_events%rowtype; l public.cash_ledger%rowtype;\n v_student uuid; v_mentor uuid; v_amount bigint; v_balance bigint; v_end timestamptz;\n v_key text; v_notice public.subscription_billing_events%rowtype;\nbegin\n if p_subscription_id is null or p_period_end is null or p_processed_at is null then\n   return query select false,''invalid_subscription''::text,''subscription, period and time are required''::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;\n end if;\n v_key := ''sub_renewal:''||p_subscription_id::text||'':''||to_char(p_period_end at time zone ''UTC'',''YYYY-MM-DD'');\n if p_idempotency_key is distinct from v_key or char_length(p_idempotency_key)>128 then\n   return query select false,''invalid_idempotency_key''::text,''key must identify this subscription period''::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;\n end if;\n -- Match checkout''s pair mutex before row locks. No stale client snapshot decides eligibility.\n select student_id,mentor_id into v_student,v_mentor from public.subscriptions where id=p_subscription_id;\n if v_student is null then\n   return query select false,''not_found''::text,''subscription not found''::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;\n end if;\n perform pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));\n select * into s from public.subscriptions where id=p_subscription_id for update;\n if s.id is null or s.student_id is distinct from v_student or s.mentor_id is distinct from v_mentor then\n   raise exception ''SUBSCRIPTION_BINDING_MISMATCH'';\n end if;\n select * into e from public.subscription_billing_events where idempotency_key=v_key for update;\n -- Older web normalizes timestamps through JS Date (millisecond precision). Bind\n -- to the locked subscription, or the original event on replay, without rounding\n -- stored financial periods. A different millisecond is still a stale request.\n if e.id is not null and e.subscription_id=s.id\n    and date_trunc(''milliseconds'',e.period_start)=date_trunc(''milliseconds'',p_period_end) then\n  p_period_end := e.period_start;\n elsif e.id is null\n    and date_trunc(''milliseconds'',s.current_period_end)=date_trunc(''milliseconds'',p_period_end) then\n  p_period_end := s.current_period_end;\n end if;\n if e.id is not null then\n   if e.subscription_id is distinct from s.id or e.student_id is distinct from s.student_id\n      or e.mentor_id is distinct from s.mentor_id or e.period_start is distinct from p_period_end\n      or e.event_type not in (''renewal'',''renewal_failed'') then\n     raise exception ''BILLING_EVENT_BINDING_MISMATCH'';\n   end if;\n   if e.status=''succeeded'' then\n     select * into l from public.cash_ledger where id=e.ledger_id;\n     if l.id is null or l.delta_cents is distinct from -e.amount_cents::bigint\n        or l.user_id is distinct from s.student_id or l.ref_id is distinct from s.id\n        or l.idempotency_key is distinct from v_key or l.reason is distinct from ''subscription_renewal'' then\n       raise exception ''LEDGER_BINDING_MISMATCH'';\n     end if;\n     return query select true,''already_succeeded''::text,''renewal already processed''::text,e.id,l.id,e.period_start,e.period_end,null::bigint,e.attempt_count; return;\n   end if;\n   if e.status not in (''failed'',''skipped'') then\n     return query select false,''already_processing''::text,''renewal is already processing''::text,e.id,e.ledger_id,e.period_start,e.period_end,null::bigint,e.attempt_count; return;\n   end if;\n end if;\n if s.status not in (''active'',''past_due'') or s.cancel_at_period_end\n    or (s.status=''past_due'' and s.grace_until is not null and s.grace_until<=p_processed_at)\n    or s.current_period_end is distinct from p_period_end or s.next_billing_at is null\n    or s.next_billing_at>p_processed_at or p_period_end>p_processed_at then\n   return query select false,''not_renewal_eligible''::text,''subscription state or period changed''::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;\n end if;\n select * into p from public.mentor_plans where id=s.plan_id for share;\n if p.id is null or p.mentor_id is distinct from s.mentor_id or p.plan_tier is distinct from s.plan_tier\n    or p.amount_cents is null or p.amount_cents<=0 or p.amount_cents%100<>0 then\n   e := core_private.record_subscription_renewal_block(s.id,''price_unavailable'',v_key,p_processed_at);\n   return query select false,''price_unavailable''::text,''plan price or binding unavailable''::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;\n end if;\n -- is_active controls NEW subscriptions only. Existing subscriptions may renew.\n v_amount := p.amount_cents;\n select * into v_notice from public.subscription_billing_events\n  where idempotency_key=''sub_renewal_notice:''||s.id::text||'':''||to_char(p_period_end at time zone ''UTC'',''YYYY-MM-DD'');\n if v_notice.id is not null and (v_notice.amount_cents is distinct from v_amount\n    or v_notice.plan_id is distinct from p.id or v_notice.plan_tier is distinct from p.plan_tier) then\n   e := core_private.record_subscription_renewal_block(s.id,''price_changed_since_notice'',v_key,p_processed_at);\n   return query select false,''price_changed_since_notice''::text,''renewal price differs from the sent notice''::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;\n end if;\n if exists(select 1 from public.cash_ledger where idempotency_key=v_key) then\n   raise exception ''LEDGER_WITHOUT_SUCCEEDED_EVENT'';\n end if;\n v_end := ((p_period_end at time zone ''Asia/Seoul'' + interval ''1 month'') at time zone ''Asia/Seoul'');\n if e.id is null then\n   insert into public.subscription_billing_events\n    (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,\n     amount_cents,plan_tier,plan_id,idempotency_key,attempt_count,created_at)\n   values(s.id,s.student_id,s.mentor_id,''renewal'',''processing'',p_period_end,v_end,p_processed_at,\n          v_amount,p.plan_tier,p.id,v_key,1,p_processed_at) returning * into e;\n else\n   update public.subscription_billing_events b set event_type=''renewal'',status=''processing'',\n     amount_cents=v_amount,plan_id=p.id,plan_tier=p.plan_tier,billing_at=p_processed_at,\n     attempt_count=b.attempt_count+1,processed_at=null,failure_code=null,failure_message=null\n   where b.id=e.id returning b.* into e;\n end if;\n insert into public.cash_wallets(user_id,balance_cents) values(s.student_id,0) on conflict(user_id) do nothing;\n update public.cash_wallets w set balance_cents=w.balance_cents-v_amount\n   where w.user_id=s.student_id and w.balance_cents>=v_amount returning w.balance_cents into v_balance;\n if not found then\n   update public.subscription_billing_events b set event_type=''renewal_failed'',status=''failed'',\n     failure_code=''insufficient_cash'',failure_message=''CASH_INSUFFICIENT'',processed_at=p_processed_at where b.id=e.id;\n   update public.subscriptions set status=''past_due'',grace_until=coalesce(grace_until,p_processed_at+interval ''2 days''),\n     updated_at=p_processed_at,last_billing_event_id=e.id where id=s.id;\n   return query select false,''insufficient_cash''::text,''CASH_INSUFFICIENT''::text,e.id,null::uuid,p_period_end,v_end,null::bigint,e.attempt_count; return;\n end if;\n insert into public.cash_ledger(user_id,delta_cents,reason,ref_type,ref_id,idempotency_key,created_at)\n values(s.student_id,-v_amount,''subscription_renewal'',''subscriptions'',s.id,v_key,p_processed_at) returning * into l;\n update public.subscription_billing_events b set event_type=''renewal'',status=''succeeded'',ledger_id=l.id,\n   processed_at=p_processed_at,failure_code=null,failure_message=null where b.id=e.id;\n update public.subscriptions set status=''active'',current_period_start=p_period_end,current_period_end=v_end,\n   next_billing_at=v_end,last_renewed_at=p_processed_at,last_billing_event_id=e.id,grace_until=null,updated_at=p_processed_at where id=s.id;\n return query select true,''succeeded''::text,''renewal processed''::text,e.id,l.id,p_period_end,v_end,v_balance,e.attempt_count;\nend $function$\n", "configuration": ["search_path=\"\""], "security_definer": true}, "[\"public\", \"process_subscription_renewal(uuid,timestamp with time zone,bigint,text,timestamp with time zone)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "process_subscription_renewal(uuid,timestamp with time zone,bigint,text,timestamp with time zone)", "definition": "CREATE OR REPLACE FUNCTION public.process_subscription_renewal(p_subscription_id uuid, p_period_end timestamp with time zone, p_amount_cents bigint, p_idempotency_key text, p_processed_at timestamp with time zone DEFAULT now())\n RETURNS TABLE(ok boolean, code text, message text, billing_event_id uuid, ledger_id uuid, next_period_start timestamp with time zone, next_period_end timestamp with time zone, wallet_balance_cents bigint, attempt_count integer)\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\n select * from public.process_subscription_renewal_v2(p_subscription_id,p_period_end,p_idempotency_key,p_processed_at)\n$function$\n", "configuration": ["search_path=\"\""], "security_definer": true}, "[\"public\", \"qa_answer_notification_after()\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": false, "authenticated": false}, "identity": "qa_answer_notification_after()", "definition": "CREATE OR REPLACE FUNCTION public.qa_answer_notification_after()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin\n  perform public.qna_emit_answer_notification(NEW.thread_id, null, NEW.id);\n  return NEW;\nend; $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qa_direct_answered_after()\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "qa_direct_answered_after()", "definition": "CREATE OR REPLACE FUNCTION public.qa_direct_answered_after()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''public''\nAS $function$\nbegin\n  if public.qna_is_direct_untrusted_writer() then perform public.qna_apply_answered_transition(NEW.thread_id); end if;\n  return NEW;\nend; $function$\n", "configuration": ["search_path=public"], "security_definer": false}, "[\"public\", \"qa_direct_write_guard()\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "qa_direct_write_guard()", "definition": "CREATE OR REPLACE FUNCTION public.qa_direct_write_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''public''\nAS $function$\ndeclare v_room uuid; v_status text;\nbegin\n  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;\n  select mentor_student_room_id, status into v_room, v_status from public.question_threads where id = NEW.thread_id;\n  if v_status in (''confirmed'',''closed'',''archived'') then raise exception ''DIRECT_ATT_THREAD_LOCKED''; end if;\n  if NEW.storage_path is null or NEW.storage_path not like (v_room::text||''/''||NEW.thread_id::text||''/%'') then raise exception ''DIRECT_ATT_PATH_FORGERY''; end if;\n  if not exists (select 1 from storage.objects o where o.bucket_id=''question-room-attachments'' and o.name=NEW.storage_path and o.owner_id=auth.uid()::text) then raise exception ''DIRECT_ATT_OBJECT_NOT_OWNED''; end if;\n  return NEW;\nend; $function$\n", "configuration": ["search_path=public"], "security_definer": false}, "[\"public\", \"qm_answer_notification_after()\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": false, "authenticated": false}, "identity": "qm_answer_notification_after()", "definition": "CREATE OR REPLACE FUNCTION public.qm_answer_notification_after()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin\n  perform public.qna_emit_answer_notification(NEW.thread_id, NEW.id, null);\n  return NEW;\nend; $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qm_direct_answered_after()\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "qm_direct_answered_after()", "definition": "CREATE OR REPLACE FUNCTION public.qm_direct_answered_after()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''public''\nAS $function$\nbegin\n  if public.qna_is_direct_untrusted_writer() then perform public.qna_apply_answered_transition(NEW.thread_id); end if;\n  return NEW;\nend; $function$\n", "configuration": ["search_path=public"], "security_definer": false}, "[\"public\", \"qm_direct_write_guard()\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "qm_direct_write_guard()", "definition": "CREATE OR REPLACE FUNCTION public.qm_direct_write_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''public''\nAS $function$\ndeclare v_status text;\nbegin\n  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;\n  select status into v_status from public.question_threads where id = NEW.thread_id;\n  if v_status in (''confirmed'',''closed'',''archived'') then raise exception ''DIRECT_MSG_THREAD_LOCKED''; end if;\n  return NEW;\nend; $function$\n", "configuration": ["search_path=public"], "security_definer": false}, "[\"public\", \"qna_append_message(uuid,text)\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": "S3-C 보정 §3: 질문방 메시지 추가 — 당사자 확정 직후 계정 상태(ACCOUNT_NOT_ACTIVE/ACCOUNT_BANNED/ACCOUNT_SUSPENDED/ACCOUNT_DELETION_IN_PROGRESS) + 상호 차단(BLOCKED) 게이트. 그 외 thread lock·mentor approval·구독/환불·알림 트리거 의미 전부 보존.", "execute": {"anon": false, "service_role": true, "authenticated": true}, "identity": "qna_append_message(uuid,text)", "definition": "CREATE OR REPLACE FUNCTION public.qna_append_message(p_thread_id uuid, p_body text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_status text; v_thread_status text;\n  v_first_answered timestamptz; v_message_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_sub_id uuid;\n  v_susp timestamptz; v_norm text;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_body is null or btrim(p_body)='''' then raise exception ''BODY_REQUIRED''; end if;\n  if char_length(p_body)>10000 then raise exception ''MESSAGE_TOO_LONG''; end if;\n  select t.mentor_student_room_id, t.status, t.first_answered_at into v_room, v_thread_status, v_first_answered\n    from public.question_threads t where t.id=p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;\n  if v_uid=v_mentor then v_is_mentor:=true; elsif v_uid=v_student then v_is_mentor:=false; else raise exception ''NOT_ROOM_PARTY''; end if;\n\n  -- [S3-C 보정 §3] 당사자 확정 직후 — 계정 상태 4종 + 상호 차단. 이 아래로는\n  -- 어떤 INSERT·상태 전이도 없으므로 차단 시 부수효과 0 이다.\n  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id=v_uid;\n  if not found then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  v_norm := lower(btrim(coalesce(v_status,'''')));\n  if v_norm=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if v_norm=''suspended'' and (v_susp is null or v_susp > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if v_norm not in (''active'',''suspended'') then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  if public.account_deletion_write_blocked(v_uid) then raise exception ''ACCOUNT_DELETION_IN_PROGRESS''; end if;\n  if public.qna_users_blocked(v_student, v_mentor) then raise exception ''BLOCKED''; end if;\n\n  if v_thread_status in (''confirmed'',''closed'',''archived'') then raise exception ''THREAD_LOCKED''; end if;\n  if v_is_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  -- 학생 후속 메시지: 활성 구독 FOR UPDATE + live pending refund 게이트(142 유지).\n  if not v_is_mentor then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n  end if;\n\n  -- F2(D-12)+R1: 아래 INSERT 가 AFTER INSERT 알림 트리거를 발화 — 멘토 메시지 행 1건 = 알림 정확히 1건.\n  insert into public.question_messages (thread_id, author_id, body) values (p_thread_id, v_uid, btrim(p_body)) returning id into v_message_id;\n  if v_is_mentor and v_first_answered is null then\n    update public.question_threads set status=''answered'', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;\n    v_transitioned := true;\n  end if;\n  return jsonb_build_object(''ok'',true,''message_id'',v_message_id,''answered_transition'',v_transitioned);\nend; $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qna_apply_answered_transition(uuid)\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": "P1-8A(144)→F2(D-12): 멘토 첫 실제 콘텐츠 → pending/open→answered + first_answered_at 스레드당 exactly-once. 알림 발행 책임은 F2 에서 qna_emit_answer_notification 로 분리됐다(본 함수는 전이 전용).", "execute": {"anon": false, "service_role": true, "authenticated": true}, "identity": "qna_apply_answered_transition(uuid)", "definition": "CREATE OR REPLACE FUNCTION public.qna_apply_answered_transition(p_thread_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_room uuid; v_status text; v_first timestamptz; v_student uuid; v_mentor uuid;\nbegin\n  select mentor_student_room_id, status, first_answered_at into v_room, v_status, v_first from public.question_threads where id=p_thread_id;\n  if v_room is null then return; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;\n  if auth.uid() is distinct from v_mentor then return; end if;          -- 멘토만\n  if v_first is not null or v_status not in (''pending'',''open'') then return; end if;\n  if not exists (select 1 from public.question_messages m where m.thread_id=p_thread_id and m.author_id=v_mentor)\n     and not exists (select 1 from public.question_attachments a where a.thread_id=p_thread_id and a.author_id=v_mentor) then\n    return; -- content-less: no-op\n  end if;\n  update public.question_threads set status=''answered'', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;\nend; $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qna_confirm_thread(uuid)\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": true}, "identity": "qna_confirm_thread(uuid)", "definition": "CREATE OR REPLACE FUNCTION public.qna_confirm_thread(p_thread_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_status text;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  select t.mentor_student_room_id, t.status into v_room, v_status from public.question_threads t where t.id=p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n  select student_id into v_student from public.mentor_student_rooms where id=v_room;\n  if v_uid <> v_student then raise exception ''STUDENT_ONLY''; end if;\n  if v_status=''confirmed'' then return jsonb_build_object(''ok'',true,''thread_id'',p_thread_id); end if;\n  if v_status <> ''answered'' then raise exception ''NOT_ANSWERED''; end if;\n  update public.question_threads set status=''confirmed'', confirmed_at=coalesce(confirmed_at,now()), updated_at=now() where id=p_thread_id;\n  return jsonb_build_object(''ok'',true,''thread_id'',p_thread_id);\nend; $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qna_create_free_question_thread(uuid,text,text,text,text)\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": true}, "identity": "qna_create_free_question_thread(uuid,text,text,text,text)", "definition": "CREATE OR REPLACE FUNCTION public.qna_create_free_question_thread(p_room_id uuid, p_title text, p_subject text DEFAULT NULL::text, p_topic text DEFAULT NULL::text, p_first_message_body text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin return public.qna_create_question_thread(p_room_id, p_title, p_subject, p_topic, p_first_message_body); end; $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qna_create_question_thread(uuid,text,text,text,text)\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": true}, "identity": "qna_create_question_thread(uuid,text,text,text,text)", "definition": "CREATE OR REPLACE FUNCTION public.qna_create_question_thread(p_room_id uuid, p_title text, p_subject text DEFAULT NULL::text, p_topic text DEFAULT NULL::text, p_first_message_body text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid; v_status text; v_suspended_until timestamptz;\n  v_created_at timestamptz; v_total int; v_per int; v_subject text; v_thread_id uuid; v_message_id uuid;\n  v_has_active_sub boolean; v_usage json; v_path text; v_sub_id uuid;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_title is null or btrim(p_title)='''' then raise exception ''TITLE_REQUIRED''; end if;\n  if char_length(p_title)>120 then raise exception ''TITLE_TOO_LONG''; end if;\n  if char_length(p_topic)>80 then raise exception ''TOPIC_TOO_LONG''; end if;\n  if char_length(p_first_message_body)>10000 then raise exception ''MESSAGE_TOO_LONG''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=p_room_id;\n  if not found then raise exception ''ROOM_NOT_FOUND''; end if;\n  if v_uid <> v_student then\n    if v_uid = v_mentor then raise exception ''MENTOR_CANNOT_CREATE_THREAD''; else raise exception ''NOT_ROOM_PARTY''; end if;\n  end if;\n  perform 1 from public.users where id=v_student for update;\n  select status, suspended_until, created_at into v_status, v_suspended_until, v_created_at from public.users where id=v_student;\n  if lower(coalesce(v_status,''active''))=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if lower(coalesce(v_status,''active''))=''suspended'' and (v_suspended_until is null or v_suspended_until > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if exists (select 1 from public.user_blocks where (blocker_id=v_student and blocked_id=v_mentor) or (blocker_id=v_mentor and blocked_id=v_student)) then raise exception ''BLOCKED''; end if;\n  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  v_has_active_sub := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'');\n  if v_has_active_sub then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n    v_usage := public.get_weekly_question_usage(v_student, v_mentor);\n    if not coalesce((v_usage->>''can_ask'')::boolean, false) then raise exception ''WEEKLY_LIMIT_EXHAUSTED''; end if;\n    v_path := ''subscription'';\n  else\n    if v_created_at is not null and now() >= v_created_at + interval ''7 days'' then raise exception ''FREE_QUOTA_EXPIRED''; end if;\n    select count(*) into v_total from public.free_question_usage where student_id=v_student;\n    if v_total >= 7 then raise exception ''FREE_QUOTA_TOTAL_EXHAUSTED''; end if;\n    select count(*) into v_per from public.free_question_usage where student_id=v_student and mentor_id=v_mentor;\n    if v_per >= 3 then raise exception ''FREE_QUOTA_MENTOR_EXHAUSTED''; end if;\n    v_path := ''free'';\n  end if;\n  v_subject := nullif(btrim(coalesce(p_subject,'''')),'''');\n  if v_subject is not null and not exists (select 1 from public.subjects where code=v_subject) then raise exception ''SUBJECT_INVALID''; end if;\n  insert into public.question_threads (mentor_student_room_id, title, status, subject, topic)\n  values (p_room_id, btrim(p_title), ''pending'', v_subject, nullif(btrim(coalesce(p_topic,'''')),'''')) returning id into v_thread_id;\n  if p_first_message_body is not null and btrim(p_first_message_body) <> '''' then\n    insert into public.question_messages (thread_id, author_id, body) values (v_thread_id, v_student, btrim(p_first_message_body)) returning id into v_message_id;\n  end if;\n  if v_path=''free'' then insert into public.free_question_usage (student_id, mentor_id, thread_id) values (v_student, v_mentor, v_thread_id); end if;\n\n  -- ── 새 질문 → 방 멘토 인앱 알림(question_received) ──\n  -- 20260805 도입(구독 한정) → S1-7/QA-C13 에서 무료 경로까지 확장.\n  -- 같은 트랜잭션 안 — 위 생성이 롤백되면 알림도 롤백(원자), record_domain_notification\n  -- 이 (recipient,event_key) 멱등 + outbox 게이트를 기존 계약대로 처리한다.\n  -- S1-7/QA-C13: 무료·구독 경로 모두 알린다(종전에는 subscription 한정 조건이 있었다).\n    perform public.record_domain_notification(\n      v_mentor,\n      ''question_received:'' || v_thread_id::text,\n      ''question_received:'' || v_thread_id::text,\n      ''question_received'',\n      ''새 질문이 도착했어요'',\n      ''학생이 새 질문을 등록했어요.'',\n      ''/mentor/question-room/'' || p_room_id::text || ''?thread='' || v_thread_id::text,\n      jsonb_build_object(''room_id'', p_room_id, ''thread_id'', v_thread_id, ''student_id'', v_student),\n      jsonb_build_object(''room_id'', p_room_id, ''thread_id'', v_thread_id, ''student_id'', v_student)\n    );\n\n  return jsonb_build_object(''ok'',true,''thread_id'',v_thread_id,''message_id'',v_message_id,''path'',v_path,''used_free_quota'',(v_path=''free''));\nend;\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qna_emit_answer_notification(uuid,uuid,uuid)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": "F2(D-12)+R1: 멘토 답변 이벤트(메시지 행/단독 첨부 행)당 학생 question_answered 알림 exactly-once. event_key = question_answer_message:<message_id> | question_answer_attachment:<attachment_id>. 메시지 연결 첨부는 메시지 이벤트에 합류(추가 알림 0). self-gating: auth.uid()=room 멘토 AND 행 author=멘토. owner-only 내부 함수 — 외부(PUBLIC/anon/authenticated/service_role) EXECUTE 0, AFTER INSERT 알림 트리거(qm/qa_answer_notification_after)에서만 실행. Data API 호출 표면 아님 — 과거 행 ID 수동 전달로 소급 알림 생성 불가.", "execute": {"anon": false, "service_role": false, "authenticated": false}, "identity": "qna_emit_answer_notification(uuid,uuid,uuid)", "definition": "CREATE OR REPLACE FUNCTION public.qna_emit_answer_notification(p_thread_id uuid, p_message_id uuid DEFAULT NULL::uuid, p_attachment_id uuid DEFAULT NULL::uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_room uuid; v_student uuid; v_mentor uuid; v_name text;\n  v_key text; v_body_suffix text; v_meta jsonb;\n  v_actor uuid;\nbegin\n  if p_thread_id is null then return; end if;\n  -- 정확히 하나의 행 스코프(메시지 XOR 단독첨부)만 허용 — 호출 계약 위반은 즉시 실패(무음 금지).\n  if (p_message_id is null) = (p_attachment_id is null) then\n    raise exception ''ANSWER_EVENT_SCOPE_REQUIRED'';\n  end if;\n\n  select t.mentor_student_room_id into v_room\n  from public.question_threads t where t.id = p_thread_id;\n  if v_room is null then return; end if;\n\n  select student_id, mentor_id into v_student, v_mentor\n  from public.mentor_student_rooms where id = v_room;\n  if v_student is null then return; end if;\n\n  v_actor := (select auth.uid());\n\n  -- ── 멘토 발신 → 학생 (기존 동작 · 불변) ────────────────────────────────\n  if v_actor is not distinct from v_mentor then\n    if p_message_id is not null then\n      if not exists (\n        select 1 from public.question_messages m\n        where m.id = p_message_id and m.thread_id = p_thread_id and m.author_id = v_mentor\n      ) then return; end if;\n      v_key := ''question_answer_message:'' || p_message_id::text;\n      v_body_suffix := ''님이 답변을 남겼습니다.'';\n      v_meta := jsonb_build_object(''room_id'', v_room, ''thread_id'', p_thread_id, ''message_id'', p_message_id);\n    else\n      if not exists (\n        select 1 from public.question_attachments a\n        where a.id = p_attachment_id and a.thread_id = p_thread_id\n          and a.author_id = v_mentor and a.message_id is null\n      ) then return; end if;\n      v_key := ''question_answer_attachment:'' || p_attachment_id::text;\n      v_body_suffix := ''님이 파일을 보냈습니다.'';\n      v_meta := jsonb_build_object(''room_id'', v_room, ''thread_id'', p_thread_id, ''attachment_id'', p_attachment_id);\n    end if;\n\n    select coalesce(nullif(btrim(full_name),''''), nullif(btrim(nickname),''''), ''멘토'')\n      into v_name from public.users where id = v_mentor;\n\n    perform public.record_domain_notification(\n      v_student,\n      v_key,\n      v_key,\n      ''question_answered'',\n      ''새 답변이 도착했어요'',\n      coalesce(v_name,''멘토'') || v_body_suffix,\n      ''/question-room/'' || v_room::text || ''?thread='' || p_thread_id::text,\n      v_meta,\n      v_meta\n    );\n    return;\n  end if;\n\n  -- ── 학생 발신 → 멘토 (S1-4 신규) ──────────────────────────────────────\n  if v_actor is not distinct from v_student then\n    if p_message_id is not null then\n      if not exists (\n        select 1 from public.question_messages m\n        where m.id = p_message_id and m.thread_id = p_thread_id and m.author_id = v_student\n      ) then return; end if;\n      -- ★ 스레드의 **첫 메시지**는 이 경로에서 알리지 않는다.\n      --   질문 생성 RPC(qna_create_question_thread)가 이미 ''새 질문이 도착했어요''\n      --   (question_received:<thread_id>)를 보내므로, 여기서 또 보내면 질문\n      --   1건에 멘토 알림이 2건 생긴다(무료·구독 공통 — 검증에서 실제 확인).\n      --\n      --   판정 기준은 **이 스레드에 이보다 앞선 메시지가 있는가**다.\n      --   앞선 것이 없으면 곧 첫 메시지 → 침묵, 있으면 → 알림.\n      --   (초안이던 ''스레드와 같은 트랜잭션인가''(m2.created_at = t2.created_at)는\n      --    p_first_message_body 를 주지 않고 스레드만 만드는 경로에서 무너진다 —\n      --    free_question_entry.createFreeThread 의 firstMessageBody 는 nullable 이라\n      --    학생의 진짜 첫 메시지가 별도 트랜잭션으로 들어오고, 그러면 생성 알림과\n      --    이 알림이 겹쳐 다시 2건이 된다. 그 경로까지 덮으려면 순서 비교가 맞다.)\n      --   동률 created_at 도 (created_at, id) 튜플 비교로 전순서가 되어\n      --   2번째 메시지를 잘못 삼키지 않는다.\n      if not exists (\n        select 1\n          from public.question_messages m_prev\n          join public.question_messages m_self on m_self.id = p_message_id\n         where m_prev.thread_id = p_thread_id\n           and (m_prev.created_at, m_prev.id) < (m_self.created_at, m_self.id)\n      ) then return; end if;\n      v_key := ''question_student_message:'' || p_message_id::text;\n      v_body_suffix := ''님이 메시지를 보냈어요.'';\n      v_meta := jsonb_build_object(''room_id'', v_room, ''thread_id'', p_thread_id, ''message_id'', p_message_id);\n    else\n      if not exists (\n        select 1 from public.question_attachments a\n        where a.id = p_attachment_id and a.thread_id = p_thread_id\n          and a.author_id = v_student and a.message_id is null\n      ) then return; end if;\n      v_key := ''question_student_attachment:'' || p_attachment_id::text;\n      v_body_suffix := ''님이 파일을 보냈어요.'';\n      v_meta := jsonb_build_object(''room_id'', v_room, ''thread_id'', p_thread_id, ''attachment_id'', p_attachment_id);\n    end if;\n\n    select coalesce(nullif(btrim(full_name),''''), nullif(btrim(nickname),''''), ''학생'')\n      into v_name from public.users where id = v_student;\n\n    perform public.record_domain_notification(\n      v_mentor,\n      v_key,\n      v_key,\n      ''question_received'',\n      ''새 메시지가 도착했어요'',\n      coalesce(v_name,''학생'') || v_body_suffix,\n      ''/mentor/question-room/'' || v_room::text || ''?thread='' || p_thread_id::text,\n      v_meta,\n      v_meta\n    );\n    return;\n  end if;\n\n  -- 방 당사자가 아닌 세션(관리자·워커 등)은 알림을 만들지 않는다.\n  return;\nend;\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qna_flag_wrong_answer(uuid,boolean)\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": true}, "identity": "qna_flag_wrong_answer(uuid,boolean)", "definition": "CREATE OR REPLACE FUNCTION public.qna_flag_wrong_answer(p_thread_id uuid, p_is_wrong boolean DEFAULT true)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_uid uuid := auth.uid();\n  v_room uuid;\n  v_student uuid;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n\n  select t.mentor_student_room_id into v_room\n  from public.question_threads t where t.id = p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n\n  select student_id into v_student from public.mentor_student_rooms where id = v_room;\n  if v_uid <> v_student then raise exception ''STUDENT_ONLY''; end if;\n\n  update public.question_threads\n    set is_wrong_answer = coalesce(p_is_wrong, true),\n        mastery_status = case when coalesce(p_is_wrong, true) then ''wrong'' else ''unknown'' end,\n        updated_at = now()\n  where id = p_thread_id;\n\n  return jsonb_build_object(''ok'', true, ''thread_id'', p_thread_id, ''is_wrong_answer'', coalesce(p_is_wrong, true));\nend;\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qna_is_direct_untrusted_writer()\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "anon", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "qna_is_direct_untrusted_writer()", "definition": "CREATE OR REPLACE FUNCTION public.qna_is_direct_untrusted_writer()\n RETURNS boolean\n LANGUAGE sql\n STABLE\n SET search_path TO ''''\nAS $function$ select current_user in (''authenticated'',''anon''); $function$\n", "configuration": ["search_path=\"\""], "security_definer": false}, "[\"public\", \"qna_register_attachment(uuid,text,text,text,uuid)\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": "S3-C 보정 §3+2차 §2: 질문방 첨부 등록 — 당사자 확정 직후 계정 상태 + 상호 차단 게이트(종전 계정 검사 전무) + 미승인 멘토 첨부-only 답변 차단(MENTOR_NOT_APPROVED). 그 외 thread lock·storage path/소유권·message 정합·구독/환불·알림 트리거 의미 전부 보존.", "execute": {"anon": false, "service_role": true, "authenticated": true}, "identity": "qna_register_attachment(uuid,text,text,text,uuid)", "definition": "CREATE OR REPLACE FUNCTION public.qna_register_attachment(p_thread_id uuid, p_storage_path text, p_file_name text DEFAULT NULL::text, p_mime_type text DEFAULT NULL::text, p_message_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_thread_status text;\n  v_first_answered timestamptz; v_att_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_sub_id uuid;\n  v_status text; v_susp timestamptz; v_norm text;\nbegin\n  if v_uid is null then raise exception ''AUTH_REQUIRED''; end if;\n  if p_storage_path is null or btrim(p_storage_path)='''' then raise exception ''STORAGE_PATH_REQUIRED''; end if;\n  select t.mentor_student_room_id, t.status, t.first_answered_at into v_room, v_thread_status, v_first_answered\n    from public.question_threads t where t.id=p_thread_id for update;\n  if not found then raise exception ''THREAD_NOT_FOUND''; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=v_room;\n  if v_uid=v_mentor then v_is_mentor:=true; elsif v_uid=v_student then v_is_mentor:=false; else raise exception ''NOT_ROOM_PARTY''; end if;\n\n  -- [S3-C 보정 §3] 당사자 확정 직후 — 계정 상태 4종 + 상호 차단(종전 계정 검사 전무).\n  select u.status, u.suspended_until into v_status, v_susp from public.users u where u.id=v_uid;\n  if not found then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  v_norm := lower(btrim(coalesce(v_status,'''')));\n  if v_norm=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n  if v_norm=''suspended'' and (v_susp is null or v_susp > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n  if v_norm not in (''active'',''suspended'') then raise exception ''ACCOUNT_NOT_ACTIVE''; end if;\n  if public.account_deletion_write_blocked(v_uid) then raise exception ''ACCOUNT_DELETION_IN_PROGRESS''; end if;\n  if public.qna_users_blocked(v_student, v_mentor) then raise exception ''BLOCKED''; end if;\n\n  if v_thread_status in (''confirmed'',''closed'',''archived'') then raise exception ''THREAD_LOCKED''; end if;\n  -- [S3-C 보정 2차 §2] 미승인 멘토가 **첨부-only 답변**으로 승인 게이트를 우회하지 못하게 한다.\n  --   attachment INSERT · answered 전이 · first_answered_at 기록 · 알림 트리거보다 앞이며,\n  --   append 와 동일한 코드·동일한 판정기를 쓴다(THREAD_LOCKED 우선순위는 유지).\n  if v_is_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n  if p_storage_path not like (v_room::text || ''/'' || p_thread_id::text || ''/%'') then raise exception ''STORAGE_PATH_MISMATCH''; end if;\n  if not exists (select 1 from storage.objects o where o.bucket_id=''question-room-attachments'' and o.name = btrim(p_storage_path) and o.owner_id = v_uid::text) then raise exception ''STORAGE_OBJECT_NOT_OWNED''; end if;\n  if p_message_id is not null and not exists (select 1 from public.question_messages m where m.id=p_message_id and m.thread_id=p_thread_id) then raise exception ''MESSAGE_THREAD_MISMATCH''; end if;\n  if not v_is_mentor then\n    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'' for update;\n    if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n  end if;\n\n  -- F2(D-12)+R1: 아래 INSERT 가 AFTER INSERT 알림 트리거를 발화 — 멘토 단독 첨부 행 1건 = 알림 정확히 1건.\n  insert into public.question_attachments (thread_id, message_id, author_id, storage_path, file_name, mime_type)\n  values (p_thread_id, p_message_id, v_uid, btrim(p_storage_path), p_file_name, p_mime_type) returning id into v_att_id;\n  if v_is_mentor and v_first_answered is null then\n    update public.question_threads set status=''answered'', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;\n    v_transitioned := true;\n  end if;\n  return jsonb_build_object(''ok'',true,''attachment_id'',v_att_id,''answered_transition'',v_transitioned);\nend; $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qna_subscription_has_live_refund(uuid)\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": true}, "identity": "qna_subscription_has_live_refund(uuid)", "definition": "CREATE OR REPLACE FUNCTION public.qna_subscription_has_live_refund(p_subscription_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select exists (\n    select 1\n    from public.refunds r\n    join public.subscriptions s on s.id = r.subscription_id\n    where r.subscription_id = p_subscription_id\n      and r.status = ''pending''\n      and r.request_type in (''subscription_prorated'',''subscription_mentor_suspended'')\n      and (r.billing_event_id is null or r.billing_event_id = s.last_billing_event_id)\n  );\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qna_users_blocked(uuid,uuid)\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": true}, "identity": "qna_users_blocked(uuid,uuid)", "definition": "CREATE OR REPLACE FUNCTION public.qna_users_blocked(p_a uuid, p_b uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select exists (select 1 from public.user_blocks where (blocker_id=p_a and blocked_id=p_b) or (blocker_id=p_b and blocked_id=p_a));\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qra_path_upload_eligible(text)\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": true}, "identity": "qra_path_upload_eligible(text)", "definition": "CREATE OR REPLACE FUNCTION public.qra_path_upload_eligible(p_name text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_uid uuid := auth.uid(); v_room uuid; v_thread uuid; v_student uuid; v_mentor uuid; v_sub_id uuid;\nbegin\n  if v_uid is null then return false; end if;\n  v_room := public.qra_room_uuid_from_path(p_name);\n  begin\n    v_thread := nullif(split_part(p_name, ''/'', 2), '''')::uuid;\n  exception when others then\n    return false;\n  end;\n  if v_room is null or v_thread is null then return false; end if;\n\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = v_room;\n  if v_student is null then return false; end if;\n\n  if v_uid = v_mentor then return true; end if;\n  if v_uid <> v_student then return false; end if;\n\n  if not exists (\n    select 1 from public.question_threads t where t.id = v_thread and t.mentor_student_room_id = v_room\n  ) then\n    return false;\n  end if;\n\n  select id into v_sub_id from public.subscriptions\n    where student_id = v_student and mentor_id = v_mentor and lower(coalesce(status,'''')) = ''active'' limit 1;\n  if v_sub_id is not null then\n    return not public.qna_subscription_has_live_refund(v_sub_id);\n  end if;\n\n  return exists (\n    select 1 from public.free_question_usage f where f.thread_id = v_thread and f.student_id = v_student\n  );\nend; $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qra_room_uuid_from_path(text)\"]": {"acl": {"entries": [{"grantee": "PUBLIC", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "anon", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": true, "service_role": true, "authenticated": true}, "identity": "qra_room_uuid_from_path(text)", "definition": "CREATE OR REPLACE FUNCTION public.qra_room_uuid_from_path(p_name text)\n RETURNS uuid\n LANGUAGE plpgsql\n IMMUTABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\r\nbegin\r\n  return nullif(split_part(p_name, ''/'', 1), '''')::uuid;\r\nexception\r\n  when others then\r\n    return null;\r\nend;\r\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qra_thread_writable_for_path(text)\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": true}, "identity": "qra_thread_writable_for_path(text)", "definition": "CREATE OR REPLACE FUNCTION public.qra_thread_writable_for_path(p_name text)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select exists (\n    select 1 from public.question_threads t\n    where t.id = nullif(split_part(p_name, ''/'', 2), '''')::uuid\n      and t.mentor_student_room_id = public.qra_room_uuid_from_path(p_name)\n      and coalesce(t.status, '''') in (''pending'',''open'',''answered'')\n  );\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qra_uploader_allowed_for_path(text)\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": true}, "identity": "qra_uploader_allowed_for_path(text)", "definition": "CREATE OR REPLACE FUNCTION public.qra_uploader_allowed_for_path(p_name text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_room uuid; v_student uuid; v_mentor uuid; v_uid uuid := auth.uid(); v_status text;\nbegin\n  if v_uid is null then return false; end if;\n  v_room := public.qra_room_uuid_from_path(p_name);\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = v_room;\n  if v_student is null then return false; end if;\n  select status into v_status from public.users where id = v_uid;\n  if lower(coalesce(v_status,''active'')) = ''banned'' then return false; end if;\n  if lower(coalesce(v_status,''active'')) = ''suspended'' then\n    if exists (select 1 from public.users where id=v_uid and (suspended_until is null or suspended_until > now())) then return false; end if;\n  end if;\n  if v_uid = v_mentor and not public.individual_question_user_is_approved_mentor(v_mentor) then return false; end if;\n  if public.qna_users_blocked(v_student, v_mentor) then return false; end if;\n  return true;\nend; $function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"qt_direct_consume_free_usage()\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "qt_direct_consume_free_usage()", "definition": "CREATE OR REPLACE FUNCTION public.qt_direct_consume_free_usage()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''public''\nAS $function$\ndeclare v_student uuid; v_mentor uuid;\nbegin\n  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = NEW.mentor_student_room_id;\n  if not exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'') then\n    insert into public.free_question_usage (student_id, mentor_id, thread_id) values (v_student, v_mentor, NEW.id);\n  end if;\n  return NEW;\nend; $function$\n", "configuration": ["search_path=public"], "security_definer": false}, "[\"public\", \"qt_direct_write_guard()\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": null, "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "qt_direct_write_guard()", "definition": "CREATE OR REPLACE FUNCTION public.qt_direct_write_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid; v_status text; v_suspended_until timestamptz;\n  v_created_at timestamptz; v_total int; v_per int; v_has_sub boolean; v_usage json; v_sub_id uuid;\nbegin\n  if not public.qna_is_direct_untrusted_writer() then return NEW; end if;\n  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id = NEW.mentor_student_room_id;\n  if TG_OP = ''INSERT'' then\n    if v_student is null then raise exception ''ROOM_NOT_FOUND''; end if;\n    if v_uid is distinct from v_student then raise exception ''DIRECT_CREATE_STUDENT_ONLY''; end if;\n    if coalesce(NEW.status,''pending'') not in (''pending'',''open'') then raise exception ''DIRECT_INSERT_STATUS_FORBIDDEN''; end if;\n    if NEW.first_answered_at is not null or NEW.confirmed_at is not null then raise exception ''DIRECT_INSERT_WORKFLOW_FIELDS_FORBIDDEN''; end if;\n    select status, suspended_until, created_at into v_status, v_suspended_until, v_created_at from public.users where id=v_student;\n    if lower(coalesce(v_status,''active''))=''banned'' then raise exception ''ACCOUNT_BANNED''; end if;\n    if lower(coalesce(v_status,''active''))=''suspended'' and (v_suspended_until is null or v_suspended_until > now()) then raise exception ''ACCOUNT_SUSPENDED''; end if;\n    if public.qna_users_blocked(v_student, v_mentor) then raise exception ''BLOCKED''; end if;\n    if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception ''MENTOR_NOT_APPROVED''; end if;\n    v_has_sub := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'');\n    if v_has_sub then\n      select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor and lower(coalesce(status,''''))=''active'';\n      if v_sub_id is not null and public.qna_subscription_has_live_refund(v_sub_id) then raise exception ''SUBSCRIPTION_REFUND_PENDING''; end if;\n      v_usage := public.get_weekly_question_usage(v_student, v_mentor);\n      if not coalesce((v_usage->>''can_ask'')::boolean, false) then raise exception ''WEEKLY_LIMIT_EXHAUSTED''; end if;\n    else\n      if v_created_at is not null and now() >= v_created_at + interval ''7 days'' then raise exception ''FREE_QUOTA_EXPIRED''; end if;\n      select count(*) into v_total from public.free_question_usage where student_id=v_student;\n      if v_total >= 7 then raise exception ''FREE_QUOTA_TOTAL_EXHAUSTED''; end if;\n      select count(*) into v_per from public.free_question_usage where student_id=v_student and mentor_id=v_mentor;\n      if v_per >= 3 then raise exception ''FREE_QUOTA_MENTOR_EXHAUSTED''; end if;\n    end if;\n    return NEW;\n  end if;\n  if NEW.status is distinct from OLD.status then\n    if NEW.status = ''answered'' then raise exception ''DIRECT_ANSWERED_VIA_CONTENT_ONLY''; end if;\n    if NEW.status = ''confirmed'' and v_uid is distinct from v_student then raise exception ''DIRECT_CONFIRM_STUDENT_ONLY''; end if;\n  end if;\n  if NEW.first_answered_at is distinct from OLD.first_answered_at then raise exception ''DIRECT_FIRST_ANSWERED_VIA_CONTENT_ONLY''; end if;\n  if (NEW.is_wrong_answer is distinct from OLD.is_wrong_answer or NEW.mastery_status is distinct from OLD.mastery_status) and v_uid is distinct from v_student then raise exception ''DIRECT_WRONG_FLAG_STUDENT_ONLY''; end if;\n  return NEW;\nend; $function$\n", "configuration": ["search_path=public"], "security_definer": false}, "[\"public\", \"record_cash_topup(uuid,bigint,text)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": "P0: Service-role only RPC for test cash topup. Public, anon, and authenticated execution are explicitly revoked.", "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "record_cash_topup(uuid,bigint,text)", "definition": "CREATE OR REPLACE FUNCTION public.record_cash_topup(p_user_id uuid, p_amount_cents bigint, p_idempotency_key text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin\n  -- S2 M9(계약 §7 F11 2층): 검증·원자 판정·지갑 가산은 공용 구현부가 020 과 동일\n  -- 메시지·순서로 수행한다. 반환값은 폐기하며 duplicate(필드 불일치 포함)는 기존\n  -- 계약대로 무음 반환한다 — mismatch 를 새로 외부에 노출하지 않는다.\n  perform core_private.record_cash_topup_impl(p_user_id, p_amount_cents, p_idempotency_key);\nend;\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"record_custom_order_dispute_split(uuid,integer,integer,uuid)\"]": {"acl": {"entries": [{"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantor": "postgres", "grantable": false, "privilege": "EXECUTE"}], "is_null": false}, "owner": "postgres", "schema": "public", "comment": "P0: Custom order dispute escrow split — mentor net (gross − settlement fee_rate) + student refund; hold gross must match sum. 191: fee_rate from custom_order_settlement_items (SETTLEMENT_FEE_RATE_MISSING if absent). service_role only.", "execute": {"anon": false, "service_role": true, "authenticated": false}, "identity": "record_custom_order_dispute_split(uuid,integer,integer,uuid)", "definition": "CREATE OR REPLACE FUNCTION public.record_custom_order_dispute_split(p_order_id uuid, p_mentor_gross_won integer, p_student_refund_won integer, p_admin_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  o public.custom_request_orders%rowtype;\n  s public.custom_order_settlement_items%rowtype;\n  v_hold_idem text := ''cr_hold_'' || p_order_id::text;\n  v_payout_idem text := ''cr_payout_'' || p_order_id::text;\n  v_refund_idem text := ''cr_refund_'' || p_order_id::text;\n  v_dispute_payout_idem text := ''cr_dispute_payout_'' || p_order_id::text;\n  v_dispute_refund_idem text := ''cr_dispute_refund_'' || p_order_id::text;\n  v_hold_cents bigint;\n  v_hold_gross_won integer;\n  v_settlement_gross integer;\n  v_fee_rate numeric;                 -- 191: 정산 행(custom_order_settlement_items.fee_rate)에서 읽는다 — 내부 상수 없음\n  v_settlement_found boolean := false;\n  v_platform_fee_won integer;\n  v_mentor_net_won integer;\n  v_mentor_cents bigint;\n  v_student_cents bigint;\n  v_pay text;\n  v_norm text;\n  v_admin_ok boolean;\n  v_new_mentor_ledger uuid;\n  v_new_student_ledger uuid;\n  v_wu int;\n  v_now timestamptz := now();\n  v_disputes_resolved int := 0;\nbegin\n  if p_order_id is null then\n    raise exception ''p_order_id is required'';\n  end if;\n  if p_admin_id is null then\n    raise exception ''ADMIN_REQUIRED'';\n  end if;\n  if p_mentor_gross_won is null or p_student_refund_won is null then\n    raise exception ''DISPUTE_SPLIT_AMOUNTS_REQUIRED'';\n  end if;\n  if p_mentor_gross_won < 0 or p_student_refund_won < 0 then\n    raise exception ''DISPUTE_SPLIT_AMOUNTS_INVALID'';\n  end if;\n\n  select exists(\n    select 1 from public.users u where u.id = p_admin_id and u.role = ''admin''\n  ) into v_admin_ok;\n  if not coalesce(v_admin_ok, false) then\n    raise exception ''ADMIN_REQUIRED'';\n  end if;\n\n  select * into o\n  from public.custom_request_orders\n  where id = p_order_id\n  for update;\n\n  if not found then\n    raise exception ''ORDER_NOT_FOUND'';\n  end if;\n\n  if o.student_id is null or o.mentor_id is null then\n    raise exception ''ORDER_PARTIES_MISSING'';\n  end if;\n\n  v_pay := lower(trim(coalesce(nullif(trim(o.payment_status), ''''), '''')));\n  v_norm := public._order_primary_status_norm(o);\n\n  -- payout / refund / dispute-split 상호 배타\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key = v_payout_idem\n      and l.reason = ''custom_order_escrow_payout''\n  ) then\n    raise exception ''ALREADY_PAID_OUT'';\n  end if;\n\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key = v_refund_idem\n      and l.reason = ''custom_order_escrow_refund''\n  ) then\n    raise exception ''ALREADY_REFUNDED'';\n  end if;\n\n  select * into s\n  from public.custom_order_settlement_items\n  where custom_request_order_id = p_order_id\n  for update;\n  v_settlement_found := found;\n\n  if v_settlement_found and s.status = ''paid'' then\n    raise exception ''ALREADY_PAID_OUT'';\n  end if;\n\n  -- 191: 플랫폼 수수료율은 해당 주문의 정산 행 요율만 쓴다. 정산 행이 없거나 요율이 NULL 이면\n  --      추측하지 않고 예외(부분 반영 0 — 트랜잭션 전체 rollback).\n  if not v_settlement_found or s.fee_rate is null then\n    raise exception ''SETTLEMENT_FEE_RATE_MISSING'';\n  end if;\n  v_fee_rate := s.fee_rate;\n\n  select abs(l.delta_cents) into v_hold_cents\n  from public.cash_ledger l\n  where l.idempotency_key = v_hold_idem\n    and l.reason = ''custom_order_escrow_hold''\n  limit 1;\n\n  if v_hold_cents is null then\n    raise exception ''ESCROW_HOLD_MISSING'';\n  end if;\n\n  if v_hold_cents <= 0 or v_hold_cents > 1000000000 then\n    raise exception ''ESCROW_HOLD_AMOUNT_INVALID'';\n  end if;\n\n  if v_hold_cents % 100 <> 0 then\n    raise exception ''ESCROW_HOLD_AMOUNT_INVALID'';\n  end if;\n\n  v_hold_gross_won := (v_hold_cents / 100)::integer;\n\n  if found then\n    v_settlement_gross := s.gross_amount;\n    if v_settlement_gross is distinct from v_hold_gross_won then\n      raise exception ''ESCROW_HOLD_AMOUNT_MISMATCH'';\n    end if;\n  end if;\n\n  -- 멱등: 분배 ledger 가 하나라도 있으면 상태 수리 후 종료\n  if exists (\n    select 1 from public.cash_ledger l\n    where l.idempotency_key in (v_dispute_payout_idem, v_dispute_refund_idem)\n      and l.reason in (''custom_order_dispute_payout'', ''custom_order_dispute_refund'')\n  ) then\n    update public.custom_order_settlement_items\n    set status = ''cancelled'', updated_at = v_now\n    where custom_request_order_id = p_order_id\n      and status in (''pending'', ''on_hold'', ''payable'');\n\n    update public.custom_request_orders\n    set\n      payment_status = ''dispute_resolved'',\n      status = ''dispute_resolved'',\n      state = ''dispute_resolved'',\n      order_status = ''dispute_resolved'',\n      updated_at = v_now\n    where id = p_order_id;\n\n    update public.disputes d\n    set\n      status = ''resolved'',\n      resolved_at = coalesce(d.resolved_at, v_now),\n      resolved_by = coalesce(d.resolved_by, p_admin_id),\n      updated_at = v_now\n    where d.custom_request_order_id = p_order_id\n      and d.status in (''open'', ''under_review'', ''escalated'');\n\n    get diagnostics v_disputes_resolved = row_count;\n\n    return jsonb_build_object(\n      ''ok'', true,\n      ''noop'', true,\n      ''order_id'', p_order_id,\n      ''hold_gross_won'', v_hold_gross_won,\n      ''disputes_resolved'', v_disputes_resolved\n    );\n  end if;\n\n  if p_mentor_gross_won + p_student_refund_won is distinct from v_hold_gross_won then\n    raise exception ''DISPUTE_SPLIT_MISMATCH'';\n  end if;\n\n  if v_pay not in (''escrowed'', ''dispute_resolved'') then\n    raise exception ''PAYMENT_NOT_ESCROWED'';\n  end if;\n\n  v_platform_fee_won := floor(p_mentor_gross_won * v_fee_rate)::integer;\n  v_mentor_net_won := p_mentor_gross_won - v_platform_fee_won;\n  v_mentor_cents := v_mentor_net_won::bigint * 100;\n  v_student_cents := p_student_refund_won::bigint * 100;\n\n  if v_mentor_cents > 1000000000 or v_student_cents > 1000000000 then\n    raise exception ''p_amount_too_large'';\n  end if;\n\n  if v_mentor_cents > 0 then\n    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n    values (\n      o.mentor_id,\n      v_mentor_cents,\n      ''custom_order_dispute_payout'',\n      ''custom_request_orders'',\n      p_order_id,\n      v_dispute_payout_idem\n    )\n    on conflict (idempotency_key) do nothing\n    returning id into v_new_mentor_ledger;\n\n    if v_new_mentor_ledger is not null then\n      insert into public.cash_wallets (user_id, balance_cents)\n      values (o.mentor_id, 0)\n      on conflict (user_id) do nothing;\n\n      update public.cash_wallets w\n      set balance_cents = w.balance_cents + v_mentor_cents\n      where w.user_id = o.mentor_id;\n      get diagnostics v_wu = row_count;\n      if coalesce(v_wu, 0) = 0 then\n        raise exception ''CASH_WALLET_UPDATE_FAILED'' using errcode = ''P0001'';\n      end if;\n    end if;\n  end if;\n\n  if v_student_cents > 0 then\n    insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)\n    values (\n      o.student_id,\n      v_student_cents,\n      ''custom_order_dispute_refund'',\n      ''custom_request_orders'',\n      p_order_id,\n      v_dispute_refund_idem\n    )\n    on conflict (idempotency_key) do nothing\n    returning id into v_new_student_ledger;\n\n    if v_new_student_ledger is not null then\n      insert into public.cash_wallets (user_id, balance_cents)\n      values (o.student_id, 0)\n      on conflict (user_id) do nothing;\n\n      update public.cash_wallets w\n      set balance_cents = w.balance_cents + v_student_cents\n      where w.user_id = o.student_id;\n      get diagnostics v_wu = row_count;\n      if coalesce(v_wu, 0) = 0 then\n        raise exception ''CASH_WALLET_UPDATE_FAILED'' using errcode = ''P0001'';\n      end if;\n    end if;\n  end if;\n\n  update public.custom_order_settlement_items\n  set status = ''cancelled'', updated_at = v_now\n  where custom_request_order_id = p_order_id\n    and status in (''pending'', ''on_hold'', ''payable'');\n\n  update public.custom_request_orders\n  set\n    payment_status = ''dispute_resolved'',\n    status = ''dispute_resolved'',\n    state = ''dispute_resolved'',\n    order_status = ''dispute_resolved'',\n    updated_at = v_now\n  where id = p_order_id;\n\n  update public.disputes d\n  set\n    status = ''resolved'',\n    resolved_at = coalesce(d.resolved_at, v_now),\n    resolved_by = coalesce(d.resolved_by, p_admin_id),\n    updated_at = v_now\n  where d.custom_request_order_id = p_order_id\n    and d.status in (''open'', ''under_review'', ''escalated'');\n\n  get diagnostics v_disputes_resolved = row_count;\n\n  return jsonb_build_object(\n    ''ok'', true,\n    ''noop'', false,\n    ''order_id'', p_order_id,\n    ''hold_gross_won'', v_hold_gross_won,\n    ''mentor_gross_won'', p_mentor_gross_won,\n    ''mentor_platform_fee_won'', v_platform_fee_won,\n    ''mentor_net_won'', v_mentor_net_won,\n    ''mentor_cents'', v_mentor_cents,\n    ''student_refund_won'', p_student_refund_won,\n    ''student_cents'', v_student_cents,\n    ''fee_rate'', v_fee_rate,\n    ''disputes_resolved'', v_disputes_resolved\n  );\nend;\n$function$\n", "configuration": ["search_path=public"], "security_definer": true}, "[\"public\", \"record_custom_order_escrow_hold(uuid,uuid,