istinct from old.suspended_until\n     or new.status_reason     is distinct from old.status_reason\n     or new.status_changed_at is distinct from old.status_changed_at\n     or new.status_changed_by is distinct from old.status_changed_by\n     or new.terms_agreed_at   is distinct from old.terms_agreed_at\n     or new.privacy_agreed_at is distinct from old.privacy_agreed_at\n     or new.marketing_agreed  is distinct from old.marketing_agreed\n     or new.created_at        is distinct from old.created_at then\n    raise exception ''USERS_PROTECTED_COLUMNS'' using errcode = ''42501'';\n  end if;\n  return new;\nend\n$function$\n", "configuration": ["search_path=\"\""], "security_definer": false}}, "relations": {"[\"api_app_v1\", \"community_posts_v1\"]": {"acl": {"entries": [{"grantee": "authenticated", "grantor": "postgres", "grantable": false, "privilege": "SELECT"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "DELETE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "INSERT"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "MAINTAIN"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "REFERENCES"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "SELECT"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "TRIGGER"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "TRUNCATE"}, {"grantee": "postgres", "grantor": "postgres", "grantable": false, "privilege": "UPDATE"}], "is_null": false}, "rls": false, "kind": "v", "name": "community_posts_v1", "owner": "postgres", "schema": "api_app_v1", "options": ["security_invoker=true"], "force_rls": false, "view_definition": " SELECT id,\n    author_id,\n    title,\n    COALESCE(content, body) AS body,\n    category,\n    COALESCE(image_urls, ''{}''::text[]) AS image_refs,\n    author_label,\n    author_ro