'pending''::text, ''on_hold''::text, ''payable''::text])) AND (o.accepted_at IS NOT NULL) AND (o.accepted_at <= now()) AND (COALESCE(lower(TRIM(BOTH FROM o.payment_status)), ''''::text) <> ''refunded''::text) AND (COALESCE(lower(TRIM(BOTH FROM o.status)), ''''::text) <> ALL (ARRAY[''cancelled''::text, ''canceled''::text, ''refunded''::text])) AND (NOT (EXISTS ( SELECT 1\n           FROM disputes d\n          WHERE ((d.custom_request_order_id = o.id) AND (d.status = ANY (ARRAY[''open''::text, ''under_review''::text, ''escalated''::text])))))))\nUNION ALL\n SELECT ''individual_question''::text AS source_type,\n    q.id AS source_id,\n    COALESCE(q.claimed_mentor_id, q.designated_mentor_id) AS mentor_id,\n    (floor(((q.price_cents)::numeric * 0.85)))::bigint AS mentor_amount_cents,\n    (q.price_cents)::bigint AS gross_cents,\n    (q.price_cents - (floor(((q.price_cents)::numeric * 0.85)))::bigint) AS platform_fee_cents,\n    0.15 AS fee_rate,\n    q.released_at AS completion_ts\n   FROM individual_questions q\n  WHERE ((q.released_at IS NOT NULL) AND (q.released_at <= now()) AND (q.release_ledger_id IS NULL) AND (q.refund_ledger_id IS NULL) AND (q.status <> ALL (ARRAY[''refunded''::text, ''expired''::text, ''canceled''::text])) AND (COALESCE(q.claimed_mentor_id, q.designated_mentor_id) IS NOT NULL));"}, "[\"public\", \"favorites\"]": {"acl": {"entries": [{"grantee": "anon", "grantor": "postgres", "grantable": false, "privilege": "DELETE"}, {"grantee": "anon", "grantor": "postgres", "grantable": false, "privilege": "INSERT"}, {"grantee": "anon", "grantor": "postgres", "grantable": false, "privilege": "MAINTAIN"}, {"grantee": "anon", "grantor": "postgres", "grantable": false, "privilege": "REFERENCES"}, {"grantee": "anon", "grantor": "postgres", "grantable": false, "privilege": "SELECT"}, {"grantee": "anon", "grantor": "postgres", "grantable": false, "privilege": "TRIGGER"}, {"grantee": "anon", "grantor": "postgres", "grantable": false, "privilege": "TRUNCATE"}, {"gra