-- SOURCE supabase/integration_fragments/00_period_schema.sql
-- Integrator-owned additive schema. The applied 127 migrations remain immutable.
ALTER TABLE public.subscriptions ADD COLUMN current_service_period_event_id uuid
 REFERENCES public.subscription_billing_events(id) ON DELETE RESTRICT;
CREATE INDEX subscriptions_current_service_period_event_idx ON public.subscriptions(current_service_period_event_id);
ALTER TABLE public.subscriptions ADD COLUMN renewal_notice_attempted_at timestamptz;
CREATE INDEX subscriptions_renewal_notice_fair_idx ON public.subscriptions
 (renewal_notice_attempted_at ASC NULLS FIRST,next_billing_at,id)
 WHERE status='active' AND NOT cancel_at_period_end AND next_billing_at IS NOT NULL;
ALTER TABLE public.question_threads ADD COLUMN service_period_event_id uuid
 REFERENCES public.subscription_billing_events(id) ON DELETE RESTRICT;
CREATE INDEX question_threads_service_period_event_idx ON public.question_threads(service_period_event_id);

CREATE TABLE public.service_period_extensions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 billing_event_id uuid NOT NULL REFERENCES public.subscription_billing_events(id) ON DELETE RESTRICT,
 mentor_activity_event_id uuid NOT NULL REFERENCES public.mentor_activity_events(id) ON DELETE RESTRICT,
 extension_seconds bigint NOT NULL CHECK(extension_seconds>0 AND extension_seconds<=604800),
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(billing_event_id,mentor_activity_event_id)
);
ALTER TABLE public.service_period_extensions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.service_period_extensions FROM PUBLIC,anon,authenticated,service_role;
CREATE INDEX service_period_extensions_activity_idx ON public.service_period_extensions(mentor_activity_event_id);

CREATE FUNCTION core_private.qna_assert_text_bound(p_value text,p_max integer)
RETURNS void LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
BEGIN IF char_length(p_value)>p_max THEN RAISE EXCEPTION USING ERRCODE='22001',MESSAGE='QNA_INPUT_TOO_LONG'; END IF; END $$;
REVOKE ALL ON FUNCTION core_private.qna_assert_text_bound(text,integer) FROM PUBLIC,anon,authenticated,service_role;
ALTER TABLE public.question_attachments ADD CONSTRAINT question_attachments_storage_path_length CHECK(char_length(storage_path)<=1024);
ALTER TABLE public.question_attachments ADD CONSTRAINT question_attachments_file_name_length CHECK(char_length(file_name)<=255);
ALTER TABLE public.question_attachments ADD CONSTRAINT question_attachments_mime_type_length CHECK(char_length(mime_type)<=127);
-- Preserve the RC subject bound alongside PR138's stricter topic bound.
ALTER TABLE public.question_threads ADD CONSTRAINT question_threads_subject_length_check CHECK (subject IS NULL OR char_length(subject)<=64);

-- SOURCE supabase/integration_fragments/track_a/01_schema.sql
-- Track A fragment: no issuance and no external writes. Integrator owns final migration.
CREATE TABLE public.voucher_campaigns (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_key text NOT NULL UNIQUE CHECK(length(campaign_key) BETWEEN 1 AND 120),
 redeem_start timestamptz NOT NULL DEFAULT '2026-10-06 00:00+09' CHECK(redeem_start='2026-10-06 00:00+09'),
 redeem_end timestamptz NOT NULL DEFAULT '2026-11-20 00:00+09' CHECK(redeem_end='2026-11-20 00:00+09'),
 service_end timestamptz NOT NULL DEFAULT '2026-11-20 00:00+09' CHECK(service_end='2026-11-20 00:00+09'),
 gross_cents integer NOT NULL DEFAULT 11500000 CHECK(gross_cents=11500000),
 platform_fee_cents integer NOT NULL DEFAULT 1725000 CHECK(platform_fee_cents=1725000),
 mentor_amount_cents integer NOT NULL DEFAULT 9775000 CHECK(mentor_amount_cents=9775000),
 plan_tier text NOT NULL DEFAULT 'standard' CHECK(plan_tier='standard'),
 weekly_question_limit integer NOT NULL DEFAULT 9 CHECK(weekly_question_limit=9),
 status text NOT NULL DEFAULT 'disabled' CHECK(status IN ('active','disabled'))
);
CREATE TABLE public.voucher_entitlements (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES public.voucher_campaigns(id) ON DELETE RESTRICT,
 external_entitlement_hmac text NOT NULL UNIQUE CHECK(external_entitlement_hmac ~ '^[0-9a-f]{64}$'),
 code_hmac text NOT NULL UNIQUE CHECK(code_hmac ~ '^[0-9a-f]{64}$'),
 hmac_key_version text NOT NULL CHECK(length(hmac_key_version) BETWEEN 1 AND 64),
 status text NOT NULL DEFAULT 'issued' CHECK(status IN ('issued','redeemed','revoked')),
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.voucher_delivery_envelopes (
 entitlement_id uuid PRIMARY KEY REFERENCES public.voucher_entitlements(id) ON DELETE RESTRICT,
 ciphertext text NOT NULL CHECK(length(ciphertext) BETWEEN 24 AND 4096 AND ciphertext ~ '^[A-Za-z0-9+/]+={0,2}$'),
 nonce text NOT NULL CHECK(length(nonce)=16 AND nonce ~ '^[A-Za-z0-9+/]{16}$'),
 auth_tag text NOT NULL CHECK(length(auth_tag)=24 AND auth_tag ~ '^[A-Za-z0-9+/]{22}==$'),
 encryption_key_version text NOT NULL CHECK(length(encryption_key_version) BETWEEN 1 AND 64),
 algorithm text NOT NULL DEFAULT 'A256GCM' CHECK(algorithm='A256GCM'), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.voucher_redemptions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entitlement_id uuid NOT NULL UNIQUE REFERENCES public.voucher_entitlements(id) ON DELETE RESTRICT,
 subscription_id uuid NOT NULL REFERENCES public.subscriptions(id) ON DELETE RESTRICT,
 student_id uuid NOT NULL REFERENCES public.users(id) ON DELETE RESTRICT,
 mentor_id uuid NOT NULL REFERENCES public.users(id) ON DELETE RESTRICT,
 request_id uuid NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','refunded','revoked')),
 service_start timestamptz NOT NULL, service_end timestamptz NOT NULL CHECK(service_end='2026-11-20 00:00+09'),
 decided_at timestamptz NOT NULL, gross_cents integer NOT NULL DEFAULT 11500000 CHECK(gross_cents=11500000),
 platform_fee_cents integer NOT NULL DEFAULT 1725000 CHECK(platform_fee_cents=1725000),
 mentor_amount_cents integer NOT NULL DEFAULT 9775000 CHECK(mentor_amount_cents=9775000),
 weekly_question_limit integer NOT NULL DEFAULT 9 CHECK(weekly_question_limit=9), plan_tier text NOT NULL DEFAULT 'standard' CHECK(plan_tier='standard'),
 UNIQUE(student_id,request_id),
 CHECK(service_start=decided_at AND service_start >= '2026-10-06 00:00+09' AND service_start < service_end),
 UNIQUE(id,subscription_id,student_id,mentor_id,service_start,service_end,gross_cents)
);
ALTER TABLE public.subscriptions DROP CONSTRAINT subscriptions_funding_source_check;
ALTER TABLE public.subscriptions ADD CONSTRAINT subscriptions_funding_source_check CHECK(funding_source IN ('cash','pg','voucher'));
ALTER TABLE public.subscription_billing_events ADD COLUMN funding_source text CHECK(funding_source IN ('cash','pg','voucher'));
ALTER TABLE public.subscription_billing_events ADD COLUMN voucher_redemption_id uuid UNIQUE REFERENCES public.voucher_redemptions(id) ON DELETE RESTRICT;
ALTER TABLE public.subscription_billing_events ADD CONSTRAINT voucher_event_source_binding CHECK (
 (funding_source IS DISTINCT FROM 'voucher' AND voucher_redemption_id IS NULL) OR
 (funding_source IS NOT DISTINCT FROM 'voucher' AND voucher_redemption_id IS NOT NULL AND payment_id IS NULL AND ledger_id IS NULL AND event_type='initial' AND amount_cents IS NOT DISTINCT FROM 11500000 AND plan_tier IS NOT DISTINCT FROM 'standard' AND period_start IS NOT NULL AND period_end IS NOT NULL)
);
ALTER TABLE public.subscription_billing_events ADD CONSTRAINT voucher_event_snapshot_binding FOREIGN KEY(voucher_redemption_id,subscription_id,student_id,mentor_id,period_start,period_end,amount_cents)
 REFERENCES public.voucher_redemptions(id,subscription_id,student_id,mentor_id,service_start,service_end,gross_cents) ON DELETE RESTRICT;
ALTER TABLE public.voucher_campaigns ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.voucher_entitlements ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.voucher_delivery_envelopes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.voucher_redemptions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.voucher_campaigns,public.voucher_entitlements,public.voucher_delivery_envelopes,public.voucher_redemptions FROM PUBLIC,anon,authenticated;
-- No seed: real campaign creation/issuance is an explicit operational action outside RC.

-- SOURCE supabase/integration_fragments/track_b/001_schema.sql
-- Track B financial sidecar: paid ledger history is never rewritten.
create table public.service_period_financial_holds (
 billing_event_id uuid primary key references public.subscription_billing_events(id) on delete restrict,
 state text not null check(state in ('hold','adjustment_required')),
 reason text not null check(char_length(reason) between 1 and 120),
 updated_at timestamptz not null default now()
);
alter table public.service_period_financial_holds enable row level security;
revoke all on public.service_period_financial_holds from public,anon,authenticated;
create table public.voucher_external_refunds (
 external_refund_key text primary key check(char_length(external_refund_key) between 1 and 200),
 billing_event_id uuid not null references public.subscription_billing_events(id) on delete restrict,
 amount_cents bigint not null check(amount_cents>0),
 refund_id uuid not null unique references public.refunds(id) on delete restrict,
 created_at timestamptz not null default now()
);
alter table public.voucher_external_refunds enable row level security;
revoke all on public.voucher_external_refunds from public,anon,authenticated;

-- Provider-confirmed receipts only. No provider call or user-supplied browser proof.
create table public.subscription_pg_refund_receipts (
 refund_id uuid primary key references public.refunds(id) on delete restrict,
 payment_id uuid not null references public.payments(id) on delete restrict,
 provider text not null check(char_length(provider) between 1 and 64),
 cancellation_id text not null check(char_length(cancellation_id) between 1 and 200),
 amount_cents bigint not null check(amount_cents>0),
 cancelled_at timestamptz not null,
 unique(provider,cancellation_id)
);
alter table public.subscription_pg_refund_receipts enable row level security;
revoke all on public.subscription_pg_refund_receipts from public,anon,authenticated;

-- SOURCE supabase/integration_fragments/track_b/010_financial_state.sql
-- Legacy unbound refunds match a payment only if it identifies exactly one service event.
-- An unresolved subscription-only refund holds rather than contaminating every historical period.
create or replace function core_private.refund_matches_service_period(p_refund public.refunds,p_event public.subscription_billing_events)
returns boolean language sql stable set search_path='' as $$
 select case when p_refund.billing_event_id is not null then p_refund.billing_event_id=p_event.id
 when p_refund.payment_id is not null and p_refund.payment_id=p_event.payment_id then
  (select count(*)=1 from public.subscription_billing_events x where x.payment_id=p_event.payment_id and x.status='succeeded' and x.event_type in ('initial','renewal'))
 else false end
$$;

create or replace function core_private.service_period_financial_state(p_event_id uuid)
returns text language plpgsql volatile security definer set search_path='' as $$
declare e public.subscription_billing_events%rowtype; v text; r public.voucher_redemptions%rowtype;
begin
 select * into e from public.subscription_billing_events where id=p_event_id;
 if not found or e.status<>'succeeded' or e.event_type not in ('initial','renewal') then return 'hold'; end if;
 if core_private.service_period_funding(e.id)='unknown' then return 'hold'; end if;
 select state into v from public.service_period_financial_holds where billing_event_id=e.id;
 if v='adjustment_required' then return v; end if;
 if exists(select 1 from public.refunds f where f.status='succeeded' and core_private.refund_matches_service_period(f,e)) then return 'refunded'; end if;
 if exists(select 1 from public.refunds f where f.status='pending' and (core_private.refund_matches_service_period(f,e) or (f.billing_event_id is null and f.subscription_id=e.subscription_id))) then return 'pending'; end if;
 if v='hold' then return v; end if;
 if exists(select 1 from public.refunds f where f.status='succeeded' and f.billing_event_id is null and f.subscription_id=e.subscription_id and (f.payment_id is null or f.payment_id=e.payment_id) and not core_private.refund_matches_service_period(f,e)) then return 'hold'; end if;
 if e.voucher_redemption_id is not null then
  select * into r from public.voucher_redemptions where id=e.voucher_redemption_id;
  if not found or r.status<>'active' or r.subscription_id<>e.subscription_id or r.student_id<>e.student_id or r.mentor_id<>e.mentor_id then return 'hold'; end if;
  if not exists(select 1 from public.voucher_entitlements t where t.id=r.entitlement_id and t.status='redeemed') then return 'hold'; end if;
 elsif e.payment_id is not null then
  if not exists(select 1 from public.payments p where p.id=e.payment_id and coalesce(p.student_id,p.payer_id,p.user_id)=e.student_id and p.mentor_id=e.mentor_id and p.status in ('succeeded','paid','success','complete','captured') and p.amount*100=e.amount_cents) then return 'hold'; end if;
 elsif e.ledger_id is null then return 'hold'; end if;
 if e.ledger_id is not null and not exists(select 1 from public.cash_ledger l where l.id=e.ledger_id and l.user_id=e.student_id and l.delta_cents=-e.amount_cents) then return 'hold'; end if;
 return 'clear';
end $$;

create or replace function public.qna_subscription_has_live_refund(p_subscription_id uuid)
returns boolean language sql volatile security definer set search_path='' as $$
 select exists(select 1 from public.refunds r where r.subscription_id=p_subscription_id and r.status='pending'
 and (r.request_type in ('subscription_prorated','subscription_mentor_suspended','voucher_external') or r.billing_event_id is not null))
$$;

-- Pair lock is the shared serializing primitive for refund/payout/checkout/redeem.
create or replace function core_private.lock_service_period_finance(p_event_id uuid)
returns void language plpgsql set search_path='' as $$
declare e public.subscription_billing_events%rowtype; v_entitlement uuid;
begin
 select * into e from public.subscription_billing_events where id=p_event_id;
 if not found then raise exception 'SERVICE_PERIOD_NOT_FOUND'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(e.student_id::text),pg_catalog.hashtext(e.mentor_id::text));
 if e.voucher_redemption_id is not null then
  select entitlement_id into v_entitlement from public.voucher_redemptions where id=e.voucher_redemption_id;
  perform 1 from public.voucher_entitlements where id=v_entitlement for update;
 elsif e.payment_id is not null then perform 1 from public.payments where id=e.payment_id for update; end if;
 perform 1 from public.subscriptions where id=e.subscription_id for update;
 -- profile lock precedes event/item, also freezes payout account and pause/termination state.
 perform 1 from public.mentor_profiles where user_id=e.mentor_id for update;
 perform 1 from public.subscription_billing_events where id=e.id for update;
 if e.voucher_redemption_id is not null then perform 1 from public.voucher_redemptions where id=e.voucher_redemption_id for update; end if;
end $$;

create or replace function public.keep_subscription_refunded_status()
returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.status='canceled' and exists(select 1 from public.subscription_billing_events e join public.refunds r on core_private.refund_matches_service_period(r,e)
 where e.id=coalesce(new.current_service_period_event_id,new.last_billing_event_id) and e.subscription_id=new.id and r.status='succeeded') then
 new.status:='refunded'; new.cancel_at_period_end:=false; new.next_billing_at:=null;
 new.canceled_at:=coalesce(new.canceled_at,now()); new.expired_at:=coalesce(new.expired_at,now()); end if;
 return new;
end $$;
create or replace function public.sync_subscription_refunded_from_refund()
returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.status='succeeded' and new.subscription_id is not null then
  update public.subscriptions s set status='refunded',cancel_at_period_end=false,canceled_at=coalesce(s.canceled_at,now()),expired_at=coalesce(s.expired_at,now()),next_billing_at=null,updated_at=now()
  where s.id=new.subscription_id and exists(select 1 from public.subscription_billing_events e where e.id=coalesce(s.current_service_period_event_id,s.last_billing_event_id) and e.subscription_id=s.id and core_private.refund_matches_service_period(new,e));
  insert into public.service_period_financial_holds(billing_event_id,state,reason)
  select i.billing_event_id,'adjustment_required','refund_after_payout' from public.subscription_settlement_items i join public.subscription_billing_events e on e.id=i.billing_event_id
  where i.status='paid' and core_private.refund_matches_service_period(new,e)
  on conflict(billing_event_id) do update set state='adjustment_required',reason='refund_after_payout',updated_at=now();
 end if;
 return new;
end $$;
create or replace function core_private.subscription_has_pending_refund(p_subscription_id uuid)
returns boolean language sql volatile security definer set search_path='' as $$
 select exists(select 1 from public.refunds r where r.subscription_id=p_subscription_id and r.status='pending')
$$;

-- SOURCE supabase/integration_fragments/10_effective_period.sql
-- The original billing snapshot is never extended in place.
CREATE FUNCTION core_private.service_period_effective_end(p_event_id uuid)
RETURNS timestamptz LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE e public.subscription_billing_events%ROWTYPE; v_seconds bigint;
BEGIN
 SELECT * INTO e FROM public.subscription_billing_events WHERE id=p_event_id;
 IF NOT FOUND OR e.event_type NOT IN ('initial','renewal') OR e.period_start IS NULL
    OR e.period_end IS NULL OR e.period_start>=e.period_end THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM public.service_period_extensions x
   JOIN public.mentor_activity_events a ON a.id=x.mentor_activity_event_id
   WHERE x.billing_event_id=e.id AND (a.mentor_id IS DISTINCT FROM e.mentor_id
     OR a.event_type IS DISTINCT FROM 'pause_started' OR e.funding_source='voucher'
     OR e.voucher_redemption_id IS NOT NULL)) THEN RETURN NULL; END IF;
 SELECT coalesce(sum(extension_seconds),0) INTO v_seconds FROM public.service_period_extensions WHERE billing_event_id=e.id;
 RETURN e.period_end+v_seconds*interval '1 second';
END $$;
REVOKE ALL ON FUNCTION core_private.service_period_effective_end(uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION core_private.service_period_effective_end(uuid) TO service_role;

CREATE FUNCTION core_private.guard_service_period_extension()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE e public.subscription_billing_events%ROWTYPE; a public.mentor_activity_events%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'SERVICE_PERIOD_EXTENSION_IMMUTABLE'; END IF;
 SELECT * INTO e FROM public.subscription_billing_events WHERE id=NEW.billing_event_id;
 SELECT * INTO a FROM public.mentor_activity_events WHERE id=NEW.mentor_activity_event_id;
 IF e.id IS NULL OR a.id IS NULL OR e.mentor_id IS DISTINCT FROM a.mentor_id
    OR a.event_type IS DISTINCT FROM 'pause_started' OR e.status IS DISTINCT FROM 'succeeded'
    OR e.event_type NOT IN ('initial','renewal') OR e.period_start IS NULL OR e.period_end IS NULL
    OR e.period_start>=e.period_end OR e.voucher_redemption_id IS NOT NULL
    OR (e.funding_source IS NOT NULL AND e.funding_source NOT IN ('cash','pg'))
    OR core_private.service_period_funding(e.id) NOT IN ('cash','verified_legacy_cash','pg')
    OR core_private.service_period_financial_state(e.id) IS DISTINCT FROM 'clear' THEN
   RAISE EXCEPTION 'SERVICE_PERIOD_EXTENSION_BINDING_INVALID';
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION core_private.guard_service_period_extension() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER guard_service_period_extension BEFORE INSERT OR UPDATE OR DELETE ON public.service_period_extensions
 FOR EACH ROW EXECUTE FUNCTION core_private.guard_service_period_extension();

-- Existing initial trigger remains in force. Protect successful renewals too.
CREATE FUNCTION core_private.guard_renewal_period_snapshot()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF OLD.event_type='initial' AND OLD.status IN ('succeeded','refunded')
  AND ROW(NEW.funding_source,NEW.voucher_redemption_id) IS DISTINCT FROM ROW(OLD.funding_source,OLD.voucher_redemption_id)
  THEN RAISE EXCEPTION 'INITIAL_BILLING_EVENT_IMMUTABLE'; END IF;
 IF OLD.event_type='renewal' AND OLD.status IN ('succeeded','refunded') AND
  ROW(NEW.subscription_id,NEW.student_id,NEW.mentor_id,NEW.event_type,NEW.period_start,NEW.period_end,
      NEW.billing_at,NEW.amount_cents,NEW.plan_tier,NEW.plan_id,NEW.ledger_id,NEW.payment_id,NEW.idempotency_key,
      NEW.funding_source,NEW.voucher_redemption_id)
  IS DISTINCT FROM
  ROW(OLD.subscription_id,OLD.student_id,OLD.mentor_id,OLD.event_type,OLD.period_start,OLD.period_end,
      OLD.billing_at,OLD.amount_cents,OLD.plan_tier,OLD.plan_id,OLD.ledger_id,OLD.payment_id,OLD.idempotency_key,
      OLD.funding_source,OLD.voucher_redemption_id) THEN RAISE EXCEPTION 'RENEWAL_BILLING_EVENT_IMMUTABLE'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION core_private.guard_renewal_period_snapshot() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER guard_renewal_period_snapshot BEFORE UPDATE ON public.subscription_billing_events
 FOR EACH ROW EXECUTE FUNCTION core_private.guard_renewal_period_snapshot();

-- SOURCE supabase/integration_fragments/15_funding_context.sql
CREATE FUNCTION core_private.service_period_funding(p_event_id uuid)
RETURNS text LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE e public.subscription_billing_events%ROWTYPE; p public.payments%ROWTYPE;
 l public.cash_ledger%ROWTYPE; s public.subscriptions%ROWTYPE; r public.voucher_redemptions%ROWTYPE;
BEGIN
 SELECT * INTO e FROM public.subscription_billing_events WHERE id=p_event_id;
 IF NOT FOUND OR e.event_type NOT IN ('initial','renewal') OR e.status NOT IN ('succeeded','refunded')
  OR e.amount_cents IS NULL OR e.amount_cents<=0 OR e.period_start IS NULL OR e.period_end IS NULL OR e.period_start>=e.period_end THEN RETURN 'unknown'; END IF;
 SELECT * INTO s FROM public.subscriptions WHERE id=e.subscription_id;
 IF s.id IS NULL OR s.student_id IS DISTINCT FROM e.student_id OR s.mentor_id IS DISTINCT FROM e.mentor_id THEN RETURN 'unknown'; END IF;
 IF e.funding_source='voucher' THEN
  SELECT * INTO r FROM public.voucher_redemptions WHERE id=e.voucher_redemption_id;
  IF r.id IS NULL OR e.payment_id IS NOT NULL OR e.ledger_id IS NOT NULL
    OR ROW(r.subscription_id,r.student_id,r.mentor_id,r.service_start,r.service_end,r.gross_cents,r.plan_tier)
     IS DISTINCT FROM ROW(e.subscription_id,e.student_id,e.mentor_id,e.period_start,e.period_end,e.amount_cents,e.plan_tier)
    OR NOT EXISTS(SELECT 1 FROM public.voucher_entitlements WHERE id=r.entitlement_id)
    OR r.gross_cents<>11500000 OR r.platform_fee_cents<>1725000 OR r.mentor_amount_cents<>9775000
    OR r.plan_tier<>'standard' OR r.weekly_question_limit<>9 THEN RETURN 'unknown'; END IF;
  RETURN 'voucher';
 END IF;
 IF e.voucher_redemption_id IS NOT NULL OR (e.funding_source IS NOT NULL AND e.funding_source NOT IN ('cash','pg')) THEN RETURN 'unknown'; END IF;
 IF e.payment_id IS NOT NULL THEN
  SELECT * INTO p FROM public.payments WHERE id=e.payment_id;
  IF p.id IS NULL OR coalesce(p.student_id,p.payer_id,p.user_id) IS DISTINCT FROM e.student_id
    OR p.mentor_id IS DISTINCT FROM e.mentor_id OR p.plan_id IS DISTINCT FROM e.plan_id
    OR p.status NOT IN ('succeeded','paid','success','complete','captured','refunded')
    OR p.amount*100 IS DISTINCT FROM e.amount_cents::numeric THEN RETURN 'unknown'; END IF;
 END IF;
 IF e.funding_source='pg' THEN
  IF e.payment_id IS NULL OR e.ledger_id IS NOT NULL THEN RETURN 'unknown'; END IF;
  RETURN 'pg';
 END IF;
 SELECT * INTO l FROM public.cash_ledger WHERE id=e.ledger_id;
 IF l.id IS NULL OR l.user_id IS DISTINCT FROM e.student_id OR l.ref_id IS DISTINCT FROM e.subscription_id
  OR l.ref_type IS DISTINCT FROM 'subscriptions' OR l.delta_cents IS DISTINCT FROM -e.amount_cents::bigint THEN RETURN 'unknown'; END IF;
 IF e.event_type='initial' THEN
  IF p.id IS NULL OR l.reason IS DISTINCT FROM 'subscription_payment'
   OR l.idempotency_key IS DISTINCT FROM 'sub_debit_'||p.id::text
   OR e.idempotency_key IS DISTINCT FROM 'sub_initial:'||e.subscription_id::text||':'||p.id::text
   OR (l.created_at IS DISTINCT FROM e.period_start AND NOT (
     e.funding_source IS NULL AND e.period_start=date_trunc('milliseconds',e.period_start)
     AND e.period_start=date_trunc('milliseconds',l.created_at))) THEN RETURN 'unknown'; END IF;
 ELSIF l.reason IS DISTINCT FROM 'subscription_renewal' OR l.idempotency_key IS DISTINCT FROM e.idempotency_key
       OR e.payment_id IS NOT NULL THEN RETURN 'unknown'; END IF;
 RETURN CASE WHEN e.funding_source IS NULL THEN 'verified_legacy_cash' ELSE 'cash' END;
END $$;
REVOKE ALL ON FUNCTION core_private.service_period_funding(uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION core_private.service_period_matches_subscription(p_subscription_id uuid,p_event_id uuid)
RETURNS boolean LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM public.subscriptions s JOIN public.subscription_billing_events e ON e.id=p_event_id
 WHERE s.id=p_subscription_id AND e.subscription_id=s.id AND e.student_id=s.student_id AND e.mentor_id=s.mentor_id
 AND (s.funding_source=e.funding_source OR ((s.funding_source IS NULL OR s.funding_source='cash')
   AND core_private.service_period_funding(e.id)='verified_legacy_cash')
   OR (s.funding_source IS NULL AND core_private.service_period_funding(e.id)='cash'))
 AND ((e.period_start=s.current_period_start AND core_private.service_period_effective_end(e.id)=s.current_period_end)
  OR (core_private.service_period_funding(e.id)='verified_legacy_cash'
   AND e.period_start=date_trunc('milliseconds',e.period_start)
   AND core_private.service_period_effective_end(e.id)=date_trunc('milliseconds',core_private.service_period_effective_end(e.id))
   AND e.period_start=date_trunc('milliseconds',s.current_period_start)
   AND core_private.service_period_effective_end(e.id)=date_trunc('milliseconds',s.current_period_end))))
$$;
REVOKE ALL ON FUNCTION core_private.service_period_matches_subscription(uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION api_app_v1.subscription_funding_context()
RETURNS TABLE(subscription_id uuid,billing_event_id uuid,is_current boolean,funding_source text,
 binding_verified boolean,legacy_cash_verified boolean,period_start timestamptz,period_end timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT e.subscription_id,e.id,coalesce((s.current_service_period_event_id=e.id)
   OR (s.current_service_period_event_id IS NULL AND s.funding_source='voucher' AND s.status='expired'
     AND core_private.service_period_matches_subscription(s.id,e.id)
     AND EXISTS(SELECT 1 FROM public.subscription_billing_events terminal WHERE terminal.id=s.last_billing_event_id
       AND terminal.subscription_id=s.id AND terminal.student_id=s.student_id AND terminal.mentor_id=s.mentor_id
       AND terminal.event_type='expired' AND terminal.status='succeeded'
       AND terminal.idempotency_key='voucher_expired:'||e.id::text)),false),e.funding_source,
   f.kind<>'unknown' AND (s.current_service_period_event_id IS DISTINCT FROM e.id
     OR core_private.service_period_matches_subscription(s.id,e.id)),
   f.kind='verified_legacy_cash',e.period_start,core_private.service_period_effective_end(e.id)
 FROM public.subscription_billing_events e JOIN public.subscriptions s ON s.id=e.subscription_id
 CROSS JOIN LATERAL (SELECT core_private.service_period_funding(e.id) kind OFFSET 0) f
 WHERE s.student_id=auth.uid() AND e.student_id=auth.uid() AND e.event_type IN ('initial','renewal')
 ORDER BY e.created_at DESC,e.id
$$;
REVOKE ALL ON FUNCTION api_app_v1.subscription_funding_context() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION api_app_v1.subscription_funding_context() TO authenticated;

CREATE FUNCTION core_private.current_cash_service_period_valid(p_subscription_id uuid)
RETURNS boolean LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM public.subscriptions s
 JOIN public.subscription_billing_events e ON e.id=s.current_service_period_event_id
 WHERE s.id=p_subscription_id AND e.subscription_id=s.id AND e.student_id=s.student_id AND e.mentor_id=s.mentor_id
 AND e.status='succeeded' AND core_private.service_period_matches_subscription(s.id,e.id)
 AND (s.funding_source='cash' OR s.funding_source IS NULL)
 AND core_private.service_period_funding(e.id) IN ('cash','verified_legacy_cash')
 AND core_private.service_period_financial_state(e.id)='clear')
$$;
REVOKE ALL ON FUNCTION core_private.current_cash_service_period_valid(uuid) FROM PUBLIC,anon,authenticated,service_role;

-- Cancel/undo and terminal transitions never debit cash. They retain the
-- verified PG contract while cash renewal/notice/claim remain cash-only.
CREATE FUNCTION core_private.current_standard_service_period_valid(p_subscription_id uuid)
RETURNS boolean LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path='' AS $$
 SELECT core_private.current_cash_service_period_valid(p_subscription_id) OR EXISTS(
 SELECT 1 FROM public.subscriptions s
 JOIN public.subscription_billing_events e ON e.id=s.current_service_period_event_id
 WHERE s.id=p_subscription_id AND s.funding_source='pg' AND e.status='succeeded'
 AND s.plan_id=e.plan_id AND s.plan_tier=e.plan_tier
 AND core_private.service_period_matches_subscription(s.id,e.id)
 AND core_private.service_period_funding(e.id)='pg'
 AND core_private.service_period_financial_state(e.id)='clear')
$$;
REVOKE ALL ON FUNCTION core_private.current_standard_service_period_valid(uuid) FROM PUBLIC,anon,authenticated,service_role;

-- SOURCE supabase/integration_fragments/track_b/021_refund_request.sql
CREATE OR REPLACE FUNCTION api_app_v1.refund_request_create(p_subscription_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_role text; v_status text; v_susp timestamptz; v_norm text;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_sub record;
  v_pending uuid;
  v_est jsonb;
  v_amount bigint;
  v_refund_id uuid;
  v_event uuid;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'AUTH_REQUIRED');
  end if;
  select u.role, u.status, u.suspended_until into v_role, v_status, v_susp from public.users u where u.id = v_uid;
  if not found or v_role is distinct from 'student' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROLE_NOT_STUDENT');
  end if;
  v_norm := lower(btrim(coalesce(v_status, '')));
  if v_norm = 'banned' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_BANNED');
  end if;
  if v_norm = 'suspended' and (v_susp is null or v_susp > now()) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_SUSPENDED');
  end if;
  if v_norm not in ('active', 'suspended') then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_NOT_ACTIVE');
  end if;
  if public.account_deletion_write_blocked(v_uid) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_DELETION_IN_PROGRESS');
  end if;
  if char_length(v_reason) < 5 then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'REASON_TOO_SHORT', 'min_length', 5);
  end if;
  if char_length(v_reason) > 2000 then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'REASON_TOO_LONG', 'max_length', 2000);
  end if;
  if p_subscription_id is null then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUBSCRIPTION_NOT_FOUND');
  end if;

  select coalesce(s.current_service_period_event_id,s.last_billing_event_id) into v_event from public.subscriptions s where s.id=p_subscription_id and s.student_id=v_uid;
  if v_event is null then return jsonb_build_object('ok',false,'contract_version',1,'code','SERVICE_PERIOD_UNRESOLVED'); end if;
  perform core_private.lock_service_period_finance(v_event);
  -- 본인 구독 잠금(동시 중복 신청 직렬화) · 현재 구독만
  select s.id, s.student_id, s.status, s.payment_id, s.last_billing_event_id
    into v_sub from public.subscriptions s where s.id = p_subscription_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUBSCRIPTION_NOT_FOUND');
  end if;
  if v_sub.student_id is distinct from v_uid then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'NOT_SUBSCRIPTION_OWNER');
  end if;
  if lower(btrim(coalesce(v_sub.status, ''))) not in ('active', 'past_due') then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUBSCRIPTION_NOT_CURRENT', 'status', v_sub.status);
  end if;
  select r.id into v_pending from public.refunds r
   where r.user_id = v_uid and r.subscription_id = p_subscription_id and r.status = 'pending'
   order by r.created_at desc limit 1;
  if v_pending is not null then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ALREADY_REQUESTED', 'refund_id', v_pending);
  end if;

  v_est := core_private.subscription_refund_estimate_impl(p_subscription_id, clock_timestamp());
  if not coalesce((v_est ->> 'ok')::boolean, false) then
    return v_est;
  end if;
  if (v_est->>'billing_event_id')::uuid is distinct from v_event then return jsonb_build_object('ok',false,'contract_version',1,'code','SERVICE_PERIOD_CHANGED'); end if;
  v_amount := coalesce((v_est ->> 'refundable_cents')::bigint, 0);
  if v_amount <= 0 then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'REFUND_NOT_AVAILABLE',
                              'rule', v_est ->> 'rule', 'bracket_reason', v_est ->> 'bracket_reason');
  end if;

  insert into public.refunds (user_id, amount_cents, status, payment_id, subscription_id, billing_event_id, request_type, reason)
  values (v_uid, v_amount, 'pending',
          coalesce((v_est ->> 'billing_payment_id')::uuid, v_sub.payment_id),
          p_subscription_id,
          coalesce((v_est ->> 'billing_event_id')::uuid, v_sub.last_billing_event_id),
          'subscription_prorated', v_reason)
  returning id into v_refund_id;

  return jsonb_build_object('ok', true, 'contract_version', 1, 'refund_id', v_refund_id,
                            'subscription_id', p_subscription_id, 'amount_cents', v_amount,
                            'rule', v_est ->> 'rule', 'bracket_reason', v_est ->> 'bracket_reason', 'status', 'pending');
end
$function$;

-- SOURCE supabase/integration_fragments/track_b/022_refund_approval.sql
CREATE OR REPLACE FUNCTION public.approve_refund_request_admin(p_refund_id uuid, p_admin_id uuid, p_admin_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  e public.subscription_billing_events%rowtype; v_event uuid;
  r public.refunds%rowtype; v_amount bigint; v_settlement_status text;
  v_idem text := 'refund_credit:' || p_refund_id::text; v_ledger_id uuid; v_existing_delta bigint; v_wu int; v_admin_ok boolean;
begin
  if coalesce(auth.role(),'')<>'service_role' and auth.uid() is distinct from p_admin_id then raise exception 'ADMIN_REQUIRED'; end if;
  if p_refund_id is null then return jsonb_build_object('ok', false, 'message', '환불 ID가 필요합니다.'); end if;
  if p_admin_id is null then return jsonb_build_object('ok', false, 'message', '관리자 ID가 필요합니다.'); end if;
  select exists(select 1 from public.users u where u.id = p_admin_id and u.role = 'admin') into v_admin_ok;
  if not coalesce(v_admin_ok, false) then raise exception 'ADMIN_REQUIRED'; end if;
  select * into r from public.refunds where id=p_refund_id;
  if r.subscription_id is not null then
    v_event:=r.billing_event_id;
    if v_event is null and r.payment_id is not null then
      select case when count(*)=1 then (array_agg(id))[1] end into v_event from public.subscription_billing_events where payment_id=r.payment_id and subscription_id=r.subscription_id and status='succeeded' and event_type in ('initial','renewal');
    end if;
    if v_event is null then return jsonb_build_object('ok',false,'code','SERVICE_PERIOD_UNRESOLVED'); end if;
    perform core_private.lock_service_period_finance(v_event);
    select * into e from public.subscription_billing_events where id=v_event;
    select * into r from public.refunds where id=p_refund_id for update;
    if r.status<>'pending' then return jsonb_build_object('ok',true,'noop',true,'refund_id',r.id,'status',r.status); end if;
    if not core_private.refund_matches_service_period(r,e) or r.user_id<>e.student_id then raise exception 'REFUND_PERIOD_BINDING_MISMATCH'; end if;
    if e.voucher_redemption_id is not null then return jsonb_build_object('ok',false,'code','VOUCHER_EXTERNAL_REFUND_REQUIRED'); end if;
    if r.amount_cents is null or r.amount_cents<=0 or r.amount_cents>e.amount_cents then raise exception 'REFUND_AMOUNT_INVALID'; end if;
    if exists(select 1 from public.subscription_settlement_items where billing_event_id=e.id and status='paid') then
      insert into public.service_period_financial_holds(billing_event_id,state,reason) values(e.id,'adjustment_required','refund_after_payout') on conflict(billing_event_id) do update set state='adjustment_required',reason='refund_after_payout',updated_at=now();
      return jsonb_build_object('ok',false,'code','ADJUSTMENT_REQUIRED');
    end if;
    if e.funding_source='pg' or exists(select 1 from public.payments p where p.id=e.payment_id and p.pg_tx_id is not null) then
      -- A trusted adapter must record the confirmed provider cancellation before finalization.
      if r.pg_cancellation_id is null or r.pg_cancelled_at is null then return jsonb_build_object('ok',false,'code','PG_REFUND_CONFIRMATION_REQUIRED'); end if;
    else
      insert into public.cash_ledger(user_id,delta_cents,reason,ref_type,ref_id,idempotency_key)
      values(r.user_id,r.amount_cents,'refund_approved','refunds',r.id,v_idem) on conflict(idempotency_key) do nothing returning id into v_ledger_id;
      if v_ledger_id is null then
        if not exists(select 1 from public.cash_ledger where idempotency_key=v_idem and delta_cents=r.amount_cents and user_id=r.user_id and ref_id=r.id) then raise exception 'REFUND_LEDGER_BINDING_MISMATCH'; end if;
      else
        insert into public.cash_wallets(user_id,balance_cents) values(r.user_id,0) on conflict(user_id) do nothing;
        update public.cash_wallets set balance_cents=balance_cents+r.amount_cents where user_id=r.user_id;
      end if;
    end if;
    update public.refunds set billing_event_id=e.id,status='succeeded',processed_at=clock_timestamp(),processed_by=p_admin_id,admin_note=p_admin_note where id=r.id;
    -- Only this period's immutable payment; never the subscription's newer payment reference.
    if e.payment_id is not null then update public.payments set status='refunded',updated_at=now() where id=e.payment_id; end if;
    if r.amount_cents=e.amount_cents then delete from public.service_period_financial_holds where billing_event_id=e.id and state='hold'; end if;
    if r.amount_cents<e.amount_cents then
      insert into public.service_period_financial_holds(billing_event_id,state,reason) values(e.id,'hold','partial_refund_allocation_unresolved') on conflict(billing_event_id) do nothing;
    end if;
    return jsonb_build_object('ok',true,'noop',false,'refund_id',r.id,'amount_cents',r.amount_cents);
  end if;
  select * into r from public.refunds where id = p_refund_id for update;
  if not found then return jsonb_build_object('ok', false, 'message', '환불 요청을 찾을 수 없습니다.'); end if;
  if r.status is distinct from 'pending' then
    return jsonb_build_object('ok', true, 'noop', true, 'refund_id', p_refund_id, 'message', '이미 처리되었거나 대기 상태가 아닙니다.', 'status', r.status);
  end if;
  if r.custom_request_order_id is not null then
    select s.status into v_settlement_status from public.custom_order_settlement_items s where s.custom_request_order_id = r.custom_request_order_id limit 1;
    if found and v_settlement_status = 'paid' then
      return jsonb_build_object('ok', false, 'message', '이미 정산 지급이 완료된 건은 자동 환불할 수 없습니다. 수동 조정이 필요합니다.');
    end if;
  end if;
  if r.payment_id is not null and (r.subscription_id is not null or coalesce(r.request_type, '') = 'subscription_prorated') then
    select s.status into v_settlement_status from public.subscription_settlement_items s where s.payment_id = r.payment_id and s.status = 'paid' limit 1;
    if found then return jsonb_build_object('ok', false, 'message', '이미 멘토 정산 지급이 완료된 구독 건은 자동 환불할 수 없습니다. 수동 조정이 필요합니다.'); end if;
  end if;
  if r.custom_request_order_id is not null then
    perform public.record_custom_order_escrow_refund(r.custom_request_order_id);
    update public.refunds set status='succeeded', processed_at=now(), processed_by=p_admin_id, admin_note=p_admin_note, updated_at=now() where id=r.id;
    return jsonb_build_object('ok', true, 'noop', false, 'refund_id', r.id, 'kind', 'custom_order_escrow', 'message', '맞춤의뢰 환불이 승인되었습니다.');
  end if;
  if r.amount_cents is null or r.amount_cents <= 0 then raise exception '환불 금액이 설정되지 않아 자동 승인할 수 없습니다.'; end if;
  v_amount := r.amount_cents;
  if v_amount > 1000000000 then return jsonb_build_object('ok', false, 'message', '환불 금액이 허용 한도를 초과합니다.'); end if;
  insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)
  values (r.user_id, v_amount, 'refund_approved', 'refunds', r.id, v_idem) on conflict (idempotency_key) do nothing returning id into v_ledger_id;
  if v_ledger_id is null then
    select cl.delta_cents into v_existing_delta from public.cash_ledger cl where cl.idempotency_key = v_idem limit 1;
    if not found then raise exception 'REFUND_LEDGER_IDEMPOTENT_MISS' using errcode = 'P0001'; end if;
    if v_existing_delta is distinct from v_amount then raise exception 'REFUND_LEDGER_AMOUNT_MISMATCH' using errcode = 'P0001'; end if;
  end if;
  if v_ledger_id is not null then
    insert into public.cash_wallets (user_id, balance_cents) values (r.user_id, 0) on conflict (user_id) do nothing;
    update public.cash_wallets w set balance_cents = w.balance_cents + v_amount where w.user_id = r.user_id;
    get diagnostics v_wu = row_count;
    if coalesce(v_wu, 0) = 0 then raise exception 'CASH_WALLET_UPDATE_FAILED' using errcode = 'P0001'; end if;
  end if;
  update public.refunds set status='succeeded', processed_at=now(), processed_by=p_admin_id, admin_note=p_admin_note, updated_at=now() where id=r.id;
  if r.payment_id is not null then update public.payments p set status='refunded', updated_at=now() where p.id = r.payment_id; end if;
  if r.payment_id is not null then update public.subscriptions s set status='canceled', updated_at=now() where s.payment_id = r.payment_id and s.status is distinct from 'canceled'; end if;
  return jsonb_build_object('ok', true, 'noop', false, 'refund_id', r.id, 'ledger_inserted', (v_ledger_id is not null), 'amount_cents', v_amount, 'message', '환불이 승인되었습니다.');
end; $function$;

-- SOURCE supabase/integration_fragments/track_b/023_external_voucher_refund.sql
create or replace function public.record_voucher_external_refund(p_billing_event_id uuid,p_external_refund_key text,p_amount_cents bigint)
returns jsonb language plpgsql security definer set search_path='' as $$
declare e public.subscription_billing_events%rowtype; v_existing public.voucher_external_refunds%rowtype; v_refund uuid; v_paid boolean; v_total bigint;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED'; end if;
 if p_external_refund_key is null or char_length(p_external_refund_key) not between 1 and 200 or p_amount_cents is null or p_amount_cents<=0 then raise exception 'INVALID_EXTERNAL_REFUND'; end if;
 perform core_private.lock_service_period_finance(p_billing_event_id);
 select * into e from public.subscription_billing_events where id=p_billing_event_id;
 if e.voucher_redemption_id is null then raise exception 'NOT_VOUCHER_PERIOD'; end if;
 select * into v_existing from public.voucher_external_refunds where external_refund_key=p_external_refund_key;
 if found then
  if v_existing.billing_event_id<>e.id or v_existing.amount_cents<>p_amount_cents then raise exception 'EXTERNAL_REFUND_REPLAY_CONFLICT'; end if;
  return jsonb_build_object('ok',true,'idempotent',true,'refund_id',v_existing.refund_id);
 end if;
 select coalesce(sum(amount_cents),0) into v_total from public.voucher_external_refunds where billing_event_id=e.id;
 if v_total+p_amount_cents>e.amount_cents then raise exception 'EXTERNAL_REFUND_AMOUNT_EXCEEDED'; end if;
 perform 1 from public.subscription_settlement_items where billing_event_id=e.id for update;
 select exists(select 1 from public.subscription_settlement_items where billing_event_id=e.id and status='paid') into v_paid;
 insert into public.refunds(user_id,subscription_id,billing_event_id,payment_id,amount_cents,status,request_type,reason)
 values(e.student_id,e.subscription_id,e.id,null,p_amount_cents,'pending','voucher_external','Confirmed external voucher refund') returning id into v_refund;
 insert into public.voucher_external_refunds(external_refund_key,billing_event_id,amount_cents,refund_id) values(p_external_refund_key,e.id,p_amount_cents,v_refund);
 update public.refunds set status='succeeded',processed_at=clock_timestamp() where id=v_refund;
 if v_total+p_amount_cents=e.amount_cents then
  update public.voucher_redemptions set status='refunded' where id=e.voucher_redemption_id;
  update public.refunds set status='canceled' where billing_event_id=e.id and status='pending' and id<>v_refund;
  delete from public.service_period_financial_holds where billing_event_id=e.id and state='hold';
 end if;
 if v_paid or v_total+p_amount_cents<e.amount_cents then
  insert into public.service_period_financial_holds(billing_event_id,state,reason)
  values(e.id,case when v_paid then 'adjustment_required' else 'hold' end,case when v_paid then 'external_refund_after_payout' else 'partial_refund_allocation_unresolved' end)
  on conflict(billing_event_id) do update set state=excluded.state,reason=excluded.reason,updated_at=now();
 end if;
 update public.subscription_settlement_items set status=case when v_total+p_amount_cents=e.amount_cents then 'canceled' else 'hold' end,
 hold_reason=case when v_total+p_amount_cents=e.amount_cents then 'refund_succeeded' else 'partial_refund_allocation_unresolved' end,updated_at=now()
 where billing_event_id=e.id and status<>'paid';
 return jsonb_build_object('ok',true,'idempotent',false,'refund_id',v_refund,'adjustment_required',v_paid);
end $$;

-- SOURCE supabase/integration_fragments/track_b/024_refund_write_guard.sql
-- Guard legacy/admin direct writes too. A row-level UPDATE already owns its row lock;
-- never wait backwards for a pair lock: serialization failure requires a full retry.
create or replace function core_private.guard_subscription_refund_write()
returns trigger language plpgsql security definer set search_path='' as $$
declare e public.subscription_billing_events%rowtype; v_student uuid; v_mentor uuid; v_event uuid;
begin
 if new.subscription_id is null then return new; end if;
 select student_id,mentor_id into v_student,v_mentor from public.subscriptions where id=new.subscription_id;
 if not found or new.user_id is distinct from v_student then raise exception 'REFUND_PARTY_MISMATCH'; end if;
 if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtext(v_student::text),pg_catalog.hashtext(v_mentor::text)) then
  raise exception 'REFUND_RETRY_REQUIRED' using errcode='40001';
 end if;
 if new.billing_event_id is null and new.payment_id is not null then
  select case when count(*)=1 then (array_agg(id))[1] end into v_event from public.subscription_billing_events
  where subscription_id=new.subscription_id and payment_id=new.payment_id and status='succeeded' and event_type in ('initial','renewal');
  new.billing_event_id:=v_event;
 end if;
 if new.billing_event_id is null then
  if new.status in ('rejected','canceled') then return new; end if;
  raise exception 'SERVICE_PERIOD_UNRESOLVED';
 end if;
 perform core_private.lock_service_period_finance(new.billing_event_id);
 select * into e from public.subscription_billing_events where id=new.billing_event_id;
 if e.subscription_id is distinct from new.subscription_id or e.student_id is distinct from new.user_id or e.payment_id is distinct from new.payment_id then raise exception 'REFUND_PERIOD_BINDING_MISMATCH'; end if;
 if tg_op='UPDATE' and(old.billing_event_id is not null and new.billing_event_id is distinct from old.billing_event_id or new.subscription_id is distinct from old.subscription_id or new.user_id is distinct from old.user_id or new.payment_id is distinct from old.payment_id) then raise exception 'REFUND_IDENTITY_IMMUTABLE'; end if;
 if tg_op='UPDATE' and old.status='succeeded' and (new.status is distinct from old.status or new.amount_cents is distinct from old.amount_cents or new.pg_cancellation_id is distinct from old.pg_cancellation_id or new.pg_cancelled_at is distinct from old.pg_cancelled_at) then raise exception 'FINAL_REFUND_IMMUTABLE'; end if;
 if new.amount_cents is not null and (new.amount_cents<=0 or new.amount_cents>e.amount_cents) then raise exception 'REFUND_AMOUNT_INVALID'; end if;
 if new.status='succeeded' and new.amount_cents is null then raise exception 'REFUND_AMOUNT_UNRESOLVED'; end if;
 if new.status='succeeded' and new.amount_cents+(select coalesce(sum(f.amount_cents),0) from public.refunds f where f.billing_event_id=e.id and f.status='succeeded' and f.id<>new.id)>e.amount_cents then raise exception 'REFUND_TOTAL_EXCEEDED'; end if;
 return new;
end $$;
create trigger rc_refund_period_binding before insert or update on public.refunds for each row execute function core_private.guard_subscription_refund_write();
create trigger rc_refund_insert_sync after insert on public.refunds for each row when(new.status='succeeded') execute function public.sync_subscription_refunded_from_refund();

-- SOURCE supabase/integration_fragments/track_b/025_pg_refund_confirmation.sql
-- Called only by a trusted provider adapter AFTER verifying the provider cancellation.
-- The RC never calls a live PG/refund service; provider adapter deployment remains an external dependency.
create or replace function public.record_subscription_pg_refund_confirmation(p_refund_id uuid,p_payment_id uuid,p_cancellation_id text,p_amount_cents bigint,p_cancelled_at timestamptz)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.refunds%rowtype; e public.subscription_billing_events%rowtype; p public.payments%rowtype; receipt public.subscription_pg_refund_receipts%rowtype; v_paid boolean;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED'; end if;
 select * into r from public.refunds where id=p_refund_id;
 if not found or r.billing_event_id is null then raise exception 'SERVICE_PERIOD_UNRESOLVED'; end if;
 perform core_private.lock_service_period_finance(r.billing_event_id);
 select * into e from public.subscription_billing_events where id=r.billing_event_id;
 select * into p from public.payments where id=e.payment_id;
 select * into r from public.refunds where id=p_refund_id for update;
 if p.id is null or p.id is distinct from p_payment_id or r.payment_id is distinct from p.id or r.user_id<>e.student_id or r.subscription_id<>e.subscription_id
 or p.pg_tx_id is null or p.pg_provider is null or e.voucher_redemption_id is not null then raise exception 'PG_REFUND_BINDING_MISMATCH'; end if;
 if p_amount_cents is distinct from r.amount_cents or p_amount_cents<=0 or p_amount_cents>e.amount_cents or p_cancelled_at is null or p_cancelled_at>clock_timestamp()
 or p_cancellation_id is null or char_length(p_cancellation_id) not between 1 and 200 then raise exception 'PG_REFUND_PROOF_INVALID'; end if;
 select * into receipt from public.subscription_pg_refund_receipts where refund_id=r.id;
 if found then
  if receipt.payment_id<>p.id or receipt.cancellation_id<>p_cancellation_id or receipt.amount_cents<>p_amount_cents or receipt.cancelled_at<>p_cancelled_at then raise exception 'PG_REFUND_REPLAY_CONFLICT'; end if;
  return jsonb_build_object('ok',true,'idempotent',true,'refund_id',r.id);
 end if;
 perform 1 from public.subscription_settlement_items where billing_event_id=e.id for update;
 select exists(select 1 from public.subscription_settlement_items where billing_event_id=e.id and status='paid') into v_paid;
 insert into public.subscription_pg_refund_receipts(refund_id,payment_id,provider,cancellation_id,amount_cents,cancelled_at)
 values(r.id,p.id,p.pg_provider,p_cancellation_id,p_amount_cents,p_cancelled_at);
 update public.refunds set pg_cancellation_id=p_cancellation_id,pg_cancelled_at=p_cancelled_at,status='succeeded',processed_at=clock_timestamp() where id=r.id;
 update public.payments set status='refunded',updated_at=now() where id=p.id;
 if p_amount_cents=e.amount_cents then update public.refunds set status='canceled' where billing_event_id=e.id and status='pending' and id<>r.id; end if;
 if v_paid or p_amount_cents<e.amount_cents then
  insert into public.service_period_financial_holds(billing_event_id,state,reason)
  values(e.id,case when v_paid then 'adjustment_required' else 'hold' end,case when v_paid then 'pg_refund_after_payout' else 'partial_refund_allocation_unresolved' end)
  on conflict(billing_event_id) do update set state=excluded.state,reason=excluded.reason,updated_at=now();
 else delete from public.service_period_financial_holds where billing_event_id=e.id and state='hold'; end if;
 update public.subscription_settlement_items set status=case when p_amount_cents=e.amount_cents then 'canceled' else 'hold' end,hold_reason='pg_refund_confirmed',updated_at=now() where billing_event_id=e.id and status<>'paid';
 return jsonb_build_object('ok',true,'idempotent',false,'refund_id',r.id,'adjustment_required',v_paid);
end $$;

-- SOURCE supabase/integration_fragments/financial_periods.sql
-- Final B-track definitions. Depends on voucher schema, B financial-state helpers,
-- and the integrator-owned immutable extensions/effective-end helper.

CREATE OR REPLACE FUNCTION core_private.subscription_refund_estimate_impl(p_subscription_id uuid, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_sub record;
  v_ev record;
  v_room uuid;
  v_now timestamptz;
  v_start timestamptz;
  v_end timestamptz;
  v_amount bigint;
  v_usage boolean;
  v_total_ms numeric;
  v_elapsed_ms numeric;
  v_remaining_ms numeric;
  v_refund bigint;
  v_bracket text;
  v_rule text;
begin
  if p_subscription_id is null then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUBSCRIPTION_NOT_FOUND');
  end if;
  select s.id, s.student_id, s.mentor_id, s.status, s.current_period_start, s.current_period_end, s.payment_id, s.last_billing_event_id, s.current_service_period_event_id
    into v_sub from public.subscriptions s where s.id = p_subscription_id;
  if not found then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUBSCRIPTION_NOT_FOUND');
  end if;

  select e.id,e.amount_cents,e.payment_id,e.period_start,e.period_end,e.voucher_redemption_id into v_ev
  from public.subscription_billing_events e where e.id=coalesce(v_sub.current_service_period_event_id,v_sub.last_billing_event_id)
  and e.subscription_id=v_sub.id and e.student_id=v_sub.student_id and e.mentor_id=v_sub.mentor_id and e.status='succeeded' and e.event_type in ('initial','renewal');
  if not found then return jsonb_build_object('ok',false,'contract_version',1,'code','SERVICE_PERIOD_UNRESOLVED'); end if;
  if v_ev.voucher_redemption_id is not null then return jsonb_build_object('ok',false,'contract_version',1,'code','VOUCHER_EXTERNAL_REFUND_REQUIRED'); end if;
  if core_private.service_period_financial_state(v_ev.id)<>'clear' then return jsonb_build_object('ok',false,'contract_version',1,'code','SERVICE_PERIOD_FINANCIAL_BLOCKED'); end if;
  v_start:=v_ev.period_start; v_end:=core_private.service_period_effective_end(v_ev.id);
  if v_end is null then return jsonb_build_object('ok',false,'contract_version',1,'code','SERVICE_PERIOD_UNRESOLVED'); end if;
  v_amount := greatest(0, coalesce(v_ev.amount_cents, 0));

  -- 이용 개시(첫 질문 작성) — 웹 hasSubscriptionUsageStartedForPair 동일 순서
  if v_sub.mentor_id is null then
    v_usage := true;   -- 멘토 미상(이상 데이터)은 보수적으로 개시로 본다(웹 동일)
  elsif v_start is null then
    v_usage := false;
  else
    select r.id into v_room from public.mentor_student_rooms r
     where r.student_id = v_sub.student_id and r.mentor_id = v_sub.mentor_id limit 1;
    if v_room is null then
      v_usage := false;
    else
      v_usage := exists (select 1 from public.question_threads t
                          where t.mentor_student_room_id = v_room and (t.service_period_event_id=v_ev.id or (t.service_period_event_id is null and t.created_at >= v_start and t.created_at < v_end)));
    end if;
  end if;

  -- JS Date 는 ms 정밀도 — 동일하게 ms 로 절단한다
  v_now := date_trunc('milliseconds', coalesce(p_now, now()));
  v_start := date_trunc('milliseconds', v_start);
  v_end := date_trunc('milliseconds', v_end);

  if v_amount = 0 or v_start is null or v_end is null or v_end <= v_start then
    return jsonb_build_object('ok', true, 'contract_version', 1, 'subscription_id', v_sub.id,
      'refundable_cents', 0, 'amount_cents', v_amount, 'rule', '계산 불가', 'bracket_reason', 'invalid',
      'usage_started', v_usage, 'elapsed_days', 0, 'period_days', 0, 'remaining_days', 0,
      'remaining_ratio', 0, 'elapsed_ratio', 0, 'period_start', v_start, 'period_end', v_end,
      'billing_event_id', v_ev.id, 'billing_payment_id', v_ev.payment_id, 'as_of', v_now);
  end if;

  v_total_ms := (extract(epoch from v_end) - extract(epoch from v_start)) * 1000;
  v_elapsed_ms := greatest(0, (extract(epoch from v_now) - extract(epoch from v_start)) * 1000);
  v_remaining_ms := greatest(0, (extract(epoch from v_end) - extract(epoch from v_now)) * 1000);

  if v_usage = false then
    v_refund := v_amount; v_bracket := 'before_usage'; v_rule := '이용 개시 전';
  elsif v_elapsed_ms * 3 < v_total_ms then
    v_refund := (v_amount * 2) / 3; v_bracket := 'lt_1_3'; v_rule := '1/3 전';
  elsif v_elapsed_ms * 2 < v_total_ms then
    v_refund := v_amount / 2; v_bracket := 'lt_1_2'; v_rule := '1/2 전';
  else
    v_refund := 0; v_bracket := 'ge_1_2'; v_rule := '1/2 후';
  end if;

  return jsonb_build_object('ok', true, 'contract_version', 1, 'subscription_id', v_sub.id,
    'refundable_cents', v_refund, 'amount_cents', v_amount, 'rule', v_rule, 'bracket_reason', v_bracket,
    'usage_started', v_usage,
    'elapsed_days', floor(v_elapsed_ms / 86400000)::int,
    'period_days', greatest(1, ceil(v_total_ms / 86400000)::int),
    'remaining_days', ceil(v_remaining_ms / 86400000)::int,
    'remaining_ratio', round(least(1, v_remaining_ms / v_total_ms), 6),
    'elapsed_ratio', round(least(1, v_elapsed_ms / v_total_ms), 6),
    'period_start', v_start, 'period_end', v_end,
    'billing_event_id', v_ev.id, 'billing_payment_id', v_ev.payment_id, 'as_of', v_now);
end
$function$;


create or replace function public.refresh_subscription_settlement_items(p_from timestamptz default null,p_to timestamptz default null)
returns table(item_status text,item_count bigint,gross_cents bigint,platform_fee_cents bigint,mentor_amount_cents bigint)
language plpgsql security definer set search_path='' as $$
begin
 -- Event identity owns economics; current subscription state is never historical evidence.
 with source as (
 select e.*,core_private.service_period_effective_end(e.id) effective_end,core_private.service_period_financial_state(e.id) financial_state,
 case when e.voucher_redemption_id is not null then r.platform_fee_cents::bigint else floor(e.amount_cents::numeric*0.15)::bigint end fee,
 case when e.voucher_redemption_id is not null then r.mentor_amount_cents::bigint else e.amount_cents-floor(e.amount_cents::numeric*0.15)::bigint end mentor_amount,
 coalesce(mp.activity_status,'active') activity_status,
 h.reason explicit_hold
 from public.subscription_billing_events e
 left join public.voucher_redemptions r on r.id=e.voucher_redemption_id
 left join public.mentor_profiles mp on mp.user_id=e.mentor_id
 left join public.service_period_financial_holds h on h.billing_event_id=e.id
 where e.status='succeeded' and e.event_type in ('initial','renewal') and e.amount_cents>0
 and (p_from is null or coalesce(e.billing_at,e.processed_at,e.created_at)>=p_from)
 and (p_to is null or coalesce(e.billing_at,e.processed_at,e.created_at)<p_to)
 ), calculated as (
 select *,case when explicit_hold is not null then 'hold' when financial_state='refunded' then 'canceled'
 when financial_state<>'clear' or activity_status<>'active' then 'hold'
 when effective_end is null then 'hold' when effective_end>clock_timestamp() then 'accruing' else 'pending' end new_status,
 case when effective_end is null then 'service_period_unresolved' when explicit_hold is not null then explicit_hold when financial_state<>'clear' then 'financial_'||financial_state
 when activity_status<>'active' then 'mentor_activity_unresolved' else null end new_hold
 from source
 )
 insert into public.subscription_settlement_items(billing_event_id,subscription_id,mentor_id,student_id,payment_id,ledger_id,event_type,billing_at,period_start,period_end,gross_cents,platform_fee_cents,mentor_amount_cents,fee_rate,status,hold_reason,idempotency_key)
 select id,subscription_id,mentor_id,student_id,payment_id,ledger_id,event_type,coalesce(billing_at,processed_at,created_at),period_start,effective_end,amount_cents,fee,mentor_amount,0.15,new_status,new_hold,'sub_settlement:'||id::text from calculated
 on conflict(billing_event_id) do update set status=excluded.status,hold_reason=excluded.hold_reason,period_start=excluded.period_start,period_end=excluded.period_end,updated_at=now()
 where public.subscription_settlement_items.status<>'paid';
 return query select i.status,count(*),coalesce(sum(i.gross_cents),0)::bigint,coalesce(sum(i.platform_fee_cents),0)::bigint,coalesce(sum(i.mentor_amount_cents),0)::bigint
 from public.subscription_settlement_items i where (p_from is null or i.billing_at>=p_from) and(p_to is null or i.billing_at<p_to) group by i.status order by i.status;
end $$;


create or replace view public.due_payouts as
 SELECT 'subscription'::text AS source_type,
    ssi.id AS source_id,
    ssi.mentor_id,
    ssi.mentor_amount_cents,
    ssi.gross_cents,
    ssi.platform_fee_cents,
    ssi.fee_rate,
    period.effective_end AS completion_ts
   FROM subscription_settlement_items ssi
  CROSS JOIN LATERAL (SELECT core_private.service_period_effective_end(ssi.billing_event_id) AS effective_end) period
  WHERE core_private.service_period_financial_state(ssi.billing_event_id)='clear' AND NOT EXISTS (SELECT 1 FROM public.service_period_financial_holds h WHERE h.billing_event_id=ssi.billing_event_id) AND NOT EXISTS (SELECT 1 FROM public.mentor_profiles mp WHERE mp.user_id=ssi.mentor_id AND coalesce(mp.activity_status,'active')<>'active') AND period.effective_end IS NOT NULL AND ssi.period_end IS NOT DISTINCT FROM period.effective_end AND period.effective_end <= now() AND (ssi.status <> ALL (ARRAY['paid'::text, 'hold'::text, 'canceled'::text]))
UNION ALL
 SELECT 'custom_request'::text AS source_type,
    cs.id AS source_id,
    cs.mentor_id,
    cs.mentor_amount::bigint * 100 AS mentor_amount_cents,
    cs.gross_amount::bigint * 100 AS gross_cents,
    cs.platform_fee_amount::bigint * 100 AS platform_fee_cents,
    cs.fee_rate,
    o.accepted_at AS completion_ts
   FROM custom_order_settlement_items cs
     JOIN custom_request_orders o ON o.id = cs.custom_request_order_id
  WHERE (cs.status = ANY (ARRAY['pending'::text, 'on_hold'::text, 'payable'::text])) AND o.accepted_at IS NOT NULL AND o.accepted_at <= now() AND COALESCE(lower(TRIM(BOTH FROM o.payment_status)), ''::text) <> 'refunded'::text AND (COALESCE(lower(TRIM(BOTH FROM o.status)), ''::text) <> ALL (ARRAY['cancelled'::text, 'canceled'::text, 'refunded'::text])) AND NOT (EXISTS ( SELECT 1
           FROM disputes d
          WHERE d.custom_request_order_id = o.id AND (d.status = ANY (ARRAY['open'::text, 'under_review'::text, 'escalated'::text]))))
UNION ALL
 SELECT 'individual_question'::text AS source_type,
    q.id AS source_id,
    COALESCE(q.claimed_mentor_id, q.designated_mentor_id) AS mentor_id,
    floor(q.price_cents::numeric * 0.85)::bigint AS mentor_amount_cents,
    q.price_cents::bigint AS gross_cents,
    q.price_cents - floor(q.price_cents::numeric * 0.85)::bigint AS platform_fee_cents,
    0.15 AS fee_rate,
    q.released_at AS completion_ts
   FROM individual_questions q
  WHERE q.released_at IS NOT NULL AND q.released_at <= now() AND q.release_ledger_id IS NULL AND q.refund_ledger_id IS NULL AND (q.status <> ALL (ARRAY['refunded'::text, 'expired'::text, 'canceled'::text])) AND COALESCE(q.claimed_mentor_id, q.designated_mentor_id) IS NOT NULL;


CREATE OR REPLACE FUNCTION public.pay_due_payouts_for_run(p_run_date date, p_idempotency_key text DEFAULT NULL::text, p_dry_run boolean DEFAULT true)
 RETURNS TABLE(run_id uuid, paid_count integer, skipped_no_account integer, total_mentor_cents bigint, total_withholding_cents bigint, total_net_cents bigint, dry_run boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_idem text := coalesce(p_idempotency_key, 'payout:' || to_char(p_run_date, 'YYYY-MM'));
  v_cutoff timestamptz := (date_trunc('month', p_run_date::timestamp) at time zone 'Asia/Seoul') - interval '1 second';
  v_run public.payout_runs%rowtype;
  v_run_id uuid;
  v_subscription_candidates uuid[];
  rec record; lock_pair record; fresh public.subscription_settlement_items%rowtype; ev public.subscription_billing_events%rowtype;
  v_ledger_id uuid; v_item_id uuid; v_has_account boolean; v_effective_end timestamptz;
  v_paid int := 0; v_skipped int := 0;
  v_total bigint := 0; v_total_wh bigint := 0; v_total_net bigint := 0;
  v_withholding bigint; v_net bigint; v_wh_ledger_id uuid;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED'; end if;
  if p_run_date is null or p_dry_run is null then raise exception 'PAYOUT_ARGUMENT_REQUIRED'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('subscription_payout_runs'),0);
  select coalesce(array_agg(d.source_id),'{}'::uuid[]) into v_subscription_candidates from public.due_payouts d where d.source_type='subscription' and d.completion_ts<=v_cutoff;
  -- Pre-acquire every candidate pair before retaining a profile/resource lock across loop iterations.
  for lock_pair in select distinct e.student_id,e.mentor_id from public.subscription_settlement_items i
   join public.subscription_billing_events e on e.id=i.billing_event_id where i.id=any(v_subscription_candidates)
   order by e.student_id,e.mentor_id
  loop perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(lock_pair.student_id::text),pg_catalog.hashtext(lock_pair.mentor_id::text)); end loop;
  if not p_dry_run then
    select * into v_run from public.payout_runs where idempotency_key = v_idem;
    if found then
      v_run_id := v_run.id;
      if v_run.status = 'completed' then
        return query select v_run.id, v_run.mentor_count, 0, v_run.total_mentor_cents,
          coalesce((select sum(withholding_cents) from public.payout_run_items where payout_run_id=v_run.id),0)::bigint,
          coalesce((select sum(net_paid_cents) from public.payout_run_items where payout_run_id=v_run.id),0)::bigint, false;
        return;
      end if;
    else
      insert into public.payout_runs (run_date, cutoff_end, status, idempotency_key)
      values (p_run_date, v_cutoff, 'executing', v_idem) returning id into v_run_id;
    end if;
  end if;

  for rec in
    select d.* from public.due_payouts d
    where d.completion_ts <= v_cutoff
      and (d.source_type<>'subscription' or d.source_id=any(v_subscription_candidates))
      and not exists (select 1 from public.payout_run_items i where i.source_type=d.source_type and i.source_id=d.source_id)
    order by d.mentor_id, d.source_type, d.completion_ts
  loop
    if rec.source_type='subscription' then
      select * into fresh from public.subscription_settlement_items where id=rec.source_id;
      if not found then continue; end if;
      perform core_private.lock_service_period_finance(fresh.billing_event_id);
      select * into ev from public.subscription_billing_events where id=fresh.billing_event_id;
      select * into fresh from public.subscription_settlement_items where id=rec.source_id for update;
      v_effective_end:=core_private.service_period_effective_end(ev.id);
      if v_effective_end is null or fresh.status not in ('pending','accruing') or fresh.period_end is null or fresh.period_end>clock_timestamp() or fresh.period_end>v_cutoff
       or core_private.service_period_financial_state(ev.id)<>'clear'
       or exists(select 1 from public.mentor_profiles where user_id=ev.mentor_id and coalesce(activity_status,'active')<>'active')
       or exists(select 1 from public.service_period_financial_holds where billing_event_id=ev.id)
       or exists(select 1 from public.payout_run_items where source_type='subscription' and source_id=fresh.id)
       or exists(select 1 from public.cash_ledger where idempotency_key='sub_payout:'||fresh.id::text)
       or fresh.mentor_id<>ev.mentor_id or fresh.student_id is distinct from ev.student_id or fresh.subscription_id<>ev.subscription_id
       or fresh.gross_cents<>ev.amount_cents or fresh.payment_id is distinct from ev.payment_id
       or fresh.period_start is distinct from ev.period_start or fresh.period_end is distinct from v_effective_end then continue; end if;
      if ev.voucher_redemption_id is not null then
        if not exists(select 1 from public.voucher_redemptions r where r.id=ev.voucher_redemption_id and r.gross_cents=fresh.gross_cents and r.platform_fee_cents=fresh.platform_fee_cents and r.mentor_amount_cents=fresh.mentor_amount_cents) then continue; end if;
      elsif fresh.platform_fee_cents<>floor(ev.amount_cents::numeric*0.15)::bigint or fresh.mentor_amount_cents<>ev.amount_cents-floor(ev.amount_cents::numeric*0.15)::bigint then continue; end if;
      rec.mentor_id:=fresh.mentor_id; rec.mentor_amount_cents:=fresh.mentor_amount_cents; rec.gross_cents:=fresh.gross_cents;
      rec.platform_fee_cents:=fresh.platform_fee_cents; rec.fee_rate:=fresh.fee_rate;
    end if;
    select coalesce(nullif(trim(mp.payout_account_number), ''), '') <> '' into v_has_account
      from public.mentor_profiles mp where mp.user_id = rec.mentor_id;
    if coalesce(v_has_account, false) = false then
      v_skipped := v_skipped + 1; continue;
    end if;

    v_withholding := public.calc_withholding_cents(rec.mentor_amount_cents);
    v_net := rec.mentor_amount_cents - v_withholding;

    if p_dry_run then
      v_paid := v_paid + 1; v_total := v_total + rec.mentor_amount_cents;
      v_total_wh := v_total_wh + v_withholding; v_total_net := v_total_net + v_net;
      continue;
    end if;

    v_ledger_id := null;
    v_item_id := null;
    if rec.source_type = 'custom_request' then
      perform public.record_custom_order_escrow_payout(rec.source_id);
      select id into v_ledger_id from public.cash_ledger
        where idempotency_key = 'cr_payout_' || rec.source_id::text and reason='custom_order_escrow_payout' limit 1;
    elsif rec.source_type = 'individual_question' then
      perform public.release_individual_question_payout(rec.source_id);
      select id into v_ledger_id from public.cash_ledger
        where idempotency_key = 'iq_payout:' || rec.source_id::text and reason='individual_question_payout' limit 1;
    elsif rec.source_type = 'subscription' then
      insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)
      values (rec.mentor_id, rec.mentor_amount_cents, 'subscription_settlement_payout',
              'subscription_settlement_items', rec.source_id, 'sub_payout:' || rec.source_id::text)
      on conflict (idempotency_key) do nothing returning id into v_ledger_id;
      if v_ledger_id is not null then
        insert into public.cash_wallets (user_id, balance_cents) values (rec.mentor_id, 0) on conflict (user_id) do nothing;
        update public.cash_wallets w set balance_cents = w.balance_cents + rec.mentor_amount_cents where w.user_id = rec.mentor_id;
      else
        select id into v_ledger_id from public.cash_ledger where idempotency_key='sub_payout:' || rec.source_id::text limit 1;
      end if;
      update public.subscription_settlement_items set status='paid', paid_at=coalesce(paid_at, now()), updated_at=now()
        where id = rec.source_id and status <> 'paid';
    else
      continue;
    end if;

    if v_withholding > 0 then
      v_wh_ledger_id := null;
      insert into public.cash_ledger (user_id, delta_cents, reason, ref_type, ref_id, idempotency_key)
      values (rec.mentor_id, -v_withholding, 'payout_withholding_3_3pct', rec.source_type, rec.source_id,
              'wh:' || rec.source_type || ':' || rec.source_id::text)
      on conflict (idempotency_key) do nothing returning id into v_wh_ledger_id;
      if v_wh_ledger_id is not null then
        update public.cash_wallets w set balance_cents = w.balance_cents - v_withholding where w.user_id = rec.mentor_id;
      end if;
    end if;

    insert into public.payout_run_items (
      payout_run_id, mentor_id, source_type, source_id,
      gross_cents, platform_fee_cents, mentor_amount_cents, fee_rate, ledger_id,
      withholding_cents, net_paid_cents
    ) values (
      v_run_id, rec.mentor_id, rec.source_type, rec.source_id,
      rec.gross_cents, rec.platform_fee_cents, rec.mentor_amount_cents, rec.fee_rate, v_ledger_id,
      v_withholding, v_net
    )
    on conflict (source_type, source_id) do nothing
    returning id into v_item_id;

    if v_item_id is not null then
      v_paid := v_paid + 1;
      v_total := v_total + rec.mentor_amount_cents;
      v_total_wh := v_total_wh + v_withholding;
      v_total_net := v_total_net + v_net;
    end if;
  end loop;

  if not p_dry_run then
    update public.payout_runs
    set status='completed',
        mentor_count=(select count(distinct mentor_id) from public.payout_run_items where payout_run_id=v_run_id),
        total_mentor_cents=(select coalesce(sum(mentor_amount_cents),0) from public.payout_run_items where payout_run_id=v_run_id),
        executed_at=now(), updated_at=now()
    where id=v_run_id;
  end if;

  return query select v_run_id, v_paid, v_skipped, v_total, v_total_wh, v_total_net, p_dry_run;
end;
$function$;

-- Both installed app RPC and web service RPC converge here. Caller wrappers own
-- actor authorization; this private implementation owns the complete transaction.
CREATE OR REPLACE FUNCTION core_private.mentor_financial_transition_impl(
 p_mentor_id uuid,p_action text,p_days integer,p_reason text,
 p_pause_until timestamptz DEFAULT NULL,p_termination_effective_at timestamptz DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
 s public.subscriptions%rowtype; e public.subscription_billing_events%rowtype;
 mp public.mentor_profiles%rowtype; v_subscription_ids uuid[];
 v_now timestamptz; v_end timestamptz; v_pause_until timestamptz; v_effective_at timestamptz;
 v_count integer:=0; v_refunds integer:=0; v_plans integer:=0; v_notified integer:=0;
 v_amount bigint; v_days integer; v_activity_id uuid; v_event_status text;
BEGIN
 IF p_action IS NULL OR p_action NOT IN ('termination_start','termination_finalize','pause','resume','abandonment') THEN
  RAISE EXCEPTION 'INVALID_MENTOR_ACTION';
 END IF;
 SELECT coalesce(array_agg(id ORDER BY id),'{}'::uuid[]) INTO v_subscription_ids
 FROM public.subscriptions WHERE mentor_id=p_mentor_id;
 -- Global pair order before retaining any shared mentor/profile lock.
 FOR s IN SELECT * FROM public.subscriptions WHERE id=ANY(v_subscription_ids) ORDER BY student_id,id LOOP
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(s.student_id::text),pg_catalog.hashtext(s.mentor_id::text));
 END LOOP;
 FOR s IN SELECT * FROM public.subscriptions WHERE id=ANY(v_subscription_ids) ORDER BY student_id,id LOOP
  IF coalesce(s.current_service_period_event_id,s.last_billing_event_id) IS NOT NULL THEN
   SELECT * INTO e FROM public.subscription_billing_events WHERE id=coalesce(s.current_service_period_event_id,s.last_billing_event_id);
   IF e.subscription_id IS DISTINCT FROM s.id OR e.student_id IS DISTINCT FROM s.student_id OR e.mentor_id IS DISTINCT FROM s.mentor_id THEN
    RAISE EXCEPTION 'SERVICE_PERIOD_UNRESOLVED';
   END IF;
   PERFORM core_private.lock_service_period_finance(e.id);
  ELSE
   PERFORM 1 FROM public.subscriptions WHERE id=s.id FOR UPDATE;
  END IF;
 END LOOP;
 SELECT * INTO mp FROM public.mentor_profiles WHERE user_id=p_mentor_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','MENTOR_PROFILE_NOT_FOUND'); END IF;
 IF EXISTS(SELECT 1 FROM public.subscriptions WHERE mentor_id=p_mentor_id AND NOT(id=ANY(v_subscription_ids))) THEN
  RAISE EXCEPTION 'MENTOR_TRANSITION_RETRY_REQUIRED' USING errcode='40001';
 END IF;
 v_now:=clock_timestamp();
 IF p_action='termination_start' THEN
  IF mp.activity_status IN ('terminating','terminated') THEN RETURN jsonb_build_object('ok',false,'code','MENTOR_ALREADY_TERMINATING'); END IF;
  v_effective_at:=greatest(coalesce(p_termination_effective_at,v_now+interval '14 days'),v_now+interval '14 days');
  IF NOT isfinite(v_effective_at) OR v_effective_at>v_now+interval '90 days' THEN RETURN jsonb_build_object('ok',false,'code','TERMINATION_DATE_TOO_FAR','max_days',90); END IF;
 ELSIF p_action='resume' THEN
  IF mp.activity_status IS DISTINCT FROM 'paused' THEN RETURN jsonb_build_object('ok',false,'code','MENTOR_NOT_PAUSED'); END IF;
 ELSIF p_action='pause' THEN
  -- The installed app treats an elapsed scheduled pause as active. Preserve that
  -- behavior while still allowing an explicit resume for a paused profile.
  IF coalesce(mp.activity_status,'active')<>'active' AND NOT coalesce(mp.activity_status='paused' AND mp.pause_until<=v_now,false) THEN
   RETURN jsonb_build_object('ok',false,'code','MENTOR_NOT_ACTIVE');
  END IF;
  IF p_reason IS NULL OR p_reason NOT IN ('rest','illness') THEN RETURN jsonb_build_object('ok',false,'code','PAUSE_REASON_INVALID'); END IF;
  IF p_reason='rest' AND mp.last_pause_at IS NOT NULL
   AND mp.last_pause_at > ((v_now AT TIME ZONE 'Asia/Seoul'-interval '6 months') AT TIME ZONE 'Asia/Seoul') THEN
   RETURN jsonb_build_object('ok',false,'code','REST_FREQUENCY_LIMIT','last_pause_at',mp.last_pause_at,
     'next_available_at',((mp.last_pause_at AT TIME ZONE 'Asia/Seoul'+interval '6 months') AT TIME ZONE 'Asia/Seoul'));
  END IF;
  IF p_pause_until IS NOT NULL THEN
   IF NOT isfinite(p_pause_until) OR p_pause_until<=v_now THEN RETURN jsonb_build_object('ok',false,'code','PAUSE_UNTIL_INVALID'); END IF;
   IF p_pause_until>v_now+interval '7 days' THEN RETURN jsonb_build_object('ok',false,'code','PAUSE_TOO_LONG','max_days',7); END IF;
   v_days:=greatest(1,ceil(extract(epoch FROM(p_pause_until-v_now))/86400.0)::integer);
   IF v_days>7 THEN RETURN jsonb_build_object('ok',false,'code','PAUSE_TOO_LONG','max_days',7); END IF;
   v_pause_until:=p_pause_until;
  ELSE
   v_days:=least(7,greatest(1,coalesce(p_days,1)));
   v_pause_until:=v_now+v_days*interval '1 day';
  END IF;
 ELSIF p_action='termination_finalize' AND (mp.termination_effective_at IS NULL OR mp.termination_effective_at>v_now) THEN
  RETURN jsonb_build_object('ok',false,'code','TERMINATION_NOT_DUE');
 END IF;
 v_event_status:=CASE WHEN p_action='abandonment' OR(p_action='pause' AND p_reason='illness') THEN 'pending_review' ELSE 'logged' END;
 INSERT INTO public.mentor_activity_events(mentor_id,event_type,reason,detail,status)
 VALUES(p_mentor_id,CASE p_action WHEN 'termination_start' THEN 'termination_requested' WHEN 'termination_finalize' THEN 'termination_finalized'
  WHEN 'pause' THEN 'pause_started' WHEN 'resume' THEN 'pause_resumed' ELSE 'abandonment_suspected' END,
  p_reason,jsonb_build_object('days',v_days,'pause_until',v_pause_until),v_event_status) RETURNING id INTO v_activity_id;
 IF p_action='termination_start' THEN
  UPDATE public.mentor_profiles SET activity_status='terminating',termination_requested_at=v_now,termination_effective_at=v_effective_at WHERE user_id=p_mentor_id;
  UPDATE public.mentor_plans SET is_active=false WHERE mentor_id=p_mentor_id AND is_active IS DISTINCT FROM false;
  GET DIAGNOSTICS v_plans=ROW_COUNT;
  SELECT count(*) INTO v_notified FROM public.subscriptions WHERE mentor_id=p_mentor_id AND status IN ('active','past_due');
 ELSIF p_action='resume' THEN
  UPDATE public.mentor_profiles SET activity_status='active',pause_until=NULL WHERE user_id=p_mentor_id;
  UPDATE public.mentor_plans SET is_active=true WHERE mentor_id=p_mentor_id AND is_active IS DISTINCT FROM true;
  GET DIAGNOSTICS v_plans=ROW_COUNT;
 ELSIF p_action='pause' THEN
  UPDATE public.mentor_profiles SET activity_status='paused',pause_started_at=v_now,pause_until=v_pause_until,pause_reason=p_reason,
   last_pause_at=CASE WHEN p_reason='rest' THEN v_now ELSE last_pause_at END WHERE user_id=p_mentor_id;
  FOR s IN SELECT * FROM public.subscriptions WHERE mentor_id=p_mentor_id AND status IN ('active','past_due') ORDER BY student_id,id LOOP
   SELECT * INTO e FROM public.subscription_billing_events WHERE id=coalesce(s.current_service_period_event_id,s.last_billing_event_id);
   v_end:=core_private.service_period_effective_end(e.id);
   IF e.id IS NULL OR e.status<>'succeeded' OR v_end IS NULL
    OR NOT core_private.service_period_matches_subscription(s.id,e.id) THEN
    RAISE EXCEPTION 'SERVICE_PERIOD_UNRESOLVED';
   END IF;
   IF e.voucher_redemption_id IS NOT NULL OR s.funding_source='voucher' THEN
    INSERT INTO public.service_period_financial_holds(billing_event_id,state,reason)
    VALUES(e.id,'hold','voucher_pause_allocation_unresolved') ON CONFLICT(billing_event_id) DO NOTHING;
   ELSE
    IF EXISTS(SELECT 1 FROM public.subscription_settlement_items WHERE billing_event_id=e.id AND status='paid') THEN
     RAISE EXCEPTION 'SERVICE_PERIOD_PAID_EXTENSION_REVIEW_REQUIRED';
    END IF;
    INSERT INTO public.service_period_extensions(billing_event_id,mentor_activity_event_id,extension_seconds)
    VALUES(e.id,v_activity_id,v_days::bigint*86400);
    UPDATE public.subscriptions SET current_period_end=core_private.service_period_effective_end(e.id),
     next_billing_at=coalesce(next_billing_at,v_end)+v_days*interval '1 day',updated_at=v_now WHERE id=s.id;
    v_count:=v_count+1;
   END IF;
  END LOOP;
 ELSE
  FOR s IN SELECT * FROM public.subscriptions WHERE mentor_id=p_mentor_id AND status IN ('active','past_due') ORDER BY student_id,id LOOP
   SELECT * INTO e FROM public.subscription_billing_events WHERE id=coalesce(s.current_service_period_event_id,s.last_billing_event_id);
   v_end:=core_private.service_period_effective_end(e.id);
   IF e.id IS NULL OR v_end IS NULL THEN RAISE EXCEPTION 'SERVICE_PERIOD_UNRESOLVED'; END IF;
   INSERT INTO public.service_period_financial_holds(billing_event_id,state,reason)
   VALUES(e.id,'hold',CASE WHEN p_action='abandonment' THEN 'mentor_abandonment_unresolved' ELSE 'mentor_termination_allocation_unresolved' END)
   ON CONFLICT(billing_event_id) DO NOTHING;
   IF NOT core_private.subscription_has_pending_refund(s.id) THEN
    -- Preserve the established cash remaining-time formula. Voucher allocation
    -- remains undecided: no invented cash value or automatic payout release.
    v_amount:=CASE WHEN e.voucher_redemption_id IS NOT NULL THEN NULL ELSE
     floor(e.amount_cents::numeric*least(1,greatest(0,extract(epoch FROM(v_end-v_now)))/nullif(extract(epoch FROM(v_end-e.period_start)),0)))::bigint END;
    IF e.voucher_redemption_id IS NOT NULL OR v_amount>0 THEN
     INSERT INTO public.refunds(user_id,subscription_id,billing_event_id,payment_id,amount_cents,status,request_type,reason)
     VALUES(e.student_id,e.subscription_id,e.id,e.payment_id,v_amount,'pending','subscription_mentor_suspended','Mentor termination: service period review required');
     v_refunds:=v_refunds+1;
    END IF;
   END IF;
   UPDATE public.subscriptions SET status='canceled',cancel_at_period_end=false,canceled_at=v_now,next_billing_at=NULL,updated_at=v_now WHERE id=s.id;
   v_count:=v_count+1;
  END LOOP;
  UPDATE public.mentor_profiles SET activity_status='terminated',abandonment_flagged_at=CASE WHEN p_action='abandonment' THEN v_now ELSE abandonment_flagged_at END WHERE user_id=p_mentor_id;
  UPDATE public.mentor_plans SET is_active=false WHERE mentor_id=p_mentor_id;
 END IF;
 UPDATE public.mentor_activity_events SET detail=jsonb_build_object('subscriptions',v_count,'refunds_created',v_refunds,'days',v_days,'pause_until',v_pause_until,'effective_at',v_effective_at) WHERE id=v_activity_id;
 -- Only this mentor's items; paid economics and period snapshots stay immutable.
 UPDATE public.subscription_settlement_items i SET
 status=CASE WHEN core_private.service_period_effective_end(be.id) IS NULL THEN 'hold'
  WHEN EXISTS(SELECT 1 FROM public.service_period_financial_holds h WHERE h.billing_event_id=be.id) THEN 'hold'
  WHEN core_private.service_period_financial_state(be.id)='refunded' THEN 'canceled'
  WHEN core_private.service_period_financial_state(be.id)<>'clear' OR p_action<>'resume' THEN 'hold'
  WHEN core_private.service_period_effective_end(be.id)>v_now THEN 'accruing' ELSE 'pending' END,
 hold_reason=CASE WHEN EXISTS(SELECT 1 FROM public.service_period_financial_holds h WHERE h.billing_event_id=be.id)
  THEN (SELECT h.reason FROM public.service_period_financial_holds h WHERE h.billing_event_id=be.id)
  WHEN core_private.service_period_effective_end(be.id) IS NULL THEN 'service_period_unresolved'
  WHEN p_action<>'resume' THEN 'mentor_activity_unresolved' ELSE NULL END,
 period_start=be.period_start,period_end=core_private.service_period_effective_end(be.id),updated_at=v_now
 FROM public.subscription_billing_events be WHERE be.id=i.billing_event_id AND i.mentor_id=p_mentor_id AND i.status<>'paid';
 RETURN jsonb_build_object('ok',true,'event_id',v_activity_id,'event_status',v_event_status,
  'summary',jsonb_build_object('refundsCreated',v_refunds,'subscriptions',v_count,'subscriptionsExtended',CASE WHEN p_action='pause' THEN v_count ELSE 0 END,
   'days',v_days,'pauseUntil',v_pause_until,'effectiveAt',v_effective_at,'plansChanged',v_plans,'notifiedSubscribers',v_notified));
END $$;
REVOKE ALL ON FUNCTION core_private.mentor_financial_transition_impl(uuid,text,integer,text,timestamptz,timestamptz) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.mentor_financial_transition(p_mentor_id uuid,p_action text,p_days integer DEFAULT NULL,p_reason text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED'; END IF;
 RETURN core_private.mentor_financial_transition_impl(p_mentor_id,p_action,p_days,p_reason);
END $$;
REVOKE ALL ON FUNCTION public.mentor_financial_transition(uuid,text,integer,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.mentor_financial_transition(uuid,text,integer,text) TO service_role;


-- Keep the installed application's signature, actor checks, timestamp inputs,
-- and successful envelope. It never writes subscription periods directly.
CREATE OR REPLACE FUNCTION api_app_v1.mentor_activity_set(
 p_status text,p_pause_until timestamptz DEFAULT NULL,
 p_termination_effective_at timestamptz DEFAULT NULL,p_reason text DEFAULT 'rest'
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
 v_uid uuid:=(SELECT auth.uid());
 v_role text; v_status text; v_susp timestamptz; v_norm text;
 v_target text:=lower(btrim(coalesce(p_status,'')));
 v_reason text:=lower(btrim(coalesce(p_reason,'rest')));
 v_result jsonb; v_summary jsonb; v_code text; v_state text;
BEGIN
  if v_uid is null then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'AUTH_REQUIRED');
  end if;
  select u.role, u.status, u.suspended_until into v_role, v_status, v_susp from public.users u where u.id = v_uid;
  if not found or v_role is distinct from 'mentor' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROLE_NOT_MENTOR');
  end if;
  v_norm := lower(btrim(coalesce(v_status, '')));
  if v_norm = 'banned' then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_BANNED');
  end if;
  if v_norm = 'suspended' and (v_susp is null or v_susp > now()) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_SUSPENDED');
  end if;
  if v_norm not in ('active', 'suspended') then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_NOT_ACTIVE');
  end if;
  if public.account_deletion_write_blocked(v_uid) then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACCOUNT_DELETION_IN_PROGRESS');
  end if;
  if v_target not in ('active', 'paused', 'terminating') then
    return jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ACTIVITY_STATUS_INVALID');
  end if;


 IF v_target='paused' AND p_pause_until IS NULL THEN
  RETURN jsonb_build_object('ok',false,'contract_version',1,'code','PAUSE_UNTIL_REQUIRED');
 END IF;
 v_result:=core_private.mentor_financial_transition_impl(v_uid,
  CASE v_target WHEN 'paused' THEN 'pause' WHEN 'active' THEN 'resume' ELSE 'termination_start' END,
  NULL,CASE WHEN v_target='paused' THEN v_reason ELSE NULL END,p_pause_until,p_termination_effective_at);
 IF NOT coalesce((v_result->>'ok')::boolean,false) THEN
  v_code:=v_result->>'code';
  IF v_code IN ('MENTOR_NOT_PAUSED','MENTOR_NOT_ACTIVE','MENTOR_ALREADY_TERMINATING') THEN
   SELECT coalesce(activity_status,'active') INTO v_state FROM public.mentor_profiles WHERE user_id=v_uid;
   RETURN jsonb_build_object('ok',false,'contract_version',1,'code','ACTIVITY_STATE_INVALID','current_state',v_state);
  END IF;
  RETURN v_result||jsonb_build_object('contract_version',1);
 END IF;
 v_summary:=v_result->'summary';
 IF v_target='paused' THEN
  RETURN jsonb_build_object('ok',true,'contract_version',1,'activity_status','paused',
   'pause_until',v_summary->'pauseUntil','pause_days',v_summary->'days','pause_reason',v_reason,
   'subscriptions_extended',v_summary->'subscriptionsExtended','event_status',v_result->'event_status','event_id',v_result->'event_id');
 ELSIF v_target='active' THEN
  RETURN jsonb_build_object('ok',true,'contract_version',1,'activity_status','active',
   'plans_reactivated',v_summary->'plansChanged','event_id',v_result->'event_id');
 ELSE
  RETURN jsonb_build_object('ok',true,'contract_version',1,'activity_status','terminating',
   'termination_effective_at',v_summary->'effectiveAt','notified_subscribers',v_summary->'notifiedSubscribers',
   'plans_deactivated',v_summary->'plansChanged','event_id',v_result->'event_id');
 END IF;
END $$;
REVOKE ALL ON FUNCTION api_app_v1.mentor_activity_set(text,timestamptz,timestamptz,text) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION api_app_v1.mentor_activity_set(text,timestamptz,timestamptz,text) TO authenticated;

-- SOURCE supabase/integration_fragments/20_cash_checkout.sql
-- PR138 initial identity and common v2/v3/app checkout are preserved.
CREATE OR REPLACE FUNCTION core_private.record_initial_subscription_billing_event(p_payment_id uuid, p_subscription_id uuid, p_set_latest boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  p public.payments%rowtype; s public.subscriptions%rowtype; l public.cash_ledger%rowtype;
  e public.subscription_billing_events%rowtype;
  v_tier text; v_key text := 'sub_initial:' || p_subscription_id::text || ':' || p_payment_id::text;
  v_start timestamptz; v_end timestamptz;
begin
  select * into strict p from public.payments where id = p_payment_id;
  select * into strict s from public.subscriptions where id = p_subscription_id for update;
  select * into l from public.cash_ledger where idempotency_key = 'sub_debit_' || p_payment_id::text;
  if l.id is null or l.user_id is distinct from p.user_id or l.ref_id is distinct from s.id
     or l.ref_type is distinct from 'subscriptions' or l.reason is distinct from 'subscription_payment'
     or l.delta_cents is distinct from -(p.amount * 100)::bigint
     or s.student_id is distinct from p.user_id or s.mentor_id is distinct from p.mentor_id
     or p.status not in ('succeeded','paid','success','complete','captured') then
    raise exception 'BILLING_EVENT_BINDING_MISMATCH';
  end if;
  select plan_tier into v_tier from public.mentor_plans where id = p.plan_id and mentor_id = p.mentor_id;
  if v_tier is null then raise exception 'PLAN_BINDING_MISMATCH'; end if;
  select * into e from public.subscription_billing_events
    where payment_id = p.id and event_type = 'initial' order by created_at, id limit 1;
  if e.id is not null then
    if e.subscription_id is distinct from s.id or e.ledger_id is distinct from l.id
       or e.amount_cents is distinct from -l.delta_cents or e.plan_id is distinct from p.plan_id
       or e.status not in ('succeeded', 'refunded') then
      raise exception 'BILLING_EVENT_BINDING_MISMATCH';
    end if;
    return e.id;
  end if;
  -- Checkout and its debit both use transaction now(). Never infer an old payment's
  -- period from subscriptions.current_period_*: cash renewals do not change last_payment_id.
  v_start := l.created_at;
  v_end := ((v_start at time zone 'Asia/Seoul' + interval '1 month') at time zone 'Asia/Seoul');
  insert into public.subscription_billing_events
    (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,
     amount_cents,plan_tier,plan_id,idempotency_key,ledger_id,payment_id,processed_at,funding_source)
  values (s.id,p.user_id,p.mentor_id,'initial','succeeded',v_start,v_end,l.created_at,
          -l.delta_cents,v_tier,p.plan_id,v_key,l.id,p.id,l.created_at,'cash')
  returning * into e;
  if p_set_latest and s.last_payment_id = p.id then
    update public.subscriptions set last_billing_event_id = e.id, current_service_period_event_id=e.id where id = s.id;
  end if;
  return e.id;
end $function$
;
CREATE OR REPLACE FUNCTION core_private.confirm_cash_subscription_payment(p_payment_id uuid, p_plan_id uuid, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY INVOKER
 SET search_path TO ''
AS $function$
declare
  v_student uuid; v_mentor uuid; v_pay_status text; v_created_at timestamptz; v_kind text;
  v_plan_mentor uuid; v_plan_tier text; v_plan_active boolean; v_amount_cents int;
  v_is_open boolean; v_sub_id uuid; v_reactivated boolean := false;
  v_status text; v_suspended_until timestamptz;
  v_l_user uuid; v_l_delta bigint; v_l_reason text; v_l_reftype text; v_l_refid uuid;
  v_succeeded_aliases text[] := array['succeeded','paid','success','complete','captured'];
  v_anom uuid; v_err text; v_errcode text;
  v_pair_student uuid; v_pair_mentor uuid; v_existing public.subscriptions%ROWTYPE; v_decided_at timestamptz;
begin
  select user_id,mentor_id into v_pair_student,v_pair_mentor from public.payments where id=p_payment_id;
  if not found then raise exception 'PAYMENT_NOT_FOUND'; end if;
  perform pg_advisory_xact_lock(hashtext(v_pair_student::text),hashtext(v_pair_mentor::text));
  select user_id, mentor_id, status, created_at, kind into v_student, v_mentor, v_pay_status, v_created_at, v_kind
    from public.payments where id = p_payment_id for update;
  if not found then raise exception 'PAYMENT_NOT_FOUND'; end if;
  if v_student is distinct from v_pair_student or v_mentor is distinct from v_pair_mentor then raise exception 'PAYMENT_PARTY_CHANGED'; end if;
  if v_student is null then raise exception 'PAYMENT_NO_USER'; end if;
  if v_mentor is null then raise exception 'PAYMENT_NO_MENTOR'; end if;
  if lower(coalesce(v_kind,'')) in ('cash_topup','topup','cash','individual_question','iq','custom_order','custom_request','deliverable') then raise exception 'PAYMENT_KIND_INVALID'; end if;
  perform pg_advisory_xact_lock(hashtext(v_student::text), hashtext(v_mentor::text));
  select * into v_existing from public.subscriptions where student_id=v_student and mentor_id=v_mentor for update;
  perform 1 from public.mentor_profiles where user_id=v_mentor for update;
  select mentor_id, plan_tier, is_active, amount_cents into v_plan_mentor, v_plan_tier, v_plan_active, v_amount_cents
    from public.mentor_plans where id = p_plan_id for update;
  if not found then raise exception 'PLAN_NOT_FOUND'; end if;
  if v_plan_mentor <> v_mentor then raise exception 'PLAN_MENTOR_MISMATCH'; end if;
  if v_amount_cents is null or v_amount_cents <= 0 then raise exception 'PLAN_AMOUNT_INVALID'; end if;
  if v_pay_status = any(v_succeeded_aliases) then
    select id into v_sub_id from public.subscriptions where student_id=v_student and mentor_id=v_mentor;
    if v_sub_id is null then
      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
        values (p_payment_id, null, 'SUCCEEDED_NO_SUBSCRIPTION', 'succeeded payment without subscription') returning id into v_anom;
      return jsonb_build_object('ok',false,'code','SUCCEEDED_NO_SUBSCRIPTION','anomaly_id',v_anom);
    end if;
    select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid
      from public.cash_ledger where idempotency_key = 'sub_debit_' || p_payment_id::text;
    if v_l_user is null then
      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
        values (p_payment_id, v_sub_id, 'SUCCEEDED_NO_LEDGER', 'succeeded payment without ledger debit') returning id into v_anom;
      return jsonb_build_object('ok',false,'code','SUCCEEDED_NO_LEDGER','anomaly_id',v_anom);
    end if;
    if v_l_user <> v_student or v_l_refid is distinct from v_sub_id or coalesce(v_l_reftype,'') <> 'subscriptions'
       or coalesce(v_l_reason,'') <> 'subscription_payment' or v_l_delta <> -v_amount_cents then
      insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)
        values (p_payment_id, v_sub_id, 'LEDGER_FIELD_MISMATCH', 'idempotent re-check field mismatch',
          jsonb_build_object('user_id',v_student,'ref_id',v_sub_id,'ref_type','subscriptions','reason','subscription_payment','delta_cents',-v_amount_cents),
          jsonb_build_object('user_id',v_l_user,'ref_id',v_l_refid,'ref_type',v_l_reftype,'reason',v_l_reason,'delta_cents',v_l_delta))
        returning id into v_anom;
      return jsonb_build_object('ok',false,'code','LEDGER_FIELD_MISMATCH','anomaly_id',v_anom);
    end if;
    return jsonb_build_object('ok',true,'idempotent',true,'subscription_id',v_sub_id,'payment_status','succeeded');
  end if;
  if v_pay_status = 'processing' then raise exception 'PAYMENT_PROCESSING'; end if;
  if v_pay_status in ('failed','canceled','refunded') then raise exception 'PAYMENT_NOT_PENDING'; end if;
  if v_pay_status <> 'pending' then raise exception 'PAYMENT_STATE_UNEXPECTED'; end if;
  if v_created_at is null or now() > v_created_at + interval '30 minutes' then raise exception 'PAYMENT_STALE'; end if;
  select status, suspended_until into v_status, v_suspended_until from public.users where id = v_student for update;
  if lower(coalesce(v_status,'active')) = 'banned' then raise exception 'ACCOUNT_BANNED'; end if;
  if lower(coalesce(v_status,'active')) = 'suspended' and (v_suspended_until is null or v_suspended_until > now()) then raise exception 'ACCOUNT_SUSPENDED'; end if;
  perform 1 from public.mentor_profiles where user_id = v_mentor for update;
  select is_open_for_subscriptions into v_is_open from public.mentor_profiles where user_id = v_mentor;
  if not coalesce(v_is_open, true) then raise exception 'MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS'; end if;
  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception 'MENTOR_NOT_APPROVED'; end if;
  if not coalesce(v_plan_active, true) then raise exception 'PLAN_INACTIVE'; end if;
  v_decided_at := clock_timestamp();
  if v_existing.id is not null and core_private.subscription_has_pending_refund(v_existing.id) then
    return jsonb_build_object('ok',false,'code','SERVICE_PERIOD_REFUND_PENDING');
  end if;
  if v_existing.funding_source='voucher' and core_private.service_period_financial_state(v_existing.current_service_period_event_id)<>'refunded' and coalesce((select period_end from public.subscription_billing_events where id=v_existing.current_service_period_event_id and voucher_redemption_id is not null),v_existing.current_period_end,'infinity'::timestamptz)>v_decided_at then
    return jsonb_build_object('ok',false,'code','SERVICE_PERIOD_ACTIVE');
  end if;
  -- Profile row is locked: count the actual weight delta on voucher/cash tier changes too.
  if public.mentor_cap_used(v_mentor) - (case when v_existing.status='active' then public.subscription_cap_weight(v_existing.plan_tier) else 0 end)
     + public.subscription_cap_weight(v_plan_tier) > public.mentor_cap_limit(v_mentor) then raise exception 'MENTOR_CAP_EXCEEDED'; end if;
  v_reactivated := exists (select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor);
  begin
    insert into public.subscriptions (student_id, mentor_id, plan_id, plan_tier, status, payment_id,
      started_at, current_period_start, current_period_end, next_billing_at, billing_cycle, cancel_at_period_end, last_payment_id, funding_source)
    values (v_student, v_mentor, p_plan_id, v_plan_tier, 'active', p_payment_id,
      now(), now(), ((now() at time zone 'Asia/Seoul' + interval '1 month') at time zone 'Asia/Seoul'), ((now() at time zone 'Asia/Seoul' + interval '1 month') at time zone 'Asia/Seoul'), 'monthly', false, p_payment_id, 'cash')
    on conflict (student_id, mentor_id) do update set
      plan_id=excluded.plan_id, plan_tier=excluded.plan_tier, status='active', payment_id=excluded.payment_id,
      last_payment_id=excluded.last_payment_id, funding_source='cash', started_at=coalesce(public.subscriptions.started_at, now()),
      current_period_start=now(), current_period_end=((now() at time zone 'Asia/Seoul' + interval '1 month') at time zone 'Asia/Seoul'), next_billing_at=((now() at time zone 'Asia/Seoul' + interval '1 month') at time zone 'Asia/Seoul'),
      cancel_at_period_end=false, cancel_requested_at=null, canceled_at=null, expired_at=null, grace_until=null,
      last_renewed_at=now(), updated_at=now()
    returning id into v_sub_id;
    select user_id, delta_cents, reason, ref_type, ref_id into v_l_user, v_l_delta, v_l_reason, v_l_reftype, v_l_refid
      from public.cash_ledger where idempotency_key = 'sub_debit_' || p_payment_id::text;
    if v_l_user is not null and (v_l_user <> v_student or v_l_refid is distinct from v_sub_id
       or coalesce(v_l_reftype,'') <> 'subscriptions' or coalesce(v_l_reason,'') <> 'subscription_payment' or v_l_delta <> -v_amount_cents) then
      raise exception 'LEDGER_FIELD_MISMATCH';
    end if;
    perform public.record_subscription_cash_debit(v_student, v_sub_id, p_payment_id, v_amount_cents::bigint);
    update public.payments set status='succeeded', plan_id=p_plan_id,
      metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object('planId',p_plan_id::text,'subscription_id',v_sub_id::text),
      updated_at=now() where id=p_payment_id;
  exception when others then
    get stacked diagnostics v_errcode = returned_sqlstate;
    v_err := sqlerrm;
  end;
  if v_err is not null then
    if v_err like '%CASH_INSUFFICIENT%' then return jsonb_build_object('ok',false,'code','CASH_INSUFFICIENT'); end if;
    insert into public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      values (p_payment_id, v_sub_id, case when v_err like '%LEDGER_FIELD_MISMATCH%' then 'LEDGER_FIELD_MISMATCH' else 'FINANCIAL_WRITE_ERROR' end, 'cash checkout transaction failed') returning id into v_anom;
    return jsonb_build_object('ok',false,'code', case when v_err like '%LEDGER_FIELD_MISMATCH%' then 'LEDGER_FIELD_MISMATCH' else 'FINANCIAL_WRITE_ERROR' end, 'sqlstate',v_errcode,'anomaly_id',v_anom);
  end if;
  return jsonb_build_object('ok',true,'subscription_id',v_sub_id,'payment_status','succeeded','amount_cents',v_amount_cents,'reactivated',v_reactivated);
end; $function$;

CREATE OR REPLACE FUNCTION core_private.subscription_checkout_confirm_impl(p_payment_id uuid, p_plan_id uuid, p_expected_amount_cents integer, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_succeeded    constant text[] := array['succeeded','paid','success','complete','captured'];
  -- 정본 confirm_subscription_checkout raise 17종(§9.8 — 동명 envelope 변환)
  v_canon_raises constant text[] := array[
    'PAYMENT_NOT_FOUND','PAYMENT_NO_USER','PAYMENT_NO_MENTOR','PAYMENT_KIND_INVALID',
    'PLAN_NOT_FOUND','PLAN_MENTOR_MISMATCH','PLAN_AMOUNT_INVALID',
    'PAYMENT_PROCESSING','PAYMENT_NOT_PENDING','PAYMENT_STATE_UNEXPECTED','PAYMENT_STALE',
    'ACCOUNT_BANNED','ACCOUNT_SUSPENDED',
    'MENTOR_NOT_OPEN_FOR_SUBSCRIPTIONS','MENTOR_NOT_APPROVED','PLAN_INACTIVE','MENTOR_CAP_EXCEEDED'];
  p_rec          record;      -- P = 이번 호출 payment
  v_sub          record;      -- 잠근 subscription
  v_led          record;      -- P 자신의 sub_debit_ 원장 행
  v_c            record;      -- C = subscription.last_payment_id 가 가리키는 payment
  v_room         record;
  v_intent       bigint;      -- 결제 시점 불변 동의 금액 = payments.amount × 100
  v_plan_amount  integer;
  v_anom         uuid;
  v_canon        jsonb;
  v_roomres      jsonb;
  v_room_id      uuid;
  v_sub_id       uuid;
  v_room_found   boolean := false;
  v_room_new_sub uuid;        -- Phase 2 보정 후보(subscription_id)
  v_room_new_pay uuid;        -- Phase 2 보정 후보(payment_id)
  v_room_dirty   boolean := false;
  v_pair_student uuid; v_pair_mentor uuid; v_old_event uuid;
BEGIN
  IF p_payment_id IS NULL OR p_plan_id IS NULL OR p_expected_amount_cents IS NULL THEN
    RAISE EXCEPTION 'p_payment_id, p_plan_id, p_expected_amount_cents are required';
  END IF;

  SELECT user_id,mentor_id INTO v_pair_student,v_pair_mentor FROM public.payments WHERE id=p_payment_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','PAYMENT_NOT_FOUND'); END IF;
  PERFORM pg_advisory_xact_lock(hashtext(v_pair_student::text),hashtext(v_pair_mentor::text));
  -- 1) payments FOR UPDATE — §12.2/[C3]: 레거시와 동일하게 payments 를 먼저 잠근다
  SELECT p.id, p.user_id, p.mentor_id, p.status, p.kind, p.amount, p.currency, p.plan_id
    INTO p_rec
    FROM public.payments p WHERE p.id = p_payment_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PAYMENT_NOT_FOUND');
  END IF;
  IF p_rec.user_id IS DISTINCT FROM v_pair_student OR p_rec.mentor_id IS DISTINCT FROM v_pair_mentor THEN
    RAISE EXCEPTION 'PAYMENT_PARTY_CHANGED' USING ERRCODE='40001'; END IF;
  IF p_rec.user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PAYMENT_NO_USER');
  END IF;
  IF p_rec.mentor_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PAYMENT_NO_MENTOR');
  END IF;
  -- 결제 시점 불변 동의 금액 검증(§7 F12 — 구현 결정: 사전 동명 재사용, anomaly 미기록)
  IF p_rec.kind IS DISTINCT FROM 'subscription' THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PAYMENT_KIND_INVALID');
  END IF;
  IF p_rec.currency IS DISTINCT FROM 'KRW'
     OR p_rec.amount IS NULL OR p_rec.amount <= 0 OR p_rec.amount <> trunc(p_rec.amount) THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PAYMENT_STATE_UNEXPECTED');
  END IF;
  v_intent := (p_rec.amount * 100)::bigint;

  -- 2) 재생 판정 — succeeded 계열이면 재생 계약(Phase 1/2)으로 분기(정본 재호출 금지)
  IF p_rec.status = ANY(v_succeeded) THEN
    -- ── Phase 1: 검증 전용 (business-state 쓰기 금지 · anomaly INSERT 만 허용) ──
    -- 1·2. subscription 행 확인·잠금 (최신 결제 정본은 오직 last_payment_id — 추론 금지)
    SELECT s.id, s.student_id, s.mentor_id, s.last_payment_id, s.funding_source, s.current_service_period_event_id
      INTO v_sub
      FROM public.subscriptions s
     WHERE s.student_id = p_rec.user_id AND s.mentor_id = p_rec.mentor_id
     FOR UPDATE;
    IF NOT FOUND THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, NULL, 'SUCCEEDED_NO_SUBSCRIPTION', 'F12 replay: succeeded payment without subscription')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUCCEEDED_NO_SUBSCRIPTION', 'anomaly_id', v_anom);
    END IF;
    -- 3. P 자신의 원장 행 확인
    SELECT l.user_id, l.delta_cents, l.reason, l.ref_type, l.ref_id
      INTO v_led
      FROM public.cash_ledger l
     WHERE l.idempotency_key = 'sub_debit_' || p_payment_id::text;
    IF NOT FOUND THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, v_sub.id, 'SUCCEEDED_NO_LEDGER', 'F12 replay: succeeded payment without ledger debit')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUCCEEDED_NO_LEDGER', 'anomaly_id', v_anom);
    END IF;
    -- 4. P 의 payment–plan 결속 (필수 관계 — NULL 은 일치가 아니라 명시 거부)
    IF p_rec.plan_id IS NULL OR p_rec.plan_id <> p_plan_id THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)
      VALUES (p_payment_id, v_sub.id, 'PLAN_BINDING_MISMATCH', 'F12 replay: payments.plan_id <> p_plan_id',
              jsonb_build_object('plan_id', p_plan_id), jsonb_build_object('plan_id', p_rec.plan_id))
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PLAN_BINDING_MISMATCH', 'anomaly_id', v_anom);
    END IF;
    -- 5. P 의 payment–subscription 당사자 결속
    IF p_rec.user_id <> v_sub.student_id OR p_rec.mentor_id <> v_sub.mentor_id THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, v_sub.id, 'PARTY_BINDING_MISMATCH', 'F12 replay: P party mismatch')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PARTY_BINDING_MISMATCH', 'anomaly_id', v_anom);
    END IF;
    -- 6. ledger–subscription 결속 (필수 관계 — NULL 명시 거부)
    IF v_led.user_id IS NULL OR v_led.user_id <> p_rec.user_id
       OR v_led.ref_id IS NULL OR v_led.ref_id <> v_sub.id THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)
      VALUES (p_payment_id, v_sub.id, 'LEDGER_BINDING_MISMATCH', 'F12 replay: ledger user/ref binding mismatch',
              jsonb_build_object('user_id', p_rec.user_id, 'ref_id', v_sub.id),
              jsonb_build_object('user_id', v_led.user_id, 'ref_id', v_led.ref_id))
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'LEDGER_BINDING_MISMATCH', 'anomaly_id', v_anom);
    END IF;
    -- 7. 원장 필드값 대조 — 기준은 결제 시점 불변 동의 금액(payments.amount×100).
    --    현재 플랜 가격을 읽지 않는다(가격 변경 후 정당한 재시도 오탐 금지 — T-CONC-09).
    IF v_led.delta_cents IS DISTINCT FROM -v_intent
       OR coalesce(v_led.reason, '') <> 'subscription_payment'
       OR coalesce(v_led.ref_type, '') <> 'subscriptions' THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)
      VALUES (p_payment_id, v_sub.id, 'LEDGER_FIELD_MISMATCH', 'F12 replay: ledger field mismatch vs intent amount',
              jsonb_build_object('user_id', p_rec.user_id, 'ref_id', v_sub.id, 'ref_type', 'subscriptions',
                                 'reason', 'subscription_payment', 'delta_cents', -v_intent),
              jsonb_build_object('user_id', v_led.user_id, 'ref_id', v_led.ref_id, 'ref_type', v_led.ref_type,
                                 'reason', v_led.reason, 'delta_cents', v_led.delta_cents))
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'LEDGER_FIELD_MISMATCH', 'anomaly_id', v_anom);
    END IF;
    -- A past cash checkout replay during a voucher period returns its immutable
    -- event without replacing current period/room/payment pointers.
    IF v_sub.funding_source='voucher' THEN
      SELECT id INTO v_old_event FROM public.subscription_billing_events
       WHERE payment_id=p_payment_id AND subscription_id=v_sub.id AND event_type='initial';
      IF v_old_event IS NULL THEN RAISE EXCEPTION 'BILLING_EVENT_BINDING_MISMATCH'; END IF;
      PERFORM core_private.record_initial_subscription_billing_event(p_payment_id,v_sub.id,false);
      SELECT id INTO v_room_id FROM public.mentor_student_rooms WHERE student_id=v_sub.student_id AND mentor_id=v_sub.mentor_id AND subscription_id=v_sub.id;
      IF v_room_id IS NULL THEN RETURN jsonb_build_object('ok',false,'code','ROOM_REF_MISMATCH'); END IF;
      RETURN jsonb_build_object('ok',true,'contract_version',1,'idempotent',true,'subscription_id',v_sub.id,
       'payment_status','succeeded','room_id',v_room_id,'billing_event_id',v_old_event);
    END IF;
    -- 8. C = subscription.last_payment_id 유효성 (detail 은 anomaly 에만 — 코드는 1종 고정)
    IF v_sub.last_payment_id IS NULL THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, v_sub.id, 'SUBSCRIPTION_REF_INVALID', 'LAST_PAYMENT_ID_NULL')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUBSCRIPTION_REF_INVALID', 'anomaly_id', v_anom);
    END IF;
    SELECT p2.id, p2.user_id, p2.mentor_id, p2.status
      INTO v_c FROM public.payments p2 WHERE p2.id = v_sub.last_payment_id;
    IF NOT FOUND THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, v_sub.id, 'SUBSCRIPTION_REF_INVALID', 'LAST_PAYMENT_NOT_FOUND')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUBSCRIPTION_REF_INVALID', 'anomaly_id', v_anom);
    END IF;
    IF NOT (v_c.status = ANY(v_succeeded)) THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, v_sub.id, 'SUBSCRIPTION_REF_INVALID', 'LAST_PAYMENT_NOT_SUCCEEDED')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'SUBSCRIPTION_REF_INVALID', 'anomaly_id', v_anom);
    END IF;
    -- C 당사자 불일치는 8단계 PARTY_BINDING_MISMATCH (LEDGER_BINDING 으로 뭉개지 않는다)
    IF v_c.user_id IS NULL OR v_c.user_id <> v_sub.student_id
       OR v_c.mentor_id IS NULL OR v_c.mentor_id <> v_sub.mentor_id THEN
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, v_sub.id, 'PARTY_BINDING_MISMATCH', 'F12 replay: C party mismatch')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PARTY_BINDING_MISMATCH', 'anomaly_id', v_anom);
    END IF;
    -- 9. room 참조 판정 (쓰기 없음 — 보정 예정값 후보만 계산)
    SELECT r.id, r.subscription_id, r.payment_id
      INTO v_room
      FROM public.mentor_student_rooms r
     WHERE r.student_id = v_sub.student_id AND r.mentor_id = v_sub.mentor_id
     FOR UPDATE;
    v_room_found := FOUND;
    IF v_room_found THEN
      IF v_room.subscription_id IS NULL THEN
        v_room_new_sub := v_sub.id; v_room_dirty := true;
      ELSIF v_room.subscription_id <> v_sub.id THEN
        INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)
        VALUES (p_payment_id, v_sub.id, 'ROOM_REF_MISMATCH', 'F12 replay: room.subscription_id conflict',
                jsonb_build_object('subscription_id', v_sub.id),
                jsonb_build_object('subscription_id', v_room.subscription_id))
        RETURNING id INTO v_anom;
        RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROOM_REF_MISMATCH', 'anomaly_id', v_anom);
      ELSE
        v_room_new_sub := v_room.subscription_id;
      END IF;
      IF v_room.payment_id IS NULL THEN
        v_room_new_pay := v_sub.last_payment_id; v_room_dirty := true;                  -- NULL → C 로 복구 후보
      ELSIF v_room.payment_id = v_sub.last_payment_id THEN
        v_room_new_pay := v_room.payment_id;                                            -- C 동일 → 유지
      ELSIF v_room.payment_id = p_payment_id AND p_payment_id <> v_sub.last_payment_id THEN
        v_room_new_pay := v_sub.last_payment_id; v_room_dirty := true;                  -- stale → C 로 교체 후보
      ELSE
        INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail, expected, found)
        VALUES (p_payment_id, v_sub.id, 'ROOM_REF_MISMATCH', 'F12 replay: room.payment_id references third payment',
                jsonb_build_object('payment_id_c', v_sub.last_payment_id, 'payment_id_p', p_payment_id),
                jsonb_build_object('payment_id', v_room.payment_id))
        RETURNING id INTO v_anom;
        RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROOM_REF_MISMATCH', 'anomaly_id', v_anom);
      END IF;
    END IF;

    -- ── Phase 2: 검증 전부 통과 후에만 room 확보·보정 (참조 복구 — 자금 반복 0) ──
    BEGIN
      IF NOT v_room_found THEN
        v_roomres := core_private.ensure_student_mentor_room(
                       v_sub.student_id, v_sub.mentor_id,
                       p_payment_id => v_sub.last_payment_id,
                       p_subscription_id => v_sub.id,
                       p_require_entitlement => false);
        IF NOT coalesce((v_roomres->>'ok')::boolean, false) THEN
          RAISE EXCEPTION 'S2_M9_ROOM_STEP_FAILED';
        END IF;
        v_room_id := (v_roomres->>'room_id')::uuid;
        -- 동시 생성 경합 포함 재확인: NULL 참조만 채운다(F10 은 기존 방 참조를 덮어쓰지 않음)
        UPDATE public.mentor_student_rooms r
           SET subscription_id = coalesce(r.subscription_id, v_sub.id),
               payment_id      = coalesce(r.payment_id, v_sub.last_payment_id)
         WHERE r.id = v_room_id;
      ELSE
        v_room_id := v_room.id;
        IF v_room_dirty THEN
          UPDATE public.mentor_student_rooms r
             SET subscription_id = v_room_new_sub,
                 payment_id      = v_room_new_pay
           WHERE r.id = v_room_id;
        END IF;
      END IF;
      PERFORM core_private.record_initial_subscription_billing_event(p_payment_id, v_sub.id, false);
    EXCEPTION WHEN OTHERS THEN
      IF SQLERRM = 'BILLING_EVENT_BINDING_MISMATCH' THEN RAISE; END IF;
      -- 운영 오류(9단계와 별도): 자금·원장·구독·결제 성공 상태는 건드리지 않고,
      -- room 부분 변경은 이 블록에서 롤백되며, 재시도 가능하다(§7 F12 재생 결과)
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROOM_ENSURE_FAILED');
    END;

    RETURN jsonb_build_object('ok', true, 'contract_version', 1, 'idempotent', true,
                              'subscription_id', v_sub.id, 'payment_status', 'succeeded',
                              'room_id', v_room_id);
  END IF;

  -- ── 최초 실행 경로 ──
  -- 3) advisory (정본과 동일 인자 형식 — 전환기 잠금 순서 일치 [C3])
  PERFORM pg_advisory_xact_lock(hashtext(p_rec.user_id::text), hashtext(p_rec.mentor_id::text));
  PERFORM 1 FROM public.subscriptions WHERE student_id=p_rec.user_id AND mentor_id=p_rec.mentor_id FOR UPDATE;
  PERFORM 1 FROM public.mentor_profiles WHERE user_id=p_rec.mentor_id FOR UPDATE;
  -- 4) mentor_plans FOR UPDATE — 5)~6) 내내 유지되어 TOCTOU 차단(멘토 UPDATE 대기, T-CONC-04)
  SELECT mp.amount_cents INTO v_plan_amount
    FROM public.mentor_plans mp WHERE mp.id = p_plan_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PLAN_NOT_FOUND');
  END IF;
  -- 5) 3자 일치: payments.amount×100 = p_expected_amount_cents = 잠근 amount_cents
  IF v_intent <> p_expected_amount_cents OR v_intent <> v_plan_amount THEN
    RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'PLAN_AMOUNT_CHANGED',
                              'expected_amount_cents', p_expected_amount_cents,
                              'actual_amount_cents', v_plan_amount);
  END IF;
  -- 6)~7) 정본 호출 + 방 확보 — 한 subtransaction: 방 확보 실패 시 자금·원장·구독·
  --       결제 변경 전부 롤백(rev 8 A-2 §3). 정본 raise 는 잡아 동명 envelope 변환.
  BEGIN
    v_canon := core_private.confirm_cash_subscription_payment(p_payment_id, p_plan_id, p_idempotency_key);
    IF NOT coalesce((v_canon->>'ok')::boolean, false) THEN
      -- 정본 envelope 실패(CASH_INSUFFICIENT·anomaly 계열): 금융 변경은 정본 내부에서
      -- 이미 롤백됨 — anomaly 행만 유지한 채 그대로 승격 반환
      RETURN v_canon || jsonb_build_object('contract_version', 1);
    END IF;
    v_sub_id := (v_canon->>'subscription_id')::uuid;
    v_roomres := core_private.ensure_student_mentor_room(
                   p_rec.user_id, p_rec.mentor_id,
                   p_payment_id => p_payment_id,
                   p_subscription_id => v_sub_id,
                   p_require_entitlement => false);
    IF NOT coalesce((v_roomres->>'ok')::boolean, false) THEN
      RAISE EXCEPTION 'S2_M9_ROOM_STEP_FAILED';
    END IF;
    v_room_id := (v_roomres->>'room_id')::uuid;
    -- room 참조 규칙(신규 결제 — §7 F12 표): pair 불변 · subscription_id NULL 이면
    -- 채움/다른 값이면 거부 · payment_id 는 현재 결제로 갱신(최신 참조 의미론)
    SELECT r.id, r.subscription_id, r.payment_id INTO v_room
      FROM public.mentor_student_rooms r WHERE r.id = v_room_id FOR UPDATE;
    IF v_room.subscription_id IS NOT NULL AND v_room.subscription_id <> v_sub_id THEN
      RAISE EXCEPTION 'S2_M9_ROOM_REF_CONFLICT';
    END IF;
    UPDATE public.mentor_student_rooms r
       SET subscription_id = coalesce(r.subscription_id, v_sub_id),
           payment_id      = p_payment_id
     WHERE r.id = v_room_id;
    PERFORM core_private.record_initial_subscription_billing_event(p_payment_id, v_sub_id, true);
  EXCEPTION WHEN OTHERS THEN
    IF sqlerrm LIKE '%S2_M9_ROOM_REF_CONFLICT%' THEN
      -- 초기 경로 room 참조 충돌 = 거부(§7 F12 표) — 자금 변경은 위 블록에서 전부 롤백됨
      INSERT INTO public.subscription_checkout_anomalies(payment_id, subscription_id, code, detail)
      VALUES (p_payment_id, v_sub_id, 'ROOM_REF_MISMATCH', 'F12 initial: room.subscription_id conflict')
      RETURNING id INTO v_anom;
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROOM_REF_MISMATCH', 'anomaly_id', v_anom);
    ELSIF sqlerrm LIKE '%S2_M9_ROOM_STEP_FAILED%' THEN
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', 'ROOM_ENSURE_FAILED');
    ELSIF sqlerrm = ANY(v_canon_raises) THEN
      RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', sqlerrm);
    ELSE
      RAISE;  -- 사전 밖 예외는 그대로 전파(§8.2)
    END IF;
  END;

  -- 8) 성공: 기존 정본 반환 + contract_version + room_id (§8.3 F12 행)
  RETURN v_canon || jsonb_build_object('contract_version', 1, 'room_id', v_room_id);
END $function$
;

CREATE OR REPLACE FUNCTION public.confirm_subscription_checkout(p_payment_id uuid,p_plan_id uuid,p_idempotency_key text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_amount bigint;
BEGIN
 SELECT (amount*100)::bigint INTO v_amount FROM public.payments WHERE id=p_payment_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PAYMENT_NOT_FOUND'; END IF;
 IF v_amount IS NULL OR v_amount<=0 OR v_amount>2147483647 THEN RAISE EXCEPTION 'PLAN_AMOUNT_INVALID'; END IF;
 RETURN core_private.subscription_checkout_confirm_impl(p_payment_id,p_plan_id,v_amount::integer,p_idempotency_key);
END $$;
REVOKE ALL ON FUNCTION core_private.confirm_cash_subscription_payment(uuid,uuid,text),
 core_private.subscription_checkout_confirm_impl(uuid,uuid,integer,text),
 core_private.record_initial_subscription_billing_event(uuid,uuid,boolean) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.confirm_subscription_checkout(uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.confirm_subscription_checkout(uuid,uuid,text) TO service_role;

-- SOURCE supabase/integration_fragments/track_a/02_voucher_core.sql
CREATE OR REPLACE FUNCTION public.issue_voucher_entitlement(p_campaign_id uuid,p_external_entitlement_hmac text,p_code_hmac text,p_hmac_key_version text,p_ciphertext text,p_nonce text,p_auth_tag text,p_encryption_key_version text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_e public.voucher_entitlements%ROWTYPE; v_new boolean := false;
BEGIN
 IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'VOUCHER_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_external_entitlement_hmac IS NULL OR p_external_entitlement_hmac !~ '^[0-9a-f]{64}$' OR p_code_hmac IS NULL OR p_code_hmac !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'VOUCHER_INPUT_INVALID'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('voucher_issue:'||p_external_entitlement_hmac,0));
 SELECT * INTO v_e FROM public.voucher_entitlements WHERE external_entitlement_hmac=p_external_entitlement_hmac FOR UPDATE;
 IF FOUND THEN
  IF v_e.campaign_id IS DISTINCT FROM p_campaign_id THEN RAISE EXCEPTION 'VOUCHER_ENTITLEMENT_CONFLICT'; END IF;
 ELSE
  PERFORM 1 FROM public.voucher_campaigns WHERE id=p_campaign_id AND status IN ('active','disabled') FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'VOUCHER_CAMPAIGN_UNAVAILABLE'; END IF;
  INSERT INTO public.voucher_entitlements(campaign_id,external_entitlement_hmac,code_hmac,hmac_key_version)
   VALUES(p_campaign_id,p_external_entitlement_hmac,p_code_hmac,p_hmac_key_version) RETURNING * INTO v_e;
  INSERT INTO public.voucher_delivery_envelopes(entitlement_id,ciphertext,nonce,auth_tag,encryption_key_version)
   VALUES(v_e.id,p_ciphertext,p_nonce,p_auth_tag,p_encryption_key_version);
  v_new:=true;
 END IF;
 RETURN jsonb_build_object('ok',true,'entitlement_id',v_e.id,'idempotent',NOT v_new,'envelope',(SELECT to_jsonb(d)-'entitlement_id'-'created_at' FROM public.voucher_delivery_envelopes d WHERE entitlement_id=v_e.id));
END $$;

CREATE OR REPLACE FUNCTION public.preview_voucher(p_student_id uuid,p_mentor_id uuid,p_code_hmac text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE v_c public.voucher_campaigns%ROWTYPE;
BEGIN
 IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'VOUCHER_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT c.* INTO v_c FROM public.voucher_entitlements e JOIN public.voucher_campaigns c ON c.id=e.campaign_id WHERE e.code_hmac=p_code_hmac AND e.status='issued' AND c.status='active';
 IF NOT FOUND OR now()<v_c.redeem_start OR now()>=v_c.redeem_end THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_UNAVAILABLE'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=p_student_id AND role='student' AND status='active') OR NOT public.individual_question_user_is_approved_mentor(p_mentor_id) THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_PARTY_UNAVAILABLE'); END IF;
 RETURN jsonb_build_object('ok',true,'gross_cents',v_c.gross_cents,'plan_tier',v_c.plan_tier,'weekly_question_limit',v_c.weekly_question_limit,'service_end',v_c.service_end);
END $$;

CREATE OR REPLACE FUNCTION public.redeem_voucher(p_student_id uuid,p_mentor_id uuid,p_code_hmac text,p_request_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE
 v_e public.voucher_entitlements%ROWTYPE; v_c public.voucher_campaigns%ROWTYPE; v_s public.subscriptions%ROWTYPE;
 v_r public.voucher_redemptions%ROWTYPE; v_p public.mentor_plans%ROWTYPE; v_m public.mentor_profiles%ROWTYPE;
 v_u public.users%ROWTYPE; v_mentor_status text; v_constraint text; v_decided_at timestamptz; v_event uuid; v_room uuid; v_sub uuid;
BEGIN
 IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'VOUCHER_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_student_id IS NULL OR p_mentor_id IS NULL OR p_request_id IS NULL OR p_student_id=p_mentor_id OR p_code_hmac IS NULL OR p_code_hmac !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'VOUCHER_INPUT_INVALID'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(p_student_id::text),hashtext(p_mentor_id::text));
 SELECT * INTO v_e FROM public.voucher_entitlements WHERE code_hmac=p_code_hmac FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_UNAVAILABLE'); END IF;
 -- Request replay never restores mutable subscription or room references.
 SELECT * INTO v_r FROM public.voucher_redemptions WHERE student_id=p_student_id AND request_id=p_request_id;
 IF FOUND THEN
  IF v_r.entitlement_id<>v_e.id OR v_r.mentor_id<>p_mentor_id THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_REQUEST_CONFLICT'); END IF;
  SELECT id INTO v_event FROM public.subscription_billing_events WHERE voucher_redemption_id=v_r.id;
  IF v_event IS NULL THEN RAISE EXCEPTION 'VOUCHER_STATE_INCONSISTENT'; END IF;
  SELECT id INTO v_room FROM public.mentor_student_rooms WHERE student_id=p_student_id AND mentor_id=p_mentor_id;
  RETURN jsonb_build_object('ok',true,'idempotent',true,'subscription_id',v_r.subscription_id,'redemption_id',v_r.id,'billing_event_id',v_event,'room_id',v_room);
 END IF;
 IF v_e.status<>'issued' THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_UNAVAILABLE'); END IF;
 SELECT * INTO v_c FROM public.voucher_campaigns WHERE id=v_e.campaign_id FOR SHARE;
 SELECT * INTO v_s FROM public.subscriptions WHERE student_id=p_student_id AND mentor_id=p_mentor_id FOR UPDATE;
 SELECT * INTO v_m FROM public.mentor_profiles WHERE user_id=p_mentor_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_PARTY_UNAVAILABLE'); END IF;
 SELECT * INTO v_p FROM public.mentor_plans WHERE mentor_id=p_mentor_id AND plan_tier='standard' AND is_active FOR SHARE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_PLAN_UNAVAILABLE'); END IF;
 SELECT * INTO v_u FROM public.users WHERE id=p_student_id FOR UPDATE;
 IF NOT FOUND OR v_u.role<>'student' THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_PARTY_UNAVAILABLE'); END IF;
 SELECT status INTO v_mentor_status FROM public.users WHERE id=p_mentor_id FOR SHARE;
 SELECT * INTO v_m FROM public.mentor_profiles WHERE user_id=p_mentor_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_PARTY_UNAVAILABLE'); END IF;
 -- All approval locks acquired; exactly one wall-clock sample after waits.
 v_decided_at := clock_timestamp();
 IF v_c.status<>'active' OR v_decided_at<v_c.redeem_start OR v_decided_at>=v_c.redeem_end THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_WINDOW_CLOSED'); END IF;
 IF v_u.status<>'active' OR v_mentor_status IS DISTINCT FROM 'active' OR NOT v_m.is_open_for_subscriptions OR v_m.activity_status<>'active' OR NOT public.individual_question_user_is_approved_mentor(p_mentor_id) THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_PARTY_UNAVAILABLE'); END IF;
 IF v_s.id IS NOT NULL AND core_private.subscription_has_pending_refund(v_s.id) THEN RETURN jsonb_build_object('ok',false,'code','SERVICE_PERIOD_REFUND_PENDING'); END IF;
 IF v_s.current_service_period_event_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.subscription_billing_events WHERE id=v_s.current_service_period_event_id AND status='succeeded' AND core_private.service_period_effective_end(id)>v_decided_at) AND core_private.service_period_financial_state(v_s.current_service_period_event_id)<>'refunded' THEN RETURN jsonb_build_object('ok',false,'code','SERVICE_PERIOD_ACTIVE'); END IF;
 IF v_s.id IS NOT NULL AND (v_s.status IN ('active','past_due','cancel_scheduled') AND (v_s.current_period_end IS NULL OR v_s.current_period_end>v_decided_at)) THEN RETURN jsonb_build_object('ok',false,'code','SERVICE_PERIOD_ACTIVE'); END IF;
 IF public.mentor_cap_used(p_mentor_id) - (CASE WHEN v_s.status='active' THEN public.subscription_cap_weight(v_s.plan_tier) ELSE 0 END) + public.subscription_cap_weight('standard') > public.mentor_cap_limit(p_mentor_id) THEN RETURN jsonb_build_object('ok',false,'code','MENTOR_CAP_EXCEEDED'); END IF;
 -- Every write below belongs to this transaction; any exception rolls everything back.
 INSERT INTO public.subscriptions(student_id,mentor_id,plan_id,plan_tier,status,payment_id,last_payment_id,funding_source,started_at,current_period_start,current_period_end,next_billing_at,billing_cycle,cancel_at_period_end)
 VALUES(p_student_id,p_mentor_id,v_p.id,'standard','active',NULL,NULL,'voucher',v_decided_at,v_decided_at,v_c.service_end,NULL,'fixed',true)
 ON CONFLICT(student_id,mentor_id) DO UPDATE SET plan_id=excluded.plan_id,plan_tier='standard',status='active',payment_id=NULL,last_payment_id=NULL,funding_source='voucher',current_period_start=v_decided_at,current_period_end=v_c.service_end,next_billing_at=NULL,billing_cycle='fixed',cancel_at_period_end=true,cancel_requested_at=NULL,canceled_at=NULL,expired_at=NULL,grace_until=NULL
 RETURNING id INTO v_sub;
 INSERT INTO public.voucher_redemptions(entitlement_id,subscription_id,student_id,mentor_id,request_id,service_start,service_end,decided_at)
 VALUES(v_e.id,v_sub,p_student_id,p_mentor_id,p_request_id,v_decided_at,v_c.service_end,v_decided_at) RETURNING * INTO v_r;
 INSERT INTO public.subscription_billing_events(subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,amount_cents,plan_tier,plan_id,idempotency_key,processed_at,funding_source,voucher_redemption_id)
 VALUES(v_sub,p_student_id,p_mentor_id,'initial','succeeded',v_decided_at,v_c.service_end,v_decided_at,v_c.gross_cents,'standard',v_p.id,'voucher_initial:'||v_r.id::text,v_decided_at,'voucher',v_r.id) RETURNING id INTO v_event;
 UPDATE public.subscriptions SET current_service_period_event_id=v_event,last_billing_event_id=v_event WHERE id=v_sub;
 UPDATE public.voucher_entitlements SET status='redeemed' WHERE id=v_e.id;
 INSERT INTO public.mentor_student_rooms(student_id,mentor_id,subscription_id,payment_id)
 VALUES(p_student_id,p_mentor_id,v_sub,NULL) ON CONFLICT(student_id,mentor_id) DO UPDATE SET subscription_id=excluded.subscription_id,payment_id=NULL WHERE public.mentor_student_rooms.subscription_id IS NULL OR public.mentor_student_rooms.subscription_id=v_sub RETURNING id INTO v_room;
 IF v_room IS NULL THEN RAISE EXCEPTION 'VOUCHER_ROOM_CONFLICT'; END IF;
 RETURN jsonb_build_object('ok',true,'idempotent',false,'subscription_id',v_sub,'redemption_id',v_r.id,'billing_event_id',v_event,'room_id',v_room);
EXCEPTION WHEN unique_violation THEN
 GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
 IF v_constraint='voucher_redemptions_student_id_request_id_key' THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_REQUEST_CONFLICT'); END IF;
 RAISE;
END $$;
REVOKE ALL ON FUNCTION public.issue_voucher_entitlement(uuid,text,text,text,text,text,text,text),public.preview_voucher(uuid,uuid,text),public.redeem_voucher(uuid,uuid,text,uuid) FROM PUBLIC,anon,authenticated;

-- SOURCE supabase/integration_fragments/track_a/06_voucher_expiry.sql
-- Voucher terminal event preserves the original service event/redemption for completion-only Q&A.
CREATE OR REPLACE FUNCTION public.expire_voucher_service_period(p_subscription_id uuid,p_expected_event_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE s public.subscriptions%ROWTYPE; e public.subscription_billing_events%ROWTYPE;
 r public.voucher_redemptions%ROWTYPE; v_student uuid; v_mentor uuid; v_entitlement uuid;
 v_decided_at timestamptz; v_terminal uuid; v_key text;
BEGIN
 IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'VOUCHER_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_subscription_id IS NULL OR p_expected_event_id IS NULL THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_EXPIRY_INPUT_INVALID'); END IF;
 SELECT student_id,mentor_id INTO v_student,v_mentor FROM public.subscriptions WHERE id=p_subscription_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','SUBSCRIPTION_NOT_FOUND'); END IF;
 PERFORM pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));
 SELECT vr.entitlement_id INTO v_entitlement FROM public.subscription_billing_events be JOIN public.voucher_redemptions vr ON vr.id=be.voucher_redemption_id WHERE be.id=p_expected_event_id AND be.subscription_id=p_subscription_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_EXPIRY_STATE_CHANGED'); END IF;
 PERFORM 1 FROM public.voucher_entitlements WHERE id=v_entitlement FOR UPDATE;
 SELECT * INTO s FROM public.subscriptions WHERE id=p_subscription_id FOR UPDATE;
 IF s.student_id IS DISTINCT FROM v_student OR s.mentor_id IS DISTINCT FROM v_mentor THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_EXPIRY_STATE_CHANGED'); END IF;
 -- Same mentor-cap serialization as checkout/redeem; release seats atomically.
 PERFORM 1 FROM public.mentor_profiles WHERE user_id=v_mentor FOR UPDATE;
 SELECT * INTO e FROM public.subscription_billing_events WHERE id=p_expected_event_id FOR UPDATE;
 SELECT * INTO r FROM public.voucher_redemptions WHERE id=e.voucher_redemption_id FOR UPDATE;
 v_decided_at := clock_timestamp();
 v_key:='voucher_expired:'||p_expected_event_id::text;
 SELECT id INTO v_terminal FROM public.subscription_billing_events WHERE idempotency_key=v_key AND subscription_id=p_subscription_id AND event_type='expired' AND status='succeeded';
 IF FOUND THEN RETURN jsonb_build_object('ok',true,'code','already_succeeded','billing_event_id',v_terminal); END IF;
 IF s.funding_source IS DISTINCT FROM 'voucher' OR s.current_service_period_event_id IS DISTINCT FROM e.id
  OR s.status NOT IN ('active','cancel_scheduled','past_due') OR e.funding_source IS DISTINCT FROM 'voucher'
  OR e.status<>'succeeded' OR e.subscription_id<>s.id OR e.student_id<>s.student_id OR e.mentor_id<>s.mentor_id
  OR r.id IS NULL OR r.entitlement_id<>v_entitlement OR r.service_end IS DISTINCT FROM e.period_end
  OR e.period_end IS NULL OR v_decided_at<e.period_end THEN RETURN jsonb_build_object('ok',false,'code','VOUCHER_EXPIRY_STATE_CHANGED'); END IF;
 INSERT INTO public.subscription_billing_events(subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,plan_tier,plan_id,idempotency_key,processed_at)
 VALUES(s.id,s.student_id,s.mentor_id,'expired','succeeded',e.period_start,e.period_end,v_decided_at,e.plan_tier,e.plan_id,v_key,v_decided_at) RETURNING id INTO v_terminal;
 -- Existing expired-status trigger enqueues notification within this transaction.
 UPDATE public.subscriptions SET status='expired',expired_at=v_decided_at,next_billing_at=NULL,current_service_period_event_id=NULL,last_billing_event_id=v_terminal,updated_at=v_decided_at WHERE id=s.id;
 RETURN jsonb_build_object('ok',true,'code','succeeded','billing_event_id',v_terminal);
END $$;
REVOKE ALL ON FUNCTION public.expire_voucher_service_period(uuid,uuid) FROM PUBLIC,anon,authenticated;

-- SOURCE supabase/integration_fragments/30_renewal.sql
-- PR138 DB pricing, notice-price guard and replay binding. Legacy precision is explicitly scoped.
CREATE OR REPLACE FUNCTION core_private.process_subscription_renewal_impl(p_subscription_id uuid, p_period_end timestamp with time zone, p_idempotency_key text, p_processed_at timestamp with time zone DEFAULT now(), p_legacy_millisecond boolean DEFAULT false)
 RETURNS TABLE(ok boolean, code text, message text, billing_event_id uuid, ledger_id uuid, next_period_start timestamp with time zone, next_period_end timestamp with time zone, wallet_balance_cents bigint, attempt_count integer)
 LANGUAGE plpgsql
 SECURITY INVOKER
 SET search_path TO ''
AS $function$
declare
 s public.subscriptions%rowtype; p public.mentor_plans%rowtype;
 e public.subscription_billing_events%rowtype; l public.cash_ledger%rowtype;
 v_student uuid; v_mentor uuid; v_amount bigint; v_balance bigint; v_end timestamptz;
 v_key text; v_notice public.subscription_billing_events%rowtype;
begin
 if p_subscription_id is null or p_period_end is null or p_processed_at is null then
   return query select false,'invalid_subscription'::text,'subscription, period and time are required'::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;
 end if;
 v_key := 'sub_renewal:'||p_subscription_id::text||':'||to_char(p_period_end at time zone 'UTC','YYYY-MM-DD');
 if p_idempotency_key is distinct from v_key or char_length(p_idempotency_key)>128 then
   return query select false,'invalid_idempotency_key'::text,'key must identify this subscription period'::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;
 end if;
 -- Match checkout's pair mutex before row locks. No stale client snapshot decides eligibility.
 select student_id,mentor_id into v_student,v_mentor from public.subscriptions where id=p_subscription_id;
 if v_student is null then
   return query select false,'not_found'::text,'subscription not found'::text,null::uuid,null::uuid,null::timestamptz,null::timestamptz,null::bigint,0; return;
 end if;
 perform pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));
 select * into s from public.subscriptions where id=p_subscription_id for update;
 if s.id is null or s.student_id is distinct from v_student or s.mentor_id is distinct from v_mentor then
   raise exception 'SUBSCRIPTION_BINDING_MISMATCH';
 end if;
 perform 1 from public.mentor_profiles where user_id=s.mentor_id for update;
 select * into e from public.subscription_billing_events where idempotency_key=v_key for update;
 -- Older web normalizes timestamps through JS Date (millisecond precision). Bind
 -- to the locked subscription, or the original event on replay, without rounding
 -- stored financial periods. A different millisecond is still a stale request.
 if p_legacy_millisecond then
 if e.id is not null and e.subscription_id=s.id
    and date_trunc('milliseconds',e.period_start)=date_trunc('milliseconds',p_period_end) then
  p_period_end := e.period_start;
 elsif e.id is null
    and date_trunc('milliseconds',s.current_period_end)=date_trunc('milliseconds',p_period_end) then
  p_period_end := s.current_period_end;
 end if;
 end if;
 if e.id is not null then
   if e.subscription_id is distinct from s.id or e.student_id is distinct from s.student_id
      or e.mentor_id is distinct from s.mentor_id or e.period_start is distinct from p_period_end
      or e.event_type not in ('renewal','renewal_failed') then
     raise exception 'BILLING_EVENT_BINDING_MISMATCH';
   end if;
   if e.status='succeeded' then
     select * into l from public.cash_ledger where id=e.ledger_id;
     if l.id is null or l.delta_cents is distinct from -e.amount_cents::bigint
        or l.user_id is distinct from s.student_id or l.ref_id is distinct from s.id
        or l.idempotency_key is distinct from v_key or l.reason is distinct from 'subscription_renewal' then
       raise exception 'LEDGER_BINDING_MISMATCH';
     end if;
     return query select true,'already_succeeded'::text,'renewal already processed'::text,e.id,l.id,e.period_start,e.period_end,null::bigint,e.attempt_count; return;
   end if;
   if e.status not in ('failed','skipped') then
     return query select false,'already_processing'::text,'renewal is already processing'::text,e.id,e.ledger_id,e.period_start,e.period_end,null::bigint,e.attempt_count; return;
   end if;
 end if;
 if s.funding_source is not null and s.funding_source<>'cash' then
   return query select false,'not_cash_subscription'::text,'cash renewal is unavailable for this funding source'::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,0; return;
 end if;
 if not core_private.current_cash_service_period_valid(s.id) then
   return query select false,'SERVICE_PERIOD_FUNDING_UNRESOLVED'::text,'service period funding must be verified'::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,0; return;
 end if;
 if s.status not in ('active','past_due') or s.cancel_at_period_end
    or (s.status='past_due' and s.grace_until is not null and s.grace_until<=p_processed_at)
    or s.current_period_end is distinct from p_period_end or s.next_billing_at is null
    or s.next_billing_at>p_processed_at or p_period_end>p_processed_at then
   return query select false,'not_renewal_eligible'::text,'subscription state or period changed'::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;
 end if;
 select * into p from public.mentor_plans where id=s.plan_id for share;
 if p.id is null or p.mentor_id is distinct from s.mentor_id or p.plan_tier is distinct from s.plan_tier
    or p.amount_cents is null or p.amount_cents<=0 or p.amount_cents%100<>0 then
   e := core_private.record_subscription_renewal_block(s.id,'price_unavailable',v_key,p_processed_at);
   return query select false,'price_unavailable'::text,'plan price or binding unavailable'::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;
 end if;
 -- is_active controls NEW subscriptions only. Existing subscriptions may renew.
 v_amount := p.amount_cents;
 select * into v_notice from public.subscription_billing_events
  where idempotency_key='sub_renewal_notice:'||s.id::text||':'||to_char(p_period_end at time zone 'UTC','YYYY-MM-DD');
 if v_notice.id is not null and (v_notice.amount_cents is distinct from v_amount
    or v_notice.plan_id is distinct from p.id or v_notice.plan_tier is distinct from p.plan_tier) then
   e := core_private.record_subscription_renewal_block(s.id,'price_changed_since_notice',v_key,p_processed_at);
   return query select false,'price_changed_since_notice'::text,'renewal price differs from the sent notice'::text,e.id,null::uuid,s.current_period_start,s.current_period_end,null::bigint,coalesce(e.attempt_count,0); return;
 end if;
 if exists(select 1 from public.cash_ledger where idempotency_key=v_key) then
   raise exception 'LEDGER_WITHOUT_SUCCEEDED_EVENT';
 end if;
 v_end := ((p_period_end at time zone 'Asia/Seoul' + interval '1 month') at time zone 'Asia/Seoul');
 if e.id is null then
   insert into public.subscription_billing_events
    (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,
     amount_cents,plan_tier,plan_id,idempotency_key,attempt_count,created_at,funding_source)
   values(s.id,s.student_id,s.mentor_id,'renewal','processing',p_period_end,v_end,p_processed_at,
          v_amount,p.plan_tier,p.id,v_key,1,p_processed_at,'cash') returning * into e;
 else
   update public.subscription_billing_events b set event_type='renewal',status='processing',funding_source='cash',
     amount_cents=v_amount,plan_id=p.id,plan_tier=p.plan_tier,billing_at=p_processed_at,
     attempt_count=b.attempt_count+1,processed_at=null,failure_code=null,failure_message=null
   where b.id=e.id returning b.* into e;
 end if;
 insert into public.cash_wallets(user_id,balance_cents) values(s.student_id,0) on conflict(user_id) do nothing;
 update public.cash_wallets w set balance_cents=w.balance_cents-v_amount
   where w.user_id=s.student_id and w.balance_cents>=v_amount returning w.balance_cents into v_balance;
 if not found then
   update public.subscription_billing_events b set event_type='renewal_failed',status='failed',
     failure_code='insufficient_cash',failure_message='CASH_INSUFFICIENT',processed_at=p_processed_at where b.id=e.id;
   update public.subscriptions set status='past_due',grace_until=coalesce(grace_until,p_processed_at+interval '2 days'),
     updated_at=p_processed_at,last_billing_event_id=e.id where id=s.id;
   return query select false,'insufficient_cash'::text,'CASH_INSUFFICIENT'::text,e.id,null::uuid,p_period_end,v_end,null::bigint,e.attempt_count; return;
 end if;
 insert into public.cash_ledger(user_id,delta_cents,reason,ref_type,ref_id,idempotency_key,created_at)
 values(s.student_id,-v_amount,'subscription_renewal','subscriptions',s.id,v_key,p_processed_at) returning * into l;
 update public.subscription_billing_events b set event_type='renewal',status='succeeded',ledger_id=l.id,
   processed_at=p_processed_at,failure_code=null,failure_message=null where b.id=e.id;
 update public.subscriptions set status='active',funding_source='cash',current_period_start=p_period_end,current_period_end=v_end,
   next_billing_at=v_end,last_renewed_at=p_processed_at,last_billing_event_id=e.id,current_service_period_event_id=e.id,grace_until=null,updated_at=p_processed_at where id=s.id;
 return query select true,'succeeded'::text,'renewal processed'::text,e.id,l.id,p_period_end,v_end,v_balance,e.attempt_count;
end $function$
;

CREATE OR REPLACE FUNCTION public.process_subscription_renewal_v2(p_subscription_id uuid,p_period_end timestamptz,p_idempotency_key text,p_processed_at timestamptz DEFAULT now())
RETURNS TABLE(ok boolean,code text,message text,billing_event_id uuid,ledger_id uuid,next_period_start timestamptz,next_period_end timestamptz,wallet_balance_cents bigint,attempt_count integer) LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT * FROM core_private.process_subscription_renewal_impl(p_subscription_id,p_period_end,p_idempotency_key,p_processed_at,true)
$$;
REVOKE ALL ON FUNCTION public.process_subscription_renewal_v2(uuid,timestamptz,text,timestamptz) FROM PUBLIC,anon,authenticated;
