-- SOURCE supabase/integration_fragments/32_notice_claims.sql
-- The legacy wrapper alone accepts the historical JavaScript millisecond round trip.
CREATE FUNCTION core_private.record_subscription_renewal_notice_impl(
 p_subscription_id uuid,p_period_end timestamptz,p_at timestamptz,p_legacy_millisecond boolean)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE s public.subscriptions%ROWTYPE; p public.mentor_plans%ROWTYPE;
 e public.subscription_billing_events%ROWTYPE; v_key text; v_student uuid; v_mentor uuid;
BEGIN
 IF p_subscription_id IS NULL OR p_period_end IS NULL OR p_at IS NULL THEN RETURN jsonb_build_object('ok',false,'code','not_notice_eligible'); END IF;
 SELECT student_id,mentor_id INTO v_student,v_mentor FROM public.subscriptions WHERE id=p_subscription_id;
 IF v_student IS NULL THEN RETURN jsonb_build_object('ok',false,'code','not_notice_eligible'); END IF;
 PERFORM pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));
 SELECT * INTO s FROM public.subscriptions WHERE id=p_subscription_id FOR UPDATE;
 IF s.student_id IS DISTINCT FROM v_student OR s.mentor_id IS DISTINCT FROM v_mentor THEN RAISE EXCEPTION 'SUBSCRIPTION_BINDING_MISMATCH'; END IF;
 PERFORM 1 FROM public.mentor_profiles WHERE user_id=s.mentor_id FOR UPDATE;
 v_key:='sub_renewal_notice:'||s.id::text||':'||to_char(p_period_end AT TIME ZONE 'UTC','YYYY-MM-DD');
 SELECT * INTO e FROM public.subscription_billing_events WHERE idempotency_key=v_key FOR UPDATE;
 IF p_legacy_millisecond THEN
  IF e.id IS NOT NULL AND date_trunc('milliseconds',e.period_end)=date_trunc('milliseconds',p_period_end) THEN p_period_end:=e.period_end;
  ELSIF e.id IS NULL AND date_trunc('milliseconds',s.current_period_end)=date_trunc('milliseconds',p_period_end) THEN p_period_end:=s.current_period_end; END IF;
 END IF;
 IF e.id IS NOT NULL THEN
  IF ROW(e.subscription_id,e.student_id,e.mentor_id,e.period_end,e.event_type,e.status,e.failure_code)
   IS DISTINCT FROM ROW(s.id,s.student_id,s.mentor_id,p_period_end,'renewal'::text,'skipped'::text,'pre_renewal_notice_sent'::text)
   THEN RAISE EXCEPTION 'BILLING_EVENT_BINDING_MISMATCH'; END IF;
  RETURN jsonb_build_object('ok',true,'code','already','billing_event_id',e.id,'amount_cents',e.amount_cents,
   'plan_id',e.plan_id,'plan_tier',e.plan_tier,'period_end',e.period_end);
 END IF;
 IF s.status<>'active' OR s.cancel_at_period_end OR s.current_period_end IS DISTINCT FROM p_period_end
  OR s.next_billing_at IS NULL OR s.next_billing_at<=p_at THEN RETURN jsonb_build_object('ok',false,'code','not_notice_eligible'); END IF;
 IF NOT core_private.current_cash_service_period_valid(s.id) THEN RETURN jsonb_build_object('ok',false,'code','SERVICE_PERIOD_FUNDING_UNRESOLVED'); END IF;
 SELECT * INTO p FROM public.mentor_plans WHERE id=s.plan_id FOR SHARE;
 IF p.id IS NULL OR p.mentor_id IS DISTINCT FROM s.mentor_id OR p.plan_tier IS DISTINCT FROM s.plan_tier
  OR p.amount_cents IS NULL OR p.amount_cents<=0 OR p.amount_cents%100<>0 THEN RETURN jsonb_build_object('ok',false,'code','price_unavailable'); END IF;
 INSERT INTO public.subscription_billing_events
  (subscription_id,student_id,mentor_id,event_type,status,period_start,period_end,billing_at,amount_cents,plan_tier,plan_id,
   idempotency_key,failure_code,failure_message,attempt_count,created_at,processed_at,funding_source)
 VALUES(s.id,s.student_id,s.mentor_id,'renewal','skipped',s.current_period_start,s.current_period_end,s.next_billing_at,p.amount_cents,p.plan_tier,p.id,
  v_key,'pre_renewal_notice_sent','pre-renewal notice marker',0,p_at,p_at,'cash') RETURNING * INTO e;
 RETURN jsonb_build_object('ok',true,'code','sent','billing_event_id',e.id,'amount_cents',e.amount_cents,
  'plan_id',e.plan_id,'plan_tier',e.plan_tier,'period_end',e.period_end);
END $$;
REVOKE ALL ON FUNCTION core_private.record_subscription_renewal_notice_impl(uuid,timestamptz,timestamptz,boolean) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.record_subscription_renewal_notice(p_subscription_id uuid,p_period_end timestamptz,p_at timestamptz DEFAULT now())
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT core_private.record_subscription_renewal_notice_impl(p_subscription_id,p_period_end,p_at,true)
$$;
CREATE FUNCTION public.record_subscription_renewal_notice_exact(p_subscription_id uuid,p_period_end timestamptz,p_at timestamptz DEFAULT now())
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT core_private.record_subscription_renewal_notice_impl(p_subscription_id,p_period_end,p_at,false)
$$;
REVOKE ALL ON FUNCTION public.record_subscription_renewal_notice(uuid,timestamptz,timestamptz),public.record_subscription_renewal_notice_exact(uuid,timestamptz,timestamptz) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.record_subscription_renewal_notice(uuid,timestamptz,timestamptz),public.record_subscription_renewal_notice_exact(uuid,timestamptz,timestamptz) TO service_role;

CREATE OR REPLACE FUNCTION public.claim_subscription_renewal_batch(p_at timestamptz,p_limit integer DEFAULT 50)
RETURNS SETOF public.subscriptions LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF p_at IS NULL OR p_limit IS NULL OR p_limit<1 OR p_limit>100 THEN RAISE EXCEPTION 'INVALID_BATCH_PARAMETERS'; END IF;
 RETURN QUERY WITH candidates AS (
  SELECT s.id FROM public.subscriptions s WHERE s.next_billing_at<=p_at AND s.status IN ('active','past_due')
   AND (s.funding_source='cash' OR (s.funding_source IS NULL AND core_private.current_cash_service_period_valid(s.id)))
  ORDER BY s.renewal_batch_attempted_at ASC NULLS FIRST,s.next_billing_at,s.id LIMIT p_limit FOR UPDATE SKIP LOCKED
 ) UPDATE public.subscriptions s SET renewal_batch_attempted_at=clock_timestamp() FROM candidates c WHERE s.id=c.id RETURNING s.*;
END $$;
CREATE FUNCTION public.claim_subscription_renewal_notice_batch(p_at timestamptz,p_until timestamptz,p_limit integer DEFAULT 50)
RETURNS SETOF public.subscriptions LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF p_at IS NULL OR p_until IS NULL OR p_until<=p_at OR p_limit IS NULL OR p_limit<1 OR p_limit>100 THEN RAISE EXCEPTION 'INVALID_BATCH_PARAMETERS'; END IF;
 RETURN QUERY WITH candidates AS (
  SELECT s.id FROM public.subscriptions s WHERE s.next_billing_at>p_at AND s.next_billing_at<=p_until
   AND s.status='active' AND NOT s.cancel_at_period_end
   AND (s.funding_source='cash' OR (s.funding_source IS NULL AND core_private.current_cash_service_period_valid(s.id)))
   AND NOT EXISTS(SELECT 1 FROM public.subscription_billing_events e
    WHERE e.subscription_id=s.id AND e.idempotency_key='sub_renewal_notice:'||s.id::text||':'||to_char(s.current_period_end AT TIME ZONE 'UTC','YYYY-MM-DD')
    AND e.period_end=s.current_period_end AND e.status='skipped' AND e.failure_code='pre_renewal_notice_sent')
  ORDER BY s.renewal_notice_attempted_at ASC NULLS FIRST,s.next_billing_at,s.id LIMIT p_limit FOR UPDATE SKIP LOCKED
 ) UPDATE public.subscriptions s SET renewal_notice_attempted_at=clock_timestamp() FROM candidates c WHERE s.id=c.id RETURNING s.*;
END $$;
REVOKE ALL ON FUNCTION public.claim_subscription_renewal_batch(timestamptz,integer),public.claim_subscription_renewal_notice_batch(timestamptz,timestamptz,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_subscription_renewal_batch(timestamptz,integer),public.claim_subscription_renewal_notice_batch(timestamptz,timestamptz,integer) TO service_role;

-- SOURCE supabase/integration_fragments/40_terminal.sql
-- Period identity prevents a delayed terminal retry from closing a later subscription period.
CREATE TABLE public.subscription_terminal_transitions (
 service_period_event_id uuid PRIMARY KEY REFERENCES public.subscription_billing_events(id) ON DELETE RESTRICT,
 subscription_id uuid NOT NULL REFERENCES public.subscriptions(id) ON DELETE RESTRICT,
 terminal_event_id uuid NOT NULL UNIQUE REFERENCES public.subscription_billing_events(id) ON DELETE RESTRICT,
 expected_last_event_id uuid REFERENCES public.subscription_billing_events(id) ON DELETE RESTRICT,
 legacy_request_key text UNIQUE,
 created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.subscription_terminal_transitions ENABLE ROW LEVEL SECURITY;
CREATE INDEX subscription_terminal_transitions_subscription_idx ON public.subscription_terminal_transitions(subscription_id,expected_last_event_id);
REVOKE ALL ON TABLE public.subscription_terminal_transitions FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION core_private.finalize_subscription_terminal_impl(p_subscription_id uuid,p_expected_period_end timestamptz,
 p_expected_last_billing_event_id uuid,p_event_type text,p_processed_at timestamptz,p_legacy_key text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE s public.subscriptions%ROWTYPE; e public.subscription_billing_events%ROWTYPE;
 t public.subscription_terminal_transitions%ROWTYPE; v_student uuid; v_mentor uuid; v_alias text; v_key text;
 v_matching_periods integer; v_expected_period_matches boolean; v_matching_cash integer;
BEGIN
 IF p_subscription_id IS NULL OR p_processed_at IS NULL OR p_event_type IS NULL OR p_event_type NOT IN ('canceled','expired') THEN
  RETURN jsonb_build_object('ok',false,'code','invalid_transition'); END IF;
 SELECT student_id,mentor_id INTO v_student,v_mentor FROM public.subscriptions WHERE id=p_subscription_id;
 IF v_student IS NULL THEN RETURN jsonb_build_object('ok',false,'code','not_found'); END IF;
 PERFORM pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));
 SELECT * INTO s FROM public.subscriptions WHERE id=p_subscription_id FOR UPDATE;
 IF s.student_id IS DISTINCT FROM v_student OR s.mentor_id IS DISTINCT FROM v_mentor THEN RAISE EXCEPTION 'SUBSCRIPTION_BINDING_MISMATCH'; END IF;
 PERFORM 1 FROM public.mentor_profiles WHERE user_id=s.mentor_id FOR UPDATE;
 IF p_legacy_key IS NOT NULL THEN
  -- Look up the historical request before inspecting the current period. A replay never mutates it.
  SELECT b.* INTO e FROM public.subscription_billing_events b
   LEFT JOIN public.subscription_terminal_transitions x ON x.terminal_event_id=b.id
   WHERE x.legacy_request_key=p_legacy_key OR b.idempotency_key=p_legacy_key;
  IF e.id IS NOT NULL THEN
   IF e.subscription_id IS DISTINCT FROM s.id OR e.student_id IS DISTINCT FROM s.student_id OR e.mentor_id IS DISTINCT FROM s.mentor_id
    OR e.event_type IS DISTINCT FROM p_event_type OR e.status<>'succeeded' THEN RAISE EXCEPTION 'BILLING_EVENT_BINDING_MISMATCH'; END IF;
   RETURN jsonb_build_object('ok',true,'code','already_succeeded','billing_event_id',e.id);
  END IF;
  p_expected_period_end:=s.current_period_end;
  p_expected_last_billing_event_id:=s.last_billing_event_id;
 ELSE
  SELECT x.* INTO t FROM public.subscription_terminal_transitions x
   JOIN public.subscription_billing_events b ON b.id=x.terminal_event_id
   WHERE x.subscription_id=s.id AND b.period_end=p_expected_period_end AND b.event_type=p_event_type
    AND (x.expected_last_event_id IS NOT DISTINCT FROM p_expected_last_billing_event_id OR x.terminal_event_id=p_expected_last_billing_event_id);
  IF t.terminal_event_id IS NOT NULL THEN
   SELECT * INTO e FROM public.subscription_billing_events WHERE id=t.terminal_event_id;
   IF e.status<>'succeeded' OR e.student_id IS DISTINCT FROM s.student_id OR e.mentor_id IS DISTINCT FROM s.mentor_id THEN RAISE EXCEPTION 'BILLING_EVENT_BINDING_MISMATCH'; END IF;
   RETURN jsonb_build_object('ok',true,'code','already_succeeded','billing_event_id',e.id);
  END IF;
  -- A terminal committed by PR138 before this delta has no transition sidecar.
  -- Acknowledge that exact completed request without creating a mapping or
  -- touching today's period. A paid-event predecessor must identify a unique
  -- verified period; equal timestamps alone cannot distinguish a rejoin.
  SELECT * INTO e FROM public.subscription_billing_events b
   WHERE b.idempotency_key=CASE p_event_type WHEN 'canceled' THEN 'sub_cancel:' ELSE 'sub_expired:' END
     ||s.id::text||':'||to_char(p_expected_period_end AT TIME ZONE 'UTC','YYYY-MM-DD')
    AND b.period_end=p_expected_period_end;
  IF e.id IS NOT NULL THEN
   IF e.subscription_id IS DISTINCT FROM s.id OR e.student_id IS DISTINCT FROM s.student_id
    OR e.mentor_id IS DISTINCT FROM s.mentor_id OR e.event_type IS DISTINCT FROM p_event_type
    OR e.status<>'succeeded' THEN RAISE EXCEPTION 'BILLING_EVENT_BINDING_MISMATCH'; END IF;
   IF p_expected_last_billing_event_id=e.id THEN
    RETURN jsonb_build_object('ok',true,'code','already_succeeded','billing_event_id',e.id);
   END IF;
   SELECT count(*),coalesce(bool_or(b.id=p_expected_last_billing_event_id),false),
     count(*) FILTER (WHERE f.kind IN ('cash','verified_legacy_cash'))
    INTO v_matching_periods,v_expected_period_matches,v_matching_cash
    FROM public.subscription_billing_events b
    CROSS JOIN LATERAL (SELECT core_private.service_period_funding(b.id) kind OFFSET 0) f
    WHERE b.subscription_id=s.id AND b.student_id=s.student_id AND b.mentor_id=s.mentor_id
     AND b.event_type IN ('initial','renewal') AND f.kind IN ('cash','verified_legacy_cash','pg','voucher')
     AND ((b.period_start=e.period_start AND core_private.service_period_effective_end(b.id)=e.period_end)
      OR (f.kind='verified_legacy_cash' AND b.period_start=date_trunc('milliseconds',b.period_start)
       AND core_private.service_period_effective_end(b.id)=date_trunc('milliseconds',core_private.service_period_effective_end(b.id))
       AND b.period_start=date_trunc('milliseconds',e.period_start)
       AND core_private.service_period_effective_end(b.id)=date_trunc('milliseconds',e.period_end)));
   IF v_matching_periods=1 AND v_expected_period_matches THEN
    RETURN jsonb_build_object('ok',true,'code','already_succeeded','billing_event_id',e.id);
   END IF;
   -- Before grace expiry the recorded last event is normally the unsuccessful
   -- next renewal, not the paid period. It is a predecessor proof only: never
   -- classify this undebited attempt as a paid service period.
   IF v_matching_periods=1 AND v_matching_cash=1 AND EXISTS(
    SELECT 1 FROM public.subscription_billing_events failed
    WHERE failed.id=p_expected_last_billing_event_id AND failed.subscription_id=s.id
     AND failed.student_id=s.student_id AND failed.mentor_id=s.mentor_id
     AND failed.event_type='renewal_failed' AND failed.status='failed'
     AND failed.failure_code='insufficient_cash' AND failed.attempt_count>=1 AND failed.amount_cents>0
     AND failed.payment_id IS NULL AND failed.ledger_id IS NULL AND failed.voucher_redemption_id IS NULL
     AND (failed.funding_source IS NULL OR failed.funding_source='cash')
     AND failed.period_start=e.period_end AND failed.period_end>failed.period_start
     AND failed.processed_at<=e.processed_at AND failed.plan_tier=e.plan_tier
     AND failed.idempotency_key='sub_renewal:'||s.id::text||':'||to_char(e.period_end AT TIME ZONE 'UTC','YYYY-MM-DD')
     AND EXISTS(SELECT 1 FROM public.mentor_plans plan WHERE plan.id=failed.plan_id
       AND plan.mentor_id=s.mentor_id AND plan.plan_tier=failed.plan_tier)
     AND NOT EXISTS(SELECT 1 FROM public.cash_ledger ledger WHERE ledger.idempotency_key=failed.idempotency_key)
   ) THEN
    RETURN jsonb_build_object('ok',true,'code','already_succeeded','billing_event_id',e.id);
   END IF;
   RETURN jsonb_build_object('ok',false,'code','stale_transition');
  END IF;
 END IF;
 v_alias:=CASE p_event_type WHEN 'canceled' THEN 'sub_cancel:' ELSE 'sub_expired:' END||s.id::text||':'||to_char(s.current_period_end AT TIME ZONE 'UTC','YYYY-MM-DD');
 IF (p_legacy_key IS NOT NULL AND p_legacy_key IS DISTINCT FROM v_alias)
  OR p_expected_period_end IS NULL OR s.current_period_end IS DISTINCT FROM p_expected_period_end
  OR s.last_billing_event_id IS DISTINCT FROM p_expected_last_billing_event_id THEN RETURN jsonb_build_object('ok',false,'code','stale_transition'); END IF;
 IF s.status NOT IN ('active','past_due') OR s.current_period_end>p_processed_at
  OR (p_event_type='canceled' AND NOT coalesce(s.cancel_at_period_end,false))
  OR (p_event_type='expired' AND (s.status<>'past_due' OR s.grace_until IS NULL OR s.grace_until>p_processed_at OR s.cancel_at_period_end))
  THEN RETURN jsonb_build_object('ok',false,'code','not_terminal_eligible'); END IF;
 IF NOT core_private.current_standard_service_period_valid(s.id) THEN RETURN jsonb_build_object('ok',false,'code','SERVICE_PERIOD_FUNDING_UNRESOLVED'); END IF;
 v_key:='sub_terminal:'||s.current_service_period_event_id::text;
 IF EXISTS(SELECT 1 FROM public.subscription_terminal_transitions WHERE legacy_request_key=v_alias)
  OR EXISTS(SELECT 1 FROM public.subscription_billing_events WHERE idempotency_key=v_alias) THEN v_alias:=NULL; END IF;
 INSERT INTO public.subscription_billing_events(subscription_id,student_id,mentor_id,event_type,status,
  period_start,period_end,billing_at,plan_tier,plan_id,idempotency_key,processed_at,funding_source)
 VALUES(s.id,s.student_id,s.mentor_id,p_event_type,'succeeded',s.current_period_start,s.current_period_end,p_processed_at,
  s.plan_tier,s.plan_id,v_key,p_processed_at,s.funding_source) RETURNING * INTO e;
 INSERT INTO public.subscription_terminal_transitions(service_period_event_id,subscription_id,terminal_event_id,expected_last_event_id,legacy_request_key)
 VALUES(s.current_service_period_event_id,s.id,e.id,s.last_billing_event_id,v_alias);
 UPDATE public.subscriptions SET status='expired',expired_at=p_processed_at,next_billing_at=NULL,
  canceled_at=CASE WHEN p_event_type='canceled' THEN p_processed_at ELSE canceled_at END,
  last_billing_event_id=e.id,updated_at=p_processed_at WHERE id=s.id;
 RETURN jsonb_build_object('ok',true,'code','succeeded','billing_event_id',e.id);
END $$;
REVOKE ALL ON FUNCTION core_private.finalize_subscription_terminal_impl(uuid,timestamptz,uuid,text,timestamptz,text) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.finalize_subscription_terminal_transition(p_subscription_id uuid,p_transition text,p_at timestamptz,p_idempotency_key text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF p_transition IS NULL OR p_transition NOT IN ('cancel_at_period_end','grace_expired') OR p_idempotency_key IS NULL THEN
  RETURN jsonb_build_object('ok',false,'code','invalid_transition'); END IF;
 RETURN core_private.finalize_subscription_terminal_impl(p_subscription_id,NULL,NULL,
  CASE p_transition WHEN 'cancel_at_period_end' THEN 'canceled' ELSE 'expired' END,p_at,p_idempotency_key);
END $$;
CREATE FUNCTION public.finalize_subscription_terminal_transition(p_subscription_id uuid,p_expected_period_end timestamptz,
 p_expected_last_billing_event_id uuid,p_event_type text,p_processed_at timestamptz)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT core_private.finalize_subscription_terminal_impl(p_subscription_id,p_expected_period_end,p_expected_last_billing_event_id,p_event_type,p_processed_at,NULL)
$$;
REVOKE ALL ON FUNCTION public.finalize_subscription_terminal_transition(uuid,text,timestamptz,text),public.finalize_subscription_terminal_transition(uuid,timestamptz,uuid,text,timestamptz) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.finalize_subscription_terminal_transition(uuid,text,timestamptz,text),public.finalize_subscription_terminal_transition(uuid,timestamptz,uuid,text,timestamptz) TO service_role;

-- SOURCE supabase/integration_fragments/42_cancel.sql
CREATE FUNCTION core_private.set_subscription_cancel_impl(p_subscription_id uuid,p_cancel boolean,p_student_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE s public.subscriptions%ROWTYPE; v_mentor uuid; v_student uuid; v_was boolean;
BEGIN
 IF p_student_id IS NULL THEN RETURN jsonb_build_object('ok',false,'contract_version',1,'code','AUTH_REQUIRED'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=p_student_id AND role='student') THEN
  RETURN jsonb_build_object('ok',false,'contract_version',1,'code','ROLE_NOT_STUDENT'); END IF;
 IF p_cancel IS NULL THEN RETURN jsonb_build_object('ok',false,'contract_version',1,'code','INVALID_CANCEL_REQUEST'); END IF;
 SELECT student_id,mentor_id INTO v_student,v_mentor FROM public.subscriptions WHERE id=p_subscription_id;
 IF v_student IS NULL THEN RETURN jsonb_build_object('ok',false,'contract_version',1,'code','SUBSCRIPTION_NOT_FOUND'); END IF;
 IF v_student IS DISTINCT FROM p_student_id THEN RETURN jsonb_build_object('ok',false,'contract_version',1,'code','NOT_SUBSCRIPTION_OWNER'); END IF;
 PERFORM pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));
 SELECT * INTO s FROM public.subscriptions WHERE id=p_subscription_id FOR UPDATE;
 IF s.student_id IS DISTINCT FROM p_student_id OR s.mentor_id IS DISTINCT FROM v_mentor THEN RAISE EXCEPTION 'SUBSCRIPTION_BINDING_MISMATCH'; END IF;
 PERFORM 1 FROM public.mentor_profiles WHERE user_id=s.mentor_id FOR UPDATE;
 IF s.status NOT IN ('active','past_due') THEN RETURN jsonb_build_object('ok',false,'contract_version',1,'code','SUBSCRIPTION_NOT_CURRENT','status',s.status); END IF;
 IF s.funding_source='voucher' THEN RETURN jsonb_build_object('ok',false,'contract_version',1,'code','VOUCHER_EXTERNAL_REFUND_REQUIRED'); END IF;
 IF NOT core_private.current_standard_service_period_valid(s.id) THEN RETURN jsonb_build_object('ok',false,'contract_version',1,'code','SERVICE_PERIOD_FUNDING_UNRESOLVED'); END IF;
 v_was:=coalesce(s.cancel_at_period_end,false);
 IF v_was IS DISTINCT FROM p_cancel THEN
  UPDATE public.subscriptions SET cancel_at_period_end=p_cancel,cancel_requested_at=CASE WHEN p_cancel THEN now() ELSE NULL END
   WHERE id=s.id RETURNING * INTO s;
 END IF;
 RETURN jsonb_build_object('ok',true,'code',CASE WHEN v_was=p_cancel THEN 'already_succeeded' ELSE 'succeeded' END,
  'contract_version',1,'subscription_id',s.id,'cancel_at_period_end',s.cancel_at_period_end,'already_scheduled',v_was AND p_cancel,
  'was_scheduled',v_was,'cancel_requested_at',s.cancel_requested_at,'current_period_end',s.current_period_end,'next_billing_at',s.next_billing_at);
END $$;
REVOKE ALL ON FUNCTION core_private.set_subscription_cancel_impl(uuid,boolean,uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.set_subscription_cancel_at_period_end(p_subscription_id uuid,p_cancel boolean,p_student_id uuid)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT core_private.set_subscription_cancel_impl(p_subscription_id,p_cancel,p_student_id)
$$;
REVOKE ALL ON FUNCTION public.set_subscription_cancel_at_period_end(uuid,boolean,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.set_subscription_cancel_at_period_end(uuid,boolean,uuid) TO service_role;
CREATE OR REPLACE FUNCTION api_app_v1.subscription_cancel_at_period_end(p_subscription_id uuid)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT core_private.set_subscription_cancel_impl(p_subscription_id,true,auth.uid())
$$;
CREATE OR REPLACE FUNCTION api_app_v1.subscription_cancel_undo(p_subscription_id uuid)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT core_private.set_subscription_cancel_impl(p_subscription_id,false,auth.uid())
$$;
REVOKE ALL ON FUNCTION api_app_v1.subscription_cancel_at_period_end(uuid),api_app_v1.subscription_cancel_undo(uuid) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION api_app_v1.subscription_cancel_at_period_end(uuid),api_app_v1.subscription_cancel_undo(uuid) TO authenticated;

-- SOURCE supabase/integration_fragments/50_service_period_eligibility.sql
-- Shared Q&A/Storage entitlement decision. Callers acquire domain locks FIRST,
-- capture clock_timestamp() ONCE, then supply that decision time. VOLATILE is
-- intentional: post-lock queries must see transactions that committed while waiting.
CREATE OR REPLACE FUNCTION core_private.service_period_eligibility(
  p_event_id uuid, p_actor_id uuid, p_action text, p_at timestamptz
) RETURNS text LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE
  e public.subscription_billing_events%ROWTYPE;
  s public.subscriptions%ROWTYPE;
  r public.voucher_redemptions%ROWTYPE;
  ent public.voucher_entitlements%ROWTYPE;
  financial_state text;
  v_effective_end timestamptz;
BEGIN
  IF p_actor_id IS NULL THEN RETURN 'AUTH_REQUIRED'; END IF;
  IF p_event_id IS NULL OR p_at IS NULL THEN RETURN 'SERVICE_PERIOD_REQUIRED'; END IF;
  IF p_action IS NULL OR p_action NOT IN ('new_question','quota','message','attachment') THEN
    RETURN 'SERVICE_PERIOD_ACTION_INVALID';
  END IF;
  -- Private helper; wrappers pass the authenticated actor, service callers pass
  -- only a server-verified actor. A client cannot select another actor by UUID.
  IF auth.uid() IS NOT NULL AND auth.uid() IS DISTINCT FROM p_actor_id
     AND (auth.jwt()->>'role') IS DISTINCT FROM 'service_role' THEN
    RETURN 'NOT_ROOM_PARTY';
  END IF;
  SELECT * INTO e FROM public.subscription_billing_events WHERE id=p_event_id;
  IF NOT FOUND THEN RETURN 'SERVICE_PERIOD_NOT_FOUND'; END IF;
  IF p_actor_id IS DISTINCT FROM e.student_id AND p_actor_id IS DISTINCT FROM e.mentor_id THEN
    RETURN 'NOT_ROOM_PARTY';
  END IF;
  IF e.status IS DISTINCT FROM 'succeeded' OR e.event_type NOT IN ('initial','renewal')
     OR e.period_start IS NULL OR e.period_end IS NULL OR e.period_start>=e.period_end THEN
    RETURN 'SERVICE_PERIOD_INVALID';
  END IF;
  SELECT * INTO s FROM public.subscriptions WHERE id=e.subscription_id;
  IF NOT FOUND OR s.student_id IS DISTINCT FROM e.student_id OR s.mentor_id IS DISTINCT FROM e.mentor_id THEN
    RETURN 'SERVICE_PERIOD_PARTY_INVALID';
  END IF;
  IF p_action IN ('new_question','quota') THEN
    IF p_action='new_question' AND p_actor_id IS DISTINCT FROM e.student_id THEN RETURN 'MENTOR_CANNOT_CREATE_THREAD'; END IF;
    IF s.current_service_period_event_id IS DISTINCT FROM e.id OR s.status IS DISTINCT FROM 'active' THEN
      RETURN 'SERVICE_PERIOD_NOT_CURRENT';
    END IF;
    IF NOT core_private.service_period_matches_subscription(s.id,e.id) THEN RETURN 'SERVICE_PERIOD_INVALID'; END IF;
  END IF;
  financial_state := core_private.service_period_financial_state(e.id);
  CASE financial_state
    WHEN 'clear' THEN NULL;
    WHEN 'pending' THEN
      -- Preserve cash's existing pending-refund contract: students cannot add
      -- usage; mentors can complete their outstanding response.
      IF p_action IN ('new_question','quota') OR p_actor_id=e.student_id THEN
        RETURN 'SUBSCRIPTION_REFUND_PENDING';
      END IF;
    WHEN 'refunded' THEN RETURN 'SERVICE_PERIOD_REFUNDED';
    WHEN 'hold' THEN RETURN 'SERVICE_PERIOD_ON_HOLD';
    WHEN 'adjustment_required' THEN RETURN 'SERVICE_PERIOD_ADJUSTMENT_REQUIRED';
    ELSE RETURN 'SERVICE_PERIOD_FINANCIAL_UNRESOLVED';
  END CASE;
  IF e.funding_source='voucher' THEN
    IF e.voucher_redemption_id IS NULL OR e.payment_id IS NOT NULL OR e.ledger_id IS NOT NULL THEN
      RETURN 'VOUCHER_EVENT_INVALID';
    END IF;
    SELECT * INTO r FROM public.voucher_redemptions WHERE id=e.voucher_redemption_id;
    IF NOT FOUND OR r.status IS DISTINCT FROM 'active'
       OR r.subscription_id IS DISTINCT FROM e.subscription_id
       OR r.student_id IS DISTINCT FROM e.student_id OR r.mentor_id IS DISTINCT FROM e.mentor_id
       OR r.service_start IS DISTINCT FROM e.period_start OR r.service_end IS DISTINCT FROM e.period_end
       OR r.gross_cents IS DISTINCT FROM 11500000 OR r.platform_fee_cents IS DISTINCT FROM 1725000
       OR r.mentor_amount_cents IS DISTINCT FROM 9775000 OR r.weekly_question_limit IS DISTINCT FROM 9
       OR r.plan_tier IS DISTINCT FROM 'standard' OR e.amount_cents IS DISTINCT FROM r.gross_cents
       OR e.plan_tier IS DISTINCT FROM r.plan_tier THEN RETURN 'VOUCHER_ENTITLEMENT_INVALID'; END IF;
    SELECT * INTO ent FROM public.voucher_entitlements WHERE id=r.entitlement_id;
    IF NOT FOUND OR ent.status IS DISTINCT FROM 'redeemed' THEN RETURN 'VOUCHER_ENTITLEMENT_INVALID'; END IF;
  ELSIF e.voucher_redemption_id IS NOT NULL
        OR (e.funding_source IS NOT NULL AND e.funding_source NOT IN ('cash','pg')) THEN
    RETURN 'SERVICE_PERIOD_FUNDING_INVALID';
  END IF;
  v_effective_end:=core_private.service_period_effective_end(e.id);
  IF v_effective_end IS NULL THEN RETURN 'SERVICE_PERIOD_INVALID'; END IF;
  IF p_at<e.period_start THEN RETURN 'SERVICE_PERIOD_NOT_STARTED'; END IF;
  IF p_action IN ('new_question','quota') AND p_at>=v_effective_end THEN RETURN 'SERVICE_PERIOD_EXPIRED'; END IF;
  -- Open-thread message/attachment continuation intentionally survives expiry.
  -- Thread status/account/block checks are shared by the C thread adapter.
  RETURN 'allowed';
END $$;
-- Final ACL inventory is owned by D. Revoke defaults immediately in the chain.
REVOKE ALL ON FUNCTION core_private.service_period_eligibility(uuid,uuid,text,timestamptz)
  FROM PUBLIC,anon,authenticated,service_role;

-- SOURCE supabase/integration_fragments/track_c/010_identity_helpers.sql
-- Integration of PR #138 and c74c37b; final migration is integrator-owned.
CREATE OR REPLACE FUNCTION core_private.qna_pair_write_eligibility(p_student uuid,p_mentor uuid,p_actor uuid,p_at timestamptz)
RETURNS text LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF p_actor IS NULL OR p_actor NOT IN (p_student,p_mentor) THEN RETURN 'NOT_ROOM_PARTY'; END IF;
 IF EXISTS(SELECT 1 FROM public.users WHERE id=p_actor AND status='banned') THEN RETURN 'ACCOUNT_BANNED'; END IF;
 IF EXISTS(SELECT 1 FROM public.users WHERE id=p_actor AND status='suspended' AND (suspended_until IS NULL OR suspended_until>p_at)) THEN RETURN 'ACCOUNT_SUSPENDED'; END IF;
 IF EXISTS(SELECT 1 FROM public.users WHERE id IN(p_student,p_mentor) AND (lower(coalesce(status,'')) NOT IN('active','suspended') OR (status='suspended' AND (suspended_until IS NULL OR suspended_until>p_at)))) THEN RETURN 'ACCOUNT_NOT_ACTIVE'; END IF;
 IF (SELECT count(*) FROM public.users WHERE id IN(p_student,p_mentor))<>2 THEN RETURN 'ACCOUNT_NOT_ACTIVE'; END IF;
 IF public.account_deletion_write_blocked(p_actor) THEN RETURN 'ACCOUNT_DELETION_IN_PROGRESS'; END IF;
 IF public.qna_users_blocked(p_student,p_mentor) THEN RETURN 'BLOCKED'; END IF;
 IF NOT public.individual_question_user_is_approved_mentor(p_mentor) THEN RETURN 'MENTOR_NOT_APPROVED'; END IF;
 RETURN 'allowed';
END $$;

-- Every content RPC and Storage INSERT reaches this same locked authorization path.
CREATE OR REPLACE FUNCTION core_private.qna_lock_thread_write(p_thread uuid,p_action text) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE v_student uuid; v_mentor uuid; v_sub uuid; v_event uuid; v_redemption uuid; v_entitlement uuid; v_payment uuid; v_status text; v_at timestamptz; v_code text; v_actor uuid:=auth.uid();
BEGIN
 SELECT r.student_id,r.mentor_id,t.service_period_event_id INTO v_student,v_mentor,v_event
 FROM public.question_threads t JOIN public.mentor_student_rooms r ON r.id=t.mentor_student_room_id WHERE t.id=p_thread;
 IF NOT FOUND THEN RAISE EXCEPTION 'THREAD_NOT_FOUND'; END IF;
 IF v_actor IS NULL OR v_actor NOT IN(v_student,v_mentor) THEN RAISE EXCEPTION 'NOT_ROOM_PARTY'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));
 IF v_event IS NOT NULL THEN
   -- The shared finance adapter owns the global row-lock order.
   PERFORM core_private.lock_service_period_finance(v_event);
 ELSE
   SELECT id INTO v_sub FROM public.subscriptions WHERE student_id=v_student AND mentor_id=v_mentor AND status='active' ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
   PERFORM 1 FROM public.mentor_profiles WHERE user_id=v_mentor FOR UPDATE;
 END IF;
 SELECT status INTO v_status FROM public.question_threads WHERE id=p_thread FOR UPDATE;
 v_at := clock_timestamp();
 IF v_status NOT IN('pending','open','answered') THEN RAISE EXCEPTION 'THREAD_LOCKED'; END IF;
 v_code := core_private.qna_pair_write_eligibility(v_student,v_mentor,v_actor,v_at);
 IF v_code<>'allowed' THEN RAISE EXCEPTION '%',v_code; END IF;
 IF v_event IS NOT NULL THEN
   v_code := core_private.service_period_eligibility(v_event,v_actor,p_action,v_at);
   IF v_code<>'allowed' THEN RAISE EXCEPTION '%',v_code; END IF;
 ELSIF v_sub IS NOT NULL THEN
   IF public.qna_subscription_has_live_refund(v_sub) THEN RAISE EXCEPTION 'SUBSCRIPTION_REFUND_PENDING'; END IF;
 ELSIF NOT EXISTS(SELECT 1 FROM public.free_question_usage WHERE thread_id=p_thread AND student_id=v_student) THEN
   -- Historical unbound cash threads retain existing completion behavior; voucher never has NULL binding.
   IF EXISTS(SELECT 1 FROM public.voucher_redemptions WHERE student_id=v_student AND mentor_id=v_mentor) THEN RAISE EXCEPTION 'SERVICE_PERIOD_UNBOUND'; END IF;
 END IF;
END $$;

CREATE OR REPLACE FUNCTION core_private.qna_identity_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE v_thread uuid;
BEGIN
 IF TG_TABLE_NAME='question_threads' THEN
   IF TG_OP='UPDATE' AND (NEW.service_period_event_id IS DISTINCT FROM OLD.service_period_event_id OR NEW.mentor_student_room_id IS DISTINCT FROM OLD.mentor_student_room_id) THEN RAISE EXCEPTION 'SERVICE_PERIOD_IMMUTABLE'; END IF;
   IF TG_OP='INSERT' AND public.qna_is_direct_untrusted_writer() AND (NEW.service_period_event_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.mentor_student_rooms r JOIN public.subscriptions v ON v.student_id=r.student_id AND v.mentor_id=r.mentor_id WHERE r.id=NEW.mentor_student_room_id AND (v.funding_source='voucher' OR v.current_service_period_event_id IS NOT NULL))) THEN RAISE EXCEPTION 'QNA_USE_RPC'; END IF;
   IF TG_OP='INSERT' AND NEW.service_period_event_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.subscription_billing_events e JOIN public.mentor_student_rooms r ON r.student_id=e.student_id AND r.mentor_id=e.mentor_id WHERE e.id=NEW.service_period_event_id AND r.id=NEW.mentor_student_room_id) THEN RAISE EXCEPTION 'SERVICE_PERIOD_PARTY_INVALID'; END IF;
 ELSE
   IF TG_OP='UPDATE' AND NEW.thread_id IS DISTINCT FROM OLD.thread_id THEN RAISE EXCEPTION 'THREAD_BINDING_IMMUTABLE'; END IF;
   v_thread:=NEW.thread_id;
   IF public.qna_is_direct_untrusted_writer() AND EXISTS(SELECT 1 FROM public.question_threads WHERE id=v_thread AND service_period_event_id IS NOT NULL) THEN RAISE EXCEPTION 'QNA_USE_RPC'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER qna_period_identity_guard BEFORE INSERT OR UPDATE ON public.question_threads FOR EACH ROW EXECUTE FUNCTION core_private.qna_identity_guard();
CREATE TRIGGER qna_period_identity_guard BEFORE INSERT OR UPDATE ON public.question_messages FOR EACH ROW EXECUTE FUNCTION core_private.qna_identity_guard();
CREATE TRIGGER qna_period_identity_guard BEFORE INSERT OR UPDATE ON public.question_attachments FOR EACH ROW EXECUTE FUNCTION core_private.qna_identity_guard();

-- SOURCE supabase/integration_fragments/track_c/015_quota_helper.sql
-- Integration of PR #138 and c74c37b; final migration is integrator-owned.
-- Counting is side effect free; caller holds pair/event locks for a write decision.
CREATE OR REPLACE FUNCTION core_private.qna_voucher_weekly_usage(p_event uuid,p_at timestamptz) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE v_start timestamptz; v_end timestamptz; v_week timestamptz; v_used integer;
BEGIN
 SELECT r.service_start,r.service_end INTO v_start,v_end FROM public.subscription_billing_events e JOIN public.voucher_redemptions r ON r.id=e.voucher_redemption_id WHERE e.id=p_event;
 IF NOT FOUND OR p_at IS NULL OR p_at<v_start THEN RAISE EXCEPTION 'SERVICE_PERIOD_INVALID'; END IF;
 v_week:=v_start+floor(extract(epoch from(least(p_at,v_end-interval '1 microsecond')-v_start))/604800)::integer*interval '7 days';
 SELECT count(*) INTO v_used FROM public.question_threads WHERE service_period_event_id=p_event AND created_at>=v_week AND created_at<least(v_week+interval '7 days',v_end);
 RETURN jsonb_build_object('used',v_used,'limit',9,'remaining',case when p_at<v_end then greatest(0,9-v_used) else 0 end,'can_ask',p_at<v_end and v_used<9,'week_start',v_week,'week_end',least(v_week+interval '7 days',v_end));
END $$;

-- SOURCE supabase/integration_fragments/track_c/017_cash_quota_helper.sql
-- Preserve cash's established anchor/count; evaluate the caller's post-lock
-- decision time so transactions waiting across a week boundary count that week.
CREATE OR REPLACE FUNCTION core_private.qna_cash_weekly_usage(p_student_id uuid,p_mentor_id uuid,p_at timestamptz)
RETURNS json LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE
 v_anchor timestamptz; v_week_start timestamptz; v_week_end timestamptz;
 v_elapsed_seconds numeric; v_period_index integer; v_used integer:=0;
 v_plan_tier text; v_limit integer:=0;
BEGIN
 IF p_at IS NULL THEN RAISE EXCEPTION 'SERVICE_PERIOD_REQUIRED'; END IF;
  select
    s.plan_tier,
    coalesce(s.started_at, s.created_at)
  into v_plan_tier, v_anchor
  from public.subscriptions s
  where s.student_id = p_student_id
    and s.mentor_id = p_mentor_id
    and lower(coalesce(s.status, '')) = 'active'
  order by s.created_at desc
  limit 1;

  v_limit := case lower(coalesce(v_plan_tier, ''))
    when 'limited' then 4
    when 'standard' then 9
    when 'premium' then 999
    else 0
  end;

  if v_anchor is not null then
    v_elapsed_seconds := extract(epoch from (p_at - v_anchor));
    v_period_index := greatest(0, floor(v_elapsed_seconds / 604800.0)::integer);
    v_week_start := v_anchor + (v_period_index * interval '7 days');
    v_week_end := v_week_start + interval '7 days';

    select count(*)::integer into v_used
    from public.question_threads qt
    inner join public.mentor_student_rooms r on r.id = qt.mentor_student_room_id
    where r.student_id = p_student_id
      and r.mentor_id = p_mentor_id
      and lower(coalesce(qt.status, '')) in ('pending', 'answered', 'confirmed', 'closed', 'archived')
      and qt.created_at >= v_week_start
      and qt.created_at < v_week_end;
  end if;

  return json_build_object(
    'used', coalesce(v_used, 0),
    'limit', v_limit,
    'plan_tier', v_plan_tier,
    'remaining', greatest(0, v_limit - coalesce(v_used, 0)),
    'can_ask', coalesce(v_used, 0) < v_limit,
    'week_start', v_week_start,
    'week_end', v_week_end
  );
END $$;

-- SOURCE supabase/integration_fragments/track_c/020_create.sql
-- Integration of PR #138 and c74c37b; final migration is integrator-owned.
CREATE OR REPLACE FUNCTION public.qna_create_question_thread(p_room_id uuid, p_title text, p_subject text DEFAULT NULL::text, p_topic text DEFAULT NULL::text, p_first_message_body text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid(); v_student uuid; v_mentor uuid; v_status text; v_suspended_until timestamptz;
  v_created_at timestamptz; v_total int; v_per int; v_subject text; v_thread_id uuid; v_message_id uuid;
  v_event uuid; v_redemption uuid; v_entitlement uuid; v_payment uuid; v_decided_at timestamptz; v_code text; v_start timestamptz; v_end timestamptz; v_week timestamptz; v_used integer; v_has_active_sub boolean; v_usage json; v_path text; v_sub_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if char_length(p_title)>120 then raise exception 'TITLE_TOO_LONG'; end if;
  if char_length(p_topic)>80 then raise exception 'TOPIC_TOO_LONG'; end if;
  if char_length(p_first_message_body)>10000 then raise exception 'MESSAGE_TOO_LONG'; end if;
  if char_length(p_subject)>64 then raise exception 'SUBJECT_INVALID'; end if;
  if p_title is null or btrim(p_title)='' then raise exception 'TITLE_REQUIRED'; end if;
  select student_id, mentor_id into v_student, v_mentor from public.mentor_student_rooms where id=p_room_id;
  if not found then raise exception 'ROOM_NOT_FOUND'; end if;
  if v_uid <> v_student then
    if v_uid = v_mentor then raise exception 'MENTOR_CANNOT_CREATE_THREAD'; else raise exception 'NOT_ROOM_PARTY'; end if;
  end if;
  perform pg_advisory_xact_lock(hashtext(v_student::text),hashtext(v_mentor::text));
  select id,current_service_period_event_id into v_sub_id,v_event from public.subscriptions
    where student_id=v_student and mentor_id=v_mentor order by created_at desc limit 1;
  if v_event is not null then
    perform core_private.lock_service_period_finance(v_event);
    select voucher_redemption_id into v_redemption from public.subscription_billing_events where id=v_event;
  else
    perform 1 from public.subscriptions where id=v_sub_id for update;
    perform 1 from public.mentor_profiles where user_id=v_mentor for update;
  end if;
  perform 1 from public.users where id=v_student for update;
  v_decided_at := clock_timestamp();
  v_code := core_private.qna_pair_write_eligibility(v_student,v_mentor,v_uid,v_decided_at);
  if v_code <> 'allowed' then raise exception '%',v_code; end if;
  select status, suspended_until, created_at into v_status, v_suspended_until, v_created_at from public.users where id=v_student;
  if lower(coalesce(v_status,'active'))='banned' then raise exception 'ACCOUNT_BANNED'; end if;
  if lower(coalesce(v_status,'active'))='suspended' and (v_suspended_until is null or v_suspended_until > v_decided_at) then raise exception 'ACCOUNT_SUSPENDED'; end if;
  if exists (select 1 from public.user_blocks where (blocker_id=v_student and blocked_id=v_mentor) or (blocker_id=v_mentor and blocked_id=v_student)) then raise exception 'BLOCKED'; end if;
  if not public.individual_question_user_is_approved_mentor(v_mentor) then raise exception 'MENTOR_NOT_APPROVED'; end if;
  if v_event is not null then
    v_code := core_private.service_period_eligibility(v_event,v_uid,'new_question',v_decided_at);
    if v_code <> 'allowed' then raise exception '%',v_code; end if;
    if v_redemption is not null then
      v_usage := core_private.qna_voucher_weekly_usage(v_event,v_decided_at);
      if not (v_usage->>'can_ask')::boolean then raise exception 'WEEKLY_LIMIT_EXHAUSTED'; end if;
    else
      v_usage := core_private.qna_cash_weekly_usage(v_student,v_mentor,v_decided_at);
      if not coalesce((v_usage->>'can_ask')::boolean,false) then raise exception 'WEEKLY_LIMIT_EXHAUSTED'; end if;
    end if;
    v_path := 'subscription';
  elsif exists(select 1 from public.subscriptions where student_id=v_student and mentor_id=v_mentor and status='active') then
    -- An active row without a verified financial period is unknown, not cash.
    raise exception 'SERVICE_PERIOD_UNBOUND';
  else
    if exists(select 1 from public.voucher_redemptions where student_id=v_student and mentor_id=v_mentor) then raise exception 'SERVICE_PERIOD_EXPIRED'; end if;
    if v_created_at is not null and v_decided_at >= v_created_at + interval '7 days' then raise exception 'FREE_QUOTA_EXPIRED'; end if;
    select count(*) into v_total from public.free_question_usage where student_id=v_student;
    if v_total >= 7 then raise exception 'FREE_QUOTA_TOTAL_EXHAUSTED'; end if;
    select count(*) into v_per from public.free_question_usage where student_id=v_student and mentor_id=v_mentor;
    if v_per >= 3 then raise exception 'FREE_QUOTA_MENTOR_EXHAUSTED'; end if;
    v_path := 'free';
  end if;
  v_subject := nullif(btrim(coalesce(p_subject,'')),'');
  if v_subject is not null and not exists (select 1 from public.subjects where code=v_subject) then raise exception 'SUBJECT_INVALID'; end if;
  insert into public.question_threads (mentor_student_room_id, title, status, subject, topic, service_period_event_id, created_at)
  values (p_room_id, btrim(p_title), 'pending', v_subject, nullif(btrim(coalesce(p_topic,'')),''),v_event,v_decided_at) returning id into v_thread_id;
  if p_first_message_body is not null and btrim(p_first_message_body) <> '' then
    insert into public.question_messages (thread_id, author_id, body) values (v_thread_id, v_student, btrim(p_first_message_body)) returning id into v_message_id;
  end if;
  if v_path='free' then insert into public.free_question_usage (student_id, mentor_id, thread_id) values (v_student, v_mentor, v_thread_id); end if;

  -- ── 새 질문 → 방 멘토 인앱 알림(question_received) ──
  -- 20260805 도입(구독 한정) → S1-7/QA-C13 에서 무료 경로까지 확장.
  -- 같은 트랜잭션 안 — 위 생성이 롤백되면 알림도 롤백(원자), record_domain_notification
  -- 이 (recipient,event_key) 멱등 + outbox 게이트를 기존 계약대로 처리한다.
  -- S1-7/QA-C13: 무료·구독 경로 모두 알린다(종전에는 subscription 한정 조건이 있었다).
    perform public.record_domain_notification(
      v_mentor,
      'question_received:' || v_thread_id::text,
      'question_received:' || v_thread_id::text,
      'question_received',
      '새 질문이 도착했어요',
      '학생이 새 질문을 등록했어요.',
      '/mentor/question-room/' || p_room_id::text || '?thread=' || v_thread_id::text,
      jsonb_build_object('room_id', p_room_id, 'thread_id', v_thread_id, 'student_id', v_student),
      jsonb_build_object('room_id', p_room_id, 'thread_id', v_thread_id, 'student_id', v_student)
    );

  return jsonb_build_object('ok',true,'thread_id',v_thread_id,'message_id',v_message_id,'path',v_path,'used_free_quota',(v_path='free'));
end;
$function$;

-- SOURCE supabase/integration_fragments/track_c/025_quota.sql
-- Integration of PR #138 and c74c37b; final migration is integrator-owned.
CREATE OR REPLACE FUNCTION public.get_weekly_question_usage(p_student_id uuid, p_mentor_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_usage jsonb; v_event uuid; v_redemption uuid; v_end timestamptz; v_now timestamptz; v_code text := 'allowed'; v_anchor timestamptz;
  v_week_start timestamptz;
  v_week_end timestamptz;
  v_elapsed_seconds numeric;
  v_period_index integer;
  v_used integer := 0;
  v_plan_tier text;
  v_limit integer := 0;
begin
  -- [S2 M15] NULL-safe pair-party 가드 (계약 §7 F1 — 오너 확정 형태 고정).
  IF (auth.jwt() ->> 'role') IS DISTINCT FROM 'service_role'
     AND auth.uid() IS DISTINCT FROM p_student_id
     AND auth.uid() IS DISTINCT FROM p_mentor_id
  THEN
    RAISE EXCEPTION 'NOT_PAIR_PARTY'
      USING ERRCODE = '42501';
  END IF;

  if p_student_id is null or p_mentor_id is null then
    raise exception 'p_student_id and p_mentor_id are required';
  end if;

  v_now:=clock_timestamp();
  select e.id,e.voucher_redemption_id into v_event,v_redemption
    from public.subscriptions s join public.subscription_billing_events e on e.id=s.current_service_period_event_id
    where s.student_id=p_student_id and s.mentor_id=p_mentor_id order by s.created_at desc limit 1;
  if v_event is not null then
    v_code:=core_private.service_period_eligibility(v_event,coalesce(auth.uid(),p_student_id),'quota',v_now);
    if v_redemption is not null then
      v_usage:=core_private.qna_voucher_weekly_usage(v_event,v_now);
      return (v_usage || jsonb_build_object('plan_tier','standard','remaining',case when v_code='allowed' then (v_usage->>'remaining')::int else 0 end,'can_ask',v_code='allowed' and (v_usage->>'can_ask')::boolean,'code',nullif(v_code,'allowed')))::json;
    end if;
  end if;
  if v_event is null then
    if exists(select 1 from public.subscriptions where student_id=p_student_id and mentor_id=p_mentor_id and status='active') then
      raise exception 'SERVICE_PERIOD_UNBOUND';
    end if;
    if exists(select 1 from public.voucher_redemptions where student_id=p_student_id and mentor_id=p_mentor_id) then
      -- A cleared current pointer after expiry must not look like a free-quota
      -- candidate to existing clients (limit=0 / plan_tier=null means free).
      select id into v_event from public.subscription_billing_events
        where student_id=p_student_id and mentor_id=p_mentor_id and voucher_redemption_id is not null
          and event_type in ('initial','renewal') order by period_start desc,id limit 1;
      if v_event is not null then v_usage:=core_private.qna_voucher_weekly_usage(v_event,v_now); end if;
      return (coalesce(v_usage,'{}'::jsonb)||jsonb_build_object('used',coalesce((v_usage->>'used')::integer,0),
        'limit',9,'plan_tier','standard','remaining',0,'can_ask',false,'code','SERVICE_PERIOD_EXPIRED'))::json;
    end if;
  end if;
  -- Cash retains its established weekly anchor/count. The common eligibility
  -- decision gates both this display and the locked creation RPC.
  v_usage:=core_private.qna_cash_weekly_usage(p_student_id,p_mentor_id,v_now)::jsonb;
  return (v_usage||jsonb_build_object(
    'remaining',case when v_code='allowed' then (v_usage->>'remaining')::integer else 0 end,
    'can_ask',v_code='allowed' and (v_usage->>'can_ask')::boolean,'code',nullif(v_code,'allowed')))::json;
end;
$function$;

-- SOURCE supabase/integration_fragments/track_c/030_qna_append_message.sql
-- Integration of PR #138 and c74c37b; final migration is integrator-owned.
CREATE OR REPLACE FUNCTION public.qna_append_message(p_thread_id uuid, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_status text; v_thread_status text;
  v_first_answered timestamptz; v_message_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_sub_id uuid;
  v_susp timestamptz; v_norm text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if char_length(p_body)>10000 then raise exception 'MESSAGE_TOO_LONG'; end if;
  if p_body is null or btrim(p_body)='' then raise exception 'BODY_REQUIRED'; end if;
  perform core_private.qna_lock_thread_write(p_thread_id,'message');
  select t.mentor_student_room_id,t.status,t.first_answered_at into v_room,v_thread_status,v_first_answered from public.question_threads t where id=p_thread_id;
  select student_id,mentor_id into v_student,v_mentor from public.mentor_student_rooms where id=v_room;
  v_is_mentor := v_uid=v_mentor;
  -- F2(D-12)+R1: 아래 INSERT 가 AFTER INSERT 알림 트리거를 발화 — 멘토 메시지 행 1건 = 알림 정확히 1건.
  insert into public.question_messages (thread_id, author_id, body) values (p_thread_id, v_uid, btrim(p_body)) returning id into v_message_id;
  if v_is_mentor and v_first_answered is null then
    update public.question_threads set status='answered', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;
    v_transitioned := true;
  end if;
  return jsonb_build_object('ok',true,'message_id',v_message_id,'answered_transition',v_transitioned);
end; $function$;

-- SOURCE supabase/integration_fragments/track_c/030_qna_register_attachment.sql
-- Integration of PR #138 and c74c37b; final migration is integrator-owned.
CREATE OR REPLACE FUNCTION public.qna_register_attachment(p_thread_id uuid, p_storage_path text, p_file_name text DEFAULT NULL::text, p_mime_type text DEFAULT NULL::text, p_message_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid(); v_room uuid; v_student uuid; v_mentor uuid; v_thread_status text;
  v_first_answered timestamptz; v_att_id uuid; v_is_mentor boolean; v_transitioned boolean := false; v_sub_id uuid;
  v_status text; v_susp timestamptz; v_norm text;
begin
  perform core_private.qna_assert_text_bound(p_storage_path,1024);
  perform core_private.qna_assert_text_bound(p_file_name,255);
  perform core_private.qna_assert_text_bound(p_mime_type,127);

  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_storage_path is null or btrim(p_storage_path)='' then raise exception 'STORAGE_PATH_REQUIRED'; end if;
  perform core_private.qna_lock_thread_write(p_thread_id,'attachment');
  select t.mentor_student_room_id,t.status,t.first_answered_at into v_room,v_thread_status,v_first_answered from public.question_threads t where id=p_thread_id;
  select student_id,mentor_id into v_student,v_mentor from public.mentor_student_rooms where id=v_room;
  v_is_mentor := v_uid=v_mentor;
  if p_storage_path not like (v_room::text || '/' || p_thread_id::text || '/%') then raise exception 'STORAGE_PATH_MISMATCH'; end if;
  if not exists (select 1 from storage.objects o where o.bucket_id='question-room-attachments' and o.name=btrim(p_storage_path) and o.owner_id=v_uid::text) then raise exception 'STORAGE_OBJECT_NOT_OWNED'; end if;
  if p_message_id is not null and not exists(select 1 from public.question_messages where id=p_message_id and thread_id=p_thread_id) then raise exception 'MESSAGE_THREAD_MISMATCH'; end if;
  -- F2(D-12)+R1: 아래 INSERT 가 AFTER INSERT 알림 트리거를 발화 — 멘토 단독 첨부 행 1건 = 알림 정확히 1건.
  insert into public.question_attachments (thread_id, message_id, author_id, storage_path, file_name, mime_type)
  values (p_thread_id, p_message_id, v_uid, btrim(p_storage_path), p_file_name, p_mime_type) returning id into v_att_id;
  if v_is_mentor and v_first_answered is null then
    update public.question_threads set status='answered', first_answered_at=now(), updated_at=now() where id=p_thread_id and first_answered_at is null;
    v_transitioned := true;
  end if;
  return jsonb_build_object('ok',true,'attachment_id',v_att_id,'answered_transition',v_transitioned);
end; $function$;

-- SOURCE supabase/integration_fragments/track_c/040_storage.sql
-- Integration of PR #138 and c74c37b; final migration is integrator-owned.
CREATE OR REPLACE FUNCTION public.qra_path_upload_eligible(p_name text) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE v_thread uuid; v_room uuid;
BEGIN
 IF auth.uid() IS NULL OR length(p_name)>1024 THEN RETURN false; END IF;
 BEGIN
  v_room:=split_part(p_name,'/',1)::uuid;
  v_thread:=split_part(p_name,'/',2)::uuid;
 EXCEPTION WHEN invalid_text_representation THEN RETURN false;
 END;
 IF split_part(p_name,'/',3)='' OR NOT EXISTS(SELECT 1 FROM public.question_threads WHERE id=v_thread AND mentor_student_room_id=v_room) THEN RETURN false; END IF;
 BEGIN
  PERFORM core_private.qna_lock_thread_write(v_thread,'attachment');
 EXCEPTION WHEN raise_exception THEN RETURN false;
 END;
 RETURN true;
END $$;
DROP POLICY IF EXISTS qra_storage_insert_party ON storage.objects;
CREATE POLICY qra_storage_insert_party ON storage.objects FOR INSERT TO authenticated
WITH CHECK(bucket_id='question-room-attachments' AND owner_id=(SELECT auth.uid())::text AND public.qra_path_upload_eligible(name));

-- SOURCE supabase/integration_fragments/track_c/050_api_wrappers.sql
CREATE OR REPLACE FUNCTION api_web_v1.qna_create_question_thread(p_room_id uuid, p_title text, p_subject text DEFAULT NULL::text, p_topic text DEFAULT NULL::text, p_first_message_body text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_res  jsonb;
  v_code text;
BEGIN
  -- 판정 로직을 복제하지 않는다 — 정본 호출 + 예외의 안정 코드 변환만(§13.2)
  v_res := public.qna_create_question_thread(p_room_id, p_title, p_subject, p_topic, p_first_message_body);
  RETURN v_res || jsonb_build_object('contract_version', 1);
EXCEPTION WHEN OTHERS THEN
  v_code := CASE SQLERRM
    -- 트리거 코드 수렴(XW-08 — §9.8 매핑표)
    WHEN 'FREE_QUESTION_EXPIRED'           THEN 'FREE_QUOTA_EXPIRED'
    WHEN 'FREE_QUESTION_TOTAL_LIMIT'       THEN 'FREE_QUOTA_TOTAL_EXHAUSTED'
    WHEN 'FREE_QUESTION_PER_MENTOR_LIMIT'  THEN 'FREE_QUOTA_MENTOR_EXHAUSTED'
    WHEN 'FREE_QUESTION_STUDENT_NOT_FOUND' THEN 'FREE_QUOTA_STUDENT_NOT_FOUND'
    -- 정본 raise 14종(실측 전수 — §9.8 "qna_* raise 14종 동명 유지")
    WHEN 'AUTH_REQUIRED'                 THEN 'AUTH_REQUIRED'
    WHEN 'TITLE_REQUIRED'                THEN 'TITLE_REQUIRED'
    WHEN 'ROOM_NOT_FOUND'                THEN 'ROOM_NOT_FOUND'
    WHEN 'NOT_ROOM_PARTY'                THEN 'NOT_ROOM_PARTY'
    WHEN 'MENTOR_CANNOT_CREATE_THREAD'   THEN 'MENTOR_CANNOT_CREATE_THREAD'
    WHEN 'ACCOUNT_BANNED'                THEN 'ACCOUNT_BANNED'
    WHEN 'ACCOUNT_SUSPENDED'             THEN 'ACCOUNT_SUSPENDED'
    WHEN 'ACCOUNT_DELETION_IN_PROGRESS'  THEN 'ACCOUNT_DELETION_IN_PROGRESS'
    WHEN 'BLOCKED'                       THEN 'BLOCKED'
    WHEN 'MENTOR_NOT_APPROVED'           THEN 'MENTOR_NOT_APPROVED'
    WHEN 'SUBSCRIPTION_REFUND_PENDING'   THEN 'SUBSCRIPTION_REFUND_PENDING'
    WHEN 'WEEKLY_LIMIT_EXHAUSTED'        THEN 'WEEKLY_LIMIT_EXHAUSTED'
    WHEN 'FREE_QUOTA_EXPIRED'            THEN 'FREE_QUOTA_EXPIRED'
    WHEN 'FREE_QUOTA_TOTAL_EXHAUSTED'    THEN 'FREE_QUOTA_TOTAL_EXHAUSTED'
    WHEN 'FREE_QUOTA_MENTOR_EXHAUSTED'   THEN 'FREE_QUOTA_MENTOR_EXHAUSTED'
    WHEN 'TITLE_TOO_LONG' THEN 'TITLE_TOO_LONG'
    WHEN 'TOPIC_TOO_LONG' THEN 'TOPIC_TOO_LONG'
    WHEN 'MESSAGE_TOO_LONG' THEN 'MESSAGE_TOO_LONG'
    WHEN 'SUBJECT_INVALID' THEN 'SUBJECT_INVALID'
    WHEN 'ACCOUNT_NOT_ACTIVE' THEN 'ACCOUNT_NOT_ACTIVE'
    WHEN 'SERVICE_PERIOD_REQUIRED' THEN 'SERVICE_PERIOD_REQUIRED'
    WHEN 'SERVICE_PERIOD_NOT_FOUND' THEN 'SERVICE_PERIOD_NOT_FOUND'
    WHEN 'SERVICE_PERIOD_INVALID' THEN 'SERVICE_PERIOD_INVALID'
    WHEN 'SERVICE_PERIOD_PARTY_INVALID' THEN 'SERVICE_PERIOD_PARTY_INVALID'
    WHEN 'SERVICE_PERIOD_NOT_CURRENT' THEN 'SERVICE_PERIOD_NOT_CURRENT'
    WHEN 'SERVICE_PERIOD_NOT_STARTED' THEN 'SERVICE_PERIOD_NOT_STARTED'
    WHEN 'SERVICE_PERIOD_EXPIRED' THEN 'SERVICE_PERIOD_EXPIRED'
    WHEN 'SERVICE_PERIOD_REFUNDED' THEN 'SERVICE_PERIOD_REFUNDED'
    WHEN 'SERVICE_PERIOD_ON_HOLD' THEN 'SERVICE_PERIOD_ON_HOLD'
    WHEN 'SERVICE_PERIOD_ADJUSTMENT_REQUIRED' THEN 'SERVICE_PERIOD_ADJUSTMENT_REQUIRED'
    WHEN 'SERVICE_PERIOD_FINANCIAL_UNRESOLVED' THEN 'SERVICE_PERIOD_FINANCIAL_UNRESOLVED'
    WHEN 'SERVICE_PERIOD_FUNDING_INVALID' THEN 'SERVICE_PERIOD_FUNDING_INVALID'
    WHEN 'SERVICE_PERIOD_UNBOUND' THEN 'SERVICE_PERIOD_UNBOUND'
    WHEN 'VOUCHER_EVENT_INVALID' THEN 'VOUCHER_EVENT_INVALID'
    WHEN 'VOUCHER_ENTITLEMENT_INVALID' THEN 'VOUCHER_ENTITLEMENT_INVALID'
    ELSE NULL
  END;
  IF v_code IS NULL THEN
    -- 사전에 없는 예외는 삼키지 않고 그대로 전파(§8.2 — T-CON-06)
    RAISE;
  END IF;
  RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', v_code);
END $function$
;

CREATE OR REPLACE FUNCTION api_app_v1.qna_create_question_thread(p_room_id uuid, p_title text, p_subject text DEFAULT NULL::text, p_topic text DEFAULT NULL::text, p_first_message_body text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_res  jsonb;
  v_code text;
BEGIN
  v_res := public.qna_create_question_thread(p_room_id, p_title, p_subject, p_topic, p_first_message_body);
  RETURN v_res || jsonb_build_object('contract_version', 1);
EXCEPTION WHEN OTHERS THEN
  v_code := CASE SQLERRM
    WHEN 'FREE_QUESTION_EXPIRED'           THEN 'FREE_QUOTA_EXPIRED'
    WHEN 'FREE_QUESTION_TOTAL_LIMIT'       THEN 'FREE_QUOTA_TOTAL_EXHAUSTED'
    WHEN 'FREE_QUESTION_PER_MENTOR_LIMIT'  THEN 'FREE_QUOTA_MENTOR_EXHAUSTED'
    WHEN 'FREE_QUESTION_STUDENT_NOT_FOUND' THEN 'FREE_QUOTA_STUDENT_NOT_FOUND'
    WHEN 'AUTH_REQUIRED'                 THEN 'AUTH_REQUIRED'
    WHEN 'TITLE_REQUIRED'                THEN 'TITLE_REQUIRED'
    WHEN 'ROOM_NOT_FOUND'                THEN 'ROOM_NOT_FOUND'
    WHEN 'NOT_ROOM_PARTY'                THEN 'NOT_ROOM_PARTY'
    WHEN 'MENTOR_CANNOT_CREATE_THREAD'   THEN 'MENTOR_CANNOT_CREATE_THREAD'
    WHEN 'ACCOUNT_BANNED'                THEN 'ACCOUNT_BANNED'
    WHEN 'ACCOUNT_SUSPENDED'             THEN 'ACCOUNT_SUSPENDED'
    WHEN 'ACCOUNT_DELETION_IN_PROGRESS'  THEN 'ACCOUNT_DELETION_IN_PROGRESS'
    WHEN 'BLOCKED'                       THEN 'BLOCKED'
    WHEN 'MENTOR_NOT_APPROVED'           THEN 'MENTOR_NOT_APPROVED'
    WHEN 'SUBSCRIPTION_REFUND_PENDING'   THEN 'SUBSCRIPTION_REFUND_PENDING'
    WHEN 'WEEKLY_LIMIT_EXHAUSTED'        THEN 'WEEKLY_LIMIT_EXHAUSTED'
    WHEN 'FREE_QUOTA_EXPIRED'            THEN 'FREE_QUOTA_EXPIRED'
    WHEN 'FREE_QUOTA_TOTAL_EXHAUSTED'    THEN 'FREE_QUOTA_TOTAL_EXHAUSTED'
    WHEN 'FREE_QUOTA_MENTOR_EXHAUSTED'   THEN 'FREE_QUOTA_MENTOR_EXHAUSTED'
    WHEN 'TITLE_TOO_LONG' THEN 'TITLE_TOO_LONG'
    WHEN 'TOPIC_TOO_LONG' THEN 'TOPIC_TOO_LONG'
    WHEN 'MESSAGE_TOO_LONG' THEN 'MESSAGE_TOO_LONG'
    WHEN 'SUBJECT_INVALID' THEN 'SUBJECT_INVALID'
    WHEN 'ACCOUNT_NOT_ACTIVE' THEN 'ACCOUNT_NOT_ACTIVE'
    WHEN 'SERVICE_PERIOD_REQUIRED' THEN 'SERVICE_PERIOD_REQUIRED'
    WHEN 'SERVICE_PERIOD_NOT_FOUND' THEN 'SERVICE_PERIOD_NOT_FOUND'
    WHEN 'SERVICE_PERIOD_INVALID' THEN 'SERVICE_PERIOD_INVALID'
    WHEN 'SERVICE_PERIOD_PARTY_INVALID' THEN 'SERVICE_PERIOD_PARTY_INVALID'
    WHEN 'SERVICE_PERIOD_NOT_CURRENT' THEN 'SERVICE_PERIOD_NOT_CURRENT'
    WHEN 'SERVICE_PERIOD_NOT_STARTED' THEN 'SERVICE_PERIOD_NOT_STARTED'
    WHEN 'SERVICE_PERIOD_EXPIRED' THEN 'SERVICE_PERIOD_EXPIRED'
    WHEN 'SERVICE_PERIOD_REFUNDED' THEN 'SERVICE_PERIOD_REFUNDED'
    WHEN 'SERVICE_PERIOD_ON_HOLD' THEN 'SERVICE_PERIOD_ON_HOLD'
    WHEN 'SERVICE_PERIOD_ADJUSTMENT_REQUIRED' THEN 'SERVICE_PERIOD_ADJUSTMENT_REQUIRED'
    WHEN 'SERVICE_PERIOD_FINANCIAL_UNRESOLVED' THEN 'SERVICE_PERIOD_FINANCIAL_UNRESOLVED'
    WHEN 'SERVICE_PERIOD_FUNDING_INVALID' THEN 'SERVICE_PERIOD_FUNDING_INVALID'
    WHEN 'SERVICE_PERIOD_UNBOUND' THEN 'SERVICE_PERIOD_UNBOUND'
    WHEN 'VOUCHER_EVENT_INVALID' THEN 'VOUCHER_EVENT_INVALID'
    WHEN 'VOUCHER_ENTITLEMENT_INVALID' THEN 'VOUCHER_ENTITLEMENT_INVALID'
    ELSE NULL
  END;
  IF v_code IS NULL THEN
    -- 사전에 없는 예외는 삼키지 않고 그대로 전파(앱 계약 §3.3 envelope 규약)
    RAISE;
  END IF;
  RETURN jsonb_build_object('ok', false, 'contract_version', 1, 'code', v_code);
END $function$
;

-- SOURCE supabase/integration_fragments/track_c/070_privileges.sql
-- C-owned functions: keep the original authenticated RPC surface, no new
-- client entry point for identity, locks or entitlement decisions.
REVOKE ALL ON FUNCTION
 core_private.qna_pair_write_eligibility(uuid,uuid,uuid,timestamptz),
 core_private.qna_lock_thread_write(uuid,text),
 core_private.qna_identity_guard(),
 core_private.qna_voucher_weekly_usage(uuid,timestamptz),
 core_private.qna_cash_weekly_usage(uuid,uuid,timestamptz)
 FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION
 public.qna_create_question_thread(uuid,text,text,text,text),
 public.qna_append_message(uuid,text),
 public.qna_register_attachment(uuid,text,text,text,uuid),
 public.get_weekly_question_usage(uuid,uuid),
 public.qra_path_upload_eligible(text)
 FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION
 public.qna_create_question_thread(uuid,text,text,text,text),
 public.qna_append_message(uuid,text),
 public.qna_register_attachment(uuid,text,text,text,uuid),
 public.get_weekly_question_usage(uuid,uuid),
 public.qra_path_upload_eligible(text)
 TO authenticated,service_role;

-- SOURCE supabase/integration_fragments/mentor_directory.sql
-- New candidate fragment. Never rewrite the 127 historical migrations.
-- The legacy invoker view keeps its 17-column projection and base-table ACLs.
-- Only bounded public read wrappers receive API-role EXECUTE privileges.
create or replace function core_private.mentor_directory_base(p_mentor_ids uuid[])
returns setof api_web_v1.mentor_directory_v1
language sql stable security definer set search_path = '' as $fn$
 with requested_profiles as materialized (
   -- Separate branches avoid a generic nullable-OR scan. Materialize this
   -- bounded set before joining users, preventing repeated small-table scans.
   select user_id,university_name,department_name,teaching_subjects,intro_line,profile_image_url,high_school_name,is_open_for_subscriptions,created_at,verification_status from public.mentor_profiles where p_mentor_ids is null
   union all
   select user_id,university_name,department_name,teaching_subjects,intro_line,profile_image_url,high_school_name,is_open_for_subscriptions,created_at,verification_status from public.mentor_profiles
     where p_mentor_ids is not null and user_id=any(p_mentor_ids)
 )
 select mp.user_id,u.nickname,mp.university_name,mp.department_name,mp.teaching_subjects,mp.intro_line,
   mp.profile_image_url,mp.high_school_name,sv.mentor_id is not null,sv.school_tier,sv.verified_major_category,
   sv.verified_university_name,sv.verified_department_name,mp.is_open_for_subscriptions,null::numeric,null::integer,mp.created_at
 from requested_profiles mp join public.users u on u.id=mp.user_id
 left join lateral (select msv.mentor_id,msv.school_tier,msv.verified_major_category,msv.verified_university_name,msv.verified_department_name
    from public.mentor_school_verifications msv where msv.mentor_id=mp.user_id and msv.status='approved'
    order by coalesce(msv.reviewed_at,msv.updated_at,msv.created_at) desc,msv.created_at desc limit 1) sv on true
 where u.role='mentor' and lower(coalesce(u.status,'active'))='active'
   and lower(coalesce(mp.verification_status,'')) in ('approved','verified','active')
   and not exists(select 1 from public.account_deletion_jobs j where j.user_id=mp.user_id
     and j.state in ('pending','locked','purging','storage_purged','finalized','auth_soft_deleted'))
$fn$;

create or replace function core_private.mentor_directory_rows(p_mentor_ids uuid[])
returns setof api_web_v1.mentor_directory_v1
language sql stable security definer set search_path = '' as $fn$
 select b.mentor_id,b.nickname,b.university_name,b.department_name,b.teaching_subjects,b.intro_line,
   b.profile_image_url,b.high_school_name,b.school_verified,b.school_tier,b.verified_major_category,
   b.verified_university_name,b.verified_department_name,b.is_open_for_subscriptions,
   rv.avg_rating,rv.review_count,b.created_at
 from core_private.mentor_directory_base(p_mentor_ids) b
 left join lateral (
   select avg(r.rating) avg_rating,count(*)::integer review_count from public.reviews r
   where r.mentor_id=b.mentor_id and r.moderation_state='visible'
     and not coalesce(r.is_hidden,false) and not coalesce(r.is_blinded,false)
 ) rv on true
$fn$;

-- The old function is retained for callers that still use its no-argument contract.
create or replace function core_private.mentor_directory_public_rows()
returns table(mentor_id uuid,nickname text,university_name text,department_name text,
 teaching_subjects text[],intro_line text,profile_image_url text,high_school_name text,
 school_verified boolean,school_tier text,verified_major_category text,verified_university_name text,
 verified_department_name text,is_open_for_subscriptions boolean,avg_rating numeric,review_count integer,created_at timestamptz)
language sql stable security definer set search_path = '' as $fn$
 select * from core_private.mentor_directory_rows(null)
$fn$;

create or replace function core_private.mentor_directory_visible_ids()
returns table(mentor_id uuid)
language sql stable security definer set search_path = '' as $fn$
 select mp.user_id from public.mentor_profiles mp join public.users u on u.id=mp.user_id
 where u.role='mentor' and lower(coalesce(u.status,'active'))='active'
   and lower(coalesce(mp.verification_status,'')) in ('approved','verified','active')
   and not exists(select 1 from public.account_deletion_jobs j where j.user_id=mp.user_id
     and j.state in ('pending','locked','purging','storage_purged','finalized','auth_soft_deleted'))
$fn$;

-- Existing apps filter this view, not the new RPC. Expose the ID from the cheap
-- visible-ID scan, so an outer eq/in is evaluated BEFORE either school/review
-- lookup. The compatibility path still enumerates eligible IDs; new RPCs bind
-- IDs at the initial indexed profile lookup and do not enumerate the directory.
create or replace view api_web_v1.mentor_directory_v1 with (security_invoker=true) as
 select ids.mentor_id,r.nickname,r.university_name,r.department_name,r.teaching_subjects,r.intro_line,
   r.profile_image_url,r.high_school_name,r.school_verified,r.school_tier,r.verified_major_category,
   r.verified_university_name,r.verified_department_name,r.is_open_for_subscriptions,
   r.avg_rating,r.review_count,r.created_at
 from core_private.mentor_directory_visible_ids() ids
 cross join lateral core_private.mentor_directory_rows(array[ids.mentor_id]) r;

create or replace function api_web_v1.mentor_directory_by_ids(p_mentor_ids uuid[])
returns setof api_web_v1.mentor_directory_v1
language plpgsql stable security definer set search_path = '' as $fn$
begin
 if p_mentor_ids is null or cardinality(p_mentor_ids)>500
    or array_position(p_mentor_ids,null) is not null then
   raise exception 'MENTOR_DIRECTORY_INPUT_INVALID' using errcode='22023';
 end if;
 return query select * from core_private.mentor_directory_rows(p_mentor_ids);
end
$fn$;

create or replace function api_web_v1.mentor_directory_count()
returns bigint language sql stable security definer set search_path = '' as $fn$
 select count(*) from core_private.mentor_directory_visible_ids()
$fn$;

-- Match ECMAScript String.trim(), including Korean full-width/nonbreaking spaces.
create or replace function core_private.mentor_directory_trim(p_text text)
returns text language sql immutable set search_path = '' as $fn$
 select btrim(coalesce(p_text,''),chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(32)||chr(160)||
   chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||
   chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288)||chr(65279))
$fn$;

create or replace function api_web_v1.mentor_directory_page(
 p_filters jsonb default '{}'::jsonb,p_page integer default 1,p_page_size integer default 12,
 p_mentor_ids uuid[] default null,p_order_by_ids boolean default false)
returns jsonb language plpgsql stable security definer set search_path = '' as $fn$
declare
 v_sort text := coalesce(p_filters->>'sort','popular');
 v_result jsonb;
 v_key text;
begin
 if p_filters is null or jsonb_typeof(p_filters)<>'object' or octet_length(p_filters::text)>16384
    or p_page is null or p_page<1 or p_page_size is null or p_page_size not between 1 and 100
    or p_order_by_ids is null or (p_order_by_ids and p_mentor_ids is null)
    or cardinality(p_mentor_ids)>10000 or array_position(p_mentor_ids,null) is not null
    or v_sort not in ('popular','new','review','rating','price_asc','price_desc') then
   raise exception 'MENTOR_DIRECTORY_INPUT_INVALID' using errcode='22023';
 end if;
 for v_key in select jsonb_object_keys(p_filters) loop
   if v_key not in ('q','school','university','verification','verified_only','subject_labels','grades','mentor_types','price_band','sort') then
     raise exception 'MENTOR_DIRECTORY_INPUT_INVALID' using errcode='22023';
   end if;
   if v_key in ('subject_labels','grades','mentor_types') then
     if jsonb_typeof(p_filters->v_key)<>'array' then
       raise exception 'MENTOR_DIRECTORY_INPUT_INVALID' using errcode='22023';
     end if;
     if jsonb_array_length(p_filters->v_key)>128 or exists (
       select 1 from jsonb_array_elements(p_filters->v_key) e where jsonb_typeof(e)<>'string' or char_length(e#>>'{}')>120
     ) then raise exception 'MENTOR_DIRECTORY_INPUT_INVALID' using errcode='22023'; end if;
   elsif v_key='verified_only' then
     if jsonb_typeof(p_filters->v_key)<>'boolean' then
       raise exception 'MENTOR_DIRECTORY_INPUT_INVALID' using errcode='22023';
     end if;
   elsif jsonb_typeof(p_filters->v_key)<>'string' or char_length(p_filters->>v_key)>500 then
     raise exception 'MENTOR_DIRECTORY_INPUT_INVALID' using errcode='22023';
   end if;
 end loop;
 if coalesce(p_filters->>'price_band','') not in ('','3to5','5to10','10to20','over20') then
   raise exception 'MENTOR_DIRECTORY_INPUT_INVALID' using errcode='22023';
 end if;

 with base as materialized (
   select b.*,
     case when b.school_tier='그외' then '미분류' else coalesce(b.school_tier,'') end normalized_school_tier,
     coalesce(nullif(core_private.mentor_directory_trim(b.nickname),''),'멘토') display_name,
     case when b.school_verified then coalesce(nullif(b.verified_university_name,''),b.university_name) else b.university_name end display_university,
     case when b.school_verified then coalesce(nullif(b.verified_department_name,''),b.department_name) else b.department_name end display_department,
     coalesce(array_to_string(b.teaching_subjects,', '),'') subjects_text
   from core_private.mentor_directory_base(p_mentor_ids) b
   where exists(select 1 from unnest(b.teaching_subjects) s where core_private.mentor_directory_trim(s)<>'')
 ), searchable as (
   select b.*,lower(concat_ws(' ',display_name,coalesce(intro_line,''),subjects_text,'',display_university,
     display_department,university_name,department_name,coalesce(verified_major_category,''),normalized_school_tier,
     high_school_name,case when core_private.mentor_directory_trim(department_name) ~ '([0-9]{1,2}학번|^[0-9]{2}$)'
       then core_private.mentor_directory_trim(department_name) else '' end)) search_blob
   from base b
 ), filtered as materialized (
   select b.* from searchable b
   where (coalesce(p_filters->>'q','')='' or strpos(search_blob,lower(p_filters->>'q'))>0)
     and (coalesce(p_filters->>'school','')='' or (school_verified and normalized_school_tier=p_filters->>'school'))
     and (coalesce(p_filters->>'school','')<>'' or coalesce(p_filters->>'university','')=''
       or (school_verified and strpos(lower(display_university),lower(p_filters->>'university'))>0))
     -- The adapter's verification value is always approved (the visibility invariant).
     and (coalesce(p_filters->>'verification','')='' or strpos('approved',lower(p_filters->>'verification'))>0)
     and (coalesce(jsonb_array_length(p_filters->'subject_labels'),0)=0 or exists (
       select 1 from jsonb_array_elements_text(p_filters->'subject_labels') s where strpos(lower(subjects_text),lower(s))>0))
     and (coalesce(jsonb_array_length(p_filters->'grades'),0)=0 or exists (
       select 1 from jsonb_array_elements_text(p_filters->'grades') g where
         (g='중등' and search_blob ~ '중등|중학|중1|중2|중3') or
         (g='고등' and search_blob ~ '고등|고1|고2|고3|내신|수능') or
         (g='N수' and search_blob ~ 'n수|재수|검정')))
     and (coalesce(jsonb_array_length(p_filters->'mentor_types'),0)=0 or (school_verified and exists (
       select 1 from jsonb_array_elements_text(p_filters->'mentor_types') t
       where t=core_private.mentor_directory_trim(verified_major_category))))
 ), priced as materialized (
   select f.*,pl.plans,pl.prices,pl.min_price from filtered f
   left join lateral (
     -- These are existing catalog DISPLAY fallbacks for missing/invalid plans,
     -- never a debit price. Actual checkout continues to lock its DB plan.
     select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'mentor_id',p.mentor_id,'plan_tier',p.plan_tier,
       'amount_cents',p.amount_cents,'label',p.label) order by tiers.ord) filter(where p.id is not null),'[]'::jsonb) plans,
       array_agg(case when p.amount_cents>0 then round(p.amount_cents::numeric/100)::integer else tiers.fallback end order by tiers.ord) prices,
       min(case when p.amount_cents>0 then round(p.amount_cents::numeric/100)::integer else tiers.fallback end) min_price
     from (values ('limited',29900,1),('standard',84900,2),('premium',174900,3)) tiers(tier,fallback,ord)
     left join public.mentor_plans p on p.mentor_id=f.mentor_id and p.plan_tier=tiers.tier
   ) pl on true
 ), matching as materialized (
   select * from priced where coalesce(p_filters->>'price_band','')='' or exists (
     select 1 from unnest(prices) price where case p_filters->>'price_band'
       when '3to5' then price>=30000 and price<50000
       when '5to10' then price>=50000 and price<100000
       when '10to20' then price>=100000 and price<200000
       when 'over20' then price>=200000 else false end)
 ), ranked as (
   select m.*,rv.avg_rating computed_rating,rv.review_count computed_review_count,
     case when not school_verified or core_private.mentor_directory_trim(normalized_school_tier)='' then 4
       when core_private.mentor_directory_trim(normalized_school_tier)='서연고' and core_private.mentor_directory_trim(verified_major_category)='메디컬' then 0
       when core_private.mentor_directory_trim(verified_major_category)='메디컬' then 1
       when core_private.mentor_directory_trim(normalized_school_tier)='서연고' then 2 else 3 end group_rank
   from matching m left join lateral (
     select avg(r.rating) avg_rating,count(*)::integer review_count from public.reviews r
     where r.mentor_id=m.mentor_id and r.moderation_state='visible' and not coalesce(r.is_hidden,false) and not coalesce(r.is_blinded,false)
       and not p_order_by_ids and v_sort in ('popular','review','rating')
   ) rv on true
 ), selected as materialized (
   select * from ranked order by
     case when p_order_by_ids then array_position(p_mentor_ids,mentor_id) end asc,
     case when not p_order_by_ids and v_sort='popular' then group_rank end asc,
     case when not p_order_by_ids and v_sort='popular' then core_private.mentor_directory_trim(intro_line)<>'' end desc,
     -- bio is absent from the existing public 17-field contract, hence its old
     -- description-length sort key is zero for every row; do not expose it here.
     case when not p_order_by_ids and v_sort='popular' then computed_review_count*10+coalesce(computed_rating,0) end desc,
     case when not p_order_by_ids and v_sort='review' then computed_review_count end desc,
     case when not p_order_by_ids and v_sort='rating' then computed_rating end desc nulls last,
     case when not p_order_by_ids and v_sort='price_asc' then min_price end asc,
     case when not p_order_by_ids and v_sort='price_desc' then min_price end desc,
     created_at desc,mentor_id asc
   limit p_page_size offset (p_page::bigint-1)*p_page_size
 ), detailed as (
   select s.*,row_number() over () ordinal,
     case when p_order_by_ids or v_sort not in ('popular','review','rating') then rv.avg_rating else s.computed_rating end final_rating,
     case when p_order_by_ids or v_sort not in ('popular','review','rating') then rv.review_count else s.computed_review_count end final_count
   from selected s left join lateral (
     select avg(r.rating) avg_rating,count(*)::integer review_count from public.reviews r
     where r.mentor_id=s.mentor_id and r.moderation_state='visible' and not coalesce(r.is_hidden,false) and not coalesce(r.is_blinded,false)
       and (p_order_by_ids or v_sort not in ('popular','review','rating'))
   ) rv on true
 )
 select jsonb_build_object('total_count',(select count(*) from matching),'items',coalesce((
   select jsonb_agg(jsonb_build_object('profile',jsonb_build_object(
     'mentor_id',d.mentor_id,'nickname',d.nickname,'university_name',d.university_name,'department_name',d.department_name,
     'teaching_subjects',d.teaching_subjects,'intro_line',d.intro_line,'profile_image_url',d.profile_image_url,
     'high_school_name',d.high_school_name,'school_verified',d.school_verified,'school_tier',d.school_tier,
     'verified_major_category',d.verified_major_category,'verified_university_name',d.verified_university_name,
     'verified_department_name',d.verified_department_name,'is_open_for_subscriptions',d.is_open_for_subscriptions,
     'avg_rating',d.final_rating,'review_count',d.final_count,'created_at',d.created_at),
     'plans',d.plans,'subscription_closed',
       public.mentor_cap_used(d.mentor_id)+public.subscription_cap_weight('limited')>public.mentor_cap_limit(d.mentor_id)) order by d.ordinal)
   from detailed d),'[]'::jsonb)) into v_result;
 return v_result;
end
$fn$;

