-- SOURCE supabase/integration_fragments/60_backfill.sql
-- This temporary trigger runs after the ordinary updated_at trigger, only while
-- migration locks exclude writers. It cannot be enabled through a caller GUC.
CREATE FUNCTION core_private.preserve_period_backfill_updated_at()
RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF (to_jsonb(NEW)-'current_service_period_event_id'-'updated_at')
  IS DISTINCT FROM (to_jsonb(OLD)-'current_service_period_event_id'-'updated_at') THEN
  RAISE EXCEPTION 'BACKFILL_UNEXPECTED_ROW_CHANGE';
 END IF;
 NEW.updated_at:=OLD.updated_at;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION core_private.preserve_period_backfill_updated_at() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER zz_preserve_period_backfill_updated_at BEFORE UPDATE ON public.subscriptions
 FOR EACH ROW EXECUTE FUNCTION core_private.preserve_period_backfill_updated_at();
WITH verified AS (
 SELECT s.id,min(e.id::text)::uuid event_id FROM public.subscriptions s
 JOIN public.subscription_billing_events e ON e.subscription_id=s.id
 WHERE s.current_service_period_event_id IS NULL AND e.event_type IN ('initial','renewal') AND e.status='succeeded'
  AND core_private.service_period_funding(e.id) IN ('cash','verified_legacy_cash','pg','voucher')
  AND core_private.service_period_matches_subscription(s.id,e.id)
 GROUP BY s.id HAVING count(*)=1
)
UPDATE public.subscriptions s SET current_service_period_event_id=v.event_id FROM verified v WHERE s.id=v.id;
DROP TRIGGER zz_preserve_period_backfill_updated_at ON public.subscriptions;
DROP FUNCTION core_private.preserve_period_backfill_updated_at();

